window.HSK_DATA = window.HSK_DATA || {};
window.HSK_DATA["6"] = [{"id":"遍布","hanzi":"遍布","pinyin":"biànbù","meaning_vi":"trải khắp","explanation":"遍 (biến – khắp) + 布 (bố – phân bố, rải ra) → phân bố khắp nơi. Ví dụ: 分店遍布全国 (chi nhánh có khắp cả nước).","hsk_level":6,"tags":["dong-tu"],"image":"🌐","examples":[{"type":"basic","zh":"他的朋友遍布全国。","pinyin":"Tā de péngyou biànbù quánguó.","vi":"Anh ấy có bạn bè khắp cả nước."},{"type":"simple","zh":"这家奶茶店的分店已经遍布整个城市。","pinyin":"Zhè jiā nǎichá diàn de fēndiàn yǐjīng biànbù zhěnggè chéngshì.","vi":"Chi nhánh của tiệm trà sữa này đã có mặt khắp cả thành phố."},{"type":"compound","zh":"因为下了一夜大雨，所以街上遍布积水。","pinyin":"Yīnwèi xiàle yí yè dàyǔ, suǒyǐ jiēshang biànbù jīshuǐ.","vi":"Vì mưa to suốt đêm nên trên đường phố đọng nước khắp nơi."}],"related":[{"hanzi":"分布","pinyin":"fēnbù","vi":"phân bố"},{"hanzi":"遍地","pinyin":"biàndì","vi":"khắp nơi"},{"hanzi":"布满","pinyin":"bùmǎn","vi":"phủ đầy"},{"hanzi":"到处","pinyin":"dàochù","vi":"khắp nơi"}],"traditional":"遍佈"},{"id":"变本加厉","hanzi":"变本加厉","pinyin":"biànběn-jiālì","meaning_vi":"càng lúc càng nghiêm trọng hơn","explanation":"变 (biến – đổi) + 本 (bản – gốc) + 加 (gia – thêm) + 厉 (lệ – dữ dội) → so với ban đầu càng dữ dội hơn → (việc xấu) ngày càng trầm trọng. Mang nghĩa xấu.","hsk_level":6,"tags":["thanh-ngu"],"image":"⚠️","examples":[{"type":"basic","zh":"他的赌瘾变本加厉。","pinyin":"Tā de dǔ yǐn biànběnjiālì.","vi":"Cơn nghiện cờ bạc của anh ta ngày càng nặng hơn."},{"type":"simple","zh":"他对员工的克扣变本加厉了。","pinyin":"Tā duì yuángōng de kèkòu biànběnjiālì le.","vi":"Việc anh ta cắt xén tiền của nhân viên ngày càng quá đáng hơn."},{"type":"compound","zh":"他不但不改正错误，反而变本加厉地撒谎。","pinyin":"Tā búdàn bù gǎizhèng cuòwù, fǎn'ér biànběnjiālì de sāhuǎng.","vi":"Anh ta không những không sửa sai mà còn nói dối ngày càng trắng trợn hơn."}],"related":[{"hanzi":"愈演愈烈","pinyin":"yùyǎnyùliè","vi":"ngày càng dữ dội"},{"hanzi":"加剧","pinyin":"jiājù","vi":"tăng thêm mức độ"},{"hanzi":"恶化","pinyin":"èhuà","vi":"xấu đi"},{"hanzi":"有所收敛","pinyin":"yǒusuǒshōuliǎn","vi":"có phần kiềm chế"}],"traditional":"變本加厲"},{"id":"遍地","hanzi":"遍地","pinyin":"biàndì","meaning_vi":"khắp mặt đất, khắp nơi","explanation":"遍 (khắp) + 地 (đất).","hsk_level":6,"tags":["danh-tu","dia-diem"],"image":"🌍","examples":[{"type":"basic","zh":"秋天落叶遍地。","pinyin":"Qiūtiān luòyè biàndì.","vi":"Mùa thu lá rụng khắp mặt đất."},{"type":"simple","zh":"春天的山坡上遍地都是野花。","pinyin":"Chūntiān de shānpō shang biàndì dōu shì yěhuā.","vi":"Mùa xuân, trên sườn đồi đâu đâu cũng là hoa dại."},{"type":"compound","zh":"孩子们一玩起来，客厅里就遍地都是玩具。","pinyin":"Háizimen yì wán qǐlái, kètīng li jiù biàndì dōu shì wánjù.","vi":"Bọn trẻ vừa chơi là phòng khách liền vương vãi đồ chơi khắp sàn."}],"related":[{"hanzi":"到处","pinyin":"dàochù","vi":"khắp nơi"},{"hanzi":"满地","pinyin":"mǎndì","vi":"đầy đất"},{"hanzi":"处处","pinyin":"chùchù","vi":"mọi nơi"},{"hanzi":"遍布","pinyin":"biànbù","vi":"trải khắp"}]},{"id":"变革","hanzi":"变革","pinyin":"biàngé","meaning_vi":"cải cách, biến đổi lớn","explanation":"变 (đổi) + 革 (cải cách).","hsk_level":6,"tags":["dong-tu","danh-tu"],"image":"🔄","examples":[{"type":"basic","zh":"社会正在变革。","pinyin":"Shèhuì zhèngzài biàngé.","vi":"Xã hội đang chuyển mình thay đổi."},{"type":"simple","zh":"互联网给零售业带来了巨大的变革。","pinyin":"Hùliánwǎng gěi língshòu yè dàiláile jùdà de biàngé.","vi":"Internet đã mang lại sự thay đổi to lớn cho ngành bán lẻ."},{"type":"compound","zh":"如果公司不进行变革，就会被市场淘汰。","pinyin":"Rúguǒ gōngsī bú jìnxíng biàngé, jiù huì bèi shìchǎng táotài.","vi":"Nếu công ty không cải cách thì sẽ bị thị trường đào thải."}],"related":[{"hanzi":"改革","pinyin":"gǎigé","vi":"cải cách"},{"hanzi":"变化","pinyin":"biànhuà","vi":"biến đổi"},{"hanzi":"革新","pinyin":"géxīn","vi":"đổi mới"},{"hanzi":"革命","pinyin":"gémìng","vi":"cách mạng"}],"traditional":"變革"},{"id":"变幻莫测","hanzi":"变幻莫测","pinyin":"biànhuàn-mòcè","meaning_vi":"biến hóa khôn lường","explanation":"变幻 + 莫测 (không đoán được). Thành ngữ.","hsk_level":6,"tags":["thanh-ngu","thoi-tiet"],"image":"🌪️","examples":[{"type":"basic","zh":"山里的天气变幻莫测。","pinyin":"Shān li de tiānqì biànhuànmòcè.","vi":"Thời tiết trong núi biến hóa khôn lường."},{"type":"simple","zh":"我们在变幻莫测的大海上航行了三天。","pinyin":"Wǒmen zài biànhuànmòcè de dà hǎishang hángxíngle sān tiān.","vi":"Chúng tôi đã lênh đênh ba ngày trên biển cả biến hóa khôn lường."},{"type":"compound","zh":"虽然股市变幻莫测，但是他依然坚持长期投资。","pinyin":"Suīrán gǔshì biànhuànmòcè, dànshì tā yīrán jiānchí chángqī tóuzī.","vi":"Tuy thị trường chứng khoán biến động khôn lường nhưng anh ấy vẫn kiên trì đầu tư dài hạn."}],"related":[{"hanzi":"变化多端","pinyin":"biànhuàduōduān","vi":"biến hóa đa dạng"},{"hanzi":"变幻","pinyin":"biànhuàn","vi":"biến ảo"},{"hanzi":"捉摸不定","pinyin":"zhuōmōbúdìng","vi":"khó nắm bắt"},{"hanzi":"一成不变","pinyin":"yìchéngbúbiàn","vi":"không hề thay đổi"}],"traditional":"變幻莫測"},{"id":"辩护","hanzi":"辩护","pinyin":"biànhù","meaning_vi":"biện hộ, bào chữa","explanation":"辩 (tranh luận) + 护 (bảo vệ).","hsk_level":6,"tags":["dong-tu","phap-luat"],"image":"⚖️","examples":[{"type":"basic","zh":"律师为他辩护。","pinyin":"Lǜshī wèi tā biànhù.","vi":"Luật sư bào chữa cho anh ấy."},{"type":"simple","zh":"这位年轻律师在法庭上为被告做了无罪辩护。","pinyin":"Zhè wèi niánqīng lǜshī zài fǎtíng shang wèi bèigào zuòle wúzuì biànhù.","vi":"Vị luật sư trẻ này đã bào chữa vô tội cho bị cáo tại tòa."},{"type":"compound","zh":"即使证据对他不利，律师也坚持为他辩护。","pinyin":"Jíshǐ zhèngjù duì tā búlì, lǜshī yě jiānchí wèi tā biànhù.","vi":"Dù chứng cứ bất lợi cho anh ta, luật sư vẫn kiên quyết bào chữa cho anh ta."}],"related":[{"hanzi":"辩护律师","pinyin":"biànhùlǜshī","vi":"luật sư bào chữa"},{"hanzi":"辩解","pinyin":"biànjiě","vi":"biện bạch"},{"hanzi":"辩论","pinyin":"biànlùn","vi":"tranh luận"},{"hanzi":"指控","pinyin":"zhǐkòng","vi":"cáo buộc"}],"traditional":"辯護"},{"id":"辩解","hanzi":"辩解","pinyin":"biànjiě","meaning_vi":"biện bạch, giải thích thanh minh","explanation":"辩 + 解 (giải thích).","hsk_level":6,"tags":["dong-tu","giao-tiep"],"image":"🗣️","examples":[{"type":"basic","zh":"你别再辩解了。","pinyin":"Nǐ bié zài biànjiě le.","vi":"Cậu đừng thanh minh nữa."},{"type":"simple","zh":"他红着脸向经理辩解迟到的原因。","pinyin":"Tā hóngzhe liǎn xiàng jīnglǐ biànjiě chídào de yuányīn.","vi":"Anh ấy đỏ mặt thanh minh với giám đốc về lý do đến muộn."},{"type":"compound","zh":"与其花时间辩解，不如马上改正错误。","pinyin":"Yǔqí huāshíjiān biànjiě, bùrú mǎshàng gǎizhèng cuòwù.","vi":"Thay vì mất thời gian biện bạch, chi bằng lập tức sửa sai."}],"related":[{"hanzi":"解释","pinyin":"jiěshì","vi":"giải thích"},{"hanzi":"辩护","pinyin":"biànhù","vi":"biện hộ"},{"hanzi":"狡辩","pinyin":"jiǎobiàn","vi":"cãi chày cãi cối"},{"hanzi":"争辩","pinyin":"zhēngbiàn","vi":"tranh cãi"}],"traditional":"辯解"},{"id":"便利店","hanzi":"便利店","pinyin":"biànlìdiàn","meaning_vi":"cửa hàng tiện lợi","explanation":"便利 + 店 (cửa hàng).","hsk_level":6,"tags":["danh-tu","mua-sam","dia-diem"],"image":"🏪","examples":[{"type":"basic","zh":"楼下有家便利店。","pinyin":"Lóuxià yǒu jiā biànlìdiàn.","vi":"Dưới tầng có một cửa hàng tiện lợi."},{"type":"simple","zh":"我每天早上在便利店买一个饭团当早餐。","pinyin":"Wǒ měitiān zǎoshang zài biànlìdiàn mǎi yí gè fàntuán dāng zǎocān.","vi":"Sáng nào tôi cũng mua một nắm cơm ở cửa hàng tiện lợi làm bữa sáng."},{"type":"compound","zh":"因为这家便利店二十四小时营业，所以夜里也很方便。","pinyin":"Yīnwèi zhè jiā biànlìdiàn èr shísì xiǎoshí yíngyè, suǒyǐ yèli yě hěn fāngbiàn.","vi":"Vì cửa hàng tiện lợi này mở cửa hai mươi bốn giờ nên ban đêm cũng rất tiện."}],"related":[{"hanzi":"超市","pinyin":"chāoshì","vi":"siêu thị"},{"hanzi":"商店","pinyin":"shāngdiàn","vi":"cửa hàng"},{"hanzi":"便利","pinyin":"biànlì","vi":"tiện lợi"},{"hanzi":"小卖部","pinyin":"xiǎomàibù","vi":"tiệm tạp hóa nhỏ"}]},{"id":"辨认","hanzi":"辨认","pinyin":"biànrèn","meaning_vi":"nhận diện","explanation":"辨 (biện – phân biệt) + 认 (nhận – nhận ra) → phân biệt và nhận ra. Thường: 辨认字迹, 辨认方向, 辨认嫌疑人.","hsk_level":6,"tags":["dong-tu"],"image":"🔍","examples":[{"type":"basic","zh":"字迹很难辨认。","pinyin":"Zìjì hěn nán biànrèn.","vi":"Nét chữ rất khó nhận ra."},{"type":"simple","zh":"警察请目击者辨认照片上的嫌疑人。","pinyin":"Jǐngchá qǐng mùjīzhě biànrèn zhàopiàn shang de xiányírén.","vi":"Cảnh sát nhờ nhân chứng nhận diện nghi phạm trong ảnh."},{"type":"compound","zh":"因为雾太大了，所以我们连路牌都辨认不清。","pinyin":"Yīnwèi wù tài dà le, suǒyǐ wǒmen lián lùpái dōu biànrèn bùqīng.","vi":"Vì sương mù quá dày nên chúng tôi đến biển chỉ đường cũng không nhận ra rõ."}],"related":[{"hanzi":"辨别","pinyin":"biànbié","vi":"phân biệt"},{"hanzi":"识别","pinyin":"shíbié","vi":"nhận dạng"},{"hanzi":"认出","pinyin":"rènchū","vi":"nhận ra"},{"hanzi":"辨认出","pinyin":"biànrènchū","vi":"nhận diện ra"}],"traditional":"辨認"},{"id":"辨析","hanzi":"辨析","pinyin":"biànxī","meaning_vi":"phân tích phân biệt (từ đồng nghĩa/ngữ nghĩa)","explanation":"辨 (phân biệt) + 析 (mổ xẻ).","hsk_level":6,"tags":["dong-tu","hoc-tap"],"image":"🔍","examples":[{"type":"basic","zh":"老师在辨析近义词。","pinyin":"Lǎoshī zài biànxī jìnyìcí.","vi":"Thầy giáo đang phân tích, phân biệt các từ gần nghĩa."},{"type":"simple","zh":"这本书专门辨析了三百组容易混淆的词语。","pinyin":"Zhè běn shū zhuānmén biànxīle sān bǎi zǔ róngyì hùnxiáo de cíyǔ.","vi":"Cuốn sách này chuyên phân tích, phân biệt ba trăm cặp từ dễ nhầm lẫn."},{"type":"compound","zh":"只要认真辨析这两个词的用法，就不会再用错了。","pinyin":"Zhǐyào rènzhēn biànxī zhè liǎng gè cí de yòngfǎ, jiù bú huì zài yòng cuò le.","vi":"Chỉ cần phân tích kỹ cách dùng của hai từ này thì sẽ không dùng sai nữa."}],"related":[{"hanzi":"辨别","pinyin":"biànbié","vi":"phân biệt"},{"hanzi":"分析","pinyin":"fēnxī","vi":"phân tích"},{"hanzi":"区分","pinyin":"qūfēn","vi":"phân biệt"},{"hanzi":"近义词","pinyin":"jìnyìcí","vi":"từ gần nghĩa"}]},{"id":"辩证","hanzi":"辩证","pinyin":"biànzhèng","meaning_vi":"biện chứng","explanation":"辩 + 证 (chứng minh).","hsk_level":6,"tags":["tinh-tu","hoc-tap"],"image":"🧠","examples":[{"type":"basic","zh":"要辩证地看问题。","pinyin":"Yào biànzhèngde kàn wèntí.","vi":"Phải nhìn vấn đề một cách biện chứng."},{"type":"simple","zh":"哲学课上，老师讲解了辩证思维的基本方法。","pinyin":"Zhéxué kè shang, lǎoshī jiǎngjiěle biànzhèng sīwéi de jīběn fāngfǎ.","vi":"Trong giờ triết học, thầy giảng giải phương pháp cơ bản của tư duy biện chứng."},{"type":"compound","zh":"既要看到网络的好处，又要辩证地看待它的危害。","pinyin":"Jì yào kàndào wǎngluò de hǎochù, yòu yào biànzhèngde kàndài tā de wēihài.","vi":"Vừa phải thấy lợi ích của mạng Internet, vừa phải nhìn nhận tác hại của nó một cách biện chứng."}],"related":[{"hanzi":"辩证法","pinyin":"biànzhèngfǎ","vi":"phép biện chứng"},{"hanzi":"唯物主义","pinyin":"wéiwùzhǔyì","vi":"chủ nghĩa duy vật"},{"hanzi":"辩证地","pinyin":"biànzhèngde","vi":"một cách biện chứng"},{"hanzi":"片面","pinyin":"piànmiàn","vi":"phiến diện"}],"traditional":"辯證"},{"id":"变质","hanzi":"变质","pinyin":"biànzhì","meaning_vi":"biến chất, hư hỏng","explanation":"变 (biến – đổi) + 质 (chất – bản chất) → biến chất. Dùng cho đồ ăn hư (牛奶变质了) hoặc con người tha hóa về phẩm chất.","hsk_level":6,"tags":["dong-tu"],"image":"🤢","examples":[{"type":"basic","zh":"牛奶已经变质了。","pinyin":"Niúnǎi yǐjīng biànzhì le.","vi":"Sữa đã bị hỏng rồi."},{"type":"simple","zh":"夏天的剩菜放在桌上很容易变质。","pinyin":"Xiàtiān de shèngcài fàng zài zhuō shang hěn róngyì biànzhì.","vi":"Mùa hè, thức ăn thừa để trên bàn rất dễ bị hỏng."},{"type":"compound","zh":"如果面包过了保质期，就可能已经变质了。","pinyin":"Rúguǒ miànbāoguò le bǎozhìqī, jiù kěnéng yǐjīng biànzhì le.","vi":"Nếu bánh mì đã quá hạn sử dụng thì có thể đã bị hỏng rồi."}],"related":[{"hanzi":"腐烂","pinyin":"fǔlàn","vi":"thối rữa"},{"hanzi":"过期","pinyin":"guòqī","vi":"quá hạn"},{"hanzi":"变坏","pinyin":"biànhuài","vi":"hỏng"},{"hanzi":"保鲜","pinyin":"bǎoxiān","vi":"giữ tươi"}],"traditional":"變質"},{"id":"别出心裁","hanzi":"别出心裁","pinyin":"biéchū-xīncái","meaning_vi":"sáng tạo độc đáo, khác biệt","explanation":"别 (biệt – khác) + 出 (xuất – đưa ra) + 心裁 (tâm tài – ý tưởng tự nghĩ ra) → nghĩ ra cách khác người → sáng tạo, độc đáo, không theo lối mòn.","hsk_level":6,"tags":["thanh-ngu"],"image":"💡","examples":[{"type":"basic","zh":"他的设计别出心裁。","pinyin":"Tā de shèjì biéchūxīncái.","vi":"Thiết kế của anh ấy rất sáng tạo độc đáo."},{"type":"simple","zh":"这家餐厅别出心裁地把菜单印在了筷子套上。","pinyin":"Zhè jiā cāntīng biéchūxīncái de bǎ càidān yìn zài le kuàizi tào shang.","vi":"Nhà hàng này độc đáo ở chỗ in thực đơn lên vỏ bọc đũa."},{"type":"compound","zh":"她的婚礼不但别出心裁，而且花费不多。","pinyin":"Tā de hūnlǐ búdàn biéchūxīncái, érqiě huāfèi bù duō.","vi":"Đám cưới của cô ấy không những độc đáo mà còn không tốn kém nhiều."}],"related":[{"hanzi":"标新立异","pinyin":"biāoxīnlìyì","vi":"đưa ra cái mới lạ"},{"hanzi":"独出心裁","pinyin":"dúchūxīncái","vi":"sáng tạo độc đáo"},{"hanzi":"别具一格","pinyin":"biéjùyìgé","vi":"phong cách riêng"},{"hanzi":"千篇一律","pinyin":"qiānpiānyílǜ","vi":"rập khuôn như nhau"}],"traditional":"別出心裁"},{"id":"别具一格","hanzi":"别具一格","pinyin":"biéjù-yìgé","meaning_vi":"mang phong cách độc đáo riêng","explanation":"别 (biệt – riêng) + 具 (cụ – có) + 一格 (nhất cách – một phong cách) → có phong cách riêng → độc đáo, khác biệt. Thường khen kiến trúc, tác phẩm, cách trang trí.","hsk_level":6,"tags":["thanh-ngu"],"image":"✨","examples":[{"type":"basic","zh":"这座桥别具一格。","pinyin":"Zhè zuò qiáo biéjùyìgé.","vi":"Cây cầu này mang phong cách độc đáo riêng."},{"type":"simple","zh":"小镇上的石头房子显得别具一格。","pinyin":"Xiǎozhèn shang de shítou fángzi xiǎnde biéjùyìgé.","vi":"Những ngôi nhà đá ở thị trấn nhỏ trông rất độc đáo."},{"type":"compound","zh":"虽然这家咖啡馆面积不大，但是装修别具一格。","pinyin":"Suīrán zhè jiā kāfēiguǎn miànjī búdà, dànshì zhuāngxiū biéjùyìgé.","vi":"Tuy quán cà phê này diện tích không lớn nhưng cách trang trí rất có phong cách riêng."}],"related":[{"hanzi":"独具特色","pinyin":"dújùtèsè","vi":"có nét đặc sắc riêng"},{"hanzi":"与众不同","pinyin":"yǔzhòngbùtóng","vi":"khác người"},{"hanzi":"别出心裁","pinyin":"biéchūxīncái","vi":"sáng tạo độc đáo"},{"hanzi":"千篇一律","pinyin":"qiānpiānyílǜ","vi":"rập khuôn như nhau"}],"traditional":"別具一格"},{"id":"别墅","hanzi":"别墅","pinyin":"biéshù","meaning_vi":"biệt thự","explanation":"别 (biệt – riêng, khác) + 墅 (thự – nhà ở ngoài thành) → nhà ở riêng có vườn, biệt thự. Lượng từ 栋/座.","hsk_level":6,"tags":["danh-tu","nha-cua"],"image":"🏡","examples":[{"type":"basic","zh":"他买了一栋别墅。","pinyin":"Tā mǎile yí dòng biéshù.","vi":"Anh ấy đã mua một căn biệt thự."},{"type":"simple","zh":"我们在海边租了一栋带游泳池的别墅。","pinyin":"Wǒmen zài hǎibiān zūle yí dòng dài yóuyǒngchí de biéshù.","vi":"Chúng tôi đã thuê một căn biệt thự có bể bơi ở bờ biển."},{"type":"compound","zh":"别墅虽然宽敞，但是离市中心太远了。","pinyin":"Biéshù suīrán kuānchang, dànshì lí shìzhōngxīn tài yuǎn le.","vi":"Biệt thự tuy rộng rãi nhưng cách trung tâm thành phố quá xa."}],"related":[{"hanzi":"豪宅","pinyin":"háozhái","vi":"nhà sang trọng"},{"hanzi":"公寓","pinyin":"gōngyù","vi":"chung cư"},{"hanzi":"住宅","pinyin":"zhùzhái","vi":"nhà ở"},{"hanzi":"花园","pinyin":"huāyuán","vi":"vườn hoa"}],"traditional":"別墅"},{"id":"鞭策","hanzi":"鞭策","pinyin":"biāncè","meaning_vi":"thúc đẩy, khích lệ tiến lên","explanation":"鞭 (roi ngựa) + 策 (thúc ngựa).","hsk_level":6,"tags":["dong-tu"],"image":"🐎","examples":[{"type":"basic","zh":"失败鞭策我前进。","pinyin":"Shībài biāncè wǒ qiánjìn.","vi":"Thất bại thúc đẩy tôi tiến lên."},{"type":"simple","zh":"父亲的话一直鞭策着我努力学习。","pinyin":"Fùqīn dehuà yìzhí biāncèzhe wǒ nǔlì xuéxí.","vi":"Lời của cha luôn thúc giục tôi chăm chỉ học tập."},{"type":"compound","zh":"老师的批评不是打击，而是对我们的鞭策。","pinyin":"Lǎoshī de pīpíng bú shì dǎjī, érshì duì wǒmen de biāncè.","vi":"Lời phê bình của thầy không phải là đả kích mà là sự thúc đẩy đối với chúng tôi."}],"related":[{"hanzi":"激励","pinyin":"jīlì","vi":"khích lệ"},{"hanzi":"鼓励","pinyin":"gǔlì","vi":"động viên"},{"hanzi":"督促","pinyin":"dūcù","vi":"đôn đốc"},{"hanzi":"鞭子","pinyin":"biānzi","vi":"cái roi"}]},{"id":"边界","hanzi":"边界","pinyin":"biānjiè","meaning_vi":"biên giới","explanation":"边 (biên – ven, cạnh) + 界 (giới – ranh giới) → đường ranh giới giữa hai nước hoặc hai vùng. Ví dụ: 边界线, 划定边界.","hsk_level":6,"tags":["danh-tu","dia-diem"],"image":"🚧","examples":[{"type":"basic","zh":"两国边界很长。","pinyin":"Liǎngguó biānjiè hěn cháng.","vi":"Đường biên giới giữa hai nước rất dài."},{"type":"simple","zh":"这条小河就是两个省的边界。","pinyin":"Zhè tiáo xiǎohé jiùshì liǎng gè shěng de biānjiè.","vi":"Con sông nhỏ này chính là ranh giới giữa hai tỉnh."},{"type":"compound","zh":"一过边界，手机就自动换成了当地网络。","pinyin":"Yíguò biānjiè, shǒujī jiù zìdòng huàn chéngle dāngdì wǎngluò.","vi":"Vừa qua biên giới, điện thoại liền tự động chuyển sang mạng địa phương."}],"related":[{"hanzi":"国界","pinyin":"guójiè","vi":"biên giới quốc gia"},{"hanzi":"边境","pinyin":"biānjìng","vi":"vùng biên giới"},{"hanzi":"界限","pinyin":"jièxiàn","vi":"giới hạn"},{"hanzi":"边界线","pinyin":"biānjièxiàn","vi":"đường biên giới"}],"traditional":"邊界"},{"id":"边远","hanzi":"边远","pinyin":"biānyuǎn","meaning_vi":"vùng sâu vùng xa, hẻo lánh","explanation":"边 (biên giới) + 远 (xa).","hsk_level":6,"tags":["tinh-tu","dia-diem"],"image":"🏔️","examples":[{"type":"basic","zh":"他去边远山区教书。","pinyin":"Tā qù biānyuǎn shānqū jiāoshū.","vi":"Anh ấy đến vùng núi xa xôi dạy học."},{"type":"simple","zh":"志愿者给边远地区的孩子送去了冬衣。","pinyin":"Zhìyuànzhě gěi biānyuǎn dìqū de háizi sòngqùle dōngyī.","vi":"Tình nguyện viên đã mang áo ấm đến cho trẻ em vùng sâu vùng xa."},{"type":"compound","zh":"虽然那个村子很边远，但是现在也通了网络。","pinyin":"Suīrán nà gè cūnzi hěn biānyuǎn, dànshì xiànzài yě tōngle wǎngluò.","vi":"Tuy ngôi làng đó rất hẻo lánh nhưng giờ cũng đã có mạng Internet."}],"related":[{"hanzi":"偏远","pinyin":"piānyuǎn","vi":"xa xôi hẻo lánh"},{"hanzi":"偏僻","pinyin":"piānpì","vi":"hẻo lánh"},{"hanzi":"边疆","pinyin":"biānjiāng","vi":"biên cương"},{"hanzi":"山区","pinyin":"shānqū","vi":"vùng núi"}],"traditional":"邊遠"},{"id":"编造","hanzi":"编造","pinyin":"biānzào","meaning_vi":"bịa đặt, hư cấu","explanation":"编 (dệt/soạn) + 造 (tạo ra).","hsk_level":6,"tags":["dong-tu"],"image":"🤥","examples":[{"type":"basic","zh":"他编造了一个借口。","pinyin":"Tā biānzàole yí gè jièkǒu.","vi":"Anh ta bịa ra một cái cớ."},{"type":"simple","zh":"有人在网上编造假新闻吸引眼球。","pinyin":"Yǒurén zài wǎngshang biān zàojiǎ xīnwén xīyǐn yǎnqiú.","vi":"Có người bịa đặt tin giả trên mạng để thu hút sự chú ý."},{"type":"compound","zh":"即使你编造得再完美，谎言也总会被揭穿。","pinyin":"Jíshǐ nǐ biānzào de zài wánměi, huǎngyán yě zǒng huì bèi jiēchuān.","vi":"Dù cậu bịa đặt hoàn hảo đến đâu thì lời nói dối cũng sẽ bị vạch trần."}],"related":[{"hanzi":"捏造","pinyin":"niēzào","vi":"bịa đặt"},{"hanzi":"虚构","pinyin":"xūgòu","vi":"hư cấu"},{"hanzi":"撒谎","pinyin":"sāhuǎng","vi":"nói dối"},{"hanzi":"谎言","pinyin":"huǎngyán","vi":"lời nói dối"}],"traditional":"編造"},{"id":"标本","hanzi":"标本","pinyin":"biāoběn","meaning_vi":"tiêu bản, mẫu vật","explanation":"标 (tiêu – mẫu, dấu hiệu) + 本 (bản – gốc) → mẫu vật được xử lý, bảo quản để nghiên cứu, tiêu bản. Ví dụ: 昆虫标本, 植物标本.","hsk_level":6,"tags":["danh-tu","khoa-hoc"],"image":"🦋","examples":[{"type":"basic","zh":"这是蝴蝶标本。","pinyin":"Zhè shì húdié biāoběn.","vi":"Đây là tiêu bản bướm."},{"type":"simple","zh":"博物馆里陈列着上千种植物标本。","pinyin":"Bówùguǎn li chénlièzhe shàng qiān zhǒng zhíwù biāoběn.","vi":"Trong bảo tàng trưng bày hơn một nghìn loại tiêu bản thực vật."},{"type":"compound","zh":"为了做昆虫标本，他一放假就去山里采集。","pinyin":"Wèile zuò kūnchóng biāoběn, tā yí fàngjià jiù qù shān li cǎijí.","vi":"Để làm tiêu bản côn trùng, cứ được nghỉ là cậu ấy lên núi thu thập."}],"related":[{"hanzi":"样本","pinyin":"yàngběn","vi":"mẫu"},{"hanzi":"样品","pinyin":"yàngpǐn","vi":"hàng mẫu"},{"hanzi":"动物标本","pinyin":"dòngwùbiāoběn","vi":"tiêu bản động vật"},{"hanzi":"治标治本","pinyin":"zhìbiāozhìběn","vi":"trị cả gốc lẫn ngọn"}],"traditional":"標本"},{"id":"标杆","hanzi":"标杆","pinyin":"biāogān","meaning_vi":"chuẩn mực, hình mẫu dẫn đầu","explanation":"标 + 杆 (cột mốc).","hsk_level":6,"tags":["danh-tu","cong-viec"],"image":"🚩","examples":[{"type":"basic","zh":"她是行业标杆。","pinyin":"Tā shì hángyè biāogān.","vi":"Cô ấy là hình mẫu dẫn đầu của ngành."},{"type":"simple","zh":"这家医院成了全省服务质量的标杆。","pinyin":"Zhè jiā yīyuàn chéngle quánshěng fúwù zhìliàng de biāogān.","vi":"Bệnh viện này đã trở thành chuẩn mực về chất lượng phục vụ của cả tỉnh."},{"type":"compound","zh":"既然他是公司的标杆，就更应该严格要求自己。","pinyin":"Jìrán tā shì gōngsī de biāogān, jiù gèng yīnggāi yángé yāoqiú zìjǐ.","vi":"Đã là hình mẫu của công ty thì anh ấy càng phải nghiêm khắc với bản thân."}],"related":[{"hanzi":"榜样","pinyin":"bǎngyàng","vi":"tấm gương"},{"hanzi":"典范","pinyin":"diǎnfàn","vi":"điển hình"},{"hanzi":"模范","pinyin":"mófàn","vi":"mô phạm"},{"hanzi":"标准","pinyin":"biāozhǔn","vi":"tiêu chuẩn"}],"traditional":"標杆"},{"id":"标新立异","hanzi":"标新立异","pinyin":"biāoxīn-lìyì","meaning_vi":"đưa ra cái mới lạ độc đáo","explanation":"标新立异: nêu cái mới, lập cái khác (Thế Thuyết Tân Ngữ, chuyện Chi Độn giảng Trang Tử) → đưa ra chủ trương mới lạ, khác người; đôi khi hàm ý cố tình lập dị.","hsk_level":6,"tags":["thanh-ngu"],"image":"💡","examples":[{"type":"basic","zh":"他总爱标新立异。","pinyin":"Tā zǒng ài biāoxīnlìyì.","vi":"Anh ấy luôn thích làm điều mới lạ khác người."},{"type":"simple","zh":"这位年轻导演喜欢在电影里标新立异。","pinyin":"Zhè wèi niánqīng dǎoyǎn xǐhuan zài diànyǐng li biāoxīnlìyì.","vi":"Vị đạo diễn trẻ này thích đưa những cái mới lạ vào phim."},{"type":"compound","zh":"做设计固然要创新，但是不能为了标新立异而忽视实用。","pinyin":"Zuò shèjì gùrán yào chuàngxīn, dànshì bù néng wèile biāoxīnlìyì ér hūshì shíyòng.","vi":"Làm thiết kế tất nhiên phải đổi mới, nhưng không thể vì muốn khác người mà xem nhẹ tính thực dụng."}],"related":[{"hanzi":"别出心裁","pinyin":"biéchūxīncái","vi":"sáng tạo độc đáo"},{"hanzi":"与众不同","pinyin":"yǔzhòngbùtóng","vi":"khác người"},{"hanzi":"创新","pinyin":"chuàngxīn","vi":"sáng tạo"},{"hanzi":"墨守成规","pinyin":"mòshǒuchéngguī","vi":"khư khư giữ lối cũ"}],"traditional":"標新立異"},{"id":"标语","hanzi":"标语","pinyin":"biāoyǔ","meaning_vi":"khẩu hiệu, biểu ngữ","explanation":"标 + 语 (lời nói).","hsk_level":6,"tags":["danh-tu","xa-hoi"],"image":"📢","examples":[{"type":"basic","zh":"墙上贴着标语。","pinyin":"Qiáng shang tiēzhe biāoyǔ.","vi":"Trên tường dán khẩu hiệu."},{"type":"simple","zh":"校门口挂着一条欢迎新生的红色标语。","pinyin":"Xiào ménkǒu guàzhe yì tiáo huānyíng xīnshēng de hóngsè biāoyǔ.","vi":"Trước cổng trường treo một băng rôn đỏ chào đón tân sinh viên."},{"type":"compound","zh":"只要走进这个工厂，就能看到安全生产的标语。","pinyin":"Zhǐyào zǒujìn zhè gè gōngchǎng, jiù néng kàndào ānquán shēngchǎn de biāoyǔ.","vi":"Chỉ cần bước vào nhà máy này là có thể thấy khẩu hiệu về sản xuất an toàn."}],"related":[{"hanzi":"口号","pinyin":"kǒuhào","vi":"khẩu hiệu"},{"hanzi":"横幅","pinyin":"héngfú","vi":"băng rôn"},{"hanzi":"广告","pinyin":"guǎnggào","vi":"quảng cáo"},{"hanzi":"海报","pinyin":"hǎibào","vi":"áp phích"}],"traditional":"標語"},{"id":"标致","hanzi":"标致","pinyin":"biāozhì","meaning_vi":"xinh đẹp, ưa nhìn (thường nói phụ nữ)","explanation":"标 (tiêu – dáng vẻ, phong thái) + 致 (trí – tinh tế, hấp dẫn) → xinh đẹp, ưa nhìn, chủ yếu khen phụ nữ. Cụm: 长得很标致.","hsk_level":6,"tags":["tinh-tu","con-nguoi"],"image":"😍","examples":[{"type":"basic","zh":"她长得很标致。","pinyin":"Tā zhǎngde hěn biāozhì.","vi":"Cô ấy trông rất xinh xắn."},{"type":"simple","zh":"新来的那位女老师模样十分标致。","pinyin":"Xīn lái de nà wèi nǚ lǎoshī múyàng shífēn biāozhì.","vi":"Cô giáo mới đến có dung mạo rất xinh đẹp."},{"type":"compound","zh":"她不但长得标致，而且说话很温柔。","pinyin":"Tā búdàn zhǎngde biāozhì, érqiě shuōhuà hěn wēnróu.","vi":"Cô ấy không những xinh xắn mà nói năng còn rất dịu dàng."}],"related":[{"hanzi":"漂亮","pinyin":"piàoliang","vi":"xinh đẹp"},{"hanzi":"美丽","pinyin":"měilì","vi":"đẹp"},{"hanzi":"秀丽","pinyin":"xiùlì","vi":"thanh tú"},{"hanzi":"俊俏","pinyin":"jùnqiào","vi":"xinh xắn"}],"traditional":"標致"},{"id":"扁","hanzi":"扁","pinyin":"biǎn","meaning_vi":"dẹt, bẹp","explanation":"扁 (biển) → dẹt, dẹp, bẹp. Ví dụ: 压扁了 (bị đè bẹp), 扁豆 (đậu ván); 别把人看扁了 = đừng xem thường người khác.","hsk_level":6,"tags":["tinh-tu"],"image":"🥞","examples":[{"type":"basic","zh":"盒子被压扁了。","pinyin":"Hézi bèi yābiǎn le.","vi":"Cái hộp bị đè bẹp rồi."},{"type":"simple","zh":"这个扁扁的铁罐子是用来装茶叶的。","pinyin":"Zhè gè biǎn biǎn de tiě guànzi shì yònglái zhuāng cháyè de.","vi":"Cái hộp sắt dẹt này dùng để đựng trà."},{"type":"compound","zh":"因为行李箱太满了，所以里面的蛋糕被压扁了。","pinyin":"Yīnwèi xínglixiāng tài mǎn le, suǒyǐ lǐmiàn de dàngāo bèi yābiǎn le.","vi":"Vì vali quá đầy nên chiếc bánh ngọt bên trong bị đè bẹp."}],"related":[{"hanzi":"扁平","pinyin":"biǎnpíng","vi":"dẹt phẳng"},{"hanzi":"圆","pinyin":"yuán","vi":"tròn"},{"hanzi":"压扁","pinyin":"yābiǎn","vi":"đè bẹp"},{"hanzi":"扁担","pinyin":"biǎndan","vi":"đòn gánh"}]},{"id":"贬义词","hanzi":"贬义词","pinyin":"biǎnyìcí","meaning_vi":"từ mang nghĩa xấu/chê bai","explanation":"贬义 + 词 (từ ngữ). Đối nghĩa với 褒义词.","hsk_level":6,"tags":["danh-tu","ngon-ngu","hoc-tap"],"image":"👎","examples":[{"type":"basic","zh":"这是个贬义词。","pinyin":"Zhè shì gè biǎnyìcí.","vi":"Đây là một từ mang nghĩa xấu."},{"type":"simple","zh":"骄傲在这个句子里是一个贬义词。","pinyin":"Jiāo'ào zài zhè gè jùzi li shì yí gè biǎnyìcí.","vi":"Trong câu này, từ kiêu ngạo là một từ mang nghĩa chê bai."},{"type":"compound","zh":"如果你不知道它是贬义词，就很容易在作文里用错。","pinyin":"Rúguǒ nǐ bù zhīdào tā shì biǎnyìcí, jiù hěn róngyì zài zuòwén li yòng cuò.","vi":"Nếu không biết đó là từ mang nghĩa xấu thì rất dễ dùng sai trong bài văn."}],"related":[{"hanzi":"褒义词","pinyin":"bāoyìcí","vi":"từ mang nghĩa tốt"},{"hanzi":"中性词","pinyin":"zhōngxìngcí","vi":"từ trung tính"},{"hanzi":"贬低","pinyin":"biǎndī","vi":"hạ thấp"},{"hanzi":"词语","pinyin":"cíyǔ","vi":"từ ngữ"}],"traditional":"貶義詞"},{"id":"贬值","hanzi":"贬值","pinyin":"biǎnzhí","meaning_vi":"mất giá (tiền tệ/hàng hóa)","explanation":"贬 (giảm) + 值 (giá trị). Đối nghĩa với 升值 (tăng giá trị).","hsk_level":6,"tags":["dong-tu","tien-te"],"image":"📉","examples":[{"type":"basic","zh":"这种货币贬值了。","pinyin":"Zhè zhǒng huòbì biǎnzhí le.","vi":"Đồng tiền này đã mất giá."},{"type":"simple","zh":"新车一开出店门就会贬值不少。","pinyin":"Xīnchē yì kāi chū diàn mén jiù huì biǎnzhí bùshǎo.","vi":"Xe mới vừa lăn bánh ra khỏi cửa hàng là đã mất giá không ít."},{"type":"compound","zh":"由于本国货币贬值，所以进口商品都涨价了。","pinyin":"Yóuyú běnguó huòbì biǎnzhí, suǒyǐ jìnkǒu shāngpǐn dōu zhǎngjià le.","vi":"Do đồng nội tệ mất giá nên hàng nhập khẩu đều tăng giá."}],"related":[{"hanzi":"升值","pinyin":"shēngzhí","vi":"tăng giá trị"},{"hanzi":"通货膨胀","pinyin":"tōnghuòpéngzhàng","vi":"lạm phát"},{"hanzi":"汇率","pinyin":"huìlǜ","vi":"tỷ giá"},{"hanzi":"保值","pinyin":"bǎozhí","vi":"giữ giá trị"}],"traditional":"貶值"},{"id":"表白","hanzi":"表白","pinyin":"biǎobái","meaning_vi":"tỏ tình, bày tỏ lòng mình","explanation":"表 (bày tỏ) + 白 (rõ ràng).","hsk_level":6,"tags":["dong-tu","cam-xuc"],"image":"💌","examples":[{"type":"basic","zh":"他向她表白了。","pinyin":"Tā xiàng tā biǎobái le.","vi":"Anh ấy đã tỏ tình với cô ấy."},{"type":"simple","zh":"他在毕业典礼上向暗恋多年的女孩表白。","pinyin":"Tā zài bìyè diǎnlǐ shang xiàng ànliàn duōnián de nǚhái biǎobái.","vi":"Anh ấy tỏ tình với cô gái mình thầm yêu nhiều năm trong lễ tốt nghiệp."},{"type":"compound","zh":"虽然他很想表白，但是一直没有勇气开口。","pinyin":"Suīrán tā hěn xiǎng biǎobái, dànshì yìzhí méiyǒu yǒngqì kāikǒu.","vi":"Tuy rất muốn tỏ tình nhưng anh ấy mãi không đủ can đảm mở lời."}],"related":[{"hanzi":"告白","pinyin":"gàobái","vi":"tỏ tình"},{"hanzi":"表达","pinyin":"biǎodá","vi":"bày tỏ"},{"hanzi":"倾诉","pinyin":"qīngsù","vi":"giãi bày"},{"hanzi":"求爱","pinyin":"qiú'ài","vi":"cầu tình"}]},{"id":"表决","hanzi":"表决","pinyin":"biǎojué","meaning_vi":"biểu quyết","explanation":"表 (biểu – bày tỏ) + 决 (quyết – quyết định) → bày tỏ ý kiến để đi đến quyết định, biểu quyết. Thường: 投票表决, 举手表决.","hsk_level":6,"tags":["dong-tu"],"image":"🙋","examples":[{"type":"basic","zh":"大家举手表决。","pinyin":"Dàjiā jǔshǒu biǎojué.","vi":"Mọi người giơ tay biểu quyết."},{"type":"simple","zh":"业主大会表决通过了更换物业公司的方案。","pinyin":"Yèzhǔ dàhuì biǎojué tōngguòle gēng huàn wùyè gōngsī de fāng'àn.","vi":"Hội nghị chủ hộ đã biểu quyết thông qua phương án thay công ty quản lý tòa nhà."},{"type":"compound","zh":"只要超过一半的人同意，这个提议就能表决通过。","pinyin":"Zhǐyào chāoguò yíbàn de rén tóngyì, zhè gè tíyì jiù néng biǎojué tōngguò.","vi":"Chỉ cần quá nửa số người đồng ý thì đề xuất này sẽ được biểu quyết thông qua."}],"related":[{"hanzi":"投票","pinyin":"tóupiào","vi":"bỏ phiếu"},{"hanzi":"举手表决","pinyin":"jǔshǒubiǎojué","vi":"biểu quyết giơ tay"},{"hanzi":"通过","pinyin":"tōngguò","vi":"thông qua"},{"hanzi":"否决","pinyin":"fǒujué","vi":"phủ quyết"}],"traditional":"表決"},{"id":"表面化","hanzi":"表面化","pinyin":"biǎomiànhuà","meaning_vi":"bộc lộ ra ngoài, trở nên công khai (mâu thuẫn, bất đồng)","explanation":"表面 (biểu diện – bề mặt) + 化 (hóa – trở thành) → nổi lên bề mặt: mâu thuẫn, bất đồng vốn ngầm nay lộ rõ công khai. Cụm: 矛盾表面化.","hsk_level":6,"tags":["dong-tu","tinh-tu"],"image":"🪞","examples":[{"type":"basic","zh":"矛盾表面化了。","pinyin":"Máodùn biǎomiànhuà le.","vi":"Mâu thuẫn đã bộc lộ ra ngoài."},{"type":"simple","zh":"两位合伙人之间的分歧终于表面化了。","pinyin":"Liǎng wèi héhuǒrén zhījiān de fēnqí zhōngyú biǎomiànhuà le.","vi":"Bất đồng giữa hai người cộng sự cuối cùng đã lộ rõ ra ngoài."},{"type":"compound","zh":"如果问题不及时解决，矛盾迟早就会表面化。","pinyin":"Rúguǒ wèntí bù jíshí jiějué, máodùn chízǎo jiù huì biǎomiànhuà.","vi":"Nếu vấn đề không được giải quyết kịp thời thì sớm muộn mâu thuẫn cũng sẽ bộc lộ ra ngoài."}],"related":[{"hanzi":"公开化","pinyin":"gōngkāihuà","vi":"công khai hóa"},{"hanzi":"暴露","pinyin":"bàolù","vi":"bộc lộ"},{"hanzi":"激化","pinyin":"jīhuà","vi":"trở nên gay gắt"},{"hanzi":"表面","pinyin":"biǎomiàn","vi":"bề mặt"}]},{"id":"表率","hanzi":"表率","pinyin":"biǎoshuài","meaning_vi":"tấm gương mẫu mực","explanation":"表 + 率 (dẫn đầu).","hsk_level":6,"tags":["danh-tu","con-nguoi"],"image":"🌟","examples":[{"type":"basic","zh":"父母是孩子的表率。","pinyin":"Fùmǔ shì háizi de biǎoshuài.","vi":"Cha mẹ là tấm gương cho con cái."},{"type":"simple","zh":"班长在劳动中为全班同学做出了表率。","pinyin":"Bānzhǎng zài láodòng zhōng wèi quánbān tóngxué zuòchūle biǎoshuài.","vi":"Lớp trưởng đã làm gương cho cả lớp trong buổi lao động."},{"type":"compound","zh":"领导既然要求员工守时，就应该先起表率作用。","pinyin":"Lǐngdǎo jìrán yāoqiú yuángōng shǒushí, jiù yīnggāi xiān qǐ biǎoshuài zuòyòng.","vi":"Lãnh đạo đã yêu cầu nhân viên đúng giờ thì trước hết nên làm gương."}],"related":[{"hanzi":"榜样","pinyin":"bǎngyàng","vi":"tấm gương"},{"hanzi":"模范","pinyin":"mófàn","vi":"mô phạm"},{"hanzi":"带头","pinyin":"dàitóu","vi":"đi đầu"},{"hanzi":"典范","pinyin":"diǎnfàn","vi":"điển hình"}]},{"id":"表扬信","hanzi":"表扬信","pinyin":"biǎoyángxìn","meaning_vi":"thư khen ngợi","explanation":"表扬 (biểu dương – khen ngợi) + 信 (tín – thư) → thư biểu dương, gửi cơ quan để khen người tốt việc tốt. Cụm: 写表扬信.","hsk_level":6,"tags":["danh-tu","giao-tiep"],"image":"💌","examples":[{"type":"basic","zh":"他收到一封表扬信。","pinyin":"Tā shōudào yì fēng biǎoyángxìn.","vi":"Anh ấy nhận được một lá thư khen ngợi."},{"type":"simple","zh":"乘客给公交公司写了一封表扬信。","pinyin":"Chéngkè gěi gōngjiāo gōngsī xiěle yì fēng biǎoyángxìn.","vi":"Hành khách đã viết một lá thư khen ngợi gửi công ty xe buýt."},{"type":"compound","zh":"因为她帮老人找回了钱包，所以学校收到了一封表扬信。","pinyin":"Yīnwèi tā bāng lǎorén zhǎohuíle qiánbāo, suǒyǐ xuéxiào shōudàole yì fēng biǎoyángxìn.","vi":"Vì cô bé giúp cụ già tìm lại ví tiền nên nhà trường đã nhận được một lá thư khen ngợi."}],"related":[{"hanzi":"感谢信","pinyin":"gǎnxièxìn","vi":"thư cảm ơn"},{"hanzi":"表扬","pinyin":"biǎoyáng","vi":"biểu dương"},{"hanzi":"批评","pinyin":"pīpíng","vi":"phê bình"},{"hanzi":"信件","pinyin":"xìnjiàn","vi":"thư từ"}],"traditional":"表揚信"},{"id":"罢工","hanzi":"罢工","pinyin":"bàgōng","meaning_vi":"đình công","explanation":"罢 (bãi – thôi, ngừng) + 工 (công – công việc) → ngừng làm việc → đình công, bãi công. Tương tự: 罢课 (bãi khóa), 罢市 (bãi thị).","hsk_level":6,"tags":["dong-tu"],"image":"✊","examples":[{"type":"basic","zh":"工人们罢工了。","pinyin":"Gōngrénmen bàgōng le.","vi":"Công nhân đã đình công."},{"type":"simple","zh":"航空公司的飞行员昨天宣布罢工三天。","pinyin":"Hángkōng gōngsī de fēixíngyuán zuótiān xuānbù bàgōng sān tiān.","vi":"Phi công của hãng hàng không hôm qua tuyên bố đình công ba ngày."},{"type":"compound","zh":"如果公司再拖欠工资，司机们就要罢工。","pinyin":"Rúguǒ gōngsī zài tuōqiàn gōngzī, sījīmen jiùyào bàgōng.","vi":"Nếu công ty còn nợ lương nữa thì các tài xế sẽ đình công."}],"related":[{"hanzi":"罢课","pinyin":"bàkè","vi":"bãi khóa"},{"hanzi":"工人","pinyin":"gōngrén","vi":"công nhân"},{"hanzi":"抗议","pinyin":"kàngyì","vi":"kháng nghị"},{"hanzi":"停工","pinyin":"tínggōng","vi":"ngừng làm việc"}],"traditional":"罷工"},{"id":"霸权","hanzi":"霸权","pinyin":"bàquán","meaning_vi":"bá quyền","explanation":"霸 (bá chủ) + 权 (quyền lực).","hsk_level":6,"tags":["danh-tu","xa-hoi"],"image":"👑","examples":[{"type":"basic","zh":"他们反对霸权。","pinyin":"Tāmen fǎnduì bàquán.","vi":"Họ phản đối bá quyền."},{"type":"simple","zh":"历史上很多大国都曾试图建立海上霸权。","pinyin":"Lìshǐshang hěn duōdà guódōu céng shìtú jiànlì hǎishàng bàquán.","vi":"Trong lịch sử, nhiều cường quốc từng tìm cách thiết lập bá quyền trên biển."},{"type":"compound","zh":"一个国家无论多强大，都不应该推行霸权。","pinyin":"Yí gè guójiā wúlùn duō qiángdà, dōu bù yīnggāi tuīxíng bàquán.","vi":"Một quốc gia dù hùng mạnh đến đâu cũng không nên thi hành chính sách bá quyền."}],"related":[{"hanzi":"霸权主义","pinyin":"bàquánzhǔyì","vi":"chủ nghĩa bá quyền"},{"hanzi":"强权","pinyin":"qiángquán","vi":"cường quyền"},{"hanzi":"霸主","pinyin":"bàzhǔ","vi":"bá chủ"},{"hanzi":"称霸","pinyin":"chēngbà","vi":"xưng bá"}],"traditional":"霸權"},{"id":"霸气","hanzi":"霸气","pinyin":"bàqì","meaning_vi":"khí chất bá đạo, uy phong mạnh mẽ","explanation":"霸 + 气 (khí chất).","hsk_level":6,"tags":["danh-tu","tinh-tu"],"image":"🦁","examples":[{"type":"basic","zh":"这个名字真霸气。","pinyin":"Zhè gè míngzi zhēn bàqì.","vi":"Cái tên này thật uy phong."},{"type":"simple","zh":"穿着黑色西装的她看起来特别霸气。","pinyin":"Chuānzhe hēisè xīzhuāng de tā kànqǐlái tèbié bàqì.","vi":"Cô ấy mặc bộ vest đen trông cực kỳ uy phong mạnh mẽ."},{"type":"compound","zh":"这位队长不但说话霸气，而且做事果断。","pinyin":"Zhè wèi duìzhǎng búdàn shuōhuà bàqì, érqiě zuòshì guǒduàn.","vi":"Vị đội trưởng này không những ăn nói uy phong mà còn làm việc quyết đoán."}],"related":[{"hanzi":"威风","pinyin":"wēifēng","vi":"oai phong"},{"hanzi":"气势","pinyin":"qìshì","vi":"khí thế"},{"hanzi":"霸道","pinyin":"bàdào","vi":"ngang ngược"},{"hanzi":"强势","pinyin":"qiángshì","vi":"mạnh mẽ"}],"traditional":"霸氣"},{"id":"霸占","hanzi":"霸占","pinyin":"bàzhàn","meaning_vi":"chiếm đoạt, ngang ngược chiếm giữ","explanation":"霸 (bá đạo) + 占 (chiếm).","hsk_level":6,"tags":["dong-tu"],"image":"🚫","examples":[{"type":"basic","zh":"他霸占了座位。","pinyin":"Tā bàzhànle zuòwèi.","vi":"Anh ta chiếm giữ chỗ ngồi."},{"type":"simple","zh":"弟弟一回家就霸占了电视遥控器。","pinyin":"Dìdi yì huíjiā jiù bàzhànle diànshì yáokòngqì.","vi":"Em trai vừa về nhà đã chiếm luôn cái điều khiển tivi."},{"type":"compound","zh":"那个恶霸不但霸占了村民的土地，还打伤了人。","pinyin":"Nà gè èbà búdàn bàzhànle cūnmín de tǔdì, hái dǎshāngle rén.","vi":"Tên cường hào đó không những chiếm đoạt đất của dân làng mà còn đánh người bị thương."}],"related":[{"hanzi":"侵占","pinyin":"qīnzhàn","vi":"xâm chiếm"},{"hanzi":"强占","pinyin":"qiángzhàn","vi":"chiếm đoạt cưỡng bức"},{"hanzi":"占据","pinyin":"zhànjù","vi":"chiếm giữ"},{"hanzi":"掠夺","pinyin":"lüèduó","vi":"cướp đoạt"}],"traditional":"霸佔"},{"id":"败坏","hanzi":"败坏","pinyin":"bàihuài","meaning_vi":"làm hư hỏng, suy đồi","explanation":"败 (bại – hỏng, thua) + 坏 (hoại – hư) → làm hư hỏng, bại hoại. Thường đi với 名誉, 风气, 道德: 败坏名声.","hsk_level":6,"tags":["dong-tu"],"image":"👎","examples":[{"type":"basic","zh":"他败坏了家风。","pinyin":"Tā bàihuàile jiāfēng.","vi":"Anh ta làm bại hoại nề nếp gia đình."},{"type":"simple","zh":"几个游客的不文明行为败坏了景区的名声。","pinyin":"Jǐ gè yóukè de bù wénmíng xíngwéi bàihuàile jǐngqū de míngshēng.","vi":"Hành vi thiếu văn minh của vài du khách đã làm hỏng danh tiếng khu du lịch."},{"type":"compound","zh":"如果任由腐败蔓延，社会风气就会被败坏。","pinyin":"Rúguǒ rènyóu fǔbài mànyán, shèhuì fēngqì jiù huì bèi bàihuài.","vi":"Nếu để mặc tham nhũng lan rộng thì phong khí xã hội sẽ bị suy đồi."}],"related":[{"hanzi":"腐败","pinyin":"fǔbài","vi":"hủ bại"},{"hanzi":"破坏","pinyin":"pòhuài","vi":"phá hoại"},{"hanzi":"堕落","pinyin":"duòluò","vi":"sa đọa"},{"hanzi":"败坏名声","pinyin":"bàihuàimíngshēng","vi":"làm hỏng danh tiếng"}],"traditional":"敗壞"},{"id":"败露","hanzi":"败露","pinyin":"bàilù","meaning_vi":"bại lộ (âm mưu/bí mật)","explanation":"败 (hỏng) + 露 (lộ ra).","hsk_level":6,"tags":["dong-tu"],"image":"🔓","examples":[{"type":"basic","zh":"他的阴谋败露了。","pinyin":"Tā de yīnmóu bàilù le.","vi":"Âm mưu của hắn đã bại lộ."},{"type":"simple","zh":"偷税的事情很快就败露了。","pinyin":"Tōushuì de shìqing hěn kuài jiù bàilù le.","vi":"Chuyện trốn thuế nhanh chóng bị bại lộ."},{"type":"compound","zh":"计划一败露，他就连夜逃到了外地。","pinyin":"Jì huàyī bàilù, tā jiù liányè táo dàole wàidì.","vi":"Kế hoạch vừa bại lộ, hắn liền bỏ trốn đi nơi khác ngay trong đêm."}],"related":[{"hanzi":"暴露","pinyin":"bàolù","vi":"bại lộ"},{"hanzi":"泄露","pinyin":"xièlòu","vi":"tiết lộ"},{"hanzi":"揭露","pinyin":"jiēlù","vi":"vạch trần"},{"hanzi":"事情败露","pinyin":"shìqingbàilù","vi":"sự việc bại lộ"}],"traditional":"敗露"},{"id":"办公","hanzi":"办公","pinyin":"bàngōng","meaning_vi":"làm việc văn phòng","explanation":"办 (làm) + 公 (công việc). Cụm: 办公室.","hsk_level":6,"tags":["dong-tu","cong-viec"],"image":"💼","examples":[{"type":"basic","zh":"他在家办公。","pinyin":"Tā zài jiā bàngōng.","vi":"Anh ấy làm việc tại nhà."},{"type":"simple","zh":"新的办公大楼下个月就能投入使用。","pinyin":"Xīn de bàngōng dàlóu xiàgèyuè jiù néng tóurù shǐyòng.","vi":"Tòa nhà văn phòng mới tháng sau có thể đưa vào sử dụng."},{"type":"compound","zh":"自从公司允许远程办公，我就不用每天挤地铁了。","pinyin":"Zìcóng gōngsī yǔnxǔ yuǎnchéngbàngōng, wǒ jiù bú yòng měitiān jǐ dìtiě le.","vi":"Từ khi công ty cho phép làm việc từ xa, tôi không phải chen chúc tàu điện ngầm mỗi ngày nữa."}],"related":[{"hanzi":"办公室","pinyin":"bàngōngshì","vi":"văn phòng"},{"hanzi":"上班","pinyin":"shàngbān","vi":"đi làm"},{"hanzi":"办公楼","pinyin":"bàngōnglóu","vi":"tòa văn phòng"},{"hanzi":"办事","pinyin":"bànshì","vi":"làm việc"}],"traditional":"辦公"},{"id":"伴随","hanzi":"伴随","pinyin":"bànsuí","meaning_vi":"đi kèm theo","explanation":"伴 (bạn – đi cùng) + 随 (tùy – theo) → đi theo, kèm theo. Thường: 伴随着…, 伴随而来的问题.","hsk_level":6,"tags":["dong-tu"],"image":"👣","examples":[{"type":"basic","zh":"音乐伴随着我长大。","pinyin":"Yīnyuè bàn suízhe wǒ zhǎngdà.","vi":"Âm nhạc đồng hành cùng tôi lớn lên."},{"type":"simple","zh":"伴随着一声巨响，整栋旧楼倒塌了。","pinyin":"Bàn suízhe yìshēng jùxiǎng, zhěng dòng jiù lóu dǎotā le.","vi":"Kèm theo một tiếng nổ lớn, cả tòa nhà cũ sụp đổ."},{"type":"compound","zh":"虽然城市发展很快，但是也伴随着交通拥堵的问题。","pinyin":"Suīrán chéngshì fāzhǎn hěn kuài, dànshì yě bàn suízhe jiāotōng yōngdǔ de wèntí.","vi":"Tuy thành phố phát triển nhanh nhưng cũng kéo theo vấn đề tắc nghẽn giao thông."}],"related":[{"hanzi":"陪伴","pinyin":"péibàn","vi":"bầu bạn"},{"hanzi":"随着","pinyin":"suízhe","vi":"cùng với"},{"hanzi":"跟随","pinyin":"gēnsuí","vi":"đi theo"},{"hanzi":"伴侣","pinyin":"bànlǚ","vi":"bạn đời"}],"traditional":"伴隨"},{"id":"半信半疑","hanzi":"半信半疑","pinyin":"bànxìn-bànyí","meaning_vi":"nửa tin nửa ngờ","explanation":"半信半疑: nửa tin nửa ngờ → chưa tin hẳn, còn hoài nghi. Ví dụ: 他半信半疑地看着我.","hsk_level":6,"tags":["thanh-ngu"],"image":"🤔","examples":[{"type":"basic","zh":"他半信半疑地点头。","pinyin":"Tā bànxìnbànyí dediǎn tóu.","vi":"Anh ấy nửa tin nửa ngờ gật đầu."},{"type":"simple","zh":"奶奶对网上的养生广告总是半信半疑。","pinyin":"Nǎinai duì wǎngshang de yǎngshēng guǎnggào zǒngshì bànxìnbànyí.","vi":"Bà luôn nửa tin nửa ngờ với quảng cáo dưỡng sinh trên mạng."},{"type":"compound","zh":"虽然朋友说得很肯定，但是我还是半信半疑。","pinyin":"Suīrán péngyou shuō de hěn kěndìng, dànshì wǒ háishi bànxìnbànyí.","vi":"Tuy bạn nói rất chắc chắn nhưng tôi vẫn nửa tin nửa ngờ."}],"related":[{"hanzi":"将信将疑","pinyin":"jiāngxìnjiāngyí","vi":"nửa tin nửa ngờ"},{"hanzi":"怀疑","pinyin":"huáiyí","vi":"nghi ngờ"},{"hanzi":"深信不疑","pinyin":"shēnxìnbùyí","vi":"tin tưởng tuyệt đối"},{"hanzi":"犹豫","pinyin":"yóuyù","vi":"do dự"}]},{"id":"半夜三更","hanzi":"半夜三更","pinyin":"bànyè-sāngēng","meaning_vi":"nửa đêm canh ba, đêm khuya thanh vắng","explanation":"半夜三更: nửa đêm, canh ba (đêm chia năm canh, canh ba khoảng 23 giờ đến 1 giờ) → đêm khuya khoắt. Ví dụ: 半夜三更才回家.","hsk_level":6,"tags":["thanh-ngu","thoi-gian"],"image":"🌃","examples":[{"type":"basic","zh":"半夜三更谁敲门？","pinyin":"Bànyèsāngēng shéi qiāomén?","vi":"Nửa đêm canh ba ai gõ cửa thế?"},{"type":"simple","zh":"邻居半夜三更还在楼上装修房子。","pinyin":"Línjū bànyèsāngēng hái zài lóushàng zhuāngxiū fángzi.","vi":"Nửa đêm canh ba mà hàng xóm tầng trên vẫn còn sửa nhà."},{"type":"compound","zh":"如果你半夜三更还不睡，明天就没精神上班了。","pinyin":"Rúguǒ nǐ bànyèsāngēng hái bú shuì, míngtiān jiù méi jīngshen shàngbān le.","vi":"Nếu nửa đêm canh ba cậu còn chưa ngủ thì mai sẽ không có sức đi làm."}],"related":[{"hanzi":"深更半夜","pinyin":"shēngēngbànyè","vi":"đêm khuya"},{"hanzi":"半夜","pinyin":"bànyè","vi":"nửa đêm"},{"hanzi":"深夜","pinyin":"shēnyè","vi":"đêm khuya"},{"hanzi":"凌晨","pinyin":"língchén","vi":"rạng sáng"}]},{"id":"半真半假","hanzi":"半真半假","pinyin":"bànzhēn-bànjiǎ","meaning_vi":"nửa thật nửa giả","explanation":"半真半假: nửa thật nửa giả → lời nói, việc làm lẫn lộn thật giả, khó phân biệt; hay dùng cho kiểu nói nửa đùa nửa thật.","hsk_level":6,"tags":["thanh-ngu"],"image":"🎭","examples":[{"type":"basic","zh":"他的话半真半假。","pinyin":"Tā dehuà bànzhēnbànjiǎ.","vi":"Lời anh ta nửa thật nửa giả."},{"type":"simple","zh":"她半真半假地说要辞职去旅行。","pinyin":"Tā bànzhēnbànjiǎ de shuō yào cízhí qù lǚxíng.","vi":"Cô ấy nửa đùa nửa thật nói muốn nghỉ việc để đi du lịch."},{"type":"compound","zh":"因为这份简历半真半假，所以公司没有录用他。","pinyin":"Yīnwèi zhè fèn jiǎnlì bànzhēnbànjiǎ, suǒyǐ gōngsī méiyǒu lùyòng tā.","vi":"Vì bản lý lịch này nửa thật nửa giả nên công ty không tuyển anh ta."}],"related":[{"hanzi":"真假","pinyin":"zhēnjiǎ","vi":"thật giả"},{"hanzi":"虚实","pinyin":"xūshí","vi":"hư thực"},{"hanzi":"半信半疑","pinyin":"bànxìnbànyí","vi":"nửa tin nửa ngờ"},{"hanzi":"真真假假","pinyin":"zhēnzhēnjiǎjiǎ","vi":"thật thật giả giả"}]},{"id":"伴奏","hanzi":"伴奏","pinyin":"bànzòu","meaning_vi":"đệm nhạc, hòa tấu đệm","explanation":"伴 (đi kèm) + 奏 (tấu nhạc).","hsk_level":6,"tags":["dong-tu","giai-tri"],"image":"🎹","examples":[{"type":"basic","zh":"她弹钢琴伴奏。","pinyin":"Tā tángāngqín bànzòu.","vi":"Cô ấy đệm đàn piano."},{"type":"simple","zh":"合唱团在吉他的伴奏下唱完了这首歌。","pinyin":"Héchàngtuán zài jítā de bànzòu xià chàng wánle zhè shǒu gē.","vi":"Dàn hợp xướng hát xong bài này cùng tiếng đàn guitar đệm theo."},{"type":"compound","zh":"如果没有乐队伴奏，我们就只能清唱了。","pinyin":"Rúguǒ méiyǒu yuèduì bànzòu, wǒmen jiù zhǐnéng qīngchàng le.","vi":"Nếu không có ban nhạc đệm thì chúng ta chỉ có thể hát chay thôi."}],"related":[{"hanzi":"伴唱","pinyin":"bànchàng","vi":"hát đệm"},{"hanzi":"演奏","pinyin":"yǎnzòu","vi":"biểu diễn nhạc"},{"hanzi":"乐队","pinyin":"yuèduì","vi":"ban nhạc"},{"hanzi":"钢琴伴奏","pinyin":"gāngqínbànzòu","vi":"đệm đàn piano"}]},{"id":"傍晚时分","hanzi":"傍晚时分","pinyin":"bàngwǎnshífēn","meaning_vi":"vào lúc chập tối","explanation":"傍晚 (bạng vãn – gần tối) + 时分 (thời phân – lúc, khoảng thời gian) → vào lúc chập tối, khi trời sắp tối. Văn viết, hay dùng trong miêu tả.","hsk_level":6,"tags":["danh-tu","thoi-gian"],"image":"🌆","examples":[{"type":"basic","zh":"傍晚时分起风了。","pinyin":"Bàngwǎnshífēn qǐ fēng le.","vi":"Lúc chập tối trời nổi gió."},{"type":"simple","zh":"傍晚时分，渔船陆续回到了港口。","pinyin":"Bàngwǎnshífēn, yúchuán lùxù huídàole gǎngkǒu.","vi":"Lúc chập tối, những chiếc thuyền đánh cá lần lượt trở về cảng."},{"type":"compound","zh":"每到傍晚时分，公园里就挤满了散步的人。","pinyin":"Měi dào bàngwǎnshífēn, gōngyuán li jiù jǐmǎnle sànbù de rén.","vi":"Cứ đến lúc chập tối, công viên lại chật kín người đi dạo."}],"related":[{"hanzi":"傍晚","pinyin":"bàngwǎn","vi":"chập tối"},{"hanzi":"黄昏","pinyin":"huánghūn","vi":"hoàng hôn"},{"hanzi":"日落","pinyin":"rìluò","vi":"mặt trời lặn"},{"hanzi":"清晨","pinyin":"qīngchén","vi":"sáng sớm"}],"traditional":"傍晚時分"},{"id":"报仇","hanzi":"报仇","pinyin":"bàochóu","meaning_vi":"báo thù","explanation":"报 (báo – đáp trả) + 仇 (cừu – thù) → trả thù, báo thù. Ví dụ: 为父报仇; 报仇雪恨 (rửa hận).","hsk_level":6,"tags":["dong-tu"],"image":"⚔️","examples":[{"type":"basic","zh":"他发誓要报仇。","pinyin":"Tā fāshì yào bàochóu.","vi":"Anh ta thề sẽ báo thù."},{"type":"simple","zh":"电影里的主角花了十年时间为父亲报仇。","pinyin":"Diànyǐng li de zhǔjué huāle shí nián shíjiān wèi fùqīn bàochóu.","vi":"Nhân vật chính trong phim mất mười năm để báo thù cho cha."},{"type":"compound","zh":"与其一心想着报仇，不如好好过自己的生活。","pinyin":"Yǔqí yìxīn xiǎngzhe bàochóu, bùrú hǎo hǎoguò zìjǐ de shēnghuó.","vi":"Thay vì chỉ chăm chăm nghĩ đến báo thù, chi bằng sống tốt cuộc đời mình."}],"related":[{"hanzi":"报复","pinyin":"bàofù","vi":"trả thù"},{"hanzi":"复仇","pinyin":"fùchóu","vi":"phục thù"},{"hanzi":"仇恨","pinyin":"chóuhèn","vi":"thù hận"},{"hanzi":"报恩","pinyin":"bào'ēn","vi":"báo ân"}],"traditional":"報仇"},{"id":"报复","hanzi":"报复","pinyin":"bàofù","meaning_vi":"trả thù, báo thù","explanation":"报 (đáp trả) + 复 (lại).","hsk_level":6,"tags":["dong-tu"],"image":"⚔️","examples":[{"type":"basic","zh":"他想报复同事。","pinyin":"Tā xiǎng bàofù tóngshì.","vi":"Anh ta muốn trả thù đồng nghiệp."},{"type":"simple","zh":"被辞退的员工删除了公司数据进行报复。","pinyin":"Bèi cítuì de yuángōng shānchúle gōngsī shùjù jìnxíng bàofù.","vi":"Nhân viên bị sa thải đã xóa dữ liệu công ty để trả thù."},{"type":"compound","zh":"他因为害怕遭到报复，所以不敢出来作证。","pinyin":"Tā yīnwèi hàipà zāodào bàofù, suǒyǐ bù gǎn chūlái zuòzhèng.","vi":"Vì sợ bị trả thù nên anh ấy không dám ra làm chứng."}],"related":[{"hanzi":"报仇","pinyin":"bàochóu","vi":"báo thù"},{"hanzi":"复仇","pinyin":"fùchóu","vi":"phục thù"},{"hanzi":"报复心","pinyin":"bàofùxīn","vi":"lòng thù hận"},{"hanzi":"宽恕","pinyin":"kuānshù","vi":"tha thứ"}],"traditional":"報復"},{"id":"暴风骤雨","hanzi":"暴风骤雨","pinyin":"bàofēng-zhòuyǔ","meaning_vi":"mưa to gió lớn, bão táp mưa sa","explanation":"暴风骤雨: gió dữ và mưa xối xả bất ngờ → mưa to gió lớn; nghĩa bóng: phong trào, sự việc diễn ra dữ dội, mạnh mẽ.","hsk_level":6,"tags":["thanh-ngu","thoi-tiet"],"image":"⛈️","examples":[{"type":"basic","zh":"外面暴风骤雨。","pinyin":"Wàimiàn bàofēngzhòuyǔ.","vi":"Bên ngoài mưa to gió lớn."},{"type":"simple","zh":"一场暴风骤雨把院子里的花全打落了。","pinyin":"Yì cháng bàofēngzhòuyǔ bǎ yuànzi li de huā quán dǎ luò le.","vi":"Một trận mưa to gió lớn đã làm rụng hết hoa trong sân."},{"type":"compound","zh":"即使是暴风骤雨的夜晚，快递员也准时送来了包裹。","pinyin":"Jíshǐ shì bàofēngzhòuyǔ de yèwǎn, kuàidìyuán yě zhǔnshí sòng láile bāoguǒ.","vi":"Dù là đêm mưa gió bão bùng, người giao hàng vẫn mang bưu kiện đến đúng giờ."}],"related":[{"hanzi":"狂风暴雨","pinyin":"kuángfēngbàoyǔ","vi":"mưa to gió lớn"},{"hanzi":"暴风雨","pinyin":"bàofēngyǔ","vi":"bão táp"},{"hanzi":"风平浪静","pinyin":"fēngpínglàngjìng","vi":"sóng yên gió lặng"},{"hanzi":"雷雨","pinyin":"léiyǔ","vi":"mưa giông"}],"traditional":"暴風驟雨"},{"id":"曝光率","hanzi":"曝光率","pinyin":"bàoguānglǜ","meaning_vi":"tần suất xuất hiện trước công chúng/truyền thông","explanation":"曝光 (bộc quang – phơi ra ánh sáng, lên truyền thông) + 率 (suất – tỷ lệ) → mức độ xuất hiện trước công chúng, truyền thông. Cụm: 提高曝光率.","hsk_level":6,"tags":["danh-tu","cong-nghe"],"image":"📸","examples":[{"type":"basic","zh":"她的曝光率很高。","pinyin":"Tā de bàoguānglǜ hěn gāo.","vi":"Tần suất xuất hiện trước công chúng của cô ấy rất cao."},{"type":"simple","zh":"这部热播剧让男主角的曝光率大大提高。","pinyin":"Zhè bù rèbōjù ràng nánzhǔjué de bàoguānglǜ dàdà tígāo.","vi":"Bộ phim ăn khách này giúp nam chính xuất hiện trên truyền thông nhiều hơn hẳn."},{"type":"compound","zh":"为了提高品牌的曝光率，公司请了很多网红来做直播。","pinyin":"Wèile tígāo pǐnpái de bàoguānglǜ, gōngsī qǐngle hěn duō wǎnghóng lái zuò zhíbō.","vi":"Để tăng độ phủ sóng của thương hiệu, công ty đã mời nhiều người nổi tiếng trên mạng đến livestream."}],"related":[{"hanzi":"曝光","pinyin":"bàoguāng","vi":"phơi bày, lên sóng"},{"hanzi":"知名度","pinyin":"zhīmíngdù","vi":"độ nổi tiếng"},{"hanzi":"媒体","pinyin":"méitǐ","vi":"truyền thông"},{"hanzi":"关注度","pinyin":"guānzhùdù","vi":"mức độ quan tâm"}]},{"id":"报警","hanzi":"报警","pinyin":"bàojǐng","meaning_vi":"báo cảnh sát","explanation":"报 (báo – báo cho biết) + 警 (cảnh – cảnh báo, cảnh sát) → báo cảnh sát hoặc phát tín hiệu báo động. Ở Trung Quốc gọi số 110 để 报警.","hsk_level":6,"tags":["dong-tu"],"image":"🚔","examples":[{"type":"basic","zh":"快打电话报警！","pinyin":"Kuài dǎdiànhuà bàojǐng!","vi":"Mau gọi điện báo cảnh sát!"},{"type":"simple","zh":"她发现家门被撬开后立刻报警了。","pinyin":"Tā fāxiàn jiāmén bèi qiàokāi hòu lìkè bàojǐng le.","vi":"Phát hiện cửa nhà bị cạy, cô ấy lập tức báo cảnh sát."},{"type":"compound","zh":"如果遇到可疑的人，就要马上报警。","pinyin":"Rúguǒ yùdào kěyí de rén, jiùyào mǎshàng bàojǐng.","vi":"Nếu gặp người khả nghi thì phải báo cảnh sát ngay."}],"related":[{"hanzi":"警察","pinyin":"jǐngchá","vi":"cảnh sát"},{"hanzi":"报案","pinyin":"bào'àn","vi":"trình báo vụ án"},{"hanzi":"警报","pinyin":"jǐngbào","vi":"còi báo động"},{"hanzi":"求救","pinyin":"qiújiù","vi":"cầu cứu"}],"traditional":"報警"},{"id":"报刊","hanzi":"报刊","pinyin":"bàokān","meaning_vi":"báo chí và tạp chí","explanation":"报 (báo) + 刊 (tạp chí).","hsk_level":6,"tags":["danh-tu","van-hoa"],"image":"📰","examples":[{"type":"basic","zh":"他爱看报刊。","pinyin":"Tā ài kàn bàokān.","vi":"Anh ấy thích đọc báo và tạp chí."},{"type":"simple","zh":"图书馆的阅览室里有上百种报刊。","pinyin":"Túshūguǎn de yuèlǎnshì li yǒu shàng bǎi zhǒng bàokān.","vi":"Phòng đọc của thư viện có hơn một trăm loại báo và tạp chí."},{"type":"compound","zh":"虽然网络新闻越来越多，但是爷爷还是习惯订阅报刊。","pinyin":"Suīrán wǎngluò xīnwén yuèláiyuè duō, dànshì yéye háishi xíguàn dìngyuè bàokān.","vi":"Tuy tin tức trên mạng ngày càng nhiều nhưng ông vẫn quen đặt mua báo và tạp chí."}],"related":[{"hanzi":"报纸","pinyin":"bàozhǐ","vi":"báo"},{"hanzi":"杂志","pinyin":"zázhì","vi":"tạp chí"},{"hanzi":"期刊","pinyin":"qīkān","vi":"tạp chí định kỳ"},{"hanzi":"媒体","pinyin":"méitǐ","vi":"truyền thông"}],"traditional":"報刊"},{"id":"报刊亭","hanzi":"报刊亭","pinyin":"bàokāntíng","meaning_vi":"sạp báo, quầy bán báo chí","explanation":"报刊 + 亭 (gian hàng nhỏ).","hsk_level":6,"tags":["danh-tu","dia-diem"],"image":"📰","examples":[{"type":"basic","zh":"路口有个报刊亭。","pinyin":"Lùkǒu yǒu gè bàokāntíng.","vi":"Ở ngã tư có một sạp báo."},{"type":"simple","zh":"我在地铁站旁的报刊亭买了一本杂志。","pinyin":"Wǒ zài dìtiězhàn páng de bàokāntíng mǎile yì běn zázhì.","vi":"Tôi mua một cuốn tạp chí ở sạp báo cạnh ga tàu điện ngầm."},{"type":"compound","zh":"因为大家都用手机看新闻，所以街上的报刊亭越来越少了。","pinyin":"Yīnwèi dàjiā dōu yòng shǒujī kàn xīnwén, suǒyǐ jiēshang de bàokāntíng yuèláiyuè shǎo le.","vi":"Vì mọi người đều xem tin tức trên điện thoại nên sạp báo trên phố ngày càng ít."}],"related":[{"hanzi":"报摊","pinyin":"bàotān","vi":"sạp báo"},{"hanzi":"报纸","pinyin":"bàozhǐ","vi":"báo"},{"hanzi":"杂志","pinyin":"zázhì","vi":"tạp chí"},{"hanzi":"小卖部","pinyin":"xiǎomàibù","vi":"tiệm tạp hóa nhỏ"}],"traditional":"報刊亭"},{"id":"暴力","hanzi":"暴力","pinyin":"bàolì","meaning_vi":"bạo lực","explanation":"暴 (bạo – hung dữ) + 力 (lực – sức) → dùng sức mạnh hung bạo, bạo lực. Ví dụ: 家庭暴力 (bạo lực gia đình), 暴力事件.","hsk_level":6,"tags":["danh-tu"],"image":"⚠️","examples":[{"type":"basic","zh":"暴力解决不了问题。","pinyin":"Bàolì jiějué bùliǎo wèntí.","vi":"Bạo lực không giải quyết được vấn đề."},{"type":"simple","zh":"这部电影因为暴力镜头太多被禁止播放。","pinyin":"Zhè bù diànyǐng yīnwèi bàolì jìngtóu tài duō bèi jìnzhǐ bōfàng.","vi":"Bộ phim này bị cấm chiếu vì có quá nhiều cảnh bạo lực."},{"type":"compound","zh":"如果孩子在学校遭受语言暴力，家长就应该及时跟老师沟通。","pinyin":"Rúguǒ háizi zài xuéxiào zāoshòu yǔyán bàolì, jiāzhǎng jiù yīnggāi jíshí gēn lǎoshī gōutōng.","vi":"Nếu con bị bạo lực ngôn từ ở trường thì phụ huynh nên kịp thời trao đổi với giáo viên."}],"related":[{"hanzi":"家庭暴力","pinyin":"jiātíngbàolì","vi":"bạo lực gia đình"},{"hanzi":"暴力倾向","pinyin":"bàolìqīngxiàng","vi":"khuynh hướng bạo lực"},{"hanzi":"非暴力","pinyin":"fēibàolì","vi":"phi bạo lực"},{"hanzi":"武力","pinyin":"wǔlì","vi":"vũ lực"}]},{"id":"暴利","hanzi":"暴利","pinyin":"bàolì","meaning_vi":"lợi nhuận kếch xù bất chính","explanation":"暴 (dữ dội) + 利 (lợi ích).","hsk_level":6,"tags":["danh-tu","tien-te"],"image":"💰","examples":[{"type":"basic","zh":"他们靠走私牟取暴利。","pinyin":"Tāmen kào zǒusī móuqǔ bàolì.","vi":"Họ dựa vào buôn lậu để kiếm lợi nhuận kếch xù."},{"type":"simple","zh":"有些商家在节假日哄抬房价获取暴利。","pinyin":"Yǒuxiē shāngjiā zài jiéjiàrì hōngtái fángjià huòqǔ bàolì.","vi":"Một số nhà kinh doanh đẩy giá phòng lên vào dịp lễ để thu lợi kếch xù."},{"type":"compound","zh":"即使能赚取暴利，我们也不能卖假冒产品。","pinyin":"Jíshǐ néng zhuànqǔ bàolì, wǒmen yě bù néng mài jiǎmào chǎnpǐn.","vi":"Dù có thể kiếm lời kếch xù, chúng ta cũng không được bán hàng giả."}],"related":[{"hanzi":"利润","pinyin":"lìrùn","vi":"lợi nhuận"},{"hanzi":"牟取暴利","pinyin":"móuqǔbàolì","vi":"kiếm lời kếch xù"},{"hanzi":"微利","pinyin":"wēilì","vi":"lãi mỏng"},{"hanzi":"奸商","pinyin":"jiānshāng","vi":"gian thương"}]},{"id":"爆炸","hanzi":"爆炸","pinyin":"bàozhà","meaning_vi":"nổ, vụ nổ","explanation":"爆 (bộc – nổ tung) + 炸 (tạc – nổ) → nổ, vụ nổ. Ví dụ: 发生爆炸; nghĩa bóng: 信息爆炸 (bùng nổ thông tin).","hsk_level":6,"tags":["dong-tu"],"image":"💥","examples":[{"type":"basic","zh":"工厂发生了爆炸。","pinyin":"Gōngchǎng fāshēngle bàozhà.","vi":"Nhà máy đã xảy ra vụ nổ."},{"type":"simple","zh":"那辆汽车在停车场突然爆炸了。","pinyin":"Nà liàng qìchē zài tíngchēchǎng tūrán bàozhà le.","vi":"Chiếc ô tô đó bất ngờ phát nổ trong bãi đỗ xe."},{"type":"compound","zh":"煤气一泄漏，遇到火星就可能爆炸。","pinyin":"Méiqì yí xièlòu, yùdào huǒxīng jiù kěnéng bàozhà.","vi":"Khí ga một khi rò rỉ, gặp tia lửa là có thể phát nổ."}],"related":[{"hanzi":"爆炸案","pinyin":"bàozhà'àn","vi":"vụ đánh bom"},{"hanzi":"炸弹","pinyin":"zhàdàn","vi":"quả bom"},{"hanzi":"爆发","pinyin":"bàofā","vi":"bùng nổ"},{"hanzi":"信息爆炸","pinyin":"xìnxībàozhà","vi":"bùng nổ thông tin"}]},{"id":"暴躁","hanzi":"暴躁","pinyin":"bàozào","meaning_vi":"nóng nảy, cộc cằn","explanation":"暴 (hung dữ) + 躁 (nóng tính).","hsk_level":6,"tags":["tinh-tu","con-nguoi"],"image":"😡","examples":[{"type":"basic","zh":"他脾气很暴躁。","pinyin":"Tā píqi hěn bàozào.","vi":"Anh ấy tính khí rất nóng nảy."},{"type":"simple","zh":"睡眠不足的人容易变得暴躁。","pinyin":"Shuìmián bùzú de rén róngyì biànde bàozào.","vi":"Người thiếu ngủ dễ trở nên cáu kỉnh nóng nảy."},{"type":"compound","zh":"他虽然性格暴躁，但是对孩子特别有耐心。","pinyin":"Tā suīrán xìnggé bàozào, dànshì duì háizi tèbié yǒu nàixīn.","vi":"Anh ấy tuy tính nóng nảy nhưng lại rất kiên nhẫn với trẻ con."}],"related":[{"hanzi":"急躁","pinyin":"jízào","vi":"nóng vội"},{"hanzi":"脾气","pinyin":"píqi","vi":"tính khí"},{"hanzi":"暴脾气","pinyin":"bàopíqi","vi":"tính nóng nảy"},{"hanzi":"温和","pinyin":"wēnhé","vi":"ôn hòa"}]},{"id":"拔","hanzi":"拔","pinyin":"bá","meaning_vi":"nhổ, kéo ra, rút","explanation":"Bộ tài gảy 扌+ 友. Cụm: 拔牙 (nhổ răng), 拔河 (kéo co).","hsk_level":6,"tags":["dong-tu"],"image":"🦷","examples":[{"type":"basic","zh":"他拔了一颗牙。","pinyin":"Tā bále yì kē yá.","vi":"Anh ấy đã nhổ một chiếc răng."},{"type":"simple","zh":"周末我们去菜园里帮奶奶拔草。","pinyin":"Zhōumò wǒmen qù càiyuán li bāng nǎinai bácǎo.","vi":"Cuối tuần chúng tôi ra vườn rau giúp bà nhổ cỏ."},{"type":"compound","zh":"他一拔出瓶塞，香槟就喷了出来。","pinyin":"Tā yì báchū píngsāi, xiāngbīn jiù pēnle chūlái.","vi":"Anh ấy vừa rút nút chai ra, rượu sâm panh liền trào ra ngoài."}],"related":[{"hanzi":"拔河","pinyin":"báhé","vi":"kéo co"},{"hanzi":"拔草","pinyin":"bácǎo","vi":"nhổ cỏ"},{"hanzi":"拔牙","pinyin":"báyá","vi":"nhổ răng"},{"hanzi":"拔出","pinyin":"báchū","vi":"rút ra"}]},{"id":"白白","hanzi":"白白","pinyin":"báibái","meaning_vi":"uổng công, vô ích, không công","explanation":"Lặp lại chữ 白.","hsk_level":6,"tags":["pho-tu"],"image":"🤷","examples":[{"type":"basic","zh":"钱白白浪费了。","pinyin":"Qián báibái làngfèi le.","vi":"Tiền bị lãng phí vô ích."},{"type":"simple","zh":"我们在门口白白等了他两个小时。","pinyin":"Wǒmen zài ménkǒu báibái děngle tā liǎng gè xiǎoshí.","vi":"Chúng tôi đã chờ anh ta vô ích suốt hai tiếng ở cổng."},{"type":"compound","zh":"如果你不按时复习，前面的努力就白白浪费了。","pinyin":"Rúguǒ nǐ bú ànshí fùxí, qiánmiàn de nǔlì jiù báibái làngfèi le.","vi":"Nếu cậu không ôn tập đúng hạn thì công sức trước đó sẽ bị phí hoài."}],"related":[{"hanzi":"白费","pinyin":"báifèi","vi":"uổng phí"},{"hanzi":"徒劳","pinyin":"túláo","vi":"uổng công"},{"hanzi":"浪费","pinyin":"làngfèi","vi":"lãng phí"},{"hanzi":"白搭","pinyin":"báidā","vi":"vô ích"}]},{"id":"白费","hanzi":"白费","pinyin":"báifèi","meaning_vi":"uổng phí, lãng phí công sức","explanation":"白 (trắng tay/vô ích) + 费 (tốn).","hsk_level":6,"tags":["dong-tu"],"image":"💸","examples":[{"type":"basic","zh":"我的心血白费了。","pinyin":"Wǒ de xīnxuè báifèi le.","vi":"Tâm huyết của tôi đã uổng phí rồi."},{"type":"simple","zh":"一场大雨让我们一上午的准备全白费了。","pinyin":"Yì cháng dàyǔ ràng wǒmen yí shàngwǔ de zhǔnbèi quán báifèi le.","vi":"Một trận mưa lớn khiến công chuẩn bị cả buổi sáng của chúng tôi thành công cốc."},{"type":"compound","zh":"既然他不听劝，你就别白费口舌了。","pinyin":"Jìrán tā bù tīngquàn, nǐ jiù bié báifèi kǒushé le.","vi":"Anh ta đã không nghe khuyên thì cậu đừng phí lời nữa."}],"related":[{"hanzi":"白白","pinyin":"báibái","vi":"uổng công"},{"hanzi":"浪费","pinyin":"làngfèi","vi":"lãng phí"},{"hanzi":"徒劳","pinyin":"túláo","vi":"uổng công"},{"hanzi":"白费力气","pinyin":"báifèilìqi","vi":"phí sức"}],"traditional":"白費"},{"id":"白领","hanzi":"白领","pinyin":"báilǐng","meaning_vi":"dân văn phòng, lao động trí óc (cổ cồn trắng)","explanation":"白 (trắng) + 领 (cổ áo). Đối ứng với 蓝领 (công nhân).","hsk_level":6,"tags":["danh-tu","nghe-nghiep","con-nguoi"],"image":"👔","examples":[{"type":"basic","zh":"她是一名白领。","pinyin":"Tā shì yì míng báilǐng.","vi":"Cô ấy là một nhân viên văn phòng."},{"type":"simple","zh":"很多白领中午只在工位上吃个外卖。","pinyin":"Hěn duō báilǐng zhōngwǔ zhǐ zài gōngwèi shang chī gè wàimài.","vi":"Nhiều dân văn phòng buổi trưa chỉ ăn đồ đặt ngoài ngay tại chỗ làm."},{"type":"compound","zh":"虽然白领的收入比较稳定，但是加班也很多。","pinyin":"Suīrán báilǐng de shōurù bǐjiào wěndìng, dànshì jiābān yě hěn duō.","vi":"Tuy thu nhập của dân văn phòng khá ổn định nhưng phải tăng ca cũng nhiều."}],"related":[{"hanzi":"蓝领","pinyin":"lánlǐng","vi":"công nhân cổ xanh"},{"hanzi":"上班族","pinyin":"shàngbānzú","vi":"dân công sở"},{"hanzi":"职员","pinyin":"zhíyuán","vi":"nhân viên"},{"hanzi":"金领","pinyin":"jīnlǐng","vi":"quản lý cấp cao"}],"traditional":"白領"},{"id":"白昼","hanzi":"白昼","pinyin":"báizhòu","meaning_vi":"ban ngày (văn viết)","explanation":"白 (sáng) + 昼 (ban ngày). Đối nghĩa với 黑夜 (ban đêm).","hsk_level":6,"tags":["danh-tu","thoi-gian"],"image":"☀️","examples":[{"type":"basic","zh":"灯光亮如白昼。","pinyin":"Dēng guāngliàng rú báizhòu.","vi":"Ánh đèn sáng như ban ngày."},{"type":"simple","zh":"夏至这天的白昼是一年中最长的。","pinyin":"Xiàzhì zhè tiān de báizhòu shì yì niánzhōng zuì cháng de.","vi":"Ban ngày vào ngày Hạ chí là dài nhất trong năm."},{"type":"compound","zh":"一到夏天，北极就会出现几乎没有黑夜的白昼。","pinyin":"Yí dào xiàtiān, Běijí jiù huì chūxiàn jīhū méiyǒu hēiyè de báizhòu.","vi":"Cứ đến mùa hè, Bắc Cực lại có những ngày dài gần như không có đêm tối."}],"related":[{"hanzi":"白天","pinyin":"báitiān","vi":"ban ngày"},{"hanzi":"黑夜","pinyin":"hēiyè","vi":"đêm tối"},{"hanzi":"昼夜","pinyin":"zhòuyè","vi":"ngày đêm"},{"hanzi":"白日","pinyin":"báirì","vi":"ban ngày"}],"traditional":"白晝"},{"id":"背道而驰","hanzi":"背道而驰","pinyin":"bèidào-érchí","meaning_vi":"đi ngược lại với mục tiêu/nguyên tắc","explanation":"背道 (quay lưng với đường) + 而驰 (mà chạy). Thành ngữ.","hsk_level":6,"tags":["thanh-ngu"],"image":"↩️","examples":[{"type":"basic","zh":"这和初衷背道而驰。","pinyin":"Zhè hé chūzhōng bèidào'érchí.","vi":"Điều này đi ngược lại với ý định ban đầu."},{"type":"simple","zh":"他的做法与公司的环保理念背道而驰。","pinyin":"Tā de zuòfǎ yǔ gōngsī de huánbǎo lǐniàn bèidào'érchí.","vi":"Cách làm của anh ta đi ngược với triết lý bảo vệ môi trường của công ty."},{"type":"compound","zh":"如果你想减肥却天天吃夜宵，就跟目标背道而驰了。","pinyin":"Rúguǒ nǐ xiǎng jiǎnféi què tiāntiān chī yèxiāo, jiù gēn mùbiāo bèidào'érchí le.","vi":"Nếu muốn giảm cân mà ngày nào cũng ăn khuya thì là đi ngược với mục tiêu rồi."}],"related":[{"hanzi":"南辕北辙","pinyin":"nányuánběizhé","vi":"làm ngược với mục đích"},{"hanzi":"相反","pinyin":"xiāngfǎn","vi":"trái ngược"},{"hanzi":"违背","pinyin":"wéibèi","vi":"làm trái"},{"hanzi":"殊途同归","pinyin":"shūtútóngguī","vi":"khác đường cùng đích"}],"traditional":"背道而馳"},{"id":"备份","hanzi":"备份","pinyin":"bèifèn","meaning_vi":"sao lưu dữ liệu","explanation":"备 (bị – chuẩn bị) + 份 (phần – bản, phần) → chuẩn bị thêm một bản → sao lưu, bản dự phòng. Ví dụ: 备份文件, 数据备份.","hsk_level":6,"tags":["dong-tu"],"image":"💾","examples":[{"type":"basic","zh":"记得备份文件。","pinyin":"Jìde bèifèn wénjiàn.","vi":"Nhớ sao lưu tệp tin."},{"type":"simple","zh":"我每周都把手机照片备份到电脑上。","pinyin":"Wǒ měizhōu dōu bǎshǒu jī zhàopiàn bèifèn dào diànnǎo shang.","vi":"Tuần nào tôi cũng sao lưu ảnh trong điện thoại vào máy tính."},{"type":"compound","zh":"因为他没有及时备份，所以电脑坏了以后论文全没了。","pinyin":"Yīnwèi tā méiyǒu jíshí bèifèn, suǒyǐ diànnǎo huàile yǐhòu lùnwén quán méile.","vi":"Vì không sao lưu kịp thời nên sau khi máy tính hỏng, luận văn của anh ấy mất sạch."}],"related":[{"hanzi":"复制","pinyin":"fùzhì","vi":"sao chép"},{"hanzi":"数据","pinyin":"shùjù","vi":"dữ liệu"},{"hanzi":"恢复","pinyin":"huīfù","vi":"khôi phục"},{"hanzi":"文件","pinyin":"wénjiàn","vi":"tệp tin"}],"traditional":"備份"},{"id":"被告","hanzi":"被告","pinyin":"bèigào","meaning_vi":"bị cáo, bị đơn (tòa án)","explanation":"被 + 告 (kiện). Đối ứng với 原告 (nguyên đơn).","hsk_level":6,"tags":["danh-tu","phap-luat","con-nguoi"],"image":"⚖️","examples":[{"type":"basic","zh":"被告当庭认罪。","pinyin":"Bèigào dāng tíng rènzuì.","vi":"Bị cáo nhận tội ngay tại tòa."},{"type":"simple","zh":"法官允许被告做最后陈述。","pinyin":"Fǎguān yǔnxǔ bèigào zuò zuìhòu chénshù.","vi":"Thẩm phán cho phép bị cáo trình bày lời sau cùng."},{"type":"compound","zh":"虽然被告不服判决，但是他放弃了上诉。","pinyin":"Suīrán bèigào bùfú pànjué, dànshì tā fàngqìle shàngsù.","vi":"Tuy bị cáo không phục bản án nhưng anh ta đã từ bỏ kháng cáo."}],"related":[{"hanzi":"原告","pinyin":"yuángào","vi":"nguyên đơn"},{"hanzi":"被告人","pinyin":"bèigàorén","vi":"bị cáo"},{"hanzi":"起诉","pinyin":"qǐsù","vi":"khởi tố"},{"hanzi":"法庭","pinyin":"fǎtíng","vi":"tòa án"}]},{"id":"倍感","hanzi":"倍感","pinyin":"bèigǎn","meaning_vi":"càng thêm cảm thấy (vinh dự/ấm áp)","explanation":"倍 (gấp bội) + 感 (cảm nhận).","hsk_level":6,"tags":["dong-tu","cam-xuc"],"image":"❤️","examples":[{"type":"basic","zh":"我倍感荣幸。","pinyin":"Wǒ bèigǎn róngxìng.","vi":"Tôi cảm thấy vô cùng vinh dự."},{"type":"simple","zh":"在异国他乡收到家书让我倍感温暖。","pinyin":"Zài yìguótāxiāng shōudào jiāshū ràng wǒ bèigǎn wēnnuǎn.","vi":"Nhận được thư nhà nơi đất khách khiến tôi càng thấy ấm lòng."},{"type":"compound","zh":"每逢佳节，独自在外的游子就倍感孤独。","pinyin":"Měiféng jiājié, dú zìzài wài de yóuzǐ jiù bèigǎn gūdú.","vi":"Mỗi dịp lễ tết, người con xa xứ lại càng cảm thấy cô đơn."}],"related":[{"hanzi":"深感","pinyin":"shēngǎn","vi":"cảm thấy sâu sắc"},{"hanzi":"倍感荣幸","pinyin":"bèigǎnróngxìng","vi":"vô cùng vinh hạnh"},{"hanzi":"倍感温暖","pinyin":"bèigǎnwēnnuǎn","vi":"cảm thấy rất ấm áp"},{"hanzi":"感到","pinyin":"gǎndào","vi":"cảm thấy"}]},{"id":"背水一战","hanzi":"背水一战","pinyin":"bèishuǐ-yízhàn","meaning_vi":"trận chiến quyết tử (không còn đường lùi)","explanation":"Điển tích Hàn Tín. Thành ngữ.","hsk_level":6,"tags":["thanh-ngu"],"image":"⚔️","examples":[{"type":"basic","zh":"他决定背水一战。","pinyin":"Tā juédìng bèishuǐyízhàn.","vi":"Anh ấy quyết định liều một phen không đường lùi."},{"type":"simple","zh":"这场决赛对球队来说是背水一战。","pinyin":"Zhè cháng juésài duì qiúduì lái shuō shì bèishuǐyízhàn.","vi":"Trận chung kết này đối với đội bóng là trận chiến không còn đường lùi."},{"type":"compound","zh":"公司如果这次融资失败，就只能背水一战了。","pinyin":"Gōngsī rúguǒ zhè cì róngzī shībài, jiù zhǐnéng bèishuǐyízhàn le.","vi":"Nếu lần này gọi vốn thất bại thì công ty chỉ còn cách tử chiến không đường lùi."}],"related":[{"hanzi":"破釜沉舟","pinyin":"pòfǔchénzhōu","vi":"đập nồi dìm thuyền"},{"hanzi":"决一死战","pinyin":"juéyìsǐzhàn","vi":"quyết tử chiến"},{"hanzi":"孤注一掷","pinyin":"gūzhùyízhì","vi":"được ăn cả ngã về không"},{"hanzi":"退路","pinyin":"tuìlù","vi":"đường lui"}],"traditional":"背水一戰"},{"id":"背诵","hanzi":"背诵","pinyin":"bèisòng","meaning_vi":"học thuộc lòng","explanation":"背 (bối – đọc thuộc không nhìn sách) + 诵 (tụng – đọc to) → đọc thuộc lòng. Ví dụ: 背诵课文, 背诵唐诗.","hsk_level":6,"tags":["dong-tu"],"image":"📖","examples":[{"type":"basic","zh":"请背诵课文。","pinyin":"Qǐng bèisòngkèwén.","vi":"Hãy đọc thuộc lòng bài khóa."},{"type":"simple","zh":"小女孩能一字不差地背诵整首唐诗。","pinyin":"Xiǎo nǚhái néng yízì búchà de bèisòng zhěng shǒu Tángshī.","vi":"Cô bé có thể đọc thuộc lòng nguyên bài thơ Đường không sai một chữ."},{"type":"compound","zh":"只要每天背诵十个单词，一年下来就能积累三千多个。","pinyin":"Zhǐyào měitiān bèisòng shí gè dāncí, yì nián xiàlái jiù néng jīlěi sān qiān duōgè.","vi":"Chỉ cần mỗi ngày học thuộc mười từ, một năm sau là có thể tích lũy hơn ba nghìn từ."}],"related":[{"hanzi":"朗读","pinyin":"lǎngdú","vi":"đọc to"},{"hanzi":"记忆","pinyin":"jìyì","vi":"ghi nhớ"},{"hanzi":"默写","pinyin":"mòxiě","vi":"viết chính tả thuộc lòng"},{"hanzi":"背书","pinyin":"bèishū","vi":"học thuộc bài"}],"traditional":"背誦"},{"id":"笨手笨脚","hanzi":"笨手笨脚","pinyin":"bènshǒu-bènjiǎo","meaning_vi":"vụng về tay chân","explanation":"笨手笨脚: tay vụng chân vụng → hậu đậu, lóng ngóng, làm gì cũng vụng về.","hsk_level":6,"tags":["thanh-ngu"],"image":"🙈","examples":[{"type":"basic","zh":"他做事笨手笨脚。","pinyin":"Tā zuòshì bènshǒubènjiǎo.","vi":"Anh ấy làm gì cũng vụng về."},{"type":"simple","zh":"新来的服务员笨手笨脚地打翻了一杯咖啡。","pinyin":"Xīn lái de fúwùyuán bènshǒubènjiǎo de dǎfānle yì bēi kāfēi.","vi":"Người phục vụ mới vụng về làm đổ một cốc cà phê."},{"type":"compound","zh":"我第一次包饺子时笨手笨脚的，但是奶奶一直耐心地教我。","pinyin":"Wǒ dìyīcì bāojiǎozi shí bènshǒubènjiǎo de, dànshì nǎinai yìzhí nàixīn de jiāo wǒ.","vi":"Lần đầu gói sủi cảo tôi rất vụng về, nhưng bà luôn kiên nhẫn dạy tôi."}],"related":[{"hanzi":"笨拙","pinyin":"bènzhuō","vi":"vụng về"},{"hanzi":"心灵手巧","pinyin":"xīnlíngshǒuqiǎo","vi":"khéo tay"},{"hanzi":"手忙脚乱","pinyin":"shǒumángjiǎoluàn","vi":"luống cuống"},{"hanzi":"笨","pinyin":"bèn","vi":"ngốc, vụng"}],"traditional":"笨手笨腳"},{"id":"蹦","hanzi":"蹦","pinyin":"bèng","meaning_vi":"nhảy cẫng lên","explanation":"蹦: nhảy bật lên (thường bằng cả hai chân). Ví dụ: 蹦蹦跳跳 (nhảy nhót tung tăng), 高兴得蹦起来, 蹦极 (nhảy bungee).","hsk_level":6,"tags":["dong-tu"],"image":"🦘","examples":[{"type":"basic","zh":"兔子蹦了出来。","pinyin":"Tùzi bèngle chūlái.","vi":"Con thỏ nhảy ra ngoài."},{"type":"simple","zh":"一条鱼从水桶里蹦到了地上。","pinyin":"Yì tiáo yú cóng shuǐtǒng li bèng dàole dìshang.","vi":"Một con cá nhảy từ trong xô nước ra đất."},{"type":"compound","zh":"他一听说考上了大学，就高兴得蹦了起来。","pinyin":"Tā yì tīngshuō kǎoshàngle dàxué, jiù gāoxìng de bèngle qǐlái.","vi":"Vừa nghe tin đỗ đại học, cậu ấy liền vui sướng nhảy cẫng lên."}],"related":[{"hanzi":"跳","pinyin":"tiào","vi":"nhảy"},{"hanzi":"蹦蹦跳跳","pinyin":"bèngbengtiàotiào","vi":"nhảy nhót tung tăng"},{"hanzi":"蹦极","pinyin":"bèngjí","vi":"nhảy bungee"},{"hanzi":"跳跃","pinyin":"tiàoyuè","vi":"nhảy vọt"}]},{"id":"闭关锁国","hanzi":"闭关锁国","pinyin":"bìguān-suǒguó","meaning_vi":"bế quan tỏa cảng","explanation":"闭关 + 锁国. Thành ngữ lịch sử.","hsk_level":6,"tags":["thanh-ngu","van-hoa"],"image":"🔒","examples":[{"type":"basic","zh":"那时实行闭关锁国。","pinyin":"Nàshí shíxíng bìguānsuǒguó.","vi":"Thời đó thi hành chính sách bế quan tỏa cảng."},{"type":"simple","zh":"清朝后期的闭关锁国政策让中国落后于世界。","pinyin":"Qīngcháo hòuqī de bìguānsuǒguó zhèngcè ràng Zhōngguó luòhòu yú shìjiè.","vi":"Chính sách bế quan tỏa cảng cuối thời nhà Thanh khiến Trung Quốc tụt hậu so với thế giới."},{"type":"compound","zh":"一个国家如果闭关锁国，就很难跟上时代的发展。","pinyin":"Yí gè guójiā rúguǒ bìguānsuǒguó, jiù hěn nán gēnshàng shídài de fāzhǎn.","vi":"Một quốc gia nếu bế quan tỏa cảng thì rất khó theo kịp sự phát triển của thời đại."}],"related":[{"hanzi":"闭关自守","pinyin":"bìguānzìshǒu","vi":"đóng cửa tự thủ"},{"hanzi":"对外开放","pinyin":"duìwàikāifàng","vi":"mở cửa với bên ngoài"},{"hanzi":"封闭","pinyin":"fēngbì","vi":"khép kín"},{"hanzi":"孤立","pinyin":"gūlì","vi":"cô lập"}],"traditional":"閉關鎖國"},{"id":"必将","hanzi":"必将","pinyin":"bìjiāng","meaning_vi":"tất sẽ, chắc chắn sẽ","explanation":"必 (ắt hẳn) + 将 (sắp tới).","hsk_level":6,"tags":["pho-tu"],"image":"❗","examples":[{"type":"basic","zh":"正义必将胜利。","pinyin":"Zhèngyì bìjiāng shènglì.","vi":"Chính nghĩa tất sẽ chiến thắng."},{"type":"simple","zh":"这条高铁的开通必将带动沿线城市的发展。","pinyin":"Zhè tiáo gāotiě de kāitōng bìjiāng dàidòng yánxiàn chéngshì de fāzhǎn.","vi":"Việc khai thông tuyến đường sắt cao tốc này chắc chắn sẽ thúc đẩy các thành phố dọc tuyến phát triển."},{"type":"compound","zh":"只要坚持锻炼，你的身体必将越来越好。","pinyin":"Zhǐyào jiānchí duànliàn, nǐ de shēntǐ bìjiāng yuèláiyuè hǎo.","vi":"Chỉ cần kiên trì tập luyện, sức khỏe của bạn chắc chắn sẽ ngày càng tốt hơn."}],"related":[{"hanzi":"必然","pinyin":"bìrán","vi":"tất nhiên"},{"hanzi":"一定","pinyin":"yídìng","vi":"nhất định"},{"hanzi":"必定","pinyin":"bìdìng","vi":"chắc chắn"},{"hanzi":"将会","pinyin":"jiānghuì","vi":"sẽ"}],"traditional":"必將"},{"id":"碧绿","hanzi":"碧绿","pinyin":"bìlǜ","meaning_vi":"xanh biếc, xanh mướt","explanation":"碧 (ngọc bích) + 绿 (xanh lá).","hsk_level":6,"tags":["tinh-tu","mau-sac"],"image":"🌿","examples":[{"type":"basic","zh":"湖水碧绿碧绿的。","pinyin":"Húshuǐ bìlǜ bìlǜ de.","vi":"Nước hồ xanh biếc."},{"type":"simple","zh":"雨后的稻田显得格外碧绿。","pinyin":"Yǔ hòu de dàotián xiǎnde géwài bìlǜ.","vi":"Cánh đồng lúa sau mưa trông xanh mướt lạ thường."},{"type":"compound","zh":"春天一到，山上的竹林就变得碧绿了。","pinyin":"Chūntiān yí dào, shān shang de zhúlín jiù biànde bìlǜ le.","vi":"Mùa xuân vừa đến, rừng trúc trên núi liền trở nên xanh mướt."}],"related":[{"hanzi":"翠绿","pinyin":"cuìlǜ","vi":"xanh ngọc"},{"hanzi":"绿油油","pinyin":"lǜyóuyóu","vi":"xanh mơn mởn"},{"hanzi":"碧蓝","pinyin":"bìlán","vi":"xanh biếc"},{"hanzi":"绿色","pinyin":"lǜsè","vi":"màu xanh lá"}],"traditional":"碧綠"},{"id":"闭门造车","hanzi":"闭门造车","pinyin":"bìmén-zàochē","meaning_vi":"đóng cửa làm xe (làm việc chủ quan xa rời thực tế)","explanation":"闭门 (bế môn – đóng cửa) + 造车 (tạo xa – đóng xe) → đóng cửa ở nhà đóng xe, không cần biết đường thực tế ra sao → làm việc theo ý chủ quan, xa rời thực tế.","hsk_level":6,"tags":["thanh-ngu"],"image":"🚗","examples":[{"type":"basic","zh":"做研究不能闭门造车。","pinyin":"Zuò yánjiū bù néng bìménzàochē.","vi":"Làm nghiên cứu không được đóng cửa làm theo ý mình, xa rời thực tế."},{"type":"simple","zh":"这款产品是工程师们闭门造车的结果。","pinyin":"Zhè kuǎn chǎnpǐn shì gōngchéngshīmen bìménzàochē de jiéguǒ.","vi":"Sản phẩm này là kết quả của việc các kỹ sư làm việc khép kín, xa rời thực tế."},{"type":"compound","zh":"与其闭门造车，不如先去市场调查一下顾客的需求。","pinyin":"Yǔqí bìménzàochē, bùrú xiān qù shìchǎng diàochá yíxià gùkè de xūqiú.","vi":"Thay vì ngồi một chỗ làm theo ý mình, chi bằng ra thị trường khảo sát nhu cầu khách hàng trước."}],"related":[{"hanzi":"脱离实际","pinyin":"tuōlíshíjì","vi":"xa rời thực tế"},{"hanzi":"纸上谈兵","pinyin":"zhǐshàngtánbīng","vi":"bàn binh trên giấy"},{"hanzi":"主观","pinyin":"zhǔguān","vi":"chủ quan"},{"hanzi":"实事求是","pinyin":"shíshìqiúshì","vi":"thực sự cầu thị"}],"traditional":"閉門造車"},{"id":"闭目养神","hanzi":"闭目养神","pinyin":"bìmù-yǎngshén","meaning_vi":"nhắm mắt dưỡng thần","explanation":"闭目养神: nhắm mắt để dưỡng tinh thần → nhắm mắt nghỉ ngơi, thư giãn tinh thần (không hẳn là ngủ).","hsk_level":6,"tags":["thanh-ngu","suc-khoe"],"image":"🧘","examples":[{"type":"basic","zh":"爷爷在闭目养神。","pinyin":"Yéye zài bìmùyǎngshén.","vi":"Ông đang nhắm mắt dưỡng thần."},{"type":"simple","zh":"他靠在高铁的座位上闭目养神。","pinyin":"Tā kào zài gāotiě de zuòwèi shang bìmùyǎngshén.","vi":"Anh ấy tựa vào ghế tàu cao tốc nhắm mắt nghỉ ngơi."},{"type":"compound","zh":"如果午饭后没时间睡觉，就闭目养神十分钟吧。","pinyin":"Rúguǒ wǔfàn hòu méi shíjiān shuìjiào, jiù bìmùyǎngshén shí fēnzhōng ba.","vi":"Nếu sau bữa trưa không có thời gian ngủ thì hãy nhắm mắt dưỡng thần mười phút nhé."}],"related":[{"hanzi":"休息","pinyin":"xiūxi","vi":"nghỉ ngơi"},{"hanzi":"养神","pinyin":"yǎngshén","vi":"dưỡng thần"},{"hanzi":"闭眼","pinyin":"bìyǎn","vi":"nhắm mắt"},{"hanzi":"打盹","pinyin":"dǎdǔn","vi":"ngủ gật"}],"traditional":"閉目養神"},{"id":"闭塞","hanzi":"闭塞","pinyin":"bìsè","meaning_vi":"hẻo lánh, cách trở (giao thông); bế tắc, thiếu thông tin","explanation":"闭 (bế – đóng) + 塞 (tắc – lấp) → bị ngăn lấp, không thông. Chỉ vùng hẻo lánh, giao thông khó khăn (交通闭塞) hoặc thông tin kém (消息闭塞).","hsk_level":6,"tags":["tinh-tu"],"image":"🚧","examples":[{"type":"basic","zh":"他的思想很闭塞。","pinyin":"Tā de sīxiǎng hěn bìsè.","vi":"Tư tưởng của anh ấy rất bảo thủ, khép kín."},{"type":"simple","zh":"这个小山村过去信息十分闭塞。","pinyin":"Zhè gè xiǎo shāncūn guòqù xìnxī shífēn bìsè.","vi":"Ngôi làng miền núi nhỏ này trước đây rất thiếu thông tin."},{"type":"compound","zh":"因为山区交通闭塞，所以农产品很难运出去。","pinyin":"Yīnwèi shānqū jiāotōng bìsè, suǒyǐ nóngchǎnpǐn hěn nán yùn chūqù.","vi":"Vì vùng núi giao thông cách trở nên nông sản rất khó vận chuyển ra ngoài."}],"related":[{"hanzi":"封闭","pinyin":"fēngbì","vi":"khép kín"},{"hanzi":"偏僻","pinyin":"piānpì","vi":"hẻo lánh"},{"hanzi":"消息闭塞","pinyin":"xiāoxibìsè","vi":"thiếu thông tin"},{"hanzi":"开放","pinyin":"kāifàng","vi":"cởi mở"}],"traditional":"閉塞"},{"id":"必由之路","hanzi":"必由之路","pinyin":"bìyóu-zhīlù","meaning_vi":"con đường tất yếu phải đi qua","explanation":"必由之路: con đường tất phải đi qua → cách duy nhất, con đường tất yếu để đạt mục tiêu. Ví dụ: 改革是发展的必由之路.","hsk_level":6,"tags":["thanh-ngu"],"image":"🛤️","examples":[{"type":"basic","zh":"改革是必由之路。","pinyin":"Gǎigé shì bìyóuzhīlù.","vi":"Cải cách là con đường tất yếu."},{"type":"simple","zh":"坚持练习是学好外语的必由之路。","pinyin":"Jiānchí liànxí shì xuéhǎo wàiyǔ de bìyóuzhīlù.","vi":"Kiên trì luyện tập là con đường tất yếu để học giỏi ngoại ngữ."},{"type":"compound","zh":"既然创新是企业发展的必由之路，我们就必须加大研发投入。","pinyin":"Jìrán chuàngxīn shì qǐyè fāzhǎn de bìyóuzhīlù, wǒmen jiù bìxū jiādà yánfā tóurù.","vi":"Vì đổi mới là con đường tất yếu để doanh nghiệp phát triển nên chúng ta phải tăng đầu tư cho nghiên cứu phát triển."}],"related":[{"hanzi":"必经之路","pinyin":"bìjīngzhīlù","vi":"con đường phải qua"},{"hanzi":"唯一出路","pinyin":"wéiyīchūlù","vi":"lối thoát duy nhất"},{"hanzi":"道路","pinyin":"dàolù","vi":"con đường"},{"hanzi":"途径","pinyin":"tújìng","vi":"con đường, cách thức"}]},{"id":"并存","hanzi":"并存","pinyin":"bìngcún","meaning_vi":"cùng tồn tại, song song tồn tại","explanation":"并 (cùng) + 存 (tồn tại).","hsk_level":6,"tags":["dong-tu"],"image":"🤝","examples":[{"type":"basic","zh":"机遇与挑战并存。","pinyin":"Jīyù yǔ tiǎozhàn bìngcún.","vi":"Cơ hội và thách thức cùng tồn tại."},{"type":"simple","zh":"这座城市里古老的胡同和现代高楼并存。","pinyin":"Zhè zuò chéngshì li gǔlǎo de hútòng hé xiàndài gāolóu bìngcún.","vi":"Trong thành phố này, những con ngõ cổ và nhà cao tầng hiện đại cùng tồn tại."},{"type":"compound","zh":"虽然两种观点完全不同，但是它们可以和平并存。","pinyin":"Suīrán liǎng zhǒng guāndiǎn wánquán bùtóng, dànshì tāmen kěyǐ hépíng bìngcún.","vi":"Tuy hai quan điểm hoàn toàn khác nhau nhưng chúng có thể cùng tồn tại hòa bình."}],"related":[{"hanzi":"共存","pinyin":"gòngcún","vi":"cùng tồn tại"},{"hanzi":"共处","pinyin":"gòngchǔ","vi":"chung sống"},{"hanzi":"兼顾","pinyin":"jiāngù","vi":"chăm lo cả hai"},{"hanzi":"和平共处","pinyin":"hépínggòngchǔ","vi":"chung sống hòa bình"}],"traditional":"並存"},{"id":"并非","hanzi":"并非","pinyin":"bìngfēi","meaning_vi":"không phải là","explanation":"并 (tịnh – hoàn toàn, nhấn mạnh phủ định) + 非 (phi – không phải) → hoàn toàn không phải. Dùng để bác bỏ: 事实并非如此.","hsk_level":6,"tags":["pho-tu"],"image":"🚫","examples":[{"type":"basic","zh":"事实并非如此。","pinyin":"Shìshí bìngfēi rúcǐ.","vi":"Sự thật không phải như vậy."},{"type":"simple","zh":"价格高的东西并非都是好东西。","pinyin":"Jiàgé gāo de dōngxi bìngfēi dōu shì hǎo dōngxi.","vi":"Đồ đắt tiền không phải món nào cũng là đồ tốt."},{"type":"compound","zh":"他不来并非因为生气，而是因为孩子发烧了。","pinyin":"Tā bù lái bìngfēi yīnwèi shēngqì, érshì yīnwèi háizi fāshāo le.","vi":"Anh ấy không đến không phải vì giận mà là vì con bị sốt."}],"related":[{"hanzi":"并不","pinyin":"bìngbù","vi":"hoàn toàn không"},{"hanzi":"不是","pinyin":"búshì","vi":"không phải"},{"hanzi":"绝非","pinyin":"juéfēi","vi":"tuyệt không phải"},{"hanzi":"而是","pinyin":"érshì","vi":"mà là"}],"traditional":"並非"},{"id":"并驾齐驱","hanzi":"并驾齐驱","pinyin":"bìngjià-qíqū","meaning_vi":"sánh vai cùng tiến, ngang tài ngang sức","explanation":"并驾 (tịnh giá – thắng ngựa sóng đôi) + 齐驱 (tề khu – cùng phi) → các ngựa kéo xe chạy ngang nhau → ngang tài ngang sức, cùng tiến song song.","hsk_level":6,"tags":["thanh-ngu"],"image":"🐎","examples":[{"type":"basic","zh":"两家公司并驾齐驱。","pinyin":"Liǎng jiā gōngsī bìngjiàqíqū.","vi":"Hai công ty ngang tài ngang sức."},{"type":"simple","zh":"他的成绩已经能和班里的尖子生并驾齐驱了。","pinyin":"Tā de chéngjì yǐjīng néng hé bān li de jiānzishēng bìngjiàqíqū le.","vi":"Thành tích của cậu ấy đã có thể sánh ngang với học sinh giỏi nhất lớp."},{"type":"compound","zh":"只要我们不断提高技术，就能和国外品牌并驾齐驱。","pinyin":"Zhǐyào wǒmen búduàn tígāo jìshù, jiù néng hé guówài pǐnpái bìngjiàqíqū.","vi":"Chỉ cần không ngừng nâng cao kỹ thuật, chúng ta có thể sánh vai với các thương hiệu nước ngoài."}],"related":[{"hanzi":"齐头并进","pinyin":"qítóubìngjìn","vi":"cùng tiến song song"},{"hanzi":"不相上下","pinyin":"bùxiāngshàngxià","vi":"ngang nhau"},{"hanzi":"旗鼓相当","pinyin":"qígǔxiāngdāng","vi":"ngang tài ngang sức"},{"hanzi":"望尘莫及","pinyin":"wàngchénmòjí","vi":"không theo kịp"}],"traditional":"並駕齊驅"},{"id":"病入膏肓","hanzi":"病入膏肓","pinyin":"bìngrù-gāohuāng","meaning_vi":"bệnh đã vào giai đoạn nguy kịch khó chữa","explanation":"病入 (bệnh nhập – bệnh vào) + 膏肓 (cao hoang – chỗ giữa tim và cơ hoành, thuốc không tới) → truyện Tấn Cảnh Công (Tả truyện) → bệnh không chữa được; ví tình thế hết cứu vãn.","hsk_level":6,"tags":["thanh-ngu","suc-khoe"],"image":"🏥","examples":[{"type":"basic","zh":"他已经病入膏肓。","pinyin":"Tā yǐjīng bìngrùgāohuāng.","vi":"Ông ấy đã bệnh nặng hết cách chữa."},{"type":"simple","zh":"这家连年亏损的企业早已病入膏肓。","pinyin":"Zhè jiā liánnián kuīsǔn de qǐyè zǎoyǐ bìngrùgāohuāng.","vi":"Doanh nghiệp thua lỗ liên tục nhiều năm này từ lâu đã lâm vào tình trạng không thể cứu vãn."},{"type":"compound","zh":"如果等到病入膏肓才去看医生，就太晚了。","pinyin":"Rúguǒ děngdào bìngrùgāohuāng cái qù kànyīshēng, jiù tài wǎn le.","vi":"Nếu đợi đến khi bệnh nguy kịch mới đi khám bác sĩ thì đã quá muộn."}],"related":[{"hanzi":"不可救药","pinyin":"bùkějiùyào","vi":"hết thuốc chữa"},{"hanzi":"无药可救","pinyin":"wúyàokějiù","vi":"vô phương cứu chữa"},{"hanzi":"危重","pinyin":"wēizhòng","vi":"nguy kịch"},{"hanzi":"奄奄一息","pinyin":"yǎnyǎnyìxī","vi":"thoi thóp"}]},{"id":"鼻梁","hanzi":"鼻梁","pinyin":"bíliáng","meaning_vi":"sống mũi","explanation":"鼻 (mũi) + 梁 (cầu/xà ngang).","hsk_level":6,"tags":["danh-tu","co-the"],"image":"👃","examples":[{"type":"basic","zh":"他的鼻梁很高。","pinyin":"Tā de bíliáng hěn gāo.","vi":"Sống mũi anh ấy rất cao."},{"type":"simple","zh":"爷爷的鼻梁上架着一副老花镜。","pinyin":"Yéye de bíliáng shangjiàzhe yí fù lǎohuājìng.","vi":"Trên sống mũi ông đeo một cặp kính lão."},{"type":"compound","zh":"因为摔了一跤，所以他的鼻梁上留下了一道伤口。","pinyin":"Yīnwèi shuāile yì jiāo, suǒyǐ tā de bíliáng shang liúxiàle yídào shāngkǒu.","vi":"Vì bị ngã một cú nên trên sống mũi anh ấy để lại một vết thương."}],"related":[{"hanzi":"鼻子","pinyin":"bízi","vi":"mũi"},{"hanzi":"鼻孔","pinyin":"bíkǒng","vi":"lỗ mũi"},{"hanzi":"眉毛","pinyin":"méimao","vi":"lông mày"},{"hanzi":"五官","pinyin":"wǔguān","vi":"ngũ quan"}],"traditional":"鼻樑"},{"id":"鼻涕","hanzi":"鼻涕","pinyin":"bítì","meaning_vi":"nước mũi","explanation":"鼻 (tị – mũi) + 涕 (thế – nước mắt, nước mũi) → nước mũi. Ví dụ: 流鼻涕 (chảy nước mũi), 擤鼻涕 (hỉ mũi).","hsk_level":6,"tags":["danh-tu","co-the"],"image":"🤧","examples":[{"type":"basic","zh":"快擦擦鼻涕。","pinyin":"Kuài cā ca bítì.","vi":"Mau lau nước mũi đi."},{"type":"simple","zh":"感冒的小男孩一直在流鼻涕。","pinyin":"Gǎnmào de xiǎo nánhái yìzhí zài liúbítì.","vi":"Cậu bé bị cảm cứ chảy nước mũi mãi."},{"type":"compound","zh":"天气一变冷，我就打喷嚏、流鼻涕。","pinyin":"Tiānqì yí biàn lěng, wǒ jiù dǎpēntì, liúbítì.","vi":"Trời vừa trở lạnh là tôi lại hắt hơi, chảy nước mũi."}],"related":[{"hanzi":"鼻子","pinyin":"bízi","vi":"mũi"},{"hanzi":"流鼻涕","pinyin":"liúbítì","vi":"chảy nước mũi"},{"hanzi":"感冒","pinyin":"gǎnmào","vi":"cảm cúm"},{"hanzi":"眼泪","pinyin":"yǎnlèi","vi":"nước mắt"}]},{"id":"勃勃生机","hanzi":"勃勃生机","pinyin":"bóbó-shēngjī","meaning_vi":"tràn đầy sức sống","explanation":"勃勃 (bột bột – dâng trào mạnh mẽ) + 生机 (sinh cơ – sức sống) → tràn trề sức sống. Thường nói 生机勃勃 hoặc 充满勃勃生机.","hsk_level":6,"tags":["thanh-ngu"],"image":"🌱","examples":[{"type":"basic","zh":"春天充满勃勃生机。","pinyin":"Chūntiān chōngmǎn bóbóshēngjī.","vi":"Mùa xuân tràn đầy sức sống."},{"type":"simple","zh":"雨后的森林呈现出一派勃勃生机。","pinyin":"Yǔ hòu de sēnlín chéngxiàn chū yí pài bóbóshēngjī.","vi":"Khu rừng sau mưa hiện lên tràn trề sức sống."},{"type":"compound","zh":"自从开了几家新工厂，这个小镇就焕发出了勃勃生机。","pinyin":"Zìcóng kāile jǐ jiā xīn gōngchǎng, zhè gè xiǎozhèn jiù huànfā chūle bóbóshēngjī.","vi":"Từ khi mở thêm vài nhà máy mới, thị trấn nhỏ này bừng lên sức sống."}],"related":[{"hanzi":"生机勃勃","pinyin":"shēngjībóbó","vi":"tràn đầy sức sống"},{"hanzi":"朝气蓬勃","pinyin":"zhāoqìpéngbó","vi":"tràn trề sức sống"},{"hanzi":"活力","pinyin":"huólì","vi":"sức sống"},{"hanzi":"死气沉沉","pinyin":"sǐqìchénchén","vi":"ủ rũ không sức sống"}],"traditional":"勃勃生機"},{"id":"驳斥","hanzi":"驳斥","pinyin":"bóchì","meaning_vi":"bác bỏ, phản bác gay gắt","explanation":"驳 (bác lại) + 斥 (trách mắng).","hsk_level":6,"tags":["dong-tu","giao-tiep"],"image":"🗣️","examples":[{"type":"basic","zh":"他驳斥了谣言。","pinyin":"Tā bóchìle yáoyán.","vi":"Anh ấy bác bỏ tin đồn."},{"type":"simple","zh":"外交部发言人严厉驳斥了这些无理指责。","pinyin":"Wàijiāobù fāyánrén yánlì bóchìle zhèxiē wúlǐ zhǐzé.","vi":"Người phát ngôn Bộ Ngoại giao đã kịch liệt bác bỏ những cáo buộc vô lý này."},{"type":"compound","zh":"他不但驳斥了对方的观点，而且拿出了有力的证据。","pinyin":"Tā búdàn bóchìle duìfāng de guāndiǎn, érqiě náchūle yǒulì de zhèngjù.","vi":"Anh ấy không những bác bỏ quan điểm của đối phương mà còn đưa ra chứng cứ thuyết phục."}],"related":[{"hanzi":"反驳","pinyin":"fǎnbó","vi":"phản bác"},{"hanzi":"批驳","pinyin":"pībó","vi":"bác bỏ"},{"hanzi":"否定","pinyin":"fǒudìng","vi":"phủ định"},{"hanzi":"赞同","pinyin":"zàntóng","vi":"tán thành"}],"traditional":"駁斥"},{"id":"博大","hanzi":"博大","pinyin":"bódà","meaning_vi":"rộng lớn, uyên bác","explanation":"博 (bác – rộng, nhiều) + 大 (đại – lớn) → rộng lớn, sâu rộng (tri thức, tư tưởng, tấm lòng). Cụm: 博大精深, 博大的胸怀.","hsk_level":6,"tags":["tinh-tu"],"image":"🌍","examples":[{"type":"basic","zh":"大海胸怀博大。","pinyin":"Dàhǎi xiōnghuái bódà.","vi":"Biển cả có tấm lòng bao la."},{"type":"simple","zh":"母亲博大的爱支撑着我度过了难关。","pinyin":"Mǔqīn bódà de ài zhīchēngzhe wǒ dùguòle nánguān.","vi":"Tình yêu bao la của mẹ đã giúp tôi vượt qua khó khăn."},{"type":"compound","zh":"这位老教授既学识博大，又为人谦和。","pinyin":"Zhè wèi lǎo jiàoshòu jì xuéshí bódà, yòu wéirén qiānhé.","vi":"Vị giáo sư già này vừa có học thức uyên bác vừa khiêm tốn hòa nhã."}],"related":[{"hanzi":"广博","pinyin":"guǎngbó","vi":"uyên bác rộng"},{"hanzi":"宽广","pinyin":"kuānguǎng","vi":"rộng lớn"},{"hanzi":"博大精深","pinyin":"bódàjīngshēn","vi":"uyên thâm sâu rộng"},{"hanzi":"渊博","pinyin":"yuānbó","vi":"uyên bác"}]},{"id":"博大精深","hanzi":"博大精深","pinyin":"bódà-jīngshēn","meaning_vi":"uyên bác sâu rộng","explanation":"博大 (bác đại – rộng lớn) + 精深 (tinh thâm – tinh tế, sâu sắc) → (tư tưởng, học vấn, văn hóa) vừa rộng lớn vừa sâu sắc. Thường: 中华文化博大精深.","hsk_level":6,"tags":["thanh-ngu"],"image":"🏛️","examples":[{"type":"basic","zh":"中医博大精深。","pinyin":"Zhōngyī bódàjīngshēn.","vi":"Đông y uyên bác sâu rộng."},{"type":"simple","zh":"我被博大精深的中国书法艺术深深吸引了。","pinyin":"Wǒ bèi bódàjīngshēn de Zhōngguó shūfǎ yìshù shēnshēn xīyǐn le.","vi":"Tôi bị nghệ thuật thư pháp Trung Hoa uyên thâm sâu rộng cuốn hút sâu sắc."},{"type":"compound","zh":"中华文化博大精深，即使学一辈子也学不完。","pinyin":"Zhōnghuá wénhuà bódàjīngshēn, jíshǐ xué yíbèizi yě xué bù wán.","vi":"Văn hóa Trung Hoa uyên bác sâu rộng, dù học cả đời cũng không hết."}],"related":[{"hanzi":"渊博","pinyin":"yuānbó","vi":"uyên bác"},{"hanzi":"源远流长","pinyin":"yuányuǎnliúcháng","vi":"lâu đời"},{"hanzi":"深奥","pinyin":"shēn'ào","vi":"sâu xa"},{"hanzi":"浅薄","pinyin":"qiǎnbó","vi":"nông cạn"}]},{"id":"伯母","hanzi":"伯母","pinyin":"bómǔ","meaning_vi":"bác gái (vợ của anh trai bố)","explanation":"伯 (bác trai) + 母 (mẹ).","hsk_level":6,"tags":["danh-tu","gia-dinh"],"image":"👩","examples":[{"type":"basic","zh":"伯母做菜很好吃。","pinyin":"Bómǔ zuòcài hěn hǎochī.","vi":"Bác gái nấu ăn rất ngon."},{"type":"simple","zh":"春节时伯母给每个孩子都包了红包。","pinyin":"Chūnjié shí bómǔ gěi měi gè háizi dōu bāole hóngbāo.","vi":"Dịp Tết, bác gái lì xì cho từng đứa trẻ."},{"type":"compound","zh":"伯母一见到我，就拉着我的手问长问短。","pinyin":"Bómǔ yí jiàndào wǒ, jiù lāzhe wǒ de shǒu wèn cháng wèn duǎn.","vi":"Bác gái vừa gặp tôi đã nắm tay hỏi han đủ điều."}],"related":[{"hanzi":"伯父","pinyin":"bófù","vi":"bác trai"},{"hanzi":"叔叔","pinyin":"shūshu","vi":"chú"},{"hanzi":"阿姨","pinyin":"āyí","vi":"dì"},{"hanzi":"婶婶","pinyin":"shěnshen","vi":"thím"}]},{"id":"薄弱","hanzi":"薄弱","pinyin":"bóruò","meaning_vi":"mỏng manh, yếu kém","explanation":"薄 (bạc – mỏng) + 弱 (nhược – yếu) → mỏng yếu, không vững chắc. Thường: 基础薄弱, 薄弱环节 (khâu yếu).","hsk_level":6,"tags":["tinh-tu"],"image":"📉","examples":[{"type":"basic","zh":"他的数学基础薄弱。","pinyin":"Tā de shùxué jīchǔ bóruò.","vi":"Nền tảng toán của cậu ấy yếu."},{"type":"simple","zh":"这个小区的安全管理十分薄弱。","pinyin":"Zhè gè xiǎoqū de ānquán guǎnlǐ shífēn bóruò.","vi":"Công tác quản lý an ninh của khu dân cư này rất lỏng lẻo."},{"type":"compound","zh":"既然听力是你的薄弱环节，就应该每天多听多练。","pinyin":"Jìrán tīnglì shì nǐ de bóruòhuánjié, jiù yīnggāi měitiān duō tīng duō liàn.","vi":"Nghe đã là khâu yếu của bạn thì nên nghe và luyện nhiều hơn mỗi ngày."}],"related":[{"hanzi":"软弱","pinyin":"ruǎnruò","vi":"yếu mềm"},{"hanzi":"脆弱","pinyin":"cuìruò","vi":"mong manh"},{"hanzi":"坚强","pinyin":"jiānqiáng","vi":"kiên cường"},{"hanzi":"薄弱环节","pinyin":"bóruòhuánjié","vi":"khâu yếu"}]},{"id":"博学","hanzi":"博学","pinyin":"bóxué","meaning_vi":"uyên bác, học rộng biết nhiều","explanation":"博 + 学 (học vấn).","hsk_level":6,"tags":["tinh-tu","hoc-tap"],"image":"🎓","examples":[{"type":"basic","zh":"张教授非常博学。","pinyin":"Zhāng jiàoshòu fēicháng bóxué.","vi":"Giáo sư Trương rất uyên bác."},{"type":"simple","zh":"博学的导游给我们讲了很多历史故事。","pinyin":"Bóxué de dǎoyóu gěi wǒmen jiǎngle hěn duō lìshǐ gùshi.","vi":"Người hướng dẫn viên học rộng đã kể cho chúng tôi nhiều câu chuyện lịch sử."},{"type":"compound","zh":"他虽然博学多才，但是从不炫耀自己。","pinyin":"Tā suīrán bóxué duōcái, dànshì cóng bú xuànyào zìjǐ.","vi":"Anh ấy tuy học rộng tài cao nhưng chưa bao giờ khoe khoang."}],"related":[{"hanzi":"渊博","pinyin":"yuānbó","vi":"uyên bác"},{"hanzi":"学识","pinyin":"xuéshí","vi":"học thức"},{"hanzi":"博学多才","pinyin":"bóxuéduōcái","vi":"học rộng tài cao"},{"hanzi":"才疏学浅","pinyin":"cáishūxuéqiǎn","vi":"tài mọn học kém"}],"traditional":"博學"},{"id":"博爱","hanzi":"博爱","pinyin":"bó'ài","meaning_vi":"lòng bác ái, yêu thương rộng lớn","explanation":"博 (rộng lớn) + 爱 (yêu).","hsk_level":6,"tags":["danh-tu","cam-xuc"],"image":"💖","examples":[{"type":"basic","zh":"她有一颗博爱之心。","pinyin":"Tā yǒu yì kē bó'ài zhī xīn.","vi":"Cô ấy có một tấm lòng bác ái."},{"type":"simple","zh":"这家医院的创办人一生都在践行博爱精神。","pinyin":"Zhè jiā yīyuàn de chuàngbànrén yìshēng dōu zài jiànxíng bó'ài jīngshén.","vi":"Người sáng lập bệnh viện này cả đời đều thực hành tinh thần bác ái."},{"type":"compound","zh":"只要人人都懂得博爱，世界就会变得更加温暖。","pinyin":"Zhǐyào rénrén dōu dǒngde bó'ài, shìjiè jiù huì biànde gèngjiā wēnnuǎn.","vi":"Chỉ cần ai cũng biết yêu thương rộng lượng thì thế giới sẽ trở nên ấm áp hơn."}],"related":[{"hanzi":"仁爱","pinyin":"rén'ài","vi":"nhân ái"},{"hanzi":"慈善","pinyin":"císhàn","vi":"từ thiện"},{"hanzi":"爱心","pinyin":"àixīn","vi":"lòng yêu thương"},{"hanzi":"自私","pinyin":"zìsī","vi":"ích kỷ"}],"traditional":"博愛"},{"id":"步步高升","hanzi":"步步高升","pinyin":"bùbù-gāoshēng","meaning_vi":"từng bước thăng tiến","explanation":"Lời chúc thăng chức/học tập tiến bộ.","hsk_level":6,"tags":["thanh-ngu","giao-tiep"],"image":"📈","examples":[{"type":"basic","zh":"祝您步步高升！","pinyin":"Zhù nín bùbùgāoshēng!","vi":"Chúc ngài thăng tiến từng bước!"},{"type":"simple","zh":"他进入公司后凭着努力步步高升。","pinyin":"Tā jìnrù gōngsī hòu píngzhe nǔlì bùbùgāoshēng.","vi":"Sau khi vào công ty, anh ấy nhờ nỗ lực mà từng bước thăng tiến."},{"type":"compound","zh":"自从换了新领导，他在单位里就步步高升。","pinyin":"Zìcóng huànle xīn lǐngdǎo, tā zài dānwèi li jiù bùbùgāoshēng.","vi":"Từ khi đổi lãnh đạo mới, anh ấy ở cơ quan liên tục được thăng chức."}],"related":[{"hanzi":"升职","pinyin":"shēngzhí","vi":"thăng chức"},{"hanzi":"飞黄腾达","pinyin":"Fēihuángténgdá","vi":"công danh hiển đạt"},{"hanzi":"一帆风顺","pinyin":"yìfānfēngshùn","vi":"thuận buồm xuôi gió"},{"hanzi":"晋升","pinyin":"jìnshēng","vi":"thăng tiến"}],"traditional":"步步高昇"},{"id":"不卑不亢","hanzi":"不卑不亢","pinyin":"bùbēi-búkàng","meaning_vi":"không tự ti cũng không kiêu ngạo, chừng mực","explanation":"不卑 (bất ti – không hèn mọn) + 不亢 (bất kháng – không kiêu ngạo) → thái độ đúng mực, tự tin mà không tự cao, không khúm núm.","hsk_level":6,"tags":["thanh-ngu"],"image":"⚖️","examples":[{"type":"basic","zh":"他说话不卑不亢。","pinyin":"Tā shuōhuà bù bēi bú kàng.","vi":"Anh ấy ăn nói chừng mực, không tự ti cũng không kiêu ngạo."},{"type":"simple","zh":"年轻的外交官在谈判桌上表现得不卑不亢。","pinyin":"Niánqīng de wàijiāoguān zài tánpànzhuō shang biǎoxiàn de bù bēi bú kàng.","vi":"Nhà ngoại giao trẻ thể hiện thái độ đúng mực trên bàn đàm phán."},{"type":"compound","zh":"无论对方地位多高，她都能不卑不亢地表达自己的意见。","pinyin":"Wúlùn duìfāng dìwèi duō gāo, tā dōu néng bù bēi bú kàng de biǎodá zìjǐ de yìjiàn.","vi":"Dù đối phương địa vị cao đến đâu, cô ấy vẫn bày tỏ ý kiến của mình một cách đúng mực, không tự ti cũng không kiêu căng."}],"related":[{"hanzi":"落落大方","pinyin":"luòluòdàfang","vi":"đường hoàng tự nhiên"},{"hanzi":"自信","pinyin":"zìxìn","vi":"tự tin"},{"hanzi":"卑躬屈膝","pinyin":"bēigōngqūxī","vi":"khom lưng uốn gối"},{"hanzi":"傲慢","pinyin":"àomàn","vi":"kiêu ngạo"}]},{"id":"不辞而别","hanzi":"不辞而别","pinyin":"bùcí-érbié","meaning_vi":"ra đi không một lời từ biệt","explanation":"不辞而别: không chào từ biệt mà đi → bỏ đi không nói một lời. Ví dụ: 他不辞而别, 让大家很担心.","hsk_level":6,"tags":["thanh-ngu"],"image":"👋","examples":[{"type":"basic","zh":"他不辞而别了。","pinyin":"Tā bù cí ér bié le.","vi":"Anh ấy ra đi không một lời từ biệt."},{"type":"simple","zh":"那位房客半夜收拾行李不辞而别。","pinyin":"Nà wèi fángkè bànyè shōushi xíngli bù cí ér bié.","vi":"Người thuê trọ đó nửa đêm thu dọn hành lý bỏ đi không một lời từ biệt."},{"type":"compound","zh":"即使你决定离开这个团队，也不应该不辞而别。","pinyin":"Jíshǐ nǐ juédìng líkāi zhè gè tuánduì, yě bù yīnggāi bù cí ér bié.","vi":"Dù cậu quyết định rời khỏi nhóm thì cũng không nên ra đi mà không chào ai."}],"related":[{"hanzi":"告别","pinyin":"gàobié","vi":"từ biệt"},{"hanzi":"离开","pinyin":"líkāi","vi":"rời đi"},{"hanzi":"悄悄","pinyin":"qiāoqiāo","vi":"lặng lẽ"},{"hanzi":"告辞","pinyin":"gàocí","vi":"cáo từ"}],"traditional":"不辭而別"},{"id":"步调","hanzi":"步调","pinyin":"bùdiào","meaning_vi":"bước đi, nhịp điệu hành động","explanation":"步 (bước) + 调 (điệu).","hsk_level":6,"tags":["danh-tu"],"image":"👣","examples":[{"type":"basic","zh":"大家步调一致。","pinyin":"Dàjiā bùdiào yízhì.","vi":"Mọi người bước đi đồng đều."},{"type":"simple","zh":"退休后，爸爸的生活步调慢了下来。","pinyin":"Tuìxiū hòu, bàba de shēnghuó bùdiào mànle xiàlái.","vi":"Sau khi nghỉ hưu, nhịp sống của bố chậm lại."},{"type":"compound","zh":"因为两个部门步调不统一，所以项目一再推迟。","pinyin":"Yīnwèi liǎng gè bùmén bùdiào bù tǒngyī, suǒyǐ xiàngmù yízài tuīchí.","vi":"Vì hai bộ phận hành động không đồng bộ nên dự án liên tục bị trì hoãn."}],"related":[{"hanzi":"步伐","pinyin":"bùfá","vi":"bước chân"},{"hanzi":"节奏","pinyin":"jiézòu","vi":"nhịp điệu"},{"hanzi":"步调一致","pinyin":"bùdiàoyízhì","vi":"nhịp bước đồng đều"},{"hanzi":"进度","pinyin":"jìndù","vi":"tiến độ"}],"traditional":"步調"},{"id":"不打不相识","hanzi":"不打不相识","pinyin":"bù dǎ bù xiāngshí","meaning_vi":"không đánh không quen biết","explanation":"不打 (không đánh) + 不相识 (bất tương thức – không quen nhau) → không đánh nhau thì chẳng quen nhau (gốc Thủy Hử) → qua va chạm, xung đột mà hiểu nhau rồi thành bạn.","hsk_level":6,"tags":["thanh-ngu"],"image":"🤝","examples":[{"type":"basic","zh":"我们是不打不相识。","pinyin":"Wǒmen shì bù dǎ bù xiāngshí.","vi":"Chúng tôi đúng là không đánh không quen."},{"type":"simple","zh":"他俩因为一次车祸不打不相识。","pinyin":"Tā liǎ yīnwèi yí cì chēhuò bù dǎ bù xiāngshí.","vi":"Hai người họ quen nhau nhờ một vụ va chạm xe, đúng là không đánh không quen."},{"type":"compound","zh":"虽然我们刚见面就吵了一架，但是不打不相识，后来成了好朋友。","pinyin":"Suīrán wǒmen gāng jiànmiàn jiù chǎole yí jià, dànshì bù dǎ bù xiāngshí, hòulái chéngle hǎopéngyou.","vi":"Tuy vừa gặp nhau đã cãi nhau một trận, nhưng không đánh không quen, về sau chúng tôi thành bạn tốt."}],"related":[{"hanzi":"不打不成交","pinyin":"bù dǎ bù chéngjiāo","vi":"có đánh mới thành bạn"},{"hanzi":"相识","pinyin":"xiāngshí","vi":"quen biết"},{"hanzi":"朋友","pinyin":"péngyou","vi":"bạn bè"},{"hanzi":"冤家","pinyin":"yuānjia","vi":"oan gia"}],"traditional":"不打不相識"},{"id":"不妨","hanzi":"不妨","pinyin":"bùfáng","meaning_vi":"đừng ngại, chi bằng","explanation":"不 (bất – không) + 妨 (phương – ngại, cản trở) → không ngại gì → cứ thử, chi bằng. Dùng để gợi ý nhẹ nhàng: 你不妨试试.","hsk_level":6,"tags":["pho-tu"],"image":"💡","examples":[{"type":"basic","zh":"你不妨试一试。","pinyin":"Nǐ bùfáng shìyishì.","vi":"Cậu cứ thử xem sao."},{"type":"simple","zh":"周末我们不妨去郊外的山上走走。","pinyin":"Zhōumò wǒmen bùfáng qù jiāowài de shān shang zǒu zou.","vi":"Cuối tuần chúng ta cứ thử ra núi ở ngoại ô đi dạo xem."},{"type":"compound","zh":"如果你拿不定主意，不妨听听父母的建议。","pinyin":"Rúguǒ nǐ ná búdìng zhǔyi, bùfáng tīng ting fùmǔ de jiànyì.","vi":"Nếu cậu chưa quyết được thì chi bằng nghe thử lời khuyên của bố mẹ."}],"related":[{"hanzi":"何妨","pinyin":"héfáng","vi":"sao không"},{"hanzi":"最好","pinyin":"zuìhǎo","vi":"tốt nhất"},{"hanzi":"可以","pinyin":"kěyǐ","vi":"có thể"},{"hanzi":"试试","pinyin":"shìshi","vi":"thử xem"}]},{"id":"不攻自破","hanzi":"不攻自破","pinyin":"bùgōng-zìpò","meaning_vi":"không đánh tự tan (lời đồn/âm mưu)","explanation":"不攻 (bất công – không tấn công) + 自破 (tự phá – tự vỡ) → không cần đánh tự tan → (lời đồn, luận điệu sai) tự bị vạch trần. Thường: 谣言不攻自破.","hsk_level":6,"tags":["thanh-ngu"],"image":"💨","examples":[{"type":"basic","zh":"这种说法不攻自破。","pinyin":"Zhè zhǒng shuōfǎ bù gōng zì pò.","vi":"Lối nói này tự sụp đổ."},{"type":"simple","zh":"他的谎言在监控录像面前不攻自破。","pinyin":"Tā de huǎngyán zài jiānkòng lùxiàng miànqián bù gōng zì pò.","vi":"Lời nói dối của hắn tự sụp đổ trước đoạn video camera giám sát."},{"type":"compound","zh":"只要拿出真实的数据，这些谣言就会不攻自破。","pinyin":"Zhǐyào náchū zhēnshí de shùjù, zhèxiē yáoyán jiù huì bù gōng zì pò.","vi":"Chỉ cần đưa ra số liệu thật thì những tin đồn này sẽ tự tan biến."}],"related":[{"hanzi":"谣言","pinyin":"yáoyán","vi":"tin đồn"},{"hanzi":"破产","pinyin":"pòchǎn","vi":"phá sản"},{"hanzi":"站不住脚","pinyin":"zhànbúzhùjiǎo","vi":"không đứng vững"},{"hanzi":"揭穿","pinyin":"jiēchuān","vi":"vạch trần"}]},{"id":"不假思索","hanzi":"不假思索","pinyin":"bùjiǎ-sīsuǒ","meaning_vi":"không cần suy nghĩ (trả lời ngay lập tức)","explanation":"不假 (bất giả – không mượn, không cần) + 思索 (tư sách – suy nghĩ) → không cần suy nghĩ → nói, làm ngay lập tức. Thường: 不假思索地回答.","hsk_level":6,"tags":["thanh-ngu"],"image":"⚡","examples":[{"type":"basic","zh":"她不假思索地签了字。","pinyin":"Tā bù jiǎ sīsuǒ de qiānle zì.","vi":"Cô ấy ký tên ngay mà không suy nghĩ."},{"type":"simple","zh":"小伙子不假思索地跳进河里救人。","pinyin":"Xiǎohuǒzi bù jiǎ sīsuǒ de tiàojìn hé li jiùrén.","vi":"Chàng trai không chút do dự nhảy xuống sông cứu người."},{"type":"compound","zh":"老师一提问，他就不假思索地说出了答案。","pinyin":"Lǎoshī yì tíwèn, tā jiù bù jiǎ sīsuǒ de shuōchūle dá'àn.","vi":"Thầy vừa đặt câu hỏi, cậu ấy liền nói ra đáp án mà không cần nghĩ."}],"related":[{"hanzi":"脱口而出","pinyin":"tuōkǒu'érchū","vi":"buột miệng nói ra"},{"hanzi":"毫不犹豫","pinyin":"háobùyóuyù","vi":"không chút do dự"},{"hanzi":"深思熟虑","pinyin":"shēnsīshúlǜ","vi":"suy nghĩ kỹ càng"},{"hanzi":"思索","pinyin":"sīsuǒ","vi":"suy nghĩ"}]},{"id":"不堪设想","hanzi":"不堪设想","pinyin":"bùkān-shèxiǎng","meaning_vi":"không dám tưởng tượng (hậu quả nghiêm trọng)","explanation":"不堪 (bất kham – không chịu nổi) + 设想 (thiết tưởng – tưởng tượng) → không dám tưởng tượng → (hậu quả) cực kỳ nghiêm trọng. Thường: 后果不堪设想.","hsk_level":6,"tags":["thanh-ngu"],"image":"😱","examples":[{"type":"basic","zh":"那种局面不堪设想。","pinyin":"Nà zhǒng júmiàn bùkān shèxiǎng.","vi":"Tình cảnh đó thật không dám tưởng tượng."},{"type":"simple","zh":"酒后开车的后果不堪设想。","pinyin":"Jiǔhòu kāichē de hòuguǒ bùkān shèxiǎng.","vi":"Hậu quả của việc lái xe sau khi uống rượu thật khôn lường."},{"type":"compound","zh":"如果刹车再晚一秒，后果就不堪设想了。","pinyin":"Rúguǒ shāchē zài wǎn yì miǎo, hòuguǒ jiù bùkān shèxiǎng le.","vi":"Nếu phanh chậm thêm một giây nữa thì hậu quả thật không dám nghĩ tới."}],"related":[{"hanzi":"后果","pinyin":"hòuguǒ","vi":"hậu quả"},{"hanzi":"严重","pinyin":"yánzhòng","vi":"nghiêm trọng"},{"hanzi":"可怕","pinyin":"kěpà","vi":"đáng sợ"},{"hanzi":"难以想象","pinyin":"nányǐxiǎngxiàng","vi":"khó tưởng tượng"}],"traditional":"不堪設想"},{"id":"不可思议","hanzi":"不可思议","pinyin":"bùkě-sīyì","meaning_vi":"không thể tin nổi, kỳ diệu khó lý giải","explanation":"不可 (bất khả – không thể) + 思议 (tư nghị – suy nghĩ, bàn luận) → vốn là thuật ngữ Phật giáo chỉ điều huyền diệu → khó tin, khó lý giải nổi.","hsk_level":6,"tags":["thanh-ngu"],"image":"😲","examples":[{"type":"basic","zh":"这真不可思议！","pinyin":"Zhè zhēn bùkě sīyì!","vi":"Thật không thể tin nổi!"},{"type":"simple","zh":"魔术师在舞台上表演了一个不可思议的魔术。","pinyin":"Móshùshī zài wǔtái shang biǎoyǎnle yí gè bùkě sīyì de móshù.","vi":"Ảo thuật gia đã biểu diễn trên sân khấu một màn ảo thuật khó tin."},{"type":"compound","zh":"因为这只小狗自己走了几百公里回家，所以大家都觉得不可思议。","pinyin":"Yīnwèi zhè zhī xiǎogǒu zìjǐ zǒule jǐ bǎi gōnglǐ huíjiā, suǒyǐ dàjiā dōu juéde bùkě sīyì.","vi":"Vì chú chó nhỏ này tự đi mấy trăm cây số về nhà nên ai cũng thấy thật khó tin."}],"related":[{"hanzi":"难以置信","pinyin":"nányǐzhìxìn","vi":"khó tin"},{"hanzi":"神奇","pinyin":"shénqí","vi":"thần kỳ"},{"hanzi":"奇妙","pinyin":"qímiào","vi":"kỳ diệu"},{"hanzi":"匪夷所思","pinyin":"fěiyísuǒsī","vi":"khó mà nghĩ tới"}],"traditional":"不可思議"},{"id":"不了了之","hanzi":"不了了之","pinyin":"bùliǎo-liǎozhī","meaning_vi":"bỏ lửng cho qua chuyện, không giải quyết dứt điểm","explanation":"不了 (bất liễu – chưa xong) + 了之 (liễu chi – coi như xong) → việc chưa giải quyết mà bỏ mặc coi như xong → chìm xuồng, bỏ lửng cho qua.","hsk_level":6,"tags":["thanh-ngu"],"image":"🤷","examples":[{"type":"basic","zh":"这件事不了了之。","pinyin":"Zhè jiàn shì bù liǎoliǎo zhī.","vi":"Chuyện này bị bỏ lửng cho qua."},{"type":"simple","zh":"那次投诉最后不了了之了。","pinyin":"Nà cì tóusù zuìhòu bù liǎoliǎo zhī le.","vi":"Lần khiếu nại đó cuối cùng cũng bị cho qua mà không giải quyết."},{"type":"compound","zh":"如果没有人负责跟进，这个调查就会不了了之。","pinyin":"Rúguǒ méiyǒu rén fùzé gēn jìn, zhè gè diàochá jiù huì bù liǎoliǎo zhī.","vi":"Nếu không ai chịu trách nhiệm theo dõi thì cuộc điều tra này sẽ bị bỏ lửng."}],"related":[{"hanzi":"半途而废","pinyin":"bàntú'érfèi","vi":"bỏ dở giữa chừng"},{"hanzi":"有始无终","pinyin":"yǒushǐwúzhōng","vi":"có đầu không cuối"},{"hanzi":"搁置","pinyin":"gēzhì","vi":"gác lại"},{"hanzi":"一了百了","pinyin":"yìliǎobǎiliǎo","vi":"xong một việc là xong hết"}]},{"id":"不劳而获","hanzi":"不劳而获","pinyin":"bùláo-érhuò","meaning_vi":"không làm mà muốn có ăn","explanation":"不劳而获: không lao động mà được hưởng → ăn không ngồi rồi, hưởng thành quả của người khác (nghĩa chê).","hsk_level":6,"tags":["thanh-ngu"],"image":"🦥","examples":[{"type":"basic","zh":"他总想不劳而获。","pinyin":"Tā zǒng xiǎng bù láo ér huò.","vi":"Hắn lúc nào cũng muốn không làm mà có ăn."},{"type":"simple","zh":"天下没有不劳而获的好事。","pinyin":"Tiānxià méiyǒu bù láo ér huò de hǎoshì.","vi":"Trên đời không có chuyện tốt nào không làm mà có."},{"type":"compound","zh":"他因为想不劳而获，所以买了很多彩票。","pinyin":"Tā yīnwèi xiǎng bù láo ér huò, suǒyǐ mǎile hěn duō cǎipiào.","vi":"Vì muốn không làm mà có nên anh ta mua rất nhiều vé số."}],"related":[{"hanzi":"坐享其成","pinyin":"zuòxiǎngqíchéng","vi":"ngồi hưởng thành quả"},{"hanzi":"劳动","pinyin":"láodòng","vi":"lao động"},{"hanzi":"一分耕耘一分收获","pinyin":"yì fēn gēngyún yì fēn shōuhuò","vi":"gieo gì gặt nấy"},{"hanzi":"懒惰","pinyin":"lǎnduò","vi":"lười biếng"}],"traditional":"不勞而獲"},{"id":"不免","hanzi":"不免","pinyin":"bùmiǎn","meaning_vi":"khó tránh khỏi","explanation":"不 (bất – không) + 免 (miễn – tránh) → không tránh khỏi, khó tránh. Đặt trước động từ/tính từ: 第一次上台不免紧张.","hsk_level":6,"tags":["pho-tu"],"image":"😔","examples":[{"type":"basic","zh":"他不免有点失望。","pinyin":"Tā bùmiǎn yǒudiǎn shīwàng.","vi":"Anh ấy khó tránh khỏi có chút thất vọng."},{"type":"simple","zh":"一个人在国外过年不免有些想家。","pinyin":"Yígèrén zài guówài guònián bùmiǎn yǒuxiē xiǎngjiā.","vi":"Một mình đón Tết ở nước ngoài khó tránh khỏi nhớ nhà."},{"type":"compound","zh":"因为这是他第一次独自出差，所以家人不免有些担心。","pinyin":"Yīnwèi zhè shì tā dìyīcì dúzì chūchāi, suǒyǐ jiārén bùmiǎn yǒuxiē dānxīn.","vi":"Vì đây là lần đầu anh ấy đi công tác một mình nên gia đình khó tránh khỏi lo lắng."}],"related":[{"hanzi":"难免","pinyin":"nánmiǎn","vi":"khó tránh"},{"hanzi":"免不了","pinyin":"miǎnbùliǎo","vi":"không tránh khỏi"},{"hanzi":"未免","pinyin":"wèimiǎn","vi":"khó tránh, hơi"},{"hanzi":"避免","pinyin":"bìmiǎn","vi":"tránh"}]},{"id":"不谋而合","hanzi":"不谋而合","pinyin":"bùmóu-érhé","meaning_vi":"không hẹn mà gặp (trùng hợp ý tưởng)","explanation":"不谋 (bất mưu – không bàn trước) + 而合 (nhi hợp – mà trùng khớp) → không bàn với nhau mà ý kiến, kế hoạch lại trùng khớp. Thường: 我们的想法不谋而合.","hsk_level":6,"tags":["thanh-ngu"],"image":"💡","examples":[{"type":"basic","zh":"我们的想法不谋而合。","pinyin":"Wǒmen de xiǎngfǎ bù móu ér hé.","vi":"Ý tưởng của chúng tôi trùng nhau dù không hẹn trước."},{"type":"simple","zh":"两位设计师的方案竟然不谋而合。","pinyin":"Liǎng wèi shèjìshī de fāng'àn jìngrán bù móu ér hé.","vi":"Phương án của hai nhà thiết kế lại trùng khớp với nhau một cách bất ngờ."},{"type":"compound","zh":"虽然我们事先没有商量，但是选的礼物不谋而合。","pinyin":"Suīrán wǒmen shìxiān méiyǒu shāngliang, dànshì xuǎn de lǐwù bù móu ér hé.","vi":"Tuy không bàn bạc trước nhưng món quà chúng tôi chọn lại trùng nhau."}],"related":[{"hanzi":"不约而同","pinyin":"bùyuē'értóng","vi":"không hẹn mà cùng"},{"hanzi":"英雄所见略同","pinyin":"yīngxióng suǒjiàn lüè tóng","vi":"anh hùng gặp nhau"},{"hanzi":"巧合","pinyin":"qiǎohé","vi":"trùng hợp"},{"hanzi":"分歧","pinyin":"fēnqí","vi":"bất đồng"}],"traditional":"不謀而合"},{"id":"布满","hanzi":"布满","pinyin":"bùmǎn","meaning_vi":"phủ đầy, giăng kín","explanation":"布 (bố – bày, rải) + 满 (mãn – đầy) → rải đầy, phủ kín khắp. Cụm: 天空布满乌云, 布满灰尘.","hsk_level":6,"tags":["dong-tu"],"image":"✨","examples":[{"type":"basic","zh":"天空布满乌云。","pinyin":"Tiānkōng bùmǎn wūyún.","vi":"Bầu trời phủ đầy mây đen."},{"type":"simple","zh":"老房子的墙角布满了蜘蛛网。","pinyin":"Lǎo fángzi de qiángjiǎo bùmǎnle zhīzhūwǎng.","vi":"Góc tường của ngôi nhà cũ giăng đầy mạng nhện."},{"type":"compound","zh":"因为长期熬夜，所以他的眼睛里布满了血丝。","pinyin":"Yīnwèi chángqī áoyè, suǒyǐ tā de yǎnjing li bùmǎnle xuèsī.","vi":"Vì thức khuya lâu ngày nên mắt anh ấy đầy tia máu."}],"related":[{"hanzi":"遍布","pinyin":"biànbù","vi":"trải khắp"},{"hanzi":"充满","pinyin":"chōngmǎn","vi":"tràn đầy"},{"hanzi":"密布","pinyin":"mìbù","vi":"dày đặc"},{"hanzi":"满是","pinyin":"mǎnshì","vi":"đầy rẫy"}],"traditional":"佈滿"},{"id":"不屈不挠","hanzi":"不屈不挠","pinyin":"bùqū-bùnáo","meaning_vi":"kiên cường bất khuất","explanation":"不屈 (bất khuất – không chịu khuất phục) + 不挠 (bất nạo – không cong, không lùi) → kiên cường, không chịu khuất phục trước khó khăn hay kẻ thù.","hsk_level":6,"tags":["thanh-ngu"],"image":"✊","examples":[{"type":"basic","zh":"他们不屈不挠地斗争。","pinyin":"Tāmen bùqū bù náo de dòuzhēng.","vi":"Họ đấu tranh kiên cường bất khuất."},{"type":"simple","zh":"这位运动员凭着不屈不挠的精神重返赛场。","pinyin":"Zhè wèi yùndòngyuán píngzhe bùqū bù náo de jīngshén chóngfǎn sàichǎng.","vi":"Vận động viên này nhờ tinh thần kiên cường bất khuất mà trở lại thi đấu."},{"type":"compound","zh":"即使经历了无数次失败，他也不屈不挠地坚持实验。","pinyin":"Jíshǐ jīnglìle wúshù cì shībài, tā yě bùqū bù náo de jiānchí shíyàn.","vi":"Dù trải qua vô số lần thất bại, anh ấy vẫn kiên cường bền bỉ tiếp tục thí nghiệm."}],"related":[{"hanzi":"百折不挠","pinyin":"bǎizhébùnáo","vi":"trăm lần gãy không sờn"},{"hanzi":"坚强","pinyin":"jiānqiáng","vi":"kiên cường"},{"hanzi":"顽强","pinyin":"wánqiáng","vi":"ngoan cường"},{"hanzi":"屈服","pinyin":"qūfú","vi":"khuất phục"}],"traditional":"不屈不撓"},{"id":"不容置疑","hanzi":"不容置疑","pinyin":"bùróng-zhìyí","meaning_vi":"không thể nghi ngờ, chắc chắn đúng","explanation":"不容 (bất dung – không cho phép) + 置疑 (trí nghi – đặt nghi vấn) → không cho phép nghi ngờ → hoàn toàn chắc chắn, đáng tin. Thường: 事实不容置疑.","hsk_level":6,"tags":["thanh-ngu"],"image":"💯","examples":[{"type":"basic","zh":"证据不容置疑。","pinyin":"Zhèngjù bùróng zhìyí.","vi":"Chứng cứ không thể nghi ngờ."},{"type":"simple","zh":"他用不容置疑的语气下达了命令。","pinyin":"Tāyòng bùróng zhìyí de yǔqì xiàdále mìnglìng.","vi":"Ông ấy ra lệnh bằng giọng điệu không cho phép nghi ngờ."},{"type":"compound","zh":"既然实验结果不容置疑，我们就按这个方案执行。","pinyin":"Jìrán shíyàn jiéguǒ bùróng zhìyí, wǒmen jiù àn zhè gè fāng'àn zhíxíng.","vi":"Kết quả thí nghiệm đã không thể nghi ngờ thì chúng ta cứ theo phương án này mà thực hiện."}],"related":[{"hanzi":"毋庸置疑","pinyin":"wúyōngzhìyí","vi":"không cần nghi ngờ"},{"hanzi":"确凿","pinyin":"quèzáo","vi":"xác thực"},{"hanzi":"肯定","pinyin":"kěndìng","vi":"chắc chắn"},{"hanzi":"怀疑","pinyin":"huáiyí","vi":"nghi ngờ"}]},{"id":"部署","hanzi":"部署","pinyin":"bùshǔ","meaning_vi":"bố trí, triển khai","explanation":"部 (bộ – sắp xếp) + 署 (thự – bố trí) → bố trí, sắp đặt (nhân lực, nhiệm vụ). Ví dụ: 部署工作, 军事部署; trong IT là triển khai (deploy).","hsk_level":6,"tags":["dong-tu"],"image":"📊","examples":[{"type":"basic","zh":"公司部署了新任务。","pinyin":"Gōngsī bùshǔle xīn rènwu.","vi":"Công ty triển khai nhiệm vụ mới."},{"type":"simple","zh":"警方在机场周围部署了大量警力。","pinyin":"Jǐngfāng zài jīchǎng zhōuwéi bùshǔle dàliàng jǐnglì.","vi":"Cảnh sát đã bố trí lực lượng lớn xung quanh sân bay."},{"type":"compound","zh":"只要提前部署好人员，活动当天就不会乱。","pinyin":"Zhǐyào tíqián bùshǔ hǎo rényuán, huódòng dàngtiān jiù bú huì luàn.","vi":"Chỉ cần bố trí nhân sự trước thì ngày diễn ra sự kiện sẽ không bị lộn xộn."}],"related":[{"hanzi":"安排","pinyin":"ānpái","vi":"sắp xếp"},{"hanzi":"布置","pinyin":"bùzhì","vi":"bố trí"},{"hanzi":"规划","pinyin":"guīhuà","vi":"quy hoạch"},{"hanzi":"战略部署","pinyin":"zhànlüèbùshǔ","vi":"bố trí chiến lược"}]},{"id":"不惜","hanzi":"不惜","pinyin":"bùxī","meaning_vi":"không tiếc, sẵn sàng (hy sinh/trả giá)","explanation":"不 (bất – không) + 惜 (tích – tiếc) → không tiếc, sẵn sàng hy sinh hay trả giá. Thường: 不惜一切代价 (bằng mọi giá), 不惜花重金.","hsk_level":6,"tags":["dong-tu"],"image":"💪","examples":[{"type":"basic","zh":"他不惜一切代价。","pinyin":"Tā bùxī yíqiè dàijià.","vi":"Anh ấy bất chấp mọi giá."},{"type":"simple","zh":"这位母亲不惜卖掉房子为女儿治病。","pinyin":"Zhè wèi mǔqīn bùxī màidiào fángzi wèi nǚ'ér zhìbìng.","vi":"Người mẹ này không tiếc bán nhà để chữa bệnh cho con gái."},{"type":"compound","zh":"即使亏本，这家公司也不惜降价抢占市场。","pinyin":"Jíshǐ kuīběn, zhè jiā gōngsī yě bùxī jiàngjià qiǎngzhàn shìchǎng.","vi":"Dù có lỗ vốn, công ty này cũng không ngại giảm giá để giành thị trường."}],"related":[{"hanzi":"舍得","pinyin":"shěde","vi":"nỡ, không tiếc"},{"hanzi":"不惜代价","pinyin":"bùxīdàijià","vi":"bằng mọi giá"},{"hanzi":"珍惜","pinyin":"zhēnxī","vi":"trân trọng"},{"hanzi":"宁可","pinyin":"nìngkě","vi":"thà rằng"}]},{"id":"不遗余力","hanzi":"不遗余力","pinyin":"bùyí-yúlì","meaning_vi":"dốc hết toàn bộ sức lực không giữ lại chút nào","explanation":"不遗 (bất di – không để sót) + 余力 (dư lực – sức còn thừa) → không giữ lại chút sức nào → dốc toàn lực. Thường: 不遗余力地支持.","hsk_level":6,"tags":["thanh-ngu"],"image":"💪","examples":[{"type":"basic","zh":"他不遗余力地帮我。","pinyin":"Tā bù yí yúlì de bāng wǒ.","vi":"Anh ấy dốc hết sức giúp tôi."},{"type":"simple","zh":"政府不遗余力地推动乡村教育的发展。","pinyin":"Zhèngfǔ bù yí yúlì de tuīdòng xiāngcūn jiàoyù de fāzhǎn.","vi":"Chính phủ dốc toàn lực thúc đẩy giáo dục nông thôn phát triển."},{"type":"compound","zh":"虽然项目困难重重，但是团队成员都不遗余力。","pinyin":"Suīrán xiàngmù kùnnan chóngchóng, dànshì tuánduì chéngyuán dōu bù yí yúlì.","vi":"Tuy dự án gặp muôn vàn khó khăn nhưng các thành viên trong nhóm đều dốc hết sức lực."}],"related":[{"hanzi":"全力以赴","pinyin":"quánlìyǐfù","vi":"dốc toàn lực"},{"hanzi":"竭尽全力","pinyin":"jiéjìnquánlì","vi":"dồn hết sức"},{"hanzi":"尽力","pinyin":"jìnlì","vi":"cố hết sức"},{"hanzi":"敷衍了事","pinyin":"fūyǎnliǎoshì","vi":"làm qua loa cho xong"}],"traditional":"不遺餘力"},{"id":"不由自主","hanzi":"不由自主","pinyin":"bùyóu-zìzhǔ","meaning_vi":"bất giác, không tự chủ được","explanation":"不由自主: không do mình làm chủ → bất giác, không kìm được. Ví dụ: 不由自主地笑了.","hsk_level":6,"tags":["thanh-ngu"],"image":"😮","examples":[{"type":"basic","zh":"我不由自主地笑了。","pinyin":"Wǒ bùyóu zìzhǔ de xiào le.","vi":"Tôi bất giác bật cười."},{"type":"simple","zh":"她跟着熟悉的旋律不由自主地唱了起来。","pinyin":"Tā gēnzhe shúxī de xuánlǜ bùyóu zìzhǔ de chàngle qǐlái.","vi":"Cô ấy bất giác hát theo giai điệu quen thuộc."},{"type":"compound","zh":"一闻到烤肉的香味，我就不由自主地走进了那家店。","pinyin":"Yì wéndào kǎoròu de xiāngwèi, wǒ jiù bùyóu zìzhǔ de zǒujìnle nà jiā diàn.","vi":"Vừa ngửi thấy mùi thịt nướng thơm phức, tôi liền bất giác bước vào quán đó."}],"related":[{"hanzi":"情不自禁","pinyin":"qíngbúzìjīn","vi":"không kìm được"},{"hanzi":"不知不觉","pinyin":"bùzhībùjué","vi":"bất giác"},{"hanzi":"自主","pinyin":"zìzhǔ","vi":"tự chủ"},{"hanzi":"身不由己","pinyin":"shēnbùyóujǐ","vi":"thân bất do kỷ"}]},{"id":"不以为然","hanzi":"不以为然","pinyin":"bùyǐ-wéirán","meaning_vi":"không cho là đúng, không tán thành","explanation":"不以 (bất dĩ – không cho) + 为然 (vi nhiên – là đúng) → không cho là đúng → không tán thành, thường kèm thái độ coi nhẹ. Khác 不以为意 (không để tâm).","hsk_level":6,"tags":["thanh-ngu"],"image":"🙅","examples":[{"type":"basic","zh":"她不以为然地摇摇头。","pinyin":"Tā bù yǐwéi rán de yáo yaotóu.","vi":"Cô ấy lắc đầu tỏ vẻ không đồng tình."},{"type":"simple","zh":"爷爷对年轻人的消费观念很不以为然。","pinyin":"Yéye duì niánqīngrén de xiāofèi guānniàn hěn bù yǐwéi rán.","vi":"Ông không tán thành quan niệm tiêu dùng của giới trẻ."},{"type":"compound","zh":"虽然专家提出了警告，但是很多人仍然不以为然。","pinyin":"Suīrán zhuānjiā tíchūle jǐnggào, dànshì hěn duō rén réngrán bù yǐwéi rán.","vi":"Tuy chuyên gia đã đưa ra cảnh báo nhưng nhiều người vẫn không cho là đúng."}],"related":[{"hanzi":"不赞成","pinyin":"búzànchéng","vi":"không tán thành"},{"hanzi":"反对","pinyin":"fǎnduì","vi":"phản đối"},{"hanzi":"不屑","pinyin":"búxiè","vi":"coi thường"},{"hanzi":"深以为然","pinyin":"shēnyǐwéirán","vi":"rất đồng tình"}],"traditional":"不以為然"},{"id":"不知所措","hanzi":"不知所措","pinyin":"bùzhī-suǒcuò","meaning_vi":"lúng túng không biết làm sao","explanation":"不知 (bất tri – không biết) + 所措 (sở thố – chỗ đặt tay chân, cách xử trí) → không biết xử trí ra sao → luống cuống, bối rối. Thường: 一时不知所措.","hsk_level":6,"tags":["thanh-ngu","cam-xuc"],"image":"😅","examples":[{"type":"basic","zh":"她吓得不知所措。","pinyin":"Tā xià de bùzhī suǒ cuò.","vi":"Cô ấy sợ đến mức không biết làm sao."},{"type":"simple","zh":"第一次当爸爸的他抱着孩子有些不知所措。","pinyin":"Dìyīcì dāng bàba de tā bàozhe háizi yǒuxiē bùzhī suǒ cuò.","vi":"Lần đầu làm bố, anh ấy bế con mà có phần lúng túng."},{"type":"compound","zh":"面试官一问到专业问题，他就紧张得不知所措。","pinyin":"Miànshìguān yí wèn dào zhuānyè wèntí, tā jiù jǐnzhāng de bùzhī suǒ cuò.","vi":"Người phỏng vấn vừa hỏi đến chuyên môn, anh ấy liền căng thẳng đến mức không biết làm sao."}],"related":[{"hanzi":"手足无措","pinyin":"shǒuzúwúcuò","vi":"luống cuống tay chân"},{"hanzi":"惊慌失措","pinyin":"jīnghuāngshīcuò","vi":"hoảng loạn"},{"hanzi":"茫然","pinyin":"mángrán","vi":"mơ hồ, ngơ ngác"},{"hanzi":"从容不迫","pinyin":"cóngróngbúpò","vi":"ung dung thong thả"}]},{"id":"不择手段","hanzi":"不择手段","pinyin":"bùzé-shǒuduàn","meaning_vi":"không từ thủ đoạn nào","explanation":"不择 (bất trạch – không chọn lựa) + 手段 (thủ đoạn) → không phân biệt thủ đoạn tốt xấu → dùng mọi cách để đạt mục đích. Mang nghĩa xấu.","hsk_level":6,"tags":["thanh-ngu"],"image":"⚠️","examples":[{"type":"basic","zh":"他为了钱不择手段。","pinyin":"Tā wèile qián bù zé shǒuduàn.","vi":"Hắn vì tiền mà không từ thủ đoạn."},{"type":"simple","zh":"有些商家不择手段地刷好评。","pinyin":"Yǒuxiē shāngjiā bù zé shǒuduàn de shuā hǎopíng.","vi":"Một số cửa hàng không từ thủ đoạn để tạo đánh giá tốt ảo."},{"type":"compound","zh":"即使竞争再激烈，我们也不能不择手段。","pinyin":"Jíshǐ jìngzhēng zài jīliè, wǒmen yě bùnéngbù zé shǒuduàn.","vi":"Dù cạnh tranh khốc liệt đến đâu, chúng ta cũng không được dùng mọi thủ đoạn."}],"related":[{"hanzi":"不惜一切","pinyin":"bùxīyíqiè","vi":"bất chấp tất cả"},{"hanzi":"手段","pinyin":"shǒuduàn","vi":"thủ đoạn"},{"hanzi":"卑鄙","pinyin":"bēibǐ","vi":"đê tiện"},{"hanzi":"光明正大","pinyin":"guāngmíngzhèngdà","vi":"quang minh chính đại"}],"traditional":"不擇手段"},{"id":"不动声色","hanzi":"不动声色","pinyin":"búdòng-shēngsè","meaning_vi":"bình tĩnh thản nhiên, không để lộ cảm xúc","explanation":"不动 (bất động – không thay đổi) + 声色 (thanh sắc – giọng nói và sắc mặt) → giọng nói, nét mặt không đổi → điềm tĩnh, không để lộ cảm xúc hay ý định.","hsk_level":6,"tags":["thanh-ngu"],"image":"😐","examples":[{"type":"basic","zh":"他不动声色地听着。","pinyin":"Tā búdòng shēng sè de tīng zhe.","vi":"Anh ấy lặng lẽ lắng nghe, không để lộ cảm xúc."},{"type":"simple","zh":"侦探不动声色地观察着每个客人的表情。","pinyin":"Zhēntàn búdòng shēng sè de guāncházhe měi gè kèrén de biǎoqíng.","vi":"Thám tử thản nhiên quan sát nét mặt của từng vị khách."},{"type":"compound","zh":"虽然心里很生气，但是她表面上不动声色。","pinyin":"Suīrán xīnli hěn shēngqì, dànshì tā biǎomiànshang búdòng shēng sè.","vi":"Tuy trong lòng rất tức giận nhưng bề ngoài cô ấy vẫn bình thản."}],"related":[{"hanzi":"镇定自若","pinyin":"zhèndìngzìruò","vi":"bình tĩnh tự nhiên"},{"hanzi":"若无其事","pinyin":"ruòwúqíshì","vi":"như không có chuyện gì"},{"hanzi":"面不改色","pinyin":"miànbùgǎisè","vi":"mặt không biến sắc"},{"hanzi":"喜形于色","pinyin":"xǐxíngyúsè","vi":"vui lộ ra mặt"}],"traditional":"不動聲色"},{"id":"不顾","hanzi":"不顾","pinyin":"búgù","meaning_vi":"bất chấp, không màng tới","explanation":"不 + 顾 (ngoái nhìn/quan tâm).","hsk_level":6,"tags":["dong-tu","gioi-tu"],"image":"🏃","examples":[{"type":"basic","zh":"他不顾危险冲进火场。","pinyin":"Tā búgù wēixiǎn chōngjìn huǒchǎng.","vi":"Anh ấy bất chấp nguy hiểm lao vào đám cháy."},{"type":"simple","zh":"她不顾家人的反对嫁给了他。","pinyin":"Tā búgù jiārén de fǎnduì jià gěile tā.","vi":"Cô ấy bất chấp sự phản đối của gia đình mà lấy anh ấy."},{"type":"compound","zh":"如果你一直不顾健康拼命加班，就会把身体累垮。","pinyin":"Rúguǒ nǐ yìzhí búgù jiànkāng pīnmìng jiābān, jiù huì bǎ shēntǐ lèikuǎ.","vi":"Nếu cậu cứ bất chấp sức khỏe mà liều mạng tăng ca thì sẽ kiệt sức mất."}],"related":[{"hanzi":"不管","pinyin":"bùguǎn","vi":"bất kể"},{"hanzi":"顾及","pinyin":"gùjí","vi":"để ý đến"},{"hanzi":"不顾一切","pinyin":"búgùyíqiè","vi":"bất chấp tất cả"},{"hanzi":"照顾","pinyin":"zhàogù","vi":"chăm sóc"}],"traditional":"不顧"},{"id":"不计其数","hanzi":"不计其数","pinyin":"bújì-qíshù","meaning_vi":"nhiều vô kể, không đếm xuể","explanation":"不计 (bất kế – không tính) + 其数 (kỳ số – số lượng của nó) → không đếm được số lượng → nhiều vô kể.","hsk_level":6,"tags":["thanh-ngu","so-luong"],"image":"♾️","examples":[{"type":"basic","zh":"天上的星星不计其数。","pinyin":"Tiānshang de xīngxing bújì qí shù.","vi":"Sao trên trời nhiều không đếm xuể."},{"type":"simple","zh":"每年来长城参观的游客不计其数。","pinyin":"Měi niánlái Chángchéng cānguān de yóukè bújì qí shù.","vi":"Mỗi năm du khách đến tham quan Vạn Lý Trường Thành nhiều vô kể."},{"type":"compound","zh":"他虽然失败的次数不计其数，但是从来没有放弃过。","pinyin":"Tā suīrán shībài de cìshù bújì qí shù, dànshì cónglái méiyǒu fàngqì guo.","vi":"Tuy số lần thất bại nhiều không đếm xuể nhưng anh ấy chưa bao giờ từ bỏ."}],"related":[{"hanzi":"数不胜数","pinyin":"shǔbúshèngshǔ","vi":"đếm không xuể"},{"hanzi":"不胜枚举","pinyin":"búshèngméijǔ","vi":"nhiều không kể xiết"},{"hanzi":"无数","pinyin":"wúshù","vi":"vô số"},{"hanzi":"寥寥无几","pinyin":"liáoliáowújǐ","vi":"ít ỏi"}],"traditional":"不計其數"},{"id":"不愧","hanzi":"不愧","pinyin":"búkuì","meaning_vi":"không hổ thẹn là, xứng đáng là","explanation":"不 + 愧 (xấu hổ). Cụm: 不愧是...","hsk_level":6,"tags":["dong-tu","pho-tu"],"image":"🏅","examples":[{"type":"basic","zh":"他不愧是冠军。","pinyin":"Tā búkuì shì guànjūn.","vi":"Anh ấy xứng đáng là nhà vô địch."},{"type":"simple","zh":"李医生不愧为全国有名的心脏专家。","pinyin":"Lǐ yīshēng búkuì wéi quánguó yǒumíng de xīnzàng zhuānjiā.","vi":"Bác sĩ Lý xứng đáng là chuyên gia tim mạch nổi tiếng toàn quốc."},{"type":"compound","zh":"他一开口就逗笑了全场，不愧是有名的相声演员。","pinyin":"Tā yì kāikǒu jiù dòuxiàole quánchǎng, búkuì shì yǒumíng de xiàngsheng yǎnyuán.","vi":"Anh ấy vừa mở lời đã khiến cả khán phòng cười ồ, quả xứng danh diễn viên tấu hài nổi tiếng."}],"related":[{"hanzi":"无愧","pinyin":"wúkuì","vi":"không hổ thẹn"},{"hanzi":"不愧为","pinyin":"búkuìwéi","vi":"xứng đáng là"},{"hanzi":"名副其实","pinyin":"míngfùqíshí","vi":"danh xứng với thực"},{"hanzi":"惭愧","pinyin":"cánkuì","vi":"hổ thẹn"}]},{"id":"不料","hanzi":"不料","pinyin":"búliào","meaning_vi":"không ngờ, chẳng ngờ","explanation":"不 + 料 (dự đoán).","hsk_level":6,"tags":["lien-tu","pho-tu"],"image":"😲","examples":[{"type":"basic","zh":"不料天下起了雨。","pinyin":"Búliào tiānxià qǐle yǔ.","vi":"Không ngờ trời lại đổ mưa."},{"type":"simple","zh":"不料他今天竟然迟到了一个小时。","pinyin":"Búliào tā jīntiān jìngrán chídàole yí gè xiǎoshí.","vi":"Không ngờ hôm nay anh ấy lại đến muộn cả tiếng đồng hồ."},{"type":"compound","zh":"我本想给她一个惊喜，不料她早就知道了。","pinyin":"Wǒ běn xiǎng gěi tā yí gè jīngxǐ, búliào tā zǎojiù zhīdàole.","vi":"Tôi vốn định tạo bất ngờ cho cô ấy, không ngờ cô ấy đã biết từ lâu."}],"related":[{"hanzi":"没想到","pinyin":"méixiǎngdào","vi":"không ngờ"},{"hanzi":"意外","pinyin":"yìwài","vi":"bất ngờ"},{"hanzi":"竟然","pinyin":"jìngrán","vi":"vậy mà"},{"hanzi":"果然","pinyin":"guǒrán","vi":"quả nhiên"}]},{"id":"不胜枚举","hanzi":"不胜枚举","pinyin":"búshèng-méijǔ","meaning_vi":"nhiều không kể xiết","explanation":"不胜 (bất thắng – không kham nổi) + 枚举 (mai cử – kể ra từng cái) → không thể kể ra từng cái một → nhiều không kể xiết. Hay dùng khi nói ví dụ quá nhiều.","hsk_level":6,"tags":["thanh-ngu"],"image":"📑","examples":[{"type":"basic","zh":"这样的例子不胜枚举。","pinyin":"Zhèyàng de lìzi búshèng méijǔ.","vi":"Những ví dụ như vậy nhiều không kể xiết."},{"type":"simple","zh":"这位老中医治好的病人不胜枚举。","pinyin":"Zhè wèi lǎo zhōngyī zhìhǎo de bìngrén búshèng méijǔ.","vi":"Số bệnh nhân vị lương y già này chữa khỏi nhiều không kể xiết."},{"type":"compound","zh":"因为网络诈骗的手法不胜枚举，所以大家一定要提高警惕。","pinyin":"Yīnwèi wǎngluòzhàpiàn de shǒufǎ búshèng méijǔ, suǒyǐ dàjiā yídìngyào tígāo jǐngtì.","vi":"Vì thủ đoạn lừa đảo qua mạng nhiều không kể xiết nên mọi người nhất định phải nâng cao cảnh giác."}],"related":[{"hanzi":"不计其数","pinyin":"bújìqíshù","vi":"nhiều vô kể"},{"hanzi":"数不胜数","pinyin":"shǔbúshèngshǔ","vi":"đếm không xuể"},{"hanzi":"比比皆是","pinyin":"bǐbǐjiēshì","vi":"đâu đâu cũng có"},{"hanzi":"屈指可数","pinyin":"qūzhǐkěshǔ","vi":"đếm trên đầu ngón tay"}],"traditional":"不勝枚舉"},{"id":"不务正业","hanzi":"不务正业","pinyin":"búwù-zhèngyè","meaning_vi":"không lo làm ăn chân chính","explanation":"不务 (bất vụ – không chuyên tâm) + 正业 (chính nghiệp – nghề chính đáng) → không lo làm việc chính → lêu lổng; cũng dùng vui cho người làm trái nghề.","hsk_level":6,"tags":["thanh-ngu"],"image":"🎮","examples":[{"type":"basic","zh":"他整天不务正业。","pinyin":"Tā zhěngtiān bú wù zhèngyè.","vi":"Hắn suốt ngày không lo làm ăn đàng hoàng."},{"type":"simple","zh":"那个不务正业的年轻人又在街上闲逛。","pinyin":"Nà gè bú wù zhèngyè de niánqīngrén yòu zài jiēshang xiánguàng.","vi":"Gã thanh niên lêu lổng đó lại đang lang thang ngoài phố."},{"type":"compound","zh":"如果你再这样不务正业，就别想从家里拿一分钱。","pinyin":"Rúguǒ nǐ zài zhèyàng bú wù zhèngyè, jiù biéxiǎng cóng jiāli ná yì fēnqián.","vi":"Nếu con còn lêu lổng không lo làm ăn như thế thì đừng mong lấy được một xu nào của nhà."}],"related":[{"hanzi":"游手好闲","pinyin":"yóushǒuhàoxián","vi":"du thủ du thực"},{"hanzi":"正业","pinyin":"zhèngyè","vi":"nghề chính đáng"},{"hanzi":"安分守己","pinyin":"ānfènshǒujǐ","vi":"an phận thủ thường"},{"hanzi":"无所事事","pinyin":"wúsuǒshìshì","vi":"không có việc gì làm"}],"traditional":"不務正業"},{"id":"不屑一顾","hanzi":"不屑一顾","pinyin":"búxiè-yígù","meaning_vi":"không thèm ngó ngàng tới","explanation":"不屑 (bất tiết – không thèm) + 一顾 (nhất cố – nhìn một cái) → không thèm nhìn lấy một cái → hết sức coi thường, khinh miệt.","hsk_level":6,"tags":["thanh-ngu"],"image":"😒","examples":[{"type":"basic","zh":"他对名利不屑一顾。","pinyin":"Tā duì mínglì búxiè yí gù.","vi":"Anh ấy không thèm để mắt đến danh lợi."},{"type":"simple","zh":"那位明星对网上的批评不屑一顾。","pinyin":"Nà wèi míngxīng duì wǎngshang de pīpíng búxiè yí gù.","vi":"Ngôi sao đó chẳng thèm ngó ngàng đến những lời chỉ trích trên mạng."},{"type":"compound","zh":"虽然当初大家都对他的发明不屑一顾，但是现在它卖得非常好。","pinyin":"Suīrán dāngchū dàjiā dōu duì tā de fāmíng búxiè yí gù, dànshì xiànzài tā mài de fēicháng hǎo.","vi":"Tuy lúc đầu mọi người đều chẳng thèm để ý đến phát minh của anh ấy nhưng giờ nó bán rất chạy."}],"related":[{"hanzi":"不屑","pinyin":"búxiè","vi":"khinh thường"},{"hanzi":"轻视","pinyin":"qīngshì","vi":"coi nhẹ"},{"hanzi":"看不起","pinyin":"kànbuqǐ","vi":"xem thường"},{"hanzi":"重视","pinyin":"zhòngshì","vi":"coi trọng"}],"traditional":"不屑一顧"},{"id":"不厌其烦","hanzi":"不厌其烦","pinyin":"búyàn-qífán","meaning_vi":"không ngại phiền hà (kiên nhẫn giúp đỡ)","explanation":"不厌 (không chán) + 其烦 (sự phiền phức). Thành ngữ.","hsk_level":6,"tags":["thanh-ngu"],"image":"🤗","examples":[{"type":"basic","zh":"老师不厌其烦地讲解。","pinyin":"Lǎoshī búyàn qí fán de jiǎngjiě.","vi":"Thầy kiên nhẫn giảng giải, không ngại phiền."},{"type":"simple","zh":"客服人员不厌其烦地回答我的问题。","pinyin":"Kèfú rényuán búyàn qí fán de huídá wǒ de wèntí.","vi":"Nhân viên chăm sóc khách hàng kiên nhẫn trả lời các câu hỏi của tôi."},{"type":"compound","zh":"无论奶奶问多少遍，我都不厌其烦地教她用手机。","pinyin":"Wúlùn nǎinai wèn duōshǎo biàn, wǒ dōu búyàn qí fán de jiāo tā yòng shǒujī.","vi":"Dù bà hỏi bao nhiêu lần, tôi vẫn kiên nhẫn dạy bà dùng điện thoại."}],"related":[{"hanzi":"耐心","pinyin":"nàixīn","vi":"kiên nhẫn"},{"hanzi":"耐心细致","pinyin":"nàixīnxìzhì","vi":"kiên nhẫn tỉ mỉ"},{"hanzi":"不耐烦","pinyin":"búnàifán","vi":"mất kiên nhẫn"},{"hanzi":"厌烦","pinyin":"yànfán","vi":"chán ghét"}],"traditional":"不厭其煩"},{"id":"不二法门","hanzi":"不二法门","pinyin":"bú'èr-fǎmén","meaning_vi":"phương pháp duy nhất và tốt nhất","explanation":"不二 (bất nhị – không có cái thứ hai) + 法门 (pháp môn – con đường tu hành, gốc kinh Duy Ma Cật) → pháp môn duy nhất → cách tốt nhất, duy nhất để đạt mục đích.","hsk_level":6,"tags":["thanh-ngu"],"image":"🔑","examples":[{"type":"basic","zh":"他终于找到了不二法门。","pinyin":"Tā zhōngyú zhǎodàole bú'èr fǎmén.","vi":"Cuối cùng anh ấy đã tìm ra phương pháp tốt nhất."},{"type":"simple","zh":"控制饮食加适量运动是减肥的不二法门。","pinyin":"Kòngzhì yǐnshí jiā shìliàng yùndòng shì jiǎnféi de bú'èr fǎmén.","vi":"Kiểm soát ăn uống kết hợp vận động vừa phải là cách giảm cân hiệu quả nhất."},{"type":"compound","zh":"要想留住老顾客，就得靠诚信这个不二法门。","pinyin":"Yào xiǎng liúzhù lǎo gùkè, jiù děi kào chéngxìn zhè gè bú'èr fǎmén.","vi":"Muốn giữ chân khách quen thì phải dựa vào chữ tín, con đường duy nhất."}],"related":[{"hanzi":"唯一","pinyin":"wéiyī","vi":"duy nhất"},{"hanzi":"方法","pinyin":"fāngfǎ","vi":"phương pháp"},{"hanzi":"诀窍","pinyin":"juéqiào","vi":"bí quyết"},{"hanzi":"捷径","pinyin":"jiéjìng","vi":"đường tắt"}],"traditional":"不二法門"},{"id":"扒","hanzi":"扒","pinyin":"bā","meaning_vi":"bám, vịn; bới, gạt ra; lột, cởi","explanation":"扒 (bā): bám, víu (扒着窗台); bới, cào (扒土); bóc, lột (扒皮, 扒香蕉皮). Đọc pá thì nghĩa là móc túi (扒手) hoặc ninh nhừ (扒鸡).","hsk_level":6,"tags":["dong-tu"],"image":"👐","examples":[{"type":"basic","zh":"他扒开了草丛。","pinyin":"Tā bākāile cǎocóng.","vi":"Anh ấy rẽ bụi cỏ ra."},{"type":"simple","zh":"小猫扒着窗台往外看。","pinyin":"Xiǎomāo bāzhe chuāngtái wǎng wài kàn.","vi":"Con mèo con bám vào bậu cửa sổ nhìn ra ngoài."},{"type":"compound","zh":"他一回到家，就扒下湿透的外套扔在沙发上。","pinyin":"Tā yì huí dàojiā, jiù bā xià shītòu de wàitào rēng zài shāfā shang.","vi":"Anh ấy vừa về đến nhà liền lột chiếc áo khoác ướt sũng ra quăng lên ghế sofa."}],"related":[{"hanzi":"扒开","pinyin":"bākāi","vi":"vạch ra"},{"hanzi":"扒皮","pinyin":"bāpí","vi":"lột da"},{"hanzi":"扒手","pinyin":"páshǒu","vi":"kẻ móc túi"},{"hanzi":"剥","pinyin":"bāo","vi":"bóc, lột"}]},{"id":"八成","hanzi":"八成","pinyin":"bāchéng","meaning_vi":"tám phần mười; chắc là, phần lớn khả năng","explanation":"八 (tám) + 成 (phần mười).","hsk_level":6,"tags":["pho-tu","so-luong"],"image":"🎲","examples":[{"type":"basic","zh":"他八成忘了。","pinyin":"Tā bāchéng wàng le.","vi":"Chắc anh ấy quên rồi."},{"type":"simple","zh":"这批苹果有八成都已经熟了。","pinyin":"Zhè pī píngguǒ yǒu bāchéng dōu yǐjīng shú le.","vi":"Lô táo này có tám phần mười đã chín rồi."},{"type":"compound","zh":"既然他的手机一直关机，八成是在飞机上。","pinyin":"Jìrán tā de shǒujī yìzhí guānjī, bāchéng shì zài fēijī shang.","vi":"Điện thoại anh ấy đã tắt suốt thì chắc là đang ở trên máy bay."}],"related":[{"hanzi":"大概","pinyin":"dàgài","vi":"đại khái"},{"hanzi":"可能","pinyin":"kěnéng","vi":"có thể"},{"hanzi":"也许","pinyin":"yěxǔ","vi":"có lẽ"},{"hanzi":"十有八九","pinyin":"shíyǒubājiǔ","vi":"mười phần chắc tám chín"}]},{"id":"疤痕","hanzi":"疤痕","pinyin":"bāhén","meaning_vi":"vết sẹo","explanation":"Cả hai chữ đều có bộ nạch 疒.","hsk_level":6,"tags":["danh-tu","co-the"],"image":"🩹","examples":[{"type":"basic","zh":"他脸上有道疤痕。","pinyin":"Tā liǎn shang yǒudào bāhén.","vi":"Trên mặt anh ấy có một vết sẹo."},{"type":"simple","zh":"手术后留下的疤痕已经慢慢变淡了。","pinyin":"Shǒushù hòu liúxià de bāhén yǐjīng mànmàn biàn dàn le.","vi":"Vết sẹo để lại sau phẫu thuật đã dần mờ đi."},{"type":"compound","zh":"即使伤口愈合了，心里的疤痕也很难消失。","pinyin":"Jíshǐ shāngkǒu yùhé le, xīnli de bāhén yě hěn nán xiāoshī.","vi":"Dù vết thương đã lành thì vết sẹo trong lòng cũng khó mà biến mất."}],"related":[{"hanzi":"伤疤","pinyin":"shāngbā","vi":"vết sẹo"},{"hanzi":"伤口","pinyin":"shāngkǒu","vi":"vết thương"},{"hanzi":"痕迹","pinyin":"hénjì","vi":"dấu vết"},{"hanzi":"留疤","pinyin":"liúbā","vi":"để lại sẹo"}]},{"id":"斑白","hanzi":"斑白","pinyin":"bānbái","meaning_vi":"hoa râm (tóc bạc lẫn đen)","explanation":"斑 (đốm/lẫn lộn) + 白 (trắng). Cụm: 两鬓斑白.","hsk_level":6,"tags":["tinh-tu","co-the"],"image":"👴","examples":[{"type":"basic","zh":"父亲两鬓斑白。","pinyin":"Fùqīn liǎng bìn bānbái.","vi":"Hai bên tóc mai của cha đã hoa râm."},{"type":"simple","zh":"那位头发斑白的老人每天在公园里打太极拳。","pinyin":"Nà wèi tóufa bānbái de lǎorén měitiān zài gōngyuán li dǎ tàijíquán.","vi":"Cụ già tóc hoa râm đó ngày nào cũng tập thái cực quyền trong công viên."},{"type":"compound","zh":"才过了几年，他的头发就已经斑白了。","pinyin":"Cáiguò le jǐ nián, tā de tóufa jiù yǐjīng bānbái le.","vi":"Mới qua mấy năm mà tóc anh ấy đã hoa râm rồi."}],"related":[{"hanzi":"白发","pinyin":"báifà","vi":"tóc bạc"},{"hanzi":"两鬓斑白","pinyin":"liǎngbìnbānbái","vi":"tóc mai hoa râm"},{"hanzi":"苍老","pinyin":"cānglǎo","vi":"già nua"},{"hanzi":"花白","pinyin":"huābái","vi":"hoa râm"}]},{"id":"斑斓","hanzi":"斑斓","pinyin":"bānlán","meaning_vi":"sặc sỡ, rực rỡ nhiều màu sắc","explanation":"Cụm: 五彩斑斓 (ngũ sắc rực rỡ).","hsk_level":6,"tags":["tinh-tu","mau-sac"],"image":"🌈","examples":[{"type":"basic","zh":"秋天的山色斑斓。","pinyin":"Qiūtiān de shān sè bānlán.","vi":"Sắc núi mùa thu rực rỡ nhiều màu."},{"type":"simple","zh":"孩子们在纸上画出了色彩斑斓的蝴蝶。","pinyin":"Háizimen zài zhǐ shang huà chūle sècǎi bānlán de húdié.","vi":"Bọn trẻ vẽ lên giấy những chú bướm sặc sỡ sắc màu."},{"type":"compound","zh":"一到夜晚，河两岸的灯光就变得五彩斑斓。","pinyin":"Yí dào yèwǎn, hé liǎng'àn de dēngguāng jiù biànde wǔcǎi bānlán.","vi":"Cứ đến đêm, ánh đèn hai bên bờ sông lại trở nên rực rỡ sắc màu."}],"related":[{"hanzi":"五彩斑斓","pinyin":"wǔcǎibānlán","vi":"rực rỡ sắc màu"},{"hanzi":"绚丽","pinyin":"xuànlì","vi":"rực rỡ"},{"hanzi":"多彩","pinyin":"duōcǎi","vi":"nhiều màu"},{"hanzi":"色彩","pinyin":"sècǎi","vi":"sắc màu"}],"traditional":"斑斕"},{"id":"搬迁","hanzi":"搬迁","pinyin":"bānqiān","meaning_vi":"di dời, chuyển chỗ ở/nhà máy","explanation":"搬 (chuyển) + 迁 (dời).","hsk_level":6,"tags":["dong-tu","nha-cua"],"image":"🚚","examples":[{"type":"basic","zh":"工厂要搬迁了。","pinyin":"Gōngchǎng yào bānqiān le.","vi":"Nhà máy sắp di dời."},{"type":"simple","zh":"我们公司下个月将搬迁到新区。","pinyin":"Wǒmen gōngsī xiàgèyuè jiāng bānqiān dào xīn qū.","vi":"Tháng sau công ty chúng tôi sẽ chuyển đến khu mới."},{"type":"compound","zh":"因为要修建水库，所以整个村子都要搬迁。","pinyin":"Yīnwèi yào xiūjiàn shuǐkù, suǒyǐ zhěnggè cūnzi dōu yào bānqiān.","vi":"Vì phải xây hồ chứa nước nên cả ngôi làng đều phải di dời."}],"related":[{"hanzi":"搬家","pinyin":"bānjiā","vi":"chuyển nhà"},{"hanzi":"迁移","pinyin":"qiānyí","vi":"di dời"},{"hanzi":"拆迁","pinyin":"chāiqiān","vi":"giải tỏa di dời"},{"hanzi":"移民","pinyin":"yímín","vi":"di dân"}],"traditional":"搬遷"},{"id":"斑纹","hanzi":"斑纹","pinyin":"bānwén","meaning_vi":"vằn, đốm, hoa văn","explanation":"斑 (ban – vết lốm đốm) + 纹 (văn – đường vân) → vằn, đốm trên da, lông động vật hoặc bề mặt vật. Ví dụ: 老虎的斑纹; 斑马 = ngựa vằn.","hsk_level":6,"tags":["danh-tu"],"image":"🦓","examples":[{"type":"basic","zh":"老虎身上有斑纹。","pinyin":"Lǎohǔ shēnshang yǒu bānwén.","vi":"Trên mình con hổ có vằn."},{"type":"simple","zh":"每匹斑马身上的黑白斑纹都不一样。","pinyin":"Měi pǐ bānmǎ shēnshang de hēibái bānwén dōu bù yíyàng.","vi":"Vằn đen trắng trên mình mỗi con ngựa vằn đều không giống nhau."},{"type":"compound","zh":"这种蛇不但有鲜艳的斑纹，而且毒性很强。","pinyin":"Zhè zhǒng shé búdàn yǒu xiānyàn de bānwén, érqiě dúxìng hěn qiáng.","vi":"Loài rắn này không những có hoa văn sặc sỡ mà độc tính còn rất mạnh."}],"related":[{"hanzi":"条纹","pinyin":"tiáowén","vi":"sọc"},{"hanzi":"斑点","pinyin":"bāndiǎn","vi":"đốm"},{"hanzi":"花纹","pinyin":"huāwén","vi":"hoa văn"},{"hanzi":"斑马","pinyin":"bānmǎ","vi":"ngựa vằn"}],"traditional":"斑紋"},{"id":"颁行","hanzi":"颁行","pinyin":"bānxíng","meaning_vi":"ban hành và thi hành","explanation":"颁 (ban bố) + 行 (thi hành).","hsk_level":6,"tags":["dong-tu","phap-luat"],"image":"📜","examples":[{"type":"basic","zh":"新法已经颁行。","pinyin":"Xīn fǎ yǐjīng bānxíng.","vi":"Luật mới đã được ban hành."},{"type":"simple","zh":"国家颁行了新的食品安全标准。","pinyin":"Guójiā bānxíngle xīn de shípǐn ānquán biāozhǔn.","vi":"Nhà nước đã ban hành tiêu chuẩn an toàn thực phẩm mới."},{"type":"compound","zh":"这项条例一颁行，各地就开始严格执行。","pinyin":"Zhè xiàng tiáolì yì bānxíng, gèdì jiù kāishǐ yángé zhíxíng.","vi":"Điều lệ này vừa được ban hành, các địa phương đã bắt đầu thi hành nghiêm ngặt."}],"related":[{"hanzi":"颁布","pinyin":"bānbù","vi":"ban bố"},{"hanzi":"实行","pinyin":"shíxíng","vi":"thực hiện"},{"hanzi":"施行","pinyin":"shīxíng","vi":"thi hành"},{"hanzi":"法令","pinyin":"fǎlìng","vi":"pháp lệnh"}],"traditional":"頒行"},{"id":"帮凶","hanzi":"帮凶","pinyin":"bāngxiōng","meaning_vi":"đồng lõa, tòng phạm","explanation":"帮 (giúp) + 凶 (hung thủ).","hsk_level":6,"tags":["danh-tu","phap-luat","con-nguoi"],"image":"🦹","examples":[{"type":"basic","zh":"他成了帮凶。","pinyin":"Tā chéngle bāngxiōng.","vi":"Hắn đã trở thành đồng lõa."},{"type":"simple","zh":"法院认定司机是这起抢劫案的帮凶。","pinyin":"Fǎyuàn rèndìng sījī shì zhè qǐ qiǎngjié'àn de bāngxiōng.","vi":"Tòa án xác định tài xế là đồng phạm trong vụ cướp này."},{"type":"compound","zh":"如果你明知他在犯罪还帮他隐瞒，你就是帮凶。","pinyin":"Rúguǒ nǐ míngzhī tā zài fànzuì hái bāng tā yǐnmán, nǐ jiùshì bāngxiōng.","vi":"Nếu biết rõ hắn đang phạm tội mà còn giúp che giấu thì cậu chính là đồng lõa."}],"related":[{"hanzi":"同伙","pinyin":"tónghuǒ","vi":"đồng bọn"},{"hanzi":"共犯","pinyin":"gòngfàn","vi":"đồng phạm"},{"hanzi":"帮手","pinyin":"bāngshou","vi":"người giúp"},{"hanzi":"主谋","pinyin":"zhǔmóu","vi":"kẻ chủ mưu"}],"traditional":"幫凶"},{"id":"包办","hanzi":"包办","pinyin":"bāobàn","meaning_vi":"bao biện, làm thay toàn bộ","explanation":"包 (ôm trọn) + 办 (làm).","hsk_level":6,"tags":["dong-tu"],"image":"📋","examples":[{"type":"basic","zh":"婚姻不能包办。","pinyin":"Hūnyīn bù néng bāobàn.","vi":"Hôn nhân không thể để người khác sắp đặt thay."},{"type":"simple","zh":"妈妈包办了我从小到大的所有事情。","pinyin":"Māma bāobànle wǒ cóngxiǎo dào dà de suǒyǒu shìqing.","vi":"Mẹ đã lo liệu thay tôi mọi việc từ nhỏ đến lớn."},{"type":"compound","zh":"如果父母什么都包办，孩子就学不会独立。","pinyin":"Rúguǒ fùmǔ shénme dōu bāobàn, háizi jiù xué bú huì dúlì.","vi":"Nếu bố mẹ việc gì cũng làm thay thì con cái sẽ không học được cách tự lập."}],"related":[{"hanzi":"包揽","pinyin":"bāolǎn","vi":"ôm đồm"},{"hanzi":"代替","pinyin":"dàitì","vi":"thay thế"},{"hanzi":"包办婚姻","pinyin":"bāobànhūnyīn","vi":"hôn nhân sắp đặt"},{"hanzi":"包干","pinyin":"bāogān","vi":"khoán trọn"}],"traditional":"包辦"},{"id":"包袱","hanzi":"包袱","pinyin":"bāofu","meaning_vi":"tay nải, bọc đồ; gánh nặng (tư tưởng)","explanation":"包 (bao – gói) + 袱 (phục – tấm vải gói) → tay nải, bọc đồ; nghĩa bóng: gánh nặng tư tưởng (思想包袱, 放下包袱). Trong tấu hài, 抖包袱 = tung miếng hài.","hsk_level":6,"tags":["danh-tu"],"image":"🎒","examples":[{"type":"basic","zh":"你别有思想包袱。","pinyin":"Nǐ biéyǒu sīxiǎng bāofu.","vi":"Cậu đừng mang gánh nặng tư tưởng."},{"type":"simple","zh":"他终于卸下了心里的包袱。","pinyin":"Tā zhōngyú xièxiàle xīnli de bāofu.","vi":"Cuối cùng anh ấy đã trút bỏ được gánh nặng trong lòng."},{"type":"compound","zh":"只要放下面子的包袱，你就能大胆地开口说外语。","pinyin":"Zhǐyào fàngxià miànzi de bāofu, nǐ jiù néng dàdǎn de kāikǒu shuō wàiyǔ.","vi":"Chỉ cần trút bỏ gánh nặng sĩ diện, bạn sẽ có thể mạnh dạn mở miệng nói ngoại ngữ."}],"related":[{"hanzi":"负担","pinyin":"fùdān","vi":"gánh nặng"},{"hanzi":"压力","pinyin":"yālì","vi":"áp lực"},{"hanzi":"行李","pinyin":"xíngli","vi":"hành lý"},{"hanzi":"放下包袱","pinyin":"fàngxiàbāofu","vi":"trút bỏ gánh nặng"}]},{"id":"包罗万象","hanzi":"包罗万象","pinyin":"bāoluó-wànxiàng","meaning_vi":"bao gồm muôn hình vạn trạng, phong phú đa dạng","explanation":"包罗 (bao gồm) + 万象 (vạn vật). Thành ngữ.","hsk_level":6,"tags":["thanh-ngu"],"image":"🌐","examples":[{"type":"basic","zh":"这本百科全书包罗万象。","pinyin":"Zhè běn bǎikēquánshū bāoluówànxiàng.","vi":"Cuốn bách khoa toàn thư này bao quát đủ mọi thứ."},{"type":"simple","zh":"夜市里包罗万象的小吃让游客眼花缭乱。","pinyin":"Yèshì li bāoluówànxiàng de xiǎochī ràng yóukè yǎnhuā liáoluàn.","vi":"Các món ăn vặt muôn hình muôn vẻ ở chợ đêm khiến du khách hoa cả mắt."},{"type":"compound","zh":"这个展览不但包罗万象，而且门票免费。","pinyin":"Zhè gè zhǎnlǎn búdàn bāoluówànxiàng, érqiě ménpiào miǎnfèi.","vi":"Triển lãm này không những phong phú đa dạng mà vé vào cửa còn miễn phí."}],"related":[{"hanzi":"应有尽有","pinyin":"yīngyǒujìnyǒu","vi":"có đủ mọi thứ"},{"hanzi":"丰富多彩","pinyin":"fēngfùduōcǎi","vi":"phong phú đa dạng"},{"hanzi":"无所不包","pinyin":"wúsuǒbùbāo","vi":"bao quát tất cả"},{"hanzi":"单调","pinyin":"dāndiào","vi":"đơn điệu"}],"traditional":"包羅萬象"},{"id":"包扎","hanzi":"包扎","pinyin":"bāozā","meaning_vi":"băng bó (vết thương)","explanation":"包 + 扎 (đọc zā - buộc).","hsk_level":6,"tags":["dong-tu","suc-khoe"],"image":"🩹","examples":[{"type":"basic","zh":"护士帮他包扎伤口。","pinyin":"Hùshi bāng tā bāozā shāngkǒu.","vi":"Y tá băng bó vết thương cho anh ấy."},{"type":"simple","zh":"妈妈用纱布给我包扎了受伤的手指。","pinyin":"Māma yòng shābù gěi wǒ bāozāle shòushāng de shǒuzhǐ.","vi":"Mẹ dùng gạc băng ngón tay bị thương cho tôi."},{"type":"compound","zh":"如果伤口流血不止，就要先简单包扎再去医院。","pinyin":"Rúguǒ shāngkǒu liúxuè bùzhǐ, jiùyào xiān jiǎndān bāozā zài qù yīyuàn.","vi":"Nếu vết thương chảy máu không ngừng thì phải băng bó sơ qua rồi mới đến bệnh viện."}],"related":[{"hanzi":"绷带","pinyin":"bēngdài","vi":"băng gạc"},{"hanzi":"伤口","pinyin":"shāngkǒu","vi":"vết thương"},{"hanzi":"止血","pinyin":"zhǐxuè","vi":"cầm máu"},{"hanzi":"急救","pinyin":"jíjiù","vi":"cấp cứu"}],"traditional":"包紮"},{"id":"悲惨","hanzi":"悲惨","pinyin":"bēicǎn","meaning_vi":"bi thảm","explanation":"悲 (bi – buồn) + 惨 (thảm – thê thảm) → bi thảm, đau thương. Thường: 悲惨的遭遇, 悲惨的命运.","hsk_level":6,"tags":["tinh-tu"],"image":"😭","examples":[{"type":"basic","zh":"他的童年很悲惨。","pinyin":"Tā de tóngnián hěn bēicǎn.","vi":"Tuổi thơ của anh ấy rất bi thảm."},{"type":"simple","zh":"这部纪录片讲述了战争难民的悲惨遭遇。","pinyin":"Zhè bù jìlùpiàn jiǎngshùle zhànzhēng nànmín de bēicǎn zāoyù.","vi":"Bộ phim tài liệu này kể về cảnh ngộ bi thảm của những người tị nạn chiến tranh."},{"type":"compound","zh":"虽然她的经历十分悲惨，但是她从来没有失去希望。","pinyin":"Suīrán tā de jīnglì shífēn bēicǎn, dànshì tā cónglái méiyǒu shīqù xīwàng.","vi":"Tuy trải nghiệm của cô ấy vô cùng bi thảm nhưng cô ấy chưa bao giờ mất hy vọng."}],"related":[{"hanzi":"凄惨","pinyin":"qīcǎn","vi":"thê thảm"},{"hanzi":"悲剧","pinyin":"bēijù","vi":"bi kịch"},{"hanzi":"不幸","pinyin":"búxìng","vi":"bất hạnh"},{"hanzi":"幸福","pinyin":"xìngfú","vi":"hạnh phúc"}],"traditional":"悲慘"},{"id":"卑躬屈膝","hanzi":"卑躬屈膝","pinyin":"bēigōng-qūxī","meaning_vi":"khom lưng quỳ gối, luồn cúi nịnh bợ","explanation":"卑躬 (ti cung – khom lưng thấp) + 屈膝 (khuất tất – quỳ gối) → khom lưng quỳ gối → hèn hạ, luồn cúi nịnh bợ kẻ có quyền thế.","hsk_level":6,"tags":["thanh-ngu"],"image":"🙇","examples":[{"type":"basic","zh":"他对上司卑躬屈膝。","pinyin":"Tā duì shàngsi bēigōngqūxī.","vi":"Hắn khom lưng uốn gối trước cấp trên."},{"type":"simple","zh":"我看不惯他在老板面前卑躬屈膝的样子。","pinyin":"Wǒ kànbúguàn tā zài lǎobǎn miànqián bēigōngqūxī de yàngzi.","vi":"Tôi không chịu nổi cái vẻ luồn cúi của hắn trước mặt ông chủ."},{"type":"compound","zh":"即使生活再艰难，我们也不能卑躬屈膝地求人。","pinyin":"Jíshǐ shēnghuó zài jiānnán, wǒmen yě bù néng bēigōngqūxī de qiúrén.","vi":"Dù cuộc sống khó khăn đến đâu, chúng ta cũng không thể khúm núm cầu xin người khác."}],"related":[{"hanzi":"奴颜婢膝","pinyin":"núyánbìxī","vi":"khúm núm nịnh bợ"},{"hanzi":"阿谀奉承","pinyin":"ēyúfèngcheng","vi":"a dua nịnh hót"},{"hanzi":"不卑不亢","pinyin":"bùbēibúkàng","vi":"không tự ti không kiêu"},{"hanzi":"宁死不屈","pinyin":"nìngsǐbùqū","vi":"thà chết không khuất phục"}]},{"id":"悲欢离合","hanzi":"悲欢离合","pinyin":"bēihuān-líhé","meaning_vi":"buồn vui ly hợp (thăng trầm cuộc đời)","explanation":"悲 (bi – buồn) + 欢 (hoan – vui) + 离 (ly – chia lìa) + 合 (hợp – sum họp) → buồn vui, tan hợp → những thăng trầm của đời người (câu nổi tiếng trong bài Thủy điệu ca đầu của Tô Thức).","hsk_level":6,"tags":["thanh-ngu","cam-xuc"],"image":"🎭","examples":[{"type":"basic","zh":"人有悲欢离合。","pinyin":"Rén yǒu bēihuānlíhé.","vi":"Con người ai cũng có lúc buồn vui ly hợp."},{"type":"simple","zh":"这部小说描写了一个家族几十年的悲欢离合。","pinyin":"Zhè bù xiǎoshuō miáoxiěle yí gè jiāzú jǐ shí nián de bēihuānlíhé.","vi":"Cuốn tiểu thuyết này miêu tả những buồn vui ly hợp suốt mấy chục năm của một gia tộc."},{"type":"compound","zh":"在火车站工作久了，他就看惯了人间的悲欢离合。","pinyin":"Zài huǒchēzhàn gōngzuò jiǔ le, tā jiù kànguànle rénjiān de bēihuānlíhé.","vi":"Làm việc ở ga tàu lâu ngày, anh ấy đã quen với cảnh buồn vui ly hợp của nhân gian."}],"related":[{"hanzi":"酸甜苦辣","pinyin":"suāntiánkǔlà","vi":"chua ngọt đắng cay"},{"hanzi":"喜怒哀乐","pinyin":"xǐnù'āilè","vi":"hỉ nộ ái lạc"},{"hanzi":"人生","pinyin":"rénshēng","vi":"cuộc đời"},{"hanzi":"聚散","pinyin":"jùsàn","vi":"hợp tan"}],"traditional":"悲歡離合"},{"id":"悲天悯人","hanzi":"悲天悯人","pinyin":"bēitiān-mǐnrén","meaning_vi":"thương trời xót người, giàu lòng trắc ẩn","explanation":"悲天 (bi thiên – than trời, lo thời thế) + 悯人 (mẫn nhân – thương xót người) → lo cho thời thế, thương cảm nỗi khổ của dân → lòng trắc ẩn lớn lao.","hsk_level":6,"tags":["thanh-ngu"],"image":"💖","examples":[{"type":"basic","zh":"他有悲天悯人的情怀。","pinyin":"Tā yǒu bēitiānmǐnrén de qínghuái.","vi":"Ông ấy có tấm lòng thương đời thương người."},{"type":"simple","zh":"这位诗人的作品里处处流露出悲天悯人的情感。","pinyin":"Zhè wèi shīrén de zuòpǐn li chùchù liúlù chū bēitiānmǐnrén de qínggǎn.","vi":"Trong tác phẩm của nhà thơ này đâu đâu cũng toát lên tình cảm thương đời xót người."},{"type":"compound","zh":"他虽然出身富贵，但是一直有一颗悲天悯人的心。","pinyin":"Tā suīrán chūshēn fùguì, dànshì yìzhí yǒu yì kē bēitiānmǐnrén de xīn.","vi":"Tuy xuất thân giàu sang nhưng anh ấy luôn có tấm lòng trắc ẩn thương người."}],"related":[{"hanzi":"同情","pinyin":"tóngqíng","vi":"đồng cảm"},{"hanzi":"怜悯","pinyin":"liánmǐn","vi":"thương xót"},{"hanzi":"慈悲","pinyin":"cíbēi","vi":"từ bi"},{"hanzi":"冷漠","pinyin":"lěngmò","vi":"lạnh lùng"}],"traditional":"悲天憫人"},{"id":"悲痛","hanzi":"悲痛","pinyin":"bēitòng","meaning_vi":"đau buồn, bi thương","explanation":"悲 (buồn) + 痛 (đau xót).","hsk_level":6,"tags":["tinh-tu","cam-xuc"],"image":"😭","examples":[{"type":"basic","zh":"全家人都很悲痛。","pinyin":"Quán jiārén dōu hěn bēitòng.","vi":"Cả nhà đều rất đau buồn."},{"type":"simple","zh":"她强忍着悲痛参加了父亲的葬礼。","pinyin":"Tā qiángrěnzhe bēitòng cānjiāle fùqīn de zànglǐ.","vi":"Cô ấy cố nén đau thương dự đám tang của cha."},{"type":"compound","zh":"一听到老校长去世的消息，同学们就悲痛不已。","pinyin":"Yì tīngdào lǎo xiàozhǎng qùshì de xiāoxi, tóngxuémen jiù bēitòng bùyǐ.","vi":"Vừa nghe tin thầy hiệu trưởng cũ qua đời, các học sinh đều đau buồn khôn xiết."}],"related":[{"hanzi":"悲伤","pinyin":"bēishāng","vi":"đau buồn"},{"hanzi":"哀痛","pinyin":"āitòng","vi":"đau thương"},{"hanzi":"悲痛欲绝","pinyin":"bēitòngyùjué","vi":"đau đớn tột cùng"},{"hanzi":"喜悦","pinyin":"xǐyuè","vi":"vui mừng"}]},{"id":"卑微","hanzi":"卑微","pinyin":"bēiwēi","meaning_vi":"thấp hèn, nhỏ bé, khiêm nhường","explanation":"卑 (thấp) + 微 (nhỏ).","hsk_level":6,"tags":["tinh-tu"],"image":"🌱","examples":[{"type":"basic","zh":"他出身卑微。","pinyin":"Tā chūshēn bēiwēi.","vi":"Anh ấy xuất thân thấp hèn."},{"type":"simple","zh":"那个卑微的小职员后来成了公司总裁。","pinyin":"Nà gè bēiwēi de xiǎo zhíyuán hòulái chéngle gōngsī zǒngcái.","vi":"Anh nhân viên quèn nhỏ bé đó về sau đã trở thành tổng giám đốc công ty."},{"type":"compound","zh":"即使工作再卑微，也应该得到别人的尊重。","pinyin":"Jíshǐ gōngzuò zài bēiwēi, yě yīnggāi dédào biérén de zūnzhòng.","vi":"Dù công việc thấp kém đến đâu cũng đáng được người khác tôn trọng."}],"related":[{"hanzi":"低微","pinyin":"dīwēi","vi":"thấp kém"},{"hanzi":"渺小","pinyin":"miǎoxiǎo","vi":"nhỏ bé"},{"hanzi":"卑贱","pinyin":"bēijiàn","vi":"hèn mọn"},{"hanzi":"高贵","pinyin":"gāoguì","vi":"cao quý"}]},{"id":"奔赴","hanzi":"奔赴","pinyin":"bēnfù","meaning_vi":"lao tới, lên đường tới (tiền tuyến/nơi công tác)","explanation":"奔 (chạy nhanh) + 赴 (đi tới).","hsk_level":6,"tags":["dong-tu"],"image":"🏃","examples":[{"type":"basic","zh":"医生们奔赴灾区。","pinyin":"Yīshēngmen bēnfù zāiqū.","vi":"Các bác sĩ lên đường tới vùng thiên tai."},{"type":"simple","zh":"大学毕业后，她奔赴西部山区支教。","pinyin":"Dàxué bìyè hòu, tā bēnfù Xībù shānqū zhījiào.","vi":"Sau khi tốt nghiệp đại học, cô ấy lên đường tới vùng núi miền Tây dạy học tình nguyện."},{"type":"compound","zh":"地震发生后，救援队一接到命令就奔赴现场。","pinyin":"Dìzhèn fāshēng hòu, jiùyuánduì yì jiēdào mìnglìng jiù bēnfù xiànchǎng.","vi":"Sau khi động đất xảy ra, đội cứu hộ vừa nhận lệnh đã lao tới hiện trường."}],"related":[{"hanzi":"赶赴","pinyin":"gǎnfù","vi":"vội đến"},{"hanzi":"前往","pinyin":"qiánwǎng","vi":"đi tới"},{"hanzi":"奔向","pinyin":"bēnxiàng","vi":"lao về phía"},{"hanzi":"奔赴前线","pinyin":"bēnfùqiánxiàn","vi":"lên đường ra tiền tuyến"}]},{"id":"奔腾","hanzi":"奔腾","pinyin":"bēnténg","meaning_vi":"phi nước đại; cuồn cuộn chảy (sông nước)","explanation":"奔 (chạy) + 腾 (nhảy vọt).","hsk_level":6,"tags":["dong-tu","thien-nhien"],"image":"🌊","examples":[{"type":"basic","zh":"黄河奔腾不息。","pinyin":"Huánghé bēnténg bùxī.","vi":"Hoàng Hà cuồn cuộn chảy không ngừng."},{"type":"simple","zh":"一群野马在辽阔的草原上奔腾。","pinyin":"Yìqún yěmǎ zài liáokuò de cǎoyuán shang bēnténg.","vi":"Một đàn ngựa hoang phi nước đại trên thảo nguyên bao la."},{"type":"compound","zh":"每到雨季，山下的江水就变得汹涌奔腾。","pinyin":"Měi dào yǔjì, Shānxià de jiāngshuǐ jiù biànde xiōngyǒng bēnténg.","vi":"Cứ đến mùa mưa, nước sông dưới núi lại cuồn cuộn dữ dội."}],"related":[{"hanzi":"奔流","pinyin":"bēnliú","vi":"chảy xiết"},{"hanzi":"汹涌","pinyin":"xiōngyǒng","vi":"cuồn cuộn"},{"hanzi":"万马奔腾","pinyin":"wànmǎbēnténg","vi":"vạn ngựa phi"},{"hanzi":"奔跑","pinyin":"bēnpǎo","vi":"chạy nhanh"}],"traditional":"奔騰"},{"id":"北半球","hanzi":"北半球","pinyin":"Běibànqiú","meaning_vi":"bán cầu Bắc","explanation":"北 + 半球 (nửa quả cầu).","hsk_level":6,"tags":["danh-tu","khoa-hoc","dia-danh"],"image":"🌍","examples":[{"type":"basic","zh":"中国位于北半球。","pinyin":"Zhōngguó wèiyú Běibànqiú.","vi":"Trung Quốc nằm ở bán cầu Bắc."},{"type":"simple","zh":"候鸟每年秋天从北半球飞往南方过冬。","pinyin":"Hòuniǎo měinián qiūtiān cóng Běibànqiú fēiwǎng nánfāng guòdōng.","vi":"Mỗi mùa thu, chim di cư bay từ bán cầu Bắc xuống phương nam tránh rét."},{"type":"compound","zh":"当北半球进入夏天时，南半球却正好是冬天。","pinyin":"Dāng Běibànqiú jìnrù xiàtiān shí, Nánbànqiú què zhènghǎo shì dōngtiān.","vi":"Khi bán cầu Bắc vào hè thì bán cầu Nam lại đúng vào mùa đông."}],"related":[{"hanzi":"南半球","pinyin":"Nánbànqiú","vi":"bán cầu Nam"},{"hanzi":"赤道","pinyin":"Chìdào","vi":"xích đạo"},{"hanzi":"地球","pinyin":"dìqiú","vi":"trái đất"},{"hanzi":"北极","pinyin":"Běijí","vi":"Bắc Cực"}]},{"id":"北纬","hanzi":"北纬","pinyin":"Běiwěi","meaning_vi":"vĩ độ Bắc","explanation":"北 (phương Bắc) + 纬 (vĩ tuyến).","hsk_level":6,"tags":["danh-tu","khoa-hoc","dia-danh"],"image":"🌐","examples":[{"type":"basic","zh":"这里是北纬三十度。","pinyin":"Zhèli shì Běiwěi sānshí dù.","vi":"Đây là vĩ độ ba mươi Bắc."},{"type":"simple","zh":"地图上标出了北纬十八度的位置。","pinyin":"Dìtú shangbiāo chūle Běiwěi shí bādù de wèizhì.","vi":"Trên bản đồ đã đánh dấu vị trí vĩ độ mười tám Bắc."},{"type":"compound","zh":"因为这里位于北纬五十度以北，所以冬天特别漫长。","pinyin":"Yīnwèi zhèli wèiyú Běiwěi wǔshí dù yǐběi, suǒyǐ dōngtiān tèbié màncháng.","vi":"Vì nơi này nằm ở phía bắc vĩ tuyến năm mươi độ Bắc nên mùa đông đặc biệt dài."}],"related":[{"hanzi":"南纬","pinyin":"nánwěi","vi":"vĩ độ Nam"},{"hanzi":"纬度","pinyin":"Wěidù","vi":"vĩ độ"},{"hanzi":"经度","pinyin":"Jīngdù","vi":"kinh độ"},{"hanzi":"赤道","pinyin":"Chìdào","vi":"xích đạo"}],"traditional":"北緯"},{"id":"本末倒置","hanzi":"本末倒置","pinyin":"běnmò-dàozhì","meaning_vi":"đảo lộn gốc ngọn, lộn ngược thứ tự chính phụ","explanation":"本末 (gốc ngọn) + 倒置 (đặt ngược). Thành ngữ.","hsk_level":6,"tags":["thanh-ngu"],"image":"🙃","examples":[{"type":"basic","zh":"这样做本末倒置。","pinyin":"Zhèyàng zuò běnmòdàozhì.","vi":"Làm như vậy là đảo lộn gốc ngọn."},{"type":"simple","zh":"为了拍照而忘了欣赏风景实在是本末倒置。","pinyin":"Wèile pāizhào ér wàngle xīnshǎng fēngjǐng shízài shì běnmòdàozhì.","vi":"Vì mải chụp ảnh mà quên ngắm cảnh thật là đảo lộn gốc ngọn."},{"type":"compound","zh":"如果只追求分数而忽视能力培养，就是本末倒置。","pinyin":"Rúguǒ zhǐ zhuīqiú fēnshù ér hūshì nénglì péiyǎng, jiùshì běnmòdàozhì.","vi":"Nếu chỉ chạy theo điểm số mà xem nhẹ việc bồi dưỡng năng lực thì chính là đảo lộn gốc ngọn."}],"related":[{"hanzi":"舍本逐末","pinyin":"shěběnzhúmò","vi":"bỏ gốc theo ngọn"},{"hanzi":"轻重倒置","pinyin":"qīngzhòngdàozhì","vi":"đảo lộn nặng nhẹ"},{"hanzi":"主次","pinyin":"zhǔcì","vi":"chính phụ"},{"hanzi":"颠倒","pinyin":"diāndǎo","vi":"đảo lộn"}]},{"id":"本能","hanzi":"本能","pinyin":"běnnéng","meaning_vi":"bản năng","explanation":"本 (bản – gốc) + 能 (năng – khả năng) → khả năng vốn có từ khi sinh ra, bản năng. Ví dụ: 求生本能; 本能地 + động từ = theo phản xạ.","hsk_level":6,"tags":["danh-tu"],"image":"🧠","examples":[{"type":"basic","zh":"吃奶是婴儿的本能。","pinyin":"Chīnǎi shì yīng'ér de běnnéng.","vi":"Bú sữa là bản năng của trẻ sơ sinh."},{"type":"simple","zh":"他本能地伸手接住了掉下来的杯子。","pinyin":"Tā běnnéng de shēnshǒu jiēzhùle diào xiàlái de bēizi.","vi":"Anh ấy theo bản năng đưa tay đỡ lấy chiếc cốc rơi xuống."},{"type":"compound","zh":"一遇到危险，动物就会本能地保护自己的孩子。","pinyin":"Yí yùdào wēixiǎn, dòngwù jiù huì běnnéng de bǎohù zìjǐ de háizi.","vi":"Vừa gặp nguy hiểm, động vật sẽ theo bản năng bảo vệ con của mình."}],"related":[{"hanzi":"天性","pinyin":"tiānxìng","vi":"thiên tính"},{"hanzi":"本性","pinyin":"běnxìng","vi":"bản tính"},{"hanzi":"本能反应","pinyin":"běnnéngfǎnyìng","vi":"phản ứng bản năng"},{"hanzi":"直觉","pinyin":"zhíjué","vi":"trực giác"}]},{"id":"本身","hanzi":"本身","pinyin":"běnshēn","meaning_vi":"bản thân","explanation":"本 (bản – chính) + 身 (thân – thân mình) → bản thân, tự thân (của người hoặc sự vật). Ví dụ: 问题本身并不难 (bản thân vấn đề không khó).","hsk_level":6,"tags":["dai-tu"],"image":"👤","examples":[{"type":"basic","zh":"问题本身不难。","pinyin":"Wèntí běnshēn bùnán.","vi":"Bản thân vấn đề không khó."},{"type":"simple","zh":"旅行本身就是一种很好的学习。","pinyin":"Lǚxíng běnshēn jiùshì yì zhǒng hěn hǎo de xuéxí.","vi":"Bản thân việc đi du lịch đã là một cách học rất tốt."},{"type":"compound","zh":"虽然这款手机本身很便宜，但是配件都特别贵。","pinyin":"Suīrán zhè kuǎn shǒujī běnshēn hěn piányi, dànshì pèijiàn dōu tèbié guì.","vi":"Tuy bản thân chiếc điện thoại này rẻ nhưng phụ kiện thì đều rất đắt."}],"related":[{"hanzi":"自身","pinyin":"zìshēn","vi":"bản thân"},{"hanzi":"本人","pinyin":"běnrén","vi":"bản thân tôi"},{"hanzi":"自己","pinyin":"zìjǐ","vi":"tự mình"},{"hanzi":"事物本身","pinyin":"shìwùběnshēn","vi":"bản thân sự vật"}]},{"id":"本性","hanzi":"本性","pinyin":"běnxìng","meaning_vi":"bản tính","explanation":"本 (gốc) + 性 (tính chất).","hsk_level":6,"tags":["danh-tu","con-nguoi"],"image":"🧠","examples":[{"type":"basic","zh":"他本性善良。","pinyin":"Tā běnxìng shànliáng.","vi":"Bản tính anh ấy lương thiện."},{"type":"simple","zh":"那次危机暴露了他自私的本性。","pinyin":"Nà cì wēijī bàolùle tā zìsī de běnxìng.","vi":"Cuộc khủng hoảng lần đó đã bộc lộ bản tính ích kỷ của hắn."},{"type":"compound","zh":"即使环境变了，一个人的本性也很难改变。","pinyin":"Jíshǐ huánjìng biàn le, yígèrén de běnxìng yě hěn nán gǎibiàn.","vi":"Dù hoàn cảnh thay đổi, bản tính của một người cũng khó mà thay đổi."}],"related":[{"hanzi":"天性","pinyin":"tiānxìng","vi":"thiên tính"},{"hanzi":"本质","pinyin":"běnzhì","vi":"bản chất"},{"hanzi":"个性","pinyin":"gèxìng","vi":"cá tính"},{"hanzi":"江山易改本性难移","pinyin":"jiāngshān yì gǎi běnxìng nán yí","vi":"giang sơn dễ đổi bản tính khó dời"}]},{"id":"逼迫","hanzi":"逼迫","pinyin":"bīpò","meaning_vi":"bức bách, ép buộc","explanation":"逼 (ép) + 迫 (thúc ép).","hsk_level":6,"tags":["dong-tu"],"image":"😤","examples":[{"type":"basic","zh":"没人逼迫你。","pinyin":"Méi rén bīpò nǐ.","vi":"Không ai ép buộc cậu."},{"type":"simple","zh":"那个公司逼迫员工签了不合理的合同。","pinyin":"Nà gè gōngsī bīpò yuán gōngqiānle bù hélǐ de hétong.","vi":"Công ty đó ép nhân viên ký hợp đồng bất hợp lý."},{"type":"compound","zh":"父母如果总是逼迫孩子学钢琴，孩子就可能会讨厌音乐。","pinyin":"Fùmǔ rúguǒ zǒngshì bīpò háizi xué gāngqín, háizi jiù kěnéng huì tǎoyàn yīnyuè.","vi":"Nếu bố mẹ cứ ép con học piano thì con có thể sẽ ghét âm nhạc."}],"related":[{"hanzi":"强迫","pinyin":"qiǎngpò","vi":"cưỡng ép"},{"hanzi":"迫使","pinyin":"pòshǐ","vi":"buộc phải"},{"hanzi":"威逼","pinyin":"wēibī","vi":"uy hiếp"},{"hanzi":"自愿","pinyin":"zìyuàn","vi":"tự nguyện"}]},{"id":"逼真","hanzi":"逼真","pinyin":"bīzhēn","meaning_vi":"sống động như thật (tranh vẽ/diễn xuất)","explanation":"逼 (sát gần) + 真 (thật).","hsk_level":6,"tags":["tinh-tu","giai-tri"],"image":"🎨","examples":[{"type":"basic","zh":"这幅画很逼真。","pinyin":"Zhè fú huà hěn bīzhēn.","vi":"Bức tranh này sống động như thật."},{"type":"simple","zh":"演员把一个盲人演得非常逼真。","pinyin":"Yǎnyuán bǎ yí gè mángrén yǎn de fēicháng bīzhēn.","vi":"Diễn viên đóng vai một người mù vô cùng chân thực."},{"type":"compound","zh":"因为这些塑料水果做得很逼真，所以弟弟想咬一口。","pinyin":"Yīnwèi zhèxiē sùliào shuǐguǒ zuò de hěn bīzhēn, suǒyǐ dìdi xiǎng yǎo yìkǒu.","vi":"Vì những quả nhựa này làm rất giống thật nên em trai muốn cắn một miếng."}],"related":[{"hanzi":"栩栩如生","pinyin":"xǔxǔrúshēng","vi":"sống động như thật"},{"hanzi":"生动","pinyin":"shēngdòng","vi":"sinh động"},{"hanzi":"真实","pinyin":"zhēnshí","vi":"chân thực"},{"hanzi":"传神","pinyin":"chuánshén","vi":"có hồn"}]},{"id":"濒临","hanzi":"濒临","pinyin":"bīnlín","meaning_vi":"đứng bên bờ vực","explanation":"濒 (tần – ven bờ, kề sát) + 临 (lâm – tới gần) → kề sát, sắp lâm vào. Thường: 濒临灭绝 (sắp tuyệt chủng), 濒临破产; cũng chỉ vị trí giáp biển.","hsk_level":6,"tags":["dong-tu"],"image":"⚠️","examples":[{"type":"basic","zh":"这种鸟濒临灭绝。","pinyin":"Zhè zhǒng niǎo bīnlín mièjué.","vi":"Loài chim này đang đứng bên bờ tuyệt chủng."},{"type":"simple","zh":"疫情期间，许多小餐馆濒临倒闭。","pinyin":"Yìqíng qījiān, xǔduō xiǎo cānguǎn bīnlín dǎobì.","vi":"Trong thời gian dịch bệnh, nhiều quán ăn nhỏ đứng bên bờ vực đóng cửa."},{"type":"compound","zh":"如果不采取保护措施，这片湿地就会濒临消失。","pinyin":"Rúguǒ bù cǎiqǔ bǎohù cuòshī, zhè piàn shīdì jiù huì bīnlín xiāoshī.","vi":"Nếu không có biện pháp bảo vệ thì vùng đất ngập nước này sẽ đứng trước nguy cơ biến mất."}],"related":[{"hanzi":"面临","pinyin":"miànlín","vi":"đối mặt"},{"hanzi":"濒危","pinyin":"bīnwēi","vi":"có nguy cơ tuyệt chủng"},{"hanzi":"接近","pinyin":"jiējìn","vi":"tiếp cận"},{"hanzi":"濒临破产","pinyin":"bīnlínpòchǎn","vi":"bên bờ phá sản"}],"traditional":"瀕臨"},{"id":"宾至如归","hanzi":"宾至如归","pinyin":"bīnzhì-rúguī","meaning_vi":"khách đến như về nhà","explanation":"宾 (tân – khách) + 至 (chí – đến) + 如 (như) + 归 (quy – về nhà) → khách đến như về nhà mình (gốc Tả truyện) → chủ nhà, khách sạn tiếp đãi chu đáo, ấm cúng.","hsk_level":6,"tags":["thanh-ngu","du-lich"],"image":"🏨","examples":[{"type":"basic","zh":"我们力求宾至如归。","pinyin":"Wǒmen lìqiú bīnzhìrúguī.","vi":"Chúng tôi cố gắng để khách đến như về nhà."},{"type":"simple","zh":"民宿主人的热情招待让我们有宾至如归的感觉。","pinyin":"Mínsù zhǔrén de rèqíng zhāodài ràng wǒmen yǒu bīnzhìrúguī de gǎnjué.","vi":"Sự tiếp đón nhiệt tình của chủ homestay khiến chúng tôi có cảm giác như ở nhà."},{"type":"compound","zh":"这家酒店不但设施齐全，而且服务让人宾至如归。","pinyin":"Zhè jiā jiǔdiàn búdàn shèshī qíquán, érqiě fúwù ràng rén bīnzhìrúguī.","vi":"Khách sạn này không những tiện nghi đầy đủ mà dịch vụ còn khiến khách thấy như ở nhà."}],"related":[{"hanzi":"热情好客","pinyin":"rèqínghàokè","vi":"hiếu khách"},{"hanzi":"宾馆","pinyin":"bīnguǎn","vi":"khách sạn"},{"hanzi":"周到","pinyin":"zhōudào","vi":"chu đáo"},{"hanzi":"款待","pinyin":"kuǎndài","vi":"tiếp đãi"}],"traditional":"賓至如歸"},{"id":"兵荒马乱","hanzi":"兵荒马乱","pinyin":"bīnghuāng-mǎluàn","meaning_vi":"binh hoang mã loạn (cảnh chiến tranh loạn lạc)","explanation":"兵 (binh – quân lính) + 荒 (hoang – hỗn loạn) + 马 (mã – ngựa) + 乱 (loạn) → binh lính rối ren, ngựa xe hỗn loạn → cảnh xã hội bất ổn thời chiến tranh.","hsk_level":6,"tags":["thanh-ngu"],"image":"⚔️","examples":[{"type":"basic","zh":"那是兵荒马乱的年代。","pinyin":"Nàshì bīnghuāngmǎluàn de niándài.","vi":"Đó là thời buổi binh đao loạn lạc."},{"type":"simple","zh":"爷爷在兵荒马乱中失去了所有家人。","pinyin":"Yéye zài bīnghuāngmǎluàn zhōng shīqùle suǒyǒu jiārén.","vi":"Ông nội đã mất hết người thân trong cảnh loạn lạc chiến tranh."},{"type":"compound","zh":"虽然那时候兵荒马乱，但是奶奶还是坚持读完了书。","pinyin":"Suīrán nàshíhou bīnghuāngmǎluàn, dànshì nǎinai háishi jiānchí dú wánle shū.","vi":"Tuy thời đó binh đao loạn lạc nhưng bà vẫn kiên trì học hết."}],"related":[{"hanzi":"战乱","pinyin":"zhànluàn","vi":"loạn lạc chiến tranh"},{"hanzi":"动荡不安","pinyin":"dòngdàngbù'ān","vi":"bất ổn"},{"hanzi":"天下太平","pinyin":"tiānxiàtàipíng","vi":"thiên hạ thái bình"},{"hanzi":"战争","pinyin":"zhànzhēng","vi":"chiến tranh"}],"traditional":"兵荒馬亂"},{"id":"冰清玉洁","hanzi":"冰清玉洁","pinyin":"bīngqīng-yùjié","meaning_vi":"trong trắng tinh khiết như băng ngọc","explanation":"冰清 (băng thanh – trong như băng) + 玉洁 (ngọc khiết – sạch như ngọc) → trong như băng, sạch như ngọc → phẩm chất trong sạch, cao quý; thường khen người con gái.","hsk_level":6,"tags":["thanh-ngu"],"image":"💎","examples":[{"type":"basic","zh":"她为人冰清玉洁。","pinyin":"Tā wéirén bīngqīngyùjié.","vi":"Cô ấy sống trong sạch thanh khiết."},{"type":"simple","zh":"古人常用荷花比喻冰清玉洁的品格。","pinyin":"Gǔrén chángyòng héhuā bǐyù bīngqīngyùjié de pǐngé.","vi":"Người xưa thường dùng hoa sen để ví với phẩm cách trong sạch thanh cao."},{"type":"compound","zh":"她虽然身处娱乐圈，但是始终保持着冰清玉洁的形象。","pinyin":"Tā suīrán shēnchǔ yúlèquān, dànshì shǐzhōng bǎochízhe bīngqīngyùjié de xíngxiàng.","vi":"Tuy ở trong giới giải trí nhưng cô ấy luôn giữ được hình ảnh trong sáng thanh khiết."}],"related":[{"hanzi":"纯洁","pinyin":"chúnjié","vi":"trong sạch"},{"hanzi":"清白","pinyin":"qīngbái","vi":"trong sạch"},{"hanzi":"高洁","pinyin":"gāojié","vi":"thanh cao"},{"hanzi":"污浊","pinyin":"wūzhuó","vi":"dơ bẩn"}],"traditional":"冰清玉潔"},{"id":"冰山一角","hanzi":"冰山一角","pinyin":"bīngshān-yìjiǎo","meaning_vi":"tảng băng trôi (phần nhỏ lộ ra ngoài)","explanation":"冰山一角: một góc của núi băng → phần nhỏ lộ ra, còn phần lớn sự thật (thường là vấn đề xấu) vẫn ẩn giấu. Ví dụ: 这只是冰山一角.","hsk_level":6,"tags":["thanh-ngu"],"image":"🧊","examples":[{"type":"basic","zh":"这只是冰山一角。","pinyin":"Zhè zhǐshì bīngshānyìjiǎo.","vi":"Đây chỉ là phần nổi của tảng băng."},{"type":"simple","zh":"媒体报道的案件只是食品安全问题的冰山一角。","pinyin":"Méitǐ bàodào de ànjiàn zhǐshì shípǐn ānquán wèntí de bīngshānyìjiǎo.","vi":"Những vụ án báo chí đưa tin chỉ là phần nổi của tảng băng vấn đề an toàn thực phẩm."},{"type":"compound","zh":"如果深入调查下去，就会发现这些只是冰山一角。","pinyin":"Rúguǒ shēnrù diàochá xiàqù, jiù huì fāxiàn zhèxiē zhǐshì bīngshānyìjiǎo.","vi":"Nếu tiếp tục điều tra sâu thì sẽ phát hiện những điều này chỉ là phần nổi của tảng băng."}],"related":[{"hanzi":"冰山","pinyin":"bīngshān","vi":"núi băng"},{"hanzi":"一部分","pinyin":"yíbùfen","vi":"một phần"},{"hanzi":"表面","pinyin":"biǎomiàn","vi":"bề mặt"},{"hanzi":"全貌","pinyin":"quánmào","vi":"toàn cảnh"}]},{"id":"拨打","hanzi":"拨打","pinyin":"bōdǎ","meaning_vi":"quay số gọi điện","explanation":"拨 (gạt/quay số) + 打 (gọi).","hsk_level":6,"tags":["dong-tu","cong-nghe"],"image":"📞","examples":[{"type":"basic","zh":"请拨打急救电话。","pinyin":"Qǐng bōdǎ jíjiù diànhuà.","vi":"Hãy gọi số điện thoại cấp cứu."},{"type":"simple","zh":"您拨打的电话暂时无人接听。","pinyin":"Nín bōdǎ de diànhuà zànshí wúrén jiētīng.","vi":"Số máy quý khách vừa gọi tạm thời không có người nghe."},{"type":"compound","zh":"如果对产品有任何疑问，就请拨打客服热线。","pinyin":"Rúguǒ duì chǎnpǐn yǒu rènhé yíwèn, jiù qǐng bōdǎ kèfú rèxiàn.","vi":"Nếu có bất kỳ thắc mắc nào về sản phẩm, xin vui lòng gọi đường dây nóng chăm sóc khách hàng."}],"related":[{"hanzi":"打电话","pinyin":"dǎdiànhuà","vi":"gọi điện"},{"hanzi":"拨号","pinyin":"bōhào","vi":"quay số"},{"hanzi":"号码","pinyin":"hàomǎ","vi":"số điện thoại"},{"hanzi":"接听","pinyin":"jiētīng","vi":"nghe máy"}],"traditional":"撥打"},{"id":"拨款","hanzi":"拨款","pinyin":"bōkuǎn","meaning_vi":"cấp kinh phí, giải ngân","explanation":"拨 + 款 (tiền). Động từ ly hợp.","hsk_level":6,"tags":["dong-tu","tien-te"],"image":"💰","examples":[{"type":"basic","zh":"政府拨款修路。","pinyin":"Zhèngfǔ bōkuǎn xiūlù.","vi":"Chính phủ cấp kinh phí làm đường."},{"type":"simple","zh":"学校今年拨款五十万元更新实验设备。","pinyin":"Xuéxiào jīnnián bōkuǎn wǔ shíwàn yuán gēngxīn shíyàn shèbèi.","vi":"Năm nay nhà trường cấp năm trăm nghìn tệ để đổi mới thiết bị thí nghiệm."},{"type":"compound","zh":"只要上级的拨款到位，新图书馆就能马上开工。","pinyin":"Zhǐyào shàngjí de bōkuǎn dàowèi, xīn túshūguǎn jiù néng mǎshàng kāigōng.","vi":"Chỉ cần kinh phí cấp trên rót về, thư viện mới có thể khởi công ngay."}],"related":[{"hanzi":"经费","pinyin":"jīngfèi","vi":"kinh phí"},{"hanzi":"资金","pinyin":"zījīn","vi":"tiền vốn"},{"hanzi":"财政","pinyin":"cáizhèng","vi":"tài chính"},{"hanzi":"预算","pinyin":"yùsuàn","vi":"ngân sách"}],"traditional":"撥款"},{"id":"波澜壮阔","hanzi":"波澜壮阔","pinyin":"bōlán-zhuàngkuò","meaning_vi":"sóng gió hùng vĩ, quy mô hoành tráng","explanation":"波澜 (ba lan – sóng lớn) + 壮阔 (tráng khoát – hùng vĩ, rộng lớn) → sóng nước mênh mông hùng vĩ → ví phong trào, sự kiện, văn chương có quy mô và khí thế lớn.","hsk_level":6,"tags":["thanh-ngu"],"image":"🌊","examples":[{"type":"basic","zh":"大海波澜壮阔。","pinyin":"Dàhǎi bōlánzhuàngkuò.","vi":"Biển cả sóng gió hùng vĩ."},{"type":"simple","zh":"这部电影再现了那段波澜壮阔的历史。","pinyin":"Zhè bù diànyǐng zàixiànle nà duàn bōlánzhuàngkuò de lìshǐ.","vi":"Bộ phim này tái hiện giai đoạn lịch sử hào hùng tráng lệ đó."},{"type":"compound","zh":"他的一生虽然短暂，但是波澜壮阔。","pinyin":"Tā de yìshēng suīrán duǎnzàn, dànshì bōlánzhuàngkuò.","vi":"Cuộc đời ông tuy ngắn ngủi nhưng đầy sóng gió hào hùng."}],"related":[{"hanzi":"气势磅礴","pinyin":"qìshìpángbó","vi":"khí thế hùng vĩ"},{"hanzi":"宏伟","pinyin":"hóngwěi","vi":"to lớn"},{"hanzi":"壮观","pinyin":"zhuàngguān","vi":"hùng vĩ"},{"hanzi":"波澜","pinyin":"bōlán","vi":"sóng lớn"}],"traditional":"波瀾壯闊"},{"id":"波涛","hanzi":"波涛","pinyin":"bōtāo","meaning_vi":"sóng lớn","explanation":"波 (ba – sóng) + 涛 (đào – sóng lớn) → sóng lớn, sóng cả. Thường: 波涛汹涌 (sóng cả cuồn cuộn).","hsk_level":6,"tags":["danh-tu","thien-nhien"],"image":"🌊","examples":[{"type":"basic","zh":"海上波涛汹涌。","pinyin":"Hǎishàng bōtāo xiōngyǒng.","vi":"Trên biển sóng to dữ dội."},{"type":"simple","zh":"小船在波涛中剧烈地摇晃着。","pinyin":"Xiǎochuán zài bōtāo zhōng jùliè de yáohuàng zhe.","vi":"Con thuyền nhỏ chòng chành dữ dội giữa những con sóng lớn."},{"type":"compound","zh":"一刮起台风，海面上就掀起了巨大的波涛。","pinyin":"Yì guā qǐ táifēng, hǎimiàn shang jiù xiānqǐle jùdà de bōtāo.","vi":"Bão vừa nổi lên, mặt biển liền dậy lên những con sóng khổng lồ."}],"related":[{"hanzi":"波浪","pinyin":"bōlàng","vi":"sóng"},{"hanzi":"浪花","pinyin":"lànghuā","vi":"bọt sóng"},{"hanzi":"波涛汹涌","pinyin":"bōtāoxiōngyǒng","vi":"sóng cuộn dữ dội"},{"hanzi":"海洋","pinyin":"hǎiyáng","vi":"đại dương"}],"traditional":"波濤"},{"id":"播音","hanzi":"播音","pinyin":"bōyīn","meaning_vi":"phát thanh, đọc bản tin","explanation":"播 (phát) + 音 (âm thanh). Cụm: 播音员 (phát thanh viên).","hsk_level":6,"tags":["dong-tu","nghe-nghiep"],"image":"🎙️","examples":[{"type":"basic","zh":"他在电台播音。","pinyin":"Tā zài diàntái bōyīn.","vi":"Anh ấy làm phát thanh ở đài."},{"type":"simple","zh":"她从小的梦想就是当一名播音员。","pinyin":"Tā cóngxiǎo de mèngxiǎng jiùshì dāng yì míng bōyīnyuán.","vi":"Ước mơ từ nhỏ của cô ấy là trở thành phát thanh viên."},{"type":"compound","zh":"因为他的声音很有磁性，所以台里请他来播音。","pinyin":"Yīnwèi tā de shēngyīn hěn yǒu cíxìng, suǒyǐ tái li qǐng tā lái bōyīn.","vi":"Vì giọng anh ấy rất truyền cảm nên đài mời anh ấy đến đọc bản tin."}],"related":[{"hanzi":"播音员","pinyin":"bōyīnyuán","vi":"phát thanh viên"},{"hanzi":"广播","pinyin":"guǎngbō","vi":"phát thanh"},{"hanzi":"主持人","pinyin":"zhǔchírén","vi":"người dẫn chương trình"},{"hanzi":"电台","pinyin":"diàntái","vi":"đài phát thanh"}]},{"id":"波折","hanzi":"波折","pinyin":"bōzhé","meaning_vi":"sóng gió, trắc trở","explanation":"波 (sóng) + 折 (gãy/uốn).","hsk_level":6,"tags":["danh-tu"],"image":"🌊","examples":[{"type":"basic","zh":"事情有了波折。","pinyin":"Shìqing yǒule bōzhé.","vi":"Sự việc đã gặp trắc trở."},{"type":"simple","zh":"他们的婚事经历了不少波折。","pinyin":"Tāmen de hūnshì jīnglìle bùshǎo bōzhé.","vi":"Chuyện hôn nhân của họ đã trải qua không ít trắc trở."},{"type":"compound","zh":"虽然项目中间出了一些波折，但是最后还是顺利完成了。","pinyin":"Suīrán xiàngmù zhōngjiān chūle yìxiē bōzhé, dànshì zuìhòu háishi shùnlì wánchéng le.","vi":"Tuy dự án giữa chừng gặp một số trắc trở nhưng cuối cùng vẫn hoàn thành suôn sẻ."}],"related":[{"hanzi":"曲折","pinyin":"qūzhé","vi":"quanh co trắc trở"},{"hanzi":"挫折","pinyin":"cuòzhé","vi":"thất bại"},{"hanzi":"风波","pinyin":"fēngbō","vi":"sóng gió"},{"hanzi":"一帆风顺","pinyin":"yìfānfēngshùn","vi":"thuận buồm xuôi gió"}]},{"id":"把柄","hanzi":"把柄","pinyin":"bǎbǐng","meaning_vi":"điểm yếu bị nắm thóp; tay cầm, cán","explanation":"把 (nắm) + 柄 (chuôi/cán).","hsk_level":6,"tags":["danh-tu"],"image":"🔍","examples":[{"type":"basic","zh":"他被抓住了把柄。","pinyin":"Tā bèi zhuāzhùle bǎbǐng.","vi":"Anh ta bị nắm thóp."},{"type":"simple","zh":"那个记者手里握着市长受贿的把柄。","pinyin":"Nà gè jìzhě shǒuli wòzhe shìzhǎng shòuhuì de bǎbǐng.","vi":"Nhà báo đó nắm trong tay bằng chứng thị trưởng nhận hối lộ."},{"type":"compound","zh":"如果你做事不小心，就容易给别人留下把柄。","pinyin":"Rúguǒ nǐ zuòshì bù xiǎoxīn, jiù róngyì gěi biérén liúxià bǎbǐng.","vi":"Nếu làm việc không cẩn thận thì dễ để lại điểm yếu cho người khác nắm."}],"related":[{"hanzi":"弱点","pinyin":"ruòdiǎn","vi":"điểm yếu"},{"hanzi":"抓把柄","pinyin":"zhuābǎbǐng","vi":"nắm thóp"},{"hanzi":"漏洞","pinyin":"lòudòng","vi":"sơ hở"},{"hanzi":"证据","pinyin":"zhèngjù","vi":"chứng cứ"}]},{"id":"把戏","hanzi":"把戏","pinyin":"bǎxì","meaning_vi":"trò xiếc, trò ảo thuật; mánh khóe, trò lừa","explanation":"把 + 戏 (trò diễn).","hsk_level":6,"tags":["danh-tu","giai-tri"],"image":"🎭","examples":[{"type":"basic","zh":"别耍把戏了！","pinyin":"Bié shuǎ bǎxì le!","vi":"Đừng giở trò nữa!"},{"type":"simple","zh":"街头艺人表演了几个有趣的小把戏。","pinyin":"Jiētóu yìrén biǎoyǎnle jǐ gè yǒuqù de xiǎo bǎxì.","vi":"Nghệ sĩ đường phố biểu diễn vài trò ảo thuật nhỏ thú vị."},{"type":"compound","zh":"骗子的这些把戏虽然很老套，但是还是有人上当。","pinyin":"Piànzi de zhèxiē bǎxì suīrán hěn lǎotào, dànshì háishi yǒurén shàngdàng.","vi":"Những mánh khóe của kẻ lừa đảo tuy rất cũ nhưng vẫn có người mắc bẫy."}],"related":[{"hanzi":"花招","pinyin":"huāzhāo","vi":"mánh khóe"},{"hanzi":"伎俩","pinyin":"jìliǎng","vi":"thủ đoạn"},{"hanzi":"骗局","pinyin":"piànjú","vi":"trò lừa"},{"hanzi":"魔术","pinyin":"móshù","vi":"ảo thuật"}],"traditional":"把戲"},{"id":"百般","hanzi":"百般","pinyin":"bǎibān","meaning_vi":"trăm phương nghìn kế, hết mực","explanation":"百 (trăm) + 般 (cách/loại).","hsk_level":6,"tags":["pho-tu"],"image":"🔄","examples":[{"type":"basic","zh":"他百般讨好她。","pinyin":"Tā bǎibān tǎohǎo tā.","vi":"Anh ấy tìm mọi cách lấy lòng cô ấy."},{"type":"simple","zh":"奶奶对刚出生的孙子百般疼爱。","pinyin":"Nǎinai duì gāng chūshēng de sūnzi bǎibān téng'ài.","vi":"Bà hết mực yêu thương đứa cháu vừa chào đời."},{"type":"compound","zh":"虽然我们百般劝说，但是他还是坚持辞职。","pinyin":"Suīrán wǒmen bǎibān quànshuō, dànshì tā háishi jiānchí cízhí.","vi":"Tuy chúng tôi tìm đủ mọi cách khuyên nhủ nhưng anh ấy vẫn kiên quyết nghỉ việc."}],"related":[{"hanzi":"千方百计","pinyin":"qiānfāngbǎijì","vi":"trăm phương nghìn kế"},{"hanzi":"想方设法","pinyin":"xiǎngfāngshèfǎ","vi":"tìm mọi cách"},{"hanzi":"百般刁难","pinyin":"bǎibāndiāonàn","vi":"làm khó đủ đường"},{"hanzi":"竭力","pinyin":"jiélì","vi":"hết sức"}]},{"id":"百花齐放","hanzi":"百花齐放","pinyin":"bǎihuā-qífàng","meaning_vi":"trăm hoa đua nở","explanation":"百花齐放: trăm hoa cùng nở (khẩu hiệu 百花齐放, 百家争鸣 năm 1956) → nhiều phong cách, trường phái cùng phát triển, phong phú đa dạng.","hsk_level":6,"tags":["thanh-ngu"],"image":"🌺","examples":[{"type":"basic","zh":"花园里百花齐放。","pinyin":"Huāyuán li bǎihuāqífàng.","vi":"Trong vườn trăm hoa đua nở."},{"type":"simple","zh":"如今的国产动画电影呈现出百花齐放的局面。","pinyin":"Rújīn de guóchǎn dònghuà diànyǐng chéngxiàn chū bǎihuāqífàng de júmiàn.","vi":"Phim hoạt hình nội địa ngày nay đang ở thế trăm hoa đua nở."},{"type":"compound","zh":"只要鼓励不同的观点，学术界就能百花齐放。","pinyin":"Zhǐyào gǔlì bùtóng de guāndiǎn, xuéshùjiè jiù néng bǎihuāqífàng.","vi":"Chỉ cần khuyến khích những quan điểm khác nhau thì giới học thuật sẽ có thể trăm hoa đua nở."}],"related":[{"hanzi":"百家争鸣","pinyin":"bǎijiāzhēngmíng","vi":"trăm nhà đua tiếng"},{"hanzi":"繁荣","pinyin":"fánróng","vi":"phồn vinh"},{"hanzi":"多样","pinyin":"duōyàng","vi":"đa dạng"},{"hanzi":"一枝独秀","pinyin":"yìzhīdúxiù","vi":"một mình nổi trội"}],"traditional":"百花齊放"},{"id":"柏树","hanzi":"柏树","pinyin":"bǎishù","meaning_vi":"cây bách, cây tùng bách","explanation":"柏 (đọc bǎi) + 树 (cây).","hsk_level":6,"tags":["danh-tu","thien-nhien"],"image":"🌲","examples":[{"type":"basic","zh":"院子里有棵柏树。","pinyin":"Yuànzi li yǒu kē bǎishù.","vi":"Trong sân có một cây bách."},{"type":"simple","zh":"寺庙门前的那棵柏树已经有五百年了。","pinyin":"Sìmiào ménqián de nà kē bǎishù yǐjīng yǒu wǔ bǎinián le.","vi":"Cây bách trước cổng chùa đó đã năm trăm năm tuổi."},{"type":"compound","zh":"柏树不但四季常青，而且寿命很长。","pinyin":"Bǎishù búdàn sìjì chángqīng, érqiě shòumìng hěn cháng.","vi":"Cây bách không những xanh tốt quanh năm mà còn sống rất lâu."}],"related":[{"hanzi":"松树","pinyin":"sōngshù","vi":"cây thông"},{"hanzi":"树木","pinyin":"shùmù","vi":"cây cối"},{"hanzi":"常青","pinyin":"chángqīng","vi":"xanh quanh năm"},{"hanzi":"杨树","pinyin":"yángshù","vi":"cây dương"}],"traditional":"柏樹"},{"id":"摆脱","hanzi":"摆脱","pinyin":"bǎituō","meaning_vi":"thoát khỏi","explanation":"摆 (bãi – gạt bỏ) + 脱 (thoát – thoát ra) → gạt bỏ để thoát khỏi điều bất lợi. Thường: 摆脱困境, 摆脱贫困, 摆脱束缚.","hsk_level":6,"tags":["dong-tu"],"image":"🕊️","examples":[{"type":"basic","zh":"他摆脱了贫困。","pinyin":"Tā bǎituōle pínkùn.","vi":"Anh ấy đã thoát khỏi nghèo khó."},{"type":"simple","zh":"小偷在人群中摆脱了警察的追捕。","pinyin":"Xiǎotōu zài rénqún zhōng bǎituōle jǐngchá de zhuībǔ.","vi":"Tên trộm đã thoát khỏi sự truy bắt của cảnh sát trong đám đông."},{"type":"compound","zh":"只要每天坚持运动，你就能摆脱失眠的困扰。","pinyin":"Zhǐyào měitiān jiānchí yùndòng, nǐ jiù néng bǎituō shīmián de kùnrǎo.","vi":"Chỉ cần mỗi ngày kiên trì vận động, bạn sẽ thoát khỏi phiền toái của chứng mất ngủ."}],"related":[{"hanzi":"脱离","pinyin":"tuōlí","vi":"thoát ly"},{"hanzi":"逃脱","pinyin":"táotuō","vi":"trốn thoát"},{"hanzi":"解脱","pinyin":"jiětuō","vi":"giải thoát"},{"hanzi":"摆脱贫困","pinyin":"bǎituōpínkùn","vi":"thoát nghèo"}],"traditional":"擺脫"},{"id":"百闻不如一见","hanzi":"百闻不如一见","pinyin":"bǎi wén bùrú yí jiàn","meaning_vi":"trăm nghe không bằng một thấy","explanation":"百闻 (bách văn – nghe trăm lần) + 不如 (bất như – không bằng) + 一见 (nhất kiến – thấy một lần) → lời tướng Triệu Sung Quốc (Hán thư) → tận mắt thấy mới đáng tin.","hsk_level":6,"tags":["thanh-ngu"],"image":"👀","examples":[{"type":"basic","zh":"真是百闻不如一见！","pinyin":"Zhēn shì bǎiwénbùrúyíjiàn!","vi":"Đúng là trăm nghe không bằng một thấy!"},{"type":"simple","zh":"去了一趟桂林我才明白什么叫百闻不如一见。","pinyin":"Qùle yí tàng Guìlín wǒ cái míngbai shénme jiào bǎiwénbùrúyíjiàn.","vi":"Đi Quế Lâm một chuyến tôi mới hiểu thế nào là trăm nghe không bằng một thấy."},{"type":"compound","zh":"既然百闻不如一见，我们就亲自去工厂看看吧。","pinyin":"Jìrán bǎiwénbùrúyíjiàn, wǒmen jiù qīnzì qù gōngchǎng kànkan ba.","vi":"Đã trăm nghe không bằng một thấy thì chúng ta tự mình đến nhà máy xem thử đi."}],"related":[{"hanzi":"眼见为实","pinyin":"yǎnjiànwéishí","vi":"mắt thấy mới là thật"},{"hanzi":"耳听为虚","pinyin":"ěrtīngwéixū","vi":"tai nghe là hư"},{"hanzi":"亲眼","pinyin":"qīnyǎn","vi":"tận mắt"},{"hanzi":"见闻","pinyin":"jiànwén","vi":"kiến văn"}],"traditional":"百聞不如一見"},{"id":"百折不挠","hanzi":"百折不挠","pinyin":"bǎizhé-bùnáo","meaning_vi":"trăm lần gãy không sờn, kiên cường bất khuất","explanation":"百折 (trăm trắc trở) + 不挠 (không khuất phục). Thành ngữ.","hsk_level":6,"tags":["thanh-ngu"],"image":"💪","examples":[{"type":"basic","zh":"她百折不挠地练习。","pinyin":"Tā bǎizhébùnáo de liànxí.","vi":"Cô ấy kiên trì tập luyện không hề nản lòng."},{"type":"simple","zh":"创业者需要百折不挠的勇气。","pinyin":"Chuàngyèzhě xūyào bǎizhébùnáo de yǒngqì.","vi":"Người khởi nghiệp cần có lòng dũng cảm trăm lần gãy không sờn."},{"type":"compound","zh":"即使被拒绝了上百次，他也百折不挠地推销自己的产品。","pinyin":"Jíshǐ bèi jùjuéle shàng bǎi cì, tā yě bǎizhébùnáo de tuīxiāo zìjǐ de chǎnpǐn.","vi":"Dù bị từ chối hàng trăm lần, anh ấy vẫn kiên trì không nản chí chào bán sản phẩm của mình."}],"related":[{"hanzi":"不屈不挠","pinyin":"bùqūbùnáo","vi":"kiên cường bất khuất"},{"hanzi":"坚韧不拔","pinyin":"jiānrènbùbá","vi":"bền bỉ không lay"},{"hanzi":"锲而不舍","pinyin":"qiè'érbùshě","vi":"kiên trì không bỏ"},{"hanzi":"半途而废","pinyin":"bàntú'érfèi","vi":"bỏ dở giữa chừng"}],"traditional":"百折不撓"},{"id":"版税","hanzi":"版税","pinyin":"bǎnshuì","meaning_vi":"tiền bản quyền (tác giả)","explanation":"版 (xuất bản) + 税 (thuế/phí).","hsk_level":6,"tags":["danh-tu","tien-te","van-hoa"],"image":"📚","examples":[{"type":"basic","zh":"他靠版税生活。","pinyin":"Tā kào bǎnshuì shēnghuó.","vi":"Ông ấy sống nhờ tiền bản quyền."},{"type":"simple","zh":"这位作家把新书的版税全部捐给了山区学校。","pinyin":"Zhè wèi zuòjiā bǎ xīn shū de bǎnshuì quánbù juāngěile shānqū xuéxiào.","vi":"Nhà văn này đã quyên góp toàn bộ tiền bản quyền cuốn sách mới cho trường học vùng núi."},{"type":"compound","zh":"因为这本小说卖了上百万册，所以他拿到了很多版税。","pinyin":"Yīnwèi zhè běn xiǎoshuō màile shàng bǎiwàn cè, suǒyǐ tā nádàole hěn duō bǎnshuì.","vi":"Vì cuốn tiểu thuyết này bán được hàng triệu bản nên ông ấy nhận được rất nhiều tiền bản quyền."}],"related":[{"hanzi":"版权","pinyin":"bǎnquán","vi":"bản quyền"},{"hanzi":"稿费","pinyin":"gǎofèi","vi":"nhuận bút"},{"hanzi":"出版","pinyin":"chūbǎn","vi":"xuất bản"},{"hanzi":"作者","pinyin":"zuòzhě","vi":"tác giả"}],"traditional":"版稅"},{"id":"版图","hanzi":"版图","pinyin":"Bǎntú","meaning_vi":"lãnh thổ, cương vực; phạm vi (thế lực, kinh doanh)","explanation":"版 (bản in) + 图 (bản đồ).","hsk_level":6,"tags":["danh-tu","dia-danh","xa-hoi"],"image":"🗺️","examples":[{"type":"basic","zh":"中国版图辽阔。","pinyin":"Zhōngguó Bǎntú liáokuò.","vi":"Lãnh thổ Trung Quốc rộng lớn."},{"type":"simple","zh":"汉朝的版图比秦朝扩大了很多。","pinyin":"Hàncháo de Bǎntú bǐ Qíncháo kuòdàle hěn duō.","vi":"Lãnh thổ nhà Hán đã mở rộng hơn nhiều so với nhà Tần."},{"type":"compound","zh":"随着收购不断增加，这家公司的商业版图也越来越大。","pinyin":"Suízhe shōugòu búduàn zēngjiā, zhè jiā gōngsī de shāngyè Bǎntú yě yuèláiyuè dà.","vi":"Cùng với việc liên tục thâu tóm các công ty khác, bản đồ kinh doanh của công ty này cũng ngày càng lớn."}],"related":[{"hanzi":"疆域","pinyin":"jiāngyù","vi":"lãnh thổ"},{"hanzi":"领土","pinyin":"lǐngtǔ","vi":"lãnh thổ"},{"hanzi":"地图","pinyin":"dìtú","vi":"bản đồ"},{"hanzi":"国土","pinyin":"Guótǔ","vi":"quốc thổ"}],"traditional":"版圖"},{"id":"板着脸","hanzi":"板着脸","pinyin":"bǎnzheliǎn","meaning_vi":"mặt lạnh như tiền, nghiêm mặt","explanation":"板 (cứng như tấm ván) + 着 + 脸 (mặt).","hsk_level":6,"tags":["dong-tu","cam-xuc"],"image":"😐","examples":[{"type":"basic","zh":"爸爸板着脸不说话。","pinyin":"Bàba bǎnzheliǎn bù shuōhuà.","vi":"Bố nghiêm mặt không nói gì."},{"type":"simple","zh":"新来的经理总是板着脸训人。","pinyin":"Xīn lái de jīnglǐ zǒngshì bǎnzheliǎn xùn rén.","vi":"Giám đốc mới đến lúc nào cũng mặt lạnh mắng người."},{"type":"compound","zh":"老师虽然板着脸，但是其实心里一点也不生气。","pinyin":"Lǎoshī suīrán bǎnzheliǎn, dànshì qíshí xīnli yìdiǎn yě bù shēngqì.","vi":"Thầy giáo tuy nghiêm mặt nhưng thật ra trong lòng chẳng giận chút nào."}],"related":[{"hanzi":"严肃","pinyin":"yánsù","vi":"nghiêm túc"},{"hanzi":"冷淡","pinyin":"lěngdàn","vi":"lạnh nhạt"},{"hanzi":"笑脸","pinyin":"xiàoliǎn","vi":"khuôn mặt tươi cười"},{"hanzi":"生气","pinyin":"shēngqì","vi":"tức giận"}],"traditional":"板著臉"},{"id":"绑","hanzi":"绑","pinyin":"bǎng","meaning_vi":"trói, buộc","explanation":"Bộ mịch 纟+ 邦.","hsk_level":6,"tags":["dong-tu"],"image":"🪢","examples":[{"type":"basic","zh":"把箱子绑紧。","pinyin":"Bǎ xiāngzi bǎng jǐn.","vi":"Buộc chặt cái thùng lại."},{"type":"simple","zh":"他用绳子把行李绑在了自行车后座上。","pinyin":"Tāyòng shéngzi bǎ xíngli bǎng zài le zìxíngchē hòuzuò shang.","vi":"Anh ấy dùng dây buộc hành lý lên yên sau xe đạp."},{"type":"compound","zh":"如果你不把头发绑起来，跑步时就会很不方便。","pinyin":"Rúguǒ nǐ bù bǎ tóufa bǎng qǐlái, pǎobù shí jiù huì hěn bù fāngbiàn.","vi":"Nếu cậu không buộc tóc lên thì lúc chạy bộ sẽ rất bất tiện."}],"related":[{"hanzi":"捆","pinyin":"kǔn","vi":"buộc, bó"},{"hanzi":"绑架","pinyin":"bǎngjià","vi":"bắt cóc"},{"hanzi":"松绑","pinyin":"sōngbǎng","vi":"cởi trói"},{"hanzi":"绳子","pinyin":"shéngzi","vi":"dây thừng"}],"traditional":"綁"},{"id":"榜样","hanzi":"榜样","pinyin":"bǎngyàng","meaning_vi":"tấm gương","explanation":"榜 (bảng – bảng niêm yết) + 样 (dạng – mẫu) → hình mẫu để noi theo, tấm gương. Thường: 树立榜样, 以…为榜样, 榜样的力量.","hsk_level":6,"tags":["danh-tu"],"image":"🌟","examples":[{"type":"basic","zh":"哥哥是我的榜样。","pinyin":"Gēge shì wǒ de bǎngyàng.","vi":"Anh trai là tấm gương của tôi."},{"type":"simple","zh":"这位消防员成了全城人学习的榜样。","pinyin":"Zhè wèi xiāofángyuán chéngle quánchéng rén xuéxí de bǎngyàng.","vi":"Người lính cứu hỏa này đã trở thành tấm gương cho cả thành phố học tập."},{"type":"compound","zh":"既然你是大哥，就要给弟弟妹妹做个好榜样。","pinyin":"Jìrán nǐ shì dàgē, jiùyào gěi dìdi mèimei zuò gè hǎo bǎngyàng.","vi":"Con đã là anh cả thì phải làm gương tốt cho các em."}],"related":[{"hanzi":"模范","pinyin":"mófàn","vi":"mô phạm"},{"hanzi":"表率","pinyin":"biǎoshuài","vi":"tấm gương"},{"hanzi":"典范","pinyin":"diǎnfàn","vi":"điển hình"},{"hanzi":"学习榜样","pinyin":"xuéxíbǎngyàng","vi":"tấm gương học tập"}],"traditional":"榜樣"},{"id":"保管","hanzi":"保管","pinyin":"bǎoguǎn","meaning_vi":"bảo quản, giữ gìn","explanation":"保 (giữ) + 管 (quản lý).","hsk_level":6,"tags":["dong-tu"],"image":"🔒","examples":[{"type":"basic","zh":"请保管好行李。","pinyin":"Qǐng bǎoguǎn hǎo xíngli.","vi":"Xin hãy giữ gìn hành lý cẩn thận."},{"type":"simple","zh":"这些珍贵的古书由专人负责保管。","pinyin":"Zhèxiē zhēnguì de gǔshū yóu zhuānrén fùzé bǎoguǎn.","vi":"Những cuốn sách cổ quý giá này do người chuyên trách bảo quản."},{"type":"compound","zh":"因为药品需要低温保管，所以要放在冰箱里。","pinyin":"Yīnwèi yàopǐn xūyào dīwēn bǎoguǎn, suǒyǐ yào fàng zài bīngxiāng li.","vi":"Vì thuốc cần bảo quản ở nhiệt độ thấp nên phải để trong tủ lạnh."}],"related":[{"hanzi":"保存","pinyin":"bǎocún","vi":"bảo tồn"},{"hanzi":"保管员","pinyin":"bǎoguǎnyuán","vi":"thủ kho"},{"hanzi":"收藏","pinyin":"shōucáng","vi":"cất giữ"},{"hanzi":"看管","pinyin":"kānguǎn","vi":"trông giữ"}]},{"id":"饱和","hanzi":"饱和","pinyin":"bǎohé","meaning_vi":"bão hòa","explanation":"饱 (no/đầy) + 和 (hòa).","hsk_level":6,"tags":["dong-tu","khoa-hoc"],"image":"🧪","examples":[{"type":"basic","zh":"市场已经饱和了。","pinyin":"Shìchǎng yǐjīng bǎohé le.","vi":"Thị trường đã bão hòa rồi."},{"type":"simple","zh":"盐在水里溶解到一定程度就会饱和。","pinyin":"Yán zài shuǐ li róngjiě dào yídìng chéngdù jiù huì bǎohé.","vi":"Muối hòa tan trong nước đến mức nhất định thì sẽ bão hòa."},{"type":"compound","zh":"由于本地的奶茶店已经饱和，所以他决定去别的城市开店。","pinyin":"Yóuyú běndì de nǎichá diàn yǐjīng bǎohé, suǒyǐ tā juédìng qù biéde chéngshì kāidiàn.","vi":"Do tiệm trà sữa ở địa phương đã bão hòa nên anh ấy quyết định mở cửa hàng ở thành phố khác."}],"related":[{"hanzi":"饱和度","pinyin":"bǎohédù","vi":"độ bão hòa"},{"hanzi":"过剩","pinyin":"guòshèng","vi":"dư thừa"},{"hanzi":"市场饱和","pinyin":"shìchǎngbǎohé","vi":"thị trường bão hòa"},{"hanzi":"满","pinyin":"mǎn","vi":"đầy"}],"traditional":"飽和"},{"id":"饱经沧桑","hanzi":"饱经沧桑","pinyin":"bǎojīng-cāngsāng","meaning_vi":"trải qua nhiều thăng trầm biến cố","explanation":"饱经 (trải qua nhiều) + 沧桑 (bãi bể nương dâu). Thành ngữ.","hsk_level":6,"tags":["thanh-ngu"],"image":"🌊","examples":[{"type":"basic","zh":"老人饱经沧桑。","pinyin":"Lǎorén bǎojīngcāngsāng.","vi":"Cụ già đã trải qua nhiều thăng trầm."},{"type":"simple","zh":"这座饱经沧桑的古城墙依然屹立不倒。","pinyin":"Zhè zuò bǎojīngcāngsāng de gǔ chéngqiáng yīrán yìlì bù dǎo.","vi":"Bức tường thành cổ trải qua bao biến cố này vẫn đứng vững."},{"type":"compound","zh":"虽然他饱经沧桑，但是脸上总是带着微笑。","pinyin":"Suīrán tā bǎojīngcāngsāng, dànshì liǎn shang zǒngshì dàizhe wēixiào.","vi":"Tuy đã trải qua bao thăng trầm nhưng trên mặt ông ấy luôn nở nụ cười."}],"related":[{"hanzi":"饱经风霜","pinyin":"bǎojīngfēngshuāng","vi":"dãi dầu sương gió"},{"hanzi":"沧桑","pinyin":"cāngsāng","vi":"bể dâu"},{"hanzi":"历经","pinyin":"lìjīng","vi":"trải qua"},{"hanzi":"阅历","pinyin":"yuèlì","vi":"từng trải"}],"traditional":"飽經滄桑"},{"id":"饱经风霜","hanzi":"饱经风霜","pinyin":"bǎojīng-fēngshuāng","meaning_vi":"dãi dầu sương gió, trải đời","explanation":"饱经风霜: trải no gió sương → từng trải nhiều gian khổ, dãi dầu mưa nắng. Cụm: 饱经风霜的脸.","hsk_level":6,"tags":["thanh-ngu"],"image":"🌬️","examples":[{"type":"basic","zh":"爷爷的脸饱经风霜。","pinyin":"Yéye de liǎn bǎojīngfēngshuāng.","vi":"Gương mặt ông nội hằn dấu dãi dầu sương gió."},{"type":"simple","zh":"那位老渔民有一双饱经风霜的手。","pinyin":"Nà wèi lǎo yúmín yǒu yì shuāng bǎojīngfēngshuāng de shǒu.","vi":"Người ngư dân già ấy có đôi bàn tay dãi dầu sương gió."},{"type":"compound","zh":"虽然他饱经风霜，但是说起话来依然很乐观。","pinyin":"Suīrán tā bǎojīngfēngshuāng, dànshì shuōqǐ huà lái yīrán hěn lèguān.","vi":"Tuy đã trải qua bao sương gió, nhưng khi nói chuyện ông vẫn rất lạc quan."}],"related":[{"hanzi":"饱经沧桑","pinyin":"bǎojīngcāngsāng","vi":"trải nhiều thăng trầm"},{"hanzi":"风霜","pinyin":"fēngshuāng","vi":"gió sương"},{"hanzi":"艰辛","pinyin":"jiānxīn","vi":"gian nan"},{"hanzi":"历尽艰辛","pinyin":"lìjìnjiānxīn","vi":"trải qua bao gian khổ"}],"traditional":"飽經風霜"},{"id":"保密","hanzi":"保密","pinyin":"bǎomì","meaning_vi":"bảo mật, giữ bí mật","explanation":"保 + 密 (kín đáo). Động từ ly hợp.","hsk_level":6,"tags":["dong-tu","cong-nghe"],"image":"🤫","examples":[{"type":"basic","zh":"这件事请你保密。","pinyin":"Zhè jiàn shì qǐng nǐ bǎomì.","vi":"Chuyện này xin bạn giữ bí mật."},{"type":"simple","zh":"公司要求员工对客户资料严格保密。","pinyin":"Gōngsī yāoqiú yuángōng duì kèhù zīliào yángé bǎomì.","vi":"Công ty yêu cầu nhân viên bảo mật nghiêm ngặt thông tin khách hàng."},{"type":"compound","zh":"只要你答应保密，我就把真相告诉你。","pinyin":"Zhǐyào nǐ dāying bǎomì, wǒ jiù bǎ zhēnxiàng gàosu nǐ.","vi":"Chỉ cần bạn hứa giữ bí mật, tôi sẽ nói cho bạn sự thật."}],"related":[{"hanzi":"机密","pinyin":"jīmì","vi":"cơ mật"},{"hanzi":"秘密","pinyin":"mìmì","vi":"bí mật"},{"hanzi":"泄密","pinyin":"xièmì","vi":"tiết lộ bí mật"},{"hanzi":"保密协议","pinyin":"bǎomìxiéyì","vi":"thỏa thuận bảo mật"}]},{"id":"饱满","hanzi":"饱满","pinyin":"bǎomǎn","meaning_vi":"đầy đặn, mẩy (hạt); dồi dào, phấn chấn (tinh thần)","explanation":"饱 (no) + 满 (đầy).","hsk_level":6,"tags":["tinh-tu"],"image":"🌾","examples":[{"type":"basic","zh":"今年的稻谷颗粒饱满。","pinyin":"Jīnnián de dàogǔ kēlì bǎomǎn.","vi":"Hạt lúa năm nay rất mẩy."},{"type":"simple","zh":"他每天早上都精神饱满地去上班。","pinyin":"Tā měitiān zǎoshang dōu jīngshen bǎomǎn de qù shàngbān.","vi":"Sáng nào anh ấy cũng đi làm với tinh thần phấn chấn."},{"type":"compound","zh":"因为昨晚睡得很好，所以她今天精神饱满。","pinyin":"Yīnwèi zuó wǎnshuì de hěn hǎo, suǒyǐ tā jīntiān jīngshen bǎomǎn.","vi":"Vì tối qua ngủ rất ngon nên hôm nay cô ấy tràn đầy sinh lực."}],"related":[{"hanzi":"丰满","pinyin":"fēngmǎn","vi":"đầy đặn"},{"hanzi":"充沛","pinyin":"chōngpèi","vi":"dồi dào"},{"hanzi":"精神饱满","pinyin":"jīngshénbǎomǎn","vi":"tinh thần phấn chấn"},{"hanzi":"干瘪","pinyin":"gānbiě","vi":"khô quắt"}],"traditional":"飽滿"},{"id":"保姆","hanzi":"保姆","pinyin":"bǎomǔ","meaning_vi":"người giúp việc, bảo mẫu","explanation":"保 + 姆 (người trông trẻ).","hsk_level":6,"tags":["danh-tu","nghe-nghiep","gia-dinh"],"image":"👩‍🍼","examples":[{"type":"basic","zh":"她家请了一个保姆。","pinyin":"Tā jiā qǐngle yí gè bǎomǔ.","vi":"Nhà cô ấy thuê một người giúp việc."},{"type":"simple","zh":"保姆每天下午四点去幼儿园接孩子。","pinyin":"Bǎomǔ měitiān xiàwǔ sì diǎn qù yòu'éryuán jiē háizi.","vi":"Bảo mẫu đón đứa bé ở trường mẫu giáo lúc bốn giờ chiều mỗi ngày."},{"type":"compound","zh":"因为夫妻俩工作都很忙，所以只好请保姆照顾老人。","pinyin":"Yīnwèi fūqī liǎ gōngzuò dōu hěn máng, suǒyǐ zhǐhǎo qǐng bǎomǔ zhàogù lǎorén.","vi":"Vì hai vợ chồng đều bận việc nên đành thuê người giúp việc chăm sóc người già."}],"related":[{"hanzi":"阿姨","pinyin":"āyí","vi":"cô giúp việc"},{"hanzi":"家政","pinyin":"jiāzhèng","vi":"giúp việc gia đình"},{"hanzi":"月嫂","pinyin":"yuèsǎo","vi":"người chăm sóc sản phụ"},{"hanzi":"佣人","pinyin":"yōngrén","vi":"người làm"}]},{"id":"保守","hanzi":"保守","pinyin":"bǎoshǒu","meaning_vi":"bảo thủ; giữ (bí mật)","explanation":"保 (bảo – giữ) + 守 (thủ – giữ) → giữ chặt: giữ (bí mật); tính từ: bảo thủ, dè dặt. Cụm: 保守秘密, 思想保守, 保守估计.","hsk_level":6,"tags":["tinh-tu","dong-tu"],"image":"🛡️","examples":[{"type":"basic","zh":"我父亲的思想很保守。","pinyin":"Wǒ fùqīn de sīxiǎng hěn bǎoshǒu.","vi":"Tư tưởng của bố tôi rất bảo thủ."},{"type":"simple","zh":"这个数字是一个比较保守的估计。","pinyin":"Zhè ge shùzì shì yí gè bǐjiào bǎoshǒu de gūjì.","vi":"Con số này là một ước tính khá dè dặt."},{"type":"compound","zh":"他不但能保守秘密，而且从不在背后议论别人。","pinyin":"Tā búdàn néng bǎoshǒu mìmì, érqiě cóng bú zài bèihòu yìlùn biérén.","vi":"Anh ấy không những giữ được bí mật mà còn chưa bao giờ bàn tán sau lưng người khác."}],"related":[{"hanzi":"守旧","pinyin":"shǒujiù","vi":"thủ cựu"},{"hanzi":"开放","pinyin":"kāifàng","vi":"cởi mở"},{"hanzi":"保守秘密","pinyin":"bǎoshǒumìmì","vi":"giữ bí mật"},{"hanzi":"传统","pinyin":"chuántǒng","vi":"truyền thống"}]},{"id":"保卫","hanzi":"保卫","pinyin":"bǎowèi","meaning_vi":"bảo vệ, giữ gìn (tổ quốc, hòa bình…)","explanation":"保 (bảo – giữ) + 卫 (vệ – phòng vệ) → bảo vệ, giữ gìn chống xâm phạm. Thường dùng cho đối tượng lớn: 保卫祖国, 保卫和平; 保护 dùng rộng hơn.","hsk_level":6,"tags":["dong-tu"],"image":"🛡️","examples":[{"type":"basic","zh":"士兵们保卫祖国。","pinyin":"Shìbīngmen bǎowèi zǔguó.","vi":"Những người lính bảo vệ Tổ quốc."},{"type":"simple","zh":"村民们拿起工具保卫自己的家园。","pinyin":"Cūnmínmen náqǐ gōngjù bǎowèi zìjǐ de jiāyuán.","vi":"Dân làng cầm lấy công cụ để bảo vệ quê hương của mình."},{"type":"compound","zh":"即使条件再艰苦，战士们也坚守岗位保卫边疆。","pinyin":"Jíshǐ tiáojiàn zài jiānkǔ, zhànshìmen yě jiānshǒu gǎngwèi bǎowèi biānjiāng.","vi":"Dù điều kiện gian khổ đến đâu, các chiến sĩ vẫn bám trụ vị trí bảo vệ biên cương."}],"related":[{"hanzi":"保护","pinyin":"bǎohù","vi":"bảo vệ"},{"hanzi":"捍卫","pinyin":"hànwèi","vi":"bảo vệ, giữ gìn"},{"hanzi":"防卫","pinyin":"fángwèi","vi":"phòng vệ"},{"hanzi":"保卫祖国","pinyin":"bǎowèizǔguó","vi":"bảo vệ tổ quốc"}],"traditional":"保衛"},{"id":"保鲜","hanzi":"保鲜","pinyin":"bǎoxiān","meaning_vi":"giữ tươi (thực phẩm)","explanation":"保 + 鲜 (tươi). Cụm: 保鲜膜 (màng bọc thực phẩm).","hsk_level":6,"tags":["dong-tu","an-uong"],"image":"🥬","examples":[{"type":"basic","zh":"把菜放进冰箱保鲜。","pinyin":"Bǎ cài fàngjìn bīngxiāng bǎoxiān.","vi":"Cho rau vào tủ lạnh để giữ tươi."},{"type":"simple","zh":"妈妈用保鲜膜把剩下的西瓜包好了。","pinyin":"Māma yòng bǎoxiānmó bǎ shèngxià de xīguā bāo hǎo le.","vi":"Mẹ dùng màng bọc thực phẩm bọc kỹ phần dưa hấu còn lại."},{"type":"compound","zh":"如果水果不及时保鲜，过两天就会烂掉。","pinyin":"Rúguǒ shuǐguǒ bù jíshí bǎoxiān, guò liǎng tiān jiù huì làn diào.","vi":"Nếu hoa quả không được bảo quản tươi kịp thời, vài hôm nữa sẽ bị hỏng."}],"related":[{"hanzi":"新鲜","pinyin":"xīnxiān","vi":"tươi"},{"hanzi":"保鲜膜","pinyin":"bǎoxiānmó","vi":"màng bọc thực phẩm"},{"hanzi":"冷藏","pinyin":"lěngcáng","vi":"bảo quản lạnh"},{"hanzi":"变质","pinyin":"biànzhì","vi":"biến chất"}],"traditional":"保鮮"},{"id":"保佑","hanzi":"保佑","pinyin":"bǎoyòu","meaning_vi":"phù hộ, che chở","explanation":"保 + 佑 (giúp đỡ).","hsk_level":6,"tags":["dong-tu","van-hoa"],"image":"🙏","examples":[{"type":"basic","zh":"愿老天保佑你平安。","pinyin":"Yuàn lǎotiān bǎoyòu nǐ píng'ān.","vi":"Mong trời phù hộ cho bạn bình an."},{"type":"simple","zh":"奶奶去寺庙祈求菩萨保佑全家健康。","pinyin":"Nǎinai qù sìmiào qíqiú púsà bǎoyòu quánjiā jiànkāng.","vi":"Bà nội lên chùa cầu Bồ Tát phù hộ cả nhà mạnh khỏe."},{"type":"compound","zh":"虽然她不迷信，但是考试前也会默念老天保佑。","pinyin":"Suīrán tā bù míxìn, dànshì kǎoshì qián yě huì mòniàn lǎotiān bǎoyòu.","vi":"Tuy cô ấy không mê tín, nhưng trước kỳ thi cũng thầm niệm cầu trời phù hộ."}],"related":[{"hanzi":"庇护","pinyin":"bìhù","vi":"che chở"},{"hanzi":"神灵","pinyin":"shénlíng","vi":"thần linh"},{"hanzi":"祈祷","pinyin":"qídǎo","vi":"cầu nguyện"},{"hanzi":"平安","pinyin":"píng'ān","vi":"bình an"}]},{"id":"保质期","hanzi":"保质期","pinyin":"bǎozhìqī","meaning_vi":"hạn sử dụng","explanation":"保质 (bảo đảm chất lượng) + 期 (thời hạn).","hsk_level":6,"tags":["danh-tu","an-uong","mua-sam"],"image":"📅","examples":[{"type":"basic","zh":"这瓶牛奶过了保质期。","pinyin":"Zhè píng niúnǎiguò le bǎozhìqī.","vi":"Chai sữa này đã quá hạn sử dụng."},{"type":"simple","zh":"买罐头时一定要看清包装上的保质期。","pinyin":"Mǎi guàntou shí yídìngyào kànqīng bāozhuāng shàng de bǎozhìqī.","vi":"Khi mua đồ hộp nhất định phải xem rõ hạn sử dụng trên bao bì."},{"type":"compound","zh":"这种饼干既便宜又好吃，可惜保质期只有一个月。","pinyin":"Zhè zhǒng bǐnggān jì piányi yòu hǎochī, kěxī bǎozhìqī zhǐyǒu yí gèyuè.","vi":"Loại bánh quy này vừa rẻ vừa ngon, tiếc là hạn sử dụng chỉ có một tháng."}],"related":[{"hanzi":"有效期","pinyin":"yǒuxiàoqī","vi":"thời hạn hiệu lực"},{"hanzi":"过期","pinyin":"guòqī","vi":"quá hạn"},{"hanzi":"生产日期","pinyin":"shēngchǎnrìqī","vi":"ngày sản xuất"},{"hanzi":"食品","pinyin":"shípǐn","vi":"thực phẩm"}],"traditional":"保質期"},{"id":"宝藏","hanzi":"宝藏","pinyin":"bǎozàng","meaning_vi":"kho báu, tài nguyên quý giá","explanation":"宝 (báu vật) + 藏 (cất giấu).","hsk_level":6,"tags":["danh-tu"],"image":"💎","examples":[{"type":"basic","zh":"海底藏着很多宝藏。","pinyin":"Hǎidǐ cángzhe hěn duō bǎozàng.","vi":"Dưới đáy biển ẩn giấu nhiều kho báu."},{"type":"simple","zh":"传统文化是我们民族的精神宝藏。","pinyin":"Chuántǒng wénhuà shì wǒmen mínzú de jīngshén bǎozàng.","vi":"Văn hóa truyền thống là kho báu tinh thần của dân tộc ta."},{"type":"compound","zh":"只要用心去读，每本好书都是一座宝藏。","pinyin":"Zhǐyào yòngxīn qù dú, měi běn hǎo shū dōu shì yí zuò bǎozàng.","vi":"Chỉ cần đọc bằng cả tấm lòng, mỗi cuốn sách hay đều là một kho báu."}],"related":[{"hanzi":"宝库","pinyin":"bǎokù","vi":"kho báu"},{"hanzi":"财富","pinyin":"cáifù","vi":"của cải"},{"hanzi":"珍宝","pinyin":"zhēnbǎo","vi":"báu vật"},{"hanzi":"矿藏","pinyin":"kuàngcáng","vi":"tài nguyên khoáng sản"}],"traditional":"寶藏"},{"id":"彼","hanzi":"彼","pinyin":"bǐ","meaning_vi":"bên kia, đối phương (văn viết)","explanation":"Ví dụ: 知己知彼 (biết mình biết ta).","hsk_level":6,"tags":["dai-tu"],"image":"👤","examples":[{"type":"basic","zh":"知己知彼，百战不殆。","pinyin":"Zhījǐ zhī bǐ, bǎi zhàn bú dài.","vi":"Biết người biết ta, trăm trận không nguy."},{"type":"simple","zh":"会场里的掌声此起彼伏。","pinyin":"Huìchǎng lǐ de zhǎngshēng cǐqǐbǐfú.","vi":"Tiếng vỗ tay trong hội trường vang lên không ngớt, chỗ này dứt chỗ kia nổi."},{"type":"compound","zh":"如果只顾眼前利益，就容易顾此失彼。","pinyin":"Rúguǒ zhǐgù yǎnqián lìyì, jiù róngyì gù cǐ shī bǐ.","vi":"Nếu chỉ lo lợi ích trước mắt thì dễ được cái này mất cái kia."}],"related":[{"hanzi":"彼此","pinyin":"bǐcǐ","vi":"lẫn nhau"},{"hanzi":"此","pinyin":"cǐ","vi":"này, đây"},{"hanzi":"知己知彼","pinyin":"zhījǐzhībǐ","vi":"biết mình biết người"},{"hanzi":"彼岸","pinyin":"bǐ'àn","vi":"bờ bên kia"}]},{"id":"比比皆是","hanzi":"比比皆是","pinyin":"bǐbǐ-jiēshì","meaning_vi":"khắp nơi đều có, nhiều vô kể","explanation":"比比 (khắp nơi) + 皆是 (đều là). Thành ngữ.","hsk_level":6,"tags":["thanh-ngu"],"image":"🌐","examples":[{"type":"basic","zh":"街上的咖啡馆比比皆是。","pinyin":"Jiēshàng de kāfēiguǎn bǐbǐjiēshì.","vi":"Quán cà phê trên phố nhiều vô kể."},{"type":"simple","zh":"在这座小城里，类似的老房子比比皆是。","pinyin":"Zài zhè zuò xiǎo chénglǐ, lèi sìde lǎo fángzi bǐbǐjiēshì.","vi":"Ở thị trấn nhỏ này, những ngôi nhà cổ tương tự có ở khắp nơi."},{"type":"compound","zh":"虽然这类错误比比皆是，但是很少有人认真纠正。","pinyin":"Suīrán zhèlèi cuòwù bǐbǐjiēshì, dànshì hěn shǎoyǒu rén rènzhēn jiūzhèng.","vi":"Tuy loại lỗi này đâu đâu cũng có, nhưng rất ít người nghiêm túc sửa chữa."}],"related":[{"hanzi":"随处可见","pinyin":"suíchùkějiàn","vi":"nơi nào cũng thấy"},{"hanzi":"到处都是","pinyin":"dàochùdōushì","vi":"chỗ nào cũng có"},{"hanzi":"不胜枚举","pinyin":"búshèngméijǔ","vi":"nhiều không kể xiết"},{"hanzi":"寥寥无几","pinyin":"liáoliáowújǐ","vi":"ít ỏi"}]},{"id":"彼岸","hanzi":"彼岸","pinyin":"bǐ'àn","meaning_vi":"bờ bên kia (thành công/đại dương)","explanation":"彼 (bên kia) + 岸 (bờ).","hsk_level":6,"tags":["danh-tu"],"image":"🏖️","examples":[{"type":"basic","zh":"船终于到达了彼岸。","pinyin":"Chuán zhōngyú dàodále bǐ'àn.","vi":"Con thuyền cuối cùng đã đến bờ bên kia."},{"type":"simple","zh":"他怀着梦想漂洋过海去了大洋彼岸。","pinyin":"Tā huáizhe mèngxiǎng piāoyángguò hǎi qùle dàyáng bǐ'àn.","vi":"Anh ấy mang theo ước mơ vượt biển sang bờ bên kia đại dương."},{"type":"compound","zh":"只要坚持不懈，我们就一定能到达成功的彼岸。","pinyin":"Zhǐyào jiānchíbúxiè, wǒmen jiù yídìng néng dàodá chénggōng de bǐ'àn.","vi":"Chỉ cần kiên trì không ngừng, chúng ta nhất định sẽ đến được bến bờ thành công."}],"related":[{"hanzi":"对岸","pinyin":"duì'àn","vi":"bờ đối diện"},{"hanzi":"岸边","pinyin":"ànbiān","vi":"bờ"},{"hanzi":"成功","pinyin":"chénggōng","vi":"thành công"},{"hanzi":"理想","pinyin":"lǐxiǎng","vi":"lý tưởng"}]},{"id":"秉持","hanzi":"秉持","pinyin":"bǐngchí","meaning_vi":"giữ vững, tuân theo (nguyên tắc/tinh thần)","explanation":"秉 (nắm giữ) + 持 (duy trì).","hsk_level":6,"tags":["dong-tu"],"image":"✊","examples":[{"type":"basic","zh":"公司秉持诚信原则。","pinyin":"Gōngsī bǐngchí chéngxìn yuánzé.","vi":"Công ty giữ vững nguyên tắc chữ tín."},{"type":"simple","zh":"这家老店一直秉持着用料实在的传统。","pinyin":"Zhè jiālǎo diàn yìzhí bǐngchízhe yòngliào shízài de chuántǒng.","vi":"Tiệm lâu đời này luôn giữ truyền thống dùng nguyên liệu thật thà."},{"type":"compound","zh":"虽然市场变化很快，但是他始终秉持客户第一的理念。","pinyin":"Suīrán shìchǎng biànhuà hěn kuài, dànshì tā shǐzhōng bǐngchí kèhù dìyī de lǐniàn.","vi":"Tuy thị trường thay đổi rất nhanh, nhưng ông ấy luôn giữ vững triết lý khách hàng là trên hết."}],"related":[{"hanzi":"坚持","pinyin":"jiānchí","vi":"kiên trì"},{"hanzi":"秉承","pinyin":"bǐngchéng","vi":"kế thừa, tiếp nối"},{"hanzi":"遵循","pinyin":"zūnxún","vi":"tuân theo"},{"hanzi":"奉行","pinyin":"fèngxíng","vi":"thực hành"}]},{"id":"捕捞","hanzi":"捕捞","pinyin":"bǔlāo","meaning_vi":"đánh bắt (thủy hải sản)","explanation":"捕 (bắt) + 捞 (vớt).","hsk_level":6,"tags":["dong-tu","cong-viec"],"image":"🎣","examples":[{"type":"basic","zh":"渔民出海捕捞。","pinyin":"Yúmín chūhǎi bǔlāo.","vi":"Ngư dân ra khơi đánh bắt."},{"type":"simple","zh":"每年春天这片海域都禁止捕捞鱼虾。","pinyin":"Měinián chūntiān zhè piàn Hǎiyù dōu jìnzhǐ bǔlāo yúxiā.","vi":"Mỗi mùa xuân, vùng biển này đều cấm đánh bắt tôm cá."},{"type":"compound","zh":"如果继续过度捕捞，海里的鱼就会越来越少。","pinyin":"Rúguǒ jìxù guòdù bǔlāo, hǎilǐ de yú jiù huì yuèláiyuè shǎo.","vi":"Nếu tiếp tục đánh bắt quá mức, cá dưới biển sẽ ngày càng ít đi."}],"related":[{"hanzi":"捕鱼","pinyin":"bǔyú","vi":"đánh cá"},{"hanzi":"渔民","pinyin":"yúmín","vi":"ngư dân"},{"hanzi":"海鲜","pinyin":"hǎixiān","vi":"hải sản"},{"hanzi":"休渔期","pinyin":"xiūyúqī","vi":"mùa cấm đánh bắt"}],"traditional":"捕撈"},{"id":"哺育","hanzi":"哺育","pinyin":"bǔyù","meaning_vi":"nuôi nấng, dưỡng dục","explanation":"哺 (mớm ăn) + 育 (nuôi lớn).","hsk_level":6,"tags":["dong-tu","gia-dinh"],"image":"👶","examples":[{"type":"basic","zh":"母亲哺育了我们。","pinyin":"Mǔqīn bǔyùle wǒmen.","vi":"Mẹ đã nuôi nấng chúng tôi."},{"type":"simple","zh":"黄河哺育了一代又一代的中华儿女。","pinyin":"Huánghé bǔyùle yídài yòu yídài de Zhōnghuá érnǚ.","vi":"Sông Hoàng Hà đã nuôi dưỡng bao thế hệ người con Trung Hoa."},{"type":"compound","zh":"燕子妈妈一边捉虫，一边哺育巢里的小燕子。","pinyin":"Yànzi māma yìbiān zhuō chóng, yìbiān bǔyù cháo lǐ de xiǎo yànzi.","vi":"Chim én mẹ vừa bắt sâu vừa mớm nuôi đàn én con trong tổ."}],"related":[{"hanzi":"养育","pinyin":"yǎngyù","vi":"nuôi dạy"},{"hanzi":"抚养","pinyin":"fǔyǎng","vi":"nuôi nấng"},{"hanzi":"哺乳","pinyin":"bǔrǔ","vi":"cho bú"},{"hanzi":"培育","pinyin":"péiyù","vi":"bồi dưỡng"}]},{"id":"捕捉","hanzi":"捕捉","pinyin":"bǔzhuō","meaning_vi":"bắt giữ, nắm bắt","explanation":"捕 (bộ – bắt) + 捉 (tróc – nắm, bắt) → bắt (con vật, tội phạm); nghĩa bóng: nắm bắt (捕捉机会, 捕捉镜头, 捕捉信息).","hsk_level":6,"tags":["dong-tu"],"image":"📸","examples":[{"type":"basic","zh":"猫在捕捉老鼠。","pinyin":"Māo zài bǔzhuō lǎoshǔ.","vi":"Con mèo đang bắt chuột."},{"type":"simple","zh":"摄影师耐心地捕捉日出的那一瞬间。","pinyin":"Shèyǐngshī nàixīn de bǔzhuō rìchū de nà yíshùnjiān.","vi":"Nhiếp ảnh gia kiên nhẫn chộp lấy khoảnh khắc mặt trời mọc."},{"type":"compound","zh":"只要善于捕捉商机，小生意就能做大。","pinyin":"Zhǐyào shànyú bǔzhuō shāngjī, xiǎo shēngyi jiù néng zuòdà.","vi":"Chỉ cần giỏi nắm bắt cơ hội kinh doanh, buôn bán nhỏ cũng có thể làm lớn."}],"related":[{"hanzi":"抓住","pinyin":"zhuāzhù","vi":"nắm lấy"},{"hanzi":"捕获","pinyin":"bǔhuò","vi":"bắt được"},{"hanzi":"捉","pinyin":"zhuō","vi":"bắt"},{"hanzi":"捕捉机会","pinyin":"bǔzhuōjīhuì","vi":"nắm bắt cơ hội"}]},{"id":"串通","hanzi":"串通","pinyin":"chuàntōng","meaning_vi":"thông đồng, cấu kết","explanation":"串 (xâu chuỗi) + 通 (thông nhau).","hsk_level":6,"tags":["dong-tu"],"image":"⛓️","examples":[{"type":"basic","zh":"他们串通好了。","pinyin":"Tāmen chuàntōng hǎo le.","vi":"Bọn họ đã thông đồng với nhau."},{"type":"simple","zh":"几家商店串通起来抬高了猪肉价格。","pinyin":"Jǐ jiā shāngdiàn chuàntōng qǐlái táigāole zhūròu jiàgé.","vi":"Mấy cửa hàng cấu kết với nhau đẩy giá thịt lợn lên cao."},{"type":"compound","zh":"因为他和对手串通作弊，所以被取消了比赛资格。","pinyin":"Yīnwèi tā hé duìshǒu chuàntōng zuòbì, suǒyǐ bèi qǔxiāole bǐsài zīgé.","vi":"Vì anh ta thông đồng gian lận với đối thủ nên đã bị hủy tư cách thi đấu."}],"related":[{"hanzi":"勾结","pinyin":"gōujié","vi":"câu kết"},{"hanzi":"合谋","pinyin":"hémóu","vi":"đồng mưu"},{"hanzi":"串通一气","pinyin":"chuàntōngyíqì","vi":"thông đồng một giuộc"},{"hanzi":"同谋","pinyin":"tóngmóu","vi":"đồng mưu"}]},{"id":"创立","hanzi":"创立","pinyin":"chuànglì","meaning_vi":"sáng lập","explanation":"创 (sáng – mở đầu) + 立 (lập – dựng) → sáng lập, gây dựng lần đầu. Thường: 创立公司, 创立学说.","hsk_level":6,"tags":["dong-tu"],"image":"🏢","examples":[{"type":"basic","zh":"他创立了一家公司。","pinyin":"Tā chuànglìle yìjiā gōngsī.","vi":"Anh ấy đã sáng lập một công ty."},{"type":"simple","zh":"这所大学是在一个多世纪以前创立的。","pinyin":"Zhè suǒ dàxué shì zài yí gè duō shìjì yǐqián chuànglì de.","vi":"Trường đại học này được sáng lập cách đây hơn một thế kỷ."},{"type":"compound","zh":"虽然创立品牌时资金很少，但是她坚持了下来。","pinyin":"Suīrán chuànglì pǐnpái shí zījīn hěn shǎo, dànshì tā jiānchíle xiàlái.","vi":"Tuy lúc sáng lập thương hiệu vốn liếng rất ít, nhưng cô ấy vẫn kiên trì đến cùng."}],"related":[{"hanzi":"创办","pinyin":"chuàngbàn","vi":"sáng lập"},{"hanzi":"建立","pinyin":"jiànlì","vi":"thành lập"},{"hanzi":"创始人","pinyin":"chuàngshǐrén","vi":"nhà sáng lập"},{"hanzi":"成立","pinyin":"chénglì","vi":"thành lập"}],"traditional":"創立"},{"id":"创作","hanzi":"创作","pinyin":"chuàngzuò","meaning_vi":"sáng tác","explanation":"创 (sáng – tạo mới) + 作 (tác – làm) → sáng tác (văn học, nghệ thuật). Ví dụ: 创作歌曲, 文学创作; danh từ: tác phẩm.","hsk_level":6,"tags":["dong-tu"],"image":"✍️","examples":[{"type":"basic","zh":"他正在创作新歌。","pinyin":"Tā zhèngzài chuàngzuò xīn gē.","vi":"Anh ấy đang sáng tác bài hát mới."},{"type":"simple","zh":"这幅画是画家在海边创作的。","pinyin":"Zhè fú huà shì huàjiā zài hǎibiān chuàngzuò de.","vi":"Bức tranh này được họa sĩ sáng tác bên bờ biển."},{"type":"compound","zh":"作家一有灵感，就马上拿起笔开始创作。","pinyin":"Zuòjiā yì yǒu línggǎn, jiù mǎshàng náqǐ bǐ kāishǐ chuàngzuò.","vi":"Nhà văn hễ có cảm hứng là lập tức cầm bút bắt đầu sáng tác."}],"related":[{"hanzi":"作品","pinyin":"zuòpǐn","vi":"tác phẩm"},{"hanzi":"创造","pinyin":"chuàngzào","vi":"sáng tạo"},{"hanzi":"写作","pinyin":"xiězuò","vi":"viết lách"},{"hanzi":"创作者","pinyin":"chuàngzuòzhě","vi":"người sáng tác"}],"traditional":"創作"},{"id":"传达","hanzi":"传达","pinyin":"chuándá","meaning_vi":"truyền đạt","explanation":"传 (truyền) + 达 (đạt – đến nơi) → truyền đến cho người khác. Thường: 传达命令, 传达精神, 传达信息.","hsk_level":6,"tags":["dong-tu"],"image":"📢","examples":[{"type":"basic","zh":"请把消息传达给大家。","pinyin":"Qǐng bǎ xiāoxi chuándá gěi dàjiā.","vi":"Hãy truyền đạt tin này cho mọi người."},{"type":"simple","zh":"经理在早会上传达了总部的最新通知。","pinyin":"Jīnglǐ zài zǎo huì shàng chuándále zǒngbù de zuì xīn tōngzhī.","vi":"Giám đốc đã truyền đạt thông báo mới nhất của tổng bộ trong buổi họp sáng."},{"type":"compound","zh":"他的眼神既传达了感激，又带着几分不舍。","pinyin":"Tā de yǎnshén jì chuándále gǎnjī, yòu dàizhe jǐfēn bùshě.","vi":"Ánh mắt anh ấy vừa truyền tải lòng biết ơn, vừa mang chút lưu luyến."}],"related":[{"hanzi":"转达","pinyin":"zhuǎndá","vi":"chuyển lời"},{"hanzi":"传递","pinyin":"chuándì","vi":"truyền đạt"},{"hanzi":"表达","pinyin":"biǎodá","vi":"biểu đạt"},{"hanzi":"传达室","pinyin":"chuándáshì","vi":"phòng thường trực"}],"traditional":"傳達"},{"id":"传染病","hanzi":"传染病","pinyin":"chuánrǎnbìng","meaning_vi":"bệnh truyền nhiễm","explanation":"传染 (lây nhiễm) + 病 (bệnh).","hsk_level":6,"tags":["danh-tu","suc-khoe"],"image":"😷","examples":[{"type":"basic","zh":"流感是一种传染病。","pinyin":"Liúgǎn shì yì zhǒng chuánrǎnbìng.","vi":"Cúm là một loại bệnh truyền nhiễm."},{"type":"simple","zh":"医院专门为传染病患者设立了隔离病房。","pinyin":"Yīyuàn zhuānmén wèi chuánrǎnbìng huànzhě shèlìle gélí bìngfáng.","vi":"Bệnh viện lập riêng phòng cách ly cho bệnh nhân mắc bệnh truyền nhiễm."},{"type":"compound","zh":"只要勤洗手、戴口罩，就能有效预防很多传染病。","pinyin":"Zhǐyào qín xǐshǒu, dài kǒuzhào, jiù néng yǒuxiào yùfáng hěn duō chuánrǎnbìng.","vi":"Chỉ cần chăm rửa tay, đeo khẩu trang là có thể phòng ngừa hiệu quả nhiều bệnh truyền nhiễm."}],"related":[{"hanzi":"传染","pinyin":"chuánrǎn","vi":"lây nhiễm"},{"hanzi":"病毒","pinyin":"bìngdú","vi":"virus"},{"hanzi":"疫情","pinyin":"yìqíng","vi":"dịch bệnh"},{"hanzi":"隔离","pinyin":"gélí","vi":"cách ly"}],"traditional":"傳染病"},{"id":"传颂","hanzi":"传颂","pinyin":"chuánsòng","meaning_vi":"truyền tụng, ca ngợi lưu truyền","explanation":"传 (truyền lại) + 颂 (ca ngợi).","hsk_level":6,"tags":["dong-tu","van-hoa"],"image":"📜","examples":[{"type":"basic","zh":"他的故事被人传颂。","pinyin":"Tā de gùshi bèi rén chuánsòng.","vi":"Câu chuyện của ông được người đời truyền tụng."},{"type":"simple","zh":"这首民歌在当地已经传颂了几百年。","pinyin":"Zhè shǒu míngē zài dāngdì yǐjīng chuánsòngle jǐ bǎinián.","vi":"Bài dân ca này đã được lưu truyền ở địa phương mấy trăm năm."},{"type":"compound","zh":"虽然英雄已经离开了，但是他的事迹至今仍被传颂。","pinyin":"Suīrán yīngxióng yǐjīng líkāi le, dànshì tā de shìjì zhìjīn réng bèi chuánsòng.","vi":"Tuy người anh hùng đã ra đi, nhưng sự tích của ông đến nay vẫn được ca ngợi."}],"related":[{"hanzi":"称颂","pinyin":"chēngsòng","vi":"ca ngợi"},{"hanzi":"歌颂","pinyin":"gēsòng","vi":"ca tụng"},{"hanzi":"流传","pinyin":"liúchuán","vi":"lưu truyền"},{"hanzi":"赞颂","pinyin":"zànsòng","vi":"tán tụng"}],"traditional":"傳頌"},{"id":"传宗接代","hanzi":"传宗接代","pinyin":"chuánzōng-jiēdài","meaning_vi":"nối dõi tông đường","explanation":"传宗 (truyền tông – truyền dòng họ) + 接代 (tiếp đại – nối đời) → sinh con (trai) để dòng họ được truyền nối → nối dõi tông đường, quan niệm truyền thống.","hsk_level":6,"tags":["thanh-ngu","gia-dinh"],"image":"👨‍👩‍👦","examples":[{"type":"basic","zh":"老人盼着传宗接代。","pinyin":"Lǎorén pànzhe chuánzōngjiēdài.","vi":"Người già mong có con nối dõi tông đường."},{"type":"simple","zh":"在过去，很多家庭把传宗接代看得很重。","pinyin":"Zài guòqù, hěn duō jiātíng bǎ chuánzōngjiēdài kàn de hěn zhòng.","vi":"Ngày xưa, nhiều gia đình rất coi trọng việc nối dõi tông đường."},{"type":"compound","zh":"与其总想着传宗接代，不如先把自己的日子过好。","pinyin":"Yǔqí zǒng xiǎngzhe chuánzōngjiēdài, bùrú xiān bǎ zìjǐ de rìziguò hǎo.","vi":"Thay vì cứ nghĩ đến chuyện nối dõi tông đường, chi bằng lo sống tốt cuộc sống của mình trước."}],"related":[{"hanzi":"后代","pinyin":"hòudài","vi":"đời sau"},{"hanzi":"继承","pinyin":"jìchéng","vi":"kế thừa"},{"hanzi":"香火","pinyin":"xiānghuǒ","vi":"hương hỏa"},{"hanzi":"子孙","pinyin":"zǐsūn","vi":"con cháu"}],"traditional":"傳宗接代"},{"id":"床铺","hanzi":"床铺","pinyin":"chuángpù","meaning_vi":"giường ngủ, giường chiếu","explanation":"床 (giường) + 铺 (đọc pù).","hsk_level":6,"tags":["danh-tu","do-vat","nha-cua"],"image":"🛏️","examples":[{"type":"basic","zh":"他把床铺收拾好了。","pinyin":"Tā bǎ chuángpù shōushi hǎo le.","vi":"Anh ấy đã dọn dẹp giường gọn gàng."},{"type":"simple","zh":"宿舍里上下两层的床铺又窄又硬。","pinyin":"Sùshè lǐ shàngxià liǎng céng de chuángpù yòu zhǎi yòu yìng.","vi":"Giường hai tầng trong ký túc xá vừa hẹp vừa cứng."},{"type":"compound","zh":"因为火车上的床铺太短，所以他整晚都没睡好。","pinyin":"Yīnwèi huǒchē shàng de chuángpù tài duǎn, suǒyǐ tā zhěng wǎn dōu méi shuì hǎo.","vi":"Vì giường trên tàu hỏa quá ngắn nên anh ấy cả đêm ngủ không ngon."}],"related":[{"hanzi":"床","pinyin":"chuáng","vi":"giường"},{"hanzi":"被褥","pinyin":"bèirù","vi":"chăn đệm"},{"hanzi":"床单","pinyin":"chuángdān","vi":"ga trải giường"},{"hanzi":"铺床","pinyin":"pūchuáng","vi":"trải giường"}],"traditional":"床鋪"},{"id":"捶","hanzi":"捶","pinyin":"chuí","meaning_vi":"đấm, nện (lưng/ngực)","explanation":"Bộ tài gảy 扌+ 垂.","hsk_level":6,"tags":["dong-tu"],"image":"👊","examples":[{"type":"basic","zh":"她轻轻捶着腰。","pinyin":"Tā qīngqīng chuízhe yāo.","vi":"Cô ấy khẽ đấm lưng."},{"type":"simple","zh":"孙女每天晚上都给奶奶捶背。","pinyin":"Sūnnǚ měitiān wǎnshang dōu gěi nǎinai chuíbèi.","vi":"Tối nào cháu gái cũng đấm lưng cho bà."},{"type":"compound","zh":"他一听到比赛输了，就气得直捶桌子。","pinyin":"Tā yì tīngdào bǐsài shū le, jiù qì dezhí chuí zhuōzi.","vi":"Vừa nghe tin thua trận, anh ấy tức đến mức đấm bàn liên tục."}],"related":[{"hanzi":"捶背","pinyin":"chuíbèi","vi":"đấm lưng"},{"hanzi":"敲","pinyin":"qiāo","vi":"gõ"},{"hanzi":"打","pinyin":"dǎ","vi":"đánh"},{"hanzi":"捶胸顿足","pinyin":"chuíxiōngdùnzú","vi":"đấm ngực giậm chân"}]},{"id":"垂头丧气","hanzi":"垂头丧气","pinyin":"chuítóu-sàngqì","meaning_vi":"cúi đầu ủ rũ, chán nản thất vọng","explanation":"垂头 (thùy đầu – cúi đầu) + 丧气 (tang khí – mất tinh thần) → cúi gằm đầu, mất hết khí thế → ủ rũ, chán nản vì thất bại.","hsk_level":6,"tags":["thanh-ngu","cam-xuc"],"image":"😞","examples":[{"type":"basic","zh":"他垂头丧气地回家了。","pinyin":"Tā chuítóusàngqì de huíjiā le.","vi":"Anh ấy ủ rũ đi về nhà."},{"type":"simple","zh":"落选的队员们垂头丧气地坐在更衣室里。","pinyin":"Luòxuǎn de duìyuánmen chuítóusàngqì de zuò zài gēngyīshì lǐ.","vi":"Các cầu thủ bị loại ngồi ủ rũ trong phòng thay đồ."},{"type":"compound","zh":"即使这次面试失败了，你也不必垂头丧气。","pinyin":"Jíshǐ zhè cì miànshì shībài le, nǐ yě búbì chuítóusàngqì.","vi":"Dù lần phỏng vấn này thất bại, bạn cũng không cần phải chán nản."}],"related":[{"hanzi":"无精打采","pinyin":"wújīngdǎcǎi","vi":"uể oải"},{"hanzi":"灰心丧气","pinyin":"huīxīnsàngqì","vi":"nản lòng thoái chí"},{"hanzi":"沮丧","pinyin":"jǔsàng","vi":"chán nản"},{"hanzi":"昂首挺胸","pinyin":"ángshǒutǐngxiōng","vi":"ngẩng cao đầu"}],"traditional":"垂頭喪氣"},{"id":"垂直","hanzi":"垂直","pinyin":"chuízhí","meaning_vi":"thẳng đứng; vuông góc","explanation":"垂 (thùy – rủ xuống) + 直 (trực – thẳng) → thẳng đứng; trong toán học là vuông góc (两条线互相垂直).","hsk_level":6,"tags":["tinh-tu"],"image":"⬇️","examples":[{"type":"basic","zh":"这两条线互相垂直。","pinyin":"Zhè liǎng tiáo xiàn hùxiāng chuízhí.","vi":"Hai đường thẳng này vuông góc với nhau."},{"type":"simple","zh":"工人把旗杆垂直地立在广场中央。","pinyin":"Gōngrén bǎ qígān chuízhí de lì zài guǎngchǎng zhōngyāng.","vi":"Công nhân dựng cột cờ thẳng đứng ở giữa quảng trường."},{"type":"compound","zh":"如果墙面不垂直，挂上去的画就会歪。","pinyin":"Rúguǒ qiángmiàn bù chuízhí, guà shàngqù de huà jiù huì wāi.","vi":"Nếu mặt tường không thẳng đứng, bức tranh treo lên sẽ bị lệch."}],"related":[{"hanzi":"水平","pinyin":"shuǐpíng","vi":"nằm ngang"},{"hanzi":"竖直","pinyin":"shùzhí","vi":"thẳng đứng"},{"hanzi":"平行","pinyin":"píngxíng","vi":"song song"},{"hanzi":"垂线","pinyin":"chuíxiàn","vi":"đường vuông góc"}]},{"id":"绰绰有余","hanzi":"绰绰有余","pinyin":"chuòchuò-yǒuyú","meaning_vi":"dư dả thoải mái, thừa sức","explanation":"绰绰 (xước xước – rộng rãi) + 有余 (hữu dư – có thừa) → rộng rãi còn dư → dư dả, thừa sức đáp ứng. Ví dụ: 这些钱绰绰有余.","hsk_level":6,"tags":["thanh-ngu"],"image":"💰","examples":[{"type":"basic","zh":"这些钱绰绰有余。","pinyin":"Zhèxiē qián chuòchuòyǒuyú.","vi":"Số tiền này dư dả."},{"type":"simple","zh":"以他的水平，通过这次考试绰绰有余。","pinyin":"Yǐ tā de shuǐpíng, tōngguò zhè cì kǎoshì chuòchuòyǒuyú.","vi":"Với trình độ của anh ấy, qua kỳ thi này là thừa sức."},{"type":"compound","zh":"这间客厅既宽敞又明亮，坐十个人绰绰有余。","pinyin":"Zhè jiān kètīng jì kuānchang yòu míngliàng, zuò shí gè rén chuòchuòyǒuyú.","vi":"Phòng khách này vừa rộng vừa sáng, ngồi mười người vẫn dư chỗ."}],"related":[{"hanzi":"足够","pinyin":"zúgòu","vi":"đủ"},{"hanzi":"富余","pinyin":"fùyu","vi":"dư dả"},{"hanzi":"游刃有余","pinyin":"yóurènyǒuyú","vi":"thành thạo dư sức"},{"hanzi":"捉襟见肘","pinyin":"zhuōjīnjiànzhǒu","vi":"giật gấu vá vai"}],"traditional":"綽綽有餘"},{"id":"绰号","hanzi":"绰号","pinyin":"chuòhào","meaning_vi":"biệt danh, tên lóng","explanation":"绰 + 号 (tên gọi).","hsk_level":6,"tags":["danh-tu","con-nguoi"],"image":"📛","examples":[{"type":"basic","zh":"他的绰号叫小猴子。","pinyin":"Tā de chuòhào jiào xiǎo hóuzi.","vi":"Biệt danh của cậu ấy là Khỉ Con."},{"type":"simple","zh":"同学们给这个爱笑的女孩起了个绰号。","pinyin":"Tóngxuémen gěi zhè ge ài xiào de nǚhái qǐle gè chuòhào.","vi":"Các bạn học đặt cho cô bé hay cười này một biệt danh."},{"type":"compound","zh":"虽然这个绰号不太好听，但是他自己并不介意。","pinyin":"Suīrán zhè ge chuòhào bú tài hǎotīng, dànshì tā zìjǐ bìngbú jièyì.","vi":"Tuy biệt danh này không hay lắm, nhưng bản thân cậu ấy chẳng để bụng."}],"related":[{"hanzi":"外号","pinyin":"wàihào","vi":"biệt danh"},{"hanzi":"昵称","pinyin":"nìchēng","vi":"tên thân mật"},{"hanzi":"小名","pinyin":"xiǎomíng","vi":"tên ở nhà"},{"hanzi":"名字","pinyin":"míngzi","vi":"tên"}],"traditional":"綽號"},{"id":"穿针引线","hanzi":"穿针引线","pinyin":"chuānzhēn-yǐnxiàn","meaning_vi":"xâu kim luồn chỉ (làm cầu nối trung gian)","explanation":"穿针 (xuyên châm – xâu kim) + 引线 (dẫn tuyến – luồn chỉ) → xâu kim luồn chỉ → làm cầu nối, giới thiệu, môi giới cho hai bên.","hsk_level":6,"tags":["thanh-ngu"],"image":"🪡","examples":[{"type":"basic","zh":"这次合作是他穿针引线的。","pinyin":"Zhè cì hézuò shì tā chuānzhēnyǐnxiàn de.","vi":"Lần hợp tác này là do anh ấy làm cầu nối."},{"type":"simple","zh":"王老师为两所学校的交流穿针引线。","pinyin":"Wáng lǎoshī wèi liǎng suǒ xuéxiào de jiāoliú chuānzhēnyǐnxiàn.","vi":"Thầy Vương làm cầu nối cho sự giao lưu giữa hai trường."},{"type":"compound","zh":"如果没有她在中间穿针引线，这笔生意就谈不成。","pinyin":"Rúguǒ méiyǒu tā zài zhōngjiān chuānzhēnyǐnxiàn, zhè bǐ shēngyi jiù tán bùchéng.","vi":"Nếu không có cô ấy đứng giữa làm trung gian, vụ làm ăn này đã không thành."}],"related":[{"hanzi":"牵线搭桥","pinyin":"qiānxiàndāqiáo","vi":"làm cầu nối"},{"hanzi":"中介","pinyin":"zhōngjiè","vi":"trung gian"},{"hanzi":"介绍","pinyin":"jièshào","vi":"giới thiệu"},{"hanzi":"撮合","pinyin":"cuōhe","vi":"mai mối"}],"traditional":"穿針引線"},{"id":"创伤","hanzi":"创伤","pinyin":"chuāngshāng","meaning_vi":"vết thương, tổn thương (tâm lý/thể chất)","explanation":"创 (đọc chuāng - vết thương) + 伤.","hsk_level":6,"tags":["danh-tu","suc-khoe","cam-xuc"],"image":"💔","examples":[{"type":"basic","zh":"战争留下了创伤。","pinyin":"Zhànzhēng liúxiàle chuāngshāng.","vi":"Chiến tranh để lại vết thương."},{"type":"simple","zh":"那场车祸给他造成了很深的心理创伤。","pinyin":"Nà chǎng chēhuò gěi tā zào chéngle hěn shēn de xīnlǐ chuāngshāng.","vi":"Vụ tai nạn xe đó đã gây cho anh ấy tổn thương tâm lý rất sâu."},{"type":"compound","zh":"虽然伤口已经愈合，但是心里的创伤还需要时间。","pinyin":"Suīrán shāngkǒu yǐjīng yùhé, dànshì xīnlǐ de chuāngshāng hái xūyào shíjiān.","vi":"Tuy vết thương đã lành, nhưng tổn thương trong lòng vẫn cần thời gian."}],"related":[{"hanzi":"伤口","pinyin":"shāngkǒu","vi":"vết thương"},{"hanzi":"心理创伤","pinyin":"xīnlǐchuāngshāng","vi":"tổn thương tâm lý"},{"hanzi":"伤害","pinyin":"shānghài","vi":"tổn hại"},{"hanzi":"伤痕","pinyin":"shānghén","vi":"vết sẹo"}],"traditional":"創傷"},{"id":"疮痍","hanzi":"疮痍","pinyin":"chuāngyí","meaning_vi":"vết thương, cảnh điêu tàn sau chiến tranh/thiên tai","explanation":"Danh từ văn viết.","hsk_level":6,"tags":["danh-tu"],"image":"🏚️","examples":[{"type":"basic","zh":"地震后满目疮痍。","pinyin":"Dìzhèn hòu mǎnmù chuāngyí.","vi":"Sau động đất, khắp nơi tan hoang."},{"type":"simple","zh":"洪水过后，整个村庄一片疮痍。","pinyin":"Hóngshuǐ guòhòu, zhěnggè cūnzhuāng yípiàn chuāngyí.","vi":"Sau trận lũ, cả ngôi làng điêu tàn tan hoang."},{"type":"compound","zh":"虽然战后城市满目疮痍，但是人们很快开始了重建。","pinyin":"Suīrán zhànhòu chéngshì mǎnmù chuāngyí, dànshì rénmen hěn kuài kāishǐle chóngjiàn.","vi":"Tuy thành phố sau chiến tranh tan hoang khắp nơi, nhưng người dân nhanh chóng bắt tay tái thiết."}],"related":[{"hanzi":"满目疮痍","pinyin":"mǎnmùchuāngyí","vi":"khắp nơi tan hoang"},{"hanzi":"战乱","pinyin":"zhànluàn","vi":"chiến loạn"},{"hanzi":"破败","pinyin":"pòbài","vi":"đổ nát"},{"hanzi":"废墟","pinyin":"fèixū","vi":"đống đổ nát"}],"traditional":"瘡痍"},{"id":"吹毛求疵","hanzi":"吹毛求疵","pinyin":"chuīmáo-qiúcī","meaning_vi":"vạch lá tìm sâu, bới lông tìm vết","explanation":"吹毛 (thổi lông) + 求疵 (tìm vết). Thành ngữ.","hsk_level":6,"tags":["thanh-ngu"],"image":"🔍","examples":[{"type":"basic","zh":"老板总是吹毛求疵。","pinyin":"Lǎobǎn zǒngshì chuīmáoqiúcī.","vi":"Ông chủ lúc nào cũng bới lông tìm vết."},{"type":"simple","zh":"她对新来的实习生的报告吹毛求疵。","pinyin":"Tā duì xīn lái de shíxíshēng de bàogào chuīmáoqiúcī.","vi":"Cô ấy vạch lá tìm sâu bản báo cáo của thực tập sinh mới."},{"type":"compound","zh":"与其对别人吹毛求疵，不如先检查自己的问题。","pinyin":"Yǔqí duì biérén chuīmáoqiúcī, bùrú xiān jiǎnchá zìjǐ de wèntí.","vi":"Thay vì bới lông tìm vết người khác, chi bằng hãy xem lại vấn đề của chính mình trước."}],"related":[{"hanzi":"挑剔","pinyin":"tiāoti","vi":"kén chọn, bắt bẻ"},{"hanzi":"鸡蛋里挑骨头","pinyin":"jīdàn lǐ tiāo gǔtou","vi":"bới lông tìm vết"},{"hanzi":"苛求","pinyin":"kēqiú","vi":"đòi hỏi khắt khe"},{"hanzi":"宽容","pinyin":"kuānróng","vi":"khoan dung"}]},{"id":"喘气","hanzi":"喘气","pinyin":"chuǎnqì","meaning_vi":"thở hổn hển","explanation":"喘 (suyễn – thở gấp) + 气 (khí – hơi) → thở, thở hổn hển; cũng chỉ nghỉ lấy hơi. Ví dụ: 喘不过气来, 喘口气.","hsk_level":6,"tags":["dong-tu"],"image":"😮‍💨","examples":[{"type":"basic","zh":"他累得直喘气。","pinyin":"Tā lèi dezhí chuǎnqì.","vi":"Anh ấy mệt đến thở hổn hển."},{"type":"simple","zh":"爬到山顶后，大家坐在石头上喘气。","pinyin":"Pá dào shāndǐng hòu, dàjiā zuò zài shítou shàng chuǎnqì.","vi":"Leo lên đến đỉnh núi, mọi người ngồi trên tảng đá thở dốc."},{"type":"compound","zh":"他一口气跑上六楼，一进门就扶着墙喘气。","pinyin":"Tā yìkǒuqì pǎo shàng liù lóu, yí jìnmén jiù fúzhe qiáng chuǎnqì.","vi":"Anh ấy chạy một mạch lên tầng sáu, vừa vào cửa đã vịn tường thở hổn hển."}],"related":[{"hanzi":"呼吸","pinyin":"hūxī","vi":"hô hấp"},{"hanzi":"气喘吁吁","pinyin":"qìchuǎnxūxū","vi":"thở hổn hển"},{"hanzi":"喘息","pinyin":"chuǎnxī","vi":"thở dốc"},{"hanzi":"休息","pinyin":"xiūxi","vi":"nghỉ ngơi"}],"traditional":"喘氣"},{"id":"喘息","hanzi":"喘息","pinyin":"chuǎnxī","meaning_vi":"thở dốc, nghỉ lấy hơi","explanation":"喘 (thở gấp) + 息 (nghỉ).","hsk_level":6,"tags":["dong-tu"],"image":"😮‍💨","examples":[{"type":"basic","zh":"终于有了喘息的机会。","pinyin":"Zhōngyú yǒule chuǎnxī de jīhuì.","vi":"Cuối cùng cũng có cơ hội nghỉ lấy hơi."},{"type":"simple","zh":"连续加班一个月后，他请了三天假喘息一下。","pinyin":"Liánxù jiābān yí gèyuè hòu, tā qǐngle sān tiān jià chuǎnxī yíxià.","vi":"Sau một tháng tăng ca liên tục, anh ấy xin nghỉ ba ngày để thở một chút."},{"type":"compound","zh":"既然敌人已经撤退，就不能给他们喘息的时间。","pinyin":"Jìrán dírén yǐjīng chètuì, jiù bù néng gěi tāmen chuǎnxī de shíjiān.","vi":"Kẻ địch đã rút lui thì không thể cho chúng thời gian hồi sức."}],"related":[{"hanzi":"喘气","pinyin":"chuǎnqì","vi":"thở hổn hển"},{"hanzi":"休息","pinyin":"xiūxi","vi":"nghỉ ngơi"},{"hanzi":"喘息之机","pinyin":"chuǎnxīzhījī","vi":"cơ hội nghỉ lấy hơi"},{"hanzi":"呼吸","pinyin":"hūxī","vi":"hô hấp"}]},{"id":"刹那间","hanzi":"刹那间","pinyin":"chànàjiān","meaning_vi":"trong chớp mắt","explanation":"刹那 (sát-na, phiên âm tiếng Phạn kṣaṇa – khoảnh khắc cực ngắn) + 间 (gian – khoảng) → trong nháy mắt, chớp mắt.","hsk_level":6,"tags":["pho-tu","thoi-gian"],"image":"⚡","examples":[{"type":"basic","zh":"刹那间灯全灭了。","pinyin":"Chànàjiān dēng quán miè le.","vi":"Trong chớp mắt, đèn tắt hết."},{"type":"simple","zh":"烟花升空，刹那间照亮了整个夜空。","pinyin":"Yānhuā shēngkōng, chànàjiān zhàoliàngle zhěnggè yèkōng.","vi":"Pháo hoa bay lên, trong chớp mắt soi sáng cả bầu trời đêm."},{"type":"compound","zh":"他一推开门，刹那间所有人都安静了下来。","pinyin":"Tā yì tuī kāimén, chànàjiān suǒyǒurén dōu ānjìngle xiàlái.","vi":"Anh ấy vừa đẩy cửa, trong tích tắc mọi người đều im lặng."}],"related":[{"hanzi":"一瞬间","pinyin":"yíshùnjiān","vi":"trong nháy mắt"},{"hanzi":"顷刻","pinyin":"qǐngkè","vi":"chốc lát"},{"hanzi":"转眼","pinyin":"zhuǎnyǎn","vi":"chớp mắt"},{"hanzi":"霎时","pinyin":"shàshí","vi":"thoáng chốc"}],"traditional":"刹那間"},{"id":"诧异","hanzi":"诧异","pinyin":"chàyì","meaning_vi":"kinh ngạc","explanation":"诧 (sá – ngạc nhiên) + 异 (dị – lạ) → thấy lạ mà ngạc nhiên. Thường: 感到诧异, 诧异地看着他.","hsk_level":6,"tags":["tinh-tu"],"image":"😲","examples":[{"type":"basic","zh":"她诧异地看着我。","pinyin":"Tā chàyì de kànzhe wǒ.","vi":"Cô ấy kinh ngạc nhìn tôi."},{"type":"simple","zh":"听到他辞职的消息，同事们都很诧异。","pinyin":"Tīngdào tā cízhí de xiāoxi, tóngshìmen dōu hěn chàyì.","vi":"Nghe tin anh ấy nghỉ việc, đồng nghiệp đều rất kinh ngạc."},{"type":"compound","zh":"因为他平时很少说话，所以今天的发言让大家十分诧异。","pinyin":"Yīnwèi tā píngshí hěn shǎo shuōhuà, suǒyǐ jīntiān de fāyán ràng dàjiā shífēn chàyì.","vi":"Vì bình thường anh ấy ít nói nên bài phát biểu hôm nay khiến mọi người hết sức ngạc nhiên."}],"related":[{"hanzi":"惊讶","pinyin":"jīngyà","vi":"ngạc nhiên"},{"hanzi":"惊奇","pinyin":"jīngqí","vi":"kinh ngạc"},{"hanzi":"吃惊","pinyin":"chījīng","vi":"giật mình"},{"hanzi":"奇怪","pinyin":"qíguài","vi":"kỳ lạ"}],"traditional":"詫異"},{"id":"姹紫嫣红","hanzi":"姹紫嫣红","pinyin":"chàzǐ-yānhóng","meaning_vi":"muôn hồng nghìn tía (hoa nở rực rỡ)","explanation":"姹 (xá – đẹp) + 紫 (tử – tím) + 嫣 (yên – tươi đẹp) + 红 (hồng – đỏ) → tím đẹp hồng tươi (gốc vở Mẫu Đơn Đình) → hoa nở muôn màu rực rỡ.","hsk_level":6,"tags":["thanh-ngu","thien-nhien"],"image":"🌺","examples":[{"type":"basic","zh":"花园里姹紫嫣红。","pinyin":"Huāyuán lǐ chàzǐyānhóng.","vi":"Trong vườn hoa muôn hồng nghìn tía."},{"type":"simple","zh":"四月的公园里，各种花开得姹紫嫣红。","pinyin":"Sìyuè de gōngyuán lǐ, gè zhǒnghuā kāi de chàzǐyānhóng.","vi":"Công viên tháng tư, đủ loại hoa nở rực rỡ sắc màu."},{"type":"compound","zh":"一到春天，山坡上就变得姹紫嫣红，美极了。","pinyin":"Yí dào chūntiān, shānpō shàng jiù biànde chàzǐyānhóng, měi jíle.","vi":"Hễ đến mùa xuân, sườn đồi lại rực rỡ muôn sắc hoa, đẹp vô cùng."}],"related":[{"hanzi":"百花齐放","pinyin":"bǎihuāqífàng","vi":"trăm hoa đua nở"},{"hanzi":"五彩缤纷","pinyin":"wǔcǎibīnfēn","vi":"sặc sỡ nhiều màu"},{"hanzi":"春暖花开","pinyin":"chūnnuǎnhuākāi","vi":"xuân ấm hoa nở"},{"hanzi":"鲜艳","pinyin":"xiānyàn","vi":"tươi sáng"}],"traditional":"姹紫嫣紅"},{"id":"颤抖","hanzi":"颤抖","pinyin":"chàndǒu","meaning_vi":"run rẩy","explanation":"颤 (chiến – rung) + 抖 (đẩu – run) → run rẩy. Ví dụ: 冷得浑身颤抖, 声音颤抖.","hsk_level":6,"tags":["dong-tu"],"image":"🥶","examples":[{"type":"basic","zh":"他冷得浑身颤抖。","pinyin":"Tā lěng de húnshēn chàndǒu.","vi":"Anh ấy lạnh đến run cả người."},{"type":"simple","zh":"她用颤抖的手打开了那封旧信。","pinyin":"Tā yòng chàndǒu de shǒu dǎkāile nà fēng jiù xìn.","vi":"Cô ấy dùng đôi tay run rẩy mở lá thư cũ."},{"type":"compound","zh":"虽然他努力保持镇定，但是声音还是在颤抖。","pinyin":"Suīrán tā nǔlì bǎochí zhèndìng, dànshì shēngyīn háishi zài chàndǒu.","vi":"Tuy cố giữ bình tĩnh, nhưng giọng anh ấy vẫn run run."}],"related":[{"hanzi":"发抖","pinyin":"fādǒu","vi":"run"},{"hanzi":"哆嗦","pinyin":"duōsuo","vi":"lập cập"},{"hanzi":"颤动","pinyin":"chàndòng","vi":"rung động"},{"hanzi":"战栗","pinyin":"zhànlì","vi":"run sợ"}],"traditional":"顫抖"},{"id":"颤巍巍","hanzi":"颤巍巍","pinyin":"chànwēiwēi","meaning_vi":"run rẩy, lẩy bẩy (người già)","explanation":"颤 (chiến – run) + 巍巍 (nguy nguy – lắc lư, chênh vênh) → run run, lẩy bẩy, thường tả dáng người già, người yếu. Cụm: 颤巍巍地站起来.","hsk_level":6,"tags":["tinh-tu"],"image":"👴","examples":[{"type":"basic","zh":"老奶奶颤巍巍地站起来。","pinyin":"Lǎonǎinai chànwēiwēi de zhànqǐlái.","vi":"Bà cụ lẩy bẩy đứng dậy."},{"type":"simple","zh":"老人颤巍巍地拄着拐杖走进了药店。","pinyin":"Lǎorén chànwēiwēi de zhǔzhe guǎizhàng zǒujìnle yàodiàn.","vi":"Cụ già run rẩy chống gậy bước vào hiệu thuốc."},{"type":"compound","zh":"爷爷虽然已经九十岁了，但是还颤巍巍地坚持去菜园浇水。","pinyin":"Yéye suīrán yǐjīng jiǔshí suì le, dànshì hái chànwēiwēi de jiānchí qù càiyuán jiāoshuǐ.","vi":"Ông nội tuy đã chín mươi tuổi, nhưng vẫn lẩy bẩy kiên trì ra vườn tưới rau."}],"related":[{"hanzi":"颤抖","pinyin":"chàndǒu","vi":"run rẩy"},{"hanzi":"摇摇晃晃","pinyin":"yáoyaohuànghuàng","vi":"lảo đảo"},{"hanzi":"老态龙钟","pinyin":"lǎotàilóngzhōng","vi":"già yếu lụ khụ"},{"hanzi":"哆嗦","pinyin":"duōsuo","vi":"lập cập"}],"traditional":"顫巍巍"},{"id":"倡导","hanzi":"倡导","pinyin":"chàngdǎo","meaning_vi":"khởi xướng","explanation":"倡 (xướng – đề xướng) + 导 (đạo – dẫn dắt) → khởi xướng và dẫn dắt (thực hiện điều tốt). Thường: 倡导环保, 倡导节约.","hsk_level":6,"tags":["dong-tu"],"image":"📢","examples":[{"type":"basic","zh":"学校倡导节约用水。","pinyin":"Xuéxiào chàngdǎo jiéyuē yòng shuǐ.","vi":"Nhà trường khởi xướng tiết kiệm nước."},{"type":"simple","zh":"这个城市大力倡导市民骑自行车出行。","pinyin":"Zhè ge chéngshì dàlì chàngdǎo shìmín qí zìxíngchē chūxíng.","vi":"Thành phố này tích cực khuyến khích người dân đi lại bằng xe đạp."},{"type":"compound","zh":"政府不但倡导垃圾分类，而且在每个小区设置了回收点。","pinyin":"Zhèngfǔ búdàn chàngdǎo lājīfēnlèi, érqiě zài měi gè xiǎoqū shèzhìle huíshōu diǎn.","vi":"Chính quyền không chỉ khởi xướng phân loại rác mà còn đặt điểm thu gom ở mỗi khu dân cư."}],"related":[{"hanzi":"提倡","pinyin":"tíchàng","vi":"đề xướng"},{"hanzi":"倡议","pinyin":"chàngyì","vi":"kiến nghị"},{"hanzi":"主张","pinyin":"zhǔzhāng","vi":"chủ trương"},{"hanzi":"号召","pinyin":"hàozhào","vi":"kêu gọi"}],"traditional":"倡導"},{"id":"畅所欲言","hanzi":"畅所欲言","pinyin":"chàngsuǒ-yùyán","meaning_vi":"thoải mái phát biểu điều mình muốn nói","explanation":"畅 (thỏa thích) + 所欲言 (điều muốn nói). Thành ngữ.","hsk_level":6,"tags":["thanh-ngu","giao-tiep"],"image":"🗣️","examples":[{"type":"basic","zh":"请大家畅所欲言。","pinyin":"Qǐng dàjiā chàngsuǒyùyán.","vi":"Xin mọi người cứ thoải mái phát biểu."},{"type":"simple","zh":"座谈会上，员工们对公司的管理畅所欲言。","pinyin":"Zuòtánhuì shàng, yuángōngmen duì gōngsī de guǎnlǐ chàngsuǒyùyán.","vi":"Tại buổi tọa đàm, nhân viên thoải mái nói lên ý kiến về cách quản lý của công ty."},{"type":"compound","zh":"只要气氛轻松，学生们就敢在课堂上畅所欲言。","pinyin":"Zhǐyào qìfēn qīngsōng, xuéshēngmen jiù gǎn zài kètáng shàng chàngsuǒyùyán.","vi":"Chỉ cần không khí thoải mái, học sinh sẽ dám nói hết suy nghĩ trong lớp."}],"related":[{"hanzi":"各抒己见","pinyin":"gèshūjǐjiàn","vi":"mỗi người nêu ý kiến"},{"hanzi":"直言不讳","pinyin":"zhíyánbúhuì","vi":"nói thẳng không kiêng nể"},{"hanzi":"知无不言","pinyin":"zhīwúbùyán","vi":"biết gì nói nấy"},{"hanzi":"沉默不语","pinyin":"chénmòbùyǔ","vi":"im lặng không nói"}],"traditional":"暢所欲言"},{"id":"畅谈","hanzi":"畅谈","pinyin":"chàngtán","meaning_vi":"trò chuyện thoải mái, tâm sự say sưa","explanation":"畅 + 谈 (nói chuyện).","hsk_level":6,"tags":["dong-tu","giao-tiep"],"image":"☕","examples":[{"type":"basic","zh":"老友相聚畅谈往事。","pinyin":"Lǎoyǒu xiāngjù chàngtán wǎngshì.","vi":"Bạn cũ gặp nhau say sưa trò chuyện chuyện xưa."},{"type":"simple","zh":"两位校友在咖啡馆里畅谈了一个下午。","pinyin":"Liǎng wèi xiàoyǒu zài kāfēiguǎn lǐ chàngtánle yí gè xiàwǔ.","vi":"Hai cựu sinh viên trò chuyện thỏa thích cả buổi chiều trong quán cà phê."},{"type":"compound","zh":"我们一见如故，一坐下就畅谈到了深夜。","pinyin":"Wǒmen yí jiàn rúgù, yí zuòxià jiù chàng tándàole shēnyè.","vi":"Chúng tôi vừa gặp đã thân, vừa ngồi xuống là trò chuyện say sưa đến tận khuya."}],"related":[{"hanzi":"交谈","pinyin":"jiāotán","vi":"trò chuyện"},{"hanzi":"聊天","pinyin":"liáotiān","vi":"tán gẫu"},{"hanzi":"畅所欲言","pinyin":"chàngsuǒyùyán","vi":"nói thoải mái"},{"hanzi":"谈心","pinyin":"tánxīn","vi":"tâm sự"}],"traditional":"暢談"},{"id":"畅通无阻","hanzi":"畅通无阻","pinyin":"chàngtōng-wúzǔ","meaning_vi":"thông suốt không gặp trở ngại","explanation":"畅通 (sướng thông – thông suốt) + 无阻 (vô trở – không trở ngại) → thông suốt, không gì cản trở. Thường nói giao thông, thông tin: 道路畅通无阻.","hsk_level":6,"tags":["thanh-ngu","giao-thong"],"image":"🛣️","examples":[{"type":"basic","zh":"今天道路畅通无阻。","pinyin":"Jīntiān dàolù chàngtōngwúzǔ.","vi":"Hôm nay đường sá thông suốt."},{"type":"simple","zh":"新隧道开通后，进城的车辆畅通无阻。","pinyin":"Xīn suìdào kāitōng hòu, jìnchéng de chēliàng chàngtōngwúzǔ.","vi":"Sau khi đường hầm mới thông xe, xe vào thành phố đi lại thông suốt."},{"type":"compound","zh":"只要有了这张通行证，你在园区里就能畅通无阻。","pinyin":"Zhǐyào yǒule zhè zhāng tōngxíngzhèng, nǐ zài yuánqū lǐ jiù néng chàngtōngwúzǔ.","vi":"Chỉ cần có tấm thẻ thông hành này, bạn có thể đi lại không trở ngại trong khu."}],"related":[{"hanzi":"一路畅通","pinyin":"yílùchàngtōng","vi":"đi suốt không vướng"},{"hanzi":"顺畅","pinyin":"shùnchàng","vi":"trôi chảy"},{"hanzi":"交通","pinyin":"jiāotōng","vi":"giao thông"},{"hanzi":"堵塞","pinyin":"dǔsè","vi":"tắc nghẽn"}],"traditional":"暢通無阻"},{"id":"倡议书","hanzi":"倡议书","pinyin":"chàngyìshū","meaning_vi":"thư kêu gọi, bản kiến nghị","explanation":"倡议 + 书 (văn bản).","hsk_level":6,"tags":["danh-tu","xa-hoi"],"image":"📜","examples":[{"type":"basic","zh":"他起草了一份倡议书。","pinyin":"Tā qǐcǎole yí fèn chàngyìshū.","vi":"Anh ấy đã soạn thảo một bản thư kêu gọi."},{"type":"simple","zh":"学生会在食堂门口贴出了节约粮食的倡议书。","pinyin":"Xuéshēnghuì zài shítáng ménkǒu tiē chūle jiéyuē liángshi de chàngyìshū.","vi":"Hội sinh viên dán thư kêu gọi tiết kiệm lương thực trước cửa nhà ăn."},{"type":"compound","zh":"倡议书一发出，就得到了全校师生的积极响应。","pinyin":"Chàngyìshū yì fāchū, jiù dédàole quán xiào shīshēng de jījí xiǎngyìng.","vi":"Thư kêu gọi vừa được phát đi đã nhận được sự hưởng ứng tích cực của toàn thể thầy trò."}],"related":[{"hanzi":"倡议","pinyin":"chàngyì","vi":"kiến nghị"},{"hanzi":"建议书","pinyin":"jiànyìshū","vi":"thư kiến nghị"},{"hanzi":"号召","pinyin":"hàozhào","vi":"kêu gọi"},{"hanzi":"呼吁","pinyin":"hūyù","vi":"kêu gọi"}],"traditional":"倡議書"},{"id":"查获","hanzi":"查获","pinyin":"cháhuò","meaning_vi":"khám xét thu giữ, phát hiện bắt giữ","explanation":"查 (tra – kiểm tra, điều tra) + 获 (hoạch – thu được) → điều tra và thu giữ (tang vật, tội phạm). Thường: 查获毒品, 查获走私货物.","hsk_level":6,"tags":["dong-tu"],"image":"🚔","examples":[{"type":"basic","zh":"警方查获了一批毒品。","pinyin":"Jǐngfāng cháhuòle yìpī dúpǐn.","vi":"Cảnh sát đã thu giữ một lô ma túy."},{"type":"simple","zh":"海关在一辆货车里查获了大量走私香烟。","pinyin":"Hǎiguān zài yí liàng huòchē lǐ cháhuòle dàliàng zǒusī xiāngyān.","vi":"Hải quan đã thu giữ một lượng lớn thuốc lá lậu trong một xe tải."},{"type":"compound","zh":"虽然走私分子藏得很隐蔽，但是还是被警察查获了。","pinyin":"Suīrán zǒusī fènzǐ cáng de hěn yǐnbì, dànshì háishi bèi jǐngchá cháhuò le.","vi":"Tuy bọn buôn lậu giấu rất kín, nhưng vẫn bị cảnh sát phát hiện bắt giữ."}],"related":[{"hanzi":"破获","pinyin":"pòhuò","vi":"phá án bắt được"},{"hanzi":"缴获","pinyin":"jiǎohuò","vi":"thu giữ"},{"hanzi":"没收","pinyin":"mòshōu","vi":"tịch thu"},{"hanzi":"查处","pinyin":"cháchǔ","vi":"điều tra xử lý"}],"traditional":"查獲"},{"id":"查明","hanzi":"查明","pinyin":"chámíng","meaning_vi":"điều tra làm rõ","explanation":"查 (kiểm tra) + 明 (rõ ràng).","hsk_level":6,"tags":["dong-tu","phap-luat"],"image":"🔍","examples":[{"type":"basic","zh":"事故原因已经查明。","pinyin":"Shìgù yuányīn yǐjīng chámíng.","vi":"Nguyên nhân tai nạn đã được làm rõ."},{"type":"simple","zh":"消防部门正在查明这场火灾的起因。","pinyin":"Xiāofáng bùmén zhèngzài chámíng zhè chǎng huǒzāi de qǐyīn.","vi":"Cơ quan phòng cháy đang điều tra làm rõ nguyên nhân vụ cháy."},{"type":"compound","zh":"只有彻底查明真相，才能还他一个清白。","pinyin":"Zhǐyǒu chèdǐ chámíng zhēnxiàng, cáinéng huán tā yí gè qīngbái.","vi":"Chỉ có điều tra làm rõ sự thật mới có thể trả lại sự trong sạch cho anh ấy."}],"related":[{"hanzi":"调查","pinyin":"diàochá","vi":"điều tra"},{"hanzi":"弄清","pinyin":"nòngqīng","vi":"làm rõ"},{"hanzi":"查明真相","pinyin":"chámíngzhēnxiàng","vi":"làm rõ sự thật"},{"hanzi":"核实","pinyin":"héshí","vi":"kiểm chứng"}]},{"id":"察言观色","hanzi":"察言观色","pinyin":"cháyán-guānsè","meaning_vi":"nhìn sắc mặt đoán ý người","explanation":"察言 (sát ngôn – xét lời nói) + 观色 (quan sắc – nhìn sắc mặt) → xét lời nói, nhìn sắc mặt → đoán ý người khác để ứng xử cho khéo.","hsk_level":6,"tags":["thanh-ngu","giao-tiep"],"image":"👀","examples":[{"type":"basic","zh":"她很会察言观色。","pinyin":"Tā hěn huì cháyánguānsè.","vi":"Cô ấy rất giỏi nhìn mặt đoán ý."},{"type":"simple","zh":"新来的秘书很擅长察言观色。","pinyin":"Xīn lái de mìshū hěn shàncháng cháyánguānsè.","vi":"Cô thư ký mới rất giỏi quan sát sắc mặt đoán ý người."},{"type":"compound","zh":"因为他善于察言观色，所以总能说出领导想听的话。","pinyin":"Yīnwèi tā shànyú cháyánguānsè, suǒyǐ zǒngnéng shuōchū lǐngdǎo xiǎng tīng dehuà.","vi":"Vì giỏi nhìn mặt đoán ý nên anh ta luôn nói được những lời lãnh đạo muốn nghe."}],"related":[{"hanzi":"看脸色","pinyin":"kànliǎnsè","vi":"nhìn sắc mặt"},{"hanzi":"观察","pinyin":"guānchá","vi":"quan sát"},{"hanzi":"见机行事","pinyin":"jiànjīxíngshì","vi":"tùy cơ ứng biến"},{"hanzi":"揣摩","pinyin":"chuǎimó","vi":"đoán ý"}],"traditional":"察言觀色"},{"id":"茶余饭后","hanzi":"茶余饭后","pinyin":"cháyú-fànhòu","meaning_vi":"lúc rảnh rỗi sau bữa cơm chén trà","explanation":"茶余 (trà dư – sau khi uống trà) + 饭后 (phạn hậu – sau bữa cơm) → lúc nghỉ ngơi nhàn rỗi. Thường: 茶余饭后的话题 (chuyện bàn tán lúc rảnh).","hsk_level":6,"tags":["thanh-ngu","sinh-hoat"],"image":"🍵","examples":[{"type":"basic","zh":"这成了茶余饭后的话题。","pinyin":"Zhè chéngle cháyúfànhòu de huàtí.","vi":"Chuyện này trở thành đề tài bàn tán lúc rảnh rỗi."},{"type":"simple","zh":"邻居们茶余饭后最爱聊小区里的新鲜事。","pinyin":"Línjūmen cháyúfànhòu zuì ài liáo xiǎoqū lǐ de xīnxiān shì.","vi":"Lúc rảnh rỗi sau bữa ăn, hàng xóm thích nhất là bàn chuyện mới trong khu."},{"type":"compound","zh":"虽然只是茶余饭后的闲谈，但是这些话还是传到了他耳朵里。","pinyin":"Suīrán zhǐshì cháyúfànhòu de xiántán, dànshì zhèxiē huà háishi chuán dàole tā ěrduo lǐ.","vi":"Tuy chỉ là chuyện phiếm lúc rảnh rỗi, nhưng những lời này vẫn lọt đến tai anh ấy."}],"related":[{"hanzi":"闲暇","pinyin":"xiánxiá","vi":"lúc rảnh rỗi"},{"hanzi":"业余","pinyin":"yèyú","vi":"thời gian ngoài giờ"},{"hanzi":"聊天","pinyin":"liáotiān","vi":"tán gẫu"},{"hanzi":"话题","pinyin":"huàtí","vi":"đề tài"}],"traditional":"茶餘飯後"},{"id":"馋","hanzi":"馋","pinyin":"chán","meaning_vi":"thèm ăn","explanation":"馋 (sàm) → thèm ăn, háo ăn; cũng là thèm muốn nói chung. Ví dụ: 嘴馋, 馋猫 (người tham ăn), 看得我直馋.","hsk_level":6,"tags":["tinh-tu"],"image":"🤤","examples":[{"type":"basic","zh":"这孩子嘴真馋。","pinyin":"Zhè háizi zuǐ zhēn chán.","vi":"Đứa bé này thật tham ăn."},{"type":"simple","zh":"闻到烤肉的香味，弟弟馋得直流口水。","pinyin":"Wéndào kǎoròu de xiāngwèi, dìdi chán dezhí liúkǒushuǐ.","vi":"Ngửi thấy mùi thịt nướng, em trai thèm đến chảy nước miếng."},{"type":"compound","zh":"我一看到街边的糖葫芦，就馋得走不动路。","pinyin":"Wǒ yí kàndào jiē biān de tánghúlu, jiù chán de zǒu búdòng lù.","vi":"Tôi hễ thấy kẹo hồ lô bên đường là thèm đến mức không bước nổi."}],"related":[{"hanzi":"嘴馋","pinyin":"zuǐchán","vi":"thèm ăn"},{"hanzi":"贪吃","pinyin":"tānchī","vi":"tham ăn"},{"hanzi":"馋猫","pinyin":"chánmāo","vi":"người háu ăn"},{"hanzi":"流口水","pinyin":"liúkǒushuǐ","vi":"chảy nước miếng"}],"traditional":"饞"},{"id":"禅宗","hanzi":"禅宗","pinyin":"Chánzōng","meaning_vi":"Thiền tông","explanation":"禅 (thiền) + 宗 (tông phái).","hsk_level":6,"tags":["danh-tu","van-hoa"],"image":"🧘","examples":[{"type":"basic","zh":"他对禅宗很感兴趣。","pinyin":"Tā duì Chánzōng hěn gǎnxìngqù.","vi":"Anh ấy rất hứng thú với Thiền tông."},{"type":"simple","zh":"禅宗对日本的茶道产生了深远的影响。","pinyin":"Chánzōng duì Rìběn de chádào chǎnshēngle shēnyuǎn de yǐngxiǎng.","vi":"Thiền tông đã ảnh hưởng sâu rộng đến trà đạo Nhật Bản."},{"type":"compound","zh":"禅宗不但主张静心修行，而且重视在日常生活中领悟。","pinyin":"Chánzōng búdàn zhǔzhāng jìngxīn xiūxíng, érqiě zhòngshì zài rìcháng shēnghuó zhōng lǐngwù.","vi":"Thiền tông không chỉ chủ trương tĩnh tâm tu hành mà còn coi trọng sự giác ngộ trong đời sống thường ngày."}],"related":[{"hanzi":"佛教","pinyin":"Fójiào","vi":"Phật giáo"},{"hanzi":"和尚","pinyin":"héshang","vi":"hòa thượng"},{"hanzi":"寺庙","pinyin":"sìmiào","vi":"chùa chiền"},{"hanzi":"坐禅","pinyin":"zuòchán","vi":"ngồi thiền"}],"traditional":"禪宗"},{"id":"偿付","hanzi":"偿付","pinyin":"chángfù","meaning_vi":"thanh toán, trả nợ","explanation":"偿 (trả) + 付 (trả tiền).","hsk_level":6,"tags":["dong-tu","tien-te"],"image":"💳","examples":[{"type":"basic","zh":"公司无力偿付债务。","pinyin":"Gōngsī wúlì chángfù zhàiwù.","vi":"Công ty không có khả năng thanh toán nợ."},{"type":"simple","zh":"保险公司按合同偿付了全部维修费用。","pinyin":"Bǎoxiǎn gōngsī àn hétóng chángfùle quánbù wéixiū fèiyòng.","vi":"Công ty bảo hiểm đã chi trả toàn bộ chi phí sửa chữa theo hợp đồng."},{"type":"compound","zh":"如果到期不能偿付贷款，银行就会收回房子。","pinyin":"Rúguǒ dàoqī bù néng chángfù dàikuǎn, yínháng jiù huì shōuhuí fángzi.","vi":"Nếu đến hạn không trả được khoản vay, ngân hàng sẽ thu hồi nhà."}],"related":[{"hanzi":"偿还","pinyin":"chánghuán","vi":"hoàn trả"},{"hanzi":"支付","pinyin":"zhīfù","vi":"chi trả"},{"hanzi":"付款","pinyin":"fùkuǎn","vi":"trả tiền"},{"hanzi":"赔偿","pinyin":"péicháng","vi":"bồi thường"}],"traditional":"償付"},{"id":"偿还","hanzi":"偿还","pinyin":"chánghuán","meaning_vi":"hoàn trả","explanation":"偿 (thường – đền trả) + 还 (hoàn – trả lại) → hoàn trả (nợ nần). Thường: 偿还债务, 偿还贷款.","hsk_level":6,"tags":["dong-tu"],"image":"💸","examples":[{"type":"basic","zh":"他按时偿还了借款。","pinyin":"Tā ànshí chánghuánle jièkuǎn.","vi":"Anh ấy đã hoàn trả khoản vay đúng hạn."},{"type":"simple","zh":"她用了整整五年才偿还清助学贷款。","pinyin":"Tā yòngle zhěngzhěng wǔ nián cái chánghuán qīng zhùxué dàikuǎn.","vi":"Cô ấy mất tròn năm năm mới trả hết khoản vay học phí."},{"type":"compound","zh":"虽然生意失败了，但是他发誓一定要偿还所有欠款。","pinyin":"Suīrán shēngyi shībài le, dànshì tā fāshì yídìngyào chánghuán suǒyǒu qiànkuǎn.","vi":"Tuy làm ăn thất bại, nhưng anh ấy thề nhất định sẽ hoàn trả mọi khoản nợ."}],"related":[{"hanzi":"归还","pinyin":"guīhuán","vi":"trả lại"},{"hanzi":"还债","pinyin":"huánzhài","vi":"trả nợ"},{"hanzi":"偿付","pinyin":"chángfù","vi":"thanh toán"},{"hanzi":"借贷","pinyin":"jièdài","vi":"vay mượn"}],"traditional":"償還"},{"id":"常理","hanzi":"常理","pinyin":"chánglǐ","meaning_vi":"lẽ thường","explanation":"常 (thông thường) + 理 (lý lẽ).","hsk_level":6,"tags":["danh-tu"],"image":"💡","examples":[{"type":"basic","zh":"这不符合常理。","pinyin":"Zhèbù fúhé chánglǐ.","vi":"Điều này không hợp lẽ thường."},{"type":"simple","zh":"按常理说，这个时间他早该到家了。","pinyin":"Ànchánglǐ shuō, zhè ge shíjiān tā zǎo gāi dàojiā le.","vi":"Theo lẽ thường, giờ này anh ấy lẽ ra đã về đến nhà rồi."},{"type":"compound","zh":"既然这件事违背常理，那么背后一定另有原因。","pinyin":"Jìrán zhè jiàn shì wéibèi chánglǐ, nàme bèihòu yídìng lìngyǒu yuányīn.","vi":"Chuyện này đã trái với lẽ thường thì đằng sau ắt hẳn có nguyên nhân khác."}],"related":[{"hanzi":"常识","pinyin":"chángshí","vi":"thường thức"},{"hanzi":"道理","pinyin":"dàoli","vi":"đạo lý"},{"hanzi":"情理","pinyin":"qínglǐ","vi":"tình lý"},{"hanzi":"按常理","pinyin":"ànchánglǐ","vi":"theo lẽ thường"}]},{"id":"常年","hanzi":"常年","pinyin":"chángnián","meaning_vi":"quanh năm, nhiều năm liền","explanation":"常 (thường) + 年 (năm).","hsk_level":6,"tags":["pho-tu","thoi-gian"],"image":"📅","examples":[{"type":"basic","zh":"山顶常年积雪。","pinyin":"Shāndǐng chángnián jīxuě.","vi":"Đỉnh núi quanh năm phủ tuyết."},{"type":"simple","zh":"他父亲常年在海上跑运输。","pinyin":"Tā fùqīn chángnián zài hǎishàng pǎo yùnshū.","vi":"Bố anh ấy quanh năm chạy tàu vận tải trên biển."},{"type":"compound","zh":"因为常年坐在电脑前，所以他的颈椎出了毛病。","pinyin":"Yīnwèi chángnián zuò zài diànnǎo qián, suǒyǐ tā de jǐngzhuī chūle máobìng.","vi":"Vì nhiều năm liền ngồi trước máy tính nên cột sống cổ của anh ấy có vấn đề."}],"related":[{"hanzi":"终年","pinyin":"zhōngnián","vi":"quanh năm"},{"hanzi":"长年","pinyin":"chángnián","vi":"nhiều năm"},{"hanzi":"全年","pinyin":"quánnián","vi":"cả năm"},{"hanzi":"常年累月","pinyin":"chángniánlěiyuè","vi":"năm này qua năm khác"}]},{"id":"长年累月","hanzi":"长年累月","pinyin":"chángnián-lěiyuè","meaning_vi":"năm này qua tháng nọ, thời gian dài","explanation":"长年 (trường niên – nhiều năm) + 累月 (lũy nguyệt – chồng chất tháng) → năm này qua tháng khác → thời gian rất dài.","hsk_level":6,"tags":["thanh-ngu","thoi-gian"],"image":"⏳","examples":[{"type":"basic","zh":"他长年累月地工作。","pinyin":"Tā chángniánlěiyuè de gōngzuò.","vi":"Anh ấy làm việc năm này qua tháng nọ."},{"type":"simple","zh":"长年累月的风吹日晒让这扇木门褪了色。","pinyin":"Chángniánlěiyuè de fēng chuī rì shài ràng zhè shàn mù mén tuìle sè.","vi":"Nắng gió năm này qua tháng nọ khiến cánh cửa gỗ này bạc màu."},{"type":"compound","zh":"只要长年累月地坚持练字，你的书法就会有明显进步。","pinyin":"Zhǐyào chángniánlěiyuè de jiānchí liànzì, nǐ de shūfǎ jiù huì yǒu míngxiǎn jìnbù.","vi":"Chỉ cần kiên trì luyện chữ năm này qua tháng nọ, thư pháp của bạn sẽ tiến bộ rõ rệt."}],"related":[{"hanzi":"日积月累","pinyin":"rìjīyuèlěi","vi":"ngày qua tháng lại tích lũy"},{"hanzi":"年复一年","pinyin":"niánfùyìnián","vi":"năm này qua năm khác"},{"hanzi":"长期","pinyin":"chángqī","vi":"dài hạn"},{"hanzi":"一朝一夕","pinyin":"yìzhāoyìxī","vi":"một sớm một chiều"}],"traditional":"長年累月"},{"id":"常识性","hanzi":"常识性","pinyin":"chángshíxìng","meaning_vi":"mang tính thường thức","explanation":"常识 (thường thức – kiến thức phổ thông) + 性 (tính – tính chất) → mang tính thường thức, cơ bản ai cũng nên biết. Cụm: 常识性错误.","hsk_level":6,"tags":["tinh-tu"],"image":"🧠","examples":[{"type":"basic","zh":"这是常识性错误。","pinyin":"Zhè shì chángshíxìng cuòwù.","vi":"Đây là lỗi về kiến thức thông thường."},{"type":"simple","zh":"这本科普书介绍了很多常识性的安全知识。","pinyin":"Zhè běn kēpǔ shū jièshàole hěn duō chángshíxìng de ānquán zhīshi.","vi":"Cuốn sách phổ biến khoa học này giới thiệu nhiều kiến thức an toàn mang tính thường thức."},{"type":"compound","zh":"虽然这只是个常识性问题，但是很多人都答错了。","pinyin":"Suīrán zhè zhǐshì gè chángshíxìng wèntí, dànshì hěn duō rén dōu dá cuò le.","vi":"Tuy đây chỉ là câu hỏi mang tính thường thức, nhưng rất nhiều người đã trả lời sai."}],"related":[{"hanzi":"常识","pinyin":"chángshí","vi":"thường thức"},{"hanzi":"基本","pinyin":"jīběn","vi":"cơ bản"},{"hanzi":"知识","pinyin":"zhīshi","vi":"tri thức"},{"hanzi":"常识性错误","pinyin":"chángshíxìng cuòwù","vi":"lỗi sơ đẳng"}],"traditional":"常識性"},{"id":"常务","hanzi":"常务","pinyin":"chángwù","meaning_vi":"thường vụ, công việc thường trực","explanation":"常 (thường – thường xuyên) + 务 (vụ – việc) → thường vụ, phụ trách công việc thường ngày. Cụm: 常务副市长, 常务委员.","hsk_level":6,"tags":["tinh-tu","cong-viec","xa-hoi"],"image":"🏢","examples":[{"type":"basic","zh":"他是常务副市长。","pinyin":"Tā shì chángwù fùshìzhǎng.","vi":"Ông ấy là phó thị trưởng thường trực."},{"type":"simple","zh":"公司的日常管理由常务董事负责。","pinyin":"Gōngsī de rìcháng guǎn lǐyóu chángwù dǒngshì fùzé.","vi":"Việc quản lý hằng ngày của công ty do giám đốc thường trực phụ trách."},{"type":"compound","zh":"常务委员会一开完会，就公布了新的人事安排。","pinyin":"Chángwù wěiyuánhuì yì kāi wán huì, jiù gōngbùle xīn de rénshì ānpái.","vi":"Ủy ban thường vụ vừa họp xong đã công bố sự sắp xếp nhân sự mới."}],"related":[{"hanzi":"常务委员","pinyin":"chángwùwěiyuán","vi":"ủy viên thường vụ"},{"hanzi":"常务副总","pinyin":"chángwùfùzǒng","vi":"phó tổng thường trực"},{"hanzi":"日常","pinyin":"rìcháng","vi":"hàng ngày"},{"hanzi":"事务","pinyin":"shìwù","vi":"sự vụ"}],"traditional":"常務"},{"id":"长远","hanzi":"长远","pinyin":"chángyuǎn","meaning_vi":"lâu dài, dài hạn","explanation":"长 (dài) + 远 (xa).","hsk_level":6,"tags":["tinh-tu","thoi-gian"],"image":"🔭","examples":[{"type":"basic","zh":"我们要看得长远。","pinyin":"Wǒmen yào kàn de chángyuǎn.","vi":"Chúng ta phải nhìn xa trông rộng."},{"type":"simple","zh":"公司制定了一个十年的长远发展规划。","pinyin":"Gōngsī zhìdìngle yí gè shí nián de chángyuǎn fāzhǎn guīhuà.","vi":"Công ty đã đề ra kế hoạch phát triển dài hạn mười năm."},{"type":"compound","zh":"与其只顾眼前的小利，不如从长远考虑。","pinyin":"Yǔqí zhǐgù yǎnqián de xiǎo lì, bùrú cóng chángyuǎn kǎolǜ.","vi":"Thay vì chỉ lo cái lợi nhỏ trước mắt, chi bằng cân nhắc về lâu dài."}],"related":[{"hanzi":"长期","pinyin":"chángqī","vi":"lâu dài"},{"hanzi":"长远利益","pinyin":"chángyuǎnlìyì","vi":"lợi ích lâu dài"},{"hanzi":"眼前","pinyin":"yǎnqián","vi":"trước mắt"},{"hanzi":"远见","pinyin":"yuǎnjiàn","vi":"tầm nhìn xa"}],"traditional":"長遠"},{"id":"嘲笑","hanzi":"嘲笑","pinyin":"cháoxiào","meaning_vi":"chế giễu","explanation":"嘲 (trào – chế nhạo) + 笑 (tiếu – cười) → cười nhạo, chế giễu. Ví dụ: 别嘲笑别人的缺点.","hsk_level":6,"tags":["dong-tu"],"image":"😏","examples":[{"type":"basic","zh":"别嘲笑别人的口音。","pinyin":"Bié cháoxiào biérén de kǒuyīn.","vi":"Đừng chế giễu giọng nói của người khác."},{"type":"simple","zh":"几个男孩围着他嘲笑他的旧鞋子。","pinyin":"Jǐ gè nánhái wéizhe tā cháoxiào tā de jiù xiézi.","vi":"Mấy cậu bé vây quanh chế giễu đôi giày cũ của cậu ấy."},{"type":"compound","zh":"即使别人嘲笑你的梦想，你也不要轻易放弃。","pinyin":"Jíshǐ biérén cháoxiào nǐ de mèngxiǎng, nǐ yě bú yào qīngyì fàngqì.","vi":"Dù người khác chế giễu ước mơ của bạn, bạn cũng đừng dễ dàng từ bỏ."}],"related":[{"hanzi":"讥笑","pinyin":"jīxiào","vi":"chế nhạo"},{"hanzi":"取笑","pinyin":"qǔxiào","vi":"trêu chọc"},{"hanzi":"讽刺","pinyin":"fěngcì","vi":"châm biếm"},{"hanzi":"嘲讽","pinyin":"cháofěng","vi":"mỉa mai"}]},{"id":"彻夜","hanzi":"彻夜","pinyin":"chèyè","meaning_vi":"suốt đêm, thâu đêm","explanation":"彻 (thông suốt) + 夜 (đêm).","hsk_level":6,"tags":["pho-tu","thoi-gian"],"image":"🦉","examples":[{"type":"basic","zh":"他彻夜未眠。","pinyin":"Tā chèyè wèi mián.","vi":"Anh ấy thức trắng đêm."},{"type":"simple","zh":"医生们彻夜守在病床前抢救伤员。","pinyin":"Yīshēngmen chèyè shǒu zài bìngchuáng qián qiǎngjiù shāngyuán.","vi":"Các bác sĩ túc trực suốt đêm bên giường bệnh cấp cứu người bị thương."},{"type":"compound","zh":"因为明天要交方案，所以整个团队彻夜加班。","pinyin":"Yīnwèi míngtiān yào jiāo fāng'àn, suǒyǐ zhěnggè tuánduì chèyè jiābān.","vi":"Vì ngày mai phải nộp phương án nên cả đội tăng ca thâu đêm."}],"related":[{"hanzi":"通宵","pinyin":"tōngxiāo","vi":"thâu đêm"},{"hanzi":"彻夜未眠","pinyin":"chèyèwèimián","vi":"cả đêm không ngủ"},{"hanzi":"熬夜","pinyin":"áoyè","vi":"thức khuya"},{"hanzi":"整夜","pinyin":"zhěngyè","vi":"cả đêm"}],"traditional":"徹夜"},{"id":"陈词滥调","hanzi":"陈词滥调","pinyin":"chéncí-làndiào","meaning_vi":"lời lẽ sáo rỗng cũ rích","explanation":"陈词 (lời cũ) + 滥调 (điệu nhàm). Thành ngữ.","hsk_level":6,"tags":["thanh-ngu"],"image":"🙄","examples":[{"type":"basic","zh":"他的演讲全是陈词滥调。","pinyin":"Tā de yǎnjiǎng quán shì chéncílàndiào.","vi":"Bài diễn thuyết của anh ta toàn lời lẽ sáo rỗng."},{"type":"simple","zh":"读者早就厌倦了广告里的那些陈词滥调。","pinyin":"Dúzhě zǎojiù yànjuànle guǎnggào lǐ de nàxiē chéncílàndiào.","vi":"Độc giả từ lâu đã chán ngán những lời sáo rỗng trong quảng cáo."},{"type":"compound","zh":"如果作文里都是陈词滥调，就很难打动阅卷老师。","pinyin":"Rúguǒ zuòwén lǐ dōu shì chéncílàndiào, jiù hěn nán dǎdòng yuèjuàn lǎoshī.","vi":"Nếu bài văn toàn lời lẽ sáo mòn thì rất khó làm giám khảo xúc động."}],"related":[{"hanzi":"老生常谈","pinyin":"lǎoshēngchángtán","vi":"chuyện cũ rích"},{"hanzi":"套话","pinyin":"tàohuà","vi":"lời sáo rỗng"},{"hanzi":"空话","pinyin":"kōnghuà","vi":"lời nói suông"},{"hanzi":"新颖","pinyin":"xīnyǐng","vi":"mới mẻ"}],"traditional":"陳詞濫調"},{"id":"沉淀","hanzi":"沉淀","pinyin":"chéndiàn","meaning_vi":"lắng đọng","explanation":"沉 (trầm – chìm) + 淀 (điến – cặn lắng) → chất lắng xuống đáy, lắng đọng; nghĩa bóng: tích lũy, đúc kết (文化沉淀, 让心情沉淀一下).","hsk_level":6,"tags":["dong-tu"],"image":"🧪","examples":[{"type":"basic","zh":"泥沙慢慢沉淀下来。","pinyin":"Níshā mànmàn chéndiàn xiàlái.","vi":"Bùn cát từ từ lắng xuống."},{"type":"simple","zh":"这些经验需要时间慢慢沉淀。","pinyin":"Zhèxiē jīngyàn xūyào shíjiān mànmàn chéndiàn.","vi":"Những kinh nghiệm này cần thời gian để từ từ lắng đọng."},{"type":"compound","zh":"只要把豆浆放一会儿，豆渣就会沉淀到杯底。","pinyin":"Zhǐyào bǎ dòujiāng fàng yíhuìr, dòuzhā jiù huì chéndiàn dào bēi dǐ.","vi":"Chỉ cần để sữa đậu nành một lúc, bã đậu sẽ lắng xuống đáy cốc."}],"related":[{"hanzi":"沉积","pinyin":"chénjī","vi":"lắng tụ"},{"hanzi":"积累","pinyin":"jīlěi","vi":"tích lũy"},{"hanzi":"沉淀物","pinyin":"chéndiànwù","vi":"chất lắng"},{"hanzi":"过滤","pinyin":"guòlǜ","vi":"lọc"}],"traditional":"沉澱"},{"id":"沉甸甸","hanzi":"沉甸甸","pinyin":"chéndiàndiàn","meaning_vi":"nặng trĩu","explanation":"沉 (trầm – nặng) + 甸甸 (điện điện – láy tả cảm giác) → nặng trĩu (đồ vật); nghĩa bóng: trĩu nặng trong lòng. Cụm: 沉甸甸的稻穗, 心里沉甸甸的.","hsk_level":6,"tags":["tinh-tu"],"image":"🏋️","examples":[{"type":"basic","zh":"稻穗沉甸甸的。","pinyin":"Dàosuì chéndiàndiàn de.","vi":"Bông lúa nặng trĩu."},{"type":"simple","zh":"他背着一个沉甸甸的书包走进教室。","pinyin":"Tā bēizhe yí gè chéndiàndiàn de shūbāo zǒujìn jiàoshì.","vi":"Cậu ấy đeo chiếc cặp sách nặng trĩu bước vào lớp."},{"type":"compound","zh":"虽然奖杯沉甸甸的，但是她心里感到无比轻松。","pinyin":"Suīrán jiǎngbēi chéndiàndiàn de, dànshì tā xīnlǐ gǎndào wúbǐ qīngsōng.","vi":"Tuy chiếc cúp nặng trĩu, nhưng trong lòng cô ấy cảm thấy vô cùng nhẹ nhõm."}],"related":[{"hanzi":"沉重","pinyin":"chénzhòng","vi":"nặng nề"},{"hanzi":"重","pinyin":"zhòng","vi":"nặng"},{"hanzi":"轻飘飘","pinyin":"qīngpiāopiāo","vi":"nhẹ bẫng"},{"hanzi":"压力","pinyin":"yālì","vi":"áp lực"}]},{"id":"沉寂","hanzi":"沉寂","pinyin":"chénjì","meaning_vi":"im ắng, tĩnh mịch","explanation":"沉 + 寂 (vắng lặng).","hsk_level":6,"tags":["tinh-tu"],"image":"🌙","examples":[{"type":"basic","zh":"夜晚的山谷很沉寂。","pinyin":"Yèwǎn de shāngǔ hěn chénjì.","vi":"Thung lũng về đêm rất tĩnh mịch."},{"type":"simple","zh":"这位歌手沉寂了三年后终于推出了新专辑。","pinyin":"Zhè wèi gēshǒu chénjìle sān nián hòu zhōngyú tuīchūle xīn zhuānjí.","vi":"Ca sĩ này sau ba năm im ắng cuối cùng đã ra album mới."},{"type":"compound","zh":"枪声一响，沉寂的森林就热闹了起来。","pinyin":"Qiāngshēng yì xiǎng, chénjì de sēnlín jiù rènaole qǐlái.","vi":"Tiếng súng vừa vang lên, khu rừng tĩnh mịch liền trở nên náo động."}],"related":[{"hanzi":"寂静","pinyin":"jìjìng","vi":"yên tĩnh"},{"hanzi":"沉默","pinyin":"chénmò","vi":"im lặng"},{"hanzi":"冷清","pinyin":"lěngqīng","vi":"vắng vẻ"},{"hanzi":"热闹","pinyin":"rènao","vi":"náo nhiệt"}]},{"id":"陈列","hanzi":"陈列","pinyin":"chénliè","meaning_vi":"trưng bày","explanation":"陈 (trần – bày ra) + 列 (liệt – xếp hàng) → bày ra theo thứ tự cho người xem. Thường: 陈列商品; 陈列馆 = nhà trưng bày.","hsk_level":6,"tags":["dong-tu"],"image":"🏛️","examples":[{"type":"basic","zh":"橱窗里陈列着新款。","pinyin":"Chúchuāng lǐ chénlièzhe xīnkuǎn.","vi":"Trong tủ kính trưng bày mẫu mới."},{"type":"simple","zh":"博物馆里陈列着两千多年前的青铜器。","pinyin":"Bówùguǎn lǐ chénlièzhe liǎng qiān duō niánqián de qīngtóngqì.","vi":"Bảo tàng trưng bày đồ đồng từ hơn hai nghìn năm trước."},{"type":"compound","zh":"商品陈列得既整齐又美观，顾客一进门就很喜欢。","pinyin":"Shāngpǐn chénliè de jì zhěngqí yòu měiguān, gùkè yí jìnmén jiù hěn xǐhuan.","vi":"Hàng hóa được bày vừa ngăn nắp vừa đẹp mắt, khách vừa vào cửa đã rất thích."}],"related":[{"hanzi":"展览","pinyin":"zhǎnlǎn","vi":"triển lãm"},{"hanzi":"展示","pinyin":"zhǎnshì","vi":"trưng bày"},{"hanzi":"摆设","pinyin":"bǎishè","vi":"bày biện"},{"hanzi":"陈列室","pinyin":"chénlièshì","vi":"phòng trưng bày"}],"traditional":"陳列"},{"id":"沉迷","hanzi":"沉迷","pinyin":"chénmí","meaning_vi":"mê mẩn, đắm chìm (vào game/thú vui)","explanation":"沉 (chìm) + 迷 (mê).","hsk_level":6,"tags":["dong-tu"],"image":"🎮","examples":[{"type":"basic","zh":"他沉迷于网络游戏。","pinyin":"Tā chénmí yú wǎngluò yóuxì.","vi":"Cậu ấy mê mẩn trò chơi trực tuyến."},{"type":"simple","zh":"弟弟最近沉迷于拼装各种模型飞机。","pinyin":"Dìdi zuìjìn chénmí yú pīnzhuāng gèzhǒng móxíng fēijī.","vi":"Dạo này em trai say mê lắp ráp đủ loại máy bay mô hình."},{"type":"compound","zh":"如果你一直沉迷手机，学习成绩就会越来越差。","pinyin":"Rúguǒ nǐ yìzhí chénmí shǒujī, xuéxí chéngjì jiù huì yuèláiyuè chà.","vi":"Nếu bạn cứ mải mê điện thoại, thành tích học tập sẽ ngày càng kém."}],"related":[{"hanzi":"沉溺","pinyin":"chénnì","vi":"chìm đắm"},{"hanzi":"着迷","pinyin":"zháomí","vi":"say mê"},{"hanzi":"痴迷","pinyin":"chīmí","vi":"si mê"},{"hanzi":"沉迷游戏","pinyin":"chénmíyóuxì","vi":"nghiện game"}]},{"id":"陈设","hanzi":"陈设","pinyin":"chénshè","meaning_vi":"bày biện; đồ bày biện trong nhà","explanation":"陈 (bày) + 设 (đặt).","hsk_level":6,"tags":["dong-tu","nha-cua"],"image":"🛋️","examples":[{"type":"basic","zh":"房间陈设很简单。","pinyin":"Fángjiān chénshè hěn jiǎndān.","vi":"Đồ đạc trong phòng bày biện rất đơn giản."},{"type":"simple","zh":"客厅里陈设着一套古色古香的红木家具。","pinyin":"Kètīng lǐ chénshèzhe yítào gǔsègǔxiāng de hóngmù jiājù.","vi":"Phòng khách bày một bộ đồ gỗ gụ mang phong cách cổ kính."},{"type":"compound","zh":"虽然屋里的陈设很朴素，但是收拾得十分干净。","pinyin":"Suīrán wū lǐ de chénshè hěn pǔsù, dànshì shōushi de shífēn gānjìng.","vi":"Tuy đồ đạc trong nhà rất mộc mạc, nhưng được dọn dẹp hết sức sạch sẽ."}],"related":[{"hanzi":"摆设","pinyin":"bǎishè","vi":"đồ bày biện"},{"hanzi":"家具","pinyin":"jiājù","vi":"đồ nội thất"},{"hanzi":"布置","pinyin":"bùzhì","vi":"bố trí"},{"hanzi":"装饰","pinyin":"zhuāngshì","vi":"trang trí"}],"traditional":"陳設"},{"id":"沉稳","hanzi":"沉稳","pinyin":"chénwěn","meaning_vi":"điềm đạm, vững vàng","explanation":"沉 + 稳 (ổn định).","hsk_level":6,"tags":["tinh-tu","con-nguoi"],"image":"🧘","examples":[{"type":"basic","zh":"他性格很沉稳。","pinyin":"Tā xìnggé hěn chénwěn.","vi":"Tính cách anh ấy rất điềm đạm."},{"type":"simple","zh":"老司机沉稳地把车停在了路边。","pinyin":"Lǎosījī chénwěn de bǎ chē tíng zài le lùbiān.","vi":"Người tài xế lâu năm bình tĩnh đỗ xe vào lề đường."},{"type":"compound","zh":"他虽然年纪不大，但是说话办事非常沉稳。","pinyin":"Tā suīrán niánjì búdà, dànshì shuōhuà bànshì fēicháng chénwěn.","vi":"Anh ấy tuy tuổi không lớn, nhưng ăn nói làm việc rất chín chắn."}],"related":[{"hanzi":"稳重","pinyin":"wěnzhòng","vi":"chín chắn"},{"hanzi":"沉着","pinyin":"chénzhuó","vi":"điềm tĩnh"},{"hanzi":"老练","pinyin":"lǎoliàn","vi":"lão luyện"},{"hanzi":"浮躁","pinyin":"fúzào","vi":"nông nổi"}],"traditional":"沉穩"},{"id":"沉鱼落雁","hanzi":"沉鱼落雁","pinyin":"chényú-luòyàn","meaning_vi":"chim sa cá lặn (vẻ đẹp nghiêng nước nghiêng thành)","explanation":"沉鱼 (trầm ngư – cá lặn) + 落雁 (lạc nhạn – nhạn sa) → cá thấy phải lặn, nhạn thấy phải sa (gốc Trang Tử, sau gắn với Tây Thi, Chiêu Quân) → nhan sắc tuyệt trần.","hsk_level":6,"tags":["thanh-ngu"],"image":"💃","examples":[{"type":"basic","zh":"她有沉鱼落雁之貌。","pinyin":"Tā yǒu chényúluòyàn zhī mào.","vi":"Cô ấy có nhan sắc chim sa cá lặn."},{"type":"simple","zh":"传说西施长得沉鱼落雁，美丽动人。","pinyin":"Chuánshuō Xīshī zhǎngde chényúluòyàn, měilì dòngrén.","vi":"Tương truyền Tây Thi có vẻ đẹp chim sa cá lặn, xinh đẹp động lòng người."},{"type":"compound","zh":"新娘虽然算不上沉鱼落雁，但是笑起来特别温柔。","pinyin":"Xīnniáng suīrán suànbúshàng chényúluòyàn, dànshì xiào qǐlái tèbié wēnróu.","vi":"Cô dâu tuy không đến mức chim sa cá lặn, nhưng khi cười lại vô cùng dịu dàng."}],"related":[{"hanzi":"闭月羞花","pinyin":"bìyuèxiūhuā","vi":"hoa nhường nguyệt thẹn"},{"hanzi":"倾国倾城","pinyin":"qīngguóqīngchéng","vi":"nghiêng nước nghiêng thành"},{"hanzi":"美丽","pinyin":"měilì","vi":"đẹp"},{"hanzi":"貌美如花","pinyin":"màoměirúhuā","vi":"đẹp như hoa"}],"traditional":"沉魚落雁"},{"id":"沉重","hanzi":"沉重","pinyin":"chénzhòng","meaning_vi":"nặng nề, trầm trọng","explanation":"沉 (trầm – nặng chìm) + 重 (trọng – nặng) → nặng nề (vật, gánh nặng, tâm trạng). Thường: 沉重的打击, 心情沉重, 负担沉重.","hsk_level":6,"tags":["tinh-tu"],"image":"🏋️","examples":[{"type":"basic","zh":"他的心情很沉重。","pinyin":"Tā de xīnqíng hěn chénzhòng.","vi":"Tâm trạng anh ấy rất nặng nề."},{"type":"simple","zh":"搬运工扛着沉重的箱子走上了楼梯。","pinyin":"Bānyùngōng kángzhe chénzhòng de xiāngzi zǒushàngle lóutī.","vi":"Người khuân vác vác chiếc thùng nặng trịch bước lên cầu thang."},{"type":"compound","zh":"因为房贷压力太沉重，所以他不得不再找一份兼职。","pinyin":"Yīnwèi fángdài yālì tài chénzhòng, suǒyǐ tā bùdébú zài zhǎo yí fèn jiānzhí.","vi":"Vì áp lực trả nợ mua nhà quá nặng nề nên anh ấy buộc phải tìm thêm một công việc bán thời gian."}],"related":[{"hanzi":"沉甸甸","pinyin":"chéndiàndiàn","vi":"nặng trĩu"},{"hanzi":"繁重","pinyin":"fánzhòng","vi":"nặng nề"},{"hanzi":"轻松","pinyin":"qīngsōng","vi":"nhẹ nhõm"},{"hanzi":"负担","pinyin":"fùdān","vi":"gánh nặng"}]},{"id":"尘埃","hanzi":"尘埃","pinyin":"chén'āi","meaning_vi":"bụi bặm, cát bụi","explanation":"尘 (trần – bụi) + 埃 (ai – bụi) → bụi bặm; nghĩa bóng: thứ nhỏ nhoi, trần tục. Cụm: 尘埃落定 (bụi lắng xuống: mọi việc đã ngã ngũ).","hsk_level":6,"tags":["danh-tu"],"image":"🌫️","examples":[{"type":"basic","zh":"桌上落满了尘埃。","pinyin":"Zhuō shàng luò mǎnle chén'āi.","vi":"Trên bàn phủ đầy bụi."},{"type":"simple","zh":"阳光下能看见无数尘埃在空中飞舞。","pinyin":"Yángguāng xià néng kànjiàn wúshù chén'āi zài kōngzhōng fēiwǔ.","vi":"Dưới ánh nắng có thể thấy vô số hạt bụi nhảy múa trong không trung."},{"type":"compound","zh":"直到比赛结果公布，这场争论才尘埃落定。","pinyin":"Zhídào bǐsài jiéguǒ gōngbù, zhè chǎng zhēnglùn cái chén'āiluòdìng.","vi":"Mãi đến khi kết quả cuộc thi được công bố, cuộc tranh cãi này mới ngã ngũ."}],"related":[{"hanzi":"灰尘","pinyin":"huīchén","vi":"bụi"},{"hanzi":"尘土","pinyin":"chéntǔ","vi":"bụi đất"},{"hanzi":"尘埃落定","pinyin":"chén'āiluòdìng","vi":"mọi chuyện ngã ngũ"},{"hanzi":"污垢","pinyin":"wūgòu","vi":"vết bẩn"}],"traditional":"塵埃"},{"id":"乘","hanzi":"乘","pinyin":"chéng","meaning_vi":"đi, đáp (xe, tàu, máy bay); nhân (phép nhân)","explanation":"乘 (thừa): đi, cưỡi phương tiện (乘车, 乘飞机); phép nhân (二乘三等于六); nhân dịp (乘机).","hsk_level":6,"tags":["dong-tu"],"image":"✖️","examples":[{"type":"basic","zh":"三乘五等于十五。","pinyin":"Sān chéng wǔ děngyú shíwǔ.","vi":"Ba nhân năm bằng mười lăm."},{"type":"simple","zh":"我们明天早上乘第一班飞机去北京。","pinyin":"Wǒmen míngtiān zǎo shangchéng dìyī bān fēijī qù Běijīng.","vi":"Sáng mai chúng tôi đi chuyến bay đầu tiên đến Bắc Kinh."},{"type":"compound","zh":"如果乘地铁去机场，就能避开下班高峰。","pinyin":"Rúguǒ chéng dìtiě qù jīchǎng, jiù néng bìkāi xiàbān gāofēng.","vi":"Nếu đi tàu điện ngầm ra sân bay thì có thể tránh được giờ cao điểm tan tầm."}],"related":[{"hanzi":"乘法","pinyin":"chéngfǎ","vi":"phép nhân"},{"hanzi":"乘车","pinyin":"chéngchē","vi":"đi xe"},{"hanzi":"乘客","pinyin":"chéngkè","vi":"hành khách"},{"hanzi":"除","pinyin":"chú","vi":"phép chia"}]},{"id":"成败","hanzi":"成败","pinyin":"chéngbài","meaning_vi":"thành bại, thắng thua","explanation":"成 (thành công) + 败 (thất bại).","hsk_level":6,"tags":["danh-tu"],"image":"⚖️","examples":[{"type":"basic","zh":"细节决定成败。","pinyin":"Xìjiéjuédìngchéngbài.","vi":"Chi tiết quyết định thành bại."},{"type":"simple","zh":"这次谈判关系到整个项目的成败。","pinyin":"Zhè cì tánpàn guānxìdào zhěnggè xiàng mùde chéngbài.","vi":"Cuộc đàm phán này liên quan đến thành bại của cả dự án."},{"type":"compound","zh":"与其担心成败，不如把每一步都做好。","pinyin":"Yǔqí dānxīn chéngbài, bùrú bǎ měi yí bù dōu zuò hǎo.","vi":"Thay vì lo lắng chuyện thành bại, chi bằng làm tốt từng bước một."}],"related":[{"hanzi":"成功","pinyin":"chénggōng","vi":"thành công"},{"hanzi":"失败","pinyin":"shībài","vi":"thất bại"},{"hanzi":"胜负","pinyin":"shèngfù","vi":"thắng bại"},{"hanzi":"成败得失","pinyin":"chéngbàidéshī","vi":"thành bại được mất"}],"traditional":"成敗"},{"id":"承包","hanzi":"承包","pinyin":"chéngbāo","meaning_vi":"nhận thầu","explanation":"承 (thừa – nhận lấy) + 包 (bao – bao trọn) → nhận khoán, nhận thầu trọn gói một công việc. Thường: 承包工程; 承包商 = nhà thầu.","hsk_level":6,"tags":["dong-tu"],"image":"🏗️","examples":[{"type":"basic","zh":"他承包了这片果园。","pinyin":"Tā chéngbāole zhè piàn guǒyuán.","vi":"Anh ấy đã nhận khoán vườn cây ăn quả này."},{"type":"simple","zh":"这家建筑公司承包了新医院的施工工程。","pinyin":"Zhè jiā jiànzhù gōngsī chéngbāole xīn yīyuàn de shīgōng gōngchéng.","vi":"Công ty xây dựng này đã nhận thầu công trình thi công bệnh viện mới."},{"type":"compound","zh":"因为承包了村里的鱼塘，所以他家的收入增加了一倍。","pinyin":"Yīnwèi chéngbāole cūnlǐ de yútáng, suǒyǐ tā jiā de shōurù zēngjiāle yí bèi.","vi":"Vì nhận khoán ao cá của làng nên thu nhập nhà anh ấy tăng gấp đôi."}],"related":[{"hanzi":"承包商","pinyin":"chéngbāoshāng","vi":"nhà thầu"},{"hanzi":"承担","pinyin":"chéngdān","vi":"đảm nhận"},{"hanzi":"包工","pinyin":"bāogōng","vi":"khoán việc"},{"hanzi":"外包","pinyin":"wàibāo","vi":"thuê ngoài"}]},{"id":"惩处","hanzi":"惩处","pinyin":"chéngchǔ","meaning_vi":"trừng phạt, xử lý kỷ luật","explanation":"惩 (trừng trị) + 处 (xử lý).","hsk_level":6,"tags":["dong-tu","phap-luat"],"image":"⚖️","examples":[{"type":"basic","zh":"违规者将受到惩处。","pinyin":"Wéiguī zhě jiāng shòudào chéngchǔ.","vi":"Người vi phạm sẽ bị xử phạt."},{"type":"simple","zh":"法院依法惩处了这批制造假药的罪犯。","pinyin":"Fǎyuàn yīfǎ chéngchǔle zhè pī zhìzào jiǎyào de zuìfàn.","vi":"Tòa án đã trừng trị theo pháp luật nhóm tội phạm sản xuất thuốc giả này."},{"type":"compound","zh":"只要发现酒后驾驶，交警就会从严惩处。","pinyin":"Zhǐyào fāxiàn jiǔhòu jiàshǐ, jiāojǐng jiù huì cóng yán chéngchǔ.","vi":"Chỉ cần phát hiện lái xe sau khi uống rượu, cảnh sát giao thông sẽ xử phạt nghiêm khắc."}],"related":[{"hanzi":"惩罚","pinyin":"chéngfá","vi":"trừng phạt"},{"hanzi":"处罚","pinyin":"chǔfá","vi":"xử phạt"},{"hanzi":"处分","pinyin":"chǔfèn","vi":"kỷ luật"},{"hanzi":"严惩","pinyin":"yánchéng","vi":"trừng trị nghiêm"}],"traditional":"懲處"},{"id":"成家立业","hanzi":"成家立业","pinyin":"chéngjiā-lìyè","meaning_vi":"lập gia đình và gây dựng sự nghiệp","explanation":"成家 (thành gia – lập gia đình) + 立业 (lập nghiệp – dựng sự nghiệp) → có gia đình và sự nghiệp ổn định, thường nói về người đã trưởng thành.","hsk_level":6,"tags":["thanh-ngu","gia-dinh"],"image":"🏡","examples":[{"type":"basic","zh":"儿子已经成家立业了。","pinyin":"Érzi yǐjīng chéngjiālìyè le.","vi":"Con trai đã lập gia đình và có sự nghiệp."},{"type":"simple","zh":"父母最大的心愿就是看到孩子们成家立业。","pinyin":"Fùmǔ zuì dà de xīnyuàn jiùshì kàndào háizimen chéngjiālìyè.","vi":"Tâm nguyện lớn nhất của cha mẹ là thấy các con yên bề gia thất, vững vàng sự nghiệp."},{"type":"compound","zh":"等弟弟成家立业了，妈妈就可以放心了。","pinyin":"Děng dìdi chéngjiālìyè le, māma jiù kěyǐ fàngxīn le.","vi":"Đợi em trai yên bề gia thất, có sự nghiệp ổn định rồi, mẹ sẽ yên lòng."}],"related":[{"hanzi":"结婚","pinyin":"jiéhūn","vi":"kết hôn"},{"hanzi":"立业","pinyin":"lìyè","vi":"lập nghiệp"},{"hanzi":"成家","pinyin":"chéngjiā","vi":"lập gia đình"},{"hanzi":"事业","pinyin":"shìyè","vi":"sự nghiệp"}],"traditional":"成家立業"},{"id":"成龙配套","hanzi":"成龙配套","pinyin":"chénglóng-pèitào","meaning_vi":"đồng bộ hoàn chỉnh thành hệ thống","explanation":"成龙 (thành long – nối thành dải như rồng) + 配套 (phối sáo – phối hợp thành bộ) → các bộ phận được kết nối thành hệ thống hoàn chỉnh, đồng bộ (thiết bị, công trình).","hsk_level":6,"tags":["thanh-ngu"],"image":"🔗","examples":[{"type":"basic","zh":"设备已经成龙配套。","pinyin":"Shèbèi yǐjīng chénglóngpèitào.","vi":"Thiết bị đã được trang bị đồng bộ."},{"type":"simple","zh":"新厂区的水电设施已经全部成龙配套。","pinyin":"Xīn chǎngqū de shuǐdiàn shèshī yǐjīng quánbù chénglóngpèitào.","vi":"Hệ thống điện nước của khu nhà máy mới đã hoàn toàn đồng bộ."},{"type":"compound","zh":"只有把生产线成龙配套，工厂才能真正提高效率。","pinyin":"Zhǐyǒu bǎ shēngchǎnxiàn chénglóngpèitào, gōngchǎng cáinéng zhēnzhèng tígāo xiàolǜ.","vi":"Chỉ khi dây chuyền sản xuất được đồng bộ hoàn chỉnh, nhà máy mới thật sự nâng cao hiệu suất."}],"related":[{"hanzi":"配套","pinyin":"pèitào","vi":"đồng bộ"},{"hanzi":"系统","pinyin":"xìtǒng","vi":"hệ thống"},{"hanzi":"完整","pinyin":"wánzhěng","vi":"hoàn chỉnh"},{"hanzi":"配套设施","pinyin":"pèitàoshèshī","vi":"cơ sở hạ tầng đồng bộ"}],"traditional":"成龍配套"},{"id":"承前启后","hanzi":"承前启后","pinyin":"chéngqián-qǐhòu","meaning_vi":"kế thừa quá khứ mở ra tương lai","explanation":"承前 (thừa tiền – tiếp nối cái trước) + 启后 (khải hậu – mở đường cho sau) → kế thừa người đi trước, mở lối cho người sau; thường nói về vai trò của thế hệ, sự nghiệp.","hsk_level":6,"tags":["thanh-ngu"],"image":"🌉","examples":[{"type":"basic","zh":"这一代人承前启后。","pinyin":"Zhè yídàirén chéngqiánqǐhòu.","vi":"Thế hệ này kế thừa quá khứ, mở lối tương lai."},{"type":"simple","zh":"这次会议在公司历史上起到了承前启后的作用。","pinyin":"Zhè cì huìyì zài gōngsī lìshǐshàng qǐdàole chéngqiánqǐhòu de zuòyòng.","vi":"Hội nghị này đóng vai trò kế thừa và mở đường trong lịch sử công ty."},{"type":"compound","zh":"他的研究不但总结了前人的成果，而且具有承前启后的意义。","pinyin":"Tā de yánjiū búdàn zǒngjiéle qiánrén de chéngguǒ, érqiě jùyǒu chéngqiánqǐhòu de yìyì.","vi":"Nghiên cứu của ông không chỉ tổng kết thành quả của người đi trước mà còn có ý nghĩa kế thừa và mở ra hướng mới."}],"related":[{"hanzi":"继往开来","pinyin":"jìwǎngkāilái","vi":"kế thừa quá khứ mở lối tương lai"},{"hanzi":"承上启下","pinyin":"chéngshàngqǐxià","vi":"nối trên mở dưới"},{"hanzi":"继承","pinyin":"jìchéng","vi":"kế thừa"},{"hanzi":"传承","pinyin":"chuánchéng","vi":"truyền thừa"}],"traditional":"承前啟後"},{"id":"成千上万","hanzi":"成千上万","pinyin":"chéngqiān-shàngwàn","meaning_vi":"hàng nghìn hàng vạn","explanation":"成千 + 上万. Thành ngữ chỉ số lượng rất lớn.","hsk_level":6,"tags":["thanh-ngu","so-luong"],"image":"🔢","examples":[{"type":"basic","zh":"广场上有成千上万的人。","pinyin":"Guǎngchǎng shàng yǒu chéngqiānshàngwàn de rén.","vi":"Trên quảng trường có hàng nghìn hàng vạn người."},{"type":"simple","zh":"每年秋天，成千上万只候鸟飞到这片湖区过冬。","pinyin":"Měinián qiūtiān, chéngqiānshàngwàn zhī hòuniǎo fēi dào zhè piàn Húqū guòdōng.","vi":"Mỗi mùa thu, hàng nghìn hàng vạn con chim di trú bay về vùng hồ này trú đông."},{"type":"compound","zh":"这首歌一上线，就被成千上万的网友转发。","pinyin":"Zhè shǒu gē yí shàngxiàn, jiù bèi chéngqiānshàngwàn de wǎngyǒu zhuǎnfā.","vi":"Bài hát này vừa phát hành đã được hàng nghìn hàng vạn cư dân mạng chia sẻ."}],"related":[{"hanzi":"成千成万","pinyin":"chéngqiānchéngwàn","vi":"hàng ngàn hàng vạn"},{"hanzi":"数以万计","pinyin":"shùyǐwànjì","vi":"hàng vạn"},{"hanzi":"不计其数","pinyin":"bújìqíshù","vi":"vô số"},{"hanzi":"寥寥无几","pinyin":"liáoliáowújǐ","vi":"ít ỏi"}],"traditional":"成千上萬"},{"id":"成日","hanzi":"成日","pinyin":"chéngrì","meaning_vi":"suốt ngày","explanation":"成 (thành – trọn, cả) + 日 (nhật – ngày) → cả ngày, suốt ngày (thường hàm ý chê). Đồng nghĩa 整天. Ví dụ: 成日玩游戏.","hsk_level":6,"tags":["pho-tu","thoi-gian"],"image":"⏳","examples":[{"type":"basic","zh":"他成日待在家里。","pinyin":"Tā chéngrì dāi zài jiālǐ.","vi":"Anh ấy suốt ngày ở trong nhà."},{"type":"simple","zh":"退休后，外公成日在公园里下象棋。","pinyin":"Tuìxiū hòu, wàigōng chéngrì zài gōngyuán lǐ xià xiàngqí.","vi":"Sau khi nghỉ hưu, ông ngoại suốt ngày chơi cờ tướng trong công viên."},{"type":"compound","zh":"因为他成日无所事事，所以父母很为他担心。","pinyin":"Yīnwèi tā chéngrì wúsuǒshìshì, suǒyǐ fùmǔ hěn wèi tā dānxīn.","vi":"Vì cậu ta suốt ngày không làm gì nên bố mẹ rất lo cho cậu."}],"related":[{"hanzi":"成天","pinyin":"chéngtiān","vi":"suốt ngày"},{"hanzi":"整天","pinyin":"zhěngtiān","vi":"cả ngày"},{"hanzi":"终日","pinyin":"zhōngrì","vi":"suốt ngày"},{"hanzi":"一整天","pinyin":"yìzhěngtiān","vi":"trọn một ngày"}]},{"id":"承上启下","hanzi":"承上启下","pinyin":"chéngshàng-qǐxià","meaning_vi":"nối tiếp phần trên mở ra phần dưới (bố cục bài văn)","explanation":"承上 (thừa thượng – tiếp nối phần trên) + 启下 (khải hạ – mở ra phần dưới) → câu/đoạn chuyển tiếp trong bài văn; cũng chỉ vai trò trung gian giữa cấp trên và cấp dưới.","hsk_level":6,"tags":["thanh-ngu","hoc-tap"],"image":"📝","examples":[{"type":"basic","zh":"这一段承上启下。","pinyin":"Zhè yí duàn chéngshàngqǐxià.","vi":"Đoạn này nối tiếp phần trên, mở ra phần dưới."},{"type":"simple","zh":"老师让我们找出文章中承上启下的句子。","pinyin":"Lǎoshī ràng wǒmen zhǎochū wénzhāng zhōng chéngshàngqǐxià de jùzi.","vi":"Thầy giáo bảo chúng tôi tìm câu chuyển tiếp nối ý trên mở ý dưới trong bài văn."},{"type":"compound","zh":"如果缺少承上启下的过渡段，文章就会显得很生硬。","pinyin":"Rúguǒ quēshǎo chéngshàngqǐxià de guòdù duàn, wénzhāng jiù huì xiǎnde hěn shēngyìng.","vi":"Nếu thiếu đoạn chuyển tiếp nối trên mở dưới, bài văn sẽ trở nên rất gượng gạo."}],"related":[{"hanzi":"承前启后","pinyin":"chéngqiánqǐhòu","vi":"kế thừa quá khứ mở ra tương lai"},{"hanzi":"过渡","pinyin":"guòdù","vi":"chuyển tiếp"},{"hanzi":"段落","pinyin":"duànluò","vi":"đoạn văn"},{"hanzi":"衔接","pinyin":"xiánjiē","vi":"nối tiếp"}],"traditional":"承上啟下"},{"id":"成天","hanzi":"成天","pinyin":"chéngtiān","meaning_vi":"suốt ngày","explanation":"成 (thành – trọn) + 天 (thiên – ngày) → cả ngày, suốt ngày (khẩu ngữ, thường mang ý phàn nàn). Ví dụ: 他成天玩游戏.","hsk_level":6,"tags":["pho-tu"],"image":"⏳","examples":[{"type":"basic","zh":"她成天忙个不停。","pinyin":"Tā chéngtiān máng gè bùtíng.","vi":"Cô ấy suốt ngày bận rộn không ngừng."},{"type":"simple","zh":"小狗成天跟在主人后面跑来跑去。","pinyin":"Xiǎogǒu chéngtiān gēn zài zhǔrén hòumiàn pǎo lái pǎo qù.","vi":"Chú chó nhỏ suốt ngày chạy theo sau chủ."},{"type":"compound","zh":"与其成天抱怨工作太累，不如换个轻松点的岗位。","pinyin":"Yǔqí chéngtiān bàoyuàn gōngzuò tài lèi, bùrú huàn gè qīngsōng diǎn de gǎngwèi.","vi":"Thay vì suốt ngày than công việc quá mệt, chi bằng đổi sang vị trí nhẹ nhàng hơn."}],"related":[{"hanzi":"整天","pinyin":"zhěngtiān","vi":"cả ngày"},{"hanzi":"成日","pinyin":"chéngrì","vi":"suốt ngày"},{"hanzi":"天天","pinyin":"tiāntiān","vi":"ngày ngày"},{"hanzi":"一天到晚","pinyin":"yìtiāndàowǎn","vi":"từ sáng đến tối"}]},{"id":"成员","hanzi":"成员","pinyin":"chéngyuán","meaning_vi":"thành viên","explanation":"成 (thành – tạo thành) + 员 (viên – người) → người hợp thành tổ chức, thành viên. Thường: 家庭成员, 团队成员.","hsk_level":6,"tags":["danh-tu","con-nguoi"],"image":"👥","examples":[{"type":"basic","zh":"他是乐队的成员。","pinyin":"Tā shì yuèduì de chéngyuán.","vi":"Anh ấy là thành viên của ban nhạc."},{"type":"simple","zh":"这个读书会的成员每周六都在图书馆见面。","pinyin":"Zhè ge dúshūhuì de chéngyuán měi Zhōuliù dōu zài túshūguǎn jiànmiàn.","vi":"Các thành viên câu lạc bộ đọc sách này gặp nhau ở thư viện mỗi thứ bảy."},{"type":"compound","zh":"只要有一个成员不同意，这个方案就不能通过。","pinyin":"Zhǐyào yǒu yí gè chéngyuán bùtóng yì, zhè ge fāng'àn jiù bù néng tōngguò.","vi":"Chỉ cần có một thành viên không đồng ý, phương án này sẽ không được thông qua."}],"related":[{"hanzi":"会员","pinyin":"huìyuán","vi":"hội viên"},{"hanzi":"成员国","pinyin":"chéngyuánguó","vi":"quốc gia thành viên"},{"hanzi":"团队","pinyin":"tuánduì","vi":"đội nhóm"},{"hanzi":"组员","pinyin":"zǔyuán","vi":"thành viên nhóm"}],"traditional":"成員"},{"id":"成竹在胸","hanzi":"成竹在胸","pinyin":"chéngzhú-zàixiōng","meaning_vi":"đã có tính toán sẵn trong lòng, tự tin nắm chắc","explanation":"Điển tích vẽ trúc. Thành ngữ.","hsk_level":6,"tags":["thanh-ngu"],"image":"🎋","examples":[{"type":"basic","zh":"他对比赛成竹在胸。","pinyin":"Tā duì bǐsài chéngzhúzàixiōng.","vi":"Anh ấy đã nắm chắc phần thắng trong cuộc thi."},{"type":"simple","zh":"面对记者的提问，发言人显得成竹在胸。","pinyin":"Miànduì jìzhě de tíwèn, fāyánrén xiǎnde chéngzhúzàixiōng.","vi":"Trước câu hỏi của phóng viên, người phát ngôn tỏ ra đã liệu sẵn trong lòng."},{"type":"compound","zh":"因为他提前做了充分准备，所以上台时成竹在胸。","pinyin":"Yīnwèi tā tíqián zuòle chōngfèn zhǔnbèi, suǒyǐ shàngtái shí chéngzhúzàixiōng.","vi":"Vì đã chuẩn bị kỹ từ trước nên khi lên sân khấu anh ấy rất tự tin nắm chắc."}],"related":[{"hanzi":"胸有成竹","pinyin":"xiōngyǒuchéngzhú","vi":"đã có tính toán trước"},{"hanzi":"有把握","pinyin":"yǒubǎwò","vi":"nắm chắc"},{"hanzi":"心中有数","pinyin":"xīnzhōngyǒushù","vi":"trong lòng đã rõ"},{"hanzi":"手足无措","pinyin":"shǒuzúwúcuò","vi":"luống cuống"}]},{"id":"赤手空拳","hanzi":"赤手空拳","pinyin":"chìshǒu-kōngquán","meaning_vi":"tay không tấc sắt","explanation":"赤手 (xích thủ – tay trần) + 空拳 (không quyền – nắm tay không) → tay không, không vũ khí hay vốn liếng gì → tay không tấc sắt.","hsk_level":6,"tags":["thanh-ngu"],"image":"✊","examples":[{"type":"basic","zh":"他赤手空拳去创业。","pinyin":"Tā chìshǒukōngquán qù chuàngyè.","vi":"Anh ấy tay trắng đi khởi nghiệp."},{"type":"simple","zh":"那位保安赤手空拳制服了持刀的歹徒。","pinyin":"Nà wèi bǎo'ān chìshǒukōngquán zhìfúle chídāo de dǎitú.","vi":"Người bảo vệ ấy tay không tấc sắt đã khống chế tên côn đồ cầm dao."},{"type":"compound","zh":"虽然他当年赤手空拳来到城市，但是现在已经有了自己的工厂。","pinyin":"Suīrán tā dāngnián chìshǒukōngquán láidào chéngshì, dànshì xiànzài yǐjīng yǒule zìjǐ de gōngchǎng.","vi":"Tuy năm ấy anh ta tay trắng lên thành phố, nhưng giờ đã có nhà máy riêng."}],"related":[{"hanzi":"手无寸铁","pinyin":"shǒuwúcùntiě","vi":"tay không tấc sắt"},{"hanzi":"空手","pinyin":"kōngshǒu","vi":"tay không"},{"hanzi":"白手起家","pinyin":"báishǒuqǐjiā","vi":"tay trắng làm nên"},{"hanzi":"全副武装","pinyin":"quánfùwǔzhuāng","vi":"vũ trang đầy đủ"}]},{"id":"持家","hanzi":"持家","pinyin":"chíjiā","meaning_vi":"quán xuyến gia đình","explanation":"持 (nắm giữ) + 家 (nhà). Cụm: 勤俭持家.","hsk_level":6,"tags":["dong-tu","gia-dinh"],"image":"🏡","examples":[{"type":"basic","zh":"她很会持家。","pinyin":"Tā hěn huì chíjiā.","vi":"Cô ấy rất giỏi quán xuyến gia đình."},{"type":"simple","zh":"母亲靠着勤俭持家供三个孩子读完了大学。","pinyin":"Mǔqīn kàozhe qínjiǎn chíjiā gōng sān gè háizi dú wánle dàxué.","vi":"Mẹ nhờ cần kiệm quán xuyến gia đình mà nuôi ba đứa con học hết đại học."},{"type":"compound","zh":"她既要上班赚钱，又要操心持家，实在不容易。","pinyin":"Tā jì yào shàngbān zhuànqián, yòu yào cāoxīn chíjiā, shízài bù róngyì.","vi":"Cô ấy vừa phải đi làm kiếm tiền, vừa phải lo quán xuyến nhà cửa, thật chẳng dễ dàng."}],"related":[{"hanzi":"管家","pinyin":"guǎnjiā","vi":"quản gia"},{"hanzi":"勤俭持家","pinyin":"qínjiǎnchíjiā","vi":"cần kiệm quán xuyến gia đình"},{"hanzi":"家务","pinyin":"jiāwù","vi":"việc nhà"},{"hanzi":"当家","pinyin":"dāngjiā","vi":"làm chủ gia đình"}]},{"id":"持久","hanzi":"持久","pinyin":"chíjiǔ","meaning_vi":"bền bỉ, lâu dài","explanation":"持 (trì – giữ) + 久 (cửu – lâu) → giữ được lâu dài, bền bỉ. Thường: 持久战 (chiến tranh trường kỳ), 香味持久.","hsk_level":6,"tags":["tinh-tu"],"image":"♾️","examples":[{"type":"basic","zh":"这种香味很持久。","pinyin":"Zhè zhǒng xiāngwèi hěn chíjiǔ.","vi":"Mùi hương này lưu rất lâu."},{"type":"simple","zh":"这款电池的续航时间非常持久。","pinyin":"Zhè kuǎn diànchí de xùháng shíjiān fēicháng chíjiǔ.","vi":"Thời lượng sử dụng của loại pin này rất bền lâu."},{"type":"compound","zh":"只有培养真正的兴趣，学习的动力才会持久。","pinyin":"Zhǐyǒu péiyǎng zhēnzhèng de xìngqù, xuéxí de dònglì cái huì chíjiǔ.","vi":"Chỉ khi nuôi dưỡng niềm hứng thú thật sự, động lực học tập mới bền lâu."}],"related":[{"hanzi":"持续","pinyin":"chíxù","vi":"liên tục"},{"hanzi":"长久","pinyin":"chángjiǔ","vi":"lâu dài"},{"hanzi":"耐久","pinyin":"nàijiǔ","vi":"bền lâu"},{"hanzi":"短暂","pinyin":"duǎnzàn","vi":"ngắn ngủi"}]},{"id":"持之以恒","hanzi":"持之以恒","pinyin":"chízhī-yǐhéng","meaning_vi":"kiên trì bền bỉ không ngừng nghỉ","explanation":"持之 (trì chi – giữ lấy) + 以恒 (dĩ hằng – một cách bền bỉ) → giữ vững lâu dài → kiên trì đến cùng. Thường dùng khuyên học tập, rèn luyện.","hsk_level":6,"tags":["thanh-ngu","hoc-tap"],"image":"♾️","examples":[{"type":"basic","zh":"学外语要持之以恒。","pinyin":"Xué wàiyǔ yào chízhīyǐhéng.","vi":"Học ngoại ngữ phải kiên trì bền bỉ."},{"type":"simple","zh":"外婆持之以恒地每天写一页毛笔字。","pinyin":"Wàipó chízhīyǐhéng de měitiān xiě yí yè máobǐ zì.","vi":"Bà ngoại kiên trì bền bỉ mỗi ngày viết một trang chữ bút lông."},{"type":"compound","zh":"如果能持之以恒地锻炼，你的身体就会越来越好。","pinyin":"Rúguǒ néng chízhīyǐhéng de duànliàn, nǐ de shēntǐ jiù huì yuèláiyuè hǎo.","vi":"Nếu có thể kiên trì tập luyện bền bỉ, sức khỏe của bạn sẽ ngày càng tốt."}],"related":[{"hanzi":"坚持不懈","pinyin":"jiānchíbúxiè","vi":"kiên trì không ngừng"},{"hanzi":"锲而不舍","pinyin":"qiè'érbùshě","vi":"kiên trì không bỏ"},{"hanzi":"半途而废","pinyin":"bàntú'érfèi","vi":"bỏ dở giữa chừng"},{"hanzi":"三天打鱼两天晒网","pinyin":"sān tiān dǎyú liǎng tiān shài wǎng","vi":"bữa đực bữa cái"}],"traditional":"持之以恆"},{"id":"重叠","hanzi":"重叠","pinyin":"chóngdié","meaning_vi":"trùng lặp, chồng chéo","explanation":"重 (trùng – lặp lại) + 叠 (điệp – chồng lên) → chồng lên nhau, trùng lặp. Ví dụ: 机构重叠 (bộ máy chồng chéo); 重叠词 = từ lặp.","hsk_level":6,"tags":["dong-tu"],"image":"📑","examples":[{"type":"basic","zh":"两张图片重叠了。","pinyin":"Liǎng zhāng túpiàn chóngdié le.","vi":"Hai bức ảnh bị chồng lên nhau."},{"type":"simple","zh":"这两个部门的职能有很多重叠的地方。","pinyin":"Zhè liǎng gè bùmén de zhínéng yǒu hěn duō chóngdié de dìfang.","vi":"Chức năng của hai bộ phận này có nhiều chỗ chồng chéo."},{"type":"compound","zh":"因为两门课的时间重叠了，所以我只能选一门。","pinyin":"Yīnwèi liǎng mén kè de shíjiān chóngdié le, suǒyǐ wǒ zhǐnéng xuǎn yì mén.","vi":"Vì giờ của hai môn học trùng nhau nên tôi chỉ có thể chọn một môn."}],"related":[{"hanzi":"重复","pinyin":"chóngfù","vi":"lặp lại"},{"hanzi":"交叉","pinyin":"jiāochā","vi":"giao nhau"},{"hanzi":"叠加","pinyin":"diéjiā","vi":"chồng lên"},{"hanzi":"层层叠叠","pinyin":"céngcéngdiédié","vi":"chồng chất lớp lớp"}],"traditional":"重疊"},{"id":"重蹈覆辙","hanzi":"重蹈覆辙","pinyin":"chóngdǎo-fùzhé","meaning_vi":"đi vào vết xe đổ (lặp lại sai lầm cũ)","explanation":"重蹈 (trùng đạo – giẫm lại) + 覆辙 (phúc triệt – vết bánh xe đã lật) → giẫm lại vết xe đổ → lặp lại sai lầm đã thất bại trước đó.","hsk_level":6,"tags":["thanh-ngu"],"image":"⚠️","examples":[{"type":"basic","zh":"我们不能重蹈覆辙。","pinyin":"Wǒmen bù néng chóngdǎofùzhé.","vi":"Chúng ta không thể đi vào vết xe đổ."},{"type":"simple","zh":"他吸取了哥哥的教训，没有重蹈覆辙。","pinyin":"Tā xīqǔle gēge de jiàoxùn, méiyǒu chóngdǎofùzhé.","vi":"Anh ấy rút kinh nghiệm từ người anh trai nên không lặp lại sai lầm cũ."},{"type":"compound","zh":"如果不认真总结失败的原因，就很可能重蹈覆辙。","pinyin":"Rúguǒ bú rènzhēn zǒngjié shībài de yuányīn, jiù hěn kěnéng chóngdǎofùzhé.","vi":"Nếu không nghiêm túc tổng kết nguyên nhân thất bại, rất có thể sẽ đi vào vết xe đổ."}],"related":[{"hanzi":"前车之鉴","pinyin":"qiánchēzhījiàn","vi":"bài học xe đi trước"},{"hanzi":"重复","pinyin":"chóngfù","vi":"lặp lại"},{"hanzi":"吸取教训","pinyin":"xīqǔjiàoxùn","vi":"rút ra bài học"},{"hanzi":"再犯","pinyin":"zàifàn","vi":"tái phạm"}],"traditional":"重蹈覆轍"},{"id":"崇敬","hanzi":"崇敬","pinyin":"chóngjìng","meaning_vi":"tôn kính","explanation":"崇 (sùng – tôn cao) + 敬 (kính – kính trọng) → sùng kính, tôn kính. Thường: 崇敬的心情, 对英雄充满崇敬.","hsk_level":6,"tags":["dong-tu"],"image":"🙇","examples":[{"type":"basic","zh":"人们崇敬这位英雄。","pinyin":"Rénmen chóngjìng zhè wèi yīngxióng.","vi":"Mọi người tôn kính vị anh hùng này."},{"type":"simple","zh":"学生们怀着崇敬的心情参观了烈士纪念馆。","pinyin":"Xuéshēngmen huáizhe chóngjìng de xīnqíng cānguānle lièshì jìniànguǎn.","vi":"Học sinh mang tấm lòng tôn kính đến thăm nhà tưởng niệm liệt sĩ."},{"type":"compound","zh":"他不但医术高明，而且心地善良，所以深受村民崇敬。","pinyin":"Tā búdàn yīshù gāomíng, érqiě xīndì shànliáng, suǒyǐ shēnshòu cūnmín chóngjìng.","vi":"Ông không chỉ y thuật cao minh mà còn tốt bụng, nên được dân làng hết mực tôn kính."}],"related":[{"hanzi":"尊敬","pinyin":"zūnjìng","vi":"tôn kính"},{"hanzi":"敬仰","pinyin":"jìngyǎng","vi":"kính ngưỡng"},{"hanzi":"崇拜","pinyin":"chóngbài","vi":"sùng bái"},{"hanzi":"敬佩","pinyin":"jìngpèi","vi":"khâm phục"}]},{"id":"崇山峻岭","hanzi":"崇山峻岭","pinyin":"chóngshān-jùnlǐng","meaning_vi":"núi non trùng điệp hiểm trở","explanation":"崇山 (núi cao) + 峻岭 (đèo dốc). Thành ngữ.","hsk_level":6,"tags":["thanh-ngu","thien-nhien"],"image":"🏔️","examples":[{"type":"basic","zh":"公路穿过崇山峻岭。","pinyin":"Gōnglù chuānguò chóngshānjùnlǐng.","vi":"Con đường cắt qua núi non trùng điệp hiểm trở."},{"type":"simple","zh":"红军战士翻越了无数崇山峻岭。","pinyin":"Hóngjūn zhànshì fānyuèle wúshù chóngshānjùnlǐng.","vi":"Chiến sĩ Hồng quân đã vượt qua vô số núi non hiểm trở."},{"type":"compound","zh":"虽然村子藏在崇山峻岭之中，但是现在已经通了公路。","pinyin":"Suīrán cūnzi cáng zài chóngshānjùnlǐng zhīzhōng, dànshì xiànzài yǐjīng tōngle gōnglù.","vi":"Tuy ngôi làng nằm khuất giữa núi non trùng điệp, nhưng nay đã có đường cái thông tới."}],"related":[{"hanzi":"高山","pinyin":"gāoshān","vi":"núi cao"},{"hanzi":"层峦叠嶂","pinyin":"céngluándiézhàng","vi":"núi non trùng điệp"},{"hanzi":"山脉","pinyin":"shānmài","vi":"dãy núi"},{"hanzi":"平原","pinyin":"píngyuán","vi":"đồng bằng"}],"traditional":"崇山峻嶺"},{"id":"重温","hanzi":"重温","pinyin":"chóngwēn","meaning_vi":"ôn lại (kỷ niệm/kiến thức cũ)","explanation":"重 (đọc chóng) + 温 (ôn tập).","hsk_level":6,"tags":["dong-tu","hoc-tap"],"image":"📖","examples":[{"type":"basic","zh":"我们重温了老电影。","pinyin":"Wǒmen chóngwēnle lǎo diànyǐng.","vi":"Chúng tôi đã xem lại những bộ phim cũ."},{"type":"simple","zh":"考试前，他把上学期的笔记重温了一遍。","pinyin":"Kǎoshì qián, tā bǎ shàng xuéqī de bǐjì chóngwēnle yíbiàn.","vi":"Trước kỳ thi, cậu ấy ôn lại một lượt ghi chép của học kỳ trước."},{"type":"compound","zh":"每次翻开这本相册，我就仿佛重温了童年的时光。","pinyin":"Měi cì fānkāi zhè běn xiàngcè, wǒ jiù fǎngfú chóngwēnle tóngnián de shíguāng.","vi":"Mỗi lần mở cuốn album này, tôi như được sống lại quãng thời thơ ấu."}],"related":[{"hanzi":"回顾","pinyin":"huígù","vi":"nhìn lại"},{"hanzi":"复习","pinyin":"fùxí","vi":"ôn tập"},{"hanzi":"回忆","pinyin":"huíyì","vi":"hồi tưởng"},{"hanzi":"温故知新","pinyin":"wēngùzhīxīn","vi":"ôn cũ biết mới"}],"traditional":"重溫"},{"id":"重阳节","hanzi":"重阳节","pinyin":"Chóngyángjié","meaning_vi":"Tết Trùng Cửu (mùng 9/9 Âm lịch)","explanation":"Lễ hội leo núi và kính trọng người cao tuổi.","hsk_level":6,"tags":["danh-tu","van-hoa","thoi-gian"],"image":"⛰️","examples":[{"type":"basic","zh":"今天是重阳节。","pinyin":"Jīntiān shì Chóngyángjié.","vi":"Hôm nay là Tết Trùng Cửu."},{"type":"simple","zh":"重阳节那天，我们陪爷爷奶奶去爬山。","pinyin":"Chóngyángjié nà tiān, wǒmen péi yéye nǎinai qù páshān.","vi":"Ngày Tết Trùng Cửu, chúng tôi đưa ông bà đi leo núi."},{"type":"compound","zh":"重阳节一到，社区就会组织志愿者去看望孤寡老人。","pinyin":"Chóngyángjié yí dào, shèqū jiù huì zǔzhī zhìyuànzhě qù kànwàng gūguǎ lǎorén.","vi":"Hễ đến Tết Trùng Cửu, khu dân cư lại tổ chức tình nguyện viên đi thăm người già neo đơn."}],"related":[{"hanzi":"中秋节","pinyin":"Zhōngqiūjié","vi":"Tết Trung thu"},{"hanzi":"登高","pinyin":"dēnggāo","vi":"leo núi"},{"hanzi":"敬老","pinyin":"jìnglǎo","vi":"kính lão"},{"hanzi":"菊花","pinyin":"júhuā","vi":"hoa cúc"}],"traditional":"重陽節"},{"id":"重整旗鼓","hanzi":"重整旗鼓","pinyin":"chóngzhěng-qígǔ","meaning_vi":"chấn chỉnh đội ngũ làm lại từ đầu","explanation":"重整 (trùng chỉnh – chỉnh đốn lại) + 旗鼓 (kỳ cổ – cờ và trống trận) → chỉnh đốn lại cờ trống → tập hợp lực lượng làm lại sau thất bại.","hsk_level":6,"tags":["thanh-ngu"],"image":"🚩","examples":[{"type":"basic","zh":"球队决定重整旗鼓。","pinyin":"Qiúduì juédìng chóngzhěngqígǔ.","vi":"Đội bóng quyết định chấn chỉnh lại đội ngũ."},{"type":"simple","zh":"生意失败后，他回到老家重整旗鼓。","pinyin":"Shēngyi shībài hòu, tā huídào lǎojiā chóngzhěngqígǔ.","vi":"Sau khi làm ăn thất bại, anh ấy về quê gây dựng lại từ đầu."},{"type":"compound","zh":"虽然这次比赛输了，但是我们明年一定会重整旗鼓。","pinyin":"Suīrán zhè cì bǐsài shū le, dànshì wǒmen míngnián yídìng huì chóngzhěngqígǔ.","vi":"Tuy trận này thua rồi, nhưng năm sau chúng tôi nhất định sẽ làm lại từ đầu."}],"related":[{"hanzi":"东山再起","pinyin":"dōngshānzàiqǐ","vi":"gây dựng lại sự nghiệp"},{"hanzi":"卷土重来","pinyin":"juǎntǔchónglái","vi":"quay trở lại"},{"hanzi":"从头再来","pinyin":"cóngtóuzàilái","vi":"làm lại từ đầu"},{"hanzi":"一蹶不振","pinyin":"yìjuébúzhèn","vi":"gục ngã không gượng dậy"}]},{"id":"筹集","hanzi":"筹集","pinyin":"chóují","meaning_vi":"quyên góp, huy động (vốn/tiền)","explanation":"筹 (tính toán) + 集 (gom lại).","hsk_level":6,"tags":["dong-tu","tien-te"],"image":"💰","examples":[{"type":"basic","zh":"他们在筹集资金。","pinyin":"Tāmen zài chóují zījīn.","vi":"Họ đang huy động vốn."},{"type":"simple","zh":"同学们通过义卖为山区小学筹集了五万元。","pinyin":"Tóngxuémen tōngguò yìmài wèi shānqū xiǎoxué chóujíle wǔ wàn yuán.","vi":"Các bạn học đã quyên góp được năm vạn tệ cho trường tiểu học vùng núi qua buổi bán hàng từ thiện."},{"type":"compound","zh":"如果筹集不到足够的经费，这个项目就只能推迟。","pinyin":"Rúguǒ chóují búdào zúgòu de jīngfèi, zhè ge xiàngmù jiù zhǐnéng tuīchí.","vi":"Nếu không huy động đủ kinh phí, dự án này đành phải lùi lại."}],"related":[{"hanzi":"筹款","pinyin":"chóukuǎn","vi":"gây quỹ"},{"hanzi":"募捐","pinyin":"mùjuān","vi":"quyên góp"},{"hanzi":"集资","pinyin":"jízī","vi":"huy động vốn"},{"hanzi":"资金","pinyin":"zījīn","vi":"vốn"}],"traditional":"籌集"},{"id":"愁眉苦脸","hanzi":"愁眉苦脸","pinyin":"chóuméi-kǔliǎn","meaning_vi":"mặt mày ủ rũ buồn rầu","explanation":"愁眉 (sầu mi – lông mày rầu rĩ) + 苦脸 (khổ kiểm – mặt khổ sở) → mặt mày nhăn nhó, rầu rĩ vì lo buồn.","hsk_level":6,"tags":["thanh-ngu","cam-xuc"],"image":"😟","examples":[{"type":"basic","zh":"他整天愁眉苦脸的。","pinyin":"Tā zhěngtiān chóuméikǔliǎn de.","vi":"Anh ấy cả ngày mặt mày ủ rũ."},{"type":"simple","zh":"拿到成绩单后，弟弟愁眉苦脸地坐在门口。","pinyin":"Nádào chéngjìdān hòu, dìdi chóuméikǔliǎn de zuò zài ménkǒu.","vi":"Nhận phiếu điểm xong, em trai ngồi ủ rũ ở cửa."},{"type":"compound","zh":"与其愁眉苦脸地等结果，不如出去走走放松一下。","pinyin":"Yǔqí chóuméikǔliǎn de děng jiéguǒ, bùrú chūqù zǒu zou fàngsōng yíxià.","vi":"Thay vì mặt ủ mày chau ngồi chờ kết quả, chi bằng ra ngoài dạo một chút cho thư giãn."}],"related":[{"hanzi":"垂头丧气","pinyin":"chuítóusàngqì","vi":"cúi đầu ủ rũ"},{"hanzi":"愁眉不展","pinyin":"chóuméibùzhǎn","vi":"mặt mày cau có"},{"hanzi":"眉开眼笑","pinyin":"méikāiyǎnxiào","vi":"mặt mày hớn hở"},{"hanzi":"忧愁","pinyin":"yōuchóu","vi":"buồn rầu"}],"traditional":"愁眉苦臉"},{"id":"筹码","hanzi":"筹码","pinyin":"chóumǎ","meaning_vi":"phỉnh, thẻ (đánh bạc); con bài mặc cả","explanation":"筹 (trù – thẻ tính) + 码 (mã – con số, phỉnh) → thẻ, phỉnh tính điểm khi đánh bạc; nghĩa bóng: con bài mặc cả, lợi thế trong đàm phán. Cụm: 谈判筹码.","hsk_level":6,"tags":["danh-tu"],"image":"🎲","examples":[{"type":"basic","zh":"他手里还有筹码。","pinyin":"Tā shǒulǐ háiyǒu chóumǎ.","vi":"Anh ta trong tay vẫn còn con bài mặc cả."},{"type":"simple","zh":"赌客把面前所有的筹码都推到了桌子中央。","pinyin":"Dǔkè bǎ miànqián suǒyǒu de chóumǎ dōu tuī dàole zhuōzi zhōngyāng.","vi":"Người chơi đẩy toàn bộ phỉnh trước mặt ra giữa bàn."},{"type":"compound","zh":"因为掌握了核心技术，所以公司在谈判中多了一个筹码。","pinyin":"Yīnwèi zhǎngwòle héxīnjìshù, suǒyǐ gōngsī zài tánpàn zhōng duōle yí gè chóumǎ.","vi":"Vì nắm được công nghệ cốt lõi nên công ty có thêm một con bài trong đàm phán."}],"related":[{"hanzi":"赌注","pinyin":"dǔzhù","vi":"tiền cược"},{"hanzi":"谈判","pinyin":"tánpàn","vi":"đàm phán"},{"hanzi":"砝码","pinyin":"fǎmǎ","vi":"quả cân"},{"hanzi":"资本","pinyin":"zīběn","vi":"vốn liếng"}],"traditional":"籌碼"},{"id":"触犯","hanzi":"触犯","pinyin":"chùfàn","meaning_vi":"xúc phạm, vi phạm","explanation":"触 (xúc – chạm) + 犯 (phạm – xâm phạm) → chạm đến, vi phạm (pháp luật, lợi ích, cấm kỵ) hoặc làm mếch lòng người khác. Thường: 触犯法律.","hsk_level":6,"tags":["dong-tu"],"image":"🚫","examples":[{"type":"basic","zh":"他触犯了法律。","pinyin":"Tā chùfànle fǎlǜ.","vi":"Anh ta đã vi phạm pháp luật."},{"type":"simple","zh":"这句话无意中触犯了当地人的禁忌。","pinyin":"Zhè jù huà wúyìzhōng chùfànle dāngdìrén de jìnjì.","vi":"Câu nói này vô tình phạm vào điều kiêng kỵ của người địa phương."},{"type":"compound","zh":"即使你不是故意的，触犯了校规也要受到处分。","pinyin":"Jíshǐ nǐ bú shì gùyì de, chùfànle xiàoguī yě yào shòudào chǔfèn.","vi":"Dù bạn không cố ý, vi phạm nội quy nhà trường cũng phải chịu kỷ luật."}],"related":[{"hanzi":"违反","pinyin":"wéifǎn","vi":"vi phạm"},{"hanzi":"冒犯","pinyin":"màofàn","vi":"mạo phạm"},{"hanzi":"触犯法律","pinyin":"chùfànfǎlǜ","vi":"vi phạm pháp luật"},{"hanzi":"得罪","pinyin":"dézuì","vi":"đắc tội"}],"traditional":"觸犯"},{"id":"触景生情","hanzi":"触景生情","pinyin":"chùjǐng-shēngqíng","meaning_vi":"tức cảnh sinh tình","explanation":"触景 (xúc cảnh – gặp cảnh) + 生情 (sinh tình – nảy sinh cảm xúc) → gặp cảnh mà nảy sinh cảm xúc, tức cảnh sinh tình (thường gợi nhớ chuyện cũ).","hsk_level":6,"tags":["thanh-ngu","cam-xuc"],"image":"🌄","examples":[{"type":"basic","zh":"她不禁触景生情。","pinyin":"Tā bùjīn chùjǐngshēngqíng.","vi":"Cô ấy không khỏi tức cảnh sinh tình."},{"type":"simple","zh":"老人在故居前触景生情地讲起了往事。","pinyin":"Lǎorén zài gùjū qián chùjǐngshēngqíng de jiǎng qǐle wǎngshì.","vi":"Ông lão đứng trước nhà cũ tức cảnh sinh tình kể lại chuyện xưa."},{"type":"compound","zh":"每当走过那条小巷，我就会触景生情，想起外婆。","pinyin":"Měidāng zǒuguò nà tiáo xiǎoxiàng, wǒ jiù huì chùjǐngshēngqíng, xiǎngqǐ wàipó.","vi":"Mỗi lần đi qua con hẻm đó, tôi lại tức cảnh sinh tình mà nhớ đến bà ngoại."}],"related":[{"hanzi":"睹物思人","pinyin":"dǔwùsīrén","vi":"nhìn vật nhớ người"},{"hanzi":"感慨","pinyin":"gǎnkǎi","vi":"cảm khái"},{"hanzi":"怀旧","pinyin":"huáijiù","vi":"hoài cổ"},{"hanzi":"情景","pinyin":"qíngjǐng","vi":"cảnh tình"}],"traditional":"觸景生情"},{"id":"触类旁通","hanzi":"触类旁通","pinyin":"chùlèi-pángtōng","meaning_vi":"hiểu một biết mười, suy rộng ra các vấn đề tương tự","explanation":"触类 (xúc loại – chạm tới một loại) + 旁通 (bàng thông – thông suốt sang bên) → nắm được một điều thì suy ra hiểu những điều cùng loại (gốc Kinh Dịch).","hsk_level":6,"tags":["thanh-ngu","hoc-tap"],"image":"💡","examples":[{"type":"basic","zh":"学习要触类旁通。","pinyin":"Xuéxí yào chùlèipángtōng.","vi":"Học tập phải biết suy một ra mười."},{"type":"simple","zh":"他学会一种乐器后很快就触类旁通了。","pinyin":"Tā xuéhuì yì zhǒng yuèqì hòu hěn kuài jiù chùlèipángtōng le.","vi":"Học xong một nhạc cụ, anh ấy nhanh chóng hiểu một biết mười."},{"type":"compound","zh":"只要真正理解了基本原理，你就能触类旁通。","pinyin":"Zhǐyào zhēnzhèng lǐjiěle jīběn yuánlǐ, nǐ jiù néng chùlèipángtōng.","vi":"Chỉ cần thật sự hiểu nguyên lý cơ bản, bạn sẽ có thể suy rộng ra những vấn đề tương tự."}],"related":[{"hanzi":"举一反三","pinyin":"jǔyìfǎnsān","vi":"suy một ra ba"},{"hanzi":"融会贯通","pinyin":"rónghuìguàntōng","vi":"hiểu thấu đáo"},{"hanzi":"一窍不通","pinyin":"yíqiàobùtōng","vi":"mù tịt"},{"hanzi":"类推","pinyin":"lèituī","vi":"suy luận tương tự"}],"traditional":"觸類旁通"},{"id":"除","hanzi":"除","pinyin":"chú","meaning_vi":"bỏ đi, loại trừ; ngoài… ra; phép chia","explanation":"除 (trừ): bỏ đi, loại trừ (除草, 除害); ngoài… ra (除了); phép chia (六除以二等于三). Lưu ý: phép trừ là 减.","hsk_level":6,"tags":["dong-tu"],"image":"➗","examples":[{"type":"basic","zh":"十除以二等于五。","pinyin":"Shí chúyǐ èr děngyú wǔ.","vi":"Mười chia hai bằng năm."},{"type":"simple","zh":"他用总分除以科目数算出了平均分。","pinyin":"Tāyòng zǒngfēn chúyǐ kēmù shù suànchūle píngjūnfēn.","vi":"Cậu ấy lấy tổng điểm chia cho số môn để tính ra điểm trung bình."},{"type":"compound","zh":"如果把六十除以四，得到的商就是十五。","pinyin":"Rúguǒ bǎ liùshí chúyǐ sì, dédào de shāng jiùshì shíwǔ.","vi":"Nếu lấy sáu mươi chia cho bốn thì thương nhận được là mười lăm."}],"related":[{"hanzi":"除了","pinyin":"chúle","vi":"ngoài ra"},{"hanzi":"除法","pinyin":"chúfǎ","vi":"phép chia"},{"hanzi":"去除","pinyin":"qùchú","vi":"loại bỏ"},{"hanzi":"清除","pinyin":"qīngchú","vi":"dọn sạch"}]},{"id":"除旧布新","hanzi":"除旧布新","pinyin":"chújiù-bùxīn","meaning_vi":"bỏ cũ đón mới (dịp Tết)","explanation":"除旧 (trừ cựu – bỏ cái cũ) + 布新 (bố tân – bày ra cái mới) → bỏ cũ thay mới; thường nói về phong tục dọn dẹp đón Tết hoặc đổi mới xã hội.","hsk_level":6,"tags":["thanh-ngu","van-hoa"],"image":"🧧","examples":[{"type":"basic","zh":"春节前家家除旧布新。","pinyin":"Chūnjié qián jiā jiā chújiùbùxīn.","vi":"Trước Tết nhà nhà bỏ cũ đón mới."},{"type":"simple","zh":"腊月二十四，家家户户都忙着除旧布新。","pinyin":"Làyuè èr shísì, jiājiāhùhù dōu mángzhe chújiùbùxīn.","vi":"Ngày hai mươi tư tháng Chạp, nhà nhà đều tất bật dọn cũ đón mới."},{"type":"compound","zh":"新领导一上任，就在公司里除旧布新，改了很多老规定。","pinyin":"Xīn lǐngdǎo yí shàngrèn, jiù zài gōngsī lǐ chújiùbùxīn, gǎile hěn duō lǎo guīdìng.","vi":"Lãnh đạo mới vừa nhậm chức đã bỏ cũ thay mới trong công ty, sửa nhiều quy định cũ."}],"related":[{"hanzi":"辞旧迎新","pinyin":"cíjiùyíngxīn","vi":"tiễn cũ đón mới"},{"hanzi":"推陈出新","pinyin":"tuīchénchūxīn","vi":"bỏ cũ thay mới"},{"hanzi":"春节","pinyin":"Chūnjié","vi":"Tết Nguyên Đán"},{"hanzi":"大扫除","pinyin":"dàsǎochú","vi":"tổng vệ sinh"}],"traditional":"除舊布新"},{"id":"醇厚","hanzi":"醇厚","pinyin":"chúnhòu","meaning_vi":"đậm đà (rượu, trà); chất phác, thuần hậu","explanation":"醇 (thuần – rượu đậm, tinh khiết) + 厚 (hậu – dày, đậm) → hương vị đậm đà, êm (rượu, trà); tính tình chất phác, thuần hậu.","hsk_level":6,"tags":["tinh-tu","an-uong"],"image":"🍷","examples":[{"type":"basic","zh":"这酒味道醇厚。","pinyin":"Zhè jiǔ wèidào chúnhòu.","vi":"Rượu này hương vị đậm đà."},{"type":"simple","zh":"这壶陈年普洱茶的口感特别醇厚。","pinyin":"Zhè hú chénnián Pǔ'ěrchá de kǒugǎn tèbié chúnhòu.","vi":"Ấm trà Phổ Nhĩ lâu năm này có vị đặc biệt đậm đà."},{"type":"compound","zh":"这里的村民既醇厚又好客，让游客感到很温暖。","pinyin":"Zhèlǐ de cūnmín jì chúnhòu yòu hàokè, ràng yóukè gǎndào hěn wēnnuǎn.","vi":"Người dân ở đây vừa chất phác vừa hiếu khách, khiến du khách cảm thấy ấm áp."}],"related":[{"hanzi":"浓郁","pinyin":"nóngyù","vi":"nồng đượm"},{"hanzi":"香醇","pinyin":"xiāngchún","vi":"thơm nồng"},{"hanzi":"淳朴","pinyin":"chúnpǔ","vi":"chất phác"},{"hanzi":"清淡","pinyin":"qīngdàn","vi":"thanh nhạt"}]},{"id":"唇亡齿寒","hanzi":"唇亡齿寒","pinyin":"chúnwáng-chǐhán","meaning_vi":"môi hở răng lạnh (quan hệ sống còn gắn bó)","explanation":"唇亡 (thần vong – môi mất) + 齿寒 (xỉ hàn – răng lạnh) → môi hở răng lạnh (truyện Tấn mượn đường nước Ngu đánh nước Quắc) → hai bên gắn bó, một bên mất thì bên kia nguy.","hsk_level":6,"tags":["thanh-ngu"],"image":"🦷","examples":[{"type":"basic","zh":"两国唇亡齿寒。","pinyin":"Liǎngguó chúnwángchǐhán.","vi":"Hai nước như môi với răng."},{"type":"simple","zh":"上下游企业之间是唇亡齿寒的关系。","pinyin":"Shàngxiàyóu qǐyè zhījiān shì chúnwángchǐhán de guānxì.","vi":"Các doanh nghiệp thượng nguồn và hạ nguồn có quan hệ môi hở răng lạnh."},{"type":"compound","zh":"因为两家店唇亡齿寒，所以一家关门后另一家也撑不下去了。","pinyin":"Yīnwèi liǎng jiā diàn chúnwángchǐhán, suǒyǐ yìjiā guānmén hòu lìng yìjiā yě chēng bú xiàqù le.","vi":"Vì hai cửa hàng gắn bó như môi với răng nên một nhà đóng cửa thì nhà kia cũng không trụ nổi."}],"related":[{"hanzi":"唇齿相依","pinyin":"chúnchǐxiāngyī","vi":"gắn bó như môi với răng"},{"hanzi":"休戚相关","pinyin":"xiūqīxiāngguān","vi":"vui buồn có nhau"},{"hanzi":"息息相关","pinyin":"xīxīxiāngguān","vi":"liên quan mật thiết"},{"hanzi":"毫不相干","pinyin":"háobùxiānggān","vi":"không liên quan"}],"traditional":"唇亡齒寒"},{"id":"差错","hanzi":"差错","pinyin":"chācuò","meaning_vi":"sai sót; sự cố bất trắc","explanation":"差 (lệch) + 错 (sai).","hsk_level":6,"tags":["danh-tu"],"image":"⚠️","examples":[{"type":"basic","zh":"账目出了差错。","pinyin":"Zhàngmù chūle chācuò.","vi":"Sổ sách có sai sót."},{"type":"simple","zh":"这次手术不能有半点差错。","pinyin":"Zhè cì shǒushù bù néng yǒu bàn diǎn chācuò.","vi":"Ca phẫu thuật lần này không được có chút sai sót nào."},{"type":"compound","zh":"万一路上出了什么差错，你就马上给我打电话。","pinyin":"Wànyī lùshang chūle shénme chācuò, nǐ jiù mǎshàng gěi wǒ dǎdiànhuà.","vi":"Lỡ trên đường có sự cố gì, bạn hãy gọi điện cho tôi ngay."}],"related":[{"hanzi":"错误","pinyin":"cuòwù","vi":"lỗi sai"},{"hanzi":"失误","pinyin":"shīwù","vi":"sai sót"},{"hanzi":"过错","pinyin":"guòcuò","vi":"lỗi lầm"},{"hanzi":"万无一失","pinyin":"wànwúyìshī","vi":"không hề sai sót"}],"traditional":"差錯"},{"id":"差强人意","hanzi":"差强人意","pinyin":"chāqiáng-rényì","meaning_vi":"tạm chấp nhận được, tạm hài lòng","explanation":"差 (hơi) + 强人意 (làm người ta hài lòng). Thành ngữ hay thi HSK 6.","hsk_level":6,"tags":["thanh-ngu"],"image":"👌","examples":[{"type":"basic","zh":"结果差强人意。","pinyin":"Jiéguǒ chāqiángrényì.","vi":"Kết quả tạm chấp nhận được."},{"type":"simple","zh":"这家新餐厅的服务还算差强人意。","pinyin":"Zhè jiā xīn cāntīng de fúwù hái suàn chāqiángrényì.","vi":"Dịch vụ của nhà hàng mới này cũng tạm được."},{"type":"compound","zh":"虽然这次成绩只是差强人意，但是比上次进步了不少。","pinyin":"Suīrán zhè cì chéngjì zhǐshì chāqiángrényì, dànshì bǐ shàngcì jìnbùle bùshǎo.","vi":"Tuy thành tích lần này chỉ tạm được, nhưng đã tiến bộ khá nhiều so với lần trước."}],"related":[{"hanzi":"勉强","pinyin":"miǎnqiǎng","vi":"miễn cưỡng"},{"hanzi":"过得去","pinyin":"guòdeqù","vi":"tạm được"},{"hanzi":"尚可","pinyin":"shàngkě","vi":"còn được"},{"hanzi":"令人满意","pinyin":"lìngrénmǎnyì","vi":"làm người ta hài lòng"}],"traditional":"差強人意"},{"id":"掺杂","hanzi":"掺杂","pinyin":"chānzá","meaning_vi":"pha trộn, lẫn lộn","explanation":"掺 (trộn) + 杂 (lẫn).","hsk_level":6,"tags":["dong-tu"],"image":"🧪","examples":[{"type":"basic","zh":"米里掺杂着沙子。","pinyin":"Mǐ lǐ chānzázhe shāzi.","vi":"Trong gạo có lẫn sạn."},{"type":"simple","zh":"他的普通话里掺杂着浓重的四川口音。","pinyin":"Tā de pǔtōnghuà lǐ chānzázhe nóngzhòng de Sìchuān kǒuyīn.","vi":"Tiếng phổ thông của anh ấy pha lẫn giọng Tứ Xuyên nặng."},{"type":"compound","zh":"如果评选中掺杂了个人感情，结果就不公平了。","pinyin":"Rúguǒ píngxuǎn zhōng chānzále gèrén gǎnqíng, jiéguǒ jiù bù gōngpíng le.","vi":"Nếu trong việc bình chọn có lẫn tình cảm cá nhân thì kết quả sẽ không công bằng."}],"related":[{"hanzi":"混杂","pinyin":"hùnzá","vi":"lẫn lộn"},{"hanzi":"夹杂","pinyin":"jiāzá","vi":"xen lẫn"},{"hanzi":"混合","pinyin":"hùnhé","vi":"hỗn hợp"},{"hanzi":"纯粹","pinyin":"chúncuì","vi":"thuần túy"}],"traditional":"摻雜"},{"id":"猖狂","hanzi":"猖狂","pinyin":"chāngkuáng","meaning_vi":"ngông cuồng, điên cuồng (tội phạm)","explanation":"Cả hai chữ đều có bộ khuyển 犭.","hsk_level":6,"tags":["tinh-tu"],"image":"👹","examples":[{"type":"basic","zh":"这伙小偷很猖狂。","pinyin":"Zhè huǒ xiǎotōu hěn chāngkuáng.","vi":"Bọn trộm này rất ngông cuồng."},{"type":"simple","zh":"最近电信诈骗活动十分猖狂。","pinyin":"Zuìjìn diànxìn zhàpiàn huódòng shífēn chāngkuáng.","vi":"Gần đây hoạt động lừa đảo qua điện thoại hoành hành dữ dội."},{"type":"compound","zh":"因为歹徒越来越猖狂，所以警方加强了夜间巡逻。","pinyin":"Yīnwèi dǎitú yuèláiyuè chāngkuáng, suǒyǐ jǐngfāng jiāqiángle yèjiān xúnluó.","vi":"Vì bọn côn đồ ngày càng ngông cuồng nên cảnh sát đã tăng cường tuần tra ban đêm."}],"related":[{"hanzi":"嚣张","pinyin":"xiāozhāng","vi":"hung hăng"},{"hanzi":"疯狂","pinyin":"fēngkuáng","vi":"điên cuồng"},{"hanzi":"狂妄","pinyin":"kuángwàng","vi":"ngông cuồng"},{"hanzi":"收敛","pinyin":"shōuliǎn","vi":"kiềm chế"}]},{"id":"超标","hanzi":"超标","pinyin":"chāobiāo","meaning_vi":"vượt mức tiêu chuẩn cho phép","explanation":"超 (vượt) + 标 (tiêu chuẩn). Động từ ly hợp.","hsk_level":6,"tags":["dong-tu"],"image":"⚠️","examples":[{"type":"basic","zh":"这辆车尾气超标。","pinyin":"Zhè liàng chē wěiqì chāobiāo.","vi":"Khí thải xe này vượt mức tiêu chuẩn."},{"type":"simple","zh":"检测发现这批蔬菜的农药残留严重超标。","pinyin":"Jiǎncè fāxiàn zhè pī shūcài de nóngyào cánliú yánzhòng chāobiāo.","vi":"Kiểm tra phát hiện dư lượng thuốc trừ sâu trong lô rau này vượt chuẩn nghiêm trọng."},{"type":"compound","zh":"一旦行李超标，你就得另外付托运费。","pinyin":"Yídàn xíngli chāobiāo, nǐ jiù děi lìngwài fùtuō yùnfèi.","vi":"Một khi hành lý vượt quá quy định, bạn phải trả thêm phí ký gửi."}],"related":[{"hanzi":"超过","pinyin":"chāoguò","vi":"vượt quá"},{"hanzi":"标准","pinyin":"biāozhǔn","vi":"tiêu chuẩn"},{"hanzi":"达标","pinyin":"dábiāo","vi":"đạt chuẩn"},{"hanzi":"超载","pinyin":"chāozài","vi":"quá tải"}],"traditional":"超標"},{"id":"超凡脱俗","hanzi":"超凡脱俗","pinyin":"chāofán-tuōsú","meaning_vi":"siêu phàm thoát tục","explanation":"超凡 (siêu phàm – vượt người thường) + 脱俗 (thoát tục – thoát khỏi thế tục) → khí chất, phẩm cách thanh cao, vượt lên sự tầm thường.","hsk_level":6,"tags":["thanh-ngu"],"image":"✨","examples":[{"type":"basic","zh":"她的气质超凡脱俗。","pinyin":"Tā de qìzhì chāofántuōsú.","vi":"Khí chất của cô ấy siêu phàm thoát tục."},{"type":"simple","zh":"山顶的古寺在云雾中显得超凡脱俗。","pinyin":"Shāndǐng de gǔ sì zài yúnwù zhōng xiǎnde chāofántuōsú.","vi":"Ngôi chùa cổ trên đỉnh núi giữa mây mù trông thật thoát tục."},{"type":"compound","zh":"虽然他看起来超凡脱俗，但是生活中也有很多烦恼。","pinyin":"Suīrán tā kànqǐlái chāofántuōsú, dànshì shēnghuó zhōng yě yǒu hěn duō fánnǎo.","vi":"Tuy trông anh ấy siêu phàm thoát tục, nhưng trong cuộc sống cũng có nhiều phiền muộn."}],"related":[{"hanzi":"超凡","pinyin":"chāofán","vi":"siêu phàm"},{"hanzi":"脱俗","pinyin":"tuōsú","vi":"thoát tục"},{"hanzi":"清高","pinyin":"qīnggāo","vi":"thanh cao"},{"hanzi":"庸俗","pinyin":"yōngsú","vi":"dung tục"}],"traditional":"超凡脫俗"},{"id":"超前","hanzi":"超前","pinyin":"chāoqián","meaning_vi":"đi trước thời đại, vượt trước","explanation":"超 (siêu – vượt) + 前 (tiền – trước) → vượt lên trước (thời đại, điều kiện hiện tại). Cụm: 超前意识, 超前消费 (tiêu dùng vượt khả năng).","hsk_level":6,"tags":["tinh-tu"],"image":"🚀","examples":[{"type":"basic","zh":"他的想法很超前。","pinyin":"Tā de xiǎngfǎ hěn chāoqián.","vi":"Suy nghĩ của anh ấy rất đi trước thời đại."},{"type":"simple","zh":"这座图书馆的建筑设计在当时非常超前。","pinyin":"Zhè zuò túshūguǎn de jiànzhù shèjì zài dāngshí fēicháng chāoqián.","vi":"Thiết kế kiến trúc của thư viện này vào thời điểm đó rất vượt thời đại."},{"type":"compound","zh":"因为观念太超前，所以他的发明当时没人看得懂。","pinyin":"Yīnwèi guānniàn tài chāoqián, suǒyǐ tā de fāmíng dāngshí méi rén kàn de dǒng.","vi":"Vì quan niệm quá đi trước thời đại nên phát minh của ông khi đó không ai hiểu được."}],"related":[{"hanzi":"领先","pinyin":"lǐngxiān","vi":"dẫn đầu"},{"hanzi":"超前消费","pinyin":"chāoqiánxiāofèi","vi":"tiêu dùng vượt khả năng"},{"hanzi":"先进","pinyin":"xiānjìn","vi":"tiên tiến"},{"hanzi":"滞后","pinyin":"zhìhòu","vi":"chậm trễ"}]},{"id":"超越","hanzi":"超越","pinyin":"chāoyuè","meaning_vi":"vượt qua","explanation":"超 (siêu – vượt) + 越 (việt – vượt qua) → vượt qua, vượt lên trên. Thường: 超越自我, 超越对手, 超越时代.","hsk_level":6,"tags":["dong-tu"],"image":"🚀","examples":[{"type":"basic","zh":"他超越了自己。","pinyin":"Tā chāoyuèle zìjǐ.","vi":"Anh ấy đã vượt qua chính mình."},{"type":"simple","zh":"最后一圈，二号选手成功超越了对手。","pinyin":"Zuìhòu yìquān, èrhào xuǎnshǒu chénggōng chāoyuèle duìshǒu.","vi":"Ở vòng cuối, vận động viên số hai đã vượt qua đối thủ thành công."},{"type":"compound","zh":"只要每天比昨天进步一点，你就能不断超越自我。","pinyin":"Zhǐyào měitiān bǐ zuótiān jìnbù yìdiǎn, nǐ jiù néng búduàn chāoyuè zìwǒ.","vi":"Chỉ cần mỗi ngày tiến bộ hơn hôm qua một chút, bạn sẽ không ngừng vượt qua chính mình."}],"related":[{"hanzi":"超过","pinyin":"chāoguò","vi":"vượt qua"},{"hanzi":"超出","pinyin":"chāochū","vi":"vượt ra ngoài"},{"hanzi":"突破","pinyin":"tūpò","vi":"đột phá"},{"hanzi":"超越自我","pinyin":"chāoyuèzìwǒ","vi":"vượt qua chính mình"}]},{"id":"车水马龙","hanzi":"车水马龙","pinyin":"chēshuǐ-mǎlóng","meaning_vi":"xe cộ như nước, ngựa như rồng (tấp nập)","explanation":"车 (xa – xe) + 水 (thủy – nước) + 马 (mã – ngựa) + 龙 (long – rồng) → xe như nước chảy, ngựa như rồng lượn (Hậu Hán thư) → đường phố đông đúc, tấp nập.","hsk_level":6,"tags":["thanh-ngu","giao-thong"],"image":"🏙️","examples":[{"type":"basic","zh":"街上车水马龙。","pinyin":"Jiēshàng chēshuǐmǎlóng.","vi":"Đường phố xe cộ tấp nập."},{"type":"simple","zh":"下班时间，市中心的大街上车水马龙。","pinyin":"Xiàbān shíjiān, shìzhōngxīn de dà jiēshàng chēshuǐmǎlóng.","vi":"Giờ tan tầm, đường lớn ở trung tâm thành phố xe cộ nườm nượp."},{"type":"compound","zh":"这里虽然白天车水马龙，但是一到深夜就安静得出奇。","pinyin":"Zhèlǐ suīrán báitiān chēshuǐmǎlóng, dànshì yí dào shēnyè jiù ānjìng de chūqí.","vi":"Nơi này tuy ban ngày xe cộ tấp nập, nhưng hễ về khuya lại yên tĩnh lạ thường."}],"related":[{"hanzi":"熙熙攘攘","pinyin":"xīxīrǎngrǎng","vi":"tấp nập"},{"hanzi":"川流不息","pinyin":"chuānliúbùxī","vi":"nườm nượp không ngớt"},{"hanzi":"热闹","pinyin":"rènao","vi":"náo nhiệt"},{"hanzi":"门可罗雀","pinyin":"ménkěluóquè","vi":"vắng tanh"}],"traditional":"車水馬龍"},{"id":"称霸","hanzi":"称霸","pinyin":"chēngbà","meaning_vi":"xưng bá, làm bá chủ","explanation":"称 (gọi) + 霸 (bá chủ).","hsk_level":6,"tags":["dong-tu"],"image":"👑","examples":[{"type":"basic","zh":"这支球队称霸联赛。","pinyin":"Zhè zhī qiúduì chēngbà liánsài.","vi":"Đội bóng này thống trị giải đấu."},{"type":"simple","zh":"恐龙曾经称霸地球长达上亿年。","pinyin":"Kǒnglóng céngjīng chēngbà dìqiú chángdá shàng yì nián.","vi":"Khủng long từng làm bá chủ Trái Đất suốt hàng trăm triệu năm."},{"type":"compound","zh":"这家公司不但称霸国内市场，而且开始进军海外。","pinyin":"Zhè jiā gōngsī búdàn chēngbà guónèi shìchǎng, érqiě kāishǐ jìnjūn hǎiwài.","vi":"Công ty này không chỉ thống trị thị trường trong nước mà còn bắt đầu tiến ra nước ngoài."}],"related":[{"hanzi":"霸权","pinyin":"bàquán","vi":"bá quyền"},{"hanzi":"霸主","pinyin":"bàzhǔ","vi":"bá chủ"},{"hanzi":"称王","pinyin":"chēngwáng","vi":"xưng vương"},{"hanzi":"争霸","pinyin":"zhēngbà","vi":"tranh bá"}],"traditional":"稱霸"},{"id":"称号","hanzi":"称号","pinyin":"chēnghào","meaning_vi":"danh hiệu","explanation":"称 (xưng – gọi) + 号 (hiệu – tên hiệu) → danh xưng được trao tặng, danh hiệu. Thường: 荣誉称号, 获得…称号.","hsk_level":6,"tags":["danh-tu"],"image":"🏅","examples":[{"type":"basic","zh":"他获得了劳模称号。","pinyin":"Tā huòdéle láomó chēnghào.","vi":"Anh ấy nhận danh hiệu lao động kiểu mẫu."},{"type":"simple","zh":"这座小镇荣获了全国最美乡村的称号。","pinyin":"Zhè zuò xiǎozhèn rónghuòle quánguó zuì měi xiāngcūn de chēnghào.","vi":"Thị trấn nhỏ này đã vinh dự nhận danh hiệu làng quê đẹp nhất toàn quốc."},{"type":"compound","zh":"因为她连续三年业绩第一，所以获得了优秀员工称号。","pinyin":"Yīnwèi tā liánxù sān nián yèjì dìyī, suǒyǐ huòdéle yōuxiù yuángōng chēnghào.","vi":"Vì ba năm liền có thành tích đứng đầu nên cô ấy được trao danh hiệu nhân viên xuất sắc."}],"related":[{"hanzi":"名称","pinyin":"míngchēng","vi":"tên gọi"},{"hanzi":"头衔","pinyin":"tóuxián","vi":"danh hiệu"},{"hanzi":"荣誉","pinyin":"róngyù","vi":"vinh dự"},{"hanzi":"称呼","pinyin":"chēnghu","vi":"cách xưng hô"}],"traditional":"稱號"},{"id":"称兄道弟","hanzi":"称兄道弟","pinyin":"chēngxiōng-dàodì","meaning_vi":"gọi anh xưng em (quan hệ thân thiết)","explanation":"称兄 (xưng huynh – gọi anh) + 道弟 (đạo đệ – xưng em) → gọi nhau anh em → quan hệ thân thiết, suồng sã (đôi khi hàm ý kết bè kéo cánh).","hsk_level":6,"tags":["thanh-ngu","giao-tiep"],"image":"👬","examples":[{"type":"basic","zh":"他们俩称兄道弟。","pinyin":"Tāmen liǎ chēngxiōngdàodì.","vi":"Hai người họ gọi nhau anh anh em em."},{"type":"simple","zh":"他和村里的年轻人整天称兄道弟。","pinyin":"Tā hé cūnlǐ de niánqīngrén zhěngtiān chēngxiōngdàodì.","vi":"Anh ta suốt ngày xưng huynh gọi đệ với đám thanh niên trong làng."},{"type":"compound","zh":"虽然他们平时称兄道弟，但是一到关键时刻就各顾各了。","pinyin":"Suīrán tāmen píngshí chēngxiōngdàodì, dànshì yí dào guānjiànshíkè jiù gè gù gè le.","vi":"Tuy bình thường họ xưng huynh gọi đệ, nhưng đến lúc then chốt thì ai lo thân nấy."}],"related":[{"hanzi":"亲密","pinyin":"qīnmì","vi":"thân mật"},{"hanzi":"哥们儿","pinyin":"gēmenr","vi":"anh em bạn bè"},{"hanzi":"兄弟","pinyin":"xiōngdì","vi":"anh em"},{"hanzi":"交情","pinyin":"jiāoqing","vi":"tình giao hảo"}],"traditional":"稱兄道弟"},{"id":"吃喝玩乐","hanzi":"吃喝玩乐","pinyin":"chīhē-wánlè","meaning_vi":"ăn chơi hưởng lạc","explanation":"吃 (ngật – ăn) + 喝 (hát – uống) + 玩 (ngoạn – chơi) + 乐 (lạc – vui) → ăn uống vui chơi → chỉ lo hưởng thụ, ăn chơi. Mang ý chê.","hsk_level":6,"tags":["thanh-ngu"],"image":"🥳","examples":[{"type":"basic","zh":"他只知道吃喝玩乐。","pinyin":"Tā zhǐ zhīdào chīhēwánlè.","vi":"Anh ta chỉ biết ăn chơi hưởng lạc."},{"type":"simple","zh":"这几个富二代把父母的钱都花在了吃喝玩乐上。","pinyin":"Zhè jǐ gè fù'èrdài bǎ fùmǔ de qián dōu huā zài le chīhēwánlè shàng.","vi":"Mấy cậu ấm này tiêu hết tiền của bố mẹ vào việc ăn chơi hưởng lạc."},{"type":"compound","zh":"如果年轻时只顾吃喝玩乐，老了就会后悔。","pinyin":"Rúguǒ niánqīng shí zhǐgù chīhēwánlè, lǎole jiù huì hòuhuǐ.","vi":"Nếu lúc trẻ chỉ lo ăn chơi hưởng lạc thì về già sẽ hối hận."}],"related":[{"hanzi":"享乐","pinyin":"xiǎnglè","vi":"hưởng lạc"},{"hanzi":"游手好闲","pinyin":"yóushǒuhàoxián","vi":"du thủ du thực"},{"hanzi":"花天酒地","pinyin":"huātiānjiǔdì","vi":"ăn chơi trác táng"},{"hanzi":"勤奋","pinyin":"qínfèn","vi":"chăm chỉ"}],"traditional":"吃喝玩樂"},{"id":"吃苦耐劳","hanzi":"吃苦耐劳","pinyin":"chīkǔ-nàiláo","meaning_vi":"chịu thương chịu khó","explanation":"吃苦 (chịu khổ) + 耐劳 (bền bỉ lao động). Thành ngữ.","hsk_level":6,"tags":["thanh-ngu"],"image":"💪","examples":[{"type":"basic","zh":"农民们吃苦耐劳。","pinyin":"Nóngmínmen chīkǔnàiláo.","vi":"Người nông dân chịu thương chịu khó."},{"type":"simple","zh":"老板很欣赏这个吃苦耐劳的年轻人。","pinyin":"Lǎobǎn hěn xīnshǎng zhè ge chīkǔnàiláo de niánqīngrén.","vi":"Ông chủ rất quý chàng trai trẻ chịu thương chịu khó này."},{"type":"compound","zh":"她不但吃苦耐劳，而且脑子灵活，很快就当上了店长。","pinyin":"Tā búdàn chīkǔnàiláo, érqiě nǎozi línghuó, hěn kuài jiù dāngshàngle diànzhǎng.","vi":"Cô ấy không chỉ chịu thương chịu khó mà còn nhanh nhạy, chẳng bao lâu đã lên làm cửa hàng trưởng."}],"related":[{"hanzi":"吃苦","pinyin":"chīkǔ","vi":"chịu khổ"},{"hanzi":"勤劳","pinyin":"qínláo","vi":"cần cù"},{"hanzi":"任劳任怨","pinyin":"rènláorènyuàn","vi":"chịu khó không oán thán"},{"hanzi":"好逸恶劳","pinyin":"hàoyìwùláo","vi":"ham nhàn sợ khó"}],"traditional":"吃苦耐勞"},{"id":"吃力","hanzi":"吃力","pinyin":"chīlì","meaning_vi":"vất vả, tốn sức","explanation":"吃 (ngật – chịu, tốn) + 力 (lực – sức) → tốn sức, vất vả. Ví dụ: 学中文很吃力; 吃力不讨好 = làm vất vả mà chẳng được cảm ơn.","hsk_level":6,"tags":["tinh-tu"],"image":"😓","examples":[{"type":"basic","zh":"他走路有点吃力。","pinyin":"Tā zǒulù yǒudiǎn chīlì.","vi":"Anh ấy đi lại có phần khó nhọc."},{"type":"simple","zh":"外婆戴着老花镜吃力地读着报纸。","pinyin":"Wàipó dàizhe lǎohuājìng chīlì de dúzhe bàozhǐ.","vi":"Bà ngoại đeo kính lão chật vật đọc báo."},{"type":"compound","zh":"因为基础太差，所以他学高等数学很吃力。","pinyin":"Yīnwèi jīchǔ tài chà, suǒyǐ tā xué gāoděng shùxué hěn chīlì.","vi":"Vì nền tảng quá kém nên cậu ấy học toán cao cấp rất vất vả."}],"related":[{"hanzi":"费力","pinyin":"fèilì","vi":"tốn sức"},{"hanzi":"辛苦","pinyin":"xīnkǔ","vi":"vất vả"},{"hanzi":"轻松","pinyin":"qīngsōng","vi":"nhẹ nhàng"},{"hanzi":"吃力不讨好","pinyin":"chīlì bù tǎohǎo","vi":"mất công mà chẳng được gì"}]},{"id":"痴迷","hanzi":"痴迷","pinyin":"chīmí","meaning_vi":"si mê, mê mẩn","explanation":"痴 (say mê) + 迷 (mê).","hsk_level":6,"tags":["dong-tu","cam-xuc"],"image":"😍","examples":[{"type":"basic","zh":"他痴迷于下棋。","pinyin":"Tā chīmí yú xiàqí.","vi":"Anh ấy say mê chơi cờ."},{"type":"simple","zh":"这位老人痴迷收集各个年代的邮票。","pinyin":"Zhè wèi lǎorén chīmí shōují gègè niándài de yóupiào.","vi":"Cụ già này mê mẩn sưu tầm tem của nhiều thời kỳ."},{"type":"compound","zh":"他对昆虫痴迷到了极点，一有空就去山里找蝴蝶。","pinyin":"Tā duì kūnchóng chīmí dàole jídiǎn, yì yǒukòng jiù qù shān lǐ zhǎo húdié.","vi":"Anh ấy mê côn trùng đến cực điểm, hễ rảnh là vào núi tìm bướm."}],"related":[{"hanzi":"着迷","pinyin":"zháomí","vi":"say mê"},{"hanzi":"沉迷","pinyin":"chénmí","vi":"đắm chìm"},{"hanzi":"入迷","pinyin":"rùmí","vi":"mê mẩn"},{"hanzi":"迷恋","pinyin":"míliàn","vi":"mê luyến"}],"traditional":"癡迷"},{"id":"痴心妄想","hanzi":"痴心妄想","pinyin":"chīxīn-wàngxiǎng","meaning_vi":"mơ tưởng hão huyền viển vông","explanation":"痴心 (si tâm – lòng si mê) + 妄想 (vọng tưởng – nghĩ viển vông) → si mê mà nghĩ tới điều không thể thực hiện → mơ tưởng hão huyền.","hsk_level":6,"tags":["thanh-ngu"],"image":"💭","examples":[{"type":"basic","zh":"别再痴心妄想了。","pinyin":"Bié zài chīxīnwàngxiǎng le.","vi":"Đừng mơ tưởng hão huyền nữa."},{"type":"simple","zh":"他总是痴心妄想靠买彩票发大财。","pinyin":"Tā zǒngshì chīxīnwàngxiǎng kào mǎi cǎipiào fā dà cái.","vi":"Anh ta lúc nào cũng mơ tưởng viển vông sẽ phát tài nhờ mua vé số."},{"type":"compound","zh":"如果不努力学习却想考上名校，那就是痴心妄想。","pinyin":"Rúguǒ bù nǔlì xuéxí què xiǎng kǎoshàng míngxiào, nà jiùshì chīxīnwàngxiǎng.","vi":"Nếu không chịu học hành mà lại muốn đỗ trường danh tiếng thì đó chỉ là mơ tưởng hão huyền."}],"related":[{"hanzi":"异想天开","pinyin":"yìxiǎngtiānkāi","vi":"nghĩ chuyện viển vông"},{"hanzi":"白日做梦","pinyin":"báirìzuòmèng","vi":"mơ giữa ban ngày"},{"hanzi":"妄想","pinyin":"wàngxiǎng","vi":"vọng tưởng"},{"hanzi":"脚踏实地","pinyin":"jiǎotàshídì","vi":"thực tế, chắc chắn"}],"traditional":"癡心妄想"},{"id":"吃一堑长一智","hanzi":"吃一堑长一智","pinyin":"chī yí qiàn zhǎng yí zhì","meaning_vi":"vấp một lần, khôn thêm một chút","explanation":"吃一堑 (ngã xuống hào một lần) + 长一智 (tăng thêm một phần khôn) → vấp ngã một lần thì khôn ra một chút → biết rút kinh nghiệm từ thất bại.","hsk_level":6,"tags":["thanh-ngu"],"image":"💡","examples":[{"type":"basic","zh":"这次就算吃一堑长一智吧。","pinyin":"Zhè cì jiùsuàn chīyíqiànzhǎngyízhì ba.","vi":"Lần này coi như vấp ngã một lần, khôn ra một chút vậy."},{"type":"simple","zh":"这次被骗让他懂得了吃一堑长一智的道理。","pinyin":"Zhè cì bèi piàn ràng tā dǒngdele chīyíqiànzhǎngyízhì de dàolǐ.","vi":"Lần bị lừa này giúp anh ấy hiểu ra đạo lý vấp một lần khôn ra một chút."},{"type":"compound","zh":"虽然这次投资亏了钱，但是吃一堑长一智，下次他会更谨慎。","pinyin":"Suīrán zhè cì tóuzī kuīle qián, dànshì chīyíqiànzhǎngyízhì, xiàcì tā huì gèng jǐnshèn.","vi":"Tuy lần đầu tư này lỗ tiền, nhưng vấp một lần khôn ra một chút, lần sau anh ấy sẽ thận trọng hơn."}],"related":[{"hanzi":"吸取教训","pinyin":"xīqǔjiàoxùn","vi":"rút ra bài học"},{"hanzi":"失败是成功之母","pinyin":"shībài shì chénggōng zhī mǔ","vi":"thất bại là mẹ thành công"},{"hanzi":"经验","pinyin":"jīngyàn","vi":"kinh nghiệm"},{"hanzi":"教训","pinyin":"jiàoxùn","vi":"bài học"}],"traditional":"吃一塹長一智"},{"id":"充斥","hanzi":"充斥","pinyin":"chōngchì","meaning_vi":"tràn ngập, đầy rẫy (thường mang nghĩa tiêu cực)","explanation":"充 (sung – đầy) + 斥 (xích – mở rộng, tràn) → tràn ngập, đầy rẫy, thường là thứ không tốt. Ví dụ: 市场上充斥着假货.","hsk_level":6,"tags":["dong-tu"],"image":"🌊","examples":[{"type":"basic","zh":"市场上充斥着假货。","pinyin":"Shìchǎng shàng chōngchìzhe jiǎhuò.","vi":"Thị trường tràn ngập hàng giả."},{"type":"simple","zh":"网络上充斥着各种真假难辨的消息。","pinyin":"Wǎngluò shàng chōngchìzhe gèzhǒng zhēnjiǎ nán biàn de xiāoxi.","vi":"Trên mạng đầy rẫy đủ loại tin tức thật giả khó phân biệt."},{"type":"compound","zh":"因为房间里充斥着烟味，所以她一进门就咳嗽起来。","pinyin":"Yīnwèi fángjiān lǐ chōngchìzhe yān wèi, suǒyǐ tā yí jìnmén jiù késou qǐlái.","vi":"Vì căn phòng nồng nặc mùi thuốc lá nên cô ấy vừa vào cửa đã ho sặc sụa."}],"related":[{"hanzi":"充满","pinyin":"chōngmǎn","vi":"tràn đầy"},{"hanzi":"泛滥","pinyin":"fànlàn","vi":"tràn lan"},{"hanzi":"遍布","pinyin":"biànbù","vi":"trải khắp"},{"hanzi":"充塞","pinyin":"chōngsè","vi":"nhồi nhét"}]},{"id":"冲动","hanzi":"冲动","pinyin":"chōngdòng","meaning_vi":"bốc đồng, kích động","explanation":"冲 + 动 (hành động).","hsk_level":6,"tags":["tinh-tu","cam-xuc"],"image":"🔥","examples":[{"type":"basic","zh":"你别太冲动。","pinyin":"Nǐ bié tài chōngdòng.","vi":"Bạn đừng quá bốc đồng."},{"type":"simple","zh":"她冲动地买下了一件很贵的大衣。","pinyin":"Tā chōngdòng de mǎixiàle yí jiàn hěn guì de dàyī.","vi":"Cô ấy bốc đồng mua ngay một chiếc áo khoác rất đắt."},{"type":"compound","zh":"如果当时不那么冲动，他就不会和朋友吵翻了。","pinyin":"Rúguǒ dāngshí bú nàme chōngdòng, tā jiù bú huì hé péngyou chǎo fān le.","vi":"Nếu lúc đó không bốc đồng như vậy thì anh ấy đã không cãi nhau to với bạn."}],"related":[{"hanzi":"激动","pinyin":"jīdòng","vi":"kích động"},{"hanzi":"鲁莽","pinyin":"lǔmǎng","vi":"lỗ mãng"},{"hanzi":"冷静","pinyin":"lěngjìng","vi":"bình tĩnh"},{"hanzi":"一时冲动","pinyin":"yìshíchōngdòng","vi":"bốc đồng nhất thời"}],"traditional":"衝動"},{"id":"充当","hanzi":"充当","pinyin":"chōngdāng","meaning_vi":"đóng vai trò","explanation":"充 (sung – đảm nhận) + 当 (đương – làm) → đảm nhận, đóng vai (thường là vai tạm thời). Thường: 充当翻译, 充当中间人.","hsk_level":6,"tags":["dong-tu"],"image":"👔","examples":[{"type":"basic","zh":"他充当翻译。","pinyin":"Tā chōngdāng fānyì.","vi":"Anh ấy đóng vai phiên dịch."},{"type":"simple","zh":"那块大石头在野餐时充当了我们的桌子。","pinyin":"Nà kuài dà shítou zài yěcān shí chōngdāngle wǒmen de zhuōzi.","vi":"Tảng đá lớn đó đã làm bàn cho chúng tôi trong buổi dã ngoại."},{"type":"compound","zh":"因为老师生病了，所以班长临时充当了主持人。","pinyin":"Yīnwèi lǎoshī shēngbìng le, suǒyǐ bānzhǎng línshí chōngdāngle zhǔchírén.","vi":"Vì thầy giáo bị ốm nên lớp trưởng tạm thời đảm nhận vai trò người dẫn chương trình."}],"related":[{"hanzi":"担任","pinyin":"dānrèn","vi":"đảm nhiệm"},{"hanzi":"扮演","pinyin":"bànyǎn","vi":"đóng vai"},{"hanzi":"作为","pinyin":"zuòwéi","vi":"với vai trò"},{"hanzi":"当作","pinyin":"dàngzuò","vi":"coi như"}],"traditional":"充當"},{"id":"冲锋陷阵","hanzi":"冲锋陷阵","pinyin":"chōngfēng-xiànzhèn","meaning_vi":"xung phong hãm trận, đi đầu tiên phong","explanation":"冲锋 (xung phong – xông lên) + 陷阵 (hãm trận – phá trận địch) → xông lên phá trận → chiến đấu dũng cảm; ví người đi đầu trong công việc.","hsk_level":6,"tags":["thanh-ngu"],"image":"⚔️","examples":[{"type":"basic","zh":"战士们冲锋陷阵。","pinyin":"Zhànshìmen chōngfēngxiànzhèn.","vi":"Các chiến sĩ xung phong hãm trận."},{"type":"simple","zh":"每次遇到难题，老张总是第一个冲锋陷阵。","pinyin":"Měi cì yùdào nántí, lǎo Zhāng zǒngshì dìyī gè chōngfēngxiànzhèn.","vi":"Mỗi khi gặp vấn đề khó, anh Trương luôn là người đầu tiên xông lên."},{"type":"compound","zh":"他不但在前线冲锋陷阵，而且还细心照顾受伤的战友。","pinyin":"Tā búdàn zài qiánxiàn chōngfēngxiànzhèn, érqiě hái xìxīn zhàogù shòushāng de zhànyǒu.","vi":"Anh ấy không chỉ xung phong hãm trận ở tiền tuyến mà còn chu đáo chăm sóc đồng đội bị thương."}],"related":[{"hanzi":"冲锋","pinyin":"chōngfēng","vi":"xung phong"},{"hanzi":"身先士卒","pinyin":"shēnxiānshìzú","vi":"đi đầu làm gương"},{"hanzi":"勇往直前","pinyin":"yǒngwǎngzhíqián","vi":"dũng cảm tiến lên"},{"hanzi":"临阵脱逃","pinyin":"línzhèntuōtáo","vi":"đào ngũ khi lâm trận"}],"traditional":"衝鋒陷陣"},{"id":"冲击","hanzi":"冲击","pinyin":"chōngjī","meaning_vi":"tác động mạnh, va đập, xung kích","explanation":"冲 (xung – xông) + 击 (kích – đánh) → xông vào đánh, va đập mạnh; nghĩa bóng: tác động mạnh, ảnh hưởng lớn. Cụm: 受到冲击, 巨大的冲击.","hsk_level":6,"tags":["dong-tu","danh-tu"],"image":"💥","examples":[{"type":"basic","zh":"海浪冲击着礁石。","pinyin":"Hǎilàng chōngjīzhe jiāoshí.","vi":"Sóng biển vỗ mạnh vào ghềnh đá."},{"type":"simple","zh":"网上购物对传统商场造成了巨大的冲击。","pinyin":"Wǎngshàng gòuwù duì chuántǒng shāngchǎng zào chéngle jùdà de chōngjī.","vi":"Mua sắm trực tuyến đã gây tác động mạnh mẽ đến các trung tâm thương mại truyền thống."},{"type":"compound","zh":"虽然金融危机冲击了出口行业，但是这家工厂挺了过来。","pinyin":"Suīrán jīnróngwēijī chōngjīle chūkǒu hángyè, dànshì zhè jiā gōngchǎng tǐngle guòlái.","vi":"Tuy khủng hoảng tài chính giáng đòn vào ngành xuất khẩu, nhưng nhà máy này vẫn trụ vững."}],"related":[{"hanzi":"冲撞","pinyin":"chōngzhuàng","vi":"va chạm"},{"hanzi":"撞击","pinyin":"zhuàngjī","vi":"va đập"},{"hanzi":"影响","pinyin":"yǐngxiǎng","vi":"ảnh hưởng"},{"hanzi":"冲击力","pinyin":"chōngjīlì","vi":"lực va đập"}],"traditional":"衝擊"},{"id":"冲突","hanzi":"冲突","pinyin":"chōngtū","meaning_vi":"xung đột, mâu thuẫn","explanation":"冲 + 突 (đột ngột). Vừa là danh từ vừa là động từ.","hsk_level":6,"tags":["danh-tu","dong-tu"],"image":"⚔️","examples":[{"type":"basic","zh":"他们发生了冲突。","pinyin":"Tāmen fāshēngle chōngtū.","vi":"Họ đã xảy ra xung đột."},{"type":"simple","zh":"这两个会议的时间冲突了。","pinyin":"Zhè liǎng gè huìyì de shíjiān chōngtū le.","vi":"Thời gian của hai cuộc họp này bị trùng nhau."},{"type":"compound","zh":"只要双方都冷静一点，就能避免不必要的冲突。","pinyin":"Zhǐyào shuāngfāng dōu lěngjìng yìdiǎn, jiù néng bìmiǎn bú bìyào de chōngtū.","vi":"Chỉ cần hai bên bình tĩnh một chút là có thể tránh những xung đột không cần thiết."}],"related":[{"hanzi":"矛盾","pinyin":"máodùn","vi":"mâu thuẫn"},{"hanzi":"争端","pinyin":"zhēngduān","vi":"tranh chấp"},{"hanzi":"纠纷","pinyin":"jiūfēn","vi":"tranh chấp"},{"hanzi":"和解","pinyin":"héjiě","vi":"hòa giải"}],"traditional":"衝突"},{"id":"充耳不闻","hanzi":"充耳不闻","pinyin":"chōng'ěr-bùwén","meaning_vi":"bịt tai làm ngơ, giả điếc không nghe","explanation":"充耳 (sung nhĩ – nhét tai) + 不闻 (bất văn – không nghe) → nhét bông vào tai mà không nghe → cố ý làm ngơ, bỏ ngoài tai ý kiến người khác.","hsk_level":6,"tags":["thanh-ngu"],"image":"🙉","examples":[{"type":"basic","zh":"他对劝告充耳不闻。","pinyin":"Tā duì quàngào chōng'ěrbùwén.","vi":"Anh ta bịt tai làm ngơ trước lời khuyên."},{"type":"simple","zh":"孩子玩游戏时对妈妈的叫声充耳不闻。","pinyin":"Háizi wán yóuxì shí duì māma de jiàoshēng chōng'ěrbùwén.","vi":"Lúc chơi game, đứa trẻ giả điếc trước tiếng gọi của mẹ."},{"type":"compound","zh":"即使邻居多次投诉噪音，他也充耳不闻。","pinyin":"Jíshǐ línjū duōcì tóusù zàoyīn, tā yě chōng'ěrbùwén.","vi":"Dù hàng xóm nhiều lần phàn nàn về tiếng ồn, anh ta vẫn làm ngơ."}],"related":[{"hanzi":"置之不理","pinyin":"zhìzhībùlǐ","vi":"bỏ mặc không quan tâm"},{"hanzi":"视而不见","pinyin":"shì'érbújiàn","vi":"nhìn mà không thấy"},{"hanzi":"无动于衷","pinyin":"wúdòngyúzhōng","vi":"thờ ơ"},{"hanzi":"洗耳恭听","pinyin":"xǐ'ěrgōngtīng","vi":"lắng tai nghe"}],"traditional":"充耳不聞"},{"id":"抽空","hanzi":"抽空","pinyin":"chōukòng","meaning_vi":"tranh thủ thời gian rảnh","explanation":"抽 (rút ra) + 空 (đọc kòng - thời gian rảnh). Động từ ly hợp.","hsk_level":6,"tags":["dong-tu","thoi-gian"],"image":"⏰","examples":[{"type":"basic","zh":"我抽空去看你。","pinyin":"Wǒ chōukòng qù kàn nǐ.","vi":"Tôi sẽ tranh thủ đến thăm bạn."},{"type":"simple","zh":"她每周都抽空去养老院做义工。","pinyin":"Tā měizhōu dōu chōukòng qù yǎnglǎoyuàn zuò yìgōng.","vi":"Tuần nào cô ấy cũng tranh thủ đến viện dưỡng lão làm tình nguyện."},{"type":"compound","zh":"虽然工作很忙，但是他每天都会抽空陪女儿读书。","pinyin":"Suīrán gōngzuò hěn máng, dànshì tā měitiān dōuhuì chōukòng péi nǚ'ér dúshū.","vi":"Tuy công việc rất bận, nhưng ngày nào anh ấy cũng tranh thủ đọc sách cùng con gái."}],"related":[{"hanzi":"抽时间","pinyin":"chōushíjiān","vi":"dành thời gian"},{"hanzi":"空闲","pinyin":"kòngxián","vi":"rảnh rỗi"},{"hanzi":"百忙之中","pinyin":"bǎimángzhīzhōng","vi":"giữa lúc bận rộn"},{"hanzi":"有空","pinyin":"yǒukòng","vi":"có thời gian rảnh"}]},{"id":"出乎意料","hanzi":"出乎意料","pinyin":"chūhū-yìliào","meaning_vi":"ngoài sức tưởng tượng, bất ngờ","explanation":"出乎 (xuất hồ – vượt ra ngoài) + 意料 (ý liệu – dự đoán) → vượt ngoài dự đoán → bất ngờ. Thường: 结果出乎意料, 出乎意料地顺利.","hsk_level":6,"tags":["thanh-ngu"],"image":"😲","examples":[{"type":"basic","zh":"结果出乎意料。","pinyin":"Jiéguǒ chūhūyìliào.","vi":"Kết quả nằm ngoài dự đoán."},{"type":"simple","zh":"这部小成本电影的票房出乎意料地好。","pinyin":"Zhè bù xiǎo chéngběn diànyǐng de piàofáng chūhūyìliào de hǎo.","vi":"Doanh thu phòng vé của bộ phim kinh phí thấp này tốt ngoài sức tưởng tượng."},{"type":"compound","zh":"虽然大家都以为他会拒绝，但是他的回答出乎意料地爽快。","pinyin":"Suīrán dàjiā dōu yǐwéi tā huì jùjué, dànshì tā de huídá chūhūyìliào de shuǎngkuai.","vi":"Tuy mọi người đều nghĩ anh ấy sẽ từ chối, nhưng câu trả lời của anh lại dứt khoát đến bất ngờ."}],"related":[{"hanzi":"意想不到","pinyin":"yìxiǎngbúdào","vi":"không ngờ tới"},{"hanzi":"出人意料","pinyin":"chūrényìliào","vi":"ngoài dự kiến"},{"hanzi":"意外","pinyin":"yìwài","vi":"bất ngờ"},{"hanzi":"不出所料","pinyin":"bùchūsuǒliào","vi":"đúng như dự đoán"}]},{"id":"出类拔萃","hanzi":"出类拔萃","pinyin":"chūlèi-bácuì","meaning_vi":"xuất chúng vượt trội hơn người","explanation":"出类 (xuất loại – vượt khỏi đồng loại) + 拔萃 (bạt tụy – nổi lên trên đám) → vượt trội hẳn so với những người cùng loại (gốc Mạnh Tử) → xuất chúng.","hsk_level":6,"tags":["thanh-ngu"],"image":"🌟","examples":[{"type":"basic","zh":"她的成绩出类拔萃。","pinyin":"Tā de chéngjì chūlèibácuì.","vi":"Thành tích của cô ấy xuất chúng."},{"type":"simple","zh":"他是这批年轻工程师中出类拔萃的一个。","pinyin":"Tā shì zhè pī niánqīng gōngchéngshī zhōng chūlèibácuì de yí gè.","vi":"Anh ấy là người xuất sắc vượt trội trong lứa kỹ sư trẻ này."},{"type":"compound","zh":"只有不断磨练技艺，才能在同行中出类拔萃。","pinyin":"Zhǐyǒu búduàn móliàn jìyì, cáinéng zài tóngháng zhōng chūlèibácuì.","vi":"Chỉ có không ngừng rèn luyện tay nghề mới có thể nổi trội giữa những người cùng nghề."}],"related":[{"hanzi":"出众","pinyin":"chūzhòng","vi":"xuất chúng"},{"hanzi":"卓越","pinyin":"zhuóyuè","vi":"xuất sắc"},{"hanzi":"鹤立鸡群","pinyin":"hèlìjīqún","vi":"hạc giữa bầy gà"},{"hanzi":"平庸","pinyin":"píngyōng","vi":"tầm thường"}],"traditional":"出類拔萃"},{"id":"出路","hanzi":"出路","pinyin":"chūlù","meaning_vi":"lối thoát","explanation":"出 (xuất – ra) + 路 (lộ – đường) → đường ra, lối thoát; nghĩa bóng: tiền đồ, hướng phát triển. Ví dụ: 寻找出路, 没有出路.","hsk_level":6,"tags":["danh-tu"],"image":"🚪","examples":[{"type":"basic","zh":"总会有出路的。","pinyin":"Zǒng huì yǒu chūlù de.","vi":"Rồi sẽ có lối thoát thôi."},{"type":"simple","zh":"发展乡村旅游成了这个山村的新出路。","pinyin":"Fāzhǎn xiāngcūnlǚyóu chéngle zhè ge shāncūn de xīn chūlù.","vi":"Phát triển du lịch nông thôn trở thành lối đi mới cho làng núi này."},{"type":"compound","zh":"如果一直守着老办法，工厂就找不到出路。","pinyin":"Rúguǒ yìzhí shǒuzhe lǎo bànfǎ, gōngchǎng jiù zhǎobúdào chūlù.","vi":"Nếu cứ khư khư giữ cách làm cũ, nhà máy sẽ không tìm ra lối thoát."}],"related":[{"hanzi":"退路","pinyin":"tuìlù","vi":"đường lui"},{"hanzi":"前途","pinyin":"qiántú","vi":"tiền đồ"},{"hanzi":"办法","pinyin":"bànfǎ","vi":"cách giải quyết"},{"hanzi":"走投无路","pinyin":"zǒutóuwúlù","vi":"cùng đường"}]},{"id":"出谋划策","hanzi":"出谋划策","pinyin":"chūmóu-huàcè","meaning_vi":"hiến kế, bày mưu tính kế","explanation":"出谋 (xuất mưu – đưa ra mưu) + 划策 (hoạch sách – vạch kế sách) → đưa ra ý kiến, kế sách giúp người khác. Thường: 为公司出谋划策.","hsk_level":6,"tags":["thanh-ngu","cong-viec"],"image":"🧠","examples":[{"type":"basic","zh":"他为公司出谋划策。","pinyin":"Tā wèi gōngsī chūmóuhuàcè.","vi":"Anh ấy hiến kế cho công ty."},{"type":"simple","zh":"几位老同学纷纷为她的小店出谋划策。","pinyin":"Jǐ wèi lǎo tóngxué fēnfēn wèi tā de xiǎodiàn chūmóuhuàcè.","vi":"Mấy người bạn học cũ lần lượt góp ý hiến kế cho cửa hàng nhỏ của cô ấy."},{"type":"compound","zh":"他虽然不在一线工作，但是经常在幕后出谋划策。","pinyin":"Tā suīrán bú zài yíxiàn gōngzuò, dànshì jīngcháng zài mùhòu chūmóuhuàcè.","vi":"Anh ấy tuy không làm việc ở tuyến đầu, nhưng thường xuyên bày mưu tính kế ở hậu trường."}],"related":[{"hanzi":"献计献策","pinyin":"xiànjìxiàncè","vi":"hiến kế"},{"hanzi":"出主意","pinyin":"chūzhǔyi","vi":"góp ý kiến"},{"hanzi":"参谋","pinyin":"cānmóu","vi":"tham mưu"},{"hanzi":"策划","pinyin":"cèhuà","vi":"lên kế hoạch"}],"traditional":"出謀劃策"},{"id":"出人头地","hanzi":"出人头地","pinyin":"chūrén-tóudì","meaning_vi":"nổi bật hơn người, thành đạt","explanation":"出 (xuất – vượt) + 人头地 (hơn người một cái đầu) → lời Âu Dương Tu khen Tô Thức, muốn nhường cho người này vượt lên một bậc → thành đạt, nổi bật hơn người.","hsk_level":6,"tags":["thanh-ngu"],"image":"🏆","examples":[{"type":"basic","zh":"他想出人头地。","pinyin":"Tā xiǎng chūréntóudì.","vi":"Anh ấy muốn nổi bật hơn người."},{"type":"simple","zh":"这个农村孩子靠读书出人头地了。","pinyin":"Zhè ge nóngcūn háizi kào dúshū chūréntóudì le.","vi":"Cậu bé nông thôn này đã thành đạt nhờ con đường học hành."},{"type":"compound","zh":"为了出人头地，他不但白天打工，而且晚上还去夜校学习。","pinyin":"Wèile chūréntóudì, tā búdàn báitiān dǎgōng, érqiě wǎnshang hái qù yèxiào xuéxí.","vi":"Để vươn lên hơn người, anh ấy không chỉ ban ngày đi làm mà buổi tối còn đi học trường đêm."}],"related":[{"hanzi":"出类拔萃","pinyin":"chūlèibácuì","vi":"xuất chúng"},{"hanzi":"成功","pinyin":"chénggōng","vi":"thành công"},{"hanzi":"有出息","pinyin":"yǒuchūxi","vi":"có tiền đồ"},{"hanzi":"默默无闻","pinyin":"mòmòwúwén","vi":"vô danh"}],"traditional":"出人頭地"},{"id":"出神","hanzi":"出神","pinyin":"chūshén","meaning_vi":"ngẩn ngơ, thất thần","explanation":"出 (xuất – rời ra) + 神 (thần – tinh thần) → tinh thần như rời khỏi người → nhìn, nghe, nghĩ say mê đến ngẩn ra. Ví dụ: 看得出神, 想得出神.","hsk_level":6,"tags":["dong-tu"],"image":"😶","examples":[{"type":"basic","zh":"她看着窗外出神。","pinyin":"Tā kànzhe chuāng wài chūshén.","vi":"Cô ấy nhìn ra ngoài cửa sổ đến ngẩn người."},{"type":"simple","zh":"孩子们听老爷爷讲故事听得出神。","pinyin":"Háizimen tīng lǎoyéye jiǎng gùshi tīng de chūshén.","vi":"Bọn trẻ nghe ông cụ kể chuyện đến say sưa ngây người."},{"type":"compound","zh":"他一想起远方的家乡，就会对着月亮出神。","pinyin":"Tā yì xiǎngqǐ yuǎnfāng de jiāxiāng, jiù huì duìzhe yuèliang chūshén.","vi":"Hễ nhớ về quê hương xa xôi, anh ấy lại ngẩn ngơ nhìn trăng."}],"related":[{"hanzi":"发呆","pinyin":"fādāi","vi":"ngẩn người"},{"hanzi":"走神","pinyin":"zǒushén","vi":"mất tập trung"},{"hanzi":"入神","pinyin":"rùshén","vi":"nhập tâm"},{"hanzi":"愣","pinyin":"lèng","vi":"ngây ra"}]},{"id":"出神入化","hanzi":"出神入化","pinyin":"chūshén-rùhuà","meaning_vi":"đạt đến trình độ điêu luyện thần sầu","explanation":"出神 (xuất thần) + 入化 (nhập hóa – đạt tới cảnh giới thần diệu) → tay nghề, kỹ năng điêu luyện đến mức thần kỳ. Thường: 技艺出神入化.","hsk_level":6,"tags":["thanh-ngu"],"image":"🌟","examples":[{"type":"basic","zh":"他的刀工出神入化。","pinyin":"Tā de dāogōng chūshénrùhuà.","vi":"Kỹ thuật dùng dao của anh ấy điêu luyện như thần."},{"type":"simple","zh":"这位魔术师的手法已经达到了出神入化的地步。","pinyin":"Zhè wèi móshùshī de shǒufǎ yǐjīng dádàole chūshénrùhuà de dìbù.","vi":"Thủ pháp của ảo thuật gia này đã đạt đến mức thần sầu."},{"type":"compound","zh":"他的琴艺之所以出神入化，是因为从小每天练琴八小时。","pinyin":"Tā de qín yì zhīsuǒyǐ chūshénrùhuà, shì yīnwèi cóngxiǎo měitiān liàn qín bā xiǎoshí.","vi":"Sở dĩ tài đàn của anh ấy điêu luyện như thần là vì từ nhỏ ngày nào cũng tập đàn tám tiếng."}],"related":[{"hanzi":"炉火纯青","pinyin":"lúhuǒchúnqīng","vi":"điêu luyện đến mức hoàn hảo"},{"hanzi":"登峰造极","pinyin":"dēngfēngzàojí","vi":"đạt đến đỉnh cao"},{"hanzi":"精湛","pinyin":"jīngzhàn","vi":"tinh xảo"},{"hanzi":"神乎其技","pinyin":"shénhūqíjì","vi":"tài nghệ thần kỳ"}]},{"id":"出言不逊","hanzi":"出言不逊","pinyin":"chūyán-búxùn","meaning_vi":"ăn nói xấc xược thiếu lễ độ","explanation":"出言 (xuất ngôn – nói ra) + 不逊 (bất tốn – không khiêm nhường) → lời nói không khiêm tốn → xấc xược, vô lễ với người khác.","hsk_level":6,"tags":["thanh-ngu","giao-tiep"],"image":"😠","examples":[{"type":"basic","zh":"他对老师出言不逊。","pinyin":"Tā duì lǎoshī chūyánbúxùn.","vi":"Cậu ta ăn nói xấc xược với thầy giáo."},{"type":"simple","zh":"那个顾客在柜台前对店员出言不逊。","pinyin":"Nà ge gùkè zài guìtái qián duì diànyuán chūyánbúxùn.","vi":"Vị khách đó ăn nói hỗn hào với nhân viên ở quầy."},{"type":"compound","zh":"因为他在会上出言不逊，所以被经理当场批评了。","pinyin":"Yīnwèi tā zài huì shàng chūyánbúxùn, suǒyǐ bèi jīnglǐ dāngchǎng pīpíng le.","vi":"Vì ăn nói thiếu lễ độ trong cuộc họp nên anh ta bị giám đốc phê bình ngay tại chỗ."}],"related":[{"hanzi":"口出狂言","pinyin":"kǒuchūkuángyán","vi":"ăn nói ngông cuồng"},{"hanzi":"无礼","pinyin":"wúlǐ","vi":"vô lễ"},{"hanzi":"粗鲁","pinyin":"cūlǔ","vi":"thô lỗ"},{"hanzi":"彬彬有礼","pinyin":"bīnbīnyǒulǐ","vi":"nho nhã lễ độ"}],"traditional":"出言不遜"},{"id":"初衷","hanzi":"初衷","pinyin":"chūzhōng","meaning_vi":"tâm nguyện ban đầu, mục đích ban đầu","explanation":"初 (ban đầu) + 衷 (lòng). Cụm: 不忘初心/初衷.","hsk_level":6,"tags":["danh-tu"],"image":"💖","examples":[{"type":"basic","zh":"不要忘了初衷。","pinyin":"Bú yào wàngle chūzhōng.","vi":"Đừng quên tâm nguyện ban đầu."},{"type":"simple","zh":"她当老师的初衷是帮助山里的孩子。","pinyin":"Tā dāng lǎoshī de chūzhōng shì bāngzhù shān lǐ de háizi.","vi":"Mục đích ban đầu khi cô ấy làm giáo viên là giúp đỡ trẻ em vùng núi."},{"type":"compound","zh":"即使遇到再多困难，他也没有改变创业的初衷。","pinyin":"Jíshǐ yùdào zài duō kùnnan, tā yě méiyǒu gǎibiàn chuàngyè de chūzhōng.","vi":"Dù gặp bao nhiêu khó khăn, anh ấy vẫn không thay đổi mục đích ban đầu khi khởi nghiệp."}],"related":[{"hanzi":"本意","pinyin":"běnyì","vi":"ý định ban đầu"},{"hanzi":"初心","pinyin":"chūxīn","vi":"sơ tâm"},{"hanzi":"心愿","pinyin":"xīnyuàn","vi":"tâm nguyện"},{"hanzi":"不忘初心","pinyin":"búwàngchūxīn","vi":"không quên ý nguyện ban đầu"}]},{"id":"春风得意","hanzi":"春风得意","pinyin":"chūnfēng-déyì","meaning_vi":"phơi phới đắc ý (khi thành công/thi đỗ)","explanation":"春风 (xuân phong – gió xuân) + 得意 (đắc ý) → thơ Mạnh Giao khi thi đỗ tiến sĩ, cưỡi ngựa trong gió xuân → đắc chí phơi phới khi thành công, thăng tiến.","hsk_level":6,"tags":["thanh-ngu"],"image":"🥳","examples":[{"type":"basic","zh":"他最近春风得意。","pinyin":"Tā zuìjìn chūnfēngdéyì.","vi":"Dạo này anh ấy rất phơi phới đắc ý."},{"type":"simple","zh":"刚升职的小王春风得意地走进了办公室。","pinyin":"Gāng shēngzhí de xiǎo Wáng chūnfēngdéyì de zǒujìnle bàngōngshì.","vi":"Tiểu Vương vừa được thăng chức hớn hở bước vào văn phòng."},{"type":"compound","zh":"越是春风得意的时候，越要保持清醒的头脑。","pinyin":"Yuè shì chūnfēngdéyì de shíhou, yuè yào bǎochí qīngxǐng de tóunǎo.","vi":"Càng lúc phơi phới đắc ý, càng phải giữ cái đầu tỉnh táo."}],"related":[{"hanzi":"得意洋洋","pinyin":"déyìyángyáng","vi":"đắc ý dương dương"},{"hanzi":"意气风发","pinyin":"yìqìfēngfā","vi":"hăng hái phấn chấn"},{"hanzi":"心花怒放","pinyin":"xīnhuānùfàng","vi":"mừng rỡ"},{"hanzi":"垂头丧气","pinyin":"chuítóusàngqì","vi":"ủ rũ chán nản"}],"traditional":"春風得意"},{"id":"春暖花开","hanzi":"春暖花开","pinyin":"chūnnuǎn-huākāi","meaning_vi":"xuân ấm hoa nở","explanation":"春暖 (xuân noãn – xuân ấm) + 花开 (hoa khai – hoa nở) → mùa xuân ấm áp, trăm hoa đua nở; ví thời cơ, hoàn cảnh thuận lợi.","hsk_level":6,"tags":["thanh-ngu","thoi-tiet"],"image":"🌸","examples":[{"type":"basic","zh":"又到了春暖花开时。","pinyin":"Yòu dàole chūnnuǎnhuākāi shí.","vi":"Lại đến mùa xuân ấm hoa nở."},{"type":"simple","zh":"春暖花开的三月，游客们纷纷来到樱花园赏花。","pinyin":"Chūnnuǎnhuākāi de Sānyuè, yóukèmen fēnfēn láidào yīng huāyuán shǎnghuā.","vi":"Tháng ba xuân ấm hoa nở, du khách lũ lượt đến vườn anh đào ngắm hoa."},{"type":"compound","zh":"等到春暖花开，我们就一起去郊外野餐吧。","pinyin":"Děngdào chūnnuǎnhuākāi, wǒmen jiù yìqǐ qù jiāowài yěcān ba.","vi":"Đợi đến khi xuân ấm hoa nở, chúng ta cùng ra ngoại ô dã ngoại nhé."}],"related":[{"hanzi":"春天","pinyin":"chūntiān","vi":"mùa xuân"},{"hanzi":"鸟语花香","pinyin":"niǎoyǔhuāxiāng","vi":"chim hót hoa thơm"},{"hanzi":"万物复苏","pinyin":"wànwùfùsū","vi":"vạn vật hồi sinh"},{"hanzi":"天寒地冻","pinyin":"tiānhándìdòng","vi":"trời rét đất đóng băng"}],"traditional":"春暖花開"},{"id":"产值","hanzi":"产值","pinyin":"chǎnzhí","meaning_vi":"giá trị sản lượng","explanation":"产 (sản xuất) + 值 (giá trị).","hsk_level":6,"tags":["danh-tu","cong-viec","tien-te"],"image":"📊","examples":[{"type":"basic","zh":"今年产值翻了一番。","pinyin":"Jīnnián chǎnzhí fānle yìfān.","vi":"Năm nay giá trị sản lượng tăng gấp đôi."},{"type":"simple","zh":"这家工厂去年的产值超过了十亿元。","pinyin":"Zhè jiā gōngchǎng qùnián de chǎnzhí chāoguòle shíyì yuán.","vi":"Giá trị sản lượng năm ngoái của nhà máy này vượt mười tỷ tệ."},{"type":"compound","zh":"虽然工厂的产值提高了，但是利润并没有增加。","pinyin":"Suīrán gōngchǎng de chǎnzhí tígāo le, dànshì lìrùn bìng méiyǒu zēngjiā.","vi":"Tuy giá trị sản lượng của nhà máy đã tăng, nhưng lợi nhuận lại không tăng."}],"related":[{"hanzi":"产量","pinyin":"chǎnliàng","vi":"sản lượng"},{"hanzi":"生产总值","pinyin":"shēngchǎnzǒngzhí","vi":"tổng giá trị sản xuất"},{"hanzi":"产品","pinyin":"chǎnpǐn","vi":"sản phẩm"},{"hanzi":"价值","pinyin":"jiàzhí","vi":"giá trị"}],"traditional":"產值"},{"id":"敞亮","hanzi":"敞亮","pinyin":"chǎngliàng","meaning_vi":"rộng rãi sáng sủa","explanation":"敞 (rộng mở) + 亮 (sáng).","hsk_level":6,"tags":["tinh-tu","nha-cua"],"image":"☀️","examples":[{"type":"basic","zh":"这间屋子很敞亮。","pinyin":"Zhè jiān wūzi hěn chǎngliàng.","vi":"Căn phòng này rộng rãi sáng sủa."},{"type":"simple","zh":"新装修的教室又干净又敞亮。","pinyin":"Xīn zhuāngxiū de jiàoshì yòu gānjìng yòu chǎngliàng.","vi":"Phòng học mới sửa sang vừa sạch sẽ vừa rộng rãi sáng sủa."},{"type":"compound","zh":"因为窗户朝南，所以客厅一年四季都很敞亮。","pinyin":"Yīnwèi chuānghu cháo nán, suǒyǐ kètīng yì nián sìjì dōu hěn chǎngliàng.","vi":"Vì cửa sổ hướng nam nên phòng khách quanh năm đều rộng rãi sáng sủa."}],"related":[{"hanzi":"宽敞","pinyin":"kuānchang","vi":"rộng rãi"},{"hanzi":"明亮","pinyin":"míngliàng","vi":"sáng sủa"},{"hanzi":"亮堂","pinyin":"liàngtang","vi":"sáng sủa"},{"hanzi":"阴暗","pinyin":"yīn'àn","vi":"u tối"}]},{"id":"场所","hanzi":"场所","pinyin":"chǎngsuǒ","meaning_vi":"địa điểm, nơi chốn","explanation":"场 (trường – bãi, nơi) + 所 (sở – chỗ) → nơi chốn dành cho hoạt động nào đó. Thường: 公共场所 (nơi công cộng), 娱乐场所.","hsk_level":6,"tags":["danh-tu","dia-diem"],"image":"📍","examples":[{"type":"basic","zh":"这里是公共场所。","pinyin":"Zhèlǐ shì gōnggòngchǎngsuǒ.","vi":"Đây là nơi công cộng."},{"type":"simple","zh":"这座老厂房被改造成了年轻人的娱乐场所。","pinyin":"Zhè zuò lǎo chǎngfáng bèi gǎizào chéngle niánqīngrén de yúlè chǎngsuǒ.","vi":"Nhà xưởng cũ này đã được cải tạo thành nơi vui chơi cho giới trẻ."},{"type":"compound","zh":"在公共场所，如果大声喧哗，就会影响别人。","pinyin":"Zài gōnggòngchǎngsuǒ, rúguǒ dàshēng xuānhuá, jiù huì yǐngxiǎng biérén.","vi":"Ở nơi công cộng, nếu nói chuyện ồn ào sẽ làm phiền người khác."}],"related":[{"hanzi":"地点","pinyin":"dìdiǎn","vi":"địa điểm"},{"hanzi":"场地","pinyin":"chǎngdì","vi":"bãi, sân"},{"hanzi":"公共场所","pinyin":"gōnggòngchǎngsuǒ","vi":"nơi công cộng"},{"hanzi":"地方","pinyin":"dìfang","vi":"nơi chốn"}],"traditional":"場所"},{"id":"炒作","hanzi":"炒作","pinyin":"chǎozuò","meaning_vi":"lăng-xê, thổi phồng gây chú ý","explanation":"炒 (xào) + 作 (làm).","hsk_level":6,"tags":["dong-tu","cong-nghe"],"image":"📢","examples":[{"type":"basic","zh":"这是商业炒作。","pinyin":"Zhè shì shāngyè chǎozuò.","vi":"Đây là chiêu thổi phồng thương mại."},{"type":"simple","zh":"那位明星的绯闻被媒体炒作了好几天。","pinyin":"Nà wèi míngxīng de fēiwén bèi méitǐ chǎozuòle hǎo jǐtiān.","vi":"Tin đồn tình ái của ngôi sao đó bị truyền thông thổi phồng suốt mấy ngày."},{"type":"compound","zh":"与其花钱炒作，不如把产品质量做好。","pinyin":"Yǔqí huāqián chǎozuò, bùrú bǎ chǎnpǐn zhìliàng zuò hǎo.","vi":"Thay vì tốn tiền lăng-xê, chi bằng làm tốt chất lượng sản phẩm."}],"related":[{"hanzi":"宣传","pinyin":"xuānchuán","vi":"tuyên truyền"},{"hanzi":"包装","pinyin":"bāozhuāng","vi":"đóng gói, lăng xê"},{"hanzi":"噱头","pinyin":"xuétóu","vi":"chiêu trò gây chú ý"},{"hanzi":"曝光","pinyin":"bàoguāng","vi":"phơi bày, lên sóng"}]},{"id":"储备","hanzi":"储备","pinyin":"chǔbèi","meaning_vi":"dự trữ","explanation":"储 (trữ – cất giữ) + 备 (bị – chuẩn bị) → cất giữ để dùng khi cần, dự trữ. Thường: 储备粮食, 外汇储备, 人才储备.","hsk_level":6,"tags":["dong-tu"],"image":"📦","examples":[{"type":"basic","zh":"国家储备了粮食。","pinyin":"Guójiā chǔbèile liángshi.","vi":"Nhà nước đã dự trữ lương thực."},{"type":"simple","zh":"松鼠在秋天储备了很多过冬的松果。","pinyin":"Sōngshǔ zài qiūtiān chǔbèile hěn duō guòdōng de sōngguǒ.","vi":"Mùa thu, con sóc đã dự trữ rất nhiều quả thông để qua đông."},{"type":"compound","zh":"只要平时多储备知识，遇到问题时就不会手忙脚乱。","pinyin":"Zhǐyào píngshí duō chǔbèi zhīshi, yùdào wèntí shí jiù bú huì shǒumángjiǎoluàn.","vi":"Chỉ cần ngày thường tích lũy nhiều kiến thức, khi gặp vấn đề sẽ không bị luống cuống."}],"related":[{"hanzi":"储存","pinyin":"chǔcún","vi":"lưu trữ"},{"hanzi":"储蓄","pinyin":"chǔxù","vi":"tiết kiệm"},{"hanzi":"备用","pinyin":"bèiyòng","vi":"dự phòng"},{"hanzi":"外汇储备","pinyin":"wàihuìchǔbèi","vi":"dự trữ ngoại hối"}],"traditional":"儲備"},{"id":"处心积虑","hanzi":"处心积虑","pinyin":"chǔxīn-jīlǜ","meaning_vi":"dụng tâm tính toán mưu mô từ lâu","explanation":"处心 (xử tâm – để tâm) + 积虑 (tích lự – suy tính lâu ngày) → toan tính kỹ lưỡng từ lâu, thường để làm việc xấu. Mang nghĩa xấu.","hsk_level":6,"tags":["thanh-ngu"],"image":"🦹","examples":[{"type":"basic","zh":"他处心积虑地报复。","pinyin":"Tā chǔxīnjīlǜ de bàofù.","vi":"Hắn dày công tính toán để trả thù."},{"type":"simple","zh":"那个骗子处心积虑地接近这位富商。","pinyin":"Nà ge piànzi chǔxīnjīlǜ de jiējìn zhè wèi fùshāng.","vi":"Tên lừa đảo đó dày công mưu tính để tiếp cận vị thương gia giàu có này."},{"type":"compound","zh":"虽然他处心积虑地想夺权，但是最后还是失败了。","pinyin":"Suīrán tā chǔxīnjīlǜ de xiǎng duóquán, dànshì zuìhòu háishi shībài le.","vi":"Tuy hắn đã dày công mưu tính để đoạt quyền, nhưng cuối cùng vẫn thất bại."}],"related":[{"hanzi":"蓄谋已久","pinyin":"xùmóuyǐjiǔ","vi":"âm mưu từ lâu"},{"hanzi":"费尽心机","pinyin":"fèijìnxīnjī","vi":"dốc hết tâm cơ"},{"hanzi":"千方百计","pinyin":"qiānfāngbǎijì","vi":"trăm phương nghìn kế"},{"hanzi":"居心叵测","pinyin":"jūxīnpǒcè","vi":"lòng dạ khó lường"}],"traditional":"處心積慮"},{"id":"脆弱","hanzi":"脆弱","pinyin":"cuìruò","meaning_vi":"mong manh, yếu đuối","explanation":"脆 (thúy – giòn, dễ vỡ) + 弱 (nhược – yếu) → dễ vỡ, yếu đuối, không chịu nổi tác động. Thường: 感情脆弱, 生态脆弱.","hsk_level":6,"tags":["tinh-tu"],"image":"🥀","examples":[{"type":"basic","zh":"她的心很脆弱。","pinyin":"Tā de xīn hěn cuìruò.","vi":"Trái tim cô ấy rất mong manh."},{"type":"simple","zh":"这片湿地的生态环境非常脆弱。","pinyin":"Zhè piàn shīdì de shēngtài huánjìng fēicháng cuìruò.","vi":"Môi trường sinh thái của vùng đất ngập nước này rất mong manh."},{"type":"compound","zh":"人在生病的时候，不但身体虚弱，而且情绪也特别脆弱。","pinyin":"Rén zài shēngbìng de shíhou, búdàn shēntǐ xūruò, érqiě qíngxù yě tèbié cuìruò.","vi":"Khi bị bệnh, con người không chỉ cơ thể suy nhược mà tâm trạng cũng đặc biệt yếu đuối."}],"related":[{"hanzi":"软弱","pinyin":"ruǎnruò","vi":"yếu mềm"},{"hanzi":"薄弱","pinyin":"bóruò","vi":"yếu kém"},{"hanzi":"坚强","pinyin":"jiānqiáng","vi":"kiên cường"},{"hanzi":"易碎","pinyin":"yìsuì","vi":"dễ vỡ"}]},{"id":"挫败","hanzi":"挫败","pinyin":"cuòbài","meaning_vi":"đánh bại, làm thất bại","explanation":"挫 (tỏa – làm nhụt, bẻ gãy) + 败 (bại – thua) → làm cho thất bại, đánh bại (âm mưu, đối thủ); cũng là sự thất bại. Cụm: 挫败阴谋, 挫败感.","hsk_level":6,"tags":["dong-tu"],"image":"⚔️","examples":[{"type":"basic","zh":"警方挫败了阴谋。","pinyin":"Jǐngfāng cuòbàile yīnmóu.","vi":"Cảnh sát đã đập tan âm mưu."},{"type":"simple","zh":"主队在加时赛中挫败了强大的对手。","pinyin":"Zhǔduì zài jiāshísài zhōng cuòbàile qiángdà de duìshǒu.","vi":"Đội chủ nhà đã đánh bại đối thủ mạnh trong hiệp phụ."},{"type":"compound","zh":"因为情报准确，所以我们成功挫败了敌人的偷袭。","pinyin":"Yīnwèi qíngbào zhǔnquè, suǒyǐ wǒmen chénggōng cuòbàile dírén de tōuxí.","vi":"Vì tình báo chính xác nên chúng ta đã đánh bại thành công cuộc đánh lén của địch."}],"related":[{"hanzi":"挫折","pinyin":"cuòzhé","vi":"thất bại"},{"hanzi":"击败","pinyin":"jībài","vi":"đánh bại"},{"hanzi":"失败","pinyin":"shībài","vi":"thất bại"},{"hanzi":"挫败感","pinyin":"cuòbàigǎn","vi":"cảm giác thất bại"}],"traditional":"挫敗"},{"id":"错综复杂","hanzi":"错综复杂","pinyin":"cuòzōng-fùzá","meaning_vi":"chằng chịt phức tạp","explanation":"错综 (thác tống – đan chéo nhau) + 复杂 (phức tạp) → đan xen chằng chịt, rất phức tạp. Thường nói về quan hệ, tình hình: 关系错综复杂.","hsk_level":6,"tags":["thanh-ngu"],"image":"🕸️","examples":[{"type":"basic","zh":"案情错综复杂。","pinyin":"Ànqíng cuòzōngfùzá.","vi":"Tình tiết vụ án rất phức tạp."},{"type":"simple","zh":"这个家族内部的关系错综复杂。","pinyin":"Zhè ge jiāzú nèibù de guānxì cuòzōngfùzá.","vi":"Quan hệ nội bộ của gia tộc này chằng chịt phức tạp."},{"type":"compound","zh":"因为老城区的小巷错综复杂，所以外地人很容易迷路。","pinyin":"Yīnwèi lǎochéngqū de xiǎoxiàng cuòzōngfùzá, suǒyǐ wàidìrén hěn róngyì mílù.","vi":"Vì ngõ hẻm khu phố cổ chằng chịt phức tạp nên người nơi khác rất dễ lạc đường."}],"related":[{"hanzi":"复杂","pinyin":"fùzá","vi":"phức tạp"},{"hanzi":"纵横交错","pinyin":"zònghéngjiāocuò","vi":"ngang dọc đan xen"},{"hanzi":"盘根错节","pinyin":"pángēncuòjié","vi":"rễ cây chằng chịt"},{"hanzi":"简单明了","pinyin":"jiǎndānmíngliǎo","vi":"đơn giản rõ ràng"}],"traditional":"錯綜複雜"},{"id":"催促","hanzi":"催促","pinyin":"cuīcù","meaning_vi":"thúc giục","explanation":"催 (giục) + 促 (gấp).","hsk_level":6,"tags":["dong-tu"],"image":"⏰","examples":[{"type":"basic","zh":"妈妈催促我起床。","pinyin":"Māma cuīcù wǒ qǐchuáng.","vi":"Mẹ giục tôi dậy."},{"type":"simple","zh":"房东已经三次打电话催促他交房租了。","pinyin":"Fángdōng yǐjīng sāncì dǎdiànhuà cuīcù tā jiāo fángzū le.","vi":"Chủ nhà đã ba lần gọi điện giục anh ấy nộp tiền thuê nhà."},{"type":"compound","zh":"即使没有人催促，她也每天按时完成作业。","pinyin":"Jíshǐ méiyǒu rén cuīcù, tā yě měitiān ànshí wánchéng zuòyè.","vi":"Dù không ai thúc giục, cô bé vẫn hoàn thành bài tập đúng giờ mỗi ngày."}],"related":[{"hanzi":"督促","pinyin":"dūcù","vi":"đôn đốc"},{"hanzi":"敦促","pinyin":"dūncù","vi":"thúc giục"},{"hanzi":"催","pinyin":"cuī","vi":"giục"},{"hanzi":"催促声","pinyin":"cuīcùshēng","vi":"tiếng giục giã"}]},{"id":"摧枯拉朽","hanzi":"摧枯拉朽","pinyin":"cuīkū-lāxiǔ","meaning_vi":"dễ như bẻ cành khô (sức mạnh áp đảo)","explanation":"摧枯 (tồi khô – bẻ cành khô) + 拉朽 (lạp hủ – kéo gỗ mục) → bẻ cây khô, kéo gỗ mục → dễ dàng đánh bại thế lực đã suy yếu; sức mạnh áp đảo.","hsk_level":6,"tags":["thanh-ngu"],"image":"💥","examples":[{"type":"basic","zh":"大军摧枯拉朽。","pinyin":"Dàjūn cuīkūlāxiǔ.","vi":"Đại quân tiến như chẻ tre."},{"type":"simple","zh":"新技术以摧枯拉朽之势改变了整个行业。","pinyin":"Xīnjìshù yǐ cuīkūlāxiǔ zhī shì gǎibiànle zhěnggè hángyè.","vi":"Công nghệ mới đã thay đổi cả ngành với sức mạnh áp đảo."},{"type":"compound","zh":"冠军队一上场，就以摧枯拉朽的气势赢下了比赛。","pinyin":"Guàn jūnduì yí shàngchǎng, jiù yǐ cuīkūlāxiǔ de qìshì yíng xiàle bǐsài.","vi":"Đội vô địch vừa ra sân đã thắng trận với khí thế dễ như bẻ cành khô."}],"related":[{"hanzi":"势如破竹","pinyin":"shìrúpòzhú","vi":"thế như chẻ tre"},{"hanzi":"所向披靡","pinyin":"suǒxiàngpīmǐ","vi":"đến đâu thắng đó"},{"hanzi":"不堪一击","pinyin":"bùkānyìjī","vi":"không chịu nổi một đòn"},{"hanzi":"摧毁","pinyin":"cuīhuǐ","vi":"phá hủy"}]},{"id":"撮合","hanzi":"撮合","pinyin":"cuōhe","meaning_vi":"mai mối, dàn xếp hòa giải","explanation":"撮 + 合 (hợp lại).","hsk_level":6,"tags":["dong-tu","giao-tiep"],"image":"💑","examples":[{"type":"basic","zh":"是她撮合了我们。","pinyin":"Shì tā cuōhele wǒmen.","vi":"Chính cô ấy đã mai mối cho chúng tôi."},{"type":"simple","zh":"姑姑一直想撮合表哥和她同事的女儿。","pinyin":"Gūgu yìzhí xiǎng cuōhe biǎogē hé tā tóngshì de nǚ'ér.","vi":"Cô tôi cứ muốn mai mối anh họ với con gái của đồng nghiệp cô."},{"type":"compound","zh":"如果不是老板从中撮合，两家公司就不会合作。","pinyin":"Rúguǒ bú shì lǎobǎn cóng zhōng cuōhe, liǎng jiā gōngsī jiù bú huì hézuò.","vi":"Nếu không có ông chủ đứng ra dàn xếp, hai công ty đã không hợp tác."}],"related":[{"hanzi":"牵线","pinyin":"qiānxiàn","vi":"se duyên"},{"hanzi":"做媒","pinyin":"zuòméi","vi":"làm mai"},{"hanzi":"介绍","pinyin":"jièshào","vi":"giới thiệu"},{"hanzi":"调解","pinyin":"tiáojiě","vi":"hòa giải"}]},{"id":"灿烂辉煌","hanzi":"灿烂辉煌","pinyin":"cànlàn-huīhuáng","meaning_vi":"rực rỡ huy hoàng","explanation":"灿烂 (xán lạn – rực rỡ) + 辉煌 (huy hoàng – chói lọi) → rực rỡ chói lọi; thường ví thành tựu, lịch sử, văn hóa vẻ vang.","hsk_level":6,"tags":["thanh-ngu"],"image":"🌟","examples":[{"type":"basic","zh":"古代文明灿烂辉煌。","pinyin":"Gǔdài wénmíng cànlànhuīhuáng.","vi":"Nền văn minh cổ đại rực rỡ huy hoàng."},{"type":"simple","zh":"节日的夜晚，整座城市灯火灿烂辉煌。","pinyin":"Jiérì de yèwǎn, zhěng zuò chéngshì dēnghuǒ cànlànhuīhuáng.","vi":"Đêm lễ hội, cả thành phố đèn đuốc rực rỡ huy hoàng."},{"type":"compound","zh":"这个王朝虽然曾经灿烂辉煌，但是最终还是走向了衰落。","pinyin":"Zhè ge wángcháo suīrán céngjīng cànlànhuīhuáng, dànshì zuìzhōng háishi zǒuxiàngle shuāiluò.","vi":"Vương triều này tuy từng rực rỡ huy hoàng, nhưng cuối cùng vẫn đi đến suy tàn."}],"related":[{"hanzi":"灿烂","pinyin":"cànlàn","vi":"rực rỡ"},{"hanzi":"辉煌","pinyin":"huīhuáng","vi":"huy hoàng"},{"hanzi":"光辉","pinyin":"guānghuī","vi":"quang huy"},{"hanzi":"暗淡","pinyin":"àndàn","vi":"ảm đạm"}],"traditional":"燦爛輝煌"},{"id":"财大气粗","hanzi":"财大气粗","pinyin":"cáidà-qìcū","meaning_vi":"lắm tiền nhiều của nên ăn nói mạnh bạo","explanation":"财大 (tài đại – của nhiều) + 气粗 (khí thô – khẩu khí lớn) → cậy giàu nên nói năng, hành xử ngạo mạn, phô trương. Mang ý chê.","hsk_level":6,"tags":["thanh-ngu","tien-te"],"image":"💰","examples":[{"type":"basic","zh":"那个老板财大气粗。","pinyin":"Nà ge lǎobǎn cáidàqìcū.","vi":"Ông chủ đó lắm tiền nên ăn nói hống hách."},{"type":"simple","zh":"他财大气粗地一口气买下了三套别墅。","pinyin":"Tā cáidàqìcū de yìkǒuqì mǎixiàle sān tào biéshù.","vi":"Hắn cậy lắm tiền, một hơi mua luôn ba căn biệt thự."},{"type":"compound","zh":"即使你财大气粗，也不能这样看不起服务员。","pinyin":"Jíshǐ nǐ cáidàqìcū, yě bù néng zhèyàng kànbuqǐ fúwùyuán.","vi":"Dù bạn lắm tiền nhiều của, cũng không được coi thường nhân viên phục vụ như vậy."}],"related":[{"hanzi":"有钱","pinyin":"yǒuqián","vi":"có tiền"},{"hanzi":"富豪","pinyin":"fùháo","vi":"phú hào"},{"hanzi":"嚣张","pinyin":"xiāozhāng","vi":"hống hách"},{"hanzi":"暴发户","pinyin":"bàofāhù","vi":"kẻ mới phất"}],"traditional":"財大氣粗"},{"id":"裁缝","hanzi":"裁缝","pinyin":"cáifeng","meaning_vi":"thợ may","explanation":"裁 (tài – cắt) + 缝 (phùng – may) → cắt may; danh từ chỉ thợ may (đọc cái feng). Ví dụ: 请裁缝做衣服.","hsk_level":6,"tags":["danh-tu","nghe-nghiep"],"image":"🧵","examples":[{"type":"basic","zh":"他是个老裁缝。","pinyin":"Tā shì gè lǎo cáifeng.","vi":"Ông ấy là một thợ may lâu năm."},{"type":"simple","zh":"裁缝仔细地给新娘量了腰围和肩宽。","pinyin":"Cáifeng zǐxì de gěi xīnniáng liángle yāowéi hé jiān kuān.","vi":"Người thợ may cẩn thận đo vòng eo và vai cho cô dâu."},{"type":"compound","zh":"这件旗袍既合身又精致，一看就是名裁缝的手艺。","pinyin":"Zhè jiàn qípáo jì héshēn yòu jīngzhì, yí kàn jiùshì míng cáifeng de shǒuyì.","vi":"Chiếc sườn xám này vừa vặn lại tinh xảo, nhìn là biết tay nghề của thợ may nổi tiếng."}],"related":[{"hanzi":"缝纫","pinyin":"féngrèn","vi":"may vá"},{"hanzi":"服装","pinyin":"fúzhuāng","vi":"quần áo"},{"hanzi":"裁剪","pinyin":"cáijiǎn","vi":"cắt may"},{"hanzi":"缝纫机","pinyin":"féngrènjī","vi":"máy may"}],"traditional":"裁縫"},{"id":"财富","hanzi":"财富","pinyin":"cáifù","meaning_vi":"tài sản, của cải","explanation":"财 (tài – tiền của) + 富 (phú – giàu) → của cải, tài sản; nghĩa rộng: điều quý giá (精神财富, 知识就是财富).","hsk_level":6,"tags":["danh-tu","tien-te"],"image":"💰","examples":[{"type":"basic","zh":"健康是最大的财富。","pinyin":"Jiànkāng shì zuì dà de cáifù.","vi":"Sức khỏe là tài sản lớn nhất."},{"type":"simple","zh":"他靠十年的努力积累了一笔可观的财富。","pinyin":"Tā kào shí nián de nǔlì jīlěile yì bǐ kěguān de cáifù.","vi":"Anh ấy nhờ mười năm nỗ lực đã tích lũy được một khối tài sản đáng kể."},{"type":"compound","zh":"即使拥有再多的财富，也买不回失去的时间。","pinyin":"Jíshǐ yōngyǒu zài duō de cáifù, yě mǎi bù huí shīqù de shíjiān.","vi":"Dù có bao nhiêu của cải đi nữa, cũng không mua lại được thời gian đã mất."}],"related":[{"hanzi":"财产","pinyin":"cáichǎn","vi":"tài sản"},{"hanzi":"金钱","pinyin":"jīnqián","vi":"tiền bạc"},{"hanzi":"富有","pinyin":"fùyǒu","vi":"giàu có"},{"hanzi":"精神财富","pinyin":"jīngshéncáifù","vi":"của cải tinh thần"}],"traditional":"財富"},{"id":"才华","hanzi":"才华","pinyin":"cáihuá","meaning_vi":"tài hoa, tài năng nghệ thuật/văn chương","explanation":"才 (tài) + 华 (tinh hoa).","hsk_level":6,"tags":["danh-tu","con-nguoi"],"image":"🌟","examples":[{"type":"basic","zh":"她很有才华。","pinyin":"Tā hěn yǒu cáihuá.","vi":"Cô ấy rất tài hoa."},{"type":"simple","zh":"这位年轻导演在首部电影中展现了出众的才华。","pinyin":"Zhè wèi niánqīng dǎoyǎn zài shǒu bù diànyǐng zhōng zhǎnxiànle chūzhòng de cáihuá.","vi":"Vị đạo diễn trẻ này đã thể hiện tài năng xuất chúng trong bộ phim đầu tay."},{"type":"compound","zh":"他虽然才华横溢，但是性格太骄傲，所以朋友不多。","pinyin":"Tā suīrán cáihuá héngyì, dànshì xìnggé tài jiāo'ào, suǒyǐ péngyou bù duō.","vi":"Anh ấy tuy tài hoa xuất chúng, nhưng tính cách quá kiêu ngạo nên ít bạn bè."}],"related":[{"hanzi":"才能","pinyin":"cáinéng","vi":"tài năng"},{"hanzi":"才干","pinyin":"cáigàn","vi":"năng lực"},{"hanzi":"天赋","pinyin":"tiānfù","vi":"thiên phú"},{"hanzi":"才华横溢","pinyin":"cáihuáhéngyì","vi":"tài hoa xuất chúng"}],"traditional":"才華"},{"id":"裁决","hanzi":"裁决","pinyin":"cáijué","meaning_vi":"phán quyết, phân xử","explanation":"裁 (cắt/xét) + 决 (quyết định).","hsk_level":6,"tags":["dong-tu","phap-luat"],"image":"⚖️","examples":[{"type":"basic","zh":"法院作出了裁决。","pinyin":"Fǎyuàn zuòchūle cáijué.","vi":"Tòa án đã đưa ra phán quyết."},{"type":"simple","zh":"仲裁委员会裁决公司赔偿员工三个月工资。","pinyin":"Zhòngcái wěiyuánhuì cáijué gōngsī péicháng yuángōng sān gèyuè gōngzī.","vi":"Hội đồng trọng tài phán quyết công ty bồi thường cho nhân viên ba tháng lương."},{"type":"compound","zh":"双方既然同意仲裁，就必须接受裁决结果。","pinyin":"Shuāngfāng jìrán tóngyì zhòngcái, jiù bìxū jiēshòu cáijué jiéguǒ.","vi":"Hai bên đã đồng ý trọng tài thì phải chấp nhận kết quả phán quyết."}],"related":[{"hanzi":"判决","pinyin":"pànjué","vi":"phán quyết"},{"hanzi":"裁定","pinyin":"cáidìng","vi":"phán định"},{"hanzi":"仲裁","pinyin":"zhòngcái","vi":"trọng tài"},{"hanzi":"裁判","pinyin":"cáipàn","vi":"trọng tài"}],"traditional":"裁決"},{"id":"才疏学浅","hanzi":"才疏学浅","pinyin":"cáishū-xuéqiǎn","meaning_vi":"tài hèn học nông (cách nói khiêm tốn)","explanation":"才疏 (tài sơ – tài mỏng) + 学浅 (học thiển – học nông) → tài hèn, học vấn nông cạn; thường dùng để tự nói khiêm tốn về mình.","hsk_level":6,"tags":["thanh-ngu","giao-tiep"],"image":"🙇","examples":[{"type":"basic","zh":"我才疏学浅，请多指教。","pinyin":"Wǒ cái shū xué qiǎn, qǐng duō zhǐjiào.","vi":"Tôi tài hèn học kém, xin mọi người chỉ giáo thêm."},{"type":"simple","zh":"老教授总是谦虚地说自己才疏学浅。","pinyin":"Lǎo jiàoshòu zǒngshì qiānxū de shuō zìjǐ cái shū xué qiǎn.","vi":"Vị giáo sư già luôn khiêm tốn nói mình tài hèn học kém."},{"type":"compound","zh":"因为自知才疏学浅，所以我不敢接下这个重要的任务。","pinyin":"Yīnwèi zì zhī cái shū xué qiǎn, suǒyǐ wǒ bù gǎn jiēxià zhè ge zhòngyào de rènwù.","vi":"Vì tự biết mình tài hèn học kém nên tôi không dám nhận nhiệm vụ quan trọng này."}],"related":[{"hanzi":"才学","pinyin":"cáixué","vi":"tài học"},{"hanzi":"谦虚","pinyin":"qiānxū","vi":"khiêm tốn"},{"hanzi":"博学多才","pinyin":"bóxuéduōcái","vi":"học rộng tài cao"},{"hanzi":"学识","pinyin":"xuéshí","vi":"học thức"}],"traditional":"才疏學淺"},{"id":"残骸","hanzi":"残骸","pinyin":"cánhái","meaning_vi":"xác (máy bay/tàu đắm), hài cốt","explanation":"残 (sót lại) + 骸 (xương cốt).","hsk_level":6,"tags":["danh-tu"],"image":"🛩️","examples":[{"type":"basic","zh":"海边发现了飞机残骸。","pinyin":"Hǎibiān fāxiànle fēijī cánhái.","vi":"Bên bờ biển đã phát hiện xác máy bay."},{"type":"simple","zh":"潜水员在海底找到了那艘沉船的残骸。","pinyin":"Qiánshuǐyuán zài hǎidǐ zhǎodàole nà sōu chénchuán de cánhái.","vi":"Thợ lặn đã tìm thấy xác con tàu đắm dưới đáy biển."},{"type":"compound","zh":"虽然火已经扑灭了，但是仓库只剩下一堆烧焦的残骸。","pinyin":"Suīrán huǒ yǐjīng pūmiè le, dànshì cāngkù zhǐ shèngxià yìduī shāojiāo de cánhái.","vi":"Tuy lửa đã được dập tắt, nhưng nhà kho chỉ còn lại một đống tàn tích cháy đen."}],"related":[{"hanzi":"遗骸","pinyin":"yíhái","vi":"di hài"},{"hanzi":"残骸碎片","pinyin":"cánháisuìpiàn","vi":"mảnh vỡ"},{"hanzi":"废墟","pinyin":"fèixū","vi":"đống đổ nát"},{"hanzi":"尸体","pinyin":"shītǐ","vi":"thi thể"}],"traditional":"殘骸"},{"id":"残酷","hanzi":"残酷","pinyin":"cánkù","meaning_vi":"tàn khốc","explanation":"残 (tàn – tàn nhẫn) + 酷 (khốc – khốc liệt) → tàn khốc, tàn nhẫn. Thường: 残酷的现实, 竞争残酷.","hsk_level":6,"tags":["tinh-tu"],"image":"⚔️","examples":[{"type":"basic","zh":"现实很残酷。","pinyin":"Xiànshí hěn cánkù.","vi":"Hiện thực rất tàn khốc."},{"type":"simple","zh":"这部纪录片真实地展现了战争的残酷。","pinyin":"Zhè bù jìlùpiàn zhēn shíde zhǎnxiànle zhànzhēng de cánkù.","vi":"Bộ phim tài liệu này phản ánh chân thực sự tàn khốc của chiến tranh."},{"type":"compound","zh":"虽然比赛的淘汰制度很残酷，但是选手们都没有退缩。","pinyin":"Suīrán bǐsài de táotài zhìdù hěn cánkù, dànshì xuǎnshǒumen dōu méiyǒu tuìsuō.","vi":"Tuy chế độ loại trực tiếp của cuộc thi rất khốc liệt, nhưng các thí sinh đều không chùn bước."}],"related":[{"hanzi":"残忍","pinyin":"cánrěn","vi":"tàn nhẫn"},{"hanzi":"冷酷","pinyin":"lěngkù","vi":"lạnh lùng"},{"hanzi":"残暴","pinyin":"cánbào","vi":"tàn bạo"},{"hanzi":"仁慈","pinyin":"réncí","vi":"nhân từ"}],"traditional":"殘酷"},{"id":"残缺","hanzi":"残缺","pinyin":"cánquē","meaning_vi":"thiếu hụt, không trọn vẹn","explanation":"残 (tàn – hư hỏng) + 缺 (khuyết – thiếu) → sứt mẻ, thiếu mất một phần, không trọn vẹn. Cụm: 残缺不全.","hsk_level":6,"tags":["tinh-tu"],"image":"🧩","examples":[{"type":"basic","zh":"这本古书残缺不全。","pinyin":"Zhè běn gǔshū cánquēbùquán.","vi":"Cuốn sách cổ này bị thiếu, không đầy đủ."},{"type":"simple","zh":"考古队员小心地拼接那块残缺的石碑。","pinyin":"Kǎogǔ duìyuán xiǎo xīnde pīnjiē nà kuài cánquē de shíbēi.","vi":"Đội viên khảo cổ cẩn thận ghép lại tấm bia đá bị khuyết."},{"type":"compound","zh":"即使身体有些残缺，他也活出了精彩的人生。","pinyin":"Jíshǐ shēntǐ yǒuxiē cánquē, tā yě huó chūle jīngcǎi de rénshēng.","vi":"Dù cơ thể có khiếm khuyết, anh ấy vẫn sống một cuộc đời rực rỡ."}],"related":[{"hanzi":"缺损","pinyin":"quēsǔn","vi":"thiếu hụt"},{"hanzi":"不全","pinyin":"bùquán","vi":"không đầy đủ"},{"hanzi":"完整","pinyin":"wánzhěng","vi":"hoàn chỉnh"},{"hanzi":"残缺不全","pinyin":"cánquēbùquán","vi":"sứt mẻ không toàn vẹn"}],"traditional":"殘缺"},{"id":"藏龙卧虎","hanzi":"藏龙卧虎","pinyin":"cánglóng-wòhǔ","meaning_vi":"ngọa hổ tàng long (nơi ẩn giấu nhiều nhân tài)","explanation":"藏龙 (tàng long – rồng ẩn) + 卧虎 (ngọa hổ – hổ nằm) → nơi rồng ẩn hổ nằm → nơi có nhiều nhân tài ẩn mình chưa lộ diện.","hsk_level":6,"tags":["thanh-ngu"],"image":"🐉","examples":[{"type":"basic","zh":"这里藏龙卧虎。","pinyin":"Zhèlǐ cánglóngwòhǔ.","vi":"Nơi đây ngọa hổ tàng long."},{"type":"simple","zh":"这所普通中学其实是个藏龙卧虎的地方。","pinyin":"Zhè suǒ pǔtōng zhōngxué qíshí shì gè cánglóngwòhǔ de dìfang.","vi":"Ngôi trường trung học bình thường này thực ra là nơi ẩn chứa nhiều nhân tài."},{"type":"compound","zh":"既然这个比赛藏龙卧虎，我们就不能掉以轻心。","pinyin":"Jìrán zhè ge bǐsài cánglóngwòhǔ, wǒmen jiù bù néng diàoyǐqīngxīn.","vi":"Cuộc thi này đã ngọa hổ tàng long thì chúng ta không được chủ quan."}],"related":[{"hanzi":"人才济济","pinyin":"réncáijǐjǐ","vi":"nhân tài đông đúc"},{"hanzi":"卧虎藏龙","pinyin":"wòhǔcánglóng","vi":"ngọa hổ tàng long"},{"hanzi":"高手","pinyin":"gāoshǒu","vi":"cao thủ"},{"hanzi":"人才","pinyin":"réncái","vi":"nhân tài"}],"traditional":"藏龍臥虎"},{"id":"藏匿","hanzi":"藏匿","pinyin":"cángnì","meaning_vi":"ẩn nấp, cất giấu","explanation":"藏 (giấu) + 匿 (ẩn).","hsk_level":6,"tags":["dong-tu"],"image":"🙈","examples":[{"type":"basic","zh":"逃犯藏匿在山里。","pinyin":"Táofàn cángnì zài shān lǐ.","vi":"Kẻ đào tẩu ẩn nấp trong núi."},{"type":"simple","zh":"警察在床底下发现了他藏匿的现金。","pinyin":"Jǐngchá zài chuáng dǐxia fāxiànle tā cángnì de xiànjīn.","vi":"Cảnh sát phát hiện số tiền mặt hắn cất giấu dưới gầm giường."},{"type":"compound","zh":"无论罪犯藏匿在哪里，警方都会把他找出来。","pinyin":"Wúlùn zuìfàn cángnì zài nǎlǐ, jǐngfāng dōuhuì bǎ tā zhǎo chūlái.","vi":"Dù tội phạm ẩn náu ở đâu, cảnh sát cũng sẽ tìm ra hắn."}],"related":[{"hanzi":"隐藏","pinyin":"yǐncáng","vi":"ẩn giấu"},{"hanzi":"躲藏","pinyin":"duǒcáng","vi":"trốn tránh"},{"hanzi":"窝藏","pinyin":"wōcáng","vi":"chứa chấp"},{"hanzi":"暴露","pinyin":"bàolù","vi":"bại lộ"}]},{"id":"测量","hanzi":"测量","pinyin":"cèliáng","meaning_vi":"đo đạc","explanation":"测 (trắc – đo) + 量 (lượng – đo lường) → đo đạc (kích thước, nhiệt độ…). Thường: 测量体温, 测量土地.","hsk_level":6,"tags":["dong-tu"],"image":"📏","examples":[{"type":"basic","zh":"护士给我测量血压。","pinyin":"Hùshi gěi wǒ cèliáng xuèyā.","vi":"Y tá đo huyết áp cho tôi."},{"type":"simple","zh":"工人们正在测量这块土地的面积。","pinyin":"Gōngrénmen zhèngzài cèliáng zhè kuài tǔdì de miànjī.","vi":"Công nhân đang đo đạc diện tích mảnh đất này."},{"type":"compound","zh":"如果测量的数据不准确，整个实验就白做了。","pinyin":"Rúguǒ cèliáng de shùjù bù zhǔnquè, zhěnggè shíyàn jiù bái zuò le.","vi":"Nếu số liệu đo đạc không chính xác thì cả thí nghiệm coi như làm uổng công."}],"related":[{"hanzi":"测定","pinyin":"cèdìng","vi":"đo xác định"},{"hanzi":"丈量","pinyin":"zhàngliáng","vi":"đo đạc"},{"hanzi":"测量仪","pinyin":"cèliángyí","vi":"máy đo"},{"hanzi":"测试","pinyin":"cèshì","vi":"kiểm tra"}],"traditional":"測量"},{"id":"侧重","hanzi":"侧重","pinyin":"cèzhòng","meaning_vi":"thiên về, chú trọng vào mặt nào","explanation":"侧 (nghiêng) + 重 (coi trọng).","hsk_level":6,"tags":["dong-tu"],"image":"⚖️","examples":[{"type":"basic","zh":"这门课侧重口语。","pinyin":"Zhè mén kè cèzhòng kǒuyǔ.","vi":"Môn học này chú trọng khẩu ngữ."},{"type":"simple","zh":"这次培训主要侧重于提高员工的沟通能力。","pinyin":"Zhè cì péixùn zhǔyào cèzhòng yú tígāo yuángōng de gōutōng nénglì.","vi":"Đợt đào tạo này chủ yếu chú trọng nâng cao khả năng giao tiếp của nhân viên."},{"type":"compound","zh":"与其平均用力，不如侧重解决最关键的问题。","pinyin":"Yǔqí píngjūn yònglì, bùrú cèzhòng jiějué zuì guānjiàn de wèntí.","vi":"Thay vì dàn đều sức lực, chi bằng tập trung giải quyết vấn đề then chốt nhất."}],"related":[{"hanzi":"着重","pinyin":"zhuózhòng","vi":"chú trọng"},{"hanzi":"偏重","pinyin":"piānzhòng","vi":"thiên về"},{"hanzi":"重点","pinyin":"zhòngdiǎn","vi":"trọng điểm"},{"hanzi":"强调","pinyin":"qiángdiào","vi":"nhấn mạnh"}],"traditional":"側重"},{"id":"层出不穷","hanzi":"层出不穷","pinyin":"céngchū-bùqióng","meaning_vi":"xuất hiện lớp lớp không ngừng","explanation":"层出 (tằng xuất – xuất hiện lớp này đến lớp khác) + 不穷 (bất cùng – không hết) → liên tục xuất hiện, không bao giờ hết. Thường: 新产品层出不穷.","hsk_level":6,"tags":["thanh-ngu"],"image":"🌊","examples":[{"type":"basic","zh":"新产品层出不穷。","pinyin":"Xīnchǎnpǐn céngchūbùqióng.","vi":"Sản phẩm mới liên tục xuất hiện."},{"type":"simple","zh":"网络上各种新鲜词汇层出不穷。","pinyin":"Wǎngluò shàng gèzhǒng xīnxiān cíhuì céngchūbùqióng.","vi":"Trên mạng đủ loại từ ngữ mới mẻ xuất hiện không ngừng."},{"type":"compound","zh":"虽然诈骗手段层出不穷，但是只要提高警惕就能防范。","pinyin":"Suīrán zhàpiàn shǒuduàn céngchūbùqióng, dànshì zhǐyào tígāo jǐngtì jiù néng fángfàn.","vi":"Tuy thủ đoạn lừa đảo liên tục xuất hiện, nhưng chỉ cần nâng cao cảnh giác là có thể phòng tránh."}],"related":[{"hanzi":"源源不断","pinyin":"yuányuánbúduàn","vi":"liên tục không dứt"},{"hanzi":"接连不断","pinyin":"jiēliánbúduàn","vi":"liên tiếp"},{"hanzi":"日新月异","pinyin":"rìxīnyuèyì","vi":"thay đổi từng ngày"},{"hanzi":"屈指可数","pinyin":"qūzhǐkěshǔ","vi":"đếm trên đầu ngón tay"}],"traditional":"層出不窮"},{"id":"层峦叠嶂","hanzi":"层峦叠嶂","pinyin":"céngluán-diézhàng","meaning_vi":"núi non trùng điệp","explanation":"层峦 (tằng loan – núi tầng tầng) + 叠嶂 (điệp chướng – vách núi chồng chất) → núi non chồng chất, trùng trùng điệp điệp.","hsk_level":6,"tags":["thanh-ngu","thien-nhien"],"image":"⛰️","examples":[{"type":"basic","zh":"远处层峦叠嶂。","pinyin":"Yuǎnchù céngluándiézhàng.","vi":"Phía xa núi non trùng điệp."},{"type":"simple","zh":"坐在缆车上，可以俯瞰层峦叠嶂的美景。","pinyin":"Zuò zài lǎnchē shàng, kěyǐ fǔkàn céngluándiézhàng de měijǐng.","vi":"Ngồi trên cáp treo có thể ngắm nhìn cảnh đẹp núi non trùng điệp."},{"type":"compound","zh":"一走出山谷，眼前就出现了层峦叠嶂的壮丽景色。","pinyin":"Yì zǒuchū shāngǔ, yǎnqián jiù chūxiànle céngluándiézhàng de zhuànglì jǐngsè.","vi":"Vừa ra khỏi thung lũng, trước mắt đã hiện ra cảnh núi non trùng điệp hùng vĩ."}],"related":[{"hanzi":"崇山峻岭","pinyin":"chóngshānjùnlǐng","vi":"núi non hiểm trở"},{"hanzi":"连绵起伏","pinyin":"liánmiánqǐfú","vi":"nhấp nhô liên tiếp"},{"hanzi":"群山","pinyin":"qúnshān","vi":"dãy núi"},{"hanzi":"一马平川","pinyin":"yìmǎpíngchuān","vi":"đồng bằng bát ngát"}],"traditional":"層巒疊嶂"},{"id":"次日","hanzi":"次日","pinyin":"cìrì","meaning_vi":"ngày hôm sau (văn viết)","explanation":"次 (tiếp theo) + 日 (ngày).","hsk_level":6,"tags":["danh-tu","thoi-gian"],"image":"📅","examples":[{"type":"basic","zh":"他次日就出发了。","pinyin":"Tā cìrì jiù chūfā le.","vi":"Ngày hôm sau anh ấy đã lên đường."},{"type":"simple","zh":"会议安排在报到次日的上午九点举行。","pinyin":"Huìyì ānpái zài bàodào cìrì de shàngwǔ jiǔ diǎn jǔxíng.","vi":"Hội nghị được tổ chức lúc chín giờ sáng, ngày hôm sau ngày đăng ký."},{"type":"compound","zh":"因为他前一天晚上淋了雨，所以次日就发起了高烧。","pinyin":"Yīnwèi tā qiányìtiān wǎnshang línle yǔ, suǒyǐ cìrì jiù fāqǐle gāoshāo.","vi":"Vì tối hôm trước bị mắc mưa nên ngày hôm sau anh ấy sốt cao."}],"related":[{"hanzi":"第二天","pinyin":"dì'èrtiān","vi":"ngày thứ hai"},{"hanzi":"翌日","pinyin":"yìrì","vi":"hôm sau"},{"hanzi":"前日","pinyin":"qiánrì","vi":"hôm trước"},{"hanzi":"当日","pinyin":"dàngrì","vi":"ngày hôm đó"}]},{"id":"词不达意","hanzi":"词不达意","pinyin":"cíbù-dáyì","meaning_vi":"lời không diễn đạt hết ý","explanation":"词 (từ – lời) + 不达 (bất đạt – không đạt tới) + 意 (ý) → lời nói, câu viết không diễn đạt được đúng ý muốn nói.","hsk_level":6,"tags":["thanh-ngu","ngon-ngu"],"image":"🗣️","examples":[{"type":"basic","zh":"我说得词不达意。","pinyin":"Wǒ shuō de cíbùdáyì.","vi":"Tôi nói chưa diễn đạt được hết ý."},{"type":"simple","zh":"这篇翻译有好几处词不达意的地方。","pinyin":"Zhè piān fānyì yǒu hǎojǐ chù cíbùdáyì de dìfang.","vi":"Bản dịch này có mấy chỗ lời không diễn đạt hết ý."},{"type":"compound","zh":"他只要一紧张，说起话来就词不达意。","pinyin":"Tā zhǐyào yì jǐnzhāng, shuōqǐ huà lái jiù cíbùdáyì.","vi":"Hễ căng thẳng là anh ấy nói năng lủng củng, không diễn đạt được ý mình."}],"related":[{"hanzi":"言不由衷","pinyin":"yánbùyóuzhōng","vi":"nói không thật lòng"},{"hanzi":"表达","pinyin":"biǎodá","vi":"biểu đạt"},{"hanzi":"辞不达意","pinyin":"cíbùdáyì","vi":"lời không đạt ý"},{"hanzi":"言简意赅","pinyin":"yánjiǎnyìgāi","vi":"lời gọn ý đủ"}],"traditional":"詞不達意"},{"id":"辞呈","hanzi":"辞呈","pinyin":"cíchéng","meaning_vi":"đơn xin từ chức","explanation":"辞 (từ chức) + 呈 (trình lên).","hsk_level":6,"tags":["danh-tu","cong-viec"],"image":"📄","examples":[{"type":"basic","zh":"他递交了辞呈。","pinyin":"Tā dìjiāole cíchéng.","vi":"Anh ấy đã nộp đơn từ chức."},{"type":"simple","zh":"董事会最终接受了总经理的辞呈。","pinyin":"Dǒngshìhuì zuìzhōng jiēshòule zǒngjīnglǐ de cíchéng.","vi":"Hội đồng quản trị cuối cùng đã chấp nhận đơn từ chức của tổng giám đốc."},{"type":"compound","zh":"虽然老板一再挽留，但是她还是把辞呈放在了桌上。","pinyin":"Suīrán lǎobǎn yízài wǎnliú, dànshì tā háishi bǎ cíchéng fàng zài le zhuō shàng.","vi":"Tuy ông chủ nhiều lần níu giữ, nhưng cô ấy vẫn đặt đơn từ chức lên bàn."}],"related":[{"hanzi":"辞职","pinyin":"cízhí","vi":"từ chức"},{"hanzi":"辞职信","pinyin":"cízhíxìn","vi":"đơn từ chức"},{"hanzi":"递交","pinyin":"dìjiāo","vi":"nộp"},{"hanzi":"离职","pinyin":"lízhí","vi":"nghỉ việc"}],"traditional":"辭呈"},{"id":"辞旧迎新","hanzi":"辞旧迎新","pinyin":"cíjiù-yíngxīn","meaning_vi":"tiễn năm cũ đón năm mới","explanation":"辞旧 (từ cựu – từ biệt cái cũ) + 迎新 (nghênh tân – đón cái mới) → tiễn năm cũ, đón năm mới; thường dùng dịp Tết, giao thừa.","hsk_level":6,"tags":["thanh-ngu","van-hoa"],"image":"🧨","examples":[{"type":"basic","zh":"大家一起辞旧迎新。","pinyin":"Dàjiā yìqǐ cíjiùyíngxīn.","vi":"Mọi người cùng nhau tiễn năm cũ đón năm mới."},{"type":"simple","zh":"除夕夜，人们放鞭炮辞旧迎新。","pinyin":"Chúxīyè, rénmen fàngbiānpào cíjiùyíngxīn.","vi":"Đêm giao thừa, mọi người đốt pháo tiễn năm cũ đón năm mới."},{"type":"compound","zh":"每到辞旧迎新的时刻，广场上就挤满了倒计时的人群。","pinyin":"Měi dào cíjiùyíngxīn de shíkè, guǎngchǎng shàng jiù jǐmǎnle dàojìshí de rénqún.","vi":"Cứ đến thời khắc tiễn năm cũ đón năm mới, quảng trường lại chật kín người đếm ngược."}],"related":[{"hanzi":"除旧布新","pinyin":"chújiùbùxīn","vi":"bỏ cũ đón mới"},{"hanzi":"新年","pinyin":"xīnnián","vi":"năm mới"},{"hanzi":"春节","pinyin":"Chūnjié","vi":"Tết Nguyên Đán"},{"hanzi":"跨年","pinyin":"kuànián","vi":"đón giao thừa"}],"traditional":"辭舊迎新"},{"id":"慈善","hanzi":"慈善","pinyin":"císhàn","meaning_vi":"từ thiện","explanation":"慈 (từ – hiền từ, thương người) + 善 (thiện – tốt) → thương người, làm điều thiện; từ thiện. Thường: 慈善事业, 慈善机构.","hsk_level":6,"tags":["danh-tu"],"image":"💖","examples":[{"type":"basic","zh":"她热心慈善事业。","pinyin":"Tā rèxīn císhàn shìyè.","vi":"Cô ấy nhiệt tình với sự nghiệp từ thiện."},{"type":"simple","zh":"这位企业家把一半收入捐给了慈善机构。","pinyin":"Zhè wèi qǐyèjiā bǎ yíbàn shōurù juāngěile císhàn jīgòu.","vi":"Doanh nhân này đã quyên một nửa thu nhập cho tổ chức từ thiện."},{"type":"compound","zh":"只要人人献出一点爱心，慈善活动就能帮助更多的人。","pinyin":"Zhǐyào rénrén xiànchū yìdiǎn àixīn, císhàn huódòng jiù néng bāngzhù gèng duō de rén.","vi":"Chỉ cần mỗi người góp một chút tình thương, hoạt động từ thiện sẽ giúp được nhiều người hơn."}],"related":[{"hanzi":"慈善家","pinyin":"císhànjiā","vi":"nhà từ thiện"},{"hanzi":"捐款","pinyin":"juānkuǎn","vi":"quyên góp tiền"},{"hanzi":"公益","pinyin":"gōngyì","vi":"công ích"},{"hanzi":"慈善机构","pinyin":"císhànjīgòu","vi":"tổ chức từ thiện"}]},{"id":"雌雄","hanzi":"雌雄","pinyin":"cíxióng","meaning_vi":"đực cái, trống mái","explanation":"雌 (thư – giống cái) + 雄 (hùng – giống đực) → đực và cái; nghĩa bóng: thắng thua, cao thấp (一决雌雄 = quyết một trận sống mái).","hsk_level":6,"tags":["danh-tu","dong-vat"],"image":"🦚","examples":[{"type":"basic","zh":"这种鱼很难分辨雌雄。","pinyin":"Zhè zhǒng yú hěn nán fēnbiàn cíxióng.","vi":"Loài cá này rất khó phân biệt đực cái."},{"type":"simple","zh":"兽医通过羽毛的颜色判断小鸡的雌雄。","pinyin":"Shòuyī tōngguò yǔmáo de yánsè pànduàn xiǎojī de cíxióng.","vi":"Bác sĩ thú y dựa vào màu lông để phán đoán gà con là trống hay mái."},{"type":"compound","zh":"既然两队实力相当，明天的决赛就要决一雌雄了。","pinyin":"Jìrán liǎng duì shílì xiāngdāng, míngtiān de juésài jiùyào juéyìcíxióng le.","vi":"Hai đội đã ngang tài ngang sức thì trận chung kết ngày mai sẽ phân thắng bại."}],"related":[{"hanzi":"雄性","pinyin":"xióngxìng","vi":"giống đực"},{"hanzi":"雌性","pinyin":"cíxìng","vi":"giống cái"},{"hanzi":"公母","pinyin":"gōngmǔ","vi":"đực cái"},{"hanzi":"一决雌雄","pinyin":"yìjuécíxióng","vi":"phân thắng bại"}]},{"id":"凑巧","hanzi":"凑巧","pinyin":"còuqiǎo","meaning_vi":"vừa khéo, trùng hợp","explanation":"凑 + 巧 (khéo). Đồng nghĩa với 恰巧.","hsk_level":6,"tags":["pho-tu"],"image":"🍀","examples":[{"type":"basic","zh":"真凑巧，你也在这儿！","pinyin":"Zhēn còuqiǎo, nǐ yě zài zhèr!","vi":"Thật trùng hợp, bạn cũng ở đây!"},{"type":"simple","zh":"他凑巧赶上了最后一班公交车。","pinyin":"Tā còuqiǎo gǎnshàngle zuìhòu yì bān gōngjiāochē.","vi":"Anh ấy vừa khéo bắt kịp chuyến xe buýt cuối cùng."},{"type":"compound","zh":"我刚想给她打电话，凑巧她就推门进来了。","pinyin":"Wǒ gāng xiǎng gěi tā dǎdiànhuà, còuqiǎo tā jiù tuī mén jìnlái le.","vi":"Tôi vừa định gọi điện cho cô ấy thì thật trùng hợp cô ấy đẩy cửa bước vào."}],"related":[{"hanzi":"碰巧","pinyin":"pèngqiǎo","vi":"vừa may"},{"hanzi":"恰巧","pinyin":"qiàqiǎo","vi":"vừa khéo"},{"hanzi":"巧合","pinyin":"qiǎohé","vi":"trùng hợp"},{"hanzi":"偶然","pinyin":"ǒurán","vi":"ngẫu nhiên"}],"traditional":"湊巧"},{"id":"从容不迫","hanzi":"从容不迫","pinyin":"cóngróng-búpò","meaning_vi":"ung dung bình tĩnh không hề vội vã","explanation":"从容不迫: 从容 (thung dung – ung dung) + 不迫 (bất bách – không gấp gáp) → ung dung bình tĩnh, không hề vội vã, bối rối. Cụm: 从容不迫地回答.","hsk_level":6,"tags":["thanh-ngu"],"image":"😌","examples":[{"type":"basic","zh":"他从容不迫地回答。","pinyin":"Tā cóngróng bú pò de huídá.","vi":"Anh ấy ung dung trả lời."},{"type":"simple","zh":"面对突发的停电，空姐从容不迫地安抚乘客。","pinyin":"Miànduì tūfā de tíngdiàn, kōngjiě cóngróng bú pò de ānfǔ chéngkè.","vi":"Trước sự cố mất điện bất ngờ, tiếp viên hàng không bình tĩnh trấn an hành khách."},{"type":"compound","zh":"只要平时准备充分，考试时就能从容不迫。","pinyin":"Zhǐyào píngshí zhǔnbèi chōngfèn, kǎoshì shí jiù néng cóngróng bú pò.","vi":"Chỉ cần ngày thường chuẩn bị kỹ, lúc thi sẽ có thể ung dung bình tĩnh."}],"related":[{"hanzi":"不慌不忙","pinyin":"bùhuāngbùmáng","vi":"thong thả"},{"hanzi":"镇定自若","pinyin":"zhèndìngzìruò","vi":"bình tĩnh tự nhiên"},{"hanzi":"从容","pinyin":"cóngróng","vi":"ung dung"},{"hanzi":"手忙脚乱","pinyin":"shǒumángjiǎoluàn","vi":"luống cuống"}],"traditional":"從容不迫"},{"id":"从天而降","hanzi":"从天而降","pinyin":"cóngtiān-érjiàng","meaning_vi":"từ trên trời rơi xuống (bất ngờ xuất hiện)","explanation":"从天 (tòng thiên – từ trời) + 而降 (nhi giáng – rơi xuống) → từ trên trời rơi xuống → xuất hiện bất ngờ ngoài dự liệu (có thể là may mắn hoặc tai họa).","hsk_level":6,"tags":["thanh-ngu"],"image":"⚡","examples":[{"type":"basic","zh":"好运从天而降。","pinyin":"Hǎoyùn cóng tiān ér jiàng.","vi":"Vận may từ trên trời rơi xuống."},{"type":"simple","zh":"那天下午一笔意外的奖金从天而降。","pinyin":"Nà tiān xiàwǔ yì bǐ yìwài de jiǎngjīn cóng tiān ér jiàng.","vi":"Chiều hôm đó, một khoản tiền thưởng bất ngờ từ trên trời rơi xuống."},{"type":"compound","zh":"即使机会从天而降，没有准备的人也抓不住。","pinyin":"Jíshǐ jīhuì cóng tiān ér jiàng, méiyǒu zhǔnbèi de rén yě zhuā búzhù.","vi":"Cho dù cơ hội từ trên trời rơi xuống, người không chuẩn bị cũng không nắm bắt được."}],"related":[{"hanzi":"突如其来","pinyin":"tūrúqílái","vi":"đột ngột ập đến"},{"hanzi":"意外","pinyin":"yìwài","vi":"bất ngờ"},{"hanzi":"天上掉馅饼","pinyin":"tiānshàng diào xiànbǐng","vi":"trên trời rơi xuống"},{"hanzi":"降落","pinyin":"jiàngluò","vi":"hạ cánh"}],"traditional":"從天而降"},{"id":"簇拥","hanzi":"簇拥","pinyin":"cùyōng","meaning_vi":"vây quanh, xúm xít quanh","explanation":"簇 (tụ tập) + 拥 (ôm/vây).","hsk_level":6,"tags":["dong-tu"],"image":"👥","examples":[{"type":"basic","zh":"粉丝簇拥着明星。","pinyin":"Fěnsī cùyōngzhe míngxīng.","vi":"Người hâm mộ vây quanh ngôi sao."},{"type":"simple","zh":"孩子们簇拥着老师走进了教室。","pinyin":"Háizimen cùyōngzhe lǎoshī zǒujìnle jiàoshì.","vi":"Bọn trẻ xúm xít quanh cô giáo đi vào lớp học."},{"type":"compound","zh":"新娘一下车，亲友们就簇拥上去向她祝贺。","pinyin":"Xīnniáng yí xiàchē, qīnyǒumen jiù cùyōng shàng qùxiàng tā zhùhè.","vi":"Cô dâu vừa xuống xe, bạn bè người thân liền xúm lại chúc mừng cô."}],"related":[{"hanzi":"围绕","pinyin":"wéirào","vi":"vây quanh"},{"hanzi":"拥挤","pinyin":"yōngjǐ","vi":"chen chúc"},{"hanzi":"围","pinyin":"wéi","vi":"vây"},{"hanzi":"前呼后拥","pinyin":"qiánhūhòuyōng","vi":"kẻ trước người sau vây quanh"}],"traditional":"簇擁"},{"id":"寸步难行","hanzi":"寸步难行","pinyin":"cùnbù-nánxíng","meaning_vi":"nửa bước khó đi (vô cùng khó khăn)","explanation":"寸步 (một tấc bước) + 难行 (khó đi). Thành ngữ.","hsk_level":6,"tags":["thanh-ngu"],"image":"🚧","examples":[{"type":"basic","zh":"雪大得寸步难行。","pinyin":"Xuě dà de cùnbùnánxíng.","vi":"Tuyết rơi dày đến mức nửa bước cũng khó đi."},{"type":"simple","zh":"早高峰的地铁站里挤得寸步难行。","pinyin":"Zǎogāofēng de dìtiězhàn lǐ jǐ de cùnbùnánxíng.","vi":"Trong ga tàu điện giờ cao điểm buổi sáng chen chúc đến mức nửa bước cũng khó đi."},{"type":"compound","zh":"如果不会说当地语言，你在那里就会寸步难行。","pinyin":"Rúguǒ bú huì shuō dāngdì yǔyán, nǐ zài nàlǐ jiù huì cùnbùnánxíng.","vi":"Nếu không biết nói tiếng địa phương, bạn ở đó sẽ gặp khó khăn từng bước."}],"related":[{"hanzi":"举步维艰","pinyin":"jǔbùwéijiān","vi":"từng bước khó khăn"},{"hanzi":"困难重重","pinyin":"kùnnanchóngchóng","vi":"khó khăn chồng chất"},{"hanzi":"畅通无阻","pinyin":"chàngtōngwúzǔ","vi":"thông suốt"},{"hanzi":"进退两难","pinyin":"jìntuìliǎngnán","vi":"tiến thoái lưỡng nan"}],"traditional":"寸步難行"},{"id":"存亡","hanzi":"存亡","pinyin":"cúnwáng","meaning_vi":"còn mất, tồn vong","explanation":"存 (tồn tại) + 亡 (diệt vong).","hsk_level":6,"tags":["danh-tu"],"image":"⚖️","examples":[{"type":"basic","zh":"国家存亡在此一战。","pinyin":"Guójiā cúnwáng zài cǐ Yízhàn.","vi":"Sự tồn vong của quốc gia phụ thuộc vào trận này."},{"type":"simple","zh":"这次谈判关系到公司的生死存亡。","pinyin":"Zhè cì tánpàn guānxìdào gōngsī de shēngsǐ cúnwáng.","vi":"Cuộc đàm phán lần này liên quan đến sự sống còn của công ty."},{"type":"compound","zh":"既然到了存亡关头，我们就不能再互相指责了。","pinyin":"Jìrán dàole cúnwáng guāntóu, wǒmen jiù bù néng zài hùxiāng zhǐzé le.","vi":"Đã đến thời khắc tồn vong, chúng ta không thể tiếp tục đổ lỗi cho nhau nữa."}],"related":[{"hanzi":"生死存亡","pinyin":"shēngsǐcúnwáng","vi":"sống còn"},{"hanzi":"生死","pinyin":"shēngsǐ","vi":"sống chết"},{"hanzi":"兴亡","pinyin":"xīngwáng","vi":"hưng vong"},{"hanzi":"危亡","pinyin":"wēiwáng","vi":"nguy vong"}]},{"id":"存心","hanzi":"存心","pinyin":"cúnxīn","meaning_vi":"cố tình, có ý định trước","explanation":"存 (giữ) + 心 (lòng).","hsk_level":6,"tags":["pho-tu"],"image":"😏","examples":[{"type":"basic","zh":"他存心气我。","pinyin":"Tā cúnxīn qì wǒ.","vi":"Anh ta cố tình chọc tức tôi."},{"type":"simple","zh":"那个司机存心把车停在我家门口。","pinyin":"Nà gè sījī cúnxīn bǎ chē tíng zài wǒ jiā ménkǒu.","vi":"Tài xế đó cố tình đỗ xe ngay trước cửa nhà tôi."},{"type":"compound","zh":"虽然他打碎了花瓶，但是他并不是存心的。","pinyin":"Suīrán tā dǎsuìle huāpíng, dànshì tā bìngbú shì cúnxīn de.","vi":"Tuy cậu ấy làm vỡ bình hoa, nhưng cậu ấy không hề cố ý."}],"related":[{"hanzi":"故意","pinyin":"gùyì","vi":"cố ý"},{"hanzi":"有意","pinyin":"yǒuyì","vi":"có ý"},{"hanzi":"无意","pinyin":"wúyì","vi":"vô ý"},{"hanzi":"成心","pinyin":"chéngxīn","vi":"cố tình"}]},{"id":"参谋","hanzi":"参谋","pinyin":"cānmóu","meaning_vi":"tham mưu, cố vấn","explanation":"参 (tham – tham dự) + 谋 (mưu – mưu kế) → tham gia bày mưu; danh từ: sĩ quan tham mưu; khẩu ngữ: góp ý, tư vấn (帮我参谋参谋).","hsk_level":6,"tags":["dong-tu"],"image":"🧠","examples":[{"type":"basic","zh":"你帮我参谋一下。","pinyin":"Nǐ bāng wǒ cānmóu yíxià.","vi":"Bạn giúp tôi góp ý một chút nhé."},{"type":"simple","zh":"妈妈陪我去商场参谋买哪件大衣。","pinyin":"Māma péi wǒqù shāngchǎng cānmóu mǎi nǎ jiàn dàyī.","vi":"Mẹ đi cùng tôi đến trung tâm thương mại để góp ý nên mua chiếc áo khoác nào."},{"type":"compound","zh":"买房是大事，所以我请了懂行的朋友帮忙参谋。","pinyin":"Mǎifáng shì dàshì, suǒyǐ wǒ qǐngle dǒngháng de péngyou bāngmáng cānmóu.","vi":"Mua nhà là việc lớn, nên tôi đã nhờ một người bạn am hiểu giúp tư vấn."}],"related":[{"hanzi":"顾问","pinyin":"gùwèn","vi":"cố vấn"},{"hanzi":"出主意","pinyin":"chūzhǔyi","vi":"góp ý"},{"hanzi":"参谋长","pinyin":"cānmóuzhǎng","vi":"tham mưu trưởng"},{"hanzi":"军师","pinyin":"jūnshī","vi":"quân sư"}],"traditional":"參謀"},{"id":"舱","hanzi":"舱","pinyin":"cāng","meaning_vi":"khoang tàu/máy bay","explanation":"舱 (thương) → khoang trên tàu thuyền, máy bay. Ví dụ: 船舱, 机舱, 头等舱 (khoang hạng nhất), 经济舱 (khoang phổ thông).","hsk_level":6,"tags":["danh-tu","giao-thong"],"image":"✈️","examples":[{"type":"basic","zh":"这是头等舱。","pinyin":"Zhè shì tóuděngcāng.","vi":"Đây là khoang hạng nhất."},{"type":"simple","zh":"乘客们排队走进了飞机的经济舱。","pinyin":"Chéngkèmen páiduì zǒujìnle fēijī de jīngjìcāng.","vi":"Hành khách xếp hàng đi vào khoang phổ thông của máy bay."},{"type":"compound","zh":"船舱里虽然很小，但是收拾得十分整洁。","pinyin":"Chuáncāng lǐ suīrán hěn xiǎo, dànshì shōushi de shífēn zhěngjié.","vi":"Khoang tàu tuy rất nhỏ nhưng được dọn dẹp rất ngăn nắp."}],"related":[{"hanzi":"船舱","pinyin":"chuáncāng","vi":"khoang tàu"},{"hanzi":"机舱","pinyin":"jīcāng","vi":"khoang máy bay"},{"hanzi":"头等舱","pinyin":"tóuděngcāng","vi":"khoang hạng nhất"},{"hanzi":"经济舱","pinyin":"jīngjìcāng","vi":"khoang phổ thông"}],"traditional":"艙"},{"id":"仓促","hanzi":"仓促","pinyin":"cāngcù","meaning_vi":"vội vã, gấp gáp, cập rập","explanation":"仓 (vội) + 促 (gấp).","hsk_level":6,"tags":["tinh-tu","pho-tu"],"image":"🏃","examples":[{"type":"basic","zh":"他走得很仓促。","pinyin":"Tā zǒu de hěn cāngcù.","vi":"Anh ấy đi rất vội vã."},{"type":"simple","zh":"我们仓促地收拾好行李赶往机场。","pinyin":"Wǒmen cāngcù de shōushi hǎo xíngli gǎnwǎng jīchǎng.","vi":"Chúng tôi vội vã thu dọn hành lý rồi lao ra sân bay."},{"type":"compound","zh":"因为准备得太仓促，所以这次演讲漏洞百出。","pinyin":"Yīnwèi zhǔnbèi de tài cāngcù, suǒyǐ zhè cì yǎnjiǎng lòudòng bǎichū.","vi":"Vì chuẩn bị quá vội vàng nên bài diễn thuyết lần này đầy sơ hở."}],"related":[{"hanzi":"匆忙","pinyin":"cōngmáng","vi":"vội vàng"},{"hanzi":"急忙","pinyin":"jímáng","vi":"gấp gáp"},{"hanzi":"草率","pinyin":"cǎoshuài","vi":"qua loa"},{"hanzi":"从容","pinyin":"cóngróng","vi":"ung dung"}],"traditional":"倉促"},{"id":"沧桑","hanzi":"沧桑","pinyin":"cāngsāng","meaning_vi":"bãi bể nương dâu, sự biến đổi thăng trầm","explanation":"Cả hai chữ đều có bộ thủy/thảo.","hsk_level":6,"tags":["danh-tu","tinh-tu"],"image":"🌊","examples":[{"type":"basic","zh":"老街饱经沧桑。","pinyin":"Lǎojiē bǎojīngcāngsāng.","vi":"Con phố cổ đã trải qua bao thăng trầm."},{"type":"simple","zh":"爷爷的脸上写满了岁月的沧桑。","pinyin":"Yéye de liǎn shàng xiě mǎnle suìyuè de cāngsāng.","vi":"Gương mặt ông nội hằn đầy dấu vết thăng trầm của năm tháng."},{"type":"compound","zh":"这座古桥虽然历经沧桑，却依然稳稳地横跨在河上。","pinyin":"Zhè zuò gǔ qiáo suīrán lìjīng cāngsāng, què yīrán wěnwěn de héngkuà zài hé shàng.","vi":"Cây cầu cổ này tuy đã trải qua bao biến đổi nhưng vẫn vững vàng bắc ngang sông."}],"related":[{"hanzi":"沧海桑田","pinyin":"cānghǎisāngtián","vi":"bãi bể nương dâu"},{"hanzi":"饱经沧桑","pinyin":"bǎojīngcāngsāng","vi":"trải nhiều thăng trầm"},{"hanzi":"变迁","pinyin":"biànqiān","vi":"biến thiên"},{"hanzi":"岁月","pinyin":"suìyuè","vi":"năm tháng"}],"traditional":"滄桑"},{"id":"操劳","hanzi":"操劳","pinyin":"cāoláo","meaning_vi":"vất vả lo toan","explanation":"操 (thao – nắm, lo liệu) + 劳 (lao – vất vả) → làm lụng vất vả, lo toan nhiều việc. Thường: 为家务操劳, 操劳过度.","hsk_level":6,"tags":["dong-tu"],"image":"😓","examples":[{"type":"basic","zh":"母亲操劳了一生。","pinyin":"Mǔqīn cāoláole yìshēng.","vi":"Mẹ đã vất vả lo toan cả một đời."},{"type":"simple","zh":"奶奶每天为一家人的三餐操劳。","pinyin":"Nǎinai měitiān wèi yìjiārén de sān cān cāoláo.","vi":"Bà nội ngày nào cũng vất vả lo ba bữa cơm cho cả nhà."},{"type":"compound","zh":"父亲常年操劳，所以头发早早就白了。","pinyin":"Fùqīn chángnián cāoláo, suǒyǐ tóufa zǎo zǎojiù bái le.","vi":"Cha quanh năm vất vả lo toan nên tóc đã bạc sớm."}],"related":[{"hanzi":"劳累","pinyin":"láolèi","vi":"mệt nhọc"},{"hanzi":"辛劳","pinyin":"xīnláo","vi":"vất vả"},{"hanzi":"操心","pinyin":"cāoxīn","vi":"lo lắng"},{"hanzi":"过度操劳","pinyin":"guòdùcāoláo","vi":"làm việc quá sức"}],"traditional":"操勞"},{"id":"操之过急","hanzi":"操之过急","pinyin":"cāozhī-guòjí","meaning_vi":"hành động quá nóng vội","explanation":"操 (thao – làm) + 之 + 过急 (quá cấp – quá vội) → làm việc quá nóng vội, hấp tấp, không chờ điều kiện chín muồi.","hsk_level":6,"tags":["thanh-ngu"],"image":"🏃","examples":[{"type":"basic","zh":"这事不能操之过急。","pinyin":"Zhè shì bù néng cāozhīguòjí.","vi":"Việc này không thể nóng vội."},{"type":"simple","zh":"学外语最忌讳操之过急。","pinyin":"Xué wàiyǔ zuì jìhuì cāozhīguòjí.","vi":"Học ngoại ngữ kỵ nhất là nóng vội."},{"type":"compound","zh":"如果你操之过急，就可能把谈判彻底搞砸。","pinyin":"Rúguǒ nǐ cāozhīguòjí, jiù kěnéng bǎ tánpàn chèdǐ gǎozá.","vi":"Nếu bạn quá nóng vội thì có thể làm hỏng hoàn toàn cuộc đàm phán."}],"related":[{"hanzi":"急于求成","pinyin":"jíyúqiúchéng","vi":"nóng vội muốn thành công"},{"hanzi":"拔苗助长","pinyin":"bámiáozhùzhǎng","vi":"nóng vội hỏng việc"},{"hanzi":"心急","pinyin":"xīnjí","vi":"sốt ruột"},{"hanzi":"循序渐进","pinyin":"xúnxùjiànjìn","vi":"tuần tự tiến dần"}],"traditional":"操之過急"},{"id":"操纵","hanzi":"操纵","pinyin":"cāozòng","meaning_vi":"thao túng, điều khiển","explanation":"操 (nắm giữ) + 纵 (thả/điều khiển).","hsk_level":6,"tags":["dong-tu","cong-nghe"],"image":"🎛️","examples":[{"type":"basic","zh":"他会操纵无人机。","pinyin":"Tā huì cāozòng wúrénjī.","vi":"Anh ấy biết điều khiển máy bay không người lái."},{"type":"simple","zh":"警方查出有人暗中操纵股价。","pinyin":"Jǐngfāng cháchū yǒurén ànzhōng cāozòng gǔjià.","vi":"Cảnh sát phát hiện có người ngầm thao túng giá cổ phiếu."},{"type":"compound","zh":"一旦比赛被人操纵，观众就再也不会相信结果了。","pinyin":"Yídàn bǐsài bèi rén cāozòng, guānzhòng jiù zài yě bú huì xiāngxìn jiéguǒ le.","vi":"Một khi trận đấu bị người khác thao túng, khán giả sẽ không bao giờ tin vào kết quả nữa."}],"related":[{"hanzi":"控制","pinyin":"kòngzhì","vi":"khống chế"},{"hanzi":"操作","pinyin":"cāozuò","vi":"thao tác"},{"hanzi":"摆布","pinyin":"bǎibu","vi":"sai khiến"},{"hanzi":"幕后操纵","pinyin":"mùhòucāozòng","vi":"giật dây sau màn"}],"traditional":"操縱"},{"id":"参差不齐","hanzi":"参差不齐","pinyin":"cēncī-bùqí","meaning_vi":"lởm chởm không đều (đọc cēn cī)","explanation":"参差 (sâm si – dài ngắn không đều) + 不齐 (bất tề – không đều) → so le, không đồng đều; thường nói chất lượng, trình độ: 水平参差不齐.","hsk_level":6,"tags":["thanh-ngu"],"image":"📊","examples":[{"type":"basic","zh":"篱笆参差不齐。","pinyin":"Líba cēncībùqí.","vi":"Hàng rào lởm chởm không đều."},{"type":"simple","zh":"这个班学生的水平参差不齐。","pinyin":"Zhè gè bān xuésheng de shuǐpíng cēncībùqí.","vi":"Trình độ học sinh lớp này không đồng đều."},{"type":"compound","zh":"由于应聘者素质参差不齐，公司只好增加一轮面试。","pinyin":"Yóuyú yìngpìnzhě sùzhì cēncībùqí, gōngsī zhǐhǎo zēngjiā yìlún miànshì.","vi":"Do tố chất các ứng viên không đồng đều, công ty đành phải thêm một vòng phỏng vấn."}],"related":[{"hanzi":"高低不平","pinyin":"gāodībùpíng","vi":"cao thấp không đều"},{"hanzi":"良莠不齐","pinyin":"liángyǒubùqí","vi":"tốt xấu lẫn lộn"},{"hanzi":"整齐","pinyin":"zhěngqí","vi":"ngay ngắn"},{"hanzi":"错落","pinyin":"cuòluò","vi":"so le"}],"traditional":"參差不齊"},{"id":"聪慧","hanzi":"聪慧","pinyin":"cōnghuì","meaning_vi":"thông minh sáng suốt","explanation":"聪 (thông – thính, sáng) + 慧 (tuệ – trí tuệ) → thông minh, sáng dạ. Văn viết, thường khen người: 聪慧过人.","hsk_level":6,"tags":["tinh-tu"],"image":"🧠","examples":[{"type":"basic","zh":"她自幼聪慧。","pinyin":"Tā zìyòu cōnghuì.","vi":"Cô ấy thông minh từ nhỏ."},{"type":"simple","zh":"这位聪慧的女孩十岁就能读古文。","pinyin":"Zhè wèi cōnghuì de nǚhái shí suì jiù néng dú gǔwén.","vi":"Cô bé thông minh này mười tuổi đã đọc được văn cổ."},{"type":"compound","zh":"他不但聪慧过人，而且待人非常谦和。","pinyin":"Tā búdàn cōnghuì guòrén, érqiě dàirén fēicháng qiānhé.","vi":"Anh ấy không những thông minh hơn người mà còn đối xử với mọi người rất khiêm nhường."}],"related":[{"hanzi":"聪明","pinyin":"cōngming","vi":"thông minh"},{"hanzi":"智慧","pinyin":"zhìhuì","vi":"trí tuệ"},{"hanzi":"聪颖","pinyin":"cōngyǐng","vi":"thông minh lanh lợi"},{"hanzi":"愚笨","pinyin":"yúbèn","vi":"ngu đần"}],"traditional":"聰慧"},{"id":"聪明伶俐","hanzi":"聪明伶俐","pinyin":"cōngming-línglì","meaning_vi":"thông minh lanh lợi","explanation":"聪明 (thông minh) + 伶俐 (linh lợi – nhanh nhẹn, khéo léo) → thông minh lanh lợi; thường dùng khen trẻ em.","hsk_level":6,"tags":["thanh-ngu"],"image":"🦊","examples":[{"type":"basic","zh":"小侄女聪明伶俐。","pinyin":"Xiǎo zhínǚ cōngminglínglì.","vi":"Cháu gái nhỏ thông minh lanh lợi."},{"type":"simple","zh":"邻居家有个聪明伶俐的小男孩。","pinyin":"Lín jūjiā yǒu gè cōngminglínglì de xiǎo nánhái.","vi":"Nhà hàng xóm có một cậu bé thông minh lanh lợi."},{"type":"compound","zh":"这只小狗聪明伶俐，主人一喊它就跑过来。","pinyin":"Zhè zhī xiǎogǒu cōngminglínglì, zhǔrén yì hǎn tā jiù pǎo guòlái.","vi":"Chú chó nhỏ này thông minh lanh lợi, chủ vừa gọi là nó chạy lại ngay."}],"related":[{"hanzi":"机灵","pinyin":"jīling","vi":"lanh lợi"},{"hanzi":"聪明","pinyin":"cōngming","vi":"thông minh"},{"hanzi":"乖巧","pinyin":"guāiqiǎo","vi":"ngoan ngoãn khéo léo"},{"hanzi":"愚笨","pinyin":"yúbèn","vi":"ngu đần"}],"traditional":"聰明伶俐"},{"id":"聪颖","hanzi":"聪颖","pinyin":"cōngyǐng","meaning_vi":"thông minh, lanh lợi","explanation":"聪 (thông – thông minh) + 颖 (dĩnh – sáng dạ, xuất chúng) → thông minh, sáng dạ (văn viết, thường khen trẻ). Cụm: 聪颖过人.","hsk_level":6,"tags":["tinh-tu","con-nguoi"],"image":"🧠","examples":[{"type":"basic","zh":"这孩子天资聪颖。","pinyin":"Zhè háizi tiānzī cōngyǐng.","vi":"Đứa trẻ này thiên tư thông minh."},{"type":"simple","zh":"聪颖的他连跳两级考上了大学。","pinyin":"Cōngyǐng de tā lián tiào liǎng jí kǎoshàngle dàxué.","vi":"Thông minh như cậu ấy, nhảy liền hai lớp rồi đỗ đại học."},{"type":"compound","zh":"虽然她聪颖过人，但是从来不放松学习。","pinyin":"Suīrán tā cōngyǐng guòrén, dànshì cóngláibú fàngsōng xuéxí.","vi":"Tuy cô ấy thông minh hơn người nhưng chưa bao giờ lơ là việc học."}],"related":[{"hanzi":"聪慧","pinyin":"cōnghuì","vi":"thông tuệ"},{"hanzi":"聪明","pinyin":"cōngming","vi":"thông minh"},{"hanzi":"天资","pinyin":"tiānzī","vi":"tư chất"},{"hanzi":"迟钝","pinyin":"chídùn","vi":"chậm chạp"}],"traditional":"聰穎"},{"id":"粗犷","hanzi":"粗犷","pinyin":"cūguǎng","meaning_vi":"phóng khoáng, mạnh mẽ (nét vẽ/tính cách)","explanation":"粗 (thô – thô) + 犷 (quảng – thô dã, mạnh mẽ) → thô mộc mạnh mẽ, phóng khoáng (tính cách, phong cách, đường nét). Cụm: 粗犷的歌声.","hsk_level":6,"tags":["tinh-tu"],"image":"🎨","examples":[{"type":"basic","zh":"他的歌声很粗犷。","pinyin":"Tā de gēshēng hěn cūguǎng.","vi":"Giọng hát của anh ấy rất mạnh mẽ phóng khoáng."},{"type":"simple","zh":"草原上的牧民性格豪爽粗犷。","pinyin":"Cǎoyuán shàng de mùmín xìnggé háoshuǎng cūguǎng.","vi":"Những người chăn nuôi trên thảo nguyên có tính cách hào sảng, phóng khoáng."},{"type":"compound","zh":"这幅画虽然线条粗犷，但是细节处理得很用心。","pinyin":"Zhè fú huà suīrán xiàntiáo cūguǎng, dànshì xìjié chǔlǐ de hěn yòngxīn.","vi":"Bức tranh này tuy nét vẽ phóng khoáng mạnh mẽ nhưng chi tiết được xử lý rất tỉ mỉ."}],"related":[{"hanzi":"豪放","pinyin":"háofàng","vi":"hào phóng"},{"hanzi":"奔放","pinyin":"bēnfàng","vi":"phóng khoáng"},{"hanzi":"细腻","pinyin":"xìnì","vi":"tinh tế"},{"hanzi":"豪迈","pinyin":"háomài","vi":"hào hùng"}],"traditional":"粗獷"},{"id":"粗鲁","hanzi":"粗鲁","pinyin":"cūlǔ","meaning_vi":"thô lỗ","explanation":"粗 (thô – thô) + 鲁 (lỗ – lỗ mãng) → thô lỗ, lỗ mãng. Thường: 说话粗鲁, 粗鲁的行为.","hsk_level":6,"tags":["tinh-tu"],"image":"😠","examples":[{"type":"basic","zh":"别这么粗鲁！","pinyin":"Bié zhème cūlǔ!","vi":"Đừng thô lỗ như vậy!"},{"type":"simple","zh":"那位顾客粗鲁地推开了服务员。","pinyin":"Nà wèi gùkè cūlǔ de tuīkāile fúwùyuán.","vi":"Vị khách đó thô bạo đẩy nhân viên phục vụ ra."},{"type":"compound","zh":"如果你说话再这么粗鲁，就没人愿意跟你合作了。","pinyin":"Rúguǒ nǐ shuōhuà zài zhème cūlǔ, jiù méi rén yuànyì gēn nǐ hézuò le.","vi":"Nếu bạn còn ăn nói thô lỗ như vậy thì sẽ chẳng ai muốn hợp tác với bạn nữa."}],"related":[{"hanzi":"粗暴","pinyin":"cūbào","vi":"thô bạo"},{"hanzi":"野蛮","pinyin":"yěmán","vi":"dã man"},{"hanzi":"无礼","pinyin":"wúlǐ","vi":"vô lễ"},{"hanzi":"文雅","pinyin":"wényǎ","vi":"nho nhã"}],"traditional":"粗魯"},{"id":"粗心大意","hanzi":"粗心大意","pinyin":"cūxīn-dàyì","meaning_vi":"bất cẩn lơ đễnh","explanation":"粗心 (thô tâm – lòng dạ sơ sài) + 大意 (đại ý – lơ là) → làm việc không cẩn thận, hay sơ suất. Thường dùng để phê bình: 考试时粗心大意.","hsk_level":6,"tags":["thanh-ngu"],"image":"⚠️","examples":[{"type":"basic","zh":"他做题粗心大意。","pinyin":"Tā zuò tí cūxīndàyì.","vi":"Cậu ấy làm bài rất bất cẩn."},{"type":"simple","zh":"护士粗心大意拿错了病人的药。","pinyin":"Hùshi cūxīndàyì ná cuòle bìngrén de yào.","vi":"Y tá bất cẩn lấy nhầm thuốc của bệnh nhân."},{"type":"compound","zh":"因为粗心大意，所以他把护照落在了出租车上。","pinyin":"Yīnwèi cūxīndàyì, suǒyǐ tā bǎ hùzhào là zài le chūzūchē shàng.","vi":"Vì bất cẩn nên anh ấy đã để quên hộ chiếu trên taxi."}],"related":[{"hanzi":"马虎","pinyin":"mǎhu","vi":"cẩu thả"},{"hanzi":"粗心","pinyin":"cūxīn","vi":"sơ ý"},{"hanzi":"粗枝大叶","pinyin":"cūzhīdàyè","vi":"qua loa đại khái"},{"hanzi":"细心","pinyin":"xìxīn","vi":"cẩn thận"}]},{"id":"粗枝大叶","hanzi":"粗枝大叶","pinyin":"cūzhī-dàyè","meaning_vi":"qua loa đại khái, cẩu thả không tỉ mỉ","explanation":"粗枝 (cành to thô) + 大叶 (lá to) → vẽ cây chỉ phác cành lá thô → ví làm việc qua loa, đại khái, không tỉ mỉ.","hsk_level":6,"tags":["thanh-ngu"],"image":"🙈","examples":[{"type":"basic","zh":"他干活粗枝大叶。","pinyin":"Tā gànhuó cūzhīdàyè.","vi":"Anh ta làm việc qua loa đại khái."},{"type":"simple","zh":"粗枝大叶的小王又把报表填错了。","pinyin":"Cūzhīdàyè de xiǎo Wáng yòu bǎ bàobiǎo tián cuò le.","vi":"Tiểu Vương cẩu thả lại điền sai bảng báo cáo rồi."},{"type":"compound","zh":"做实验既需要耐心，又不能粗枝大叶。","pinyin":"Zuò shíyàn jì xūyào nàixīn, yòu bù néng cūzhīdàyè.","vi":"Làm thí nghiệm vừa cần kiên nhẫn, vừa không được qua loa đại khái."}],"related":[{"hanzi":"马马虎虎","pinyin":"mǎmǎhūhū","vi":"qua loa"},{"hanzi":"敷衍了事","pinyin":"fūyǎnliǎoshì","vi":"làm cho xong chuyện"},{"hanzi":"粗心大意","pinyin":"cūxīndàyì","vi":"bất cẩn"},{"hanzi":"一丝不苟","pinyin":"yìsībùgǒu","vi":"cẩn thận tỉ mỉ"}],"traditional":"粗枝大葉"},{"id":"采集","hanzi":"采集","pinyin":"cǎijí","meaning_vi":"thu thập, sưu tầm","explanation":"采 (thái – hái, lấy) + 集 (tập – gom lại) → thu thập, sưu tầm. Thường đi với 采集样本, 采集数据, 采集标本.","hsk_level":6,"tags":["dong-tu"],"image":"🔬","examples":[{"type":"basic","zh":"蜜蜂在采集花粉。","pinyin":"Mìfēng zài cǎijí huāfěn.","vi":"Ong đang thu thập phấn hoa."},{"type":"simple","zh":"警察在现场采集了几枚指纹。","pinyin":"Jǐngchá zài xiànchǎng cǎijíle jǐ méi zhǐwén.","vi":"Cảnh sát đã thu thập vài dấu vân tay tại hiện trường."},{"type":"compound","zh":"只要采集到足够的数据，我们就能完成这份报告。","pinyin":"Zhǐyào cǎijí dào zúgòu de shùjù, wǒmen jiù néng wánchéng zhè fèn bàogào.","vi":"Chỉ cần thu thập đủ dữ liệu, chúng ta sẽ hoàn thành được bản báo cáo này."}],"related":[{"hanzi":"收集","pinyin":"shōují","vi":"thu thập"},{"hanzi":"搜集","pinyin":"sōují","vi":"sưu tập"},{"hanzi":"采摘","pinyin":"cǎizhāi","vi":"hái, ngắt"},{"hanzi":"数据采集","pinyin":"shùjùcǎijí","vi":"thu thập dữ liệu"}],"traditional":"採集"},{"id":"彩排","hanzi":"彩排","pinyin":"cǎipái","meaning_vi":"tổng duyệt (chương trình biểu diễn)","explanation":"彩 + 排 (diễn tập).","hsk_level":6,"tags":["dong-tu","giai-tri"],"image":"🎭","examples":[{"type":"basic","zh":"晚会明天彩排。","pinyin":"Wǎnhuì míngtiān cǎipái.","vi":"Ngày mai tổng duyệt chương trình dạ hội."},{"type":"simple","zh":"演员们在礼堂里彩排了整整一下午。","pinyin":"Yǎnyuánmen zài lǐtáng lǐ cǎipáile zhěngzhěng yī xiàwǔ.","vi":"Các diễn viên tổng duyệt trong hội trường suốt cả buổi chiều."},{"type":"compound","zh":"虽然彩排时出了点小错，但是正式演出非常顺利。","pinyin":"Suīrán cǎipái shí chūle diǎn xiǎo cuò, dànshì zhèngshì yǎnchū fēicháng shùnlì.","vi":"Tuy lúc tổng duyệt có chút lỗi nhỏ nhưng buổi diễn chính thức rất suôn sẻ."}],"related":[{"hanzi":"排练","pinyin":"páiliàn","vi":"tập luyện"},{"hanzi":"预演","pinyin":"yùyǎn","vi":"diễn thử"},{"hanzi":"演出","pinyin":"yǎnchū","vi":"biểu diễn"},{"hanzi":"晚会","pinyin":"wǎnhuì","vi":"dạ hội"}]},{"id":"惨痛","hanzi":"惨痛","pinyin":"cǎntòng","meaning_vi":"đau xót, thảm khốc (bài học xương máu)","explanation":"惨 (thảm – thê thảm) + 痛 (thống – đau) → đau đớn thê thảm, đau xót. Cụm: 惨痛的教训 (bài học xương máu), 惨痛的代价.","hsk_level":6,"tags":["tinh-tu"],"image":"😢","examples":[{"type":"basic","zh":"这是惨痛的教训。","pinyin":"Zhè shì cǎntòng de jiàoxùn.","vi":"Đây là bài học xương máu."},{"type":"simple","zh":"那次投资失败给他留下了惨痛的回忆。","pinyin":"Nà cì tóuzī shībài gěi tā liúxiàle cǎntòng de huíyì.","vi":"Lần đầu tư thất bại đó đã để lại cho anh ấy ký ức đau xót."},{"type":"compound","zh":"只有记住这次惨痛的经历，我们才不会重蹈覆辙。","pinyin":"Zhǐyǒu jìzhù zhè cì cǎntòng de jīnglì, wǒmen cái bú huì chóngdǎofùzhé.","vi":"Chỉ khi ghi nhớ trải nghiệm đau xót lần này, chúng ta mới không lặp lại sai lầm cũ."}],"related":[{"hanzi":"沉痛","pinyin":"chéntòng","vi":"đau đớn"},{"hanzi":"惨痛教训","pinyin":"cǎntòngjiàoxùn","vi":"bài học xương máu"},{"hanzi":"悲惨","pinyin":"bēicǎn","vi":"bi thảm"},{"hanzi":"痛苦","pinyin":"tòngkǔ","vi":"đau khổ"}],"traditional":"慘痛"},{"id":"惨重","hanzi":"惨重","pinyin":"cǎnzhòng","meaning_vi":"nặng nề, thảm khốc (tổn thất/thương vong)","explanation":"惨 (thảm) + 重 (nặng).","hsk_level":6,"tags":["tinh-tu"],"image":"📉","examples":[{"type":"basic","zh":"损失十分惨重。","pinyin":"Sǔnshī shífēn cǎnzhòng.","vi":"Tổn thất vô cùng nặng nề."},{"type":"simple","zh":"地震给这个小镇造成了惨重的伤亡。","pinyin":"Dìzhèn gěi zhè gè xiǎozhèn zào chéngle cǎnzhòng de shāngwáng.","vi":"Trận động đất đã gây thương vong nặng nề cho thị trấn nhỏ này."},{"type":"compound","zh":"因为没有及时撤离，所以这次洪水的损失格外惨重。","pinyin":"Yīnwèi méiyǒu jíshí chèlí, suǒyǐ zhè cì hóngshuǐ de sǔnshī géwài cǎnzhòng.","vi":"Vì không sơ tán kịp thời nên tổn thất trong trận lũ lần này đặc biệt nặng nề."}],"related":[{"hanzi":"严重","pinyin":"yánzhòng","vi":"nghiêm trọng"},{"hanzi":"伤亡惨重","pinyin":"shāngwángcǎnzhòng","vi":"thương vong nặng nề"},{"hanzi":"损失","pinyin":"sǔnshī","vi":"tổn thất"},{"hanzi":"轻微","pinyin":"qīngwēi","vi":"nhẹ"}],"traditional":"慘重"},{"id":"草木皆兵","hanzi":"草木皆兵","pinyin":"cǎomù-jiēbīng","meaning_vi":"cây cỏ đều là quân địch (hoang mang sợ hãi quá mức)","explanation":"草木皆兵: cây cỏ đều tưởng là quân lính (Phù Kiên thua trận Phì Thủy, nhìn cây cỏ trên núi tưởng quân Tấn) → ví hoảng sợ, nghi thần nghi quỷ quá mức.","hsk_level":6,"tags":["thanh-ngu"],"image":"😨","examples":[{"type":"basic","zh":"他吓得草木皆兵。","pinyin":"Tā xià de cǎomùjiēbīng.","vi":"Anh ta sợ đến mức thấy gì cũng tưởng là địch."},{"type":"simple","zh":"那段时间股民们个个草木皆兵。","pinyin":"Nà duàn shíjiān gǔmínmen gègè cǎomùjiēbīng.","vi":"Thời gian đó, nhà đầu tư chứng khoán ai nấy đều hoảng sợ quá mức."},{"type":"compound","zh":"自从家里被盗以后，她就变得草木皆兵，一有动静就开灯。","pinyin":"Zìcóng jiālǐ bèi dào yǐhòu, tā jiù biànde cǎomùjiēbīng, yì yǒu dòngjìng jiù kāidēng.","vi":"Từ khi nhà bị trộm, cô ấy trở nên hoảng hốt quá mức, hễ có tiếng động là bật đèn."}],"related":[{"hanzi":"风声鹤唳","pinyin":"fēngshēnghèlì","vi":"nghe gió thổi hạc kêu cũng sợ"},{"hanzi":"惊弓之鸟","pinyin":"jīnggōngzhīniǎo","vi":"chim sợ cành cong"},{"hanzi":"疑神疑鬼","pinyin":"yíshényíguǐ","vi":"nghi thần nghi quỷ"},{"hanzi":"惊慌","pinyin":"jīnghuāng","vi":"hoảng sợ"}]},{"id":"此起彼伏","hanzi":"此起彼伏","pinyin":"cǐqǐ-bǐfú","meaning_vi":"chỗ này nổi lên chỗ kia lắng xuống (liên tiếp)","explanation":"此起彼伏: chỗ này nổi lên, chỗ kia lắng xuống → liên tiếp không dứt, nối nhau vang lên. Ví dụ: 掌声此起彼伏.","hsk_level":6,"tags":["thanh-ngu"],"image":"🌊","examples":[{"type":"basic","zh":"掌声此起彼伏。","pinyin":"Zhǎngshēng cǐqǐbǐfú.","vi":"Tiếng vỗ tay vang lên liên tiếp không ngớt."},{"type":"simple","zh":"夏夜的池塘边蛙声此起彼伏。","pinyin":"Xià yè de chítáng biān wā shēng cǐqǐbǐfú.","vi":"Bên ao đêm hè, tiếng ếch kêu nối tiếp nhau không dứt."},{"type":"compound","zh":"球员一进球，看台上的欢呼声就此起彼伏。","pinyin":"Qiúyuán yí jìnqiú, kàntái shàng de huān hūshēng jiù cǐqǐbǐfú.","vi":"Cầu thủ vừa ghi bàn, tiếng hò reo trên khán đài liền vang lên liên tiếp."}],"related":[{"hanzi":"接连不断","pinyin":"jiēliánbúduàn","vi":"liên tiếp không ngừng"},{"hanzi":"连绵不断","pinyin":"liánmiánbúduàn","vi":"liên miên"},{"hanzi":"此起彼落","pinyin":"cǐqǐbǐluò","vi":"chỗ này nổi chỗ kia chìm"},{"hanzi":"起伏","pinyin":"qǐfú","vi":"nhấp nhô"}]},{"id":"垫","hanzi":"垫","pinyin":"diàn","meaning_vi":"lót, đệm","explanation":"垫 (điếm): lót, đệm ở dưới; cũng là ứng tiền trước. Từ ghép: 垫子 (cái đệm), 鞋垫 (lót giày), 垫钱 (ứng tiền trả hộ).","hsk_level":6,"tags":["dong-tu"],"image":"🛋️","examples":[{"type":"basic","zh":"把书垫在下面。","pinyin":"Bǎ shū diàn zài xiàmiàn.","vi":"Lót cuốn sách xuống dưới."},{"type":"simple","zh":"她在椅子上垫了一个软软的坐垫。","pinyin":"Tā zài yǐzi shàng diànle yí gè ruǎn ruǎn de zuòdiàn.","vi":"Cô ấy lót một chiếc đệm ngồi mềm mại lên ghế."},{"type":"compound","zh":"桌子腿不太稳，所以我垫了一张纸板。","pinyin":"Zhuōzi tuǐ bú tài wěn, suǒyǐ wǒ diànle yì zhāng zhǐbǎn.","vi":"Chân bàn không vững lắm nên tôi đã chêm một tấm bìa giấy."}],"related":[{"hanzi":"垫子","pinyin":"diànzi","vi":"tấm đệm"},{"hanzi":"鞋垫","pinyin":"xiédiàn","vi":"lót giày"},{"hanzi":"坐垫","pinyin":"zuòdiàn","vi":"đệm ngồi"},{"hanzi":"垫付","pinyin":"diànfù","vi":"trả trước hộ"}],"traditional":"墊"},{"id":"吊","hanzi":"吊","pinyin":"diào","meaning_vi":"treo lên, cẩu lên","explanation":"吊 (điếu): treo, treo lên; kéo lên bằng dây/cần cẩu; còn nghĩa viếng người chết. Từ ghép: 吊车 (cần cẩu), 吊灯 (đèn treo), 吊唁 (phúng viếng).","hsk_level":6,"tags":["dong-tu"],"image":"🏗️","examples":[{"type":"basic","zh":"灯吊在屋顶上。","pinyin":"Dēng diào zài wūdǐng shàng.","vi":"Đèn được treo trên trần nhà."},{"type":"simple","zh":"工人用起重机把钢梁吊上了楼顶。","pinyin":"Gōngrén yòng qǐzhòngjī bǎ gāngliáng diào shàngle lóudǐng.","vi":"Công nhân dùng cần cẩu cẩu dầm thép lên nóc tòa nhà."},{"type":"compound","zh":"只要把篮子吊在高处，猫就够不着里面的鱼了。","pinyin":"Zhǐyào bǎ lánzi diào zài gāochù, māo jiù gòubùzháo lǐmiàn de yú le.","vi":"Chỉ cần treo giỏ lên cao là mèo không với tới cá bên trong nữa."}],"related":[{"hanzi":"吊车","pinyin":"diàochē","vi":"xe cẩu"},{"hanzi":"挂","pinyin":"guà","vi":"treo"},{"hanzi":"吊灯","pinyin":"diàodēng","vi":"đèn chùm"},{"hanzi":"上吊","pinyin":"shàngdiào","vi":"treo cổ"}]},{"id":"调兵遣将","hanzi":"调兵遣将","pinyin":"diàobīng-qiǎnjiàng","meaning_vi":"điều binh khiển tướng","explanation":"调兵 (điều binh – điều động quân) + 遣将 (khiển tướng – sai phái tướng) → điều động binh lính, bố trí nhân lực; nghĩa bóng: sắp xếp, huy động người cho một việc.","hsk_level":6,"tags":["thanh-ngu"],"image":"♟️","examples":[{"type":"basic","zh":"将军连夜调兵遣将。","pinyin":"Jiāngjūn liányè diàobīngqiǎnjiàng.","vi":"Tướng quân điều binh khiển tướng suốt đêm."},{"type":"simple","zh":"经理为新项目四处调兵遣将。","pinyin":"Jīnglǐ wèi xīn xiàngmù sìchù diàobīngqiǎnjiàng.","vi":"Giám đốc điều động nhân sự khắp nơi cho dự án mới."},{"type":"compound","zh":"一听说敌军逼近，元帅就立刻调兵遣将准备迎战。","pinyin":"Yì tīngshuō díjūn bījìn, yuánshuài jiù lìkè diàobīngqiǎnjiàng zhǔnbèi yíngzhàn.","vi":"Vừa nghe tin quân địch áp sát, nguyên soái lập tức điều binh khiển tướng chuẩn bị nghênh chiến."}],"related":[{"hanzi":"调动","pinyin":"diàodòng","vi":"điều động"},{"hanzi":"部署","pinyin":"bùshǔ","vi":"bố trí"},{"hanzi":"指挥","pinyin":"zhǐhuī","vi":"chỉ huy"},{"hanzi":"兵力","pinyin":"bīnglì","vi":"binh lực"}],"traditional":"調兵遣將"},{"id":"掉以轻心","hanzi":"掉以轻心","pinyin":"diàoyǐ-qīngxīn","meaning_vi":"coi thường, chủ quan mất cảnh giác","explanation":"掉 (trạo – vẫy, buông) + 以 (lấy) + 轻心 (khinh tâm – lòng xem nhẹ) → xem nhẹ, chủ quan, lơ là cảnh giác. Thường dùng phủ định: 不可掉以轻心.","hsk_level":6,"tags":["thanh-ngu"],"image":"⚠️","examples":[{"type":"basic","zh":"千万别掉以轻心。","pinyin":"Qiānwàn bié diàoyǐqīngxīn.","vi":"Tuyệt đối đừng chủ quan."},{"type":"simple","zh":"教练提醒队员面对弱队不可掉以轻心。","pinyin":"Jiàoliàn tíxǐng duìyuán miànduì ruò duì bùkě diàoyǐqīngxīn.","vi":"Huấn luyện viên nhắc nhở các cầu thủ không được chủ quan khi gặp đội yếu."},{"type":"compound","zh":"虽然病情好转了，但是你也不能掉以轻心。","pinyin":"Suīrán bìngqíng hǎozhuǎn le, dànshì nǐ yě bù néng diàoyǐqīngxīn.","vi":"Tuy bệnh tình đã thuyên giảm nhưng bạn cũng không được lơ là."}],"related":[{"hanzi":"粗心大意","pinyin":"cūxīndàyì","vi":"bất cẩn"},{"hanzi":"麻痹大意","pinyin":"mábìdàyì","vi":"lơ là chủ quan"},{"hanzi":"轻视","pinyin":"qīngshì","vi":"xem nhẹ"},{"hanzi":"谨小慎微","pinyin":"jǐnxiǎoshènwēi","vi":"thận trọng từng li"}],"traditional":"掉以輕心"},{"id":"颠倒黑白","hanzi":"颠倒黑白","pinyin":"diāndǎo-hēibái","meaning_vi":"đổi trắng thay đen, bóp méo sự thật","explanation":"颠倒 (điên đảo – đảo ngược) + 黑白 (hắc bạch – đen trắng) → nói đen thành trắng, trắng thành đen → cố ý bóp méo sự thật, đổi trắng thay đen.","hsk_level":6,"tags":["thanh-ngu"],"image":"🤥","examples":[{"type":"basic","zh":"你别颠倒黑白！","pinyin":"Nǐ bié diāndǎohēibái!","vi":"Anh đừng đổi trắng thay đen!"},{"type":"simple","zh":"那篇报道故意颠倒黑白误导读者。","pinyin":"Nà piān bàodào gùyì diāndǎohēibái wùdǎo dúzhě.","vi":"Bài báo đó cố ý bóp méo sự thật để đánh lừa độc giả."},{"type":"compound","zh":"他不但不认错，反而颠倒黑白说是我先动的手。","pinyin":"Tā búdàn bú rèncuò, fǎn'ér diāndǎohēibái shuō shì wǒ xiān dòng de shǒu.","vi":"Anh ta không những không nhận lỗi mà còn đổi trắng thay đen nói là tôi ra tay trước."}],"related":[{"hanzi":"混淆是非","pinyin":"hùnxiáoshìfēi","vi":"lẫn lộn phải trái"},{"hanzi":"指鹿为马","pinyin":"zhǐlùwéimǎ","vi":"chỉ hươu bảo ngựa"},{"hanzi":"歪曲事实","pinyin":"wāiqūshìshí","vi":"xuyên tạc sự thật"},{"hanzi":"实事求是","pinyin":"shíshìqiúshì","vi":"thực sự cầu thị"}],"traditional":"顛倒黑白"},{"id":"颠覆","hanzi":"颠覆","pinyin":"diānfù","meaning_vi":"lật đổ, đảo lộn","explanation":"颠 + 覆 (lật úp).","hsk_level":6,"tags":["dong-tu"],"image":"🔄","examples":[{"type":"basic","zh":"政权被颠覆了。","pinyin":"Zhèngquán bèi diānfù le.","vi":"Chính quyền đã bị lật đổ."},{"type":"simple","zh":"智能手机颠覆了人们的购物习惯。","pinyin":"Zhìnéng shǒujī diānfùle rénmen de gòuwù xíguàn.","vi":"Điện thoại thông minh đã đảo lộn thói quen mua sắm của mọi người."},{"type":"compound","zh":"这项发现如果被证实，就会颠覆传统的理论。","pinyin":"Zhè xiàng fāxiàn rúguǒ bèi zhèngshí, jiù huì diānfù chuántǒng de lǐlùn.","vi":"Phát hiện này nếu được chứng thực sẽ lật đổ lý thuyết truyền thống."}],"related":[{"hanzi":"推翻","pinyin":"tuīfān","vi":"lật đổ"},{"hanzi":"颠覆性","pinyin":"diānfùxìng","vi":"tính đột phá, lật đổ"},{"hanzi":"倾覆","pinyin":"qīngfù","vi":"lật úp"},{"hanzi":"颠倒","pinyin":"diāndǎo","vi":"đảo ngược"}],"traditional":"顛覆"},{"id":"叼","hanzi":"叼","pinyin":"diāo","meaning_vi":"ngậm trong miệng","explanation":"叼 (điêu): ngậm, cắp bằng miệng (không dùng tay). Ví dụ: 叼着烟 (ngậm điếu thuốc), 狗叼骨头 (chó ngậm xương).","hsk_level":6,"tags":["dong-tu"],"image":"🐕","examples":[{"type":"basic","zh":"猫叼着一条鱼。","pinyin":"Māo diāozhe yì tiáo yú.","vi":"Con mèo ngậm một con cá."},{"type":"simple","zh":"爷爷叼着烟斗坐在门口晒太阳。","pinyin":"Yéye diāozhe yāndǒu zuò zài ménkǒu shàitàiyáng.","vi":"Ông nội ngậm tẩu thuốc ngồi trước cửa phơi nắng."},{"type":"compound","zh":"我刚把球扔出去，小狗就把它叼了回来。","pinyin":"Wǒ gāng bǎ qiú rēng chūqù, xiǎogǒu jiù bǎ tā diāole huílái.","vi":"Tôi vừa ném quả bóng đi, chú chó nhỏ đã ngậm nó mang về."}],"related":[{"hanzi":"衔","pinyin":"xián","vi":"ngậm"},{"hanzi":"咬","pinyin":"yǎo","vi":"cắn"},{"hanzi":"叼烟","pinyin":"diāoyān","vi":"ngậm điếu thuốc"},{"hanzi":"嘴","pinyin":"zuǐ","vi":"miệng"}]},{"id":"雕虫小技","hanzi":"雕虫小技","pinyin":"diāochóng-xiǎojì","meaning_vi":"tài mọn, kỹ năng nhỏ nhặt (cách nói khiêm tốn)","explanation":"雕虫 (điêu trùng – khắc hình sâu bọ, lối viết chữ trùng thư tỉ mỉ) + 小技 (tiểu kỹ – tài vặt) → tài mọn, kỹ năng nhỏ không đáng kể; hay dùng để khiêm tốn.","hsk_level":6,"tags":["thanh-ngu"],"image":"🐛","examples":[{"type":"basic","zh":"这不过是雕虫小技。","pinyin":"Zhè búguò shì diāochóngxiǎojì.","vi":"Đây chẳng qua chỉ là tài mọn."},{"type":"simple","zh":"他把折纸当作不值一提的雕虫小技。","pinyin":"Tā bǎ zhézhǐ dàngzuò bùzhí yì tí de diāochóngxiǎojì.","vi":"Anh ấy coi việc gấp giấy là tài mọn không đáng nhắc tới."},{"type":"compound","zh":"虽然这只是雕虫小技，但是在关键时刻帮了大忙。","pinyin":"Suīrán zhè zhǐshì diāochóngxiǎojì, dànshì zài guānjiànshíkè bāngle dà máng.","vi":"Tuy đây chỉ là tài mọn nhưng vào lúc then chốt lại giúp được việc lớn."}],"related":[{"hanzi":"微不足道","pinyin":"wēibùzúdào","vi":"nhỏ nhặt không đáng kể"},{"hanzi":"小技","pinyin":"xiǎojì","vi":"mẹo vặt"},{"hanzi":"才疏学浅","pinyin":"cáishūxuéqiǎn","vi":"tài hèn học kém"},{"hanzi":"雄才大略","pinyin":"xióngcáidàlüè","vi":"tài cao lược lớn"}],"traditional":"雕蟲小技"},{"id":"跌宕起伏","hanzi":"跌宕起伏","pinyin":"diēdàng-qǐfú","meaning_vi":"thăng trầm lên xuống (cốt truyện/âm nhạc/cuộc đời)","explanation":"跌宕 (điệt đãng – lên xuống phóng khoáng) + 起伏 (khởi phục – nhô lên hạ xuống) → biến hóa thăng trầm, nhiều cao trào. Thường tả cốt truyện, âm nhạc, cuộc đời.","hsk_level":6,"tags":["thanh-ngu"],"image":"〰️","examples":[{"type":"basic","zh":"剧情跌宕起伏。","pinyin":"Jùqíng diēdàngqǐfú.","vi":"Tình tiết phim lên xuống thăng trầm."},{"type":"simple","zh":"这位作家的一生可谓跌宕起伏。","pinyin":"Zhè wèi zuòjiā de yìshēng kěwèi diēdàngqǐfú.","vi":"Cuộc đời nhà văn này có thể nói là đầy thăng trầm."},{"type":"compound","zh":"因为比分跌宕起伏，所以观众一直紧张得不敢眨眼。","pinyin":"Yīnwèi bǐfēn diēdàngqǐfú, suǒyǐ guānzhòng yìzhí jǐnzhāng de bù gǎn zhǎyǎn.","vi":"Vì tỉ số lên xuống liên tục nên khán giả căng thẳng đến mức không dám chớp mắt."}],"related":[{"hanzi":"起伏","pinyin":"qǐfú","vi":"lên xuống"},{"hanzi":"波澜起伏","pinyin":"bōlánqǐfú","vi":"sóng gió nhấp nhô"},{"hanzi":"曲折","pinyin":"qūzhé","vi":"quanh co"},{"hanzi":"平淡无奇","pinyin":"píngdànwúqí","vi":"bình thường nhạt nhẽo"}]},{"id":"丢盔弃甲","hanzi":"丢盔弃甲","pinyin":"diūkuī-qìjiǎ","meaning_vi":"vứt mũ bỏ giáp (thua chạy tán loạn)","explanation":"丢盔 (vứt mũ trụ) + 弃甲 (khí giáp – bỏ áo giáp) → quân lính vứt bỏ khí giới mà chạy → ví thua trận thảm hại, tháo chạy tán loạn.","hsk_level":6,"tags":["thanh-ngu"],"image":"🏃","examples":[{"type":"basic","zh":"敌军丢盔弃甲。","pinyin":"Díjūn diūkuīqìjiǎ.","vi":"Quân địch vứt mũ bỏ giáp tháo chạy."},{"type":"simple","zh":"客队在下半场被打得丢盔弃甲。","pinyin":"Kèduì zài xiàbànchǎng bèi dǎ de diūkuīqìjiǎ.","vi":"Đội khách bị đánh cho tan tác trong hiệp hai."},{"type":"compound","zh":"我军一发起冲锋，敌人就丢盔弃甲地逃跑了。","pinyin":"Wǒ jūn yì fāqǐ chōngfēng, dírén jiù diūkuīqìjiǎ de táopǎo le.","vi":"Quân ta vừa phát động xung phong, quân địch liền vứt mũ bỏ giáp tháo chạy."}],"related":[{"hanzi":"溃不成军","pinyin":"kuìbùchéngjūn","vi":"tan tác không thành quân"},{"hanzi":"落荒而逃","pinyin":"luòhuāng'értáo","vi":"bỏ chạy tán loạn"},{"hanzi":"狼狈","pinyin":"lángbèi","vi":"thảm hại"},{"hanzi":"凯旋","pinyin":"kǎixuán","vi":"khải hoàn"}],"traditional":"丟盔棄甲"},{"id":"典故","hanzi":"典故","pinyin":"diǎngù","meaning_vi":"điển cố, điển tích","explanation":"典 (sách cổ) + 故 (chuyện xưa).","hsk_level":6,"tags":["danh-tu","van-hoa","hoc-tap"],"image":"📜","examples":[{"type":"basic","zh":"这个典故很有名。","pinyin":"Zhè gè diǎngù hěn yǒumíng.","vi":"Điển cố này rất nổi tiếng."},{"type":"simple","zh":"老师给我们讲了卧薪尝胆的典故。","pinyin":"Lǎoshī gěi wǒmen jiǎngle wòxīnchángdǎn de diǎngù.","vi":"Thầy giáo kể cho chúng tôi nghe điển cố \"nằm gai nếm mật\"."},{"type":"compound","zh":"如果不了解其中的典故，就很难读懂这首古诗。","pinyin":"Rúguǒ bù liǎojiě qízhōng de diǎngù, jiù hěn nán dúdǒng zhè shǒu gǔshī.","vi":"Nếu không hiểu điển cố trong đó thì rất khó đọc hiểu bài thơ cổ này."}],"related":[{"hanzi":"典籍","pinyin":"diǎnjí","vi":"điển tịch"},{"hanzi":"成语","pinyin":"chéngyǔ","vi":"thành ngữ"},{"hanzi":"故事","pinyin":"gùshi","vi":"câu chuyện"},{"hanzi":"出处","pinyin":"chūchù","vi":"xuất xứ"}]},{"id":"典礼","hanzi":"典礼","pinyin":"diǎnlǐ","meaning_vi":"buổi lễ, nghi lễ","explanation":"典 (điển – nghi thức trang trọng) + 礼 (lễ) → buổi lễ long trọng. Thường gặp: 毕业典礼 (lễ tốt nghiệp), 开幕典礼 (lễ khai mạc), 结婚典礼.","hsk_level":6,"tags":["danh-tu","van-hoa"],"image":"🎓","examples":[{"type":"basic","zh":"典礼九点开始。","pinyin":"Diǎnlǐ jiǔ diǎn kāishǐ.","vi":"Buổi lễ bắt đầu lúc chín giờ."},{"type":"simple","zh":"全校师生参加了隆重的毕业典礼。","pinyin":"Quán xiào shīshēng cānjiāle lóngzhòng de bìyè diǎnlǐ.","vi":"Toàn thể thầy trò đã tham dự lễ tốt nghiệp long trọng."},{"type":"compound","zh":"典礼一结束，新郎新娘就去花园里拍照了。","pinyin":"Diǎnlǐ yì jiéshù, xīnláng xīnniáng jiù qù huāyuán lǐ pāizhào le.","vi":"Buổi lễ vừa kết thúc, cô dâu chú rể liền ra vườn hoa chụp ảnh."}],"related":[{"hanzi":"仪式","pinyin":"yíshì","vi":"nghi thức"},{"hanzi":"开学典礼","pinyin":"kāixuédiǎnlǐ","vi":"lễ khai giảng"},{"hanzi":"毕业典礼","pinyin":"bìyèdiǎnlǐ","vi":"lễ tốt nghiệp"},{"hanzi":"庆典","pinyin":"qìngdiǎn","vi":"lễ mừng"}],"traditional":"典禮"},{"id":"点石成金","hanzi":"点石成金","pinyin":"diǎnshí-chéngjīn","meaning_vi":"chạm đá thành vàng (biến cái bình thường thành tuyệt tác)","explanation":"点石成金: tiên nhân chạm ngón tay vào đá biến thành vàng (truyện thần tiên) → ví sửa chữa, nâng cấp cái tầm thường thành cái quý giá, thường nói về văn chương.","hsk_level":6,"tags":["thanh-ngu"],"image":"✨","examples":[{"type":"basic","zh":"他能点石成金。","pinyin":"Tā néng diǎnshíchéngjīn.","vi":"Anh ấy có thể chạm đá hóa vàng."},{"type":"simple","zh":"这位编辑有点石成金的本领。","pinyin":"Zhè wèi biānjí yǒu diǎnshíchéngjīn de běnlǐng.","vi":"Vị biên tập viên này có bản lĩnh biến đá thành vàng."},{"type":"compound","zh":"虽然原稿很普通，但是经过他点石成金的修改，变成了一篇佳作。","pinyin":"Suīrán yuángǎo hěn pǔtōng, dànshì jīngguò tā diǎnshíchéngjīn de xiūgǎi, biàn chéngle yì piān jiāzuò.","vi":"Tuy bản thảo gốc rất bình thường, nhưng qua sự chỉnh sửa như chạm đá hóa vàng của anh ấy, nó đã trở thành một tác phẩm hay."}],"related":[{"hanzi":"化腐朽为神奇","pinyin":"huà fǔxiǔ wéi shénqí","vi":"biến mục nát thành thần kỳ"},{"hanzi":"画龙点睛","pinyin":"huàlóngdiǎnjīng","vi":"vẽ rồng điểm mắt"},{"hanzi":"妙笔生花","pinyin":"miàobǐshēnghuā","vi":"ngòi bút tài hoa"},{"hanzi":"点金术","pinyin":"diǎnjīnshù","vi":"thuật hóa vàng"}],"traditional":"點石成金"},{"id":"断绝","hanzi":"断绝","pinyin":"duànjué","meaning_vi":"đoạn tuyệt, cắt đứt","explanation":"断 (đoạn – cắt) + 绝 (tuyệt – dứt hẳn) → cắt đứt hoàn toàn. Thường đi với 断绝关系, 断绝往来, 断绝联系.","hsk_level":6,"tags":["dong-tu"],"image":"✂️","examples":[{"type":"basic","zh":"两国断绝了往来。","pinyin":"Liǎngguó duànjuéle wǎnglái.","vi":"Hai nước đã cắt đứt qua lại."},{"type":"simple","zh":"大雪断绝了山村与外界的联系。","pinyin":"Dàxuě duànjuéle shāncūn yǔ wàijiè de liánxì.","vi":"Tuyết lớn đã cắt đứt liên lạc giữa làng núi và bên ngoài."},{"type":"compound","zh":"即使父亲反对这门婚事，她也不愿和家人断绝关系。","pinyin":"Jíshǐ fùqīn fǎnduì zhè mén hūnshì, tā yě búyuàn hé jiārén duànjué guānxì.","vi":"Cho dù cha phản đối cuộc hôn nhân này, cô ấy cũng không muốn cắt đứt quan hệ với gia đình."}],"related":[{"hanzi":"中断","pinyin":"zhōngduàn","vi":"gián đoạn"},{"hanzi":"绝交","pinyin":"juéjiāo","vi":"tuyệt giao"},{"hanzi":"切断","pinyin":"qiēduàn","vi":"cắt đứt"},{"hanzi":"保持","pinyin":"bǎochí","vi":"duy trì"}],"traditional":"斷絕"},{"id":"断章取义","hanzi":"断章取义","pinyin":"duànzhāng-qǔyì","meaning_vi":"cắt xén câu chữ hiểu sai ý toàn bài","explanation":"断章 (cắt đoạn văn) + 取义 (lấy nghĩa) → trích một đoạn ra khỏi ngữ cảnh rồi hiểu theo ý mình → xuyên tạc, hiểu sai ý của cả bài/lời nói.","hsk_level":6,"tags":["thanh-ngu","ngon-ngu"],"image":"✂️","examples":[{"type":"basic","zh":"不要断章取义。","pinyin":"Bú yào duànzhāngqǔyì.","vi":"Đừng cắt xén câu chữ mà hiểu sai ý."},{"type":"simple","zh":"有些媒体断章取义地引用了他的发言。","pinyin":"Yǒuxiē méitǐ duànzhāngqǔyì de yǐnyòngle tā de fāyán.","vi":"Một số phương tiện truyền thông đã trích dẫn phát biểu của ông ấy một cách cắt xén."},{"type":"compound","zh":"与其断章取义地批评，不如先把全文认真读完。","pinyin":"Yǔqí duànzhāngqǔyì de pīpíng, bùrú xiān bǎ quánwén rènzhēn dú wán.","vi":"Thay vì cắt xén câu chữ để phê phán, chi bằng hãy đọc kỹ toàn bài trước đã."}],"related":[{"hanzi":"歪曲","pinyin":"wāiqū","vi":"xuyên tạc"},{"hanzi":"片面","pinyin":"piànmiàn","vi":"phiến diện"},{"hanzi":"曲解","pinyin":"qūjiě","vi":"hiểu sai"},{"hanzi":"以偏概全","pinyin":"yǐpiāngàiquán","vi":"lấy một phần khái quát toàn bộ"}],"traditional":"斷章取義"},{"id":"对称","hanzi":"对称","pinyin":"duìchèn","meaning_vi":"đối xứng","explanation":"对 (đối – đối nhau) + 称 (xứng – cân xứng, đọc chèn) → hai bên cân xứng nhau, đối xứng. Ví dụ: 左右对称, 对称图形. Chú ý 称 ở đây đọc chèn.","hsk_level":6,"tags":["tinh-tu"],"image":"⚖️","examples":[{"type":"basic","zh":"这座楼很对称。","pinyin":"Zhè zuò lóu hěn duìchèn.","vi":"Tòa nhà này rất đối xứng."},{"type":"simple","zh":"故宫的建筑布局左右对称。","pinyin":"Gùgōng de jiànzhù bùjú zuǒyòu duìchèn.","vi":"Bố cục kiến trúc của Cố Cung đối xứng hai bên."},{"type":"compound","zh":"蝴蝶的翅膀不但颜色鲜艳，而且图案完全对称。","pinyin":"Húdié de chìbǎng búdàn yánsè xiānyàn, érqiě tú'àn wánquán duìchèn.","vi":"Cánh bướm không những màu sắc tươi tắn mà hoa văn còn đối xứng hoàn toàn."}],"related":[{"hanzi":"对称性","pinyin":"duìchènxìng","vi":"tính đối xứng"},{"hanzi":"平衡","pinyin":"pínghéng","vi":"cân bằng"},{"hanzi":"不对称","pinyin":"búduìchèn","vi":"bất đối xứng"},{"hanzi":"均匀","pinyin":"jūnyún","vi":"đều đặn"}],"traditional":"對稱"},{"id":"对立","hanzi":"对立","pinyin":"duìlì","meaning_vi":"đối lập","explanation":"对 (đối – đối diện) + 立 (lập – đứng) → đứng đối diện nhau, mâu thuẫn trái ngược. Thường gặp: 对立面 (mặt đối lập), 对立统一, 互相对立.","hsk_level":6,"tags":["dong-tu"],"image":"↔️","examples":[{"type":"basic","zh":"双方观点对立。","pinyin":"Shuāngfāng guāndiǎn duìlì.","vi":"Quan điểm hai bên đối lập nhau."},{"type":"simple","zh":"婆媳俩因为装修问题对立起来了。","pinyin":"Póxí liǎ yīnwèi zhuāngxiū wèntí duìlì qǐlái le.","vi":"Mẹ chồng nàng dâu vì chuyện sửa nhà mà trở nên đối lập nhau."},{"type":"compound","zh":"虽然我们的立场对立，但是可以坐下来好好谈。","pinyin":"Suīrán wǒmen de lìchǎng duìlì, dànshì kěyǐ zuò xiàlái hǎohǎo tán.","vi":"Tuy lập trường chúng ta đối lập nhưng vẫn có thể ngồi xuống nói chuyện đàng hoàng."}],"related":[{"hanzi":"对抗","pinyin":"duìkàng","vi":"đối kháng"},{"hanzi":"矛盾","pinyin":"máodùn","vi":"mâu thuẫn"},{"hanzi":"对立面","pinyin":"duìlìmiàn","vi":"mặt đối lập"},{"hanzi":"统一","pinyin":"tǒngyī","vi":"thống nhất"}],"traditional":"對立"},{"id":"对牛弹琴","hanzi":"对牛弹琴","pinyin":"duìniú-tánqín","meaning_vi":"đàn gảy tai trâu","explanation":"对牛弹琴: gảy đàn cho trâu nghe (Công Minh Nghi đàn cho trâu, trâu vẫn cúi đầu ăn cỏ) → nói chuyện với người không hiểu; cũng chê người nói không đúng đối tượng.","hsk_level":6,"tags":["thanh-ngu"],"image":"🐄","examples":[{"type":"basic","zh":"别对牛弹琴了。","pinyin":"Bié duìniútánqín le.","vi":"Đừng đàn gảy tai trâu nữa."},{"type":"simple","zh":"跟他讲艺术简直是对牛弹琴。","pinyin":"Gēn tā jiǎng yìshù jiǎnzhí shì duìniútánqín.","vi":"Nói chuyện nghệ thuật với anh ta đúng là đàn gảy tai trâu."},{"type":"compound","zh":"既然他根本不想听，你再解释也是对牛弹琴。","pinyin":"Jìrán tā gēnběnbù xiǎng tīng, nǐ zài jiěshì yě shì duìniútánqín.","vi":"Đã là anh ta hoàn toàn không muốn nghe thì bạn có giải thích nữa cũng chỉ là đàn gảy tai trâu."}],"related":[{"hanzi":"白费口舌","pinyin":"báifèikǒushé","vi":"phí lời"},{"hanzi":"无的放矢","pinyin":"wúdìfàngshǐ","vi":"bắn tên không đích"},{"hanzi":"有的放矢","pinyin":"yǒudìfàngshǐ","vi":"bắn tên có đích"},{"hanzi":"鸡同鸭讲","pinyin":"jītóngyājiǎng","vi":"ông nói gà bà nói vịt"}],"traditional":"對牛彈琴"},{"id":"对照","hanzi":"对照","pinyin":"duìzhào","meaning_vi":"đối chiếu","explanation":"对 (đối – đặt đối nhau) + 照 (chiếu – soi, so) → đặt cạnh nhau để so sánh, đối chiếu. Thường gặp: 对照原文, 中英对照, 对照检查.","hsk_level":6,"tags":["dong-tu"],"image":"🔍","examples":[{"type":"basic","zh":"请对照原文。","pinyin":"Qǐng duìzhào yuánwén.","vi":"Xin hãy đối chiếu với nguyên văn."},{"type":"simple","zh":"他对照说明书一步步组装书架。","pinyin":"Tā duìzhào shuōmíngshū yí bùbù zǔzhuāng shūjià.","vi":"Anh ấy đối chiếu sách hướng dẫn lắp từng bước giá sách."},{"type":"compound","zh":"只要把两份合同对照一下，就能发现哪里被改过。","pinyin":"Zhǐyào bǎ liǎng fèn hétong duìzhào yíxià, jiù néng fāxiàn nǎlǐ bèi gǎiguò.","vi":"Chỉ cần đối chiếu hai bản hợp đồng là có thể phát hiện chỗ nào đã bị sửa."}],"related":[{"hanzi":"对比","pinyin":"duìbǐ","vi":"so sánh"},{"hanzi":"比较","pinyin":"bǐjiào","vi":"so sánh"},{"hanzi":"参照","pinyin":"cānzhào","vi":"tham chiếu"},{"hanzi":"核对","pinyin":"héduì","vi":"đối chiếu kiểm tra"}],"traditional":"對照"},{"id":"对症下药","hanzi":"对症下药","pinyin":"duìzhèng-xiàyào","meaning_vi":"bốc thuốc đúng bệnh (giải quyết đúng nguyên nhân)","explanation":"对症 (đúng triệu chứng) + 下药 (cho thuốc) → bác sĩ kê thuốc đúng bệnh → ví tìm đúng nguyên nhân của vấn đề để giải quyết hiệu quả.","hsk_level":6,"tags":["thanh-ngu","suc-khoe"],"image":"💊","examples":[{"type":"basic","zh":"治病要对症下药。","pinyin":"Zhìbìng yào duìzhèngxiàyào.","vi":"Chữa bệnh phải bốc thuốc đúng bệnh."},{"type":"simple","zh":"医生查明病因后对症下药。","pinyin":"Yīshēng chámíng bìngyīn hòu duìzhèngxiàyào.","vi":"Bác sĩ sau khi tìm rõ nguyên nhân bệnh đã kê thuốc đúng bệnh."},{"type":"compound","zh":"只有找到销量下滑的原因，我们才能对症下药。","pinyin":"Zhǐyǒu zhǎodào xiāoliàng xiàhuá de yuányīn, wǒmen cáinéng duìzhèngxiàyào.","vi":"Chỉ khi tìm ra nguyên nhân doanh số sụt giảm, chúng ta mới có thể giải quyết đúng chỗ."}],"related":[{"hanzi":"因材施教","pinyin":"yīncáishījiào","vi":"dạy theo năng lực"},{"hanzi":"有的放矢","pinyin":"yǒudìfàngshǐ","vi":"bắn tên có đích"},{"hanzi":"症状","pinyin":"zhèngzhuàng","vi":"triệu chứng"},{"hanzi":"治标不治本","pinyin":"zhìbiāo bú zhìběn","vi":"chữa ngọn không chữa gốc"}],"traditional":"對症下藥"},{"id":"端正","hanzi":"端正","pinyin":"duānzhèng","meaning_vi":"ngay ngắn, đứng đắn","explanation":"端 (đoan – ngay ngắn) + 正 (chính – thẳng) → ngay ngắn, đoan chính; cũng dùng làm động từ: sửa cho đúng. Thường đi với 五官端正, 端正态度.","hsk_level":6,"tags":["tinh-tu"],"image":"🧍","examples":[{"type":"basic","zh":"字写得很端正。","pinyin":"Zì xiě de hěn duānzhèng.","vi":"Chữ viết rất ngay ngắn."},{"type":"simple","zh":"学生们端正地坐在座位上听课。","pinyin":"Xuéshengmen duānzhèng de zuò zài zuòwèi shàng tīngkè.","vi":"Học sinh ngồi ngay ngắn tại chỗ nghe giảng."},{"type":"compound","zh":"只要学习态度端正，成绩就会慢慢提高。","pinyin":"Zhǐyào xuéxí tàidù duānzhèng, chéngjì jiù huì mànmàn tígāo.","vi":"Chỉ cần thái độ học tập đứng đắn, thành tích sẽ dần dần nâng cao."}],"related":[{"hanzi":"端端正正","pinyin":"duānduānzhèngzhèng","vi":"ngay ngắn"},{"hanzi":"正直","pinyin":"zhèngzhí","vi":"chính trực"},{"hanzi":"歪斜","pinyin":"wāixié","vi":"xiêu vẹo"},{"hanzi":"端正态度","pinyin":"duānzhèngtàidu","vi":"chấn chỉnh thái độ"}]},{"id":"多才多艺","hanzi":"多才多艺","pinyin":"duōcái-duōyì","meaning_vi":"đa tài đa nghệ","explanation":"多才 (đa tài – nhiều tài) + 多艺 (đa nghệ – nhiều nghề, nhiều kỹ năng) → giỏi nhiều lĩnh vực, có nhiều tài năng. Dùng để khen người.","hsk_level":6,"tags":["thanh-ngu"],"image":"🎭","examples":[{"type":"basic","zh":"她多才多艺。","pinyin":"Tā duōcáiduōyì.","vi":"Cô ấy đa tài đa nghệ."},{"type":"simple","zh":"我们班有一位多才多艺的班长。","pinyin":"Wǒmen bān yǒu yí wèi duōcáiduōyì de bānzhǎng.","vi":"Lớp chúng tôi có một lớp trưởng đa tài đa nghệ."},{"type":"compound","zh":"他不但会弹钢琴，而且擅长书法，真是多才多艺。","pinyin":"Tā búdàn huì tángāngqín, érqiě shàncháng shūfǎ, zhēn shì duōcáiduōyì.","vi":"Anh ấy không những biết chơi piano mà còn giỏi thư pháp, thật là đa tài đa nghệ."}],"related":[{"hanzi":"才华横溢","pinyin":"cáihuáhéngyì","vi":"tài hoa xuất chúng"},{"hanzi":"全能","pinyin":"quánnéng","vi":"toàn năng"},{"hanzi":"博学多才","pinyin":"bóxuéduōcái","vi":"học rộng tài cao"},{"hanzi":"一无所长","pinyin":"yìwúsuǒcháng","vi":"không có sở trường gì"}],"traditional":"多才多藝"},{"id":"咄咄逼人","hanzi":"咄咄逼人","pinyin":"duōduō-bīrén","meaning_vi":"hung hăng lấn lướt người khác","explanation":"咄咄 (đốt đốt – tiếng quát tháo) + 逼人 (bức nhân – ép người) → thái độ, lời lẽ hung hăng lấn át người khác; cũng tả khí thế mạnh khiến người khác áp lực.","hsk_level":6,"tags":["thanh-ngu"],"image":"😤","examples":[{"type":"basic","zh":"他语气咄咄逼人。","pinyin":"Tā yǔqì duōduōbīrén.","vi":"Giọng điệu của anh ta hung hăng lấn lướt."},{"type":"simple","zh":"记者咄咄逼人地追问事故的真相。","pinyin":"Jìzhě duōduōbīrén de zhuīwèn shìgù de zhēnxiàng.","vi":"Phóng viên hung hăng dồn dập truy hỏi sự thật về vụ tai nạn."},{"type":"compound","zh":"虽然对方咄咄逼人，但是她始终保持着冷静。","pinyin":"Suīrán duìfāng duōduōbīrén, dànshì tā shǐzhōng bǎochízhe lěngjìng.","vi":"Tuy đối phương hung hăng lấn lướt nhưng cô ấy trước sau vẫn giữ bình tĩnh."}],"related":[{"hanzi":"盛气凌人","pinyin":"shèngqìlíngrén","vi":"hống hách lấn người"},{"hanzi":"气势汹汹","pinyin":"qìshìxiōngxiōng","vi":"hùng hổ"},{"hanzi":"和蔼可亲","pinyin":"hé'ǎikěqīn","vi":"hiền hòa dễ gần"},{"hanzi":"强势","pinyin":"qiángshì","vi":"mạnh mẽ áp đảo"}]},{"id":"多多益善","hanzi":"多多益善","pinyin":"duōduō-yìshàn","meaning_vi":"càng nhiều càng tốt","explanation":"多多益善: càng nhiều càng tốt (Hàn Tín nói với Lưu Bang mình cầm quân thì càng nhiều càng giỏi) → nay dùng chung cho mọi thứ: càng nhiều càng hay.","hsk_level":6,"tags":["thanh-ngu"],"image":"➕","examples":[{"type":"basic","zh":"钱当然多多益善。","pinyin":"Qián dāngrán duōduōyìshàn.","vi":"Tiền thì đương nhiên càng nhiều càng tốt."},{"type":"simple","zh":"志愿者人数对这次活动来说多多益善。","pinyin":"Zhìyuànzhě rénshù duì zhè cì huódòng lái shuō duōduōyìshàn.","vi":"Đối với hoạt động lần này, số tình nguyện viên càng nhiều càng tốt."},{"type":"compound","zh":"意见不怕多，只要有道理就多多益善。","pinyin":"Yìjiàn bú pà duō, zhǐyào yǒudàolǐ jiù duōduōyìshàn.","vi":"Ý kiến không sợ nhiều, chỉ cần có lý thì càng nhiều càng tốt."}],"related":[{"hanzi":"越多越好","pinyin":"yuèduōyuèhǎo","vi":"càng nhiều càng tốt"},{"hanzi":"韩信点兵","pinyin":"hánxìndiǎnbīng","vi":"Hàn Tín điểm binh"},{"hanzi":"贪多","pinyin":"tānduō","vi":"tham nhiều"},{"hanzi":"适可而止","pinyin":"shìkě'érzhǐ","vi":"vừa phải thì dừng"}]},{"id":"多媒体","hanzi":"多媒体","pinyin":"duōméitǐ","meaning_vi":"đa phương tiện","explanation":"多 (đa – nhiều) + 媒体 (môi thể – phương tiện truyền thông) → đa phương tiện, kết hợp chữ, hình, âm thanh, video. Thường gặp: 多媒体教室, 多媒体技术.","hsk_level":6,"tags":["danh-tu","cong-nghe"],"image":"🖥️","examples":[{"type":"basic","zh":"教室里有多媒体。","pinyin":"Jiàoshì lǐ yǒu duōméitǐ.","vi":"Trong lớp học có thiết bị đa phương tiện."},{"type":"simple","zh":"老师用多媒体课件讲解地球的结构。","pinyin":"Lǎoshī yòng duōméitǐ kèjiàn jiǎngjiě dìqiú de jiégòu.","vi":"Giáo viên dùng bài giảng đa phương tiện để giải thích cấu tạo của Trái Đất."},{"type":"compound","zh":"自从学校有了多媒体教室，学生上课就更专心了。","pinyin":"Zìcóng xuéxiào yǒule duōméitǐ jiàoshì, xuésheng shàngkè jiù gèng zhuānxīn le.","vi":"Từ khi trường có phòng học đa phương tiện, học sinh lên lớp tập trung hơn."}],"related":[{"hanzi":"媒体","pinyin":"méitǐ","vi":"truyền thông"},{"hanzi":"视频","pinyin":"shìpín","vi":"video"},{"hanzi":"音频","pinyin":"yīnpín","vi":"âm thanh"},{"hanzi":"网络","pinyin":"wǎngluò","vi":"mạng"}],"traditional":"多媒體"},{"id":"多事之秋","hanzi":"多事之秋","pinyin":"duōshì-zhīqiū","meaning_vi":"thời buổi rối ren nhiều biến cố","explanation":"多事 (nhiều việc, nhiều biến cố) + 之秋 (thời kỳ – 秋 chỉ thời điểm) → thời buổi nhiều biến động, rối ren, tai họa liên tiếp; thường nói về đất nước, xã hội.","hsk_level":6,"tags":["thanh-ngu"],"image":"🍂","examples":[{"type":"basic","zh":"今年是多事之秋。","pinyin":"Jīnnián shì duōshìzhīqiū.","vi":"Năm nay là thời buổi nhiều biến cố."},{"type":"simple","zh":"公司正处在人员变动的多事之秋。","pinyin":"Gōngsī zhèng chǔzài rényuán biàndòng de duōshìzhīqiū.","vi":"Công ty đang ở giai đoạn rối ren vì biến động nhân sự."},{"type":"compound","zh":"正因为现在是多事之秋，所以大家更要团结一心。","pinyin":"Zhèng yīnwèi xiànzài shì duōshìzhīqiū, suǒyǐ dàjiā gèng yào tuánjié yìxīn.","vi":"Chính vì bây giờ là thời buổi rối ren nên mọi người càng phải đồng lòng đoàn kết."}],"related":[{"hanzi":"动荡","pinyin":"dòngdàng","vi":"bất ổn"},{"hanzi":"风雨飘摇","pinyin":"fēngyǔpiāoyáo","vi":"lung lay sóng gió"},{"hanzi":"多灾多难","pinyin":"duōzāiduōnàn","vi":"lắm tai nhiều nạn"},{"hanzi":"太平盛世","pinyin":"tàipíngshèngshì","vi":"thời thái bình thịnh trị"}]},{"id":"大不了","hanzi":"大不了","pinyin":"dàbuliǎo","meaning_vi":"cùng lắm thì","explanation":"大 (to) + 不了 (không xong) → cùng lắm thì, tệ nhất cũng chỉ là. Ví dụ: 大不了重新来 (cùng lắm thì làm lại). Dạng phủ định 没什么大不了 = chẳng có gì to tát.","hsk_level":6,"tags":["pho-tu"],"image":"🤷","examples":[{"type":"basic","zh":"大不了重新来。","pinyin":"Dàbuliǎo chóngxīn lái.","vi":"Cùng lắm thì làm lại từ đầu."},{"type":"simple","zh":"赶不上末班车大不了打车回家。","pinyin":"Gǎnbúshàng mòbānchē dàbuliǎo dǎchē huíjiā.","vi":"Không kịp chuyến xe cuối thì cùng lắm bắt taxi về nhà."},{"type":"compound","zh":"即使这次失败了，我也不怕，大不了明年再考。","pinyin":"Jíshǐ zhè cì shībài le, wǒ yě bú pà, dàbuliǎo míngnián zài kǎo.","vi":"Cho dù lần này thất bại, tôi cũng không sợ, cùng lắm thì sang năm thi lại."}],"related":[{"hanzi":"最多","pinyin":"zuìduō","vi":"nhiều nhất"},{"hanzi":"顶多","pinyin":"dǐngduō","vi":"cùng lắm"},{"hanzi":"无所谓","pinyin":"wúsuǒwèi","vi":"không sao cả"},{"hanzi":"了不起","pinyin":"liǎobuqǐ","vi":"ghê gớm"}]},{"id":"大彻大悟","hanzi":"大彻大悟","pinyin":"dàchè-dàwù","meaning_vi":"giác ngộ hoàn toàn, thấu hiểu triệt để","explanation":"大彻大悟: thấu triệt hoàn toàn, tỉnh ngộ hoàn toàn (gốc từ Phật giáo) → giác ngộ, nhận ra trọn vẹn chân lý hay sai lầm của mình.","hsk_level":6,"tags":["thanh-ngu"],"image":"💡","examples":[{"type":"basic","zh":"他终于大彻大悟。","pinyin":"Tā zhōngyú dàchèdàwù.","vi":"Cuối cùng anh ấy đã giác ngộ hoàn toàn."},{"type":"simple","zh":"一场大病让他对人生大彻大悟。","pinyin":"Yì chǎng dàbìng ràng tā duì rénshēng dàchèdàwù.","vi":"Một trận ốm nặng khiến anh ấy thấu hiểu triệt để về cuộc đời."},{"type":"compound","zh":"因为经历过破产，所以他对金钱早已大彻大悟。","pinyin":"Yīnwèi jīnglìguò pòchǎn, suǒyǐ tā duì jīnqián zǎoyǐ dàchèdàwù.","vi":"Vì từng trải qua phá sản nên anh ấy đã sớm thấu suốt về tiền bạc."}],"related":[{"hanzi":"恍然大悟","pinyin":"huǎngrándàwù","vi":"bỗng nhiên tỉnh ngộ"},{"hanzi":"觉悟","pinyin":"juéwù","vi":"giác ngộ"},{"hanzi":"醒悟","pinyin":"xǐngwù","vi":"tỉnh ngộ"},{"hanzi":"执迷不悟","pinyin":"zhímíbúwù","vi":"mê muội không tỉnh"}],"traditional":"大徹大悟"},{"id":"大材小用","hanzi":"大材小用","pinyin":"dàcái-xiǎoyòng","meaning_vi":"lãng phí nhân tài (tài lớn dùng việc nhỏ)","explanation":"大材 (đại tài – gỗ lớn, người tài lớn) + 小用 (dùng vào việc nhỏ) → giao người có tài lớn làm việc nhỏ, lãng phí nhân tài.","hsk_level":6,"tags":["thanh-ngu","cong-viec"],"image":"📉","examples":[{"type":"basic","zh":"这是大材小用。","pinyin":"Zhè shì dàcáixiǎoyòng.","vi":"Đây là lãng phí nhân tài."},{"type":"simple","zh":"让博士生去复印文件实在大材小用。","pinyin":"Ràng bóshìshēng qù fùyìn wénjiàn shízài dàcáixiǎoyòng.","vi":"Để nghiên cứu sinh tiến sĩ đi photo tài liệu thật là phí nhân tài."},{"type":"compound","zh":"与其让他在前台大材小用，不如派他去负责研发。","pinyin":"Yǔqí ràng tā zài qiántái dàcáixiǎoyòng, bùrú pài tā qù fùzé yánfā.","vi":"Thay vì để anh ấy ở quầy lễ tân phí tài, chi bằng cử anh ấy phụ trách nghiên cứu phát triển."}],"related":[{"hanzi":"怀才不遇","pinyin":"huáicáibúyù","vi":"có tài không gặp thời"},{"hanzi":"浪费人才","pinyin":"làngfèiréncái","vi":"lãng phí nhân tài"},{"hanzi":"人尽其才","pinyin":"rénjìnqícái","vi":"dùng người đúng tài"},{"hanzi":"屈才","pinyin":"qūcái","vi":"phí tài"}]},{"id":"大公无私","hanzi":"大公无私","pinyin":"dàgōng-wúsī","meaning_vi":"chí công vô tư","explanation":"大公无私: rất công bằng, không chút riêng tư → chí công vô tư, hoàn toàn vì lợi ích chung.","hsk_level":6,"tags":["thanh-ngu"],"image":"⚖️","examples":[{"type":"basic","zh":"他大公无私。","pinyin":"Tā dàgōngwúsī.","vi":"Ông ấy chí công vô tư."},{"type":"simple","zh":"这位法官以大公无私闻名全县。","pinyin":"Zhè wèi fǎguān yǐ dàgōngwúsī wénmíng quán xiàn.","vi":"Vị thẩm phán này nổi tiếng khắp huyện nhờ chí công vô tư."},{"type":"compound","zh":"他既大公无私，又关心群众，所以深受大家爱戴。","pinyin":"Tā jì dàgōngwúsī, yòu guānxīn qúnzhòng, suǒyǐ shēnshòu dàjiā àidài.","vi":"Ông ấy vừa chí công vô tư, vừa quan tâm quần chúng, nên rất được mọi người yêu mến."}],"related":[{"hanzi":"公正无私","pinyin":"gōngzhèngwúsī","vi":"công bằng vô tư"},{"hanzi":"铁面无私","pinyin":"tiěmiànwúsī","vi":"chí công vô tư"},{"hanzi":"自私自利","pinyin":"zìsīzìlì","vi":"ích kỷ vụ lợi"},{"hanzi":"无私","pinyin":"wúsī","vi":"vô tư"}],"traditional":"大公無私"},{"id":"大海捞针","hanzi":"大海捞针","pinyin":"dàhǎi-lāozhēn","meaning_vi":"mò kim đáy bể","explanation":"大海 (biển lớn) + 捞针 (vớt kim) → mò kim dưới đáy biển → ví việc tìm kiếm cực kỳ khó khăn, gần như không thể.","hsk_level":6,"tags":["thanh-ngu"],"image":"🪡","examples":[{"type":"basic","zh":"这像大海捞针。","pinyin":"Zhè xiàng dàhǎilāozhēn.","vi":"Việc này như mò kim đáy bể."},{"type":"simple","zh":"在人山人海中找一个孩子如同大海捞针。","pinyin":"Zài rénshānrénhǎi zhōng zhǎo yí gè háizi rútóng dàhǎilāozhēn.","vi":"Tìm một đứa trẻ giữa biển người chẳng khác nào mò kim đáy bể."},{"type":"compound","zh":"如果没有监控录像，找那辆车就像大海捞针。","pinyin":"Rúguǒ méiyǒu jiānkòng lùxiàng, zhǎo nà liàng chē jiù xiàng dàhǎilāozhēn.","vi":"Nếu không có video giám sát thì tìm chiếc xe đó chẳng khác gì mò kim đáy bể."}],"related":[{"hanzi":"海底捞针","pinyin":"hǎidǐlāozhēn","vi":"mò kim đáy biển"},{"hanzi":"难上加难","pinyin":"nánshàngjiānán","vi":"khó càng thêm khó"},{"hanzi":"易如反掌","pinyin":"yìrúfǎnzhǎng","vi":"dễ như trở bàn tay"},{"hanzi":"寻找","pinyin":"xúnzhǎo","vi":"tìm kiếm"}],"traditional":"大海撈針"},{"id":"大局","hanzi":"大局","pinyin":"dàjú","meaning_vi":"đại cục, cục diện chung","explanation":"大 + 局 (cục diện).","hsk_level":6,"tags":["danh-tu"],"image":"🌐","examples":[{"type":"basic","zh":"要顾全大局。","pinyin":"Yào gùquándàjú.","vi":"Phải biết lo cho đại cục."},{"type":"simple","zh":"队长的那个进球稳住了比赛大局。","pinyin":"Duìzhǎng de nà gè jìnqiú wěn zhùle bǐsài dàjú.","vi":"Bàn thắng đó của đội trưởng đã giữ vững cục diện trận đấu."},{"type":"compound","zh":"虽然我心里有意见，但是为了大局还是选择了让步。","pinyin":"Suīrán wǒ xīnlǐ yǒu yìjiàn, dànshì wèile dàjú háishì xuǎnzéle ràngbù.","vi":"Tuy trong lòng có ý kiến, nhưng vì đại cục tôi vẫn chọn nhượng bộ."}],"related":[{"hanzi":"全局","pinyin":"quánjú","vi":"toàn cục"},{"hanzi":"局势","pinyin":"júshì","vi":"tình thế"},{"hanzi":"顾全大局","pinyin":"gùquándàjú","vi":"chăm lo đại cục"},{"hanzi":"局部","pinyin":"júbù","vi":"cục bộ"}]},{"id":"大惊小怪","hanzi":"大惊小怪","pinyin":"dàjīng-xiǎoguài","meaning_vi":"chuyện bé xé ra to, ngạc nhiên thái quá","explanation":"大惊小怪: kinh ngạc lớn vì chuyện lạ nhỏ → ngạc nhiên thái quá, làm ầm lên vì chuyện bình thường. Ví dụ: 别大惊小怪的.","hsk_level":6,"tags":["thanh-ngu"],"image":"😱","examples":[{"type":"basic","zh":"别大惊小怪的。","pinyin":"Bié dàjīngxiǎoguài de.","vi":"Đừng có làm to chuyện thế."},{"type":"simple","zh":"外婆看见扫地机器人时大惊小怪地叫起来。","pinyin":"Wàipó kànjiàn sǎodì jīqìrén shí dàjīngxiǎoguài de jiào qǐlái.","vi":"Bà ngoại thấy robot hút bụi thì ngạc nhiên kêu ầm lên."},{"type":"compound","zh":"这种小擦伤很常见，所以你不必大惊小怪。","pinyin":"Zhè zhǒng xiǎo cāshāng hěn chángjiàn, suǒyǐ nǐ búbì dàjīngxiǎoguài.","vi":"Vết trầy nhỏ kiểu này rất thường gặp nên bạn không cần làm to chuyện."}],"related":[{"hanzi":"少见多怪","pinyin":"shǎojiànduōguài","vi":"ít thấy nên lạ"},{"hanzi":"小题大做","pinyin":"xiǎotídàzuò","vi":"chuyện bé xé ra to"},{"hanzi":"习以为常","pinyin":"xíyǐwéicháng","vi":"quen thuộc rồi"},{"hanzi":"司空见惯","pinyin":"sīkōngjiànguàn","vi":"quá quen thuộc"}],"traditional":"大驚小怪"},{"id":"大名鼎鼎","hanzi":"大名鼎鼎","pinyin":"dàmíng-dǐngdǐng","meaning_vi":"lừng danh, nổi tiếng khắp nơi","explanation":"大名 (đại danh – tên tuổi lớn) + 鼎鼎 (đỉnh đỉnh – hiển hách, lẫy lừng) → nổi tiếng lừng lẫy, ai cũng biết. Đồng nghĩa: 鼎鼎大名.","hsk_level":6,"tags":["thanh-ngu"],"image":"🌟","examples":[{"type":"basic","zh":"他大名鼎鼎。","pinyin":"Tā dàmíngdǐngdǐng.","vi":"Ông ấy lừng danh."},{"type":"simple","zh":"我们终于见到了大名鼎鼎的长城。","pinyin":"Wǒmen zhōngyú jiàndàole dàmíngdǐngdǐng de Chángchéng.","vi":"Cuối cùng chúng tôi đã được thấy Vạn Lý Trường Thành lừng danh."},{"type":"compound","zh":"这位厨师虽然大名鼎鼎，但是一点架子也没有。","pinyin":"Zhè wèi chúshī suīrán dàmíngdǐngdǐng, dànshì yìdiǎn jiàzi yě méiyǒu.","vi":"Vị đầu bếp này tuy lừng danh nhưng chẳng hề kiêu căng chút nào."}],"related":[{"hanzi":"鼎鼎大名","pinyin":"dǐngdǐngdàmíng","vi":"nổi tiếng lừng lẫy"},{"hanzi":"赫赫有名","pinyin":"hèhèyǒumíng","vi":"danh tiếng hiển hách"},{"hanzi":"闻名遐迩","pinyin":"wénmíngxiá'ěr","vi":"nổi tiếng gần xa"},{"hanzi":"默默无闻","pinyin":"mòmòwúwén","vi":"vô danh"}]},{"id":"大气","hanzi":"大气","pinyin":"dàqì","meaning_vi":"khí quyển; khoáng đạt, sang trọng (phong cách)","explanation":"大 + 气 (không khí/khí chất).","hsk_level":6,"tags":["danh-tu","khoa-hoc"],"image":"🌍","examples":[{"type":"basic","zh":"地球被大气包围。","pinyin":"Dìqiú bèi dàqì bāowéi.","vi":"Trái Đất được bao quanh bởi khí quyển."},{"type":"simple","zh":"工厂排放的废气严重污染了大气。","pinyin":"Gōngchǎng páifàng de fèiqì yánzhòng wūrǎnle dàqì.","vi":"Khí thải nhà máy thải ra đã gây ô nhiễm nghiêm trọng bầu khí quyển."},{"type":"compound","zh":"这套客厅的设计既简洁又大气，客人都很喜欢。","pinyin":"Zhè tào kètīng de shèjì jì jiǎnjié yòu dàqì, kèrén dōu hěn xǐhuan.","vi":"Thiết kế phòng khách này vừa đơn giản vừa khoáng đạt sang trọng, khách ai cũng thích."}],"related":[{"hanzi":"大气层","pinyin":"dàqìcéng","vi":"tầng khí quyển"},{"hanzi":"空气","pinyin":"kōngqì","vi":"không khí"},{"hanzi":"大方","pinyin":"dàfang","vi":"hào phóng"},{"hanzi":"小气","pinyin":"xiǎoqi","vi":"keo kiệt"}],"traditional":"大氣"},{"id":"大肆","hanzi":"大肆","pinyin":"dàsì","meaning_vi":"trắng trợn, rầm rộ","explanation":"大 (đại – lớn) + 肆 (tứ – buông thả, không kiêng nể) → làm một cách trắng trợn, không kiêng dè; mang sắc thái xấu. Thường đi với 大肆宣扬, 大肆挥霍, 大肆破坏.","hsk_level":6,"tags":["pho-tu"],"image":"📢","examples":[{"type":"basic","zh":"敌人大肆抢掠。","pinyin":"Dírén dàsì qiǎnglüè.","vi":"Quân địch cướp bóc trắng trợn."},{"type":"simple","zh":"这家公司在网上大肆宣传假药。","pinyin":"Zhè jiā gōngsī zài wǎngshàng dàsì xuānchuán jiǎyào.","vi":"Công ty này rầm rộ quảng cáo thuốc giả trên mạng."},{"type":"compound","zh":"他刚中了彩票，就开始在朋友面前大肆挥霍。","pinyin":"Tā gāng zhòngle cǎipiào, jiù kāishǐ zài péngyou miànqián dàsì huīhuò.","vi":"Anh ta vừa trúng xổ số đã bắt đầu vung tiền trắng trợn trước mặt bạn bè."}],"related":[{"hanzi":"肆意","pinyin":"sìyì","vi":"tùy tiện"},{"hanzi":"大张旗鼓","pinyin":"dàzhāngqígǔ","vi":"rầm rộ phô trương"},{"hanzi":"大肆宣扬","pinyin":"dàsìxuānyáng","vi":"rêu rao rầm rộ"},{"hanzi":"放肆","pinyin":"fàngsì","vi":"càn rỡ"}]},{"id":"大同小异","hanzi":"大同小异","pinyin":"dàtóng-xiǎoyì","meaning_vi":"đại đồng tiểu dị (giống nhau phần lớn, chỉ khác chút ít)","explanation":"大同 (đại đồng – phần lớn giống) + 小异 (tiểu dị – khác chút ít) → về cơ bản giống nhau, chỉ khác ở chi tiết nhỏ.","hsk_level":6,"tags":["thanh-ngu"],"image":"👯","examples":[{"type":"basic","zh":"两个方案大同小异。","pinyin":"Liǎng gè fāng'àn dàtóngxiǎoyì.","vi":"Hai phương án giống nhau là chính, chỉ khác chút ít."},{"type":"simple","zh":"这几家酒店的服务其实大同小异。","pinyin":"Zhè jǐ jiā jiǔdiàn de fúwù qíshí dàtóngxiǎoyì.","vi":"Dịch vụ của mấy khách sạn này thực ra đại đồng tiểu dị."},{"type":"compound","zh":"既然各家的价格大同小异，那就选离家近的吧。","pinyin":"Jìrán gè jiā de jiàgé dàtóngxiǎoyì, nà jiù xuǎn lí jiā jìn de ba.","vi":"Đã giá cả các nơi gần như nhau thì chọn chỗ gần nhà đi."}],"related":[{"hanzi":"相差无几","pinyin":"xiāngchàwújǐ","vi":"không chênh lệch mấy"},{"hanzi":"差不多","pinyin":"chàbuduō","vi":"gần như"},{"hanzi":"大相径庭","pinyin":"dàxiāngjìngtíng","vi":"khác một trời một vực"},{"hanzi":"截然不同","pinyin":"jiéránbùtóng","vi":"hoàn toàn khác"}],"traditional":"大同小異"},{"id":"大相径庭","hanzi":"大相径庭","pinyin":"dàxiāng-jìngtíng","meaning_vi":"khác nhau một trời một vực","explanation":"径 (kính – lối nhỏ ngoài cửa) và 庭 (đình – sân trong) cách nhau rất xa (Trang Tử) → khác nhau rất xa, hoàn toàn trái ngược. Thường đi với 与……大相径庭.","hsk_level":6,"tags":["thanh-ngu"],"image":"↔️","examples":[{"type":"basic","zh":"结果大相径庭。","pinyin":"Jiéguǒ dàxiāngjìngtíng.","vi":"Kết quả khác nhau một trời một vực."},{"type":"simple","zh":"兄弟俩的性格大相径庭。","pinyin":"Xiōngdì liǎ de xìnggé dàxiāngjìngtíng.","vi":"Tính cách hai anh em khác nhau một trời một vực."},{"type":"compound","zh":"虽然他们读的是同一本书，但是理解大相径庭。","pinyin":"Suīrán tāmen dú de shì tóngyī běn shū, dànshì lǐjiě dàxiāngjìngtíng.","vi":"Tuy họ cùng đọc một cuốn sách nhưng cách hiểu khác nhau một trời một vực."}],"related":[{"hanzi":"截然不同","pinyin":"jiéránbùtóng","vi":"hoàn toàn khác nhau"},{"hanzi":"天壤之别","pinyin":"tiānrǎngzhībié","vi":"khác như trời với đất"},{"hanzi":"大同小异","pinyin":"dàtóngxiǎoyì","vi":"đại đồng tiểu dị"},{"hanzi":"相差","pinyin":"xiāngchà","vi":"chênh lệch"}],"traditional":"大相徑庭"},{"id":"大显身手","hanzi":"大显身手","pinyin":"dàxiǎn-shēnshǒu","meaning_vi":"trổ hết tài năng","explanation":"大显 (thể hiện lớn) + 身手 (tài nghệ). Thành ngữ.","hsk_level":6,"tags":["thanh-ngu"],"image":"🌟","examples":[{"type":"basic","zh":"该你大显身手了。","pinyin":"Gāi nǐ dàxiǎnshēnshǒu le.","vi":"Đến lượt bạn trổ tài rồi."},{"type":"simple","zh":"新来的厨师在年夜饭上大显身手。","pinyin":"Xīn lái de chúshī zài niányèfàn shàng dàxiǎnshēnshǒu.","vi":"Đầu bếp mới đến trổ hết tài nghệ trong bữa cơm tất niên."},{"type":"compound","zh":"只要给年轻人舞台，他们就能大显身手。","pinyin":"Zhǐyào gěi niánqīngrén wǔtái, tāmen jiù néng dàxiǎnshēnshǒu.","vi":"Chỉ cần cho người trẻ sân khấu, họ sẽ trổ hết tài năng."}],"related":[{"hanzi":"一显身手","pinyin":"yìxiǎnshēnshǒu","vi":"trổ tài"},{"hanzi":"大展宏图","pinyin":"dàzhǎnhóngtú","vi":"thực hiện hoài bão lớn"},{"hanzi":"施展","pinyin":"shīzhǎn","vi":"phát huy"},{"hanzi":"英雄无用武之地","pinyin":"yīngxióng wúyòng wǔ zhī dì","vi":"anh hùng không đất dụng võ"}],"traditional":"大顯身手"},{"id":"大有可为","hanzi":"大有可为","pinyin":"dàyǒu-kěwéi","meaning_vi":"có triển vọng lớn, nhiều cơ hội phát triển","explanation":"大有 (có rất nhiều) + 可为 (khả vi – có thể làm được) → có nhiều điều để làm, nhiều triển vọng phát triển. Thường nói về ngành nghề, lĩnh vực, thanh niên.","hsk_level":6,"tags":["thanh-ngu"],"image":"🚀","examples":[{"type":"basic","zh":"农业大有可为。","pinyin":"Nóngyè dàyǒukěwéi.","vi":"Nông nghiệp có triển vọng lớn."},{"type":"simple","zh":"年轻人在新能源领域大有可为。","pinyin":"Niánqīngrén zài xīnnéngyuán lǐngyù dàyǒukěwéi.","vi":"Người trẻ có nhiều cơ hội phát triển trong lĩnh vực năng lượng mới."},{"type":"compound","zh":"只要找准方向，乡村旅游就大有可为。","pinyin":"Zhǐyào zhǎo zhǔn fāngxiàng, xiāngcūnlǚyóu jiù dàyǒukěwéi.","vi":"Chỉ cần tìm đúng hướng, du lịch nông thôn sẽ có triển vọng lớn."}],"related":[{"hanzi":"前途无量","pinyin":"qiántúwúliàng","vi":"tiền đồ vô lượng"},{"hanzi":"大有作为","pinyin":"dàyǒuzuòwéi","vi":"có thể làm nên việc lớn"},{"hanzi":"前景","pinyin":"qiánjǐng","vi":"triển vọng"},{"hanzi":"无能为力","pinyin":"wúnéngwéilì","vi":"bất lực"}],"traditional":"大有可為"},{"id":"大张旗鼓","hanzi":"大张旗鼓","pinyin":"dàzhāng-qígǔ","meaning_vi":"rầm rộ, phô trương thanh thế","explanation":"大张 + 旗鼓 (cờ trống). Thành ngữ.","hsk_level":6,"tags":["thanh-ngu"],"image":"🥁","examples":[{"type":"basic","zh":"他们大张旗鼓地庆祝。","pinyin":"Tāmen dàzhāngqígǔ de qìngzhù.","vi":"Họ ăn mừng rầm rộ."},{"type":"simple","zh":"商场大张旗鼓地搞了一场促销活动。","pinyin":"Shāngchǎng dàzhāngqígǔ de gǎole yì chǎng cùxiāo huódòng.","vi":"Trung tâm thương mại rầm rộ tổ chức một đợt khuyến mãi."},{"type":"compound","zh":"与其大张旗鼓地宣传，不如踏踏实实地把产品做好。","pinyin":"Yǔqí dàzhāngqígǔ de xuānchuán, bùrú tā tāshí shíde bǎ chǎnpǐn zuò hǎo.","vi":"Thay vì quảng bá rầm rộ, chi bằng chăm chỉ làm tốt sản phẩm."}],"related":[{"hanzi":"轰轰烈烈","pinyin":"hōnghōnglièliè","vi":"rầm rộ sôi nổi"},{"hanzi":"声势浩大","pinyin":"shēngshìhàodà","vi":"thanh thế lớn"},{"hanzi":"悄无声息","pinyin":"qiǎowúshēngxī","vi":"lặng lẽ không tiếng động"},{"hanzi":"偃旗息鼓","pinyin":"yǎnqíxīgǔ","vi":"hạ cờ ngừng trống"}],"traditional":"大張旗鼓"},{"id":"带动","hanzi":"带动","pinyin":"dàidòng","meaning_vi":"thúc đẩy, kéo theo cùng phát triển","explanation":"带 (dẫn) + 动 (chuyển động).","hsk_level":6,"tags":["dong-tu"],"image":"🚀","examples":[{"type":"basic","zh":"旅游带动了经济。","pinyin":"Lǚyóu dàidòngle jīngjì.","vi":"Du lịch đã thúc đẩy kinh tế."},{"type":"simple","zh":"新修的高铁带动了沿线小城的发展。","pinyin":"Xīnxiū de gāotiě dàidòngle yánxiàn xiǎochéng de fāzhǎn.","vi":"Tuyến đường sắt cao tốc mới xây đã kéo theo sự phát triển của các thị trấn dọc tuyến."},{"type":"compound","zh":"他不但自己致富了，而且带动了全村人一起种茶。","pinyin":"Tā búdàn zìjǐ zhìfù le, érqiě dàidòngle quán cūn rén yìqǐ zhòng chá.","vi":"Anh ấy không những tự mình làm giàu mà còn kéo cả làng cùng trồng chè."}],"related":[{"hanzi":"推动","pinyin":"tuīdòng","vi":"thúc đẩy"},{"hanzi":"促进","pinyin":"cùjìn","vi":"xúc tiến"},{"hanzi":"拉动","pinyin":"lādòng","vi":"kéo theo"},{"hanzi":"带头","pinyin":"dàitóu","vi":"dẫn đầu"}],"traditional":"帶動"},{"id":"代沟","hanzi":"代沟","pinyin":"dàigōu","meaning_vi":"khoảng cách thế hệ","explanation":"代 (thế hệ) + 沟 (rãnh ngăn cách).","hsk_level":6,"tags":["danh-tu","gia-dinh","xa-hoi"],"image":"👨‍👩‍👧","examples":[{"type":"basic","zh":"我们有代沟。","pinyin":"Wǒmen yǒu dàigōu.","vi":"Chúng tôi có khoảng cách thế hệ."},{"type":"simple","zh":"爸爸和我在穿衣风格上存在明显的代沟。","pinyin":"Bàba hé wǒ zài chuānyī fēnggé shàng cúnzài míngxiǎn de dàigōu.","vi":"Bố và tôi có khoảng cách thế hệ rõ rệt trong phong cách ăn mặc."},{"type":"compound","zh":"只要彼此多沟通，代沟就会慢慢缩小。","pinyin":"Zhǐyào bǐcǐ duō gōutōng, dàigōu jiù huì mànmàn suōxiǎo.","vi":"Chỉ cần trao đổi với nhau nhiều hơn, khoảng cách thế hệ sẽ dần thu hẹp."}],"related":[{"hanzi":"隔阂","pinyin":"géhé","vi":"sự ngăn cách"},{"hanzi":"两代人","pinyin":"liǎngdàirén","vi":"hai thế hệ"},{"hanzi":"沟通","pinyin":"gōutōng","vi":"giao tiếp"},{"hanzi":"观念","pinyin":"guānniàn","vi":"quan niệm"}],"traditional":"代溝"},{"id":"带领","hanzi":"带领","pinyin":"dàilǐng","meaning_vi":"dẫn dắt","explanation":"带 (đới – mang, dẫn) + 领 (lĩnh – dẫn dắt, lãnh đạo) → dẫn đầu, dẫn dắt người khác cùng làm. Ví dụ: 带领团队, 在老师的带领下.","hsk_level":6,"tags":["dong-tu"],"image":"🚩","examples":[{"type":"basic","zh":"老师带领我们参观。","pinyin":"Lǎoshī dàilǐng wǒmen cānguān.","vi":"Thầy giáo dẫn chúng tôi đi tham quan."},{"type":"simple","zh":"导游带领游客走进了古老的寺庙。","pinyin":"Dǎoyóu dàilǐng yóukè zǒujìnle gǔlǎo de sìmiào.","vi":"Hướng dẫn viên dẫn du khách vào ngôi chùa cổ."},{"type":"compound","zh":"在新教练的带领下，球队不但赢了比赛，而且士气大涨。","pinyin":"Zài xīn jiàoliàn de dàilǐng xià, qiúduì búdàn yíngle bǐsài, érqiě shìqì dà zhǎng.","vi":"Dưới sự dẫn dắt của huấn luyện viên mới, đội bóng không những thắng trận mà còn lên tinh thần hẳn."}],"related":[{"hanzi":"率领","pinyin":"shuàilǐng","vi":"thống lĩnh"},{"hanzi":"领导","pinyin":"lǐngdǎo","vi":"lãnh đạo"},{"hanzi":"引领","pinyin":"yǐnlǐng","vi":"dẫn dắt"},{"hanzi":"指引","pinyin":"zhǐyǐn","vi":"chỉ dẫn"}],"traditional":"帶領"},{"id":"代言人","hanzi":"代言人","pinyin":"dàiyánrén","meaning_vi":"người đại diện phát ngôn, đại sứ thương hiệu","explanation":"代言 (nói thay) + 人 (người).","hsk_level":6,"tags":["danh-tu","cong-viec","giai-tri"],"image":"🎤","examples":[{"type":"basic","zh":"她是品牌代言人。","pinyin":"Tā shì pǐnpái dàiyánrén.","vi":"Cô ấy là đại sứ thương hiệu."},{"type":"simple","zh":"这家手机公司请了一位奥运冠军当代言人。","pinyin":"Zhè jiā shǒujī gōngsī qǐngle yí wèi Àoyùn guànjūn dāng dàiyánrén.","vi":"Công ty điện thoại này mời một nhà vô địch Olympic làm đại sứ thương hiệu."},{"type":"compound","zh":"代言人一出丑闻，品牌的销量就跟着下降了。","pinyin":"Dàiyánrén yì chū chǒuwén, pǐnpái de xiāoliàng jiù gēnzhe xiàjiàng le.","vi":"Người đại diện vừa dính bê bối, doanh số của thương hiệu liền giảm theo."}],"related":[{"hanzi":"形象大使","pinyin":"xíngxiàngdàshǐ","vi":"đại sứ hình ảnh"},{"hanzi":"发言人","pinyin":"fāyánrén","vi":"người phát ngôn"},{"hanzi":"代言","pinyin":"dàiyán","vi":"đại diện quảng bá"},{"hanzi":"广告","pinyin":"guǎnggào","vi":"quảng cáo"}]},{"id":"淡泊名利","hanzi":"淡泊名利","pinyin":"dànbó-mínglì","meaning_vi":"xem nhẹ danh lợi","explanation":"淡泊 (đạm bạc – thanh đạm, không ham) + 名利 (danh lợi) → không màng danh vọng tiền tài, sống thanh thản. Dùng để khen phẩm chất người cao thượng.","hsk_level":6,"tags":["thanh-ngu"],"image":"🧘","examples":[{"type":"basic","zh":"他一向淡泊名利。","pinyin":"Tā yíxiàng dànbómínglì.","vi":"Ông ấy luôn xem nhẹ danh lợi."},{"type":"simple","zh":"淡泊名利的老教授拒绝了所有采访。","pinyin":"Dànbómínglì de lǎo jiàoshòu jùjuéle suǒyǒu cǎifǎng.","vi":"Vị giáo sư già xem nhẹ danh lợi đã từ chối mọi cuộc phỏng vấn."},{"type":"compound","zh":"正因为她淡泊名利，所以才能静下心来搞研究。","pinyin":"Zhèng yīnwèi tā dànbómínglì, suǒyǐ cáinéng jìng xià xīn lái gǎo yánjiū.","vi":"Chính vì bà ấy xem nhẹ danh lợi nên mới có thể tĩnh tâm làm nghiên cứu."}],"related":[{"hanzi":"淡泊","pinyin":"dànbó","vi":"đạm bạc"},{"hanzi":"名利","pinyin":"mínglì","vi":"danh lợi"},{"hanzi":"与世无争","pinyin":"yǔshìwúzhēng","vi":"không tranh với đời"},{"hanzi":"追名逐利","pinyin":"zhuīmíngzhúlì","vi":"chạy theo danh lợi"}]},{"id":"淡季","hanzi":"淡季","pinyin":"dànjì","meaning_vi":"mùa thấp điểm","explanation":"淡 (đạm – nhạt, ế ẩm) + 季 (quý – mùa) → mùa vắng khách, mùa thấp điểm kinh doanh. Trái nghĩa: 旺季 (mùa cao điểm). Thường gặp: 旅游淡季.","hsk_level":6,"tags":["danh-tu","cong-viec"],"image":"📉","examples":[{"type":"basic","zh":"现在是淡季。","pinyin":"Xiànzài shì dànjì.","vi":"Bây giờ là mùa thấp điểm."},{"type":"simple","zh":"淡季的海边酒店价格便宜了一半。","pinyin":"Dànjì de hǎibiān jiǔdiàn jiàgé piányile yíbàn.","vi":"Giá khách sạn ven biển mùa thấp điểm rẻ đi một nửa."},{"type":"compound","zh":"如果你想避开人群，就选在旅游淡季出发。","pinyin":"Rúguǒ nǐ xiǎng bìkāi rénqún, jiù xuǎn zài lǚyóu dànjì chūfā.","vi":"Nếu bạn muốn tránh đám đông thì hãy chọn khởi hành vào mùa du lịch thấp điểm."}],"related":[{"hanzi":"旺季","pinyin":"wàngjì","vi":"mùa cao điểm"},{"hanzi":"季节","pinyin":"jìjié","vi":"mùa"},{"hanzi":"生意","pinyin":"shēngyi","vi":"buôn bán"},{"hanzi":"冷清","pinyin":"lěngqīng","vi":"vắng vẻ"}]},{"id":"淡漠","hanzi":"淡漠","pinyin":"dànmò","meaning_vi":"lạnh nhạt, thờ ơ, phai nhạt","explanation":"淡 (nhạt) + 漠 (lạnh lùng).","hsk_level":6,"tags":["tinh-tu","cam-xuc"],"image":"😐","examples":[{"type":"basic","zh":"他神情淡漠。","pinyin":"Tā shénqíng dànmò.","vi":"Vẻ mặt anh ấy lạnh nhạt."},{"type":"simple","zh":"她淡漠地看了一眼桌上的礼物。","pinyin":"Tā dànmò de kànle yìyǎn zhuō shàng de lǐwù.","vi":"Cô ấy thờ ơ liếc nhìn món quà trên bàn."},{"type":"compound","zh":"虽然多年没回故乡，但是那些记忆并没有淡漠。","pinyin":"Suīrán duōnián méi huí gùxiāng, dànshì nàxiē jìyì bìng méiyǒu dànmò.","vi":"Tuy nhiều năm không về quê nhưng những ký ức ấy không hề phai nhạt."}],"related":[{"hanzi":"冷漠","pinyin":"lěngmò","vi":"lạnh lùng"},{"hanzi":"冷淡","pinyin":"lěngdàn","vi":"lạnh nhạt"},{"hanzi":"漠不关心","pinyin":"mòbùguānxīn","vi":"thờ ơ"},{"hanzi":"热情","pinyin":"rèqíng","vi":"nhiệt tình"}]},{"id":"档次","hanzi":"档次","pinyin":"dàngcì","meaning_vi":"đẳng cấp","explanation":"档 (đáng – bậc, hạng) + 次 (thứ – thứ bậc) → cấp bậc chất lượng, đẳng cấp. Thường gặp: 高档次, 提高档次, 档次不同.","hsk_level":6,"tags":["danh-tu"],"image":"⭐","examples":[{"type":"basic","zh":"这家店档次很高。","pinyin":"Zhè jiā diàn dàngcì hěn gāo.","vi":"Cửa hàng này đẳng cấp rất cao."},{"type":"simple","zh":"新装修的餐厅提升了整条街的档次。","pinyin":"Xīn zhuāngxiū de cāntīng tíshēngle zhěngtiáo jiē de dàngcì.","vi":"Nhà hàng mới sửa sang đã nâng tầm đẳng cấp của cả con phố."},{"type":"compound","zh":"礼物不一定要高档次，只要用心就好。","pinyin":"Lǐwù bù yídìngyào gāo dàngcì, zhǐyào yòngxīn jiù hǎo.","vi":"Quà không nhất thiết phải cao cấp, chỉ cần có tâm là được."}],"related":[{"hanzi":"等级","pinyin":"děngjí","vi":"đẳng cấp"},{"hanzi":"级别","pinyin":"jíbié","vi":"cấp bậc"},{"hanzi":"高档","pinyin":"gāodàng","vi":"cao cấp"},{"hanzi":"低档","pinyin":"dīdàng","vi":"cấp thấp"}],"traditional":"檔次"},{"id":"荡漾","hanzi":"荡漾","pinyin":"dàngyàng","meaning_vi":"gợn sóng, dập dềnh","explanation":"Cả hai chữ đều có bộ thủy 氵.","hsk_level":6,"tags":["dong-tu","thien-nhien"],"image":"🌊","examples":[{"type":"basic","zh":"湖水微微荡漾。","pinyin":"Húshuǐ wēiwēi dàngyàng.","vi":"Mặt hồ khẽ gợn sóng."},{"type":"simple","zh":"小船在月光下的湖面上轻轻荡漾。","pinyin":"Xiǎochuán zài yuèguāng xià de húmiàn shàng qīngqīng dàngyàng.","vi":"Con thuyền nhỏ dập dềnh nhẹ nhàng trên mặt hồ dưới ánh trăng."},{"type":"compound","zh":"风一吹过，池水就荡漾起一圈圈波纹。","pinyin":"Fēng yì chuī guò, chí shuǐ jiù dàngyàng qǐ yì quānquān bōwén.","vi":"Gió vừa thổi qua, nước ao liền gợn lên từng vòng sóng lăn tăn."}],"related":[{"hanzi":"波动","pinyin":"bōdòng","vi":"dao động"},{"hanzi":"涟漪","pinyin":"liányī","vi":"gợn sóng"},{"hanzi":"飘荡","pinyin":"piāodàng","vi":"lênh đênh"},{"hanzi":"荡漾开来","pinyin":"dàngyàngkāilái","vi":"lan tỏa ra"}],"traditional":"蕩漾"},{"id":"稻谷","hanzi":"稻谷","pinyin":"dàogǔ","meaning_vi":"lúa, thóc","explanation":"稻 (đạo – cây lúa) + 谷 (cốc – hạt ngũ cốc) → thóc, lúa chưa xay vỏ. Liên quan: 稻田 (ruộng lúa), 大米 (gạo đã xát).","hsk_level":6,"tags":["danh-tu","thien-nhien"],"image":"🌾","examples":[{"type":"basic","zh":"金黄的稻谷熟了。","pinyin":"Jīnhuáng de dàogǔ shú le.","vi":"Lúa vàng óng đã chín."},{"type":"simple","zh":"农民们在晒场上翻晒刚收的稻谷。","pinyin":"Nóngmínmen zài shài chǎng shàng fān shài gāng shōu de dàogǔ.","vi":"Nông dân đang trở phơi lúa vừa gặt trên sân phơi."},{"type":"compound","zh":"因为今年雨水充足，所以稻谷的收成特别好。","pinyin":"Yīnwèi jīnnián yǔshuǐ chōngzú, suǒyǐ dàogǔ de shōuchéng tèbié hǎo.","vi":"Vì năm nay mưa thuận nên lúa được mùa đặc biệt."}],"related":[{"hanzi":"水稻","pinyin":"shuǐdào","vi":"lúa nước"},{"hanzi":"大米","pinyin":"dàmǐ","vi":"gạo"},{"hanzi":"稻田","pinyin":"dàotián","vi":"ruộng lúa"},{"hanzi":"粮食","pinyin":"liángshi","vi":"lương thực"}],"traditional":"稻穀"},{"id":"道貌岸然","hanzi":"道貌岸然","pinyin":"dàomào-ànrán","meaning_vi":"vẻ ngoài đạo mạo nghiêm trang (thường mang nghĩa mỉa mai)","explanation":"道貌 (đạo mạo – vẻ đạo đức) + 岸然 (ngạn nhiên – nghiêm trang, cao ngạo) → vẻ ngoài nghiêm trang đạo mạo; nay thường mỉa mai kẻ giả đạo đức, bên ngoài đứng đắn bên trong xấu xa.","hsk_level":6,"tags":["thanh-ngu"],"image":"🎭","examples":[{"type":"basic","zh":"他道貌岸然。","pinyin":"Tā dàomào'ànrán.","vi":"Hắn ta bề ngoài đạo mạo."},{"type":"simple","zh":"那个道貌岸然的老板背地里拖欠工资。","pinyin":"Nà gè dàomào'ànrán de lǎobǎn bèidìlǐ tuōqiàn gōngzī.","vi":"Ông chủ bề ngoài đạo mạo đó sau lưng lại nợ lương nhân viên."},{"type":"compound","zh":"他虽然表面上道貌岸然，但是私下里却干尽了坏事。","pinyin":"Tā suīrán biǎomiànshàng dàomào'ànrán, dànshì sīxià lǐ què gàn jìnle huàishì.","vi":"Hắn tuy bề ngoài ra vẻ đạo mạo nhưng sau lưng lại làm đủ điều xấu."}],"related":[{"hanzi":"伪君子","pinyin":"wěijūnzǐ","vi":"kẻ đạo đức giả"},{"hanzi":"假惺惺","pinyin":"jiǎxīngxīng","vi":"giả bộ"},{"hanzi":"虚伪","pinyin":"xūwěi","vi":"giả dối"},{"hanzi":"表里如一","pinyin":"biǎolǐrúyī","vi":"trong ngoài như một"}]},{"id":"到头来","hanzi":"到头来","pinyin":"dàotóulái","meaning_vi":"cuối cùng thì, rốt cuộc","explanation":"到头 (đến đầu cuối) + 来.","hsk_level":6,"tags":["pho-tu"],"image":"⏳","examples":[{"type":"basic","zh":"到头来一场空。","pinyin":"Dàotóulái yìchǎngkōng.","vi":"Rốt cuộc chỉ là công cốc."},{"type":"simple","zh":"他算计了半天到头来还是吃了亏。","pinyin":"Tā suànjìle bàn tiān dàotóulái háishì chīle kuī.","vi":"Anh ta tính toán mãi rốt cuộc vẫn chịu thiệt."},{"type":"compound","zh":"如果现在不努力，到头来就只能后悔。","pinyin":"Rúguǒ xiànzài bù nǔlì, dàotóulái jiù zhǐnéng hòuhuǐ.","vi":"Nếu bây giờ không cố gắng thì cuối cùng chỉ có thể hối hận."}],"related":[{"hanzi":"最终","pinyin":"zuìzhōng","vi":"cuối cùng"},{"hanzi":"结果","pinyin":"jiéguǒ","vi":"kết quả"},{"hanzi":"终究","pinyin":"zhōngjiū","vi":"rốt cuộc"},{"hanzi":"最后","pinyin":"zuìhòu","vi":"sau cùng"}],"traditional":"到頭來"},{"id":"道听途说","hanzi":"道听途说","pinyin":"dàotīng-túshuō","meaning_vi":"nghe hơi nồi chõ, tin đồn ngoài đường","explanation":"道听途说: nghe ngoài đường rồi nói lại ngoài đường (Luận Ngữ) → tin đồn không có căn cứ, nghe hơi nồi chõ.","hsk_level":6,"tags":["thanh-ngu"],"image":"🗣️","examples":[{"type":"basic","zh":"这是道听途说。","pinyin":"Zhè shì dàotīngtúshuō.","vi":"Đây là chuyện nghe hơi nồi chõ."},{"type":"simple","zh":"别把道听途说的消息发到群里。","pinyin":"Bié bǎ dàotīngtúshuō de xiāoxi fā dào qún lǐ.","vi":"Đừng đăng tin đồn nghe hơi nồi chõ lên nhóm."},{"type":"compound","zh":"既然是道听途说的事，你就别太当真了。","pinyin":"Jìrán shì dàotīngtúshuō de shì, nǐ jiù bié tài dàngzhēn le.","vi":"Đã là chuyện nghe hơi nồi chõ thì bạn đừng quá tin là thật."}],"related":[{"hanzi":"小道消息","pinyin":"xiǎodàoxiāoxi","vi":"tin đồn hành lang"},{"hanzi":"传闻","pinyin":"chuánwén","vi":"lời đồn"},{"hanzi":"谣言","pinyin":"yáoyán","vi":"tin đồn nhảm"},{"hanzi":"亲眼所见","pinyin":"qīnyǎnsuǒjiàn","vi":"tận mắt chứng kiến"}],"traditional":"道聽途說"},{"id":"达成","hanzi":"达成","pinyin":"dáchéng","meaning_vi":"đạt được (thỏa thuận, nhận thức chung…)","explanation":"达 (đạt – đến, đạt tới) + 成 (thành – thành công) → đạt được (sau thương lượng). Thường đi với 达成协议, 达成共识, 达成一致.","hsk_level":6,"tags":["dong-tu"],"image":"✅","examples":[{"type":"basic","zh":"双方达成了协议。","pinyin":"Shuāngfāng dáchéngle xiéyì.","vi":"Hai bên đã đạt được thỏa thuận."},{"type":"simple","zh":"两家公司终于就合作价格达成了共识。","pinyin":"Liǎng jiā gōngsī zhōngyú jiù hézuò jiàgé dá chéngle gòngshí.","vi":"Hai công ty cuối cùng đã đạt được đồng thuận về giá hợp tác."},{"type":"compound","zh":"只要双方各让一步，就能很快达成和解。","pinyin":"Zhǐyào shuāngfāng gè ràng yí bù, jiù néng hěn kuài dáchéng héjiě.","vi":"Chỉ cần mỗi bên nhường một bước là có thể nhanh chóng hòa giải."}],"related":[{"hanzi":"达到","pinyin":"dádào","vi":"đạt tới"},{"hanzi":"实现","pinyin":"shíxiàn","vi":"thực hiện"},{"hanzi":"达成协议","pinyin":"dáchéngxiéyì","vi":"đạt được thỏa thuận"},{"hanzi":"完成","pinyin":"wánchéng","vi":"hoàn thành"}],"traditional":"達成"},{"id":"答谢","hanzi":"答谢","pinyin":"dáxiè","meaning_vi":"cảm tạ, đáp lễ","explanation":"答 (đáp lại) + 谢 (cảm ơn).","hsk_level":6,"tags":["dong-tu","giao-tiep"],"image":"🙇","examples":[{"type":"basic","zh":"他设宴答谢朋友。","pinyin":"Tā shèyàn dáxiè péngyou.","vi":"Anh ấy mở tiệc cảm tạ bạn bè."},{"type":"simple","zh":"歌手在演唱会结尾鞠躬答谢歌迷。","pinyin":"Gēshǒu zài yǎnchànghuì jiéwěi jūgōng dáxiè gēmí.","vi":"Ca sĩ cúi chào cảm tạ người hâm mộ ở cuối buổi hòa nhạc."},{"type":"compound","zh":"为了答谢老顾客，这家店不但打折，而且送小礼品。","pinyin":"Wèile dáxiè lǎo gùkè, zhè jiā diàn búdàn dǎzhé, érqiě sòng xiǎo lǐpǐn.","vi":"Để tri ân khách quen, cửa hàng này không những giảm giá mà còn tặng quà nhỏ."}],"related":[{"hanzi":"感谢","pinyin":"gǎnxiè","vi":"cảm ơn"},{"hanzi":"致谢","pinyin":"zhìxiè","vi":"bày tỏ cảm ơn"},{"hanzi":"回报","pinyin":"huíbào","vi":"đền đáp"},{"hanzi":"答谢宴","pinyin":"dáxièyàn","vi":"tiệc cảm ơn"}],"traditional":"答謝"},{"id":"德才兼备","hanzi":"德才兼备","pinyin":"décái-jiānbèi","meaning_vi":"vừa có đức vừa có tài","explanation":"德 (đức) + 才 (tài) + 兼备 (kiêm bị – có đủ cả) → vừa có đạo đức vừa có tài năng. Hay dùng khi nói tiêu chuẩn chọn người, cán bộ.","hsk_level":6,"tags":["thanh-ngu"],"image":"🌟","examples":[{"type":"basic","zh":"他德才兼备。","pinyin":"Tā décáijiānbèi.","vi":"Anh ấy vừa có đức vừa có tài."},{"type":"simple","zh":"公司正在寻找德才兼备的管理人才。","pinyin":"Gōngsī zhèngzài xúnzhǎo décáijiānbèi de guǎnlǐ réncái.","vi":"Công ty đang tìm kiếm nhân tài quản lý có cả đức lẫn tài."},{"type":"compound","zh":"只有德才兼备的人，才能真正赢得下属的尊重。","pinyin":"Zhǐyǒu décáijiānbèi de rén, cáinéng zhēnzhèng yíngdé xiàshǔ de zūnzhòng.","vi":"Chỉ người có cả đức lẫn tài mới thực sự giành được sự tôn trọng của cấp dưới."}],"related":[{"hanzi":"德智体","pinyin":"dézhìtǐ","vi":"đức trí thể"},{"hanzi":"品学兼优","pinyin":"pǐnxuéjiānyōu","vi":"phẩm hạnh học lực đều tốt"},{"hanzi":"德高望重","pinyin":"dégāowàngzhòng","vi":"đức cao vọng trọng"},{"hanzi":"才德","pinyin":"cáidé","vi":"tài đức"}],"traditional":"德才兼備"},{"id":"得寸进尺","hanzi":"得寸进尺","pinyin":"décùn-jìnchǐ","meaning_vi":"được voi đòi tiên, được tấc tiến thước","explanation":"得寸进尺: được tấc lại muốn tiến thước → được đằng chân lân đằng đầu, được voi đòi tiên, lòng tham không đáy.","hsk_level":6,"tags":["thanh-ngu"],"image":"🤑","examples":[{"type":"basic","zh":"别得寸进尺！","pinyin":"Bié décùnjìnchǐ!","vi":"Đừng được voi đòi tiên!"},{"type":"simple","zh":"邻居得寸进尺地把车停到了我家院子里。","pinyin":"Línjū décùnjìnchǐ de bǎ chē tíng dàole wǒ jiā yuànzi lǐ.","vi":"Người hàng xóm được đằng chân lân đằng đầu, đỗ xe luôn vào sân nhà tôi."},{"type":"compound","zh":"如果你一再让步，他就会得寸进尺地提要求。","pinyin":"Rúguǒ nǐ yízài ràngbù, tā jiù huì décùnjìnchǐ de tí yāoqiú.","vi":"Nếu bạn cứ nhượng bộ mãi thì anh ta sẽ được voi đòi tiên, đưa ra thêm yêu cầu."}],"related":[{"hanzi":"贪得无厌","pinyin":"tāndéwúyàn","vi":"tham lam vô đáy"},{"hanzi":"得陇望蜀","pinyin":"délǒngwàngshǔ","vi":"được Lũng trông Thục"},{"hanzi":"适可而止","pinyin":"shìkě'érzhǐ","vi":"vừa phải thì dừng"},{"hanzi":"知足","pinyin":"zhīzú","vi":"biết đủ"}],"traditional":"得寸進尺"},{"id":"得过且过","hanzi":"得过且过","pinyin":"déguò-qiěguò","meaning_vi":"sống qua ngày đoạn tháng, làm cho xong chuyện","explanation":"得过 (sống qua được) + 且过 (tạm cứ qua) → qua được ngày nào hay ngày đó, sống tạm bợ, làm việc cầm chừng không có chí tiến thủ.","hsk_level":6,"tags":["thanh-ngu"],"image":"🤷","examples":[{"type":"basic","zh":"他总是得过且过。","pinyin":"Tā zǒngshì déguòqiěguò.","vi":"Anh ta lúc nào cũng sống qua ngày."},{"type":"simple","zh":"失业后的小李过着得过且过的日子。","pinyin":"Shīyè hòu de xiǎo lǐguò zhe déguòqiěguò de rìzi.","vi":"Tiểu Lý sau khi thất nghiệp sống những ngày qua loa cho xong."},{"type":"compound","zh":"与其得过且过地混日子，不如学一门真本事。","pinyin":"Yǔqí déguòqiěguò de hùnrìzi, bùrú xué yì mén zhēn běnshi.","vi":"Thay vì sống lay lắt qua ngày, chi bằng học lấy một nghề thực sự."}],"related":[{"hanzi":"敷衍了事","pinyin":"fūyǎnliǎoshì","vi":"làm qua loa cho xong"},{"hanzi":"混日子","pinyin":"hùnrìzi","vi":"sống lay lắt qua ngày"},{"hanzi":"精益求精","pinyin":"jīngyìqiújīng","vi":"đã tốt còn muốn tốt hơn"},{"hanzi":"过一天算一天","pinyin":"guò yì tiān suàn yì tiān","vi":"sống ngày nào hay ngày đó"}],"traditional":"得過且過"},{"id":"德高望重","hanzi":"德高望重","pinyin":"dégāo-wàngzhòng","meaning_vi":"đức cao vọng trọng","explanation":"德高 (đức cao – đạo đức cao) + 望重 (vọng trọng – uy tín lớn) → đạo đức cao, được mọi người kính trọng. Thường dùng cho bậc trưởng bối, học giả.","hsk_level":6,"tags":["thanh-ngu"],"image":"👴","examples":[{"type":"basic","zh":"爷爷德高望重。","pinyin":"Yéye dégāowàngzhòng.","vi":"Ông nội đức cao vọng trọng."},{"type":"simple","zh":"村里请德高望重的老人来调解纠纷。","pinyin":"Cūnlǐ qǐng dégāowàngzhòng de lǎorén lái tiáojiě jiūfēn.","vi":"Trong làng mời cụ già đức cao vọng trọng đến hòa giải tranh chấp."},{"type":"compound","zh":"因为这位医生德高望重，所以大家都很信任他。","pinyin":"Yīnwèi zhè wèi yīshēng dégāowàngzhòng, suǒyǐ dàjiā dōu hěn xìnrèn tā.","vi":"Vì vị bác sĩ này đức cao vọng trọng nên mọi người đều rất tin tưởng ông."}],"related":[{"hanzi":"德才兼备","pinyin":"décáijiānbèi","vi":"có cả đức lẫn tài"},{"hanzi":"威望","pinyin":"wēiwàng","vi":"uy tín"},{"hanzi":"受人尊敬","pinyin":"shòurénzūnjìng","vi":"được mọi người kính trọng"},{"hanzi":"老前辈","pinyin":"lǎoqiánbèi","vi":"bậc tiền bối"}]},{"id":"得陇望蜀","hanzi":"得陇望蜀","pinyin":"délǒng-wàngshǔ","meaning_vi":"được Lũng trông Thục (tham lam không đáy)","explanation":"得陇望蜀: được đất Lũng rồi lại muốn chiếm đất Thục (lời Hán Quang Vũ Đế) → ví lòng tham không đáy, được cái này lại đòi cái khác.","hsk_level":6,"tags":["thanh-ngu"],"image":"🤑","examples":[{"type":"basic","zh":"人不能得陇望蜀。","pinyin":"Rén bù néng délǒngwàngshǔ.","vi":"Con người không nên được Lũng trông Thục."},{"type":"simple","zh":"他刚升了主管又得陇望蜀想当经理。","pinyin":"Tā gāng shēngle zhǔguǎn yòu délǒngwàngshǔ xiǎng dāng jīnglǐ.","vi":"Anh ta vừa lên trưởng nhóm đã được voi đòi tiên muốn làm giám đốc."},{"type":"compound","zh":"既然已经有了稳定的工作，就别再得陇望蜀了。","pinyin":"Jìrán yǐjīng yǒule wěndìng de gōngzuò, jiù bié zài délǒngwàngshǔ le.","vi":"Đã có công việc ổn định rồi thì đừng được Lũng trông Thục nữa."}],"related":[{"hanzi":"得寸进尺","pinyin":"décùnjìnchǐ","vi":"được voi đòi tiên"},{"hanzi":"贪得无厌","pinyin":"tāndéwúyàn","vi":"tham lam vô đáy"},{"hanzi":"贪心","pinyin":"tānxīn","vi":"tham lam"},{"hanzi":"知足常乐","pinyin":"zhīzúchánglè","vi":"biết đủ là vui"}],"traditional":"得隴望蜀"},{"id":"得天独厚","hanzi":"得天独厚","pinyin":"détiān-dúhòu","meaning_vi":"được thiên nhiên ưu đãi","explanation":"得天 (được trời ban) + 独厚 (độc hậu – riêng được ưu đãi) → có điều kiện tự nhiên hoặc hoàn cảnh đặc biệt thuận lợi hơn nơi khác/người khác.","hsk_level":6,"tags":["thanh-ngu"],"image":"🏞️","examples":[{"type":"basic","zh":"这里得天独厚。","pinyin":"Zhèlǐ détiāndúhòu.","vi":"Nơi này được thiên nhiên ưu đãi."},{"type":"simple","zh":"云南拥有种植花卉得天独厚的气候条件。","pinyin":"Yúnnán yōngyǒu zhòngzhí huāhuì détiāndúhòu de qìhòu tiáojiàn.","vi":"Vân Nam có điều kiện khí hậu được thiên nhiên ưu đãi để trồng hoa."},{"type":"compound","zh":"这座小城既有温泉，又靠近大海，自然条件得天独厚。","pinyin":"Zhè zuò xiǎochéng jìyǒu wēnquán, yòu kàojìn dàhǎi, zìrán tiáojiàn détiāndúhòu.","vi":"Thành phố nhỏ này vừa có suối nước nóng vừa gần biển, điều kiện tự nhiên được ưu đãi đặc biệt."}],"related":[{"hanzi":"天时地利","pinyin":"tiānshídìlì","vi":"thiên thời địa lợi"},{"hanzi":"优越","pinyin":"yōuyuè","vi":"ưu việt"},{"hanzi":"地大物博","pinyin":"dìdàwùbó","vi":"đất rộng của nhiều"},{"hanzi":"先天不足","pinyin":"xiāntiānbùzú","vi":"thiếu hụt bẩm sinh"}],"traditional":"得天獨厚"},{"id":"得心应手","hanzi":"得心应手","pinyin":"déxīn-yìngshǒu","meaning_vi":"thành thạo, làm đâu được đấy (lòng muốn sao tay làm được vậy)","explanation":"得心 (trong lòng nghĩ được) + 应手 (ứng thủ – tay làm theo được) → lòng muốn sao tay làm được vậy → làm việc thuần thục, trôi chảy, rất thạo tay.","hsk_level":6,"tags":["thanh-ngu"],"image":"✨","examples":[{"type":"basic","zh":"她工作得心应手。","pinyin":"Tā gōngzuò déxīnyìngshǒu.","vi":"Cô ấy làm việc rất trôi chảy thành thạo."},{"type":"simple","zh":"这把新菜刀用起来得心应手。","pinyin":"Zhè bǎ xīn càidāo yòng qǐlái déxīnyìngshǒu.","vi":"Con dao bếp mới này dùng rất thuận tay."},{"type":"compound","zh":"虽然刚开始手忙脚乱，但是一个月后他就得心应手了。","pinyin":"Suīrán gāng kāishǐ shǒumángjiǎoluàn, dànshì yí gèyuè hòu tā jiù déxīnyìngshǒu le.","vi":"Tuy lúc đầu luống cuống nhưng một tháng sau anh ấy đã làm thuần thục."}],"related":[{"hanzi":"熟能生巧","pinyin":"shúnéngshēngqiǎo","vi":"quen tay hay việc"},{"hanzi":"游刃有余","pinyin":"yóurènyǒuyú","vi":"thành thạo dư sức"},{"hanzi":"驾轻就熟","pinyin":"jiàqīngjiùshú","vi":"quen việc dễ làm"},{"hanzi":"力不从心","pinyin":"lìbùcóngxīn","vi":"lực bất tòng tâm"}],"traditional":"得心應手"},{"id":"地步","hanzi":"地步","pinyin":"dìbù","meaning_vi":"mức độ, tình trạng","explanation":"地 (địa – chỗ) + 步 (bộ – bước) → mức độ, tình cảnh (thường là xấu); cũng chỉ chỗ lùi. Thường gặp: 到了……的地步, 发展到这种地步.","hsk_level":6,"tags":["danh-tu"],"image":"📊","examples":[{"type":"basic","zh":"没想到会到这种地步。","pinyin":"Méi xiǎngdào huì dào zhè zhǒng dìbù.","vi":"Không ngờ lại đến nông nỗi này."},{"type":"simple","zh":"他穷到了连房租都交不起的地步。","pinyin":"Tā qióng dàole lián fángzū dōu jiāo bù qǐ de dìbù.","vi":"Anh ấy nghèo đến mức ngay cả tiền thuê nhà cũng không trả nổi."},{"type":"compound","zh":"如果当初多沟通，就不会走到今天这个地步。","pinyin":"Rúguǒ dāngchū duō gōutōng, jiù bú huì zǒu dào jīntiān zhè gè dìbù.","vi":"Nếu lúc đầu trao đổi nhiều hơn thì đã không đến nông nỗi như hôm nay."}],"related":[{"hanzi":"程度","pinyin":"chéngdù","vi":"mức độ"},{"hanzi":"境地","pinyin":"jìngdì","vi":"cảnh ngộ"},{"hanzi":"田地","pinyin":"tiándì","vi":"tình cảnh"},{"hanzi":"局面","pinyin":"júmiàn","vi":"cục diện"}]},{"id":"地地道道","hanzi":"地地道道","pinyin":"dìdìdàodào","meaning_vi":"chính gốc, chuẩn 100%","explanation":"Từ láy AABB.","hsk_level":6,"tags":["tinh-tu"],"image":"👍","examples":[{"type":"basic","zh":"他是地地道道的北京人。","pinyin":"Tā shì dìdìdàodào de Běijīngrén.","vi":"Anh ấy là người Bắc Kinh chính gốc."},{"type":"simple","zh":"这家小馆做的是地地道道的四川菜。","pinyin":"Zhè jiā xiǎo guǎn zuò de shì dìdìdàodào de sìchuāncài.","vi":"Quán nhỏ này nấu món Tứ Xuyên chuẩn vị."},{"type":"compound","zh":"虽然她在国外长大，但是说一口地地道道的普通话。","pinyin":"Suīrán tā zài guówài zhǎngdà, dànshì shuō yìkǒu dìdìdàodào de pǔtōnghuà.","vi":"Tuy lớn lên ở nước ngoài nhưng cô ấy nói tiếng phổ thông chuẩn trăm phần trăm."}],"related":[{"hanzi":"地道","pinyin":"dìdao","vi":"chính gốc"},{"hanzi":"正宗","pinyin":"zhèngzōng","vi":"chính tông"},{"hanzi":"纯正","pinyin":"chúnzhèng","vi":"thuần chính"},{"hanzi":"冒牌","pinyin":"màopái","vi":"hàng giả"}]},{"id":"地大物博","hanzi":"地大物博","pinyin":"dìdà-wùbó","meaning_vi":"đất rộng của nhiều (tài nguyên phong phú)","explanation":"地大 (đất rộng) + 物博 (vật bác – sản vật phong phú) → lãnh thổ rộng lớn, tài nguyên dồi dào. Thường dùng để nói về Trung Quốc hoặc một quốc gia lớn.","hsk_level":6,"tags":["thanh-ngu","thien-nhien"],"image":"🌍","examples":[{"type":"basic","zh":"中国地大物博。","pinyin":"Zhōngguó dìdàwùbó.","vi":"Trung Quốc đất rộng của nhiều."},{"type":"simple","zh":"这个地大物博的国家拥有丰富的矿产。","pinyin":"Zhè gè dìdàwùbó de guójiā yōngyǒu fēngfù de kuàngchǎn.","vi":"Đất nước đất rộng của nhiều này sở hữu khoáng sản phong phú."},{"type":"compound","zh":"虽然这里地大物博，但是我们也要节约资源。","pinyin":"Suīrán zhèlǐ dìdàwùbó, dànshì wǒmen yě yào jiéyuē zīyuán.","vi":"Tuy nơi đây đất rộng của nhiều nhưng chúng ta cũng phải tiết kiệm tài nguyên."}],"related":[{"hanzi":"物产丰富","pinyin":"wùchǎnfēngfù","vi":"sản vật phong phú"},{"hanzi":"资源","pinyin":"zīyuán","vi":"tài nguyên"},{"hanzi":"幅员辽阔","pinyin":"fúyuánliáokuò","vi":"lãnh thổ rộng lớn"},{"hanzi":"得天独厚","pinyin":"détiāndúhòu","vi":"được thiên nhiên ưu đãi"}]},{"id":"递增","hanzi":"递增","pinyin":"dìzēng","meaning_vi":"tăng dần lên","explanation":"递 (đệ – lần lượt, tuần tự) + 增 (tăng) → tăng dần theo từng bước, tăng lũy tiến. Trái nghĩa: 递减. Ví dụ: 逐年递增 (tăng dần qua từng năm).","hsk_level":6,"tags":["dong-tu"],"image":"📈","examples":[{"type":"basic","zh":"销量逐年递增。","pinyin":"Xiāoliàng zhúnián dìzēng.","vi":"Doanh số tăng dần qua từng năm."},{"type":"simple","zh":"这家网店的会员人数每月递增百分之十。","pinyin":"Zhè jiā wǎngdiàn de huìyuán rénshù měiyuè dìzēng bǎifēnzhī shí.","vi":"Số thành viên của cửa hàng trực tuyến này tăng dần mười phần trăm mỗi tháng."},{"type":"compound","zh":"如果客流量继续递增，我们就得多招几名店员。","pinyin":"Rúguǒ kèliúliàng jìxù dìzēng, wǒmen jiù děi duō zhāo jǐ míng diànyuán.","vi":"Nếu lượng khách tiếp tục tăng dần, chúng ta phải tuyển thêm vài nhân viên."}],"related":[{"hanzi":"递减","pinyin":"dìjiǎn","vi":"giảm dần"},{"hanzi":"增加","pinyin":"zēngjiā","vi":"tăng thêm"},{"hanzi":"逐年递增","pinyin":"zhúniándìzēng","vi":"tăng dần theo năm"},{"hanzi":"增长","pinyin":"zēngzhǎng","vi":"tăng trưởng"}],"traditional":"遞增"},{"id":"定义","hanzi":"定义","pinyin":"dìngyì","meaning_vi":"định nghĩa","explanation":"定 (định – xác định) + 义 (nghĩa) → xác định nội hàm của khái niệm, định nghĩa; dùng được cả danh từ và động từ. Ví dụ: 下定义 (đưa ra định nghĩa).","hsk_level":6,"tags":["danh-tu"],"image":"📖","examples":[{"type":"basic","zh":"这个定义不准确。","pinyin":"Zhè gè dìngyì bù zhǔnquè.","vi":"Định nghĩa này không chính xác."},{"type":"simple","zh":"每个人对幸福都有不同的定义。","pinyin":"Měigèrén duì xìngfú dōu yǒu bùtóng de dìngyì.","vi":"Mỗi người đều có định nghĩa khác nhau về hạnh phúc."},{"type":"compound","zh":"如果先弄懂了定义，后面的题目就容易多了。","pinyin":"Rúguǒ xiān nòngdǒngle dìngyì, hòumiàn de tímù jiù róngyì duō le.","vi":"Nếu hiểu rõ định nghĩa trước thì các bài phía sau sẽ dễ hơn nhiều."}],"related":[{"hanzi":"概念","pinyin":"gàiniàn","vi":"khái niệm"},{"hanzi":"下定义","pinyin":"xiàdìngyì","vi":"đưa ra định nghĩa"},{"hanzi":"含义","pinyin":"hányì","vi":"hàm nghĩa"},{"hanzi":"解释","pinyin":"jiěshì","vi":"giải thích"}],"traditional":"定義"},{"id":"敌视","hanzi":"敌视","pinyin":"díshì","meaning_vi":"coi là kẻ thù, nhìn với ánh mắt thù địch","explanation":"敌 (địch – kẻ thù) + 视 (thị – nhìn) → nhìn bằng con mắt thù địch, coi như kẻ thù. Ví dụ: 互相敌视, 敌视的眼光.","hsk_level":6,"tags":["dong-tu"],"image":"😠","examples":[{"type":"basic","zh":"他敌视一切外人。","pinyin":"Tā díshì yíqiè wàirén.","vi":"Hắn thù địch với mọi người ngoài."},{"type":"simple","zh":"那只流浪猫敌视地盯着陌生人。","pinyin":"Nà zhī liúlàngmāo díshì de dīngzhe mòshēngrén.","vi":"Con mèo hoang nhìn chằm chằm người lạ đầy thù địch."},{"type":"compound","zh":"虽然两家曾经互相敌视，但是现在已经和好了。","pinyin":"Suīrán liǎng jiā céngjīng hùxiāng díshì, dànshì xiànzài yǐjīng héhǎo le.","vi":"Tuy hai nhà từng thù địch nhau nhưng giờ đã làm lành rồi."}],"related":[{"hanzi":"仇视","pinyin":"chóushì","vi":"căm thù"},{"hanzi":"敌意","pinyin":"díyì","vi":"thù địch"},{"hanzi":"敌人","pinyin":"dírén","vi":"kẻ thù"},{"hanzi":"友好","pinyin":"yǒuhǎo","vi":"hữu hảo"}],"traditional":"敵視"},{"id":"洞察","hanzi":"洞察","pinyin":"dòngchá","meaning_vi":"nhìn thấu, thấu hiểu sâu sắc","explanation":"洞 (xuyên suốt) + 察 (xem xét).","hsk_level":6,"tags":["dong-tu","nhan-thuc"],"image":"👁️","examples":[{"type":"basic","zh":"他善于洞察人心。","pinyin":"Tā shànyú dòngchá rénxīn.","vi":"Anh ấy giỏi nhìn thấu lòng người."},{"type":"simple","zh":"优秀的记者能洞察社会的细微变化。","pinyin":"Yōuxiù de jìzhě néng dòngchá shèhuì de xìwēi biànhuà.","vi":"Phóng viên giỏi có thể nhìn thấu những biến đổi nhỏ của xã hội."},{"type":"compound","zh":"因为她洞察到了市场的需求，所以抢先推出了新产品。","pinyin":"Yīnwèi tā dòngchá dàole shìchǎng de xūqiú, suǒyǐ qiǎngxiān tuīchūle xīnchǎnpǐn.","vi":"Vì cô ấy đã nhìn thấu nhu cầu thị trường nên tung ra sản phẩm mới trước đối thủ."}],"related":[{"hanzi":"洞察力","pinyin":"dòngchálì","vi":"óc quan sát sâu sắc"},{"hanzi":"洞悉","pinyin":"dòngxī","vi":"hiểu rõ"},{"hanzi":"观察","pinyin":"guānchá","vi":"quan sát"},{"hanzi":"看透","pinyin":"kàntòu","vi":"nhìn thấu"}]},{"id":"动机","hanzi":"动机","pinyin":"dòngjī","meaning_vi":"động cơ","explanation":"动 (động – chuyển động, thúc đẩy) + 机 (cơ – then chốt, nguyên nhân) → nguyên nhân thúc đẩy hành động, động cơ. Ví dụ: 学习动机, 犯罪动机, 动机不纯.","hsk_level":6,"tags":["danh-tu"],"image":"💡","examples":[{"type":"basic","zh":"他的动机不纯。","pinyin":"Tā de dòngjī bù chún.","vi":"Động cơ của hắn không trong sáng."},{"type":"simple","zh":"警方正在调查嫌疑人的作案动机。","pinyin":"Jǐngfāng zhèngzài diàochá xiányírén de zuò'àn dòngjī.","vi":"Cảnh sát đang điều tra động cơ gây án của nghi phạm."},{"type":"compound","zh":"即使动机是好的，方法不对也会造成伤害。","pinyin":"Jíshǐ dòngjī shì hǎo de, fāngfǎ bú duì yě huì zàochéng shānghài.","vi":"Cho dù động cơ là tốt, phương pháp sai cũng sẽ gây tổn thương."}],"related":[{"hanzi":"目的","pinyin":"mùdì","vi":"mục đích"},{"hanzi":"意图","pinyin":"yìtú","vi":"ý đồ"},{"hanzi":"动力","pinyin":"dònglì","vi":"động lực"},{"hanzi":"作案动机","pinyin":"zuò'àndòngjī","vi":"động cơ gây án"}],"traditional":"動機"},{"id":"动脉","hanzi":"动脉","pinyin":"dòngmài","meaning_vi":"động mạch","explanation":"动 (động – đập) + 脉 (mạch – mạch máu) → mạch máu đưa máu từ tim đi khắp cơ thể, động mạch; nghĩa bóng: tuyến giao thông huyết mạch. Đối: 静脉 (tĩnh mạch).","hsk_level":6,"tags":["danh-tu","co-the"],"image":"🫀","examples":[{"type":"basic","zh":"动脉被堵住了。","pinyin":"Dòngmài bèi dǔzhù le.","vi":"Động mạch bị tắc rồi."},{"type":"simple","zh":"医生在他的颈动脉里发现了斑块。","pinyin":"Yīshēng zài tā de jǐngdòngmài lǐ fāxiànle bānkuài.","vi":"Bác sĩ phát hiện mảng bám trong động mạch cảnh của ông ấy."},{"type":"compound","zh":"如果动脉长期硬化，就容易引发心脏病。","pinyin":"Rúguǒ dòngmài chángqī yìnghuà, jiù róngyì yǐnfā xīnzàngbìng.","vi":"Nếu động mạch bị xơ cứng lâu ngày thì dễ dẫn đến bệnh tim."}],"related":[{"hanzi":"静脉","pinyin":"jìngmài","vi":"tĩnh mạch"},{"hanzi":"血管","pinyin":"xuèguǎn","vi":"mạch máu"},{"hanzi":"心脏","pinyin":"xīnzàng","vi":"tim"},{"hanzi":"血液","pinyin":"xuèyè","vi":"máu"}],"traditional":"動脈"},{"id":"动态","hanzi":"动态","pinyin":"dòngtài","meaning_vi":"động thái","explanation":"动 (động – chuyển động) + 态 (thái – trạng thái) → tình hình biến đổi, diễn biến mới; cũng là tính từ 'động' (đối với 静态). Ví dụ: 市场动态, 朋友圈动态.","hsk_level":6,"tags":["danh-tu"],"image":"📊","examples":[{"type":"basic","zh":"请关注最新动态。","pinyin":"Qǐng guānzhù zuì xīn dòngtài.","vi":"Xin hãy theo dõi động thái mới nhất."},{"type":"simple","zh":"她每天晚上都在朋友圈发生活动态。","pinyin":"Tā měitiān wǎnshang dōu zài péngyouquān fāshēng huódòng tài.","vi":"Tối nào cô ấy cũng đăng trạng thái về cuộc sống lên vòng bạn bè."},{"type":"compound","zh":"只要密切留意对手的动态，我们就不会措手不及。","pinyin":"Zhǐyào mìqiè liúyì duìshǒu de dòngtài, wǒmen jiù bú huì cuòshǒubùjí.","vi":"Chỉ cần theo dõi sát động thái của đối thủ, chúng ta sẽ không bị trở tay không kịp."}],"related":[{"hanzi":"静态","pinyin":"jìngtài","vi":"tĩnh thái"},{"hanzi":"动向","pinyin":"dòngxiàng","vi":"xu hướng"},{"hanzi":"变化","pinyin":"biànhuà","vi":"thay đổi"},{"hanzi":"最新动态","pinyin":"zuìxīndòngtài","vi":"động thái mới nhất"}],"traditional":"動態"},{"id":"洞悉","hanzi":"洞悉","pinyin":"dòngxī","meaning_vi":"hiểu rõ tường tận","explanation":"洞 + 悉 (biết rõ).","hsk_level":6,"tags":["dong-tu"],"image":"💡","examples":[{"type":"basic","zh":"他洞悉一切。","pinyin":"Tā dòngxī yíqiè.","vi":"Ông ấy hiểu rõ tường tận mọi chuyện."},{"type":"simple","zh":"老侦探一眼就洞悉了凶手的诡计。","pinyin":"Lǎo zhēntàn yìyǎn jiù dòngxīle xiōngshǒu de guǐjì.","vi":"Viên thám tử già chỉ nhìn một cái đã hiểu thấu mưu kế của hung thủ."},{"type":"compound","zh":"虽然他洞悉其中的秘密，却始终守口如瓶。","pinyin":"Suīrán tā dòngxī qízhōng de mìmì, què shǐzhōng shǒu kǒu rú píng.","vi":"Tuy anh ấy biết tường tận bí mật bên trong nhưng trước sau vẫn kín miệng như bưng."}],"related":[{"hanzi":"洞察","pinyin":"dòngchá","vi":"nhìn thấu"},{"hanzi":"了解","pinyin":"liǎojiě","vi":"hiểu"},{"hanzi":"熟悉","pinyin":"shúxī","vi":"quen thuộc"},{"hanzi":"一无所知","pinyin":"yìwúsuǒzhī","vi":"không biết gì"}]},{"id":"斗争","hanzi":"斗争","pinyin":"dòuzhēng","meaning_vi":"đấu tranh","explanation":"斗 (đấu – đánh nhau, đọc dòu) + 争 (tranh – giành) → đấu tranh chống lại, đấu tranh giành lấy. Thường gặp: 与疾病斗争, 阶级斗争, 斗争到底.","hsk_level":6,"tags":["dong-tu"],"image":"✊","examples":[{"type":"basic","zh":"他们坚持斗争。","pinyin":"Tāmen jiānchí dòuzhēng.","vi":"Họ kiên trì đấu tranh."},{"type":"simple","zh":"工人们为了提高工资和老板进行了斗争。","pinyin":"Gōngrénmen wèile tígāo gōngzī hé lǎobǎn jìnxíngle dòuzhēng.","vi":"Công nhân đã đấu tranh với ông chủ để được tăng lương."},{"type":"compound","zh":"虽然跟病魔斗争了三年，但是她始终没有放弃。","pinyin":"Suīrán gēn bìngmó dòuzhēngle sān nián, dànshì tā shǐzhōng méiyǒu fàngqì.","vi":"Tuy phải chiến đấu với bệnh tật ba năm nhưng cô ấy chưa bao giờ bỏ cuộc."}],"related":[{"hanzi":"奋斗","pinyin":"fèndòu","vi":"phấn đấu"},{"hanzi":"战斗","pinyin":"zhàndòu","vi":"chiến đấu"},{"hanzi":"抗争","pinyin":"kàngzhēng","vi":"đấu tranh chống lại"},{"hanzi":"妥协","pinyin":"tuǒxié","vi":"thỏa hiệp"}],"traditional":"鬥爭"},{"id":"度日如年","hanzi":"度日如年","pinyin":"dùrì-rúnián","meaning_vi":"một ngày dài như một năm (sốt ruột/khổ sở)","explanation":"度日 (độ nhật – sống qua một ngày) + 如年 (như một năm) → một ngày dài như một năm → tả cảnh sống khổ sở hoặc chờ đợi sốt ruột.","hsk_level":6,"tags":["thanh-ngu","thoi-gian"],"image":"⏳","examples":[{"type":"basic","zh":"等待让人度日如年。","pinyin":"Děngdài ràng rén dùrìrúnián.","vi":"Chờ đợi khiến người ta thấy một ngày dài như một năm."},{"type":"simple","zh":"住院的那段时间他觉得度日如年。","pinyin":"Zhùyuàn de nà duàn shíjiān tā juéde dùrìrúnián.","vi":"Thời gian nằm viện đó anh ấy thấy một ngày dài như một năm."},{"type":"compound","zh":"自从儿子出国留学，她就天天度日如年地盼着他回来。","pinyin":"Zìcóng érzi chūguó liúxué, tā jiù tiāntiān dùrìrúnián de pànzhe tā huílái.","vi":"Từ khi con trai đi du học, ngày nào bà cũng mỏi mòn ngóng con về."}],"related":[{"hanzi":"一日三秋","pinyin":"yīrìsānqiū","vi":"một ngày như ba thu"},{"hanzi":"煎熬","pinyin":"jiān'áo","vi":"giày vò"},{"hanzi":"光阴似箭","pinyin":"guāngyīnsìjiàn","vi":"thời gian như tên bay"},{"hanzi":"难熬","pinyin":"nán'áo","vi":"khó chịu đựng"}]},{"id":"独裁","hanzi":"独裁","pinyin":"dúcái","meaning_vi":"độc tài","explanation":"独 (độc – một mình) + 裁 (tài – quyết định, phán xét) → một người nắm hết quyền quyết định, độc tài. Thường gặp: 独裁者, 独裁统治.","hsk_level":6,"tags":["tinh-tu"],"image":"👑","examples":[{"type":"basic","zh":"这位老板很独裁。","pinyin":"Zhè wèi lǎobǎn hěn dúcái.","vi":"Ông chủ này rất độc đoán."},{"type":"simple","zh":"人民推翻了那个独裁的政府。","pinyin":"Rénmín tuīfānle nà gè dúcái de zhèngfǔ.","vi":"Nhân dân đã lật đổ chính phủ độc tài đó."},{"type":"compound","zh":"如果经理太独裁，员工就不敢说出真实想法。","pinyin":"Rúguǒ jīnglǐ tài dúcái, yuángōng jiù bù gǎn shuōchū zhēnshí xiǎngfǎ.","vi":"Nếu giám đốc quá độc đoán thì nhân viên sẽ không dám nói ra suy nghĩ thật."}],"related":[{"hanzi":"专制","pinyin":"zhuānzhì","vi":"chuyên chế"},{"hanzi":"独裁者","pinyin":"dúcáizhě","vi":"kẻ độc tài"},{"hanzi":"民主","pinyin":"mínzhǔ","vi":"dân chủ"},{"hanzi":"集权","pinyin":"jíquán","vi":"tập quyền"}],"traditional":"獨裁"},{"id":"独具匠心","hanzi":"独具匠心","pinyin":"dújù-jiàngxīn","meaning_vi":"có sự sáng tạo tinh xảo độc đáo","explanation":"独具 (độc cụ – riêng có) + 匠心 (tượng tâm – tâm huyết khéo léo của người thợ) → có ý tưởng, cách làm sáng tạo độc đáo. Thường khen tác phẩm, thiết kế.","hsk_level":6,"tags":["thanh-ngu"],"image":"🎨","examples":[{"type":"basic","zh":"设计独具匠心。","pinyin":"Shèjì dújùjiàngxīn.","vi":"Thiết kế vô cùng độc đáo tinh xảo."},{"type":"simple","zh":"这座园林的布局可谓独具匠心。","pinyin":"Zhè zuò yuánlín de bùjú kěwèi dújùjiàngxīn.","vi":"Bố cục của khu vườn này có thể nói là độc đáo tinh xảo."},{"type":"compound","zh":"这份礼物虽然不贵，但是包装独具匠心。","pinyin":"Zhè fèn lǐwù suīrán bú guì, dànshì bāozhuāng dújùjiàngxīn.","vi":"Món quà này tuy không đắt nhưng cách gói rất độc đáo tinh tế."}],"related":[{"hanzi":"别具匠心","pinyin":"biéjùjiàngxīn","vi":"khéo léo độc đáo"},{"hanzi":"匠心独运","pinyin":"jiàngxīndúyùn","vi":"tâm huyết riêng có"},{"hanzi":"别出心裁","pinyin":"biéchūxīncái","vi":"sáng tạo độc đáo"},{"hanzi":"千篇一律","pinyin":"qiānpiānyílǜ","vi":"rập khuôn như nhau"}],"traditional":"獨具匠心"},{"id":"独一无二","hanzi":"独一无二","pinyin":"dúyì-wú'èr","meaning_vi":"độc nhất vô nhị","explanation":"独一 (độc nhất – chỉ có một) + 无二 (vô nhị – không có cái thứ hai) → duy nhất, không gì sánh được, độc nhất vô nhị.","hsk_level":6,"tags":["thanh-ngu"],"image":"1️⃣","examples":[{"type":"basic","zh":"你是独一无二的。","pinyin":"Nǐ shì dúyìwú'èr de.","vi":"Bạn là độc nhất vô nhị."},{"type":"simple","zh":"每片雪花的形状都是独一无二的。","pinyin":"Měi piàn xuěhuā de xíngzhuàng dōu shì dúyìwú'èr de.","vi":"Hình dạng của mỗi bông tuyết đều là độc nhất vô nhị."},{"type":"compound","zh":"因为这块手表是手工打造的，所以独一无二。","pinyin":"Yīnwèi zhè kuài shǒubiǎo shì shǒugōng dǎzào de, suǒyǐ dúyìwú'èr.","vi":"Vì chiếc đồng hồ này được chế tác thủ công nên là độc nhất vô nhị."}],"related":[{"hanzi":"举世无双","pinyin":"jǔshìwúshuāng","vi":"có một không hai"},{"hanzi":"绝无仅有","pinyin":"juéwújǐnyǒu","vi":"độc nhất"},{"hanzi":"唯一","pinyin":"wéiyī","vi":"duy nhất"},{"hanzi":"比比皆是","pinyin":"bǐbǐjiēshì","vi":"đâu đâu cũng có"}],"traditional":"獨一無二"},{"id":"搭","hanzi":"搭","pinyin":"dā","meaning_vi":"dựng, bắc; đi nhờ (xe); phối, kết hợp","explanation":"搭 (đáp): dựng, bắc (lều, cầu); đi nhờ, đi (xe, tàu); phối hợp, kết hợp. Từ ghép: 搭车, 搭桥, 搭配 (phối hợp), 搭档 (cộng sự).","hsk_level":6,"tags":["dong-tu"],"image":"🚗","examples":[{"type":"basic","zh":"我搭朋友的车。","pinyin":"Wǒ dā péngyou de chē.","vi":"Tôi đi nhờ xe bạn."},{"type":"simple","zh":"工人们在广场上搭了一个大舞台。","pinyin":"Gōngrénmen zài guǎngchǎng shàng dāle yí gè dà wǔtái.","vi":"Công nhân dựng một sân khấu lớn trên quảng trường."},{"type":"compound","zh":"这件白衬衫既能搭裙子，又能搭牛仔裤。","pinyin":"Zhè jiàn bái chènshān jì néng dā qúnzi, yòu néng dā niúzǎikù.","vi":"Chiếc áo sơ mi trắng này vừa có thể phối với váy vừa có thể phối với quần jeans."}],"related":[{"hanzi":"搭车","pinyin":"dāchē","vi":"đi nhờ xe"},{"hanzi":"搭配","pinyin":"dāpèi","vi":"phối hợp"},{"hanzi":"搭建","pinyin":"dājiàn","vi":"dựng"},{"hanzi":"搭档","pinyin":"dādàng","vi":"cộng sự"}]},{"id":"搭理","hanzi":"搭理","pinyin":"dāli","meaning_vi":"bắt chuyện, để ý tới","explanation":"搭 + 理 (để ý).","hsk_level":6,"tags":["dong-tu","giao-tiep"],"image":"🗣️","examples":[{"type":"basic","zh":"你别搭理他。","pinyin":"Nǐ bié dāli tā.","vi":"Bạn đừng để ý đến anh ta."},{"type":"simple","zh":"她生气了一整天都不搭理我。","pinyin":"Tā shēngqìle yìzhěngtiān dōu bù dāli wǒ.","vi":"Cô ấy giận, cả ngày chẳng thèm nói chuyện với tôi."},{"type":"compound","zh":"如果你一直不搭理她，她就会更伤心。","pinyin":"Rúguǒ nǐ yìzhí bù dāli tā, tā jiù huì gèng shāngxīn.","vi":"Nếu bạn cứ không đoái hoài đến cô ấy thì cô ấy sẽ càng buồn."}],"related":[{"hanzi":"理睬","pinyin":"lǐcǎi","vi":"để ý tới"},{"hanzi":"理会","pinyin":"lǐhuì","vi":"quan tâm"},{"hanzi":"不理","pinyin":"bùlǐ","vi":"phớt lờ"},{"hanzi":"答理","pinyin":"dāli","vi":"đáp lời"}]},{"id":"呆板","hanzi":"呆板","pinyin":"dāibǎn","meaning_vi":"cứng nhắc, máy móc, thiếu linh hoạt","explanation":"呆 (ngây) + 板 (tấm ván).","hsk_level":6,"tags":["tinh-tu"],"image":"🤖","examples":[{"type":"basic","zh":"他说话很呆板。","pinyin":"Tā shuōhuà hěn dāibǎn.","vi":"Anh ấy nói chuyện rất cứng nhắc."},{"type":"simple","zh":"这张证件照拍得表情有点呆板。","pinyin":"Zhè zhāng zhèngjiànzhào pāi de biǎoqíng yǒudiǎn dāibǎn.","vi":"Bức ảnh thẻ này chụp biểu cảm hơi đơ cứng."},{"type":"compound","zh":"虽然规章制度很重要，但是执行起来不能太呆板。","pinyin":"Suīrán guīzhāng zhìdù hěn zhòngyào, dànshì zhíxíng qǐlái bù néng tài dāibǎn.","vi":"Tuy nội quy rất quan trọng nhưng khi thực hiện không thể quá máy móc."}],"related":[{"hanzi":"死板","pinyin":"sǐbǎn","vi":"cứng nhắc"},{"hanzi":"僵硬","pinyin":"jiāngyìng","vi":"cứng đờ"},{"hanzi":"机械","pinyin":"jīxiè","vi":"máy móc"},{"hanzi":"灵活","pinyin":"línghuó","vi":"linh hoạt"}]},{"id":"呆若木鸡","hanzi":"呆若木鸡","pinyin":"dāiruò-mùjī","meaning_vi":"ngây như phỗng (đứng đờ ra vì kinh ngạc)","explanation":"呆若木鸡: ngây như gà gỗ (Trang Tử: gà chọi luyện đến mức đứng im như gà gỗ) → nay ví người sững sờ, đứng đờ ra vì sợ hãi hay kinh ngạc.","hsk_level":6,"tags":["thanh-ngu"],"image":"🐔","examples":[{"type":"basic","zh":"他呆若木鸡。","pinyin":"Tā dāiruòmùjī.","vi":"Anh ấy đứng ngây như phỗng."},{"type":"simple","zh":"听到中奖的消息她呆若木鸡地站着。","pinyin":"Tīngdào zhòngjiǎng de xiāoxi tā dāiruòmùjī de zhàn zhe.","vi":"Nghe tin trúng thưởng, cô ấy đứng ngây ra như phỗng."},{"type":"compound","zh":"他一看到考试成绩，就呆若木鸡地愣在那里。","pinyin":"Tā yí kàndào kǎoshì chéngjì, jiù dāiruòmùjī de lèng zài nàlǐ.","vi":"Cậu ấy vừa nhìn thấy điểm thi liền đứng sững ra như phỗng."}],"related":[{"hanzi":"目瞪口呆","pinyin":"mùdèngkǒudāi","vi":"trợn mắt há mồm"},{"hanzi":"发呆","pinyin":"fādāi","vi":"ngẩn người"},{"hanzi":"惊呆","pinyin":"jīngdāi","vi":"sững sờ"},{"hanzi":"愣住","pinyin":"lèngzhù","vi":"đứng sững"}],"traditional":"呆若木雞"},{"id":"担保","hanzi":"担保","pinyin":"dānbǎo","meaning_vi":"bảo lãnh","explanation":"担 (đảm – gánh vác) + 保 (bảo – bảo đảm) → đứng ra bảo đảm, chịu trách nhiệm thay; bảo lãnh. Ví dụ: 我担保他没问题, 担保人, 贷款担保.","hsk_level":6,"tags":["dong-tu"],"image":"✍️","examples":[{"type":"basic","zh":"我给你担保。","pinyin":"Wǒ gěi nǐ dānbǎo.","vi":"Tôi bảo lãnh cho bạn."},{"type":"simple","zh":"叔叔为我的助学贷款做了担保。","pinyin":"Shūshu wèi wǒ de zhùxué dàikuǎn zuòle dānbǎo.","vi":"Chú tôi đã đứng ra bảo lãnh khoản vay hỗ trợ học tập của tôi."},{"type":"compound","zh":"如果没有人担保，银行就不会批这笔贷款。","pinyin":"Rúguǒ méiyǒu rén dānbǎo, yínháng jiù bú huì pī zhè bǐ dàikuǎn.","vi":"Nếu không có ai bảo lãnh thì ngân hàng sẽ không duyệt khoản vay này."}],"related":[{"hanzi":"保证","pinyin":"bǎozhèng","vi":"bảo đảm"},{"hanzi":"担保人","pinyin":"dānbǎorén","vi":"người bảo lãnh"},{"hanzi":"抵押","pinyin":"dǐyā","vi":"thế chấp"},{"hanzi":"贷款","pinyin":"dàikuǎn","vi":"khoản vay"}],"traditional":"擔保"},{"id":"单枪匹马","hanzi":"单枪匹马","pinyin":"dānqiāng-pǐmǎ","meaning_vi":"đơn thương độc mã","explanation":"单枪 (đơn thương – một cây giáo) + 匹马 (thất mã – một con ngựa) → một mình xông trận → ví một mình làm việc, không ai giúp đỡ.","hsk_level":6,"tags":["thanh-ngu"],"image":"🐎","examples":[{"type":"basic","zh":"他单枪匹马去谈判。","pinyin":"Tā dānqiāngpǐmǎ qù tánpàn.","vi":"Anh ấy đơn thương độc mã đi đàm phán."},{"type":"simple","zh":"她单枪匹马在异国开了一家小店。","pinyin":"Tā dānqiāngpǐmǎ zài yìguó kāile yìjiā xiǎodiàn.","vi":"Cô ấy một mình mở một cửa hàng nhỏ nơi đất khách."},{"type":"compound","zh":"与其单枪匹马地硬拼，不如找几个伙伴一起干。","pinyin":"Yǔqí dānqiāngpǐmǎ de yìng pīn, bùrú zhǎo jǐ gè huǒbàn yìqǐ gàn.","vi":"Thay vì đơn thương độc mã liều mình, chi bằng tìm vài cộng sự cùng làm."}],"related":[{"hanzi":"孤军奋战","pinyin":"gūjūnfènzhàn","vi":"đơn độc chiến đấu"},{"hanzi":"独自","pinyin":"dúzì","vi":"một mình"},{"hanzi":"齐心协力","pinyin":"qíxīnxiélì","vi":"đồng tâm hiệp lực"},{"hanzi":"单独","pinyin":"dāndú","vi":"đơn độc"}],"traditional":"單槍匹馬"},{"id":"丹青","hanzi":"丹青","pinyin":"dānqīng","meaning_vi":"hội họa (tranh thủy mặc)","explanation":"丹 (màu đỏ) + 青 (màu xanh).","hsk_level":6,"tags":["danh-tu","van-hoa"],"image":"🎨","examples":[{"type":"basic","zh":"他擅长丹青。","pinyin":"Tā shàncháng dānqīng.","vi":"Ông ấy giỏi hội họa."},{"type":"simple","zh":"这位老人退休后一直潜心研习丹青。","pinyin":"Zhè wèi lǎorén tuìxiū hòu yìzhí qiánxīn yánxí dānqīng.","vi":"Cụ già này sau khi nghỉ hưu luôn chuyên tâm học vẽ tranh."},{"type":"compound","zh":"他不但精通丹青，而且写得一手好字。","pinyin":"Tā búdàn jīngtōng dānqīng, érqiě xiě de yìshǒu hǎo zì.","vi":"Ông ấy không những tinh thông hội họa mà còn viết chữ rất đẹp."}],"related":[{"hanzi":"绘画","pinyin":"huìhuà","vi":"hội họa"},{"hanzi":"国画","pinyin":"guóhuà","vi":"tranh quốc họa"},{"hanzi":"水墨画","pinyin":"shuǐmòhuà","vi":"tranh thủy mặc"},{"hanzi":"画家","pinyin":"huàjiā","vi":"họa sĩ"}]},{"id":"丹心","hanzi":"丹心","pinyin":"dānxīn","meaning_vi":"tấm lòng son sắt trung thành","explanation":"丹 (đỏ son) + 心 (tim).","hsk_level":6,"tags":["danh-tu","van-hoa"],"image":"❤️","examples":[{"type":"basic","zh":"他一片丹心报国。","pinyin":"Tā yípiàn dānxīn bàoguó.","vi":"Ông ấy một lòng son sắt báo quốc."},{"type":"simple","zh":"老将军用一生诠释了报国的丹心。","pinyin":"Lǎojiāng jūnyòng yìshēng quánshìle bàoguó de dānxīn.","vi":"Vị lão tướng dùng cả cuộc đời để thể hiện tấm lòng son báo quốc."},{"type":"compound","zh":"虽然他身处逆境，但是一颗丹心始终不变。","pinyin":"Suīrán tā shēnchǔ nìjìng, dànshì yì kē dānxīn shǐzhōng búbiàn.","vi":"Tuy ở trong nghịch cảnh nhưng tấm lòng son của ông ấy trước sau không đổi."}],"related":[{"hanzi":"忠心","pinyin":"zhōngxīn","vi":"lòng trung thành"},{"hanzi":"赤胆忠心","pinyin":"chìdǎnzhōngxīn","vi":"lòng son dạ sắt"},{"hanzi":"一片丹心","pinyin":"yípiàndānxīn","vi":"một tấm lòng son"},{"hanzi":"忠诚","pinyin":"zhōngchéng","vi":"trung thành"}]},{"id":"当场","hanzi":"当场","pinyin":"dāngchǎng","meaning_vi":"ngay tại chỗ","explanation":"当 (đương – ngay tại) + 场 (trường – nơi, hiện trường) → ngay tại chỗ, ngay lúc đó. Ví dụ: 当场抓住 (bắt quả tang), 当场死亡.","hsk_level":6,"tags":["pho-tu"],"image":"📍","examples":[{"type":"basic","zh":"小偷被当场抓住。","pinyin":"Xiǎotōu bèi dāngchǎng zhuāzhù.","vi":"Tên trộm bị bắt ngay tại chỗ."},{"type":"simple","zh":"评委当场宣布了比赛的冠军。","pinyin":"Píngwěi dāngchǎng xuānbùle bǐsài de guànjūn.","vi":"Ban giám khảo công bố nhà vô địch ngay tại chỗ."},{"type":"compound","zh":"他一听到这个笑话，就当场笑出了声。","pinyin":"Tā yì tīngdào zhè gè xiàohua, jiù dāngchǎng xiào chūle shēng.","vi":"Anh ấy vừa nghe câu chuyện cười liền bật cười thành tiếng ngay tại chỗ."}],"related":[{"hanzi":"当面","pinyin":"dāngmiàn","vi":"trước mặt"},{"hanzi":"现场","pinyin":"xiànchǎng","vi":"hiện trường"},{"hanzi":"当即","pinyin":"dāngjí","vi":"ngay lập tức"},{"hanzi":"事后","pinyin":"shìhòu","vi":"sau sự việc"}],"traditional":"當場"},{"id":"当机立断","hanzi":"当机立断","pinyin":"dāngjī-lìduàn","meaning_vi":"quyết đoán kịp thời, chớp thời cơ quyết định ngay","explanation":"当机 (đương cơ – đúng thời cơ) + 立断 (lập đoạn – quyết ngay) → nắm đúng thời cơ, quyết định dứt khoát ngay không do dự.","hsk_level":6,"tags":["thanh-ngu"],"image":"⚡","examples":[{"type":"basic","zh":"他当机立断。","pinyin":"Tā dāngjīlìduàn.","vi":"Anh ấy quyết định ngay lập tức."},{"type":"simple","zh":"船长当机立断下令全体弃船。","pinyin":"Chuánzhǎng dāngjīlìduàn xiàlìng quántǐ qìchuán.","vi":"Thuyền trưởng quyết đoán ra lệnh toàn bộ bỏ tàu."},{"type":"compound","zh":"要不是经理当机立断，公司就会损失更多。","pinyin":"Yàobúshì jīnglǐ dāngjīlìduàn, gōngsī jiù huì sǔnshī gèng duō.","vi":"Nếu không nhờ giám đốc quyết đoán kịp thời thì công ty đã thiệt hại nhiều hơn."}],"related":[{"hanzi":"果断","pinyin":"guǒduàn","vi":"quả quyết"},{"hanzi":"斩钉截铁","pinyin":"zhǎndīngjiétiě","vi":"dứt khoát"},{"hanzi":"优柔寡断","pinyin":"yōuróuguǎduàn","vi":"do dự thiếu quyết đoán"},{"hanzi":"犹豫不决","pinyin":"yóuyùbùjué","vi":"do dự không quyết"}],"traditional":"當機立斷"},{"id":"当前","hanzi":"当前","pinyin":"dāngqián","meaning_vi":"hiện tại, trước mắt","explanation":"当 (đương – đang, hiện) + 前 (tiền – trước mắt) → hiện nay, trước mắt; trang trọng hơn 现在. Thường gặp: 当前形势, 当前任务.","hsk_level":6,"tags":["danh-tu","thoi-gian"],"image":"⌚","examples":[{"type":"basic","zh":"当前形势很好。","pinyin":"Dāngqián xíngshì hěn hǎo.","vi":"Tình hình hiện tại rất tốt."},{"type":"simple","zh":"找工作是毕业生当前最关心的问题。","pinyin":"Zhǎogōngzuò shì bìyèshēng dāngqián zuì guānxīn de wèntí.","vi":"Tìm việc là vấn đề sinh viên tốt nghiệp quan tâm nhất hiện nay."},{"type":"compound","zh":"虽然当前困难不少，但是前景还是光明的。","pinyin":"Suīrán dāngqián kùnnan bùshǎo, dànshì qiánjǐng háishì guāngmíng de.","vi":"Tuy trước mắt khó khăn không ít nhưng triển vọng vẫn tươi sáng."}],"related":[{"hanzi":"目前","pinyin":"mùqián","vi":"hiện nay"},{"hanzi":"眼前","pinyin":"yǎnqián","vi":"trước mắt"},{"hanzi":"现在","pinyin":"xiànzài","vi":"bây giờ"},{"hanzi":"当下","pinyin":"dāngxià","vi":"hiện tại"}],"traditional":"當前"},{"id":"当仁不让","hanzi":"当仁不让","pinyin":"dāngrén-búràng","meaning_vi":"việc nghĩa không nhường ai, sẵn sàng gánh vác","explanation":"当仁 (gặp việc nhân nghĩa) + 不让 (không nhường) → gặp việc nên làm thì chủ động gánh vác, không nhường ai (Luận Ngữ: 当仁不让于师).","hsk_level":6,"tags":["thanh-ngu"],"image":"🦸","examples":[{"type":"basic","zh":"这件事我当仁不让。","pinyin":"Zhè jiàn shì wǒ dāngrénbúràng.","vi":"Việc này tôi sẵn sàng gánh vác."},{"type":"simple","zh":"遇到救人的事他总是当仁不让。","pinyin":"Yùdào jiùrén de shì tā zǒngshì dāngrénbúràng.","vi":"Gặp việc cứu người anh ấy luôn xông lên không nhường ai."},{"type":"compound","zh":"既然大家推选了我，我就当仁不让了。","pinyin":"Jìrán dàjiā tuīxuǎnle wǒ, wǒ jiù dāngrénbúràng le.","vi":"Đã được mọi người đề cử thì tôi xin không chối từ."}],"related":[{"hanzi":"义不容辞","pinyin":"yìbùróngcí","vi":"việc nghĩa không thể chối"},{"hanzi":"责无旁贷","pinyin":"zéwúpángdài","vi":"trách nhiệm không thể đùn đẩy"},{"hanzi":"推辞","pinyin":"tuīcí","vi":"từ chối"},{"hanzi":"挺身而出","pinyin":"tǐngshēn'érchū","vi":"đứng ra gánh vác"}],"traditional":"當仁不讓"},{"id":"当选","hanzi":"当选","pinyin":"dāngxuǎn","meaning_vi":"trúng cử","explanation":"当 (đương – đảm nhận) + 选 (tuyển – bầu chọn) → được bầu, trúng cử. Ví dụ: 当选总统, 当选为班长.","hsk_level":6,"tags":["dong-tu"],"image":"🗳️","examples":[{"type":"basic","zh":"他当选为班长。","pinyin":"Tā dāngxuǎn wéi bānzhǎng.","vi":"Cậu ấy được bầu làm lớp trưởng."},{"type":"simple","zh":"她以高票当选为新一届市长。","pinyin":"Tā yǐ gāo piào dāngxuǎn wéi xīn yí jiè shìzhǎng.","vi":"Bà ấy trúng cử thị trưởng nhiệm kỳ mới với số phiếu cao."},{"type":"compound","zh":"如果他当选了，就会先解决停车难的问题。","pinyin":"Rúguǒ tā dāngxuǎn le, jiù huì xiān jiějué tíngchē nán de wèntí.","vi":"Nếu ông ấy trúng cử thì sẽ giải quyết vấn đề khó đỗ xe trước tiên."}],"related":[{"hanzi":"选举","pinyin":"xuǎnjǔ","vi":"bầu cử"},{"hanzi":"落选","pinyin":"luòxuǎn","vi":"trượt bầu cử"},{"hanzi":"候选人","pinyin":"hòuxuǎnrén","vi":"ứng cử viên"},{"hanzi":"投票","pinyin":"tóupiào","vi":"bỏ phiếu"}],"traditional":"當選"},{"id":"当之无愧","hanzi":"当之无愧","pinyin":"dāngzhī-wúkuì","meaning_vi":"xứng đáng không hổ thẹn","explanation":"当之无愧: nhận lấy mà không hổ thẹn → hoàn toàn xứng đáng với danh hiệu, lời khen. Ví dụ: 他是当之无愧的冠军.","hsk_level":6,"tags":["thanh-ngu"],"image":"🏆","examples":[{"type":"basic","zh":"他当之无愧。","pinyin":"Tā dāngzhīwúkuì.","vi":"Anh ấy hoàn toàn xứng đáng."},{"type":"simple","zh":"她是当之无愧的年度最佳演员。","pinyin":"Tā shì dāngzhīwúkuì de niándù zuì jiā yǎnyuán.","vi":"Cô ấy là nữ diễn viên xuất sắc nhất năm hoàn toàn xứng đáng."},{"type":"compound","zh":"因为他救了三个孩子，所以英雄称号当之无愧。","pinyin":"Yīnwèi tā jiùle sān gè háizi, suǒyǐ yīngxióng chēnghào dāngzhīwúkuì.","vi":"Vì anh ấy đã cứu ba đứa trẻ nên danh hiệu anh hùng hoàn toàn xứng đáng."}],"related":[{"hanzi":"受之无愧","pinyin":"shòuzhīwúkuì","vi":"nhận mà không hổ thẹn"},{"hanzi":"名副其实","pinyin":"míngfùqíshí","vi":"danh xứng với thực"},{"hanzi":"不愧","pinyin":"búkuì","vi":"xứng đáng"},{"hanzi":"名不副实","pinyin":"míngbúfùshí","vi":"danh không xứng thực"}],"traditional":"當之無愧"},{"id":"刀刃","hanzi":"刀刃","pinyin":"dāorèn","meaning_vi":"lưỡi dao; chỗ then chốt (nơi cần dùng nhất)","explanation":"刀 (dao) + 刃 (lưỡi bén).","hsk_level":6,"tags":["danh-tu","do-vat"],"image":"🔪","examples":[{"type":"basic","zh":"刀刃很锋利。","pinyin":"Dāorèn hěn fēnglì.","vi":"Lưỡi dao rất sắc."},{"type":"simple","zh":"有限的经费一定要花在刀刃上。","pinyin":"Yǒuxiàn de jīngfèi yídìngyào huā zài dāorèn shàng.","vi":"Kinh phí hạn chế nhất định phải chi vào chỗ then chốt."},{"type":"compound","zh":"如果刀刃卷了，切起菜来就会很费劲。","pinyin":"Rúguǒ dāorèn juǎn le, qiē qǐ cài lái jiù huì hěn fèijìn.","vi":"Nếu lưỡi dao bị quăn thì thái rau sẽ rất tốn sức."}],"related":[{"hanzi":"刀口","pinyin":"dāokǒu","vi":"lưỡi dao"},{"hanzi":"刀","pinyin":"dāo","vi":"con dao"},{"hanzi":"锋利","pinyin":"fēnglì","vi":"sắc bén"},{"hanzi":"好钢用在刀刃上","pinyin":"hǎo gāng yòng zài dāorèn shang","vi":"dùng đúng chỗ cần"}]},{"id":"刀山火海","hanzi":"刀山火海","pinyin":"dāoshān-huǒhǎi","meaning_vi":"núi đao biển lửa (nơi vô cùng nguy hiểm)","explanation":"刀山 (núi đao) + 火海 (biển lửa) → nơi cực kỳ hiểm nguy, khó khăn. Thường dùng: 上刀山下火海也不怕 (dù núi đao biển lửa cũng không sợ).","hsk_level":6,"tags":["thanh-ngu"],"image":"🔥","examples":[{"type":"basic","zh":"那里简直是刀山火海。","pinyin":"Nàlǐ jiǎnzhí shì dāoshānhuǒhǎi.","vi":"Nơi đó quả thực là núi đao biển lửa."},{"type":"simple","zh":"消防员为了救人不惜闯进刀山火海。","pinyin":"Xiāofángyuán wèile jiùrén bùxī chuǎngjìn dāoshānhuǒhǎi.","vi":"Lính cứu hỏa sẵn sàng xông vào nơi nguy hiểm tột cùng để cứu người."},{"type":"compound","zh":"即使前面是刀山火海，他也要把药送到山里。","pinyin":"Jíshǐ qiánmiàn shì dāoshānhuǒhǎi, tā yě yào bǎ yào sòng dào shān lǐ.","vi":"Cho dù phía trước là núi đao biển lửa, anh ấy cũng phải đưa thuốc vào trong núi."}],"related":[{"hanzi":"赴汤蹈火","pinyin":"fùtāngdǎohuǒ","vi":"vào sinh ra tử"},{"hanzi":"危险","pinyin":"wēixiǎn","vi":"nguy hiểm"},{"hanzi":"龙潭虎穴","pinyin":"lóngtánhǔxué","vi":"hang hùm miệng rồng"},{"hanzi":"在所不辞","pinyin":"zàisuǒbùcí","vi":"không từ nan"}]},{"id":"登峰造极","hanzi":"登峰造极","pinyin":"dēngfēng-zàojí","meaning_vi":"lên tới đỉnh cao tột bậc","explanation":"登峰 (lên đỉnh núi) + 造极 (tới cực điểm). Thành ngữ.","hsk_level":6,"tags":["thanh-ngu"],"image":"🏔️","examples":[{"type":"basic","zh":"他的技艺登峰造极。","pinyin":"Tā de jìyì dēngfēngzàojí.","vi":"Kỹ nghệ của ông ấy đạt đến đỉnh cao tột bậc."},{"type":"simple","zh":"宋代的瓷器工艺达到了登峰造极的水平。","pinyin":"Sòngdài de cíqì gōngyì dádàole dēngfēngzàojí de shuǐpíng.","vi":"Nghệ thuật gốm sứ thời Tống đạt đến trình độ đỉnh cao tột bậc."},{"type":"compound","zh":"虽然他的球技已经登峰造极，但是每天依然苦练。","pinyin":"Suīrán tā de qiú jì yǐjīng dēngfēngzàojí, dànshì měitiān yīrán kǔliàn.","vi":"Tuy kỹ thuật chơi bóng của anh ấy đã đạt đỉnh cao nhưng ngày nào vẫn khổ luyện."}],"related":[{"hanzi":"炉火纯青","pinyin":"lúhuǒchúnqīng","vi":"điêu luyện tuyệt đỉnh"},{"hanzi":"出神入化","pinyin":"chūshénrùhuà","vi":"điêu luyện thần sầu"},{"hanzi":"巅峰","pinyin":"diānfēng","vi":"đỉnh cao"},{"hanzi":"尽善尽美","pinyin":"jìnshànjìnměi","vi":"hoàn hảo"}],"traditional":"登峰造極"},{"id":"灯火辉煌","hanzi":"灯火辉煌","pinyin":"dēnghuǒ-huīhuáng","meaning_vi":"đèn đuốc sáng trưng rực rỡ","explanation":"灯火辉煌: đèn đuốc rực rỡ chói lọi → sáng trưng, lung linh, thường tả thành phố, lễ hội về đêm.","hsk_level":6,"tags":["thanh-ngu"],"image":"🌃","examples":[{"type":"basic","zh":"夜晚灯火辉煌。","pinyin":"Yèwǎn dēnghuǒhuīhuáng.","vi":"Ban đêm đèn đuốc sáng trưng."},{"type":"simple","zh":"除夕夜的外滩灯火辉煌。","pinyin":"Chúxīyè de Wàitān dēnghuǒhuīhuáng.","vi":"Đêm giao thừa, bến Thượng Hải đèn đuốc sáng trưng rực rỡ."},{"type":"compound","zh":"天一黑，整条商业街就变得灯火辉煌。","pinyin":"Tiān yì hēi, zhěngtiáo shāngyè jiē jiù biànde dēnghuǒhuīhuáng.","vi":"Trời vừa tối, cả con phố thương mại liền trở nên rực rỡ ánh đèn."}],"related":[{"hanzi":"灯火通明","pinyin":"dēnghuǒtōngmíng","vi":"đèn đuốc sáng trưng"},{"hanzi":"金碧辉煌","pinyin":"jīnbìhuīhuáng","vi":"vàng son rực rỡ"},{"hanzi":"璀璨","pinyin":"cuǐcàn","vi":"lấp lánh"},{"hanzi":"漆黑一片","pinyin":"qīhēiyípiàn","vi":"tối om"}],"traditional":"燈火輝煌"},{"id":"灯红酒绿","hanzi":"灯红酒绿","pinyin":"dēnghóng-jiǔlǜ","meaning_vi":"đèn đỏ rượu xanh (cảnh ăn chơi xa hoa)","explanation":"灯红 (đèn đỏ) + 酒绿 (rượu xanh) → đèn rực rỡ, rượu đầy bàn → tả cảnh sống ăn chơi xa hoa trụy lạc, chốn phồn hoa.","hsk_level":6,"tags":["thanh-ngu"],"image":"🍸","examples":[{"type":"basic","zh":"城里灯红酒绿。","pinyin":"Chénglǐ dēnghóngjiǔlǜ.","vi":"Trong thành phố đèn đỏ rượu xanh."},{"type":"simple","zh":"他厌倦了大都市灯红酒绿的生活。","pinyin":"Tā yànjuànle dàdūshì dēnghóngjiǔlǜ de shēnghuó.","vi":"Anh ấy đã chán cuộc sống ăn chơi xa hoa nơi đô thị lớn."},{"type":"compound","zh":"即使身处灯红酒绿之中，她也从不迷失自己。","pinyin":"Jíshǐ shēnchǔ dēnghóngjiǔlǜ zhīzhōng, tā yě cóng bù míshī zìjǐ.","vi":"Cho dù sống giữa chốn phồn hoa xa xỉ, cô ấy cũng chưa bao giờ đánh mất bản thân."}],"related":[{"hanzi":"纸醉金迷","pinyin":"zhǐzuìjīnmí","vi":"ăn chơi xa hoa"},{"hanzi":"花天酒地","pinyin":"huātiānjiǔdì","vi":"ăn chơi trác táng"},{"hanzi":"奢侈","pinyin":"shēchǐ","vi":"xa xỉ"},{"hanzi":"夜生活","pinyin":"yèshēnghuó","vi":"cuộc sống về đêm"}],"traditional":"燈紅酒綠"},{"id":"登录","hanzi":"登录","pinyin":"dēnglù","meaning_vi":"đăng nhập","explanation":"登 (đăng – ghi vào, bước lên) + 录 (lục – ghi chép) → đăng nhập (tài khoản, hệ thống); cũng là đăng ký ghi vào. Trái nghĩa: 退出. Ví dụ: 登录账号.","hsk_level":6,"tags":["dong-tu"],"image":"💻","examples":[{"type":"basic","zh":"请先登录账号。","pinyin":"Qǐng xiān dēnglù zhànghào.","vi":"Vui lòng đăng nhập tài khoản trước."},{"type":"simple","zh":"他用手机号登录了公司的邮箱。","pinyin":"Tāyòng shǒujī hào dēnglùle gōngsī de yóuxiāng.","vi":"Anh ấy dùng số điện thoại đăng nhập vào hộp thư công ty."},{"type":"compound","zh":"如果密码连续输错三次，就暂时无法登录。","pinyin":"Rúguǒ mìmǎ liánxù shū cuò sāncì, jiù zànshí wúfǎ dēnglù.","vi":"Nếu nhập sai mật khẩu ba lần liên tiếp thì tạm thời không thể đăng nhập."}],"related":[{"hanzi":"注册","pinyin":"zhùcè","vi":"đăng ký"},{"hanzi":"账号","pinyin":"zhànghào","vi":"tài khoản"},{"hanzi":"密码","pinyin":"mìmǎ","vi":"mật khẩu"},{"hanzi":"退出","pinyin":"tuìchū","vi":"đăng xuất"}],"traditional":"登錄"},{"id":"等级","hanzi":"等级","pinyin":"děngjí","meaning_vi":"đẳng cấp","explanation":"等 (đẳng – bậc) + 级 (cấp) → cấp bậc, thứ hạng phân theo mức cao thấp. Thường gặp: 等级制度, 等级考试, 划分等级.","hsk_level":6,"tags":["danh-tu"],"image":"📶","examples":[{"type":"basic","zh":"酒店分为五个等级。","pinyin":"Jiǔdiàn fēnwéi wǔ gè děngjí.","vi":"Khách sạn được chia thành năm hạng."},{"type":"simple","zh":"游戏里他的角色等级已经很高了。","pinyin":"Yóuxì lǐ tā de juésè děngjí yǐjīng hěn gāo le.","vi":"Trong game, cấp độ nhân vật của cậu ấy đã rất cao."},{"type":"compound","zh":"只要通过这次考试，你的汉语等级就能提高一级。","pinyin":"Zhǐyào tōngguò zhè cì kǎoshì, nǐ de Hànyǔ děngjí jiù néng tígāo yìjí.","vi":"Chỉ cần vượt qua kỳ thi này, cấp độ tiếng Hán của bạn sẽ nâng lên một bậc."}],"related":[{"hanzi":"级别","pinyin":"jíbié","vi":"cấp bậc"},{"hanzi":"档次","pinyin":"dàngcì","vi":"đẳng cấp"},{"hanzi":"等级制度","pinyin":"děngjízhìdù","vi":"chế độ đẳng cấp"},{"hanzi":"层次","pinyin":"céngcì","vi":"tầng lớp"}],"traditional":"等級"},{"id":"等闲视之","hanzi":"等闲视之","pinyin":"děngxián-shìzhī","meaning_vi":"xem thường, coi nhẹ","explanation":"等闲 (đẳng nhàn – tầm thường) + 视之 (thị chi – nhìn nó) → coi như chuyện bình thường, xem nhẹ. Thường dùng phủ định: 不可等闲视之.","hsk_level":6,"tags":["thanh-ngu"],"image":"😒","examples":[{"type":"basic","zh":"不可等闲视之。","pinyin":"Bùkě děngxiánshìzhī.","vi":"Không thể xem thường."},{"type":"simple","zh":"这种新型病毒绝不能等闲视之。","pinyin":"Zhè zhǒng xīnxíng bìngdú juébù néng děngxiánshìzhī.","vi":"Loại virus mới này tuyệt đối không được xem nhẹ."},{"type":"compound","zh":"虽然对手是新人，但是我们也不能等闲视之。","pinyin":"Suīrán duìshǒu shì xīnrén, dànshì wǒmen yě bù néng děngxiánshìzhī.","vi":"Tuy đối thủ là người mới nhưng chúng ta cũng không được coi nhẹ."}],"related":[{"hanzi":"掉以轻心","pinyin":"diàoyǐqīngxīn","vi":"chủ quan"},{"hanzi":"轻视","pinyin":"qīngshì","vi":"xem nhẹ"},{"hanzi":"不屑一顾","pinyin":"búxièyígù","vi":"không thèm để ý"},{"hanzi":"刮目相看","pinyin":"guāmùxiāngkàn","vi":"nhìn bằng con mắt khác"}],"traditional":"等閒視之"},{"id":"低谷","hanzi":"低谷","pinyin":"dīgǔ","meaning_vi":"giai đoạn trầm lắng, đáy (kinh tế/tâm trạng)","explanation":"低 (thấp) + 谷 (thung lũng).","hsk_level":6,"tags":["danh-tu"],"image":"📉","examples":[{"type":"basic","zh":"他正处在低谷。","pinyin":"Tā zhèng chǔzài dīgǔ.","vi":"Anh ấy đang ở giai đoạn trầm lắng."},{"type":"simple","zh":"去年房地产市场陷入了低谷。","pinyin":"Qùnián fángdìchǎn shìchǎng xiànrùle dīgǔ.","vi":"Năm ngoái thị trường bất động sản rơi vào giai đoạn đáy."},{"type":"compound","zh":"即使人生跌入低谷，也不要放弃希望。","pinyin":"Jíshǐ rénshēng diē rù dīgǔ, yě bú yào fàngqì xīwàng.","vi":"Cho dù cuộc đời rơi xuống đáy, cũng đừng từ bỏ hy vọng."}],"related":[{"hanzi":"高峰","pinyin":"gāofēng","vi":"đỉnh cao"},{"hanzi":"谷底","pinyin":"gǔdǐ","vi":"đáy vực"},{"hanzi":"低潮","pinyin":"dīcháo","vi":"thời kỳ thoái trào"},{"hanzi":"走出低谷","pinyin":"zǒuchūdīgǔ","vi":"vượt qua giai đoạn khó khăn"}]},{"id":"低廉","hanzi":"低廉","pinyin":"dīlián","meaning_vi":"rẻ, thấp (giá cả)","explanation":"低 (đê – thấp) + 廉 (liêm – rẻ) → giá thấp, rẻ. Cụm: 价格低廉, 成本低廉.","hsk_level":6,"tags":["tinh-tu","mua-sam"],"image":"🏷️","examples":[{"type":"basic","zh":"这里租金低廉。","pinyin":"Zhèlǐ zūjīn dīlián.","vi":"Tiền thuê ở đây rẻ."},{"type":"simple","zh":"这家工厂靠低廉的价格抢占了市场。","pinyin":"Zhè jiā gōngchǎng kào dīlián de jiàgé qiǎngzhànle shìchǎng.","vi":"Nhà máy này dựa vào giá rẻ để chiếm lĩnh thị trường."},{"type":"compound","zh":"虽然这家旅馆收费低廉，但是房间干净整洁。","pinyin":"Suīrán zhè jiā lǚguǎn shōufèi dīlián, dànshì fángjiān gānjìng zhěngjié.","vi":"Tuy nhà nghỉ này giá rẻ nhưng phòng sạch sẽ gọn gàng."}],"related":[{"hanzi":"便宜","pinyin":"piányi","vi":"rẻ"},{"hanzi":"廉价","pinyin":"liánjià","vi":"giá rẻ"},{"hanzi":"昂贵","pinyin":"ángguì","vi":"đắt đỏ"},{"hanzi":"物美价廉","pinyin":"wùměijiàlián","vi":"hàng tốt giá rẻ"}]},{"id":"低劣","hanzi":"低劣","pinyin":"dīliè","meaning_vi":"kém cỏi, thấp kém (chất lượng)","explanation":"低 (đê – thấp) + 劣 (liệt – kém) → kém cỏi, tồi (chất lượng, phẩm chất). Cụm: 质量低劣, 手段低劣.","hsk_level":6,"tags":["tinh-tu"],"image":"👎","examples":[{"type":"basic","zh":"质量非常低劣。","pinyin":"Zhìliàng fēicháng dīliè.","vi":"Chất lượng vô cùng kém."},{"type":"simple","zh":"这部电影的特效制作十分低劣。","pinyin":"Zhè bù diànyǐng de tèxiào zhìzuò shífēn dīliè.","vi":"Kỹ xảo của bộ phim này làm rất kém."},{"type":"compound","zh":"他不但手段低劣，而且被揭穿后毫无悔意。","pinyin":"Tā búdàn shǒuduàn dīliè, érqiě bèi jiēchuān hòu háowú huǐyì.","vi":"Hắn không những thủ đoạn hèn hạ mà bị vạch trần rồi vẫn không hề hối hận."}],"related":[{"hanzi":"劣质","pinyin":"lièzhì","vi":"chất lượng kém"},{"hanzi":"粗劣","pinyin":"cūliè","vi":"thô kém"},{"hanzi":"优良","pinyin":"yōuliáng","vi":"tốt đẹp"},{"hanzi":"低下","pinyin":"dīxià","vi":"thấp kém"}]},{"id":"滴水穿石","hanzi":"滴水穿石","pinyin":"dīshuǐ-chuānshí","meaning_vi":"nước chảy đá mòn (kiên trì ắt thành công)","explanation":"滴水 (giọt nước) + 穿石 (xuyên đá) → giọt nước nhỏ mãi cũng làm thủng đá → ví kiên trì bền bỉ thì việc khó mấy cũng làm được. Đồng nghĩa: 水滴石穿.","hsk_level":6,"tags":["thanh-ngu"],"image":"💧","examples":[{"type":"basic","zh":"滴水穿石靠坚持。","pinyin":"Dīshuǐchuānshí kào jiānchí.","vi":"Nước chảy đá mòn là nhờ kiên trì."},{"type":"simple","zh":"他用滴水穿石的毅力学会了三门外语。","pinyin":"Tāyòng dīshuǐchuānshí de yìlì xuéhuìle Sānmén wàiyǔ.","vi":"Anh ấy dùng nghị lực nước chảy đá mòn để học được ba ngoại ngữ."},{"type":"compound","zh":"只要每天背十个单词，滴水穿石，你就一定能成功。","pinyin":"Zhǐyào měitiān bèi shí gè dāncí, dīshuǐchuānshí, nǐ jiù yídìng néng chénggōng.","vi":"Chỉ cần mỗi ngày học mười từ, nước chảy đá mòn, bạn nhất định sẽ thành công."}],"related":[{"hanzi":"水滴石穿","pinyin":"shuǐdīshíchuān","vi":"nước chảy đá mòn"},{"hanzi":"持之以恒","pinyin":"chízhīyǐhéng","vi":"kiên trì bền bỉ"},{"hanzi":"铁杵磨成针","pinyin":"tiě chǔ mó chéng zhēn","vi":"có công mài sắt có ngày nên kim"},{"hanzi":"锲而不舍","pinyin":"qiè'érbùshě","vi":"kiên trì không bỏ"}]},{"id":"叮嘱","hanzi":"叮嘱","pinyin":"dīngzhǔ","meaning_vi":"dặn dò kỹ lưỡng","explanation":"叮 (đinh – dặn đi dặn lại) + 嘱 (chúc – dặn dò) → dặn dò kỹ càng, nhắc đi nhắc lại. Ví dụ: 妈妈再三叮嘱我注意安全.","hsk_level":6,"tags":["dong-tu"],"image":"🗣️","examples":[{"type":"basic","zh":"妈妈再三叮嘱我。","pinyin":"Māma zàisān dīngzhǔ wǒ.","vi":"Mẹ dặn dò tôi nhiều lần."},{"type":"simple","zh":"医生叮嘱他按时吃药少喝酒。","pinyin":"Yīshēng dīngzhǔ tā ànshí chīyào shǎo hējiǔ.","vi":"Bác sĩ dặn dò anh ấy uống thuốc đúng giờ, bớt uống rượu."},{"type":"compound","zh":"临走前，奶奶不但给我装了一包吃的，而且叮嘱我常打电话。","pinyin":"Línzǒu qián, nǎinai búdàn gěi wǒ zhuāngle yì bāo chī de, érqiě dīngzhǔ wǒ cháng dǎdiànhuà.","vi":"Trước lúc đi, bà nội không những gói cho tôi một túi đồ ăn mà còn dặn tôi thường xuyên gọi điện."}],"related":[{"hanzi":"嘱咐","pinyin":"zhǔfù","vi":"dặn dò"},{"hanzi":"叮咛","pinyin":"dīngníng","vi":"căn dặn"},{"hanzi":"提醒","pinyin":"tíxǐng","vi":"nhắc nhở"},{"hanzi":"交代","pinyin":"jiāodài","vi":"giao phó"}],"traditional":"叮囑"},{"id":"东道主","hanzi":"东道主","pinyin":"dōngdàozhǔ","meaning_vi":"chủ nhà, bên đăng cai (người hoặc nước)","explanation":"东道主: vốn là 'chủ nhà trên đường phía đông' (nước Trịnh tiếp đón sứ nước Tần, Tả truyện) → người/nước đứng ra tiếp đãi khách, chủ nhà. Ví dụ: 东道主国家.","hsk_level":6,"tags":["danh-tu","con-nguoi"],"image":"🏟️","examples":[{"type":"basic","zh":"中国是东道主。","pinyin":"Zhōngguó shì dōngdàozhǔ.","vi":"Trung Quốc là nước chủ nhà."},{"type":"simple","zh":"作为东道主，他热情地招待了客人。","pinyin":"Zuòwéi dōngdàozhǔ, tā rèqíng de zhāodàile kèrén.","vi":"Là chủ nhà, anh ấy nhiệt tình tiếp đãi khách."},{"type":"compound","zh":"因为是东道主，所以这次会议由我们负责安排。","pinyin":"Yīnwèi shì dōngdàozhǔ, suǒyǐ zhè cì huìyì yóu wǒmen fùzé ānpái.","vi":"Vì là chủ nhà nên hội nghị lần này do chúng tôi phụ trách sắp xếp."}],"related":[{"hanzi":"主人","pinyin":"zhǔrén","vi":"chủ nhà"},{"hanzi":"主办方","pinyin":"zhǔbànfāng","vi":"bên tổ chức"},{"hanzi":"客人","pinyin":"kèrén","vi":"khách"},{"hanzi":"做东","pinyin":"zuòdōng","vi":"làm chủ tiệc"}],"traditional":"東道主"},{"id":"东山再起","hanzi":"东山再起","pinyin":"dōngshān-zàiqǐ","meaning_vi":"Đông Sơn tái khởi (khôi phục lại sự nghiệp sau thất bại)","explanation":"Điển tích Tạ An. Thành ngữ.","hsk_level":6,"tags":["thanh-ngu"],"image":"🌅","examples":[{"type":"basic","zh":"他终于东山再起。","pinyin":"Tā zhōngyú dōngshānzàiqǐ.","vi":"Cuối cùng anh ấy đã gượng dậy trở lại."},{"type":"simple","zh":"破产五年后，他靠卖茶叶东山再起。","pinyin":"Pòchǎn wǔ nián hòu, tā kào mài cháyè dōngshānzàiqǐ.","vi":"Năm năm sau khi phá sản, ông ấy gây dựng lại sự nghiệp nhờ bán chè."},{"type":"compound","zh":"只要人还在，我们就有东山再起的机会。","pinyin":"Zhǐyào rén hái zài, wǒmen jiù yǒu dōngshānzàiqǐ de jīhuì.","vi":"Chỉ cần người vẫn còn, chúng ta vẫn có cơ hội làm lại."}],"related":[{"hanzi":"卷土重来","pinyin":"juǎntǔchónglái","vi":"quay trở lại"},{"hanzi":"重整旗鼓","pinyin":"chóngzhěngqígǔ","vi":"chấn chỉnh làm lại"},{"hanzi":"死灰复燃","pinyin":"sǐhuīfùrán","vi":"tro tàn bùng cháy lại"},{"hanzi":"一蹶不振","pinyin":"yìjuébúzhèn","vi":"gục ngã không gượng dậy"}],"traditional":"東山再起"},{"id":"打抱不平","hanzi":"打抱不平","pinyin":"dǎbào-bùpíng","meaning_vi":"bênh vực kẻ yếu, bất bình trước chuyện ngang trái","explanation":"打 (ra tay) + 抱不平 (ôm mối bất bình) → thấy người bị ức hiếp thì đứng ra bênh vực, giúp đỡ kẻ yếu.","hsk_level":6,"tags":["thanh-ngu"],"image":"🦸","examples":[{"type":"basic","zh":"他爱打抱不平。","pinyin":"Tā ài dǎbàobùpíng.","vi":"Anh ấy thích bênh vực kẻ yếu."},{"type":"simple","zh":"路人纷纷站出来为被欺负的老人打抱不平。","pinyin":"Lùrén fēnfēn zhàn chūlái wèi bèi qīfu de lǎorén dǎbàobùpíng.","vi":"Người đi đường lần lượt đứng ra bênh vực cụ già bị ức hiếp."},{"type":"compound","zh":"他一看到有人插队，就忍不住要打抱不平。","pinyin":"Tā yí kàndào yǒurén chāduì, jiù rěnbúzhù yào dǎbàobùpíng.","vi":"Anh ấy hễ thấy có người chen hàng là không nhịn được phải lên tiếng bất bình."}],"related":[{"hanzi":"路见不平","pinyin":"lùjiànbùpíng","vi":"thấy chuyện bất bình"},{"hanzi":"见义勇为","pinyin":"jiànyìyǒngwéi","vi":"thấy việc nghĩa dũng cảm làm"},{"hanzi":"伸张正义","pinyin":"shēnzhāngzhèngyì","vi":"thực thi công lý"},{"hanzi":"袖手旁观","pinyin":"xiùshǒupángguān","vi":"khoanh tay đứng nhìn"}]},{"id":"打包","hanzi":"打包","pinyin":"dǎbāo","meaning_vi":"đóng gói mang về","explanation":"打 (làm) + 包 (bao – gói) → đóng gói, gói hành lý; trong quán ăn là gói đồ ăn thừa mang về. Ví dụ: 服务员，打包！, 打包行李.","hsk_level":6,"tags":["dong-tu"],"image":"🥡","examples":[{"type":"basic","zh":"剩菜打包吧。","pinyin":"Shèngcài dǎbāo ba.","vi":"Gói đồ ăn thừa mang về đi."},{"type":"simple","zh":"服务员帮我们把没吃完的饺子打包了。","pinyin":"Fúwùyuán bāng wǒmen bǎ méi chīwán de jiǎozi dǎbāo le.","vi":"Phục vụ giúp chúng tôi gói chỗ sủi cảo ăn chưa hết mang về."},{"type":"compound","zh":"如果你赶时间，就让店家打包带走吧。","pinyin":"Rúguǒ nǐ gǎnshíjiān, jiù ràng diànjiā dǎbāo dàizǒu ba.","vi":"Nếu bạn vội thì nhờ quán đóng gói mang đi nhé."}],"related":[{"hanzi":"外卖","pinyin":"wàimài","vi":"đồ ăn mang đi"},{"hanzi":"打包盒","pinyin":"dǎbāohé","vi":"hộp đựng đồ ăn"},{"hanzi":"包装","pinyin":"bāozhuāng","vi":"đóng gói"},{"hanzi":"带走","pinyin":"dàizǒu","vi":"mang đi"}]},{"id":"打草惊蛇","hanzi":"打草惊蛇","pinyin":"dǎcǎo-jīngshé","meaning_vi":"đánh rắn động cỏ","explanation":"打草 (đánh cỏ) + 惊蛇 (làm rắn sợ) → đánh cỏ làm rắn giật mình bỏ chạy → ví hành động thiếu kín đáo khiến đối phương cảnh giác.","hsk_level":6,"tags":["thanh-ngu"],"image":"🐍","examples":[{"type":"basic","zh":"别打草惊蛇。","pinyin":"Bié dǎcǎojīngshé.","vi":"Đừng đánh rắn động cỏ."},{"type":"simple","zh":"警方暂时按兵不动以免打草惊蛇。","pinyin":"Jǐngfāng zànshí àn bīng búdòng yǐmiǎn dǎcǎojīngshé.","vi":"Cảnh sát tạm thời án binh bất động để tránh đánh rắn động cỏ."},{"type":"compound","zh":"如果现在就去质问他，就会打草惊蛇。","pinyin":"Rúguǒ xiànzài jiù qù zhìwèn tā, jiù huì dǎcǎojīngshé.","vi":"Nếu bây giờ đi chất vấn hắn thì sẽ đánh rắn động cỏ."}],"related":[{"hanzi":"走漏风声","pinyin":"zǒulòufēngshēng","vi":"lộ tin"},{"hanzi":"轻举妄动","pinyin":"qīngjǔwàngdòng","vi":"hành động thiếu suy nghĩ"},{"hanzi":"不动声色","pinyin":"búdòngshēngsè","vi":"không để lộ"},{"hanzi":"引蛇出洞","pinyin":"yǐnshéchūdòng","vi":"dụ rắn ra hang"}],"traditional":"打草驚蛇"},{"id":"打瞌睡","hanzi":"打瞌睡","pinyin":"dǎkēshuì","meaning_vi":"ngủ gật","explanation":"打 + 瞌睡 (buồn ngủ). Động từ ly hợp.","hsk_level":6,"tags":["dong-tu","sinh-hoat"],"image":"😴","examples":[{"type":"basic","zh":"他在打瞌睡。","pinyin":"Tā zài dǎkēshuì.","vi":"Anh ấy đang ngủ gật."},{"type":"simple","zh":"同桌上数学课时又打瞌睡了。","pinyin":"Tóngzhuō shàng shùxué kèshí yòu dǎkēshuì le.","vi":"Bạn cùng bàn lại ngủ gật trong giờ toán."},{"type":"compound","zh":"因为昨晚熬夜，所以他开会时一直打瞌睡。","pinyin":"Yīnwèi zuówǎn áoyè, suǒyǐ tā kāihuì shí yìzhí dǎkēshuì.","vi":"Vì đêm qua thức khuya nên anh ấy ngủ gật suốt buổi họp."}],"related":[{"hanzi":"打盹","pinyin":"dǎdǔn","vi":"ngủ gật"},{"hanzi":"犯困","pinyin":"fànkùn","vi":"buồn ngủ"},{"hanzi":"瞌睡","pinyin":"kēshuì","vi":"buồn ngủ"},{"hanzi":"打哈欠","pinyin":"dǎhāqian","vi":"ngáp"}]},{"id":"打量","hanzi":"打量","pinyin":"dǎliang","meaning_vi":"nhìn ngắm từ trên xuống dưới","explanation":"打 (làm) + 量 (lượng – đo, ước lượng) → nhìn ngắm, quan sát kỹ (người, trang phục); còn nghĩa cho rằng, đoán. Ví dụ: 上下打量他.","hsk_level":6,"tags":["dong-tu"],"image":"👀","examples":[{"type":"basic","zh":"她打量着我。","pinyin":"Tā dǎliangzhe wǒ.","vi":"Cô ấy nhìn tôi từ đầu đến chân."},{"type":"simple","zh":"门卫上下打量了这个陌生的年轻人。","pinyin":"Ménwèi shàngxià dǎliangle zhè gè mòshēng de niánqīngrén.","vi":"Bảo vệ nhìn chàng trai lạ mặt từ trên xuống dưới."},{"type":"compound","zh":"他一走进店里，老板就仔细打量起他的穿着。","pinyin":"Tā yì zǒujìn diàn lǐ, lǎobǎn jiù zǐxì dǎliang qǐ tā de chuānzhuó.","vi":"Anh ấy vừa bước vào cửa hàng, ông chủ liền săm soi cách ăn mặc của anh ấy."}],"related":[{"hanzi":"端详","pinyin":"duānxiáng","vi":"ngắm nghía kỹ"},{"hanzi":"观察","pinyin":"guānchá","vi":"quan sát"},{"hanzi":"上下打量","pinyin":"shàngxiàdǎliang","vi":"nhìn từ trên xuống dưới"},{"hanzi":"注视","pinyin":"zhùshì","vi":"chăm chú nhìn"}]},{"id":"打捞","hanzi":"打捞","pinyin":"dǎlāo","meaning_vi":"trục vớt (tàu đắm/vật rơi xuống nước)","explanation":"打 (đả – làm, động từ chung) + 捞 (lao – vớt) → vớt lên từ dưới nước: trục vớt. Cụm: 打捞沉船, 打捞尸体.","hsk_level":6,"tags":["dong-tu"],"image":"⚓","examples":[{"type":"basic","zh":"他们在打捞沉船。","pinyin":"Tāmen zài dǎlāo chénchuán.","vi":"Họ đang trục vớt tàu đắm."},{"type":"simple","zh":"潜水员从湖底打捞起一部手机。","pinyin":"Qiánshuǐyuán cóng hú dǐ dǎlāo qǐ yí bù shǒujī.","vi":"Thợ lặn vớt được một chiếc điện thoại từ đáy hồ."},{"type":"compound","zh":"虽然水流很急，但是救援队还是打捞到了那辆车。","pinyin":"Suīrán shuǐliú hěn jí, dànshì jiùyuánduì háishì dǎlāo dàole nà liàng chē.","vi":"Tuy dòng nước chảy xiết nhưng đội cứu hộ vẫn trục vớt được chiếc xe đó."}],"related":[{"hanzi":"捞","pinyin":"lāo","vi":"vớt"},{"hanzi":"沉船","pinyin":"chénchuán","vi":"tàu đắm"},{"hanzi":"救援","pinyin":"jiùyuán","vi":"cứu hộ"},{"hanzi":"潜水","pinyin":"qiánshuǐ","vi":"lặn"}],"traditional":"打撈"},{"id":"打破沙锅问到底","hanzi":"打破沙锅问到底","pinyin":"dǎpò shāguō wèn dàodǐ","meaning_vi":"hỏi cho ra nhẽ đến tận cùng","explanation":"Tục ngữ khẩu ngữ.","hsk_level":6,"tags":["thanh-ngu"],"image":"❓","examples":[{"type":"basic","zh":"他总爱打破沙锅问到底。","pinyin":"Tā zǒng ài dǎpòshāguōwèndàodǐ.","vi":"Cậu ấy luôn thích hỏi cho ra nhẽ."},{"type":"simple","zh":"记者对这件事打破沙锅问到底。","pinyin":"Jìzhě duì zhè jiàn shì dǎpòshāguōwèndàodǐ.","vi":"Phóng viên hỏi đến tận cùng về chuyện này."},{"type":"compound","zh":"遇到不懂的问题，只要打破沙锅问到底，就能学到真知识。","pinyin":"Yùdào bù dǒng de wèntí, zhǐyào dǎpòshāguōwèndàodǐ, jiù néng xuédào zhēn zhīshi.","vi":"Gặp vấn đề chưa hiểu, chỉ cần hỏi cho đến tận cùng là sẽ học được kiến thức thật."}],"related":[{"hanzi":"追根究底","pinyin":"zhuīgēnjiūdǐ","vi":"truy đến tận gốc"},{"hanzi":"刨根问底","pinyin":"páogēnwèndǐ","vi":"hỏi cặn kẽ"},{"hanzi":"寻根问底","pinyin":"xúngēnwèndǐ","vi":"hỏi đến tận cùng"},{"hanzi":"好奇","pinyin":"hàoqí","vi":"tò mò"}],"traditional":"打破沙鍋問到底"},{"id":"歹徒","hanzi":"歹徒","pinyin":"dǎitú","meaning_vi":"kẻ xấu, côn đồ","explanation":"歹 (đãi – xấu, ác) + 徒 (đồ – kẻ, bọn) → kẻ gian ác, tội phạm hung hãn. Thường gặp trong tin tức: 持刀歹徒, 与歹徒搏斗.","hsk_level":6,"tags":["danh-tu","con-nguoi"],"image":"🦹","examples":[{"type":"basic","zh":"歹徒被抓了。","pinyin":"Dǎitú bèi zhuā le.","vi":"Kẻ côn đồ đã bị bắt."},{"type":"simple","zh":"一名歹徒持刀闯进了银行。","pinyin":"Yì míng dǎitú chídāo chuǎngjìnle yínháng.","vi":"Một tên côn đồ cầm dao xông vào ngân hàng."},{"type":"compound","zh":"歹徒一看到警察，就扔下抢来的包逃跑了。","pinyin":"Dǎitú yí kàndào jǐngchá, jiù rēngxià qiǎng lái de bāo táopǎo le.","vi":"Kẻ côn đồ vừa thấy cảnh sát liền vứt chiếc túi cướp được rồi bỏ chạy."}],"related":[{"hanzi":"罪犯","pinyin":"zuìfàn","vi":"tội phạm"},{"hanzi":"坏人","pinyin":"huàirén","vi":"kẻ xấu"},{"hanzi":"匪徒","pinyin":"fěitú","vi":"thổ phỉ"},{"hanzi":"劫匪","pinyin":"jiéfěi","vi":"kẻ cướp"}]},{"id":"胆战心惊","hanzi":"胆战心惊","pinyin":"dǎnzhàn-xīnjīng","meaning_vi":"run sợ, kinh hãi","explanation":"胆 (đảm – mật, gan) run, 心 (tâm – tim) kinh → sợ đến run mật, thót tim; hết sức kinh hãi, run sợ.","hsk_level":6,"tags":["thanh-ngu","cam-xuc"],"image":"😱","examples":[{"type":"basic","zh":"我看得胆战心惊。","pinyin":"Wǒ kàn de dǎnzhànxīnjīng.","vi":"Tôi xem mà run sợ."},{"type":"simple","zh":"她胆战心惊地走过那座吊桥。","pinyin":"Tā dǎnzhànxīnjīng de zǒuguò nà zuò diàoqiáo.","vi":"Cô ấy run rẩy sợ hãi bước qua cây cầu treo đó."},{"type":"compound","zh":"只要窗外一打雷，小猫就吓得胆战心惊。","pinyin":"Zhǐyào chuāng wài yì dǎléi, xiǎomāo jiù xià de dǎnzhànxīnjīng.","vi":"Chỉ cần ngoài cửa sổ có sấm, mèo con liền sợ run cầm cập."}],"related":[{"hanzi":"心惊胆战","pinyin":"xīnjīngdǎnzhàn","vi":"kinh hồn bạt vía"},{"hanzi":"提心吊胆","pinyin":"tíxīndiàodǎn","vi":"nơm nớp lo sợ"},{"hanzi":"惊恐","pinyin":"jīngkǒng","vi":"kinh hoàng"},{"hanzi":"镇定自若","pinyin":"zhèndìngzìruò","vi":"bình tĩnh tự nhiên"}],"traditional":"膽戰心驚"},{"id":"党派","hanzi":"党派","pinyin":"dǎngpài","meaning_vi":"đảng phái","explanation":"党 + 派 (phe phái).","hsk_level":6,"tags":["danh-tu","xa-hoi"],"image":"🏛️","examples":[{"type":"basic","zh":"他不属于任何党派。","pinyin":"Tā bù shǔyú rènhé dǎngpài.","vi":"Ông ấy không thuộc đảng phái nào."},{"type":"simple","zh":"议会里各党派就新法案展开了辩论。","pinyin":"Yìhuì lǐ gè dǎngpài jiù xīn fǎ'àn zhǎnkāile biànlùn.","vi":"Các đảng phái trong nghị viện đã tranh luận về dự luật mới."},{"type":"compound","zh":"虽然两个党派意见不同，但是在环保问题上达成了一致。","pinyin":"Suīrán liǎng gè dǎngpài yìjiàn bùtóng, dànshì zài huánbǎo wèntí shàngdá chéngle yízhì.","vi":"Tuy hai đảng phái bất đồng ý kiến nhưng đã thống nhất về vấn đề bảo vệ môi trường."}],"related":[{"hanzi":"政党","pinyin":"zhèngdǎng","vi":"chính đảng"},{"hanzi":"派别","pinyin":"pàibié","vi":"phe phái"},{"hanzi":"党员","pinyin":"dǎngyuán","vi":"đảng viên"},{"hanzi":"无党派","pinyin":"wúdǎngpài","vi":"không đảng phái"}],"traditional":"黨派"},{"id":"导火索","hanzi":"导火索","pinyin":"dǎohuǒsuǒ","meaning_vi":"ngòi nổ, nguyên nhân trực tiếp châm ngòi","explanation":"导火 + 索 (dây dẫn).","hsk_level":6,"tags":["danh-tu"],"image":"🧨","examples":[{"type":"basic","zh":"这是战争的导火索。","pinyin":"Zhè shì zhànzhēng de dǎohuǒsuǒ.","vi":"Đây là ngòi nổ của chiến tranh."},{"type":"simple","zh":"一句玩笑成了两人吵架的导火索。","pinyin":"Yíjù wánxiào chéngle liǎng rén chǎojià de dǎohuǒsuǒ.","vi":"Một câu đùa đã trở thành ngòi nổ cho cuộc cãi vã của hai người."},{"type":"compound","zh":"虽然涨价只是导火索，但是员工的不满早就存在了。","pinyin":"Suīrán zhǎngjià zhǐshì dǎohuǒsuǒ, dànshì yuángōng de bùmǎn zǎojiù cúnzài le.","vi":"Tuy tăng giá chỉ là ngòi nổ nhưng sự bất mãn của nhân viên đã có từ lâu."}],"related":[{"hanzi":"导火线","pinyin":"dǎohuǒxiàn","vi":"dây dẫn lửa"},{"hanzi":"起因","pinyin":"qǐyīn","vi":"nguyên nhân"},{"hanzi":"引发","pinyin":"yǐnfā","vi":"gây ra"},{"hanzi":"爆发","pinyin":"bàofā","vi":"bùng nổ"}],"traditional":"導火索"},{"id":"捣乱","hanzi":"捣乱","pinyin":"dǎoluàn","meaning_vi":"quấy rối, phá đám","explanation":"捣 (đảo – đâm, khuấy) + 乱 (loạn) → quấy phá, gây rối làm hỏng việc người khác. Ví dụ: 别捣乱, 小孩子在课堂上捣乱.","hsk_level":6,"tags":["dong-tu"],"image":"🤪","examples":[{"type":"basic","zh":"别在这里捣乱。","pinyin":"Bié zài zhèlǐ dǎoluàn.","vi":"Đừng phá phách ở đây."},{"type":"simple","zh":"弟弟趁我写作业时在旁边捣乱。","pinyin":"Dìdi chèn wǒ xiě zuòyè shí zài pángbiān dǎoluàn.","vi":"Em trai nhân lúc tôi làm bài tập thì quấy phá bên cạnh."},{"type":"compound","zh":"如果有人故意捣乱，保安就会把他请出去。","pinyin":"Rúguǒ yǒurén gùyì dǎoluàn, bǎo'ān jiù huì bǎ tā qǐng chūqù.","vi":"Nếu có ai cố tình quấy rối, bảo vệ sẽ mời người đó ra ngoài."}],"related":[{"hanzi":"捣蛋","pinyin":"dǎodàn","vi":"nghịch ngợm"},{"hanzi":"添乱","pinyin":"tiānluàn","vi":"thêm rối"},{"hanzi":"闹事","pinyin":"nàoshì","vi":"gây chuyện"},{"hanzi":"破坏","pinyin":"pòhuài","vi":"phá hoại"}],"traditional":"搗亂"},{"id":"倒塌","hanzi":"倒塌","pinyin":"dǎotā","meaning_vi":"đổ sập, sụp đổ (nhà cửa/tường)","explanation":"倒 (ngã) + 塌 (sập).","hsk_level":6,"tags":["dong-tu"],"image":"🏚️","examples":[{"type":"basic","zh":"老房子倒塌了。","pinyin":"Lǎo fángzi dǎotā le.","vi":"Ngôi nhà cũ đã đổ sập."},{"type":"simple","zh":"暴雨过后村口的土墙倒塌了。","pinyin":"Bàoyǔ guòhòu cūn kǒu de tǔ qiáng dǎotā le.","vi":"Sau trận mưa lớn, bức tường đất đầu làng đã đổ sập."},{"type":"compound","zh":"地震一发生，那座年久失修的楼就倒塌了。","pinyin":"Dìzhèn yì fāshēng, nà zuò nián jiǔ shīxiū de lóu jiù dǎotā le.","vi":"Động đất vừa xảy ra, tòa nhà lâu năm không tu sửa đó liền đổ sập."}],"related":[{"hanzi":"坍塌","pinyin":"tāntā","vi":"sụp đổ"},{"hanzi":"崩塌","pinyin":"bēngtā","vi":"đổ sụp"},{"hanzi":"倒下","pinyin":"dǎoxià","vi":"đổ xuống"},{"hanzi":"建造","pinyin":"jiànzào","vi":"xây dựng"}]},{"id":"抵触","hanzi":"抵触","pinyin":"dǐchù","meaning_vi":"mâu thuẫn, xung đột, chống đối","explanation":"抵 (chống) + 触 (va chạm).","hsk_level":6,"tags":["dong-tu","cam-xuc"],"image":"💢","examples":[{"type":"basic","zh":"他有抵触情绪。","pinyin":"Tā yǒu dǐchù qíngxù.","vi":"Cậu ấy có tâm lý chống đối."},{"type":"simple","zh":"这条规定与国家的法律相抵触。","pinyin":"Zhè tiáo guīdìng yǔ guójiā de fǎlǜ xiāng dǐchù.","vi":"Quy định này mâu thuẫn với pháp luật quốc gia."},{"type":"compound","zh":"如果家长一味强迫，孩子就会对学习产生抵触。","pinyin":"Rúguǒ jiāzhǎng yíwèi qiǎngpò, háizi jiù huì duì xuéxí chǎnshēng dǐchù.","vi":"Nếu phụ huynh cứ ép buộc thì trẻ sẽ sinh ra tâm lý chống đối việc học."}],"related":[{"hanzi":"抵触情绪","pinyin":"dǐchùqíngxù","vi":"tâm lý chống đối"},{"hanzi":"抵制","pinyin":"dǐzhì","vi":"tẩy chay"},{"hanzi":"对抗","pinyin":"duìkàng","vi":"đối kháng"},{"hanzi":"矛盾","pinyin":"máodùn","vi":"mâu thuẫn"}],"traditional":"抵觸"},{"id":"抵押","hanzi":"抵押","pinyin":"dǐyā","meaning_vi":"thế chấp (tài sản vay vốn)","explanation":"抵 + 押 (cầm cố).","hsk_level":6,"tags":["dong-tu","tien-te"],"image":"🏦","examples":[{"type":"basic","zh":"他抵押了房子。","pinyin":"Tā dǐyāle fángzi.","vi":"Anh ấy đã thế chấp căn nhà."},{"type":"simple","zh":"老王用汽车作抵押向银行借了钱。","pinyin":"Lǎo Wáng yòng qìchē zuò dǐyā xiàng yínháng jièle qián.","vi":"Lão Vương dùng ô tô làm tài sản thế chấp để vay tiền ngân hàng."},{"type":"compound","zh":"如果到期还不上贷款，抵押的房子就会被拍卖。","pinyin":"Rúguǒ dàoqī huán bú shàng dàikuǎn, dǐyā de fángzi jiù huì bèi pāimài.","vi":"Nếu đến hạn không trả được khoản vay thì căn nhà thế chấp sẽ bị bán đấu giá."}],"related":[{"hanzi":"抵押贷款","pinyin":"dǐyādàikuǎn","vi":"vay thế chấp"},{"hanzi":"担保","pinyin":"dānbǎo","vi":"bảo lãnh"},{"hanzi":"典当","pinyin":"diǎndàng","vi":"cầm đồ"},{"hanzi":"押金","pinyin":"yājīn","vi":"tiền đặt cọc"}]},{"id":"鼎鼎大名","hanzi":"鼎鼎大名","pinyin":"dǐngdǐng-dàmíng","meaning_vi":"nổi tiếng lừng lẫy","explanation":"鼎鼎 (đỉnh đỉnh – hiển hách, lừng lẫy) + 大名 (đại danh – tên tuổi lớn) → danh tiếng lẫy lừng, ai cũng biết. Đồng nghĩa: 大名鼎鼎.","hsk_level":6,"tags":["thanh-ngu"],"image":"🌟","examples":[{"type":"basic","zh":"他的鼎鼎大名谁都知道。","pinyin":"Tā de dǐngdǐngdàmíng shuí dōu zhīdào.","vi":"Tiếng tăm lừng lẫy của ông ấy ai cũng biết."},{"type":"simple","zh":"我早就听说过这位教授的鼎鼎大名。","pinyin":"Wǒ zǎojiù tīngshuōguo zhè wèi jiàoshòu de dǐngdǐngdàmíng.","vi":"Tôi đã nghe danh tiếng lẫy lừng của vị giáo sư này từ lâu."},{"type":"compound","zh":"虽然他鼎鼎大名，但是生活中却十分低调。","pinyin":"Suīrán tā dǐngdǐngdàmíng, dànshì shēnghuó zhōng què shífēn dīdiào.","vi":"Tuy ông ấy nổi tiếng lừng lẫy nhưng trong cuộc sống lại rất khiêm tốn."}],"related":[{"hanzi":"大名鼎鼎","pinyin":"dàmíngdǐngdǐng","vi":"lừng danh"},{"hanzi":"赫赫有名","pinyin":"hèhèyǒumíng","vi":"nổi danh"},{"hanzi":"著名","pinyin":"zhùmíng","vi":"nổi tiếng"},{"hanzi":"无名小卒","pinyin":"wúmíngxiǎozú","vi":"kẻ vô danh tiểu tốt"}]},{"id":"顶天立地","hanzi":"顶天立地","pinyin":"dǐngtiān-lìdì","meaning_vi":"đầu đội trời chân đạp đất (khí phách anh hùng)","explanation":"顶天 (đầu đội trời) + 立地 (chân đứng trên đất) → hình tượng cao lớn hiên ngang → ví người có khí phách anh hùng, chính trực. Thường gặp: 顶天立地的男子汉.","hsk_level":6,"tags":["thanh-ngu"],"image":"🦸","examples":[{"type":"basic","zh":"他是顶天立地的汉子。","pinyin":"Tā shì dǐngtiānlìdì de hànzi.","vi":"Anh ấy là đấng nam nhi đầu đội trời chân đạp đất."},{"type":"simple","zh":"父亲希望我做一个顶天立地的人。","pinyin":"Fùqīn xīwàng wǒ zuò yí gè dǐngtiānlìdì de rén.","vi":"Cha mong tôi trở thành người đầu đội trời chân đạp đất."},{"type":"compound","zh":"既然要做顶天立地的男子汉，就要敢作敢当。","pinyin":"Jìrán yào zuò dǐngtiānlìdì de nánzǐhàn, jiùyào gǎn zuò gǎn dāng.","vi":"Đã muốn làm nam tử hán đầu đội trời chân đạp đất thì phải dám làm dám chịu."}],"related":[{"hanzi":"英雄","pinyin":"yīngxióng","vi":"anh hùng"},{"hanzi":"气壮山河","pinyin":"qìzhuàngshānhé","vi":"khí thế hùng tráng"},{"hanzi":"堂堂正正","pinyin":"tángtángzhèngzhèng","vi":"đường đường chính chính"},{"hanzi":"卑躬屈膝","pinyin":"bēigōngqūxī","vi":"khom lưng uốn gối"}],"traditional":"頂天立地"},{"id":"堵塞","hanzi":"堵塞","pinyin":"dǔsè","meaning_vi":"tắc nghẽn","explanation":"堵 (đổ – chặn, lấp) + 塞 (tắc – nhét, bít) → bị bít lại, tắc nghẽn không thông. Thường gặp: 交通堵塞, 管道堵塞.","hsk_level":6,"tags":["dong-tu"],"image":"🚗","examples":[{"type":"basic","zh":"下水道堵塞了。","pinyin":"Xiàshuǐdào dǔsè le.","vi":"Cống thoát nước bị tắc rồi."},{"type":"simple","zh":"一场车祸堵塞了通往机场的高速公路。","pinyin":"Yì chǎng chēhuò dǔsèle tōngwǎng jīchǎng de gāosùgōnglù.","vi":"Một vụ tai nạn đã làm tắc nghẽn đường cao tốc dẫn ra sân bay."},{"type":"compound","zh":"因为落叶堵塞了排水口，所以院子里积满了水。","pinyin":"Yīnwèi luòyè dǔsèle páishuǐkǒu, suǒyǐ yuànzi lǐ jī mǎnle shuǐ.","vi":"Vì lá rụng làm tắc lỗ thoát nước nên sân ngập đầy nước."}],"related":[{"hanzi":"堵车","pinyin":"dǔchē","vi":"tắc đường"},{"hanzi":"阻塞","pinyin":"zǔsè","vi":"tắc nghẽn"},{"hanzi":"畅通","pinyin":"chàngtōng","vi":"thông suốt"},{"hanzi":"拥堵","pinyin":"yōngdǔ","vi":"ùn tắc"}]},{"id":"犯规","hanzi":"犯规","pinyin":"fànguī","meaning_vi":"phạm quy, phạm luật (thể thao)","explanation":"犯 (vi phạm) + 规 (quy tắc). Động từ ly hợp.","hsk_level":6,"tags":["dong-tu","the-thao"],"image":"🟨","examples":[{"type":"basic","zh":"他又犯规了。","pinyin":"Tā yòu fànguī le.","vi":"Anh ta lại phạm lỗi rồi."},{"type":"simple","zh":"裁判判定那名后卫在禁区内犯规。","pinyin":"Cáipàn pàndìng nà míng hòuwèi zài jìnqū nèi fànguī.","vi":"Trọng tài xác định hậu vệ đó phạm lỗi trong vòng cấm."},{"type":"compound","zh":"如果他再犯规一次，就会被裁判罚下场。","pinyin":"Rúguǒ tā zài fànguī yí cì, jiù huì bèi cáipàn fá xiàchǎng.","vi":"Nếu anh ta phạm lỗi thêm một lần nữa sẽ bị trọng tài đuổi khỏi sân."}],"related":[{"hanzi":"违规","pinyin":"wéiguī","vi":"vi phạm quy định"},{"hanzi":"犯错","pinyin":"fàncuò","vi":"phạm lỗi"},{"hanzi":"裁判","pinyin":"cáipàn","vi":"trọng tài"},{"hanzi":"罚球","pinyin":"fáqiú","vi":"phạt bóng"}],"traditional":"犯規"},{"id":"泛滥","hanzi":"泛滥","pinyin":"fànlàn","meaning_vi":"tràn lan, lũ lụt","explanation":"泛 (phiếm – tràn) + 滥 (lạm – tràn lan quá mức) → nước tràn bờ gây lụt; nghĩa bóng: điều xấu lan tràn không kiểm soát. Ví dụ: 河水泛滥, 假货泛滥.","hsk_level":6,"tags":["dong-tu"],"image":"🌊","examples":[{"type":"basic","zh":"河水泛滥了。","pinyin":"Héshuǐ fànlàn le.","vi":"Nước sông tràn bờ rồi."},{"type":"simple","zh":"网络上的虚假广告越来越泛滥。","pinyin":"Wǎngluò shàng de xūjiǎ guǎnggào yuèláiyuè fànlàn.","vi":"Quảng cáo giả trên mạng ngày càng tràn lan."},{"type":"compound","zh":"如果不加强管理，盗版书就会泛滥成灾。","pinyin":"Rúguǒ bù jiāqiáng guǎnlǐ, dàobǎn shū jiù huì fànlàn chéngzāi.","vi":"Nếu không tăng cường quản lý thì sách lậu sẽ tràn lan thành tai họa."}],"related":[{"hanzi":"洪水","pinyin":"hóngshuǐ","vi":"lũ lụt"},{"hanzi":"泛滥成灾","pinyin":"fànlànchéngzāi","vi":"tràn lan thành thảm họa"},{"hanzi":"充斥","pinyin":"chōngchì","vi":"tràn ngập"},{"hanzi":"蔓延","pinyin":"mànyán","vi":"lan rộng"}],"traditional":"泛濫"},{"id":"放射","hanzi":"放射","pinyin":"fàngshè","meaning_vi":"phát ra, tỏa ra (tia, ánh sáng); bức xạ","explanation":"放 (phóng – phát ra) + 射 (xạ – bắn ra) → phát ra, tỏa ra từ một điểm (ánh sáng, tia). Thường gặp: 放射性 (tính phóng xạ), 放射线.","hsk_level":6,"tags":["dong-tu"],"image":"☢️","examples":[{"type":"basic","zh":"太阳放射出光和热。","pinyin":"Tàiyáng fàngshè chū guāng hé rè.","vi":"Mặt trời phát ra ánh sáng và nhiệt."},{"type":"simple","zh":"这种矿石会放射出微弱的辐射。","pinyin":"Zhè zhǒng kuàngshí huì fàngshè chū wēiruò de fúshè.","vi":"Loại quặng này phát ra bức xạ yếu."},{"type":"compound","zh":"因为这些物质会放射有害射线，所以必须密封保存。","pinyin":"Yīnwèi zhèxiē wùzhì huì fàngshè yǒuhài shèxiàn, suǒyǐ bìxū mìfēng bǎocún.","vi":"Vì những chất này phát ra tia có hại nên phải bảo quản kín."}],"related":[{"hanzi":"辐射","pinyin":"fúshè","vi":"bức xạ"},{"hanzi":"发射","pinyin":"fāshè","vi":"phóng ra"},{"hanzi":"放射性","pinyin":"fàngshèxìng","vi":"tính phóng xạ"},{"hanzi":"照射","pinyin":"zhàoshè","vi":"chiếu xạ"}]},{"id":"凡是","hanzi":"凡是","pinyin":"fánshì","meaning_vi":"phàm là, hễ là","explanation":"凡 (phàm – hễ, tất cả) + 是 (là) → phàm là, hễ là, tất cả những gì. Đặt đầu câu, thường đi với 都: 凡是参加的人都有奖品.","hsk_level":6,"tags":["pho-tu"],"image":"🌐","examples":[{"type":"basic","zh":"凡是学生都免票。","pinyin":"Fánshì xuésheng dōu miǎnpiào.","vi":"Phàm là học sinh đều được miễn vé."},{"type":"simple","zh":"凡是来过这家店的人都说好吃。","pinyin":"Fánshì láiguo zhè jiā diàn de rén dōu shuō hǎochī.","vi":"Hễ ai đã đến quán này đều khen ngon."},{"type":"compound","zh":"凡是答应别人的事，他就一定会做到。","pinyin":"Fánshì dāying biérén de shì, tā jiù yídìng huì zuòdào.","vi":"Phàm việc gì đã hứa với người khác thì anh ấy nhất định làm được."}],"related":[{"hanzi":"所有","pinyin":"suǒyǒu","vi":"tất cả"},{"hanzi":"只要","pinyin":"zhǐyào","vi":"chỉ cần"},{"hanzi":"一切","pinyin":"yíqiè","vi":"mọi thứ"},{"hanzi":"但凡","pinyin":"dànfán","vi":"hễ là"}]},{"id":"繁琐","hanzi":"繁琐","pinyin":"fánsuǒ","meaning_vi":"rườm rà, phức tạp (thủ tục)","explanation":"繁 (nhiều) + 琐 (vụn vặt).","hsk_level":6,"tags":["tinh-tu"],"image":"📋","examples":[{"type":"basic","zh":"手续太繁琐了。","pinyin":"Shǒuxù tài fánsuǒ le.","vi":"Thủ tục rườm rà quá."},{"type":"simple","zh":"办签证需要填写许多繁琐的表格。","pinyin":"Bàn qiānzhèng xūyào tiánxiě xǔduō fánsuǒ de biǎogé.","vi":"Làm visa cần điền rất nhiều tờ khai rườm rà."},{"type":"compound","zh":"虽然步骤有点繁琐，但是做出来的蛋糕特别好吃。","pinyin":"Suīrán bùzhòu yǒudiǎn fánsuǒ, dànshì zuò chūlái de dàngāo tèbié hǎochī.","vi":"Tuy các bước hơi rườm rà nhưng bánh làm ra đặc biệt ngon."}],"related":[{"hanzi":"烦琐","pinyin":"fánsuǒ","vi":"rườm rà"},{"hanzi":"复杂","pinyin":"fùzá","vi":"phức tạp"},{"hanzi":"简便","pinyin":"jiǎnbiàn","vi":"đơn giản tiện lợi"},{"hanzi":"麻烦","pinyin":"máfan","vi":"phiền phức"}],"traditional":"繁瑣"},{"id":"繁体字","hanzi":"繁体字","pinyin":"fántǐzì","meaning_vi":"chữ Phồn thể","explanation":"繁 (phồn – rườm, nhiều nét) + 体 (thể – kiểu) + 字 (chữ) → chữ Hán phồn thể, dùng ở Đài Loan, Hồng Kông. Đối lập: 简体字 (giản thể).","hsk_level":6,"tags":["danh-tu","ngon-ngu"],"image":"🈷️","examples":[{"type":"basic","zh":"他会写繁体字。","pinyin":"Tā huì xiě fántǐzì.","vi":"Anh ấy biết viết chữ phồn thể."},{"type":"simple","zh":"香港的路牌上用的都是繁体字。","pinyin":"Xiānggǎng de lùpái shàng yòng de dōu shì fántǐzì.","vi":"Biển báo đường phố ở Hồng Kông đều dùng chữ phồn thể."},{"type":"compound","zh":"如果你学会了繁体字，就能读懂更多古籍。","pinyin":"Rúguǒ nǐ xuéhuìle fántǐzì, jiù néng dúdǒng gèng duō gǔjí.","vi":"Nếu bạn học được chữ phồn thể thì có thể đọc hiểu nhiều sách cổ hơn."}],"related":[{"hanzi":"简体字","pinyin":"jiǎntǐzì","vi":"chữ giản thể"},{"hanzi":"汉字","pinyin":"hànzì","vi":"chữ Hán"},{"hanzi":"书法","pinyin":"shūfǎ","vi":"thư pháp"},{"hanzi":"异体字","pinyin":"yìtǐzì","vi":"chữ dị thể"}],"traditional":"繁體字"},{"id":"繁重","hanzi":"繁重","pinyin":"fánzhòng","meaning_vi":"nặng nề (công việc/nhiệm vụ)","explanation":"繁 (phồn – nhiều, rườm rà) + 重 (trọng – nặng) → vừa nhiều vừa nặng, vất vả. Thường đi với 任务, 工作, 负担.","hsk_level":6,"tags":["tinh-tu","cong-viec"],"image":"🏋️","examples":[{"type":"basic","zh":"任务十分繁重。","pinyin":"Rènwu shífēn fánzhòng.","vi":"Nhiệm vụ vô cùng nặng nề."},{"type":"simple","zh":"高三学生每天都要面对繁重的作业。","pinyin":"Gāo sān xuésheng měitiān dōu yào miànduì fánzhòng de zuòyè.","vi":"Học sinh lớp mười hai ngày nào cũng phải đối mặt với lượng bài tập nặng nề."},{"type":"compound","zh":"尽管工作繁重，她还是每周抽空陪父母。","pinyin":"Jǐnguǎn gōngzuò fánzhòng, tā háishì měizhōu chōukòng péi fùmǔ.","vi":"Mặc dù công việc nặng nề, cô ấy vẫn dành thời gian mỗi tuần ở bên bố mẹ."}],"related":[{"hanzi":"沉重","pinyin":"chénzhòng","vi":"nặng nề"},{"hanzi":"艰巨","pinyin":"jiānjù","vi":"gian khổ nặng nề"},{"hanzi":"轻松","pinyin":"qīngsōng","vi":"nhẹ nhàng"},{"hanzi":"繁忙","pinyin":"fánmáng","vi":"bận rộn"}]},{"id":"防备","hanzi":"防备","pinyin":"fángbèi","meaning_vi":"đề phòng, phòng bị","explanation":"防 + 备 (chuẩn bị).","hsk_level":6,"tags":["dong-tu"],"image":"🛡️","examples":[{"type":"basic","zh":"要防备小偷。","pinyin":"Yào fángbèi xiǎotōu.","vi":"Phải đề phòng kẻ trộm."},{"type":"simple","zh":"他对陌生人一向很有防备。","pinyin":"Tā duì mòshēngrén yíxiàng hěn yǒu fángbèi.","vi":"Anh ấy luôn rất đề phòng người lạ."},{"type":"compound","zh":"因为事先有所防备，所以台风来时损失不大。","pinyin":"Yīnwèi shìxiān yǒusuǒ fángbèi, suǒyǐ táifēng lái shí sǔnshī búdà.","vi":"Vì đã đề phòng từ trước nên khi bão đến thiệt hại không lớn."}],"related":[{"hanzi":"防范","pinyin":"fángfàn","vi":"phòng ngừa"},{"hanzi":"戒备","pinyin":"jièbèi","vi":"cảnh giác"},{"hanzi":"提防","pinyin":"dīfang","vi":"đề phòng"},{"hanzi":"预防","pinyin":"yùfáng","vi":"dự phòng"}],"traditional":"防備"},{"id":"防患未然","hanzi":"防患未然","pinyin":"fánghuàn-wèirán","meaning_vi":"phòng bệnh hơn chữa bệnh, ngăn ngừa tai họa từ trước","explanation":"防患 (phòng hoạn – phòng tai họa) + 未然 (vị nhiên – khi chưa xảy ra) → đề phòng tai họa, sự cố từ trước khi nó xảy ra. Còn viết 防患于未然.","hsk_level":6,"tags":["thanh-ngu"],"image":"🛡️","examples":[{"type":"basic","zh":"安全工作要防患未然。","pinyin":"Ānquán gōngzuò yào fánghuànwèirán.","vi":"Công tác an toàn phải phòng ngừa từ trước."},{"type":"simple","zh":"学校定期检查电线以防患未然。","pinyin":"Xuéxiào dìngqī jiǎnchá diànxiàn yǐ fánghuànwèirán.","vi":"Nhà trường định kỳ kiểm tra dây điện để phòng ngừa tai họa từ trước."},{"type":"compound","zh":"与其出了事再去补救，不如提前防患未然。","pinyin":"Yǔqí chūleshì zài qù bǔjiù, bùrú tíqián fánghuànwèirán.","vi":"Thay vì xảy ra chuyện rồi mới khắc phục, chi bằng phòng ngừa từ trước."}],"related":[{"hanzi":"未雨绸缪","pinyin":"wèiyǔchóumóu","vi":"lo trước khi mưa"},{"hanzi":"防微杜渐","pinyin":"fángwēidùjiàn","vi":"ngăn từ khi chớm"},{"hanzi":"预防","pinyin":"yùfáng","vi":"phòng ngừa"},{"hanzi":"亡羊补牢","pinyin":"wángyángbǔláo","vi":"mất bò mới lo làm chuồng"}]},{"id":"防守","hanzi":"防守","pinyin":"fángshǒu","meaning_vi":"phòng thủ","explanation":"防 (phòng – đề phòng) + 守 (thủ – giữ) → canh giữ, phòng thủ chống tấn công; dùng nhiều trong quân sự, thể thao. Trái nghĩa: 进攻.","hsk_level":6,"tags":["dong-tu"],"image":"🛡️","examples":[{"type":"basic","zh":"他们加强了防守。","pinyin":"Tāmen jiāqiángle fángshǒu.","vi":"Họ đã tăng cường phòng thủ."},{"type":"simple","zh":"这支球队的防守像一堵墙一样坚固。","pinyin":"Zhè zhī qiúduì de fángshǒu xiàng yì dǔ qiáng yíyàng jiāngù.","vi":"Hàng phòng thủ của đội bóng này vững chắc như một bức tường."},{"type":"compound","zh":"我们不但要做好防守，而且要抓住机会反击。","pinyin":"Wǒmen búdàn yào zuò hǎo fángshǒu, érqiě yào zhuāzhù jīhuì fǎnjī.","vi":"Chúng ta không những phải phòng thủ tốt mà còn phải nắm cơ hội phản công."}],"related":[{"hanzi":"进攻","pinyin":"jìngōng","vi":"tấn công"},{"hanzi":"防御","pinyin":"fángyù","vi":"phòng ngự"},{"hanzi":"守卫","pinyin":"shǒuwèi","vi":"canh giữ"},{"hanzi":"后卫","pinyin":"hòuwèi","vi":"hậu vệ"}]},{"id":"防卫","hanzi":"防卫","pinyin":"fángwèi","meaning_vi":"phòng vệ, tự vệ","explanation":"防 + 卫 (bảo vệ). Cụm: 正当防卫 (phòng vệ chính đáng).","hsk_level":6,"tags":["dong-tu","phap-luat"],"image":"🥋","examples":[{"type":"basic","zh":"这是正当防卫。","pinyin":"Zhè shì zhèngdàng fángwèi.","vi":"Đây là phòng vệ chính đáng."},{"type":"simple","zh":"她报名参加了女子防卫课程。","pinyin":"Tā bàomíng cānjiāle nǚzǐ fángwèi kèchéng.","vi":"Cô ấy đăng ký tham gia khóa học tự vệ dành cho nữ."},{"type":"compound","zh":"如果防卫超过了必要限度，就要承担法律责任。","pinyin":"Rúguǒ fángwèi chāoguòle bìyào xiàndù, jiùyào chéngdān fǎlǜ zérèn.","vi":"Nếu phòng vệ vượt quá giới hạn cần thiết thì phải chịu trách nhiệm pháp lý."}],"related":[{"hanzi":"自卫","pinyin":"zìwèi","vi":"tự vệ"},{"hanzi":"防御","pinyin":"fángyù","vi":"phòng ngự"},{"hanzi":"正当防卫","pinyin":"zhèngdàngfángwèi","vi":"phòng vệ chính đáng"},{"hanzi":"保卫","pinyin":"bǎowèi","vi":"bảo vệ"}],"traditional":"防衛"},{"id":"防微杜渐","hanzi":"防微杜渐","pinyin":"fángwēi-dùjiàn","meaning_vi":"ngăn chặn mầm mống sai lầm ngay từ khi mới chớm","explanation":"防微 (phòng vi – phòng cái nhỏ) + 杜渐 (đỗ tiệm – chặn cái đang lớn dần) → ngăn chặn sai lầm, điều xấu ngay từ lúc mới manh nha, không để phát triển.","hsk_level":6,"tags":["thanh-ngu"],"image":"🌱","examples":[{"type":"basic","zh":"教育要防微杜渐。","pinyin":"Jiàoyù yào fángwēidùjiàn.","vi":"Giáo dục phải ngăn chặn từ khi mới chớm."},{"type":"simple","zh":"父母应该防微杜渐地纠正孩子的坏习惯。","pinyin":"Fùmǔ yīnggāi fángwēidùjiàn de jiūzhèng háizi de huài xíguàn.","vi":"Cha mẹ nên uốn nắn thói xấu của con ngay từ khi mới chớm."},{"type":"compound","zh":"小错如果不防微杜渐，就可能酿成大祸。","pinyin":"Xiǎo cuò rúguǒ bù fángwēidùjiàn, jiù kěnéng niàngchéng dàhuò.","vi":"Lỗi nhỏ nếu không ngăn chặn từ khi mới chớm thì có thể gây ra họa lớn."}],"related":[{"hanzi":"防患未然","pinyin":"fánghuànwèirán","vi":"phòng họa từ trước"},{"hanzi":"未雨绸缪","pinyin":"wèiyǔchóumóu","vi":"lo trước khi mưa"},{"hanzi":"防止","pinyin":"fángzhǐ","vi":"ngăn chặn"},{"hanzi":"积重难返","pinyin":"jīzhòngnánfǎn","vi":"tích lâu khó sửa"}],"traditional":"防微杜漸"},{"id":"防治","hanzi":"防治","pinyin":"fángzhì","meaning_vi":"phòng và chữa","explanation":"防 (phòng – phòng ngừa) + 治 (trị – chữa trị) → phòng ngừa và chữa trị. Thường đi với 防治疾病, 防治污染, 病虫害防治.","hsk_level":6,"tags":["dong-tu"],"image":"🩺","examples":[{"type":"basic","zh":"防治病虫害。","pinyin":"Fángzhì bìngchónghài.","vi":"Phòng trừ sâu bệnh."},{"type":"simple","zh":"社区医院开展了高血压防治讲座。","pinyin":"Shèqū yīyuàn kāizhǎnle gāoxuèyā fángzhì jiǎngzuò.","vi":"Bệnh viện cộng đồng tổ chức buổi tọa đàm phòng và chữa bệnh cao huyết áp."},{"type":"compound","zh":"只有防治结合，才能有效控制这种传染病。","pinyin":"Zhǐyǒu fángzhì jiéhé, cáinéng yǒuxiào kòngzhì zhè zhǒng chuánrǎnbìng.","vi":"Chỉ có kết hợp phòng và chữa mới kiểm soát hiệu quả bệnh truyền nhiễm này."}],"related":[{"hanzi":"预防","pinyin":"yùfáng","vi":"phòng ngừa"},{"hanzi":"治疗","pinyin":"zhìliáo","vi":"điều trị"},{"hanzi":"防治措施","pinyin":"fángzhìcuòshī","vi":"biện pháp phòng chống"},{"hanzi":"防控","pinyin":"fángkòng","vi":"phòng chống kiểm soát"}]},{"id":"肺腑之言","hanzi":"肺腑之言","pinyin":"fèifǔ-zhīyán","meaning_vi":"lời nói tận đáy lòng, lời tâm huyết","explanation":"肺腑 (phế phủ – phổi và tạng phủ, ý chỉ tận đáy lòng) + 之言 (lời) → lời nói thật lòng, xuất phát từ tận đáy lòng.","hsk_level":6,"tags":["thanh-ngu","giao-tiep"],"image":"❤️","examples":[{"type":"basic","zh":"这是我的肺腑之言。","pinyin":"Zhè shì wǒ de fèifǔzhīyán.","vi":"Đây là lời nói tận đáy lòng của tôi."},{"type":"simple","zh":"老师的一番肺腑之言让他流下了眼泪。","pinyin":"Lǎoshī de yìfān fèifǔzhīyán ràng tā liú xiàle yǎnlèi.","vi":"Những lời tâm huyết của thầy giáo khiến cậu ấy rơi nước mắt."},{"type":"compound","zh":"虽然这些话不太好听，但是句句都是肺腑之言。","pinyin":"Suīrán zhèxiē huà bú tài hǎotīng, dànshì jù jù dōu shì fèifǔzhīyán.","vi":"Tuy những lời này không dễ nghe nhưng câu nào cũng là lời thật lòng."}],"related":[{"hanzi":"由衷之言","pinyin":"yóuzhōngzhīyán","vi":"lời từ đáy lòng"},{"hanzi":"真心话","pinyin":"zhēnxīnhuà","vi":"lời thật lòng"},{"hanzi":"推心置腹","pinyin":"tuīxīnzhìfù","vi":"thật lòng đối đãi"},{"hanzi":"花言巧语","pinyin":"huāyánqiǎoyǔ","vi":"lời ngon tiếng ngọt"}]},{"id":"废寝忘食","hanzi":"废寝忘食","pinyin":"fèiqǐn-wàngshí","meaning_vi":"quên ăn quên ngủ","explanation":"废寝 (phế tẩm – bỏ ngủ) + 忘食 (vong thực – quên ăn) → quên ăn quên ngủ → tả sự chăm chỉ, chuyên tâm hết mức vào học tập, công việc.","hsk_level":6,"tags":["thanh-ngu"],"image":"📚","examples":[{"type":"basic","zh":"他学习废寝忘食。","pinyin":"Tā xuéxí fèiqǐnwàngshí.","vi":"Cậu ấy học quên ăn quên ngủ."},{"type":"simple","zh":"科学家们废寝忘食地研究新疫苗。","pinyin":"Kēxuéjiāmen fèiqǐnwàngshí de yánjiū xīn yìmiáo.","vi":"Các nhà khoa học quên ăn quên ngủ nghiên cứu vắc xin mới."},{"type":"compound","zh":"他一迷上下棋，就废寝忘食，连饭都顾不上吃。","pinyin":"Tā yì míshàng xiàqí, jiù fèiqǐnwàngshí, lián fàn dōu gùbúshàng chī.","vi":"Hễ mê cờ là anh ấy quên ăn quên ngủ, đến cơm cũng chẳng màng ăn."}],"related":[{"hanzi":"夜以继日","pinyin":"yèyǐjìrì","vi":"ngày đêm không nghỉ"},{"hanzi":"专心致志","pinyin":"zhuānxīnzhìzhì","vi":"chuyên tâm"},{"hanzi":"孜孜不倦","pinyin":"zīzībújuàn","vi":"cần mẫn không mệt mỏi"},{"hanzi":"游手好闲","pinyin":"yóushǒuhàoxián","vi":"du thủ du thực"}],"traditional":"廢寢忘食"},{"id":"奋不顾身","hanzi":"奋不顾身","pinyin":"fènbú-gùshēn","meaning_vi":"quên mình vì nghĩa, dũng cảm lao vào nguy hiểm","explanation":"奋 (phấn – hăng hái xông lên) + 不顾身 (bất cố thân – không đoái tới thân mình) → dũng cảm lao lên, không màng an nguy bản thân.","hsk_level":6,"tags":["thanh-ngu"],"image":"🦸","examples":[{"type":"basic","zh":"他奋不顾身救人。","pinyin":"Tā fènbúgùshēn jiùrén.","vi":"Anh ấy quên mình cứu người."},{"type":"simple","zh":"一位路人奋不顾身地跳进河里救起了孩子。","pinyin":"Yí wèi lùrén fènbúgùshēn de tiàojìn hé lǐ jiù qǐle háizi.","vi":"Một người qua đường đã quên mình nhảy xuống sông cứu đứa trẻ."},{"type":"compound","zh":"火灾一发生，消防员就奋不顾身地冲进了大楼。","pinyin":"Huǒzāi yì fāshēng, xiāofángyuán jiù fènbúgùshēn de chōngjìnle dàlóu.","vi":"Hỏa hoạn vừa xảy ra, lính cứu hỏa đã quên mình lao vào tòa nhà."}],"related":[{"hanzi":"舍生忘死","pinyin":"shěshēngwàngsǐ","vi":"quên mình"},{"hanzi":"见义勇为","pinyin":"jiànyìyǒngwéi","vi":"thấy việc nghĩa dũng cảm làm"},{"hanzi":"勇往直前","pinyin":"yǒngwǎngzhíqián","vi":"dũng cảm tiến lên"},{"hanzi":"贪生怕死","pinyin":"tānshēngpàsǐ","vi":"tham sống sợ chết"}],"traditional":"奮不顧身"},{"id":"愤愤不平","hanzi":"愤愤不平","pinyin":"fènfèn-bùpíng","meaning_vi":"ấm ức bất bình","explanation":"愤愤 (phẫn phẫn – tức giận) + 不平 (bất bình) → trong lòng tức giận, ấm ức vì thấy bất công.","hsk_level":6,"tags":["thanh-ngu","cam-xuc"],"image":"😤","examples":[{"type":"basic","zh":"他愤愤不平地走了。","pinyin":"Tā fènfènbùpíng de zǒu le.","vi":"Anh ấy ấm ức bỏ đi."},{"type":"simple","zh":"她对这次不公平的评选愤愤不平。","pinyin":"Tā duì zhè cì bù gōngpíng de píngxuǎn fènfènbùpíng.","vi":"Cô ấy ấm ức bất bình về đợt bình chọn không công bằng này."},{"type":"compound","zh":"虽然他心里愤愤不平，但是表面上什么也没说。","pinyin":"Suīrán tā xīnlǐ fènfènbùpíng, dànshì biǎomiànshàng shénme yě méi shuō.","vi":"Tuy trong lòng ấm ức bất bình nhưng bề ngoài anh ấy chẳng nói gì."}],"related":[{"hanzi":"愤怒","pinyin":"fènnù","vi":"phẫn nộ"},{"hanzi":"不满","pinyin":"bùmǎn","vi":"bất mãn"},{"hanzi":"忿忿不平","pinyin":"fènfènbùpíng","vi":"ấm ức bất bình"},{"hanzi":"心平气和","pinyin":"xīnpíngqìhé","vi":"bình tâm hòa nhã"}],"traditional":"憤憤不平"},{"id":"分量","hanzi":"分量","pinyin":"fènliàng","meaning_vi":"trọng lượng, sức nặng","explanation":"分 (phân – phần, đọc fèn) + 量 (lượng) → trọng lượng, khối lượng; nghĩa bóng: sức nặng, tầm quan trọng. Ví dụ: 他说话很有分量 (lời nói có trọng lượng).","hsk_level":6,"tags":["danh-tu"],"image":"⚖️","examples":[{"type":"basic","zh":"这个箱子分量不轻。","pinyin":"Zhè gè xiāngzi fènliàng bù qīng.","vi":"Cái thùng này khá nặng."},{"type":"simple","zh":"校长的这句话在家长心中很有分量。","pinyin":"Xiàozhǎng de zhè jù huà zài jiāzhǎng xīnzhōng hěn yǒufènliàng.","vi":"Câu nói này của hiệu trưởng rất có trọng lượng trong lòng phụ huynh."},{"type":"compound","zh":"这家餐厅的菜不但便宜，而且分量很足。","pinyin":"Zhè jiā cāntīng de cài búdàn piányi, érqiě fènliàng hěn zú.","vi":"Món ăn ở nhà hàng này không những rẻ mà khẩu phần còn rất đầy đặn."}],"related":[{"hanzi":"重量","pinyin":"zhòngliàng","vi":"trọng lượng"},{"hanzi":"份量","pinyin":"fènliàng","vi":"phần lượng"},{"hanzi":"轻重","pinyin":"qīngzhòng","vi":"nặng nhẹ"},{"hanzi":"有分量","pinyin":"yǒufènliàng","vi":"có trọng lượng"}]},{"id":"分外","hanzi":"分外","pinyin":"fènwài","meaning_vi":"vô cùng, đặc biệt (hơn bình thường)","explanation":"分 (đọc fèn) + 外 (ngoài).","hsk_level":6,"tags":["pho-tu"],"image":"🌟","examples":[{"type":"basic","zh":"月亮分外明亮。","pinyin":"Yuèliang fènwài míngliàng.","vi":"Mặt trăng đặc biệt sáng."},{"type":"simple","zh":"雨后的山林显得分外清新。","pinyin":"Yǔ hòu de shānlín xiǎnde fènwài qīngxīn.","vi":"Núi rừng sau mưa trông đặc biệt trong lành."},{"type":"compound","zh":"一到中秋节，远在他乡的游子就分外想家。","pinyin":"Yí dào Zhōngqiūjié, yuǎn zài tāxiāng de yóuzǐ jiù fènwài xiǎngjiā.","vi":"Cứ đến Tết Trung thu, những người con xa quê lại đặc biệt nhớ nhà."}],"related":[{"hanzi":"格外","pinyin":"géwài","vi":"đặc biệt"},{"hanzi":"特别","pinyin":"tèbié","vi":"đặc biệt"},{"hanzi":"十分","pinyin":"shífēn","vi":"rất"},{"hanzi":"分外妖娆","pinyin":"fènwàiyāoráo","vi":"đẹp lạ thường"}]},{"id":"凤毛麟角","hanzi":"凤毛麟角","pinyin":"fèngmáo-línjiǎo","meaning_vi":"lông phượng sừng lân (vô cùng quý hiếm)","explanation":"凤毛 (lông phượng) + 麟角 (sừng kỳ lân) → những thứ cực hiếm → ví người tài hoặc vật quý vô cùng hiếm có.","hsk_level":6,"tags":["thanh-ngu"],"image":"🦄","examples":[{"type":"basic","zh":"这种人才凤毛麟角。","pinyin":"Zhè zhǒng réncái fèngmáolínjiǎo.","vi":"Loại nhân tài này vô cùng hiếm."},{"type":"simple","zh":"能同时精通五种语言的人可谓凤毛麟角。","pinyin":"Néng tóngshí jīngtōng wǔ zhǒng yǔyán de rén kěwèi fèngmáolínjiǎo.","vi":"Người có thể cùng lúc tinh thông năm ngôn ngữ có thể nói là hiếm như lông phượng sừng lân."},{"type":"compound","zh":"因为真正懂古琴修复的师傅凤毛麟角，所以价格非常高。","pinyin":"Yīnwèi zhēnzhèng dǒng gǔqín xiūfù de shīfu fèngmáolínjiǎo, suǒyǐ jiàgé fēicháng gāo.","vi":"Vì thợ thực sự biết phục chế đàn cổ cầm vô cùng hiếm nên giá rất cao."}],"related":[{"hanzi":"稀少","pinyin":"xīshǎo","vi":"hiếm"},{"hanzi":"罕见","pinyin":"hǎnjiàn","vi":"hiếm thấy"},{"hanzi":"寥寥无几","pinyin":"liáoliáowújǐ","vi":"ít ỏi"},{"hanzi":"比比皆是","pinyin":"bǐbǐjiēshì","vi":"đâu đâu cũng có"}],"traditional":"鳳毛麟角"},{"id":"肥皂剧","hanzi":"肥皂剧","pinyin":"féizàojù","meaning_vi":"phim truyền hình dài tập tâm lý tình cảm","explanation":"Dịch từ tiếng Anh 'soap opera'.","hsk_level":6,"tags":["danh-tu","giai-tri"],"image":"📺","examples":[{"type":"basic","zh":"妈妈爱看肥皂剧。","pinyin":"Māma ài kàn féizàojù.","vi":"Mẹ thích xem phim truyền hình dài tập."},{"type":"simple","zh":"这部肥皂剧已经连续播了三百多集。","pinyin":"Zhè bù féizàojù yǐjīng liánxù bōle sān bǎi duō jí.","vi":"Bộ phim truyền hình dài tập này đã chiếu liên tục hơn ba trăm tập."},{"type":"compound","zh":"虽然肥皂剧的剧情很老套，但是很多人还是追着看。","pinyin":"Suīrán féizàojù de jùqíng hěn lǎotào, dànshì hěn duō rén háishì zhuīzhe kàn.","vi":"Tuy tình tiết phim dài tập rất cũ mòn nhưng nhiều người vẫn theo dõi."}],"related":[{"hanzi":"电视剧","pinyin":"diànshìjù","vi":"phim truyền hình"},{"hanzi":"连续剧","pinyin":"liánxùjù","vi":"phim nhiều tập"},{"hanzi":"偶像剧","pinyin":"ǒuxiàngjù","vi":"phim thần tượng"},{"hanzi":"情景喜剧","pinyin":"qíngjǐngxǐjù","vi":"phim hài tình huống"}],"traditional":"肥皂劇"},{"id":"逢场作戏","hanzi":"逢场作戏","pinyin":"féngchǎng-zuòxì","meaning_vi":"gặp dịp thì vui đùa cho qua chuyện (không nghiêm túc)","explanation":"逢场 (gặp sân diễn) + 作戏 (diễn trò) → người làm xiếc gặp chỗ đông là diễn → ví gặp dịp thì chiều theo, vui đùa cho qua, không thật lòng.","hsk_level":6,"tags":["thanh-ngu"],"image":"🎭","examples":[{"type":"basic","zh":"他只是逢场作戏。","pinyin":"Tā zhǐshì féngchǎngzuòxì.","vi":"Anh ta chỉ vui đùa cho qua chuyện thôi."},{"type":"simple","zh":"酒桌上的那些客套话不过是逢场作戏。","pinyin":"Jiǔ zhuō shàng de nàxiē kètàohuà búguò shì féngchǎngzuòxì.","vi":"Những lời khách sáo trên bàn rượu chẳng qua chỉ là gặp dịp thì chơi."},{"type":"compound","zh":"既然你对她不是真心的，就别再逢场作戏了。","pinyin":"Jìrán nǐ duì tā bú shì zhēnxīn de, jiù bié zài féngchǎngzuòxì le.","vi":"Đã không thật lòng với cô ấy thì đừng đùa cợt cho qua chuyện nữa."}],"related":[{"hanzi":"敷衍","pinyin":"fūyǎn","vi":"qua loa"},{"hanzi":"应酬","pinyin":"yìngchou","vi":"xã giao"},{"hanzi":"做戏","pinyin":"zuòxì","vi":"đóng kịch"},{"hanzi":"认真","pinyin":"rènzhēn","vi":"nghiêm túc"}],"traditional":"逢場作戲"},{"id":"逢凶化吉","hanzi":"逢凶化吉","pinyin":"féngxiōng-huàjí","meaning_vi":"gặp dữ hóa lành","explanation":"逢凶 (gặp điều xấu) + 化吉 (hóa tốt lành). Thành ngữ.","hsk_level":6,"tags":["thanh-ngu"],"image":"🍀","examples":[{"type":"basic","zh":"祝你逢凶化吉。","pinyin":"Zhù nǐ féngxiōnghuàjí.","vi":"Chúc bạn gặp dữ hóa lành."},{"type":"simple","zh":"他在那次车祸中幸运地逢凶化吉。","pinyin":"Tā zài nà cì chēhuò zhōng xìngyùn de féngxiōnghuàjí.","vi":"Anh ấy may mắn gặp dữ hóa lành trong vụ tai nạn xe đó."},{"type":"compound","zh":"只要大家冷静应对，就一定能逢凶化吉。","pinyin":"Zhǐyào dàjiā lěngjìng yìngduì, jiù yídìng néng féngxiōnghuàjí.","vi":"Chỉ cần mọi người bình tĩnh ứng phó thì nhất định sẽ gặp dữ hóa lành."}],"related":[{"hanzi":"转危为安","pinyin":"zhuǎnwēiwéi'ān","vi":"chuyển nguy thành an"},{"hanzi":"遇难呈祥","pinyin":"yùnànchéngxiáng","vi":"gặp nạn hóa lành"},{"hanzi":"化险为夷","pinyin":"huàxiǎnwéiyí","vi":"vượt qua hiểm nguy"},{"hanzi":"吉祥","pinyin":"jíxiáng","vi":"may mắn"}]},{"id":"副","hanzi":"副","pinyin":"fù","meaning_vi":"phó (chức vụ); bộ, cặp, đôi (lượng từ)","explanation":"副 (phó): phó, phụ (đối với 正); lượng từ cho vật thành cặp/bộ và vẻ mặt. Ví dụ: 副经理 (phó giám đốc), 一副眼镜 (một cặp kính), 一副笑脸.","hsk_level":6,"tags":["luong-tu"],"image":"👓","examples":[{"type":"basic","zh":"我买了一副手套。","pinyin":"Wǒ mǎile yí fù shǒutào.","vi":"Tôi đã mua một đôi găng tay."},{"type":"simple","zh":"新来的副经理负责市场部的工作。","pinyin":"Xīn lái de fùjīnglǐ fùzé shìchǎng bù de gōngzuò.","vi":"Phó giám đốc mới đến phụ trách công việc của phòng thị trường."},{"type":"compound","zh":"他虽然戴着一副眼镜，但是看起来一点也不斯文。","pinyin":"Tā suīrán dàizhe yí fù yǎnjìng, dànshì kànqǐlái yìdiǎn yě bù sīwen.","vi":"Anh ấy tuy đeo một cặp kính nhưng trông chẳng nho nhã chút nào."}],"related":[{"hanzi":"副总","pinyin":"fùzǒng","vi":"phó tổng"},{"hanzi":"副作用","pinyin":"fùzuòyòng","vi":"tác dụng phụ"},{"hanzi":"正","pinyin":"zhèng","vi":"chính"},{"hanzi":"一副眼镜","pinyin":"yífùyǎnjìng","vi":"một cặp kính"}]},{"id":"覆盖","hanzi":"覆盖","pinyin":"fùgài","meaning_vi":"bao phủ, che phủ","explanation":"覆 (che) + 盖 (đậy).","hsk_level":6,"tags":["dong-tu"],"image":"❄️","examples":[{"type":"basic","zh":"白雪覆盖大地。","pinyin":"Báixuě fùgài dàdì.","vi":"Tuyết trắng phủ kín mặt đất."},{"type":"simple","zh":"这个小区的无线网络已经全面覆盖。","pinyin":"Zhè gè xiǎoqū de wúxiànwǎngluò yǐjīng quánmiàn fùgài.","vi":"Mạng không dây của khu dân cư này đã phủ sóng toàn bộ."},{"type":"compound","zh":"因为森林覆盖率很高，所以这里的空气格外新鲜。","pinyin":"Yīnwèi sēnlín fùgàilǜ hěn gāo, suǒyǐ zhèlǐ de kōngqì géwài xīnxiān.","vi":"Vì tỷ lệ che phủ rừng rất cao nên không khí ở đây đặc biệt trong lành."}],"related":[{"hanzi":"遮盖","pinyin":"zhēgài","vi":"che đậy"},{"hanzi":"覆盖率","pinyin":"fùgàilǜ","vi":"tỷ lệ bao phủ"},{"hanzi":"掩盖","pinyin":"yǎngài","vi":"che giấu"},{"hanzi":"笼罩","pinyin":"lǒngzhào","vi":"bao trùm"}],"traditional":"覆蓋"},{"id":"富丽堂皇","hanzi":"富丽堂皇","pinyin":"fùlì-tánghuáng","meaning_vi":"nguy nga tráng lệ","explanation":"富丽 (phú lệ – giàu đẹp) + 堂皇 (đường hoàng – to lớn, bề thế) → lộng lẫy, nguy nga tráng lệ; thường tả cung điện, khách sạn, kiến trúc.","hsk_level":6,"tags":["thanh-ngu"],"image":"🏰","examples":[{"type":"basic","zh":"宫殿富丽堂皇。","pinyin":"Gōngdiàn fùlìtánghuáng.","vi":"Cung điện nguy nga tráng lệ."},{"type":"simple","zh":"婚礼在一家富丽堂皇的酒店里举行。","pinyin":"Hūnlǐ zài yìjiā fùlìtánghuáng de jiǔdiàn lǐ jǔxíng.","vi":"Đám cưới được tổ chức tại một khách sạn nguy nga tráng lệ."},{"type":"compound","zh":"这座别墅虽然装修得富丽堂皇，但是住起来并不舒服。","pinyin":"Zhè zuò biéshù suīrán zhuāngxiū de fùlìtánghuáng, dànshì zhù qǐlái bìngbù shūfu.","vi":"Căn biệt thự này tuy được trang trí nguy nga tráng lệ nhưng ở thì không hề thoải mái."}],"related":[{"hanzi":"金碧辉煌","pinyin":"jīnbìhuīhuáng","vi":"vàng son rực rỡ"},{"hanzi":"豪华","pinyin":"háohuá","vi":"xa hoa"},{"hanzi":"宏伟","pinyin":"hóngwěi","vi":"hùng vĩ"},{"hanzi":"简陋","pinyin":"jiǎnlòu","vi":"sơ sài"}],"traditional":"富麗堂皇"},{"id":"附属","hanzi":"附属","pinyin":"fùshǔ","meaning_vi":"trực thuộc, phụ thuộc","explanation":"附 (phụ – bám vào) + 属 (thuộc) → phụ thuộc, trực thuộc vào đơn vị khác. Thường gặp: 附属医院 (bệnh viện trực thuộc), 附属品.","hsk_level":6,"tags":["dong-tu"],"image":"🏢","examples":[{"type":"basic","zh":"这是附属医院。","pinyin":"Zhè shì fùshǔ yīyuàn.","vi":"Đây là bệnh viện trực thuộc."},{"type":"simple","zh":"这所中学附属于北京师范大学。","pinyin":"Zhè suǒ zhōngxué fù shǔyú Běijīngshīfàndàxué.","vi":"Trường trung học này trực thuộc Đại học Sư phạm Bắc Kinh."},{"type":"compound","zh":"既然这家工厂附属于集团，就必须遵守集团的规定。","pinyin":"Jìrán zhè jiā gōngchǎng fù shǔyú jítuán, jiù bìxū zūnshǒu jítuán de guīdìng.","vi":"Đã là nhà máy trực thuộc tập đoàn thì phải tuân thủ quy định của tập đoàn."}],"related":[{"hanzi":"附属医院","pinyin":"fùshǔyīyuàn","vi":"bệnh viện trực thuộc"},{"hanzi":"隶属","pinyin":"lìshǔ","vi":"trực thuộc"},{"hanzi":"附属品","pinyin":"fùshǔpǐn","vi":"vật phụ thuộc"},{"hanzi":"独立","pinyin":"dúlì","vi":"độc lập"}],"traditional":"附屬"},{"id":"腹泻","hanzi":"腹泻","pinyin":"fùxiè","meaning_vi":"tiêu chảy, đau bụng đi ngoài","explanation":"腹 (bụng) + 泻 (tiêu chảy).","hsk_level":6,"tags":["dong-tu","suc-khoe"],"image":"🤒","examples":[{"type":"basic","zh":"他吃坏肚子腹泻了。","pinyin":"Tā chīhuài dùzi fùxiè le.","vi":"Anh ấy ăn phải đồ hỏng nên bị tiêu chảy."},{"type":"simple","zh":"这种药专门治疗儿童的急性腹泻。","pinyin":"Zhè zhǒng yào zhuānmén zhìliáo értóng de jíxìng fùxiè.","vi":"Loại thuốc này chuyên điều trị tiêu chảy cấp ở trẻ em."},{"type":"compound","zh":"如果腹泻持续三天以上，就应该马上去医院。","pinyin":"Rúguǒ fùxiè chíxù sān tiān yǐshàng, jiù yīnggāi mǎshàng qù yīyuàn.","vi":"Nếu tiêu chảy kéo dài trên ba ngày thì nên đến bệnh viện ngay."}],"related":[{"hanzi":"拉肚子","pinyin":"lādùzi","vi":"tiêu chảy"},{"hanzi":"便秘","pinyin":"biànmì","vi":"táo bón"},{"hanzi":"肚子疼","pinyin":"dùziténg","vi":"đau bụng"},{"hanzi":"呕吐","pinyin":"ǒutù","vi":"nôn mửa"}],"traditional":"腹瀉"},{"id":"付诸东流","hanzi":"付诸东流","pinyin":"fùzhū-dōngliú","meaning_vi":"đổ sông đổ biển (công sức uổng phí)","explanation":"付诸 (giao cho) + 东流 (dòng nước chảy về đông) → thả trôi theo dòng sông chảy về đông → ví công sức, hy vọng mất trắng, đổ sông đổ biển.","hsk_level":6,"tags":["thanh-ngu"],"image":"🌊","examples":[{"type":"basic","zh":"心血全都付诸东流了。","pinyin":"Xīnxuè quándōu fùzhūdōngliú le.","vi":"Bao tâm huyết đều đổ sông đổ biển cả."},{"type":"simple","zh":"一场大火让他十年的积蓄付诸东流。","pinyin":"Yì chǎng dàhuǒ ràng tā shí nián de jīxù fùzhūdōngliú.","vi":"Một trận hỏa hoạn khiến khoản tiết kiệm mười năm của anh ấy đổ sông đổ biển."},{"type":"compound","zh":"如果现在放弃，我们三个月的努力就付诸东流了。","pinyin":"Rúguǒ xiànzài fàngqì, wǒmen sān gèyuè de nǔlì jiù fùzhūdōngliú le.","vi":"Nếu bây giờ bỏ cuộc thì ba tháng nỗ lực của chúng ta sẽ đổ sông đổ biển."}],"related":[{"hanzi":"前功尽弃","pinyin":"qiángōngjìnqì","vi":"công sức đổ sông đổ biển"},{"hanzi":"白费","pinyin":"báifèi","vi":"uổng phí"},{"hanzi":"功亏一篑","pinyin":"gōngkuīyíkuì","vi":"đắp núi thiếu một sọt"},{"hanzi":"付出","pinyin":"fùchū","vi":"bỏ ra"}],"traditional":"付諸東流"},{"id":"副作用","hanzi":"副作用","pinyin":"fùzuòyòng","meaning_vi":"tác dụng phụ","explanation":"副 (phó – phụ) + 作用 (tác dụng) → tác dụng phụ ngoài ý muốn, nhất là của thuốc; nghĩa bóng: hậu quả không mong muốn. Ví dụ: 这种药副作用很小.","hsk_level":6,"tags":["danh-tu","suc-khoe"],"image":"💊","examples":[{"type":"basic","zh":"这种药副作用很小。","pinyin":"Zhè zhǒng yào fùzuòyòng hěn xiǎo.","vi":"Loại thuốc này có rất ít tác dụng phụ."},{"type":"simple","zh":"医生提醒我注意感冒药的副作用。","pinyin":"Yīshēng tíxǐng wǒ zhùyì gǎnmàoyào de fùzuòyòng.","vi":"Bác sĩ nhắc tôi chú ý tác dụng phụ của thuốc cảm."},{"type":"compound","zh":"虽然这个政策初衷很好，但是带来了不少副作用。","pinyin":"Suīrán zhè ge zhèngcè chūzhōng hěn hǎo, dànshì dàiláile bùshǎo fùzuòyòng.","vi":"Tuy chính sách này xuất phát từ ý tốt nhưng lại gây ra không ít tác dụng phụ."}],"related":[{"hanzi":"作用","pinyin":"zuòyòng","vi":"tác dụng"},{"hanzi":"不良反应","pinyin":"bùliángfǎnyìng","vi":"phản ứng có hại"},{"hanzi":"药物","pinyin":"yàowù","vi":"thuốc"},{"hanzi":"后遗症","pinyin":"hòuyízhèng","vi":"di chứng"}]},{"id":"伏","hanzi":"伏","pinyin":"fú","meaning_vi":"cúi rạp, nằm sấp; ẩn nấp; tiết phục (những ngày nóng nhất)","explanation":"Cụm: 伏案工作 (cúi bên bàn làm việc).","hsk_level":6,"tags":["dong-tu"],"image":"🙇","examples":[{"type":"basic","zh":"小猫伏在窗台上。","pinyin":"Xiǎomāo fú zài chuāngtái shang.","vi":"Con mèo con nằm phục trên bậu cửa sổ."},{"type":"simple","zh":"他写着写着就伏在桌子上睡着了。","pinyin":"Tā xiězhe xiězhe jiù fú zài zhuōzi shang shuìzháo le.","vi":"Anh ấy viết một lúc rồi gục xuống bàn ngủ thiếp đi."},{"type":"compound","zh":"一进入三伏天，气温就一下子升到了三十八度。","pinyin":"Yí jìnrù sānfútiān, qìwēn jiù yíxiàzi shēng dàole sānshí bādù.","vi":"Vừa vào tiết tam phục, nhiệt độ liền tăng vọt lên ba mươi tám độ."}],"related":[{"hanzi":"三伏天","pinyin":"sānfútiān","vi":"những ngày nóng nhất hè"},{"hanzi":"埋伏","pinyin":"máifú","vi":"mai phục"},{"hanzi":"趴","pinyin":"pā","vi":"nằm sấp"},{"hanzi":"起伏","pinyin":"qǐfú","vi":"nhấp nhô"}]},{"id":"幅度","hanzi":"幅度","pinyin":"fúdù","meaning_vi":"biên độ, mức độ","explanation":"幅 (phúc – bề rộng) + 度 (độ – mức) → biên độ, mức độ thay đổi lên xuống. Thường gặp: 大幅度提高, 涨幅, 降价幅度.","hsk_level":6,"tags":["danh-tu"],"image":"📊","examples":[{"type":"basic","zh":"房价上涨幅度很大。","pinyin":"Fángjià shàngzhǎng fúdù hěn dà.","vi":"Giá nhà tăng với biên độ rất lớn."},{"type":"simple","zh":"今年公司的利润有了大幅度的提高。","pinyin":"Jīnnián gōngsī de lìrùn yǒule dàfúdù de tígāo.","vi":"Năm nay lợi nhuận của công ty đã tăng mạnh."},{"type":"compound","zh":"因为原材料涨价，所以这批产品的价格调整幅度比较大。","pinyin":"Yīnwèi yuáncáiliào zhǎngjià, suǒyǐ zhè pī chǎnpǐn de jiàgé tiáozhěng fúdù bǐjiào dà.","vi":"Vì nguyên liệu tăng giá nên mức điều chỉnh giá của lô hàng này khá lớn."}],"related":[{"hanzi":"程度","pinyin":"chéngdù","vi":"mức độ"},{"hanzi":"大幅度","pinyin":"dàfúdù","vi":"biên độ lớn"},{"hanzi":"涨幅","pinyin":"zhǎngfú","vi":"mức tăng"},{"hanzi":"范围","pinyin":"fànwéi","vi":"phạm vi"}]},{"id":"服气","hanzi":"服气","pinyin":"fúqì","meaning_vi":"tâm phục","explanation":"服 (phục – khâm phục, chịu) + 气 (khí) → chịu phục, tâm phục khẩu phục; hay dùng phủ định: 不服气 (không chịu thua, không phục).","hsk_level":6,"tags":["dong-tu"],"image":"👍","examples":[{"type":"basic","zh":"输了他还不服气。","pinyin":"Shūle tā hái bùfúqì.","vi":"Thua rồi mà anh ta vẫn chưa chịu phục."},{"type":"simple","zh":"他的解释让在场的人都很服气。","pinyin":"Tā de jiěshì ràng zài chǎng de rén dōu hěn fúqì.","vi":"Lời giải thích của anh ấy khiến những người có mặt đều tâm phục."},{"type":"compound","zh":"只要你拿出真本事，大家就会服气的。","pinyin":"Zhǐyào nǐ náchū zhēn běnshi, dàjiā jiù huì fúqì de.","vi":"Chỉ cần bạn thể hiện bản lĩnh thật sự, mọi người sẽ phục thôi."}],"related":[{"hanzi":"服输","pinyin":"fúshū","vi":"chịu thua"},{"hanzi":"心服口服","pinyin":"xīnfúkǒufú","vi":"tâm phục khẩu phục"},{"hanzi":"不服气","pinyin":"bùfúqì","vi":"không phục"},{"hanzi":"佩服","pinyin":"pèifú","vi":"khâm phục"}],"traditional":"服氣"},{"id":"浮想联翩","hanzi":"浮想联翩","pinyin":"fúxiǎng-liánpiān","meaning_vi":"suy nghĩ miên man liên tiếp","explanation":"浮想 (phù tưởng – suy nghĩ hiện lên) + 联翩 (liên phiên – liên tiếp như chim bay) → hết ý nghĩ này đến ý nghĩ khác nối nhau dâng lên, suy nghĩ miên man.","hsk_level":6,"tags":["thanh-ngu","nhan-thuc"],"image":"💭","examples":[{"type":"basic","zh":"看着老照片，我浮想联翩。","pinyin":"Kànzhe lǎo zhàopiàn, wǒ fúxiǎngliánpiān.","vi":"Nhìn những tấm ảnh cũ, tôi miên man suy nghĩ."},{"type":"simple","zh":"站在长城上，他不禁浮想联翩。","pinyin":"Zhàn zài Chángchéng shang, tā bùjīn fúxiǎngliánpiān.","vi":"Đứng trên Vạn Lý Trường Thành, anh ấy không khỏi suy nghĩ miên man."},{"type":"compound","zh":"每当听到这首老歌，我就浮想联翩，想起了大学时光。","pinyin":"Měidāng tīngdào zhè shǒu lǎogē, wǒ jiù fúxiǎngliánpiān, xiǎngqǐle dàxué shíguāng.","vi":"Mỗi khi nghe bài hát cũ này, tôi lại miên man suy nghĩ, nhớ về thời đại học."}],"related":[{"hanzi":"想入非非","pinyin":"xiǎngrùfēifēi","vi":"nghĩ ngợi viển vông"},{"hanzi":"联想","pinyin":"liánxiǎng","vi":"liên tưởng"},{"hanzi":"思绪万千","pinyin":"sīxùwànqiān","vi":"suy nghĩ miên man"},{"hanzi":"遐想","pinyin":"xiáxiǎng","vi":"mơ màng"}],"traditional":"浮想聯翩"},{"id":"幅员","hanzi":"幅员","pinyin":"Fúyuán","meaning_vi":"diện tích lãnh thổ","explanation":"幅 + 员. Cụm: 幅员辽阔 (lãnh thổ rộng lớn).","hsk_level":6,"tags":["danh-tu","dia-danh"],"image":"🗺️","examples":[{"type":"basic","zh":"中国幅员辽阔。","pinyin":"Zhōngguó Fúyuán liáokuò.","vi":"Trung Quốc có lãnh thổ rộng lớn."},{"type":"simple","zh":"俄罗斯是世界上幅员最广的国家。","pinyin":"Éluósī shì shìjiè shang Fúyuán zuì guǎng de guójiā.","vi":"Nga là quốc gia có diện tích lãnh thổ rộng nhất thế giới."},{"type":"compound","zh":"由于幅员辽阔，所以各地的气候差别很大。","pinyin":"Yóuyú Fúyuán liáokuò, suǒyǐ gèdì de qìhòu chābié hěn dà.","vi":"Do lãnh thổ rộng lớn nên khí hậu các vùng khác nhau rất nhiều."}],"related":[{"hanzi":"幅员辽阔","pinyin":"fúyuánliáokuò","vi":"lãnh thổ rộng lớn"},{"hanzi":"面积","pinyin":"miànjī","vi":"diện tích"},{"hanzi":"疆域","pinyin":"jiāngyù","vi":"lãnh thổ"},{"hanzi":"领土","pinyin":"lǐngtǔ","vi":"lãnh thổ"}],"traditional":"幅員"},{"id":"扶摇直上","hanzi":"扶摇直上","pinyin":"fúyáo-zhíshàng","meaning_vi":"bay thẳng lên cao, thăng tiến không ngừng","explanation":"扶摇 (phù dao – cơn gió xoáy cực mạnh) + 直上 (bay thẳng lên) → chim bằng cưỡi gió lốc bay vút lên trời (Trang Tử) → ví thăng tiến, tăng lên nhanh chóng.","hsk_level":6,"tags":["thanh-ngu"],"image":"🚀","examples":[{"type":"basic","zh":"他的名气扶摇直上。","pinyin":"Tā de míngqì fúyáozhíshàng.","vi":"Danh tiếng của anh ấy tăng vọt."},{"type":"simple","zh":"风筝借着风势扶摇直上。","pinyin":"Fēngzheng jièzhe fēngshì fúyáozhíshàng.","vi":"Con diều nhờ sức gió bay vút lên cao."},{"type":"compound","zh":"自从新产品上市以后，公司的股价就扶摇直上。","pinyin":"Zìcóng xīnchǎnpǐn shàngshì yǐhòu, gōngsī de gǔjià jiù fúyáozhíshàng.","vi":"Từ khi sản phẩm mới ra mắt, giá cổ phiếu công ty liên tục tăng vọt."}],"related":[{"hanzi":"青云直上","pinyin":"qīngyúnzhíshàng","vi":"một bước lên mây"},{"hanzi":"飞黄腾达","pinyin":"Fēihuángténgdá","vi":"công danh hiển đạt"},{"hanzi":"步步高升","pinyin":"bùbùgāoshēng","vi":"từng bước thăng tiến"},{"hanzi":"一落千丈","pinyin":"yíluòqiānzhàng","vi":"tụt dốc không phanh"}],"traditional":"扶搖直上"},{"id":"发布","hanzi":"发布","pinyin":"fābù","meaning_vi":"công bố, phát hành","explanation":"发 (phát – đưa ra) + 布 (bố – tuyên bố, phổ biến) → công bố, phát hành ra công chúng. Thường gặp: 发布消息, 发布会 (họp báo), 发布新产品.","hsk_level":6,"tags":["dong-tu"],"image":"📢","examples":[{"type":"basic","zh":"气象台发布了暴雨预警。","pinyin":"Qìxiàngtái fābùle bàoyǔ yùjǐng.","vi":"Đài khí tượng đã phát cảnh báo mưa lớn."},{"type":"simple","zh":"这家公司下周将发布新款手机。","pinyin":"Zhè jiā gōngsī xiàzhōu jiāng fābù xīnkuǎn shǒujī.","vi":"Công ty này tuần sau sẽ ra mắt mẫu điện thoại mới."},{"type":"compound","zh":"消息一发布，网上就引起了热烈讨论。","pinyin":"Xiāoxi yì fābù, wǎngshang jiù yǐnqǐle rèliè tǎolùn.","vi":"Tin vừa được công bố, trên mạng liền dấy lên cuộc thảo luận sôi nổi."}],"related":[{"hanzi":"公布","pinyin":"gōngbù","vi":"công bố"},{"hanzi":"发表","pinyin":"fābiǎo","vi":"phát biểu, đăng"},{"hanzi":"发布会","pinyin":"fābùhuì","vi":"buổi họp báo"},{"hanzi":"颁布","pinyin":"bānbù","vi":"ban bố"}],"traditional":"發布"},{"id":"发动","hanzi":"发动","pinyin":"fādòng","meaning_vi":"phát động, khởi động","explanation":"发 (phát – khởi) + 动 (động) → phát động (chiến tranh, phong trào); khởi động (máy móc); huy động mọi người. Ví dụ: 发动机 (động cơ), 发动群众.","hsk_level":6,"tags":["dong-tu"],"image":"🚀","examples":[{"type":"basic","zh":"汽车发动不起来了。","pinyin":"Qìchē fādòng bu qǐlái le.","vi":"Xe ô tô không nổ máy được nữa."},{"type":"simple","zh":"村长发动全村人一起修路。","pinyin":"Cūnzhǎng fādòng quán cūn rén yìqǐ xiūlù.","vi":"Trưởng thôn vận động cả làng cùng nhau sửa đường."},{"type":"compound","zh":"因为敌人还没准备好，所以我们决定立即发动进攻。","pinyin":"Yīnwèi dírén hái méi zhǔnbèihǎo, suǒyǐ wǒmen juédìng lìjí fādòng jìngōng.","vi":"Vì kẻ địch chưa chuẩn bị xong nên chúng ta quyết định phát động tấn công ngay lập tức."}],"related":[{"hanzi":"启动","pinyin":"qǐdòng","vi":"khởi động"},{"hanzi":"发起","pinyin":"fāqǐ","vi":"phát khởi"},{"hanzi":"发动机","pinyin":"fādòngjī","vi":"động cơ"},{"hanzi":"动员","pinyin":"dòngyuán","vi":"động viên, huy động"}],"traditional":"發動"},{"id":"发愣","hanzi":"发愣","pinyin":"fālèng","meaning_vi":"ngẩn người, sững sờ","explanation":"发 + 愣 (ngẩn ra). Động từ ly hợp.","hsk_level":6,"tags":["dong-tu"],"image":"😲","examples":[{"type":"basic","zh":"他坐在那儿发愣。","pinyin":"Tā zuò zài nàr fālèng.","vi":"Anh ấy ngồi đó ngẩn người ra."},{"type":"simple","zh":"听到这个消息，她站在门口发愣。","pinyin":"Tīngdào zhè ge xiāoxi, tā zhàn zài ménkǒu fālèng.","vi":"Nghe tin này, cô ấy đứng sững sờ ở cửa."},{"type":"compound","zh":"老师虽然叫了他好几声，但是他还在发愣。","pinyin":"Lǎoshī suīrán jiàole tā hǎojǐ shēng, dànshì tā hái zài fālèng.","vi":"Thầy giáo tuy đã gọi cậu ấy mấy lần nhưng cậu vẫn ngẩn người ra."}],"related":[{"hanzi":"发呆","pinyin":"fādāi","vi":"ngẩn người"},{"hanzi":"愣住","pinyin":"lèngzhù","vi":"đứng sững"},{"hanzi":"出神","pinyin":"chūshén","vi":"thất thần"},{"hanzi":"走神","pinyin":"zǒushén","vi":"mất tập trung"}],"traditional":"發愣"},{"id":"发誓","hanzi":"发誓","pinyin":"fāshì","meaning_vi":"thề, thề thốt","explanation":"发 (phát – nói ra) + 誓 (thệ – lời thề) → thề, lập lời thề. Ví dụ: 我发誓再也不迟到了, 对天发誓.","hsk_level":6,"tags":["dong-tu"],"image":"🤞","examples":[{"type":"basic","zh":"他发誓再也不喝酒了。","pinyin":"Tā fāshì zài yě bù hējiǔ le.","vi":"Anh ấy thề sẽ không bao giờ uống rượu nữa."},{"type":"simple","zh":"她在父亲墓前发誓要考上医学院。","pinyin":"Tā zài fùqīn mù qián fāshì yào kǎoshàng yīxuéyuàn.","vi":"Cô ấy thề trước mộ cha sẽ thi đỗ trường y."},{"type":"compound","zh":"他虽然发誓会按时还钱，但是到现在一分钱也没还。","pinyin":"Tā suīrán fāshì huì ànshí huán qián, dànshì dàoxiànzài yì fēnqián yě méi huán.","vi":"Tuy anh ta đã thề sẽ trả tiền đúng hạn nhưng đến giờ vẫn chưa trả một xu nào."}],"related":[{"hanzi":"宣誓","pinyin":"xuānshì","vi":"tuyên thệ"},{"hanzi":"誓言","pinyin":"shìyán","vi":"lời thề"},{"hanzi":"保证","pinyin":"bǎozhèng","vi":"bảo đảm"},{"hanzi":"承诺","pinyin":"chéngnuò","vi":"hứa hẹn"}],"traditional":"發誓"},{"id":"发泄","hanzi":"发泄","pinyin":"fāxiè","meaning_vi":"trút giận, giải tỏa (cảm xúc)","explanation":"发 + 泄 (thoát ra).","hsk_level":6,"tags":["dong-tu","cam-xuc"],"image":"😤","examples":[{"type":"basic","zh":"别拿孩子发泄怒气。","pinyin":"Bié ná háizi fāxiè nùqì.","vi":"Đừng trút giận lên con trẻ."},{"type":"simple","zh":"他通过跑步来发泄工作的压力。","pinyin":"Tā tōngguò pǎobù lái fāxiè gōngzuò de yālì.","vi":"Anh ấy giải tỏa áp lực công việc bằng cách chạy bộ."},{"type":"compound","zh":"与其把不满憋在心里，不如找个朋友发泄一下。","pinyin":"Yǔqí bǎ bùmǎn biē zài xīnli, bùrú zhǎo gè péngyou fāxiè yíxià.","vi":"Thay vì dồn nén bất mãn trong lòng, chi bằng tìm một người bạn để trút bầu tâm sự."}],"related":[{"hanzi":"宣泄","pinyin":"xuānxiè","vi":"giải tỏa"},{"hanzi":"排解","pinyin":"páijiě","vi":"giải khuây"},{"hanzi":"出气","pinyin":"chūqì","vi":"trút giận"},{"hanzi":"压抑","pinyin":"yāyì","vi":"kìm nén"}],"traditional":"發泄"},{"id":"发源地","hanzi":"发源地","pinyin":"fāyuándì","meaning_vi":"nơi bắt nguồn, cái nôi (văn minh/dòng sông)","explanation":"发源 (bắt nguồn) + 地 (đất).","hsk_level":6,"tags":["danh-tu","dia-diem","van-hoa"],"image":"🌊","examples":[{"type":"basic","zh":"这里是黄河的发源地。","pinyin":"Zhèlǐ shì Huánghé de fāyuándì.","vi":"Đây là nơi bắt nguồn của sông Hoàng Hà."},{"type":"simple","zh":"希腊被称为西方文明的发源地。","pinyin":"Xīlà bèi chēngwéi Xīfāng wénmíng de fāyuándì.","vi":"Hy Lạp được gọi là cái nôi của văn minh phương Tây."},{"type":"compound","zh":"既然这里是茶文化的发源地，我们就一定要尝尝当地的茶。","pinyin":"Jìrán zhèlǐ shì chá wénhuà de fāyuándì, wǒmen jiù yídìngyào cháng chang dāngdì de chá.","vi":"Đã đến cái nôi của văn hóa trà thì chúng ta nhất định phải nếm thử trà địa phương."}],"related":[{"hanzi":"起源","pinyin":"qǐyuán","vi":"khởi nguồn"},{"hanzi":"摇篮","pinyin":"yáolán","vi":"cái nôi"},{"hanzi":"源头","pinyin":"yuántóu","vi":"đầu nguồn"},{"hanzi":"发祥地","pinyin":"fāxiángdì","vi":"nơi phát tích"}],"traditional":"發源地"},{"id":"发扬光大","hanzi":"发扬光大","pinyin":"fāyáng-guāngdà","meaning_vi":"phát huy rạng rỡ rộng lớn","explanation":"发扬 (phát dương – phát huy) + 光大 (quang đại – làm cho rạng rỡ to lớn) → phát huy và làm rạng rỡ thêm truyền thống, tinh thần, sự nghiệp tốt đẹp.","hsk_level":6,"tags":["thanh-ngu"],"image":"🌟","examples":[{"type":"basic","zh":"传统美德要发扬光大。","pinyin":"Chuántǒng měidé yào fāyángguāngdà.","vi":"Đức tính truyền thống cần được phát huy rạng rỡ."},{"type":"simple","zh":"年轻一代把这门手艺发扬光大了。","pinyin":"Niánqīng yídài bǎ zhè mén shǒuyì fāyángguāngdà le.","vi":"Thế hệ trẻ đã phát huy rộng rãi nghề thủ công này."},{"type":"compound","zh":"只有不断创新，京剧艺术才能真正发扬光大。","pinyin":"Zhǐyǒu búduàn chuàngxīn, Jīngjù yìshù cáinéng zhēnzhèng fāyángguāngdà.","vi":"Chỉ có không ngừng đổi mới, nghệ thuật Kinh kịch mới thực sự được phát huy rạng rỡ."}],"related":[{"hanzi":"发扬","pinyin":"fāyáng","vi":"phát huy"},{"hanzi":"继承","pinyin":"jìchéng","vi":"kế thừa"},{"hanzi":"弘扬","pinyin":"hóngyáng","vi":"phát huy rộng rãi"},{"hanzi":"传承","pinyin":"chuánchéng","vi":"truyền thừa"}],"traditional":"發揚光大"},{"id":"发育","hanzi":"发育","pinyin":"fāyù","meaning_vi":"phát triển thể chất","explanation":"发 (phát – phát triển) + 育 (dục – nuôi lớn) → sinh vật lớn lên và trưởng thành về cơ thể. Thường gặp: 发育期 (tuổi dậy thì), 发育不良.","hsk_level":6,"tags":["dong-tu"],"image":"🌱","examples":[{"type":"basic","zh":"孩子发育得很好。","pinyin":"Háizi fāyù de hěn hǎo.","vi":"Đứa trẻ phát triển rất tốt."},{"type":"simple","zh":"青春期的孩子正处在身体发育的关键阶段。","pinyin":"Qīngchūnqī de háizi zhèng chǔzài shēntǐ fāyù de guānjiàn jiēduàn.","vi":"Trẻ tuổi dậy thì đang ở giai đoạn then chốt của sự phát triển thể chất."},{"type":"compound","zh":"如果营养跟不上，孩子的发育就会受到影响。","pinyin":"Rúguǒ yíngyǎng gēnbushàng, háizi de fāyù jiù huì shòudào yǐngxiǎng.","vi":"Nếu dinh dưỡng không theo kịp, sự phát triển của trẻ sẽ bị ảnh hưởng."}],"related":[{"hanzi":"成长","pinyin":"chéngzhǎng","vi":"trưởng thành"},{"hanzi":"生长","pinyin":"shēngzhǎng","vi":"sinh trưởng"},{"hanzi":"青春期","pinyin":"qīngchūnqī","vi":"tuổi dậy thì"},{"hanzi":"发育不良","pinyin":"fāyùbùliáng","vi":"phát triển kém"}],"traditional":"發育"},{"id":"翻来覆去","hanzi":"翻来覆去","pinyin":"fānlái-fùqù","meaning_vi":"trằn trọc lật qua lật lại (khó ngủ / suy nghĩ mãi)","explanation":"翻来 (lật qua) + 覆去 (úp lại) → nằm trằn trọc lật qua lật lại không ngủ được; cũng chỉ lặp đi lặp lại nhiều lần một việc, một câu.","hsk_level":6,"tags":["thanh-ngu"],"image":"🛏️","examples":[{"type":"basic","zh":"他翻来覆去睡不着。","pinyin":"Tā fānláifùqù shuìbuzháo.","vi":"Anh ấy trằn trọc mãi không ngủ được."},{"type":"simple","zh":"这件事她翻来覆去地想了一整夜。","pinyin":"Zhè jiàn shì tā fānláifùqù de xiǎngle yì zhěngyè.","vi":"Chuyện này cô ấy cứ nghĩ đi nghĩ lại suốt cả đêm."},{"type":"compound","zh":"他虽然翻来覆去解释了很多遍，但是客户还是不明白。","pinyin":"Tā suīrán fānláifùqù jiěshìle hěn duō biàn, dànshì kèhù háishi bù míngbai.","vi":"Tuy anh ấy đã giải thích đi giải thích lại nhiều lần nhưng khách hàng vẫn không hiểu."}],"related":[{"hanzi":"辗转反侧","pinyin":"zhǎnzhuǎnfǎncè","vi":"trằn trọc"},{"hanzi":"失眠","pinyin":"shīmián","vi":"mất ngủ"},{"hanzi":"反复","pinyin":"fǎnfù","vi":"lặp đi lặp lại"},{"hanzi":"左思右想","pinyin":"zuǒsīyòuxiǎng","vi":"nghĩ tới nghĩ lui"}],"traditional":"翻來覆去"},{"id":"翻天覆地","hanzi":"翻天覆地","pinyin":"fāntiān-fùdì","meaning_vi":"long trời lở đất (thay đổi to lớn)","explanation":"翻天覆地: lật trời úp đất → biến đổi cực kỳ to lớn, long trời lở đất; cũng chỉ ồn ào náo loạn. Cụm: 发生了翻天覆地的变化.","hsk_level":6,"tags":["thanh-ngu"],"image":"🌍","examples":[{"type":"basic","zh":"家乡变化翻天覆地。","pinyin":"Jiāxiāng biànhuà fāntiānfùdì.","vi":"Quê hương thay đổi long trời lở đất."},{"type":"simple","zh":"孩子们在客厅里闹得翻天覆地。","pinyin":"Háizimen zài kètīng li nào de fāntiānfùdì.","vi":"Bọn trẻ quậy tung trời trong phòng khách."},{"type":"compound","zh":"虽然只离开了十年，但是这座城市已经发生了翻天覆地的变化。","pinyin":"Suīrán zhǐ líkāile shí nián, dànshì zhè zuò chéngshì yǐjīng fāshēngle fāntiānfùdì de biànhuà.","vi":"Tuy chỉ xa cách mười năm nhưng thành phố này đã thay đổi long trời lở đất."}],"related":[{"hanzi":"天翻地覆","pinyin":"tiānfāndìfù","vi":"trời long đất lở"},{"hanzi":"巨变","pinyin":"jùbiàn","vi":"thay đổi to lớn"},{"hanzi":"日新月异","pinyin":"rìxīnyuèyì","vi":"thay đổi từng ngày"},{"hanzi":"一成不变","pinyin":"yìchéngbúbiàn","vi":"không hề thay đổi"}]},{"id":"方位","hanzi":"方位","pinyin":"fāngwèi","meaning_vi":"phương vị, hướng","explanation":"方 (phương – hướng) + 位 (vị – vị trí) → phương hướng và vị trí (đông tây nam bắc, trên dưới trái phải). Thường gặp: 方位词 (từ chỉ phương vị).","hsk_level":6,"tags":["danh-tu","phuong-huong"],"image":"🧭","examples":[{"type":"basic","zh":"我分不清方位了。","pinyin":"Wǒ fēn buqīng fāngwèi le.","vi":"Tôi không phân biệt được phương hướng nữa."},{"type":"simple","zh":"古人常常靠北极星来判断方位。","pinyin":"Gǔrén chángcháng kào Běijíxīng lái pànduàn fāngwèi.","vi":"Người xưa thường dựa vào sao Bắc Cực để xác định phương hướng."},{"type":"compound","zh":"因为这套房子的方位很好，所以一年四季阳光都很充足。","pinyin":"Yīnwèi zhè tào fángzi de fāngwèi hěn hǎo, suǒyǐ yì nián sìjì yángguāng dōu hěn chōngzú.","vi":"Vì căn nhà này có hướng rất tốt nên quanh năm đều đầy đủ ánh nắng."}],"related":[{"hanzi":"方向","pinyin":"fāngxiàng","vi":"phương hướng"},{"hanzi":"位置","pinyin":"wèizhi","vi":"vị trí"},{"hanzi":"东南西北","pinyin":"dōngnánxīběi","vi":"đông nam tây bắc"},{"hanzi":"定位","pinyin":"dìngwèi","vi":"định vị"}]},{"id":"方圆","hanzi":"方圆","pinyin":"fāngyuán","meaning_vi":"chu vi, vùng xung quanh (bán kính)","explanation":"方 (vuông) + 圆 (tròn).","hsk_level":6,"tags":["danh-tu","so-luong"],"image":"⭕","examples":[{"type":"basic","zh":"方圆十里都是农田。","pinyin":"Fāngyuán shí lǐ dōu shì nóngtián.","vi":"Trong vòng mười dặm xung quanh đều là ruộng đồng."},{"type":"simple","zh":"他是方圆几百里有名的老中医。","pinyin":"Tā shì fāngyuán jǐ Bǎilǐ yǒumíng de lǎo zhōngyī.","vi":"Ông ấy là thầy thuốc Đông y nổi tiếng khắp vùng mấy trăm dặm."},{"type":"compound","zh":"爆炸声一响，方圆几公里的居民就都听到了。","pinyin":"Bàozhà shēng yì xiǎng, fāngyuán jǐ gōnglǐ de jūmín jiù dōu tīngdào le.","vi":"Tiếng nổ vừa vang lên, cư dân trong bán kính vài cây số đều nghe thấy."}],"related":[{"hanzi":"周围","pinyin":"zhōuwéi","vi":"xung quanh"},{"hanzi":"范围","pinyin":"fànwéi","vi":"phạm vi"},{"hanzi":"附近","pinyin":"fùjìn","vi":"lân cận"},{"hanzi":"方圆百里","pinyin":"fāngyuánbǎilǐ","vi":"trong vòng trăm dặm"}],"traditional":"方圓"},{"id":"非得","hanzi":"非得","pinyin":"fēiděi","meaning_vi":"nhất định phải, bằng được","explanation":"非 + 得 (đọc děi - phải).","hsk_level":6,"tags":["pho-tu"],"image":"❗","examples":[{"type":"basic","zh":"你非得今天去吗？","pinyin":"Nǐ fēiděi jīntiān qù ma?","vi":"Bạn nhất định phải đi hôm nay sao?"},{"type":"simple","zh":"这种病非得做手术才能治好。","pinyin":"Zhè zhǒng bìng fēiděi zuò shǒushù cáinéng zhìhǎo.","vi":"Bệnh này nhất định phải phẫu thuật mới chữa khỏi."},{"type":"compound","zh":"虽然外面下着大雨，但是孩子非得出去踢球。","pinyin":"Suīrán wàimiàn xiàzhe dàyǔ, dànshì háizi fēiděi chūqù tī qiú.","vi":"Tuy bên ngoài đang mưa to nhưng đứa trẻ cứ nhất quyết đòi ra ngoài đá bóng."}],"related":[{"hanzi":"必须","pinyin":"bìxū","vi":"phải"},{"hanzi":"一定要","pinyin":"yídìngyào","vi":"nhất định phải"},{"hanzi":"非要","pinyin":"fēiyào","vi":"cứ phải"},{"hanzi":"不必","pinyin":"búbì","vi":"không cần"}]},{"id":"飞黄腾达","hanzi":"飞黄腾达","pinyin":"fēihuáng-téngdá","meaning_vi":"lên như diều gặp gió, thăng quan tiến chức nhanh","explanation":"飞黄 (Phi Hoàng – tên ngựa thần) + 腾达 (đằng đạt – phi vút lên) → ngựa thần phi nhanh vút lên (thơ Hàn Dũ) → ví thăng quan tiến chức nhanh, giàu sang hiển đạt.","hsk_level":6,"tags":["thanh-ngu"],"image":"🚀","examples":[{"type":"basic","zh":"他梦想飞黄腾达。","pinyin":"Tā mèngxiǎng Fēihuángténgdá.","vi":"Anh ta mơ được thăng tiến vùn vụt."},{"type":"simple","zh":"他当上经理以后就飞黄腾达了。","pinyin":"Tā dāngshàng jīnglǐ yǐhòu jiù Fēihuángténgdá le.","vi":"Sau khi lên làm giám đốc, anh ấy thăng tiến như diều gặp gió."},{"type":"compound","zh":"即使将来飞黄腾达了，你也不要忘记帮助过你的人。","pinyin":"Jíshǐ jiānglái Fēihuángténgdá le, nǐ yě bú yào wàngjì bāngzhùguo nǐ de rén.","vi":"Cho dù sau này có công thành danh toại, bạn cũng đừng quên những người đã giúp đỡ mình."}],"related":[{"hanzi":"青云直上","pinyin":"qīngyúnzhíshàng","vi":"một bước lên mây"},{"hanzi":"步步高升","pinyin":"bùbùgāoshēng","vi":"từng bước thăng tiến"},{"hanzi":"扶摇直上","pinyin":"fúyáozhíshàng","vi":"bay thẳng lên cao"},{"hanzi":"穷困潦倒","pinyin":"qióngkùnliáodǎo","vi":"nghèo túng khổ sở"}],"traditional":"飛黃騰達"},{"id":"飞禽走兽","hanzi":"飞禽走兽","pinyin":"fēiqín-zǒushòu","meaning_vi":"chim bay thú chạy","explanation":"飞禽 (phi cầm – chim bay) + 走兽 (tẩu thú – thú chạy) → chim muông cầm thú nói chung, mọi loài động vật trên trời dưới đất.","hsk_level":6,"tags":["thanh-ngu"],"image":"🦅","examples":[{"type":"basic","zh":"森林里有很多飞禽走兽。","pinyin":"Sēnlín li yǒu hěn duō fēiqínzǒushòu.","vi":"Trong rừng có rất nhiều chim muông thú vật."},{"type":"simple","zh":"这幅古画上画满了各种飞禽走兽。","pinyin":"Zhè fú gǔ huà shang huà mǎnle gèzhǒng fēiqínzǒushòu.","vi":"Bức tranh cổ này vẽ đầy các loài chim muông thú vật."},{"type":"compound","zh":"自从这里建立了保护区，飞禽走兽就越来越多了。","pinyin":"Zìcóng zhèlǐ jiànlìle bǎohùqū, fēiqínzǒushòu jiù yuèláiyuè duō le.","vi":"Từ khi nơi đây thành lập khu bảo tồn, chim muông thú vật ngày càng nhiều."}],"related":[{"hanzi":"动物","pinyin":"dòngwù","vi":"động vật"},{"hanzi":"鸟类","pinyin":"niǎolèi","vi":"loài chim"},{"hanzi":"野兽","pinyin":"yěshòu","vi":"thú hoang"},{"hanzi":"禽兽","pinyin":"qínshòu","vi":"cầm thú"}],"traditional":"飛禽走獸"},{"id":"飞逝","hanzi":"飞逝","pinyin":"fēishì","meaning_vi":"trôi qua nhanh như bay (thời gian)","explanation":"飞 (bay) + 逝 (trôi đi). Cụm: 光阴似箭，日月如梭 / 时间飞逝.","hsk_level":6,"tags":["dong-tu","thoi-gian"],"image":"⏳","examples":[{"type":"basic","zh":"时光飞逝，转眼一年。","pinyin":"Shíguāng fēishì, zhuǎnyǎn yì nián.","vi":"Thời gian trôi nhanh, chớp mắt đã một năm."},{"type":"simple","zh":"大学四年在忙碌中飞逝而过。","pinyin":"Dàxué sì nián zài mánglù zhōng fēishì ér guò.","vi":"Bốn năm đại học trôi vèo qua trong bận rộn."},{"type":"compound","zh":"假期一开始，日子就像流星一样飞逝。","pinyin":"Jiàqī yì kāishǐ, rìzi jiù xiàng liúxīng yíyàng fēishì.","vi":"Kỳ nghỉ vừa bắt đầu, ngày tháng đã trôi vụt qua như sao băng."}],"related":[{"hanzi":"流逝","pinyin":"liúshì","vi":"trôi qua"},{"hanzi":"光阴似箭","pinyin":"guāngyīnsìjiàn","vi":"thời gian như tên bay"},{"hanzi":"转瞬即逝","pinyin":"zhuǎnshùnjíshì","vi":"thoáng chốc đã qua"},{"hanzi":"岁月","pinyin":"suìyuè","vi":"năm tháng"}],"traditional":"飛逝"},{"id":"非同小可","hanzi":"非同小可","pinyin":"fēitóng-xiǎokě","meaning_vi":"không phải chuyện nhỏ, vô cùng quan trọng","explanation":"非同 (không giống) + 小可 (tiểu khả – chuyện nhỏ bình thường) → không phải chuyện thường, rất nghiêm trọng hoặc rất quan trọng.","hsk_level":6,"tags":["thanh-ngu"],"image":"❗","examples":[{"type":"basic","zh":"这件事非同小可。","pinyin":"Zhè jiàn shì fēitóngxiǎokě.","vi":"Chuyện này không phải chuyện nhỏ."},{"type":"simple","zh":"医生的一个小失误可能造成非同小可的后果。","pinyin":"Yīshēng de yí gè xiǎo shīwù kěnéng zàochéng fēitóngxiǎokě de hòuguǒ.","vi":"Một sai sót nhỏ của bác sĩ có thể gây ra hậu quả vô cùng nghiêm trọng."},{"type":"compound","zh":"既然问题非同小可，我们就得马上向领导汇报。","pinyin":"Jìrán wèntí fēitóngxiǎokě, wǒmen jiù děi mǎshàng xiàng lǐngdǎo huìbào.","vi":"Vấn đề đã hệ trọng như vậy thì chúng ta phải báo cáo lãnh đạo ngay."}],"related":[{"hanzi":"至关重要","pinyin":"zhìguānzhòngyào","vi":"vô cùng quan trọng"},{"hanzi":"事关重大","pinyin":"shìguānzhòngdà","vi":"việc hệ trọng"},{"hanzi":"无关紧要","pinyin":"wúguānjǐnyào","vi":"không quan trọng"},{"hanzi":"严重","pinyin":"yánzhòng","vi":"nghiêm trọng"}]},{"id":"分辨","hanzi":"分辨","pinyin":"fēnbiàn","meaning_vi":"phân biệt, nhìn rõ","explanation":"分 (phân – chia) + 辨 (biện – phân biệt) → phân biệt, nhận rõ sự khác nhau. Ví dụ: 分辨真假, 分辨是非. Chú ý phân biệt với 分辩 (biện bạch).","hsk_level":6,"tags":["dong-tu"],"image":"🔍","examples":[{"type":"basic","zh":"这对双胞胎很难分辨。","pinyin":"Zhè duì shuāngbāotāi hěn nán fēnbiàn.","vi":"Cặp song sinh này rất khó phân biệt."},{"type":"simple","zh":"小孩子还不能分辨是非对错。","pinyin":"Xiǎoháizi hái bù néng fēnbiàn shìfēi duìcuò.","vi":"Trẻ nhỏ chưa biết phân biệt phải trái đúng sai."},{"type":"compound","zh":"因为雾太大，所以司机分辨不出前面的路标。","pinyin":"Yīnwèi wù tài dà, suǒyǐ sījī fēnbiàn bu chū qiánmiàn de lùbiāo.","vi":"Vì sương mù quá dày nên tài xế không nhìn rõ biển báo phía trước."}],"related":[{"hanzi":"辨别","pinyin":"biànbié","vi":"phân biệt"},{"hanzi":"区分","pinyin":"qūfēn","vi":"phân biệt"},{"hanzi":"识别","pinyin":"shíbié","vi":"nhận biết"},{"hanzi":"分辨率","pinyin":"fēnbiànlǜ","vi":"độ phân giải"}]},{"id":"分崩离析","hanzi":"分崩离析","pinyin":"fēnbēng-líxī","meaning_vi":"tan rã, chia năm xẻ bảy","explanation":"分崩 (phân băng – chia ra sụp đổ) + 离析 (ly tích – tách rời) → tan rã, sụp đổ, chia năm xẻ bảy; thường nói về quốc gia, tổ chức (Luận Ngữ).","hsk_level":6,"tags":["thanh-ngu"],"image":"💔","examples":[{"type":"basic","zh":"帝国最终分崩离析。","pinyin":"Dìguó zuìzhōng fēnbēnglíxī.","vi":"Đế quốc cuối cùng đã tan rã."},{"type":"simple","zh":"那支乐队因为内讧而分崩离析了。","pinyin":"Nà zhī yuèduì yīnwèi nèihòng ér fēnbēnglíxī le.","vi":"Ban nhạc đó đã tan rã vì đấu đá nội bộ."},{"type":"compound","zh":"如果领导层继续争吵，这个公司迟早会分崩离析。","pinyin":"Rúguǒ lǐngdǎocéng jìxù zhēngchǎo, zhè ge gōngsī chízǎo huì fēnbēnglíxī.","vi":"Nếu ban lãnh đạo tiếp tục cãi vã, công ty này sớm muộn cũng sẽ tan rã."}],"related":[{"hanzi":"四分五裂","pinyin":"sìfēnwǔliè","vi":"chia năm xẻ bảy"},{"hanzi":"土崩瓦解","pinyin":"tǔbēngwǎjiě","vi":"tan rã"},{"hanzi":"瓦解","pinyin":"wǎjiě","vi":"tan rã"},{"hanzi":"团结一致","pinyin":"tuánjiéyízhì","vi":"đoàn kết nhất trí"}],"traditional":"分崩離析"},{"id":"分道扬镳","hanzi":"分道扬镳","pinyin":"fēndào-yángbiāo","meaning_vi":"đường ai nấy đi (chia tay vì khác chí hướng)","explanation":"分道 (chia đường) + 扬镳 (dương tiêu – giật hàm thiếc cho ngựa đi) → mỗi người thúc ngựa đi một đường → ví chia tay, mỗi người theo một chí hướng riêng.","hsk_level":6,"tags":["thanh-ngu"],"image":"🔀","examples":[{"type":"basic","zh":"毕业后他们分道扬镳了。","pinyin":"Bìyè hòu tāmen fēndàoyángbiāo le.","vi":"Sau khi tốt nghiệp, họ mỗi người một ngả."},{"type":"simple","zh":"合作十年的两位歌手去年正式分道扬镳。","pinyin":"Hézuò shí nián de liǎng wèi gēshǒu qùnián zhèngshì fēndàoyángbiāo.","vi":"Hai ca sĩ hợp tác mười năm đã chính thức chia tay vào năm ngoái."},{"type":"compound","zh":"既然我们的目标完全不同，那就不如早点分道扬镳。","pinyin":"Jìrán wǒmen de mùbiāo wánquán bùtóng, nà jiù bùrú zǎodiǎn fēndàoyángbiāo.","vi":"Nếu mục tiêu của chúng ta đã hoàn toàn khác nhau thì chi bằng sớm đường ai nấy đi."}],"related":[{"hanzi":"各奔东西","pinyin":"gèbèndōngxī","vi":"mỗi người một ngả"},{"hanzi":"分手","pinyin":"fēnshǒu","vi":"chia tay"},{"hanzi":"志同道合","pinyin":"zhìtóngdàohé","vi":"cùng chí hướng"},{"hanzi":"分离","pinyin":"fēnlí","vi":"chia lìa"}],"traditional":"分道揚鑣"},{"id":"分裂","hanzi":"分裂","pinyin":"fēnliè","meaning_vi":"phân chia, tách ra; chia rẽ, chia cắt","explanation":"分 (phân – chia) + 裂 (liệt – nứt, vỡ) → chia rẽ, tách ra (tổ chức, quốc gia); trong sinh học là phân bào. Ví dụ: 国家分裂, 细胞分裂.","hsk_level":6,"tags":["dong-tu"],"image":"💔","examples":[{"type":"basic","zh":"细胞正在分裂。","pinyin":"Xìbāo zhèngzài fēnliè.","vi":"Tế bào đang phân chia."},{"type":"simple","zh":"这场争论使党内出现了分裂。","pinyin":"Zhè chǎng zhēnglùn shǐ dǎngnèi chūxiànle fēnliè.","vi":"Cuộc tranh cãi này khiến nội bộ đảng xuất hiện sự chia rẽ."},{"type":"compound","zh":"只要大家团结一心，谁也无法分裂我们。","pinyin":"Zhǐyào dàjiā tuánjié yìxīn, shéi yě wúfǎ fēnliè wǒmen.","vi":"Chỉ cần mọi người đồng lòng đoàn kết thì không ai có thể chia rẽ chúng ta."}],"related":[{"hanzi":"分离","pinyin":"fēnlí","vi":"tách rời"},{"hanzi":"分化","pinyin":"fēnhuà","vi":"phân hóa"},{"hanzi":"统一","pinyin":"tǒngyī","vi":"thống nhất"},{"hanzi":"团结","pinyin":"tuánjié","vi":"đoàn kết"}]},{"id":"分歧","hanzi":"分歧","pinyin":"fēnqí","meaning_vi":"bất đồng ý kiến","explanation":"分 (phân – chia) + 歧 (kỳ – ngã rẽ) → chỗ khác nhau, bất đồng (ý kiến, quan điểm). Thường gặp: 意见分歧, 存在分歧, 消除分歧.","hsk_level":6,"tags":["danh-tu"],"image":"🔀","examples":[{"type":"basic","zh":"我们存在一些分歧。","pinyin":"Wǒmen cúnzài yìxiē fēnqí.","vi":"Chúng tôi có một số bất đồng."},{"type":"simple","zh":"夫妻俩在孩子教育问题上有很大分歧。","pinyin":"Fūqī liǎ zài háizi jiàoyù wèntí shang yǒu hěn dà fēnqí.","vi":"Hai vợ chồng có bất đồng lớn về vấn đề giáo dục con cái."},{"type":"compound","zh":"虽然双方有分歧，但是最后还是达成了协议。","pinyin":"Suīrán shuāngfāng yǒu fēnqí, dànshì zuìhòu háishi dáchéngle xiéyì.","vi":"Tuy hai bên có bất đồng nhưng cuối cùng vẫn đạt được thỏa thuận."}],"related":[{"hanzi":"分歧意见","pinyin":"fēnqíyìjiàn","vi":"ý kiến bất đồng"},{"hanzi":"争议","pinyin":"zhēngyì","vi":"tranh cãi"},{"hanzi":"矛盾","pinyin":"máodùn","vi":"mâu thuẫn"},{"hanzi":"共识","pinyin":"gòngshí","vi":"nhận thức chung"}]},{"id":"丰碑","hanzi":"丰碑","pinyin":"fēngbēi","meaning_vi":"tượng đài, công lao to lớn bất hủ","explanation":"丰 (to lớn) + 碑 (bia đá).","hsk_level":6,"tags":["danh-tu","van-hoa"],"image":"🗿","examples":[{"type":"basic","zh":"他在人们心中立起了丰碑。","pinyin":"Tā zài rénmen xīn zhōnglì qǐle fēngbēi.","vi":"Ông ấy đã dựng nên một tượng đài trong lòng mọi người."},{"type":"simple","zh":"这部作品是中国文学史上的一座丰碑。","pinyin":"Zhè bù zuòpǐn shì Zhōngguó wénxué shǐshang de yí zuò fēngbēi.","vi":"Tác phẩm này là một tượng đài trong lịch sử văn học Trung Quốc."},{"type":"compound","zh":"因为他一生致力于治沙，所以人们把那片绿洲称为他的丰碑。","pinyin":"Yīnwèi tā yìshēng zhìlìyú zhì shā, suǒyǐ rénmen bǎ nà piàn lǜzhōu chēngwéi tā de fēngbēi.","vi":"Vì cả đời ông cống hiến cho việc chống sa mạc hóa nên người ta gọi ốc đảo xanh ấy là tượng đài của ông."}],"related":[{"hanzi":"纪念碑","pinyin":"jìniànbēi","vi":"bia tưởng niệm"},{"hanzi":"丰功伟绩","pinyin":"fēnggōngwěijì","vi":"công lao to lớn"},{"hanzi":"里程碑","pinyin":"lǐchéngbēi","vi":"cột mốc"},{"hanzi":"功绩","pinyin":"gōngjì","vi":"công tích"}],"traditional":"豐碑"},{"id":"风波","hanzi":"风波","pinyin":"fēngbō","meaning_vi":"sóng gió, biến cố rắc rối","explanation":"风 (gió) + 波 (sóng).","hsk_level":6,"tags":["danh-tu"],"image":"🌊","examples":[{"type":"basic","zh":"这场风波终于平息了。","pinyin":"Zhè chǎng fēngbō zhōngyú píngxī le.","vi":"Cơn sóng gió này cuối cùng đã lắng xuống."},{"type":"simple","zh":"一条微博在公司内部引起了一场风波。","pinyin":"Yì tiáo wēibó zài gōngsī nèibù yǐnqǐle yì chǎng fēngbō.","vi":"Một bài đăng Weibo đã gây ra sóng gió trong nội bộ công ty."},{"type":"compound","zh":"如果当时处理得好，就不会闹出这么大的风波。","pinyin":"Rúguǒ dāngshí chǔlǐ de hǎo, jiù bú huì nào chū zhème dà de fēngbō.","vi":"Nếu lúc đó xử lý tốt thì đã không gây ra sóng gió lớn như vậy."}],"related":[{"hanzi":"风浪","pinyin":"fēnglàng","vi":"sóng gió"},{"hanzi":"纠纷","pinyin":"jiūfēn","vi":"tranh chấp"},{"hanzi":"波折","pinyin":"bōzhé","vi":"trắc trở"},{"hanzi":"平息风波","pinyin":"píngxīfēngbō","vi":"dẹp yên sóng gió"}],"traditional":"風波"},{"id":"风吹草动","hanzi":"风吹草动","pinyin":"fēngchuī-cǎodòng","meaning_vi":"gió thổi cỏ lay (dấu hiệu biến động nhỏ)","explanation":"风吹 (gió thổi) + 草动 (cỏ lay) → gió thổi làm cỏ lay động → ví chút động tĩnh, biến động nhỏ. Thường gặp: 一有风吹草动就……","hsk_level":6,"tags":["thanh-ngu"],"image":"🍃","examples":[{"type":"basic","zh":"小鹿对风吹草动很敏感。","pinyin":"Xiǎo lù duì fēngchuīcǎodòng hěn mǐngǎn.","vi":"Con nai nhỏ rất nhạy cảm với mọi động tĩnh."},{"type":"simple","zh":"股市里的任何风吹草动都会影响他的心情。","pinyin":"Gǔshì li de rènhé fēngchuīcǎodòng dōuhuì yǐngxiǎng tā de xīnqíng.","vi":"Mọi biến động nhỏ trên thị trường chứng khoán đều ảnh hưởng đến tâm trạng anh ấy."},{"type":"compound","zh":"外面一有风吹草动，看门的狗就叫个不停。","pinyin":"Wàimiàn yì yǒu fēngchuīcǎodòng, kānmén de gǒu jiù jiào gè bùtíng.","vi":"Bên ngoài hễ có động tĩnh gì, con chó giữ nhà liền sủa không ngớt."}],"related":[{"hanzi":"动静","pinyin":"dòngjing","vi":"động tĩnh"},{"hanzi":"迹象","pinyin":"jìxiàng","vi":"dấu hiệu"},{"hanzi":"变动","pinyin":"biàndòng","vi":"biến động"},{"hanzi":"草木皆兵","pinyin":"cǎomùjiēbīng","vi":"cây cỏ đều là quân địch"}],"traditional":"風吹草動"},{"id":"风光","hanzi":"风光","pinyin":"fēngguāng","meaning_vi":"phong cảnh, cảnh sắc","explanation":"风 (phong – gió, cảnh) + 光 (quang – ánh sáng) → phong cảnh, cảnh sắc; đọc fēngguang còn nghĩa vẻ vang, nở mày nở mặt. Ví dụ: 风光秀丽, 风光无限.","hsk_level":6,"tags":["danh-tu"],"image":"🌄","examples":[{"type":"basic","zh":"这里风光秀丽。","pinyin":"Zhèlǐ fēngguāng xiùlì.","vi":"Phong cảnh nơi đây tươi đẹp."},{"type":"simple","zh":"我们坐船欣赏了漓江两岸的风光。","pinyin":"Wǒmen zuò chuán xīnshǎngle Líjiāng liǎng'àn de fēngguāng.","vi":"Chúng tôi đi thuyền ngắm phong cảnh hai bờ sông Li."},{"type":"compound","zh":"既然来了云南，就不能错过玉龙雪山的风光。","pinyin":"Jìrán láile Yúnnán, jiù bù néng cuòguò Yùlóngxuěshān de fēngguāng.","vi":"Đã đến Vân Nam thì không thể bỏ lỡ phong cảnh núi tuyết Ngọc Long."}],"related":[{"hanzi":"风景","pinyin":"fēngjǐng","vi":"phong cảnh"},{"hanzi":"景色","pinyin":"jǐngsè","vi":"cảnh sắc"},{"hanzi":"风光无限","pinyin":"fēngguāngwúxiàn","vi":"phong cảnh vô hạn"},{"hanzi":"体面","pinyin":"tǐmiàn","vi":"vẻ vang"}],"traditional":"風光"},{"id":"丰功伟绩","hanzi":"丰功伟绩","pinyin":"fēnggōng-wěijì","meaning_vi":"công lao to lớn vĩ đại","explanation":"丰功 (phong công – công lao lớn) + 伟绩 (vĩ tích – thành tích vĩ đại) → công lao, sự nghiệp to lớn vĩ đại; thường nói về lãnh tụ, anh hùng.","hsk_level":6,"tags":["thanh-ngu"],"image":"🏆","examples":[{"type":"basic","zh":"他立下了丰功伟绩。","pinyin":"Tā lìxiàle fēnggōngwěijì.","vi":"Ông ấy đã lập nên công lao to lớn."},{"type":"simple","zh":"博物馆展示了大禹治水的丰功伟绩。","pinyin":"Bówùguǎn zhǎnshìle Dàyǔ zhìshuǐ de fēnggōngwěijì.","vi":"Bảo tàng trưng bày công lao vĩ đại của vua Vũ trị thủy."},{"type":"compound","zh":"虽然他建立了丰功伟绩，但是他从不居功自傲。","pinyin":"Suīrán tā jiànlìle fēnggōngwěijì, dànshì tā cóng bù jūgōng zì'ào.","vi":"Tuy ông lập nên công lao to lớn nhưng chưa bao giờ cậy công kiêu ngạo."}],"related":[{"hanzi":"功绩","pinyin":"gōngjì","vi":"công tích"},{"hanzi":"丰碑","pinyin":"fēngbēi","vi":"tượng đài"},{"hanzi":"伟大","pinyin":"wěidà","vi":"vĩ đại"},{"hanzi":"功勋","pinyin":"gōngxūn","vi":"công huân"}],"traditional":"豐功偉績"},{"id":"峰回路转","hanzi":"峰回路转","pinyin":"fēnghuí-lùzhuǎn","meaning_vi":"hết đường cùng lại mở ra lối mới, bước ngoặt bất ngờ","explanation":"峰回 (núi vòng) + 路转 (đường rẽ) → núi uốn quanh, đường quanh co (Âu Dương Tu, Túy Ông Đình Ký) → ví sự việc có bước ngoặt, tưởng bế tắc lại có lối ra.","hsk_level":6,"tags":["thanh-ngu"],"image":"⛰️","examples":[{"type":"basic","zh":"剧情峰回路转。","pinyin":"Jùqíng fēnghuílùzhuǎn.","vi":"Tình tiết phim bất ngờ đảo chiều."},{"type":"simple","zh":"这场比赛在最后一分钟峰回路转。","pinyin":"Zhè chǎng bǐsài zài zuìhòu yì fēnzhōng fēnghuílùzhuǎn.","vi":"Trận đấu này xoay chuyển bất ngờ ở phút cuối cùng."},{"type":"compound","zh":"就在我们准备放弃的时候，事情却峰回路转了。","pinyin":"Jiù zài wǒmen zhǔnbèi fàngqì de shíhou, shìqing què fēnghuílùzhuǎn le.","vi":"Đúng lúc chúng tôi định bỏ cuộc thì sự việc lại xoay chuyển bất ngờ."}],"related":[{"hanzi":"柳暗花明","pinyin":"liǔ'ànhuāmíng","vi":"liễu rủ hoa tươi (lối mới)"},{"hanzi":"转机","pinyin":"zhuǎnjī","vi":"bước ngoặt"},{"hanzi":"山重水复","pinyin":"shānchóngshuǐfù","vi":"núi non trùng điệp"},{"hanzi":"绝处逢生","pinyin":"juéchùféngshēng","vi":"tìm được lối sống nơi tuyệt cảnh"}],"traditional":"峰迴路轉"},{"id":"风和日丽","hanzi":"风和日丽","pinyin":"fēnghé-rìlì","meaning_vi":"gió hòa nắng đẹp (thời tiết tuyệt đẹp)","explanation":"风和 (gió hiền hòa) + 日丽 (nắng tươi đẹp) → trời trong gió nhẹ nắng đẹp, thời tiết dễ chịu; hay dùng tả ngày xuân.","hsk_level":6,"tags":["thanh-ngu","thoi-tiet"],"image":"☀️","examples":[{"type":"basic","zh":"今天风和日丽。","pinyin":"Jīntiān fēnghérìlì.","vi":"Hôm nay trời trong gió nhẹ."},{"type":"simple","zh":"在一个风和日丽的周末，我们去郊外野餐。","pinyin":"Zài yí gè fēnghérìlì de zhōumò, wǒmen qù jiāowài yěcān.","vi":"Vào một cuối tuần nắng đẹp, chúng tôi đi dã ngoại ở ngoại ô."},{"type":"compound","zh":"只要明天风和日丽，运动会就照常举行。","pinyin":"Zhǐyào míngtiān fēnghérìlì, yùndònghuì jiù zhàocháng jǔxíng.","vi":"Chỉ cần ngày mai trời đẹp, hội thao sẽ diễn ra như thường lệ."}],"related":[{"hanzi":"晴空万里","pinyin":"qíngkōngwànlǐ","vi":"bầu trời trong xanh"},{"hanzi":"阳光明媚","pinyin":"yángguāngmíngmèi","vi":"nắng đẹp rực rỡ"},{"hanzi":"风雨交加","pinyin":"fēngyǔjiāojiā","vi":"mưa gió dữ dội"},{"hanzi":"天气","pinyin":"tiānqì","vi":"thời tiết"}],"traditional":"風和日麗"},{"id":"风起云涌","hanzi":"风起云涌","pinyin":"fēngqǐ-yúnyǒng","meaning_vi":"gió nổi mây vần (phong trào phát triển mạnh mẽ)","explanation":"风起 (gió nổi) + 云涌 (mây cuộn) → gió nổi mây cuộn → ví sự việc, phong trào nổi lên mạnh mẽ, dồn dập.","hsk_level":6,"tags":["thanh-ngu"],"image":"🌪️","examples":[{"type":"basic","zh":"各地起义风起云涌。","pinyin":"Gèdì qǐyì fēngqǐyúnyǒng.","vi":"Các cuộc khởi nghĩa nổi lên khắp nơi như vũ bão."},{"type":"simple","zh":"当时风起云涌的学生运动影响了整个国家。","pinyin":"Dāngshí fēngqǐyúnyǒng de xuésheng yùndòng yǐngxiǎngle zhěnggè guójiā.","vi":"Phong trào sinh viên dâng cao lúc bấy giờ đã ảnh hưởng đến cả đất nước."},{"type":"compound","zh":"近几年人工智能创业不但风起云涌，而且吸引了大量资金。","pinyin":"Jìnjǐnián réngōngzhìnéng chuàngyè búdàn fēngqǐyúnyǒng, érqiě xīyǐnle dàliàng zījīn.","vi":"Mấy năm gần đây làn sóng khởi nghiệp trí tuệ nhân tạo không những bùng nổ mạnh mẽ mà còn thu hút lượng vốn lớn."}],"related":[{"hanzi":"如火如荼","pinyin":"rúhuǒrútú","vi":"sôi sục rầm rộ"},{"hanzi":"蓬勃发展","pinyin":"péngbófāzhǎn","vi":"phát triển mạnh mẽ"},{"hanzi":"此起彼伏","pinyin":"cǐqǐbǐfú","vi":"nối tiếp nhau"},{"hanzi":"风平浪静","pinyin":"fēngpínglàngjìng","vi":"sóng yên gió lặng"}],"traditional":"風起雲湧"},{"id":"封锁","hanzi":"封锁","pinyin":"fēngsuǒ","meaning_vi":"phong tỏa","explanation":"封 (phong – niêm, đóng) + 锁 (tỏa – khóa) → bịt kín, cắt đứt liên lạc, không cho ra vào. Thường gặp: 封锁消息, 经济封锁, 封锁现场.","hsk_level":6,"tags":["dong-tu"],"image":"🚧","examples":[{"type":"basic","zh":"警察封锁了现场。","pinyin":"Jǐngchá fēngsuǒle xiànchǎng.","vi":"Cảnh sát đã phong tỏa hiện trường."},{"type":"simple","zh":"大雪封锁了进山的唯一一条公路。","pinyin":"Dàxuě fēngsuǒle jìn shān de wéi yīyī tiáo gōnglù.","vi":"Tuyết lớn đã phong tỏa con đường duy nhất vào núi."},{"type":"compound","zh":"因为消息被严密封锁，所以外界对此一无所知。","pinyin":"Yīnwèi xiāoxi bèi yánmì fēngsuǒ, suǒyǐ wàijiè duì cǐ yìwúsuǒzhī.","vi":"Vì tin tức bị phong tỏa chặt chẽ nên bên ngoài không hề hay biết gì."}],"related":[{"hanzi":"封闭","pinyin":"fēngbì","vi":"phong tỏa, đóng cửa"},{"hanzi":"封锁线","pinyin":"fēngsuǒxiàn","vi":"tuyến phong tỏa"},{"hanzi":"开放","pinyin":"kāifàng","vi":"mở cửa"},{"hanzi":"封城","pinyin":"fēngchéng","vi":"phong tỏa thành phố"}],"traditional":"封鎖"},{"id":"风土人情","hanzi":"风土人情","pinyin":"fēngtǔ-rénqíng","meaning_vi":"phong tục tập quán địa phương","explanation":"风土 (phong thổ – khí hậu, đất đai) + 人情 (nhân tình – phong tục, tình người) → đặc điểm tự nhiên và phong tục tập quán của một vùng.","hsk_level":6,"tags":["thanh-ngu"],"image":"🏮","examples":[{"type":"basic","zh":"我喜欢了解风土人情。","pinyin":"Wǒ xǐhuan liǎojiě fēngtǔrénqíng.","vi":"Tôi thích tìm hiểu phong tục tập quán các nơi."},{"type":"simple","zh":"这本游记介绍了西藏独特的风土人情。","pinyin":"Zhè běn yóujì jièshàole Xīzàng dútè de fēngtǔrénqíng.","vi":"Cuốn du ký này giới thiệu phong tục tập quán độc đáo của Tây Tạng."},{"type":"compound","zh":"与其跟着旅行团匆匆拍照，不如住下来慢慢体会当地的风土人情。","pinyin":"Yǔqí gēnzhe lǚxíngtuán cōngcōng pāizhào, bùrú zhù xiàlái mànmàn tǐhuì dāngdì de fēngtǔrénqíng.","vi":"Thay vì theo đoàn du lịch vội vã chụp ảnh, chi bằng ở lại từ từ cảm nhận phong tục tập quán địa phương."}],"related":[{"hanzi":"风俗","pinyin":"fēngsú","vi":"phong tục"},{"hanzi":"民俗","pinyin":"mínsú","vi":"dân gian, phong tục"},{"hanzi":"习俗","pinyin":"xísú","vi":"tập tục"},{"hanzi":"人情世故","pinyin":"rénqíngshìgù","vi":"nhân tình thế thái"}],"traditional":"風土人情"},{"id":"风韵","hanzi":"风韵","pinyin":"fēngyùn","meaning_vi":"phong vận, nét duyên dáng thanh nhã","explanation":"风 + 韵 (vần điệu/duyên).","hsk_level":6,"tags":["danh-tu","con-nguoi"],"image":"💃","examples":[{"type":"basic","zh":"这座古镇别有风韵。","pinyin":"Zhè zuò gǔzhèn biéyǒu fēngyùn.","vi":"Thị trấn cổ này có nét duyên dáng riêng."},{"type":"simple","zh":"这首诗带有浓厚的江南风韵。","pinyin":"Zhè shǒu shī dàiyǒu nónghòu de Jiāngnán fēngyùn.","vi":"Bài thơ này mang đậm phong vị Giang Nam."},{"type":"compound","zh":"虽然她已经五十多岁了，但是举手投足之间仍有一种独特的风韵。","pinyin":"Suīrán tā yǐjīng wǔshí duō suì le, dànshì jǔshǒu tóu zú zhījiān réng yǒu yì zhǒng dútè de fēngyùn.","vi":"Tuy bà đã ngoài năm mươi nhưng từng cử chỉ vẫn toát lên một nét duyên dáng riêng."}],"related":[{"hanzi":"韵味","pinyin":"yùnwèi","vi":"ý vị"},{"hanzi":"风度","pinyin":"fēngdù","vi":"phong độ"},{"hanzi":"气质","pinyin":"qìzhì","vi":"khí chất"},{"hanzi":"风韵犹存","pinyin":"fēngyùnyóucún","vi":"vẫn còn mặn mà"}],"traditional":"風韻"},{"id":"风雨同舟","hanzi":"风雨同舟","pinyin":"fēngyǔ-tóngzhōu","meaning_vi":"chung thuyền vượt sóng gió","explanation":"风雨 (mưa gió) + 同舟 (cùng thuyền) → cùng ngồi một thuyền vượt mưa gió → ví cùng nhau đồng cam cộng khổ, vượt qua khó khăn.","hsk_level":6,"tags":["thanh-ngu"],"image":"⛵","examples":[{"type":"basic","zh":"两国人民风雨同舟。","pinyin":"Liǎngguó rénmín fēngyǔtóngzhōu.","vi":"Nhân dân hai nước cùng chung thuyền vượt sóng gió."},{"type":"simple","zh":"这对老夫妻风雨同舟地走过了半个世纪。","pinyin":"Zhè duì lǎo fūqī fēngyǔtóngzhōu de zǒuguòle bàn gè shìjì.","vi":"Đôi vợ chồng già này đã cùng nhau vượt qua sóng gió suốt nửa thế kỷ."},{"type":"compound","zh":"只要我们风雨同舟，就没有渡不过的难关。","pinyin":"Zhǐyào wǒmen fēngyǔtóngzhōu, jiù méiyǒu dù buguò de nánguān.","vi":"Chỉ cần chúng ta đồng cam cộng khổ thì không có cửa ải nào không vượt qua được."}],"related":[{"hanzi":"同舟共济","pinyin":"tóngzhōugòngjì","vi":"đồng cam cộng khổ"},{"hanzi":"患难与共","pinyin":"huànnànyǔgòng","vi":"hoạn nạn có nhau"},{"hanzi":"齐心协力","pinyin":"qíxīnxiélì","vi":"đồng tâm hiệp lực"},{"hanzi":"分道扬镳","pinyin":"fēndàoyángbiāo","vi":"đường ai nấy đi"}],"traditional":"風雨同舟"},{"id":"诽谤","hanzi":"诽谤","pinyin":"fěibàng","meaning_vi":"phỉ báng, vu khống","explanation":"诽 (phỉ – nói xấu) + 谤 (báng – chê bai) → bịa đặt nói xấu làm tổn hại danh dự người khác, vu khống. Thường gặp: 诽谤罪, 恶意诽谤.","hsk_level":6,"tags":["dong-tu"],"image":"🗣️","examples":[{"type":"basic","zh":"他被人恶意诽谤。","pinyin":"Tā bèi rén èyì fěibàng.","vi":"Anh ấy bị người ta ác ý phỉ báng."},{"type":"simple","zh":"这位明星把诽谤自己的网友告上了法庭。","pinyin":"Zhè wèi míngxīng bǎ fěibàng zìjǐ de wǎngyǒu gào shàngle fǎtíng.","vi":"Ngôi sao này đã kiện cư dân mạng phỉ báng mình ra tòa."},{"type":"compound","zh":"如果你继续在网上诽谤他人，就要承担法律责任。","pinyin":"Rúguǒ nǐ jìxù zài wǎngshang fěibàng tārén, jiùyào chéngdān fǎlǜ zérèn.","vi":"Nếu bạn tiếp tục phỉ báng người khác trên mạng thì sẽ phải chịu trách nhiệm pháp lý."}],"related":[{"hanzi":"诬蔑","pinyin":"wūmiè","vi":"vu khống"},{"hanzi":"造谣","pinyin":"zàoyáo","vi":"tung tin đồn"},{"hanzi":"中伤","pinyin":"zhòngshāng","vi":"nói xấu"},{"hanzi":"名誉","pinyin":"míngyù","vi":"danh dự"}],"traditional":"誹謗"},{"id":"匪夷所思","hanzi":"匪夷所思","pinyin":"fěiyí-suǒsī","meaning_vi":"không thể tưởng tượng nổi, kỳ lạ khó hiểu","explanation":"匪 (phỉ – không phải) + 夷 (di – bình thường) + 所思 (điều nghĩ tới) → không phải điều người thường nghĩ ra được → kỳ quặc, khó tin, không thể tưởng tượng nổi.","hsk_level":6,"tags":["thanh-ngu"],"image":"😲","examples":[{"type":"basic","zh":"他的想法匪夷所思。","pinyin":"Tā de xiǎngfǎ fěiyísuǒsī.","vi":"Suy nghĩ của anh ta thật khó hiểu nổi."},{"type":"simple","zh":"魔术师表演了一个匪夷所思的节目。","pinyin":"Móshùshī biǎoyǎnle yí gè fěiyísuǒsī de jiémù.","vi":"Ảo thuật gia biểu diễn một tiết mục khó tin nổi."},{"type":"compound","zh":"虽然他很有钱，但是每天只吃泡面，这种行为真让人匪夷所思。","pinyin":"Suīrán tā hěn yǒuqián, dànshì měitiān zhǐ chī pàomiàn, zhè zhǒng xíngwéi zhēn ràng rén fěiyísuǒsī.","vi":"Tuy anh ta rất giàu nhưng ngày nào cũng chỉ ăn mì gói, hành vi này thật khiến người ta không thể hiểu nổi."}],"related":[{"hanzi":"不可思议","pinyin":"bùkěsīyì","vi":"không thể tin nổi"},{"hanzi":"难以置信","pinyin":"nányǐzhìxìn","vi":"khó tin"},{"hanzi":"离奇","pinyin":"líqí","vi":"ly kỳ"},{"hanzi":"理所当然","pinyin":"lǐsuǒdāngrán","vi":"lẽ đương nhiên"}]},{"id":"粉末","hanzi":"粉末","pinyin":"fěnmò","meaning_vi":"bột mịn","explanation":"粉 (phấn – bột) + 末 (mạt – vụn nhỏ) → bột mịn, chất ở dạng hạt rất nhỏ. Ví dụ: 白色粉末, 磨成粉末 (nghiền thành bột).","hsk_level":6,"tags":["danh-tu"],"image":"🧂","examples":[{"type":"basic","zh":"这是一种黄色粉末。","pinyin":"Zhè shì yì zhǒng huángsè fěnmò.","vi":"Đây là một loại bột màu vàng."},{"type":"simple","zh":"桌子上撒满了白色的粉末。","pinyin":"Zhuōzi shang sǎ mǎnle báisè de fěnmò.","vi":"Trên bàn rắc đầy bột màu trắng."},{"type":"compound","zh":"如果把咖啡豆磨成细粉末，冲出来的味道就会更浓。","pinyin":"Rúguǒ bǎ kāfēidòu mó chéng xì fěnmò, chōng chūlái de wèidào jiù huì gèng nóng.","vi":"Nếu xay hạt cà phê thành bột mịn thì vị cà phê pha ra sẽ đậm hơn."}],"related":[{"hanzi":"粉","pinyin":"fěn","vi":"bột"},{"hanzi":"面粉","pinyin":"miànfěn","vi":"bột mì"},{"hanzi":"颗粒","pinyin":"kēlì","vi":"hạt"},{"hanzi":"粉碎","pinyin":"fěnsuì","vi":"nghiền nát"}]},{"id":"夫妇","hanzi":"夫妇","pinyin":"fūfù","meaning_vi":"vợ chồng","explanation":"夫 (chồng) + 妇 (vợ). Trang trọng hơn 夫妻.","hsk_level":6,"tags":["danh-tu","gia-dinh"],"image":"💑","examples":[{"type":"basic","zh":"这对夫妇很恩爱。","pinyin":"Zhè duì fūfù hěn ēn'ài.","vi":"Đôi vợ chồng này rất yêu thương nhau."},{"type":"simple","zh":"隔壁新搬来了一对年轻夫妇。","pinyin":"Gébì xīn bān láile yíduì niánqīng fūfù.","vi":"Nhà bên vừa có một đôi vợ chồng trẻ chuyển đến."},{"type":"compound","zh":"王先生夫妇不但收养了三个孤儿，而且供他们上了大学。","pinyin":"Wáng xiānsheng fūfù búdàn shōuyǎngle sān gè gū'ér, érqiě gōng tāmen shàngle dàxué.","vi":"Vợ chồng ông Vương không những nhận nuôi ba trẻ mồ côi mà còn cho chúng học đại học."}],"related":[{"hanzi":"夫妻","pinyin":"fūqī","vi":"vợ chồng"},{"hanzi":"丈夫","pinyin":"zhàngfu","vi":"chồng"},{"hanzi":"妻子","pinyin":"qīzi","vi":"vợ"},{"hanzi":"伴侣","pinyin":"bànlǚ","vi":"bạn đời"}],"traditional":"夫婦"},{"id":"夫人","hanzi":"夫人","pinyin":"fūrén","meaning_vi":"phu nhân, bà","explanation":"夫人 (phu nhân): cách gọi trang trọng vợ của người khác, nhất là vợ người có địa vị. Ví dụ: 总统夫人, 王夫人. Không dùng để gọi vợ mình.","hsk_level":6,"tags":["danh-tu","con-nguoi"],"image":"👩","examples":[{"type":"basic","zh":"总统夫人来访。","pinyin":"Zǒngtǒng fūrén láifǎng.","vi":"Phu nhân tổng thống đến thăm."},{"type":"simple","zh":"李教授和夫人一起出席了晚宴。","pinyin":"Lǐ jiàoshòu hé fūrén yìqǐ chūxíle wǎnyàn.","vi":"Giáo sư Lý cùng phu nhân dự tiệc tối."},{"type":"compound","zh":"因为夫人身体不好，所以他推掉了所有的应酬。","pinyin":"Yīnwèi fūrén shēntǐ bù hǎo, suǒyǐ tā tuī diàole suǒyǒu de yìngchou.","vi":"Vì phu nhân sức khỏe không tốt nên ông ấy đã từ chối mọi cuộc xã giao."}],"related":[{"hanzi":"太太","pinyin":"tàitai","vi":"bà, vợ"},{"hanzi":"妻子","pinyin":"qīzi","vi":"vợ"},{"hanzi":"女士","pinyin":"nǚshì","vi":"quý bà"},{"hanzi":"丈夫","pinyin":"zhàngfu","vi":"chồng"}]},{"id":"敷衍了事","hanzi":"敷衍了事","pinyin":"fūyǎn-liǎoshì","meaning_vi":"làm qua loa đại khái cho xong việc","explanation":"敷衍 (phu diễn – làm chiếu lệ, qua quýt) + 了事 (liễu sự – cho xong việc) → làm cho có, qua loa cho xong chuyện, thiếu trách nhiệm.","hsk_level":6,"tags":["thanh-ngu"],"image":"🙈","examples":[{"type":"basic","zh":"做事不能敷衍了事。","pinyin":"Zuòshì bù néng fūyǎnliǎoshì.","vi":"Làm việc không được qua loa đại khái."},{"type":"simple","zh":"那个装修工人总是敷衍了事。","pinyin":"Nà ge zhuāngxiū gōngrén zǒngshì fūyǎnliǎoshì.","vi":"Người thợ sửa nhà đó lúc nào cũng làm qua loa cho xong."},{"type":"compound","zh":"如果你写报告敷衍了事，老板一眼就能看出来。","pinyin":"Rúguǒ nǐ xiě bàogào fūyǎnliǎoshì, lǎobǎn yìyǎn jiù néng kàn chūlái.","vi":"Nếu bạn viết báo cáo qua loa đại khái, sếp nhìn một cái là nhận ra ngay."}],"related":[{"hanzi":"马马虎虎","pinyin":"mǎmǎhūhū","vi":"qua loa"},{"hanzi":"得过且过","pinyin":"déguòqiěguò","vi":"được chăng hay chớ"},{"hanzi":"应付","pinyin":"yìngfu","vi":"đối phó"},{"hanzi":"一丝不苟","pinyin":"yìsībùgǒu","vi":"tỉ mỉ cẩn thận"}]},{"id":"法制","hanzi":"法制","pinyin":"fǎzhì","meaning_vi":"pháp chế","explanation":"法 (pháp luật) + 制 (chế độ).","hsk_level":6,"tags":["danh-tu","phap-luat"],"image":"⚖️","examples":[{"type":"basic","zh":"要加强法制教育。","pinyin":"Yào jiāqiáng fǎzhì jiàoyù.","vi":"Cần tăng cường giáo dục pháp luật."},{"type":"simple","zh":"学校每学期都会请律师来做法制讲座。","pinyin":"Xuéxiào měi xuéqī dōuhuì qǐng lǜshī lái zuò fǎzhì jiǎngzuò.","vi":"Mỗi học kỳ trường đều mời luật sư đến nói chuyện về pháp chế."},{"type":"compound","zh":"只有法制健全了，老百姓的权益才能得到保障。","pinyin":"Zhǐyǒu fǎzhì jiànquán le, lǎobǎixìng de quányì cáinéng dédào bǎozhàng.","vi":"Chỉ khi hệ thống pháp chế hoàn thiện, quyền lợi của người dân mới được bảo đảm."}],"related":[{"hanzi":"法律","pinyin":"fǎlǜ","vi":"pháp luật"},{"hanzi":"法治","pinyin":"fǎzhì","vi":"pháp trị"},{"hanzi":"制度","pinyin":"zhìdù","vi":"chế độ"},{"hanzi":"法制建设","pinyin":"fǎzhìjiànshè","vi":"xây dựng pháp chế"}]},{"id":"法治","hanzi":"法治","pinyin":"fǎzhì","meaning_vi":"pháp trị (quản lý bằng pháp luật)","explanation":"法 + 治 (cai trị).","hsk_level":6,"tags":["danh-tu","phap-luat","xa-hoi"],"image":"🏛️","examples":[{"type":"basic","zh":"法治是社会的基石。","pinyin":"Fǎzhì shì shèhuì de jīshí.","vi":"Pháp trị là nền tảng của xã hội."},{"type":"simple","zh":"这个国家正在努力建设法治社会。","pinyin":"Zhè ge guójiā zhèngzài nǔlì jiànshè fǎzhì shèhuì.","vi":"Quốc gia này đang nỗ lực xây dựng xã hội pháp trị."},{"type":"compound","zh":"在法治国家里，即使是官员违法，也要受到惩罚。","pinyin":"Zài fǎzhì guójiā li, jíshǐ shì guānyuán wéifǎ, yě yào shòudào chéngfá.","vi":"Ở quốc gia pháp trị, cho dù là quan chức phạm pháp cũng phải bị trừng phạt."}],"related":[{"hanzi":"人治","pinyin":"rénzhì","vi":"nhân trị"},{"hanzi":"依法治国","pinyin":"yīfǎzhìguó","vi":"quản lý đất nước bằng pháp luật"},{"hanzi":"法律","pinyin":"fǎlǜ","vi":"pháp luật"},{"hanzi":"法制","pinyin":"fǎzhì","vi":"pháp chế"}]},{"id":"反倒","hanzi":"反倒","pinyin":"fǎndào","meaning_vi":"trái lại","explanation":"反 (phản – ngược lại) + 倒 (đảo – lại, trái lại) → ngược lại, trái lại (kết quả trái với dự đoán). Ví dụ: 吃了药，病反倒重了. Gần nghĩa: 反而.","hsk_level":6,"tags":["pho-tu"],"image":"↩️","examples":[{"type":"basic","zh":"吃了药反倒更难受了。","pinyin":"Chīle yào fǎndào gèng nánshòu le.","vi":"Uống thuốc rồi trái lại còn khó chịu hơn."},{"type":"simple","zh":"被批评以后他反倒更努力了。","pinyin":"Bèi pīpíng yǐhòu tā fǎndào gèng nǔlì le.","vi":"Sau khi bị phê bình, trái lại anh ấy còn cố gắng hơn."},{"type":"compound","zh":"外面的雨不但没有停，反倒越下越大了。","pinyin":"Wàimiàn de yǔ búdàn méiyǒu tíng, fǎndào yuè xià yuè dà le.","vi":"Mưa bên ngoài không những không tạnh mà ngược lại càng lúc càng to."}],"related":[{"hanzi":"反而","pinyin":"fǎn'ér","vi":"trái lại"},{"hanzi":"相反","pinyin":"xiāngfǎn","vi":"ngược lại"},{"hanzi":"却","pinyin":"què","vi":"nhưng lại"},{"hanzi":"倒是","pinyin":"dàoshì","vi":"lại là"}]},{"id":"反抗","hanzi":"反抗","pinyin":"fǎnkàng","meaning_vi":"phản kháng","explanation":"反 (phản – chống lại) + 抗 (kháng – kháng cự) → chống lại, kháng cự sự áp bức, đàn áp. Ví dụ: 反抗压迫, 奋起反抗.","hsk_level":6,"tags":["dong-tu"],"image":"✊","examples":[{"type":"basic","zh":"奴隶们起来反抗了。","pinyin":"Núlìmen qǐlái fǎnkàng le.","vi":"Những người nô lệ đã vùng lên phản kháng."},{"type":"simple","zh":"小偷被抓住后没有任何反抗。","pinyin":"Xiǎotōu bèi zhuāzhù hòu méiyǒu rènhé fǎnkàng.","vi":"Tên trộm sau khi bị bắt không hề phản kháng."},{"type":"compound","zh":"只要压迫存在一天，人民的反抗就不会停止。","pinyin":"Zhǐyào yāpò cúnzài yì tiān, rénmín de fǎnkàng jiù bú huì tíngzhǐ.","vi":"Chừng nào áp bức còn tồn tại thì sự phản kháng của nhân dân sẽ không dừng lại."}],"related":[{"hanzi":"抵抗","pinyin":"dǐkàng","vi":"chống cự"},{"hanzi":"反对","pinyin":"fǎnduì","vi":"phản đối"},{"hanzi":"服从","pinyin":"fúcóng","vi":"phục tùng"},{"hanzi":"起义","pinyin":"qǐyì","vi":"khởi nghĩa"}]},{"id":"反射","hanzi":"反射","pinyin":"fǎnshè","meaning_vi":"phản xạ","explanation":"反 (phản – quay lại) + 射 (xạ – chiếu, bắn) → phản xạ (ánh sáng, âm thanh dội lại; phản xạ thần kinh). Ví dụ: 镜子反射阳光, 条件反射.","hsk_level":6,"tags":["dong-tu"],"image":"🪞","examples":[{"type":"basic","zh":"镜子会反射光线。","pinyin":"Jìngzi huì fǎnshè guāngxiàn.","vi":"Gương sẽ phản xạ ánh sáng."},{"type":"simple","zh":"雪地反射的阳光刺得我睁不开眼。","pinyin":"Xuědì fǎnshè de yángguāng cì de wǒ zhēng bu kāiyǎn.","vi":"Ánh nắng phản chiếu từ mặt tuyết chói đến mức tôi không mở mắt được."},{"type":"compound","zh":"医生一敲他的膝盖，他的腿就条件反射地弹了起来。","pinyin":"Yīshēng yì qiāo tā de xīgài, tā de tuǐ jiù tiáojiàn fǎnshè de tánle qǐlái.","vi":"Bác sĩ vừa gõ vào đầu gối, chân anh ấy liền bật lên theo phản xạ."}],"related":[{"hanzi":"反光","pinyin":"fǎnguāng","vi":"phản quang"},{"hanzi":"条件反射","pinyin":"tiáojiànfǎnshè","vi":"phản xạ có điều kiện"},{"hanzi":"反应","pinyin":"fǎnyìng","vi":"phản ứng"},{"hanzi":"折射","pinyin":"zhéshè","vi":"khúc xạ"}]},{"id":"反响","hanzi":"反响","pinyin":"fǎnxiǎng","meaning_vi":"tiếng vang, phản hồi từ dư luận","explanation":"反 + 响 (vang dội).","hsk_level":6,"tags":["danh-tu"],"image":"📢","examples":[{"type":"basic","zh":"新书反响很好。","pinyin":"Xīn shū fǎnxiǎng hěn hǎo.","vi":"Cuốn sách mới nhận được phản hồi rất tốt."},{"type":"simple","zh":"这部纪录片在观众中引起了强烈反响。","pinyin":"Zhè bù jìlùpiàn zài guānzhòng zhōng yǐnqǐle qiángliè fǎnxiǎng.","vi":"Bộ phim tài liệu này đã gây tiếng vang mạnh mẽ trong khán giả."},{"type":"compound","zh":"虽然宣传花了很多钱，但是新产品在市场上没有什么反响。","pinyin":"Suīrán xuānchuán huāle hěn duō qián, dànshì xīnchǎnpǐn zài shìchǎng shang méiyǒu shénme fǎnxiǎng.","vi":"Tuy tốn nhiều tiền quảng cáo nhưng sản phẩm mới chẳng tạo được tiếng vang gì trên thị trường."}],"related":[{"hanzi":"反应","pinyin":"fǎnyìng","vi":"phản ứng"},{"hanzi":"反馈","pinyin":"fǎnkuì","vi":"phản hồi"},{"hanzi":"回响","pinyin":"huíxiǎng","vi":"tiếng vọng"},{"hanzi":"强烈反响","pinyin":"qiánglièfǎnxiǎng","vi":"tiếng vang mạnh mẽ"}],"traditional":"反響"},{"id":"反义词","hanzi":"反义词","pinyin":"fǎnyìcí","meaning_vi":"từ trái nghĩa","explanation":"反义 (nghĩa ngược) + 词 (từ). Đối ứng với 近义词.","hsk_level":6,"tags":["danh-tu","ngon-ngu","hoc-tap"],"image":"↔️","examples":[{"type":"basic","zh":"请写出三个反义词。","pinyin":"Qǐng xiě chū sān gè fǎnyìcí.","vi":"Hãy viết ra ba từ trái nghĩa."},{"type":"simple","zh":"老师让我们给每个形容词找一个反义词。","pinyin":"Lǎoshī ràng wǒmen gěi měi gè xíngróngcí zhǎo yí gè fǎnyìcí.","vi":"Cô giáo bảo chúng tôi tìm một từ trái nghĩa cho mỗi tính từ."},{"type":"compound","zh":"如果记不住生词，就可以试着把它和反义词一起记。","pinyin":"Rúguǒ jìbuzhù shēngcí, jiù kěyǐ shìzhe bǎ tā hé fǎnyìcí yìqǐ jì.","vi":"Nếu không nhớ được từ mới thì có thể thử học nó cùng với từ trái nghĩa."}],"related":[{"hanzi":"近义词","pinyin":"jìnyìcí","vi":"từ gần nghĩa"},{"hanzi":"同义词","pinyin":"tóngyìcí","vi":"từ đồng nghĩa"},{"hanzi":"词语","pinyin":"cíyǔ","vi":"từ ngữ"},{"hanzi":"反义","pinyin":"fǎnyì","vi":"nghĩa trái"}],"traditional":"反義詞"},{"id":"否决","hanzi":"否决","pinyin":"fǒujué","meaning_vi":"phủ quyết, bác bỏ","explanation":"否 (không) + 决 (quyết định).","hsk_level":6,"tags":["dong-tu","xa-hoi"],"image":"❌","examples":[{"type":"basic","zh":"提案被否决了。","pinyin":"Tí'àn bèi fǒujué le.","vi":"Đề án đã bị bác bỏ."},{"type":"simple","zh":"董事会否决了总经理的扩张计划。","pinyin":"Dǒngshìhuì fǒujuéle zǒngjīnglǐ de kuòzhāng jìhuà.","vi":"Hội đồng quản trị đã bác bỏ kế hoạch mở rộng của tổng giám đốc."},{"type":"compound","zh":"只要有一个常任理事国反对，这项决议就会被否决。","pinyin":"Zhǐyào yǒu yí gè chángrèn lǐshì guó fǎnduì, zhè xiàng juéyì jiù huì bèi fǒujué.","vi":"Chỉ cần có một nước ủy viên thường trực phản đối, nghị quyết này sẽ bị phủ quyết."}],"related":[{"hanzi":"否定","pinyin":"fǒudìng","vi":"phủ định"},{"hanzi":"否决权","pinyin":"fǒujuéquán","vi":"quyền phủ quyết"},{"hanzi":"通过","pinyin":"tōngguò","vi":"thông qua"},{"hanzi":"驳回","pinyin":"bóhuí","vi":"bác bỏ"}],"traditional":"否決"},{"id":"腐败","hanzi":"腐败","pinyin":"fǔbài","meaning_vi":"thối rữa; hủ bại, tham nhũng","explanation":"腐 (hủ – mục, thối) + 败 (bại – hỏng) → thối rữa; nghĩa bóng: tham nhũng, hủ bại. Thường gặp: 反腐败 (chống tham nhũng), 政治腐败.","hsk_level":6,"tags":["tinh-tu"],"image":"⚠️","examples":[{"type":"basic","zh":"这块肉已经腐败了。","pinyin":"Zhè kuài ròu yǐjīng fǔbài le.","vi":"Miếng thịt này đã bị thối rữa."},{"type":"simple","zh":"政府下决心严厉打击腐败行为。","pinyin":"Zhèngfǔ xiàjuéxīn yánlì dǎjī fǔbài xíngwéi.","vi":"Chính phủ quyết tâm trấn áp mạnh tay các hành vi tham nhũng."},{"type":"compound","zh":"如果权力得不到监督，就很容易产生腐败。","pinyin":"Rúguǒ quánlì débudào jiāndū, jiù hěn róngyì chǎnshēng fǔbài.","vi":"Nếu quyền lực không được giám sát thì rất dễ sinh ra tham nhũng."}],"related":[{"hanzi":"腐化","pinyin":"fǔhuà","vi":"hủ hóa"},{"hanzi":"贪污","pinyin":"tānwū","vi":"tham ô"},{"hanzi":"反腐","pinyin":"fǎnfǔ","vi":"chống tham nhũng"},{"hanzi":"廉洁","pinyin":"liánjié","vi":"liêm khiết"}],"traditional":"腐敗"},{"id":"抚摸","hanzi":"抚摸","pinyin":"fǔmō","meaning_vi":"vuốt ve","explanation":"抚 (phủ – vỗ về) + 摸 (mô – sờ) → vuốt ve, xoa nhẹ bằng tay thể hiện yêu thương. Ví dụ: 抚摸孩子的头, 抚摸小猫.","hsk_level":6,"tags":["dong-tu"],"image":"🤗","examples":[{"type":"basic","zh":"她轻轻抚摸着小狗。","pinyin":"Tā qīngqīng fǔmōzhe xiǎogǒu.","vi":"Cô ấy nhẹ nhàng vuốt ve chú chó nhỏ."},{"type":"simple","zh":"奶奶用粗糙的手抚摸着我的脸。","pinyin":"Nǎinai yòng cūcāo de shǒu fǔmōzhe wǒ de liǎn.","vi":"Bà nội dùng bàn tay thô ráp vuốt ve mặt tôi."},{"type":"compound","zh":"妈妈一抚摸他的头，哭闹的婴儿就安静下来了。","pinyin":"Māma yì fǔmō tā de tóu, kūnào de yīng'ér jiù ānjìng xiàlái le.","vi":"Mẹ vừa xoa đầu, đứa bé đang quấy khóc liền yên lặng."}],"related":[{"hanzi":"抚摩","pinyin":"fǔmó","vi":"vuốt ve"},{"hanzi":"摸","pinyin":"mō","vi":"sờ"},{"hanzi":"爱抚","pinyin":"àifǔ","vi":"âu yếm"},{"hanzi":"轻抚","pinyin":"qīngfǔ","vi":"vuốt nhẹ"}],"traditional":"撫摸"},{"id":"俯首帖耳","hanzi":"俯首帖耳","pinyin":"fǔshǒu-tiē'ěr","meaning_vi":"cúi đầu nghe lời răm rắp","explanation":"俯首 (cúi đầu) + 帖耳 (cụp tai) → như chó cúi đầu cụp tai trước chủ → ví ngoan ngoãn phục tùng, khúm núm vâng lời; mang nghĩa xấu.","hsk_level":6,"tags":["thanh-ngu"],"image":"🐕","examples":[{"type":"basic","zh":"他对老板俯首帖耳。","pinyin":"Tā duì lǎobǎn fǔshǒutiē'ěr.","vi":"Anh ta răm rắp nghe lời sếp."},{"type":"simple","zh":"那些大臣在皇帝面前个个俯首帖耳。","pinyin":"Nàxiē dàchén zài huángdì miànqián gègè fǔshǒutiē'ěr.","vi":"Các đại thần trước mặt hoàng đế ai nấy đều cúi đầu nghe lời."},{"type":"compound","zh":"虽然他在家里说一不二，但是在岳母面前却俯首帖耳。","pinyin":"Suīrán tā zài jiāli shuōyìbú'èr, dànshì zài yuèmǔ miànqián què fǔshǒutiē'ěr.","vi":"Tuy ở nhà anh ta nói một là một nhưng trước mặt mẹ vợ lại răm rắp nghe lời."}],"related":[{"hanzi":"唯命是从","pinyin":"wéimìngshìcóng","vi":"chỉ biết nghe lệnh"},{"hanzi":"言听计从","pinyin":"yántīngjìcóng","vi":"nghe theo răm rắp"},{"hanzi":"顺从","pinyin":"shùncóng","vi":"thuận theo"},{"hanzi":"桀骜不驯","pinyin":"jié'àobúxùn","vi":"ngang ngạnh bất kham"}]},{"id":"腐朽","hanzi":"腐朽","pinyin":"fǔxiǔ","meaning_vi":"mục nát, lỗi thời","explanation":"腐 (hủ – mục) + 朽 (hủ – mục nát) → gỗ mục nát; nghĩa bóng: tư tưởng, chế độ suy đồi, lạc hậu. Ví dụ: 腐朽的木头, 腐朽思想.","hsk_level":6,"tags":["tinh-tu"],"image":"🪵","examples":[{"type":"basic","zh":"木头已经腐朽了。","pinyin":"Mùtou yǐjīng fǔxiǔ le.","vi":"Khúc gỗ đã mục nát rồi."},{"type":"simple","zh":"这座古庙的房梁早已腐朽不堪。","pinyin":"Zhè zuò gǔ miào de fángliáng zǎoyǐ fǔxiǔ bùkān.","vi":"Xà nhà của ngôi miếu cổ này đã mục nát từ lâu."},{"type":"compound","zh":"因为清政府十分腐朽，所以最终被革命推翻了。","pinyin":"Yīnwèi Qīngzhèngfǔ shífēn fǔxiǔ, suǒyǐ zuìzhōng bèi gémìng tuīfān le.","vi":"Vì chính quyền nhà Thanh vô cùng mục nát nên cuối cùng đã bị cách mạng lật đổ."}],"related":[{"hanzi":"腐烂","pinyin":"fǔlàn","vi":"thối rữa"},{"hanzi":"陈腐","pinyin":"chénfǔ","vi":"cũ kỹ hủ lậu"},{"hanzi":"落后","pinyin":"luòhòu","vi":"lạc hậu"},{"hanzi":"新兴","pinyin":"xīnxīng","vi":"mới nổi"}]},{"id":"挂钩","hanzi":"挂钩","pinyin":"guàgōu","meaning_vi":"móc nối, gắn liền với (lợi ích/thu nhập)","explanation":"挂 (treo) + 钩 (cái móc). Động từ ly hợp.","hsk_level":6,"tags":["dong-tu"],"image":"🪝","examples":[{"type":"basic","zh":"两家企业挂钩合作。","pinyin":"Liǎng jiā qǐyè guàgōu hézuò.","vi":"Hai doanh nghiệp bắt tay hợp tác."},{"type":"simple","zh":"我们公司把年终奖和客户满意度挂钩。","pinyin":"Wǒmen gōngsī bǎ niánzhōngjiǎng hé kèhù mǎnyìdù guàgōu.","vi":"Công ty chúng tôi gắn tiền thưởng cuối năm với mức độ hài lòng của khách hàng."},{"type":"compound","zh":"如果工资不和效率挂钩，员工就没有动力多干活。","pinyin":"Rúguǒ gōngzī bùhé xiàolǜ guàgōu, yuángōng jiù méiyǒu dònglì duō gànhuó.","vi":"Nếu lương không gắn với hiệu suất thì nhân viên sẽ không có động lực làm nhiều hơn."}],"related":[{"hanzi":"脱钩","pinyin":"tuōgōu","vi":"tách rời, tách khỏi"},{"hanzi":"联系","pinyin":"liánxì","vi":"liên hệ"},{"hanzi":"挂靠","pinyin":"guàkào","vi":"trực thuộc, nương tựa"},{"hanzi":"关联","pinyin":"guānlián","vi":"liên quan"}],"traditional":"掛鉤"},{"id":"罐","hanzi":"罐","pinyin":"guàn","meaning_vi":"cái bình, cái lọ, lon","explanation":"罐 (quán): bình, hũ, lọ; lon, hộp. Từ ghép: 罐子 (cái hũ), 罐头 (đồ hộp), 易拉罐 (lon bật nắp); làm lượng từ: 一罐可乐.","hsk_level":6,"tags":["danh-tu","do-vat"],"image":"🥫","examples":[{"type":"basic","zh":"我买了一罐可乐。","pinyin":"Wǒ mǎile yí guàn kělè.","vi":"Tôi đã mua một lon Coca."},{"type":"simple","zh":"奶奶把腌好的咸菜装进了陶罐里。","pinyin":"Nǎinai bǎ yān hǎo de xiáncài zhuāng jìnle táo guàn li.","vi":"Bà cho dưa muối đã ngâm xong vào trong hũ gốm."},{"type":"compound","zh":"一打开这罐蜂蜜，整个厨房就飘满了甜香。","pinyin":"Yì dǎkāi zhè guàn fēngmì, zhěnggè chúfáng jiù piāo mǎnle tián xiāng.","vi":"Vừa mở hũ mật ong này, cả căn bếp đã ngào ngạt mùi thơm ngọt."}],"related":[{"hanzi":"罐头","pinyin":"guàntou","vi":"đồ hộp"},{"hanzi":"易拉罐","pinyin":"yìlāguàn","vi":"lon nước ngọt"},{"hanzi":"瓶子","pinyin":"píngzi","vi":"cái chai"},{"hanzi":"罐子","pinyin":"guànzi","vi":"cái hũ, cái lọ"}]},{"id":"贯彻","hanzi":"贯彻","pinyin":"guànchè","meaning_vi":"quán triệt","explanation":"贯 (quán – xuyên suốt) + 彻 (triệt – thấu đến cùng) → thực hiện triệt để, quán triệt (chính sách, tinh thần). Thường gặp: 贯彻方针, 贯彻落实.","hsk_level":6,"tags":["dong-tu"],"image":"📢","examples":[{"type":"basic","zh":"要贯彻这项政策。","pinyin":"Yào guànchè zhè xiàng zhèngcè.","vi":"Phải quán triệt chính sách này."},{"type":"simple","zh":"各部门正在认真贯彻会议精神。","pinyin":"Gè bùmén zhèngzài rènzhēn guànchè huìyì jīngshén.","vi":"Các phòng ban đang nghiêm túc quán triệt tinh thần hội nghị."},{"type":"compound","zh":"如果规定只写在纸上而不贯彻到底，就等于没有规定。","pinyin":"Rúguǒ guīdìng zhǐ xiě zài zhǐ shang ér bú guànchè dàodǐ, jiù děngyú méiyǒu guīdìng.","vi":"Nếu quy định chỉ viết trên giấy mà không thực hiện triệt để thì cũng như không có quy định."}],"related":[{"hanzi":"落实","pinyin":"luòshí","vi":"thực hiện, triển khai"},{"hanzi":"执行","pinyin":"zhíxíng","vi":"chấp hành"},{"hanzi":"实施","pinyin":"shíshī","vi":"thực thi"},{"hanzi":"贯彻落实","pinyin":"guànchèluòshí","vi":"quán triệt thực hiện"}],"traditional":"貫徹"},{"id":"刽子手","hanzi":"刽子手","pinyin":"guìzishǒu","meaning_vi":"đao phủ, kẻ giết người tàn bạo","explanation":"刽 (quái – chém) + 子手 (người làm) → đao phủ, người chuyên chém đầu tử tù thời xưa; nghĩa bóng: kẻ giết người tàn bạo.","hsk_level":6,"tags":["danh-tu","con-nguoi","van-hoa"],"image":"⚔️","examples":[{"type":"basic","zh":"刽子手举起了大刀。","pinyin":"Guìzishǒu jǔqǐle dàdāo.","vi":"Đao phủ giơ thanh đao lên."},{"type":"simple","zh":"历史会记住这些屠杀百姓的刽子手。","pinyin":"Lìshǐ huì jìzhù zhèxiē túshā bǎixìng de guìzishǒu.","vi":"Lịch sử sẽ ghi nhớ những kẻ đồ tể tàn sát dân lành này."},{"type":"compound","zh":"古代的刽子手虽然被人害怕，但是收入其实并不高。","pinyin":"Gǔdài de guìzishǒu suīrán bèi rén hàipà, dànshì shōurù qíshí bìngbù gāo.","vi":"Đao phủ thời xưa tuy bị người ta sợ hãi nhưng thu nhập thực ra không cao."}],"related":[{"hanzi":"杀手","pinyin":"shāshǒu","vi":"sát thủ"},{"hanzi":"凶手","pinyin":"xiōngshǒu","vi":"hung thủ"},{"hanzi":"屠夫","pinyin":"túfū","vi":"đồ tể"},{"hanzi":"死刑","pinyin":"sǐxíng","vi":"án tử hình"}],"traditional":"劊子手"},{"id":"贵族","hanzi":"贵族","pinyin":"guìzú","meaning_vi":"quý tộc","explanation":"贵 (quý – cao quý) + 族 (tộc – dòng họ) → tầng lớp quý tộc có đặc quyền; nay còn chỉ thứ sang trọng, đắt tiền: 贵族学校.","hsk_level":6,"tags":["danh-tu","con-nguoi"],"image":"👑","examples":[{"type":"basic","zh":"他出身贵族家庭。","pinyin":"Tā chūshēn guìzú jiātíng.","vi":"Anh ấy xuất thân từ gia đình quý tộc."},{"type":"simple","zh":"这座城堡曾经是英国贵族的住所。","pinyin":"Zhè zuò chéngbǎo céngjīng shì Yīngguó guìzú de zhùsuǒ.","vi":"Lâu đài này từng là nơi ở của quý tộc Anh."},{"type":"compound","zh":"虽然他是贵族后代，但是他一点儿架子也没有。","pinyin":"Suīrán tā shì guìzú hòudài, dànshì tā yìdiǎnr jiàzi yě méiyǒu.","vi":"Tuy là hậu duệ quý tộc nhưng anh ấy chẳng hề kiêu căng chút nào."}],"related":[{"hanzi":"平民","pinyin":"píngmín","vi":"thường dân"},{"hanzi":"皇室","pinyin":"huángshì","vi":"hoàng thất"},{"hanzi":"贵族学校","pinyin":"guìzúxuéxiào","vi":"trường quý tộc"},{"hanzi":"富豪","pinyin":"fùháo","vi":"phú hào, đại gia"}],"traditional":"貴族"},{"id":"过河拆桥","hanzi":"过河拆桥","pinyin":"guòhé-chāiqiáo","meaning_vi":"qua cầu rút ván (vô ơn bội nghĩa)","explanation":"过河 (qua sông) + 拆桥 (phá cầu) → qua sông rồi phá cầu → ví người vô ơn, xong việc thì gạt bỏ người đã giúp mình.","hsk_level":6,"tags":["thanh-ngu"],"image":"🌉","examples":[{"type":"basic","zh":"做人不能过河拆桥。","pinyin":"Zuòrén bù néng guòhéchāiqiáo.","vi":"Làm người không được qua cầu rút ván."},{"type":"simple","zh":"大家都看不起这种过河拆桥的人。","pinyin":"Dàjiā dōu kànbuqǐ zhè zhǒng guòhéchāiqiáo de rén.","vi":"Mọi người đều khinh thường loại người qua cầu rút ván này."},{"type":"compound","zh":"项目刚一成功，他就过河拆桥，把合伙人踢出了公司。","pinyin":"Xiàngmù gāngyì chénggōng, tā jiù guòhéchāiqiáo, bǎ héhuǒrén tī chūle gōngsī.","vi":"Dự án vừa thành công, anh ta liền qua cầu rút ván, đá đối tác ra khỏi công ty."}],"related":[{"hanzi":"忘恩负义","pinyin":"wàng'ēnfùyì","vi":"vong ân bội nghĩa"},{"hanzi":"恩将仇报","pinyin":"ēnjiāngchóubào","vi":"lấy oán báo ân"},{"hanzi":"知恩图报","pinyin":"zhī'ēntúbào","vi":"biết ơn báo đáp"},{"hanzi":"卸磨杀驴","pinyin":"xièmòshālǘ","vi":"vắt chanh bỏ vỏ"}],"traditional":"過河拆橋"},{"id":"过奖","hanzi":"过奖","pinyin":"guòjiǎng","meaning_vi":"quá khen","explanation":"过 (quá) + 奖 (tưởng – khen) → khen quá lời; câu đáp khiêm tốn khi được khen: 您过奖了 (anh/chị quá khen rồi).","hsk_level":6,"tags":["dong-tu"],"image":"🙇","examples":[{"type":"basic","zh":"您太过奖了，我还差得远。","pinyin":"Nín tài guòjiǎng le, wǒ hái chà de yuǎn.","vi":"Ngài quá khen rồi, tôi còn kém xa lắm."},{"type":"simple","zh":"她谦虚地连声说过奖过奖。","pinyin":"Tā qiānxū de lián shēngshuō guòjiǎng guòjiǎng.","vi":"Cô ấy khiêm tốn liên tục nói: quá khen, quá khen."},{"type":"compound","zh":"虽然大家都夸我的菜做得好，但是我知道大家是过奖了。","pinyin":"Suīrán dàjiā dōu kuā wǒ de cài zuò de hǎo, dànshì wǒ zhīdào dàjiā shì guòjiǎng le.","vi":"Tuy mọi người đều khen tôi nấu ăn ngon nhưng tôi biết mọi người quá khen rồi."}],"related":[{"hanzi":"夸奖","pinyin":"kuājiǎng","vi":"khen ngợi"},{"hanzi":"谦虚","pinyin":"qiānxū","vi":"khiêm tốn"},{"hanzi":"不敢当","pinyin":"bùgǎndāng","vi":"không dám nhận"},{"hanzi":"哪里哪里","pinyin":"nǎlinǎli","vi":"đâu có đâu"}],"traditional":"過獎"},{"id":"过虑","hanzi":"过虑","pinyin":"guòlǜ","meaning_vi":"lo xa quá mức, lo lắng thừa","explanation":"过 (quá) + 虑 (lo nghĩ).","hsk_level":6,"tags":["dong-tu","cam-xuc"],"image":"😟","examples":[{"type":"basic","zh":"你太过虑了。","pinyin":"Nǐ tài guòlǜ le.","vi":"Bạn lo xa quá rồi."},{"type":"simple","zh":"事实证明，他的担心完全是过虑。","pinyin":"Shìshí zhèngmíng, tā de dānxīn wánquán shì guòlǜ.","vi":"Thực tế chứng minh nỗi lo của anh ấy hoàn toàn là lo hão."},{"type":"compound","zh":"因为孩子已经长大了，所以你们实在不必过虑。","pinyin":"Yīnwèi háizi yǐjīng zhǎngdà le, suǒyǐ nǐmen shízài búbì guòlǜ.","vi":"Vì con đã lớn rồi nên các anh chị thật sự không cần lo lắng quá mức."}],"related":[{"hanzi":"多虑","pinyin":"duōlǜ","vi":"lo nghĩ quá nhiều"},{"hanzi":"担心","pinyin":"dānxīn","vi":"lo lắng"},{"hanzi":"顾虑","pinyin":"gùlǜ","vi":"băn khoăn, e ngại"},{"hanzi":"杞人忧天","pinyin":"Qǐrényōutiān","vi":"lo bò trắng răng"}],"traditional":"過慮"},{"id":"过目","hanzi":"过目","pinyin":"guòmù","meaning_vi":"xem qua, duyệt qua","explanation":"过 (quá – lướt qua) + 目 (mục – mắt) → đưa qua mắt, xem qua để duyệt/kiểm tra. Lời lịch sự: 请您过目.","hsk_level":6,"tags":["dong-tu","cong-viec"],"image":"👀","examples":[{"type":"basic","zh":"这份合同请您过目。","pinyin":"Zhè fèn hétong qǐng nín guòmù.","vi":"Bản hợp đồng này xin ngài xem qua."},{"type":"simple","zh":"所有的文件都要经过经理过目才能发出。","pinyin":"Suǒyǒu de wénjiàn dōu yào jīngguò jīnglǐ guòmù cáinéng fāchū.","vi":"Tất cả văn bản đều phải qua giám đốc xem duyệt mới được gửi đi."},{"type":"compound","zh":"因为这篇稿子很重要，所以发表前要请主编亲自过目。","pinyin":"Yīnwèi zhè piān gǎozi hěn zhòngyào, suǒyǐ fābiǎo qián yào qǐng zhǔbiān qīnzì guòmù.","vi":"Vì bài viết này rất quan trọng nên trước khi đăng phải mời tổng biên tập đích thân xem qua."}],"related":[{"hanzi":"浏览","pinyin":"liúlǎn","vi":"xem lướt"},{"hanzi":"审阅","pinyin":"shěnyuè","vi":"xem xét duyệt"},{"hanzi":"过目不忘","pinyin":"guòmùbúwàng","vi":"xem qua là nhớ"},{"hanzi":"查看","pinyin":"chákàn","vi":"kiểm tra xem"}],"traditional":"過目"},{"id":"过目不忘","hanzi":"过目不忘","pinyin":"guòmù-búwàng","meaning_vi":"nhìn qua một lần là nhớ mãi (trí nhớ siêu phàm)","explanation":"过目 (lướt qua mắt) + 不忘 (không quên) → chỉ đọc qua một lần là nhớ → tả trí nhớ cực tốt.","hsk_level":6,"tags":["thanh-ngu"],"image":"🧠","examples":[{"type":"basic","zh":"他有过目不忘的本领。","pinyin":"Tā yǒu guòmùbúwàng de běnlǐng.","vi":"Anh ấy có khả năng nhìn qua là nhớ."},{"type":"simple","zh":"这个孩子背诗几乎能过目不忘。","pinyin":"Zhè ge háizi bèi shī jīhū néng guòmùbúwàng.","vi":"Đứa trẻ này học thơ gần như nhìn qua một lần là thuộc."},{"type":"compound","zh":"即使你能过目不忘，考试前也应该好好复习。","pinyin":"Jíshǐ nǐ néng guòmùbúwàng, kǎoshì qián yě yīnggāi hǎohǎo fùxí.","vi":"Cho dù bạn có trí nhớ nhìn qua là nhớ, trước kỳ thi cũng nên ôn tập kỹ."}],"related":[{"hanzi":"记忆力","pinyin":"jìyìlì","vi":"trí nhớ"},{"hanzi":"博闻强记","pinyin":"bówénqiángjì","vi":"học rộng nhớ dai"},{"hanzi":"过目","pinyin":"guòmù","vi":"xem qua"},{"hanzi":"健忘","pinyin":"jiànwàng","vi":"hay quên"}],"traditional":"過目不忘"},{"id":"过问","hanzi":"过问","pinyin":"guòwèn","meaning_vi":"hỏi han, can dự tới","explanation":"过 (quá – đi qua) + 问 (vấn – hỏi) → hỏi đến, can thiệp, quan tâm xử lý. Thường dùng phủ định: 不闻不问, 无人过问 (không ai đoái hoài).","hsk_level":6,"tags":["dong-tu"],"image":"❓","examples":[{"type":"basic","zh":"这事你别过问。","pinyin":"Zhè shì nǐ bié guòwèn.","vi":"Chuyện này bạn đừng can dự vào."},{"type":"simple","zh":"父亲从不过问我的私生活。","pinyin":"Fùqīn cóng bú guòwèn wǒ de sīshēnghuó.","vi":"Bố tôi không bao giờ can thiệp vào đời tư của tôi."},{"type":"compound","zh":"自从市长亲自过问，这件拖了半年的案子很快就解决了。","pinyin":"Zìcóng shìzhǎng qīnzì guòwèn, zhè jiàn tuōle bàn nián de ànzi hěn kuài jiù jiějué le.","vi":"Từ khi thị trưởng đích thân hỏi đến, vụ việc kéo dài nửa năm này đã nhanh chóng được giải quyết."}],"related":[{"hanzi":"干预","pinyin":"gānyù","vi":"can thiệp"},{"hanzi":"插手","pinyin":"chāshǒu","vi":"nhúng tay"},{"hanzi":"不闻不问","pinyin":"bùwénbúwèn","vi":"làm ngơ không hỏi han"},{"hanzi":"关心","pinyin":"guānxīn","vi":"quan tâm"}],"traditional":"過問"},{"id":"过意不去","hanzi":"过意不去","pinyin":"guòyìbúqù","meaning_vi":"áy náy, cảm thấy có lỗi","explanation":"过意 (ý trong lòng) + 不去 (không qua được) → trong lòng không yên, áy náy vì làm phiền hay mang ơn người khác. Cụm: 真过意不去.","hsk_level":6,"tags":["tinh-tu","giao-tiep"],"image":"🙇","examples":[{"type":"basic","zh":"让你久等，真过意不去。","pinyin":"Ràng nǐ jiǔděng, zhēn guòyìbúqù.","vi":"Để bạn đợi lâu, tôi thật áy náy."},{"type":"simple","zh":"他对没能参加朋友的婚礼一直过意不去。","pinyin":"Tā duì méi néng cānjiā péngyou de hūnlǐ yìzhí guòyìbúqù.","vi":"Anh ấy luôn áy náy vì không thể dự đám cưới của bạn."},{"type":"compound","zh":"因为总是麻烦邻居帮忙，所以我觉得很过意不去。","pinyin":"Yīnwèi zǒngshì máfan línjū bāngmáng, suǒyǐ wǒ juéde hěn guòyìbúqù.","vi":"Vì cứ phải làm phiền hàng xóm giúp đỡ nên tôi cảm thấy rất áy náy."}],"related":[{"hanzi":"不好意思","pinyin":"bùhǎoyìsi","vi":"ngại, ngượng"},{"hanzi":"内疚","pinyin":"nèijiù","vi":"áy náy"},{"hanzi":"惭愧","pinyin":"cánkuì","vi":"hổ thẹn"},{"hanzi":"抱歉","pinyin":"bàoqiàn","vi":"xin lỗi, áy náy"}],"traditional":"過意不去"},{"id":"瓜分","hanzi":"瓜分","pinyin":"guāfēn","meaning_vi":"chia cắt, xâu xé","explanation":"瓜 (quả dưa) + 分 (chia).","hsk_level":6,"tags":["dong-tu"],"image":"🍉","examples":[{"type":"basic","zh":"列强瓜分了殖民地。","pinyin":"Lièqiáng guāfēnle zhímíndì.","vi":"Các cường quốc đã xâu xé các thuộc địa."},{"type":"simple","zh":"几家大公司瓜分了国内的手机市场。","pinyin":"Jǐ jiā dàgōngsī guāfēnle guónèi de shǒujī shìchǎng.","vi":"Mấy công ty lớn đã chia nhau thị trường điện thoại trong nước."},{"type":"compound","zh":"老人刚去世，几个儿子就开始争着瓜分他的财产。","pinyin":"Lǎorén gāng qùshì, jǐ gè érzi jiù kāishǐ zhēngzhe guāfēn tā de cáichǎn.","vi":"Ông cụ vừa mất, mấy người con trai đã bắt đầu tranh nhau chia chác tài sản."}],"related":[{"hanzi":"分割","pinyin":"fēngē","vi":"chia cắt"},{"hanzi":"瓜分豆剖","pinyin":"guāfēndòupōu","vi":"chia năm xẻ bảy"},{"hanzi":"侵占","pinyin":"qīnzhàn","vi":"xâm chiếm"},{"hanzi":"划分","pinyin":"huàfēn","vi":"phân chia"}]},{"id":"刮目相看","hanzi":"刮目相看","pinyin":"guāmù-xiāngkàn","meaning_vi":"nhìn bằng con mắt khác (ngạc nhiên vì sự tiến bộ vượt bậc)","explanation":"刮目 (lau mắt) + 相看 (nhìn) → lau mắt mà nhìn lại (chuyện Lã Mông chăm học, Lỗ Túc kinh ngạc) → nhìn người bằng con mắt khác vì họ tiến bộ vượt bậc.","hsk_level":6,"tags":["thanh-ngu"],"image":"👀","examples":[{"type":"basic","zh":"我对他刮目相看。","pinyin":"Wǒ duì tā guāmùxiāngkàn.","vi":"Tôi phải nhìn anh ấy bằng con mắt khác."},{"type":"simple","zh":"这次比赛她的表现令教练刮目相看。","pinyin":"Zhè cì bǐsài tā de biǎoxiàn lìng jiàoliàn guāmùxiāngkàn.","vi":"Màn thể hiện ở cuộc thi lần này khiến huấn luyện viên phải nhìn cô ấy bằng con mắt khác."},{"type":"compound","zh":"他不但戒了游戏，而且考进了年级前十，真让人刮目相看。","pinyin":"Tā búdàn jièle yóuxì, érqiě kǎojìnle niánjí qián shí, zhēn ràng rén guāmùxiāngkàn.","vi":"Cậu ấy không những bỏ được game mà còn lọt vào top mười của khối, thật khiến người ta phải nhìn bằng con mắt khác."}],"related":[{"hanzi":"另眼相看","pinyin":"lìngyǎnxiāngkàn","vi":"nhìn bằng con mắt khác"},{"hanzi":"士别三日","pinyin":"shìbiésānrì","vi":"ba ngày không gặp đã khác"},{"hanzi":"进步","pinyin":"jìnbù","vi":"tiến bộ"},{"hanzi":"惊讶","pinyin":"jīngyà","vi":"ngạc nhiên"}]},{"id":"乖巧","hanzi":"乖巧","pinyin":"guāiqiǎo","meaning_vi":"ngoan ngoãn thông minh, lanh lợi","explanation":"乖 (ngoan) + 巧 (khéo).","hsk_level":6,"tags":["tinh-tu","con-nguoi"],"image":"😇","examples":[{"type":"basic","zh":"这孩子真乖巧。","pinyin":"Zhè háizi zhēn guāiqiǎo.","vi":"Đứa bé này thật ngoan ngoãn lanh lợi."},{"type":"simple","zh":"乖巧的小女儿每天帮妈妈摆碗筷。","pinyin":"Guāiqiǎo de xiǎo nǚ'ér měitiān bāng māma bǎi wǎnkuài.","vi":"Cô con gái nhỏ ngoan ngoãn ngày nào cũng giúp mẹ dọn bát đũa."},{"type":"compound","zh":"虽然她在长辈面前很乖巧，但是跟朋友在一起时特别调皮。","pinyin":"Suīrán tā zài zhǎngbèi miànqián hěn guāiqiǎo, dànshì gēn péngyou zài yìqǐ shí tèbié tiáopí.","vi":"Tuy trước mặt người lớn cô bé rất ngoan ngoãn nhưng khi ở cùng bạn bè thì cực kỳ nghịch ngợm."}],"related":[{"hanzi":"乖","pinyin":"guāi","vi":"ngoan"},{"hanzi":"机灵","pinyin":"jīling","vi":"lanh lợi"},{"hanzi":"听话","pinyin":"tīnghuà","vi":"vâng lời"},{"hanzi":"调皮","pinyin":"tiáopí","vi":"nghịch ngợm"}]},{"id":"官僚","hanzi":"官僚","pinyin":"guānliáo","meaning_vi":"quan liêu","explanation":"官 (quan chức) + 僚.","hsk_level":6,"tags":["danh-tu","xa-hoi"],"image":"🏛️","examples":[{"type":"basic","zh":"他是个老官僚。","pinyin":"Tā shì gè lǎo guānliáo.","vi":"Ông ta là một tay quan liêu lâu năm."},{"type":"simple","zh":"群众最讨厌那种高高在上的官僚作风。","pinyin":"Qúnzhòng zuì tǎoyàn nà zhǒng gāo gāo zài shàng de guānliáo zuòfēng.","vi":"Quần chúng ghét nhất kiểu tác phong quan liêu ngồi trên cao ấy."},{"type":"compound","zh":"如果办事人员太官僚，老百姓办个证就要跑好几趟。","pinyin":"Rúguǒ bànshì rényuán tài guānliáo, lǎobǎixìng bàn gè zhèng jiùyào pǎo hǎojǐ tàng.","vi":"Nếu nhân viên làm việc quá quan liêu thì người dân làm một tờ giấy cũng phải chạy đi chạy lại mấy lần."}],"related":[{"hanzi":"官僚主义","pinyin":"guānliáozhǔyì","vi":"chủ nghĩa quan liêu"},{"hanzi":"官员","pinyin":"guānyuán","vi":"quan chức"},{"hanzi":"腐败","pinyin":"fǔbài","vi":"tham nhũng"},{"hanzi":"官场","pinyin":"guānchǎng","vi":"quan trường"}]},{"id":"观望","hanzi":"观望","pinyin":"guānwàng","meaning_vi":"đứng ngoài quan sát, nghe ngóng tình hình","explanation":"观 (xem) + 望 (ngóng).","hsk_level":6,"tags":["dong-tu"],"image":"👀","examples":[{"type":"basic","zh":"很多买家还在观望。","pinyin":"Hěn duō mǎijiā hái zài guānwàng.","vi":"Nhiều người mua vẫn đang nghe ngóng."},{"type":"simple","zh":"他站在门口向四周观望了一会儿。","pinyin":"Tā zhàn zài ménkǒu xiàng sìzhōu guānwàngle yíhuìr.","vi":"Anh ấy đứng ở cửa nhìn quanh một lúc."},{"type":"compound","zh":"既然市场前景不明朗，我们就先观望一段时间吧。","pinyin":"Jìrán shìchǎng qiánjǐng bù mínglǎng, wǒmen jiù xiān guānwàng yí duàn shíjiān ba.","vi":"Vì triển vọng thị trường chưa rõ ràng, chúng ta cứ quan sát thêm một thời gian đã."}],"related":[{"hanzi":"观察","pinyin":"guānchá","vi":"quan sát"},{"hanzi":"犹豫","pinyin":"yóuyù","vi":"do dự"},{"hanzi":"观望态度","pinyin":"guānwàngtàidù","vi":"thái độ chờ xem"},{"hanzi":"等待","pinyin":"děngdài","vi":"chờ đợi"}],"traditional":"觀望"},{"id":"冠心病","hanzi":"冠心病","pinyin":"guānxīnbìng","meaning_vi":"bệnh mạch vành","explanation":"冠 + 心 + 病 (bệnh tim).","hsk_level":6,"tags":["danh-tu","suc-khoe"],"image":"🫀","examples":[{"type":"basic","zh":"爷爷患有冠心病。","pinyin":"Yéye huànyǒu guānxīnbìng.","vi":"Ông nội mắc bệnh mạch vành."},{"type":"simple","zh":"长期吸烟会大大增加患冠心病的风险。","pinyin":"Chángqī xīyān huì dàdà zēngjiā huàn guānxīnbìng de fēngxiǎn.","vi":"Hút thuốc lâu dài sẽ làm tăng đáng kể nguy cơ mắc bệnh mạch vành."},{"type":"compound","zh":"因为有冠心病，所以他随身带着急救药。","pinyin":"Yīnwèi yǒu guānxīnbìng, suǒyǐ tā suíshēn dàizhe jíjiù yào.","vi":"Vì bị bệnh mạch vành nên ông ấy luôn mang theo thuốc cấp cứu bên mình."}],"related":[{"hanzi":"心脏病","pinyin":"xīnzàngbìng","vi":"bệnh tim"},{"hanzi":"高血压","pinyin":"gāoxuèyā","vi":"cao huyết áp"},{"hanzi":"血管","pinyin":"xuèguǎn","vi":"mạch máu"},{"hanzi":"心肌梗塞","pinyin":"xīnjīgěngsè","vi":"nhồi máu cơ tim"}]},{"id":"关照","hanzi":"关照","pinyin":"guānzhào","meaning_vi":"quan tâm giúp đỡ","explanation":"关 (quan – liên quan, để tâm) + 照 (chiếu – chăm nom) → quan tâm chăm sóc, giúp đỡ; cũng là dặn dò. Câu xã giao: 请多关照 (mong được giúp đỡ).","hsk_level":6,"tags":["dong-tu"],"image":"🙇","examples":[{"type":"basic","zh":"请多多关照！","pinyin":"Qǐng duōduō guānzhào!","vi":"Mong được giúp đỡ nhiều!"},{"type":"simple","zh":"刚来公司的时候师傅对我特别关照。","pinyin":"Gāng lái gōngsī de shíhou shīfu duì wǒ tèbié guānzhào.","vi":"Hồi mới vào công ty, sư phụ đặc biệt quan tâm giúp đỡ tôi."},{"type":"compound","zh":"我出差这几天，如果孩子有事，就麻烦你关照一下。","pinyin":"Wǒ chūchāi zhèjǐtiān, rúguǒ háizi yǒushì, jiù máfan nǐ guānzhào yíxià.","vi":"Mấy ngày tôi đi công tác, nếu con có chuyện gì thì phiền bạn trông nom giúp."}],"related":[{"hanzi":"照顾","pinyin":"zhàogù","vi":"chăm sóc"},{"hanzi":"关心","pinyin":"guānxīn","vi":"quan tâm"},{"hanzi":"多多关照","pinyin":"duōduōguānzhào","vi":"mong được giúp đỡ nhiều"},{"hanzi":"照应","pinyin":"zhàoying","vi":"chiếu cố, lo liệu"}],"traditional":"關照"},{"id":"关爱","hanzi":"关爱","pinyin":"guān'ài","meaning_vi":"quan tâm yêu thương","explanation":"关 (quan tâm) + 爱 (yêu).","hsk_level":6,"tags":["dong-tu","xa-hoi"],"image":"💖","examples":[{"type":"basic","zh":"孩子需要父母的关爱。","pinyin":"Háizi xūyào fùmǔ de guān'ài.","vi":"Trẻ cần sự yêu thương quan tâm của cha mẹ."},{"type":"simple","zh":"社区志愿者每周都去关爱独居老人。","pinyin":"Shèqū zhìyuànzhě měizhōu dōu qù guān'ài dújū lǎorén.","vi":"Tình nguyện viên khu dân cư mỗi tuần đều đi chăm lo người già sống một mình."},{"type":"compound","zh":"只要社会多一份关爱，这些留守儿童就会少一份孤单。","pinyin":"Zhǐyào shèhuì duō yí fèn guān'ài, zhèxiē liúshǒu értóng jiù huì shǎo yí fèn gūdān.","vi":"Chỉ cần xã hội thêm một phần quan tâm, những đứa trẻ bị bỏ lại ở quê sẽ bớt đi một phần cô đơn."}],"related":[{"hanzi":"关心","pinyin":"guānxīn","vi":"quan tâm"},{"hanzi":"爱护","pinyin":"àihù","vi":"yêu thương che chở"},{"hanzi":"关怀","pinyin":"guānhuái","vi":"quan tâm chăm sóc"},{"hanzi":"冷漠","pinyin":"lěngmò","vi":"thờ ơ"}],"traditional":"關愛"},{"id":"光顾","hanzi":"光顾","pinyin":"guānggù","meaning_vi":"ghé thăm, ủng hộ cửa hàng (kính ngữ)","explanation":"光 + 顾 (ngoái nhìn). Cụm: 欢迎光顾.","hsk_level":6,"tags":["dong-tu","mua-sam"],"image":"🏪","examples":[{"type":"basic","zh":"欢迎再次光顾！","pinyin":"Huānyíng zàicì guānggù!","vi":"Hoan nghênh quý khách lần sau lại ghé!"},{"type":"simple","zh":"这家面馆我每周都要光顾两三次。","pinyin":"Zhè jiā miànguǎn wǒ měizhōu dōu yào guānggù liǎng sāncì.","vi":"Quán mì này mỗi tuần tôi đều ghé hai ba lần."},{"type":"compound","zh":"自从换了新厨师，光顾这家餐厅的客人就越来越多了。","pinyin":"Zìcóng huànle xīn chúshī, guānggù zhè jiā cāntīng de kèrén jiù yuèláiyuè duō le.","vi":"Từ khi đổi đầu bếp mới, khách ghé nhà hàng này ngày càng đông."}],"related":[{"hanzi":"惠顾","pinyin":"huìgù","vi":"chiếu cố (khách hàng)"},{"hanzi":"顾客","pinyin":"gùkè","vi":"khách hàng"},{"hanzi":"光临","pinyin":"guānglín","vi":"ghé thăm"},{"hanzi":"欢迎光临","pinyin":"huānyíngguānglín","vi":"hân hạnh đón tiếp"}],"traditional":"光顧"},{"id":"光芒","hanzi":"光芒","pinyin":"guāngmáng","meaning_vi":"tia sáng, ánh sáng rực rỡ","explanation":"光 (quang – ánh sáng) + 芒 (mang – tia, râu lúa nhọn) → tia sáng rực rỡ tỏa ra bốn phía. Ví dụ: 太阳的光芒, 光芒四射.","hsk_level":6,"tags":["danh-tu"],"image":"☀️","examples":[{"type":"basic","zh":"太阳放射出光芒。","pinyin":"Tàiyáng fàngshè chū guāngmáng.","vi":"Mặt trời tỏa ra ánh sáng rực rỡ."},{"type":"simple","zh":"钻石在灯光下闪着耀眼的光芒。","pinyin":"Zuànshí zài dēngguāng xià shǎnzhe yàoyǎn de guāngmáng.","vi":"Viên kim cương lấp lánh ánh sáng chói lọi dưới ánh đèn."},{"type":"compound","zh":"虽然他已经退役多年，但是他的光芒依然照耀着年轻球员。","pinyin":"Suīrán tā yǐjīng tuìyì duōnián, dànshì tā de guāngmáng yīrán zhàoyàozhe niánqīng qiúyuán.","vi":"Tuy anh ấy đã giải nghệ nhiều năm nhưng hào quang của anh vẫn soi sáng các cầu thủ trẻ."}],"related":[{"hanzi":"光辉","pinyin":"guānghuī","vi":"ánh hào quang"},{"hanzi":"阳光","pinyin":"yángguāng","vi":"ánh nắng"},{"hanzi":"光芒万丈","pinyin":"guāngmángwànzhàng","vi":"hào quang rực rỡ"},{"hanzi":"光线","pinyin":"guāngxiàn","vi":"tia sáng"}]},{"id":"光明磊落","hanzi":"光明磊落","pinyin":"guāngmíng-lěiluò","meaning_vi":"quang minh lỗi lạc, ngay thẳng","explanation":"光明 (quang minh – sáng sủa) + 磊落 (lỗi lạc – ngay thẳng, cởi mở) → tâm địa trong sáng, làm việc ngay thẳng, không mờ ám.","hsk_level":6,"tags":["thanh-ngu"],"image":"☀️","examples":[{"type":"basic","zh":"他为人光明磊落。","pinyin":"Tā wéirén guāngmínglěiluò.","vi":"Ông ấy sống quang minh lỗi lạc."},{"type":"simple","zh":"光明磊落的人从来不在背后说别人坏话。","pinyin":"Guāngmínglěiluò de rén cóngláibú zài bèihòu shuō biérén huàihuà.","vi":"Người ngay thẳng không bao giờ nói xấu người khác sau lưng."},{"type":"compound","zh":"既然你做事光明磊落，又何必害怕别人调查呢？","pinyin":"Jìrán nǐ zuòshì guāngmínglěiluò, yòu hébì hàipà biérén diàochá ne?","vi":"Nếu bạn làm việc quang minh chính đại thì cần gì phải sợ người khác điều tra?"}],"related":[{"hanzi":"正大光明","pinyin":"zhèngdàguāngmíng","vi":"quang minh chính đại"},{"hanzi":"坦荡","pinyin":"tǎndàng","vi":"thẳng thắn rộng lượng"},{"hanzi":"鬼鬼祟祟","pinyin":"guǐguǐsuìsuì","vi":"lén lút"},{"hanzi":"光明","pinyin":"guāngmíng","vi":"sáng sủa, quang minh"}]},{"id":"光荣","hanzi":"光荣","pinyin":"guāngróng","meaning_vi":"vinh quang, vẻ vang","explanation":"光 + 荣 (vinh dự).","hsk_level":6,"tags":["tinh-tu","danh-tu"],"image":"🏅","examples":[{"type":"basic","zh":"劳动最光荣。","pinyin":"Láodòng zuì guāngróng.","vi":"Lao động là vinh quang nhất."},{"type":"simple","zh":"他光荣地加入了国家篮球队。","pinyin":"Tā guāngróng de jiārùle guójiā lánqiúduì.","vi":"Anh ấy vinh dự gia nhập đội bóng rổ quốc gia."},{"type":"compound","zh":"因为能代表学校参加比赛，所以我感到非常光荣。","pinyin":"Yīnwèi néng dàibiǎo xuéxiào cānjiā bǐsài, suǒyǐ wǒ gǎndào fēicháng guāngróng.","vi":"Vì được đại diện trường tham gia thi đấu nên tôi cảm thấy vô cùng vinh dự."}],"related":[{"hanzi":"荣誉","pinyin":"róngyù","vi":"vinh dự"},{"hanzi":"耻辱","pinyin":"chǐrǔ","vi":"nhục nhã"},{"hanzi":"光彩","pinyin":"guāngcǎi","vi":"vẻ vang"},{"hanzi":"自豪","pinyin":"zìháo","vi":"tự hào"}],"traditional":"光榮"},{"id":"瑰宝","hanzi":"瑰宝","pinyin":"guībǎo","meaning_vi":"báu vật, viên ngọc quý","explanation":"瑰 (ngọc quý) + 宝 (báu vật).","hsk_level":6,"tags":["danh-tu","van-hoa"],"image":"💎","examples":[{"type":"basic","zh":"京剧是国家的瑰宝。","pinyin":"Jīngjù shì guójiā de guībǎo.","vi":"Kinh kịch là báu vật quốc gia."},{"type":"simple","zh":"博物馆里收藏着许多古代文化瑰宝。","pinyin":"Bówùguǎn li shōucángzhe xǔduō gǔdài wénhuà guībǎo.","vi":"Bảo tàng lưu giữ nhiều báu vật văn hóa cổ đại."},{"type":"compound","zh":"这些古籍不但是民族的瑰宝，而且对研究历史有很大价值。","pinyin":"Zhèxiē gǔjí bú dànshì mínzú de guībǎo, érqiě duì yánjiū lìshǐ yǒu hěn dà jiàzhí.","vi":"Những cổ thư này không những là báu vật của dân tộc mà còn có giá trị lớn đối với việc nghiên cứu lịch sử."}],"related":[{"hanzi":"宝贝","pinyin":"bǎobèi","vi":"bảo bối"},{"hanzi":"珍宝","pinyin":"zhēnbǎo","vi":"châu báu"},{"hanzi":"国宝","pinyin":"guóbǎo","vi":"quốc bảo"},{"hanzi":"艺术瑰宝","pinyin":"yìshùguībǎo","vi":"báu vật nghệ thuật"}],"traditional":"瑰寶"},{"id":"规范","hanzi":"规范","pinyin":"guīfàn","meaning_vi":"quy phạm, chuẩn mực","explanation":"规 (quy – cái compa, phép tắc) + 范 (phạm – khuôn mẫu) → chuẩn mực, quy phạm; dùng cả làm tính từ (chuẩn) và động từ (quy chuẩn hóa). Ví dụ: 行为规范, 规范管理.","hsk_level":6,"tags":["danh-tu"],"image":"📏","examples":[{"type":"basic","zh":"他的发音很规范。","pinyin":"Tā de fāyīn hěn guīfàn.","vi":"Phát âm của anh ấy rất chuẩn."},{"type":"simple","zh":"每个员工都要遵守公司的行为规范。","pinyin":"Měi gè yuángōng dōu yào zūnshǒu gōngsī de xíngwéi guīfàn.","vi":"Mỗi nhân viên đều phải tuân thủ quy phạm hành vi của công ty."},{"type":"compound","zh":"如果合同写得不规范，以后就容易产生纠纷。","pinyin":"Rúguǒ hétong xiě de bù guīfàn, yǐhòu jiù róngyì chǎnshēng jiūfēn.","vi":"Nếu hợp đồng viết không đúng quy chuẩn thì sau này dễ phát sinh tranh chấp."}],"related":[{"hanzi":"标准","pinyin":"biāozhǔn","vi":"tiêu chuẩn"},{"hanzi":"规则","pinyin":"guīzé","vi":"quy tắc"},{"hanzi":"不规范","pinyin":"bùguīfàn","vi":"không chuẩn"},{"hanzi":"规范化","pinyin":"guīfànhuà","vi":"chuẩn hóa"}],"traditional":"規範"},{"id":"归根结底","hanzi":"归根结底","pinyin":"guīgēn-jiédǐ","meaning_vi":"suy cho cùng, tóm lại","explanation":"归根结底: 归 (quy – trở về) 根 (căn – gốc), 结 (kết – kết thúc) 底 (để – đáy) → về đến gốc, tới tận đáy → suy cho cùng. Thường đứng đầu câu để rút ra kết luận.","hsk_level":6,"tags":["thanh-ngu"],"image":"💡","examples":[{"type":"basic","zh":"归根结底，还得靠自己。","pinyin":"Guīgēnjiédǐ, hái děi kào zìjǐ.","vi":"Suy cho cùng vẫn phải dựa vào bản thân."},{"type":"simple","zh":"公司的竞争归根结底是人才的竞争。","pinyin":"Gōngsī de jìngzhēng guīgēnjiédǐ shì réncái de jìngzhēng.","vi":"Sự cạnh tranh giữa các công ty suy cho cùng là cạnh tranh nhân tài."},{"type":"compound","zh":"虽然原因有很多，但是归根结底还是管理出了问题。","pinyin":"Suīrán yuányīn yǒu hěn duō, dànshì guīgēnjiédǐ háishi guǎnlǐ chūle wèntí.","vi":"Tuy có nhiều nguyên nhân nhưng suy cho cùng vẫn là do quản lý có vấn đề."}],"related":[{"hanzi":"总之","pinyin":"zǒngzhī","vi":"tóm lại"},{"hanzi":"说到底","pinyin":"shuōdàodǐ","vi":"nói cho cùng"},{"hanzi":"归根到底","pinyin":"guīgēndàodǐ","vi":"rốt cuộc"},{"hanzi":"总而言之","pinyin":"zǒng'éryánzhī","vi":"nói tóm lại"}],"traditional":"歸根結底"},{"id":"归属","hanzi":"归属","pinyin":"guīshǔ","meaning_vi":"thuộc về, cảm giác thuộc về (belonging)","explanation":"归 (quay về) + 属 (thuộc). Cụm: 归属感.","hsk_level":6,"tags":["dong-tu","cam-xuc"],"image":"🏡","examples":[{"type":"basic","zh":"这块土地归属国家。","pinyin":"Zhè kuài tǔdì guīshǔ guójiā.","vi":"Mảnh đất này thuộc về nhà nước."},{"type":"simple","zh":"这个温暖的团队让我找到了归属感。","pinyin":"Zhè ge wēnnuǎn de tuánduì ràng wǒ zhǎodàole guīshǔgǎn.","vi":"Tập thể ấm áp này giúp tôi tìm thấy cảm giác thuộc về."},{"type":"compound","zh":"因为双方对岛屿的归属存在争议，所以谈判一直没有结果。","pinyin":"Yīnwèi shuāngfāng duì dǎoyǔ de guīshǔ cúnzài zhēngyì, suǒyǐ tánpàn yìzhí méiyǒu jiéguǒ.","vi":"Vì hai bên tranh chấp về quyền sở hữu hòn đảo nên đàm phán mãi không có kết quả."}],"related":[{"hanzi":"归属感","pinyin":"guīshǔgǎn","vi":"cảm giác thuộc về"},{"hanzi":"所属","pinyin":"suǒshǔ","vi":"trực thuộc"},{"hanzi":"属于","pinyin":"shǔyú","vi":"thuộc về"},{"hanzi":"隶属","pinyin":"lìshǔ","vi":"lệ thuộc"}],"traditional":"歸屬"},{"id":"归心似箭","hanzi":"归心似箭","pinyin":"guīxīn-sìjiàn","meaning_vi":"lòng mong về nhà nhanh như tên bắn","explanation":"归心 (quy tâm – lòng muốn trở về) + 似箭 (tựa mũi tên) → lòng mong về nhà nhanh như tên bắn, nóng lòng muốn về quê.","hsk_level":6,"tags":["thanh-ngu"],"image":"🏹","examples":[{"type":"basic","zh":"春节前他归心似箭。","pinyin":"Chūnjié qián tā guīxīnsìjiàn.","vi":"Trước Tết, anh ấy nóng lòng muốn về nhà."},{"type":"simple","zh":"在外打工的人们个个归心似箭。","pinyin":"Zài wài dǎgōng de rénmen gègè guīxīnsìjiàn.","vi":"Những người làm thuê xa nhà ai nấy đều nóng lòng muốn về."},{"type":"compound","zh":"一听说母亲病了，在国外留学的她就归心似箭。","pinyin":"Yì tīngshuō mǔqīn bìng le, zài guówài liúxué de tā jiù guīxīnsìjiàn.","vi":"Vừa nghe tin mẹ ốm, cô ấy đang du học ở nước ngoài liền nóng lòng muốn về ngay."}],"related":[{"hanzi":"思乡","pinyin":"sīxiāng","vi":"nhớ quê"},{"hanzi":"回家","pinyin":"huíjiā","vi":"về nhà"},{"hanzi":"迫不及待","pinyin":"pòbùjídài","vi":"nóng lòng không đợi được"},{"hanzi":"归途","pinyin":"guītú","vi":"đường về"}],"traditional":"歸心似箭"},{"id":"规章","hanzi":"规章","pinyin":"guīzhāng","meaning_vi":"quy chế, điều lệ","explanation":"规 (quy – phép tắc) + 章 (chương – điều khoản) → các quy định, điều lệ thành văn của cơ quan, tổ chức. Thường gặp: 规章制度, 遵守规章.","hsk_level":6,"tags":["danh-tu"],"image":"📜","examples":[{"type":"basic","zh":"新的规章已经公布了。","pinyin":"Xīn de guīzhāng yǐjīng gōngbù le.","vi":"Quy chế mới đã được công bố."},{"type":"simple","zh":"违反实验室规章的学生将被取消实验资格。","pinyin":"Wéifǎn shíyànshì guīzhāng de xuésheng jiāng bèi qǔxiāo shíyàn zīgé.","vi":"Sinh viên vi phạm quy chế phòng thí nghiệm sẽ bị hủy tư cách làm thí nghiệm."},{"type":"compound","zh":"即使是老板的亲戚，也必须按公司的规章办事。","pinyin":"Jíshǐ shì lǎobǎn de qīnqi, yě bìxū àn gōngsī de guīzhāng bànshì.","vi":"Cho dù là họ hàng của sếp cũng phải làm việc theo quy chế công ty."}],"related":[{"hanzi":"规章制度","pinyin":"guīzhāngzhìdù","vi":"nội quy chế độ"},{"hanzi":"规定","pinyin":"guīdìng","vi":"quy định"},{"hanzi":"条例","pinyin":"tiáolì","vi":"điều lệ"},{"hanzi":"章程","pinyin":"zhāngchéng","vi":"điều lệ, quy chế"}],"traditional":"規章"},{"id":"寡妇","hanzi":"寡妇","pinyin":"guǎfu","meaning_vi":"góa phụ","explanation":"寡 (ít/đơn độc) + 妇 (phụ nữ).","hsk_level":6,"tags":["danh-tu","con-nguoi","gia-dinh"],"image":"👩","examples":[{"type":"basic","zh":"她年轻时就成了寡妇。","pinyin":"Tā niánqīng shí jiù chéngle guǎfu.","vi":"Bà ấy góa chồng từ khi còn trẻ."},{"type":"simple","zh":"村里的寡妇独自把三个孩子拉扯大。","pinyin":"Cūnli de guǎfu dúzì bǎ sān gè háizi lāchedà.","vi":"Người góa phụ trong làng một mình nuôi ba đứa con khôn lớn."},{"type":"compound","zh":"虽然丈夫早逝，但是这位寡妇从没向生活低过头。","pinyin":"Suīrán zhàngfu zǎoshì, dànshì zhè wèi guǎfu cóng méi xiàng shēnghuó dī guotóu.","vi":"Tuy chồng mất sớm nhưng người góa phụ này chưa từng cúi đầu trước cuộc sống."}],"related":[{"hanzi":"鳏夫","pinyin":"guānfū","vi":"người góa vợ"},{"hanzi":"守寡","pinyin":"shǒuguǎ","vi":"ở góa"},{"hanzi":"丈夫","pinyin":"zhàngfu","vi":"chồng"},{"hanzi":"孤儿","pinyin":"gū'ér","vi":"trẻ mồ côi"}],"traditional":"寡婦"},{"id":"鬼斧神工","hanzi":"鬼斧神工","pinyin":"guǐfǔ-shéngōng","meaning_vi":"tuyệt tác thiên nhiên hoặc nghệ thuật tinh xảo như thần thánh tạo nên","explanation":"鬼斧 (búa của quỷ) + 神工 (tay nghề thần thánh) → như do quỷ thần làm ra → khen tác phẩm nghệ thuật hoặc cảnh thiên nhiên tinh xảo tuyệt diệu.","hsk_level":6,"tags":["thanh-ngu"],"image":"🗿","examples":[{"type":"basic","zh":"这些石林真是鬼斧神工。","pinyin":"Zhèxiē Shílín zhēn shì guǐfǔshéngōng.","vi":"Những rừng đá này thật là tuyệt tác của tạo hóa."},{"type":"simple","zh":"游客们无不惊叹这座牙雕的鬼斧神工。","pinyin":"Yóukèmen wúbù jīngtàn zhè zuò yádiāo de guǐfǔshéngōng.","vi":"Du khách ai cũng kinh ngạc trước sự tinh xảo tuyệt vời của tác phẩm chạm ngà này."},{"type":"compound","zh":"站在峡谷边上，我们不但感叹大自然的鬼斧神工，而且感到自己非常渺小。","pinyin":"Zhàn zài xiágǔ biānshang, wǒmen búdàn gǎntàn dàzìrán de guǐfǔshéngōng, érqiě gǎndào zìjǐ fēicháng miǎoxiǎo.","vi":"Đứng bên bờ hẻm núi, chúng tôi không những trầm trồ trước tuyệt tác của thiên nhiên mà còn thấy mình vô cùng nhỏ bé."}],"related":[{"hanzi":"巧夺天工","pinyin":"qiǎoduótiāngōng","vi":"khéo léo hơn trời"},{"hanzi":"精美","pinyin":"jīngměi","vi":"tinh xảo đẹp đẽ"},{"hanzi":"奇观","pinyin":"qíguān","vi":"kỳ quan"},{"hanzi":"精湛","pinyin":"jīngzhàn","vi":"tinh thông điêu luyện"}]},{"id":"轨迹","hanzi":"轨迹","pinyin":"guǐjì","meaning_vi":"quỹ đạo, dấu vết phát triển","explanation":"轨 (đường ray) + 迹 (dấu vết).","hsk_level":6,"tags":["danh-tu","khoa-hoc"],"image":"🚀","examples":[{"type":"basic","zh":"卫星的运行轨迹很稳定。","pinyin":"Wèixīng de yùnxíng guǐjì hěn wěndìng.","vi":"Quỹ đạo vận hành của vệ tinh rất ổn định."},{"type":"simple","zh":"这本传记记录了一位科学家的人生轨迹。","pinyin":"Zhè běn zhuànjì jìlùle yí wèi kēxuéjiā de rénshēng guǐjì.","vi":"Cuốn tiểu sử này ghi lại chặng đường đời của một nhà khoa học."},{"type":"compound","zh":"警方一调出监控录像，就还原了嫌疑人的行动轨迹。","pinyin":"Jǐngfāng yí diào chū jiānkòng lùxiàng, jiù huányuánle xiányírén de xíngdòng guǐjì.","vi":"Cảnh sát vừa trích xuất video giám sát đã tái hiện được hành trình di chuyển của nghi phạm."}],"related":[{"hanzi":"轨道","pinyin":"guǐdào","vi":"quỹ đạo, đường ray"},{"hanzi":"痕迹","pinyin":"hénjì","vi":"dấu vết"},{"hanzi":"足迹","pinyin":"zújì","vi":"dấu chân"},{"hanzi":"路线","pinyin":"lùxiàn","vi":"lộ trình"}],"traditional":"軌跡"},{"id":"果断","hanzi":"果断","pinyin":"guǒduàn","meaning_vi":"quả quyết, dứt khoát","explanation":"果 (quả – quả quyết) + 断 (đoạn – quyết đoán) → quyết đoán, dứt khoát, không do dự. Ví dụ: 做事果断, 采取果断措施.","hsk_level":6,"tags":["tinh-tu"],"image":"⚡","examples":[{"type":"basic","zh":"他做事很果断。","pinyin":"Tā zuòshì hěn guǒduàn.","vi":"Anh ấy làm việc rất dứt khoát."},{"type":"simple","zh":"船长果断下令所有乘客穿上救生衣。","pinyin":"Chuánzhǎng guǒduàn xiàlìng suǒyǒu chéngkè chuānshàng jiùshēngyī.","vi":"Thuyền trưởng dứt khoát ra lệnh cho mọi hành khách mặc áo phao."},{"type":"compound","zh":"要不是医生当时处理得果断，病人恐怕就保不住了。","pinyin":"Yàobúshì yīshēng dāngshí chǔlǐ de guǒduàn, bìngrén kǒngpà jiù bǎobuzhù le.","vi":"Nếu không nhờ bác sĩ lúc đó xử lý quyết đoán thì e rằng đã không giữ được tính mạng bệnh nhân."}],"related":[{"hanzi":"果敢","pinyin":"guǒgǎn","vi":"quả cảm"},{"hanzi":"犹豫","pinyin":"yóuyù","vi":"do dự"},{"hanzi":"当机立断","pinyin":"dāngjīlìduàn","vi":"quyết đoán kịp thời"},{"hanzi":"优柔寡断","pinyin":"yōuróuguǎduàn","vi":"thiếu quyết đoán"}],"traditional":"果斷"},{"id":"盖世无双","hanzi":"盖世无双","pinyin":"gàishì-wúshuāng","meaning_vi":"có một không hai trên đời","explanation":"盖世 (cái thế – trùm cả đời, vượt mọi người đương thời) + 无双 (vô song – không ai sánh) → tài năng, võ nghệ có một không hai trên đời.","hsk_level":6,"tags":["thanh-ngu"],"image":"👑","examples":[{"type":"basic","zh":"他的武功盖世无双。","pinyin":"Tā de wǔgōng gàishìwúshuāng.","vi":"Võ công của ông ta có một không hai trên đời."},{"type":"simple","zh":"传说中项羽是一位盖世无双的英雄。","pinyin":"Chuánshuō zhōng Xiàngyǔ shì yí wèi gàishìwúshuāng de yīngxióng.","vi":"Theo truyền thuyết, Hạng Vũ là một anh hùng có một không hai."},{"type":"compound","zh":"即使你的才华盖世无双，也需要别人的帮助。","pinyin":"Jíshǐ nǐ de cáihuá gàishìwúshuāng, yě xūyào biérén de bāngzhù.","vi":"Cho dù tài năng của bạn có một không hai, bạn cũng cần sự giúp đỡ của người khác."}],"related":[{"hanzi":"举世无双","pinyin":"jǔshìwúshuāng","vi":"có một không hai"},{"hanzi":"独一无二","pinyin":"dúyìwú'èr","vi":"độc nhất vô nhị"},{"hanzi":"无与伦比","pinyin":"wúyǔlúnbǐ","vi":"không gì sánh bằng"},{"hanzi":"盖世英雄","pinyin":"gàishìyīngxióng","vi":"anh hùng cái thế"}],"traditional":"蓋世無雙"},{"id":"赣","hanzi":"赣","pinyin":"Gàn","meaning_vi":"tên gọi tắt của tỉnh Giang Tây (TQ)","explanation":"Ký hiệu biển số xe tỉnh Giang Tây.","hsk_level":6,"tags":["danh-tu","dia-danh"],"image":"🗺️","examples":[{"type":"basic","zh":"赣是江西的简称。","pinyin":"Gàn shì Jiāngxī de jiǎnchēng.","vi":"Chữ Cống là tên gọi tắt của tỉnh Giang Tây."},{"type":"simple","zh":"我第一次吃赣菜就爱上了它的香辣。","pinyin":"Wǒ dìyīcì chī Gàn cài jiù àishàngle tā de xiāng là.","vi":"Lần đầu ăn món Giang Tây, tôi đã mê ngay vị cay thơm của nó."},{"type":"compound","zh":"因为赣江贯穿全省南北，所以人们常用赣来指代江西。","pinyin":"Yīnwèi Gànjiāng guànchuān quánshěng nánběi, suǒyǐ rénmen chángyòng Gàn lái zhǐdài Jiāngxī.","vi":"Vì sông Cống chảy xuyên suốt tỉnh từ nam lên bắc nên người ta thường dùng chữ Cống để chỉ Giang Tây."}],"related":[{"hanzi":"江西","pinyin":"Jiāngxī","vi":"tỉnh Giang Tây"},{"hanzi":"赣江","pinyin":"Gànjiāng","vi":"sông Cám"},{"hanzi":"南昌","pinyin":"Nánchāng","vi":"thành phố Nam Xương"},{"hanzi":"省份","pinyin":"shěngfèn","vi":"tỉnh"}],"traditional":"贛"},{"id":"干劲","hanzi":"干劲","pinyin":"gànjìn","meaning_vi":"nhiệt huyết làm việc","explanation":"干 (cán – làm việc) + 劲 (kình – sức lực, hăng hái) → nhiệt tình, sức hăng hái làm việc. Ví dụ: 干劲十足, 鼓足干劲.","hsk_level":6,"tags":["danh-tu"],"image":"🔥","examples":[{"type":"basic","zh":"年轻人干劲十足。","pinyin":"Niánqīngrén gànjìn shízú.","vi":"Người trẻ tràn đầy nhiệt huyết làm việc."},{"type":"simple","zh":"老板的一番话让大家的干劲更大了。","pinyin":"Lǎobǎn de yìfān huà ràng dàjiā de gànjìn gèng dà le.","vi":"Một phen nói chuyện của sếp khiến mọi người càng hăng say làm việc."},{"type":"compound","zh":"一听说完成任务有奖金，工人们的干劲就上来了。","pinyin":"Yì tīngshuō wánchéng rènwu yǒu jiǎngjīn, gōngrénmen de gànjìn jiù shànglái le.","vi":"Vừa nghe nói hoàn thành nhiệm vụ có thưởng, công nhân liền hăng hái hẳn lên."}],"related":[{"hanzi":"劲头","pinyin":"jìntóu","vi":"sức hăng hái"},{"hanzi":"热情","pinyin":"rèqíng","vi":"nhiệt tình"},{"hanzi":"积极性","pinyin":"jījíxìng","vi":"tính tích cực"},{"hanzi":"干劲十足","pinyin":"gànjìnshízú","vi":"tràn đầy nhiệt huyết"}],"traditional":"幹勁"},{"id":"告辞","hanzi":"告辞","pinyin":"gàocí","meaning_vi":"cáo từ, xin phép về","explanation":"告 (cáo – báo) + 辞 (từ – từ biệt) → cáo từ, xin phép ra về (lịch sự). Ví dụ: 时间不早了，我告辞了.","hsk_level":6,"tags":["dong-tu"],"image":"🙇","examples":[{"type":"basic","zh":"时间不早，我先告辞了。","pinyin":"Shíjiān bù zǎo, wǒ xiān gàocí le.","vi":"Không còn sớm nữa, tôi xin phép về trước."},{"type":"simple","zh":"客人喝完茶就起身向主人告辞了。","pinyin":"Kèrén hē wán chá jiù qǐshēn xiàng zhǔrén gàocí le.","vi":"Khách uống xong trà liền đứng dậy cáo từ chủ nhà."},{"type":"compound","zh":"既然您还有别的客人，那我就不打扰了，先告辞。","pinyin":"Jìrán nín háiyǒu biéde kèrén, nà wǒ jiù bù dǎrǎole, xiān gàocí.","vi":"Ngài còn có khách khác thì tôi không làm phiền nữa, xin cáo từ trước."}],"related":[{"hanzi":"告别","pinyin":"gàobié","vi":"từ biệt"},{"hanzi":"辞别","pinyin":"cíbié","vi":"chào từ biệt"},{"hanzi":"再见","pinyin":"zàijiàn","vi":"tạm biệt"},{"hanzi":"拜访","pinyin":"bàifǎng","vi":"thăm hỏi"}],"traditional":"告辭"},{"id":"各奔前程","hanzi":"各奔前程","pinyin":"gèbèn-qiánchéng","meaning_vi":"mỗi người một ngả theo đuổi tương lai riêng","explanation":"各 (mỗi người) + 奔 (bôn – chạy tới) + 前程 (tiền trình – con đường tương lai) → mỗi người đi một ngả theo tiền đồ của mình; thường nói khi chia tay sau tốt nghiệp.","hsk_level":6,"tags":["thanh-ngu"],"image":"🛤️","examples":[{"type":"basic","zh":"大学毕业，四个室友各奔前程。","pinyin":"Dàxué bìyè, sì gè shìyǒu gèbènqiánchéng.","vi":"Tốt nghiệp đại học, bốn người bạn cùng phòng mỗi người một ngả."},{"type":"simple","zh":"公司解散以后，老同事们各奔前程了。","pinyin":"Gōngsī jiěsàn yǐhòu, lǎo tóngshìmen gèbènqiánchéng le.","vi":"Sau khi công ty giải thể, các đồng nghiệp cũ mỗi người một ngả."},{"type":"compound","zh":"虽然我们即将各奔前程，但是这份友谊会永远留在心里。","pinyin":"Suīrán wǒmen jíjiāng gèbènqiánchéng, dànshì zhè fèn yǒuyì huì yǒngyuǎn liú zài xīnli.","vi":"Tuy chúng ta sắp mỗi người một ngả nhưng tình bạn này sẽ mãi ở trong tim."}],"related":[{"hanzi":"分道扬镳","pinyin":"fēndàoyángbiāo","vi":"mỗi người một ngả"},{"hanzi":"前程","pinyin":"qiánchéng","vi":"tiền đồ"},{"hanzi":"分别","pinyin":"fēnbié","vi":"chia tay"},{"hanzi":"各奔东西","pinyin":"gèbèndōngxī","vi":"mỗi người một phương"}]},{"id":"各抒己见","hanzi":"各抒己见","pinyin":"gèshū-jǐjiàn","meaning_vi":"mỗi người tự do bày tỏ ý kiến riêng","explanation":"各 (mỗi người) + 抒 (trữ – bày tỏ) + 己见 (kỷ kiến – ý kiến của mình) → mọi người đều nói ra ý kiến riêng; thường dùng trong thảo luận, họp.","hsk_level":6,"tags":["thanh-ngu","giao-tiep"],"image":"🗣️","examples":[{"type":"basic","zh":"会上大家各抒己见。","pinyin":"Huì shang dàjiā gèshūjǐjiàn.","vi":"Trong cuộc họp mọi người đều bày tỏ ý kiến riêng."},{"type":"simple","zh":"主持人鼓励观众围绕这个话题各抒己见。","pinyin":"Zhǔchírén gǔlì guānzhòng wéirào zhè ge huàtí gèshūjǐjiàn.","vi":"Người dẫn chương trình khuyến khích khán giả bày tỏ ý kiến riêng xoay quanh chủ đề này."},{"type":"compound","zh":"只要大家各抒己见，我们就能找到最好的方案。","pinyin":"Zhǐyào dàjiā gèshūjǐjiàn, wǒmen jiù néng zhǎodào zuìhǎo de fāng'àn.","vi":"Chỉ cần mọi người tự do phát biểu ý kiến, chúng ta sẽ tìm ra phương án tốt nhất."}],"related":[{"hanzi":"畅所欲言","pinyin":"chàngsuǒyùyán","vi":"nói hết điều muốn nói"},{"hanzi":"意见","pinyin":"yìjiàn","vi":"ý kiến"},{"hanzi":"发表","pinyin":"fābiǎo","vi":"phát biểu"},{"hanzi":"众说纷纭","pinyin":"zhòngshuōfēnyún","vi":"mỗi người một ý"}],"traditional":"各抒己見"},{"id":"各有千秋","hanzi":"各有千秋","pinyin":"gèyǒu-qiānqiū","meaning_vi":"mỗi người một vẻ, đều có thế mạnh riêng","explanation":"各有 (mỗi bên đều có) + 千秋 (thiên thu – nghìn năm, cái đáng lưu truyền) → mỗi người, mỗi thứ đều có ưu điểm, nét đặc sắc riêng, khó phân hơn kém.","hsk_level":6,"tags":["thanh-ngu"],"image":"🌟","examples":[{"type":"basic","zh":"两幅画各有千秋。","pinyin":"Liǎng fú huà gèyǒuqiānqiū.","vi":"Hai bức tranh mỗi bức một vẻ."},{"type":"simple","zh":"南方菜和北方菜在口味上各有千秋。","pinyin":"Nánfāng cài hé běifāng cài zài kǒuwèi shang gèyǒuqiānqiū.","vi":"Món ăn miền Nam và miền Bắc mỗi nơi có nét ngon riêng về hương vị."},{"type":"compound","zh":"虽然这两位歌手风格完全不同，但是可以说各有千秋。","pinyin":"Suīrán zhè liǎng wèi gēshǒu fēnggé wánquán bùtóng, dànshì kěyǐ shuō gèyǒuqiānqiū.","vi":"Tuy phong cách của hai ca sĩ này hoàn toàn khác nhau nhưng có thể nói mỗi người một vẻ."}],"related":[{"hanzi":"各有所长","pinyin":"gèyǒusuǒcháng","vi":"mỗi người có sở trường"},{"hanzi":"不相上下","pinyin":"bùxiāngshàngxià","vi":"ngang tài ngang sức"},{"hanzi":"千秋","pinyin":"qiānqiū","vi":"nghìn năm, ưu điểm"},{"hanzi":"平分秋色","pinyin":"píngfēnqiūsè","vi":"chia đều thắng lợi"}]},{"id":"更胜一筹","hanzi":"更胜一筹","pinyin":"gèngshèng-yìchóu","meaning_vi":"nhỉnh hơn một bậc, vượt trội hơn","explanation":"更胜 (càng hơn) + 一筹 (nhất trù – một thẻ tính điểm) → hơn một bậc, nhỉnh hơn khi so sánh. Thường gặp: A比B更胜一筹.","hsk_level":6,"tags":["thanh-ngu"],"image":"🏆","examples":[{"type":"basic","zh":"他的厨艺更胜一筹。","pinyin":"Tā de chúyì gèng shèng yì chóu.","vi":"Tay nghề nấu ăn của anh ấy nhỉnh hơn một bậc."},{"type":"simple","zh":"新款电脑在速度上比旧款更胜一筹。","pinyin":"Xīnkuǎn diànnǎo zài sùdù shang bǐ jiùkuǎn gèng shèng yì chóu.","vi":"Mẫu máy tính mới nhỉnh hơn mẫu cũ một bậc về tốc độ."},{"type":"compound","zh":"因为主队的配合更胜一筹，所以最后以二比一赢了比赛。","pinyin":"Yīnwèi zhǔduì de pèihé gèng shèng yì chóu, suǒyǐ zuìhòu yǐ èr bǐ yì yíngle bǐsài.","vi":"Vì đội chủ nhà phối hợp nhỉnh hơn một bậc nên cuối cùng đã thắng trận với tỉ số hai một."}],"related":[{"hanzi":"略胜一筹","pinyin":"lüèshèngyìchóu","vi":"nhỉnh hơn một chút"},{"hanzi":"技高一筹","pinyin":"jìgāoyìchóu","vi":"cao tay hơn"},{"hanzi":"超过","pinyin":"chāoguò","vi":"vượt qua"},{"hanzi":"逊色","pinyin":"xùnsè","vi":"kém hơn"}],"traditional":"更勝一籌"},{"id":"隔绝","hanzi":"隔绝","pinyin":"géjué","meaning_vi":"cách biệt hoàn toàn, cắt đứt liên lạc","explanation":"隔 (ngăn) + 绝 (dứt).","hsk_level":6,"tags":["dong-tu"],"image":"🚧","examples":[{"type":"basic","zh":"这个村子与世隔绝。","pinyin":"Zhè ge cūnzi yǔ shì géjué.","vi":"Ngôi làng này cách biệt với thế giới bên ngoài."},{"type":"simple","zh":"这种材料可以有效隔绝外面的噪音。","pinyin":"Zhè zhǒng cáiliào kěyǐ yǒuxiào géjué wàimiàn de zàoyīn.","vi":"Loại vật liệu này có thể cách ly hiệu quả tiếng ồn bên ngoài."},{"type":"compound","zh":"因为长时间与人隔绝，所以他刚回来时连话都不太会说了。","pinyin":"Yīnwèi cháng shíjiān yǔ rén géjué, suǒyǐ tā gāng huílái shí lián huà dōu bú tài huì shuō le.","vi":"Vì cách biệt với mọi người quá lâu nên lúc mới trở về anh ấy gần như không biết nói chuyện nữa."}],"related":[{"hanzi":"隔离","pinyin":"gélí","vi":"cách ly"},{"hanzi":"与世隔绝","pinyin":"yǔshìgéjué","vi":"cách biệt với thế giới"},{"hanzi":"断绝","pinyin":"duànjué","vi":"cắt đứt"},{"hanzi":"封闭","pinyin":"fēngbì","vi":"khép kín"}],"traditional":"隔絕"},{"id":"格式","hanzi":"格式","pinyin":"géshì","meaning_vi":"định dạng, quy cách","explanation":"格 (cách – ô, khuôn khổ) + 式 (thức – kiểu) → mẫu, quy cách trình bày; trong tin học là định dạng tệp. Ví dụ: 书信格式, 文件格式, 格式化.","hsk_level":6,"tags":["danh-tu","cong-nghe"],"image":"📑","examples":[{"type":"basic","zh":"这个文件格式不对。","pinyin":"Zhè ge wénjiàn géshì bú duì.","vi":"File này sai định dạng."},{"type":"simple","zh":"请按照学校规定的格式写毕业论文。","pinyin":"Qǐng ànzhào xuéxiào guīdìng de géshì xiě bìyèlùnwén.","vi":"Hãy viết luận văn tốt nghiệp theo định dạng nhà trường quy định."},{"type":"compound","zh":"如果简历格式太乱，招聘人员就可能直接跳过。","pinyin":"Rúguǒ jiǎnlì géshì tài luàn, zhāopìn rényuán jiù kěnéng zhíjiē tiàoguò.","vi":"Nếu định dạng sơ yếu lý lịch quá lộn xộn, nhà tuyển dụng có thể bỏ qua luôn."}],"related":[{"hanzi":"格式化","pinyin":"géshìhuà","vi":"định dạng hóa"},{"hanzi":"文件","pinyin":"wénjiàn","vi":"tệp tài liệu"},{"hanzi":"模板","pinyin":"múbǎn","vi":"mẫu"},{"hanzi":"规格","pinyin":"guīgé","vi":"quy cách"}]},{"id":"格杀勿论","hanzi":"格杀勿论","pinyin":"géshā-wùlùn","meaning_vi":"được phép giết tại chỗ (kẻ chống cự) mà không bị truy cứu","explanation":"格杀 (cách sát – giết kẻ chống cự) + 勿论 (vật luận – không bị truy cứu) → được phép giết ngay tại chỗ kẻ chống lệnh/chống bắt mà không bị xét tội.","hsk_level":6,"tags":["thanh-ngu"],"image":"⚔️","examples":[{"type":"basic","zh":"敢闯入者格杀勿论。","pinyin":"Gǎn chuǎngrù zhě géshāwùlùn.","vi":"Kẻ nào dám xông vào sẽ bị giết không tha."},{"type":"simple","zh":"皇帝下令对叛军首领格杀勿论。","pinyin":"Huángdì xiàlìng duì pànjūn shǒulǐng géshāwùlùn.","vi":"Hoàng đế ra lệnh giết không tha thủ lĩnh quân phản loạn."},{"type":"compound","zh":"古时候如果有人私闯皇宫，守卫就可以格杀勿论。","pinyin":"Gǔshíhou rúguǒ yǒurén sīchuǎng huánggōng, shǒuwèi jiù kěyǐ géshāwùlùn.","vi":"Thời xưa nếu có kẻ tự ý xông vào hoàng cung, lính canh có thể giết ngay không cần xét hỏi."}],"related":[{"hanzi":"杀","pinyin":"shā","vi":"giết"},{"hanzi":"镇压","pinyin":"zhènyā","vi":"trấn áp"},{"hanzi":"戒严","pinyin":"jièyán","vi":"giới nghiêm"},{"hanzi":"处死","pinyin":"chǔsǐ","vi":"xử tử"}],"traditional":"格殺勿論"},{"id":"革新","hanzi":"革新","pinyin":"géxīn","meaning_vi":"đổi mới, cải tiến kỹ thuật","explanation":"革 (đổi) + 新 (mới).","hsk_level":6,"tags":["dong-tu","cong-nghe"],"image":"💡","examples":[{"type":"basic","zh":"技术需要不断革新。","pinyin":"Jìshù xūyào búduàn géxīn.","vi":"Kỹ thuật cần không ngừng đổi mới."},{"type":"simple","zh":"这家工厂对生产线进行了全面革新。","pinyin":"Zhè jiā gōngchǎng duìshēng chǎnxiàn jìnxíngle quánmiàn géxīn.","vi":"Nhà máy này đã cải tiến toàn diện dây chuyền sản xuất."},{"type":"compound","zh":"如果企业拒绝革新，就会被市场淘汰。","pinyin":"Rúguǒ qǐyè jùjué géxīn, jiù huì bèi shìchǎng táotài.","vi":"Nếu doanh nghiệp từ chối đổi mới thì sẽ bị thị trường đào thải."}],"related":[{"hanzi":"创新","pinyin":"chuàngxīn","vi":"sáng tạo đổi mới"},{"hanzi":"改革","pinyin":"gǎigé","vi":"cải cách"},{"hanzi":"技术革新","pinyin":"jìshùgéxīn","vi":"đổi mới kỹ thuật"},{"hanzi":"守旧","pinyin":"shǒujiù","vi":"thủ cựu"}]},{"id":"隔岸观火","hanzi":"隔岸观火","pinyin":"gé'àn-guānhuǒ","meaning_vi":"đứng bên kia bờ nhìn lửa cháy (thờ ơ trước khó khăn của người khác)","explanation":"隔岸 (cách bờ – bên kia sông) + 观火 (xem lửa) → đứng bờ bên kia xem cháy → ví khoanh tay đứng nhìn người gặp nạn, không giúp đỡ, chờ hưởng lợi (một kế trong 36 kế).","hsk_level":6,"tags":["thanh-ngu"],"image":"🔥","examples":[{"type":"basic","zh":"他只会隔岸观火。","pinyin":"Tā zhǐ huì gé'ànguānhuǒ.","vi":"Anh ta chỉ biết đứng ngoài nhìn người khác gặp nạn."},{"type":"simple","zh":"邻国对这场冲突采取了隔岸观火的态度。","pinyin":"Línguó duì zhè chǎng chōngtū cǎiqǔle gé'ànguānhuǒ de tàidù.","vi":"Nước láng giềng giữ thái độ đứng ngoài bàng quan trước cuộc xung đột này."},{"type":"compound","zh":"同事遇到困难时，我们与其隔岸观火，不如伸手帮一把。","pinyin":"Tóngshì yùdào kùnnan shí, wǒmen yǔqí gé'ànguānhuǒ, bùrú shēnshǒu bāng yì bǎ.","vi":"Khi đồng nghiệp gặp khó khăn, thay vì đứng ngoài bàng quan, chúng ta nên chìa tay giúp một tay."}],"related":[{"hanzi":"袖手旁观","pinyin":"xiùshǒupángguān","vi":"khoanh tay đứng nhìn"},{"hanzi":"幸灾乐祸","pinyin":"xìngzāilèhuò","vi":"vui trên nỗi đau người khác"},{"hanzi":"见死不救","pinyin":"jiànsǐbújiù","vi":"thấy chết không cứu"},{"hanzi":"冷漠","pinyin":"lěngmò","vi":"thờ ơ"}],"traditional":"隔岸觀火"},{"id":"共处","hanzi":"共处","pinyin":"gòngchǔ","meaning_vi":"chung sống (hòa bình)","explanation":"共 (cùng) + 处 (ở). Cụm: 和平共处.","hsk_level":6,"tags":["dong-tu","xa-hoi"],"image":"🕊️","examples":[{"type":"basic","zh":"人与自然和谐共处。","pinyin":"Rén yǔ zìrán héxié gòngchǔ.","vi":"Con người và thiên nhiên chung sống hài hòa."},{"type":"simple","zh":"两只猫在同一个屋檐下和平共处。","pinyin":"Liǎng zhī māo zài tóngyī gè wūyán xià hépínggòngchǔ.","vi":"Hai con mèo chung sống hòa bình dưới cùng một mái nhà."},{"type":"compound","zh":"只要互相尊重，不同信仰的人也能友好共处。","pinyin":"Zhǐyào hùxiāng zūnzhòng, bùtóng xìnyǎng de rén yě néng yǒuhǎo gòngchǔ.","vi":"Chỉ cần tôn trọng lẫn nhau, những người có tín ngưỡng khác nhau cũng có thể chung sống thân thiện."}],"related":[{"hanzi":"相处","pinyin":"xiāngchǔ","vi":"chung sống, đối xử"},{"hanzi":"和平共处","pinyin":"hépínggòngchǔ","vi":"chung sống hòa bình"},{"hanzi":"共存","pinyin":"gòngcún","vi":"cùng tồn tại"},{"hanzi":"和睦","pinyin":"hémù","vi":"hòa thuận"}],"traditional":"共處"},{"id":"共和国","hanzi":"共和国","pinyin":"gònghéguó","meaning_vi":"nước cộng hòa","explanation":"共和 (cộng hòa – cùng điều hành) + 国 (quốc – nước) → nhà nước theo chế độ cộng hòa. Ví dụ: 中华人民共和国, 越南社会主义共和国.","hsk_level":6,"tags":["danh-tu","xa-hoi"],"image":"🌍","examples":[{"type":"basic","zh":"法国是一个共和国。","pinyin":"Fǎ guóshì yí gè gònghéguó.","vi":"Pháp là một nước cộng hòa."},{"type":"simple","zh":"这个国家在独立后宣布成立共和国。","pinyin":"Zhè ge guójiā zài dúlì hòu xuānbù chénglì gònghéguó.","vi":"Đất nước này tuyên bố thành lập nước cộng hòa sau khi độc lập."},{"type":"compound","zh":"共和国虽然没有国王，但是仍然有国家元首。","pinyin":"Gònghéguó suīrán méiyǒu guówáng, dànshì réngrán yǒu guójiā yuánshǒu.","vi":"Nước cộng hòa tuy không có vua nhưng vẫn có nguyên thủ quốc gia."}],"related":[{"hanzi":"共和","pinyin":"gònghé","vi":"cộng hòa"},{"hanzi":"国家","pinyin":"guójiā","vi":"quốc gia"},{"hanzi":"人民共和国","pinyin":"rénmín gònghéguó","vi":"nước cộng hòa nhân dân"},{"hanzi":"王国","pinyin":"wángguó","vi":"vương quốc"}],"traditional":"共和國"},{"id":"构想","hanzi":"构想","pinyin":"gòuxiǎng","meaning_vi":"ý tưởng, cấu tứ","explanation":"构 (xây dựng) + 想 (nghĩ).","hsk_level":6,"tags":["danh-tu","dong-tu"],"image":"💡","examples":[{"type":"basic","zh":"这个构想很大胆。","pinyin":"Zhè ge gòuxiǎng hěn dàdǎn.","vi":"Ý tưởng này rất táo bạo."},{"type":"simple","zh":"设计师向我们介绍了新城区的整体构想。","pinyin":"Shèjìshī xiàng wǒmen jièshàole Xīnchéngqū de zhěngtǐ gòuxiǎng.","vi":"Nhà thiết kế giới thiệu với chúng tôi ý tưởng tổng thể về khu đô thị mới."},{"type":"compound","zh":"虽然他的构想很好，但是目前的技术还无法实现。","pinyin":"Suīrán tā de gòuxiǎng hěn hǎo, dànshì mùqián de jìshù hái wúfǎ shíxiàn.","vi":"Tuy ý tưởng của anh ấy rất hay nhưng công nghệ hiện nay chưa thể thực hiện được."}],"related":[{"hanzi":"设想","pinyin":"shèxiǎng","vi":"ý tưởng, giả định"},{"hanzi":"构思","pinyin":"gòusī","vi":"cấu tứ"},{"hanzi":"想法","pinyin":"xiǎngfǎ","vi":"suy nghĩ"},{"hanzi":"方案","pinyin":"fāng'àn","vi":"phương án"}],"traditional":"構想"},{"id":"固步自封","hanzi":"固步自封","pinyin":"gùbù-zìfēng","meaning_vi":"bảo thủ trì trệ, tự giam mình trong khuôn khổ cũ","explanation":"固步 (bước chân cố định, giữ lối cũ) + 自封 (tự đóng mình) → giẫm mãi bước cũ, tự giới hạn → bảo thủ, không chịu tiến bộ. Dạng chuẩn viết 故步自封.","hsk_level":6,"tags":["thanh-ngu"],"image":"🔒","examples":[{"type":"basic","zh":"做学问不能固步自封。","pinyin":"Zuòxuéwen bù néng gùbùzìfēng.","vi":"Làm học thuật không được bảo thủ trì trệ."},{"type":"simple","zh":"固步自封的企业很难在竞争中生存。","pinyin":"Gùbùzìfēng de qǐyè hěn nán zài jìngzhēng zhōng shēngcún.","vi":"Doanh nghiệp bảo thủ trì trệ rất khó tồn tại trong cạnh tranh."},{"type":"compound","zh":"如果我们满足于现状、固步自封，就迟早会被别人超越。","pinyin":"Rúguǒ wǒmen mǎnzú yú xiànzhuàng, gùbùzìfēng, jiù chízǎo huì bèi biérén chāoyuè.","vi":"Nếu chúng ta thỏa mãn với hiện trạng, bảo thủ trì trệ thì sớm muộn sẽ bị người khác vượt qua."}],"related":[{"hanzi":"墨守成规","pinyin":"mòshǒuchéngguī","vi":"khư khư nếp cũ"},{"hanzi":"保守","pinyin":"bǎoshǒu","vi":"bảo thủ"},{"hanzi":"停滞不前","pinyin":"tíngzhìbùqián","vi":"trì trệ không tiến"},{"hanzi":"与时俱进","pinyin":"yǔshíjùjìn","vi":"theo kịp thời đại"}]},{"id":"顾名思义","hanzi":"顾名思义","pinyin":"gùmíng-sīyì","meaning_vi":"nhìn tên đoán nghĩa, đúng như tên gọi","explanation":"顾名 (cố danh – nhìn tên gọi) + 思义 (tư nghĩa – nghĩ ra ý nghĩa) → nhìn tên là đoán được nghĩa. Thường đặt đầu câu để giải thích: 顾名思义，……","hsk_level":6,"tags":["thanh-ngu"],"image":"💡","examples":[{"type":"basic","zh":"顾名思义，夜市晚上才开。","pinyin":"Gùmíngsīyì, yèshì wǎnshang cái kāi.","vi":"Đúng như tên gọi, chợ đêm chỉ mở vào buổi tối."},{"type":"simple","zh":"顾名思义，向日葵总是朝着太阳生长。","pinyin":"Gùmíngsīyì, xiàng rì kuí zǒngshì cháozhe tàiyáng shēngzhǎng.","vi":"Đúng như tên gọi, hoa hướng dương luôn mọc hướng về phía mặt trời."},{"type":"compound","zh":"顾名思义，素食馆只卖蔬菜，所以你在这里是吃不到肉的。","pinyin":"Gùmíngsīyì, sùshí guǎn zhǐ mài shūcài, suǒyǐ nǐ zài zhèlǐ shì chī budào ròu de.","vi":"Đúng như tên gọi, quán chay chỉ bán rau củ nên ở đây bạn không ăn được thịt đâu."}],"related":[{"hanzi":"名称","pinyin":"míngchēng","vi":"tên gọi"},{"hanzi":"名副其实","pinyin":"míngfùqíshí","vi":"danh xứng với thực"},{"hanzi":"字面","pinyin":"zìmiàn","vi":"nghĩa đen"},{"hanzi":"含义","pinyin":"hányì","vi":"hàm ý"}],"traditional":"顧名思義"},{"id":"顾全大局","hanzi":"顾全大局","pinyin":"gùquán-dàjú","meaning_vi":"giữ gìn đại cục, vì lợi ích chung","explanation":"顾全 (cố toàn – lo cho trọn vẹn) + 大局 (đại cục – cục diện chung) → biết đặt lợi ích chung lên trên lợi ích riêng.","hsk_level":6,"tags":["thanh-ngu"],"image":"🌐","examples":[{"type":"basic","zh":"他总能顾全大局。","pinyin":"Tā zǒngnéng gùquándàjú.","vi":"Anh ấy luôn biết đặt đại cục lên trên."},{"type":"simple","zh":"为了顾全大局，她主动放弃了出国的机会。","pinyin":"Wèile gùquándàjú, tā zhǔdòng fàngqìle chūguó de jīhuì.","vi":"Vì đại cục, cô ấy chủ động từ bỏ cơ hội ra nước ngoài."},{"type":"compound","zh":"如果每个人都只想着自己而不顾全大局，团队就会一盘散沙。","pinyin":"Rúguǒ měigèrén dōu zhǐ xiǎngzhe zìjǐ ér bú gùquándàjú, tuánduì jiù huì yì pán sǎnshā.","vi":"Nếu ai cũng chỉ nghĩ cho mình mà không vì đại cục thì cả nhóm sẽ rời rạc như một nắm cát."}],"related":[{"hanzi":"大局","pinyin":"dàjú","vi":"đại cục"},{"hanzi":"以大局为重","pinyin":"yǐ dàjú wéizhòng","vi":"lấy đại cục làm trọng"},{"hanzi":"舍己为人","pinyin":"shějǐwèirén","vi":"xả thân vì người"},{"hanzi":"识大体","pinyin":"shídàtǐ","vi":"biết nghĩ cho đại cục"}],"traditional":"顧全大局"},{"id":"固体","hanzi":"固体","pinyin":"gùtǐ","meaning_vi":"chất rắn","explanation":"固 (cố – rắn chắc) + 体 (thể – vật thể, trạng thái) → chất rắn. Đối với 液体 (chất lỏng), 气体 (chất khí).","hsk_level":6,"tags":["danh-tu","khoa-hoc"],"image":"🧊","examples":[{"type":"basic","zh":"冰是一种固体。","pinyin":"Bīng shì yì zhǒng gùtǐ.","vi":"Băng là một loại chất rắn."},{"type":"simple","zh":"实验室里的这种固体遇水会迅速溶解。","pinyin":"Shíyànshì li de zhè zhǒng gùtǐ yù shuǐ huì xùnsù róngjiě.","vi":"Loại chất rắn trong phòng thí nghiệm này gặp nước sẽ tan rất nhanh."},{"type":"compound","zh":"水一到零度以下，就会从液体变成固体。","pinyin":"Shuǐ yí dào língdù yǐxià, jiù huì cóng yètǐ biànchéng gùtǐ.","vi":"Nước hễ xuống dưới không độ sẽ chuyển từ thể lỏng sang thể rắn."}],"related":[{"hanzi":"液体","pinyin":"yètǐ","vi":"chất lỏng"},{"hanzi":"气体","pinyin":"qìtǐ","vi":"chất khí"},{"hanzi":"固态","pinyin":"gùtài","vi":"trạng thái rắn"},{"hanzi":"物体","pinyin":"wùtǐ","vi":"vật thể"}],"traditional":"固體"},{"id":"故土","hanzi":"故土","pinyin":"gùtǔ","meaning_vi":"quê hương, mảnh đất chôn rau cắt rốn","explanation":"故 (cũ) + 土 (đất).","hsk_level":6,"tags":["danh-tu","van-hoa","dia-diem"],"image":"🏞️","examples":[{"type":"basic","zh":"他终于回到了故土。","pinyin":"Tā zhōngyú huídàole gùtǔ.","vi":"Cuối cùng ông ấy đã trở về quê cũ."},{"type":"simple","zh":"老华侨临终前还念念不忘遥远的故土。","pinyin":"Lǎo Huáqiáo línzhōng qián hái niànniànbúwàng yáoyuǎn de gùtǔ.","vi":"Ông Hoa kiều già trước lúc lâm chung vẫn không nguôi nhớ về quê hương xa xôi."},{"type":"compound","zh":"虽然离开故土已经四十年了，但是他的乡音一点儿也没变。","pinyin":"Suīrán líkāi gùtǔ yǐjīng sìshí nián le, dànshì tā de xiāngyīn yìdiǎnr yě méi biàn.","vi":"Tuy đã rời quê hương bốn mươi năm nhưng giọng quê của ông không hề thay đổi."}],"related":[{"hanzi":"故乡","pinyin":"gùxiāng","vi":"cố hương"},{"hanzi":"家乡","pinyin":"jiāxiāng","vi":"quê nhà"},{"hanzi":"故土难离","pinyin":"gùtǔnánlí","vi":"khó rời quê cũ"},{"hanzi":"祖国","pinyin":"zǔguó","vi":"tổ quốc"}]},{"id":"雇佣","hanzi":"雇佣","pinyin":"gùyōng","meaning_vi":"thuê mướn nhân công","explanation":"雇 (cố – thuê) + 佣 (dung – người làm thuê) → thuê mướn người làm việc trả công. Thường gặp: 雇佣关系, 雇佣军 (lính đánh thuê).","hsk_level":6,"tags":["dong-tu"],"image":"💼","examples":[{"type":"basic","zh":"他雇佣了一个司机。","pinyin":"Tā gùyōngle yí gè sījī.","vi":"Anh ấy đã thuê một tài xế."},{"type":"simple","zh":"这家农场每年夏天都雇佣大批临时工。","pinyin":"Zhè jiā nóngchǎng měinián xiàtiān dōu gùyōng dàpī línshígōng.","vi":"Trang trại này mỗi mùa hè đều thuê rất nhiều lao động thời vụ."},{"type":"compound","zh":"如果雇佣童工，工厂就会受到严厉的处罚。","pinyin":"Rúguǒ gùyōng tónggōng, gōngchǎng jiù huì shòudào yánlì de chǔfá.","vi":"Nếu thuê lao động trẻ em, nhà máy sẽ bị xử phạt nghiêm khắc."}],"related":[{"hanzi":"雇主","pinyin":"gùzhǔ","vi":"chủ thuê"},{"hanzi":"雇员","pinyin":"gùyuán","vi":"người làm thuê"},{"hanzi":"聘请","pinyin":"pìnqǐng","vi":"mời làm, tuyển dụng"},{"hanzi":"解雇","pinyin":"jiěgù","vi":"sa thải"}],"traditional":"僱傭"},{"id":"故障","hanzi":"故障","pinyin":"gùzhàng","meaning_vi":"sự cố, trục trặc kỹ thuật","explanation":"故 (cố – sự cố) + 障 (chướng – trở ngại) → hỏng hóc, trục trặc của máy móc, thiết bị. Ví dụ: 出故障, 排除故障, 机器发生故障.","hsk_level":6,"tags":["danh-tu","cong-nghe"],"image":"⚠️","examples":[{"type":"basic","zh":"电梯出故障了。","pinyin":"Diàntī chūgùzhàng le.","vi":"Thang máy bị hỏng rồi."},{"type":"simple","zh":"机械师正在检查飞机发动机的故障。","pinyin":"Jīxièshī zhèngzài jiǎnchá fēijī fādòngjī de gùzhàng.","vi":"Thợ máy đang kiểm tra sự cố động cơ máy bay."},{"type":"compound","zh":"因为系统突然发生故障，所以银行暂停了所有业务。","pinyin":"Yīnwèi xìtǒng tūrán fāshēng gùzhàng, suǒyǐ yínháng zàntíngle suǒyǒu yèwù.","vi":"Vì hệ thống đột nhiên gặp sự cố nên ngân hàng tạm dừng mọi giao dịch."}],"related":[{"hanzi":"毛病","pinyin":"máobìng","vi":"trục trặc"},{"hanzi":"出故障","pinyin":"chūgùzhàng","vi":"bị hỏng"},{"hanzi":"维修","pinyin":"wéixiū","vi":"sửa chữa"},{"hanzi":"失灵","pinyin":"shīlíng","vi":"mất tác dụng"}]},{"id":"棍","hanzi":"棍","pinyin":"gùn","meaning_vi":"cây gậy, côn","explanation":"Bộ mộc 木 + 昆. Ví dụ: 铁棍 (gậy sắt).","hsk_level":6,"tags":["danh-tu","do-vat"],"image":"🏏","examples":[{"type":"basic","zh":"他手里拿着一根木棍。","pinyin":"Tā shǒuli názhe yìgēn mùgùn.","vi":"Anh ấy cầm một cây gậy gỗ trong tay."},{"type":"simple","zh":"老人拄着一根竹棍慢慢地走上山。","pinyin":"Lǎorén zhǔzhe yìgēn zhú gùn mànmàn de zǒu shàngshān.","vi":"Ông lão chống cây gậy tre từ từ đi lên núi."},{"type":"compound","zh":"小偷一看见保安手里的铁棍，就吓得转身逃跑了。","pinyin":"Xiǎotōu yí kànjiàn bǎo'ān shǒuli de tiě gùn, jiù xià de zhuǎnshēn táopǎo le.","vi":"Tên trộm vừa nhìn thấy cây gậy sắt trong tay bảo vệ đã sợ hãi quay đầu bỏ chạy."}],"related":[{"hanzi":"棍子","pinyin":"gùnzi","vi":"cây gậy"},{"hanzi":"木棍","pinyin":"mùgùn","vi":"gậy gỗ"},{"hanzi":"棒","pinyin":"bàng","vi":"gậy, chùy"},{"hanzi":"拐杖","pinyin":"guǎizhàng","vi":"cái gậy chống"}]},{"id":"干瘪","hanzi":"干瘪","pinyin":"gānbiě","meaning_vi":"khô héo, lép kẹp, nghèo nàn (nội dung)","explanation":"干 (khô) + 瘪 (xẹp).","hsk_level":6,"tags":["tinh-tu"],"image":"🍂","examples":[{"type":"basic","zh":"苹果放得干瘪了。","pinyin":"Píngguǒ fàng de gānbiě le.","vi":"Quả táo để lâu đã héo quắt."},{"type":"simple","zh":"他写的报告内容干瘪得像流水账。","pinyin":"Tā xiě de bàogào nèiróng gānbiě de xiàng liúshuǐzhàng.","vi":"Bản báo cáo anh ấy viết nội dung khô khan như sổ ghi chép thu chi."},{"type":"compound","zh":"因为好几个月没有下雨，所以地里的玉米都长得又小又干瘪。","pinyin":"Yīnwèi hǎojǐ gèyuè méiyǒu xiàyǔ, suǒyǐ dì li de yùmǐ dōu zhǎngde yòu xiǎo yòu gānbiě.","vi":"Vì mấy tháng liền không mưa nên ngô ngoài đồng đều vừa nhỏ vừa lép kẹp."}],"related":[{"hanzi":"干枯","pinyin":"gānkū","vi":"khô héo"},{"hanzi":"饱满","pinyin":"bǎomǎn","vi":"đầy đặn"},{"hanzi":"枯燥","pinyin":"kūzào","vi":"khô khan"},{"hanzi":"空洞","pinyin":"kōngdòng","vi":"rỗng tuếch"}],"traditional":"乾癟"},{"id":"甘拜下风","hanzi":"甘拜下风","pinyin":"gānbài-xiàfēng","meaning_vi":"cam bái hạ phong, tâm phục khẩu phục chịu thua","explanation":"甘 (cam – cam lòng) + 拜 (bái – vái) + 下风 (hạ phong – phía cuối gió, thế yếu) → cam lòng nhận thua, thật lòng thừa nhận đối phương giỏi hơn.","hsk_level":6,"tags":["thanh-ngu"],"image":"🙇","examples":[{"type":"basic","zh":"论棋艺，我甘拜下风。","pinyin":"Lùn qíyì, wǒ gānbàixiàfēng.","vi":"Về tài đánh cờ, tôi xin chịu thua."},{"type":"simple","zh":"对手的精彩表现让他不得不甘拜下风。","pinyin":"Duìshǒu de jīngcǎi biǎoxiàn ràng tā bùdébù gānbàixiàfēng.","vi":"Màn thể hiện xuất sắc của đối thủ khiến anh ấy đành phải cam bái hạ phong."},{"type":"compound","zh":"虽然我练了三年书法，但是跟他比起来只能甘拜下风。","pinyin":"Suīrán wǒ liànle sān nián shūfǎ, dànshì gēn tā bǐ qǐlái zhǐnéng gānbàixiàfēng.","vi":"Tuy tôi đã luyện thư pháp ba năm nhưng so với anh ấy thì chỉ đành chịu thua."}],"related":[{"hanzi":"心服口服","pinyin":"xīnfúkǒufú","vi":"tâm phục khẩu phục"},{"hanzi":"认输","pinyin":"rènshū","vi":"chịu thua"},{"hanzi":"自愧不如","pinyin":"zìkuìbùrú","vi":"tự thấy không bằng"},{"hanzi":"不甘示弱","pinyin":"bùgānshìruò","vi":"không chịu kém"}],"traditional":"甘拜下風"},{"id":"肝胆相照","hanzi":"肝胆相照","pinyin":"gāndǎn-xiāngzhào","meaning_vi":"gan mật tương chiếu (tình bạn chân thành hết lòng)","explanation":"肝胆 (can đởm – gan mật, ý chỉ tấm lòng) + 相照 (tương chiếu – soi thấu nhau) → đối đãi với nhau hết lòng chân thành, tình bạn thân thiết tin cậy.","hsk_level":6,"tags":["thanh-ngu"],"image":"🤝","examples":[{"type":"basic","zh":"他们是肝胆相照的朋友。","pinyin":"Tāmen shì gāndǎnxiāngzhào de péngyou.","vi":"Họ là những người bạn chân thành hết lòng với nhau."},{"type":"simple","zh":"两位老战友几十年来一直肝胆相照。","pinyin":"Liǎng wèi lǎo zhànyǒu jǐ shí niánlái yìzhí gāndǎnxiāngzhào.","vi":"Hai người đồng đội cũ mấy chục năm nay luôn đối đãi với nhau hết lòng."},{"type":"compound","zh":"只有肝胆相照，合作伙伴之间才能真正互相信任。","pinyin":"Zhǐyǒu gāndǎnxiāngzhào, hézuò huǒbàn zhījiān cáinéng zhēnzhèng hùxiāng xìnrèn.","vi":"Chỉ có thật lòng đối đãi, các đối tác mới có thể thực sự tin tưởng lẫn nhau."}],"related":[{"hanzi":"推心置腹","pinyin":"tuīxīnzhìfù","vi":"thành thật với nhau"},{"hanzi":"知己","pinyin":"zhījǐ","vi":"tri kỷ"},{"hanzi":"患难之交","pinyin":"huànnànzhījiāo","vi":"bạn hoạn nạn"},{"hanzi":"真诚","pinyin":"zhēnchéng","vi":"chân thành"}],"traditional":"肝膽相照"},{"id":"尴尬","hanzi":"尴尬","pinyin":"gāngà","meaning_vi":"lúng túng, ngượng ngùng","explanation":"尴尬 (giam giới): lúng túng, khó xử, ngượng ngùng; cũng tả tình huống khó xử. Ví dụ: 场面很尴尬, 处境尴尬.","hsk_level":6,"tags":["tinh-tu"],"image":"😅","examples":[{"type":"basic","zh":"场面十分尴尬。","pinyin":"Chǎngmiàn shífēn gāngà.","vi":"Tình cảnh vô cùng ngượng ngùng."},{"type":"simple","zh":"一阵尴尬的沉默笼罩了整个会议室。","pinyin":"Yízhèn gāngà de chénmò lǒngzhàole zhěnggè huìyìshì.","vi":"Một khoảng lặng ngượng ngùng bao trùm cả phòng họp."},{"type":"compound","zh":"一见到前女友，他就尴尬得不知道说什么好。","pinyin":"Yí jiàndào qiánnǚyǒu, tā jiù gāngà de bù zhīdào shuō shénme hǎo.","vi":"Vừa gặp bạn gái cũ, anh ấy liền lúng túng không biết nói gì."}],"related":[{"hanzi":"难堪","pinyin":"nánkān","vi":"khó xử"},{"hanzi":"窘迫","pinyin":"jiǒngpò","vi":"lúng túng"},{"hanzi":"不好意思","pinyin":"bùhǎoyìsi","vi":"ngại ngùng"},{"hanzi":"自然","pinyin":"zìrán","vi":"tự nhiên"}],"traditional":"尷尬"},{"id":"干戈","hanzi":"干戈","pinyin":"gāngē","meaning_vi":"chiến tranh, xung đột vũ trang","explanation":"干 (cái khiên) + 戈 (cái giáo). Cụm: 化干戈为玉帛.","hsk_level":6,"tags":["danh-tu","van-hoa"],"image":"⚔️","examples":[{"type":"basic","zh":"化干戈为玉帛。","pinyin":"Huà gāngē wéi yù bó.","vi":"Biến chiến tranh thành hòa bình."},{"type":"simple","zh":"这片土地上的百姓饱受干戈之苦。","pinyin":"Zhè piàn tǔdì shang de bǎixìng bǎoshòu gāngē zhī kǔ.","vi":"Người dân trên mảnh đất này đã chịu đủ khổ đau của chiến tranh."},{"type":"compound","zh":"与其大动干戈，不如坐下来好好谈一谈。","pinyin":"Yǔqí dà dòng gāngē, bùrú zuò xiàlái hǎohǎo tán yi tán.","vi":"Thay vì động binh đao, chi bằng ngồi xuống nói chuyện cho tử tế."}],"related":[{"hanzi":"战争","pinyin":"zhànzhēng","vi":"chiến tranh"},{"hanzi":"化干戈为玉帛","pinyin":"huà gāngē wéi yù bó","vi":"biến chiến tranh thành hòa bình"},{"hanzi":"大动干戈","pinyin":"dàdònggāngē","vi":"động binh đao"},{"hanzi":"和平","pinyin":"hépíng","vi":"hòa bình"}]},{"id":"干涸","hanzi":"干涸","pinyin":"gānhé","meaning_vi":"cạn kiệt (sông suối)","explanation":"干 (khô) + 涸 (cạn nước).","hsk_level":6,"tags":["dong-tu","thien-nhien"],"image":"🏜️","examples":[{"type":"basic","zh":"小河已经干涸了。","pinyin":"Xiǎohé yǐjīng gānhé le.","vi":"Con sông nhỏ đã cạn khô."},{"type":"simple","zh":"连续几个月的大旱使水库几乎干涸。","pinyin":"Liánxù jǐ gèyuè de dà hàn shǐ shuǐkù jīhū gānhé.","vi":"Hạn hán liên tục mấy tháng khiến hồ chứa gần như cạn kiệt."},{"type":"compound","zh":"如果继续过度抽取地下水，这片湖泊就会彻底干涸。","pinyin":"Rúguǒ jìxù guòdù chōuqǔ dìxiàshuǐ, zhè piàn húpō jiù huì chèdǐ gānhé.","vi":"Nếu tiếp tục khai thác nước ngầm quá mức thì hồ này sẽ cạn kiệt hoàn toàn."}],"related":[{"hanzi":"干枯","pinyin":"gānkū","vi":"khô cạn"},{"hanzi":"枯竭","pinyin":"kūjié","vi":"cạn kiệt"},{"hanzi":"干旱","pinyin":"gānhàn","vi":"hạn hán"},{"hanzi":"湿润","pinyin":"shīrùn","vi":"ẩm ướt"}],"traditional":"乾涸"},{"id":"干扰","hanzi":"干扰","pinyin":"gānrǎo","meaning_vi":"gây nhiễu, quấy rầy","explanation":"干 (can – can thiệp) + 扰 (nhiễu – quấy) → quấy rầy, làm ảnh hưởng; trong kỹ thuật là gây nhiễu sóng. Ví dụ: 干扰别人学习, 信号干扰.","hsk_level":6,"tags":["dong-tu"],"image":"📵","examples":[{"type":"basic","zh":"别干扰我学习。","pinyin":"Bié gānrǎo wǒ xuéxí.","vi":"Đừng làm phiền tôi học."},{"type":"simple","zh":"手机信号会干扰飞机的导航系统。","pinyin":"Shǒujī xìnhào huì gānrǎo fēijī de dǎoháng xìtǒng.","vi":"Tín hiệu điện thoại có thể gây nhiễu hệ thống dẫn đường của máy bay."},{"type":"compound","zh":"即使外面很吵，他也丝毫不受干扰，专心地看书。","pinyin":"Jíshǐ wàimiàn hěn chǎo, tā yě sī háobú shòu gānrǎo, zhuān xīnde kànshū.","vi":"Cho dù bên ngoài rất ồn, anh ấy cũng chẳng hề bị ảnh hưởng mà chăm chú đọc sách."}],"related":[{"hanzi":"打扰","pinyin":"dǎrǎo","vi":"làm phiền"},{"hanzi":"妨碍","pinyin":"fáng'ài","vi":"cản trở"},{"hanzi":"干预","pinyin":"gānyù","vi":"can thiệp"},{"hanzi":"信号干扰","pinyin":"xìnhàogānrǎo","vi":"nhiễu tín hiệu"}],"traditional":"干擾"},{"id":"甘心情愿","hanzi":"甘心情愿","pinyin":"gānxīn-qíngyuàn","meaning_vi":"cam tâm tình nguyện","explanation":"甘心 (cam tâm – bằng lòng) + 情愿 (tình nguyện – tự nguyện) → hoàn toàn tự nguyện, vui lòng làm không chút miễn cưỡng. Đồng nghĩa: 心甘情愿.","hsk_level":6,"tags":["thanh-ngu"],"image":"💖","examples":[{"type":"basic","zh":"我甘心情愿等你。","pinyin":"Wǒ gānxīnqíngyuàn děng nǐ.","vi":"Anh cam tâm tình nguyện đợi em."},{"type":"simple","zh":"她甘心情愿留在山村当一名老师。","pinyin":"Tā gānxīnqíngyuàn liú zài shāncūn dāng yì míng lǎoshī.","vi":"Cô ấy cam tâm tình nguyện ở lại làng núi làm giáo viên."},{"type":"compound","zh":"只要能让孩子上好学校，父母就甘心情愿吃再多的苦。","pinyin":"Zhǐyào néng ràng háizi shànghǎo xuéxiào, fùmǔ jiù gānxīnqíngyuàn chī zài duō de kǔ.","vi":"Chỉ cần con được học trường tốt, cha mẹ cam tâm tình nguyện chịu bao nhiêu vất vả cũng được."}],"related":[{"hanzi":"心甘情愿","pinyin":"xīngānqíngyuàn","vi":"cam tâm tình nguyện"},{"hanzi":"自愿","pinyin":"zìyuàn","vi":"tự nguyện"},{"hanzi":"情愿","pinyin":"qíngyuàn","vi":"bằng lòng"},{"hanzi":"被迫","pinyin":"bèipò","vi":"bị ép buộc"}],"traditional":"甘心情願"},{"id":"刚强","hanzi":"刚强","pinyin":"gāngqiáng","meaning_vi":"cương cường, kiên cường","explanation":"刚 (cứng rắn) + 强 (mạnh).","hsk_level":6,"tags":["tinh-tu","con-nguoi"],"image":"💪","examples":[{"type":"basic","zh":"她性格很刚强。","pinyin":"Tā xìnggé hěn gāngqiáng.","vi":"Cô ấy có tính cách rất kiên cường."},{"type":"simple","zh":"刚强的母亲从没在孩子面前掉过眼泪。","pinyin":"Gāngqiáng de mǔqīn cóng méi zài háizi miànqián diàoguo yǎnlèi.","vi":"Người mẹ kiên cường chưa từng rơi nước mắt trước mặt con."},{"type":"compound","zh":"虽然他外表看起来很刚强，但是内心其实非常柔软。","pinyin":"Suīrán tā wàibiǎo kànqǐlái hěn gāngqiáng, dànshì nèixīn qíshí fēicháng róuruǎn.","vi":"Tuy bề ngoài anh ấy trông rất cứng cỏi nhưng nội tâm thực ra rất mềm yếu."}],"related":[{"hanzi":"坚强","pinyin":"jiānqiáng","vi":"kiên cường"},{"hanzi":"刚毅","pinyin":"gāngyì","vi":"cương nghị"},{"hanzi":"软弱","pinyin":"ruǎnruò","vi":"yếu đuối"},{"hanzi":"顽强","pinyin":"wánqiáng","vi":"ngoan cường"}],"traditional":"剛強"},{"id":"纲要","hanzi":"纲要","pinyin":"gāngyào","meaning_vi":"đề cương, cương yếu","explanation":"纲 (mạng chính) + 要 (điểm chính).","hsk_level":6,"tags":["danh-tu","hoc-tap"],"image":"📋","examples":[{"type":"basic","zh":"请先写一份纲要。","pinyin":"Qǐng xiān xiě yí fèn gāngyào.","vi":"Hãy viết một bản đề cương trước."},{"type":"simple","zh":"教育部发布了新的课程改革纲要。","pinyin":"Jiàoyùbù fābùle xīn de kèchéng gǎigé gāngyào.","vi":"Bộ Giáo dục đã ban hành cương yếu cải cách chương trình học mới."},{"type":"compound","zh":"如果事先列好纲要，写论文时就不会思路混乱。","pinyin":"Rúguǒ shìxiān liè hǎo gāngyào, xiě lùnwén shí jiù bú huì sīlù hùnluàn.","vi":"Nếu lập đề cương trước thì khi viết luận văn sẽ không bị rối ý."}],"related":[{"hanzi":"提纲","pinyin":"tígāng","vi":"đề cương"},{"hanzi":"大纲","pinyin":"dàgāng","vi":"đại cương"},{"hanzi":"要点","pinyin":"yàodiǎn","vi":"điểm chính"},{"hanzi":"概要","pinyin":"gàiyào","vi":"khái yếu"}],"traditional":"綱要"},{"id":"刚毅","hanzi":"刚毅","pinyin":"gāngyì","meaning_vi":"cương nghị, kiên quyết","explanation":"刚 + 毅 (kiên định).","hsk_level":6,"tags":["tinh-tu"],"image":"🦁","examples":[{"type":"basic","zh":"他的眼神很刚毅。","pinyin":"Tā de yǎnshén hěn gāngyì.","vi":"Ánh mắt của anh ấy rất cương nghị."},{"type":"simple","zh":"这位老将军有一张刚毅的脸。","pinyin":"Zhè wèi lǎo jiāngjūn yǒu yì zhāng gāngyì de liǎn.","vi":"Vị lão tướng này có khuôn mặt cương nghị."},{"type":"compound","zh":"正因为他性格刚毅，所以在困难面前从不退缩。","pinyin":"Zhèng yīnwèi tā xìnggé gāngyì, suǒyǐ zài kùnnan miànqián cóng bú tuìsuō.","vi":"Chính vì tính cách cương nghị nên anh ấy chưa bao giờ lùi bước trước khó khăn."}],"related":[{"hanzi":"刚强","pinyin":"gāngqiáng","vi":"cương cường"},{"hanzi":"坚毅","pinyin":"jiānyì","vi":"kiên nghị"},{"hanzi":"果断","pinyin":"guǒduàn","vi":"quả quyết"},{"hanzi":"懦弱","pinyin":"nuòruò","vi":"nhu nhược"}],"traditional":"剛毅"},{"id":"刚正不阿","hanzi":"刚正不阿","pinyin":"gāngzhèng-bù'ē","meaning_vi":"cương trực ngay thẳng không nịnh hót","explanation":"刚正 (cương chính – cứng cỏi ngay thẳng) + 不阿 (bất a – không a dua, nịnh bợ) → cương trực ngay thẳng, không xu nịnh kẻ có quyền.","hsk_level":6,"tags":["thanh-ngu"],"image":"⚖️","examples":[{"type":"basic","zh":"包公刚正不阿。","pinyin":"Bāogōng gāngzhèngbù'ē.","vi":"Bao Công cương trực không a dua."},{"type":"simple","zh":"这位法官以刚正不阿而闻名全国。","pinyin":"Zhè wèi fǎguān yǐ gāngzhèngbù'ē ér wénmíng quánguó.","vi":"Vị thẩm phán này nổi tiếng khắp cả nước vì cương trực ngay thẳng."},{"type":"compound","zh":"即使面对权贵的威胁，他也始终刚正不阿。","pinyin":"Jíshǐ miànduì quánguì de wēixié, tā yě shǐzhōng gāngzhèngbù'ē.","vi":"Cho dù đối mặt với sự đe dọa của kẻ quyền quý, ông ấy vẫn luôn cương trực ngay thẳng."}],"related":[{"hanzi":"正直","pinyin":"zhèngzhí","vi":"chính trực"},{"hanzi":"铁面无私","pinyin":"tiěmiànwúsī","vi":"chí công vô tư"},{"hanzi":"阿谀奉承","pinyin":"ēyúfèngcheng","vi":"a dua nịnh hót"},{"hanzi":"公正","pinyin":"gōngzhèng","vi":"công bằng"}],"traditional":"剛正不阿"},{"id":"高不可攀","hanzi":"高不可攀","pinyin":"gāobù-kěpān","meaning_vi":"cao không thể với tới","explanation":"高 (cao) + 不可攀 (bất khả phan – không thể leo tới) → cao đến mức không với tới được; ví mục tiêu quá khó đạt, hoặc người quá xa cách khó gần.","hsk_level":6,"tags":["thanh-ngu"],"image":"🏔️","examples":[{"type":"basic","zh":"房价高不可攀。","pinyin":"Fángjià gāobùkěpān.","vi":"Giá nhà cao ngoài tầm với."},{"type":"simple","zh":"在很多人眼里，名牌大学似乎高不可攀。","pinyin":"Zài hěn duō rén yǎn li, míngpái dàxué sìhū gāobùkěpān.","vi":"Trong mắt nhiều người, trường đại học danh tiếng dường như cao không thể với tới."},{"type":"compound","zh":"那座雪峰虽然看起来高不可攀，但是去年已经有人登顶了。","pinyin":"Nà zuò xuěfēng suīrán kànqǐlái gāobùkěpān, dànshì qùnián yǐjīng yǒurén dēngdǐng le.","vi":"Ngọn núi tuyết đó tuy trông có vẻ cao không thể với tới nhưng năm ngoái đã có người lên tới đỉnh."}],"related":[{"hanzi":"遥不可及","pinyin":"yáobùkějí","vi":"xa không với tới"},{"hanzi":"望尘莫及","pinyin":"wàngchénmòjí","vi":"không theo kịp"},{"hanzi":"平易近人","pinyin":"píngyìjìnrén","vi":"dễ gần gũi"},{"hanzi":"高攀","pinyin":"gāopān","vi":"trèo cao"}]},{"id":"高潮","hanzi":"高潮","pinyin":"gāocháo","meaning_vi":"cao trào, đỉnh điểm","explanation":"高 (cao) + 潮 (triều – nước triều) → lúc thủy triều lên cao nhất; nghĩa bóng: đỉnh điểm, cao trào của sự việc, câu chuyện. Ví dụ: 故事的高潮, 掀起高潮.","hsk_level":6,"tags":["danh-tu"],"image":"🌊","examples":[{"type":"basic","zh":"晚会进入了高潮。","pinyin":"Wǎnhuì jìnrùle gāocháo.","vi":"Buổi dạ hội đã bước vào cao trào."},{"type":"simple","zh":"电影的高潮部分让观众都屏住了呼吸。","pinyin":"Diànyǐng de gāocháo bùfen ràng guānzhòng dōu bǐng zhùle hūxī.","vi":"Phần cao trào của bộ phim khiến khán giả đều nín thở."},{"type":"compound","zh":"歌手一唱起这首成名曲，演唱会就达到了高潮。","pinyin":"Gēshǒu yí chàng qǐ zhè shǒu chéng míngqǔ, yǎnchànghuì jiù dádàole gāocháo.","vi":"Ca sĩ vừa cất lên bài hát làm nên tên tuổi, buổi hòa nhạc liền lên đến cao trào."}],"related":[{"hanzi":"低潮","pinyin":"dīcháo","vi":"thoái trào"},{"hanzi":"高峰","pinyin":"gāofēng","vi":"đỉnh cao"},{"hanzi":"顶点","pinyin":"dǐngdiǎn","vi":"đỉnh điểm"},{"hanzi":"情节","pinyin":"qíngjié","vi":"tình tiết"}]},{"id":"高明","hanzi":"高明","pinyin":"gāomíng","meaning_vi":"cao minh, sáng suốt","explanation":"高 (cao – cao) + 明 (minh – sáng) → cao minh, sáng suốt, giỏi hơn người. Hay dùng: 高明的办法, 医术高明; 另请高明 = mời người giỏi hơn.","hsk_level":6,"tags":["tinh-tu"],"image":"💡","examples":[{"type":"basic","zh":"这一招真高明！","pinyin":"Zhè yì zhāo zhēn gāomíng!","vi":"Chiêu này thật cao tay!"},{"type":"simple","zh":"他找到了一位医术高明的外科大夫。","pinyin":"Tā zhǎodàole yí wèi yīshù gāomíng de wàikē dàifu.","vi":"Anh ấy đã tìm được một bác sĩ ngoại khoa tay nghề cao."},{"type":"compound","zh":"既然你有更高明的办法，那就说出来让大家听听。","pinyin":"Jìrán nǐ yǒu gèng gāomíng de bànfǎ, nà jiù shuō chūlái ràng dàjiā tīng ting.","vi":"Nếu bạn có cách cao minh hơn thì hãy nói ra cho mọi người nghe thử."}],"related":[{"hanzi":"高超","pinyin":"gāochāo","vi":"cao siêu"},{"hanzi":"精明","pinyin":"jīngmíng","vi":"tinh khôn"},{"hanzi":"另请高明","pinyin":"lìngqǐnggāomíng","vi":"mời người giỏi hơn"},{"hanzi":"拙劣","pinyin":"zhuōliè","vi":"vụng về"}]},{"id":"睾丸","hanzi":"睾丸","pinyin":"gāowán","meaning_vi":"tinh hoàn","explanation":"Giải phẫu học.","hsk_level":6,"tags":["danh-tu","co-the","suc-khoe"],"image":"🩺","examples":[{"type":"basic","zh":"医生检查了他的睾丸。","pinyin":"Yīshēng jiǎnchále tā de gāowán.","vi":"Bác sĩ đã kiểm tra tinh hoàn của anh ấy."},{"type":"simple","zh":"睾丸是男性重要的生殖器官。","pinyin":"Gāowán shì nánxìng zhòngyào de shēngzhí qìguān.","vi":"Tinh hoàn là cơ quan sinh dục quan trọng của nam giới."},{"type":"compound","zh":"如果睾丸出现肿痛，就应该尽快去泌尿科就诊。","pinyin":"Rúguǒ gāowán chūxiàn zhǒng tòng, jiù yīnggāi jǐnkuài qù mìniào kē jiùzhěn.","vi":"Nếu tinh hoàn bị sưng đau thì nên nhanh chóng đến khoa tiết niệu khám."}],"related":[{"hanzi":"生殖器","pinyin":"shēngzhíqì","vi":"cơ quan sinh dục"},{"hanzi":"卵巢","pinyin":"luǎncháo","vi":"buồng trứng"},{"hanzi":"精子","pinyin":"jīngzǐ","vi":"tinh trùng"},{"hanzi":"男性","pinyin":"nánxìng","vi":"nam giới"}],"traditional":"睪丸"},{"id":"膏药","hanzi":"膏药","pinyin":"gāoyao","meaning_vi":"cao dán (chữa đau nhức)","explanation":"膏 (cao – chất sệt, thuốc cao) + 药 (dược – thuốc) → miếng thuốc cao dán lên da để trị đau nhức. Cụm: 贴膏药.","hsk_level":6,"tags":["danh-tu","suc-khoe","do-vat"],"image":"🩹","examples":[{"type":"basic","zh":"他腰上贴着膏药。","pinyin":"Tā yāo shang tiēzhe gāoyao.","vi":"Trên lưng anh ấy đang dán miếng cao."},{"type":"simple","zh":"奶奶膝盖疼的时候总贴一张膏药。","pinyin":"Nǎinai xīgài téng de shíhou zǒng tiē yì zhāng gāoyao.","vi":"Mỗi khi đau đầu gối bà lại dán một miếng cao."},{"type":"compound","zh":"这种膏药虽然能止痛，但是不能根治关节炎。","pinyin":"Zhè zhǒng gāoyao suīrán néng zhǐtòng, dànshì bù néng gēnzhì guānjiéyán.","vi":"Loại cao dán này tuy giảm đau được nhưng không chữa tận gốc bệnh viêm khớp."}],"related":[{"hanzi":"药膏","pinyin":"yàogāo","vi":"thuốc mỡ"},{"hanzi":"创可贴","pinyin":"chuàngkětiē","vi":"băng dán cá nhân"},{"hanzi":"贴","pinyin":"tiē","vi":"dán"},{"hanzi":"中药","pinyin":"zhōngyào","vi":"thuốc bắc"}],"traditional":"膏藥"},{"id":"高瞻远瞩","hanzi":"高瞻远瞩","pinyin":"gāozhān-yuǎnzhǔ","meaning_vi":"nhìn xa trông rộng","explanation":"高瞻 (nhìn cao) + 远瞩 (trông xa). Thành ngữ.","hsk_level":6,"tags":["thanh-ngu"],"image":"🔭","examples":[{"type":"basic","zh":"他是个高瞻远瞩的领袖。","pinyin":"Tā shì gè gāozhānyuǎnzhǔ de lǐngxiù.","vi":"Ông ấy là một nhà lãnh đạo nhìn xa trông rộng."},{"type":"simple","zh":"正是这项高瞻远瞩的决策让城市免于水灾。","pinyin":"Zhèngshì zhè xiàng gāozhānyuǎnzhǔ de juécè ràng chéngshì miǎnyú shuǐzāi.","vi":"Chính quyết sách nhìn xa trông rộng này đã giúp thành phố tránh khỏi lũ lụt."},{"type":"compound","zh":"如果当年没有他高瞻远瞩地投资教育，这个小镇就不会有今天的繁荣。","pinyin":"Rúguǒ dāngnián méiyǒu tā gāozhānyuǎnzhǔ de tóuzī jiàoyù, zhè ge xiǎozhèn jiù bú huì yǒu jīntiān de fánróng.","vi":"Nếu năm đó không có ông nhìn xa trông rộng đầu tư cho giáo dục thì thị trấn nhỏ này đã không có sự phồn vinh như hôm nay."}],"related":[{"hanzi":"深谋远虑","pinyin":"shēnmóuyuǎnlǜ","vi":"tính sâu lo xa"},{"hanzi":"远见","pinyin":"yuǎnjiàn","vi":"tầm nhìn xa"},{"hanzi":"目光短浅","pinyin":"mùguāngduǎnqiǎn","vi":"tầm nhìn hạn hẹp"},{"hanzi":"有远见","pinyin":"yǒuyuǎnjiàn","vi":"có tầm nhìn"}],"traditional":"高瞻遠矚"},{"id":"高枕无忧","hanzi":"高枕无忧","pinyin":"gāozhěn-wúyōu","meaning_vi":"kê cao gối mà ngủ, yên tâm không phải lo nghĩ gì","explanation":"高枕无忧: kê cao gối ngủ, không lo gì → yên tâm tuyệt đối; thường dùng phủ định để nhắc đừng chủ quan: 不能高枕无忧.","hsk_level":6,"tags":["thanh-ngu"],"image":"🛏️","examples":[{"type":"basic","zh":"别以为可以高枕无忧。","pinyin":"Bié yǐwéi kěyǐ gāozhěnwúyōu.","vi":"Đừng tưởng có thể kê cao gối mà ngủ yên."},{"type":"simple","zh":"签下这份大合同后老板终于高枕无忧了。","pinyin":"Qiān xià zhè fèn dà hétong hòu lǎobǎn zhōngyú gāozhěnwúyōu le.","vi":"Sau khi ký được hợp đồng lớn này, ông chủ cuối cùng cũng yên tâm không còn lo nghĩ."},{"type":"compound","zh":"即使拿到了冠军，球队也不能从此高枕无忧。","pinyin":"Jíshǐ nádàole guànjūn, qiúduì yě bù néng cóngcǐ gāozhěnwúyōu.","vi":"Cho dù giành chức vô địch, đội bóng cũng không thể từ đó mà kê cao gối ngủ yên."}],"related":[{"hanzi":"无忧无虑","pinyin":"wúyōuwúlǜ","vi":"vô lo vô nghĩ"},{"hanzi":"麻痹大意","pinyin":"mábìdàyì","vi":"chủ quan lơ là"},{"hanzi":"居安思危","pinyin":"jū'ānsīwēi","vi":"sống yên nghĩ đến lúc nguy"},{"hanzi":"安枕","pinyin":"ānzhěn","vi":"ngủ yên"}],"traditional":"高枕無憂"},{"id":"搁","hanzi":"搁","pinyin":"gē","meaning_vi":"đặt, để, gác lại","explanation":"搁 (các – gác, đặt): đặt, để vào chỗ nào; gác lại, hoãn lại. Thường gặp: 搁在桌上, 搁置 (gác lại), 耽搁 (chậm trễ).","hsk_level":6,"tags":["dong-tu"],"image":"📥","examples":[{"type":"basic","zh":"把书搁在桌上吧。","pinyin":"Bǎ shū gē zài zhuō shang ba.","vi":"Cứ để sách lên bàn đi."},{"type":"simple","zh":"这个计划因为资金问题暂时搁下了。","pinyin":"Zhè ge jìhuà yīnwèi zījīn wèntí zànshí gē xià le.","vi":"Kế hoạch này tạm thời bị gác lại vì vấn đề kinh phí."},{"type":"compound","zh":"如果汤里再搁点儿盐，味道就更好了。","pinyin":"Rúguǒ tāng li zài gē diǎnr yán, wèidào jiù gèng hǎo le.","vi":"Nếu cho thêm chút muối vào canh thì vị sẽ ngon hơn."}],"related":[{"hanzi":"放","pinyin":"fàng","vi":"đặt, để"},{"hanzi":"搁置","pinyin":"gēzhì","vi":"gác lại"},{"hanzi":"耽搁","pinyin":"dānge","vi":"trì hoãn"},{"hanzi":"搁浅","pinyin":"gēqiǎn","vi":"mắc cạn, bế tắc"}],"traditional":"擱"},{"id":"疙瘩","hanzi":"疙瘩","pinyin":"gēda","meaning_vi":"mụn nhọt, cục u, khúc mắc trong lòng","explanation":"Ví dụ: 心里解不开的疙瘩.","hsk_level":6,"tags":["danh-tu","co-the"],"image":"🩹","examples":[{"type":"basic","zh":"他额头上起了个疙瘩。","pinyin":"Tā é tóushang qǐle gè gēda.","vi":"Trên trán anh ấy nổi một cục u."},{"type":"simple","zh":"两人心里的疙瘩终于解开了。","pinyin":"Liǎng rén xīnli de gēda zhōngyú jiěkāi le.","vi":"Khúc mắc trong lòng hai người cuối cùng đã được tháo gỡ."},{"type":"compound","zh":"一看到毛毛虫，她浑身就起鸡皮疙瘩。","pinyin":"Yí kàndào máomaochóng, tā húnshēn jiù qǐ jī pí gēda.","vi":"Vừa nhìn thấy sâu róm, cô ấy liền nổi da gà khắp người."}],"related":[{"hanzi":"心结","pinyin":"xīnjié","vi":"nút thắt trong lòng"},{"hanzi":"肿块","pinyin":"zhǒngkuài","vi":"khối u sưng"},{"hanzi":"解开","pinyin":"jiěkāi","vi":"cởi bỏ"},{"hanzi":"鸡皮疙瘩","pinyin":"jīpígēda","vi":"nổi da gà"}]},{"id":"歌功颂德","hanzi":"歌功颂德","pinyin":"gēgōng-sòngdé","meaning_vi":"ca công tụng đức, tâng bốc","explanation":"歌功颂德: ca (歌) công lao, tụng (颂) đức độ → ca ngợi công đức người có quyền; thường mang nghĩa xấu: tâng bốc, nịnh bợ.","hsk_level":6,"tags":["thanh-ngu"],"image":"👏","examples":[{"type":"basic","zh":"这篇文章通篇歌功颂德。","pinyin":"Zhè piān wénzhāng tōng piān gēgōngsòngdé.","vi":"Bài viết này từ đầu đến cuối toàn ca công tụng đức."},{"type":"simple","zh":"老板身边总围着几个歌功颂德的下属。","pinyin":"Lǎobǎn shēnbiān zǒng wéizhe jǐ gè gēgōngsòngdé de xiàshǔ.","vi":"Bên cạnh sếp lúc nào cũng có vài cấp dưới chuyên tâng bốc."},{"type":"compound","zh":"如果媒体只会歌功颂德，老百姓就听不到真实的声音。","pinyin":"Rúguǒ méitǐ zhǐ huì gēgōngsòngdé, lǎobǎixìng jiù tīngbudào zhēnshí de shēngyīn.","vi":"Nếu truyền thông chỉ biết ca công tụng đức thì người dân sẽ không nghe được tiếng nói chân thực."}],"related":[{"hanzi":"阿谀奉承","pinyin":"ēyúfèngcheng","vi":"a dua nịnh hót"},{"hanzi":"吹捧","pinyin":"chuīpěng","vi":"tâng bốc"},{"hanzi":"赞美","pinyin":"zànměi","vi":"ca ngợi"},{"hanzi":"拍马屁","pinyin":"pāimǎpì","vi":"nịnh bợ"}],"traditional":"歌功頌德"},{"id":"歌咏","hanzi":"歌咏","pinyin":"gēyǒng","meaning_vi":"ca hát, ngâm vịnh","explanation":"歌 (hát) + 咏 (ngâm thơ).","hsk_level":6,"tags":["dong-tu","van-hoa"],"image":"🎶","examples":[{"type":"basic","zh":"学校举办歌咏比赛。","pinyin":"Xuéxiào jǔbàn gēyǒng bǐsài.","vi":"Trường tổ chức cuộc thi hát."},{"type":"simple","zh":"古代诗人常常歌咏江南的春天。","pinyin":"Gǔdài shīrén chángcháng gēyǒng Jiāngnán de chūntiān.","vi":"Thi nhân xưa thường ngâm vịnh mùa xuân Giang Nam."},{"type":"compound","zh":"为了准备国庆歌咏会，全班同学一下课就去音乐教室排练。","pinyin":"Wèile zhǔnbèi Guóqìng gēyǒng huì, quánbān tóngxué yí xiàkè jiù qù yīnyuè jiàoshì páiliàn.","vi":"Để chuẩn bị cho buổi hội hát mừng Quốc khánh, cả lớp hễ tan học là đến phòng âm nhạc tập luyện."}],"related":[{"hanzi":"歌唱","pinyin":"gēchàng","vi":"ca hát"},{"hanzi":"吟诵","pinyin":"yínsòng","vi":"ngâm tụng"},{"hanzi":"合唱","pinyin":"héchàng","vi":"hợp xướng"},{"hanzi":"歌咏比赛","pinyin":"gēyǒngbǐsài","vi":"cuộc thi hát"}],"traditional":"歌詠"},{"id":"跟前","hanzi":"跟前","pinyin":"gēnqián","meaning_vi":"trước mặt, bên cạnh","explanation":"跟 (cân – gót, theo) + 前 (tiền – trước) → ngay trước mặt, sát bên cạnh. Ví dụ: 走到他跟前; 父母跟前 = bên cạnh cha mẹ.","hsk_level":6,"tags":["danh-tu","phuong-huong"],"image":"📍","examples":[{"type":"basic","zh":"他走到我跟前。","pinyin":"Tā zǒu dào wǒ gēnqián.","vi":"Anh ấy đi đến trước mặt tôi."},{"type":"simple","zh":"小狗一直乖乖地趴在主人跟前。","pinyin":"Xiǎogǒu yìzhí guāiguāi de pā zài zhǔrén gēnqián.","vi":"Chú chó nhỏ cứ ngoan ngoãn nằm bên cạnh chủ."},{"type":"compound","zh":"虽然儿女都不在跟前，但是老两口的日子过得很开心。","pinyin":"Suīrán érnǚ dōu bú zài gēnqián, dànshì lǎoliǎngkǒu de rìzi guòde hěn kāixīn.","vi":"Tuy con cái đều không ở bên cạnh nhưng hai ông bà già sống rất vui vẻ."}],"related":[{"hanzi":"面前","pinyin":"miànqián","vi":"trước mặt"},{"hanzi":"身边","pinyin":"shēnbiān","vi":"bên cạnh"},{"hanzi":"眼前","pinyin":"yǎnqián","vi":"trước mắt"},{"hanzi":"附近","pinyin":"fùjìn","vi":"gần đó"}]},{"id":"根深蒂固","hanzi":"根深蒂固","pinyin":"gēnshēn-dìgù","meaning_vi":"thâm căn cố đế, ăn sâu bám rễ","explanation":"根深 (rễ sâu) + 蒂固 (cuống chắc). Thành ngữ.","hsk_level":6,"tags":["thanh-ngu"],"image":"🌳","examples":[{"type":"basic","zh":"这种观念根深蒂固。","pinyin":"Zhè zhǒng guānniàn gēnshēndìgù.","vi":"Quan niệm này đã ăn sâu bám rễ."},{"type":"simple","zh":"重男轻女的思想在一些农村仍然根深蒂固。","pinyin":"Zhòng nán qīng nǚ de sīxiǎng zài yìxiē nóngcūn réngrán gēnshēndìgù.","vi":"Tư tưởng trọng nam khinh nữ ở một số vùng nông thôn vẫn còn ăn sâu bám rễ."},{"type":"compound","zh":"因为偏见根深蒂固，所以改变它需要几代人的努力。","pinyin":"Yīnwèi piānjiàn gēnshēndìgù, suǒyǐ gǎibiàn tā xūyào jǐdàirén de nǔlì.","vi":"Vì định kiến đã ăn sâu bám rễ nên muốn thay đổi nó cần nỗ lực của mấy thế hệ."}],"related":[{"hanzi":"积重难返","pinyin":"jīzhòngnánfǎn","vi":"thói quen khó sửa"},{"hanzi":"根深叶茂","pinyin":"gēnshēnyèmào","vi":"gốc sâu lá tốt"},{"hanzi":"牢固","pinyin":"láogù","vi":"vững chắc"},{"hanzi":"动摇","pinyin":"dòngyáo","vi":"lung lay"}]},{"id":"根深叶茂","hanzi":"根深叶茂","pinyin":"gēnshēn-yèmào","meaning_vi":"gốc rễ vững chắc cành lá sum suê","explanation":"根深叶茂: rễ sâu thì lá tốt → nền móng vững chắc nên phát triển thịnh vượng; hay dùng cho gia tộc, doanh nghiệp, sự nghiệp.","hsk_level":6,"tags":["thanh-ngu"],"image":"🌳","examples":[{"type":"basic","zh":"这棵老榕树根深叶茂。","pinyin":"Zhè kē lǎo róngshù gēnshēnyèmào.","vi":"Cây đa già này rễ sâu lá tốt."},{"type":"simple","zh":"这个家族企业经过百年发展已经根深叶茂。","pinyin":"Zhè ge jiāzú qǐyè jīngguò bǎinián fāzhǎn yǐjīng gēnshēnyèmào.","vi":"Doanh nghiệp gia đình này qua trăm năm phát triển đã vững gốc tốt cành."},{"type":"compound","zh":"只有基础打得牢，事业才能根深叶茂。","pinyin":"Zhǐyǒu jīchǔ dǎ de láo, shìyè cáinéng gēnshēnyèmào.","vi":"Chỉ khi nền móng vững chắc, sự nghiệp mới có thể phát triển sum suê."}],"related":[{"hanzi":"根深蒂固","pinyin":"gēnshēndìgù","vi":"thâm căn cố đế"},{"hanzi":"枝繁叶茂","pinyin":"zhīfányèmào","vi":"cành lá sum suê"},{"hanzi":"繁荣","pinyin":"fánróng","vi":"phồn thịnh"},{"hanzi":"根基","pinyin":"gēnjī","vi":"nền móng"}],"traditional":"根深葉茂"},{"id":"根源","hanzi":"根源","pinyin":"gēnyuán","meaning_vi":"căn nguyên, nguồn gốc sâu xa","explanation":"根 (gốc rễ) + 源 (nguồn).","hsk_level":6,"tags":["danh-tu"],"image":"🌱","examples":[{"type":"basic","zh":"贫穷是犯罪的根源之一。","pinyin":"Pínqióng shì fànzuì de gēnyuán zhīyī.","vi":"Nghèo đói là một trong những căn nguyên của tội phạm."},{"type":"simple","zh":"专家们正在调查这次事故的根源。","pinyin":"Zhuānjiāmen zhèngzài diàochá zhè cì shìgù de gēnyuán.","vi":"Các chuyên gia đang điều tra căn nguyên của vụ tai nạn này."},{"type":"compound","zh":"如果不找到问题的根源，同样的错误就会一再发生。","pinyin":"Rúguǒ bù zhǎodào wèntí de gēnyuán, tóngyàng de cuòwù jiù huì yízài fāshēng.","vi":"Nếu không tìm ra căn nguyên của vấn đề thì sai lầm tương tự sẽ lặp đi lặp lại."}],"related":[{"hanzi":"来源","pinyin":"láiyuán","vi":"nguồn gốc"},{"hanzi":"根本","pinyin":"gēnběn","vi":"căn bản"},{"hanzi":"起源","pinyin":"qǐyuán","vi":"khởi nguồn"},{"hanzi":"原因","pinyin":"yuányīn","vi":"nguyên nhân"}]},{"id":"耕地","hanzi":"耕地","pinyin":"gēngdì","meaning_vi":"đất canh tác; cày ruộng","explanation":"耕 (canh – cày) + 地 (địa – đất) → đất canh tác, đất trồng trọt; làm động từ nghĩa là cày ruộng. Ví dụ: 保护耕地, 耕地面积.","hsk_level":6,"tags":["danh-tu","thien-nhien"],"image":"🚜","examples":[{"type":"basic","zh":"农民正在耕地。","pinyin":"Nóngmín zhèngzài gēngdì.","vi":"Nông dân đang cày ruộng."},{"type":"simple","zh":"城市扩张占用了大量宝贵的耕地。","pinyin":"Chéngshì kuòzhāng zhànyòngle dàliàng bǎoguì de gēngdì.","vi":"Sự mở rộng đô thị đã chiếm dụng một lượng lớn đất canh tác quý giá."},{"type":"compound","zh":"虽然这个国家人口众多，但是耕地面积却十分有限。","pinyin":"Suīrán zhè ge guójiā rénkǒu zhòngduō, dànshì gēngdì miànjī què shífēn yǒuxiàn.","vi":"Tuy đất nước này dân số đông nhưng diện tích đất canh tác lại rất hạn chế."}],"related":[{"hanzi":"耕种","pinyin":"gēngzhòng","vi":"cày cấy"},{"hanzi":"农田","pinyin":"nóngtián","vi":"ruộng đồng"},{"hanzi":"土地","pinyin":"tǔdì","vi":"đất đai"},{"hanzi":"犁","pinyin":"lí","vi":"cái cày"}]},{"id":"更正","hanzi":"更正","pinyin":"gēngzhèng","meaning_vi":"đính chính, sửa lại cho đúng","explanation":"更 (đọc gēng - đổi) + 正 (đúng).","hsk_level":6,"tags":["dong-tu"],"image":"✍️","examples":[{"type":"basic","zh":"我要更正一个错误。","pinyin":"Wǒ yào gēngzhèng yí gè cuòwù.","vi":"Tôi muốn đính chính một lỗi."},{"type":"simple","zh":"报社第二天就在头版刊登了更正声明。","pinyin":"Bàoshè dì'èrtiān jiù zài tóubǎn kāndēngle gēngzhèng shēngmíng.","vi":"Tòa soạn ngay ngày hôm sau đã đăng lời đính chính trên trang nhất."},{"type":"compound","zh":"如果发现信息有误，请及时联系我们进行更正。","pinyin":"Rúguǒ fāxiàn xìnxī yǒu wù, qǐng jíshí liánxì wǒmen jìnxíng gēngzhèng.","vi":"Nếu phát hiện thông tin có sai sót, xin vui lòng liên hệ kịp thời với chúng tôi để đính chính."}],"related":[{"hanzi":"改正","pinyin":"gǎizhèng","vi":"sửa chữa"},{"hanzi":"纠正","pinyin":"jiūzhèng","vi":"uốn nắn, sửa sai"},{"hanzi":"修正","pinyin":"xiūzhèng","vi":"chỉnh sửa"},{"hanzi":"错误","pinyin":"cuòwù","vi":"sai sót"}]},{"id":"功不可没","hanzi":"功不可没","pinyin":"gōngbù-kěmò","meaning_vi":"công lao không thể phủ nhận","explanation":"功 + 不可没 (không thể vùi lấp). Thành ngữ.","hsk_level":6,"tags":["thanh-ngu"],"image":"🏅","examples":[{"type":"basic","zh":"教练功不可没。","pinyin":"Jiàoliàn gōngbùkěmò.","vi":"Công lao của huấn luyện viên không thể phủ nhận."},{"type":"simple","zh":"在这次救灾中，志愿者们功不可没。","pinyin":"Zài zhè cì jiùzāi zhōng, zhìyuànzhěmen gōngbùkěmò.","vi":"Trong đợt cứu trợ thiên tai lần này, các tình nguyện viên có công lao không thể phủ nhận."},{"type":"compound","zh":"公司能扭亏为盈，虽然靠的是大家，但是新经理更是功不可没。","pinyin":"Gōngsī néng niǔkuī wéi yíng, suīrán kào de shì dàjiā, dànshì xīn jīnglǐ gèng shì gōngbùkěmò.","vi":"Công ty có thể chuyển lỗ thành lãi, tuy là nhờ mọi người nhưng giám đốc mới càng có công lao không thể phủ nhận."}],"related":[{"hanzi":"功劳","pinyin":"gōngláo","vi":"công lao"},{"hanzi":"贡献","pinyin":"gòngxiàn","vi":"cống hiến"},{"hanzi":"功绩","pinyin":"gōngjì","vi":"công tích"},{"hanzi":"劳苦功高","pinyin":"láokǔgōnggāo","vi":"công lao to lớn"}],"traditional":"功不可沒"},{"id":"供不应求","hanzi":"供不应求","pinyin":"gōngbú-yìngqiú","meaning_vi":"cung không đủ cầu","explanation":"供不应求: cung (供) không đáp ứng (应) được cầu (求) → hàng hóa thiếu, cung không đủ cầu. Trái nghĩa: 供过于求.","hsk_level":6,"tags":["thanh-ngu"],"image":"📈","examples":[{"type":"basic","zh":"这款手机供不应求。","pinyin":"Zhè kuǎn shǒujī gōngbúyìngqiú.","vi":"Mẫu điện thoại này cung không đủ cầu."},{"type":"simple","zh":"春节前火车票总是供不应求。","pinyin":"Chūnjié qián huǒchēpiào zǒngshì gōngbúyìngqiú.","vi":"Trước Tết vé tàu luôn cung không đủ cầu."},{"type":"compound","zh":"因为口碑特别好，所以这家店的月饼一直供不应求。","pinyin":"Yīnwèi kǒubēi tèbié hǎo, suǒyǐ zhè jiā diàn de yuèbing yìzhí gōngbúyìngqiú.","vi":"Vì tiếng lành đồn xa nên bánh trung thu của tiệm này lúc nào cũng cung không đủ cầu."}],"related":[{"hanzi":"供过于求","pinyin":"gōngguòyúqiú","vi":"cung vượt cầu"},{"hanzi":"供应","pinyin":"gōngyìng","vi":"cung ứng"},{"hanzi":"需求","pinyin":"xūqiú","vi":"nhu cầu"},{"hanzi":"紧缺","pinyin":"jǐnquē","vi":"khan hiếm"}],"traditional":"供不應求"},{"id":"公关","hanzi":"公关","pinyin":"gōngguān","meaning_vi":"quan hệ công chúng (PR)","explanation":"公 (công – chung, công cộng) + 关 (quan – quan hệ) → viết tắt của 公共关系: quan hệ công chúng, PR. Ví dụ: 公关部, 危机公关.","hsk_level":6,"tags":["danh-tu","cong-viec"],"image":"🤝","examples":[{"type":"basic","zh":"她在公关部工作。","pinyin":"Tā zài gōngguānbù gōngzuò.","vi":"Cô ấy làm việc ở bộ phận quan hệ công chúng."},{"type":"simple","zh":"这家公司花重金请了一个专业公关团队。","pinyin":"Zhè jiā gōngsī huā zhòngjīn qǐngle yí gè zhuānyè gōngguān tuánduì.","vi":"Công ty này bỏ nhiều tiền thuê một đội ngũ quan hệ công chúng chuyên nghiệp."},{"type":"compound","zh":"产品出了质量问题以后，如果公关处理不当，品牌形象就会大受影响。","pinyin":"Chǎnpǐn chūle zhìliàng wèntí yǐhòu, rúguǒ gōngguān chǔlǐ búdàng, pǐnpái xíngxiàng jiù huì dà shòu yǐngxiǎng.","vi":"Sau khi sản phẩm gặp vấn đề chất lượng, nếu xử lý truyền thông không khéo thì hình ảnh thương hiệu sẽ bị ảnh hưởng nặng."}],"related":[{"hanzi":"公共关系","pinyin":"gōnggòngguānxì","vi":"quan hệ công chúng"},{"hanzi":"宣传","pinyin":"xuānchuán","vi":"tuyên truyền"},{"hanzi":"形象","pinyin":"xíngxiàng","vi":"hình ảnh"},{"hanzi":"公关部","pinyin":"gōngguānbù","vi":"phòng PR"}],"traditional":"公關"},{"id":"攻关","hanzi":"攻关","pinyin":"gōngguān","meaning_vi":"đột phá cửa ải khó khăn (nghiên cứu kỹ thuật)","explanation":"攻 (đánh) + 关 (cửa ải). Động từ ly hợp.","hsk_level":6,"tags":["dong-tu","khoa-hoc"],"image":"🔬","examples":[{"type":"basic","zh":"科研团队正在攻关。","pinyin":"Kēyán tuánduì zhèngzài gōngguān.","vi":"Nhóm nghiên cứu đang dốc sức đột phá."},{"type":"simple","zh":"工程师们连续三个月攻关芯片技术难题。","pinyin":"Gōngchéngshīmen liánxù sān gèyuè gōngguān xīnpiàn jìshù nántí.","vi":"Các kỹ sư liên tục ba tháng dốc sức giải quyết bài toán công nghệ chip."},{"type":"compound","zh":"只要大家齐心协力攻关，这个难题就一定能解决。","pinyin":"Zhǐyào dàjiā qíxīnxiélì gōngguān, zhè ge nántí jiù yídìng néng jiějué.","vi":"Chỉ cần mọi người đồng lòng dốc sức đột phá thì bài toán khó này nhất định sẽ được giải quyết."}],"related":[{"hanzi":"攻克","pinyin":"gōngkè","vi":"chinh phục"},{"hanzi":"难关","pinyin":"nánguān","vi":"cửa ải khó"},{"hanzi":"突破","pinyin":"tūpò","vi":"đột phá"},{"hanzi":"科研","pinyin":"kēyán","vi":"nghiên cứu khoa học"}],"traditional":"攻關"},{"id":"攻击","hanzi":"攻击","pinyin":"gōngjī","meaning_vi":"tấn công, công kích","explanation":"攻 (công – đánh) + 击 (kích – đập, đánh) → tấn công, công kích (quân sự hoặc bằng lời nói). Ví dụ: 发动攻击, 人身攻击.","hsk_level":6,"tags":["dong-tu"],"image":"⚔️","examples":[{"type":"basic","zh":"狗突然攻击了路人。","pinyin":"Gǒu tūrán gōngjīle lùrén.","vi":"Con chó đột nhiên tấn công người đi đường."},{"type":"simple","zh":"公司的网站昨晚遭到了黑客攻击。","pinyin":"Gōngsī de wǎngzhàn zuówǎn zāodàole hēikè gōngjī.","vi":"Trang web của công ty tối qua bị tin tặc tấn công."},{"type":"compound","zh":"即使你不同意他的观点，也不应该进行人身攻击。","pinyin":"Jíshǐ nǐ bù tóngyì tā de guāndiǎn, yě bù yīnggāi jìnxíng rénshēn gōngjī.","vi":"Cho dù bạn không đồng ý với quan điểm của anh ấy cũng không nên công kích cá nhân."}],"related":[{"hanzi":"进攻","pinyin":"jìngōng","vi":"tiến công"},{"hanzi":"防守","pinyin":"fángshǒu","vi":"phòng thủ"},{"hanzi":"袭击","pinyin":"xíjī","vi":"tập kích"},{"hanzi":"人身攻击","pinyin":"rénshēngōngjī","vi":"công kích cá nhân"}],"traditional":"攻擊"},{"id":"功亏一篑","hanzi":"功亏一篑","pinyin":"gōngkuī-yíkuì","meaning_vi":"thất bại ở bước cuối, chỉ thiếu chút nữa là thành công","explanation":"功亏一篑: đắp núi chỉ thiếu một sọt (篑) đất mà công cốc (sách Thượng Thư) → sắp thành công thì hỏng vì thiếu chút cố gắng cuối cùng.","hsk_level":6,"tags":["thanh-ngu"],"image":"⛰️","examples":[{"type":"basic","zh":"真可惜，功亏一篑。","pinyin":"Zhēn kěxī, gōngkuīyíkuì.","vi":"Thật đáng tiếc, chỉ thiếu chút nữa là thành."},{"type":"simple","zh":"登山队在距离顶峰百米处功亏一篑。","pinyin":"Dēngshān duì zài jùlí dǐngfēng bǎimǐ chù gōngkuīyíkuì.","vi":"Đội leo núi đã thất bại khi chỉ còn cách đỉnh một trăm mét."},{"type":"compound","zh":"如果最后这几天松懈下来，我们就会功亏一篑。","pinyin":"Rúguǒ zuìhòu zhèjǐtiān sōngxiè xiàlái, wǒmen jiù huì gōngkuīyíkuì.","vi":"Nếu mấy ngày cuối này lơi lỏng thì chúng ta sẽ hỏng việc vào phút chót."}],"related":[{"hanzi":"半途而废","pinyin":"bàntú'érfèi","vi":"bỏ dở giữa chừng"},{"hanzi":"前功尽弃","pinyin":"qiángōngjìnqì","vi":"công sức đổ sông đổ biển"},{"hanzi":"大功告成","pinyin":"dàgōnggàochéng","vi":"đại công cáo thành"},{"hanzi":"失败","pinyin":"shībài","vi":"thất bại"}],"traditional":"功虧一簣"},{"id":"公认","hanzi":"公认","pinyin":"gōngrèn","meaning_vi":"công nhận rộng rãi","explanation":"公 (công – chung, mọi người) + 认 (nhận – nhận) → được mọi người công nhận rộng rãi. Ví dụ: 公认的事实, 大家公认他是最好的.","hsk_level":6,"tags":["dong-tu"],"image":"✅","examples":[{"type":"basic","zh":"他是公认的天才。","pinyin":"Tā shì gōngrèn de tiāncái.","vi":"Anh ấy là thiên tài được mọi người công nhận."},{"type":"simple","zh":"这家医院的心脏外科是全国公认最好的。","pinyin":"Zhè jiā yīyuàn de xīnzàng wàikē shì quánguó gōngrèn zuìhǎo de.","vi":"Khoa phẫu thuật tim của bệnh viện này được cả nước công nhận là tốt nhất."},{"type":"compound","zh":"虽然这个理论现在已经被公认，但是当初提出时受到了很多质疑。","pinyin":"Suīrán zhè ge lǐlùn xiànzài yǐjīng bèi gōngrèn, dànshì dāngchū tíchū shí shòudàole hěn duō zhìyí.","vi":"Tuy lý thuyết này hiện nay đã được công nhận rộng rãi nhưng khi mới đề xuất đã bị nhiều người nghi ngờ."}],"related":[{"hanzi":"承认","pinyin":"chéngrèn","vi":"thừa nhận"},{"hanzi":"众所周知","pinyin":"zhòngsuǒzhōuzhī","vi":"ai cũng biết"},{"hanzi":"公认的","pinyin":"gōngrènde","vi":"được công nhận"},{"hanzi":"认可","pinyin":"rènkě","vi":"công nhận, chấp thuận"}],"traditional":"公認"},{"id":"供认","hanzi":"供认","pinyin":"gòngrèn","meaning_vi":"thú nhận, khai nhận (tội lỗi)","explanation":"供 (đọc gòng - khai báo) + 认 (nhận).","hsk_level":6,"tags":["dong-tu","phap-luat"],"image":"⚖️","examples":[{"type":"basic","zh":"嫌疑人供认了罪行。","pinyin":"Xiányírén gòngrènle zuìxíng.","vi":"Nghi phạm đã khai nhận tội."},{"type":"simple","zh":"在确凿的证据面前，他只好供认不讳。","pinyin":"Zài quèzáo de zhèngjù miànqián, tā zhǐhǎo gòngrèn búhuì.","vi":"Trước chứng cứ xác thực, hắn đành thú nhận hết không giấu giếm."},{"type":"compound","zh":"警察一拿出录像，他就供认了偷车的事实。","pinyin":"Jǐngchá yì náchū lùxiàng, tā jiù gòngrènle tōu chē de shìshí.","vi":"Cảnh sát vừa đưa ra đoạn video, hắn liền khai nhận hành vi trộm xe."}],"related":[{"hanzi":"招认","pinyin":"zhāorèn","vi":"thú nhận"},{"hanzi":"坦白","pinyin":"tǎnbái","vi":"thành thật khai báo"},{"hanzi":"认罪","pinyin":"rènzuì","vi":"nhận tội"},{"hanzi":"否认","pinyin":"fǒurèn","vi":"phủ nhận"}],"traditional":"供認"},{"id":"供销","hanzi":"供销","pinyin":"gōngxiāo","meaning_vi":"cung ứng và tiêu thụ","explanation":"供 (đọc gōng) + 销 (bán).","hsk_level":6,"tags":["danh-tu","cong-viec"],"image":"🏪","examples":[{"type":"basic","zh":"他在供销社工作。","pinyin":"Tā zài gōngxiāoshè gōngzuò.","vi":"Ông ấy làm việc ở hợp tác xã cung tiêu."},{"type":"simple","zh":"这家工厂专门负责农机产品的供销业务。","pinyin":"Zhè jiā gōngchǎng zhuānmén fùzé nóngjī chǎnpǐn de gōngxiāo yèwù.","vi":"Nhà máy này chuyên phụ trách nghiệp vụ cung ứng và tiêu thụ sản phẩm máy nông nghiệp."},{"type":"compound","zh":"只有供销渠道畅通，农民的蔬菜才能及时卖出去。","pinyin":"Zhǐyǒu gōngxiāo qúdào chàngtōng, nóngmín de shūcài cáinéng jíshí mài chūqù.","vi":"Chỉ khi kênh cung ứng và tiêu thụ thông suốt, rau của nông dân mới bán được kịp thời."}],"related":[{"hanzi":"供应","pinyin":"gōngyìng","vi":"cung ứng"},{"hanzi":"销售","pinyin":"xiāoshòu","vi":"tiêu thụ"},{"hanzi":"供销社","pinyin":"gōngxiāoshè","vi":"hợp tác xã mua bán"},{"hanzi":"产销","pinyin":"chǎnxiāo","vi":"sản xuất và tiêu thụ"}],"traditional":"供銷"},{"id":"工薪","hanzi":"工薪","pinyin":"gōngxīn","meaning_vi":"lương bổng (tầng lớp làm công ăn lương)","explanation":"工 + 薪 (tiền lương).","hsk_level":6,"tags":["danh-tu","tien-te","xa-hoi"],"image":"💼","examples":[{"type":"basic","zh":"我们是普通工薪家庭。","pinyin":"Wǒmen shì pǔtōng gōngxīn jiātíng.","vi":"Chúng tôi là gia đình làm công ăn lương bình thường."},{"type":"simple","zh":"这家餐厅的价格很适合工薪阶层。","pinyin":"Zhè jiā cāntīng de jiàgé hěn shìhé gōngxīnjiēcéng.","vi":"Giá của nhà hàng này rất phù hợp với tầng lớp làm công ăn lương."},{"type":"compound","zh":"对工薪族来说，如果房价继续上涨，买房就更难了。","pinyin":"Duì gōngxīnzú lái shuō, rúguǒ fángjià jìxù shàngzhǎng, mǎifáng jiù gèng nán le.","vi":"Đối với người làm công ăn lương, nếu giá nhà tiếp tục tăng thì việc mua nhà càng khó hơn."}],"related":[{"hanzi":"工资","pinyin":"gōngzī","vi":"tiền lương"},{"hanzi":"薪水","pinyin":"xīnshui","vi":"lương"},{"hanzi":"工薪阶层","pinyin":"gōngxīnjiēcéng","vi":"tầng lớp làm công"},{"hanzi":"收入","pinyin":"shōurù","vi":"thu nhập"}]},{"id":"工欲善其事必先利其器","hanzi":"工欲善其事必先利其器","pinyin":"gōng yù shàn qí shì bì xiān lì qí qì","meaning_vi":"muốn làm tốt việc trước tiên phải mài sắc công cụ","explanation":"Danh ngôn Khổng Tử.","hsk_level":6,"tags":["thanh-ngu","cong-viec"],"image":"🛠️","examples":[{"type":"basic","zh":"工欲善其事必先利其器。","pinyin":"Gōng yù shàn qí shì bì xiān lì qí qì.","vi":"Muốn làm tốt việc thì trước hết phải mài sắc công cụ."},{"type":"simple","zh":"他买新电脑是因为相信工欲善其事必先利其器。","pinyin":"Tā mǎi xīn diànnǎo shì yīnwèi xiāngxìn gōng yù shàn qí shì bì xiān lì qí qì.","vi":"Anh ấy mua máy tính mới vì tin rằng muốn làm tốt việc trước hết phải có công cụ tốt."},{"type":"compound","zh":"既然工欲善其事必先利其器，我们就先把实验设备升级吧。","pinyin":"Jìrán gōng yù shàn qí shì bì xiān lì qí qì, wǒmen jiù xiān bǎ shíyàn shèbèi shēngjí ba.","vi":"Muốn làm tốt việc thì phải có công cụ tốt trước, vậy chúng ta hãy nâng cấp thiết bị thí nghiệm trước đã."}],"related":[{"hanzi":"磨刀不误砍柴工","pinyin":"módāo búwù kǎn chái gōng","vi":"mài dao không lỡ việc đốn củi"},{"hanzi":"工具","pinyin":"gōngjù","vi":"công cụ"},{"hanzi":"准备","pinyin":"zhǔnbèi","vi":"chuẩn bị"},{"hanzi":"事半功倍","pinyin":"shìbàngōngbèi","vi":"làm ít được nhiều"}]},{"id":"公证","hanzi":"公证","pinyin":"gōngzhèng","meaning_vi":"công chứng","explanation":"公 (công – công) + 证 (chứng – chứng nhận) → công chứng: cơ quan nhà nước xác nhận tính hợp pháp của giấy tờ. Ví dụ: 公证处, 办理公证.","hsk_level":6,"tags":["dong-tu","phap-luat"],"image":"📜","examples":[{"type":"basic","zh":"这份遗嘱需要公证。","pinyin":"Zhè fèn yízhǔ xūyào gōngzhèng.","vi":"Bản di chúc này cần được công chứng."},{"type":"simple","zh":"他们去公证处办理了房产赠与手续。","pinyin":"Tāmen qù gōngzhèngchù bànlǐle fángchǎn zèngyǔ shǒuxù.","vi":"Họ đến phòng công chứng làm thủ tục tặng cho nhà đất."},{"type":"compound","zh":"因为出国留学需要学历证明，所以她把毕业证拿去做了公证。","pinyin":"Yīnwèi chūguó liúxué xūyào xuélì zhèngmíng, suǒyǐ tā bǎ bìyèzhèng ná qù zuòle gōngzhèng.","vi":"Vì đi du học cần giấy chứng minh học vấn nên cô ấy đã mang bằng tốt nghiệp đi công chứng."}],"related":[{"hanzi":"公证处","pinyin":"gōngzhèngchù","vi":"phòng công chứng"},{"hanzi":"证明","pinyin":"zhèngmíng","vi":"chứng minh"},{"hanzi":"公证人","pinyin":"gōngzhèngrén","vi":"công chứng viên"},{"hanzi":"认证","pinyin":"rènzhèng","vi":"chứng thực"}],"traditional":"公證"},{"id":"公安","hanzi":"公安","pinyin":"gōng'ān","meaning_vi":"công an","explanation":"公 (công – chung) + 安 (an – yên ổn) → công an, cơ quan giữ an ninh trật tự. Ví dụ: 公安局, 公安机关.","hsk_level":6,"tags":["danh-tu","phap-luat"],"image":"👮","examples":[{"type":"basic","zh":"他是一名公安干警。","pinyin":"Tā shì yì míng gōng'ān gànjǐng.","vi":"Anh ấy là một cán bộ công an."},{"type":"simple","zh":"市公安局破获了一起特大诈骗案。","pinyin":"Shì gōng'ānjú pòhuòle yìqǐ tèdà zhàpiàn àn.","vi":"Công an thành phố đã phá một vụ lừa đảo đặc biệt lớn."},{"type":"compound","zh":"一接到报警电话，公安人员就迅速赶到了现场。","pinyin":"Yì jiēdào bàojǐng diànhuà, gōng'ān rényuán jiù xùnsù gǎndàole xiànchǎng.","vi":"Vừa nhận được điện thoại báo án, lực lượng công an đã nhanh chóng có mặt tại hiện trường."}],"related":[{"hanzi":"警察","pinyin":"jǐngchá","vi":"cảnh sát"},{"hanzi":"公安局","pinyin":"gōng'ānjú","vi":"sở công an"},{"hanzi":"派出所","pinyin":"pàichūsuǒ","vi":"đồn công an"},{"hanzi":"治安","pinyin":"zhì'ān","vi":"trị an"}]},{"id":"勾画","hanzi":"勾画","pinyin":"gōuhuà","meaning_vi":"phác họa, vẽ phác","explanation":"勾 (câu – vẽ nét viền) + 画 (họa – vẽ) → vẽ phác đường nét; nghĩa bóng phác họa kế hoạch, viễn cảnh. Cụm: 勾画蓝图.","hsk_level":6,"tags":["dong-tu","giai-tri"],"image":"✏️","examples":[{"type":"basic","zh":"他勾画出一幅草图。","pinyin":"Tā gōuhuà chū yì fú cǎotú.","vi":"Anh ấy phác họa ra một bản vẽ phác."},{"type":"simple","zh":"市长在会上勾画了城市未来十年的蓝图。","pinyin":"Shìzhǎng zài huì shang gōuhuàle chéngshì wèilái shí nián de lántú.","vi":"Thị trưởng phác họa trong cuộc họp bức tranh tương lai mười năm của thành phố."},{"type":"compound","zh":"虽然作家只用了寥寥几笔，但是把人物的性格勾画得活灵活现。","pinyin":"Suīrán zuòjiā zhǐ yòngle liáoliáo jǐ bǐ, dànshì bǎ rénwù de xìnggé gōuhuà de huólínghuóxiàn.","vi":"Tuy nhà văn chỉ dùng vài nét bút nhưng đã phác họa tính cách nhân vật sống động như thật."}],"related":[{"hanzi":"勾勒","pinyin":"gōulè","vi":"phác thảo"},{"hanzi":"描绘","pinyin":"miáohuì","vi":"miêu tả"},{"hanzi":"素描","pinyin":"sùmiáo","vi":"vẽ phác"},{"hanzi":"轮廓","pinyin":"lúnkuò","vi":"đường nét"}],"traditional":"勾畫"},{"id":"勾结","hanzi":"勾结","pinyin":"gōujié","meaning_vi":"câu kết, thông đồng","explanation":"勾 (câu – móc) + 结 (kết – thắt, kết) → móc nối, câu kết với nhau làm việc xấu. Ví dụ: 勾结敌人, 官商勾结. Mang nghĩa xấu.","hsk_level":6,"tags":["dong-tu"],"image":"⛓️","examples":[{"type":"basic","zh":"他与黑帮勾结。","pinyin":"Tā yǔ hēibāng gōujié.","vi":"Hắn câu kết với băng đảng."},{"type":"simple","zh":"几个官员勾结商人非法倒卖土地。","pinyin":"Jǐ gè guānyuán gōujié shāngrén fēifǎ dǎomài tǔdì.","vi":"Mấy quan chức câu kết với thương nhân buôn bán đất trái phép."},{"type":"compound","zh":"如果内部人员不跟小偷勾结，仓库里的货就不可能被偷走。","pinyin":"Rúguǒ nèibù rényuán bù gēn xiǎotōu gōujié, cāngkù li de huò jiù bù kěnéng bèi tōu zǒu.","vi":"Nếu người bên trong không câu kết với kẻ trộm thì hàng trong kho không thể bị lấy mất."}],"related":[{"hanzi":"串通","pinyin":"chuàntōng","vi":"thông đồng"},{"hanzi":"狼狈为奸","pinyin":"lángbèiwéijiān","vi":"cấu kết làm bậy"},{"hanzi":"合谋","pinyin":"hémóu","vi":"đồng mưu"},{"hanzi":"同伙","pinyin":"tónghuǒ","vi":"đồng bọn"}],"traditional":"勾結"},{"id":"勾心斗角","hanzi":"勾心斗角","pinyin":"gōuxīn-dòujiǎo","meaning_vi":"đấu đá ngầm, mưu mô tính toán lẫn nhau","explanation":"勾心斗角: vốn tả kiến trúc cung điện, mái hiên móc nối, góc nhà chọi nhau (Đỗ Mục) → nay chỉ đấu đá ngầm, mưu mô tranh giành lẫn nhau.","hsk_level":6,"tags":["thanh-ngu"],"image":"🐍","examples":[{"type":"basic","zh":"他们整天勾心斗角。","pinyin":"Tāmen zhěngtiān gōuxīndòujiǎo.","vi":"Họ suốt ngày đấu đá ngầm với nhau."},{"type":"simple","zh":"这部宫廷剧讲的是妃子们勾心斗角的故事。","pinyin":"Zhè bù gōngtíng jù jiǎng de shì fēizimen gōuxīndòujiǎo de gùshi.","vi":"Bộ phim cung đấu này kể về chuyện các phi tần mưu mô đấu đá lẫn nhau."},{"type":"compound","zh":"因为受不了同事之间的勾心斗角，所以她辞职去开了家花店。","pinyin":"Yīnwèi shòubuliǎo tóngshì zhījiān de gōuxīndòujiǎo, suǒyǐ tā cízhí qù kāile jiā huādiàn.","vi":"Vì không chịu nổi cảnh đồng nghiệp đấu đá ngầm nên cô ấy đã nghỉ việc mở một tiệm hoa."}],"related":[{"hanzi":"明争暗斗","pinyin":"míngzhēng'àndòu","vi":"đấu đá công khai lẫn ngầm"},{"hanzi":"尔虞我诈","pinyin":"ěryúwǒzhà","vi":"lừa lọc lẫn nhau"},{"hanzi":"钩心斗角","pinyin":"gōuxīndòujiǎo","vi":"đấu đá mưu mô"},{"hanzi":"齐心协力","pinyin":"qíxīnxiélì","vi":"đồng lòng hiệp lực"}],"traditional":"勾心鬥角"},{"id":"孤独","hanzi":"孤独","pinyin":"gūdú","meaning_vi":"cô độc, cô đơn","explanation":"孤 (cô – lẻ loi) + 独 (độc – một mình) → cô độc, cô đơn, một mình không ai bầu bạn. Ví dụ: 感到孤独, 孤独的老人.","hsk_level":6,"tags":["tinh-tu"],"image":"😔","examples":[{"type":"basic","zh":"老人感到很孤独。","pinyin":"Lǎorén gǎndào hěn gūdú.","vi":"Ông lão cảm thấy rất cô đơn."},{"type":"simple","zh":"他独自在异国他乡度过了孤独的春节。","pinyin":"Tā dú zìzài yìguótāxiāng dùguòle gūdú de Chūnjié.","vi":"Anh ấy một mình đón cái Tết cô đơn nơi đất khách quê người."},{"type":"compound","zh":"即使身边有很多人，他有时也会觉得孤独。","pinyin":"Jíshǐ shēnbiān yǒu hěn duō rén, tā yǒushí yě huì juéde gūdú.","vi":"Cho dù xung quanh có nhiều người, đôi khi anh ấy vẫn cảm thấy cô đơn."}],"related":[{"hanzi":"寂寞","pinyin":"jìmò","vi":"cô quạnh"},{"hanzi":"孤单","pinyin":"gūdān","vi":"cô đơn"},{"hanzi":"孤零零","pinyin":"gūlínglíng","vi":"lẻ loi"},{"hanzi":"热闹","pinyin":"rènao","vi":"náo nhiệt"}],"traditional":"孤獨"},{"id":"孤陋寡闻","hanzi":"孤陋寡闻","pinyin":"gūlòu-guǎwén","meaning_vi":"kiến thức hạn hẹp, ít hiểu biết","explanation":"孤陋 + 寡闻 (nghe ít). Thành ngữ.","hsk_level":6,"tags":["thanh-ngu"],"image":"🙈","examples":[{"type":"basic","zh":"恕我孤陋寡闻。","pinyin":"Shù wǒ gūlòuguǎwén.","vi":"Xin thứ lỗi cho sự hiểu biết hạn hẹp của tôi."},{"type":"simple","zh":"孤陋寡闻的我第一次听说这种水果。","pinyin":"Gūlòuguǎwén de wǒ dìyīcì tīngshuō zhè zhǒng shuǐguǒ.","vi":"Kẻ kiến thức hạn hẹp như tôi lần đầu nghe nói đến loại trái cây này."},{"type":"compound","zh":"如果只待在自己的小圈子里，人就容易变得孤陋寡闻。","pinyin":"Rúguǒ zhǐ dāi zài zìjǐ de xiǎo quānzi li, rén jiù róngyì biànde gūlòuguǎwén.","vi":"Nếu chỉ ở trong vòng tròn nhỏ của mình thì con người dễ trở nên hiểu biết hạn hẹp."}],"related":[{"hanzi":"见多识广","pinyin":"jiànduōshíguǎng","vi":"hiểu biết rộng"},{"hanzi":"井底之蛙","pinyin":"jǐngdǐzhīwā","vi":"ếch ngồi đáy giếng"},{"hanzi":"无知","pinyin":"wúzhī","vi":"thiếu hiểu biết"},{"hanzi":"博学","pinyin":"bóxué","vi":"học rộng"}],"traditional":"孤陋寡聞"},{"id":"姑且","hanzi":"姑且","pinyin":"gūqiě","meaning_vi":"tạm thời, hãy cứ","explanation":"姑 (cô – tạm) + 且 (thả – tạm, hãy) → phó từ: tạm thời cứ, hãy tạm. Cụm: 姑且不论 (tạm không bàn đến).","hsk_level":6,"tags":["pho-tu"],"image":"⏳","examples":[{"type":"basic","zh":"你姑且试试看。","pinyin":"Nǐ gūqiě shìshikàn.","vi":"Bạn cứ tạm thử xem."},{"type":"simple","zh":"这件旧大衣姑且还能再穿一个冬天。","pinyin":"Zhè jiàn jiù dàyī gūqiě hái néng zài chuān yí gè dōngtiān.","vi":"Chiếc áo khoác cũ này tạm thời vẫn có thể mặc thêm một mùa đông."},{"type":"compound","zh":"虽然这个方案不完美，但是我们姑且按它执行吧。","pinyin":"Suīrán zhè ge fāng'àn bù wánměi, dànshì wǒmen gūqiě àn tā zhíxíng ba.","vi":"Tuy phương án này chưa hoàn hảo nhưng chúng ta cứ tạm thực hiện theo nó đã."}],"related":[{"hanzi":"暂且","pinyin":"zànqiě","vi":"tạm thời"},{"hanzi":"暂时","pinyin":"zànshí","vi":"tạm thời"},{"hanzi":"权且","pinyin":"quánqiě","vi":"tạm, tạm thời"},{"hanzi":"先","pinyin":"xiān","vi":"trước hết"}]},{"id":"孤注一掷","hanzi":"孤注一掷","pinyin":"gūzhù-yízhì","meaning_vi":"được ăn cả ngã về không, dốc hết vốn liếng đánh cược một phen","explanation":"孤注一掷: dồn hết số tiền còn lại (孤注) vào một lần gieo xúc xắc (一掷) → liều dốc toàn lực vào một phen, được ăn cả ngã về không.","hsk_level":6,"tags":["thanh-ngu"],"image":"🎲","examples":[{"type":"basic","zh":"他决定孤注一掷。","pinyin":"Tā juédìng gūzhùyízhì.","vi":"Anh ấy quyết định được ăn cả ngã về không."},{"type":"simple","zh":"他把全部积蓄孤注一掷地投进了股市。","pinyin":"Tā bǎ quánbù jīxù gūzhùyízhì de tóu jìnle gǔshì.","vi":"Anh ấy dốc toàn bộ tiền tiết kiệm đánh cược một phen vào thị trường chứng khoán."},{"type":"compound","zh":"既然已经没有退路了，我们就只能孤注一掷。","pinyin":"Jìrán yǐjīng méiyǒu tuìlù le, wǒmen jiù zhǐnéng gūzhùyízhì.","vi":"Đã không còn đường lui thì chúng ta chỉ có thể liều một phen."}],"related":[{"hanzi":"破釜沉舟","pinyin":"pòfǔchénzhōu","vi":"đập nồi dìm thuyền"},{"hanzi":"冒险","pinyin":"màoxiǎn","vi":"mạo hiểm"},{"hanzi":"赌博","pinyin":"dǔbó","vi":"cờ bạc"},{"hanzi":"背水一战","pinyin":"bèishuǐyízhàn","vi":"đánh trận quyết tử"}],"traditional":"孤注一擲"},{"id":"改过自新","hanzi":"改过自新","pinyin":"gǎiguò-zìxīn","meaning_vi":"sửa lỗi làm lại cuộc đời","explanation":"改过自新: sửa (改) lỗi (过), tự (自) làm mới (新) mình → sửa sai, làm lại cuộc đời. Thường dùng với người phạm tội: 给他改过自新的机会.","hsk_level":6,"tags":["thanh-ngu"],"image":"🌱","examples":[{"type":"basic","zh":"他决心改过自新。","pinyin":"Tā juéxīn gǎiguòzìxīn.","vi":"Anh ấy quyết tâm sửa lỗi làm lại cuộc đời."},{"type":"simple","zh":"法院给了这个少年改过自新的机会。","pinyin":"Fǎyuàn gěile zhè ge shàonián gǎiguòzìxīn de jīhuì.","vi":"Tòa án đã cho thiếu niên này cơ hội sửa lỗi làm lại."},{"type":"compound","zh":"只要你真心改过自新，大家就会重新接纳你。","pinyin":"Zhǐyào nǐ zhēnxīn gǎiguòzìxīn, dàjiā jiù huì chóngxīn jiēnà nǐ.","vi":"Chỉ cần bạn thật lòng hối cải làm lại, mọi người sẽ đón nhận bạn trở lại."}],"related":[{"hanzi":"改邪归正","pinyin":"gǎixiéguīzhèng","vi":"bỏ tà theo chính"},{"hanzi":"痛改前非","pinyin":"tònggǎiqiánfēi","vi":"hối cải sai lầm cũ"},{"hanzi":"重新做人","pinyin":"chóngxīnzuòrén","vi":"làm lại cuộc đời"},{"hanzi":"屡教不改","pinyin":"lǚjiàobùgǎi","vi":"dạy mãi không sửa"}],"traditional":"改過自新"},{"id":"改头换面","hanzi":"改头换面","pinyin":"gǎitóu-huànmiàn","meaning_vi":"thay hình đổi dạng (chỉ đổi bề ngoài)","explanation":"改头换面: đổi đầu thay mặt → chỉ thay đổi bề ngoài còn thực chất vẫn như cũ; thường mang nghĩa chê.","hsk_level":6,"tags":["thanh-ngu"],"image":"🎭","examples":[{"type":"basic","zh":"老店改头换面了。","pinyin":"Lǎo diàn gǎitóuhuànmiàn le.","vi":"Tiệm cũ đã thay hình đổi dạng."},{"type":"simple","zh":"这本书只是把旧作改头换面重新出版。","pinyin":"Zhè běn shū zhǐshì bǎ jiù zuò gǎitóuhuànmiàn chóngxīn chūbǎn.","vi":"Cuốn sách này chỉ là thay đổi bề ngoài của tác phẩm cũ rồi xuất bản lại."},{"type":"compound","zh":"这家公司虽然改头换面换了名字，但是卖的还是那些劣质产品。","pinyin":"Zhè jiā gōngsī suīrán gǎitóuhuànmiàn huànle míngzi, dànshì mài de háishi nàxiē lièzhì chǎnpǐn.","vi":"Công ty này tuy thay hình đổi dạng, đổi cả tên nhưng bán vẫn là những sản phẩm kém chất lượng đó."}],"related":[{"hanzi":"换汤不换药","pinyin":"huàn tāng bú huàn yào","vi":"bình mới rượu cũ"},{"hanzi":"面目一新","pinyin":"miànmùyìxīn","vi":"diện mạo mới"},{"hanzi":"伪装","pinyin":"wěizhuāng","vi":"ngụy trang"},{"hanzi":"改变","pinyin":"gǎibiàn","vi":"thay đổi"}],"traditional":"改頭換面"},{"id":"改邪归正","hanzi":"改邪归正","pinyin":"gǎixié-guīzhèng","meaning_vi":"bỏ tà theo chính, hoàn lương","explanation":"改邪归正: bỏ (改) đường tà (邪), quay về (归) đường chính (正) → từ bỏ việc xấu, hoàn lương, trở thành người lương thiện.","hsk_level":6,"tags":["thanh-ngu"],"image":"🕊️","examples":[{"type":"basic","zh":"他终于改邪归正了。","pinyin":"Tā zhōngyú gǎixiéguīzhèng le.","vi":"Cuối cùng hắn đã hoàn lương."},{"type":"simple","zh":"这位改邪归正的前小偷现在当了保安。","pinyin":"Zhè wèi gǎixiéguīzhèng de qián xiǎotōu xiànzài dāngle bǎo'ān.","vi":"Tên trộm cũ đã hoàn lương này giờ làm bảo vệ."},{"type":"compound","zh":"在家人的帮助下，他不但改邪归正了，而且开了一家修车铺。","pinyin":"Zài jiārén de bāngzhù xià, tā búdàn gǎixiéguīzhèng le, érqiě kāile yìjiā xiūchē pù.","vi":"Nhờ sự giúp đỡ của gia đình, anh ấy không những hoàn lương mà còn mở một tiệm sửa xe."}],"related":[{"hanzi":"改过自新","pinyin":"gǎiguòzìxīn","vi":"sửa lỗi làm lại"},{"hanzi":"弃暗投明","pinyin":"qì'àntóumíng","vi":"bỏ tối theo sáng"},{"hanzi":"浪子回头","pinyin":"làngzǐhuítóu","vi":"đứa con hoang đàng trở về"},{"hanzi":"执迷不悟","pinyin":"zhímíbúwù","vi":"u mê không tỉnh"}],"traditional":"改邪歸正"},{"id":"感触","hanzi":"感触","pinyin":"gǎnchù","meaning_vi":"cảm xúc, nỗi niềm xúc động","explanation":"感 + 触 (chạm tới).","hsk_level":6,"tags":["danh-tu","cam-xuc"],"image":"💭","examples":[{"type":"basic","zh":"我感触很深。","pinyin":"Wǒ gǎnchù hěn shēn.","vi":"Tôi rất xúc động."},{"type":"simple","zh":"这次支教经历给了我很多感触。","pinyin":"Zhè cì zhījiào jīnglì gěile wǒ hěn duō gǎnchù.","vi":"Trải nghiệm dạy học tình nguyện lần này mang lại cho tôi nhiều cảm xúc."},{"type":"compound","zh":"每当回到母校，我就会生出许多感触。","pinyin":"Měidāng huídào mǔxiào, wǒ jiù huì shēngchū xǔduō gǎnchù.","vi":"Mỗi khi trở về trường cũ, lòng tôi lại dâng lên bao nỗi niềm."}],"related":[{"hanzi":"感受","pinyin":"gǎnshòu","vi":"cảm nhận"},{"hanzi":"感慨","pinyin":"gǎnkǎi","vi":"cảm khái"},{"hanzi":"触动","pinyin":"chùdòng","vi":"chạm đến lòng"},{"hanzi":"感想","pinyin":"gǎnxiǎng","vi":"cảm nghĩ"}],"traditional":"感觸"},{"id":"感人肺腑","hanzi":"感人肺腑","pinyin":"gǎnrén-fèifǔ","meaning_vi":"cảm động tận đáy lòng","explanation":"感人肺腑: làm cảm động đến tận phổi (肺) và tạng phủ (腑) → cảm động sâu sắc tận đáy lòng. Ví dụ: 感人肺腑的故事.","hsk_level":6,"tags":["thanh-ngu","cam-xuc"],"image":"🥹","examples":[{"type":"basic","zh":"这番话感人肺腑。","pinyin":"Zhè fān huà gǎnrénfèifǔ.","vi":"Những lời này cảm động tận đáy lòng."},{"type":"simple","zh":"电影讲述了一个感人肺腑的母爱故事。","pinyin":"Diànyǐng jiǎngshùle yí gè gǎnrénfèifǔ de mǔ'ài gùshi.","vi":"Bộ phim kể một câu chuyện tình mẫu tử cảm động tận đáy lòng."},{"type":"compound","zh":"他的演讲不但感人肺腑，而且给了大家前进的勇气。","pinyin":"Tā de yǎnjiǎng búdàn gǎnrénfèifǔ, érqiě gěile dàjiā qiánjìn de yǒngqì.","vi":"Bài diễn thuyết của anh ấy không những cảm động tận đáy lòng mà còn tiếp thêm dũng khí cho mọi người."}],"related":[{"hanzi":"感人至深","pinyin":"gǎnrénzhìshēn","vi":"cảm động sâu sắc"},{"hanzi":"动人","pinyin":"dòngrén","vi":"cảm động"},{"hanzi":"肺腑之言","pinyin":"fèifǔzhīyán","vi":"lời tự đáy lòng"},{"hanzi":"感动","pinyin":"gǎndòng","vi":"cảm động"}]},{"id":"感叹","hanzi":"感叹","pinyin":"gǎntàn","meaning_vi":"cảm thán, than thở","explanation":"感 + 叹 (thở dài).","hsk_level":6,"tags":["dong-tu","cam-xuc"],"image":"😮‍💨","examples":[{"type":"basic","zh":"老人感叹时光易逝。","pinyin":"Lǎorén gǎntàn shíguāng yìshì.","vi":"Ông lão than thở thời gian trôi qua nhanh quá."},{"type":"simple","zh":"游客们纷纷感叹这里的夜景太美了。","pinyin":"Yóukèmen fēnfēn gǎntàn zhèlǐ de yèjǐng tài měi le.","vi":"Du khách đều trầm trồ cảnh đêm ở đây quá đẹp."},{"type":"compound","zh":"他一翻开二十年前的日记，就忍不住感叹自己当年太天真。","pinyin":"Tā yì fānkāi èrshí niánqián de rìjì, jiù rěnbuzhù gǎntàn zìjǐ dāngnián tài tiānzhēn.","vi":"Vừa mở cuốn nhật ký hai mươi năm trước, anh ấy không kìm được mà than rằng mình hồi đó quá ngây thơ."}],"related":[{"hanzi":"感慨","pinyin":"gǎnkǎi","vi":"cảm khái"},{"hanzi":"叹息","pinyin":"tànxī","vi":"thở dài"},{"hanzi":"感叹号","pinyin":"gǎntànhào","vi":"dấu chấm than"},{"hanzi":"赞叹","pinyin":"zàntàn","vi":"thán phục"}],"traditional":"感嘆"},{"id":"感同身受","hanzi":"感同身受","pinyin":"gǎntóng-shēnshòu","meaning_vi":"cảm nhận như chính bản thân mình trải qua (đồng cảm sâu sắc)","explanation":"感同身受: cảm nhận như chính bản thân (身) mình trải qua (受) → đồng cảm sâu sắc với hoàn cảnh người khác; cũng dùng để cảm ơn thay người khác.","hsk_level":6,"tags":["thanh-ngu","cam-xuc"],"image":"🤗","examples":[{"type":"basic","zh":"你的痛苦我感同身受。","pinyin":"Nǐ de tòngkǔ wǒ gǎntóngshēnshòu.","vi":"Nỗi đau của bạn tôi cảm nhận như chính mình trải qua."},{"type":"simple","zh":"失业的滋味让他对穷人的困境感同身受。","pinyin":"Shīyè de zīwèi ràng tā duì qióngrén de kùnjìng gǎntóngshēnshòu.","vi":"Nếm mùi thất nghiệp khiến anh ấy thấu hiểu sâu sắc cảnh khó khăn của người nghèo."},{"type":"compound","zh":"因为自己也是单亲妈妈，所以她对这些孩子感同身受。","pinyin":"Yīnwèi zìjǐ yě shì dānqīn māma, suǒyǐ tā duì zhèxiē háizi gǎntóngshēnshòu.","vi":"Vì bản thân cũng là mẹ đơn thân nên cô ấy thấu hiểu sâu sắc những đứa trẻ này."}],"related":[{"hanzi":"设身处地","pinyin":"shèshēnchǔdì","vi":"đặt mình vào hoàn cảnh"},{"hanzi":"同情","pinyin":"tóngqíng","vi":"đồng cảm"},{"hanzi":"将心比心","pinyin":"jiāngxīnbǐxīn","vi":"suy bụng ta ra bụng người"},{"hanzi":"共鸣","pinyin":"gòngmíng","vi":"đồng cảm, cộng hưởng"}]},{"id":"感性","hanzi":"感性","pinyin":"gǎnxìng","meaning_vi":"cảm tính","explanation":"感 + 性 (tính chất). Đối nghĩa với 理性 (lý tính).","hsk_level":6,"tags":["tinh-tu"],"image":"❤️","examples":[{"type":"basic","zh":"她是个感性的人。","pinyin":"Tā shì gè gǎnxìng de rén.","vi":"Cô ấy là người cảm tính."},{"type":"simple","zh":"这位导演用感性的镜头记录了小城生活。","pinyin":"Zhè wèi dǎoyǎn yòng gǎnxìng de jìngtóu jìlùle xiǎochéng shēnghuó.","vi":"Vị đạo diễn này dùng những thước phim giàu cảm xúc để ghi lại cuộc sống thị trấn nhỏ."},{"type":"compound","zh":"虽然他平时很理性，但是一谈到家人就变得特别感性。","pinyin":"Suīrán tā píngshí hěn lǐxìng, dànshì yì tándào jiārén jiù biànde tèbié gǎnxìng.","vi":"Tuy bình thường anh ấy rất lý trí nhưng hễ nói đến gia đình là trở nên đặc biệt cảm tính."}],"related":[{"hanzi":"理性","pinyin":"lǐxìng","vi":"lý tính"},{"hanzi":"感性认识","pinyin":"gǎnxìngrènshi","vi":"nhận thức cảm tính"},{"hanzi":"感情","pinyin":"gǎnqíng","vi":"tình cảm"},{"hanzi":"直觉","pinyin":"zhíjué","vi":"trực giác"}]},{"id":"岗位","hanzi":"岗位","pinyin":"gǎngwèi","meaning_vi":"vị trí công tác","explanation":"岗 (cương – trạm gác) + 位 (vị – vị trí) → vị trí công tác, cương vị. Ví dụ: 工作岗位, 坚守岗位 = giữ vững vị trí.","hsk_level":6,"tags":["danh-tu","cong-viec"],"image":"💼","examples":[{"type":"basic","zh":"他坚守在岗位上。","pinyin":"Tā jiānshǒu zài gǎngwèi shang.","vi":"Anh ấy kiên trì bám trụ ở vị trí công tác."},{"type":"simple","zh":"这家公司今年新增了五十个技术岗位。","pinyin":"Zhè jiā gōngsī jīnnián xīnzēngle wǔshí gè jìshù gǎngwèi.","vi":"Công ty này năm nay mở thêm năm mươi vị trí kỹ thuật."},{"type":"compound","zh":"即使是普通的岗位，只要用心做，也能做出成绩。","pinyin":"Jíshǐ shì pǔtōng de gǎngwèi, zhǐyào yòngxīn zuò, yě néng zuòchū chéngjì.","vi":"Cho dù là vị trí bình thường, chỉ cần làm hết lòng thì cũng có thể đạt được thành tích."}],"related":[{"hanzi":"职位","pinyin":"zhíwèi","vi":"chức vụ"},{"hanzi":"工作","pinyin":"gōngzuò","vi":"công việc"},{"hanzi":"上岗","pinyin":"shànggǎng","vi":"nhận việc"},{"hanzi":"下岗","pinyin":"xiàgǎng","vi":"mất việc"}],"traditional":"崗位"},{"id":"稿酬","hanzi":"稿酬","pinyin":"gǎochóu","meaning_vi":"tiền nhuận bút","explanation":"稿 (bản thảo) + 酬 (thù lao).","hsk_level":6,"tags":["danh-tu","tien-te","cong-viec"],"image":"✍️","examples":[{"type":"basic","zh":"这篇文章稿酬不高。","pinyin":"Zhè piān wénzhāng gǎochóu bù gāo.","vi":"Nhuận bút bài viết này không cao."},{"type":"simple","zh":"他用第一笔稿酬给母亲买了一件毛衣。","pinyin":"Tāyòng dìyī bǐ gǎochóu gěi mǔqīn mǎile yí jiàn máoyī.","vi":"Anh ấy dùng khoản nhuận bút đầu tiên mua cho mẹ một chiếc áo len."},{"type":"compound","zh":"虽然稿酬很微薄，但是他依然坚持每天写作。","pinyin":"Suīrán gǎochóu hěn wēibó, dànshì tā yīrán jiānchí měitiān xiězuò.","vi":"Tuy tiền nhuận bút rất ít ỏi nhưng anh ấy vẫn kiên trì viết mỗi ngày."}],"related":[{"hanzi":"稿费","pinyin":"gǎofèi","vi":"tiền nhuận bút"},{"hanzi":"报酬","pinyin":"bàochou","vi":"thù lao"},{"hanzi":"稿件","pinyin":"gǎojiàn","vi":"bản thảo"},{"hanzi":"版税","pinyin":"bǎnshuì","vi":"tiền bản quyền"}]},{"id":"狗急跳墙","hanzi":"狗急跳墙","pinyin":"gǒují-tiàoqiáng","meaning_vi":"chó cùng rứt giậu","explanation":"狗急跳墙: chó bị dồn đến đường cùng thì nhảy qua tường → kẻ xấu bị dồn vào thế bí thì liều lĩnh làm càn; tương đương \"chó cùng rứt giậu\".","hsk_level":6,"tags":["thanh-ngu"],"image":"🐕","examples":[{"type":"basic","zh":"小心他狗急跳墙。","pinyin":"Xiǎoxīn tā gǒujítiàoqiáng.","vi":"Cẩn thận kẻo hắn chó cùng rứt giậu."},{"type":"simple","zh":"走投无路的劫匪狗急跳墙抓了人质。","pinyin":"Zǒutóuwúlù de jiéfěi gǒujítiàoqiáng zhuāle rénzhì.","vi":"Tên cướp cùng đường đã chó cùng rứt giậu bắt con tin."},{"type":"compound","zh":"如果把对手逼得太紧，他就可能狗急跳墙。","pinyin":"Rúguǒ bǎ duìshǒu bī de tài jǐn, tā jiù kěnéng gǒujítiàoqiáng.","vi":"Nếu dồn đối thủ quá gắt, hắn có thể chó cùng rứt giậu."}],"related":[{"hanzi":"铤而走险","pinyin":"tǐng'érzǒuxiǎn","vi":"liều lĩnh làm bừa"},{"hanzi":"走投无路","pinyin":"zǒutóuwúlù","vi":"cùng đường"},{"hanzi":"困兽犹斗","pinyin":"kùnshòuyóudòu","vi":"thú cùng còn cắn"},{"hanzi":"逼上梁山","pinyin":"bīshàngliángshān","vi":"bị dồn vào đường cùng"}],"traditional":"狗急跳牆"},{"id":"古怪","hanzi":"古怪","pinyin":"gǔguài","meaning_vi":"kỳ quặc, quái lạ","explanation":"古 (cổ – xưa) + 怪 (quái – lạ) → kỳ quặc, quái lạ, khác thường. Ví dụ: 脾气古怪 (tính khí kỳ quặc), 古怪的声音.","hsk_level":6,"tags":["tinh-tu"],"image":"🤪","examples":[{"type":"basic","zh":"这个老头脾气古怪。","pinyin":"Zhè ge lǎotóu píqi gǔguài.","vi":"Ông già này tính tình kỳ quặc."},{"type":"simple","zh":"半夜里阁楼上传来一阵古怪的声音。","pinyin":"Bàn yèli gé lóushang chuánlái yízhèn gǔguài de shēngyīn.","vi":"Nửa đêm trên gác mái vọng xuống một tràng âm thanh kỳ lạ."},{"type":"compound","zh":"虽然他的打扮有点儿古怪，但是人其实很热情。","pinyin":"Suīrán tā de dǎban yǒudiǎnr gǔguài, dànshì rén qíshí hěn rèqíng.","vi":"Tuy cách ăn mặc của anh ấy hơi kỳ quặc nhưng thực ra là người rất nhiệt tình."}],"related":[{"hanzi":"奇怪","pinyin":"qíguài","vi":"kỳ lạ"},{"hanzi":"稀奇古怪","pinyin":"xīqígǔguài","vi":"kỳ quái lạ lùng"},{"hanzi":"怪异","pinyin":"guàiyì","vi":"quái dị"},{"hanzi":"正常","pinyin":"zhèngcháng","vi":"bình thường"}]},{"id":"骨干","hanzi":"骨干","pinyin":"gǔgàn","meaning_vi":"cốt cán, nòng cốt","explanation":"骨 (cốt – xương) + 干 (cán – thân, cốt) → xương sống, người hoặc lực lượng nòng cốt. Ví dụ: 骨干力量, 业务骨干.","hsk_level":6,"tags":["danh-tu","cong-viec"],"image":"🌟","examples":[{"type":"basic","zh":"他是公司的业务骨干。","pinyin":"Tā shì gōngsī de yèwù gǔgàn.","vi":"Anh ấy là trụ cột nghiệp vụ của công ty."},{"type":"simple","zh":"学校选派了十名骨干教师去外地培训。","pinyin":"Xuéxiào xuǎnpàile shí míng gǔgàn jiàoshī qù wàidì péixùn.","vi":"Trường đã cử mười giáo viên nòng cốt đi tập huấn ở tỉnh khác."},{"type":"compound","zh":"因为几位技术骨干同时离职，所以项目进度受到了严重影响。","pinyin":"Yīnwèi jǐ wèi jìshù gǔgàn tóngshí lízhí, suǒyǐ xiàngmù jìndù shòudàole yánzhòng yǐngxiǎng.","vi":"Vì mấy nhân viên kỹ thuật nòng cốt cùng lúc nghỉ việc nên tiến độ dự án bị ảnh hưởng nghiêm trọng."}],"related":[{"hanzi":"核心","pinyin":"héxīn","vi":"hạt nhân"},{"hanzi":"主力","pinyin":"zhǔlì","vi":"chủ lực"},{"hanzi":"中坚","pinyin":"zhōngjiān","vi":"nòng cốt"},{"hanzi":"骨干力量","pinyin":"gǔgànlìliàng","vi":"lực lượng nòng cốt"}],"traditional":"骨幹"},{"id":"蛊惑","hanzi":"蛊惑","pinyin":"gǔhuò","meaning_vi":"mê hoặc, xúi giục làm điều xấu","explanation":"蛊 + 惑 (làm mê muội).","hsk_level":6,"tags":["dong-tu"],"image":"🐍","examples":[{"type":"basic","zh":"别被广告蛊惑了。","pinyin":"Bié bèi guǎnggào gǔhuò le.","vi":"Đừng để bị quảng cáo mê hoặc."},{"type":"simple","zh":"他被传销组织的谎言蛊惑了。","pinyin":"Tā bèi chuánxiāo zǔzhī de huǎngyán gǔhuò le.","vi":"Anh ấy bị lời dối trá của tổ chức đa cấp mê hoặc."},{"type":"compound","zh":"虽然有人蛊惑他去赌博，但是他坚决拒绝了。","pinyin":"Suīrán yǒurén gǔhuò tā qù dǔbó, dànshì tā jiānjué jùjué le.","vi":"Tuy có người xúi giục anh ấy đi đánh bạc, nhưng anh ấy đã kiên quyết từ chối."}],"related":[{"hanzi":"迷惑","pinyin":"míhuo","vi":"mê hoặc"},{"hanzi":"煽动","pinyin":"shāndòng","vi":"kích động"},{"hanzi":"诱惑","pinyin":"yòuhuò","vi":"cám dỗ"},{"hanzi":"蛊惑人心","pinyin":"gǔhuòrénxīn","vi":"mê hoặc lòng người"}],"traditional":"蠱惑"},{"id":"古朴","hanzi":"古朴","pinyin":"gǔpǔ","meaning_vi":"cổ kính mộc mạc","explanation":"古 (cổ xưa) + 朴 (giản dị).","hsk_level":6,"tags":["tinh-tu","van-hoa"],"image":"🏯","examples":[{"type":"basic","zh":"这座小镇很古朴。","pinyin":"Zhè zuò xiǎozhèn hěn gǔpǔ.","vi":"Thị trấn nhỏ này rất cổ kính mộc mạc."},{"type":"simple","zh":"奶奶家的木桌子样式古朴而结实。","pinyin":"Nǎinai jiā de mù zhuōzi yàngshì gǔpǔ ér jiēshi.","vi":"Cái bàn gỗ nhà bà nội kiểu dáng mộc mạc mà chắc chắn."},{"type":"compound","zh":"因为这家茶馆装修得很古朴，所以吸引了很多外国游客。","pinyin":"Yīnwèi zhè jiā cháguǎn zhuāngxiū de hěn gǔpǔ, suǒyǐ xīyǐnle hěn duō wàiguó yóukè.","vi":"Vì quán trà này được trang trí rất cổ kính mộc mạc nên đã thu hút nhiều du khách nước ngoài."}],"related":[{"hanzi":"朴素","pinyin":"pǔsù","vi":"giản dị"},{"hanzi":"古老","pinyin":"gǔlǎo","vi":"cổ xưa"},{"hanzi":"典雅","pinyin":"diǎnyǎ","vi":"trang nhã"},{"hanzi":"华丽","pinyin":"huálì","vi":"hoa lệ"}],"traditional":"古樸"},{"id":"骨肉相连","hanzi":"骨肉相连","pinyin":"gǔròu-xiānglián","meaning_vi":"máu mủ ruột rà gắn bó","explanation":"骨肉相连: xương (骨) và thịt (肉) liền nhau → quan hệ máu mủ ruột thịt, gắn bó không thể tách rời; cũng dùng cho quan hệ giữa các dân tộc, vùng miền.","hsk_level":6,"tags":["thanh-ngu","gia-dinh"],"image":"👨‍👩‍👧‍👦","examples":[{"type":"basic","zh":"我们骨肉相连。","pinyin":"Wǒmen gǔròuxiānglián.","vi":"Chúng ta là máu mủ ruột rà."},{"type":"simple","zh":"两岸同胞本来就是骨肉相连的一家人。","pinyin":"Liǎng'àn tóngbāo běnlái jiùshì gǔròuxiānglián de yìjiārén.","vi":"Đồng bào hai bờ vốn là người một nhà máu mủ ruột rà."},{"type":"compound","zh":"兄弟俩虽然吵过架，但毕竟骨肉相连，很快就和好了。","pinyin":"Xiōngdì liǎ suīrán chǎoguo jià, dàn bìjìng gǔròuxiānglián, hěn kuài jiù héhǎo le.","vi":"Hai anh em tuy từng cãi nhau, nhưng dù sao cũng là máu mủ ruột rà nên nhanh chóng làm lành."}],"related":[{"hanzi":"血浓于水","pinyin":"xuènóngyúshuǐ","vi":"máu chảy ruột mềm"},{"hanzi":"骨肉","pinyin":"gǔròu","vi":"ruột thịt"},{"hanzi":"亲人","pinyin":"qīnrén","vi":"người thân"},{"hanzi":"手足情深","pinyin":"shǒuzúqíngshēn","vi":"tình anh em sâu nặng"}],"traditional":"骨肉相連"},{"id":"古往今来","hanzi":"古往今来","pinyin":"gǔwǎng-jīnlái","meaning_vi":"từ xưa đến nay","explanation":"古往今来: xưa (古) qua (往) nay (今) lại (来) → từ xưa đến nay, suốt chiều dài lịch sử. Ví dụ: 古往今来的英雄.","hsk_level":6,"tags":["thanh-ngu","thoi-gian"],"image":"⏳","examples":[{"type":"basic","zh":"古往今来，英雄辈出。","pinyin":"Gǔwǎngjīnlái, yīngxióng bèichū.","vi":"Từ xưa đến nay, anh hùng xuất hiện lớp lớp."},{"type":"simple","zh":"古往今来，无数诗人都写过关于月亮的诗。","pinyin":"Gǔwǎngjīnlái, wúshù shīrén dōu xiě guoguān yú yuèliang de shī.","vi":"Từ xưa đến nay, vô số nhà thơ đã viết thơ về mặt trăng."},{"type":"compound","zh":"古往今来，只要肯努力学习，就有机会改变命运。","pinyin":"Gǔwǎngjīnlái, zhǐyào kěn nǔlì xuéxí, jiù yǒujī huì gǎibiàn mìngyùn.","vi":"Từ xưa đến nay, chỉ cần chịu khó học tập thì sẽ có cơ hội thay đổi số phận."}],"related":[{"hanzi":"自古以来","pinyin":"zìgǔyǐlái","vi":"từ xưa tới nay"},{"hanzi":"从古至今","pinyin":"cónggǔzhìjīn","vi":"từ cổ chí kim"},{"hanzi":"历来","pinyin":"lìlái","vi":"xưa nay"},{"hanzi":"古今中外","pinyin":"gǔjīnzhōngwài","vi":"xưa nay trong ngoài"}],"traditional":"古往今來"},{"id":"化肥","hanzi":"化肥","pinyin":"huàféi","meaning_vi":"phân bón hóa học","explanation":"化 (hóa – hóa học) + 肥 (phì – phân bón) → phân bón hóa học. Ví dụ: 施化肥 (bón phân), 化肥厂. Đối lập: 农家肥 (phân chuồng).","hsk_level":6,"tags":["danh-tu","thien-nhien"],"image":"🌱","examples":[{"type":"basic","zh":"农民在田里施化肥。","pinyin":"Nóngmín zài tián lǐ shī huàféi.","vi":"Nông dân đang bón phân hóa học trên ruộng."},{"type":"simple","zh":"这片菜地从来不用化肥和农药。","pinyin":"Zhè piàn càidì cóngláibú yòng huàféi hé nóngyào.","vi":"Mảnh vườn rau này chưa bao giờ dùng phân hóa học và thuốc trừ sâu."},{"type":"compound","zh":"如果化肥用得太多，土地就会变得越来越贫瘠。","pinyin":"Rúguǒ huàféi yòng de tài duō, tǔdì jiù huì biànde yuèláiyuè pínjí.","vi":"Nếu dùng quá nhiều phân hóa học, đất đai sẽ ngày càng cằn cỗi."}],"related":[{"hanzi":"肥料","pinyin":"féiliào","vi":"phân bón"},{"hanzi":"农药","pinyin":"nóngyào","vi":"thuốc trừ sâu"},{"hanzi":"有机肥","pinyin":"yǒujīféi","vi":"phân hữu cơ"},{"hanzi":"施肥","pinyin":"shīféi","vi":"bón phân"}]},{"id":"画龙点睛","hanzi":"画龙点睛","pinyin":"huàlóng-diǎnjīng","meaning_vi":"vẽ rồng điểm mắt (nét chấm phá quyết định linh hồn tác phẩm)","explanation":"画龙点睛: vẽ rồng rồi chấm mắt thì rồng bay đi (truyện Trương Tăng Do) → thêm một nét then chốt làm nội dung sống động, nổi bật hẳn lên.","hsk_level":6,"tags":["thanh-ngu"],"image":"🐉","examples":[{"type":"basic","zh":"这句话画龙点睛。","pinyin":"Zhè jù huà huàlóngdiǎnjīng.","vi":"Câu nói này chính là nét chấm phá điểm nhãn."},{"type":"simple","zh":"文章结尾这一句起到了画龙点睛的作用。","pinyin":"Wénzhāng jiéwěi zhè yíjù qǐdàole huàlóngdiǎnjīng de zuòyòng.","vi":"Câu cuối bài văn có tác dụng như vẽ rồng điểm mắt."},{"type":"compound","zh":"虽然她穿得很朴素，但是那条红围巾简直是画龙点睛之笔。","pinyin":"Suīrán tā chuān de hěn pǔsù, dànshì nà tiáo hóng wéijīn jiǎnzhí shì huà lóng diǎnjīngzhībǐ.","vi":"Tuy cô ấy ăn mặc giản dị, nhưng chiếc khăn quàng đỏ ấy đúng là nét điểm nhãn."}],"related":[{"hanzi":"点睛之笔","pinyin":"diǎnjīngzhībǐ","vi":"nét chấm phá"},{"hanzi":"画蛇添足","pinyin":"huàshétiānzú","vi":"vẽ rắn thêm chân"},{"hanzi":"关键","pinyin":"guānjiàn","vi":"then chốt"},{"hanzi":"锦上添花","pinyin":"jǐnshàngtiānhuā","vi":"thêu hoa trên gấm"}],"traditional":"畫龍點睛"},{"id":"化妆","hanzi":"化妆","pinyin":"huàzhuāng","meaning_vi":"trang điểm","explanation":"化 (hóa – biến đổi) + 妆 (trang – trang điểm) → trang điểm, hóa trang. Ví dụ: 化妆品 (mỹ phẩm), 化妆师, 化浓妆.","hsk_level":6,"tags":["dong-tu"],"image":"💄","examples":[{"type":"basic","zh":"她正在化妆。","pinyin":"Tā zhèngzài huàzhuāng.","vi":"Cô ấy đang trang điểm."},{"type":"simple","zh":"演员们在后台忙着化妆换衣服。","pinyin":"Yǎnyuánmen zài hòutái mángzhe huàzhuāng huànyīfu.","vi":"Các diễn viên đang tất bật trang điểm, thay đồ ở hậu trường."},{"type":"compound","zh":"她每天早上一起床就化妆，所以从来不素颜出门。","pinyin":"Tā měitiān zǎoshang yì qǐchuáng jiù huàzhuāng, suǒyǐ cóngláibú sùyán chūmén.","vi":"Mỗi sáng cô ấy vừa thức dậy là trang điểm ngay, nên chưa bao giờ để mặt mộc ra ngoài."}],"related":[{"hanzi":"化妆品","pinyin":"huàzhuāngpǐn","vi":"mỹ phẩm"},{"hanzi":"打扮","pinyin":"dǎban","vi":"ăn diện"},{"hanzi":"卸妆","pinyin":"xièzhuāng","vi":"tẩy trang"},{"hanzi":"口红","pinyin":"kǒuhóng","vi":"son môi"}],"traditional":"化妝"},{"id":"焕然一新","hanzi":"焕然一新","pinyin":"huànrán-yìxīn","meaning_vi":"đổi mới hoàn toàn, diện mạo mới tinh","explanation":"焕然一新: rực rỡ (焕然) hoàn toàn mới (一新) → thay đổi hẳn, diện mạo mới tinh. Hay dùng cho nhà cửa, thành phố sau khi sửa sang.","hsk_level":6,"tags":["thanh-ngu"],"image":"✨","examples":[{"type":"basic","zh":"教室焕然一新。","pinyin":"Jiàoshì huànrányìxīn.","vi":"Lớp học trông mới hẳn."},{"type":"simple","zh":"装修以后，这家老饭店焕然一新。","pinyin":"Zhuāngxiū yǐhòu, zhè jiālǎo fàndiàn huànrányìxīn.","vi":"Sau khi sửa sang, nhà hàng cũ này đã thay da đổi thịt."},{"type":"compound","zh":"我们把房间一打扫干净，整个家就焕然一新了。","pinyin":"Wǒmen bǎ fángjiān yì dǎsǎo gānjìng, zhěnggè jiā jiù huànrányìxīn le.","vi":"Chúng tôi vừa dọn sạch phòng, cả căn nhà liền trông mới tinh."}],"related":[{"hanzi":"面目一新","pinyin":"miànmùyìxīn","vi":"diện mạo mới"},{"hanzi":"耳目一新","pinyin":"ěrmùyìxīn","vi":"mới mẻ lạ lẫm"},{"hanzi":"崭新","pinyin":"zhǎnxīn","vi":"mới tinh"},{"hanzi":"破旧","pinyin":"pòjiù","vi":"cũ nát"}],"traditional":"煥然一新"},{"id":"华丽","hanzi":"华丽","pinyin":"huálì","meaning_vi":"hoa lệ, lộng lẫy","explanation":"华 (đẹp) + 丽 (diễm lệ).","hsk_level":6,"tags":["tinh-tu"],"image":"🏰","examples":[{"type":"basic","zh":"她的礼服很华丽。","pinyin":"Tā de lǐfú hěn huálì.","vi":"Bộ lễ phục của cô ấy rất lộng lẫy."},{"type":"simple","zh":"宫殿里挂着一盏华丽的水晶吊灯。","pinyin":"Gōngdiàn lǐ guàzhe yì zhǎn huálì de shuǐjīng diàodēng.","vi":"Trong cung điện treo một chiếc đèn chùm pha lê lộng lẫy."},{"type":"compound","zh":"这篇文章辞藻虽然华丽，但是内容非常空洞。","pinyin":"Zhè piān wénzhāng cízǎo suīrán huálì, dànshì nèiróng fēicháng kōngdòng.","vi":"Bài văn này tuy từ ngữ hoa mỹ nhưng nội dung rất rỗng tuếch."}],"related":[{"hanzi":"豪华","pinyin":"háohuá","vi":"xa hoa"},{"hanzi":"富丽堂皇","pinyin":"fùlìtánghuáng","vi":"lộng lẫy nguy nga"},{"hanzi":"朴素","pinyin":"pǔsù","vi":"giản dị"},{"hanzi":"美丽","pinyin":"měilì","vi":"xinh đẹp"}],"traditional":"華麗"},{"id":"绘声绘色","hanzi":"绘声绘色","pinyin":"huìshēng-huìsè","meaning_vi":"miêu tả sống động như thật","explanation":"绘声绘色: vẽ (绘) cả âm thanh (声) lẫn màu sắc (色) → kể chuyện, miêu tả sống động như thật. Ví dụ: 讲得绘声绘色.","hsk_level":6,"tags":["thanh-ngu"],"image":"🗣️","examples":[{"type":"basic","zh":"他讲得绘声绘色。","pinyin":"Tā jiǎng de huìshēnghuìsè.","vi":"Anh ấy kể rất sinh động."},{"type":"simple","zh":"爷爷绘声绘色地给孙子讲西游记的故事。","pinyin":"Yéye huìshēnghuìsè de gěi sūnzi jiǎng Xīyóujì de gùshi.","vi":"Ông kể cho cháu nghe chuyện Tây Du Ký sống động như thật."},{"type":"compound","zh":"因为她把旅途趣事讲得绘声绘色，所以大家都听入了迷。","pinyin":"Yīnwèi tā bǎ lǚtú qùshì jiǎng de huìshēnghuìsè, suǒyǐ dàjiā dōu tīng rùle mí.","vi":"Vì cô ấy kể chuyện thú vị trên đường đi sống động như thật nên mọi người đều nghe say mê."}],"related":[{"hanzi":"栩栩如生","pinyin":"xǔxǔrúshēng","vi":"sống động như thật"},{"hanzi":"活灵活现","pinyin":"huólínghuóxiàn","vi":"sinh động như thật"},{"hanzi":"生动","pinyin":"shēngdòng","vi":"sinh động"},{"hanzi":"枯燥","pinyin":"kūzào","vi":"khô khan"}],"traditional":"繪聲繪色"},{"id":"会晤","hanzi":"会晤","pinyin":"huìwù","meaning_vi":"hội đàm, gặp gỡ cấp cao","explanation":"会 (hội – gặp) + 晤 (ngộ – gặp mặt) → hội kiến, gặp gỡ chính thức, thường giữa lãnh đạo cấp cao. Ví dụ: 两国领导人会晤.","hsk_level":6,"tags":["dong-tu"],"image":"🤝","examples":[{"type":"basic","zh":"两国领导人举行会晤。","pinyin":"Liǎngguó lǐngdǎorén jǔxíng huìwù.","vi":"Lãnh đạo hai nước tổ chức hội đàm."},{"type":"simple","zh":"双方外长将于下周在北京会晤。","pinyin":"Shuāngfāng wàizhǎng jiāng yú xiàzhōu zài Běijīng huìwù.","vi":"Ngoại trưởng hai bên sẽ hội đàm tại Bắc Kinh vào tuần tới."},{"type":"compound","zh":"这次会晤虽然时间不长，但是双方达成了多项共识。","pinyin":"Zhè cì huìwù suīrán shíjiān bù cháng, dànshì shuāngfāng dáchéngle duōxiàng gòngshí.","vi":"Cuộc hội đàm này tuy không dài nhưng hai bên đã đạt được nhiều đồng thuận."}],"related":[{"hanzi":"会见","pinyin":"huìjiàn","vi":"hội kiến"},{"hanzi":"会谈","pinyin":"huìtán","vi":"hội đàm"},{"hanzi":"峰会","pinyin":"fēnghuì","vi":"hội nghị thượng đỉnh"},{"hanzi":"接见","pinyin":"jiējiàn","vi":"tiếp kiến"}],"traditional":"會晤"},{"id":"回避","hanzi":"回避","pinyin":"huíbì","meaning_vi":"né tránh, lẩn tránh","explanation":"回 (hồi – quay lại) + 避 (tị – tránh) → né tránh, lẩn tránh. Ví dụ: 回避问题, 回避矛盾; trong luật: 回避 = tự rút lui khỏi vụ việc có liên quan.","hsk_level":6,"tags":["dong-tu"],"image":"🙈","examples":[{"type":"basic","zh":"他总是回避我的问题。","pinyin":"Tā zǒngshì huíbì wǒ de wèntí.","vi":"Anh ấy luôn né tránh câu hỏi của tôi."},{"type":"simple","zh":"作为被告的亲戚，这位法官依法应当回避。","pinyin":"Zuòwéi bèigào de qīnqi, zhè wèi fǎguān yīfǎ yīngdāng huíbì.","vi":"Là họ hàng của bị cáo, vị thẩm phán này theo luật phải rút khỏi vụ xét xử."},{"type":"compound","zh":"与其一直回避矛盾，不如坐下来好好谈一谈。","pinyin":"Yǔqí yìzhí huíbì máodùn, bùrú zuò xiàlái hǎohǎo tán yi tán.","vi":"Thay vì cứ né tránh mâu thuẫn, chi bằng ngồi xuống nói chuyện đàng hoàng."}],"related":[{"hanzi":"躲避","pinyin":"duǒbì","vi":"né tránh"},{"hanzi":"逃避","pinyin":"táobì","vi":"trốn tránh"},{"hanzi":"面对","pinyin":"miànduì","vi":"đối mặt"},{"hanzi":"避免","pinyin":"bìmiǎn","vi":"tránh khỏi"}],"traditional":"迴避"},{"id":"回味无穷","hanzi":"回味无穷","pinyin":"huíwèi-wúqióng","meaning_vi":"dư vị vô tận (món ăn ngon hoặc tác phẩm hay)","explanation":"回味无穷: dư vị (回味) không cùng (无穷) → ăn xong vẫn còn thấy ngon; nghĩa bóng: tác phẩm, lời nói càng nghĩ càng thấy hay.","hsk_level":6,"tags":["thanh-ngu"],"image":"😋","examples":[{"type":"basic","zh":"这道菜回味无穷。","pinyin":"Zhè dào cài huíwèiwúqióng.","vi":"Món này để lại dư vị khó quên."},{"type":"simple","zh":"外婆做的红烧肉让我至今回味无穷。","pinyin":"Wàipó zuò de hóngshāoròu ràng wǒ zhìjīn huíwèiwúqióng.","vi":"Món thịt kho của bà ngoại khiến tôi đến giờ vẫn nhớ mãi dư vị."},{"type":"compound","zh":"这部电影不但情节感人，而且结尾回味无穷。","pinyin":"Zhè bù diànyǐng búdàn qíngjié gǎnrén, érqiě jiéwěi huíwèiwúqióng.","vi":"Bộ phim này không những tình tiết cảm động mà phần kết còn để lại dư vị vô tận."}],"related":[{"hanzi":"意味深长","pinyin":"yìwèishēncháng","vi":"ý vị sâu xa"},{"hanzi":"余味","pinyin":"yúwèi","vi":"dư vị"},{"hanzi":"津津有味","pinyin":"jīnjīnyǒuwèi","vi":"ngon lành thích thú"},{"hanzi":"索然无味","pinyin":"suǒránwúwèi","vi":"nhạt nhẽo vô vị"}],"traditional":"回味無窮"},{"id":"豁然开朗","hanzi":"豁然开朗","pinyin":"huòrán-kāilǎng","meaning_vi":"bừng sáng, chợt hiểu thông suốt","explanation":"豁然开朗: bỗng (豁然) trở nên rộng mở sáng sủa (开朗), từ Đào Hoa Nguyên Ký → cảnh vật bỗng mở ra; nghĩa bóng: chợt hiểu ra, thông suốt.","hsk_level":6,"tags":["thanh-ngu"],"image":"💡","examples":[{"type":"basic","zh":"我顿时豁然开朗。","pinyin":"Wǒ dùnshí huòránkāilǎng.","vi":"Tôi bỗng chốc sáng tỏ mọi điều."},{"type":"simple","zh":"穿过狭窄的山洞，眼前豁然开朗。","pinyin":"Chuānguò xiázhǎi de shāndòng, yǎnqián huòránkāilǎng.","vi":"Đi qua hang núi chật hẹp, trước mắt bỗng mở ra một khoảng rộng sáng sủa."},{"type":"compound","zh":"老师一点拨，我就豁然开朗，终于明白了这道题。","pinyin":"Lǎoshī yì diǎnbō, wǒ jiù huòránkāilǎng, zhōngyú míngbaile zhè dào tí.","vi":"Thầy vừa gợi ý, tôi liền sáng tỏ, cuối cùng đã hiểu bài này."}],"related":[{"hanzi":"恍然大悟","pinyin":"huǎngrándàwù","vi":"chợt hiểu ra"},{"hanzi":"茅塞顿开","pinyin":"máosèdùnkāi","vi":"bỗng thông suốt"},{"hanzi":"开朗","pinyin":"kāilǎng","vi":"thoáng đãng, cởi mở"},{"hanzi":"百思不解","pinyin":"bǎisībùjiě","vi":"nghĩ mãi không ra"}],"traditional":"豁然開朗"},{"id":"货真价实","hanzi":"货真价实","pinyin":"huòzhēn-jiàshí","meaning_vi":"hàng thật giá thật","explanation":"货真价实: hàng (货) thật (真), giá (价) thật (实) → hàng thật giá phải chăng; nghĩa bóng: thật sự, đích thực, không giả.","hsk_level":6,"tags":["thanh-ngu","mua-sam"],"image":"✅","examples":[{"type":"basic","zh":"这家店货真价实。","pinyin":"Zhè jiā diàn huòzhēnjiàshí.","vi":"Cửa hàng này hàng thật giá thật."},{"type":"simple","zh":"这些蜂蜜都是货真价实的农家土产。","pinyin":"Zhèxiē fēngmì dōu shì huòzhēnjiàshí de nóngjiā tǔchǎn.","vi":"Chỗ mật ong này đều là đặc sản nhà nông thật trăm phần trăm."},{"type":"compound","zh":"因为老板一向货真价实，所以回头客特别多。","pinyin":"Yīnwèi lǎobǎn yíxiàng huòzhēnjiàshí, suǒyǐ huítóukè tèbié duō.","vi":"Vì ông chủ luôn bán hàng thật giá thật nên khách quay lại rất đông."}],"related":[{"hanzi":"名副其实","pinyin":"míngfùqíshí","vi":"danh xứng với thực"},{"hanzi":"物美价廉","pinyin":"wùměijiàlián","vi":"hàng tốt giá rẻ"},{"hanzi":"假冒伪劣","pinyin":"jiǎmàowěiliè","vi":"hàng giả kém chất lượng"},{"hanzi":"正品","pinyin":"zhèngpǐn","vi":"hàng chính hãng"}],"traditional":"貨真價實"},{"id":"活该","hanzi":"活该","pinyin":"huógāi","meaning_vi":"đáng đời","explanation":"活 (hoạt – sống) + 该 (cai – đáng) → đáng đời, đáng bị như vậy (giọng khẩu ngữ, trách móc). Ví dụ: 活该! 谁让你不听话.","hsk_level":6,"tags":["dong-tu"],"image":"😒","examples":[{"type":"basic","zh":"他活该被骂。","pinyin":"Tā huógāi bèi mà.","vi":"Anh ta đáng bị mắng."},{"type":"simple","zh":"考试作弊被抓的那个学生活该受罚。","pinyin":"Kǎoshì zuòbì bèi zhuā de nà ge xuésheng huógāi shòu fá.","vi":"Cậu học sinh gian lận thi cử bị bắt đó đáng bị phạt."},{"type":"compound","zh":"既然你不听大家的劝告，那么现在吃亏也是活该。","pinyin":"Jìrán nǐ bù tīng dàjiā de quàngào, nàme xiànzài chīkuī yě shì huógāi.","vi":"Đã không nghe lời khuyên của mọi người thì giờ chịu thiệt cũng là đáng đời."}],"related":[{"hanzi":"罪有应得","pinyin":"zuìyǒuyīngdé","vi":"tội đáng phải chịu"},{"hanzi":"自作自受","pinyin":"zìzuòzìshòu","vi":"gieo gió gặt bão"},{"hanzi":"应该","pinyin":"yīnggāi","vi":"nên, đáng"},{"hanzi":"报应","pinyin":"bàoyìng","vi":"quả báo"}],"traditional":"活該"},{"id":"花言巧语","hanzi":"花言巧语","pinyin":"huāyán-qiǎoyǔ","meaning_vi":"lời nói hoa mỹ xảo trá","explanation":"花言巧语: lời (言) hoa mỹ (花), lời (语) khéo léo (巧) → lời lẽ đường mật, dối trá để lừa người. Mang nghĩa xấu.","hsk_level":6,"tags":["thanh-ngu"],"image":"🤥","examples":[{"type":"basic","zh":"别信他的花言巧语。","pinyin":"Bié xìn tā de huāyánqiǎoyǔ.","vi":"Đừng tin những lời đường mật của hắn."},{"type":"simple","zh":"骗子用花言巧语骗走了老人的积蓄。","pinyin":"Piànzi yòng huāyánqiǎoyǔ piànzǒule lǎorén de jīxù.","vi":"Kẻ lừa đảo dùng lời ngon ngọt lừa lấy hết tiền tiết kiệm của cụ già."},{"type":"compound","zh":"即使他再花言巧语，她也不会再上当了。","pinyin":"Jíshǐ tā zài huāyánqiǎoyǔ, tā yě bú huì zài shàngdàng le.","vi":"Dù anh ta có ăn nói ngon ngọt đến đâu, cô ấy cũng sẽ không mắc lừa nữa."}],"related":[{"hanzi":"甜言蜜语","pinyin":"tiányánmìyǔ","vi":"lời ngon tiếng ngọt"},{"hanzi":"油嘴滑舌","pinyin":"yóuzuǐhuáshé","vi":"mồm mép trơn tru"},{"hanzi":"忠言逆耳","pinyin":"zhōngyánnì'ěr","vi":"lời thật mất lòng"},{"hanzi":"巧言令色","pinyin":"qiǎoyánlìngsè","vi":"khéo nói nịnh nọt"}],"traditional":"花言巧語"},{"id":"欢乐","hanzi":"欢乐","pinyin":"huānlè","meaning_vi":"vui vẻ, hân hoan","explanation":"欢 (hoan – vui mừng) + 乐 (lạc – vui) → vui vẻ, hân hoan, rộn ràng. Ví dụ: 欢乐的气氛, 带来欢乐. Văn viết hơn 快乐.","hsk_level":6,"tags":["tinh-tu"],"image":"🥳","examples":[{"type":"basic","zh":"大家欢乐地唱歌。","pinyin":"Dàjiā huānlè de chànggē.","vi":"Mọi người vui vẻ ca hát."},{"type":"simple","zh":"公园里传来孩子们欢乐的笑声。","pinyin":"Gōngyuán lǐ chuánlái háizimen huānlè de xiàoshēng.","vi":"Trong công viên vọng ra tiếng cười vui vẻ của lũ trẻ."},{"type":"compound","zh":"只要全家人在一起，再简单的晚餐也充满欢乐。","pinyin":"Zhǐyào quán jiārén zài yìqǐ, zài jiǎndān de wǎncān yě chōngmǎn huānlè.","vi":"Chỉ cần cả nhà ở bên nhau, bữa tối đơn giản đến mấy cũng tràn đầy niềm vui."}],"related":[{"hanzi":"快乐","pinyin":"kuàilè","vi":"vui vẻ"},{"hanzi":"欢快","pinyin":"huānkuài","vi":"vui tươi"},{"hanzi":"悲伤","pinyin":"bēishāng","vi":"buồn bã"},{"hanzi":"欢声笑语","pinyin":"huānshēngxiàoyǔ","vi":"tiếng cười nói vui vẻ"}],"traditional":"歡樂"},{"id":"欢天喜地","hanzi":"欢天喜地","pinyin":"huāntiān-xǐdì","meaning_vi":"vui mừng khôn xiết","explanation":"欢天喜地: vui mừng đến trời (天) đất (地) → vui mừng khôn xiết, hớn hở ra mặt. Ví dụ: 孩子们欢天喜地地过新年.","hsk_level":6,"tags":["thanh-ngu"],"image":"🥳","examples":[{"type":"basic","zh":"孩子们欢天喜地。","pinyin":"Háizimen huāntiānxǐdì.","vi":"Lũ trẻ vui mừng hớn hở."},{"type":"simple","zh":"全村人欢天喜地地迎接新娘进门。","pinyin":"Quán cūn rén huāntiānxǐdì de yíngjiē xīnniáng jìnmén.","vi":"Cả làng vui mừng khôn xiết đón cô dâu về nhà."},{"type":"compound","zh":"一听说明天放假，同学们就欢天喜地地跑出了教室。","pinyin":"Yì tīngshuō míngtiān fàngjià, tóngxuémen jiù huāntiānxǐdì de pǎochūle jiàoshì.","vi":"Vừa nghe nói mai được nghỉ, các bạn học liền vui mừng hớn hở chạy ra khỏi lớp."}],"related":[{"hanzi":"兴高采烈","pinyin":"xìnggāocǎiliè","vi":"hớn hở vui mừng"},{"hanzi":"喜气洋洋","pinyin":"xǐqìyángyáng","vi":"vui mừng hớn hở"},{"hanzi":"垂头丧气","pinyin":"chuítóusàngqì","vi":"ủ rũ chán nản"},{"hanzi":"欢喜","pinyin":"huānxǐ","vi":"vui mừng"}],"traditional":"歡天喜地"},{"id":"荒谬","hanzi":"荒谬","pinyin":"huāngmiù","meaning_vi":"hoang đường, vô lý","explanation":"荒 (hoang – hoang đường) + 谬 (mậu – sai lầm) → hoang đường, vô lý hết sức. Ví dụ: 荒谬的说法, 荒谬可笑.","hsk_level":6,"tags":["tinh-tu"],"image":"🤪","examples":[{"type":"basic","zh":"这种说法很荒谬。","pinyin":"Zhè zhǒng shuōfǎ hěn huāngmiù.","vi":"Cách nói này thật hoang đường."},{"type":"simple","zh":"他提出了一个荒谬的理由来推卸责任。","pinyin":"Tā tíchūle yí gè huāngmiù de lǐ yóulái tuīxiè zérèn.","vi":"Anh ta đưa ra một lý do vô lý để đùn đẩy trách nhiệm."},{"type":"compound","zh":"这个结论听起来虽然荒谬，但是实验数据确实如此。","pinyin":"Zhè ge jiélùn tīngqǐlái suīrán huāngmiù, dànshì shíyànshùjù quèshí rúcǐ.","vi":"Kết luận này nghe thì vô lý, nhưng số liệu thí nghiệm quả thật là như vậy."}],"related":[{"hanzi":"荒唐","pinyin":"huāngtáng","vi":"hoang đường"},{"hanzi":"谬论","pinyin":"miùlùn","vi":"lý lẽ sai lầm"},{"hanzi":"合理","pinyin":"hélǐ","vi":"hợp lý"},{"hanzi":"荒诞","pinyin":"huāngdàn","vi":"hoang đản"}],"traditional":"荒謬"},{"id":"荒无人烟","hanzi":"荒无人烟","pinyin":"huāngwú-rényān","meaning_vi":"hoang vắng không một bóng người","explanation":"荒无人烟: hoang vu (荒), không (无) có khói bếp nhà người (人烟) → vùng hoang vắng không một bóng người.","hsk_level":6,"tags":["thanh-ngu"],"image":"🏜️","examples":[{"type":"basic","zh":"这里荒无人烟。","pinyin":"Zhèlǐ huāngwúrényān.","vi":"Nơi đây hoang vắng không một bóng người."},{"type":"simple","zh":"他们的车在荒无人烟的沙漠里抛锚了。","pinyin":"Tāmen de chē zài huāngwúrényān de shāmò lǐ pāomáo le.","vi":"Xe của họ chết máy giữa sa mạc hoang vắng không một bóng người."},{"type":"compound","zh":"虽然那个小岛荒无人烟，但是风景美得让人惊叹。","pinyin":"Suīrán nà ge xiǎodǎo huāngwúrényān, dànshì fēngjǐng měi de ràng rén jīngtàn.","vi":"Tuy hòn đảo nhỏ ấy không một bóng người, nhưng phong cảnh đẹp đến kinh ngạc."}],"related":[{"hanzi":"人迹罕至","pinyin":"rénjìhǎnzhì","vi":"ít dấu chân người"},{"hanzi":"荒凉","pinyin":"huāngliáng","vi":"hoang vắng"},{"hanzi":"人山人海","pinyin":"rénshānrénhǎi","vi":"người đông như kiến"},{"hanzi":"荒野","pinyin":"huāngyě","vi":"đồng hoang"}],"traditional":"荒無人煙"},{"id":"辉煌","hanzi":"辉煌","pinyin":"huīhuáng","meaning_vi":"huy hoàng, rực rỡ","explanation":"辉 (huy – ánh sáng) + 煌 (hoàng – sáng rực) → huy hoàng, rực rỡ. Ví dụ: 辉煌的成就, 灯火辉煌, 再创辉煌.","hsk_level":6,"tags":["tinh-tu"],"image":"🌟","examples":[{"type":"basic","zh":"城市灯火辉煌。","pinyin":"Chéngshì dēnghuǒhuīhuáng.","vi":"Thành phố đèn đuốc rực rỡ."},{"type":"simple","zh":"这支球队曾经创造过辉煌的历史。","pinyin":"Zhè zhī qiúduì céngjīng chuàngzàoguo huīhuáng de lìshǐ.","vi":"Đội bóng này từng làm nên lịch sử huy hoàng."},{"type":"compound","zh":"公司虽然有过辉煌的过去，但是现在面临着严重危机。","pinyin":"Gōngsī suīrán yǒuguo huīhuáng de guòqù, dànshì xiànzài miànlínzhe yánzhòng wēijī.","vi":"Công ty tuy từng có quá khứ huy hoàng nhưng hiện đang đối mặt với khủng hoảng nghiêm trọng."}],"related":[{"hanzi":"灿烂","pinyin":"cànlàn","vi":"rực rỡ"},{"hanzi":"光辉","pinyin":"guānghuī","vi":"huy hoàng"},{"hanzi":"金碧辉煌","pinyin":"jīnbìhuīhuáng","vi":"vàng son lộng lẫy"},{"hanzi":"暗淡","pinyin":"àndàn","vi":"ảm đạm"}],"traditional":"輝煌"},{"id":"灰心丧气","hanzi":"灰心丧气","pinyin":"huīxīn-sàngqì","meaning_vi":"nản lòng nhụt chí","explanation":"灰心丧气: lòng (心) nguội như tro (灰), mất (丧) tinh thần (气) → nản lòng thoái chí, chán nản sau thất bại.","hsk_level":6,"tags":["thanh-ngu"],"image":"😞","examples":[{"type":"basic","zh":"别灰心丧气。","pinyin":"Bié huīxīnsàngqì.","vi":"Đừng nản lòng nhụt chí."},{"type":"simple","zh":"落榜以后，他整天灰心丧气地待在家里。","pinyin":"Luòbǎng yǐhòu, tā zhěngtiān huīxīnsàngqì de dāi zài jiālǐ.","vi":"Sau khi thi trượt, cậu ấy cả ngày ủ rũ nản chí ở nhà."},{"type":"compound","zh":"即使比赛输了，我们也不应该灰心丧气。","pinyin":"Jíshǐ bǐsài shū le, wǒmen yě bù yīnggāi huīxīnsàngqì.","vi":"Dù có thua trận, chúng ta cũng không nên nản lòng nhụt chí."}],"related":[{"hanzi":"垂头丧气","pinyin":"chuítóusàngqì","vi":"ủ rũ chán nản"},{"hanzi":"灰心","pinyin":"huīxīn","vi":"nản lòng"},{"hanzi":"心灰意冷","pinyin":"xīnhuīyìlěng","vi":"chán chường thất vọng"},{"hanzi":"意气风发","pinyin":"yìqìfēngfā","vi":"hăng hái phấn chấn"}],"traditional":"灰心喪氣"},{"id":"缓和","hanzi":"缓和","pinyin":"huǎnhé","meaning_vi":"hòa hoãn, dịu lại","explanation":"缓 (hoãn – chậm) + 和 (hòa – êm dịu) → làm dịu, hòa hoãn (căng thẳng, quan hệ, xung đột). Ví dụ: 缓和气氛, 局势缓和.","hsk_level":6,"tags":["dong-tu"],"image":"🕊️","examples":[{"type":"basic","zh":"他讲个笑话缓和气氛。","pinyin":"Tā jiǎng gè xiàohua huǎnhé qìfēn.","vi":"Anh ấy kể chuyện cười để làm dịu bầu không khí."},{"type":"simple","zh":"两国关系最近有所缓和。","pinyin":"Liǎngguó guānxì zuìjìn yǒusuǒ huǎnhé.","vi":"Quan hệ hai nước gần đây đã phần nào dịu bớt."},{"type":"compound","zh":"只要双方都退让一步，紧张的局势就会缓和。","pinyin":"Zhǐyào shuāngfāng dōu tuìràng yí bù, jǐnzhāng de júshì jiù huì huǎnhé.","vi":"Chỉ cần hai bên đều nhượng bộ một bước, tình hình căng thẳng sẽ dịu đi."}],"related":[{"hanzi":"缓解","pinyin":"huǎnjiě","vi":"xoa dịu"},{"hanzi":"和缓","pinyin":"héhuǎn","vi":"ôn hòa"},{"hanzi":"紧张","pinyin":"jǐnzhāng","vi":"căng thẳng"},{"hanzi":"激化","pinyin":"jīhuà","vi":"trở nên gay gắt"}],"traditional":"緩和"},{"id":"悔恨","hanzi":"悔恨","pinyin":"huǐhèn","meaning_vi":"hối hận, ân hận","explanation":"悔 (hối – hối) + 恨 (hận – hận, tiếc) → hối hận, ân hận, tự trách mình. Ví dụ: 悔恨不已, 悔恨的泪水. Nặng hơn 后悔.","hsk_level":6,"tags":["dong-tu"],"image":"😣","examples":[{"type":"basic","zh":"他悔恨不已。","pinyin":"Tā huǐhèn bùyǐ.","vi":"Anh ấy hối hận khôn nguôi."},{"type":"simple","zh":"他为年轻时犯下的错误悔恨了一辈子。","pinyin":"Tā wèi niánqīng shí fàn xià de cuòwù huǐhènle yíbèizi.","vi":"Ông ấy hối hận cả đời vì sai lầm thời trẻ."},{"type":"compound","zh":"与其事后悔恨，不如现在就好好珍惜家人。","pinyin":"Yǔqí shìhòu huǐhèn, bùrú xiànzài jiù hǎohǎo zhēnxī jiārén.","vi":"Thay vì sau này hối hận, chi bằng ngay bây giờ hãy trân trọng gia đình."}],"related":[{"hanzi":"后悔","pinyin":"hòuhuǐ","vi":"hối hận"},{"hanzi":"懊悔","pinyin":"àohuǐ","vi":"ân hận"},{"hanzi":"悔过","pinyin":"huǐguò","vi":"hối lỗi"},{"hanzi":"追悔莫及","pinyin":"zhuīhuǐmòjí","vi":"hối hận không kịp"}]},{"id":"火药","hanzi":"火药","pinyin":"huǒyào","meaning_vi":"thuốc súng","explanation":"火 (hỏa – lửa) + 药 (dược – thuốc) → thuốc súng, một trong tứ đại phát minh của Trung Quốc cổ đại. Ví dụ: 火药味 (mùi thuốc súng, không khí căng thẳng).","hsk_level":6,"tags":["danh-tu","van-hoa"],"image":"🧨","examples":[{"type":"basic","zh":"火药是中国发明的。","pinyin":"Huǒyào shì Zhōngguó fāmíng de.","vi":"Thuốc súng do Trung Quốc phát minh."},{"type":"simple","zh":"古人用硫磺、硝石和木炭制成火药。","pinyin":"Gǔrén yòng liúhuáng, xiāoshí hé mùtàn zhìchéng huǒyào.","vi":"Người xưa dùng lưu huỳnh, diêm tiêu và than gỗ để chế ra thuốc súng."},{"type":"compound","zh":"火药不但用来制作烟花，而且改变了古代战争的方式。","pinyin":"Huǒyào búdàn yònglái zhìzuò yānhuā, érqiě gǎibiànle gǔdài zhànzhēng de fāngshì.","vi":"Thuốc súng không chỉ dùng để làm pháo hoa mà còn thay đổi cách thức chiến tranh thời cổ."}],"related":[{"hanzi":"炸药","pinyin":"zhàyào","vi":"thuốc nổ"},{"hanzi":"四大发明","pinyin":"sìdàfāmíng","vi":"bốn phát minh lớn"},{"hanzi":"火药味","pinyin":"huǒyàowèi","vi":"mùi thuốc súng"},{"hanzi":"鞭炮","pinyin":"biānpào","vi":"pháo"}],"traditional":"火藥"},{"id":"汗流浃背","hanzi":"汗流浃背","pinyin":"hànliú-jiābèi","meaning_vi":"mồ hôi nhễ nhại ướt đẫm lưng","explanation":"汗流浃背: mồ hôi (汗) chảy (流) ướt đẫm (浃) lưng (背) → mồ hôi nhễ nhại; vốn còn chỉ sợ hãi hoặc xấu hổ đến toát mồ hôi.","hsk_level":6,"tags":["thanh-ngu"],"image":"💦","examples":[{"type":"basic","zh":"他热得汗流浃背。","pinyin":"Tā rè de hànliújiābèi.","vi":"Anh ấy nóng đến mồ hôi ướt đẫm lưng."},{"type":"simple","zh":"工人们在烈日下搬砖，个个汗流浃背。","pinyin":"Gōngrénmen zài lièrì xià bānzhuān, gègè hànliújiābèi.","vi":"Công nhân khuân gạch dưới nắng gắt, ai nấy mồ hôi nhễ nhại."},{"type":"compound","zh":"虽然只跑了三公里，但是我已经汗流浃背了。","pinyin":"Suīrán zhǐ pǎole sān gōnglǐ, dànshì wǒ yǐjīng hànliújiābèi le.","vi":"Tuy mới chạy ba cây số, nhưng tôi đã mồ hôi ướt đẫm lưng."}],"related":[{"hanzi":"大汗淋漓","pinyin":"dàhànlínlí","vi":"mồ hôi đầm đìa"},{"hanzi":"满头大汗","pinyin":"mǎntóudàhàn","vi":"mồ hôi đầy đầu"},{"hanzi":"出汗","pinyin":"chūhàn","vi":"ra mồ hôi"},{"hanzi":"汗水","pinyin":"hànshuǐ","vi":"mồ hôi"}],"traditional":"汗流浹背"},{"id":"好高骛远","hanzi":"好高骛远","pinyin":"hàogāo-wùyuǎn","meaning_vi":"mơ cao vọng xa, viển vông không thực tế","explanation":"好 (đọc hào - thích) + 高 + 骛远. Thành ngữ.","hsk_level":6,"tags":["thanh-ngu"],"image":"☁️","examples":[{"type":"basic","zh":"做事不能好高骛远。","pinyin":"Zuòshì bù néng hàogāowùyuǎn.","vi":"Làm việc không được mơ cao vọng xa."},{"type":"simple","zh":"刚毕业的他有点好高骛远，看不上普通工作。","pinyin":"Gāng bìyè de tā yǒudiǎn hàogāowùyuǎn, kàn bu shàng pǔtōng gōngzuò.","vi":"Vừa tốt nghiệp, cậu ấy hơi mơ mộng viển vông, chê công việc bình thường."},{"type":"compound","zh":"如果总是好高骛远，就永远学不好基础知识。","pinyin":"Rúguǒ zǒngshì hàogāowùyuǎn, jiù yǒngyuǎn xué bu hǎo jīchǔ zhīshi.","vi":"Nếu cứ mơ cao vọng xa thì sẽ mãi không học tốt kiến thức cơ bản."}],"related":[{"hanzi":"眼高手低","pinyin":"yǎngāoshǒudī","vi":"mắt cao tay thấp"},{"hanzi":"不切实际","pinyin":"búqièshíjì","vi":"không thực tế"},{"hanzi":"脚踏实地","pinyin":"jiǎotàshídì","vi":"chân đạp đất thật"},{"hanzi":"异想天开","pinyin":"yìxiǎngtiānkāi","vi":"nghĩ chuyện viển vông"}],"traditional":"好高騖遠"},{"id":"浩瀚","hanzi":"浩瀚","pinyin":"hàohàn","meaning_vi":"mênh mông, bao la (biển cả/vũ trụ/sách vở)","explanation":"Cả hai chữ đều có bộ thủy 氵.","hsk_level":6,"tags":["tinh-tu"],"image":"🌌","examples":[{"type":"basic","zh":"宇宙浩瀚无边。","pinyin":"Yǔzhòu hàohàn wúbiān.","vi":"Vũ trụ bao la vô tận."},{"type":"simple","zh":"他每天都沉浸在浩瀚的书海里。","pinyin":"Tā měitiān dōu chénjìn zài hàohàn de shū hǎilǐ.","vi":"Ngày nào anh ấy cũng đắm chìm trong biển sách mênh mông."},{"type":"compound","zh":"站在海边望着浩瀚的大海，我觉得自己既渺小又幸运。","pinyin":"Zhàn zài hǎibiān wàngzhe hàohàn de dàhǎi, wǒ juéde zìjǐ jì miǎoxiǎo yòu xìngyùn.","vi":"Đứng bên bờ nhìn biển cả mênh mông, tôi thấy mình vừa nhỏ bé vừa may mắn."}],"related":[{"hanzi":"广阔","pinyin":"guǎngkuò","vi":"rộng lớn"},{"hanzi":"辽阔","pinyin":"liáokuò","vi":"bao la"},{"hanzi":"无边无际","pinyin":"wúbiānwújì","vi":"mênh mông vô bờ"},{"hanzi":"浩如烟海","pinyin":"hàorúyānhǎi","vi":"nhiều như khói biển"}]},{"id":"浩浩荡荡","hanzi":"浩浩荡荡","pinyin":"hàohào-dàngdàng","meaning_vi":"hùng dũng rầm rộ (đoàn người/dòng sông)","explanation":"浩浩荡荡: (nước) mênh mông cuồn cuộn → khí thế lớn lao hùng vĩ; thường tả đoàn người, đoàn quân đông đảo rầm rộ.","hsk_level":6,"tags":["thanh-ngu"],"image":"🌊","examples":[{"type":"basic","zh":"大军浩浩荡荡出发。","pinyin":"Dàjūn hàohàodàngdàng chūfā.","vi":"Đại quân rầm rộ xuất phát."},{"type":"simple","zh":"长江浩浩荡荡地向东流去。","pinyin":"Chángjiāng hàohàodàngdàng de xiàng dōng liú qù.","vi":"Sông Trường Giang cuồn cuộn chảy về phía đông."},{"type":"compound","zh":"游行队伍一出发，就浩浩荡荡地穿过了整条大街。","pinyin":"Yóuxíng duìwu yì chūfā, jiù hàohàodàngdàng de chuānguòle zhěngtiáo dàjiē.","vi":"Đoàn diễu hành vừa xuất phát đã rầm rộ đi qua cả con phố."}],"related":[{"hanzi":"声势浩大","pinyin":"shēngshìhàodà","vi":"thanh thế lớn mạnh"},{"hanzi":"浩荡","pinyin":"hàodàng","vi":"cuồn cuộn mênh mông"},{"hanzi":"气势磅礴","pinyin":"qìshìpángbó","vi":"khí thế hùng vĩ"},{"hanzi":"队伍","pinyin":"duìwu","vi":"đoàn người"}],"traditional":"浩浩蕩蕩"},{"id":"寒暄","hanzi":"寒暄","pinyin":"hánxuān","meaning_vi":"hàn huyên","explanation":"寒 (hàn – lạnh) + 暄 (huyên – ấm) → hỏi han chuyện nóng lạnh: chào hỏi xã giao, hàn huyên. Ví dụ: 寒暄几句, 互相寒暄.","hsk_level":6,"tags":["dong-tu"],"image":"☕","examples":[{"type":"basic","zh":"他们寒暄了几句。","pinyin":"Tāmen hánxuānle jǐ jù.","vi":"Họ hàn huyên vài câu."},{"type":"simple","zh":"见面时，两位老同学热情地寒暄起来。","pinyin":"Jiànmiàn shí, liǎng wèi lǎo tóngxué rèqíng de hánxuān qǐlái.","vi":"Khi gặp mặt, hai người bạn học cũ nhiệt tình hỏi han nhau."},{"type":"compound","zh":"他一坐下就直奔主题，连寒暄都省了。","pinyin":"Tā yí zuòxià jiù zhíbèn zhǔtí, lián hánxuān dōu shěng le.","vi":"Anh ấy vừa ngồi xuống là vào thẳng vấn đề, đến cả chào hỏi xã giao cũng bỏ qua."}],"related":[{"hanzi":"问候","pinyin":"wènhòu","vi":"hỏi thăm"},{"hanzi":"客套","pinyin":"kètào","vi":"khách sáo"},{"hanzi":"打招呼","pinyin":"dǎzhāohu","vi":"chào hỏi"},{"hanzi":"聊天","pinyin":"liáotiān","vi":"trò chuyện"}]},{"id":"含蓄","hanzi":"含蓄","pinyin":"hánxù","meaning_vi":"hàm súc, kín đáo, ý nhị","explanation":"含 (ngậm/chứa) + 蓄 (tích trữ).","hsk_level":6,"tags":["tinh-tu","ngon-ngu"],"image":"🌸","examples":[{"type":"basic","zh":"她说话很含蓄。","pinyin":"Tā shuōhuà hěn hánxù.","vi":"Cô ấy nói chuyện rất ý nhị."},{"type":"simple","zh":"这首诗用含蓄的语言表达了思乡之情。","pinyin":"Zhè shǒu shī yòng hánxù de yǔyán biǎodále sīxiāng zhī qíng.","vi":"Bài thơ này dùng ngôn ngữ hàm súc để bày tỏ nỗi nhớ quê."},{"type":"compound","zh":"因为他的拒绝很含蓄，所以对方一时没听出来。","pinyin":"Yīnwèi tā de jùjué hěn hánxù, suǒyǐ duìfāng yìshí méi tīng chūlái.","vi":"Vì lời từ chối của anh ấy rất kín đáo nên đối phương nhất thời không nhận ra."}],"related":[{"hanzi":"委婉","pinyin":"wěiwǎn","vi":"uyển chuyển"},{"hanzi":"直白","pinyin":"zhíbái","vi":"thẳng thừng"},{"hanzi":"内敛","pinyin":"nèiliǎn","vi":"kín đáo"},{"hanzi":"含义","pinyin":"hányì","vi":"hàm ý"}]},{"id":"含辛茹苦","hanzi":"含辛茹苦","pinyin":"hánxīn-rúkǔ","meaning_vi":"ngậm đắng nuốt cay, chịu đựng mọi gian khổ","explanation":"含辛茹苦: ngậm (含) cay (辛), nuốt (茹) đắng (苦) → chịu đựng mọi gian khổ; hay dùng tả cha mẹ vất vả nuôi con: 含辛茹苦把孩子养大.","hsk_level":6,"tags":["thanh-ngu"],"image":"😓","examples":[{"type":"basic","zh":"他们含辛茹苦地创业。","pinyin":"Tāmen hánxīnrúkǔ de chuàngyè.","vi":"Họ lập nghiệp trong muôn vàn gian khổ."},{"type":"simple","zh":"她含辛茹苦地把三个孩子抚养成人。","pinyin":"Tā hánxīnrúkǔ de bǎ sān gè háizi fǔyǎng chéngrén.","vi":"Bà ngậm đắng nuốt cay nuôi ba đứa con khôn lớn."},{"type":"compound","zh":"父亲虽然含辛茹苦了半辈子，但是从来没有抱怨过。","pinyin":"Fùqīn suīrán hánxīnrúkǔle bànbèizi, dànshì cónglái méiyǒu bàoyuàn guo.","vi":"Bố tuy đã chịu bao gian khổ nửa đời người nhưng chưa từng than phiền."}],"related":[{"hanzi":"千辛万苦","pinyin":"qiānxīnwànkǔ","vi":"muôn vàn gian khổ"},{"hanzi":"吃苦耐劳","pinyin":"chīkǔnàiláo","vi":"chịu thương chịu khó"},{"hanzi":"艰辛","pinyin":"jiānxīn","vi":"gian truân"},{"hanzi":"养育","pinyin":"yǎngyù","vi":"nuôi dưỡng"}]},{"id":"行家","hanzi":"行家","pinyin":"hángjia","meaning_vi":"chuyên gia, người sành sỏi trong nghề","explanation":"行 (đọc háng) + 家 (chuyên gia).","hsk_level":6,"tags":["danh-tu","con-nguoi","cong-viec"],"image":"🧑‍💼","examples":[{"type":"basic","zh":"他是品茶的行家。","pinyin":"Tā shì pǐnchá de hángjia.","vi":"Ông ấy là người sành thưởng trà."},{"type":"simple","zh":"行家一看就知道这块玉是真的。","pinyin":"Hángjia yí kàn jiù zhīdào zhè kuài yù shì zhēn de.","vi":"Người trong nghề nhìn qua là biết miếng ngọc này là thật."},{"type":"compound","zh":"如果你不懂装修，最好请个行家来帮忙看看。","pinyin":"Rúguǒ nǐ bù dǒng zhuāngxiū, zuìhǎo qǐng gè hángjia lái bāngmáng kànkan.","vi":"Nếu bạn không rành sửa nhà thì tốt nhất mời một người trong nghề đến xem giúp."}],"related":[{"hanzi":"内行","pinyin":"nèiháng","vi":"người trong nghề"},{"hanzi":"专家","pinyin":"zhuānjiā","vi":"chuyên gia"},{"hanzi":"外行","pinyin":"wàiháng","vi":"người ngoại đạo"},{"hanzi":"行家里手","pinyin":"hángjiālǐshǒu","vi":"người sành nghề"}]},{"id":"航空","hanzi":"航空","pinyin":"hángkōng","meaning_vi":"hàng không","explanation":"航 (hàng – đi thuyền, bay) + 空 (không – bầu trời) → hàng không, bay trên không. Ví dụ: 航空公司, 航空邮件, 民用航空.","hsk_level":6,"tags":["danh-tu","giao-thong"],"image":"✈️","examples":[{"type":"basic","zh":"他在航空公司上班。","pinyin":"Tā zài hángkōng gōngsī shàngbān.","vi":"Anh ấy làm việc ở hãng hàng không."},{"type":"simple","zh":"这封航空信寄到法国需要一周左右。","pinyin":"Zhè fēng hángkōngxìn jì dào Fǎguó xūyào yìzhōu zuǒyòu.","vi":"Lá thư gửi đường hàng không này đến Pháp mất khoảng một tuần."},{"type":"compound","zh":"因为航空管制，所以我们的航班推迟了两个小时。","pinyin":"Yīnwèi hángkōng guǎnzhì, suǒyǐ wǒmen de hángbān tuīchíle liǎng gè xiǎoshí.","vi":"Vì kiểm soát không lưu nên chuyến bay của chúng tôi bị hoãn hai tiếng."}],"related":[{"hanzi":"航空公司","pinyin":"hángkōnggōngsī","vi":"hãng hàng không"},{"hanzi":"航天","pinyin":"hángtiān","vi":"hàng không vũ trụ"},{"hanzi":"飞机","pinyin":"fēijī","vi":"máy bay"},{"hanzi":"航班","pinyin":"hángbān","vi":"chuyến bay"}]},{"id":"航行","hanzi":"航行","pinyin":"hángxíng","meaning_vi":"đi biển, bay","explanation":"航 (hàng – đi thuyền) + 行 (hành – đi) → (tàu, máy bay) đi biển, đi lại trên mặt nước hoặc trên không. Ví dụ: 在海上航行.","hsk_level":6,"tags":["dong-tu"],"image":"🚢","examples":[{"type":"basic","zh":"船在海上航行。","pinyin":"Chuán zài hǎishàng hángxíng.","vi":"Con tàu đang đi trên biển."},{"type":"simple","zh":"这艘货轮已经在太平洋上航行了十天。","pinyin":"Zhè sōu huòlún yǐjīng zài Tàipíngyáng shàng hángxíngle shí tiān.","vi":"Chiếc tàu hàng này đã đi trên Thái Bình Dương mười ngày."},{"type":"compound","zh":"即使遇到大风浪，船长也能沉着地指挥船只继续航行。","pinyin":"Jíshǐ yùdào dà fēnglàng, chuánzhǎng yě néng chénzhuó de zhǐhuī chuánzhī jìxù hángxíng.","vi":"Dù gặp sóng to gió lớn, thuyền trưởng vẫn bình tĩnh chỉ huy con tàu tiếp tục hải trình."}],"related":[{"hanzi":"航海","pinyin":"hánghǎi","vi":"đi biển"},{"hanzi":"航线","pinyin":"hángxiàn","vi":"tuyến đường bay/biển"},{"hanzi":"船只","pinyin":"chuánzhī","vi":"tàu thuyền"},{"hanzi":"导航","pinyin":"dǎoháng","vi":"dẫn đường"}]},{"id":"豪爽","hanzi":"豪爽","pinyin":"háoshuǎng","meaning_vi":"hào sảng, phóng khoáng thẳng thắn","explanation":"豪 (hào hiệp) + 爽 (sảng khoái).","hsk_level":6,"tags":["tinh-tu","con-nguoi"],"image":"😄","examples":[{"type":"basic","zh":"他为人豪爽。","pinyin":"Tā wéirén háoshuǎng.","vi":"Anh ấy tính tình hào sảng."},{"type":"simple","zh":"东北人豪爽地请我们喝了一晚上的酒。","pinyin":"Dōngběi rén háoshuǎng de qǐng wǒmen hēle yì wǎnshang de jiǔ.","vi":"Người Đông Bắc hào phóng mời chúng tôi uống rượu cả buổi tối."},{"type":"compound","zh":"她性格既豪爽又细心，所以朋友特别多。","pinyin":"Tā xìnggé jì háoshuǎng yòu xìxīn, suǒyǐ péngyou tèbié duō.","vi":"Cô ấy tính cách vừa phóng khoáng vừa chu đáo nên có rất nhiều bạn."}],"related":[{"hanzi":"爽快","pinyin":"shuǎngkuai","vi":"sảng khoái"},{"hanzi":"豪放","pinyin":"háofàng","vi":"hào phóng"},{"hanzi":"大方","pinyin":"dàfang","vi":"rộng rãi"},{"hanzi":"小气","pinyin":"xiǎoqi","vi":"keo kiệt"}]},{"id":"毫无","hanzi":"毫无","pinyin":"háowú","meaning_vi":"hoàn toàn không có","explanation":"毫 (hào – sợi lông, mảy may) + 无 (vô – không) → không có mảy may nào, hoàn toàn không. Ví dụ: 毫无疑问, 毫无意义.","hsk_level":6,"tags":["dong-tu"],"image":"🚫","examples":[{"type":"basic","zh":"我对此毫无兴趣。","pinyin":"Wǒ duì cǐ háowú xìngqù.","vi":"Tôi hoàn toàn không hứng thú với chuyện này."},{"type":"simple","zh":"面对突如其来的问题，他毫无准备。","pinyin":"Miànduì tūrúqílái de wèntí, tā háowú zhǔnbèi.","vi":"Trước câu hỏi bất ngờ, anh ấy hoàn toàn không có sự chuẩn bị."},{"type":"compound","zh":"虽然他练了很久，但是在比赛中依然毫无优势。","pinyin":"Suīrán tā liànle hěn jiǔ, dànshì zài bǐsài zhōng yīrán háowú yōushì.","vi":"Tuy anh ấy đã luyện tập rất lâu nhưng trong trận đấu vẫn chẳng có chút ưu thế nào."}],"related":[{"hanzi":"毫无疑问","pinyin":"háowúyíwèn","vi":"không còn nghi ngờ"},{"hanzi":"丝毫","pinyin":"sīháo","vi":"mảy may"},{"hanzi":"一点也不","pinyin":"yìdiǎnyěbù","vi":"không chút nào"},{"hanzi":"毫不","pinyin":"háobù","vi":"hoàn toàn không"}],"traditional":"毫無"},{"id":"鹤立鸡群","hanzi":"鹤立鸡群","pinyin":"hèlì-jīqún","meaning_vi":"hạc đứng giữa bầy gà (nổi bật vượt trội)","explanation":"鹤立鸡群: con hạc đứng giữa bầy gà (Thế Thuyết Tân Ngữ, khen Kê Thiệu) → người tài năng, dáng vẻ nổi bật hẳn giữa đám đông.","hsk_level":6,"tags":["thanh-ngu"],"image":"🦩","examples":[{"type":"basic","zh":"他在班里鹤立鸡群。","pinyin":"Tā zài bān lǐ hèlìjīqún.","vi":"Cậu ấy nổi bật nhất lớp như hạc giữa bầy gà."},{"type":"simple","zh":"个子高高的他站在人群中显得鹤立鸡群。","pinyin":"Gèzi gāo gāo de tā zhàn zài rénqún zhōng xiǎnde hèlìjīqún.","vi":"Anh ấy cao lớn, đứng giữa đám đông trông nổi bật hẳn lên."},{"type":"compound","zh":"她的作品既新颖又实用，在众多参赛作品中鹤立鸡群。","pinyin":"Tā de zuòpǐn jì xīnyǐng yòu shíyòng, zài zhòngduō cānsài zuòpǐn zhōng hèlìjīqún.","vi":"Tác phẩm của cô ấy vừa mới lạ vừa thực dụng, nổi bật hẳn giữa nhiều tác phẩm dự thi."}],"related":[{"hanzi":"出类拔萃","pinyin":"chūlèibácuì","vi":"xuất chúng"},{"hanzi":"与众不同","pinyin":"yǔzhòngbùtóng","vi":"khác biệt mọi người"},{"hanzi":"平庸","pinyin":"píngyōng","vi":"tầm thường"},{"hanzi":"脱颖而出","pinyin":"tuōyǐng'érchū","vi":"nổi bật lên"}],"traditional":"鶴立雞群"},{"id":"合并","hanzi":"合并","pinyin":"hébìng","meaning_vi":"sáp nhập, hợp nhất","explanation":"合 (hợp – hợp lại) + 并 (tính – gộp) → sáp nhập, gộp lại làm một. Ví dụ: 两家公司合并, 合并同类项.","hsk_level":6,"tags":["dong-tu"],"image":"🔗","examples":[{"type":"basic","zh":"两个班合并了。","pinyin":"Liǎng gè bān hébìng le.","vi":"Hai lớp đã được gộp lại."},{"type":"simple","zh":"这两家银行明年将正式合并。","pinyin":"Zhè liǎng jiā yínháng míngnián jiāng zhèngshì hébìng.","vi":"Hai ngân hàng này sẽ chính thức sáp nhập vào năm sau."},{"type":"compound","zh":"如果把这两个部门合并，就能节省不少人力。","pinyin":"Rúguǒ bǎ zhè liǎng gè bùmén hébìng, jiù néng jiéshěng bùshǎo rénlì.","vi":"Nếu sáp nhập hai phòng ban này thì có thể tiết kiệm khá nhiều nhân lực."}],"related":[{"hanzi":"兼并","pinyin":"jiānbìng","vi":"sáp nhập"},{"hanzi":"合二为一","pinyin":"hé'èrwéiyī","vi":"hợp hai làm một"},{"hanzi":"拆分","pinyin":"chāifēn","vi":"tách ra"},{"hanzi":"整合","pinyin":"zhěnghé","vi":"hợp nhất, tích hợp"}],"traditional":"合併"},{"id":"和睦","hanzi":"和睦","pinyin":"hémù","meaning_vi":"hòa thuận, êm ấm","explanation":"和 (hòa – hòa hợp) + 睦 (mục – thân thiện) → hòa thuận, êm ấm. Thường đi với 家庭和睦, 邻里和睦, 和睦相处.","hsk_level":6,"tags":["tinh-tu"],"image":"🏡","examples":[{"type":"basic","zh":"他们一家很和睦。","pinyin":"Tāmen yìjiā hěn hémù.","vi":"Gia đình họ rất hòa thuận."},{"type":"simple","zh":"邻居们和睦相处了二十多年。","pinyin":"Línjūmen hémù xiāngchǔle èrshí duōnián.","vi":"Hàng xóm sống hòa thuận với nhau hơn hai mươi năm."},{"type":"compound","zh":"只要彼此多一些理解，家庭就会更加和睦。","pinyin":"Zhǐyào bǐcǐ duō yìxiē lǐjiě, jiātíng jiù huì gèngjiā hémù.","vi":"Chỉ cần hiểu nhau hơn một chút, gia đình sẽ càng êm ấm."}],"related":[{"hanzi":"和谐","pinyin":"héxié","vi":"hài hòa"},{"hanzi":"融洽","pinyin":"róngqià","vi":"hòa hợp"},{"hanzi":"和睦相处","pinyin":"hémùxiāngchǔ","vi":"chung sống hòa thuận"},{"hanzi":"不和","pinyin":"bùhé","vi":"bất hòa"}]},{"id":"合算","hanzi":"合算","pinyin":"hésuàn","meaning_vi":"có lợi, hời","explanation":"合 (hợp – hợp) + 算 (toán – tính) → tính ra thấy có lợi, đáng tiền, hời. Ví dụ: 这样买很合算. Gần nghĩa: 划算.","hsk_level":6,"tags":["tinh-tu"],"image":"💰","examples":[{"type":"basic","zh":"这笔买卖很合算。","pinyin":"Zhè bǐ mǎimai hěn hésuàn.","vi":"Vụ mua bán này rất hời."},{"type":"simple","zh":"买年卡比每次单独买票合算多了。","pinyin":"Mǎi nián kǎ bǐ měi cì dāndú mǎipiào hésuàn duō le.","vi":"Mua thẻ năm lời hơn nhiều so với mỗi lần mua vé lẻ."},{"type":"compound","zh":"打车虽然方便，但是上班高峰期坐地铁更合算。","pinyin":"Dǎchē suīrán fāngbiàn, dànshì shàngbān gāofēngqī zuò dìtiě gèng hésuàn.","vi":"Đi taxi tuy tiện, nhưng giờ cao điểm đi làm thì đi tàu điện ngầm lại kinh tế hơn."}],"related":[{"hanzi":"划算","pinyin":"huásuàn","vi":"đáng giá"},{"hanzi":"便宜","pinyin":"piányi","vi":"rẻ"},{"hanzi":"吃亏","pinyin":"chīkuī","vi":"chịu thiệt"},{"hanzi":"值得","pinyin":"zhíde","vi":"đáng"}]},{"id":"和颜悦色","hanzi":"和颜悦色","pinyin":"héyán-yuèsè","meaning_vi":"nét mặt vui vẻ hòa nhã","explanation":"和颜悦色: nét mặt (颜) ôn hòa (和), sắc mặt (色) vui vẻ (悦) → thái độ hiền hòa niềm nở, dễ gần.","hsk_level":6,"tags":["thanh-ngu"],"image":"😊","examples":[{"type":"basic","zh":"她总是和颜悦色。","pinyin":"Tā zǒngshì héyányuèsè.","vi":"Cô ấy lúc nào cũng vui vẻ hòa nhã."},{"type":"simple","zh":"店员和颜悦色地向顾客解释退货规定。","pinyin":"Diànyuán héyányuèsè de xiàng gùkè jiěshì tuìhuò guīdìng.","vi":"Nhân viên cửa hàng hòa nhã giải thích quy định đổi trả cho khách."},{"type":"compound","zh":"即使学生犯了错，王老师也总是和颜悦色地跟他们谈话。","pinyin":"Jíshǐ xuésheng fànle cuò, Wáng lǎoshī yě zǒngshì héyányuèsè de gēn tāmen tánhuà.","vi":"Dù học sinh mắc lỗi, cô Vương vẫn luôn ôn tồn trò chuyện với các em."}],"related":[{"hanzi":"和蔼可亲","pinyin":"hé'ǎikěqīn","vi":"hòa nhã dễ gần"},{"hanzi":"笑容满面","pinyin":"xiàoróngmǎnmiàn","vi":"mặt mày tươi cười"},{"hanzi":"横眉怒目","pinyin":"héngméinùmù","vi":"trợn mắt giận dữ"},{"hanzi":"温和","pinyin":"wēnhé","vi":"ôn hòa"}],"traditional":"和顏悅色"},{"id":"和蔼可亲","hanzi":"和蔼可亲","pinyin":"hé'ǎi-kěqīn","meaning_vi":"hòa nhã dễ gần","explanation":"和蔼 (hòa ái – ôn hòa hiền hậu) + 可亲 (khả thân – dễ gần) → hiền hòa dễ mến, thường tả người lớn tuổi, thầy cô.","hsk_level":6,"tags":["thanh-ngu","con-nguoi"],"image":"😊","examples":[{"type":"basic","zh":"校长和蔼可亲。","pinyin":"Xiàozhǎng hé'ǎikěqīn.","vi":"Thầy hiệu trưởng hiền hậu dễ gần."},{"type":"simple","zh":"那位和蔼可亲的老奶奶常给我们糖吃。","pinyin":"Nà wèi hé'ǎikěqīn de lǎonǎinai cháng gěi wǒmen táng chī.","vi":"Bà cụ hiền hậu dễ gần ấy hay cho chúng tôi kẹo."},{"type":"compound","zh":"他虽然是大公司的老板，但是待人非常和蔼可亲。","pinyin":"Tā suīrán shì dàgōngsī de lǎobǎn, dànshì dàirén fēicháng hé'ǎikěqīn.","vi":"Ông ấy tuy là ông chủ công ty lớn nhưng đối xử với mọi người rất hòa nhã dễ gần."}],"related":[{"hanzi":"平易近人","pinyin":"píngyìjìnrén","vi":"dễ gần gũi"},{"hanzi":"和颜悦色","pinyin":"héyányuèsè","vi":"vui vẻ hòa nhã"},{"hanzi":"和蔼","pinyin":"hé'ǎi","vi":"hòa nhã"},{"hanzi":"冷若冰霜","pinyin":"lěngruòbīngshuāng","vi":"lạnh như băng"}],"traditional":"和藹可親"},{"id":"痕迹","hanzi":"痕迹","pinyin":"hénjì","meaning_vi":"dấu vết","explanation":"痕 (ngân – vết sẹo) + 迹 (tích – dấu) → dấu vết còn lại. Ví dụ: 留下痕迹, 岁月的痕迹, 不露痕迹.","hsk_level":6,"tags":["danh-tu"],"image":"👣","examples":[{"type":"basic","zh":"墙上有一道痕迹。","pinyin":"Qiáng shàng yǒu yídào hénjì.","vi":"Trên tường có một vết."},{"type":"simple","zh":"警察在窗台上发现了攀爬的痕迹。","pinyin":"Jǐngchá zài chuāngtái shàng fāxiànle pānpá de hénjì.","vi":"Cảnh sát phát hiện dấu vết leo trèo trên bậu cửa sổ."},{"type":"compound","zh":"岁月虽然在她脸上留下了痕迹，却没有带走她的笑容。","pinyin":"Suìyuè suīrán zài tā liǎn shàng liúxiàle hénjì, què méiyǒu dàizǒu tā de xiàoróng.","vi":"Năm tháng tuy để lại dấu vết trên gương mặt bà, nhưng không lấy đi nụ cười của bà."}],"related":[{"hanzi":"踪迹","pinyin":"zōngjì","vi":"dấu vết"},{"hanzi":"印记","pinyin":"yìnjì","vi":"dấu ấn"},{"hanzi":"伤痕","pinyin":"shānghén","vi":"vết thương"},{"hanzi":"蛛丝马迹","pinyin":"zhūsīmǎjì","vi":"dấu vết mờ nhạt"}],"traditional":"痕跡"},{"id":"横行霸道","hanzi":"横行霸道","pinyin":"héngxíng-bàdào","meaning_vi":"ngang ngược hoành hành","explanation":"横行霸道: đi ngang (横行) như cua, cư xử như bá chủ (霸道) → ỷ thế làm càn, ngang ngược hống hách, ức hiếp người khác.","hsk_level":6,"tags":["thanh-ngu"],"image":"👹","examples":[{"type":"basic","zh":"横行霸道的人没好下场。","pinyin":"Héngxíngbàdào de rén méi hǎo xiàchǎng.","vi":"Kẻ ngang ngược hoành hành sẽ không có kết cục tốt."},{"type":"simple","zh":"那伙流氓在街头横行霸道了好几年。","pinyin":"Nà huǒ liúmáng zài jiētóu héngxíngbàdàole hǎojǐnián.","vi":"Bọn côn đồ đó hoành hành ngang ngược trên phố suốt mấy năm trời."},{"type":"compound","zh":"警方一出手，这些横行霸道的恶霸就全部落网了。","pinyin":"Jǐngfāng yì chūshǒu, zhèxiē héngxíngbàdào de èbà jiù quánbù luòwǎng le.","vi":"Cảnh sát vừa ra tay, bọn ác bá hoành hành ngang ngược này liền sa lưới toàn bộ."}],"related":[{"hanzi":"胡作非为","pinyin":"húzuòfēiwéi","vi":"làm càn"},{"hanzi":"无法无天","pinyin":"wúfǎwútiān","vi":"coi trời bằng vung"},{"hanzi":"霸道","pinyin":"bàdào","vi":"ngang ngược"},{"hanzi":"作威作福","pinyin":"zuòwēizuòfú","vi":"tác oai tác quái"}],"traditional":"橫行霸道"},{"id":"后顾之忧","hanzi":"后顾之忧","pinyin":"hòugù-zhīyōu","meaning_vi":"nỗi lo phía sau","explanation":"后顾之忧: nỗi lo (忧) khi ngoái nhìn lại (后顾) phía sau → nỗi lo ở hậu phương, việc nhà; hay dùng: 解除后顾之忧.","hsk_level":6,"tags":["thanh-ngu"],"image":"😟","examples":[{"type":"basic","zh":"他没有后顾之忧。","pinyin":"Tā méiyǒu hòugùzhīyōu.","vi":"Anh ấy không có nỗi lo phía sau."},{"type":"simple","zh":"公司为员工解决了孩子上学的后顾之忧。","pinyin":"Gōngsī wèi yuángōng jiějuéle háizi shàngxué de hòugùzhīyōu.","vi":"Công ty đã giải quyết nỗi lo con đi học cho nhân viên."},{"type":"compound","zh":"只要父母帮忙带孩子，她就可以没有后顾之忧地去出差。","pinyin":"Zhǐyào fùmǔ bāngmáng dàiháizi, tā jiù kěyǐ méiyǒu hòugùzhīyōu de qù chūchāi.","vi":"Chỉ cần bố mẹ giúp trông con, cô ấy có thể yên tâm đi công tác."}],"related":[{"hanzi":"顾虑","pinyin":"gùlǜ","vi":"lo ngại"},{"hanzi":"无后顾之忧","pinyin":"wú hòugùzhīyōu","vi":"không lo phía sau"},{"hanzi":"担忧","pinyin":"dānyōu","vi":"lo âu"},{"hanzi":"隐患","pinyin":"yǐnhuàn","vi":"mối lo tiềm ẩn"}],"traditional":"後顧之憂"},{"id":"后起之秀","hanzi":"后起之秀","pinyin":"hòuqǐ-zhīxiù","meaning_vi":"tài năng trẻ mới nổi","explanation":"后起之秀: người tài giỏi (秀) mới xuất hiện sau (后起) → tài năng trẻ mới nổi, thế hệ kế cận xuất sắc.","hsk_level":6,"tags":["thanh-ngu"],"image":"🌟","examples":[{"type":"basic","zh":"她是乒坛的后起之秀。","pinyin":"Tā shì pīngtán de hòuqǐzhīxiù.","vi":"Cô ấy là tài năng trẻ của làng bóng bàn."},{"type":"simple","zh":"这位年轻导演是电影界公认的后起之秀。","pinyin":"Zhè wèi niánqīng dǎoyǎn shì diànyǐngjiè gōngrèn de hòuqǐzhīxiù.","vi":"Vị đạo diễn trẻ này là tài năng mới được giới điện ảnh công nhận."},{"type":"compound","zh":"这个后起之秀虽然才十八岁，却已经打败了世界冠军。","pinyin":"Zhè ge hòuqǐzhīxiù suīrán cái shíbā suì, què yǐjīng dǎbàile shìjiè guànjūn.","vi":"Tài năng trẻ này tuy mới mười tám tuổi nhưng đã đánh bại nhà vô địch thế giới."}],"related":[{"hanzi":"新秀","pinyin":"xīnxiù","vi":"tài năng mới"},{"hanzi":"青出于蓝","pinyin":"qīngchūyúlán","vi":"trò giỏi hơn thầy"},{"hanzi":"新星","pinyin":"xīnxīng","vi":"ngôi sao mới"},{"hanzi":"年轻有为","pinyin":"niánqīngyǒuwéi","vi":"trẻ tuổi tài cao"}],"traditional":"後起之秀"},{"id":"红润","hanzi":"红润","pinyin":"hóngrùn","meaning_vi":"hồng hào (sắc mặt/làn da)","explanation":"红 (đỏ) + 润 (ẩm mịn).","hsk_level":6,"tags":["tinh-tu","suc-khoe"],"image":"😊","examples":[{"type":"basic","zh":"她脸色红润。","pinyin":"Tā liǎnsè hóngrùn.","vi":"Sắc mặt cô ấy hồng hào."},{"type":"simple","zh":"病好以后，奶奶的脸上又有了红润的光泽。","pinyin":"Bìng hǎo yǐhòu, nǎinai de liǎn shàng yòu yǒule hóngrùn de guāngzé.","vi":"Sau khi khỏi bệnh, gương mặt bà lại hồng hào tươi tắn."},{"type":"compound","zh":"只要坚持早睡早起，你的气色就会越来越红润。","pinyin":"Zhǐyào jiānchí zǎo shuì zǎoqǐ, nǐ de qìsè jiù huì yuèláiyuè hóngrùn.","vi":"Chỉ cần kiên trì ngủ sớm dậy sớm, sắc mặt bạn sẽ ngày càng hồng hào."}],"related":[{"hanzi":"红扑扑","pinyin":"hóngpūpū","vi":"đỏ hây hây"},{"hanzi":"苍白","pinyin":"cāngbái","vi":"tái nhợt"},{"hanzi":"气色","pinyin":"qìsè","vi":"sắc mặt"},{"hanzi":"滋润","pinyin":"zīrùn","vi":"tươi nhuận"}],"traditional":"紅潤"},{"id":"宏伟","hanzi":"宏伟","pinyin":"hóngwěi","meaning_vi":"hùng vĩ, to lớn (công trình/kế hoạch)","explanation":"宏 + 伟 (vĩ đại).","hsk_level":6,"tags":["tinh-tu"],"image":"🏛️","examples":[{"type":"basic","zh":"长城非常宏伟。","pinyin":"Chángchéng fēicháng hóngwěi.","vi":"Vạn Lý Trường Thành rất hùng vĩ."},{"type":"simple","zh":"市政府制定了一个宏伟的城市发展蓝图。","pinyin":"Shìzhèngfǔ zhìdìngle yí gè hóngwěi de chéngshì fāzhǎn lántú.","vi":"Chính quyền thành phố đã vạch ra một bản quy hoạch phát triển đô thị đồ sộ."},{"type":"compound","zh":"这座大桥不但设计宏伟，而且只用了两年就建成了。","pinyin":"Zhè zuò Dàqiáo búdàn shèjì hóngwěi, érqiě zhǐ yòngle liǎng nián jiù jiàn chéngle.","vi":"Cây cầu lớn này không những thiết kế hùng vĩ mà chỉ mất hai năm đã xây xong."}],"related":[{"hanzi":"雄伟","pinyin":"xióngwěi","vi":"hùng vĩ"},{"hanzi":"壮观","pinyin":"zhuàngguān","vi":"tráng lệ"},{"hanzi":"宏大","pinyin":"hóngdà","vi":"to lớn"},{"hanzi":"宏伟蓝图","pinyin":"hóngwěilántú","vi":"kế hoạch lớn lao"}],"traditional":"宏偉"},{"id":"弘扬","hanzi":"弘扬","pinyin":"hóngyáng","meaning_vi":"phát huy, lan tỏa (văn hóa/tinh thần)","explanation":"宏 (lớn) + 扬 (nêu cao). Cụm: 弘扬传统文化.","hsk_level":6,"tags":["dong-tu","van-hoa"],"image":"🏮","examples":[{"type":"basic","zh":"弘扬传统文化。","pinyin":"Hóngyáng chuántǒng wénhuà.","vi":"Phát huy văn hóa truyền thống."},{"type":"simple","zh":"学校通过各种活动弘扬尊老爱幼的美德。","pinyin":"Xuéxiào tōngguò gèzhǒng huódòng hóngyáng zūnlǎo ài yòu de měidé.","vi":"Nhà trường thông qua nhiều hoạt động để phát huy đức tính kính già yêu trẻ."},{"type":"compound","zh":"要想弘扬民族音乐，就必须先培养年轻的听众。","pinyin":"Yào xiǎng hóngyáng mínzú yīnyuè, jiù bìxū xiān péiyǎng niánqīng de tīngzhòng.","vi":"Muốn phát huy âm nhạc dân tộc thì trước hết phải bồi dưỡng thính giả trẻ."}],"related":[{"hanzi":"发扬","pinyin":"fāyáng","vi":"phát huy"},{"hanzi":"传承","pinyin":"chuánchéng","vi":"truyền thừa"},{"hanzi":"发扬光大","pinyin":"fāyángguāngdà","vi":"phát huy rạng rỡ"},{"hanzi":"宣扬","pinyin":"xuānyáng","vi":"tuyên dương"}],"traditional":"弘揚"},{"id":"混合","hanzi":"混合","pinyin":"hùnhé","meaning_vi":"hỗn hợp, pha trộn","explanation":"混 (hỗn – trộn lẫn) + 合 (hợp – gộp) → pha trộn, trộn lẫn; hỗn hợp. Ví dụ: 混合物, 男女混合双打.","hsk_level":6,"tags":["dong-tu"],"image":"🧪","examples":[{"type":"basic","zh":"把面粉和水混合。","pinyin":"Bǎ miànfěn hé shuǐ hùnhé.","vi":"Trộn bột mì với nước."},{"type":"simple","zh":"空气是由多种气体混合而成的。","pinyin":"Kōngqì shì yóu duōzhǒng qìtǐ hùnhé ér chéng de.","vi":"Không khí do nhiều loại khí hỗn hợp mà thành."},{"type":"compound","zh":"如果把这两种清洁剂混合使用，就可能产生有毒气体。","pinyin":"Rúguǒ bǎ zhè liǎng zhǒng qīngjiéjì hùnhé shǐyòng, jiù kěnéng chǎnshēng yǒudú qìtǐ.","vi":"Nếu trộn lẫn hai loại chất tẩy rửa này để dùng thì có thể sinh ra khí độc."}],"related":[{"hanzi":"混杂","pinyin":"hùnzá","vi":"lẫn lộn"},{"hanzi":"搅拌","pinyin":"jiǎobàn","vi":"khuấy trộn"},{"hanzi":"混合物","pinyin":"hùnhéwù","vi":"hỗn hợp"},{"hanzi":"分离","pinyin":"fēnlí","vi":"tách rời"}]},{"id":"狐假虎威","hanzi":"狐假虎威","pinyin":"hújiǎ-hǔwēi","meaning_vi":"cáo mượn oai hùm","explanation":"狐假虎威: cáo đi trước hổ, mượn oai hổ dọa muông thú (Chiến Quốc Sách) → ỷ thế người có quyền để ra oai, hiếp đáp người khác.","hsk_level":6,"tags":["thanh-ngu"],"image":"🦊","examples":[{"type":"basic","zh":"他不过是狐假虎威。","pinyin":"Tā búguò shì hújiǎhǔwēi.","vi":"Hắn chẳng qua là cáo mượn oai hùm."},{"type":"simple","zh":"经理的秘书常常狐假虎威地指挥别人。","pinyin":"Jīnglǐ de mìshū chángcháng hújiǎhǔwēi de zhǐhuī biérén.","vi":"Thư ký của giám đốc thường cáo mượn oai hùm sai bảo người khác."},{"type":"compound","zh":"老板一离开，那个狐假虎威的小组长就老实多了。","pinyin":"Lǎobǎn yì líkāi, nà ge hújiǎhǔwēi de xiǎo zǔzhǎng jiù lǎoshi duō le.","vi":"Ông chủ vừa đi khỏi, tay tổ trưởng cáo mượn oai hùm kia liền ngoan ngoãn hẳn."}],"related":[{"hanzi":"仗势欺人","pinyin":"zhàngshìqīrén","vi":"cậy thế ức hiếp"},{"hanzi":"狗仗人势","pinyin":"gǒuzhàngrénshì","vi":"chó cậy gần nhà"},{"hanzi":"虚张声势","pinyin":"xūzhāngshēngshì","vi":"làm ra vẻ hùng mạnh"},{"hanzi":"威风","pinyin":"wēifēng","vi":"oai phong"}]},{"id":"胡乱","hanzi":"胡乱","pinyin":"húluàn","meaning_vi":"bừa bãi, lung tung","explanation":"胡 (hồ – càn, bừa) + 乱 (loạn) → làm bừa, tùy tiện, không suy tính. Cụm: 胡乱花钱, 胡乱吃点东西.","hsk_level":6,"tags":["pho-tu"],"image":"🌪️","examples":[{"type":"basic","zh":"别胡乱花钱。","pinyin":"Bié húluàn huāqián.","vi":"Đừng tiêu tiền bừa bãi."},{"type":"simple","zh":"他胡乱吃了几口饭就去上班了。","pinyin":"Tā húluàn chīle jǐ kǒu fàn jiù qù shàngbān le.","vi":"Anh ấy ăn qua loa vài miếng cơm rồi đi làm."},{"type":"compound","zh":"如果不懂就胡乱回答，反而会让老师更生气。","pinyin":"Rúguǒ bù dǒng jiù húluàn huídá, fǎn'ér huì ràng lǎoshī gèng shēngqì.","vi":"Nếu không hiểu mà trả lời bừa thì ngược lại càng khiến thầy giáo tức giận hơn."}],"related":[{"hanzi":"随便","pinyin":"suíbiàn","vi":"tùy tiện"},{"hanzi":"乱七八糟","pinyin":"luànqībāzāo","vi":"lộn xộn"},{"hanzi":"胡说","pinyin":"húshuō","vi":"nói bậy"},{"hanzi":"草率","pinyin":"cǎoshuài","vi":"qua loa"}],"traditional":"胡亂"},{"id":"湖泊","hanzi":"湖泊","pinyin":"húpō","meaning_vi":"hồ nước, ao hồ","explanation":"湖 (hồ – hồ) + 泊 (bạc – vũng nước, đậu) → hồ nước nói chung. Dùng làm danh từ tập hợp, không đi với lượng từ cụ thể: 湖泊众多.","hsk_level":6,"tags":["danh-tu","thien-nhien"],"image":"🏞️","examples":[{"type":"basic","zh":"这里湖泊很多。","pinyin":"Zhèlǐ húpō hěn duō.","vi":"Ở đây có rất nhiều hồ."},{"type":"simple","zh":"由于长期干旱，不少湖泊已经干涸了。","pinyin":"Yóuyú chángqī gānhàn, bùshǎo húpō yǐjīng gānhé le.","vi":"Do hạn hán kéo dài, nhiều hồ đã khô cạn."},{"type":"compound","zh":"这个地区不但湖泊众多，而且到处都是茂密的森林。","pinyin":"Zhè ge dìqū búdàn húpō zhòngduō, érqiě dàochù dōu shì màomì de sēnlín.","vi":"Vùng này không chỉ có nhiều hồ mà khắp nơi còn là rừng rậm."}],"related":[{"hanzi":"湖","pinyin":"hú","vi":"hồ"},{"hanzi":"河流","pinyin":"héliú","vi":"sông ngòi"},{"hanzi":"池塘","pinyin":"chítáng","vi":"ao"},{"hanzi":"水库","pinyin":"shuǐkù","vi":"hồ chứa nước"}]},{"id":"胡思乱想","hanzi":"胡思乱想","pinyin":"húsī-luànxiǎng","meaning_vi":"suy nghĩ vẩn vơ lung tung","explanation":"胡思乱想: nghĩ (思) bậy (胡), tưởng (想) loạn (乱) → suy nghĩ vẩn vơ, nghĩ linh tinh không căn cứ. Ví dụ: 别胡思乱想了.","hsk_level":6,"tags":["thanh-ngu"],"image":"💭","examples":[{"type":"basic","zh":"别再胡思乱想了。","pinyin":"Bié zài húsīluànxiǎng le.","vi":"Đừng nghĩ vẩn vơ nữa."},{"type":"simple","zh":"失眠的夜里她躺在床上胡思乱想。","pinyin":"Shīmián de yèlǐ tā tǎng zài chuáng shàng húsīluànxiǎng.","vi":"Những đêm mất ngủ, cô ấy nằm trên giường nghĩ ngợi lung tung."},{"type":"compound","zh":"与其一个人在家胡思乱想，不如出去找朋友聊聊天。","pinyin":"Yǔqí yígèrén zài jiā húsīluànxiǎng, bùrú chūqù zhǎo péngyou liáo liaotiān.","vi":"Thay vì ở nhà một mình nghĩ ngợi lung tung, chi bằng ra ngoài tìm bạn tán gẫu."}],"related":[{"hanzi":"想入非非","pinyin":"xiǎngrùfēifēi","vi":"nghĩ viển vông"},{"hanzi":"异想天开","pinyin":"yìxiǎngtiānkāi","vi":"nghĩ chuyện hão huyền"},{"hanzi":"胡乱","pinyin":"húluàn","vi":"lung tung"},{"hanzi":"多虑","pinyin":"duōlǜ","vi":"lo nghĩ nhiều"}],"traditional":"胡思亂想"},{"id":"浑水摸鱼","hanzi":"浑水摸鱼","pinyin":"húnshuǐ-mōyú","meaning_vi":"đục nước béo cò","explanation":"浑水摸鱼: mò cá trong nước đục → lợi dụng lúc hỗn loạn để kiếm lợi riêng; tương đương \"đục nước béo cò\". Cũng viết 混水摸鱼.","hsk_level":6,"tags":["thanh-ngu"],"image":"🐟","examples":[{"type":"basic","zh":"有人想浑水摸鱼。","pinyin":"Yǒurén xiǎng húnshuǐmōyú.","vi":"Có kẻ muốn đục nước béo cò."},{"type":"simple","zh":"小偷趁着火灾现场的混乱浑水摸鱼。","pinyin":"Xiǎotōu chènzhe huǒzāi xiànchǎng de hùnluàn húnshuǐmōyú.","vi":"Tên trộm nhân lúc hiện trường vụ cháy hỗn loạn để đục nước béo cò."},{"type":"compound","zh":"只要管理制度严格，就没有人敢浑水摸鱼。","pinyin":"Zhǐyào guǎnlǐ zhìdù yángé, jiù méiyǒu rén gǎn húnshuǐmōyú.","vi":"Chỉ cần chế độ quản lý nghiêm ngặt thì sẽ chẳng ai dám đục nước béo cò."}],"related":[{"hanzi":"趁火打劫","pinyin":"chènhuǒdǎjié","vi":"thừa nước đục thả câu"},{"hanzi":"乘虚而入","pinyin":"chéngxū'érrù","vi":"thừa cơ xâm nhập"},{"hanzi":"混水摸鱼","pinyin":"hùnshuǐmōyú","vi":"đục nước béo cò"},{"hanzi":"投机取巧","pinyin":"tóujīqǔqiǎo","vi":"cơ hội trục lợi"}],"traditional":"渾水摸魚"},{"id":"呵护","hanzi":"呵护","pinyin":"hēhù","meaning_vi":"chăm sóc, che chở nâng niu","explanation":"呵 + 护 (bảo vệ).","hsk_level":6,"tags":["dong-tu","cam-xuc"],"image":"🤗","examples":[{"type":"basic","zh":"他一直呵护着妻子。","pinyin":"Tā yìzhí hēhùzhe qīzi.","vi":"Anh ấy luôn che chở cho vợ."},{"type":"simple","zh":"她像呵护孩子一样呵护着这盆兰花。","pinyin":"Tā xiàng hēhù háizi yíyàng hēhùzhe zhè pén lánhuā.","vi":"Cô ấy nâng niu chậu lan này như chăm con nhỏ."},{"type":"compound","zh":"孩子的自信心既需要鼓励，又需要细心呵护。","pinyin":"Háizi de zìxìnxīn jì xūyào gǔlì, yòu xūyào xìxīn hēhù.","vi":"Lòng tự tin của trẻ vừa cần được khích lệ, vừa cần được chăm chút cẩn thận."}],"related":[{"hanzi":"爱护","pinyin":"àihù","vi":"yêu thương che chở"},{"hanzi":"保护","pinyin":"bǎohù","vi":"bảo vệ"},{"hanzi":"照顾","pinyin":"zhàogù","vi":"chăm sóc"},{"hanzi":"疼爱","pinyin":"téng'ài","vi":"thương yêu"}],"traditional":"呵護"},{"id":"黑白分明","hanzi":"黑白分明","pinyin":"hēibái-fēnmíng","meaning_vi":"đen trắng rõ ràng, rạch ròi đúng sai","explanation":"黑白分明: đen (黑) trắng (白) phân biệt rõ ràng (分明) → phân minh đúng sai, phải trái; cũng tả mắt đen trắng rõ, trong trẻo.","hsk_level":6,"tags":["thanh-ngu"],"image":"⚖️","examples":[{"type":"basic","zh":"他做事黑白分明。","pinyin":"Tā zuòshì hēibáifēnmíng.","vi":"Anh ấy làm việc phân minh trắng đen."},{"type":"simple","zh":"这幅水墨画黑白分明，意境深远。","pinyin":"Zhè fú shuǐmòhuà hēibáifēnmíng, yìjìng shēnyuǎn.","vi":"Bức tranh thủy mặc này đen trắng rõ ràng, ý cảnh sâu xa."},{"type":"compound","zh":"小孩子的世界往往黑白分明，所以很难理解大人的妥协。","pinyin":"Xiǎoháizi de shìjiè wǎngwǎng hēibáifēnmíng, suǒyǐ hěn nán lǐjiě dàrén de tuǒxié.","vi":"Thế giới của trẻ con thường trắng đen rạch ròi, nên khó hiểu được sự thỏa hiệp của người lớn."}],"related":[{"hanzi":"是非分明","pinyin":"shìfēifēnmíng","vi":"phân rõ phải trái"},{"hanzi":"泾渭分明","pinyin":"Jīngwèifēnmíng","vi":"ranh giới rõ ràng"},{"hanzi":"颠倒黑白","pinyin":"diāndǎohēibái","vi":"đổi trắng thay đen"},{"hanzi":"分明","pinyin":"fēnmíng","vi":"rõ ràng"}]},{"id":"哼","hanzi":"哼","pinyin":"hēng","meaning_vi":"hừ, ngâm nga","explanation":"哼 (hanh): tiếng hừ bằng mũi tỏ ý khinh bỉ, bực bội; còn nghĩa là ngâm nga, hát khẽ: 哼歌, 哼着小曲. Đọc hng khi là thán từ.","hsk_level":6,"tags":["dong-tu"],"image":"😒","examples":[{"type":"basic","zh":"她哼着小曲做饭。","pinyin":"Tā hēngzhe xiǎoqǔ zuòfàn.","vi":"Cô ấy vừa ngâm nga hát vừa nấu cơm."},{"type":"simple","zh":"他不满地哼了一声，转身就走了。","pinyin":"Tā bù mǎnde hēngle yìshēng, zhuǎnshēn jiù zǒu le.","vi":"Anh ta bực bội hừ một tiếng rồi quay người bỏ đi."},{"type":"compound","zh":"爸爸一高兴就会哼起年轻时最爱的老歌。","pinyin":"Bàba yì gāoxìng jiù huì hēng qǐ niánqīng shí zuì ài de lǎogē.","vi":"Bố hễ vui là lại ngâm nga những bài hát cũ yêu thích thời trẻ."}],"related":[{"hanzi":"哼歌","pinyin":"hēnggē","vi":"ngân nga hát"},{"hanzi":"冷哼","pinyin":"lěnghēng","vi":"hừ lạnh"},{"hanzi":"哼哼","pinyin":"hēngheng","vi":"rên hừ hừ"},{"hanzi":"嘟囔","pinyin":"dūnang","vi":"lẩm bẩm"}]},{"id":"轰动","hanzi":"轰动","pinyin":"hōngdòng","meaning_vi":"gây chấn động, xôn xao","explanation":"轰 (oanh – ầm ầm) + 动 (động – chấn động) → gây chấn động, làm xôn xao dư luận. Ví dụ: 轰动全国, 引起轰动.","hsk_level":6,"tags":["dong-tu"],"image":"😲","examples":[{"type":"basic","zh":"这件事轰动全城。","pinyin":"Zhè jiàn shì hōngdòng quánchéng.","vi":"Chuyện này gây chấn động cả thành phố."},{"type":"simple","zh":"她的新小说在文坛引起了巨大的轰动。","pinyin":"Tā de xīn xiǎoshuō zài wéntán yǐnqǐle jùdà de hōngdòng.","vi":"Cuốn tiểu thuyết mới của cô ấy gây chấn động lớn trên văn đàn."},{"type":"compound","zh":"那场演唱会一结束，相关视频就在网上轰动一时。","pinyin":"Nà chǎng yǎnchànghuì yì jiéshù, xiāngguān shìpín jiù zài wǎngshàng hōngdòng yìshí.","vi":"Buổi hòa nhạc đó vừa kết thúc, video liên quan liền gây sốt trên mạng một thời."}],"related":[{"hanzi":"轰动一时","pinyin":"hōngdòngyìshí","vi":"gây chấn động một thời"},{"hanzi":"震惊","pinyin":"zhènjīng","vi":"chấn động"},{"hanzi":"引人注目","pinyin":"yǐnrénzhùmù","vi":"thu hút sự chú ý"},{"hanzi":"热议","pinyin":"rèyì","vi":"bàn tán sôi nổi"}],"traditional":"轟動"},{"id":"轰轰烈烈","hanzi":"轰轰烈烈","pinyin":"hōnghōng-lièliè","meaning_vi":"oanh oanh liệt liệt, sôi nổi rầm rộ","explanation":"轰轰烈烈: ầm ầm (轰轰) và mãnh liệt (烈烈) → khí thế sôi nổi, rầm rộ, oanh liệt. Ví dụ: 轰轰烈烈的运动, 轰轰烈烈地干一场.","hsk_level":6,"tags":["thanh-ngu"],"image":"🔥","examples":[{"type":"basic","zh":"他想轰轰烈烈地活一次。","pinyin":"Tā xiǎng hōnghōnglièliè de huó yí cì.","vi":"Anh ấy muốn sống một lần thật oanh liệt."},{"type":"simple","zh":"全市开展了一场轰轰烈烈的植树运动。","pinyin":"Quánshì kāizhǎnle yì chǎng hōnghōnglièliè de zhíshù yùndòng.","vi":"Toàn thành phố triển khai một phong trào trồng cây rầm rộ."},{"type":"compound","zh":"他们的爱情虽然轰轰烈烈，但是只维持了半年。","pinyin":"Tāmen de àiqíng suīrán hōnghōnglièliè, dànshì zhǐ wéichíle bàn nián.","vi":"Tình yêu của họ tuy nồng nhiệt sôi nổi nhưng chỉ kéo dài nửa năm."}],"related":[{"hanzi":"声势浩大","pinyin":"shēngshìhàodà","vi":"thanh thế lớn"},{"hanzi":"热火朝天","pinyin":"rèhuǒcháotiān","vi":"sôi nổi khí thế"},{"hanzi":"无声无息","pinyin":"wúshēngwúxī","vi":"lặng lẽ không tiếng động"},{"hanzi":"壮烈","pinyin":"zhuàngliè","vi":"oanh liệt"}],"traditional":"轟轟烈烈"},{"id":"哄堂大笑","hanzi":"哄堂大笑","pinyin":"hōngtáng-dàxiào","meaning_vi":"cả phòng cười ồ lên","explanation":"哄堂 (cả nhà) + 大笑 (cười lớn). Thành ngữ.","hsk_level":6,"tags":["thanh-ngu"],"image":"😂","examples":[{"type":"basic","zh":"全班哄堂大笑。","pinyin":"Quánbān hōngtángdàxiào.","vi":"Cả lớp cười ồ lên."},{"type":"simple","zh":"他的一句玩笑引得会场哄堂大笑。","pinyin":"Tā de yíjù wánxiào yǐnde huìchǎng hōngtángdàxiào.","vi":"Một câu đùa của anh ấy khiến cả hội trường cười rộ lên."},{"type":"compound","zh":"主持人一念错名字，观众们就忍不住哄堂大笑。","pinyin":"Zhǔchírén yí niàn cuò míngzi, guānzhòngmen jiù rěnbuzhù hōngtángdàxiào.","vi":"Người dẫn chương trình vừa đọc nhầm tên, khán giả liền không nhịn được cười ồ cả lên."}],"related":[{"hanzi":"捧腹大笑","pinyin":"pěngfùdàxiào","vi":"cười ôm bụng"},{"hanzi":"哈哈大笑","pinyin":"hāhādàxiào","vi":"cười ha hả"},{"hanzi":"笑声","pinyin":"xiàoshēng","vi":"tiếng cười"},{"hanzi":"鸦雀无声","pinyin":"yāquèwúshēng","vi":"im phăng phắc"}],"traditional":"鬨堂大笑"},{"id":"呼风唤雨","hanzi":"呼风唤雨","pinyin":"hūfēng-huànyǔ","meaning_vi":"hô mưa gọi gió (quyền lực/năng lực lớn)","explanation":"呼风唤雨: gọi (呼) gió (风) kêu (唤) mưa (雨), vốn nói phép thần tiên → có quyền lực hoặc năng lực rất lớn, chi phối được cục diện.","hsk_level":6,"tags":["thanh-ngu"],"image":"🌪️","examples":[{"type":"basic","zh":"他在商界呼风唤雨。","pinyin":"Tā zài shāngjiè hūfēnghuànyǔ.","vi":"Ông ta hô mưa gọi gió trên thương trường."},{"type":"simple","zh":"传说中的龙王能够呼风唤雨。","pinyin":"Chuánshuō zhōng de Lóngwáng nénggòu hūfēnghuànyǔ.","vi":"Long Vương trong truyền thuyết có thể hô mưa gọi gió."},{"type":"compound","zh":"他当年虽然能呼风唤雨，现在却过着隐居的生活。","pinyin":"Tā dāngnián suīrán néng hūfēnghuànyǔ, xiànzài quèguò zhe yǐnjū de shēnghuó.","vi":"Năm xưa ông ta tuy có thể hô mưa gọi gió, nay lại sống cuộc đời ẩn dật."}],"related":[{"hanzi":"神通广大","pinyin":"shéntōngguǎngdà","vi":"thần thông quảng đại"},{"hanzi":"叱咤风云","pinyin":"chìzhàfēngyún","vi":"làm mưa làm gió"},{"hanzi":"权势","pinyin":"quánshì","vi":"quyền thế"},{"hanzi":"无所不能","pinyin":"wúsuǒbùnéng","vi":"không gì không làm được"}],"traditional":"呼風喚雨"},{"id":"忽略","hanzi":"忽略","pinyin":"hūlüè","meaning_vi":"lơ là, bỏ qua","explanation":"忽 (hốt – lơ là) + 略 (lược – bỏ qua) → lơ là, không chú ý tới, bỏ sót. Ví dụ: 忽略细节, 不可忽略的问题.","hsk_level":6,"tags":["dong-tu"],"image":"🙈","examples":[{"type":"basic","zh":"别忽略细节。","pinyin":"Bié hūlüè xìjié.","vi":"Đừng bỏ qua chi tiết."},{"type":"simple","zh":"很多人忽略了睡眠对健康的影响。","pinyin":"Hěn duō rén hūlüèle shuìmián duì jiànkāng de yǐngxiǎng.","vi":"Nhiều người xem nhẹ ảnh hưởng của giấc ngủ đối với sức khỏe."},{"type":"compound","zh":"因为他太忙于工作，所以忽略了妻子和孩子的感受。","pinyin":"Yīnwèi tā tài mángyú gōngzuò, suǒyǐ hūlüèle qīzi hé háizi de gǎnshòu.","vi":"Vì quá bận công việc nên anh ấy đã lơ là cảm xúc của vợ con."}],"related":[{"hanzi":"忽视","pinyin":"hūshì","vi":"xem nhẹ"},{"hanzi":"疏忽","pinyin":"shūhu","vi":"sơ suất"},{"hanzi":"重视","pinyin":"zhòngshì","vi":"coi trọng"},{"hanzi":"忽略不计","pinyin":"hūlüèbújì","vi":"bỏ qua không tính"}]},{"id":"呼啸","hanzi":"呼啸","pinyin":"hūxiào","meaning_vi":"gào thét (gió/còi tàu)","explanation":"Cả hai chữ đều có bộ khẩu 口.","hsk_level":6,"tags":["dong-tu","thoi-tiet"],"image":"🌬️","examples":[{"type":"basic","zh":"寒风在窗外呼啸。","pinyin":"Hánfēng zài chuāng wài hūxiào.","vi":"Gió lạnh gào thét ngoài cửa sổ."},{"type":"simple","zh":"一列火车呼啸着从我们身边驶过。","pinyin":"Yí liè huǒchē hūxiàozhe cóng wǒmen shēnbiān shǐ guò.","vi":"Một đoàn tàu rít lên lao vụt qua bên cạnh chúng tôi."},{"type":"compound","zh":"外面虽然狂风呼啸，屋里却温暖如春。","pinyin":"Wàimiàn suīrán kuángfēng hūxiào, wū lǐ què wēnnuǎn rú chūn.","vi":"Bên ngoài tuy gió dữ gào thét nhưng trong nhà lại ấm áp như mùa xuân."}],"related":[{"hanzi":"呼啸而过","pinyin":"hūxiào'érguò","vi":"rít lên lao qua"},{"hanzi":"怒吼","pinyin":"nùhǒu","vi":"gầm thét"},{"hanzi":"狂风","pinyin":"kuángfēng","vi":"gió dữ"},{"hanzi":"咆哮","pinyin":"páoxiào","vi":"gầm rú"}],"traditional":"呼嘯"},{"id":"海拔","hanzi":"海拔","pinyin":"hǎibá","meaning_vi":"độ cao so với mực nước biển","explanation":"海 (hải – biển) + 拔 (bạt – nhô lên) → độ cao so với mực nước biển. Ví dụ: 海拔八千多米, 高海拔地区.","hsk_level":6,"tags":["danh-tu","thien-nhien"],"image":"🏔️","examples":[{"type":"basic","zh":"这座山海拔很高。","pinyin":"Zhè zuò shān hǎibá hěn gāo.","vi":"Ngọn núi này có độ cao so với mực nước biển rất lớn."},{"type":"simple","zh":"拉萨的海拔超过三千六百米。","pinyin":"Lāsà de hǎibá chāoguò sān qiān liù bǎimǐ.","vi":"Lhasa nằm ở độ cao hơn 3.600 mét so với mực nước biển."},{"type":"compound","zh":"海拔越高，空气就越稀薄，所以登山者容易缺氧。","pinyin":"Hǎibá yuè gāo, kōngqì jiù yuè xībó, suǒyǐ dēngshān zhě róngyì quēyǎng.","vi":"Độ cao càng lớn, không khí càng loãng, nên người leo núi dễ bị thiếu oxy."}],"related":[{"hanzi":"高度","pinyin":"gāodù","vi":"độ cao"},{"hanzi":"海平面","pinyin":"hǎipíngmiàn","vi":"mực nước biển"},{"hanzi":"高原","pinyin":"gāoyuán","vi":"cao nguyên"},{"hanzi":"山峰","pinyin":"shānfēng","vi":"đỉnh núi"}]},{"id":"海阔天空","hanzi":"海阔天空","pinyin":"hǎikuò-tiānkōng","meaning_vi":"biển rộng trời cao (tự do phóng khoáng / nói chuyện trên trời dưới biển)","explanation":"海阔天空: biển rộng (阔) trời cao (空) → tầm nhìn, tâm hồn rộng mở tự do; cũng chỉ nói chuyện tản mạn trên trời dưới biển không có trọng tâm.","hsk_level":6,"tags":["thanh-ngu"],"image":"🌊","examples":[{"type":"basic","zh":"退一步海阔天空。","pinyin":"Tuì yí bù hǎikuòtiānkōng.","vi":"Lùi một bước, trời cao biển rộng."},{"type":"simple","zh":"两个老朋友坐在阳台上海阔天空地聊了一夜。","pinyin":"Liǎng gè lǎopéngyou zuò zài yángtái Shànghǎi kuò tiān kōngde liáole yí yè.","vi":"Hai người bạn cũ ngồi ngoài ban công trò chuyện trên trời dưới biển suốt đêm."},{"type":"compound","zh":"只要你学会放下，就会感到海阔天空。","pinyin":"Zhǐyào nǐ xuéhuì fàngxià, jiù huì gǎndào hǎikuòtiānkōng.","vi":"Chỉ cần bạn biết buông bỏ, bạn sẽ thấy trời cao biển rộng."}],"related":[{"hanzi":"天南地北","pinyin":"tiānnándìběi","vi":"trên trời dưới biển"},{"hanzi":"无拘无束","pinyin":"wújūwúshù","vi":"tự do không ràng buộc"},{"hanzi":"广阔","pinyin":"guǎngkuò","vi":"rộng lớn"},{"hanzi":"退一步海阔天空","pinyin":"tuì yí bù hǎikuòtiānkōng","vi":"một điều nhịn chín điều lành"}],"traditional":"海闊天空"},{"id":"海枯石烂","hanzi":"海枯石烂","pinyin":"hǎikū-shílàn","meaning_vi":"biển cạn đá mòn (tình yêu chung thủy vĩnh cửu)","explanation":"海枯石烂: đến khi biển cạn (枯), đá mục (烂) → lâu dài vô tận; thường dùng trong lời thề tình yêu chung thủy mãi mãi.","hsk_level":6,"tags":["thanh-ngu","cam-xuc"],"image":"❤️","examples":[{"type":"basic","zh":"海枯石烂心不变。","pinyin":"Hǎikūshílàn xīn búbiàn.","vi":"Biển cạn đá mòn lòng chẳng đổi."},{"type":"simple","zh":"他在婚礼上发誓要和她相爱到海枯石烂。","pinyin":"Tā zài hūnlǐ shàng fāshì yào hé tā xiāng'ài dào hǎikūshílàn.","vi":"Trong lễ cưới, anh thề sẽ yêu cô đến khi biển cạn đá mòn."},{"type":"compound","zh":"即使到了海枯石烂的那一天，我对你的爱也不会改变。","pinyin":"Jíshǐ dàole hǎikūshílàn de nà yì tiān, wǒ duì nǐ de ài yě bú huì gǎibiàn.","vi":"Dù đến ngày biển cạn đá mòn, tình yêu anh dành cho em cũng không thay đổi."}],"related":[{"hanzi":"海誓山盟","pinyin":"hǎishìshānméng","vi":"thề non hẹn biển"},{"hanzi":"天长地久","pinyin":"tiānchángdìjiǔ","vi":"trời đất dài lâu"},{"hanzi":"地老天荒","pinyin":"dìlǎotiānhuāng","vi":"mãi mãi trường tồn"},{"hanzi":"坚贞不渝","pinyin":"jiānzhēnbùyú","vi":"thủy chung son sắt"}],"traditional":"海枯石爛"},{"id":"海誓山盟","hanzi":"海誓山盟","pinyin":"hǎishì-shānméng","meaning_vi":"thề non hẹn biển","explanation":"海誓山盟: thề (誓) như biển, hẹn (盟) như núi → lời thề nguyền tình yêu bền vững như núi sông; tương đương \"thề non hẹn biển\".","hsk_level":6,"tags":["thanh-ngu","cam-xuc"],"image":"💍","examples":[{"type":"basic","zh":"他们曾海誓山盟。","pinyin":"Tāmen céng hǎishìshānméng.","vi":"Họ từng thề non hẹn biển."},{"type":"simple","zh":"那些海誓山盟最后都变成了一句空话。","pinyin":"Nàxiē hǎishìshānméng zuìhòu dōu biàn chéngle yíjù kōnghuà.","vi":"Những lời thề non hẹn biển ấy cuối cùng đều thành lời nói suông."},{"type":"compound","zh":"与其说一堆海誓山盟，不如每天给她做一顿早饭。","pinyin":"Yǔqíshuō yìduī hǎishìshānméng, bùrú měitiān gěi tā zuò yí dùn zǎofàn.","vi":"Thay vì nói cả đống lời thề non hẹn biển, chi bằng mỗi ngày nấu cho cô ấy một bữa sáng."}],"related":[{"hanzi":"山盟海誓","pinyin":"shānménghǎishì","vi":"thề non hẹn biển"},{"hanzi":"海枯石烂","pinyin":"hǎikūshílàn","vi":"biển cạn đá mòn"},{"hanzi":"誓言","pinyin":"shìyán","vi":"lời thề"},{"hanzi":"白头偕老","pinyin":"báitóuxiélǎo","vi":"bạc đầu giai lão"}]},{"id":"好景不长","hanzi":"好景不长","pinyin":"hǎojǐng-bùcháng","meaning_vi":"thời tốt đẹp chẳng kéo dài","explanation":"好景不长: cảnh (景) đẹp (好) không (不) kéo dài (长) → thời kỳ tốt đẹp, niềm vui thường không được lâu.","hsk_level":6,"tags":["thanh-ngu"],"image":"🥀","examples":[{"type":"basic","zh":"可惜好景不长。","pinyin":"Kěxī hǎojǐngbùcháng.","vi":"Tiếc là cảnh vui chẳng tày gang."},{"type":"simple","zh":"股市上涨的好景不长，很快又跌了回去。","pinyin":"Gǔshì shàngzhǎng de hǎojǐngbùcháng, hěn kuài yòu diēle huíqù.","vi":"Thời kỳ chứng khoán tăng giá chẳng kéo dài, chẳng mấy chốc lại tụt xuống."},{"type":"compound","zh":"虽然饭店开张时生意火爆，但是好景不长，半年后就倒闭了。","pinyin":"Suīrán fàndiàn kāizhāng shí shēngyi huǒbào, dànshì hǎojǐngbùcháng, bàn nián hòu jiù dǎobì le.","vi":"Tuy lúc khai trương nhà hàng làm ăn phát đạt, nhưng vui chẳng tày gang, nửa năm sau đã đóng cửa."}],"related":[{"hanzi":"昙花一现","pinyin":"tánhuāyíxiàn","vi":"sớm nở tối tàn"},{"hanzi":"乐极生悲","pinyin":"lèjíshēngbēi","vi":"vui quá hóa buồn"},{"hanzi":"好景","pinyin":"hǎojǐng","vi":"cảnh đẹp, thời tốt"},{"hanzi":"天有不测风云","pinyin":"tiān yǒu búcè fēngyún","vi":"trời có lúc mưa nắng bất ngờ"}],"traditional":"好景不長"},{"id":"虎头蛇尾","hanzi":"虎头蛇尾","pinyin":"hǔtóu-shéwěi","meaning_vi":"đầu voi đuôi chuột (lúc đầu rầm rộ lúc sau bỏ dở)","explanation":"虎头蛇尾: đầu hổ đuôi rắn → khởi đầu rầm rộ, về sau lơ là bỏ dở; tương đương \"đầu voi đuôi chuột\".","hsk_level":6,"tags":["thanh-ngu"],"image":"🐍","examples":[{"type":"basic","zh":"做事别虎头蛇尾。","pinyin":"Zuòshì bié hǔtóushéwěi.","vi":"Làm việc đừng đầu voi đuôi chuột."},{"type":"simple","zh":"他的减肥计划又一次虎头蛇尾地结束了。","pinyin":"Tā de jiǎnféi jìhuà yòu yí cì hǔtóushéwěi de jiéshù le.","vi":"Kế hoạch giảm cân của anh ấy lại một lần nữa kết thúc kiểu đầu voi đuôi chuột."},{"type":"compound","zh":"这部电视剧虽然开头很精彩，结局却虎头蛇尾。","pinyin":"Zhè bù diànshìjù suīrán kāitóu hěn jīngcǎi, jiéjú què hǔtóushéwěi.","vi":"Bộ phim truyền hình này tuy mở đầu rất hấp dẫn nhưng kết thúc lại đầu voi đuôi chuột."}],"related":[{"hanzi":"有始无终","pinyin":"yǒushǐwúzhōng","vi":"có đầu không cuối"},{"hanzi":"半途而废","pinyin":"bàntú'érfèi","vi":"bỏ dở giữa chừng"},{"hanzi":"有始有终","pinyin":"yǒushǐyǒuzhōng","vi":"có đầu có cuối"},{"hanzi":"善始善终","pinyin":"shànshǐshànzhōng","vi":"đầu xuôi đuôi lọt"}],"traditional":"虎頭蛇尾"},{"id":"剑","hanzi":"剑","pinyin":"jiàn","meaning_vi":"thanh kiếm","explanation":"剑 (kiếm): thanh kiếm, gươm hai lưỡi. Từ thường gặp: 宝剑, 剑术, 舞剑; thành ngữ 刻舟求剑, 唇枪舌剑.","hsk_level":6,"tags":["danh-tu","do-vat"],"image":"⚔️","examples":[{"type":"basic","zh":"爷爷每天早上练剑。","pinyin":"Yéye měitiān zǎoshang liàn jiàn.","vi":"Sáng nào ông nội cũng luyện kiếm."},{"type":"simple","zh":"博物馆里陈列着一把两千年前的青铜剑。","pinyin":"Bówùguǎn lǐ chénlièzhe yì bǎ liǎngqiānnián qián de qīngtóng jiàn.","vi":"Trong bảo tàng trưng bày một thanh kiếm đồng xanh từ hai nghìn năm trước."},{"type":"compound","zh":"他一拔出剑，围观的人就纷纷往后退。","pinyin":"Tā yì báchū jiàn, wéiguān de rén jiù fēnfēn wǎng hòutuì.","vi":"Anh ta vừa rút kiếm ra, đám đông vây xem liền lùi lại."}],"related":[{"hanzi":"宝剑","pinyin":"bǎojiàn","vi":"bảo kiếm"},{"hanzi":"刀","pinyin":"dāo","vi":"dao"},{"hanzi":"剑术","pinyin":"jiànshù","vi":"kiếm thuật"},{"hanzi":"击剑","pinyin":"jījiàn","vi":"đấu kiếm"}],"traditional":"劍"},{"id":"鉴定","hanzi":"鉴定","pinyin":"jiàndìng","meaning_vi":"giám định, thẩm định","explanation":"鉴 (giám – soi xét) + 定 (định – xác định) → giám định, thẩm định để xác nhận thật giả, chất lượng. Ví dụ: 鉴定文物, 质量鉴定.","hsk_level":6,"tags":["dong-tu"],"image":"📜","examples":[{"type":"basic","zh":"这幅画需要鉴定。","pinyin":"Zhè fú huà xūyào jiàndìng.","vi":"Bức tranh này cần được giám định."},{"type":"simple","zh":"专家鉴定后确认这只花瓶是明代的。","pinyin":"Zhuānjiā jiàndìng hòu quèrèn zhè zhī huāpíng shì Míngdài de.","vi":"Sau khi giám định, chuyên gia xác nhận chiếc bình hoa này thuộc đời Minh."},{"type":"compound","zh":"如果对事故原因有疑问，就可以申请第三方鉴定。","pinyin":"Rúguǒ duì shìgù yuányīn yǒu yíwèn, jiù kěyǐ shēnqǐng dìsānfāng jiàndìng.","vi":"Nếu có nghi vấn về nguyên nhân sự cố, có thể yêu cầu bên thứ ba giám định."}],"related":[{"hanzi":"鉴别","pinyin":"jiànbié","vi":"phân biệt giám định"},{"hanzi":"评定","pinyin":"píngdìng","vi":"đánh giá"},{"hanzi":"鉴定书","pinyin":"jiàndìngshū","vi":"giấy giám định"},{"hanzi":"检验","pinyin":"jiǎnyàn","vi":"kiểm nghiệm"}],"traditional":"鑑定"},{"id":"见利忘义","hanzi":"见利忘义","pinyin":"jiànlì-wàngyì","meaning_vi":"thấy lợi quên nghĩa","explanation":"见利忘义: thấy (见) lợi (利) thì quên (忘) nghĩa (义) → vì lợi ích mà bỏ đạo nghĩa. Mang nghĩa chê trách.","hsk_level":6,"tags":["thanh-ngu"],"image":"💸","examples":[{"type":"basic","zh":"他是个见利忘义的人。","pinyin":"Tā shì gè jiànlìwàngyì de rén.","vi":"Hắn là kẻ thấy lợi quên nghĩa."},{"type":"simple","zh":"见利忘义的合伙人卷走了公司所有的钱。","pinyin":"Jiànlìwàngyì de héhuǒrén juǎn zǒule gōngsī suǒyǒu de qián.","vi":"Gã cộng sự thấy lợi quên nghĩa đã cuỗm hết tiền của công ty."},{"type":"compound","zh":"即使面对再大的诱惑，我们也不能见利忘义。","pinyin":"Jíshǐ miànduì zài dà de yòuhuò, wǒmen yě bù néng jiànlìwàngyì.","vi":"Dù đối mặt với cám dỗ lớn đến đâu, chúng ta cũng không được thấy lợi quên nghĩa."}],"related":[{"hanzi":"唯利是图","pinyin":"wéilìshìtú","vi":"chỉ biết lợi"},{"hanzi":"忘恩负义","pinyin":"wàng'ēnfùyì","vi":"vong ân bội nghĩa"},{"hanzi":"见义勇为","pinyin":"jiànyìyǒngwéi","vi":"thấy việc nghĩa hăng hái làm"},{"hanzi":"舍生取义","pinyin":"shěshēngqǔyì","vi":"xả thân vì nghĩa"}],"traditional":"見利忘義"},{"id":"见仁见智","hanzi":"见仁见智","pinyin":"jiànrén-jiànzhì","meaning_vi":"mỗi người một quan điểm (nhân giả kiến nhân, trí giả kiến trí)","explanation":"见仁见智: từ Kinh Dịch, người nhân thấy là nhân, người trí thấy là trí → cùng một vấn đề mỗi người nhìn nhận một kiểu tùy góc độ.","hsk_level":6,"tags":["thanh-ngu"],"image":"👀","examples":[{"type":"basic","zh":"这个问题见仁见智。","pinyin":"Zhè ge wèntí jiànrénjiànzhì.","vi":"Vấn đề này mỗi người một ý."},{"type":"simple","zh":"对于这部电影的结局，观众的看法见仁见智。","pinyin":"Duìyú zhè bù diànyǐng de jiéjú, guānzhòng de kànfǎ jiànrénjiànzhì.","vi":"Về cái kết của bộ phim này, khán giả mỗi người một quan điểm."},{"type":"compound","zh":"留在大城市还是回老家本来就见仁见智，所以不必强求一致。","pinyin":"Liú zài dàchéngshì háishì huílǎojiā běnlái jiù jiànrénjiànzhì, suǒyǐ búbì qiǎngqiú yízhì.","vi":"Ở lại thành phố lớn hay về quê vốn dĩ tùy quan điểm mỗi người, nên không cần ép phải giống nhau."}],"related":[{"hanzi":"各抒己见","pinyin":"gèshūjǐjiàn","vi":"mỗi người bày tỏ ý kiến"},{"hanzi":"众说纷纭","pinyin":"zhòngshuōfēnyún","vi":"mỗi người một ý"},{"hanzi":"因人而异","pinyin":"yīnrén'éryì","vi":"tùy người mà khác"},{"hanzi":"观点","pinyin":"guāndiǎn","vi":"quan điểm"}],"traditional":"見仁見智"},{"id":"舰艇","hanzi":"舰艇","pinyin":"jiàntǐng","meaning_vi":"tàu chiến","explanation":"舰 (hạm – tàu chiến) + 艇 (đĩnh – thuyền nhỏ) → các loại tàu thuyền quân sự nói chung. Ví dụ: 海军舰艇.","hsk_level":6,"tags":["danh-tu","giao-thong"],"image":"🚢","examples":[{"type":"basic","zh":"港口停着几艘舰艇。","pinyin":"Gǎngkǒu tíngzhe jǐ sōu jiàntǐng.","vi":"Ở cảng có mấy chiếc tàu chiến đang neo đậu."},{"type":"simple","zh":"海军舰艇在这片海域进行例行巡逻。","pinyin":"Hǎijūn jiàntǐng zài zhè piàn Hǎiyù jìnxíng lìxíng xúnluó.","vi":"Tàu chiến hải quân đang tuần tra thường lệ ở vùng biển này."},{"type":"compound","zh":"一收到求救信号，附近的舰艇就立刻赶去救援。","pinyin":"Yì shōudào qiújiù xìnhào, fùjìn de jiàntǐng jiù lìkè gǎn qù jiùyuán.","vi":"Vừa nhận được tín hiệu cầu cứu, các tàu chiến gần đó liền lập tức đến ứng cứu."}],"related":[{"hanzi":"军舰","pinyin":"jūnjiàn","vi":"tàu quân sự"},{"hanzi":"航母","pinyin":"hángmǔ","vi":"tàu sân bay"},{"hanzi":"潜艇","pinyin":"qiántǐng","vi":"tàu ngầm"},{"hanzi":"海军","pinyin":"hǎijūn","vi":"hải quân"}],"traditional":"艦艇"},{"id":"见义勇为","hanzi":"见义勇为","pinyin":"jiànyì-yǒngwéi","meaning_vi":"thấy việc nghĩa hăng hái làm","explanation":"见义勇为: thấy (见) việc nghĩa (义) thì dũng cảm (勇) làm (为) → dũng cảm ra tay cứu giúp người gặp nạn, chống cái ác.","hsk_level":6,"tags":["thanh-ngu"],"image":"🦸","examples":[{"type":"basic","zh":"他见义勇为救了人。","pinyin":"Tā jiànyìyǒngwéi jiùle rén.","vi":"Anh ấy dũng cảm làm việc nghĩa, cứu được người."},{"type":"simple","zh":"市政府表彰了三位见义勇为的出租车司机。","pinyin":"Shìzhèngfǔ biǎozhāngle sān wèi jiànyìyǒngwéi de chūzūchē sījī.","vi":"Chính quyền thành phố biểu dương ba tài xế taxi thấy việc nghĩa hăng hái làm."},{"type":"compound","zh":"见义勇为固然可贵，但是也要注意保护好自己。","pinyin":"Jiànyìyǒngwéi gùrán kěguì, dànshì yě yào zhùyì bǎohù hǎo zìjǐ.","vi":"Ra tay làm việc nghĩa tuy đáng quý, nhưng cũng phải chú ý bảo vệ bản thân."}],"related":[{"hanzi":"挺身而出","pinyin":"tǐngshēn'érchū","vi":"đứng ra dũng cảm"},{"hanzi":"见死不救","pinyin":"jiànsǐbújiù","vi":"thấy chết không cứu"},{"hanzi":"舍己救人","pinyin":"shějǐjiùrén","vi":"xả thân cứu người"},{"hanzi":"英勇","pinyin":"yīngyǒng","vi":"anh dũng"}],"traditional":"見義勇為"},{"id":"较量","hanzi":"较量","pinyin":"jiàoliàng","meaning_vi":"đọ sức","explanation":"较 (giảo – so) + 量 (lượng – đo) → so tài, đọ sức, đấu với nhau. Ví dụ: 一场较量, 跟对手较量.","hsk_level":6,"tags":["dong-tu"],"image":"⚔️","examples":[{"type":"basic","zh":"两队展开较量。","pinyin":"Liǎng duì zhǎnkāi jiàoliàng.","vi":"Hai đội bắt đầu đọ sức."},{"type":"simple","zh":"这是一场实力与意志的较量。","pinyin":"Zhè shì yì chǎng shílì yǔ yìzhì de jiàoliàng.","vi":"Đây là cuộc đọ sức giữa thực lực và ý chí."},{"type":"compound","zh":"既然你不服气，那我们就在球场上较量一下。","pinyin":"Jìrán nǐ bùfúqì, nà wǒmen jiù zài qiúchǎng shàng jiàoliàng yíxià.","vi":"Đã không phục thì chúng ta đọ sức một phen trên sân bóng."}],"related":[{"hanzi":"比赛","pinyin":"bǐsài","vi":"thi đấu"},{"hanzi":"竞争","pinyin":"jìngzhēng","vi":"cạnh tranh"},{"hanzi":"对抗","pinyin":"duìkàng","vi":"đối kháng"},{"hanzi":"比试","pinyin":"bǐshi","vi":"so tài"}],"traditional":"較量"},{"id":"戒备","hanzi":"戒备","pinyin":"jièbèi","meaning_vi":"canh phòng, đề phòng","explanation":"戒 (giới – đề phòng) + 备 (bị – chuẩn bị) → canh phòng, đề phòng, cảnh giác. Ví dụ: 戒备森严 (canh phòng nghiêm ngặt), 戒备心.","hsk_level":6,"tags":["dong-tu"],"image":"🛡️","examples":[{"type":"basic","zh":"警察严密戒备。","pinyin":"Jǐngchá yánmì jièbèi.","vi":"Cảnh sát canh phòng nghiêm ngặt."},{"type":"simple","zh":"她对陌生人一直保持着戒备的心理。","pinyin":"Tā duì mòshēngrén yìzhí bǎochízhe jièbèi de xīnlǐ.","vi":"Cô ấy luôn giữ tâm lý cảnh giác với người lạ."},{"type":"compound","zh":"因为台风即将登陆，所以沿海地区全面进入戒备状态。","pinyin":"Yīnwèi táifēng jíjiāng dēnglù, suǒyǐ yánhǎi dìqū quánmiàn jìnrù jièbèi zhuàngtài.","vi":"Vì bão sắp đổ bộ nên các vùng ven biển đều vào trạng thái cảnh giác cao độ."}],"related":[{"hanzi":"防备","pinyin":"fángbèi","vi":"phòng bị"},{"hanzi":"警惕","pinyin":"jǐngtì","vi":"cảnh giác"},{"hanzi":"戒备森严","pinyin":"jièbèisēnyán","vi":"canh phòng nghiêm ngặt"},{"hanzi":"警戒","pinyin":"jǐngjiè","vi":"cảnh giới"}],"traditional":"戒備"},{"id":"借助","hanzi":"借助","pinyin":"jièzhù","meaning_vi":"nhờ vào","explanation":"借 (tá – mượn) + 助 (trợ – giúp) → nhờ vào, dựa vào sự trợ giúp của cái gì. Ví dụ: 借助工具, 借助网络.","hsk_level":6,"tags":["dong-tu"],"image":"🤝","examples":[{"type":"basic","zh":"借助词典阅读。","pinyin":"Jièzhù cídiǎn yuèdú.","vi":"Đọc sách nhờ vào từ điển."},{"type":"simple","zh":"他借助拐杖慢慢地走到了门口。","pinyin":"Tā jièzhù guǎizhàng mànmàn de zǒu dàole ménkǒu.","vi":"Ông ấy chống gậy chậm rãi đi ra đến cửa."},{"type":"compound","zh":"如果借助人工智能，翻译效率就能大大提高。","pinyin":"Rúguǒ jièzhù réngōngzhìnéng, fānyì xiàolǜ jiù néng dàdà tígāo.","vi":"Nếu nhờ vào trí tuệ nhân tạo, hiệu suất dịch thuật sẽ được nâng cao đáng kể."}],"related":[{"hanzi":"依靠","pinyin":"yīkào","vi":"dựa vào"},{"hanzi":"凭借","pinyin":"píngjiè","vi":"nhờ vào"},{"hanzi":"利用","pinyin":"lìyòng","vi":"lợi dụng, tận dụng"},{"hanzi":"借鉴","pinyin":"jièjiàn","vi":"tham khảo"}],"traditional":"藉助"},{"id":"竭尽全力","hanzi":"竭尽全力","pinyin":"jiéjìn-quánlì","meaning_vi":"dốc hết toàn lực","explanation":"竭尽全力: dùng hết (竭尽) toàn bộ (全) sức lực (力) → dốc hết sức mình. Ví dụ: 我们将竭尽全力完成任务.","hsk_level":6,"tags":["thanh-ngu"],"image":"💪","examples":[{"type":"basic","zh":"我会竭尽全力。","pinyin":"Wǒ huì jiéjìnquánlì.","vi":"Tôi sẽ dốc hết sức."},{"type":"simple","zh":"消防员竭尽全力扑灭了仓库的大火。","pinyin":"Xiāofángyuán jiéjìnquánlì pūmièle cāngkù de dàhuǒ.","vi":"Lính cứu hỏa dốc toàn lực dập tắt đám cháy lớn ở nhà kho."},{"type":"compound","zh":"只要我们竭尽全力了，即使输掉比赛也不会后悔。","pinyin":"Zhǐyào wǒmen jiéjìnquánlì le, jíshǐ shūdiào bǐsài yě bú huì hòuhuǐ.","vi":"Chỉ cần chúng ta đã dốc hết toàn lực thì dù có thua trận cũng không hối tiếc."}],"related":[{"hanzi":"全力以赴","pinyin":"quánlìyǐfù","vi":"dốc toàn lực"},{"hanzi":"尽力而为","pinyin":"jìnlì'érwéi","vi":"cố gắng hết sức"},{"hanzi":"不遗余力","pinyin":"bùyíyúlì","vi":"không tiếc sức"},{"hanzi":"敷衍了事","pinyin":"fūyǎnliǎoshì","vi":"làm qua loa"}],"traditional":"竭盡全力"},{"id":"结晶","hanzi":"结晶","pinyin":"jiéjīng","meaning_vi":"kết tinh","explanation":"结 (kết – kết lại) + 晶 (tinh – tinh thể) → kết tinh; nghĩa bóng: thành quả quý giá của nhiều công sức. Ví dụ: 智慧的结晶, 爱情的结晶.","hsk_level":6,"tags":["danh-tu"],"image":"💎","examples":[{"type":"basic","zh":"这是汗水的结晶。","pinyin":"Zhè shì hànshuǐ de jiéjīng.","vi":"Đây là kết tinh của mồ hôi."},{"type":"simple","zh":"这本词典是三代学者智慧的结晶。","pinyin":"Zhè běn cídiǎn shì sāndài xuézhě zhìhuì de jiéjīng.","vi":"Cuốn từ điển này là kết tinh trí tuệ của ba thế hệ học giả."},{"type":"compound","zh":"盐水一蒸发，杯底就会留下白色的盐结晶。","pinyin":"Yánshuǐ yì zhēngfā, bēi dǐ jiù huì liúxià báisè de yán jiéjīng.","vi":"Nước muối vừa bay hơi, đáy cốc sẽ để lại tinh thể muối màu trắng."}],"related":[{"hanzi":"晶体","pinyin":"jīngtǐ","vi":"tinh thể"},{"hanzi":"心血","pinyin":"xīnxuè","vi":"tâm huyết"},{"hanzi":"成果","pinyin":"chéngguǒ","vi":"thành quả"},{"hanzi":"智慧的结晶","pinyin":"zhìhuì de jiéjīng","vi":"kết tinh trí tuệ"}],"traditional":"結晶"},{"id":"节目","hanzi":"节目","pinyin":"jiémù","meaning_vi":"chương trình","explanation":"节 (tiết – đoạn, mục) + 目 (mục – mục) → tiết mục, chương trình (biểu diễn, phát thanh, truyền hình). Ví dụ: 电视节目, 文艺节目.","hsk_level":6,"tags":["danh-tu","giai-tri"],"image":"📺","examples":[{"type":"basic","zh":"这个节目很好看。","pinyin":"Zhè ge jiémù hěn hǎokàn.","vi":"Chương trình này rất hay."},{"type":"simple","zh":"春节联欢晚会上有很多精彩的节目。","pinyin":"Chūnjiéliánhuānwǎnhuì shàng yǒu hěn duō jīngcǎi de jiémù.","vi":"Đêm hội Xuân có rất nhiều tiết mục đặc sắc."},{"type":"compound","zh":"我一下班就打开电视，看我最喜欢的美食节目。","pinyin":"Wǒ yí xiàbān jiù dǎkāi diànshì, kàn wǒ zuì xǐhuan de měishí jiémù.","vi":"Tôi vừa tan làm là bật ti vi xem chương trình ẩm thực yêu thích."}],"related":[{"hanzi":"电视节目","pinyin":"diànshìjiémù","vi":"chương trình truyền hình"},{"hanzi":"表演","pinyin":"biǎoyǎn","vi":"biểu diễn"},{"hanzi":"主持人","pinyin":"zhǔchírén","vi":"người dẫn chương trình"},{"hanzi":"节目单","pinyin":"jiémùdān","vi":"danh sách tiết mục"}],"traditional":"節目"},{"id":"截然不同","hanzi":"截然不同","pinyin":"jiérán-bùtóng","meaning_vi":"hoàn toàn khác biệt","explanation":"截然不同: khác nhau (不同) rạch ròi như cắt (截然) → hoàn toàn khác biệt. Ví dụ: 两种截然不同的观点.","hsk_level":6,"tags":["thanh-ngu"],"image":"↔️","examples":[{"type":"basic","zh":"结果截然不同。","pinyin":"Jiéguǒ jiéránbùtóng.","vi":"Kết quả hoàn toàn khác nhau."},{"type":"simple","zh":"南北方的饮食习惯截然不同。","pinyin":"Nán běifāng de yǐnshí xíguàn jiéránbùtóng.","vi":"Thói quen ăn uống của miền Nam và miền Bắc hoàn toàn khác nhau."},{"type":"compound","zh":"虽然是双胞胎，但是她们对未来的规划截然不同。","pinyin":"Suīrán shì shuāngbāotāi, dànshì tāmen duì wèilái de guīhuà jiéránbùtóng.","vi":"Tuy là chị em sinh đôi nhưng kế hoạch tương lai của họ hoàn toàn khác nhau."}],"related":[{"hanzi":"天壤之别","pinyin":"tiānrǎngzhībié","vi":"khác nhau một trời một vực"},{"hanzi":"迥然不同","pinyin":"jiǒngránbùtóng","vi":"khác hẳn"},{"hanzi":"大同小异","pinyin":"dàtóngxiǎoyì","vi":"na ná nhau"},{"hanzi":"一模一样","pinyin":"yìmúyíyàng","vi":"giống hệt"}]},{"id":"截至","hanzi":"截至","pinyin":"jiézhì","meaning_vi":"tính đến","explanation":"截 (tiệt – cắt) + 至 (chí – đến) → tính đến (mốc thời gian), dùng trong văn bản thống kê. Ví dụ: 截至今年六月. Phân biệt 截止 (hết hạn).","hsk_level":6,"tags":["gioi-tu"],"image":"📅","examples":[{"type":"basic","zh":"截至昨天，已报名三百人。","pinyin":"Jiézhì zuótiān, yǐ bàomíng sān bǎi rén.","vi":"Tính đến hôm qua, đã có ba trăm người đăng ký."},{"type":"simple","zh":"截至目前，警方还没有找到失踪的孩子。","pinyin":"Jiézhì mùqián, jǐngfāng hái méiyǒu zhǎodào shīzōng de háizi.","vi":"Tính đến nay, cảnh sát vẫn chưa tìm thấy đứa trẻ mất tích."},{"type":"compound","zh":"截至上个月底，这款手机不但销量破百万，而且好评率很高。","pinyin":"Jiézhì shànggè yuèdǐ, zhè kuǎn shǒujī búdàn xiāoliàng pò bǎiwàn, érqiě hǎopínglǜ hěn gāo.","vi":"Tính đến cuối tháng trước, mẫu điện thoại này không chỉ bán được hơn một triệu chiếc mà tỷ lệ đánh giá tốt còn rất cao."}],"related":[{"hanzi":"截止","pinyin":"jiézhǐ","vi":"hết hạn"},{"hanzi":"为止","pinyin":"wéizhǐ","vi":"cho đến khi"},{"hanzi":"截止日期","pinyin":"jiézhǐrìqī","vi":"hạn chót"},{"hanzi":"至今","pinyin":"zhìjīn","vi":"đến nay"}]},{"id":"救死扶伤","hanzi":"救死扶伤","pinyin":"jiùsǐ-fúshāng","meaning_vi":"cứu người bị thương chữa người nguy kịch (y đức)","explanation":"救死扶伤: cứu (救) người sắp chết (死), giúp đỡ (扶) người bị thương (伤) → tinh thần cứu người của ngành y, y đức.","hsk_level":6,"tags":["thanh-ngu","suc-khoe"],"image":"🚑","examples":[{"type":"basic","zh":"护士们救死扶伤。","pinyin":"Hùshimen jiùsǐfúshāng.","vi":"Các y tá cứu chữa người bệnh."},{"type":"simple","zh":"这位老医生救死扶伤了整整四十年。","pinyin":"Zhè wèi lǎo yīshēng jiùsǐfúshāngle zhěngzhěng sìshí nián.","vi":"Vị bác sĩ già này đã cứu người chữa bệnh suốt bốn mươi năm."},{"type":"compound","zh":"救死扶伤是医生的天职，所以他连夜赶回了医院。","pinyin":"Jiùsǐfúshāng shì yīshēng de tiānzhí, suǒyǐ tā liányè gǎn huíle yīyuàn.","vi":"Cứu người là thiên chức của bác sĩ, nên anh ấy đã trở về bệnh viện ngay trong đêm."}],"related":[{"hanzi":"治病救人","pinyin":"zhìbìngjiùrén","vi":"chữa bệnh cứu người"},{"hanzi":"医德","pinyin":"yīdé","vi":"y đức"},{"hanzi":"白衣天使","pinyin":"báiyītiānshǐ","vi":"thiên thần áo trắng"},{"hanzi":"抢救","pinyin":"qiǎngjiù","vi":"cấp cứu"}],"traditional":"救死扶傷"},{"id":"就职","hanzi":"就职","pinyin":"jiùzhí","meaning_vi":"nhậm chức","explanation":"就 (tựu – đến, nhận) + 职 (chức – chức vụ) → nhậm chức, chính thức nhận chức (thường chức vụ cao). Ví dụ: 就职典礼, 宣誓就职.","hsk_level":6,"tags":["dong-tu"],"image":"👔","examples":[{"type":"basic","zh":"新总统宣誓就职。","pinyin":"Xīn zǒngtǒng xuānshì jiùzhí.","vi":"Tân tổng thống tuyên thệ nhậm chức."},{"type":"simple","zh":"他毕业后就职于一家外资银行。","pinyin":"Tā bìyè hòu jiùzhí yú yìjiā wàizī yínháng.","vi":"Sau khi tốt nghiệp anh ấy làm việc tại một ngân hàng vốn nước ngoài."},{"type":"compound","zh":"新市长一就职，就开始着手解决交通拥堵问题。","pinyin":"Xīn shìzhǎng yí jiùzhí, jiù kāishǐ zhuóshǒu jiějué jiāotōng yōngdǔ wèntí.","vi":"Tân thị trưởng vừa nhậm chức đã bắt tay giải quyết vấn đề ùn tắc giao thông."}],"related":[{"hanzi":"就任","pinyin":"jiùrèn","vi":"nhậm chức"},{"hanzi":"上任","pinyin":"shàngrèn","vi":"nhậm chức"},{"hanzi":"辞职","pinyin":"cízhí","vi":"từ chức"},{"hanzi":"就职典礼","pinyin":"jiùzhídiǎnlǐ","vi":"lễ nhậm chức"}],"traditional":"就職"},{"id":"家常便饭","hanzi":"家常便饭","pinyin":"jiācháng-biànfàn","meaning_vi":"chuyện thường như cơm bữa","explanation":"家常便饭: bữa cơm thường ngày trong nhà → chuyện bình thường, xảy ra thường xuyên như cơm bữa. Ví dụ: 加班是家常便饭.","hsk_level":6,"tags":["thanh-ngu","an-uong"],"image":"🍚","examples":[{"type":"basic","zh":"加班是家常便饭。","pinyin":"Jiābān shì jiāchángbiànfàn.","vi":"Tăng ca là chuyện cơm bữa."},{"type":"simple","zh":"对于记者来说，熬夜赶稿是家常便饭。","pinyin":"Duìyú jìzhě lái shuō, áoyè gǎn gǎo shì jiāchángbiànfàn.","vi":"Với phóng viên, thức đêm viết bài là chuyện thường ngày."},{"type":"compound","zh":"因为家里穷，所以挨饿在我小时候是家常便饭。","pinyin":"Yīnwèi jiālǐ qióng, suǒyǐ ái'è zài wǒ xiǎoshíhou shì jiāchángbiànfàn.","vi":"Vì nhà nghèo nên hồi nhỏ chịu đói là chuyện cơm bữa với tôi."}],"related":[{"hanzi":"司空见惯","pinyin":"sīkōngjiànguàn","vi":"chuyện thường gặp"},{"hanzi":"习以为常","pinyin":"xíyǐwéicháng","vi":"quen thành thói"},{"hanzi":"家常菜","pinyin":"jiāchángcài","vi":"món ăn gia đình"},{"hanzi":"罕见","pinyin":"hǎnjiàn","vi":"hiếm thấy"}],"traditional":"家常便飯"},{"id":"家伙","hanzi":"家伙","pinyin":"jiāhuo","meaning_vi":"gã, tên, thằng cha (khẩu ngữ); đồ nghề, dụng cụ","explanation":"家 (gia – nhà) + 伙 (hỏa – bọn, nhóm) → khẩu ngữ chỉ người với ý thân mật hoặc khinh (这家伙); cũng chỉ dụng cụ, vũ khí hay con vật.","hsk_level":6,"tags":["danh-tu","con-nguoi","do-vat"],"image":"🧑","examples":[{"type":"basic","zh":"这家伙真狡猾。","pinyin":"Zhè jiāhuo zhēn jiǎohuá.","vi":"Gã này thật xảo quyệt."},{"type":"simple","zh":"修理工从包里拿出几件家伙开始修水管。","pinyin":"Xiū lǐgōng cóng bāo lǐ náchū jǐ jiàn jiāhuo kāishǐ xiū shuǐguǎn.","vi":"Người thợ lấy ra mấy món đồ nghề trong túi rồi bắt đầu sửa ống nước."},{"type":"compound","zh":"那个小家伙虽然才三岁，但是已经会背很多唐诗了。","pinyin":"Nà ge xiǎo jiāhuo suīrán cái sān suì, dànshì yǐjīng huì bèi hěn duō Tángshī le.","vi":"Nhóc con đó tuy mới ba tuổi nhưng đã thuộc nhiều bài thơ Đường."}],"related":[{"hanzi":"东西","pinyin":"dōngxi","vi":"đồ, thứ"},{"hanzi":"小子","pinyin":"xiǎozi","vi":"thằng nhóc"},{"hanzi":"工具","pinyin":"gōngjù","vi":"đồ nghề"},{"hanzi":"那个家伙","pinyin":"nàgejiāhuo","vi":"cái gã đó"}],"traditional":"傢伙"},{"id":"佳节","hanzi":"佳节","pinyin":"jiājié","meaning_vi":"ngày lễ đẹp, dịp lễ lớn","explanation":"佳 (đẹp) + 节 (ngày lễ).","hsk_level":6,"tags":["danh-tu","van-hoa","thoi-gian"],"image":"🏮","examples":[{"type":"basic","zh":"中秋佳节快到了。","pinyin":"Zhōngqiū jiājié kuài dào le.","vi":"Tết Trung thu sắp đến rồi."},{"type":"simple","zh":"每逢佳节，在外的游子都格外想家。","pinyin":"Měiféng jiājié, zài wài de yóuzǐ dōu géwài xiǎngjiā.","vi":"Mỗi dịp lễ tết, những người con xa quê đều đặc biệt nhớ nhà."},{"type":"compound","zh":"新春佳节一到，大街小巷就挂满了红灯笼。","pinyin":"Xīnchūn jiājié yí dào, dàjiēxiǎoxiàng jiù guà mǎnle hóngdēnglong.","vi":"Dịp Tết vừa đến, khắp phố lớn ngõ nhỏ đã treo đầy đèn lồng đỏ."}],"related":[{"hanzi":"节日","pinyin":"jiérì","vi":"ngày lễ"},{"hanzi":"春节","pinyin":"Chūnjié","vi":"Tết Nguyên đán"},{"hanzi":"中秋节","pinyin":"Zhōngqiūjié","vi":"Tết Trung thu"},{"hanzi":"每逢佳节倍思亲","pinyin":"měiféng jiājié bèi sīqīn","vi":"mỗi dịp lễ càng nhớ người thân"}],"traditional":"佳節"},{"id":"嘉奖","hanzi":"嘉奖","pinyin":"jiājiǎng","meaning_vi":"khen thưởng, biểu dương","explanation":"嘉 (tốt đẹp) + 奖 (thưởng).","hsk_level":6,"tags":["dong-tu"],"image":"🏅","examples":[{"type":"basic","zh":"上级嘉奖了这支队伍。","pinyin":"Shàngjí jiājiǎngle zhè zhī duìwu.","vi":"Cấp trên đã khen thưởng đội ngũ này."},{"type":"simple","zh":"公司嘉奖了在疫情期间坚守岗位的员工。","pinyin":"Gōngsī jiājiǎngle zài yìqíng qījiān jiānshǒu gǎngwèi de yuángōng.","vi":"Công ty khen thưởng những nhân viên bám trụ vị trí trong thời gian dịch bệnh."},{"type":"compound","zh":"因为他在抗洪中表现突出，所以受到了部队的嘉奖。","pinyin":"Yīnwèi tā zài kànghóng zhōng biǎoxiàn tūchū, suǒyǐ shòudàole bùduì de jiājiǎng.","vi":"Vì thể hiện xuất sắc trong đợt chống lũ nên anh ấy được đơn vị khen thưởng."}],"related":[{"hanzi":"奖励","pinyin":"jiǎnglì","vi":"khen thưởng"},{"hanzi":"表彰","pinyin":"biǎozhāng","vi":"biểu dương"},{"hanzi":"表扬","pinyin":"biǎoyáng","vi":"khen ngợi"},{"hanzi":"处分","pinyin":"chǔfèn","vi":"kỷ luật"}],"traditional":"嘉獎"},{"id":"加剧","hanzi":"加剧","pinyin":"jiājù","meaning_vi":"làm trầm trọng thêm, tăng mạnh","explanation":"加 + 剧 (dữ dội).","hsk_level":6,"tags":["dong-tu"],"image":"📈","examples":[{"type":"basic","zh":"病情加剧了。","pinyin":"Bìngqíng jiājù le.","vi":"Bệnh tình đã trở nặng."},{"type":"simple","zh":"全球变暖加剧了冰川融化的速度。","pinyin":"Quánqiúbiànnuǎn jiājùle bīngchuān rónghuà de sùdù.","vi":"Sự ấm lên toàn cầu làm tăng mạnh tốc độ tan băng."},{"type":"compound","zh":"如果不及时处理，双方的矛盾就会进一步加剧。","pinyin":"Rúguǒ bù jíshí chǔlǐ, shuāngfāng de máodùn jiù huì jìnyíbù jiājù.","vi":"Nếu không xử lý kịp thời, mâu thuẫn hai bên sẽ càng trầm trọng thêm."}],"related":[{"hanzi":"加重","pinyin":"jiāzhòng","vi":"tăng nặng"},{"hanzi":"恶化","pinyin":"èhuà","vi":"xấu đi"},{"hanzi":"缓解","pinyin":"huǎnjiě","vi":"giảm bớt"},{"hanzi":"激化","pinyin":"jīhuà","vi":"trở nên gay gắt"}],"traditional":"加劇"},{"id":"家破人亡","hanzi":"家破人亡","pinyin":"jiāpò-rénwáng","meaning_vi":"nhà tan cửa nát","explanation":"家破人亡: nhà (家) tan (破), người (人) chết (亡) → gia đình tan nát, cửa nát nhà tan do thiên tai, chiến tranh.","hsk_level":6,"tags":["thanh-ngu"],"image":"🏚️","examples":[{"type":"basic","zh":"战争使他家破人亡。","pinyin":"Zhànzhēng shǐ tā jiāpòrénwáng.","vi":"Chiến tranh khiến anh ấy nhà tan cửa nát."},{"type":"simple","zh":"一场大洪水让村里好几户人家家破人亡。","pinyin":"Yì chǎng dà hóngshuǐ ràng cūnlǐ hǎojǐ hù rénjiā jiāpòrénwáng.","vi":"Một trận lũ lớn khiến mấy hộ trong làng nhà tan cửa nát."},{"type":"compound","zh":"因为沉迷赌博，所以他最后落得个家破人亡的下场。","pinyin":"Yīnwèi chénmí dǔbó, suǒyǐ tā zuìhòu luòde gè jiāpòrénwáng de xiàchǎng.","vi":"Vì sa vào cờ bạc nên cuối cùng hắn rơi vào cảnh nhà tan cửa nát."}],"related":[{"hanzi":"妻离子散","pinyin":"qīlízǐsàn","vi":"vợ con ly tán"},{"hanzi":"流离失所","pinyin":"liúlíshīsuǒ","vi":"lưu lạc không nơi ở"},{"hanzi":"家庭","pinyin":"jiātíng","vi":"gia đình"},{"hanzi":"团圆","pinyin":"tuányuán","vi":"đoàn tụ"}]},{"id":"坚持不懈","hanzi":"坚持不懈","pinyin":"jiānchí-búxiè","meaning_vi":"kiên trì không mệt mỏi","explanation":"坚持不懈: kiên trì (坚持), không (不) lơi lỏng (懈) → bền bỉ kiên trì đến cùng. Ví dụ: 坚持不懈地努力.","hsk_level":6,"tags":["thanh-ngu"],"image":"💪","examples":[{"type":"basic","zh":"学外语要坚持不懈。","pinyin":"Xué wàiyǔ yào jiānchíbúxiè.","vi":"Học ngoại ngữ phải kiên trì bền bỉ."},{"type":"simple","zh":"经过三年坚持不懈的锻炼，他终于跑完了马拉松。","pinyin":"Jīngguò sān nián jiānchíbúxiè de duànliàn, tā zhōngyú pǎo wánle mǎlāsōng.","vi":"Sau ba năm rèn luyện không ngừng, anh ấy cuối cùng đã chạy hết cự ly marathon."},{"type":"compound","zh":"只要坚持不懈地练习，你的书法就一定会进步。","pinyin":"Zhǐyào jiānchíbúxiè de liànxí, nǐ de shūfǎ jiù yídìng huì jìnbù.","vi":"Chỉ cần kiên trì luyện tập không ngừng, thư pháp của bạn nhất định sẽ tiến bộ."}],"related":[{"hanzi":"持之以恒","pinyin":"chízhīyǐhéng","vi":"bền bỉ kiên trì"},{"hanzi":"锲而不舍","pinyin":"qiè'érbùshě","vi":"bền chí không bỏ"},{"hanzi":"半途而废","pinyin":"bàntú'érfèi","vi":"bỏ dở giữa chừng"},{"hanzi":"坚持","pinyin":"jiānchí","vi":"kiên trì"}],"traditional":"堅持不懈"},{"id":"尖端","hanzi":"尖端","pinyin":"jiānduān","meaning_vi":"tiên tiến nhất","explanation":"尖 (tiêm – nhọn) + 端 (đoan – đầu) → đầu nhọn; nghĩa bóng: tiên tiến nhất, mũi nhọn. Ví dụ: 尖端技术, 尖端科学.","hsk_level":6,"tags":["tinh-tu"],"image":"🚀","examples":[{"type":"basic","zh":"这是尖端技术。","pinyin":"Zhè shì jiānduān jìshù.","vi":"Đây là công nghệ tiên tiến nhất."},{"type":"simple","zh":"这家实验室拥有世界上最尖端的设备。","pinyin":"Zhè jiā shíyànshì yōngyǒu shìjiè shàng zuì jiānduān de shèbèi.","vi":"Phòng thí nghiệm này sở hữu thiết bị tối tân nhất thế giới."},{"type":"compound","zh":"尖端人才不但要培养，而且要想办法留住。","pinyin":"Jiānduān réncái búdàn yào péiyǎng, érqiě yào xiǎngbànfǎ liúzhù.","vi":"Nhân tài hàng đầu không những phải đào tạo mà còn phải tìm cách giữ chân."}],"related":[{"hanzi":"先进","pinyin":"xiānjìn","vi":"tiên tiến"},{"hanzi":"高科技","pinyin":"gāokējì","vi":"công nghệ cao"},{"hanzi":"前沿","pinyin":"qiányán","vi":"tiền tuyến, mũi nhọn"},{"hanzi":"落后","pinyin":"luòhòu","vi":"lạc hậu"}]},{"id":"坚固","hanzi":"坚固","pinyin":"jiāngù","meaning_vi":"kiên cố","explanation":"坚 (kiên – cứng) + 固 (cố – vững) → kiên cố, chắc chắn, vững bền. Ví dụ: 坚固的房子, 坚固耐用.","hsk_level":6,"tags":["tinh-tu"],"image":"🏰","examples":[{"type":"basic","zh":"这座桥很坚固。","pinyin":"Zhè zuò qiáo hěn jiāngù.","vi":"Cây cầu này rất kiên cố."},{"type":"simple","zh":"古城四周围着一道坚固的石墙。","pinyin":"Gǔchéng sì zhōuwéizhe yídào jiāngù de shí qiáng.","vi":"Xung quanh cổ thành bao bọc một bức tường đá kiên cố."},{"type":"compound","zh":"这种箱子既坚固又轻便，非常适合长途旅行。","pinyin":"Zhè zhǒng xiāngzi jì jiāngù yòu qīngbiàn, fēicháng shìhé chángtú lǚxíng.","vi":"Loại vali này vừa chắc chắn vừa nhẹ, rất hợp cho những chuyến đi xa."}],"related":[{"hanzi":"牢固","pinyin":"láogù","vi":"vững chắc"},{"hanzi":"结实","pinyin":"jiēshi","vi":"chắc chắn"},{"hanzi":"坚不可摧","pinyin":"jiānbùkěcuī","vi":"không thể phá vỡ"},{"hanzi":"脆弱","pinyin":"cuìruò","vi":"mong manh"}],"traditional":"堅固"},{"id":"兼顾","hanzi":"兼顾","pinyin":"jiāngù","meaning_vi":"chiếu cố cả hai mặt, kiêm cả hai","explanation":"兼 (kiêm) + 顾 (quan tâm).","hsk_level":6,"tags":["dong-tu"],"image":"⚖️","examples":[{"type":"basic","zh":"工作学习要兼顾。","pinyin":"Gōngzuò xuéxí yào jiāngù.","vi":"Phải lo cả công việc lẫn học tập."},{"type":"simple","zh":"这个方案兼顾了经济发展和环境保护。","pinyin":"Zhè ge fāng'àn jiāngùle jīngjì fāzhǎn hé huánjìngbǎohù.","vi":"Phương án này chú ý cả phát triển kinh tế lẫn bảo vệ môi trường."},{"type":"compound","zh":"她既要上班又要照顾孩子，实在很难兼顾。","pinyin":"Tā jì yào shàngbān yòu yào zhàogù háizi, shízài hěn nán jiāngù.","vi":"Cô ấy vừa phải đi làm vừa phải chăm con, thực sự khó mà lo trọn cả hai."}],"related":[{"hanzi":"两全其美","pinyin":"liǎngquánqíměi","vi":"vẹn cả đôi đường"},{"hanzi":"照顾","pinyin":"zhàogù","vi":"chăm lo"},{"hanzi":"兼职","pinyin":"jiānzhí","vi":"kiêm nhiệm"},{"hanzi":"顾此失彼","pinyin":"gùcǐshībǐ","vi":"được cái này mất cái kia"}],"traditional":"兼顧"},{"id":"艰苦奋斗","hanzi":"艰苦奋斗","pinyin":"jiānkǔ-fèndòu","meaning_vi":"gian khổ phấn đấu","explanation":"艰苦奋斗: chịu gian khổ (艰苦) mà phấn đấu (奋斗) → làm việc cần cù, vượt khó để đạt mục tiêu. Khẩu hiệu quen thuộc ở Trung Quốc.","hsk_level":6,"tags":["thanh-ngu"],"image":"⛰️","examples":[{"type":"basic","zh":"我们要艰苦奋斗。","pinyin":"Wǒmen yào jiānkǔfèndòu.","vi":"Chúng ta phải gian khổ phấn đấu."},{"type":"simple","zh":"老一辈人靠艰苦奋斗建起了这座城市。","pinyin":"Lǎoyíbèi rén kào jiānkǔfèndòu jiàn qǐle zhè zuò chéngshì.","vi":"Thế hệ đi trước đã dựng nên thành phố này nhờ gian khổ phấn đấu."},{"type":"compound","zh":"即使生活条件变好了，艰苦奋斗的精神也不能丢。","pinyin":"Jíshǐ shēnghuó tiáojiàn biàn hǎo le, jiānkǔfèndòu de jīngshén yě bù néng diū.","vi":"Dù điều kiện sống đã tốt hơn, tinh thần gian khổ phấn đấu cũng không được đánh mất."}],"related":[{"hanzi":"奋斗","pinyin":"fèndòu","vi":"phấn đấu"},{"hanzi":"自力更生","pinyin":"zìlìgēngshēng","vi":"tự lực cánh sinh"},{"hanzi":"艰苦","pinyin":"jiānkǔ","vi":"gian khổ"},{"hanzi":"吃苦耐劳","pinyin":"chīkǔnàiláo","vi":"chịu thương chịu khó"}],"traditional":"艱苦奮鬥"},{"id":"艰难","hanzi":"艰难","pinyin":"jiānnán","meaning_vi":"gian nan","explanation":"艰 (gian – khó) + 难 (nan – khó) → gian nan, khó khăn vất vả. Ví dụ: 生活艰难, 艰难的选择, 艰难地前进.","hsk_level":6,"tags":["tinh-tu"],"image":"⛰️","examples":[{"type":"basic","zh":"他艰难地站起来。","pinyin":"Tā jiānnán de zhànqǐlái.","vi":"Anh ấy khó nhọc đứng dậy."},{"type":"simple","zh":"那几年，他们一家过着十分艰难的日子。","pinyin":"Nà jǐ nián, tāmen yìjiāguò zhe shífēn jiānnán de rìzi.","vi":"Những năm đó, gia đình họ sống những ngày tháng hết sức gian nan."},{"type":"compound","zh":"尽管谈判进展艰难，但是双方都没有放弃。","pinyin":"Jǐnguǎn tánpàn jìnzhǎn jiānnán, dànshì shuāngfāng dōu méiyǒu fàngqì.","vi":"Mặc dù đàm phán tiến triển khó khăn, nhưng hai bên đều không bỏ cuộc."}],"related":[{"hanzi":"困难","pinyin":"kùnnan","vi":"khó khăn"},{"hanzi":"艰苦","pinyin":"jiānkǔ","vi":"gian khổ"},{"hanzi":"艰辛","pinyin":"jiānxīn","vi":"gian truân"},{"hanzi":"容易","pinyin":"róngyì","vi":"dễ dàng"}],"traditional":"艱難"},{"id":"兼容","hanzi":"兼容","pinyin":"jiānróng","meaning_vi":"tương thích (phần mềm/hệ thống), bao dung","explanation":"兼 + 容 (chứa đựng).","hsk_level":6,"tags":["dong-tu","cong-nghe"],"image":"💻","examples":[{"type":"basic","zh":"这两个软件不兼容。","pinyin":"Zhè liǎng gè ruǎnjiàn bù jiānróng.","vi":"Hai phần mềm này không tương thích."},{"type":"simple","zh":"新款充电器可以兼容大部分手机。","pinyin":"Xīnkuǎn chōngdiànqì kěyǐ jiānróng dàbùfen shǒujī.","vi":"Bộ sạc mẫu mới tương thích với phần lớn điện thoại."},{"type":"compound","zh":"如果系统不兼容旧文件，就得先把格式转换一下。","pinyin":"Rúguǒ xìtǒng bù jiānróng jiù wénjiàn, jiù děi xiān bǎ géshì zhuǎnhuàn yíxià.","vi":"Nếu hệ thống không tương thích với tệp cũ thì phải chuyển đổi định dạng trước."}],"related":[{"hanzi":"兼容性","pinyin":"jiānróngxìng","vi":"tính tương thích"},{"hanzi":"包容","pinyin":"bāoróng","vi":"bao dung"},{"hanzi":"兼容并包","pinyin":"jiānróngbìngbāo","vi":"dung nạp tất cả"},{"hanzi":"软件","pinyin":"ruǎnjiàn","vi":"phần mềm"}]},{"id":"监狱","hanzi":"监狱","pinyin":"jiānyù","meaning_vi":"nhà tù","explanation":"监 (giám – trông coi) + 狱 (ngục – ngục tù) → nhà tù, nhà giam. Ví dụ: 关进监狱, 越狱 (vượt ngục).","hsk_level":6,"tags":["danh-tu","phap-luat"],"image":"⛓️","examples":[{"type":"basic","zh":"他被关进了监狱。","pinyin":"Tā bèi guān jìnle jiānyù.","vi":"Hắn bị tống vào tù."},{"type":"simple","zh":"这名小偷在监狱里待了整整五年。","pinyin":"Zhè míng xiǎotōu zài jiānyù lǐ dāile zhěngzhěng wǔ nián.","vi":"Tên trộm này đã ngồi tù tròn năm năm."},{"type":"compound","zh":"他一走出监狱，就下定决心要重新做人。","pinyin":"Tā yì zǒuchū jiānyù, jiù xiàdìng juéxīn yào chóngxīn zuòrén.","vi":"Anh ấy vừa ra tù đã hạ quyết tâm làm lại cuộc đời."}],"related":[{"hanzi":"牢房","pinyin":"láofáng","vi":"phòng giam"},{"hanzi":"犯人","pinyin":"fànrén","vi":"phạm nhân"},{"hanzi":"坐牢","pinyin":"zuòláo","vi":"ngồi tù"},{"hanzi":"看守所","pinyin":"kānshǒusuǒ","vi":"trại tạm giam"}],"traditional":"監獄"},{"id":"将军","hanzi":"将军","pinyin":"jiāngjūn","meaning_vi":"tướng quân","explanation":"将 (tướng – tướng) + 军 (quân – quân đội) → tướng quân, cấp tướng; động từ 将军 còn là chiếu tướng trong cờ tướng, nghĩa bóng: làm khó người khác.","hsk_level":6,"tags":["danh-tu","con-nguoi"],"image":"🎖️","examples":[{"type":"basic","zh":"将军骑着白马。","pinyin":"Jiāngjūn qízhe bái mǎ.","vi":"Vị tướng quân cưỡi ngựa trắng."},{"type":"simple","zh":"这位老将军年轻时打过许多胜仗。","pinyin":"Zhè wèi lǎo jiāngjūn niánqīng shí dǎguo xǔduō shèngzhàng.","vi":"Vị lão tướng này thời trẻ đã đánh thắng nhiều trận."},{"type":"compound","zh":"将军一声令下，士兵们就立刻冲了出去。","pinyin":"Jiāngjūn yìshēng lìng xià, shìbīngmen jiù lìkè chōngle chūqù.","vi":"Tướng quân vừa ra lệnh, binh lính liền lập tức xông lên."}],"related":[{"hanzi":"士兵","pinyin":"shìbīng","vi":"binh lính"},{"hanzi":"军官","pinyin":"jūnguān","vi":"sĩ quan"},{"hanzi":"元帅","pinyin":"yuánshuài","vi":"nguyên soái"},{"hanzi":"军队","pinyin":"jūnduì","vi":"quân đội"}],"traditional":"將軍"},{"id":"江郎才尽","hanzi":"江郎才尽","pinyin":"jiāngláng-cáijìn","meaning_vi":"cạn kiệt tài năng sáng tạo","explanation":"Điển tích Giang Yêm. Thành ngữ.","hsk_level":6,"tags":["thanh-ngu"],"image":"✍️","examples":[{"type":"basic","zh":"他已江郎才尽。","pinyin":"Tā yǐ Jiānglángcáijìn.","vi":"Ông ấy đã cạn kiệt tài năng."},{"type":"simple","zh":"有人批评这位作家的新书显得江郎才尽。","pinyin":"Yǒurén pīpíng zhè wèi zuòjiā de xīn shū xiǎnde Jiānglángcáijìn.","vi":"Có người phê bình cuốn sách mới của nhà văn này cho thấy ông đã cạn tài."},{"type":"compound","zh":"他担心自己江郎才尽，所以每天都逼着自己读书写作。","pinyin":"Tā dānxīn zìjǐ Jiānglángcáijìn, suǒyǐ měitiān dōu bīzhe zìjǐ dúshū xiězuò.","vi":"Anh ấy sợ mình cạn kiệt tài năng nên ngày nào cũng ép bản thân đọc sách và viết."}],"related":[{"hanzi":"黔驴技穷","pinyin":"Qiánlǘjìqióng","vi":"hết đường xoay xở"},{"hanzi":"才华","pinyin":"cáihuá","vi":"tài hoa"},{"hanzi":"灵感","pinyin":"línggǎn","vi":"cảm hứng"},{"hanzi":"才思敏捷","pinyin":"cáisīmǐnjié","vi":"tài tư nhanh nhạy"}],"traditional":"江郎才盡"},{"id":"将信将疑","hanzi":"将信将疑","pinyin":"jiāngxìn-jiāngyí","meaning_vi":"nửa tin nửa ngờ","explanation":"将信将疑: vừa (将…将) tin (信) vừa ngờ (疑) → nửa tin nửa ngờ. Ví dụ: 他将信将疑地看着我.","hsk_level":6,"tags":["thanh-ngu"],"image":"🤔","examples":[{"type":"basic","zh":"他将信将疑地点头。","pinyin":"Tā jiāngxìnjiāngyí dediǎn tóu.","vi":"Anh ấy gật đầu nửa tin nửa ngờ."},{"type":"simple","zh":"听了推销员的介绍，奶奶还是将信将疑。","pinyin":"Tīngle tuīxiāoyuán de jièshào, nǎinai háishì jiāngxìnjiāngyí.","vi":"Nghe nhân viên bán hàng giới thiệu, bà vẫn bán tín bán nghi."},{"type":"compound","zh":"虽然他说得很肯定，但是大家对这个消息仍然将信将疑。","pinyin":"Suīrán tā shuō de hěn kěndìng, dànshì dàjiā duì zhè ge xiāoxi réngrán jiāngxìnjiāngyí.","vi":"Tuy anh ấy nói rất chắc chắn nhưng mọi người vẫn nửa tin nửa ngờ về tin này."}],"related":[{"hanzi":"半信半疑","pinyin":"bànxìnbànyí","vi":"nửa tin nửa ngờ"},{"hanzi":"怀疑","pinyin":"huáiyí","vi":"nghi ngờ"},{"hanzi":"深信不疑","pinyin":"shēnxìnbùyí","vi":"tin chắc không nghi"},{"hanzi":"犹豫","pinyin":"yóuyù","vi":"do dự"}],"traditional":"將信將疑"},{"id":"交代","hanzi":"交代","pinyin":"jiāodài","meaning_vi":"bàn giao; dặn dò; khai báo, giải thích","explanation":"交 (giao – giao) + 代 (đại – thay) → bàn giao công việc; dặn dò; giải thích, khai báo rõ. Ví dụ: 交代任务, 交代问题.","hsk_level":6,"tags":["dong-tu"],"image":"📋","examples":[{"type":"basic","zh":"妈妈交代了几件事。","pinyin":"Māma jiāodàile jǐ jiàn shì.","vi":"Mẹ dặn dò vài việc."},{"type":"simple","zh":"离职前，他把手头的工作都交代给了同事。","pinyin":"Lízhí qián, tā bǎ shǒutóu de gōngzuò dōu jiāodài gěile tóngshì.","vi":"Trước khi nghỉ việc, anh ấy bàn giao hết công việc đang làm cho đồng nghiệp."},{"type":"compound","zh":"如果你不老实交代，就只会受到更重的惩罚。","pinyin":"Rúguǒ nǐ bù lǎoshi jiāodài, jiù zhǐ huì shòudào gèng zhòng de chéngfá.","vi":"Nếu anh không thành thật khai báo thì sẽ chỉ bị phạt nặng hơn."}],"related":[{"hanzi":"交待","pinyin":"jiāodài","vi":"bàn giao, giải thích"},{"hanzi":"嘱咐","pinyin":"zhǔfù","vi":"dặn dò"},{"hanzi":"坦白","pinyin":"tǎnbái","vi":"thành thật khai báo"},{"hanzi":"移交","pinyin":"yíjiāo","vi":"chuyển giao"}]},{"id":"交头接耳","hanzi":"交头接耳","pinyin":"jiāotóu-jiē'ěr","meaning_vi":"ghé đầu ghé tai thì thầm","explanation":"交头接耳: ghé đầu (头) sát (交) nhau, kề (接) tai (耳) → thì thầm to nhỏ với nhau. Ví dụ: 上课时不要交头接耳.","hsk_level":6,"tags":["thanh-ngu","giao-tiep"],"image":"🤫","examples":[{"type":"basic","zh":"考试时禁止交头接耳。","pinyin":"Kǎoshì shí jìnzhǐ jiāotóujiē'ěr.","vi":"Trong giờ thi cấm thì thầm to nhỏ."},{"type":"simple","zh":"会议上，几个员工在后排交头接耳。","pinyin":"Huìyì shàng, jǐ gè yuángōng zài hòupái jiāotóujiē'ěr.","vi":"Trong cuộc họp, mấy nhân viên ở hàng sau ghé tai thì thầm."},{"type":"compound","zh":"新老师一走进教室，学生们就开始交头接耳地议论起来。","pinyin":"Xīn lǎoshī yì zǒujìn jiàoshì, xuéshengmen jiù kāishǐ jiāotóujiē'ěr de yìlùn qǐlái.","vi":"Cô giáo mới vừa bước vào lớp, học sinh đã bắt đầu ghé tai bàn tán."}],"related":[{"hanzi":"窃窃私语","pinyin":"qièqièsīyǔ","vi":"thì thầm to nhỏ"},{"hanzi":"耳语","pinyin":"ěryǔ","vi":"nói thầm"},{"hanzi":"议论","pinyin":"yìlùn","vi":"bàn tán"},{"hanzi":"低声","pinyin":"dīshēng","vi":"nói nhỏ"}],"traditional":"交頭接耳"},{"id":"皆","hanzi":"皆","pinyin":"jiē","meaning_vi":"đều, tất cả","explanation":"皆 (giai): đều, tất cả (văn viết, tương đương 都). Thường gặp: 人人皆知, 皆大欢喜, 四海皆兄弟.","hsk_level":6,"tags":["pho-tu"],"image":"🌐","examples":[{"type":"basic","zh":"此事人人皆知。","pinyin":"Cǐshì rénrén jiē zhī.","vi":"Chuyện này ai ai cũng biết."},{"type":"simple","zh":"这家店的菜价皆在二十元以下。","pinyin":"Zhè jiā diàn de cài jià jiē zài èrshí yuán yǐxià.","vi":"Giá món ăn ở quán này đều dưới hai mươi tệ."},{"type":"compound","zh":"四海之内皆兄弟，所以大家应该互相帮助。","pinyin":"Sìhǎi zhīnèi jiē xiōngdì, suǒyǐ dàjiā yīnggāi hùxiāng bāngzhù.","vi":"Bốn biển đều là anh em, nên mọi người nên giúp đỡ lẫn nhau."}],"related":[{"hanzi":"都","pinyin":"dōu","vi":"đều"},{"hanzi":"全","pinyin":"quán","vi":"toàn bộ"},{"hanzi":"人人皆知","pinyin":"rénrénjiēzhī","vi":"ai cũng biết"},{"hanzi":"皆大欢喜","pinyin":"jiēdàhuānxǐ","vi":"mọi người đều vui"}]},{"id":"接二连三","hanzi":"接二连三","pinyin":"jiē'èr-liánsān","meaning_vi":"liên tiếp hết lần này đến lần khác","explanation":"接二连三: một tiếp (接) hai, liền (连) ba → liên tiếp, hết cái này đến cái khác. Ví dụ: 接二连三地发生事故.","hsk_level":6,"tags":["thanh-ngu"],"image":"🔁","examples":[{"type":"basic","zh":"坏消息接二连三。","pinyin":"Huài xiāoxi jiē'èrliánsān.","vi":"Tin xấu dồn dập kéo đến."},{"type":"simple","zh":"这个路口最近接二连三地发生车祸。","pinyin":"Zhè ge lùkǒu zuìjìn jiē'èrliánsān de fāshēng chēhuò.","vi":"Ngã tư này gần đây liên tiếp xảy ra tai nạn."},{"type":"compound","zh":"他刚坐下，电话就接二连三地响了起来。","pinyin":"Tā gāng zuòxià, diànhuà jiù jiē'èrliánsān de xiǎngle qǐlái.","vi":"Anh ấy vừa ngồi xuống, điện thoại đã liên tục reo vang."}],"related":[{"hanzi":"接连不断","pinyin":"jiēliánbúduàn","vi":"liên tục không ngừng"},{"hanzi":"连续","pinyin":"liánxù","vi":"liên tục"},{"hanzi":"络绎不绝","pinyin":"luòyìbùjué","vi":"nối đuôi không dứt"},{"hanzi":"一而再再而三","pinyin":"yì ér zài zài ér sān","vi":"hết lần này đến lần khác"}],"traditional":"接二連三"},{"id":"解剖","hanzi":"解剖","pinyin":"jiěpōu","meaning_vi":"giải phẫu","explanation":"解 (giải – mổ, tách) + 剖 (phẫu – mổ) → giải phẫu, mổ xẻ; nghĩa bóng: phân tích sâu. Ví dụ: 解剖学, 解剖自己.","hsk_level":6,"tags":["dong-tu"],"image":"🩺","examples":[{"type":"basic","zh":"学生在解剖青蛙。","pinyin":"Xuésheng zài jiěpōu qīngwā.","vi":"Học sinh đang giải phẫu ếch."},{"type":"simple","zh":"法医对死者进行了详细的解剖。","pinyin":"Fǎyī duì sǐzhě jìnxíngle xiángxì de jiěpōu.","vi":"Pháp y đã tiến hành giải phẫu tử thi chi tiết."},{"type":"compound","zh":"作家不但要观察别人，而且要敢于解剖自己。","pinyin":"Zuòjiā búdàn yào guānchá biérén, érqiě yào gǎnyú jiěpōu zìjǐ.","vi":"Nhà văn không chỉ phải quan sát người khác mà còn phải dám mổ xẻ chính mình."}],"related":[{"hanzi":"解剖学","pinyin":"jiěpōuxué","vi":"giải phẫu học"},{"hanzi":"手术","pinyin":"shǒushù","vi":"phẫu thuật"},{"hanzi":"尸体","pinyin":"shītǐ","vi":"thi thể"},{"hanzi":"分析","pinyin":"fēnxī","vi":"phân tích"}]},{"id":"假冒","hanzi":"假冒","pinyin":"jiǎmào","meaning_vi":"giả mạo, hàng giả","explanation":"假 (giả) + 冒 (mạo danh).","hsk_level":6,"tags":["dong-tu","mua-sam"],"image":"🚫","examples":[{"type":"basic","zh":"这是假冒产品。","pinyin":"Zhè shì jiǎmào chǎnpǐn.","vi":"Đây là sản phẩm giả mạo."},{"type":"simple","zh":"有人假冒银行职员打电话骗钱。","pinyin":"Yǒurén jiǎmào yínháng zhíyuán dǎdiànhuà piàn qián.","vi":"Có kẻ giả danh nhân viên ngân hàng gọi điện lừa tiền."},{"type":"compound","zh":"如果买到假冒的名牌包，就应该马上向平台投诉。","pinyin":"Rúguǒ mǎi dào jiǎmào de míngpái bāo, jiù yīnggāi mǎshàng xiàng píngtái tóusù.","vi":"Nếu mua phải túi hàng hiệu giả thì nên khiếu nại với sàn ngay."}],"related":[{"hanzi":"冒充","pinyin":"màochōng","vi":"mạo danh"},{"hanzi":"假冒伪劣","pinyin":"jiǎmàowěiliè","vi":"hàng giả kém chất lượng"},{"hanzi":"正品","pinyin":"zhèngpǐn","vi":"hàng chính hãng"},{"hanzi":"伪造","pinyin":"wěizào","vi":"làm giả"}]},{"id":"假使","hanzi":"假使","pinyin":"jiǎshǐ","meaning_vi":"giả sử, nếu như","explanation":"假 + 使 (khiến). Đồng nghĩa với 假如.","hsk_level":6,"tags":["lien-tu"],"image":"❓","examples":[{"type":"basic","zh":"假使下雨，就改天。","pinyin":"Jiǎshǐ xiàyǔ, jiù gǎitiān.","vi":"Giả sử trời mưa thì đổi sang hôm khác."},{"type":"simple","zh":"假使你是我，你会怎么做？","pinyin":"Jiǎshǐ nǐ shì wǒ, nǐ huì zěnme zuò?","vi":"Giả sử bạn là tôi, bạn sẽ làm thế nào?"},{"type":"compound","zh":"假使当初听了父亲的话，我现在就不会这么后悔了。","pinyin":"Jiǎshǐ dāngchū tīngle fùqīn dehuà, wǒ xiànzài jiù bú huì zhème hòuhuǐ le.","vi":"Giả sử ngày ấy nghe lời bố, giờ tôi đã không hối hận thế này."}],"related":[{"hanzi":"假如","pinyin":"jiǎrú","vi":"giả như"},{"hanzi":"如果","pinyin":"rúguǒ","vi":"nếu"},{"hanzi":"倘若","pinyin":"tǎngruò","vi":"nếu như"},{"hanzi":"要是","pinyin":"yàoshi","vi":"nếu"}]},{"id":"检讨","hanzi":"检讨","pinyin":"jiǎntǎo","meaning_vi":"kiểm điểm","explanation":"检 (kiểm – kiểm tra) + 讨 (thảo – xem xét) → tự kiểm điểm, nhận lỗi; xem xét tổng kết. Ví dụ: 写检讨, 做检讨.","hsk_level":6,"tags":["dong-tu"],"image":"📝","examples":[{"type":"basic","zh":"他写了一份检讨。","pinyin":"Tā xiěle yí fèn jiǎntǎo.","vi":"Cậu ấy đã viết một bản kiểm điểm."},{"type":"simple","zh":"经理在会上检讨了自己的管理失误。","pinyin":"Jīnglǐ zài huì shàng jiǎntǎole zìjǐ de guǎnlǐ shīwù.","vi":"Giám đốc đã kiểm điểm sai sót quản lý của mình trong cuộc họp."},{"type":"compound","zh":"项目失败以后，团队不但没有推卸责任，而且认真进行了检讨。","pinyin":"Xiàngmù shībài yǐhòu, tuánduì búdàn méiyǒu tuīxiè zérèn, érqiě rènzhēn jìnxíngle jiǎntǎo.","vi":"Sau khi dự án thất bại, nhóm không những không đùn đẩy trách nhiệm mà còn nghiêm túc kiểm điểm."}],"related":[{"hanzi":"反省","pinyin":"fǎnxǐng","vi":"tự xem xét"},{"hanzi":"检讨书","pinyin":"jiǎntǎoshū","vi":"bản kiểm điểm"},{"hanzi":"自我批评","pinyin":"zìwǒpīpíng","vi":"tự phê bình"},{"hanzi":"认错","pinyin":"rèncuò","vi":"nhận lỗi"}],"traditional":"檢討"},{"id":"简要","hanzi":"简要","pinyin":"jiǎnyào","meaning_vi":"ngắn gọn","explanation":"简 (giản – gọn) + 要 (yếu – trọng yếu) → ngắn gọn mà nêu được ý chính. Ví dụ: 简要介绍, 简要说明.","hsk_level":6,"tags":["tinh-tu"],"image":"📄","examples":[{"type":"basic","zh":"请简要说明一下。","pinyin":"Qǐng jiǎnyào shuōmíng yíxià.","vi":"Xin hãy trình bày ngắn gọn."},{"type":"simple","zh":"报告的开头简要介绍了研究背景。","pinyin":"Bàogào de kāitóu jiǎnyào jièshàole yánjiū bèijǐng.","vi":"Phần mở đầu báo cáo giới thiệu vắn tắt bối cảnh nghiên cứu."},{"type":"compound","zh":"因为时间有限，所以我只能简要地回答几个问题。","pinyin":"Yīnwèi shíjiān yǒuxiàn, suǒyǐ wǒ zhǐnéng jiǎnyào de huídá jǐ gè wèntí.","vi":"Vì thời gian có hạn nên tôi chỉ có thể trả lời ngắn gọn vài câu hỏi."}],"related":[{"hanzi":"简明","pinyin":"jiǎnmíng","vi":"ngắn gọn rõ ràng"},{"hanzi":"简短","pinyin":"jiǎnduǎn","vi":"ngắn gọn"},{"hanzi":"概要","pinyin":"gàiyào","vi":"tóm tắt"},{"hanzi":"详细","pinyin":"xiángxì","vi":"chi tiết"}],"traditional":"簡要"},{"id":"奖赏","hanzi":"奖赏","pinyin":"jiǎngshǎng","meaning_vi":"ban thưởng","explanation":"奖 (tưởng – khen thưởng) + 赏 (thưởng – thưởng) → ban thưởng, khen thưởng (thường người trên thưởng người dưới). Ví dụ: 奖赏有功人员.","hsk_level":6,"tags":["dong-tu"],"image":"🎁","examples":[{"type":"basic","zh":"国王奖赏了勇士。","pinyin":"Guówáng jiǎngshǎngle yǒngshì.","vi":"Nhà vua ban thưởng cho dũng sĩ."},{"type":"simple","zh":"主人拿出一块骨头奖赏听话的小狗。","pinyin":"Zhǔrén náchū yíkuài gǔtou jiǎngshǎng tīnghuà de xiǎogǒu.","vi":"Chủ nhân lấy ra một khúc xương để thưởng cho chú chó ngoan."},{"type":"compound","zh":"只要你这次考进前十名，爸爸就给你一个奖赏。","pinyin":"Zhǐyào nǐ zhè cì kǎojìn qián shí míng, bàba jiù gěi nǐ yí gè jiǎngshǎng.","vi":"Chỉ cần lần này con thi vào top mười, bố sẽ có phần thưởng cho con."}],"related":[{"hanzi":"奖励","pinyin":"jiǎnglì","vi":"khen thưởng"},{"hanzi":"赏罚分明","pinyin":"shǎngfáfēnmíng","vi":"thưởng phạt phân minh"},{"hanzi":"惩罚","pinyin":"chéngfá","vi":"trừng phạt"},{"hanzi":"奖品","pinyin":"jiǎngpǐn","vi":"phần thưởng"}],"traditional":"獎賞"},{"id":"绞尽脑汁","hanzi":"绞尽脑汁","pinyin":"jiǎojìn-nǎozhī","meaning_vi":"vắt óc suy nghĩ","explanation":"绞尽脑汁: vắt (绞) cạn (尽) óc (脑汁) → vắt óc suy nghĩ, cố nghĩ hết cách. Ví dụ: 绞尽脑汁想办法.","hsk_level":6,"tags":["thanh-ngu","nhan-thuc"],"image":"🤯","examples":[{"type":"basic","zh":"他绞尽脑汁想办法。","pinyin":"Tā jiǎojìnnǎozhī xiǎngbànfǎ.","vi":"Anh ấy vắt óc nghĩ cách."},{"type":"simple","zh":"为了给女儿起名字，夫妻俩绞尽脑汁。","pinyin":"Wèile gěi nǚ'ér qǐ míngzi, fūqī liǎ jiǎojìnnǎozhī.","vi":"Để đặt tên cho con gái, hai vợ chồng đã vắt óc suy nghĩ."},{"type":"compound","zh":"虽然我绞尽脑汁，但是还是解不出这道数学题。","pinyin":"Suīrán wǒ jiǎojìnnǎozhī, dànshì háishì jiě bu chū zhè dào shùxué tí.","vi":"Tuy đã vắt óc suy nghĩ nhưng tôi vẫn không giải được bài toán này."}],"related":[{"hanzi":"冥思苦想","pinyin":"míngsīkǔxiǎng","vi":"nghĩ nát óc"},{"hanzi":"费尽心思","pinyin":"fèijìnxīnsi","vi":"tốn hết tâm tư"},{"hanzi":"深思熟虑","pinyin":"shēnsīshúlǜ","vi":"suy nghĩ kỹ càng"},{"hanzi":"脑汁","pinyin":"nǎozhī","vi":"chất xám"}],"traditional":"絞盡腦汁"},{"id":"脚踏实地","hanzi":"脚踏实地","pinyin":"jiǎotà-shídì","meaning_vi":"chân đạp đất thực tế, làm việc chắc chắn thiết thực","explanation":"脚踏实地: chân (脚) đạp (踏) trên đất thật (实地) → làm việc thiết thực, chắc chắn, không viển vông.","hsk_level":6,"tags":["thanh-ngu"],"image":"👣","examples":[{"type":"basic","zh":"做人要脚踏实地。","pinyin":"Zuòrén yào jiǎotàshídì.","vi":"Làm người phải thực tế, vững vàng."},{"type":"simple","zh":"他脚踏实地地从基层员工做到了经理。","pinyin":"Tā jiǎotàshídì de cóng jīcéng yuángōng zuòdàole jīnglǐ.","vi":"Anh ấy từng bước vững chắc đi lên từ nhân viên cơ sở đến giám đốc."},{"type":"compound","zh":"梦想虽然要远大，但是行动必须脚踏实地。","pinyin":"Mèngxiǎng suīrán yào yuǎndà, dànshì xíngdòng bìxū jiǎotàshídì.","vi":"Ước mơ tuy cần lớn lao, nhưng hành động phải thực tế vững chắc."}],"related":[{"hanzi":"实事求是","pinyin":"shíshìqiúshì","vi":"thực sự cầu thị"},{"hanzi":"踏实","pinyin":"tāshi","vi":"chắc chắn, vững vàng"},{"hanzi":"好高骛远","pinyin":"hàogāowùyuǎn","vi":"mơ mộng viển vông"},{"hanzi":"务实","pinyin":"wùshí","vi":"thực tế"}],"traditional":"腳踏實地"},{"id":"酒精","hanzi":"酒精","pinyin":"jiǔjīng","meaning_vi":"cồn (ethanol)","explanation":"酒 (tửu – rượu) + 精 (tinh – tinh chất) → cồn, ethanol (chất có trong rượu). Ví dụ: 酒精消毒, 酒精中毒, 无酒精饮料.","hsk_level":6,"tags":["danh-tu","suc-khoe"],"image":"🧪","examples":[{"type":"basic","zh":"用酒精给伤口消毒。","pinyin":"Yòng jiǔjīng gěi shāngkǒu xiāodú.","vi":"Dùng cồn sát trùng vết thương."},{"type":"simple","zh":"这种饮料的酒精含量只有百分之三。","pinyin":"Zhè zhǒng yǐnliào de jiǔjīng hánliàng zhǐyǒu bǎifēnzhī sān.","vi":"Nồng độ cồn của loại đồ uống này chỉ có ba phần trăm."},{"type":"compound","zh":"他对酒精过敏，所以聚会上只喝果汁。","pinyin":"Tā duì jiǔjīng guòmǐn, suǒyǐ jùhuì shàng zhǐ hē guǒzhī.","vi":"Anh ấy dị ứng với cồn nên ở các bữa tiệc chỉ uống nước trái cây."}],"related":[{"hanzi":"酒","pinyin":"jiǔ","vi":"rượu"},{"hanzi":"消毒","pinyin":"xiāodú","vi":"khử trùng"},{"hanzi":"酒精中毒","pinyin":"jiǔjīngzhòngdú","vi":"ngộ độc rượu"},{"hanzi":"乙醇","pinyin":"yǐchún","vi":"ethanol"}]},{"id":"九牛一毛","hanzi":"九牛一毛","pinyin":"jiǔniú-yìmáo","meaning_vi":"chín trâu mất một sợi lông (nhỏ bé không đáng kể)","explanation":"九牛一毛: một sợi lông trên chín con trâu (Tư Mã Thiên, Báo Nhậm An thư) → phần cực nhỏ, không đáng kể so với tổng thể.","hsk_level":6,"tags":["thanh-ngu"],"image":"🐂","examples":[{"type":"basic","zh":"我知道的只是九牛一毛。","pinyin":"Wǒ zhīdào de zhǐshì jiǔniúyìmáo.","vi":"Những gì tôi biết chỉ là hạt cát trong sa mạc."},{"type":"simple","zh":"几十万元对这位富豪来说不过是九牛一毛。","pinyin":"Jǐ shíwàn yuán duì zhè wèi fùháo lái shuō búguò shì jiǔniúyìmáo.","vi":"Vài trăm nghìn tệ đối với vị đại gia này chẳng qua chỉ như chín trâu mất một sợi lông."},{"type":"compound","zh":"我们捐的钱虽然只是九牛一毛，但是代表了大家的心意。","pinyin":"Wǒmen juān de qián suīrán zhǐshì jiǔniúyìmáo, dànshì dàibiǎole dàjiā de xīnyì.","vi":"Số tiền chúng tôi quyên góp tuy chỉ như muối bỏ biển nhưng thể hiện tấm lòng của mọi người."}],"related":[{"hanzi":"微不足道","pinyin":"wēibùzúdào","vi":"nhỏ nhặt không đáng kể"},{"hanzi":"沧海一粟","pinyin":"cānghǎiyísù","vi":"hạt thóc giữa biển"},{"hanzi":"微乎其微","pinyin":"wēihūqíwēi","vi":"cực kỳ nhỏ"},{"hanzi":"举足轻重","pinyin":"jǔzúqīngzhòng","vi":"có vai trò quan trọng"}]},{"id":"决策","hanzi":"决策","pinyin":"juécè","meaning_vi":"quyết sách","explanation":"决 (quyết – quyết định) + 策 (sách – kế sách) → đưa ra quyết sách; danh từ: quyết sách, chính sách. Ví dụ: 决策者, 正确的决策.","hsk_level":6,"tags":["dong-tu"],"image":"♟️","examples":[{"type":"basic","zh":"这是正确的决策。","pinyin":"Zhè shì zhèngquè de juécè.","vi":"Đây là một quyết sách đúng đắn."},{"type":"simple","zh":"董事会将在下周决策是否收购这家公司。","pinyin":"Dǒngshìhuì jiāng zài xiàzhōu juécè shìfǒu shōugòu zhè jiā gōngsī.","vi":"Hội đồng quản trị sẽ quyết định vào tuần sau có mua lại công ty này hay không."},{"type":"compound","zh":"如果决策失误，公司就可能损失数百万元。","pinyin":"Rúguǒ juécè shīwù, gōngsī jiù kěnéng sǔnshī shùbǎiwàn yuán.","vi":"Nếu quyết sách sai lầm, công ty có thể tổn thất hàng triệu tệ."}],"related":[{"hanzi":"决定","pinyin":"juédìng","vi":"quyết định"},{"hanzi":"策略","pinyin":"cèlüè","vi":"sách lược"},{"hanzi":"决策者","pinyin":"juécèzhě","vi":"người ra quyết định"},{"hanzi":"政策","pinyin":"zhèngcè","vi":"chính sách"}],"traditional":"決策"},{"id":"绝无仅有","hanzi":"绝无仅有","pinyin":"juéwú-jǐnyǒu","meaning_vi":"có một không hai, vô cùng hiếm","explanation":"绝无仅有: tuyệt đối (绝) không (无) có, chỉ (仅) có một → có một không hai, cực kỳ hiếm.","hsk_level":6,"tags":["thanh-ngu"],"image":"💎","examples":[{"type":"basic","zh":"这种情况绝无仅有。","pinyin":"Zhè zhǒng qíngkuàng juéwújǐnyǒu.","vi":"Tình huống này cực kỳ hiếm có."},{"type":"simple","zh":"这块陨石是世界上绝无仅有的珍贵标本。","pinyin":"Zhè kuài yǔnshí shì shìjiè shàng juéwújǐnyǒu de zhēnguì biāoběn.","vi":"Khối thiên thạch này là mẫu vật quý có một không hai trên thế giới."},{"type":"compound","zh":"一个人既获得诺贝尔物理奖又获得化学奖，在历史上几乎绝无仅有。","pinyin":"Yígèrén jì huòdé Nuòbèi'ěr wùlǐ jiǎng yòu huòdé huàxué jiǎng, zài lìshǐshàng jīhū juéwújǐnyǒu.","vi":"Một người vừa đoạt giải Nobel Vật lý vừa đoạt giải Nobel Hóa học thì trong lịch sử gần như có một không hai."}],"related":[{"hanzi":"独一无二","pinyin":"dúyìwú'èr","vi":"độc nhất vô nhị"},{"hanzi":"举世无双","pinyin":"jǔshìwúshuāng","vi":"có một không hai"},{"hanzi":"罕见","pinyin":"hǎnjiàn","vi":"hiếm thấy"},{"hanzi":"屡见不鲜","pinyin":"lǚjiànbùxiān","vi":"thường thấy"}],"traditional":"絕無僅有"},{"id":"觉醒","hanzi":"觉醒","pinyin":"juéxǐng","meaning_vi":"thức tỉnh","explanation":"觉 (giác – tỉnh ngộ) + 醒 (tỉnh – tỉnh dậy) → thức tỉnh, giác ngộ (ý thức, tư tưởng). Ví dụ: 民族觉醒, 觉醒过来.","hsk_level":6,"tags":["dong-tu"],"image":"⏰","examples":[{"type":"basic","zh":"人民觉醒了。","pinyin":"Rénmín juéxǐng le.","vi":"Nhân dân đã thức tỉnh."},{"type":"simple","zh":"这本书让很多女性的独立意识开始觉醒。","pinyin":"Zhè běn shū ràng hěn duō nǚxìng de dúlì yìshí kāishǐ juéxǐng.","vi":"Cuốn sách này khiến ý thức độc lập của nhiều phụ nữ bắt đầu thức tỉnh."},{"type":"compound","zh":"直到父亲病倒，他才真正觉醒，开始承担家庭的责任。","pinyin":"Zhídào fùqīn bìngdǎo, tā cái zhēnzhèng juéxǐng, kāishǐ chéngdān jiātíng de zérèn.","vi":"Mãi đến khi bố ngã bệnh, anh ấy mới thực sự thức tỉnh và bắt đầu gánh vác trách nhiệm gia đình."}],"related":[{"hanzi":"觉悟","pinyin":"juéwù","vi":"giác ngộ"},{"hanzi":"醒悟","pinyin":"xǐngwù","vi":"tỉnh ngộ"},{"hanzi":"唤醒","pinyin":"huànxǐng","vi":"đánh thức"},{"hanzi":"麻木","pinyin":"mámù","vi":"tê liệt, vô cảm"}],"traditional":"覺醒"},{"id":"决一雌雄","hanzi":"决一雌雄","pinyin":"juéyì-cíxióng","meaning_vi":"phân tài cao thấp","explanation":"决一雌雄: quyết (决) phân con mái (雌) con trống (雄) → quyết đấu một trận để phân thắng bại, phân tài cao thấp.","hsk_level":6,"tags":["thanh-ngu","the-thao"],"image":"⚔️","examples":[{"type":"basic","zh":"我们来决一雌雄吧！","pinyin":"Wǒmen lái juéyìcíxióng ba!","vi":"Chúng ta phân cao thấp đi!"},{"type":"simple","zh":"明晚的决赛上，中韩两位棋手将决一雌雄。","pinyin":"Míngwǎn de juésài shàng, Zhōnghán liǎng wèi qíshǒu jiāng juéyìcíxióng.","vi":"Trong trận chung kết tối mai, hai kỳ thủ Trung Quốc và Hàn Quốc sẽ phân thắng bại."},{"type":"compound","zh":"如果这场雨不停，两队就只能改天再决一雌雄了。","pinyin":"Rúguǒ zhè chǎng yǔ bùtíng, liǎng duì jiù zhǐnéng gǎitiān zài juéyìcíxióng le.","vi":"Nếu cơn mưa này không tạnh, hai đội chỉ có thể hẹn hôm khác phân cao thấp."}],"related":[{"hanzi":"一决高下","pinyin":"yìjuégāoxià","vi":"phân cao thấp"},{"hanzi":"较量","pinyin":"jiàoliàng","vi":"đọ sức"},{"hanzi":"决战","pinyin":"juézhàn","vi":"quyết chiến"},{"hanzi":"争夺","pinyin":"zhēngduó","vi":"tranh giành"}],"traditional":"決一雌雄"},{"id":"卷土重来","hanzi":"卷土重来","pinyin":"juǎntǔ-chónglái","meaning_vi":"quay trở lại mạnh mẽ sau thất bại","explanation":"卷土重来: cuốn (卷) bụi đất (土) quay lại (重来) (thơ Đỗ Mục về Hạng Vũ) → thất bại rồi tập hợp lực lượng quay trở lại.","hsk_level":6,"tags":["thanh-ngu"],"image":"🌪️","examples":[{"type":"basic","zh":"敌人卷土重来了。","pinyin":"Dírén juǎntǔchónglái le.","vi":"Quân địch đã quay lại phục thù."},{"type":"simple","zh":"去年落选的他今年卷土重来参加比赛。","pinyin":"Qùnián luòxuǎn de tā jīnnián juǎntǔchónglái cānjiā bǐsài.","vi":"Năm ngoái bị loại, năm nay anh ấy trở lại mạnh mẽ để dự thi."},{"type":"compound","zh":"如果不彻底清除病毒，它就可能卷土重来。","pinyin":"Rúguǒ bú chèdǐ qīngchú bìngdú, tā jiù kěnéng juǎntǔchónglái.","vi":"Nếu không diệt sạch virus, nó có thể quay trở lại."}],"related":[{"hanzi":"东山再起","pinyin":"dōngshānzàiqǐ","vi":"trở lại sau thất bại"},{"hanzi":"重整旗鼓","pinyin":"chóngzhěngqígǔ","vi":"chấn chỉnh lại lực lượng"},{"hanzi":"一蹶不振","pinyin":"yìjuébúzhèn","vi":"gục ngã không dậy nổi"},{"hanzi":"失败","pinyin":"shībài","vi":"thất bại"}],"traditional":"捲土重來"},{"id":"继承","hanzi":"继承","pinyin":"jìchéng","meaning_vi":"kế thừa, thừa kế","explanation":"继 (nối tiếp) + 承 (nhận lấy).","hsk_level":6,"tags":["dong-tu"],"image":"🏛️","examples":[{"type":"basic","zh":"她继承了母亲的美貌。","pinyin":"Tā jìchéngle mǔqīn de měimào.","vi":"Cô ấy thừa hưởng nhan sắc của mẹ."},{"type":"simple","zh":"我们应该继承前辈们勤俭节约的传统。","pinyin":"Wǒmen yīnggāi jìchéng qiánbèimen qínjiǎnjiéyuē de chuántǒng.","vi":"Chúng ta nên kế thừa truyền thống cần kiệm của các bậc đi trước."},{"type":"compound","zh":"他虽然继承了一大笔遗产，却在三年内全部花光了。","pinyin":"Tā suīrán jìchéngle yí dàbǐ yíchǎn, què zài sān niánnèi quánbù huāguāng le.","vi":"Anh ta tuy thừa kế một khoản di sản lớn nhưng trong ba năm đã tiêu sạch."}],"related":[{"hanzi":"继承人","pinyin":"jìchéngrén","vi":"người thừa kế"},{"hanzi":"遗产","pinyin":"yíchǎn","vi":"di sản"},{"hanzi":"传承","pinyin":"chuánchéng","vi":"truyền thừa"},{"hanzi":"发扬","pinyin":"fāyáng","vi":"phát huy"}],"traditional":"繼承"},{"id":"季度","hanzi":"季度","pinyin":"jìdù","meaning_vi":"quý (3 tháng trong năm)","explanation":"季 (mùa/quý) + 度.","hsk_level":6,"tags":["danh-tu","thoi-gian","cong-viec"],"image":"📅","examples":[{"type":"basic","zh":"第三季度结束了。","pinyin":"Dì sān jìdù jiéshù le.","vi":"Quý ba đã kết thúc."},{"type":"simple","zh":"公司本季度的销售额比上季度增长了两成。","pinyin":"Gōngsī běn jìdù de xiāoshòu'é bǐ shàng jìdù zēngzhǎngle liǎng chéng.","vi":"Doanh số quý này của công ty tăng hai mươi phần trăm so với quý trước."},{"type":"compound","zh":"只要下个季度完成目标，全体员工就能拿到奖金。","pinyin":"Zhǐyào xiàgè jìdù wánchéng mùbiāo, quántǐ yuángōng jiù néng nádào jiǎngjīn.","vi":"Chỉ cần quý sau hoàn thành mục tiêu, toàn bộ nhân viên sẽ được nhận thưởng."}],"related":[{"hanzi":"季节","pinyin":"jìjié","vi":"mùa"},{"hanzi":"年度","pinyin":"niándù","vi":"năm (tài chính)"},{"hanzi":"月度","pinyin":"yuèdù","vi":"hằng tháng"},{"hanzi":"第一季度","pinyin":"dìyījìdù","vi":"quý một"}]},{"id":"继往开来","hanzi":"继往开来","pinyin":"jìwǎng-kāilái","meaning_vi":"kế thừa quá khứ mở ra tương lai","explanation":"继往开来: 继 (kế – nối) 往 (vãng – cái đã qua), 开 (khai – mở) 来 (lai – tương lai) → kế thừa sự nghiệp người đi trước, mở đường cho đời sau.","hsk_level":6,"tags":["thanh-ngu"],"image":"🌅","examples":[{"type":"basic","zh":"我们要继往开来。","pinyin":"Wǒmen yào jìwǎngkāilái.","vi":"Chúng ta phải kế thừa quá khứ, mở lối tương lai."},{"type":"simple","zh":"这次大会是一次继往开来的重要会议。","pinyin":"Zhè cì dàhuì shì yí cì jìwǎngkāilái de zhòngyào huìyì.","vi":"Đại hội lần này là một hội nghị quan trọng mang tính kế thừa và mở đường."},{"type":"compound","zh":"年轻一代既要尊重传统，又要继往开来、勇于创新。","pinyin":"Niánqīng yídài jì yào zūnzhòng chuántǒng, yòu yào jìwǎngkāilái, yǒngyú chuàngxīn.","vi":"Thế hệ trẻ vừa phải tôn trọng truyền thống, vừa phải kế thừa mở lối, dũng cảm sáng tạo."}],"related":[{"hanzi":"承前启后","pinyin":"chéngqiánqǐhòu","vi":"kế thừa và mở lối"},{"hanzi":"继承","pinyin":"jìchéng","vi":"kế thừa"},{"hanzi":"开拓","pinyin":"kāituò","vi":"khai phá"},{"hanzi":"与时俱进","pinyin":"yǔshíjùjìn","vi":"theo kịp thời đại"}],"traditional":"繼往開來"},{"id":"记忆犹新","hanzi":"记忆犹新","pinyin":"jìyì-yóuxīn","meaning_vi":"ký ức vẫn còn mới nguyên như vừa xảy ra","explanation":"记忆犹新: ký ức (记忆) vẫn (犹) còn mới (新) → nhớ rõ như vừa mới xảy ra. Ví dụ: 那件事我至今记忆犹新.","hsk_level":6,"tags":["thanh-ngu","nhan-thuc"],"image":"🧠","examples":[{"type":"basic","zh":"那一幕我记忆犹新。","pinyin":"Nà yí mù wǒ jìyìyóuxīn.","vi":"Cảnh tượng đó tôi vẫn nhớ như in."},{"type":"simple","zh":"二十年前那场大地震至今让人记忆犹新。","pinyin":"Èrshí niánqián nà chǎng dà dìzhèn zhìjīn ràng rén jìyìyóuxīn.","vi":"Trận động đất lớn hai mươi năm trước đến nay vẫn khiến người ta nhớ như in."},{"type":"compound","zh":"虽然过去了很多年，但是第一次登台的紧张我仍记忆犹新。","pinyin":"Suīrán guòqùle hěn duōnián, dànshì dìyīcì dēng tái de jǐnzhāng wǒ réng jìyìyóuxīn.","vi":"Tuy đã nhiều năm trôi qua, nhưng cảm giác hồi hộp lần đầu lên sân khấu tôi vẫn nhớ như in."}],"related":[{"hanzi":"历历在目","pinyin":"lìlìzàimù","vi":"rõ mồn một trước mắt"},{"hanzi":"刻骨铭心","pinyin":"kègǔmíngxīn","vi":"khắc cốt ghi tâm"},{"hanzi":"记忆","pinyin":"jìyì","vi":"ký ức"},{"hanzi":"淡忘","pinyin":"dànwàng","vi":"phai nhạt trong ký ức"}],"traditional":"記憶猶新"},{"id":"记载","hanzi":"记载","pinyin":"jìzǎi","meaning_vi":"ghi chép lại","explanation":"记 (ký – ghi) + 载 (tải – chở, ghi) → ghi chép lại (trong sách sử, văn bản). Ví dụ: 史书记载, 据记载.","hsk_level":6,"tags":["dong-tu"],"image":"📜","examples":[{"type":"basic","zh":"史书上有记载。","pinyin":"Shǐshū shàng yǒu jìzǎi.","vi":"Sử sách có ghi chép."},{"type":"simple","zh":"这本日记详细记载了他在非洲的经历。","pinyin":"Zhè běn rìjì xiángxì jìzǎile tā zài Fēizhōu de jīnglì.","vi":"Cuốn nhật ký này ghi chép chi tiết những trải nghiệm của ông ở châu Phi."},{"type":"compound","zh":"如果史料记载属实，那么这座古墓就有两千多年的历史了。","pinyin":"Rúguǒ shǐliào jìzǎi shǔshí, nàme zhè zuò gǔmù jiù yǒu liǎng qiān duōnián de lìshǐ le.","vi":"Nếu sử liệu ghi chép là đúng thì ngôi mộ cổ này đã có hơn hai nghìn năm lịch sử."}],"related":[{"hanzi":"记录","pinyin":"jìlù","vi":"ghi chép"},{"hanzi":"史书","pinyin":"shǐshū","vi":"sách sử"},{"hanzi":"记述","pinyin":"jìshù","vi":"thuật lại"},{"hanzi":"文献","pinyin":"wénxiàn","vi":"văn hiến, tài liệu"}],"traditional":"記載"},{"id":"进化","hanzi":"进化","pinyin":"jìnhuà","meaning_vi":"tiến hóa","explanation":"进 (tiến – tiến lên) + 化 (hóa – biến đổi) → tiến hóa, phát triển từ thấp lên cao. Ví dụ: 进化论, 生物进化.","hsk_level":6,"tags":["dong-tu"],"image":"🧬","examples":[{"type":"basic","zh":"人类是从猿进化来的。","pinyin":"Rénlèi shì cóng yuán jìnhuà lái de.","vi":"Loài người tiến hóa từ loài vượn."},{"type":"simple","zh":"长颈鹿的脖子在漫长的进化中越变越长。","pinyin":"Chángjǐnglù de bózi zài màncháng de jìnhuà zhōng yuè biàn yuè cháng.","vi":"Cổ hươu cao cổ ngày càng dài ra trong quá trình tiến hóa lâu dài."},{"type":"compound","zh":"生物如果不能适应环境，就会在进化中被淘汰。","pinyin":"Shēngwù rúguǒ bù néng shìyìng huánjìng, jiù huì zài jìnhuà zhōng bèi táotài.","vi":"Sinh vật nếu không thích nghi được với môi trường sẽ bị đào thải trong quá trình tiến hóa."}],"related":[{"hanzi":"进化论","pinyin":"jìnhuàlùn","vi":"thuyết tiến hóa"},{"hanzi":"演变","pinyin":"yǎnbiàn","vi":"diễn biến"},{"hanzi":"退化","pinyin":"tuìhuà","vi":"thoái hóa"},{"hanzi":"发展","pinyin":"fāzhǎn","vi":"phát triển"}],"traditional":"進化"},{"id":"晋升","hanzi":"晋升","pinyin":"jìnshēng","meaning_vi":"thăng chức","explanation":"晋 (tấn – tiến lên) + 升 (thăng – lên) → thăng chức, lên cấp bậc cao hơn. Ví dụ: 晋升为经理, 晋升机会.","hsk_level":6,"tags":["dong-tu"],"image":"👔","examples":[{"type":"basic","zh":"他晋升为经理了。","pinyin":"Tā jìnshēng wéi jīnglǐ le.","vi":"Anh ấy được thăng chức lên giám đốc."},{"type":"simple","zh":"她凭着出色的业绩获得了晋升的机会。","pinyin":"Tā píngzhe chūsè de yèjì huòdéle jìnshēng de jīhuì.","vi":"Cô ấy nhờ thành tích xuất sắc mà có được cơ hội thăng chức."},{"type":"compound","zh":"只要你连续两年考核优秀，就有资格申请晋升。","pinyin":"Zhǐyào nǐ liánxù liǎng nián kǎohé yōuxiù, jiù yǒuzīgé shēnqǐng jìnshēng.","vi":"Chỉ cần bạn đạt đánh giá xuất sắc hai năm liền là đủ điều kiện xin thăng chức."}],"related":[{"hanzi":"升职","pinyin":"shēngzhí","vi":"thăng chức"},{"hanzi":"提拔","pinyin":"tíbá","vi":"đề bạt"},{"hanzi":"降职","pinyin":"jiàngzhí","vi":"giáng chức"},{"hanzi":"升迁","pinyin":"shēngqiān","vi":"thăng tiến"}],"traditional":"晉升"},{"id":"尽心尽力","hanzi":"尽心尽力","pinyin":"jìnxīn-jìnlì","meaning_vi":"tận tâm tận lực","explanation":"尽心尽力: dốc hết (尽) lòng (心), hết (尽) sức (力) → tận tâm tận lực. Ví dụ: 尽心尽力地工作.","hsk_level":6,"tags":["thanh-ngu"],"image":"❤️","examples":[{"type":"basic","zh":"她尽心尽力照顾病人。","pinyin":"Tā jìnxīnjìnlì zhàogù bìngrén.","vi":"Cô ấy tận tâm tận lực chăm sóc bệnh nhân."},{"type":"simple","zh":"这位班主任对每个学生都尽心尽力。","pinyin":"Zhè wèi bānzhǔrèn duì měi gè xuésheng dōu jìnxīnjìnlì.","vi":"Cô chủ nhiệm này tận tâm tận lực với từng học sinh."},{"type":"compound","zh":"虽然他尽心尽力地帮忙，但是事情最后还是没办成。","pinyin":"Suīrán tā jìnxīnjìnlì de bāngmáng, dànshì shìqing zuìhòu háishì méi bàn chéng.","vi":"Tuy anh ấy đã tận tâm giúp đỡ nhưng cuối cùng việc vẫn không thành."}],"related":[{"hanzi":"全心全意","pinyin":"quánxīnquányì","vi":"toàn tâm toàn ý"},{"hanzi":"竭尽全力","pinyin":"jiéjìnquánlì","vi":"dốc hết toàn lực"},{"hanzi":"敷衍了事","pinyin":"fūyǎnliǎoshì","vi":"làm qua loa"},{"hanzi":"尽力","pinyin":"jìnlì","vi":"cố hết sức"}],"traditional":"盡心盡力"},{"id":"近朱者赤近墨者黑","hanzi":"近朱者赤近墨者黑","pinyin":"jìn zhū zhě chì jìn Mòzhě hēi","meaning_vi":"gần mực thì đen gần đèn thì sáng","explanation":"近朱者赤近墨者黑: gần son (朱) thì đỏ, gần mực (墨) thì đen → môi trường, bạn bè ảnh hưởng lớn đến con người; như \"gần mực thì đen, gần đèn thì sáng\".","hsk_level":6,"tags":["thanh-ngu"],"image":"🖤","examples":[{"type":"basic","zh":"正所谓近朱者赤近墨者黑。","pinyin":"Zhèng suǒwèi jìn zhū zhě chì jìn Mòzhě hēi.","vi":"Đúng là gần mực thì đen, gần đèn thì sáng."},{"type":"simple","zh":"父母常用近朱者赤近墨者黑来提醒孩子慎重交友。","pinyin":"Fùmǔ chángyòng jìn zhū zhě chì jìn Mòzhě hēi lái tíxǐng háizi shènzhòng jiāoyǒu.","vi":"Cha mẹ thường dùng câu gần mực thì đen, gần đèn thì sáng để nhắc con cẩn thận khi chọn bạn."},{"type":"compound","zh":"近朱者赤近墨者黑，所以你一定要多和勤奋的同学交往。","pinyin":"Jìn zhū zhě chì jìn Mòzhě hēi, suǒyǐ nǐ yídìngyào duō hé qínfèn de tóngxué jiāowǎng.","vi":"Gần mực thì đen, gần đèn thì sáng, nên con nhất định phải giao du nhiều với những bạn chăm chỉ."}],"related":[{"hanzi":"物以类聚","pinyin":"wùyǐlèijù","vi":"ngưu tầm ngưu mã tầm mã"},{"hanzi":"环境","pinyin":"huánjìng","vi":"môi trường"},{"hanzi":"影响","pinyin":"yǐngxiǎng","vi":"ảnh hưởng"},{"hanzi":"耳濡目染","pinyin":"ěrrúmùrǎn","vi":"mưa dầm thấm lâu"}]},{"id":"镜头","hanzi":"镜头","pinyin":"jìngtóu","meaning_vi":"ống kính; cảnh quay, khung hình","explanation":"镜 (kính – gương, kính) + 头 (đầu) → ống kính máy ảnh, máy quay; cũng là cảnh quay, cảnh phim. Ví dụ: 摄像镜头, 特写镜头.","hsk_level":6,"tags":["danh-tu","cong-nghe"],"image":"📷","examples":[{"type":"basic","zh":"请大家看镜头。","pinyin":"Qǐng dàjiā kàn jìngtóu.","vi":"Mời mọi người nhìn vào ống kính."},{"type":"simple","zh":"这部手机的镜头可以拍出很清晰的夜景。","pinyin":"Zhè bù shǒujī de jìngtóu kěyǐ pāichū hěn qīngxī de yèjǐng.","vi":"Ống kính của chiếc điện thoại này có thể chụp cảnh đêm rất rõ nét."},{"type":"compound","zh":"她一面对镜头就紧张，所以很少接受采访。","pinyin":"Tā yí miànduì jìngtóu jiù jǐnzhāng, suǒyǐ hěn shǎo jiēshòu cǎifǎng.","vi":"Cô ấy hễ đứng trước ống kính là căng thẳng nên ít khi nhận lời phỏng vấn."}],"related":[{"hanzi":"相机","pinyin":"xiàngjī","vi":"máy ảnh"},{"hanzi":"拍摄","pinyin":"pāishè","vi":"quay chụp"},{"hanzi":"摄像头","pinyin":"shèxiàngtóu","vi":"camera"},{"hanzi":"特写","pinyin":"tèxiě","vi":"cận cảnh"}],"traditional":"鏡頭"},{"id":"敬爱","hanzi":"敬爱","pinyin":"jìng'ài","meaning_vi":"kính yêu","explanation":"敬 (kính – kính trọng) + 爱 (ái – yêu) → kính yêu. Thường dùng với người trên: 敬爱的老师, 敬爱的父母.","hsk_level":6,"tags":["dong-tu"],"image":"❤️","examples":[{"type":"basic","zh":"我们敬爱的老师。","pinyin":"Wǒmen jìng'ài de lǎoshī.","vi":"Người thầy kính yêu của chúng ta."},{"type":"simple","zh":"这位老村长深受村民们的敬爱。","pinyin":"Zhè wèi lǎo cūnzhǎng shēnshòu cūnmínmen de jìng'ài.","vi":"Vị trưởng thôn già này được dân làng hết mực kính yêu."},{"type":"compound","zh":"因为爷爷一生正直善良，所以全家人都十分敬爱他。","pinyin":"Yīnwèi yéye yìshēng zhèngzhí shànliáng, suǒyǐ quán jiārén dōu shífēn jìng'ài tā.","vi":"Vì ông nội cả đời chính trực lương thiện nên cả nhà đều rất kính yêu ông."}],"related":[{"hanzi":"尊敬","pinyin":"zūnjìng","vi":"tôn kính"},{"hanzi":"爱戴","pinyin":"àidài","vi":"kính yêu"},{"hanzi":"敬重","pinyin":"jìngzhòng","vi":"kính trọng"},{"hanzi":"亲爱","pinyin":"qīn'ài","vi":"thân yêu"}],"traditional":"敬愛"},{"id":"敬而远之","hanzi":"敬而远之","pinyin":"jìng'ér-yuǎnzhī","meaning_vi":"kính nhi viễn chi (tôn trọng nhưng giữ khoảng cách)","explanation":"敬而远之: kính trọng (敬) nhưng xa (远) nó (之) (Luận Ngữ, về quỷ thần) → tôn trọng bề ngoài nhưng giữ khoảng cách, không muốn gần.","hsk_level":6,"tags":["thanh-ngu"],"image":"🙇","examples":[{"type":"basic","zh":"对这种人最好敬而远之。","pinyin":"Duì zhè zhǒng rén zuìhǎo jìng'éryuǎnzhī.","vi":"Với loại người này tốt nhất nên giữ khoảng cách."},{"type":"simple","zh":"很多学生对这门难懂的课程敬而远之。","pinyin":"Hěn duō xuésheng duì zhè mén nándǒng de kèchéng jìng'éryuǎnzhī.","vi":"Nhiều sinh viên e dè tránh xa môn học khó hiểu này."},{"type":"compound","zh":"新经理虽然能力强，但是脾气太大，下属都对他敬而远之。","pinyin":"Xīn jīnglǐ suīrán nénglì qiáng, dànshì píqi tài dà, xiàshǔ dōu duì tā jìng'éryuǎnzhī.","vi":"Giám đốc mới tuy giỏi nhưng nóng tính, cấp dưới đều kính nể mà tránh xa."}],"related":[{"hanzi":"避而远之","pinyin":"bì'éryuǎnzhī","vi":"tránh xa"},{"hanzi":"疏远","pinyin":"shūyuǎn","vi":"xa lánh"},{"hanzi":"亲近","pinyin":"qīnjìn","vi":"gần gũi"},{"hanzi":"尊敬","pinyin":"zūnjìng","vi":"tôn kính"}],"traditional":"敬而遠之"},{"id":"疾病","hanzi":"疾病","pinyin":"jíbìng","meaning_vi":"bệnh tật","explanation":"疾 (bệnh) + 病 (ốm).","hsk_level":6,"tags":["danh-tu","suc-khoe"],"image":"🤒","examples":[{"type":"basic","zh":"他患有心脏疾病。","pinyin":"Tā huànyǒu xīnzàng jíbìng.","vi":"Ông ấy mắc bệnh tim."},{"type":"simple","zh":"蚊子会传播很多种危险的疾病。","pinyin":"Wénzi huì chuánbō hěn duōzhǒng wēixiǎn de jíbìng.","vi":"Muỗi có thể lây truyền nhiều loại bệnh nguy hiểm."},{"type":"compound","zh":"如果长期熬夜，就容易引发各种疾病。","pinyin":"Rúguǒ chángqī áoyè, jiù róngyì yǐnfā gèzhǒng jíbìng.","vi":"Nếu thức khuya lâu dài thì dễ sinh ra đủ loại bệnh tật."}],"related":[{"hanzi":"病","pinyin":"bìng","vi":"bệnh"},{"hanzi":"健康","pinyin":"jiànkāng","vi":"sức khỏe"},{"hanzi":"传染病","pinyin":"chuánrǎnbìng","vi":"bệnh truyền nhiễm"},{"hanzi":"疾病预防","pinyin":"jíbìngyùfáng","vi":"phòng bệnh"}]},{"id":"极端","hanzi":"极端","pinyin":"jíduān","meaning_vi":"cực đoan, vô cùng","explanation":"极 (tột cùng) + 端 (đầu mút).","hsk_level":6,"tags":["tinh-tu","pho-tu"],"image":"⚠️","examples":[{"type":"basic","zh":"他的想法太极端了。","pinyin":"Tā de xiǎngfǎ tài jíduān le.","vi":"Suy nghĩ của anh ta quá cực đoan."},{"type":"simple","zh":"今年夏天多地出现了极端高温天气。","pinyin":"Jīnnián xiàtiān duō dì chūxiànle jíduān gāowēn tiānqì.","vi":"Mùa hè năm nay nhiều nơi xuất hiện thời tiết nắng nóng cực đoan."},{"type":"compound","zh":"他做事一着急就容易走极端，所以大家常常劝他冷静。","pinyin":"Tā zuòshì yì zháojí jiù róngyì zǒu jíduān, suǒyǐ dàjiā chángcháng quàn tā lěngjìng.","vi":"Anh ấy hễ sốt ruột là dễ hành động cực đoan nên mọi người thường khuyên anh bình tĩnh."}],"related":[{"hanzi":"极其","pinyin":"jíqí","vi":"cực kỳ"},{"hanzi":"极端主义","pinyin":"jíduānzhǔyì","vi":"chủ nghĩa cực đoan"},{"hanzi":"偏激","pinyin":"piānjī","vi":"quá khích"},{"hanzi":"适度","pinyin":"shìdù","vi":"vừa phải"}],"traditional":"極端"},{"id":"即将","hanzi":"即将","pinyin":"jíjiāng","meaning_vi":"sắp, sắp sửa","explanation":"即 + 将 (sắp tới).","hsk_level":6,"tags":["pho-tu","thoi-gian"],"image":"⏳","examples":[{"type":"basic","zh":"列车即将进站。","pinyin":"Lièchē jíjiāng jìnzhàn.","vi":"Đoàn tàu sắp vào ga."},{"type":"simple","zh":"我们的女儿即将从医学院毕业。","pinyin":"Wǒmen de nǚ'ér jíjiāng cóng yīxuéyuàn bìyè.","vi":"Con gái chúng tôi sắp tốt nghiệp trường y."},{"type":"compound","zh":"比赛即将开始，但是主力队员还没有赶到球场。","pinyin":"Bǐsài jíjiāng kāishǐ, dànshì zhǔlì duìyuán hái méiyǒu gǎndào qiúchǎng.","vi":"Trận đấu sắp bắt đầu, nhưng cầu thủ chủ lực vẫn chưa đến sân."}],"related":[{"hanzi":"将要","pinyin":"jiāngyào","vi":"sắp"},{"hanzi":"马上","pinyin":"mǎshàng","vi":"ngay lập tức"},{"hanzi":"快要","pinyin":"kuàiyào","vi":"sắp sửa"},{"hanzi":"即将到来","pinyin":"jíjiāngdàolái","vi":"sắp tới"}],"traditional":"即將"},{"id":"汲取","hanzi":"汲取","pinyin":"jíqǔ","meaning_vi":"tiếp thu, rút ra (kinh nghiệm/tri thức)","explanation":"汲 (múc nước) + 取 (lấy).","hsk_level":6,"tags":["dong-tu","hoc-tap"],"image":"🧠","examples":[{"type":"basic","zh":"要汲取教训。","pinyin":"Yào jíqǔ jiàoxùn.","vi":"Phải rút ra bài học."},{"type":"simple","zh":"小说家从民间故事中汲取了大量创作灵感。","pinyin":"Xiǎoshuōjiā cóng mínjiān gùshi zhōng jíqǔle dàliàng chuàngzuò línggǎn.","vi":"Nhà tiểu thuyết đã lấy rất nhiều cảm hứng sáng tác từ truyện dân gian."},{"type":"compound","zh":"只要从失败中汲取经验，下次就一定能做得更好。","pinyin":"Zhǐyào cóng shībài zhōng jíqǔ jīngyàn, xiàcì jiù yídìng néng zuò de gèng hǎo.","vi":"Chỉ cần rút kinh nghiệm từ thất bại, lần sau nhất định sẽ làm tốt hơn."}],"related":[{"hanzi":"吸取","pinyin":"xīqǔ","vi":"hấp thu, rút ra"},{"hanzi":"吸收","pinyin":"xīshōu","vi":"hấp thụ"},{"hanzi":"借鉴","pinyin":"jièjiàn","vi":"tham khảo"},{"hanzi":"汲取教训","pinyin":"jíqǔjiàoxùn","vi":"rút ra bài học"}]},{"id":"棘手","hanzi":"棘手","pinyin":"jíshǒu","meaning_vi":"hóc búa, khó giải quyết (như gai đâm tay)","explanation":"棘 (gai góc) + 手 (tay).","hsk_level":6,"tags":["tinh-tu"],"image":"🌵","examples":[{"type":"basic","zh":"这件事很棘手。","pinyin":"Zhè jiàn shì hěn jíshǒu.","vi":"Việc này rất hóc búa."},{"type":"simple","zh":"新来的律师接手了一个非常棘手的案子。","pinyin":"Xīn lái de lǜshī jiēshǒule yí gè fēicháng jíshǒu de ànzi.","vi":"Luật sư mới đến đã nhận một vụ án vô cùng hóc búa."},{"type":"compound","zh":"问题虽然棘手，但是只要大家一起想办法，就一定能解决。","pinyin":"Wèntí suīrán jíshǒu, dànshì zhǐyào dàjiā yìqǐ xiǎngbànfǎ, jiù yídìng néng jiějué.","vi":"Vấn đề tuy hóc búa, nhưng chỉ cần mọi người cùng nghĩ cách thì nhất định sẽ giải quyết được."}],"related":[{"hanzi":"难办","pinyin":"nánbàn","vi":"khó làm"},{"hanzi":"麻烦","pinyin":"máfan","vi":"phiền phức"},{"hanzi":"头疼","pinyin":"tóuténg","vi":"đau đầu"},{"hanzi":"难题","pinyin":"nántí","vi":"vấn đề nan giải"}]},{"id":"集思广益","hanzi":"集思广益","pinyin":"jísī-guǎngyì","meaning_vi":"tập hợp trí tuệ tập thể","explanation":"集思 (gom suy nghĩ) + 广益 (mở rộng lợi ích). Thành ngữ.","hsk_level":6,"tags":["thanh-ngu"],"image":"🤝","examples":[{"type":"basic","zh":"我们需要集思广益。","pinyin":"Wǒmen xūyào jísīguǎngyì.","vi":"Chúng ta cần tập hợp ý kiến của mọi người."},{"type":"simple","zh":"公司召开座谈会，集思广益地制定新方案。","pinyin":"Gōngsī zhàokāi zuòtánhuì, jísīguǎngyì de zhìdìng xīn fāng'àn.","vi":"Công ty tổ chức tọa đàm, thu thập ý kiến rộng rãi để xây dựng phương án mới."},{"type":"compound","zh":"一个人的想法毕竟有限，所以最好集思广益。","pinyin":"Yígèrén de xiǎngfǎ bìjìng yǒuxiàn, suǒyǐ zuìhǎo jísīguǎngyì.","vi":"Suy nghĩ của một người dù sao cũng có hạn, nên tốt nhất là tập hợp trí tuệ tập thể."}],"related":[{"hanzi":"群策群力","pinyin":"qúncèqúnlì","vi":"đồng tâm hiệp lực"},{"hanzi":"博采众长","pinyin":"bócǎizhòngcháng","vi":"học hỏi ưu điểm mọi người"},{"hanzi":"独断专行","pinyin":"dúduànzhuānxíng","vi":"độc đoán chuyên quyền"},{"hanzi":"讨论","pinyin":"tǎolùn","vi":"thảo luận"}],"traditional":"集思廣益"},{"id":"集腋成裘","hanzi":"集腋成裘","pinyin":"jíyè-chéngqiú","meaning_vi":"góp gió thành bão","explanation":"集腋成裘: gom (集) lông nách (腋) cáo, mỗi con một chút, thành áo cừu (裘) → góp nhiều cái nhỏ thành cái lớn, \"góp gió thành bão\".","hsk_level":6,"tags":["thanh-ngu"],"image":"🧥","examples":[{"type":"basic","zh":"这就叫集腋成裘。","pinyin":"Zhèjiù jiào jíyèchéngqiú.","vi":"Đây gọi là góp gió thành bão."},{"type":"simple","zh":"全校师生集腋成裘，为灾区捐了十万元。","pinyin":"Quán xiào shīshēng jíyèchéngqiú, wèi zāiqū juānle shíwàn yuán.","vi":"Thầy trò toàn trường góp gió thành bão, quyên được một trăm nghìn tệ cho vùng thiên tai."},{"type":"compound","zh":"每人虽然只出一点力，但是集腋成裘，就能帮助很多人。","pinyin":"Měirén suīrán zhǐ chū yìdiǎn lì, dànshì jíyèchéngqiú, jiù néng bāngzhù hěn duō rén.","vi":"Mỗi người tuy chỉ góp chút sức, nhưng góp gió thành bão thì sẽ giúp được rất nhiều người."}],"related":[{"hanzi":"积少成多","pinyin":"jīshǎochéngduō","vi":"tích tiểu thành đại"},{"hanzi":"聚沙成塔","pinyin":"jùshāchéngtǎ","vi":"góp cát thành tháp"},{"hanzi":"积土成山","pinyin":"jītǔchéngshān","vi":"tích đất thành núi"},{"hanzi":"积累","pinyin":"jīlěi","vi":"tích lũy"}]},{"id":"急于求成","hanzi":"急于求成","pinyin":"jíyú-qiúchéng","meaning_vi":"nóng lòng muốn thành công ngay","explanation":"急于 (vội vàng) + 求成 (cầu thành công). Thành ngữ.","hsk_level":6,"tags":["thanh-ngu"],"image":"🏃","examples":[{"type":"basic","zh":"学习不能急于求成。","pinyin":"Xuéxí bù néng jíyúqiúchéng.","vi":"Học tập không thể nóng vội."},{"type":"simple","zh":"急于求成的心态让他犯了不少低级错误。","pinyin":"Jíyúqiúchéng de xīntài ràng tā fànle bùshǎo dījí cuòwù.","vi":"Tâm lý nóng vội khiến anh ấy mắc không ít lỗi sơ đẳng."},{"type":"compound","zh":"如果急于求成，就很容易在减肥时伤害身体。","pinyin":"Rúguǒ jíyúqiúchéng, jiù hěn róngyì zài jiǎnféi shí shānghài shēntǐ.","vi":"Nếu nóng vội muốn có kết quả ngay thì rất dễ hại sức khỏe khi giảm cân."}],"related":[{"hanzi":"急功近利","pinyin":"jígōngjìnlì","vi":"nóng vội cầu lợi"},{"hanzi":"拔苗助长","pinyin":"bámiáozhùzhǎng","vi":"nóng vội hỏng việc"},{"hanzi":"欲速则不达","pinyin":"yù sù zé bù dá","vi":"dục tốc bất đạt"},{"hanzi":"循序渐进","pinyin":"xúnxùjiànjìn","vi":"tuần tự tiến lên"}],"traditional":"急於求成"},{"id":"急中生智","hanzi":"急中生智","pinyin":"jízhōng-shēngzhì","meaning_vi":"cái khó ló cái khôn, nguy cấp sinh trí khôn","explanation":"急中生智: trong lúc nguy cấp (急中) nảy ra (生) mưu trí (智) → bị dồn vào thế khó thì nghĩ ra cách hay, \"cái khó ló cái khôn\".","hsk_level":6,"tags":["thanh-ngu"],"image":"💡","examples":[{"type":"basic","zh":"他急中生智。","pinyin":"Tā jízhōngshēngzhì.","vi":"Anh ấy nảy ra kế hay trong lúc nguy cấp."},{"type":"simple","zh":"被困电梯的小女孩急中生智按下了报警按钮。","pinyin":"Bèi kùn diàntī de xiǎo nǚhái jízhōngshēngzhì ànxiàle bàojǐng ànniǔ.","vi":"Bé gái bị kẹt trong thang máy đã nhanh trí bấm nút báo động."},{"type":"compound","zh":"因为急中生智喊来了保安，所以她的钱包没被抢走。","pinyin":"Yīnwèi jízhōngshēngzhì hǎn láile bǎo'ān, suǒyǐ tā de qiánbāo méi bèi qiǎngzǒu.","vi":"Vì nhanh trí gọi bảo vệ đến nên ví của cô ấy không bị cướp mất."}],"related":[{"hanzi":"随机应变","pinyin":"suíjīyìngbiàn","vi":"tùy cơ ứng biến"},{"hanzi":"机智","pinyin":"jīzhì","vi":"nhanh trí"},{"hanzi":"灵机一动","pinyin":"língjīyídòng","vi":"chợt nảy ra ý hay"},{"hanzi":"惊慌失措","pinyin":"jīnghuāngshīcuò","vi":"hoảng loạn"}]},{"id":"及早","hanzi":"及早","pinyin":"jízǎo","meaning_vi":"càng sớm càng tốt","explanation":"及 (kịp) + 早 (sớm).","hsk_level":6,"tags":["pho-tu","thoi-gian"],"image":"⏰","examples":[{"type":"basic","zh":"有病要及早治疗。","pinyin":"Yǒubìng yào jízǎo zhìliáo.","vi":"Có bệnh phải chữa trị sớm."},{"type":"simple","zh":"请大家及早预订春节回家的车票。","pinyin":"Qǐng dàjiā jízǎo yùdìng Chūnjié huíjiā de chēpiào.","vi":"Mọi người hãy đặt vé về quê ăn Tết càng sớm càng tốt."},{"type":"compound","zh":"如果你及早发现了问题，损失就不会这么大。","pinyin":"Rúguǒ nǐ jízǎo fāxiànle wèntí, sǔnshī jiù bú huì zhème dà.","vi":"Nếu bạn phát hiện vấn đề sớm thì tổn thất đã không lớn như vậy."}],"related":[{"hanzi":"趁早","pinyin":"chènzǎo","vi":"tranh thủ sớm"},{"hanzi":"尽早","pinyin":"jǐnzǎo","vi":"càng sớm càng tốt"},{"hanzi":"提前","pinyin":"tíqián","vi":"trước thời hạn"},{"hanzi":"及时","pinyin":"jíshí","vi":"kịp thời"}]},{"id":"剧烈","hanzi":"剧烈","pinyin":"jùliè","meaning_vi":"dữ dội","explanation":"剧 (kịch – mạnh) + 烈 (liệt – dữ dội) → dữ dội, kịch liệt. Ví dụ: 剧烈运动, 剧烈的疼痛, 剧烈变化.","hsk_level":6,"tags":["tinh-tu"],"image":"💥","examples":[{"type":"basic","zh":"他剧烈地咳嗽。","pinyin":"Tā jùliè de késou.","vi":"Anh ấy ho dữ dội."},{"type":"simple","zh":"飞机遇到气流，发生了剧烈的颠簸。","pinyin":"Fēijī yùdào qìliú, fāshēngle jùliè de diānbǒ.","vi":"Máy bay gặp luồng khí, rung lắc dữ dội."},{"type":"compound","zh":"饭后不要做剧烈运动，否则容易肚子疼。","pinyin":"Fàn hòu bú yào zuò jùliè yùndòng, fǒuzé róngyì dùziténg.","vi":"Sau bữa ăn đừng vận động mạnh, nếu không dễ bị đau bụng."}],"related":[{"hanzi":"激烈","pinyin":"jīliè","vi":"kịch liệt"},{"hanzi":"强烈","pinyin":"qiángliè","vi":"mãnh liệt"},{"hanzi":"剧烈运动","pinyin":"jùlièyùndòng","vi":"vận động mạnh"},{"hanzi":"轻微","pinyin":"qīngwēi","vi":"nhẹ"}],"traditional":"劇烈"},{"id":"聚沙成塔","hanzi":"聚沙成塔","pinyin":"jùshā-chéngtǎ","meaning_vi":"góp cát thành tháp, tích tiểu thành đại","explanation":"聚沙成塔: gom (聚) cát (沙) thành (成) tháp (塔), từ kinh Pháp Hoa → tích lũy nhiều cái nhỏ thành cái lớn, tích tiểu thành đại.","hsk_level":6,"tags":["thanh-ngu"],"image":"🗼","examples":[{"type":"basic","zh":"储蓄就是聚沙成塔。","pinyin":"Chǔxù jiùshì jùshāchéngtǎ.","vi":"Tiết kiệm chính là góp cát thành tháp."},{"type":"simple","zh":"这座图书馆的藏书是靠市民捐赠聚沙成塔积累起来的。","pinyin":"Zhè zuò túshūguǎn de cángshū shì kào shìmín juānzèng jùshāchéngtǎ jīlěi qǐlái de.","vi":"Sách của thư viện này được tích lũy dần từ quyên góp của người dân, như góp cát thành tháp."},{"type":"compound","zh":"只要每个人都节约一滴水，聚沙成塔，就能缓解城市缺水问题。","pinyin":"Zhǐyào měigèrén dōu jiéyuē yì dīshuǐ, jùshāchéngtǎ, jiù néng huǎnjiě chéngshì quēshuǐ wèntí.","vi":"Chỉ cần mỗi người tiết kiệm một giọt nước, góp cát thành tháp, là có thể giảm bớt tình trạng thiếu nước của thành phố."}],"related":[{"hanzi":"积少成多","pinyin":"jīshǎochéngduō","vi":"tích tiểu thành đại"},{"hanzi":"集腋成裘","pinyin":"jíyèchéngqiú","vi":"góp gió thành bão"},{"hanzi":"滴水穿石","pinyin":"dīshuǐchuānshí","vi":"nước chảy đá mòn"},{"hanzi":"积累","pinyin":"jīlěi","vi":"tích lũy"}]},{"id":"局面","hanzi":"局面","pinyin":"júmiàn","meaning_vi":"cục diện","explanation":"局 (cục – ván cờ, cục) + 面 (diện – mặt) → cục diện, tình thế chung. Ví dụ: 打开局面, 局面混乱, 扭转局面.","hsk_level":6,"tags":["danh-tu"],"image":"♟️","examples":[{"type":"basic","zh":"局面开始好转了。","pinyin":"Júmiàn kāishǐ hǎozhuǎn le.","vi":"Cục diện bắt đầu chuyển biến tốt."},{"type":"simple","zh":"新教练上任后扭转了球队连败的局面。","pinyin":"Xīn jiàoliàn shàngrèn hòu niǔzhuǎnle qiúduì liánbài de júmiàn.","vi":"Huấn luyện viên mới nhậm chức đã xoay chuyển cục diện thua liên tiếp của đội."},{"type":"compound","zh":"如果再不采取措施，混乱的局面就会失去控制。","pinyin":"Rúguǒ zài bù cǎiqǔ cuòshī, hùnluàn de júmiàn jiù huì shīqù kòngzhì.","vi":"Nếu còn không có biện pháp, tình thế hỗn loạn sẽ vượt khỏi tầm kiểm soát."}],"related":[{"hanzi":"局势","pinyin":"júshì","vi":"tình thế"},{"hanzi":"形势","pinyin":"xíngshì","vi":"tình hình"},{"hanzi":"僵局","pinyin":"jiāngjú","vi":"thế bế tắc"},{"hanzi":"新局面","pinyin":"xīnjúmiàn","vi":"cục diện mới"}]},{"id":"机不可失","hanzi":"机不可失","pinyin":"jībù-kěshī","meaning_vi":"cơ hội không thể bỏ lỡ","explanation":"机不可失: cơ hội (机) không thể (不可) để mất (失); thường đi với 时不再来 → cơ hội đến thì phải nắm lấy ngay.","hsk_level":6,"tags":["thanh-ngu"],"image":"🌟","examples":[{"type":"basic","zh":"机不可失，快报名吧！","pinyin":"Jībùkěshī, kuài bàomíng ba!","vi":"Cơ hội không thể bỏ lỡ, mau đăng ký đi!"},{"type":"simple","zh":"这次打折力度这么大，真是机不可失。","pinyin":"Zhè cì dǎzhé lìdù zhème dà, zhēn shì jībùkěshī.","vi":"Lần giảm giá này mạnh như vậy, đúng là cơ hội không thể bỏ lỡ."},{"type":"compound","zh":"既然公司给了你出国进修的名额，那就机不可失，赶紧答应吧。","pinyin":"Jìrán gōngsī gěile nǐ chūguó jìnxiū de míng'é, nà jiù jībùkěshī, gǎnjǐn dāying ba.","vi":"Công ty đã cho bạn suất đi tu nghiệp nước ngoài thì đừng bỏ lỡ cơ hội, mau nhận lời đi."}],"related":[{"hanzi":"机不可失时不再来","pinyin":"jībùkěshī shí bú zài lái","vi":"cơ hội không quay lại"},{"hanzi":"机会","pinyin":"jīhuì","vi":"cơ hội"},{"hanzi":"抓住机会","pinyin":"zhuāzhùjīhuì","vi":"nắm lấy cơ hội"},{"hanzi":"错失良机","pinyin":"cuòshīliángjī","vi":"bỏ lỡ thời cơ"}],"traditional":"機不可失"},{"id":"稽查","hanzi":"稽查","pinyin":"jīchá","meaning_vi":"kiểm tra, thanh tra","explanation":"稽 + 查 (kiểm tra).","hsk_level":6,"tags":["dong-tu","phap-luat"],"image":"🔍","examples":[{"type":"basic","zh":"税务局来稽查了。","pinyin":"Shuìwùjú lái jīchá le.","vi":"Cục thuế đến thanh tra rồi."},{"type":"simple","zh":"交警正在路口稽查酒后驾车的司机。","pinyin":"Jiāojǐng zhèngzài lùkǒu jīchá jiǔhòu jiàchē de sījī.","vi":"Cảnh sát giao thông đang kiểm tra tài xế lái xe sau khi uống rượu ở giao lộ."},{"type":"compound","zh":"只要稽查人员一发现假账，公司就会被重罚。","pinyin":"Zhǐyào jīchá rényuán yì fāxiàn jiǎzhàng, gōngsī jiù huì bèi zhòngfá.","vi":"Chỉ cần thanh tra viên phát hiện sổ sách giả, công ty sẽ bị phạt nặng."}],"related":[{"hanzi":"检查","pinyin":"jiǎnchá","vi":"kiểm tra"},{"hanzi":"调查","pinyin":"diàochá","vi":"điều tra"},{"hanzi":"审查","pinyin":"shěnchá","vi":"thẩm tra"},{"hanzi":"监督","pinyin":"jiāndū","vi":"giám sát"}]},{"id":"激光","hanzi":"激光","pinyin":"jīguāng","meaning_vi":"tia la-de (laser)","explanation":"激 + 光 (ánh sáng).","hsk_level":6,"tags":["danh-tu","khoa-hoc","cong-nghe"],"image":"🔦","examples":[{"type":"basic","zh":"激光可以切割钢板。","pinyin":"Jīguāng kěyǐ qiēgē gāngbǎn.","vi":"Tia laser có thể cắt thép tấm."},{"type":"simple","zh":"医生用激光为她做了近视矫正手术。","pinyin":"Yīshēng yòng jīguāng wèi tā zuòle jìnshì jiǎozhèng shǒushù.","vi":"Bác sĩ dùng laser phẫu thuật điều chỉnh cận thị cho cô ấy."},{"type":"compound","zh":"激光虽然用途广泛，但是直射眼睛非常危险。","pinyin":"Jīguāng suīrán yòngtú guǎngfàn, dànshì zhíshè yǎnjing fēicháng wēixiǎn.","vi":"Laser tuy có nhiều ứng dụng nhưng chiếu thẳng vào mắt thì rất nguy hiểm."}],"related":[{"hanzi":"光线","pinyin":"guāngxiàn","vi":"tia sáng"},{"hanzi":"激光笔","pinyin":"jīguāngbǐ","vi":"bút laser"},{"hanzi":"红外线","pinyin":"hóngwàixiàn","vi":"tia hồng ngoại"},{"hanzi":"激光手术","pinyin":"jīguāngshǒushù","vi":"phẫu thuật laser"}]},{"id":"鸡毛蒜皮","hanzi":"鸡毛蒜皮","pinyin":"jīmáo-suànpí","meaning_vi":"chuyện vặt vãnh nhỏ nhặt (lông gà vỏ tỏi)","explanation":"鸡毛蒜皮: lông gà (鸡毛) vỏ tỏi (蒜皮) → chuyện vặt vãnh nhỏ nhặt, không đáng kể. Ví dụ: 为鸡毛蒜皮的小事吵架.","hsk_level":6,"tags":["thanh-ngu"],"image":"🧄","examples":[{"type":"basic","zh":"都是鸡毛蒜皮的事。","pinyin":"Dōu shì jīmáosuànpí de shì.","vi":"Toàn là chuyện vặt vãnh."},{"type":"simple","zh":"老两口常常为了鸡毛蒜皮的小事拌嘴。","pinyin":"Lǎoliǎngkǒu chángcháng wèile jīmáosuànpí de xiǎoshì bànzuǐ.","vi":"Hai ông bà thường cãi nhau vì những chuyện lặt vặt."},{"type":"compound","zh":"如果总为鸡毛蒜皮计较，就会错过生活中更重要的东西。","pinyin":"Rúguǒ zǒng wèi jīmáosuànpí jìjiào, jiù huì cuòguò shēnghuó zhōng gèng zhòngyào de dōngxi.","vi":"Nếu cứ so đo chuyện vặt vãnh thì sẽ bỏ lỡ những điều quan trọng hơn trong cuộc sống."}],"related":[{"hanzi":"微不足道","pinyin":"wēibùzúdào","vi":"không đáng kể"},{"hanzi":"琐事","pinyin":"suǒshì","vi":"chuyện vặt"},{"hanzi":"小事","pinyin":"xiǎoshì","vi":"việc nhỏ"},{"hanzi":"大事","pinyin":"dàshì","vi":"việc lớn"}],"traditional":"雞毛蒜皮"},{"id":"机密","hanzi":"机密","pinyin":"jīmì","meaning_vi":"cơ mật, bí mật tuyệt đối","explanation":"机 + 密 (kín đáo).","hsk_level":6,"tags":["tinh-tu","danh-tu"],"image":"🔐","examples":[{"type":"basic","zh":"这是公司机密。","pinyin":"Zhè shì gōngsī jīmì.","vi":"Đây là bí mật của công ty."},{"type":"simple","zh":"那名间谍偷走了一份军事机密文件。","pinyin":"Nà míng jiàndié tōu zǒule yí fèn jūnshì jīmì wénjiàn.","vi":"Tên gián điệp đã đánh cắp một tài liệu quân sự tuyệt mật."},{"type":"compound","zh":"因为项目内容高度机密，所以每个参与者都签了保密协议。","pinyin":"Yīnwèi xiàngmù nèiróng gāodù jīmì, suǒyǐ měi gè cānyùzhě dōu qiānle bǎomì xiéyì.","vi":"Vì nội dung dự án tối mật nên mọi người tham gia đều ký thỏa thuận bảo mật."}],"related":[{"hanzi":"秘密","pinyin":"mìmì","vi":"bí mật"},{"hanzi":"保密","pinyin":"bǎomì","vi":"giữ bí mật"},{"hanzi":"绝密","pinyin":"juémì","vi":"tuyệt mật"},{"hanzi":"泄密","pinyin":"xièmì","vi":"tiết lộ bí mật"}],"traditional":"機密"},{"id":"积少成多","hanzi":"积少成多","pinyin":"jīshǎo-chéngduō","meaning_vi":"tích tiểu thành đại","explanation":"积少成多: tích (积) cái ít (少) thành (成) cái nhiều (多) → tích tiểu thành đại, năng nhặt chặt bị.","hsk_level":6,"tags":["thanh-ngu"],"image":"💰","examples":[{"type":"basic","zh":"零钱也能积少成多。","pinyin":"Língqián yě néng jīshǎochéngduō.","vi":"Tiền lẻ cũng có thể tích tiểu thành đại."},{"type":"simple","zh":"知识的积累是一个积少成多的过程。","pinyin":"Zhīshi de jīlěi shì yí gè jīshǎochéngduō de guòchéng.","vi":"Tích lũy kiến thức là một quá trình tích tiểu thành đại."},{"type":"compound","zh":"每天虽然只存十块钱，但是积少成多，一年就有三千多了。","pinyin":"Měitiān suīrán zhǐ cún shí kuài qián, dànshì jīshǎochéngduō, yì nián jiù yǒu sān qiān duō le.","vi":"Mỗi ngày tuy chỉ để dành mười tệ, nhưng tích tiểu thành đại, một năm đã có hơn ba nghìn."}],"related":[{"hanzi":"积沙成塔","pinyin":"jīshāchéngtǎ","vi":"góp cát thành tháp"},{"hanzi":"聚沙成塔","pinyin":"jùshāchéngtǎ","vi":"góp cát thành tháp"},{"hanzi":"集腋成裘","pinyin":"jíyèchéngqiú","vi":"góp gió thành bão"},{"hanzi":"积累","pinyin":"jīlěi","vi":"tích lũy"}],"traditional":"積少成多"},{"id":"畸形","hanzi":"畸形","pinyin":"jīxíng","meaning_vi":"dị dạng, phát triển lệch lạc","explanation":"畸 + 形 (hình dáng).","hsk_level":6,"tags":["tinh-tu","suc-khoe"],"image":"⚠️","examples":[{"type":"basic","zh":"这只小羊是畸形的。","pinyin":"Zhè zhī xiǎoyáng shì jīxíng de.","vi":"Con cừu non này bị dị dạng."},{"type":"simple","zh":"长期穿高跟鞋可能导致脚趾畸形。","pinyin":"Chángqī chuān gāogēnxié kěnéng dǎozhì jiǎozhǐ jīxíng.","vi":"Đi giày cao gót lâu dài có thể gây biến dạng ngón chân."},{"type":"compound","zh":"如果只追求经济增长，就可能造成畸形的发展模式。","pinyin":"Rúguǒ zhǐ zhuīqiú jīngjì zēngzhǎng, jiù kěnéng zàochéng jīxíng de fāzhǎn móshì.","vi":"Nếu chỉ chạy theo tăng trưởng kinh tế, có thể tạo ra mô hình phát triển lệch lạc."}],"related":[{"hanzi":"变形","pinyin":"biànxíng","vi":"biến dạng"},{"hanzi":"异常","pinyin":"yìcháng","vi":"bất thường"},{"hanzi":"残疾","pinyin":"cánjí","vi":"tàn tật"},{"hanzi":"正常","pinyin":"zhèngcháng","vi":"bình thường"}]},{"id":"积蓄","hanzi":"积蓄","pinyin":"jīxù","meaning_vi":"tiền tiết kiệm; tích lũy, dành dụm","explanation":"积 (tích góp) + 蓄 (dành dụm).","hsk_level":6,"tags":["danh-tu","tien-te"],"image":"💰","examples":[{"type":"basic","zh":"他花光了积蓄。","pinyin":"Tā huāguāngle jīxù.","vi":"Anh ấy đã tiêu hết tiền tiết kiệm."},{"type":"simple","zh":"父母拿出全部积蓄供他出国留学。","pinyin":"Fùmǔ náchū quánbù jīxù gōng tā chūguó liúxué.","vi":"Bố mẹ bỏ ra toàn bộ tiền tiết kiệm để cho anh ấy đi du học."},{"type":"compound","zh":"她先在城里打工积蓄力量，等时机成熟了再回乡创业。","pinyin":"Tā xiān zài chénglǐ dǎgōng jīxù lìliàng, děng shíjī chéngshúle zài huíxiāng chuàngyè.","vi":"Cô ấy trước tiên làm thuê ở thành phố để tích lũy sức lực, đợi thời cơ chín muồi sẽ về quê khởi nghiệp."}],"related":[{"hanzi":"储蓄","pinyin":"chǔxù","vi":"tiết kiệm"},{"hanzi":"存款","pinyin":"cúnkuǎn","vi":"tiền gửi"},{"hanzi":"积攒","pinyin":"jīzǎn","vi":"dành dụm"},{"hanzi":"积累","pinyin":"jīlěi","vi":"tích lũy"}],"traditional":"積蓄"},{"id":"基因","hanzi":"基因","pinyin":"jīyīn","meaning_vi":"gen di truyền","explanation":"基 (cơ – nền) + 因 (nhân – nhân tố), phiên âm từ gene → gen di truyền. Ví dụ: 基因突变, 转基因食品.","hsk_level":6,"tags":["danh-tu","khoa-hoc"],"image":"🧬","examples":[{"type":"basic","zh":"这是基因决定的。","pinyin":"Zhè shì jīyīn juédìng de.","vi":"Điều này do gen quyết định."},{"type":"simple","zh":"科学家发现了一种与长寿有关的基因。","pinyin":"Kēxuéjiā fāxiànle yì zhǒng yǔ chángshòu yǒuguān de jīyīn.","vi":"Các nhà khoa học đã phát hiện một loại gen liên quan đến tuổi thọ."},{"type":"compound","zh":"身高虽然受基因影响，但是营养和运动也很重要。","pinyin":"Shēngāo suīrán shòu jīyīn yǐngxiǎng, dànshì yíngyǎng hé yùndòng yě hěn zhòngyào.","vi":"Chiều cao tuy chịu ảnh hưởng của gen, nhưng dinh dưỡng và vận động cũng rất quan trọng."}],"related":[{"hanzi":"遗传","pinyin":"yíchuán","vi":"di truyền"},{"hanzi":"染色体","pinyin":"rǎnsètǐ","vi":"nhiễm sắc thể"},{"hanzi":"细胞","pinyin":"xìbāo","vi":"tế bào"},{"hanzi":"转基因","pinyin":"zhuǎnjīyīn","vi":"biến đổi gen"}]},{"id":"机智","hanzi":"机智","pinyin":"jīzhì","meaning_vi":"nhanh trí","explanation":"机 (cơ – lanh lợi) + 智 (trí – trí tuệ) → nhanh trí, lanh lợi, ứng biến giỏi. Ví dụ: 机智的回答, 机智勇敢.","hsk_level":6,"tags":["tinh-tu"],"image":"🧠","examples":[{"type":"basic","zh":"这孩子很机智。","pinyin":"Zhè háizi hěn jīzhì.","vi":"Đứa trẻ này rất nhanh trí."},{"type":"simple","zh":"主持人机智地化解了现场的尴尬。","pinyin":"Zhǔchírén jīzhì de huàjiěle xiànchǎng de gāngà.","vi":"Người dẫn chương trình nhanh trí hóa giải tình huống khó xử tại chỗ."},{"type":"compound","zh":"他既机智又幽默，所以每次聚会都是大家的焦点。","pinyin":"Tā jì jīzhì yòu yōumò, suǒyǐ měi cì jùhuì dōu shì dàjiā de jiāodiǎn.","vi":"Anh ấy vừa nhanh trí vừa hài hước nên buổi tụ tập nào cũng là tâm điểm."}],"related":[{"hanzi":"机灵","pinyin":"jīling","vi":"lanh lợi"},{"hanzi":"聪明","pinyin":"cōngmíng","vi":"thông minh"},{"hanzi":"随机应变","pinyin":"suíjīyìngbiàn","vi":"tùy cơ ứng biến"},{"hanzi":"愚笨","pinyin":"yúbèn","vi":"ngu đần"}],"traditional":"機智"},{"id":"激昂","hanzi":"激昂","pinyin":"jī'áng","meaning_vi":"hào hùng, sôi sục (tinh thần/giọng nói)","explanation":"激 + 昂 (cao vút).","hsk_level":6,"tags":["tinh-tu","cam-xuc"],"image":"🔥","examples":[{"type":"basic","zh":"他的声音很激昂。","pinyin":"Tā de shēngyīn hěn jī'áng.","vi":"Giọng anh ấy rất hào hùng."},{"type":"simple","zh":"运动员们在激昂的国歌声中走进了赛场。","pinyin":"Yùndòngyuánmen zài jī'áng de guógē shēng zhōng zǒujìnle sàichǎng.","vi":"Các vận động viên tiến vào sân đấu trong tiếng quốc ca hào hùng."},{"type":"compound","zh":"他一讲到家乡的变化，语气就变得慷慨激昂。","pinyin":"Tā yì jiǎngdào jiāxiāng de biànhuà, yǔqì jiù biànde kāngkǎi jī'áng.","vi":"Hễ nói đến sự đổi thay của quê hương, giọng ông ấy lại trở nên sục sôi hùng hồn."}],"related":[{"hanzi":"慷慨激昂","pinyin":"kāngkǎijī'áng","vi":"hùng hồn hào sảng"},{"hanzi":"激动","pinyin":"jīdòng","vi":"xúc động"},{"hanzi":"高昂","pinyin":"gāo'áng","vi":"dâng cao"},{"hanzi":"低沉","pinyin":"dīchén","vi":"trầm buồn"}]},{"id":"饥饿","hanzi":"饥饿","pinyin":"jī'è","meaning_vi":"đói khát, nạn đói","explanation":"饥 (đói) + 饿 (đói).","hsk_level":6,"tags":["tinh-tu","an-uong"],"image":"🍽️","examples":[{"type":"basic","zh":"他感到非常饥饿。","pinyin":"Tā gǎndào fēicháng jī'è.","vi":"Anh ấy cảm thấy rất đói."},{"type":"simple","zh":"世界上仍有数百万儿童忍受着饥饿。","pinyin":"Shìjiè shàng réng yǒushù bǎiwàn értóng rěnshòuzhe jī'è.","vi":"Trên thế giới vẫn còn hàng triệu trẻ em phải chịu đói."},{"type":"compound","zh":"虽然饥饿难忍，但是他仍然把最后一块面包让给了妹妹。","pinyin":"Suīrán jī'è nán rěn, dànshì tā réngrán bǎ zuìhòu yíkuài miànbāo ràng gěile mèimei.","vi":"Tuy đói không chịu nổi, nhưng cậu vẫn nhường mẩu bánh mì cuối cùng cho em gái."}],"related":[{"hanzi":"饥荒","pinyin":"jīhuang","vi":"nạn đói"},{"hanzi":"饿","pinyin":"è","vi":"đói"},{"hanzi":"温饱","pinyin":"wēnbǎo","vi":"no ấm"},{"hanzi":"饥寒交迫","pinyin":"jīhánjiāopò","vi":"đói rét khốn khổ"}],"traditional":"飢餓"},{"id":"金碧辉煌","hanzi":"金碧辉煌","pinyin":"jīnbì-huīhuáng","meaning_vi":"vàng son lộng lẫy nguy nga","explanation":"金碧辉煌: vàng (金) và xanh ngọc (碧) rực rỡ (辉煌) → công trình kiến trúc lộng lẫy, nguy nga tráng lệ.","hsk_level":6,"tags":["thanh-ngu"],"image":"🏯","examples":[{"type":"basic","zh":"故宫金碧辉煌。","pinyin":"Gùgōng jīnbìhuīhuáng.","vi":"Cố Cung vàng son lộng lẫy."},{"type":"simple","zh":"酒店大堂装饰得金碧辉煌，非常气派。","pinyin":"Jiǔdiàn dàtáng zhuāngshì de jīnbìhuīhuáng, fēicháng qìpài.","vi":"Sảnh khách sạn trang trí vàng son lộng lẫy, rất bề thế."},{"type":"compound","zh":"寺庙的外表虽然金碧辉煌，但是里面的僧人生活十分简朴。","pinyin":"Sìmiào de wàibiǎo suīrán jīnbìhuīhuáng, dànshì lǐmiàn de sēngrén shēnghuó shífēn jiǎnpǔ.","vi":"Bề ngoài ngôi chùa tuy vàng son lộng lẫy, nhưng các nhà sư bên trong sống rất giản dị."}],"related":[{"hanzi":"富丽堂皇","pinyin":"fùlìtánghuáng","vi":"lộng lẫy nguy nga"},{"hanzi":"辉煌","pinyin":"huīhuáng","vi":"huy hoàng"},{"hanzi":"华丽","pinyin":"huálì","vi":"hoa lệ"},{"hanzi":"简陋","pinyin":"jiǎnlòu","vi":"sơ sài"}],"traditional":"金碧輝煌"},{"id":"斤斤计较","hanzi":"斤斤计较","pinyin":"jīnjīn-jìjiào","meaning_vi":"so đo tính toán từng li từng tí","explanation":"斤斤计较: tính toán (计较) từng cân (斤) từng lạng → so đo chi li từng chút một, nhỏ mọn. Mang nghĩa chê.","hsk_level":6,"tags":["thanh-ngu"],"image":"😒","examples":[{"type":"basic","zh":"别斤斤计较。","pinyin":"Bié jīnjīnjìjiào.","vi":"Đừng so đo tính toán."},{"type":"simple","zh":"她买菜时总爱为几毛钱斤斤计较。","pinyin":"Tā mǎicài shí zǒng ài wèi jǐ máo qián jīnjīnjìjiào.","vi":"Lúc đi chợ cô ấy luôn so đo từng mấy hào."},{"type":"compound","zh":"朋友之间如果斤斤计较，友谊就很难长久。","pinyin":"Péngyou zhījiān rúguǒ jīnjīnjìjiào, yǒuyì jiù hěn nán chángjiǔ.","vi":"Giữa bạn bè nếu so đo tính toán thì tình bạn khó mà lâu dài."}],"related":[{"hanzi":"锱铢必较","pinyin":"zīzhūbìjiào","vi":"tính từng xu"},{"hanzi":"小气","pinyin":"xiǎoqi","vi":"keo kiệt"},{"hanzi":"计较","pinyin":"jìjiào","vi":"so đo"},{"hanzi":"宽宏大量","pinyin":"kuānhóngdàliàng","vi":"khoan dung độ lượng"}],"traditional":"斤斤計較"},{"id":"津津乐道","hanzi":"津津乐道","pinyin":"jīnjīn-lèdào","meaning_vi":"say sưa bàn tán thích thú","explanation":"津津乐道: say sưa (津津) thích thú (乐) nói (道) → hào hứng bàn tán mãi về chuyện gì. Ví dụ: 人们津津乐道的话题.","hsk_level":6,"tags":["thanh-ngu","giao-tiep"],"image":"🗣️","examples":[{"type":"basic","zh":"邻居们对此津津乐道。","pinyin":"Línjūmen duì cǐ jīnjīnlèdào.","vi":"Hàng xóm say sưa bàn tán về chuyện này."},{"type":"simple","zh":"他至今还对那次环球旅行津津乐道。","pinyin":"Tā zhìjīn hái duì nà cì huánqiú lǚxíng jīnjīnlèdào.","vi":"Đến giờ anh ấy vẫn say sưa kể về chuyến du lịch vòng quanh thế giới năm ấy."},{"type":"compound","zh":"那场精彩的逆转不但让球迷激动，而且成了人们津津乐道的话题。","pinyin":"Nà chǎng jīngcǎi de nìzhuǎn búdàn ràng qiúmí jīdòng, érqiě chéngle rénmen jīnjīnlèdào de huàtí.","vi":"Màn lội ngược dòng ngoạn mục ấy không chỉ khiến người hâm mộ phấn khích mà còn trở thành đề tài được say sưa bàn tán."}],"related":[{"hanzi":"津津有味","pinyin":"jīnjīnyǒuwèi","vi":"ngon lành thú vị"},{"hanzi":"夸夸其谈","pinyin":"kuākuāqítán","vi":"ba hoa"},{"hanzi":"谈论","pinyin":"tánlùn","vi":"bàn luận"},{"hanzi":"乐此不疲","pinyin":"lècǐbùpí","vi":"vui không biết mệt"}],"traditional":"津津樂道"},{"id":"精华","hanzi":"精华","pinyin":"jīnghuá","meaning_vi":"tinh hoa","explanation":"精 (tinh – tinh túy) + 华 (hoa – hoa, tốt đẹp) → tinh hoa, phần tốt đẹp nhất. Ví dụ: 文化精华, 取其精华，去其糟粕.","hsk_level":6,"tags":["danh-tu"],"image":"💎","examples":[{"type":"basic","zh":"这是全书的精华。","pinyin":"Zhè shì quánshū de jīnghuá.","vi":"Đây là tinh hoa của cả cuốn sách."},{"type":"simple","zh":"京剧是中国传统文化的精华之一。","pinyin":"Jīngjù shì Zhōngguó chuántǒng wénhuà de jīnghuá zhīyī.","vi":"Kinh kịch là một trong những tinh hoa của văn hóa truyền thống Trung Quốc."},{"type":"compound","zh":"如果你只有十分钟，就先看这部纪录片的精华片段。","pinyin":"Rúguǒ nǐ zhǐyǒu shí fēnzhōng, jiù xiān kàn zhè bù jìlùpiàn de jīnghuá piànduàn.","vi":"Nếu bạn chỉ có mười phút thì xem trước những đoạn tinh hoa của bộ phim tài liệu này."}],"related":[{"hanzi":"精髓","pinyin":"jīngsuǐ","vi":"tinh túy"},{"hanzi":"糟粕","pinyin":"zāopò","vi":"cặn bã"},{"hanzi":"取其精华","pinyin":"qǔqíjīnghuá","vi":"lấy tinh hoa"},{"hanzi":"精粹","pinyin":"jīngcuì","vi":"tinh túy"}],"traditional":"精華"},{"id":"惊慌失措","hanzi":"惊慌失措","pinyin":"jīnghuāng-shīcuò","meaning_vi":"kinh hoàng mất bình tĩnh","explanation":"惊慌失措: kinh hoàng (惊慌) đến mức mất (失) cách xử lý (措) → hoảng hốt, cuống cuồng không biết làm gì.","hsk_level":6,"tags":["thanh-ngu","cam-xuc"],"image":"😱","examples":[{"type":"basic","zh":"她惊慌失措地尖叫。","pinyin":"Tā jīnghuāngshīcuò de jiānjiào.","vi":"Cô ấy hoảng hốt hét lên."},{"type":"simple","zh":"地震发生时，乘客们惊慌失措地往外跑。","pinyin":"Dìzhèn fāshēng shí, chéngkèmen jīnghuāngshīcuò de wǎng wài pǎo.","vi":"Khi động đất xảy ra, hành khách hoảng loạn chạy ra ngoài."},{"type":"compound","zh":"遇到火灾时即使再害怕，也不要惊慌失措。","pinyin":"Yùdào huǒzāi shí jíshǐ zài hàipà, yě bú yào jīnghuāngshīcuò.","vi":"Gặp hỏa hoạn dù sợ đến mấy cũng đừng hoảng loạn mất bình tĩnh."}],"related":[{"hanzi":"手忙脚乱","pinyin":"shǒumángjiǎoluàn","vi":"luống cuống tay chân"},{"hanzi":"惊慌","pinyin":"jīnghuāng","vi":"hoảng sợ"},{"hanzi":"从容不迫","pinyin":"cóngróngbúpò","vi":"ung dung bình tĩnh"},{"hanzi":"镇定自若","pinyin":"zhèndìngzìruò","vi":"bình tĩnh như thường"}],"traditional":"驚慌失措"},{"id":"精疲力竭","hanzi":"精疲力竭","pinyin":"jīngpí-lìjié","meaning_vi":"kiệt sức mệt nhoài","explanation":"精疲力竭: tinh thần (精) mệt mỏi (疲), sức lực (力) cạn kiệt (竭) → kiệt sức, mệt rã rời. Cũng viết 筋疲力尽.","hsk_level":6,"tags":["thanh-ngu","suc-khoe"],"image":"😫","examples":[{"type":"basic","zh":"我已经精疲力竭了。","pinyin":"Wǒ yǐjīng jīngpílìjié le.","vi":"Tôi đã kiệt sức rồi."},{"type":"simple","zh":"爬完泰山，大家都累得精疲力竭。","pinyin":"Pá wán Tàishān, dàjiā dōu lèi de jīngpílìjié.","vi":"Leo xong Thái Sơn, mọi người đều mệt rã rời."},{"type":"compound","zh":"她连续值了两个夜班，所以回到家就精疲力竭地睡着了。","pinyin":"Tā liánxù zhíle liǎng gè yèbān, suǒyǐ huí dàojiā jiù jīngpílìjié de shuìzháo le.","vi":"Cô ấy trực liền hai ca đêm nên về đến nhà là kiệt sức ngủ thiếp đi."}],"related":[{"hanzi":"筋疲力尽","pinyin":"jīnpílìjìn","vi":"kiệt sức"},{"hanzi":"疲惫不堪","pinyin":"píbèibùkān","vi":"mệt mỏi rã rời"},{"hanzi":"精力充沛","pinyin":"jīnglìchōngpèi","vi":"tràn đầy sức lực"},{"hanzi":"疲劳","pinyin":"píláo","vi":"mệt mỏi"}]},{"id":"惊天动地","hanzi":"惊天动地","pinyin":"jīngtiān-dòngdì","meaning_vi":"kinh thiên động địa","explanation":"惊天动地: làm kinh động (惊) trời (天), rung chuyển (动) đất (地) → tiếng động hoặc sự kiện cực lớn, chấn động.","hsk_level":6,"tags":["thanh-ngu"],"image":"💥","examples":[{"type":"basic","zh":"那是一场惊天动地的爱情。","pinyin":"Nàshì yì chǎng jīngtiāndòngdì de àiqíng.","vi":"Đó là một mối tình kinh thiên động địa."},{"type":"simple","zh":"山洪爆发时发出了惊天动地的轰鸣声。","pinyin":"Shānhóng bàofā shí fāchūle jīngtiāndòngdì de hōngmíng shēng.","vi":"Khi lũ quét bùng phát, vang lên tiếng gầm rung chuyển trời đất."},{"type":"compound","zh":"平凡的人虽然做不出惊天动地的事业，却能默默温暖身边的人。","pinyin":"Píngfán de rén suīrán zuò bu chū jīngtiāndòngdì de shìyè, què néng mòmò wēnnuǎn shēnbiān de rén.","vi":"Người bình thường tuy không làm nên sự nghiệp kinh thiên động địa, nhưng có thể lặng lẽ sưởi ấm những người xung quanh."}],"related":[{"hanzi":"震天动地","pinyin":"zhèntiāndòngdì","vi":"rung chuyển trời đất"},{"hanzi":"轰轰烈烈","pinyin":"hōnghōnglièliè","vi":"oanh liệt"},{"hanzi":"翻天覆地","pinyin":"fāntiānfùdì","vi":"long trời lở đất"},{"hanzi":"震撼","pinyin":"zhènhàn","vi":"chấn động"}],"traditional":"驚天動地"},{"id":"精通","hanzi":"精通","pinyin":"jīngtōng","meaning_vi":"tinh thông","explanation":"精 (tinh – tinh thông) + 通 (thông – thông suốt) → am hiểu sâu, thành thạo. Ví dụ: 精通三门外语, 精通业务.","hsk_level":6,"tags":["dong-tu"],"image":"🧠","examples":[{"type":"basic","zh":"他精通三门外语。","pinyin":"Tā jīngtōng Sānmén wàiyǔ.","vi":"Anh ấy thông thạo ba ngoại ngữ."},{"type":"simple","zh":"这位老中医精通针灸和推拿。","pinyin":"Zhè wèi lǎo zhōngyī jīngtōng zhēnjiǔ hé tuīná.","vi":"Vị lương y già này tinh thông châm cứu và xoa bóp."},{"type":"compound","zh":"他不但精通电脑编程，而且对音乐也很有研究。","pinyin":"Tā búdàn jīngtōng diànnǎo biānchéng, érqiě duì yīnyuè yě hěn yǒu yánjiū.","vi":"Anh ấy không những tinh thông lập trình máy tính mà còn rất am hiểu âm nhạc."}],"related":[{"hanzi":"熟练","pinyin":"shúliàn","vi":"thành thạo"},{"hanzi":"擅长","pinyin":"shàncháng","vi":"giỏi về"},{"hanzi":"通晓","pinyin":"tōngxiǎo","vi":"thông hiểu"},{"hanzi":"一窍不通","pinyin":"yíqiàobùtōng","vi":"mù tịt"}]},{"id":"精卫填海","hanzi":"精卫填海","pinyin":"jīngwèi-tiánhǎi","meaning_vi":"chim Tinh Vệ lấp biển (ý chí kiên cường bền bỉ)","explanation":"Truyền thuyết thần thoại. Thành ngữ.","hsk_level":6,"tags":["thanh-ngu","van-hoa"],"image":"🕊️","examples":[{"type":"basic","zh":"精卫填海的故事很感人。","pinyin":"Jīngwèitiánhǎi de gùshi hěn gǎnrén.","vi":"Câu chuyện Tinh Vệ lấp biển rất cảm động."},{"type":"simple","zh":"他把这项研究比作精卫填海，一做就是二十年。","pinyin":"Tā bǎ zhè xiàng yánjiū bǐzuò Jīngwèitiánhǎi, yí zuò jiùshì èrshí nián.","vi":"Ông ví công trình nghiên cứu này như chim Tinh Vệ lấp biển, cứ thế làm suốt hai mươi năm."},{"type":"compound","zh":"因为老人有精卫填海般的毅力，所以三十年来一直坚持在沙漠里种树。","pinyin":"Yīnwèi lǎorén yǒu Jīngwèitiánhǎi bān de yìlì, suǒyǐ sānshí niánlái yìzhí jiānchí zài shāmò lǐ zhòngshù.","vi":"Vì ông cụ có nghị lực như chim Tinh Vệ lấp biển, nên ba mươi năm nay vẫn kiên trì trồng cây trên sa mạc."}],"related":[{"hanzi":"愚公移山","pinyin":"yúgōngyíshān","vi":"ngu công dời núi"},{"hanzi":"锲而不舍","pinyin":"qiè'érbùshě","vi":"bền chí không bỏ"},{"hanzi":"坚持不懈","pinyin":"jiānchíbúxiè","vi":"kiên trì không mệt mỏi"},{"hanzi":"神话","pinyin":"shénhuà","vi":"thần thoại"}],"traditional":"精衛填海"},{"id":"经纬","hanzi":"经纬","pinyin":"jīngwěi","meaning_vi":"kinh độ và vĩ độ","explanation":"经 (kinh – sợi dọc) + 纬 (vĩ – sợi ngang) → sợi dọc và ngang trên khung cửi; trong địa lý: kinh tuyến và vĩ tuyến, kinh độ vĩ độ.","hsk_level":6,"tags":["danh-tu","khoa-hoc"],"image":"🌐","examples":[{"type":"basic","zh":"请报告你的经纬坐标。","pinyin":"Qǐng bàogào nǐ de jīngwěi zuòbiāo.","vi":"Hãy báo tọa độ kinh vĩ của bạn."},{"type":"simple","zh":"船员根据经纬度确定了船只的位置。","pinyin":"Chuányuán gēnjù jīng Wěidù quèdìngle chuánzhī de wèizhì.","vi":"Thủy thủ xác định vị trí con tàu dựa vào kinh độ và vĩ độ."},{"type":"compound","zh":"只要知道一个地点的经纬，就能在地图上准确找到它。","pinyin":"Zhǐyào zhīdào yí gè dìdiǎn de jīngwěi, jiù néng zài dìtú shàng zhǔnquè zhǎodào tā.","vi":"Chỉ cần biết kinh độ, vĩ độ của một địa điểm là có thể tìm chính xác nó trên bản đồ."}],"related":[{"hanzi":"经度","pinyin":"Jīngdù","vi":"kinh độ"},{"hanzi":"纬度","pinyin":"Wěidù","vi":"vĩ độ"},{"hanzi":"地球仪","pinyin":"dìqiúyí","vi":"quả địa cầu"},{"hanzi":"坐标","pinyin":"zuòbiāo","vi":"tọa độ"}],"traditional":"經緯"},{"id":"惊讶","hanzi":"惊讶","pinyin":"jīngyà","meaning_vi":"kinh ngạc","explanation":"惊 (kinh – sợ, giật mình) + 讶 (nhạ – ngạc nhiên) → kinh ngạc, ngạc nhiên. Ví dụ: 感到惊讶, 惊讶地发现.","hsk_level":6,"tags":["tinh-tu"],"image":"😮","examples":[{"type":"basic","zh":"我感到很惊讶。","pinyin":"Wǒ gǎndào hěn jīngyà.","vi":"Tôi cảm thấy rất kinh ngạc."},{"type":"simple","zh":"她惊讶地发现钱包竟然被送回来了。","pinyin":"Tā jīngyà de fāxiàn qiánbāo jìngrán bèi sòng huílái le.","vi":"Cô ấy ngạc nhiên phát hiện chiếc ví đã được mang trả lại."},{"type":"compound","zh":"听说他辞职去当厨师，同事们既惊讶又佩服。","pinyin":"Tīngshuō tā cízhí qù dāng chúshī, tóngshìmen jì jīngyà yòu pèifú.","vi":"Nghe tin anh ấy nghỉ việc đi làm đầu bếp, đồng nghiệp vừa kinh ngạc vừa nể phục."}],"related":[{"hanzi":"吃惊","pinyin":"chījīng","vi":"giật mình"},{"hanzi":"惊奇","pinyin":"jīngqí","vi":"kinh ngạc"},{"hanzi":"诧异","pinyin":"chàyì","vi":"ngạc nhiên"},{"hanzi":"惊喜","pinyin":"jīngxǐ","vi":"ngạc nhiên vui mừng"}],"traditional":"驚訝"},{"id":"精致","hanzi":"精致","pinyin":"jīngzhì","meaning_vi":"tinh xảo","explanation":"精 (tinh – tinh tế) + 致 (trí – tỉ mỉ) → tinh xảo, tinh tế, tỉ mỉ đẹp đẽ. Ví dụ: 精致的礼物, 做工精致.","hsk_level":6,"tags":["tinh-tu"],"image":"✨","examples":[{"type":"basic","zh":"这个盒子很精致。","pinyin":"Zhè ge hézi hěn jīngzhì.","vi":"Chiếc hộp này rất tinh xảo."},{"type":"simple","zh":"她送给我一套做工精致的茶具。","pinyin":"Tā sònggěi wǒ yítào zuògōng jīngzhì de chájù.","vi":"Cô ấy tặng tôi một bộ ấm chén chế tác tinh xảo."},{"type":"compound","zh":"这家店的点心既精致又美味，所以价格贵一点也值得。","pinyin":"Zhè jiā diàn de diǎnxin jì jīngzhì yòu měiwèi, suǒyǐ jiàgé guì yìdiǎn yě zhíde.","vi":"Bánh ngọt ở tiệm này vừa tinh tế vừa ngon nên giá đắt một chút cũng đáng."}],"related":[{"hanzi":"精美","pinyin":"jīngměi","vi":"tinh mỹ"},{"hanzi":"精巧","pinyin":"jīngqiǎo","vi":"tinh xảo"},{"hanzi":"粗糙","pinyin":"cūcāo","vi":"thô ráp"},{"hanzi":"细致","pinyin":"xìzhì","vi":"tỉ mỉ"}],"traditional":"精緻"},{"id":"拘束","hanzi":"拘束","pinyin":"jūshù","meaning_vi":"gò bó, rụt rè","explanation":"拘 (câu – bó buộc) + 束 (thúc – trói) → gò bó, rụt rè, mất tự nhiên; động từ: hạn chế, ràng buộc. Ví dụ: 别拘束, 拘束感.","hsk_level":6,"tags":["tinh-tu"],"image":"😳","examples":[{"type":"basic","zh":"大家别拘束，随便坐。","pinyin":"Dàjiā bié jūshù, suíbiàn zuò.","vi":"Mọi người đừng ngại, cứ ngồi tự nhiên."},{"type":"simple","zh":"第一次去女朋友家，他显得有些拘束。","pinyin":"Dìyīcì qù nǚpéngyou jiā, tā xiǎnde yǒuxiē jūshù.","vi":"Lần đầu đến nhà bạn gái, anh ấy có vẻ hơi rụt rè."},{"type":"compound","zh":"孩子们一见到校长就变得拘束起来，连说话都小声了。","pinyin":"Háizimen yí jiàndào xiàozhǎng jiù biànde jūshù qǐlái, lián shuōhuà dōu xiǎoshēng le.","vi":"Bọn trẻ vừa gặp thầy hiệu trưởng liền trở nên rụt rè, đến nói cũng nhỏ giọng."}],"related":[{"hanzi":"约束","pinyin":"yuēshù","vi":"ràng buộc"},{"hanzi":"拘谨","pinyin":"jūjǐn","vi":"rụt rè"},{"hanzi":"无拘无束","pinyin":"wújūwúshù","vi":"tự do thoải mái"},{"hanzi":"自在","pinyin":"zìzai","vi":"thoải mái"}]},{"id":"居安思危","hanzi":"居安思危","pinyin":"jū'ān-sīwēi","meaning_vi":"sống trong yên bình phải nghĩ tới lúc nguy nan","explanation":"居安思危: sống (居) trong yên ổn (安) phải nghĩ (思) đến nguy nan (危) (Tả Truyện) → luôn đề phòng khó khăn có thể xảy ra.","hsk_level":6,"tags":["thanh-ngu"],"image":"🛡️","examples":[{"type":"basic","zh":"居安思危才能长久。","pinyin":"Jū'ānsīwēi cáinéng chángjiǔ.","vi":"Có lo xa lúc yên ổn mới bền lâu."},{"type":"simple","zh":"这家企业一向居安思危，提前准备了应急资金。","pinyin":"Zhè jiā qǐyè yíxiàng jū'ānsīwēi, tíqián zhǔnbèile yìngjí zījīn.","vi":"Doanh nghiệp này luôn lo xa khi yên ổn, đã chuẩn bị trước quỹ dự phòng."},{"type":"compound","zh":"即使现在生意很好，我们也要居安思危。","pinyin":"Jíshǐ xiànzài shēngyi hěn hǎo, wǒmen yě yào jū'ānsīwēi.","vi":"Dù hiện tại làm ăn rất tốt, chúng ta cũng phải lo xa phòng lúc nguy."}],"related":[{"hanzi":"防患于未然","pinyin":"fánghuàn yú wèirán","vi":"phòng bệnh hơn chữa bệnh"},{"hanzi":"未雨绸缪","pinyin":"wèiyǔchóumóu","vi":"lo trước khi mưa"},{"hanzi":"高枕无忧","pinyin":"gāozhěnwúyōu","vi":"kê cao gối ngủ"},{"hanzi":"忧患意识","pinyin":"yōuhuànyìshi","vi":"ý thức lo xa"}]},{"id":"挤兑","hanzi":"挤兑","pinyin":"jǐduì","meaning_vi":"rút tiền ồ ạt (khỏi ngân hàng), chèn ép","explanation":"挤 (chen) + 兑 (đổi tiền).","hsk_level":6,"tags":["dong-tu","tien-te"],"image":"🏦","examples":[{"type":"basic","zh":"银行遭遇了挤兑。","pinyin":"Yínháng zāoyùle jǐduì.","vi":"Ngân hàng gặp phải làn sóng rút tiền ồ ạt."},{"type":"simple","zh":"谣言引发了储户对这家银行的挤兑。","pinyin":"Yáoyán yǐnfāle chǔhù duì zhè jiā yínháng de jǐduì.","vi":"Tin đồn đã khiến người gửi tiền đổ xô rút tiền khỏi ngân hàng này."},{"type":"compound","zh":"他刚进公司不久，就常被几个老员工挤兑。","pinyin":"Tā gāng jìn gōngsī bùjiǔ, jiù cháng bèi jǐ gè lǎo yuángōng jǐduì.","vi":"Anh ấy mới vào công ty không lâu đã thường bị mấy nhân viên cũ chèn ép."}],"related":[{"hanzi":"银行","pinyin":"yínháng","vi":"ngân hàng"},{"hanzi":"取款","pinyin":"qǔkuǎn","vi":"rút tiền"},{"hanzi":"排挤","pinyin":"páijǐ","vi":"chèn ép"},{"hanzi":"金融危机","pinyin":"jīnróngwēijī","vi":"khủng hoảng tài chính"}],"traditional":"擠兌"},{"id":"济济一堂","hanzi":"济济一堂","pinyin":"jǐjǐ-yìtáng","meaning_vi":"đông đủ nhân tài tụ họp một nhà","explanation":"济济一堂: nhiều người tài (济济) tụ họp chung một (一) nhà (堂) → đông đủ nhân tài tề tựu. Lưu ý 济 ở đây đọc jǐ.","hsk_level":6,"tags":["thanh-ngu"],"image":"🏛️","examples":[{"type":"basic","zh":"专家们济济一堂。","pinyin":"Zhuānjiāmen jǐjǐyìtáng.","vi":"Các chuyên gia tề tựu đông đủ."},{"type":"simple","zh":"毕业三十年后，老同学们又济济一堂。","pinyin":"Bìyè sānshí nián hòu, lǎo tóngxuémen yòu jǐjǐyìtáng.","vi":"Ba mươi năm sau khi tốt nghiệp, các bạn học cũ lại tề tựu đông đủ."},{"type":"compound","zh":"虽然平时各忙各的，但是春节时我们家四代人总会济济一堂。","pinyin":"Suīrán píngshí gè máng gè de, dànshì Chūnjié shí wǒmen jiā sì dài rén zǒng huì jǐjǐyìtáng.","vi":"Tuy ngày thường ai cũng bận việc riêng, nhưng dịp Tết bốn thế hệ nhà tôi luôn sum vầy đông đủ."}],"related":[{"hanzi":"欢聚一堂","pinyin":"huānjùyìtáng","vi":"vui vẻ quây quần"},{"hanzi":"人才济济","pinyin":"réncáijǐjǐ","vi":"nhân tài đông đúc"},{"hanzi":"齐聚","pinyin":"qíjù","vi":"tụ họp đông đủ"},{"hanzi":"聚会","pinyin":"jùhuì","vi":"buổi gặp mặt"}],"traditional":"濟濟一堂"},{"id":"给予","hanzi":"给予","pinyin":"jǐyǔ","meaning_vi":"ban cho, dành cho, trao cho","explanation":"给 (đọc jǐ) + 予 (cho).","hsk_level":6,"tags":["dong-tu"],"image":"🤲","examples":[{"type":"basic","zh":"请给予支持。","pinyin":"Qǐng jǐyǔ zhīchí.","vi":"Xin hãy ủng hộ."},{"type":"simple","zh":"政府给予受灾农户每户五千元补贴。","pinyin":"Zhèngfǔ jǐyǔ shòuzāi nónghù měi hù wǔ qiān yuán bǔtiē.","vi":"Chính phủ trợ cấp năm nghìn tệ cho mỗi hộ nông dân bị thiên tai."},{"type":"compound","zh":"如果孩子做得好，家长就应该及时给予表扬。","pinyin":"Rúguǒ háizi zuò de hǎo, jiāzhǎng jiù yīnggāi jíshí jǐyǔ biǎoyáng.","vi":"Nếu con làm tốt, phụ huynh nên kịp thời khen ngợi."}],"related":[{"hanzi":"赋予","pinyin":"fùyǔ","vi":"ban cho"},{"hanzi":"给","pinyin":"gěi","vi":"cho"},{"hanzi":"提供","pinyin":"tígōng","vi":"cung cấp"},{"hanzi":"授予","pinyin":"shòuyǔ","vi":"trao tặng"}],"traditional":"給予"},{"id":"锦上添花","hanzi":"锦上添花","pinyin":"jǐnshàng-tiānhuā","meaning_vi":"thêu hoa trên gấm","explanation":"锦上添花: thêu thêm (添) hoa (花) lên gấm (锦) → đã đẹp lại càng đẹp thêm, tốt lại thêm tốt. Đối lập: 雪中送炭.","hsk_level":6,"tags":["thanh-ngu"],"image":"🌺","examples":[{"type":"basic","zh":"这真是锦上添花。","pinyin":"Zhè zhēn shì jǐnshàngtiānhuā.","vi":"Đây đúng là thêu hoa trên gấm."},{"type":"simple","zh":"一首好的背景音乐能给视频锦上添花。","pinyin":"Yì shǒu hǎo de bèijǐng yīnyuè néng gěi shìpín jǐnshàngtiānhuā.","vi":"Một bản nhạc nền hay có thể khiến video thêm phần hoàn hảo."},{"type":"compound","zh":"与其给富人锦上添花，不如给穷人雪中送炭。","pinyin":"Yǔqí gěi fùrén jǐnshàngtiānhuā, bùrú gěi qióngrén xuězhōngsòngtàn.","vi":"Thay vì thêu hoa trên gấm cho người giàu, chi bằng đưa than sưởi ấm ngày tuyết cho người nghèo."}],"related":[{"hanzi":"雪中送炭","pinyin":"xuězhōngsòngtàn","vi":"giúp người lúc khó khăn"},{"hanzi":"画龙点睛","pinyin":"huàlóngdiǎnjīng","vi":"vẽ rồng điểm mắt"},{"hanzi":"好上加好","pinyin":"hǎoshàngjiāhǎo","vi":"tốt lại càng tốt"},{"hanzi":"雪上加霜","pinyin":"xuěshàngjiāshuāng","vi":"họa vô đơn chí"}],"traditional":"錦上添花"},{"id":"警告","hanzi":"警告","pinyin":"jǐnggào","meaning_vi":"cảnh cáo","explanation":"警 (cảnh – răn) + 告 (cáo – báo) → cảnh cáo, răn đe; hình thức kỷ luật. Ví dụ: 发出警告, 警告处分.","hsk_level":6,"tags":["dong-tu"],"image":"⚠️","examples":[{"type":"basic","zh":"医生警告他戒烟。","pinyin":"Yīshēng jǐnggào tā jièyān.","vi":"Bác sĩ cảnh báo anh ấy phải bỏ thuốc lá."},{"type":"simple","zh":"裁判因为他故意拖延时间给了他一次警告。","pinyin":"Cáipàn yīnwèi tā gùyì tuōyán shíjiān gěile tā yí cì jǐnggào.","vi":"Trọng tài cảnh cáo anh ta một lần vì cố tình câu giờ."},{"type":"compound","zh":"如果你再迟到，公司就会对你发出书面警告。","pinyin":"Rúguǒ nǐ zài chídào, gōngsī jiù huì duì nǐ fāchū shūmiàn jǐnggào.","vi":"Nếu bạn còn đi muộn, công ty sẽ gửi cảnh cáo bằng văn bản cho bạn."}],"related":[{"hanzi":"警示","pinyin":"jǐngshì","vi":"cảnh báo"},{"hanzi":"提醒","pinyin":"tíxǐng","vi":"nhắc nhở"},{"hanzi":"警惕","pinyin":"jǐngtì","vi":"cảnh giác"},{"hanzi":"处分","pinyin":"chǔfèn","vi":"kỷ luật"}]},{"id":"举世闻名","hanzi":"举世闻名","pinyin":"jǔshì-wénmíng","meaning_vi":"nổi tiếng thế giới","explanation":"举世闻名: cả (举) thế giới (世) đều nghe tiếng (闻名) → nổi tiếng khắp thế giới. Ví dụ: 举世闻名的长城.","hsk_level":6,"tags":["thanh-ngu"],"image":"🌍","examples":[{"type":"basic","zh":"长城举世闻名。","pinyin":"Chángchéng jǔshìwénmíng.","vi":"Vạn Lý Trường Thành nổi tiếng khắp thế giới."},{"type":"simple","zh":"这座举世闻名的寺庙每天都吸引大批游客。","pinyin":"Zhè zuò jǔshìwénmíng de sìmiào měitiān dōu xīyǐn dàpī yóukè.","vi":"Ngôi chùa nổi tiếng thế giới này mỗi ngày đều thu hút rất đông du khách."},{"type":"compound","zh":"虽然这位科学家举世闻名，但是他生活非常简朴。","pinyin":"Suīrán zhè wèi kēxuéjiā jǔshìwénmíng, dànshì tā shēnghuó fēicháng jiǎnpǔ.","vi":"Tuy nhà khoa học này nổi tiếng khắp thế giới nhưng ông sống rất giản dị."}],"related":[{"hanzi":"闻名于世","pinyin":"wénmíngyúshì","vi":"nổi tiếng thế giới"},{"hanzi":"家喻户晓","pinyin":"jiāyùhùxiǎo","vi":"nhà nhà đều biết"},{"hanzi":"著名","pinyin":"zhùmíng","vi":"nổi tiếng"},{"hanzi":"默默无闻","pinyin":"mòmòwúwén","vi":"vô danh"}],"traditional":"舉世聞名"},{"id":"举一反三","hanzi":"举一反三","pinyin":"jǔyì-fǎnsān","meaning_vi":"học một biết ba, suy luận thông minh","explanation":"举一反三: nêu (举) một góc, suy ra (反) ba góc kia (Luận Ngữ) → học một biết mười, biết suy luận ra điều khác.","hsk_level":6,"tags":["thanh-ngu","hoc-tap"],"image":"🧠","examples":[{"type":"basic","zh":"学数学要举一反三。","pinyin":"Xué shùxué yào jǔyìfǎnsān.","vi":"Học toán phải biết học một hiểu mười."},{"type":"simple","zh":"老师鼓励我们做题时举一反三。","pinyin":"Lǎoshī gǔlì wǒmen zuò tí shí jǔyìfǎnsān.","vi":"Thầy giáo khuyến khích chúng tôi khi làm bài thì phải biết suy rộng ra."},{"type":"compound","zh":"只要掌握了基本方法，你就能举一反三。","pinyin":"Zhǐyào zhǎngwòle jīběn fāngfǎ, nǐ jiù néng jǔyìfǎnsān.","vi":"Chỉ cần nắm được phương pháp cơ bản, bạn sẽ có thể học một biết mười."}],"related":[{"hanzi":"触类旁通","pinyin":"chùlèipángtōng","vi":"hiểu một biết mười"},{"hanzi":"闻一知十","pinyin":"wényìzhīshí","vi":"nghe một biết mười"},{"hanzi":"融会贯通","pinyin":"rónghuìguàntōng","vi":"thông suốt"},{"hanzi":"死记硬背","pinyin":"sǐjìyìngbèi","vi":"học vẹt"}],"traditional":"舉一反三"},{"id":"挎","hanzi":"挎","pinyin":"kuà","meaning_vi":"khoác túi","explanation":"挎 (khóa): khoác, đeo (túi, giỏ) trên vai, khuỷu tay hoặc bên hông; cũng là khoác tay. Ví dụ: 挎包, 挎着篮子, 挎着胳膊.","hsk_level":6,"tags":["dong-tu"],"image":"👜","examples":[{"type":"basic","zh":"她挎着一个包。","pinyin":"Tā kuàzhe yí gè bāo.","vi":"Cô ấy khoác một chiếc túi."},{"type":"simple","zh":"奶奶挎着菜篮子去早市买菜了。","pinyin":"Nǎinai kuàzhe càilánzi qù zǎoshì mǎicài le.","vi":"Bà khoác giỏ đi chợ sáng mua rau rồi."},{"type":"compound","zh":"他一下车就挎上沉重的背包，朝山顶走去。","pinyin":"Tā yí xiàchē jiù kuà shàng chénzhòng de bēibāo, cháo shāndǐng zǒuqù.","vi":"Anh ấy vừa xuống xe liền khoác chiếc ba lô nặng trĩu lên, đi về phía đỉnh núi."}],"related":[{"hanzi":"挎包","pinyin":"kuàbāo","vi":"túi đeo vai"},{"hanzi":"背","pinyin":"bēi","vi":"cõng, đeo"},{"hanzi":"提","pinyin":"tí","vi":"xách"},{"hanzi":"拎","pinyin":"līn","vi":"xách"}]},{"id":"脍炙人口","hanzi":"脍炙人口","pinyin":"kuàizhì-rénkǒu","meaning_vi":"tác phẩm hay được mọi người truyền tụng yêu thích","explanation":"脍炙人口: thịt thái nhỏ (脍) và thịt nướng (炙) ai ăn cũng thích → tác phẩm, câu chuyện hay được mọi người truyền tụng yêu thích.","hsk_level":6,"tags":["thanh-ngu","van-hoa"],"image":"📖","examples":[{"type":"basic","zh":"这首诗脍炙人口。","pinyin":"Zhè shǒu shī kuàizhìrénkǒu.","vi":"Bài thơ này được mọi người yêu thích truyền tụng."},{"type":"simple","zh":"李白留下了许多脍炙人口的诗篇。","pinyin":"Lǐbái liúxiàle xǔduō kuàizhìrénkǒu de shīpiān.","vi":"Lý Bạch để lại nhiều bài thơ được truyền tụng rộng rãi."},{"type":"compound","zh":"这首歌不但旋律优美，而且歌词脍炙人口。","pinyin":"Zhè shǒu gē búdàn xuánlǜ yōuměi, érqiě gēcí kuàizhìrénkǒu.","vi":"Bài hát này không những giai điệu hay mà lời ca còn được mọi người thuộc nằm lòng."}],"related":[{"hanzi":"家喻户晓","pinyin":"jiāyùhùxiǎo","vi":"nhà nhà đều biết"},{"hanzi":"广为流传","pinyin":"guǎngwéiliúchuán","vi":"lưu truyền rộng rãi"},{"hanzi":"耳熟能详","pinyin":"ěrshúnéngxiáng","vi":"nghe quen thuộc"},{"hanzi":"名篇","pinyin":"míngpiān","vi":"tác phẩm nổi tiếng"}],"traditional":"膾炙人口"},{"id":"况且","hanzi":"况且","pinyin":"kuàngqiě","meaning_vi":"huống chi","explanation":"况 (huống) + 且 (thả – vả lại) → huống chi, vả lại; nêu thêm lý do. Ví dụ: 太晚了，况且又下雨，别去了.","hsk_level":6,"tags":["lien-tu"],"image":"➕","examples":[{"type":"basic","zh":"太晚了，况且还下着雨。","pinyin":"Tài wǎn le, kuàngqiě hái xiàzhe yǔ.","vi":"Muộn quá rồi, huống chi trời còn đang mưa."},{"type":"simple","zh":"况且他根本不知道这件事。","pinyin":"Kuàngqiě tā gēnběnbù zhīdào zhè jiàn shì.","vi":"Huống chi anh ấy hoàn toàn không biết chuyện này."},{"type":"compound","zh":"因为路太远，况且天又黑了，所以我们决定明天再去。","pinyin":"Yīnwèi lù tài yuǎn, kuàngqiě tiān yòu hēi le, suǒyǐ wǒmen juédìng míngtiān zài qù.","vi":"Vì đường quá xa, huống chi trời lại tối rồi, nên chúng tôi quyết định mai mới đi."}],"related":[{"hanzi":"何况","pinyin":"hékuàng","vi":"huống hồ"},{"hanzi":"而且","pinyin":"érqiě","vi":"hơn nữa"},{"hanzi":"再说","pinyin":"zàishuō","vi":"vả lại"},{"hanzi":"并且","pinyin":"bìngqiě","vi":"và lại"}],"traditional":"況且"},{"id":"狂风暴雨","hanzi":"狂风暴雨","pinyin":"kuángfēng-bàoyǔ","meaning_vi":"mưa to gió lớn","explanation":"狂风暴雨: gió (风) cuồng (狂) mưa (雨) dữ (暴) → mưa to gió lớn; nghĩa bóng: tình thế, cuộc đấu tranh dữ dội.","hsk_level":6,"tags":["thanh-ngu","thoi-tiet"],"image":"⛈️","examples":[{"type":"basic","zh":"昨晚狂风暴雨。","pinyin":"Zuówǎn kuángfēngbàoyǔ.","vi":"Đêm qua mưa to gió lớn."},{"type":"simple","zh":"一场狂风暴雨刮倒了路边的大树。","pinyin":"Yì cháng kuángfēngbàoyǔ guā dǎole lùbiān de dà shù.","vi":"Một trận mưa to gió lớn đã quật đổ cái cây lớn bên đường."},{"type":"compound","zh":"即使外面狂风暴雨，渔民们也要把船拴好。","pinyin":"Jíshǐ wàimiàn kuángfēngbàoyǔ, yúmínmen yě yào bǎ chuán shuān hǎo.","vi":"Dù bên ngoài mưa to gió lớn, ngư dân cũng phải buộc thuyền cho chắc."}],"related":[{"hanzi":"暴风雨","pinyin":"bàofēngyǔ","vi":"bão giông"},{"hanzi":"风和日丽","pinyin":"fēnghérìlì","vi":"trời quang mây tạnh"},{"hanzi":"倾盆大雨","pinyin":"qīngpéndàyǔ","vi":"mưa như trút nước"},{"hanzi":"狂风","pinyin":"kuángfēng","vi":"gió dữ"}],"traditional":"狂風暴雨"},{"id":"扩张","hanzi":"扩张","pinyin":"kuòzhāng","meaning_vi":"bành trướng","explanation":"扩 (khuếch – mở rộng) + 张 (trương – căng ra) → bành trướng, mở rộng (thế lực, lãnh thổ); trong y học: giãn ra. Ví dụ: 对外扩张, 血管扩张.","hsk_level":6,"tags":["dong-tu"],"image":"🌐","examples":[{"type":"basic","zh":"公司正在扩张。","pinyin":"Gōngsī zhèngzài kuòzhāng.","vi":"Công ty đang mở rộng quy mô."},{"type":"simple","zh":"这家企业计划向东南亚市场扩张。","pinyin":"Zhè jiā qǐyè jìhuà xiàng Dōngnányà shìchǎng kuòzhāng.","vi":"Doanh nghiệp này dự định bành trướng sang thị trường Đông Nam Á."},{"type":"compound","zh":"如果城市无序扩张，交通问题就会越来越严重。","pinyin":"Rúguǒ chéngshì wúxù kuòzhāng, jiāotōng wèntí jiù huì yuèláiyuè yánzhòng.","vi":"Nếu thành phố mở rộng thiếu trật tự thì vấn đề giao thông sẽ ngày càng nghiêm trọng."}],"related":[{"hanzi":"扩大","pinyin":"kuòdà","vi":"mở rộng"},{"hanzi":"扩展","pinyin":"kuòzhǎn","vi":"mở rộng"},{"hanzi":"收缩","pinyin":"shōusuō","vi":"co lại"},{"hanzi":"侵略","pinyin":"qīnlüè","vi":"xâm lược"}],"traditional":"擴張"},{"id":"宽敞","hanzi":"宽敞","pinyin":"kuānchang","meaning_vi":"rộng rãi","explanation":"宽 (khoan – rộng) + 敞 (sưởng – rộng rãi) → (nhà cửa, không gian) rộng rãi, thoáng. Ví dụ: 宽敞的客厅, 房间很宽敞.","hsk_level":6,"tags":["tinh-tu"],"image":"🏡","examples":[{"type":"basic","zh":"客厅很宽敞。","pinyin":"Kètīng hěn kuānchang.","vi":"Phòng khách rất rộng rãi."},{"type":"simple","zh":"他们搬进了一套宽敞明亮的新公寓。","pinyin":"Tāmen bān jìnle yítào kuānchang míngliàng de xīn gōngyù.","vi":"Họ đã chuyển vào một căn hộ mới rộng rãi sáng sủa."},{"type":"compound","zh":"这辆新车不但座位宽敞，而且非常省油。","pinyin":"Zhè liàng xīnchē búdàn zuòwèi kuānchang, érqiě fēicháng shěng yóu.","vi":"Chiếc xe mới này không những ghế ngồi rộng rãi mà còn rất tiết kiệm xăng."}],"related":[{"hanzi":"宽阔","pinyin":"kuānkuò","vi":"rộng rãi"},{"hanzi":"宽大","pinyin":"kuāndà","vi":"rộng lớn"},{"hanzi":"狭窄","pinyin":"xiázhǎi","vi":"chật hẹp"},{"hanzi":"明亮","pinyin":"míngliàng","vi":"sáng sủa"}],"traditional":"寬敞"},{"id":"宽宏大量","hanzi":"宽宏大量","pinyin":"kuānhóng-dàliàng","meaning_vi":"khoan hồng độ lượng","explanation":"宽宏大量: rộng (宽) lớn (宏), độ lượng (大量) → khoan dung độ lượng, không chấp nhặt lỗi người khác.","hsk_level":6,"tags":["thanh-ngu"],"image":"🤗","examples":[{"type":"basic","zh":"他为人宽宏大量。","pinyin":"Tā wéirén kuānhóngdàliàng.","vi":"Anh ấy là người khoan hồng độ lượng."},{"type":"simple","zh":"老板宽宏大量地原谅了那个新员工。","pinyin":"Lǎobǎn kuānhóngdàliàng de yuánliàngle nà gè xīn yuángōng.","vi":"Ông chủ độ lượng tha thứ cho nhân viên mới đó."},{"type":"compound","zh":"虽然邻居弄坏了他的车，但是他宽宏大量，没有追究。","pinyin":"Suīrán línjū nòng huàile tā de chē, dànshì tā kuānhóngdàliàng, méiyǒu zhuījiū.","vi":"Tuy hàng xóm làm hỏng xe của anh ấy nhưng anh ấy độ lượng, không truy cứu."}],"related":[{"hanzi":"宽容","pinyin":"kuānróng","vi":"khoan dung"},{"hanzi":"大度","pinyin":"dàdù","vi":"độ lượng"},{"hanzi":"心胸狭窄","pinyin":"xīnxiōngxiázhǎi","vi":"bụng dạ hẹp hòi"},{"hanzi":"斤斤计较","pinyin":"jīnjīnjìjiào","vi":"so đo tính toán"}],"traditional":"寬宏大量"},{"id":"款式","hanzi":"款式","pinyin":"kuǎnshì","meaning_vi":"kiểu dáng","explanation":"款 (khoản – kiểu) + 式 (thức – kiểu mẫu) → kiểu dáng, mẫu mã (quần áo, đồ dùng). Ví dụ: 款式新颖, 最新款式.","hsk_level":6,"tags":["danh-tu"],"image":"👗","examples":[{"type":"basic","zh":"这个款式很新颖。","pinyin":"Zhè gè kuǎnshì hěn xīnyǐng.","vi":"Kiểu dáng này rất mới lạ."},{"type":"simple","zh":"她挑了一件款式简单的黑色连衣裙。","pinyin":"Tā tiāole yí jiàn kuǎnshì jiǎndān de hēisè liányīqún.","vi":"Cô ấy chọn một chiếc váy liền màu đen kiểu dáng đơn giản."},{"type":"compound","zh":"与其买款式时髦的衣服，不如买质量好的。","pinyin":"Yǔqí mǎi kuǎnshì shímáo de yīfu, bùrú mǎi zhìliàng hǎo de.","vi":"Thay vì mua quần áo kiểu dáng thời thượng, chẳng thà mua đồ chất lượng tốt."}],"related":[{"hanzi":"样式","pinyin":"yàngshì","vi":"kiểu dáng"},{"hanzi":"式样","pinyin":"shìyàng","vi":"mẫu mã"},{"hanzi":"新款","pinyin":"xīnkuǎn","vi":"mẫu mới"},{"hanzi":"时尚","pinyin":"shíshàng","vi":"thời trang"}]},{"id":"看待","hanzi":"看待","pinyin":"kàndài","meaning_vi":"nhìn nhận","explanation":"看 (khán – nhìn) + 待 (đãi – đối đãi) → nhìn nhận, đánh giá, đối xử. Ví dụ: 怎么看待这个问题, 把他当朋友看待.","hsk_level":6,"tags":["dong-tu"],"image":"👀","examples":[{"type":"basic","zh":"你怎么看待这件事？","pinyin":"Nǐ zěnme kàndài zhè jiàn shì?","vi":"Bạn nhìn nhận chuyện này thế nào?"},{"type":"simple","zh":"我们应该用发展的眼光看待问题。","pinyin":"Wǒmen yīnggāi yòng fāzhǎn de yǎnguāng kàndài wèntí.","vi":"Chúng ta nên nhìn nhận vấn đề bằng con mắt phát triển."},{"type":"compound","zh":"只要换个角度看待失败，你就会发现它也有价值。","pinyin":"Zhǐyào huàn ge jiǎodù kàndài shībài, nǐ jiù huì fāxiàn tā yě yǒujiàzhí.","vi":"Chỉ cần nhìn nhận thất bại từ một góc độ khác, bạn sẽ thấy nó cũng có giá trị."}],"related":[{"hanzi":"对待","pinyin":"duìdài","vi":"đối xử"},{"hanzi":"看法","pinyin":"kànfǎ","vi":"quan điểm"},{"hanzi":"视为","pinyin":"shìwéi","vi":"coi là"},{"hanzi":"另眼看待","pinyin":"lìngyǎnkàndài","vi":"nhìn bằng con mắt khác"}]},{"id":"抗议","hanzi":"抗议","pinyin":"kàngyì","meaning_vi":"kháng nghị","explanation":"抗 (kháng – chống) + 议 (nghị – bàn) → phản đối, kháng nghị. Ví dụ: 提出抗议, 抗议活动, 强烈抗议.","hsk_level":6,"tags":["dong-tu"],"image":"✊","examples":[{"type":"basic","zh":"工人们提出抗议。","pinyin":"Gōngrénmen tíchū kàngyì.","vi":"Công nhân đưa ra lời phản đối."},{"type":"simple","zh":"居民们抗议在小区旁边建垃圾站。","pinyin":"Jūmínmen kàngyì zài xiǎoqū pángbiān jiàn lājī zhàn.","vi":"Cư dân phản đối việc xây trạm rác cạnh khu dân cư."},{"type":"compound","zh":"因为票价突然上涨，所以球迷们在球场门口抗议。","pinyin":"Yīnwèi piàojià tūrán shàngzhǎng, suǒyǐ qiúmímen zài qiúchǎng ménkǒu kàngyì.","vi":"Vì giá vé đột ngột tăng nên người hâm mộ kéo đến cổng sân vận động phản đối."}],"related":[{"hanzi":"反对","pinyin":"fǎnduì","vi":"phản đối"},{"hanzi":"示威","pinyin":"shìwēi","vi":"biểu tình"},{"hanzi":"抗议活动","pinyin":"kàngyìhuódòng","vi":"hoạt động phản đối"},{"hanzi":"支持","pinyin":"zhīchí","vi":"ủng hộ"}],"traditional":"抗議"},{"id":"刻不容缓","hanzi":"刻不容缓","pinyin":"kèbù-rónghuǎn","meaning_vi":"cấp bách không thể chậm trễ","explanation":"刻不容缓: một khắc (刻) cũng không cho phép (不容) chậm (缓) → vô cùng cấp bách, phải làm ngay.","hsk_level":6,"tags":["thanh-ngu"],"image":"🚨","examples":[{"type":"basic","zh":"救人刻不容缓！","pinyin":"Jiùrén kèbùrónghuǎn!","vi":"Cứu người là việc cấp bách không thể chậm trễ!"},{"type":"simple","zh":"治理河流污染已经刻不容缓了。","pinyin":"Zhìlǐ héliú wūrǎn yǐjīng kèbùrónghuǎn le.","vi":"Xử lý ô nhiễm sông ngòi đã là việc cấp bách không thể trì hoãn."},{"type":"compound","zh":"既然病人情况危急，手术就刻不容缓。","pinyin":"Jìrán bìngrén qíngkuàng wēijí, shǒushù jiù kèbùrónghuǎn.","vi":"Vì tình trạng bệnh nhân nguy kịch nên ca phẫu thuật không thể chậm trễ."}],"related":[{"hanzi":"迫在眉睫","pinyin":"pòzàiméijié","vi":"cấp bách trước mắt"},{"hanzi":"燃眉之急","pinyin":"ránméizhījí","vi":"việc cấp bách"},{"hanzi":"紧急","pinyin":"jǐnjí","vi":"khẩn cấp"},{"hanzi":"从长计议","pinyin":"cóngchángjìyì","vi":"bàn bạc lâu dài"}],"traditional":"刻不容緩"},{"id":"刻骨铭心","hanzi":"刻骨铭心","pinyin":"kègǔ-míngxīn","meaning_vi":"khắc cốt ghi tâm (nhớ mãi không quên)","explanation":"刻骨铭心: khắc (刻) vào xương (骨), ghi (铭) vào tim (心) → nhớ mãi không quên (ơn nghĩa, tình cảm, nỗi đau).","hsk_level":6,"tags":["thanh-ngu","cam-xuc"],"image":"❤️","examples":[{"type":"basic","zh":"那段爱情刻骨铭心。","pinyin":"Nà duàn àiqíng kègǔmíngxīn.","vi":"Mối tình ấy khắc cốt ghi tâm."},{"type":"simple","zh":"第一次登上雪山的经历让我刻骨铭心。","pinyin":"Dìyīcì dēngshàng xuěshān de jīnglì ràng wǒ kègǔmíngxīn.","vi":"Trải nghiệm lần đầu leo lên núi tuyết khiến tôi nhớ mãi không quên."},{"type":"compound","zh":"虽然地震已经过去十年了，但是那种恐惧仍然刻骨铭心。","pinyin":"Suīrán dìzhèn yǐjīng guòqù shí nián le, dànshì nà zhǒng kǒngjù réngrán kègǔmíngxīn.","vi":"Tuy trận động đất đã qua mười năm nhưng nỗi sợ hãi ấy vẫn khắc sâu trong lòng."}],"related":[{"hanzi":"铭记","pinyin":"míngjì","vi":"ghi nhớ"},{"hanzi":"记忆犹新","pinyin":"jìyìyóuxīn","vi":"ký ức còn mới"},{"hanzi":"念念不忘","pinyin":"niànniànbúwàng","vi":"nhớ mãi không quên"},{"hanzi":"难忘","pinyin":"nánwàng","vi":"khó quên"}],"traditional":"刻骨銘心"},{"id":"刻舟求剑","hanzi":"刻舟求剑","pinyin":"kèzhōu-qiújiàn","meaning_vi":"khắc thuyền tìm gươm (bảo thủ, máy móc, không biết biến thông)","explanation":"刻舟求剑: khắc dấu lên thuyền để tìm gươm rơi xuống sông (truyện nước Sở) → ví người cứng nhắc, không biết thay đổi theo hoàn cảnh.","hsk_level":6,"tags":["thanh-ngu"],"image":"🚤","examples":[{"type":"basic","zh":"这是刻舟求剑。","pinyin":"Zhè shì kèzhōuqiújiàn.","vi":"Đây đúng là khắc thuyền tìm gươm."},{"type":"simple","zh":"用十年前的老办法管理公司无异于刻舟求剑。","pinyin":"Yòng shí niánqián de lǎo bànfǎ guǎnlǐ gōngsī wúyì yú kèzhōuqiújiàn.","vi":"Dùng cách cũ từ mười năm trước để quản lý công ty chẳng khác gì khắc thuyền tìm gươm."},{"type":"compound","zh":"市场变化这么快，如果还刻舟求剑，就一定会被淘汰。","pinyin":"Shìchǎng biànhuà zhème kuài, rúguǒ hái kèzhōuqiújiàn, jiù yídìng huì bèi táotài.","vi":"Thị trường thay đổi nhanh như vậy, nếu vẫn cứng nhắc như khắc thuyền tìm gươm thì nhất định sẽ bị đào thải."}],"related":[{"hanzi":"守株待兔","pinyin":"shǒuzhūdàitù","vi":"ôm cây đợi thỏ"},{"hanzi":"墨守成规","pinyin":"mòshǒuchéngguī","vi":"khư khư nếp cũ"},{"hanzi":"随机应变","pinyin":"suíjīyìngbiàn","vi":"tùy cơ ứng biến"},{"hanzi":"死板","pinyin":"sǐbǎn","vi":"cứng nhắc"}],"traditional":"刻舟求劍"},{"id":"空白","hanzi":"空白","pinyin":"kòngbái","meaning_vi":"chỗ trống","explanation":"空 (không – trống) + 白 (bạch – trắng) → chỗ trống, khoảng trắng; lĩnh vực còn bỏ ngỏ. Ví dụ: 填补空白, 一片空白. Lưu ý 空 đọc kòng.","hsk_level":6,"tags":["danh-tu"],"image":"📄","examples":[{"type":"basic","zh":"这里请留空白。","pinyin":"Zhèlǐ qǐng liú kòngbái.","vi":"Chỗ này xin để trống."},{"type":"simple","zh":"请在试卷的空白处写上你的名字。","pinyin":"Qǐng zài shìjuàn de kòngbái chù xiě shàng nǐ de míngzi.","vi":"Hãy viết tên của bạn vào chỗ trống trên bài thi."},{"type":"compound","zh":"这项研究不但填补了国内空白，而且获得了国际大奖。","pinyin":"Zhè xiàng yánjiū búdàn tiánbǔle guónèi kòngbái, érqiě huòdéle Guójì dàjiǎng.","vi":"Nghiên cứu này không những lấp đầy khoảng trống trong nước mà còn giành giải thưởng quốc tế."}],"related":[{"hanzi":"空格","pinyin":"kònggé","vi":"ô trống"},{"hanzi":"空缺","pinyin":"kòngquē","vi":"chỗ khuyết"},{"hanzi":"填补空白","pinyin":"tiánbǔkòngbái","vi":"lấp chỗ trống"},{"hanzi":"一片空白","pinyin":"yípiànkòngbái","vi":"trống rỗng"}]},{"id":"开朗","hanzi":"开朗","pinyin":"kāilǎng","meaning_vi":"cởi mở","explanation":"开 (khai – mở) + 朗 (lãng – sáng sủa) → (tính cách) cởi mở, vui vẻ, lạc quan; (không gian) rộng sáng. Ví dụ: 性格开朗.","hsk_level":6,"tags":["tinh-tu"],"image":"😄","examples":[{"type":"basic","zh":"她性格很开朗。","pinyin":"Tā xìnggé hěn kāilǎng.","vi":"Tính cách cô ấy rất cởi mở."},{"type":"simple","zh":"新来的同事是个开朗爱笑的小伙子。","pinyin":"Xīn lái de tóngshì shì ge kāilǎng ài xiào de xiǎohuǒzi.","vi":"Đồng nghiệp mới là một chàng trai cởi mở hay cười."},{"type":"compound","zh":"自从参加了合唱团，他就变得开朗多了。","pinyin":"Zìcóng cānjiāle héchàngtuán, tā jiù biànde kāilǎng duō le.","vi":"Từ khi tham gia dàn hợp xướng, cậu ấy đã trở nên cởi mở hơn nhiều."}],"related":[{"hanzi":"乐观","pinyin":"lèguān","vi":"lạc quan"},{"hanzi":"活泼","pinyin":"huópō","vi":"hoạt bát"},{"hanzi":"内向","pinyin":"nèixiàng","vi":"hướng nội"},{"hanzi":"豁然开朗","pinyin":"huòránkāilǎng","vi":"bừng sáng"}],"traditional":"開朗"},{"id":"开拓","hanzi":"开拓","pinyin":"kāituò","meaning_vi":"mở mang","explanation":"开 (khai – mở) + 拓 (thác – mở rộng) → khai phá, mở mang (thị trường, lĩnh vực mới). Ví dụ: 开拓市场, 开拓精神.","hsk_level":6,"tags":["dong-tu"],"image":"🚀","examples":[{"type":"basic","zh":"我们要开拓市场。","pinyin":"Wǒmen yào kāituò shìchǎng.","vi":"Chúng ta phải mở rộng thị trường."},{"type":"simple","zh":"这位探险家一生都在开拓新的航线。","pinyin":"Zhè wèi tànxiǎnjiā yìshēng dōu zài kāituò xīn de hángxiàn.","vi":"Nhà thám hiểm này cả đời đều khai phá những tuyến hàng hải mới."},{"type":"compound","zh":"读书不但能增长知识，而且能开拓视野。","pinyin":"Dúshū búdàn néng zēngzhǎng zhīshi, érqiě néng kāituò shìyě.","vi":"Đọc sách không những tăng thêm kiến thức mà còn mở mang tầm nhìn."}],"related":[{"hanzi":"开辟","pinyin":"kāipì","vi":"khai phá"},{"hanzi":"开发","pinyin":"kāifā","vi":"phát triển, khai thác"},{"hanzi":"开拓进取","pinyin":"kāituòjìnqǔ","vi":"khai phá tiến thủ"},{"hanzi":"拓展","pinyin":"tuòzhǎn","vi":"mở rộng"}],"traditional":"開拓"},{"id":"开源节流","hanzi":"开源节流","pinyin":"kāiyuán-jiéliú","meaning_vi":"tăng nguồn thu giảm chi tiêu","explanation":"开源节流: mở (开) thêm nguồn (源), tiết chế (节) dòng chảy (流) → tăng nguồn thu, giảm chi tiêu (trong tài chính, kinh doanh).","hsk_level":6,"tags":["thanh-ngu","tien-te"],"image":"💰","examples":[{"type":"basic","zh":"理财要开源节流。","pinyin":"Lǐcái yào kāiyuánjiéliú.","vi":"Quản lý tài chính cần tăng thu giảm chi."},{"type":"simple","zh":"公司通过开源节流度过了经济危机。","pinyin":"Gōngsī tōngguò kāiyuánjiéliú dùguòle jīngjì wēijī.","vi":"Công ty đã vượt qua khủng hoảng kinh tế nhờ tăng thu giảm chi."},{"type":"compound","zh":"只要我们坚持开源节流，年底就能还清贷款。","pinyin":"Zhǐyào wǒmen jiānchí kāiyuánjiéliú, niándǐ jiù néng huán qīng dàikuǎn.","vi":"Chỉ cần chúng ta kiên trì tăng thu giảm chi thì cuối năm sẽ trả hết khoản vay."}],"related":[{"hanzi":"节约","pinyin":"jiéyuē","vi":"tiết kiệm"},{"hanzi":"增收节支","pinyin":"zēngshōujiézhī","vi":"tăng thu giảm chi"},{"hanzi":"开支","pinyin":"kāizhī","vi":"chi tiêu"},{"hanzi":"收入","pinyin":"shōurù","vi":"thu nhập"}],"traditional":"開源節流"},{"id":"刊登","hanzi":"刊登","pinyin":"kāndēng","meaning_vi":"đăng tải","explanation":"刊 (san – in, đăng) + 登 (đăng – đăng) → đăng trên báo, tạp chí. Ví dụ: 刊登广告, 刊登文章.","hsk_level":6,"tags":["dong-tu"],"image":"📰","examples":[{"type":"basic","zh":"报纸刊登了这条新闻。","pinyin":"Bàozhǐ kāndēngle zhè tiáo xīnwén.","vi":"Báo đã đăng tin này."},{"type":"simple","zh":"他的第一篇小说刊登在校报上。","pinyin":"Tā de dìyī piān xiǎoshuō kāndēng zài xiào bàoshàng.","vi":"Truyện ngắn đầu tiên của anh ấy được đăng trên báo trường."},{"type":"compound","zh":"如果杂志刊登了你的文章，就会给你寄稿费。","pinyin":"Rúguǒ zázhì kāndēngle nǐ de wénzhāng, jiù huì gěi nǐ jì gǎofèi.","vi":"Nếu tạp chí đăng bài của bạn thì sẽ gửi nhuận bút cho bạn."}],"related":[{"hanzi":"登载","pinyin":"dēngzǎi","vi":"đăng tải"},{"hanzi":"发表","pinyin":"fābiǎo","vi":"công bố"},{"hanzi":"报刊","pinyin":"bàokān","vi":"báo chí"},{"hanzi":"刊物","pinyin":"kānwù","vi":"tạp chí, ấn phẩm"}]},{"id":"慷慨解囊","hanzi":"慷慨解囊","pinyin":"kāngkǎi-jiěnáng","meaning_vi":"hào phóng quyên góp tiền bạc giúp đỡ","explanation":"慷慨解囊: hào phóng (慷慨) mở (解) túi tiền (囊) → rộng rãi bỏ tiền giúp đỡ người khác, quyên góp.","hsk_level":6,"tags":["thanh-ngu"],"image":"🎁","examples":[{"type":"basic","zh":"校友们慷慨解囊。","pinyin":"Xiàoyǒumen kāngkǎijiěnáng.","vi":"Các cựu học sinh hào phóng quyên góp."},{"type":"simple","zh":"许多市民为受灾的山区慷慨解囊。","pinyin":"Xǔduō shìmín wèi shòuzāi de shānqū kāngkǎijiěnáng.","vi":"Nhiều người dân hào phóng quyên góp cho vùng núi bị thiên tai."},{"type":"compound","zh":"一听说小明得了重病，同学们就纷纷慷慨解囊。","pinyin":"Yì tīngshuō xiǎo míng déle zhòngbìng, tóngxuémen jiù fēnfēn kāngkǎijiěnáng.","vi":"Vừa nghe tin Tiểu Minh mắc bệnh nặng, các bạn cùng lớp liền lần lượt hào phóng góp tiền giúp đỡ."}],"related":[{"hanzi":"捐款","pinyin":"juānkuǎn","vi":"quyên góp tiền"},{"hanzi":"慷慨","pinyin":"kāngkǎi","vi":"hào phóng"},{"hanzi":"乐善好施","pinyin":"lèshànhàoshī","vi":"thích làm việc thiện"},{"hanzi":"一毛不拔","pinyin":"yìmáobùbá","vi":"keo kiệt vắt cổ chày ra nước"}]},{"id":"可观","hanzi":"可观","pinyin":"kěguān","meaning_vi":"đáng kể","explanation":"可 (khả – đáng) + 观 (quan – xem) → đáng xem; (số lượng) đáng kể, khá lớn. Ví dụ: 收入可观, 数目可观.","hsk_level":6,"tags":["tinh-tu"],"image":"📈","examples":[{"type":"basic","zh":"收入相当可观。","pinyin":"Shōurù xiāngdāng kěguān.","vi":"Thu nhập khá đáng kể."},{"type":"simple","zh":"这家小餐馆每月的利润十分可观。","pinyin":"Zhè jiā xiǎo cānguǎn měiyuè de lìrùn shífēn kěguān.","vi":"Lợi nhuận hằng tháng của quán ăn nhỏ này rất đáng kể."},{"type":"compound","zh":"虽然每天只存十块钱，但是十年后也是一笔可观的数目。","pinyin":"Suīrán měitiān zhǐ cún shí kuài qián, dànshì shí nián hòu yě shì yì bǐ kěguān de shùmù.","vi":"Tuy mỗi ngày chỉ tiết kiệm mười tệ nhưng mười năm sau cũng là một con số đáng kể."}],"related":[{"hanzi":"不少","pinyin":"bùshǎo","vi":"không ít"},{"hanzi":"相当","pinyin":"xiāngdāng","vi":"khá, tương đối"},{"hanzi":"可观的收入","pinyin":"kěguān de shōurù","vi":"thu nhập đáng kể"},{"hanzi":"微不足道","pinyin":"wēibùzúdào","vi":"không đáng kể"}],"traditional":"可觀"},{"id":"可歌可泣","hanzi":"可歌可泣","pinyin":"kěgē-kěqì","meaning_vi":"đáng ca ngợi đáng cảm động (anh dũng)","explanation":"可歌可泣: đáng (可) ca ngợi (歌), đáng khóc (泣) vì cảm động → hành động anh dũng bi tráng khiến người ta xúc động.","hsk_level":6,"tags":["thanh-ngu"],"image":"🎖️","examples":[{"type":"basic","zh":"这是可歌可泣的故事。","pinyin":"Zhè shì kěgēkěqì de gùshi.","vi":"Đây là câu chuyện bi tráng đáng ca ngợi."},{"type":"simple","zh":"消防员救火的事迹真是可歌可泣。","pinyin":"Xiāofángyuán jiùhuǒ de shìjì zhēn shì kěgēkěqì.","vi":"Chiến công chữa cháy của lính cứu hỏa thật đáng ca ngợi và cảm động."},{"type":"compound","zh":"虽然战争已经结束多年，但是那些可歌可泣的英雄仍被人们怀念。","pinyin":"Suīrán zhànzhēng yǐjīng jiéshù duōnián, dànshì nàxiē kěgēkěqì de yīngxióng réng bèi rénmen huáiniàn.","vi":"Tuy chiến tranh đã kết thúc nhiều năm nhưng những người anh hùng bi tráng ấy vẫn được mọi người tưởng nhớ."}],"related":[{"hanzi":"感人肺腑","pinyin":"gǎnrénfèifǔ","vi":"cảm động tận đáy lòng"},{"hanzi":"惊天地泣鬼神","pinyin":"jīng tiāndì qì guǐshén","vi":"kinh thiên động địa"},{"hanzi":"英勇","pinyin":"yīngyǒng","vi":"anh dũng"},{"hanzi":"悲壮","pinyin":"bēizhuàng","vi":"bi tráng"}]},{"id":"可想而知","hanzi":"可想而知","pinyin":"kěxiǎng-érzhī","meaning_vi":"có thể tưởng tượng ra được, đương nhiên là vậy","explanation":"可想而知: có thể (可) nghĩ (想) mà biết (知) → không cần nói cũng có thể đoán ra. Ví dụ: 结果可想而知.","hsk_level":6,"tags":["thanh-ngu"],"image":"💡","examples":[{"type":"basic","zh":"结果可想而知。","pinyin":"Jiéguǒ kěxiǎng'érzhī.","vi":"Kết quả thì có thể đoán được."},{"type":"simple","zh":"第一次上台的紧张心情可想而知。","pinyin":"Dìyīcì shàngtái de jǐnzhāng xīnqíng kěxiǎng'érzhī.","vi":"Tâm trạng hồi hộp lần đầu lên sân khấu thì có thể tưởng tượng được."},{"type":"compound","zh":"他平时从不复习，所以考试成绩可想而知。","pinyin":"Tā píngshí cóng bú fùxí, suǒyǐ kǎoshì chéngjì kěxiǎng'érzhī.","vi":"Bình thường cậu ấy chẳng bao giờ ôn bài, nên điểm thi thế nào thì ai cũng đoán được."}],"related":[{"hanzi":"不言而喻","pinyin":"bùyán'éryù","vi":"không nói cũng hiểu"},{"hanzi":"显而易见","pinyin":"xiǎn'éryìjiàn","vi":"hiển nhiên"},{"hanzi":"想象","pinyin":"xiǎngxiàng","vi":"tưởng tượng"},{"hanzi":"难以想象","pinyin":"nányǐxiǎngxiàng","vi":"khó tưởng tượng"}]},{"id":"可行","hanzi":"可行","pinyin":"kěxíng","meaning_vi":"khả thi","explanation":"可 (khả – có thể) + 行 (hành – làm) → khả thi, làm được. Ví dụ: 可行性研究, 这个办法可行.","hsk_level":6,"tags":["tinh-tu"],"image":"✅","examples":[{"type":"basic","zh":"这个方案可行。","pinyin":"Zhè gè fāng'àn kěxíng.","vi":"Phương án này khả thi."},{"type":"simple","zh":"专家们正在讨论这个计划是否可行。","pinyin":"Zhuānjiāmen zhèngzài tǎolùn zhè gè jìhuà shìfǒu kěxíng.","vi":"Các chuyên gia đang thảo luận kế hoạch này có khả thi hay không."},{"type":"compound","zh":"只要成本不太高，这个办法就完全可行。","pinyin":"Zhǐyào chéngběn bú tài gāo, zhè gè bànfǎ jiù wánquán kěxíng.","vi":"Chỉ cần chi phí không quá cao thì cách này hoàn toàn khả thi."}],"related":[{"hanzi":"可行性","pinyin":"kěxíngxìng","vi":"tính khả thi"},{"hanzi":"行得通","pinyin":"xíngdetōng","vi":"làm được"},{"hanzi":"不可行","pinyin":"bùkěxíng","vi":"không khả thi"},{"hanzi":"切实可行","pinyin":"qièshíkěxíng","vi":"thiết thực khả thi"}]},{"id":"恳切","hanzi":"恳切","pinyin":"kěnqiè","meaning_vi":"khẩn thiết","explanation":"恳 (khẩn – thành khẩn) + 切 (thiết – thiết tha) → khẩn thiết, chân thành tha thiết. Ví dụ: 恳切的希望, 言辞恳切.","hsk_level":6,"tags":["tinh-tu"],"image":"🙏","examples":[{"type":"basic","zh":"他的语气很恳切。","pinyin":"Tā de yǔqì hěn kěnqiè.","vi":"Giọng điệu của anh ấy rất khẩn thiết."},{"type":"simple","zh":"母亲在信里恳切地劝我早点回家。","pinyin":"Mǔqīn zài xìn lǐ kěnqiè de quàn wǒ zǎodiǎn huíjiā.","vi":"Trong thư, mẹ khẩn thiết khuyên tôi sớm về nhà."},{"type":"compound","zh":"因为他的道歉非常恳切，所以大家都原谅了他。","pinyin":"Yīnwèi tā de dàoqiàn fēicháng kěnqiè, suǒyǐ dàjiā dōu yuánliàngle tā.","vi":"Vì lời xin lỗi của anh ấy rất chân thành khẩn thiết nên mọi người đều tha thứ cho anh."}],"related":[{"hanzi":"诚恳","pinyin":"chéngkěn","vi":"thành khẩn"},{"hanzi":"恳求","pinyin":"kěnqiú","vi":"khẩn cầu"},{"hanzi":"真诚","pinyin":"zhēnchéng","vi":"chân thành"},{"hanzi":"敷衍","pinyin":"fūyǎn","vi":"qua loa"}],"traditional":"懇切"},{"id":"空前绝后","hanzi":"空前绝后","pinyin":"kōngqián-juéhòu","meaning_vi":"vô tiền khoáng hậu","explanation":"空前绝后: trước (前) chưa từng có (空), sau (后) cũng không còn (绝) → vô tiền khoáng hậu, độc nhất vô nhị; đôi khi dùng phóng đại.","hsk_level":6,"tags":["thanh-ngu"],"image":"🌟","examples":[{"type":"basic","zh":"场面空前绝后。","pinyin":"Chǎngmiàn kōngqiánjuéhòu.","vi":"Khung cảnh vô tiền khoáng hậu."},{"type":"simple","zh":"那场音乐会的盛况可以说是空前绝后。","pinyin":"Nà chǎng yīnyuèhuì de shèngkuàng kěyǐ shuō shì kōngqiánjuéhòu.","vi":"Quang cảnh huy hoàng của buổi hòa nhạc đó có thể nói là vô tiền khoáng hậu."},{"type":"compound","zh":"虽然他的成就很大，但是说他空前绝后未免太夸张了。","pinyin":"Suīrán tā de chéngjiù hěn dà, dànshì shuō tā kōngqiánjuéhòu wèimiǎn tài kuāzhāng le.","vi":"Tuy thành tựu của ông ấy rất lớn nhưng nói ông vô tiền khoáng hậu thì có phần quá phóng đại."}],"related":[{"hanzi":"前所未有","pinyin":"qiánsuǒwèiyǒu","vi":"chưa từng có"},{"hanzi":"史无前例","pinyin":"shǐwúqiánlì","vi":"chưa có tiền lệ"},{"hanzi":"独一无二","pinyin":"dúyìwú'èr","vi":"độc nhất vô nhị"},{"hanzi":"空前","pinyin":"kōngqián","vi":"chưa từng có"}],"traditional":"空前絕後"},{"id":"空穴来风","hanzi":"空穴来风","pinyin":"kōngxué-láifēng","meaning_vi":"không có lửa làm sao có khói","explanation":"空穴来风: có hang (穴) trống mới có gió (风) lọt vào (Tống Ngọc) → tin đồn ắt có nguyên do; nay thường dùng ngược: tin đồn vô căn cứ.","hsk_level":6,"tags":["thanh-ngu"],"image":"🌬️","examples":[{"type":"basic","zh":"传言并非空穴来风。","pinyin":"Chuányán bìngfēi kōngxuéláifēng.","vi":"Lời đồn không phải tự nhiên mà có."},{"type":"simple","zh":"关于公司裁员的消息恐怕不是空穴来风。","pinyin":"Guānyú gōngsī cáiyuán de xiāoxi kǒngpà bú shì kōngxuéláifēng.","vi":"Tin về việc công ty cắt giảm nhân sự e rằng không phải không có cơ sở."},{"type":"compound","zh":"既然大家都这么说，这件事就不会是空穴来风。","pinyin":"Jìrán dàjiā dōu zhème shuō, zhè jiàn shì jiù bú huì shì kōngxuéláifēng.","vi":"Đã mọi người đều nói vậy thì chuyện này chắc chắn không phải tự dưng mà có."}],"related":[{"hanzi":"无风不起浪","pinyin":"wú fēng bù qǐ làng","vi":"không có gió sao có sóng"},{"hanzi":"事出有因","pinyin":"shìchūyǒuyīn","vi":"việc xảy ra có nguyên do"},{"hanzi":"谣言","pinyin":"yáoyán","vi":"tin đồn"},{"hanzi":"无中生有","pinyin":"wúzhōngshēngyǒu","vi":"bịa đặt"}],"traditional":"空穴來風"},{"id":"枯燥","hanzi":"枯燥","pinyin":"kūzào","meaning_vi":"khô khan","explanation":"枯 (khô – khô héo) + 燥 (táo – khô) → khô khan, tẻ nhạt, nhàm chán. Ví dụ: 枯燥无味, 枯燥的工作.","hsk_level":6,"tags":["tinh-tu"],"image":"😑","examples":[{"type":"basic","zh":"这本书很枯燥。","pinyin":"Zhè běn shū hěn kūzào.","vi":"Cuốn sách này rất khô khan."},{"type":"simple","zh":"他每天重复着枯燥的数据录入工作。","pinyin":"Tā měitiān chóngfùzhe kūzào de shùjù lùrù gōngzuò.","vi":"Ngày nào anh ấy cũng lặp lại công việc nhập liệu khô khan."},{"type":"compound","zh":"如果老师讲课太枯燥，学生就容易打瞌睡。","pinyin":"Rúguǒ lǎoshī jiǎngkè tài kūzào, xuésheng jiù róngyì dǎkēshuì.","vi":"Nếu thầy giáo giảng bài quá khô khan thì học sinh dễ ngủ gật."}],"related":[{"hanzi":"乏味","pinyin":"fáwèi","vi":"nhạt nhẽo"},{"hanzi":"单调","pinyin":"dāndiào","vi":"đơn điệu"},{"hanzi":"无聊","pinyin":"wúliáo","vi":"buồn chán"},{"hanzi":"有趣","pinyin":"yǒuqù","vi":"thú vị"}]},{"id":"卡通","hanzi":"卡通","pinyin":"kǎtōng","meaning_vi":"hoạt hình","explanation":"Phiên âm từ tiếng Anh \"cartoon\", 卡 + 通 chỉ dùng ghi âm → phim, tranh hoạt hình. Thường gặp: 卡通片, 卡通人物.","hsk_level":6,"tags":["danh-tu","giai-tri"],"image":"🎬","examples":[{"type":"basic","zh":"孩子爱看卡通。","pinyin":"Háizi ài kàn kǎtōng.","vi":"Trẻ con thích xem hoạt hình."},{"type":"simple","zh":"弟弟的书包上印着可爱的卡通图案。","pinyin":"Dìdi de shūbāo shàng yìnzhe kě'ài de kǎtōng tú'àn.","vi":"Trên cặp sách của em trai in hình hoạt hình dễ thương."},{"type":"compound","zh":"这部日本卡通片既有趣，又很有教育意义。","pinyin":"Zhè bù Rìběn kǎtōng piàn jì yǒuqù, yòu hěn yǒu jiàoyù yìyì.","vi":"Bộ phim hoạt hình Nhật Bản này vừa thú vị vừa rất có ý nghĩa giáo dục."}],"related":[{"hanzi":"动画片","pinyin":"dònghuàpiàn","vi":"phim hoạt hình"},{"hanzi":"漫画","pinyin":"mànhuà","vi":"truyện tranh"},{"hanzi":"动漫","pinyin":"dòngmàn","vi":"hoạt hình truyện tranh"},{"hanzi":"卡通人物","pinyin":"kǎtōngrénwù","vi":"nhân vật hoạt hình"}]},{"id":"考核","hanzi":"考核","pinyin":"kǎohé","meaning_vi":"khảo hạch","explanation":"考 (khảo – kiểm tra) + 核 (hạch – xét kỹ, đối chiếu) → kiểm tra đánh giá năng lực, thành tích. Thường dùng: 考核员工, 年终考核.","hsk_level":6,"tags":["dong-tu"],"image":"📋","examples":[{"type":"basic","zh":"月底要考核。","pinyin":"Yuèdǐ yào kǎohé.","vi":"Cuối tháng phải sát hạch."},{"type":"simple","zh":"公司每季度都会考核员工的销售业绩。","pinyin":"Gōngsī měi jìdù dōuhuì kǎohé yuángōng de xiāoshòu yèjì.","vi":"Công ty mỗi quý đều đánh giá doanh số bán hàng của nhân viên."},{"type":"compound","zh":"如果新司机考核不合格，就不能单独上路。","pinyin":"Rúguǒ xīn sījī kǎohé bù hégé, jiù bù néng dāndú shànglù.","vi":"Nếu tài xế mới không đạt kỳ sát hạch thì không được lái xe một mình."}],"related":[{"hanzi":"考试","pinyin":"kǎoshì","vi":"thi cử"},{"hanzi":"考察","pinyin":"kǎochá","vi":"khảo sát"},{"hanzi":"评估","pinyin":"pínggū","vi":"đánh giá"},{"hanzi":"绩效考核","pinyin":"jìxiàokǎohé","vi":"đánh giá hiệu suất"}]},{"id":"孔","hanzi":"孔","pinyin":"kǒng","meaning_vi":"cái lỗ","explanation":"Khổng – cái lỗ, lỗ hổng; cũng là họ Khổng (孔子). Từ thường gặp: 鼻孔 (lỗ mũi), 针孔 (lỗ kim), 毛孔 (lỗ chân lông).","hsk_level":6,"tags":["danh-tu"],"image":"🕳️","examples":[{"type":"basic","zh":"墙上有个小孔。","pinyin":"Qiáng shàng yǒu ge xiǎokǒng.","vi":"Trên tường có một cái lỗ nhỏ."},{"type":"simple","zh":"他在皮带上又打了一个孔。","pinyin":"Tā zài pídài shàng yòu dǎle yí gè kǒng.","vi":"Anh ấy đục thêm một cái lỗ trên thắt lưng."},{"type":"compound","zh":"因为水管上有个孔，所以厨房地板全湿了。","pinyin":"Yīnwèi shuǐguǎn shàng yǒu ge kǒng, suǒyǐ chúfáng dìbǎn quán shī le.","vi":"Vì ống nước bị thủng một lỗ nên sàn bếp ướt hết."}],"related":[{"hanzi":"洞","pinyin":"dòng","vi":"lỗ thủng"},{"hanzi":"小孔","pinyin":"xiǎokǒng","vi":"lỗ nhỏ"},{"hanzi":"毛孔","pinyin":"máokǒng","vi":"lỗ chân lông"},{"hanzi":"鼻孔","pinyin":"bíkǒng","vi":"lỗ mũi"}]},{"id":"口腔","hanzi":"口腔","pinyin":"kǒuqiāng","meaning_vi":"khoang miệng","explanation":"口 (khẩu – miệng) + 腔 (xoang – khoang rỗng trong cơ thể) → khoang miệng. Thường gặp: 口腔医院, 口腔卫生.","hsk_level":6,"tags":["danh-tu","co-the"],"image":"👄","examples":[{"type":"basic","zh":"注意口腔卫生。","pinyin":"Zhùyì kǒuqiāng wèishēng.","vi":"Chú ý vệ sinh răng miệng."},{"type":"simple","zh":"医生用小镜子仔细检查了我的口腔。","pinyin":"Yīshēng yòng xiǎo jìngzi zǐxì jiǎnchále wǒ de kǒuqiāng.","vi":"Bác sĩ dùng chiếc gương nhỏ kiểm tra kỹ khoang miệng của tôi."},{"type":"compound","zh":"如果口腔经常溃疡，就最好去医院看看。","pinyin":"Rúguǒ kǒuqiāng jīngcháng kuìyáng, jiù zuìhǎo qù yīyuàn kànkan.","vi":"Nếu khoang miệng thường xuyên bị loét thì tốt nhất nên đi bệnh viện khám."}],"related":[{"hanzi":"牙齿","pinyin":"yáchǐ","vi":"răng"},{"hanzi":"口腔医院","pinyin":"kǒuqiāngyīyuàn","vi":"bệnh viện răng hàm mặt"},{"hanzi":"舌头","pinyin":"shétou","vi":"lưỡi"},{"hanzi":"牙科","pinyin":"yákē","vi":"nha khoa"}]},{"id":"口是心非","hanzi":"口是心非","pinyin":"kǒushì-xīnfēi","meaning_vi":"khẩu thị tâm phi, miệng nói một đằng lòng nghĩ một nẻo","explanation":"Miệng nói \"phải\" (是) mà lòng nghĩ \"trái\" (非) → nói một đằng nghĩ một nẻo, không thật lòng. Hán-Việt: khẩu thị tâm phi.","hsk_level":6,"tags":["thanh-ngu"],"image":"🤥","examples":[{"type":"basic","zh":"他总是口是心非。","pinyin":"Tā zǒngshì kǒushìxīnfēi.","vi":"Anh ta luôn nói một đằng nghĩ một nẻo."},{"type":"simple","zh":"我最讨厌口是心非的人。","pinyin":"Wǒ zuì tǎoyàn kǒushìxīnfēi de rén.","vi":"Tôi ghét nhất những người nói một đằng nghĩ một nẻo."},{"type":"compound","zh":"虽然她嘴上说不想去，但是我知道她口是心非。","pinyin":"Suīrán tā zuǐ shàng shuō bù xiǎng qù, dànshì wǒ zhīdào tā kǒushìxīnfēi.","vi":"Tuy ngoài miệng cô ấy nói không muốn đi nhưng tôi biết cô ấy nói một đằng nghĩ một nẻo."}],"related":[{"hanzi":"表里不一","pinyin":"biǎolǐbùyī","vi":"trong ngoài bất nhất"},{"hanzi":"心口如一","pinyin":"xīnkǒurúyī","vi":"nói như nghĩ"},{"hanzi":"阳奉阴违","pinyin":"yángfèngyīnwéi","vi":"bề ngoài vâng dạ bên trong chống đối"},{"hanzi":"言行一致","pinyin":"yánxíngyízhì","vi":"lời nói đi đôi việc làm"}]},{"id":"苦口婆心","hanzi":"苦口婆心","pinyin":"kǔkǒu-póxīn","meaning_vi":"khuyên nhủ tận tình hết lời","explanation":"Miệng nói đến khổ, lòng như bà mẹ hiền → kiên nhẫn khuyên nhủ hết lời vì thiện ý. Thường: 苦口婆心地劝他.","hsk_level":6,"tags":["thanh-ngu","giao-tiep"],"image":"🗣️","examples":[{"type":"basic","zh":"爷爷总是苦口婆心。","pinyin":"Yéye zǒngshì kǔkǒupóxīn.","vi":"Ông nội lúc nào cũng hết lời khuyên răn."},{"type":"simple","zh":"班主任苦口婆心地劝他别再逃课了。","pinyin":"Bānzhǔrèn kǔkǒupóxīn de quàn tā bié zài táokè le.","vi":"Cô chủ nhiệm hết lời khuyên cậu ấy đừng trốn học nữa."},{"type":"compound","zh":"尽管医生苦口婆心，他还是不肯戒烟。","pinyin":"Jǐnguǎn yīshēng kǔkǒupóxīn, tā háishì bùkěn jièyān.","vi":"Mặc dù bác sĩ hết lời khuyên nhủ, ông ấy vẫn không chịu bỏ thuốc lá."}],"related":[{"hanzi":"语重心长","pinyin":"yǔzhòngxīncháng","vi":"lời lẽ thấm thía"},{"hanzi":"循循善诱","pinyin":"xúnxúnshànyòu","vi":"dẫn dắt từng bước"},{"hanzi":"劝说","pinyin":"quànshuō","vi":"khuyên nhủ"},{"hanzi":"良药苦口","pinyin":"liángyàokǔkǒu","vi":"thuốc đắng dã tật"}]},{"id":"捆","hanzi":"捆","pinyin":"kǔn","meaning_vi":"trói, buộc","explanation":"Khổn – trói, buộc, bó lại; còn làm lượng từ \"bó\". Thường gặp: 捆绑 (trói buộc), 一捆柴 (một bó củi).","hsk_level":6,"tags":["dong-tu"],"image":"🪢","examples":[{"type":"basic","zh":"把书捆起来。","pinyin":"Bǎ shū kǔn qǐlái.","vi":"Buộc sách lại."},{"type":"simple","zh":"农民用绳子把稻草捆成一束一束的。","pinyin":"Nóng mínyòng shéngzi bǎ dàocǎo kǔn chéng yí shù yi shù de.","vi":"Người nông dân dùng dây buộc rơm thành từng bó."},{"type":"compound","zh":"只要把行李捆紧，路上就不会掉下来。","pinyin":"Zhǐyào bǎ xíngli kǔn jǐn, lùshang jiù bú huì diào xiàlái.","vi":"Chỉ cần buộc chặt hành lý thì trên đường sẽ không bị rơi."}],"related":[{"hanzi":"绑","pinyin":"bǎng","vi":"trói"},{"hanzi":"系","pinyin":"jì","vi":"buộc"},{"hanzi":"捆绑","pinyin":"kǔnbǎng","vi":"trói buộc"},{"hanzi":"解开","pinyin":"jiěkāi","vi":"cởi ra"}]},{"id":"恋恋不舍","hanzi":"恋恋不舍","pinyin":"liànliàn-bùshě","meaning_vi":"lưu luyến không nỡ rời xa","explanation":"恋恋 (luyến luyến – quyến luyến) + 不舍 (không nỡ bỏ) → lưu luyến không nỡ rời xa người hay nơi chốn. Hay dùng khi chia tay.","hsk_level":6,"tags":["thanh-ngu","cam-xuc"],"image":"🥺","examples":[{"type":"basic","zh":"孩子们恋恋不舍。","pinyin":"Háizimen liànliànbùshě.","vi":"Bọn trẻ lưu luyến không nỡ rời."},{"type":"simple","zh":"毕业那天，同学们恋恋不舍地告别了母校。","pinyin":"Bìyè nà tiān, tóngxuémen liànliànbùshě de gàobiéle mǔxiào.","vi":"Ngày tốt nghiệp, các bạn học lưu luyến chia tay ngôi trường cũ."},{"type":"compound","zh":"虽然假期结束了，但是她对海边仍恋恋不舍。","pinyin":"Suīrán jiàqī jiéshù le, dànshì tā duì hǎibiān réng liànliànbùshě.","vi":"Tuy kỳ nghỉ đã kết thúc nhưng cô ấy vẫn lưu luyến bãi biển không nỡ rời."}],"related":[{"hanzi":"依依不舍","pinyin":"yīyībùshě","vi":"lưu luyến không rời"},{"hanzi":"难舍难分","pinyin":"nánshěnánfēn","vi":"khó chia lìa"},{"hanzi":"留恋","pinyin":"liúliàn","vi":"lưu luyến"},{"hanzi":"头也不回","pinyin":"tóuyěbùhuí","vi":"không ngoảnh lại"}],"traditional":"戀戀不捨"},{"id":"量力而行","hanzi":"量力而行","pinyin":"liànglì-érxíng","meaning_vi":"lượng sức mà làm","explanation":"量力 (lượng sức) + 而行 (mà làm) → liệu sức mình mà làm, không làm quá khả năng. Thường dùng để khuyên: 要量力而行.","hsk_level":6,"tags":["thanh-ngu"],"image":"⚖️","examples":[{"type":"basic","zh":"做事要量力而行。","pinyin":"Zuòshì yào liànglì'érxíng.","vi":"Làm việc phải lượng sức mà làm."},{"type":"simple","zh":"买房子应该根据收入量力而行。","pinyin":"Mǎi fángzi yīnggāi gēnjù shōurù liànglì'érxíng.","vi":"Mua nhà nên lượng sức dựa theo thu nhập."},{"type":"compound","zh":"跑马拉松虽然有益健康，但是一定要量力而行。","pinyin":"Pǎo mǎlāsōng suīrán yǒuyì jiànkāng, dànshì yídìngyào liànglì'érxíng.","vi":"Chạy marathon tuy có lợi cho sức khỏe nhưng nhất định phải lượng sức mình."}],"related":[{"hanzi":"力所能及","pinyin":"lìsuǒnéngjí","vi":"trong khả năng"},{"hanzi":"量入为出","pinyin":"liàngrùwéichū","vi":"liệu cơm gắp mắm"},{"hanzi":"自不量力","pinyin":"zìbúliànglì","vi":"không biết lượng sức"},{"hanzi":"尽力而为","pinyin":"jìnlì'érwéi","vi":"cố hết sức"}]},{"id":"联络","hanzi":"联络","pinyin":"liánluò","meaning_vi":"liên lạc","explanation":"联 (liên – nối) + 络 (lạc – mạng lưới, kết nối) → liên lạc, giữ liên hệ với nhau. Thường gặp: 联络方式, 保持联络, 联络感情.","hsk_level":6,"tags":["dong-tu"],"image":"📱","examples":[{"type":"basic","zh":"我们保持联络吧。","pinyin":"Wǒmen bǎochí liánluò ba.","vi":"Chúng ta giữ liên lạc nhé."},{"type":"simple","zh":"他负责联络各个赞助商。","pinyin":"Tā fùzé liánluò gègè zànzhùshāng.","vi":"Anh ấy phụ trách liên lạc với các nhà tài trợ."},{"type":"compound","zh":"一到北京的酒店，我就会马上跟你联络。","pinyin":"Yí dào Běijīng de jiǔdiàn, wǒ jiù huì mǎshàng gēn nǐ liánluò.","vi":"Vừa đến khách sạn ở Bắc Kinh, tôi sẽ liên lạc với bạn ngay."}],"related":[{"hanzi":"联系","pinyin":"liánxì","vi":"liên hệ"},{"hanzi":"联络方式","pinyin":"liánluòfāngshì","vi":"cách liên lạc"},{"hanzi":"通讯","pinyin":"tōngxùn","vi":"thông tin liên lạc"},{"hanzi":"失联","pinyin":"shīlián","vi":"mất liên lạc"}],"traditional":"聯絡"},{"id":"连锁","hanzi":"连锁","pinyin":"liánsuǒ","meaning_vi":"dây chuyền, liên hoàn; chuỗi (连锁店 = chuỗi cửa hàng)","explanation":"连 (liên – nối) + 锁 (tỏa – khóa, xích) → nối tiếp như mắt xích, dây chuyền. 连锁店 = chuỗi cửa hàng; 连锁反应 = phản ứng dây chuyền.","hsk_level":6,"tags":["tinh-tu","cong-viec"],"image":"🏪","examples":[{"type":"basic","zh":"这是一家连锁店。","pinyin":"Zhè shì yìjiā liánsuǒdiàn.","vi":"Đây là một cửa hàng thuộc chuỗi."},{"type":"simple","zh":"这个咖啡品牌在全国有三百多家连锁门店。","pinyin":"Zhè gè kāfēi pǐnpái zài quán guóyǒu sān bǎi duō jiā liánsuǒ méndiàn.","vi":"Thương hiệu cà phê này có hơn ba trăm cửa hàng chuỗi trên toàn quốc."},{"type":"compound","zh":"如果一家大银行倒闭，就可能引发一系列连锁反应。","pinyin":"Rúguǒ yìjiā dà yínháng dǎobì, jiù kěnéng yǐnfā yíxìliè liánsuǒ fǎnyìng.","vi":"Nếu một ngân hàng lớn sụp đổ thì có thể gây ra một loạt phản ứng dây chuyền."}],"related":[{"hanzi":"连锁店","pinyin":"liánsuǒdiàn","vi":"chuỗi cửa hàng"},{"hanzi":"连锁反应","pinyin":"liánsuǒfǎnyìng","vi":"phản ứng dây chuyền"},{"hanzi":"加盟","pinyin":"jiāméng","vi":"nhượng quyền"},{"hanzi":"分店","pinyin":"fēndiàn","vi":"chi nhánh"}],"traditional":"連鎖"},{"id":"良师益友","hanzi":"良师益友","pinyin":"liángshī-yìyǒu","meaning_vi":"người thầy tốt và người bạn hữu ích","explanation":"良师 (thầy giỏi) + 益友 (bạn có ích) → người vừa là thầy tốt vừa là bạn tốt, giúp mình tiến bộ. Hay dùng khen người dẫn dắt hoặc sách hay.","hsk_level":6,"tags":["thanh-ngu","hoc-tap"],"image":"🧑‍🏫","examples":[{"type":"basic","zh":"他是我的良师益友。","pinyin":"Tā shì wǒ de liángshīyìyǒu.","vi":"Ông ấy là thầy tốt bạn hiền của tôi."},{"type":"simple","zh":"好书是我们成长路上的良师益友。","pinyin":"Hǎo shū shì wǒmen chéngzhǎng lùshàng de liángshīyìyǒu.","vi":"Sách hay là thầy tốt bạn hiền trên con đường trưởng thành của chúng ta."},{"type":"compound","zh":"王教授既教我知识，又关心我的生活，真是我的良师益友。","pinyin":"Wáng jiàoshòu jì jiāo wǒ zhīshi, yòu guānxīn wǒ de shēnghuó, zhēn shì wǒ de liángshīyìyǒu.","vi":"Giáo sư Vương vừa dạy tôi kiến thức vừa quan tâm đến cuộc sống của tôi, thật là thầy tốt bạn hiền của tôi."}],"related":[{"hanzi":"良师","pinyin":"liángshī","vi":"thầy giỏi"},{"hanzi":"益友","pinyin":"yìyǒu","vi":"bạn tốt"},{"hanzi":"知己","pinyin":"zhījǐ","vi":"tri kỷ"},{"hanzi":"导师","pinyin":"dǎoshī","vi":"người hướng dẫn"}],"traditional":"良師益友"},{"id":"良心","hanzi":"良心","pinyin":"liángxīn","meaning_vi":"lương tâm","explanation":"良 (lương – tốt lành) + 心 (tâm – lòng) → lương tâm, ý thức phân biệt đúng sai. Thường gặp: 有良心, 没良心, 良心不安.","hsk_level":6,"tags":["danh-tu"],"image":"💖","examples":[{"type":"basic","zh":"做人要讲良心。","pinyin":"Zuòrén yào jiǎng liángxīn.","vi":"Làm người phải có lương tâm."},{"type":"simple","zh":"他昧着良心卖了一批假药。","pinyin":"Tā mèizhe liángxīn màile yìpī jiǎyào.","vi":"Hắn đã bán một lô thuốc giả trái với lương tâm."},{"type":"compound","zh":"即使没有人看见，我们也不能做违背良心的事。","pinyin":"Jíshǐ méiyǒu rén kànjiàn, wǒmen yě bù néng zuò wéibèi liángxīn de shì.","vi":"Dù không ai nhìn thấy, chúng ta cũng không được làm việc trái lương tâm."}],"related":[{"hanzi":"良知","pinyin":"liángzhī","vi":"lương tri"},{"hanzi":"道德","pinyin":"dàodé","vi":"đạo đức"},{"hanzi":"昧良心","pinyin":"mèiliángxīn","vi":"trái lương tâm"},{"hanzi":"内疚","pinyin":"nèijiù","vi":"áy náy"}]},{"id":"聊胜于无","hanzi":"聊胜于无","pinyin":"liáoshèng-yúwú","meaning_vi":"có còn hơn không","explanation":"聊 (liêu – tạm, chút ít) + 胜于无 (hơn là không có) → tuy ít ỏi nhưng vẫn còn hơn không. Dùng khi đành chấp nhận cái chưa đủ.","hsk_level":6,"tags":["thanh-ngu"],"image":"🤷","examples":[{"type":"basic","zh":"这点钱聊胜于无。","pinyin":"Zhè diǎn qián liáoshèngyúwú.","vi":"Chút tiền này có còn hơn không."},{"type":"simple","zh":"一把小扇子在闷热的车厢里也算聊胜于无。","pinyin":"Yì bǎ xiǎo shànzi zài mēnrè de chēxiāng lǐ yě suàn liáoshèngyúwú.","vi":"Một chiếc quạt nhỏ trong toa xe oi bức cũng xem như có còn hơn không."},{"type":"compound","zh":"虽然奖金只有两百块，但是聊胜于无嘛。","pinyin":"Suīrán jiǎngjīn zhǐyǒu liǎng bǎi kuài, dànshì liáoshèngyúwú ma.","vi":"Tuy tiền thưởng chỉ có hai trăm tệ nhưng có còn hơn không mà."}],"related":[{"hanzi":"有总比没有好","pinyin":"yǒu zǒng bǐ méiyǒu hǎo","vi":"có còn hơn không"},{"hanzi":"聊以自慰","pinyin":"liáoyǐzìwèi","vi":"tự an ủi"},{"hanzi":"勉强","pinyin":"miǎnqiǎng","vi":"miễn cưỡng"},{"hanzi":"不足","pinyin":"bùzú","vi":"không đủ"}],"traditional":"聊勝於無"},{"id":"列举","hanzi":"列举","pinyin":"lièjǔ","meaning_vi":"liệt kê","explanation":"列 (liệt – xếp thành hàng) + 举 (cử – nêu ra) → liệt kê, nêu ra từng cái một. Thường: 列举例子, 列举事实.","hsk_level":6,"tags":["dong-tu"],"image":"📋","examples":[{"type":"basic","zh":"请列举三个例子。","pinyin":"Qǐng lièjǔ sān gè lìzi.","vi":"Hãy liệt kê ba ví dụ."},{"type":"simple","zh":"报告中列举了城市交通存在的五大问题。","pinyin":"Bàogào zhōng lièjǔle chéngshì jiāotōng cúnzài de wǔ dà wèntí.","vi":"Bản báo cáo đã liệt kê năm vấn đề lớn của giao thông đô thị."},{"type":"compound","zh":"他的优点太多了，即使列举一整天也说不完。","pinyin":"Tā de yōudiǎn tài duō le, jíshǐ lièjǔ yìzhěngtiān yě shuō bù wán.","vi":"Ưu điểm của anh ấy nhiều quá, dù liệt kê cả ngày cũng không hết."}],"related":[{"hanzi":"举例","pinyin":"jǔlì","vi":"nêu ví dụ"},{"hanzi":"列出","pinyin":"lièchū","vi":"liệt kê ra"},{"hanzi":"罗列","pinyin":"luóliè","vi":"bày ra"},{"hanzi":"例子","pinyin":"lìzi","vi":"ví dụ"}],"traditional":"列舉"},{"id":"流芳百世","hanzi":"流芳百世","pinyin":"liúfāng-bǎishì","meaning_vi":"lưu danh muôn thuở","explanation":"流芳 (lưu phương – để lại tiếng thơm) + 百世 (trăm đời) → tiếng thơm lưu truyền muôn đời. Trái nghĩa: 遗臭万年 (tiếng xấu muôn đời).","hsk_level":6,"tags":["thanh-ngu"],"image":"👑","examples":[{"type":"basic","zh":"他的美名流芳百世。","pinyin":"Tā de měimíng liúfāngbǎishì.","vi":"Tiếng thơm của ông lưu truyền muôn đời."},{"type":"simple","zh":"岳飞的爱国精神将流芳百世。","pinyin":"Yuèfēi de àiguó jīngshén jiāng liúfāngbǎishì.","vi":"Tinh thần yêu nước của Nhạc Phi sẽ lưu danh muôn thuở."},{"type":"compound","zh":"虽然他一生清贫，但是他的医德流芳百世。","pinyin":"Suīrán tā yìshēng qīngpín, dànshì tā de yīdé liúfāngbǎishì.","vi":"Tuy ông sống thanh bần cả đời nhưng y đức của ông lưu danh muôn thuở."}],"related":[{"hanzi":"万古流芳","pinyin":"wàngǔliúfāng","vi":"tiếng thơm muôn đời"},{"hanzi":"名垂青史","pinyin":"míngchuíqīngshǐ","vi":"lưu danh sử sách"},{"hanzi":"遗臭万年","pinyin":"yíchòuwànnián","vi":"tiếng xấu muôn đời"},{"hanzi":"永垂不朽","pinyin":"yǒngchuíbùxiǔ","vi":"đời đời bất diệt"}]},{"id":"流连忘返","hanzi":"流连忘返","pinyin":"liúlián-wàngfǎn","meaning_vi":"mải mê ngắm cảnh đẹp đến quên cả đường về","explanation":"流连 (lưu liên – mải mê nán lại) + 忘返 (quên trở về) → say mê cảnh đẹp đến quên cả về. Hay dùng khen phong cảnh: 令人流连忘返.","hsk_level":6,"tags":["thanh-ngu","du-lich"],"image":"🏞️","examples":[{"type":"basic","zh":"游客流连忘返。","pinyin":"Yóukè liúliánwàngfǎn.","vi":"Du khách mải mê quên cả lối về."},{"type":"simple","zh":"西湖的美景让每位游客都流连忘返。","pinyin":"Xīhú de měijǐng ràng měi wèi yóukè dōu liúliánwàngfǎn.","vi":"Cảnh đẹp Tây Hồ khiến mọi du khách đều mải mê quên lối về."},{"type":"compound","zh":"这座古镇不但风景优美，而且小吃丰富，令人流连忘返。","pinyin":"Zhè zuò gǔzhèn búdàn fēngjǐng yōuměi, érqiě xiǎochī fēngfù, lìngrén liúliánwàngfǎn.","vi":"Thị trấn cổ này không những phong cảnh đẹp mà đồ ăn vặt còn phong phú, khiến người ta lưu luyến quên về."}],"related":[{"hanzi":"乐不思蜀","pinyin":"lèbùsīshǔ","vi":"vui quên về"},{"hanzi":"留恋","pinyin":"liúliàn","vi":"lưu luyến"},{"hanzi":"风景","pinyin":"fēngjǐng","vi":"phong cảnh"},{"hanzi":"恋恋不舍","pinyin":"liànliànbùshě","vi":"lưu luyến không rời"}],"traditional":"流連忘返"},{"id":"留神","hanzi":"留神","pinyin":"liúshén","meaning_vi":"cẩn thận","explanation":"留 (lưu – giữ lại) + 神 (thần – tinh thần, sự chú ý) → để tâm, chú ý cẩn thận. Hay dùng trong khẩu ngữ: 留神脚下 (cẩn thận dưới chân).","hsk_level":6,"tags":["dong-tu"],"image":"⚠️","examples":[{"type":"basic","zh":"过马路要留神。","pinyin":"Guòmǎlù yào liúshén.","vi":"Qua đường phải cẩn thận."},{"type":"simple","zh":"下楼梯时留神脚下的积水。","pinyin":"Xià lóutī shí liúshén jiǎoxià de jīshuǐ.","vi":"Khi xuống cầu thang hãy để ý vũng nước dưới chân."},{"type":"compound","zh":"你一不留神，钱包就可能被小偷偷走。","pinyin":"Nǐ yí bù liúshén, qiánbāo jiù kěnéng bèi xiǎo tōutōu zǒu.","vi":"Chỉ cần bạn sơ ý một chút là ví tiền có thể bị kẻ trộm lấy mất."}],"related":[{"hanzi":"小心","pinyin":"xiǎoxīn","vi":"cẩn thận"},{"hanzi":"注意","pinyin":"zhùyì","vi":"chú ý"},{"hanzi":"当心","pinyin":"dāngxīn","vi":"coi chừng"},{"hanzi":"不留神","pinyin":"bùliúshén","vi":"không để ý"}]},{"id":"溜","hanzi":"溜","pinyin":"liū","meaning_vi":"trượt, lén đi","explanation":"Lựu – trượt, lướt; lẻn đi, chuồn mất. Thường gặp: 溜冰 (trượt băng), 溜走 (lẻn đi), 溜达 (đi dạo, tản bộ).","hsk_level":6,"tags":["dong-tu"],"image":"⛸️","examples":[{"type":"basic","zh":"他偷偷溜走了。","pinyin":"Tā tōutōu liūzǒu le.","vi":"Anh ta lén chuồn đi rồi."},{"type":"simple","zh":"孩子们在结了冰的湖面上溜来溜去。","pinyin":"Háizimen zài jiéle bīng de húmiàn shàng liū lái liū qù.","vi":"Bọn trẻ trượt qua trượt lại trên mặt hồ đóng băng."},{"type":"compound","zh":"会议还没结束，他就从后门溜出去了。","pinyin":"Huìyì hái méi jiéshù, tā jiù cóng hòumén liū chūqù le.","vi":"Cuộc họp còn chưa kết thúc, anh ta đã lẻn ra bằng cửa sau."}],"related":[{"hanzi":"溜走","pinyin":"liūzǒu","vi":"lẻn đi"},{"hanzi":"滑","pinyin":"huá","vi":"trượt"},{"hanzi":"溜冰","pinyin":"liūbīng","vi":"trượt băng"},{"hanzi":"偷偷","pinyin":"tōutōu","vi":"lén lút"}]},{"id":"了如指掌","hanzi":"了如指掌","pinyin":"liǎorú-zhǐzhǎng","meaning_vi":"hiểu rõ như lòng bàn tay","explanation":"了 (liễu – hiểu rõ) + 如指掌 (như chỉ vào lòng bàn tay) → nắm rõ tường tận mọi chi tiết. Thường: 对这里的情况了如指掌.","hsk_level":6,"tags":["thanh-ngu"],"image":"🖐️","examples":[{"type":"basic","zh":"他对这里了如指掌。","pinyin":"Tā duì zhèlǐ liǎorúzhǐzhǎng.","vi":"Anh ấy biết rõ nơi này như lòng bàn tay."},{"type":"simple","zh":"老司机对城里的每条小路都了如指掌。","pinyin":"Lǎosījī duì chénglǐ de měi tiáo xiǎolù dōu liǎorúzhǐzhǎng.","vi":"Bác tài lâu năm thuộc từng con đường nhỏ trong thành phố như lòng bàn tay."},{"type":"compound","zh":"因为他在这家工厂干了三十年，所以对每台机器都了如指掌。","pinyin":"Yīnwèi tā zài zhè jiā gōngchǎng gànle sānshí nián, suǒyǐ duì měi tái jīqì dōu liǎorúzhǐzhǎng.","vi":"Vì ông ấy đã làm ở nhà máy này ba mươi năm nên hiểu rõ từng cỗ máy như lòng bàn tay."}],"related":[{"hanzi":"一清二楚","pinyin":"yìqīng'èrchǔ","vi":"rõ ràng rành mạch"},{"hanzi":"熟悉","pinyin":"shúxī","vi":"quen thuộc"},{"hanzi":"一无所知","pinyin":"yìwúsuǒzhī","vi":"không biết gì"},{"hanzi":"心中有数","pinyin":"xīnzhōngyǒushù","vi":"nắm rõ trong lòng"}],"traditional":"瞭如指掌"},{"id":"落成","hanzi":"落成","pinyin":"luòchéng","meaning_vi":"khánh thành","explanation":"落 (lạc – hạ xuống, hoàn tất) + 成 (thành – xong) → công trình xây dựng hoàn thành, khánh thành. Thường: 落成典礼 (lễ khánh thành).","hsk_level":6,"tags":["dong-tu"],"image":"🏛️","examples":[{"type":"basic","zh":"新图书馆落成了。","pinyin":"Xīn túshūguǎn luòchéng le.","vi":"Thư viện mới đã khánh thành."},{"type":"simple","zh":"这座跨海大桥将于明年五月落成。","pinyin":"Zhè zuò kuà hǎi Dàqiáo jiāng yú míngnián Wǔyuè luòchéng.","vi":"Cây cầu vượt biển này sẽ được khánh thành vào tháng năm năm sau."},{"type":"compound","zh":"体育馆一落成，市民就可以免费进去锻炼了。","pinyin":"Tǐyùguǎn yí luòchéng, shìmín jiù kěyǐ miǎnfèi jìnqù duànliàn le.","vi":"Nhà thi đấu vừa khánh thành, người dân đã có thể vào tập luyện miễn phí."}],"related":[{"hanzi":"竣工","pinyin":"jùngōng","vi":"hoàn công"},{"hanzi":"落成典礼","pinyin":"luòchéngdiǎnlǐ","vi":"lễ khánh thành"},{"hanzi":"建成","pinyin":"jiànchéng","vi":"xây xong"},{"hanzi":"开工","pinyin":"kāigōng","vi":"khởi công"}]},{"id":"落花流水","hanzi":"落花流水","pinyin":"luòhuā-liúshuǐ","meaning_vi":"thua tan tác, tơi bời","explanation":"Hoa rụng nước trôi, vốn tả cảnh cuối xuân tàn tạ → ví bị đánh thua tan tác, tơi bời. Thường: 被打得落花流水.","hsk_level":6,"tags":["thanh-ngu"],"image":"🌸","examples":[{"type":"basic","zh":"敌人被打得落花流水。","pinyin":"Dírén bèi dǎ de luòhuāliúshuǐ.","vi":"Quân địch bị đánh cho tan tác."},{"type":"simple","zh":"主队以五比零把对手打得落花流水。","pinyin":"Zhǔduì yǐ wǔ bǐ líng bǎ duìshǒu dǎ de luòhuāliúshuǐ.","vi":"Đội chủ nhà thắng năm không, đánh cho đối thủ tơi bời."},{"type":"compound","zh":"因为上次比赛我们输得落花流水，所以这次大家拼命训练。","pinyin":"Yīnwèi shàngcì bǐsài wǒmen shū de luòhuāliúshuǐ, suǒyǐ zhè cì dàjiā pīnmìng xùnliàn.","vi":"Vì lần trước chúng tôi thua tan tác nên lần này mọi người tập luyện hết sức."}],"related":[{"hanzi":"一败涂地","pinyin":"yíbàitúdì","vi":"thua thảm hại"},{"hanzi":"溃不成军","pinyin":"kuìbùchéngjūn","vi":"tan tác"},{"hanzi":"大获全胜","pinyin":"dàhuòquánshèng","vi":"toàn thắng"},{"hanzi":"惨败","pinyin":"cǎnbài","vi":"thảm bại"}]},{"id":"落井下石","hanzi":"落井下石","pinyin":"luòjǐng-xiàshí","meaning_vi":"ném đá xuống giếng, thấy người gặp nạn lại hãm hại thêm","explanation":"Thấy người rơi xuống giếng lại ném đá xuống (văn Hàn Dũ) → nhân lúc người khác gặp nạn mà hãm hại thêm.","hsk_level":6,"tags":["thanh-ngu"],"image":"🪨","examples":[{"type":"basic","zh":"不要落井下石。","pinyin":"Bú yào luòjǐngxiàshí.","vi":"Đừng ném đá xuống giếng."},{"type":"simple","zh":"他最恨那些落井下石的小人。","pinyin":"Tā zuì hèn nàxiē luòjǐngxiàshí de xiǎorén.","vi":"Anh ấy căm ghét nhất những kẻ tiểu nhân thấy người gặp nạn lại hãm hại thêm."},{"type":"compound","zh":"别人遇到困难时，我们即使不帮忙，也不能落井下石。","pinyin":"Biérén yùdào kùnnán shí, wǒmen jíshǐ bù bāngmáng, yě bù néng luòjǐngxiàshí.","vi":"Khi người khác gặp khó khăn, dù không giúp đỡ thì chúng ta cũng không được ném đá xuống giếng."}],"related":[{"hanzi":"趁火打劫","pinyin":"chènhuǒdǎjié","vi":"thừa nước đục thả câu"},{"hanzi":"雪上加霜","pinyin":"xuěshàngjiāshuāng","vi":"họa vô đơn chí"},{"hanzi":"雪中送炭","pinyin":"xuězhōngsòngtàn","vi":"giúp người lúc khó khăn"},{"hanzi":"幸灾乐祸","pinyin":"xìngzāilèhuò","vi":"vui trên nỗi đau người khác"}]},{"id":"滥竽充数","hanzi":"滥竽充数","pinyin":"lànyú-chōngshù","meaning_vi":"đánh trống ghi tên, kẻ bất tài trà trộn vào tập thể","explanation":"滥竽充数: 滥 (lạm – bừa) 竽 (vu – kèn vu) 充数 (cho đủ số) → Nam Quách tiên sinh không biết thổi kèn vẫn trà trộn vào dàn nhạc của Tề Tuyên Vương → kẻ bất tài lẫn vào cho đủ số; cũng dùng để tự khiêm.","hsk_level":6,"tags":["thanh-ngu"],"image":"🎶","examples":[{"type":"basic","zh":"他只是滥竽充数。","pinyin":"Tā zhǐshì lànyúchōngshù.","vi":"Anh ta chỉ là đánh trống ghi tên thôi."},{"type":"simple","zh":"我在合唱团里不过是滥竽充数罢了。","pinyin":"Wǒ zài héchàngtuán lǐ búguò shì lànyúchōngshù bàle.","vi":"Tôi trong dàn hợp xướng chẳng qua chỉ góp mặt cho đủ số mà thôi."},{"type":"compound","zh":"如果考核制度严格，就没有人能滥竽充数了。","pinyin":"Rúguǒ kǎohé zhìdù yángé, jiù méiyǒu rén néng lànyúchōngshù le.","vi":"Nếu chế độ sát hạch nghiêm ngặt thì sẽ không ai có thể trà trộn cho đủ số nữa."}],"related":[{"hanzi":"鱼目混珠","pinyin":"yúmùhùnzhū","vi":"vàng thau lẫn lộn"},{"hanzi":"名不副实","pinyin":"míngbúfùshí","vi":"hữu danh vô thực"},{"hanzi":"冒充","pinyin":"màochōng","vi":"mạo danh"},{"hanzi":"真才实学","pinyin":"zhēncáishíxué","vi":"tài thật học thật"}],"traditional":"濫竽充數"},{"id":"来龙去脉","hanzi":"来龙去脉","pinyin":"láilóng-qùmài","meaning_vi":"đầu đuôi ngọn ngành sự việc","explanation":"Thế núi như rồng chạy đến, mạch đất chạy đi (thuật phong thủy) → toàn bộ đầu đuôi, nguồn gốc và diễn biến sự việc. Thường: 弄清事情的来龙去脉.","hsk_level":6,"tags":["thanh-ngu"],"image":"🔍","examples":[{"type":"basic","zh":"说说事情的来龙去脉。","pinyin":"Shuōshuo shìqing de láilóngqùmài.","vi":"Kể đầu đuôi ngọn ngành sự việc đi."},{"type":"simple","zh":"记者花了一周时间调查事故的来龙去脉。","pinyin":"Jìzhě huāle yìzhōu shíjiān diàochá shìgù de láilóngqùmài.","vi":"Phóng viên mất một tuần để điều tra đầu đuôi vụ tai nạn."},{"type":"compound","zh":"只要弄清楚来龙去脉，问题就好解决了。","pinyin":"Zhǐyào nòng qīngchu láilóngqùmài, wèntí jiù hǎo jiějué le.","vi":"Chỉ cần làm rõ đầu đuôi ngọn ngành thì vấn đề sẽ dễ giải quyết."}],"related":[{"hanzi":"前因后果","pinyin":"qiányīnhòuguǒ","vi":"nguyên nhân kết quả"},{"hanzi":"始末","pinyin":"shǐmò","vi":"đầu đuôi"},{"hanzi":"经过","pinyin":"jīngguò","vi":"quá trình"},{"hanzi":"原委","pinyin":"yuánwěi","vi":"ngọn ngành"}],"traditional":"來龍去脈"},{"id":"来源","hanzi":"来源","pinyin":"láiyuán","meaning_vi":"nguồn gốc","explanation":"来 (lai – đến) + 源 (nguyên – nguồn) → nguồn gốc, nơi xuất phát. Thường: 收入来源, 信息来源; động từ: 来源于.","hsk_level":6,"tags":["danh-tu"],"image":"🌊","examples":[{"type":"basic","zh":"消息来源可靠。","pinyin":"Xiāoxi láiyuán kěkào.","vi":"Nguồn tin đáng tin cậy."},{"type":"simple","zh":"这个村子的主要经济来源是种茶。","pinyin":"Zhè gè cūnzi de zhǔyào jīngjì láiyuán shì zhòng chá.","vi":"Nguồn kinh tế chính của ngôi làng này là trồng chè."},{"type":"compound","zh":"如果水的来源受到污染，全城人的健康就会受影响。","pinyin":"Rúguǒ shuǐ de láiyuán shòudào wūrǎn, quánchéng rén de jiànkāng jiù huì shòu yǐngxiǎng.","vi":"Nếu nguồn nước bị ô nhiễm thì sức khỏe của người dân cả thành phố sẽ bị ảnh hưởng."}],"related":[{"hanzi":"根源","pinyin":"gēnyuán","vi":"căn nguyên"},{"hanzi":"出处","pinyin":"chūchù","vi":"xuất xứ"},{"hanzi":"起源","pinyin":"qǐyuán","vi":"khởi nguồn"},{"hanzi":"资金来源","pinyin":"zījīnláiyuán","vi":"nguồn vốn"}],"traditional":"來源"},{"id":"来之不易","hanzi":"来之不易","pinyin":"láizhī-búyì","meaning_vi":"không dễ dàng gì mới có được","explanation":"来 (có được) + 之 (nó) + 不易 (không dễ) → có được thật chẳng dễ dàng, cần trân trọng. Thường: 成果来之不易.","hsk_level":6,"tags":["thanh-ngu"],"image":"💎","examples":[{"type":"basic","zh":"幸福来之不易。","pinyin":"Xìngfú láizhībúyì.","vi":"Hạnh phúc không dễ gì có được."},{"type":"simple","zh":"我们要珍惜这来之不易的和平生活。","pinyin":"Wǒmen yào zhēnxī zhè láizhībúyì de hépíng shēnghuó.","vi":"Chúng ta phải trân trọng cuộc sống hòa bình có được không dễ dàng này."},{"type":"compound","zh":"因为这份工作来之不易，所以他格外努力。","pinyin":"Yīnwèi zhè fèn gōngzuò láizhībúyì, suǒyǐ tā géwài nǔlì.","vi":"Vì công việc này không dễ gì có được nên anh ấy đặc biệt nỗ lực."}],"related":[{"hanzi":"得来不易","pinyin":"déláibúyì","vi":"có được không dễ"},{"hanzi":"珍惜","pinyin":"zhēnxī","vi":"trân trọng"},{"hanzi":"千辛万苦","pinyin":"qiānxīnwànkǔ","vi":"muôn vàn gian khổ"},{"hanzi":"轻而易举","pinyin":"qīng'éryìjǔ","vi":"dễ như trở bàn tay"}],"traditional":"來之不易"},{"id":"狼狈","hanzi":"狼狈","pinyin":"lángbèi","meaning_vi":"nhếch nhác, chật vật","explanation":"狼 (lang – sói) + 狈 (bái – loài thú tương truyền chân trước ngắn, phải bám vào sói mới đi được) → chật vật, nhếch nhác, khốn đốn. Liên quan: 狼狈为奸.","hsk_level":6,"tags":["tinh-tu"],"image":"😅","examples":[{"type":"basic","zh":"他样子很狼狈。","pinyin":"Tā yàngzi hěn lángbèi.","vi":"Trông anh ấy rất nhếch nhác."},{"type":"simple","zh":"没带伞的我被大雨淋得十分狼狈。","pinyin":"Méi dài sǎn de wǒ bèi dàyǔ lín de shífēn lángbèi.","vi":"Không mang ô, tôi bị mưa to dội ướt trông rất thảm hại."},{"type":"compound","zh":"他一进门就摔了一跤，场面狼狈极了。","pinyin":"Tā yí jìnmén jiù shuāile yì jiāo, chǎngmiàn lángbèi jíle.","vi":"Anh ấy vừa vào cửa đã ngã một cú, cảnh tượng thật chật vật."}],"related":[{"hanzi":"尴尬","pinyin":"gāngà","vi":"lúng túng"},{"hanzi":"狼狈不堪","pinyin":"lángbèibùkān","vi":"vô cùng chật vật"},{"hanzi":"狼狈为奸","pinyin":"lángbèiwéijiān","vi":"cấu kết làm bậy"},{"hanzi":"从容","pinyin":"cóngróng","vi":"ung dung"}],"traditional":"狼狽"},{"id":"狼吞虎咽","hanzi":"狼吞虎咽","pinyin":"lángtūn-hǔyàn","meaning_vi":"ăn ngấu nghiến như hổ đói","explanation":"Nuốt như sói, nuốt chửng như hổ → ăn vội vàng, ngấu nghiến. Thường tả người đang rất đói.","hsk_level":6,"tags":["thanh-ngu","an-uong"],"image":"🐯","examples":[{"type":"basic","zh":"他狼吞虎咽地吃饭。","pinyin":"Tā lángtūnhǔyàn de chīfàn.","vi":"Anh ấy ăn cơm ngấu nghiến."},{"type":"simple","zh":"饿了一天的弟弟狼吞虎咽地吃完了三碗面。","pinyin":"Èle yì tiān de dìdi lángtūnhǔyàn de chī wánle sān wǎn miàn.","vi":"Cậu em đói cả ngày đã ăn ngấu nghiến hết ba bát mì."},{"type":"compound","zh":"吃饭的时候如果狼吞虎咽，就容易消化不良。","pinyin":"Chīfàn de shíhou rúguǒ lángtūnhǔyàn, jiù róngyì xiāohuà bùliáng.","vi":"Khi ăn cơm nếu ăn ngấu nghiến thì dễ bị khó tiêu."}],"related":[{"hanzi":"细嚼慢咽","pinyin":"xìjiáomànyàn","vi":"nhai kỹ nuốt chậm"},{"hanzi":"饥不择食","pinyin":"jībùzéshí","vi":"đói thì ăn gì cũng được"},{"hanzi":"吃","pinyin":"chī","vi":"ăn"},{"hanzi":"大吃大喝","pinyin":"dàchīdàhē","vi":"ăn uống thỏa thích"}],"traditional":"狼吞虎嚥"},{"id":"唠叨","hanzi":"唠叨","pinyin":"láodao","meaning_vi":"lải nhải","explanation":"唠 (lao – nói nhiều) + 叨 (thao – lải nhải) → nói đi nói lại mãi, cằn nhằn. Thường: 妈妈总是唠叨.","hsk_level":6,"tags":["dong-tu"],"image":"🗣️","examples":[{"type":"basic","zh":"妈妈又唠叨了。","pinyin":"Māma yòu láodao le.","vi":"Mẹ lại cằn nhằn rồi."},{"type":"simple","zh":"奶奶整天唠叨我穿得太少。","pinyin":"Nǎinai zhěngtiān láodao wǒ chuān de tài shǎo.","vi":"Bà nội cả ngày lải nhải rằng tôi mặc quá ít."},{"type":"compound","zh":"虽然爸爸爱唠叨，但是他说的话都很有道理。","pinyin":"Suīrán bàba ài láodao, dànshì tā shuō dehuà dōu hěn yǒudàolǐ.","vi":"Tuy bố hay cằn nhằn nhưng những lời ông nói đều rất có lý."}],"related":[{"hanzi":"啰嗦","pinyin":"luōsuo","vi":"dài dòng"},{"hanzi":"絮叨","pinyin":"xùdao","vi":"lải nhải"},{"hanzi":"抱怨","pinyin":"bàoyuàn","vi":"phàn nàn"},{"hanzi":"简洁","pinyin":"jiǎnjié","vi":"ngắn gọn"}],"traditional":"嘮叨"},{"id":"乐极生悲","hanzi":"乐极生悲","pinyin":"lèjí-shēngbēi","meaning_vi":"vui quá hóa buồn","explanation":"乐极 (vui đến cực điểm) + 生悲 (sinh ra buồn) → vui quá hóa buồn; nhắc nhở đừng quá đắc ý.","hsk_level":6,"tags":["thanh-ngu"],"image":"🎭","examples":[{"type":"basic","zh":"真是乐极生悲啊！","pinyin":"Zhēn shì lèjíshēngbēi a!","vi":"Đúng là vui quá hóa buồn!"},{"type":"simple","zh":"他庆祝生日时摔断了腿，真是乐极生悲。","pinyin":"Tā qìngzhù shēngrì shí shuāiduànle tuǐ, zhēn shì lèjíshēngbēi.","vi":"Anh ấy gãy chân ngay khi đang mừng sinh nhật, đúng là vui quá hóa buồn."},{"type":"compound","zh":"如果高兴得忘乎所以，就可能乐极生悲。","pinyin":"Rúguǒ gāoxìng de wànghūsuǒyǐ, jiù kěnéng lèjíshēngbēi.","vi":"Nếu vui mừng đến quên hết mọi thứ thì có thể vui quá hóa buồn."}],"related":[{"hanzi":"好景不长","pinyin":"hǎojǐngbùcháng","vi":"cảnh đẹp chẳng dài"},{"hanzi":"物极必反","pinyin":"wùjíbìfǎn","vi":"vật cực tất phản"},{"hanzi":"否极泰来","pinyin":"pǐjítàilái","vi":"hết cơn bĩ cực tới hồi thái lai"},{"hanzi":"得意忘形","pinyin":"déyìwàngxíng","vi":"đắc ý quên mình"}],"traditional":"樂極生悲"},{"id":"雷达","hanzi":"雷达","pinyin":"léidá","meaning_vi":"ra-đa","explanation":"Phiên âm từ tiếng Anh \"radar\", 雷 (lôi – sấm) + 达 (đạt) → thiết bị dùng sóng vô tuyến phát hiện mục tiêu. Thường: 雷达站, 雷达探测.","hsk_level":6,"tags":["danh-tu","cong-nghe"],"image":"📡","examples":[{"type":"basic","zh":"雷达发现了目标。","pinyin":"Léidá fāxiànle mùbiāo.","vi":"Ra-đa đã phát hiện mục tiêu."},{"type":"simple","zh":"机场的雷达可以监测几百公里外的飞机。","pinyin":"Jīchǎng de léidá kěyǐ jiāncè jǐ bǎi gōnglǐ wài de fēijī.","vi":"Ra-đa của sân bay có thể theo dõi máy bay cách xa mấy trăm cây số."},{"type":"compound","zh":"因为雷达出了故障，所以航班只好推迟起飞。","pinyin":"Yīnwèi léidá chūle gùzhàng, suǒyǐ hángbān zhǐhǎo tuīchí qǐfēi.","vi":"Vì ra-đa gặp sự cố nên chuyến bay đành phải hoãn cất cánh."}],"related":[{"hanzi":"信号","pinyin":"xìnhào","vi":"tín hiệu"},{"hanzi":"探测","pinyin":"tàncè","vi":"thăm dò"},{"hanzi":"卫星","pinyin":"wèixīng","vi":"vệ tinh"},{"hanzi":"声呐","pinyin":"shēngnà","vi":"sonar"}],"traditional":"雷達"},{"id":"雷厉风行","hanzi":"雷厉风行","pinyin":"léilì-fēngxíng","meaning_vi":"làm việc dứt khoát nhanh gọn mạnh mẽ","explanation":"Mạnh như sấm sét, nhanh như gió thổi → làm việc quyết đoán, nhanh chóng và triệt để. Hay dùng khen phong cách làm việc.","hsk_level":6,"tags":["thanh-ngu","cong-viec"],"image":"⚡","examples":[{"type":"basic","zh":"新经理雷厉风行。","pinyin":"Xīn jīnglǐ léilìfēngxíng.","vi":"Giám đốc mới làm việc quyết liệt nhanh gọn."},{"type":"simple","zh":"市政府雷厉风行地整顿了路边违章摊位。","pinyin":"Shìzhèngfǔ léilìfēngxíng de zhěngdùnle lùbiān wéizhāng tānwèi.","vi":"Chính quyền thành phố đã nhanh chóng chấn chỉnh các sạp hàng lấn chiếm lề đường."},{"type":"compound","zh":"她一接到任务，就雷厉风行地安排好了一切。","pinyin":"Tā yì jiēdào rènwù, jiù léilìfēngxíng de ānpái hǎole yíqiè.","vi":"Vừa nhận nhiệm vụ, cô ấy liền nhanh gọn dứt khoát sắp xếp xong mọi việc."}],"related":[{"hanzi":"说干就干","pinyin":"shuōgànjiùgàn","vi":"nói là làm"},{"hanzi":"果断","pinyin":"guǒduàn","vi":"quả quyết"},{"hanzi":"拖拖拉拉","pinyin":"tuōtuōlālā","vi":"lề mề"},{"hanzi":"迅速","pinyin":"xùnsù","vi":"nhanh chóng"}],"traditional":"雷厲風行"},{"id":"历代","hanzi":"历代","pinyin":"lìdài","meaning_vi":"các triều đại","explanation":"历 (lịch – trải qua) + 代 (đại – đời, triều đại) → các đời, các triều đại trong lịch sử. Thường: 历代王朝, 历代皇帝.","hsk_level":6,"tags":["danh-tu","thoi-gian"],"image":"🏯","examples":[{"type":"basic","zh":"历代皇帝都来过这里。","pinyin":"Lìdài huángdì dōu láiguò zhèlǐ.","vi":"Các đời hoàng đế đều từng đến đây."},{"type":"simple","zh":"博物馆里收藏着历代名家的书画作品。","pinyin":"Bówùguǎn lǐ shōucángzhe lìdài míngjiā de shūhuà zuòpǐn.","vi":"Trong bảo tàng lưu giữ tác phẩm thư họa của các danh gia qua các thời đại."},{"type":"compound","zh":"这座古桥虽然经历了历代战乱，但是至今保存完好。","pinyin":"Zhè zuò gǔ qiáo suīrán jīnglìle lìdài zhànluàn, dànshì zhìjīn bǎocún wánhǎo.","vi":"Cây cầu cổ này tuy trải qua chiến loạn của nhiều triều đại nhưng đến nay vẫn được bảo tồn nguyên vẹn."}],"related":[{"hanzi":"历朝","pinyin":"lìcháo","vi":"các triều đại"},{"hanzi":"朝代","pinyin":"cháodài","vi":"triều đại"},{"hanzi":"世世代代","pinyin":"shìshìdàidài","vi":"đời đời kiếp kiếp"},{"hanzi":"历史","pinyin":"lìshǐ","vi":"lịch sử"}],"traditional":"歷代"},{"id":"立竿见影","hanzi":"立竿见影","pinyin":"lìgān-jiànyǐng","meaning_vi":"thấy ngay hiệu quả tức thì (cắm sào thấy bóng)","explanation":"Dựng cây sào dưới nắng là thấy ngay bóng → làm là có hiệu quả tức thì. Thường: 效果立竿见影.","hsk_level":6,"tags":["thanh-ngu"],"image":"⚡","examples":[{"type":"basic","zh":"效果立竿见影。","pinyin":"Xiàoguǒ lìgānjiànyǐng.","vi":"Hiệu quả thấy ngay tức thì."},{"type":"simple","zh":"这种新药治疗咳嗽立竿见影。","pinyin":"Zhè zhǒng xīn yào zhìliáo késou lìgānjiànyǐng.","vi":"Loại thuốc mới này trị ho thấy hiệu quả ngay."},{"type":"compound","zh":"学外语不可能立竿见影，只有坚持才会进步。","pinyin":"Xué wàiyǔ bù kěnéng lìgānjiànyǐng, zhǐyǒu jiānchí cái huì jìnbù.","vi":"Học ngoại ngữ không thể thấy kết quả ngay, chỉ có kiên trì mới tiến bộ được."}],"related":[{"hanzi":"见效","pinyin":"jiànxiào","vi":"có hiệu quả"},{"hanzi":"效果","pinyin":"xiàoguǒ","vi":"hiệu quả"},{"hanzi":"立竿见影的效果","pinyin":"lìgānjiànyǐng de xiàoguǒ","vi":"hiệu quả tức thì"},{"hanzi":"遥遥无期","pinyin":"yáoyáowúqī","vi":"xa vời vợi"}],"traditional":"立竿見影"},{"id":"力所能及","hanzi":"力所能及","pinyin":"lìsuǒ-néngjí","meaning_vi":"trong khả năng của mình","explanation":"力 (sức) + 所能及 (có thể với tới) → trong phạm vi sức mình làm được. Thường: 做力所能及的事.","hsk_level":6,"tags":["thanh-ngu"],"image":"💪","examples":[{"type":"basic","zh":"做力所能及的事。","pinyin":"Zuò lìsuǒnéngjí de shì.","vi":"Làm những việc trong khả năng của mình."},{"type":"simple","zh":"孩子应该帮父母做些力所能及的家务。","pinyin":"Háizi yīnggāi bāng fùmǔ zuò xiē lìsuǒnéngjí de jiāwù.","vi":"Trẻ em nên giúp bố mẹ làm những việc nhà trong khả năng của mình."},{"type":"compound","zh":"只要是力所能及的事，我就一定会帮你。","pinyin":"Zhǐ yàoshì lìsuǒnéngjí de shì, wǒ jiù yídìng huì bāng nǐ.","vi":"Chỉ cần là việc trong khả năng của tôi, tôi nhất định sẽ giúp bạn."}],"related":[{"hanzi":"量力而行","pinyin":"liànglì'érxíng","vi":"lượng sức mà làm"},{"hanzi":"能力","pinyin":"nénglì","vi":"năng lực"},{"hanzi":"力不从心","pinyin":"lìbùcóngxīn","vi":"lực bất tòng tâm"},{"hanzi":"尽力","pinyin":"jìnlì","vi":"cố hết sức"}]},{"id":"立体","hanzi":"立体","pinyin":"lìtǐ","meaning_vi":"lập thể 3D","explanation":"立 (lập – đứng) + 体 (thể – hình khối) → có chiều sâu, ba chiều. Thường: 立体电影 (phim 3D), 立体感, 立体声.","hsk_level":6,"tags":["tinh-tu"],"image":"🧊","examples":[{"type":"basic","zh":"这幅画很立体。","pinyin":"Zhè fú huà hěn lìtǐ.","vi":"Bức tranh này trông rất có chiều sâu lập thể."},{"type":"simple","zh":"我们戴上眼镜看了一场立体电影。","pinyin":"Wǒmen dàishàng yǎnjìng kànle yì chǎng lìtǐ diànyǐng.","vi":"Chúng tôi đeo kính vào xem một bộ phim 3D."},{"type":"compound","zh":"这座城市既有地铁又有高架桥，形成了立体交通网。","pinyin":"Zhè zuò chéngshì jìyǒu dìtiě yòu yǒu gāojiàqiáo, xíng chéngle lìtǐ jiāotōng wǎng.","vi":"Thành phố này vừa có tàu điện ngầm vừa có cầu cạn, tạo thành mạng lưới giao thông lập thể."}],"related":[{"hanzi":"平面","pinyin":"píngmiàn","vi":"mặt phẳng"},{"hanzi":"三维","pinyin":"sānwéi","vi":"ba chiều"},{"hanzi":"立体声","pinyin":"lìtǐshēng","vi":"âm thanh nổi"},{"hanzi":"立体感","pinyin":"lìtǐgǎn","vi":"cảm giác lập thể"}],"traditional":"立體"},{"id":"吝啬","hanzi":"吝啬","pinyin":"lìnsè","meaning_vi":"keo kiệt","explanation":"吝 (lận – tiếc của) + 啬 (sắc – hà tiện) → keo kiệt, bủn xỉn. Thường: 吝啬鬼 (kẻ keo kiệt).","hsk_level":6,"tags":["tinh-tu"],"image":"😒","examples":[{"type":"basic","zh":"他非常吝啬。","pinyin":"Tā fēicháng lìnsè.","vi":"Ông ta rất keo kiệt."},{"type":"simple","zh":"那个吝啬的老板连空调都舍不得开。","pinyin":"Nà gè lìnsè de lǎobǎn lián kōngtiáo dōu shěbude kāi.","vi":"Ông chủ keo kiệt đó đến điều hòa cũng không nỡ bật."},{"type":"compound","zh":"虽然他很有钱，但是对朋友非常吝啬。","pinyin":"Suīrán tā hěn yǒuqián, dànshì duì péngyou fēicháng lìnsè.","vi":"Tuy anh ta rất giàu nhưng lại vô cùng keo kiệt với bạn bè."}],"related":[{"hanzi":"小气","pinyin":"xiǎoqi","vi":"keo kiệt"},{"hanzi":"抠门","pinyin":"kōumén","vi":"bủn xỉn"},{"hanzi":"大方","pinyin":"dàfang","vi":"hào phóng"},{"hanzi":"慷慨","pinyin":"kāngkǎi","vi":"hào phóng"}],"traditional":"吝嗇"},{"id":"离乡背井","hanzi":"离乡背井","pinyin":"líxiāng-bèijǐng","meaning_vi":"rời xa quê hương","explanation":"Rời quê, quay lưng (背) với giếng nước làng → bỏ quê đi sống nơi xa, thường vì hoàn cảnh bắt buộc. Cũng nói 背井离乡.","hsk_level":6,"tags":["thanh-ngu"],"image":"🧳","examples":[{"type":"basic","zh":"他离乡背井多年。","pinyin":"Tā líxiāngbèijǐng duōnián.","vi":"Anh ấy đã xa quê nhiều năm."},{"type":"simple","zh":"许多年轻人离乡背井到大城市打工。","pinyin":"Xǔduō niánqīngrén líxiāngbèijǐng dào dàchéngshì dǎgōng.","vi":"Nhiều người trẻ rời bỏ quê hương lên thành phố lớn làm thuê."},{"type":"compound","zh":"因为家乡发生了洪水，所以村民们不得不离乡背井。","pinyin":"Yīnwèi jiāxiāng fāshēngle hóngshuǐ, suǒyǐ cūnmínmen bùdébù líxiāngbèijǐng.","vi":"Vì quê nhà xảy ra lũ lụt nên dân làng buộc phải rời bỏ quê hương."}],"related":[{"hanzi":"背井离乡","pinyin":"bèijǐnglíxiāng","vi":"xa quê bỏ xứ"},{"hanzi":"漂泊","pinyin":"piāobó","vi":"phiêu bạt"},{"hanzi":"思乡","pinyin":"sīxiāng","vi":"nhớ quê"},{"hanzi":"背井离乡的人","pinyin":"bèijǐnglíxiāng de rén","vi":"người xa quê"}],"traditional":"離鄉背井"},{"id":"淋漓尽致","hanzi":"淋漓尽致","pinyin":"línlí-jìnzhì","meaning_vi":"thể hiện trọn vẹn sâu sắc hết mức","explanation":"淋漓 (lâm li – đầm đìa, thỏa thuê) + 尽致 (tận trí – đến tột cùng) → diễn tả, bộc lộ thấu đáo trọn vẹn. Thường: 表现得淋漓尽致.","hsk_level":6,"tags":["thanh-ngu"],"image":"🎨","examples":[{"type":"basic","zh":"他发挥得淋漓尽致。","pinyin":"Tā fāhuī de línlíjìnzhì.","vi":"Anh ấy phát huy hết mức khả năng."},{"type":"simple","zh":"演员把角色的痛苦表现得淋漓尽致。","pinyin":"Yǎnyuán bǎ juésè de tòngkǔ biǎoxiàn de línlíjìnzhì.","vi":"Diễn viên thể hiện nỗi đau của nhân vật một cách trọn vẹn sâu sắc."},{"type":"compound","zh":"这篇文章不但语言生动，而且把人物性格写得淋漓尽致。","pinyin":"Zhè piān wénzhāng búdàn yǔyán shēngdòng, érqiě bǎ rénwù xìnggé xiě de línlíjìnzhì.","vi":"Bài văn này không những ngôn ngữ sinh động mà còn khắc họa tính cách nhân vật thật trọn vẹn."}],"related":[{"hanzi":"酣畅淋漓","pinyin":"hānchànglínlí","vi":"thỏa thích sảng khoái"},{"hanzi":"透彻","pinyin":"tòuchè","vi":"thấu đáo"},{"hanzi":"充分","pinyin":"chōngfèn","vi":"đầy đủ"},{"hanzi":"详尽","pinyin":"xiángjìn","vi":"tường tận"}],"traditional":"淋漓盡致"},{"id":"林林总总","hanzi":"林林总总","pinyin":"línlín-zǒngzǒng","meaning_vi":"muôn hình muôn vẻ, đủ mọi loại","explanation":"Từ láy AABB.","hsk_level":6,"tags":["thanh-ngu"],"image":"📑","examples":[{"type":"basic","zh":"商品林林总总。","pinyin":"Shāngpǐn línlínzǒngzǒng.","vi":"Hàng hóa muôn hình muôn vẻ."},{"type":"simple","zh":"夜市上摆满了林林总总的小吃摊。","pinyin":"Yèshì shàng bǎimǎnle línlínzǒngzǒng de xiǎochī tān.","vi":"Chợ đêm bày đầy đủ các loại quầy ăn vặt."},{"type":"compound","zh":"虽然书店里的书林林总总，但是我要的那本却没有。","pinyin":"Suīrán shūdiàn lǐ de shū línlínzǒngzǒng, dànshì wǒ yào de nà běn què méiyǒu.","vi":"Tuy sách trong hiệu sách đủ mọi loại nhưng cuốn tôi cần lại không có."}],"related":[{"hanzi":"形形色色","pinyin":"xíngxíngsèsè","vi":"đủ loại"},{"hanzi":"五花八门","pinyin":"wǔhuābāmén","vi":"muôn hình vạn trạng"},{"hanzi":"各式各样","pinyin":"gèshìgèyàng","vi":"đủ mọi kiểu"},{"hanzi":"琳琅满目","pinyin":"línlángmǎnmù","vi":"đẹp đẽ đầy rẫy"}],"traditional":"林林總總"},{"id":"临危不惧","hanzi":"临危不惧","pinyin":"línwēi-bújù","meaning_vi":"đứng trước nguy hiểm không hề sợ hãi","explanation":"临危 (lâm nguy – gặp nguy hiểm) + 不惧 (bất cụ – không sợ) → đứng trước nguy hiểm vẫn bình tĩnh, không sợ hãi.","hsk_level":6,"tags":["thanh-ngu"],"image":"🦁","examples":[{"type":"basic","zh":"她临危不惧，十分冷静。","pinyin":"Tā línwēibújù, shífēn lěngjìng.","vi":"Cô ấy gặp nguy không sợ, rất bình tĩnh."},{"type":"simple","zh":"消防队长临危不惧地冲进了火场。","pinyin":"Xiāofáng duìzhǎng línwēibújù de chōngjìnle huǒchǎng.","vi":"Đội trưởng cứu hỏa không chút sợ hãi lao vào đám cháy."},{"type":"compound","zh":"因为船长临危不惧，所以全船乘客都安全脱险了。","pinyin":"Yīnwèi chuánzhǎng línwēibújù, suǒyǐ quán chuán chéngkè dōu ānquán tuōxiǎn le.","vi":"Vì thuyền trưởng gặp nguy không sợ nên hành khách cả tàu đều thoát nạn an toàn."}],"related":[{"hanzi":"临危不乱","pinyin":"línwēibúluàn","vi":"gặp nguy không loạn"},{"hanzi":"镇定自若","pinyin":"zhèndìngzìruò","vi":"bình tĩnh như thường"},{"hanzi":"贪生怕死","pinyin":"tānshēngpàsǐ","vi":"tham sống sợ chết"},{"hanzi":"勇敢","pinyin":"yǒnggǎn","vi":"dũng cảm"}],"traditional":"臨危不懼"},{"id":"灵魂","hanzi":"灵魂","pinyin":"línghún","meaning_vi":"linh hồn","explanation":"灵 (linh – thiêng liêng) + 魂 (hồn) → linh hồn; nghĩa bóng là phần cốt lõi quan trọng nhất. Thường: 人类灵魂的工程师 (chỉ nhà giáo).","hsk_level":6,"tags":["danh-tu"],"image":"👻","examples":[{"type":"basic","zh":"音乐是他的灵魂。","pinyin":"Yīnyuè shì tā de línghún.","vi":"Âm nhạc là linh hồn của anh ấy."},{"type":"simple","zh":"教师被称为人类灵魂的工程师。","pinyin":"Jiàoshī bèi chēngwéi rénlèi línghún de gōngchéngshī.","vi":"Giáo viên được gọi là kỹ sư tâm hồn của nhân loại."},{"type":"compound","zh":"如果一部电影没有好故事，就等于没有灵魂。","pinyin":"Rúguǒ yí bù diànyǐng méiyǒu hǎo gùshi, jiù děngyú méiyǒu línghún.","vi":"Nếu một bộ phim không có câu chuyện hay thì coi như không có linh hồn."}],"related":[{"hanzi":"心灵","pinyin":"xīnlíng","vi":"tâm hồn"},{"hanzi":"精神","pinyin":"jīngshén","vi":"tinh thần"},{"hanzi":"肉体","pinyin":"ròutǐ","vi":"thể xác"},{"hanzi":"灵魂人物","pinyin":"línghúnrénwù","vi":"nhân vật linh hồn"}],"traditional":"靈魂"},{"id":"玲珑剔透","hanzi":"玲珑剔透","pinyin":"línglóng-tītòu","meaning_vi":"tinh xảo sắc sảo, thông minh lanh lợi","explanation":"玲珑 (linh lung – tinh xảo) + 剔透 (thích thấu – trong suốt) → đồ vật chạm trổ tinh xảo, trong trẻo; cũng khen người thông minh lanh lợi.","hsk_level":6,"tags":["thanh-ngu"],"image":"💎","examples":[{"type":"basic","zh":"这块玉玲珑剔透。","pinyin":"Zhè kuài yù línglóngtītòu.","vi":"Miếng ngọc này tinh xảo trong suốt."},{"type":"simple","zh":"姑娘手里捧着一只玲珑剔透的水晶球。","pinyin":"Gūniang shǒulǐ pěngzhe yì zhī línglóngtītòu de shuǐjīngqiú.","vi":"Cô gái nâng trên tay một quả cầu pha lê tinh xảo lấp lánh."},{"type":"compound","zh":"这个孩子不但长得可爱，而且心思玲珑剔透。","pinyin":"Zhè gè háizi búdàn zhǎngde kě'ài, érqiě xīnsi línglóngtītòu.","vi":"Đứa trẻ này không những dễ thương mà còn thông minh lanh lợi."}],"related":[{"hanzi":"小巧玲珑","pinyin":"xiǎoqiǎolínglóng","vi":"nhỏ nhắn xinh xắn"},{"hanzi":"精致","pinyin":"jīngzhì","vi":"tinh xảo"},{"hanzi":"晶莹剔透","pinyin":"jīngyíngtītòu","vi":"trong suốt long lanh"},{"hanzi":"聪明伶俐","pinyin":"cōngmínglínglì","vi":"thông minh lanh lợi"}],"traditional":"玲瓏剔透"},{"id":"龙飞凤舞","hanzi":"龙飞凤舞","pinyin":"lóngfēi-fèngwǔ","meaning_vi":"rồng bay phượng múa (chữ viết phóng khoáng)","explanation":"Rồng bay phượng múa → nét chữ thư pháp phóng khoáng, bay bổng sinh động; đôi khi đùa chữ viết nguệch ngoạc khó đọc.","hsk_level":6,"tags":["thanh-ngu","van-hoa"],"image":"🐉","examples":[{"type":"basic","zh":"他的字龙飞凤舞。","pinyin":"Tā de zì lóngfēifèngwǔ.","vi":"Chữ của anh ấy như rồng bay phượng múa."},{"type":"simple","zh":"书法家在宣纸上写下龙飞凤舞的四个大字。","pinyin":"Shūfǎjiā zài xuānzhǐ shàng xiěxià lóngfēifèngwǔ de sì gè dà zì.","vi":"Nhà thư pháp viết lên giấy Tuyên bốn chữ lớn như rồng bay phượng múa."},{"type":"compound","zh":"因为医生的处方写得龙飞凤舞，所以我一个字也看不懂。","pinyin":"Yīnwèi yīshēng de chǔfāng xiě de lóngfēifèngwǔ, suǒyǐ wǒ yí gè zì yě kànbùdǒng.","vi":"Vì đơn thuốc bác sĩ viết như rồng bay phượng múa nên tôi không đọc được chữ nào."}],"related":[{"hanzi":"笔走龙蛇","pinyin":"bǐzǒulóngshé","vi":"nét bút bay bổng"},{"hanzi":"书法","pinyin":"shūfǎ","vi":"thư pháp"},{"hanzi":"潦草","pinyin":"liáocǎo","vi":"cẩu thả"},{"hanzi":"工整","pinyin":"gōngzhěng","vi":"ngay ngắn"}],"traditional":"龍飛鳳舞"},{"id":"路不拾遗","hanzi":"路不拾遗","pinyin":"lùbù-shíyí","meaning_vi":"của rơi ngoài đường không ai nhặt (xã hội thái bình)","explanation":"Của rơi trên đường không ai nhặt lấy → xã hội có đạo đức, trị an tốt. Thường đi với 夜不闭户 (đêm không cần đóng cửa).","hsk_level":6,"tags":["thanh-ngu","xa-hoi"],"image":"🕊️","examples":[{"type":"basic","zh":"当时路不拾遗。","pinyin":"Dāngshí lùbùshíyí.","vi":"Thời đó của rơi ngoài đường không ai nhặt."},{"type":"simple","zh":"古书中描写了一个路不拾遗的太平盛世。","pinyin":"Gǔshū zhōng miáoxiěle yí gè lùbùshíyí de tàipíng shèngshì.","vi":"Sách cổ miêu tả một thời thái bình thịnh trị, của rơi không ai nhặt."},{"type":"compound","zh":"如果人人都讲诚信，社会就能做到路不拾遗。","pinyin":"Rúguǒ rénrén dōu jiǎng chéngxìn, shèhuì jiù néng zuòdào lùbùshíyí.","vi":"Nếu ai cũng giữ chữ tín thì xã hội có thể đạt đến cảnh của rơi không ai nhặt."}],"related":[{"hanzi":"夜不闭户","pinyin":"yèbúbìhù","vi":"đêm không đóng cửa"},{"hanzi":"太平盛世","pinyin":"tàipíngshèngshì","vi":"thời thái bình thịnh trị"},{"hanzi":"安居乐业","pinyin":"ānjūlèyè","vi":"an cư lạc nghiệp"},{"hanzi":"治安","pinyin":"zhì'ān","vi":"trị an"}],"traditional":"路不拾遺"},{"id":"论证","hanzi":"论证","pinyin":"lùnzhèng","meaning_vi":"luận chứng","explanation":"论 (luận – bàn) + 证 (chứng – chứng minh) → dùng lý lẽ, chứng cứ để chứng minh; cũng là thẩm định tính khả thi. Thường: 论证观点, 可行性论证.","hsk_level":6,"tags":["dong-tu"],"image":"📑","examples":[{"type":"basic","zh":"他论证了这个观点。","pinyin":"Tā lùnzhèngle zhè gè guāndiǎn.","vi":"Ông ấy đã luận chứng quan điểm này."},{"type":"simple","zh":"专家们花了两年时间论证这个工程的可行性。","pinyin":"Zhuānjiāmen huāle liǎng nián shíjiān lùnzhèng zhè gè gōngchéng de kěxíngxìng.","vi":"Các chuyên gia mất hai năm để luận chứng tính khả thi của công trình này."},{"type":"compound","zh":"虽然他的结论很新颖，但是论证过程不够严密。","pinyin":"Suīrán tā de jiélùn hěn xīnyǐng, dànshì lùnzhèng guòchéng búgòu yánmì.","vi":"Tuy kết luận của anh ấy rất mới mẻ nhưng quá trình luận chứng chưa đủ chặt chẽ."}],"related":[{"hanzi":"论据","pinyin":"lùnjù","vi":"luận cứ"},{"hanzi":"论点","pinyin":"lùndiǎn","vi":"luận điểm"},{"hanzi":"证明","pinyin":"zhèngmíng","vi":"chứng minh"},{"hanzi":"推理","pinyin":"tuīlǐ","vi":"suy luận"}],"traditional":"論證"},{"id":"炉火纯青","hanzi":"炉火纯青","pinyin":"lúhuǒ-chúnqīng","meaning_vi":"đạt đến trình độ điêu luyện hoàn hảo","explanation":"Lửa lò luyện đan chuyển sang màu xanh thuần là lúc đan thành (Đạo gia) → kỹ năng, học vấn đạt đến mức tinh thông điêu luyện.","hsk_level":6,"tags":["thanh-ngu"],"image":"🔥","examples":[{"type":"basic","zh":"他的厨艺炉火纯青。","pinyin":"Tā de chúyì lúhuǒchúnqīng.","vi":"Tay nghề nấu ăn của anh ấy đã đạt mức điêu luyện."},{"type":"simple","zh":"老木匠的雕刻技艺已经达到炉火纯青的地步。","pinyin":"Lǎo mùjiàng de diāokè jìyì yǐjīng dádào lúhuǒchúnqīng de dìbù.","vi":"Kỹ thuật chạm khắc của bác thợ mộc già đã đạt đến mức điêu luyện hoàn hảo."},{"type":"compound","zh":"只要你每天坚持练琴，琴艺总有一天会炉火纯青。","pinyin":"Zhǐyào nǐ měitiān jiānchí liàn qín, qín yì zǒngyǒu yì tiān huì lúhuǒchúnqīng.","vi":"Chỉ cần bạn kiên trì luyện đàn mỗi ngày, sẽ có ngày kỹ năng chơi đàn của bạn đạt đến độ điêu luyện."}],"related":[{"hanzi":"出神入化","pinyin":"chūshénrùhuà","vi":"xuất thần nhập hóa"},{"hanzi":"登峰造极","pinyin":"dēngfēngzàojí","vi":"đạt đến đỉnh cao"},{"hanzi":"精湛","pinyin":"jīngzhàn","vi":"điêu luyện"},{"hanzi":"熟能生巧","pinyin":"shúnéngshēngqiǎo","vi":"có công mài sắt"}],"traditional":"爐火純青"},{"id":"轮船","hanzi":"轮船","pinyin":"lúnchuán","meaning_vi":"tàu thủy","explanation":"轮 (luân – bánh xe) + 船 (thuyền) → tàu thủy chạy bằng máy (xưa dùng bánh guồng). Lượng từ: 一艘轮船.","hsk_level":6,"tags":["danh-tu","giao-thong"],"image":"🚢","examples":[{"type":"basic","zh":"轮船靠岸了。","pinyin":"Lúnchuán kào'àn le.","vi":"Tàu thủy đã cập bờ."},{"type":"simple","zh":"我们坐轮船从上海到了青岛。","pinyin":"Wǒmen zuò lúnchuán cóng Shànghǎi dàole Qīngdǎo.","vi":"Chúng tôi đi tàu thủy từ Thượng Hải đến Thanh Đảo."},{"type":"compound","zh":"虽然坐轮船比坐飞机慢，但是可以欣赏海上风景。","pinyin":"Suīrán zuò lúnchuán bǐ zuòfēijī màn, dànshì kěyǐ xīnshǎng hǎishàng fēngjǐng.","vi":"Tuy đi tàu thủy chậm hơn đi máy bay nhưng có thể ngắm cảnh biển."}],"related":[{"hanzi":"船","pinyin":"chuán","vi":"thuyền"},{"hanzi":"游轮","pinyin":"yóulún","vi":"tàu du lịch"},{"hanzi":"码头","pinyin":"mǎtou","vi":"bến tàu"},{"hanzi":"渡轮","pinyin":"dùlún","vi":"phà"}],"traditional":"輪船"},{"id":"冷嘲热讽","hanzi":"冷嘲热讽","pinyin":"lěngcháo-rèfěng","meaning_vi":"châm biếm mỉa mai chua cay","explanation":"冷嘲 (chế giễu lạnh lùng) + 热讽 (châm chọc gay gắt) → mỉa mai, châm biếm cay độc.","hsk_level":6,"tags":["thanh-ngu"],"image":"😏","examples":[{"type":"basic","zh":"别冷嘲热讽了。","pinyin":"Bié lěngcháorèfěng le.","vi":"Đừng mỉa mai châm chọc nữa."},{"type":"simple","zh":"他受不了邻居整天的冷嘲热讽。","pinyin":"Tā shòubùliǎo línjū zhěngtiān de lěngcháorèfěng.","vi":"Anh ấy không chịu nổi những lời mỉa mai chua cay suốt ngày của hàng xóm."},{"type":"compound","zh":"即使别人冷嘲热讽，她也坚持自己的梦想。","pinyin":"Jíshǐ biérén lěngcháorèfěng, tā yě jiānchí zìjǐ de mèngxiǎng.","vi":"Dù người khác mỉa mai châm chọc, cô ấy vẫn kiên trì với ước mơ của mình."}],"related":[{"hanzi":"冷言冷语","pinyin":"lěngyánlěngyǔ","vi":"lời lẽ lạnh lùng"},{"hanzi":"讽刺","pinyin":"fěngcì","vi":"châm biếm"},{"hanzi":"挖苦","pinyin":"wāku","vi":"chế giễu"},{"hanzi":"嘲笑","pinyin":"cháoxiào","vi":"chế nhạo"}],"traditional":"冷嘲熱諷"},{"id":"冷却","hanzi":"冷却","pinyin":"lěngquè","meaning_vi":"làm nguội","explanation":"冷 (lãnh – lạnh) + 却 (khước – lùi, giảm) → làm nguội, hạ nhiệt; nghĩa bóng: tình cảm, phong trào nguội đi. Thường: 冷却水, 冷却系统.","hsk_level":6,"tags":["dong-tu"],"image":"🧊","examples":[{"type":"basic","zh":"让汤冷却一下。","pinyin":"Ràng tāng lěngquè yíxià.","vi":"Để canh nguội đi một chút."},{"type":"simple","zh":"工人用水冷却刚出炉的钢板。","pinyin":"Gōngrén yòng shuǐ lěngquè gāng chūlú de gāngbǎn.","vi":"Công nhân dùng nước làm nguội tấm thép vừa ra lò."},{"type":"compound","zh":"如果发动机不能及时冷却，就可能烧坏。","pinyin":"Rúguǒ fādòngjī bù néng jíshí lěngquè, jiù kěnéng shāo huài.","vi":"Nếu động cơ không được làm nguội kịp thời thì có thể bị cháy hỏng."}],"related":[{"hanzi":"降温","pinyin":"jiàngwēn","vi":"hạ nhiệt"},{"hanzi":"冷却水","pinyin":"lěngquèshuǐ","vi":"nước làm mát"},{"hanzi":"加热","pinyin":"jiārè","vi":"đun nóng"},{"hanzi":"冷静","pinyin":"lěngjìng","vi":"bình tĩnh"}],"traditional":"冷卻"},{"id":"老马识途","hanzi":"老马识途","pinyin":"lǎomǎ-shítú","meaning_vi":"ngựa già quen đường (người có kinh nghiệm dẫn dắt)","explanation":"Ngựa già biết đường (Quản Trọng lạc đường khi đánh nước Cô Trúc, thả ngựa già dẫn lối) → người từng trải, giàu kinh nghiệm dẫn dắt được người khác.","hsk_level":6,"tags":["thanh-ngu"],"image":"🐎","examples":[{"type":"basic","zh":"这叫老马识途。","pinyin":"Zhè jiào lǎomǎshítú.","vi":"Cái này gọi là ngựa già quen đường."},{"type":"simple","zh":"这次登山多亏了老马识途的向导。","pinyin":"Zhè cì dēngshān duōkuīle lǎomǎshítú de xiàngdǎo.","vi":"Chuyến leo núi lần này may nhờ có người dẫn đường già dặn kinh nghiệm."},{"type":"compound","zh":"既然王师傅老马识途，我们就跟着他走吧。","pinyin":"Jìrán Wáng shīfu lǎomǎshítú, wǒmen jiù gēnzhe tā zǒu ba.","vi":"Bác Vương đã là ngựa già quen đường thì chúng ta cứ đi theo bác ấy thôi."}],"related":[{"hanzi":"经验丰富","pinyin":"jīngyànfēngfù","vi":"giàu kinh nghiệm"},{"hanzi":"识途老马","pinyin":"shítúlǎomǎ","vi":"người từng trải"},{"hanzi":"老手","pinyin":"lǎoshǒu","vi":"tay lão luyện"},{"hanzi":"新手","pinyin":"xīnshǒu","vi":"người mới"}],"traditional":"老馬識途"},{"id":"礼尚往来","hanzi":"礼尚往来","pinyin":"lǐshàng-wǎnglái","meaning_vi":"có đi có lại mới toại lòng nhau","explanation":"Lễ nghĩa coi trọng sự qua lại (sách Lễ Ký) → có đi có lại; được người đối tốt thì đáp lại, đôi khi cũng mang ý ăn miếng trả miếng.","hsk_level":6,"tags":["thanh-ngu","giao-tiep"],"image":"🎁","examples":[{"type":"basic","zh":"中国人讲究礼尚往来。","pinyin":"Zhōngguórén jiǎngjiu lǐshàngwǎnglái.","vi":"Người Trung Quốc coi trọng có đi có lại."},{"type":"simple","zh":"朋友之间的礼尚往来能加深感情。","pinyin":"Péngyou zhījiān de lǐshàngwǎnglái néng jiāshēn gǎnqíng.","vi":"Có qua có lại giữa bạn bè có thể làm sâu sắc tình cảm."},{"type":"compound","zh":"因为他上次请我吃了饭，所以这次我也要礼尚往来。","pinyin":"Yīnwèi tā shàngcì qǐng wǒ chīle fàn, suǒyǐ zhè cì wǒ yě yào lǐshàngwǎnglái.","vi":"Vì lần trước anh ấy mời tôi ăn cơm nên lần này tôi cũng phải có đi có lại."}],"related":[{"hanzi":"有来有往","pinyin":"yǒuláiyǒuwǎng","vi":"có đi có lại"},{"hanzi":"投桃报李","pinyin":"tóutáobàolǐ","vi":"có qua có lại"},{"hanzi":"礼物","pinyin":"lǐwù","vi":"quà tặng"},{"hanzi":"回礼","pinyin":"huílǐ","vi":"đáp lễ"}],"traditional":"禮尚往來"},{"id":"理直气壮","hanzi":"理直气壮","pinyin":"lǐzhí-qìzhuàng","meaning_vi":"lý lẽ vững vàng","explanation":"理直 (lý lẽ ngay thẳng) + 气壮 (khí thế mạnh) → tự tin, hùng hồn vì biết mình có lý. Thường: 理直气壮地说.","hsk_level":6,"tags":["thanh-ngu"],"image":"✊","examples":[{"type":"basic","zh":"他说得理直气壮。","pinyin":"Tā shuō de lǐzhíqìzhuàng.","vi":"Anh ấy nói rất hùng hồn, đầy lý lẽ."},{"type":"simple","zh":"犯了错的小王居然理直气壮地反驳经理。","pinyin":"Fànle cuò de xiǎo Wáng jūrán lǐzhíqìzhuàng de fǎnbó jīnglǐ.","vi":"Tiểu Vương phạm lỗi mà lại hùng hồn cãi lại giám đốc."},{"type":"compound","zh":"只要你没做错事，就可以理直气壮地说出来。","pinyin":"Zhǐyào nǐ méi zuò cuòshì, jiù kěyǐ lǐzhíqìzhuàng de shuō chūlái.","vi":"Chỉ cần bạn không làm sai thì có thể đường hoàng nói ra."}],"related":[{"hanzi":"振振有词","pinyin":"zhènzhènyǒucí","vi":"nói năng hùng hồn"},{"hanzi":"心安理得","pinyin":"xīn'ānlǐdé","vi":"yên lòng thanh thản"},{"hanzi":"理亏","pinyin":"lǐkuī","vi":"đuối lý"},{"hanzi":"理屈词穷","pinyin":"lǐqūcíqióng","vi":"đuối lý hết lời"}],"traditional":"理直氣壯"},{"id":"领会","hanzi":"领会","pinyin":"lǐnghuì","meaning_vi":"lĩnh hội","explanation":"领 (lĩnh – nhận) + 会 (hội – hiểu) → lĩnh hội, nắm được ý nghĩa. Thường: 领会精神, 领会意图.","hsk_level":6,"tags":["dong-tu"],"image":"🧠","examples":[{"type":"basic","zh":"我领会了你的意思。","pinyin":"Wǒ lǐnghuìle nǐ de yìsi.","vi":"Tôi đã hiểu ý của bạn."},{"type":"simple","zh":"学生们很快就领会了这道题的解法。","pinyin":"Xuéshengmen hěn kuài jiù lǐnghuìle zhè dào tí de jiěfǎ.","vi":"Học sinh nhanh chóng lĩnh hội cách giải bài này."},{"type":"compound","zh":"只有认真读原文，才能领会作者的真正用意。","pinyin":"Zhǐyǒu rènzhēn dú yuánwén, cáinéng lǐnghuì zuòzhě de zhēnzhèng yòngyì.","vi":"Chỉ có đọc kỹ nguyên văn mới lĩnh hội được dụng ý thật sự của tác giả."}],"related":[{"hanzi":"理解","pinyin":"lǐjiě","vi":"hiểu"},{"hanzi":"领悟","pinyin":"lǐngwù","vi":"lĩnh ngộ"},{"hanzi":"体会","pinyin":"tǐhuì","vi":"thể nghiệm"},{"hanzi":"心领神会","pinyin":"xīnlǐngshénhuì","vi":"hiểu ý ngầm"}],"traditional":"領會"},{"id":"领悟","hanzi":"领悟","pinyin":"lǐngwù","meaning_vi":"lĩnh ngộ","explanation":"领 (lĩnh – nhận) + 悟 (ngộ – tỉnh ngộ, hiểu ra) → hiểu thấu, ngộ ra điều sâu sắc. So với 领会, 领悟 thiên về tự mình giác ngộ.","hsk_level":6,"tags":["dong-tu"],"image":"💡","examples":[{"type":"basic","zh":"他终于领悟了。","pinyin":"Tā zhōngyú lǐngwù le.","vi":"Cuối cùng anh ấy đã ngộ ra."},{"type":"simple","zh":"老人在病床上领悟到了健康的可贵。","pinyin":"Lǎorén zài bìngchuáng shàng lǐngwù dàole jiànkāng de kěguì.","vi":"Ông lão nằm trên giường bệnh mới ngộ ra sức khỏe quý giá thế nào."},{"type":"compound","zh":"直到当了父亲，他才领悟到父母的辛苦。","pinyin":"Zhídào dāngle fùqīn, tā cái lǐngwù dào fùmǔ de xīnkǔ.","vi":"Mãi đến khi làm cha, anh ấy mới thấu hiểu nỗi vất vả của cha mẹ."}],"related":[{"hanzi":"领会","pinyin":"lǐnghuì","vi":"lĩnh hội"},{"hanzi":"觉悟","pinyin":"juéwù","vi":"giác ngộ"},{"hanzi":"感悟","pinyin":"gǎnwù","vi":"cảm ngộ"},{"hanzi":"醒悟","pinyin":"xǐngwù","vi":"tỉnh ngộ"}],"traditional":"領悟"},{"id":"笼罩","hanzi":"笼罩","pinyin":"lǒngzhào","meaning_vi":"bao trùm","explanation":"笼 (lung – lồng, bao phủ) + 罩 (tráo – trùm lên) → bao trùm, phủ kín. Thường: 雾气笼罩, 笼罩在悲伤中.","hsk_level":6,"tags":["dong-tu"],"image":"🌫️","examples":[{"type":"basic","zh":"大雾笼罩着城市。","pinyin":"Dàwù lǒngzhàozhe chéngshì.","vi":"Sương mù dày đặc bao trùm thành phố."},{"type":"simple","zh":"整个山谷都笼罩在一片薄雾之中。","pinyin":"Zhěnggè shāngǔ dōu lǒngzhào zài yípiàn bówù zhīzhōng.","vi":"Cả thung lũng đều bao phủ trong một làn sương mỏng."},{"type":"compound","zh":"一听到失事的消息，全村就笼罩在悲伤里。","pinyin":"Yì tīngdào shīshì de xiāoxi, quán cūn jiù lǒngzhào zài bēishāng lǐ.","vi":"Vừa nghe tin tai nạn, cả làng liền chìm trong đau thương."}],"related":[{"hanzi":"覆盖","pinyin":"fùgài","vi":"che phủ"},{"hanzi":"弥漫","pinyin":"mímàn","vi":"tràn ngập"},{"hanzi":"包围","pinyin":"bāowéi","vi":"bao vây"},{"hanzi":"烟雾笼罩","pinyin":"yānwùlǒngzhào","vi":"khói sương bao phủ"}],"traditional":"籠罩"},{"id":"屡次","hanzi":"屡次","pinyin":"lǚcì","meaning_vi":"nhiều lần","explanation":"屡 (lũ – nhiều lần) + 次 (thứ – lần) → hết lần này đến lần khác. Thường: 屡次犯错, 屡次获奖; gần nghĩa 多次.","hsk_level":6,"tags":["pho-tu"],"image":"🔁","examples":[{"type":"basic","zh":"他屡次迟到。","pinyin":"Tā lǚcì chídào.","vi":"Anh ta nhiều lần đi muộn."},{"type":"simple","zh":"这名运动员屡次打破全国纪录。","pinyin":"Zhè míng yùndòngyuán lǚcì dǎpò quánguó jìlù.","vi":"Vận động viên này nhiều lần phá kỷ lục quốc gia."},{"type":"compound","zh":"虽然我屡次提醒他，但是他还是忘了带钥匙。","pinyin":"Suīrán wǒ lǚcì tíxǐng tā, dànshì tā háishì wàngle dài yàoshi.","vi":"Tuy tôi đã nhắc nhiều lần nhưng anh ấy vẫn quên mang chìa khóa."}],"related":[{"hanzi":"多次","pinyin":"duōcì","vi":"nhiều lần"},{"hanzi":"屡屡","pinyin":"lǚlǚ","vi":"nhiều lần"},{"hanzi":"一再","pinyin":"yízài","vi":"hết lần này đến lần khác"},{"hanzi":"屡教不改","pinyin":"lǚjiàobùgǎi","vi":"dạy mãi không sửa"}],"traditional":"屢次"},{"id":"面红耳赤","hanzi":"面红耳赤","pinyin":"miànhóng-ěrchì","meaning_vi":"đỏ mặt tía tai (vì ngại hoặc tranh cãi)","explanation":"Mặt đỏ, tai đỏ → đỏ mặt tía tai vì xấu hổ, tức giận hoặc tranh cãi gay gắt. Thường: 争得面红耳赤.","hsk_level":6,"tags":["thanh-ngu"],"image":"😳","examples":[{"type":"basic","zh":"他们争得面红耳赤。","pinyin":"Tāmen zhēngde miànhóng'ěrchì.","vi":"Họ cãi nhau đỏ mặt tía tai."},{"type":"simple","zh":"害羞的男孩被问得面红耳赤。","pinyin":"Hàixiū de nánhái bèi wèn de miànhóng'ěrchì.","vi":"Cậu bé nhút nhát bị hỏi đến đỏ mặt tía tai."},{"type":"compound","zh":"他一喝酒就面红耳赤，所以很少参加聚会。","pinyin":"Tā yì hējiǔ jiù miànhóng'ěrchì, suǒyǐ hěn shǎo cānjiā jùhuì.","vi":"Anh ấy hễ uống rượu là đỏ mặt tía tai, nên hiếm khi tham gia tiệc tùng."}],"related":[{"hanzi":"脸红","pinyin":"liǎnhóng","vi":"đỏ mặt"},{"hanzi":"害羞","pinyin":"hàixiū","vi":"xấu hổ"},{"hanzi":"争吵","pinyin":"zhēngchǎo","vi":"cãi nhau"},{"hanzi":"恼羞成怒","pinyin":"nǎoxiūchéngnù","vi":"xấu hổ hóa giận"}],"traditional":"面紅耳赤"},{"id":"面貌","hanzi":"面貌","pinyin":"miànmào","meaning_vi":"diện mạo, bộ mặt","explanation":"面 (diện – mặt) + 貌 (mạo – dáng vẻ) → diện mạo con người; nghĩa bóng bộ mặt, tình trạng chung của sự vật. Cụm: 城市面貌, 精神面貌.","hsk_level":6,"tags":["danh-tu"],"image":"🏙️","examples":[{"type":"basic","zh":"照片里的人面貌模糊。","pinyin":"Zhàopiàn lǐ de rén miànmào móhu.","vi":"Diện mạo người trong ảnh mờ không rõ."},{"type":"simple","zh":"这几年家乡的面貌发生了巨大变化。","pinyin":"Zhè jǐ nián jiāxiāng de miànmào fāshēngle jùdà biànhuà.","vi":"Mấy năm nay diện mạo quê hương đã thay đổi rất lớn."},{"type":"compound","zh":"自从修了高速公路，山村的面貌就焕然一新了。","pinyin":"Zìcóng xiūle gāosùgōnglù, shāncūn de miànmào jiù huànrányìxīn le.","vi":"Từ khi làm đường cao tốc, bộ mặt làng núi đã hoàn toàn đổi mới."}],"related":[{"hanzi":"面目","pinyin":"miànmù","vi":"bộ mặt"},{"hanzi":"外貌","pinyin":"wàimào","vi":"ngoại hình"},{"hanzi":"精神面貌","pinyin":"jīngshénmiànmào","vi":"diện mạo tinh thần"},{"hanzi":"面貌一新","pinyin":"miànmàoyìxīn","vi":"diện mạo mới"}]},{"id":"棉花","hanzi":"棉花","pinyin":"miánhua","meaning_vi":"bông (vải/y tế)","explanation":"棉 (cây bông) + 花 (hoa).","hsk_level":6,"tags":["danh-tu","thien-nhien","do-vat"],"image":"☁️","examples":[{"type":"basic","zh":"棉花很柔软。","pinyin":"Miánhua hěn róuruǎn.","vi":"Bông rất mềm."},{"type":"simple","zh":"护士用棉花蘸了点酒精给我消毒。","pinyin":"Hùshi yòng miánhua zhànle diǎn jiǔjīng gěi wǒ xiāodú.","vi":"Y tá dùng bông chấm chút cồn để sát trùng cho tôi."},{"type":"compound","zh":"新疆不但出产葡萄，而且盛产优质棉花。","pinyin":"Xīnjiāng búdàn chūchǎn pútao, érqiě shèngchǎn yōuzhì miánhua.","vi":"Tân Cương không những sản xuất nho mà còn có rất nhiều bông chất lượng cao."}],"related":[{"hanzi":"棉","pinyin":"mián","vi":"bông"},{"hanzi":"棉布","pinyin":"miánbù","vi":"vải bông"},{"hanzi":"棉签","pinyin":"miánqiān","vi":"tăm bông"},{"hanzi":"纯棉","pinyin":"chúnmián","vi":"cotton nguyên chất"}]},{"id":"瞄准","hanzi":"瞄准","pinyin":"miáozhǔn","meaning_vi":"ngắm chuẩn, nhắm mục tiêu","explanation":"瞄 (miêu – nhắm, ngắm) + 准 (chuẩn – chính xác) → ngắm cho trúng; nghĩa bóng nhắm vào mục tiêu, thị trường. Cụm: 瞄准目标.","hsk_level":6,"tags":["dong-tu"],"image":"🎯","examples":[{"type":"basic","zh":"他瞄准了靶心。","pinyin":"Tā miáozhǔnle bǎxīn.","vi":"Anh ấy nhắm chuẩn hồng tâm."},{"type":"simple","zh":"这家公司把目标瞄准了年轻消费者。","pinyin":"Zhè jiā gōngsī bǎ mùbiāo miáozhǔnle niánqīng xiāofèizhě.","vi":"Công ty này nhắm mục tiêu vào người tiêu dùng trẻ."},{"type":"compound","zh":"只要你已经瞄准了球门，就大胆地起脚射门吧。","pinyin":"Zhǐyào nǐ yǐjīng miáozhǔnle qiúmén, jiù dàdǎn de qǐ jiǎo shèmén ba.","vi":"Chỉ cần bạn đã nhắm chuẩn khung thành thì cứ mạnh dạn tung chân sút đi."}],"related":[{"hanzi":"对准","pinyin":"duìzhǔn","vi":"nhắm đúng"},{"hanzi":"目标","pinyin":"mùbiāo","vi":"mục tiêu"},{"hanzi":"射击","pinyin":"shèjī","vi":"bắn"},{"hanzi":"准星","pinyin":"zhǔnxīng","vi":"đầu ruồi"}],"traditional":"瞄準"},{"id":"灭亡","hanzi":"灭亡","pinyin":"mièwáng","meaning_vi":"diệt vong","explanation":"灭 (diệt – tiêu diệt) + 亡 (vong – mất) → bị diệt mà mất hẳn, dùng cho quốc gia, dân tộc, giống loài.","hsk_level":6,"tags":["dong-tu"],"image":"🥀","examples":[{"type":"basic","zh":"秦朝很快灭亡了。","pinyin":"Qíncháo hěn kuài mièwáng le.","vi":"Nhà Tần nhanh chóng diệt vong."},{"type":"simple","zh":"那个古老的王国在战争中走向了灭亡。","pinyin":"Nà gè gǔlǎo de wángguó zài zhànzhēng zhōng zǒuxiàngle mièwáng.","vi":"Vương quốc cổ xưa ấy đã đi đến diệt vong trong chiến tranh."},{"type":"compound","zh":"一个国家如果腐败成风，就迟早会灭亡。","pinyin":"Yí gè guójiā rúguǒ fǔbài chéngfēng, jiù chízǎo huì mièwáng.","vi":"Một quốc gia nếu tham nhũng thành thói thì sớm muộn cũng diệt vong."}],"related":[{"hanzi":"消亡","pinyin":"xiāowáng","vi":"tiêu vong"},{"hanzi":"覆灭","pinyin":"fùmiè","vi":"bị tiêu diệt"},{"hanzi":"兴起","pinyin":"xīngqǐ","vi":"hưng khởi"},{"hanzi":"灭绝","pinyin":"mièjué","vi":"tuyệt chủng"}],"traditional":"滅亡"},{"id":"免得","hanzi":"免得","pinyin":"miǎnde","meaning_vi":"khỏi phải, tránh cho","explanation":"免 (miễn – tránh) + 得 (đắc) → liên từ: để khỏi, để tránh điều không mong muốn, đứng ở vế sau. Ví dụ: 多穿点，免得感冒.","hsk_level":6,"tags":["lien-tu"],"image":"🛡️","examples":[{"type":"basic","zh":"多穿点，免得感冒。","pinyin":"Duō chuān diǎn, miǎnde gǎnmào.","vi":"Mặc thêm áo vào để khỏi bị cảm."},{"type":"simple","zh":"出门前查好路线免得迷路。","pinyin":"Chū ménqián chá hǎo lùxiàn miǎnde mílù.","vi":"Trước khi ra ngoài hãy xem kỹ lộ trình để khỏi lạc đường."},{"type":"compound","zh":"如果晚回家，就提前说一声，免得家人担心。","pinyin":"Rúguǒ wǎn huíjiā, jiù tíqián shuō yìshēng, miǎnde jiārén dānxīn.","vi":"Nếu về nhà muộn thì báo trước một tiếng, để người nhà khỏi lo."}],"related":[{"hanzi":"以免","pinyin":"yǐmiǎn","vi":"để tránh"},{"hanzi":"省得","pinyin":"shěngde","vi":"đỡ phải"},{"hanzi":"避免","pinyin":"bìmiǎn","vi":"tránh"},{"hanzi":"防止","pinyin":"fángzhǐ","vi":"ngăn ngừa"}]},{"id":"勉励","hanzi":"勉励","pinyin":"miǎnlì","meaning_vi":"khích lệ, động viên","explanation":"勉 (gắng sức) + 励 (cổ vũ).","hsk_level":6,"tags":["dong-tu","giao-tiep"],"image":"👏","examples":[{"type":"basic","zh":"老师勉励我们。","pinyin":"Lǎoshī miǎnlì wǒmen.","vi":"Thầy giáo động viên chúng tôi."},{"type":"simple","zh":"校长勉励毕业生要勇敢追求梦想。","pinyin":"Xiàozhǎng miǎnlì bìyèshēng yào yǒnggǎn zhuīqiú mèngxiǎng.","vi":"Hiệu trưởng khích lệ học sinh tốt nghiệp dũng cảm theo đuổi ước mơ."},{"type":"compound","zh":"虽然这次比赛输了，但是教练还是勉励大家继续努力。","pinyin":"Suīrán zhè cì bǐsài shū le, dànshì jiàoliàn háishì miǎnlì dàjiā jìxù nǔlì.","vi":"Tuy trận này thua nhưng huấn luyện viên vẫn động viên mọi người tiếp tục cố gắng."}],"related":[{"hanzi":"鼓励","pinyin":"gǔlì","vi":"khích lệ"},{"hanzi":"激励","pinyin":"jīlì","vi":"khuyến khích"},{"hanzi":"鞭策","pinyin":"biāncè","vi":"thúc giục"},{"hanzi":"打击","pinyin":"dǎjī","vi":"đả kích"}],"traditional":"勉勵"},{"id":"迈进","hanzi":"迈进","pinyin":"màijìn","meaning_vi":"tiến bước, sải bước tiến tới","explanation":"迈 (bước) + 进 (tiến lên).","hsk_level":6,"tags":["dong-tu"],"image":"🚀","examples":[{"type":"basic","zh":"我们大步迈进。","pinyin":"Wǒmen dàbù màijìn.","vi":"Chúng ta sải bước tiến lên."},{"type":"simple","zh":"这座城市正向国际化大都市迈进。","pinyin":"Zhè zuò chéngshì zhèngxiàng guójìhuà dàdūshì màijìn.","vi":"Thành phố này đang tiến bước trở thành đô thị lớn mang tầm quốc tế."},{"type":"compound","zh":"只要全体员工齐心协力，公司就能向新目标迈进。","pinyin":"Zhǐyào quántǐ yuángōng qíxīnxiélì, gōngsī jiù néng xiàng xīn mùbiāo màijìn.","vi":"Chỉ cần toàn thể nhân viên đồng lòng hiệp sức, công ty sẽ tiến tới mục tiêu mới."}],"related":[{"hanzi":"前进","pinyin":"qiánjìn","vi":"tiến lên"},{"hanzi":"迈步","pinyin":"màibù","vi":"bước đi"},{"hanzi":"跨越","pinyin":"kuàyuè","vi":"vượt qua"},{"hanzi":"倒退","pinyin":"dàotuì","vi":"thụt lùi"}],"traditional":"邁進"},{"id":"漫不经心","hanzi":"漫不经心","pinyin":"mànbù-jīngxīn","meaning_vi":"lơ đễnh, thờ ơ không để tâm","explanation":"漫 (mạn – tùy tiện) + 不经心 (không để tâm) → lơ đễnh, hời hợt, chẳng chú ý gì. Thường: 漫不经心地回答.","hsk_level":6,"tags":["thanh-ngu"],"image":"🙈","examples":[{"type":"basic","zh":"他做事漫不经心。","pinyin":"Tā zuòshì mànbùjīngxīn.","vi":"Anh ta làm việc lơ đễnh."},{"type":"simple","zh":"她漫不经心地翻着手里的杂志。","pinyin":"Tā mànbùjīngxīn de fān zheshǒu lǐ de zázhì.","vi":"Cô ấy hờ hững lật cuốn tạp chí trên tay."},{"type":"compound","zh":"因为司机开车漫不经心，所以撞上了路边的栏杆。","pinyin":"Yīnwèi sījī kāichē mànbùjīngxīn, suǒyǐ zhuàngshàngle lùbiān de lángān.","vi":"Vì tài xế lái xe lơ đễnh nên đã đâm vào lan can bên đường."}],"related":[{"hanzi":"心不在焉","pinyin":"xīnbúzàiyān","vi":"lơ đãng"},{"hanzi":"粗心大意","pinyin":"cūxīndàyì","vi":"cẩu thả"},{"hanzi":"全神贯注","pinyin":"quánshénguànzhù","vi":"tập trung cao độ"},{"hanzi":"一丝不苟","pinyin":"yìsībùgǒu","vi":"tỉ mỉ cẩn thận"}],"traditional":"漫不經心"},{"id":"漫无边际","hanzi":"漫无边际","pinyin":"mànwú-biānjì","meaning_vi":"mênh mông vô tận, lan man không bờ bến","explanation":"漫 (tràn ra) + 无边际 (không bờ bến) → mênh mông vô tận; nghĩa bóng: nói, viết lan man xa đề.","hsk_level":6,"tags":["thanh-ngu"],"image":"🌊","examples":[{"type":"basic","zh":"草原漫无边际。","pinyin":"Cǎoyuán mànwúbiānjì.","vi":"Thảo nguyên mênh mông vô tận."},{"type":"simple","zh":"他在会上漫无边际地讲了一个小时。","pinyin":"Tā zài huì shàng mànwúbiānjì de jiǎngle yí gè xiǎoshí.","vi":"Anh ta nói lan man không đầu không cuối suốt một tiếng trong cuộc họp."},{"type":"compound","zh":"如果写作文时漫无边际，就很难得到高分。","pinyin":"Rúguǒ xiě zuòwén shí mànwúbiānjì, jiù hěn nándé dào gāofēn.","vi":"Nếu viết văn lan man không trọng tâm thì rất khó được điểm cao."}],"related":[{"hanzi":"无边无际","pinyin":"wúbiānwújì","vi":"vô bờ vô bến"},{"hanzi":"漫无目的","pinyin":"mànwúmùdì","vi":"không mục đích"},{"hanzi":"海阔天空","pinyin":"hǎikuòtiānkōng","vi":"trên trời dưới biển"},{"hanzi":"言简意赅","pinyin":"yánjiǎnyìgāi","vi":"lời ngắn ý đủ"}],"traditional":"漫無邊際"},{"id":"慢性","hanzi":"慢性","pinyin":"mànxìng","meaning_vi":"mãn tính","explanation":"慢 (mạn – chậm) + 性 (tính – tính chất) → có tính kéo dài, phát triển chậm; trái nghĩa 急性 (cấp tính). Cụm: 慢性病.","hsk_level":6,"tags":["tinh-tu","suc-khoe"],"image":"🩺","examples":[{"type":"basic","zh":"他有慢性胃炎。","pinyin":"Tā yǒu mànxìng wèiyán.","vi":"Ông ấy bị viêm dạ dày mãn tính."},{"type":"simple","zh":"长期熬夜容易导致各种慢性疾病。","pinyin":"Chángqī áoyè róngyì dǎozhì gèzhǒng mànxìng jíbìng.","vi":"Thức khuya lâu ngày dễ dẫn đến các bệnh mãn tính."},{"type":"compound","zh":"慢性病虽然不会马上致命，但是需要长期治疗。","pinyin":"Mànxìngbìng suīrán bú huì mǎshàng zhìmìng, dànshì xūyào chángqī zhìliáo.","vi":"Bệnh mãn tính tuy không gây chết người ngay nhưng cần điều trị lâu dài."}],"related":[{"hanzi":"急性","pinyin":"jíxìng","vi":"cấp tính"},{"hanzi":"慢性病","pinyin":"mànxìngbìng","vi":"bệnh mãn tính"},{"hanzi":"慢性子","pinyin":"mànxìngzi","vi":"người chậm chạp"},{"hanzi":"长期","pinyin":"chángqī","vi":"lâu dài"}]},{"id":"冒充","hanzi":"冒充","pinyin":"màochōng","meaning_vi":"giả mạo, mạo danh","explanation":"冒 (mạo – giả mạo) + 充 (sung – đóng vai, thế vào) → giả làm người hoặc vật khác để lừa gạt. Cụm: 冒充警察, 冒充名牌.","hsk_level":6,"tags":["dong-tu","phap-luat"],"image":"🎭","examples":[{"type":"basic","zh":"他冒充警察。","pinyin":"Tā màochōng jǐngchá.","vi":"Hắn giả danh cảnh sát."},{"type":"simple","zh":"骗子冒充银行职员给老人打电话。","pinyin":"Piànzi màochōng yínháng zhíyuán gěi lǎorén dǎdiànhuà.","vi":"Kẻ lừa đảo giả danh nhân viên ngân hàng gọi điện cho người già."},{"type":"compound","zh":"如果有人冒充快递员敲门，就千万别开门。","pinyin":"Rúguǒ yǒurén màochōng kuàidìyuán qiāomén, jiù qiānwàn bié kāimén.","vi":"Nếu có người giả làm nhân viên giao hàng gõ cửa thì tuyệt đối đừng mở cửa."}],"related":[{"hanzi":"假冒","pinyin":"jiǎmào","vi":"giả mạo"},{"hanzi":"冒名顶替","pinyin":"màomíngdǐngtì","vi":"mạo danh thay thế"},{"hanzi":"伪装","pinyin":"wěizhuāng","vi":"ngụy trang"},{"hanzi":"冒牌","pinyin":"màopái","vi":"hàng nhái"}]},{"id":"冒犯","hanzi":"冒犯","pinyin":"màofàn","meaning_vi":"mạo phạm, xúc phạm","explanation":"冒 + 犯 (phạm phải).","hsk_level":6,"tags":["dong-tu","giao-tiep"],"image":"🙇","examples":[{"type":"basic","zh":"多有冒犯，请原谅。","pinyin":"Duō yǒu màofàn, qǐng yuánliàng.","vi":"Có nhiều điều mạo phạm, xin thứ lỗi."},{"type":"simple","zh":"我刚才的玩笑可能冒犯了您。","pinyin":"Wǒ gāngcái de wánxiào kěnéng màofànle nín.","vi":"Câu đùa vừa rồi của tôi có thể đã xúc phạm ngài."},{"type":"compound","zh":"在国外旅行时，如果不了解当地习俗，就容易冒犯别人。","pinyin":"Zài guówài lǚxíng shí, rúguǒ bù liǎojiě dāngdì xísú, jiù róngyì màofàn biérén.","vi":"Khi du lịch nước ngoài, nếu không hiểu phong tục địa phương thì dễ xúc phạm người khác."}],"related":[{"hanzi":"得罪","pinyin":"dézuì","vi":"đắc tội"},{"hanzi":"冒昧","pinyin":"màomèi","vi":"đường đột"},{"hanzi":"侵犯","pinyin":"qīnfàn","vi":"xâm phạm"},{"hanzi":"失礼","pinyin":"shīlǐ","vi":"thất lễ"}]},{"id":"茂密","hanzi":"茂密","pinyin":"màomì","meaning_vi":"rậm rạp (rừng cây/tóc)","explanation":"茂 (tươi tốt) + 密 (dày đặc).","hsk_level":6,"tags":["tinh-tu","thien-nhien"],"image":"🌲","examples":[{"type":"basic","zh":"森林很茂密。","pinyin":"Sēnlín hěn màomì.","vi":"Khu rừng rất rậm rạp."},{"type":"simple","zh":"小鸟在茂密的树叶间跳来跳去。","pinyin":"Xiǎoniǎo zài màomì de shùyè jiān tiào lái tiào qù.","vi":"Chim nhỏ nhảy nhót giữa tán lá rậm rạp."},{"type":"compound","zh":"这片山林既茂密又潮湿，所以很容易迷路。","pinyin":"Zhè piàn shānlín jì màomì yòu cháoshī, suǒyǐ hěn róngyì mílù.","vi":"Khu rừng núi này vừa rậm rạp vừa ẩm ướt, nên rất dễ lạc đường."}],"related":[{"hanzi":"茂盛","pinyin":"màoshèng","vi":"tươi tốt"},{"hanzi":"浓密","pinyin":"nóngmì","vi":"dày rậm"},{"hanzi":"稀疏","pinyin":"xīshū","vi":"thưa thớt"},{"hanzi":"郁郁葱葱","pinyin":"yùyùcōngcōng","vi":"xanh tươi um tùm"}]},{"id":"麻痹","hanzi":"麻痹","pinyin":"mábì","meaning_vi":"tê liệt, mất cảnh giác","explanation":"麻 (ma – tê) + 痹 (tý – tê bại) → tê liệt cơ thể; nghĩa bóng lơ là, mất cảnh giác. Cụm: 麻痹大意.","hsk_level":6,"tags":["dong-tu","suc-khoe"],"image":"⚠️","examples":[{"type":"basic","zh":"千万不能麻痹大意。","pinyin":"Qiānwàn bù néng mábì dàyì.","vi":"Tuyệt đối không được lơ là mất cảnh giác."},{"type":"simple","zh":"这种蛇毒能迅速麻痹猎物的神经。","pinyin":"Zhè zhǒng shédú néng xùnsù mábì lièwù de shénjīng.","vi":"Nọc của loài rắn này có thể nhanh chóng làm tê liệt thần kinh con mồi."},{"type":"compound","zh":"因为敌人故意示弱来麻痹我们，所以大家更要提高警惕。","pinyin":"Yīnwèi dírén gùyì shìruò lái mábì wǒmen, suǒyǐ dàjiā gèng yào tígāo jǐngtì.","vi":"Vì kẻ địch cố ý tỏ ra yếu để làm chúng ta mất cảnh giác nên mọi người càng phải đề cao cảnh giác."}],"related":[{"hanzi":"麻木","pinyin":"mámù","vi":"tê dại"},{"hanzi":"麻痹大意","pinyin":"mábìdàyì","vi":"chủ quan lơ là"},{"hanzi":"瘫痪","pinyin":"tānhuàn","vi":"bại liệt"},{"hanzi":"警惕","pinyin":"jǐngtì","vi":"cảnh giác"}],"traditional":"麻痺"},{"id":"麻利","hanzi":"麻利","pinyin":"máli","meaning_vi":"nhanh nhẹn, lanh lẹ (tay chân)","explanation":"麻 (ma) + 利 (lợi – nhanh, sắc) → khẩu ngữ: tay chân nhanh nhẹn, làm việc lẹ làng gọn gàng. Ví dụ: 干活儿很麻利.","hsk_level":6,"tags":["tinh-tu"],"image":"⚡","examples":[{"type":"basic","zh":"她干活很麻利。","pinyin":"Tā gànhuó hěn máli.","vi":"Cô ấy làm việc rất nhanh nhẹn."},{"type":"simple","zh":"服务员麻利地把桌子收拾干净了。","pinyin":"Fúwùyuán máli de bǎ zhuōzi shōushi gānjìng le.","vi":"Nhân viên phục vụ nhanh nhẹn dọn sạch bàn."},{"type":"compound","zh":"小李不但手脚麻利，而且做事很细心。","pinyin":"Xiǎo Lǐ búdàn shǒujiǎo máli, érqiě zuòshì hěn xìxīn.","vi":"Tiểu Lý không những tay chân nhanh nhẹn mà còn làm việc rất cẩn thận."}],"related":[{"hanzi":"利索","pinyin":"lìsuo","vi":"gọn gàng nhanh nhẹn"},{"hanzi":"敏捷","pinyin":"mǐnjié","vi":"nhanh nhẹn"},{"hanzi":"手脚麻利","pinyin":"shǒujiǎomáli","vi":"tay chân nhanh nhẹn"},{"hanzi":"笨拙","pinyin":"bènzhuō","vi":"vụng về"}]},{"id":"麻醉剂","hanzi":"麻醉剂","pinyin":"mázuìjì","meaning_vi":"thuốc mê, thuốc tê","explanation":"麻醉 (gây tê, gây mê) + 剂 (tễ – thuốc pha chế) → thuốc dùng để gây mê hoặc gây tê khi phẫu thuật. Lưu ý: 麻醉 không phải ma túy (毒品).","hsk_level":6,"tags":["danh-tu","suc-khoe"],"image":"💉","examples":[{"type":"basic","zh":"医生注射了麻醉剂。","pinyin":"Yīshēng zhùshèle mázuìjì.","vi":"Bác sĩ đã tiêm thuốc gây mê."},{"type":"simple","zh":"拔牙前牙医给我打了一点局部麻醉剂。","pinyin":"Báyá qián yáyī gěi wǒ dǎle yìdiǎn júbù mázuìjì.","vi":"Trước khi nhổ răng, nha sĩ tiêm cho tôi một ít thuốc tê cục bộ."},{"type":"compound","zh":"虽然用了麻醉剂，但是手术后伤口还是很疼。","pinyin":"Suīrán yòngle mázuìjì, dànshì shǒushù hòu shāngkǒu háishì hěn téng.","vi":"Tuy đã dùng thuốc mê nhưng sau phẫu thuật vết thương vẫn rất đau."}],"related":[{"hanzi":"麻醉","pinyin":"mázuì","vi":"gây mê"},{"hanzi":"麻药","pinyin":"máyào","vi":"thuốc tê"},{"hanzi":"手术","pinyin":"shǒushù","vi":"phẫu thuật"},{"hanzi":"止痛药","pinyin":"zhǐtòngyào","vi":"thuốc giảm đau"}],"traditional":"麻醉劑"},{"id":"埋没","hanzi":"埋没","pinyin":"máimò","meaning_vi":"vùi lấp, làm mai một","explanation":"埋 (mai – chôn) + 没 (một – chìm) → vùi lấp; nghĩa bóng làm tài năng không được phát huy. Cụm: 埋没人才.","hsk_level":6,"tags":["dong-tu"],"image":"🌫️","examples":[{"type":"basic","zh":"别埋没了人才。","pinyin":"Bié máimòle réncái.","vi":"Đừng làm mai một nhân tài."},{"type":"simple","zh":"古城遗址被黄沙埋没了上千年。","pinyin":"Gǔchéng yízhǐ bèi huáng shā máimòle shàng qiānnián.","vi":"Di chỉ thành cổ bị cát vàng vùi lấp hơn nghìn năm."},{"type":"compound","zh":"如果他一直待在小山村，他的绘画天赋就会被埋没。","pinyin":"Rúguǒ tā yì zhídāi zài xiǎo shāncūn, tā de huìhuà tiānfù jiù huì bèi máimò.","vi":"Nếu cậu ấy cứ ở mãi trong làng núi nhỏ thì tài năng hội họa của cậu sẽ bị mai một."}],"related":[{"hanzi":"埋没人才","pinyin":"máimòréncái","vi":"vùi dập nhân tài"},{"hanzi":"掩埋","pinyin":"yǎnmái","vi":"chôn lấp"},{"hanzi":"发掘","pinyin":"fājué","vi":"khai quật, phát hiện"},{"hanzi":"怀才不遇","pinyin":"huáicáibúyù","vi":"có tài mà không gặp thời"}],"traditional":"埋沒"},{"id":"埋怨","hanzi":"埋怨","pinyin":"mányuàn","meaning_vi":"trách móc, oán trách","explanation":"埋 (đọc mán) + 怨.","hsk_level":6,"tags":["dong-tu","cam-xuc"],"image":"😤","examples":[{"type":"basic","zh":"别总埋怨别人。","pinyin":"Bié zǒng mányuàn biérén.","vi":"Đừng lúc nào cũng trách móc người khác."},{"type":"simple","zh":"她埋怨丈夫忘了结婚纪念日。","pinyin":"Tā mányuàn zhàngfu wàngle jiéhūn jìniànrì.","vi":"Cô ấy trách chồng quên ngày kỷ niệm cưới."},{"type":"compound","zh":"与其埋怨天气不好，不如想想室内能做什么。","pinyin":"Yǔqí mányuàn tiānqì bù hǎo, bùrú xiǎng xiang shì nèinéng zuò shénme.","vi":"Thay vì than trách thời tiết xấu, chẳng thà nghĩ xem trong nhà có thể làm gì."}],"related":[{"hanzi":"抱怨","pinyin":"bàoyuàn","vi":"phàn nàn"},{"hanzi":"责怪","pinyin":"zéguài","vi":"trách móc"},{"hanzi":"怨恨","pinyin":"yuànhèn","vi":"oán hận"},{"hanzi":"牢骚","pinyin":"láosāo","vi":"than phiền"}]},{"id":"茫茫","hanzi":"茫茫","pinyin":"mángmáng","meaning_vi":"mênh mông, mịt mù","explanation":"Lặp lại chữ 茫.","hsk_level":6,"tags":["tinh-tu"],"image":"🌊","examples":[{"type":"basic","zh":"茫茫大海一望无际。","pinyin":"Mángmáng dàhǎi yí wàng wújì.","vi":"Biển cả mênh mông bát ngát."},{"type":"simple","zh":"一只小船在茫茫的夜色中慢慢前进。","pinyin":"Yì zhī xiǎochuán zài mángmáng de yèsè zhōng mànman qiánjìn.","vi":"Một con thuyền nhỏ chậm rãi tiến lên trong màn đêm mịt mù."},{"type":"compound","zh":"虽然人海茫茫，但是我相信我们还会再见面。","pinyin":"Suīrán rénhǎi mángmáng, dànshì wǒ xiāngxìn wǒmen hái huì zàijiàn miàn.","vi":"Tuy biển người mênh mông nhưng tôi tin chúng ta sẽ còn gặp lại."}],"related":[{"hanzi":"茫然","pinyin":"mángrán","vi":"mờ mịt"},{"hanzi":"白茫茫","pinyin":"báimángmáng","vi":"trắng xóa"},{"hanzi":"渺茫","pinyin":"miǎománg","vi":"mờ mịt xa vời"},{"hanzi":"辽阔","pinyin":"liáokuò","vi":"bao la"}]},{"id":"毛遂自荐","hanzi":"毛遂自荐","pinyin":"máosuì-zìjiàn","meaning_vi":"tự tiến cử bản thân","explanation":"Điển tích Mao Toại. Thành ngữ.","hsk_level":6,"tags":["thanh-ngu","cong-viec"],"image":"🙋","examples":[{"type":"basic","zh":"他毛遂自荐当班长。","pinyin":"Tā Máosuìzìjiàn dāng bānzhǎng.","vi":"Cậu ấy tự tiến cử làm lớp trưởng."},{"type":"simple","zh":"毕业生小林写信向这家公司毛遂自荐。","pinyin":"Bìyèshēng Xiǎolín xiěxìn xiàng zhè jiā gōngsī Máosuìzìjiàn.","vi":"Sinh viên tốt nghiệp Tiểu Lâm viết thư tự tiến cử bản thân với công ty này."},{"type":"compound","zh":"既然没有人愿意主持晚会，我就毛遂自荐吧。","pinyin":"Jìrán méiyǒu rén yuànyì zhǔchí wǎnhuì, wǒ jiù Máosuìzìjiàn ba.","vi":"Đã không ai muốn dẫn chương trình buổi dạ hội thì tôi xin tự tiến cử vậy."}],"related":[{"hanzi":"自告奋勇","pinyin":"zìgàofènyǒng","vi":"xung phong"},{"hanzi":"自荐","pinyin":"zìjiàn","vi":"tự tiến cử"},{"hanzi":"推荐","pinyin":"tuījiàn","vi":"tiến cử"},{"hanzi":"挺身而出","pinyin":"tǐngshēn'érchū","vi":"đứng ra gánh vác"}],"traditional":"毛遂自薦"},{"id":"梦寐以求","hanzi":"梦寐以求","pinyin":"mèngmèi-yǐqiú","meaning_vi":"mơ ước bấy lâu nay","explanation":"梦寐 (mộng mị – lúc ngủ mơ) + 以求 (để tìm kiếm) → mong ước tha thiết đến cả trong mơ. Thường: 梦寐以求的工作.","hsk_level":6,"tags":["thanh-ngu"],"image":"🌠","examples":[{"type":"basic","zh":"这是我梦寐以求的车。","pinyin":"Zhè shì wǒ mèngmèiyǐqiú de chē.","vi":"Đây là chiếc xe tôi mơ ước bấy lâu."},{"type":"simple","zh":"她终于考上了梦寐以求的音乐学院。","pinyin":"Tā zhōngyú kǎoshàngle mèngmèiyǐqiú de yīnyuè xuéyuàn.","vi":"Cô ấy cuối cùng đã đỗ vào học viện âm nhạc mà mình hằng mơ ước."},{"type":"compound","zh":"只要坚持努力，你就能得到梦寐以求的工作。","pinyin":"Zhǐyào jiānchí nǔlì, nǐ jiù néng dédào mèngmèiyǐqiú de gōngzuò.","vi":"Chỉ cần kiên trì nỗ lực, bạn sẽ có được công việc mơ ước bấy lâu."}],"related":[{"hanzi":"朝思暮想","pinyin":"zhāosīmùxiǎng","vi":"ngày nhớ đêm mong"},{"hanzi":"梦想","pinyin":"mèngxiǎng","vi":"ước mơ"},{"hanzi":"求之不得","pinyin":"qiúzhībùdé","vi":"cầu còn không được"},{"hanzi":"渴望","pinyin":"kěwàng","vi":"khao khát"}],"traditional":"夢寐以求"},{"id":"门当户对","hanzi":"门当户对","pinyin":"méndāng-hùduì","meaning_vi":"môn đăng hộ đối","explanation":"Cửa nhà hai bên tương xứng → hai gia đình có địa vị, gia thế ngang nhau, thường nói về hôn nhân. Hán-Việt: môn đăng hộ đối.","hsk_level":6,"tags":["thanh-ngu","gia-dinh"],"image":"💍","examples":[{"type":"basic","zh":"他们门当户对。","pinyin":"Tāmen méndānghùduì.","vi":"Họ môn đăng hộ đối."},{"type":"simple","zh":"老一辈人结婚很看重门当户对。","pinyin":"Lǎoyíbèi rén jiéhūn hěn kànzhòng méndānghùduì.","vi":"Thế hệ trước khi kết hôn rất coi trọng môn đăng hộ đối."},{"type":"compound","zh":"虽然两家并不门当户对，但是父母还是同意了这门婚事。","pinyin":"Suīrán liǎng jiā bìngbù méndānghùduì, dànshì fùmǔ háishì tóngyìle zhè mén hūnshì.","vi":"Tuy hai nhà không hề môn đăng hộ đối nhưng bố mẹ vẫn đồng ý cuộc hôn nhân này."}],"related":[{"hanzi":"般配","pinyin":"bānpèi","vi":"xứng đôi"},{"hanzi":"门第","pinyin":"méndì","vi":"gia thế"},{"hanzi":"婚姻","pinyin":"hūnyīn","vi":"hôn nhân"},{"hanzi":"天作之合","pinyin":"tiānzuòzhīhé","vi":"trời sinh một cặp"}],"traditional":"門當戶對"},{"id":"门庭若市","hanzi":"门庭若市","pinyin":"méntíng-ruòshì","meaning_vi":"khách khứa ra vào tấp nập như chợ","explanation":"Trước cửa và trong sân đông như chợ (Chiến Quốc sách: Tề Uy Vương mời dân góp ý) → khách đến tấp nập. Trái nghĩa: 门可罗雀.","hsk_level":6,"tags":["thanh-ngu"],"image":"🏪","examples":[{"type":"basic","zh":"他家门庭若市。","pinyin":"Tā jiā méntíngruòshì.","vi":"Nhà ông ấy khách khứa ra vào nườm nượp."},{"type":"simple","zh":"新开的火锅店每天晚上都门庭若市。","pinyin":"Xīn kāi de huǒguōdiàn měitiān wǎnshang dōu méntíngruòshì.","vi":"Quán lẩu mới mở tối nào cũng đông khách tấp nập như chợ."},{"type":"compound","zh":"这家诊所因为医生医术高明，所以每天都门庭若市。","pinyin":"Zhè jiā zhěnsuǒ yīnwèi yīshēng yīshù gāomíng, suǒyǐ měitiān dōu méntíngruòshì.","vi":"Phòng khám này vì bác sĩ tay nghề cao nên ngày nào cũng đông nghịt người."}],"related":[{"hanzi":"门可罗雀","pinyin":"ménkěluóquè","vi":"vắng tanh như chùa bà đanh"},{"hanzi":"车水马龙","pinyin":"chēshuǐmǎlóng","vi":"xe cộ tấp nập"},{"hanzi":"熙熙攘攘","pinyin":"xīxīrǎngrǎng","vi":"đông đúc nhộn nhịp"},{"hanzi":"络绎不绝","pinyin":"luòyìbùjué","vi":"nối đuôi không dứt"}],"traditional":"門庭若市"},{"id":"萌芽","hanzi":"萌芽","pinyin":"méngyá","meaning_vi":"nảy mầm, mầm mống ban đầu","explanation":"萌 (mọc mầm) + 芽 (chồi non).","hsk_level":6,"tags":["dong-tu","thien-nhien"],"image":"🌱","examples":[{"type":"basic","zh":"种子萌芽了。","pinyin":"Zhǒngzi méngyá le.","vi":"Hạt giống đã nảy mầm."},{"type":"simple","zh":"他心中萌芽了出国留学的想法。","pinyin":"Tā xīnzhōng méngyále chūguó liúxué de xiǎngfǎ.","vi":"Trong lòng cậu ấy nhen nhóm ý định đi du học."},{"type":"compound","zh":"如果把问题消灭在萌芽状态，就能避免更大的损失。","pinyin":"Rúguǒ bǎ wèntí xiāomiè zài méngyá zhuàngtài, jiù néng bìmiǎn gèng dà de sǔnshī.","vi":"Nếu dập tắt vấn đề ngay từ trong trứng nước thì có thể tránh được tổn thất lớn hơn."}],"related":[{"hanzi":"发芽","pinyin":"fāyá","vi":"nảy mầm"},{"hanzi":"萌发","pinyin":"méngfā","vi":"nảy sinh"},{"hanzi":"雏形","pinyin":"chúxíng","vi":"hình thức ban đầu"},{"hanzi":"扼杀在萌芽状态","pinyin":"èshā zài méngyá zhuàngtài","vi":"bóp chết từ trong trứng"}]},{"id":"弥补","hanzi":"弥补","pinyin":"míbǔ","meaning_vi":"bù đắp, khắc phục","explanation":"弥 (di – lấp đầy) + 补 (bổ – vá, bù) → lấp vào chỗ thiếu hụt, bù đắp. Cụm: 弥补损失, 弥补不足.","hsk_level":6,"tags":["dong-tu"],"image":"🩹","examples":[{"type":"basic","zh":"我会弥补损失的。","pinyin":"Wǒ huì míbǔ sǔnshī de.","vi":"Tôi sẽ bù đắp tổn thất."},{"type":"simple","zh":"他用周末时间弥补落下的功课。","pinyin":"Tāyòng zhōumò shíjiān míbǔ làxià de gōngkè.","vi":"Cậu ấy dùng thời gian cuối tuần để bù lại bài vở bị chậm."},{"type":"compound","zh":"虽然他尽力弥补，但是造成的伤害已经无法挽回。","pinyin":"Suīrán tā jìnlì míbǔ, dànshì zàochéng de shānghài yǐjīng wúfǎ wǎnhuí.","vi":"Tuy anh ấy đã cố hết sức bù đắp nhưng tổn thương gây ra đã không thể cứu vãn."}],"related":[{"hanzi":"补偿","pinyin":"bǔcháng","vi":"bồi thường"},{"hanzi":"填补","pinyin":"tiánbǔ","vi":"lấp đầy"},{"hanzi":"挽回","pinyin":"wǎnhuí","vi":"cứu vãn"},{"hanzi":"无法弥补","pinyin":"wúfǎmíbǔ","vi":"không thể bù đắp"}],"traditional":"彌補"},{"id":"迷人","hanzi":"迷人","pinyin":"mírén","meaning_vi":"mê người, quyến rũ","explanation":"迷 (mê – làm say mê) + 人 (nhân – người) → khiến người ta say mê; quyến rũ. Cụm: 迷人的风景, 迷人的笑容.","hsk_level":6,"tags":["tinh-tu"],"image":"😍","examples":[{"type":"basic","zh":"夜景很迷人。","pinyin":"Yèjǐng hěn mírén.","vi":"Cảnh đêm rất quyến rũ."},{"type":"simple","zh":"她有一双迷人的大眼睛。","pinyin":"Tā yǒu yì shuāng mírén de dà yǎnjing.","vi":"Cô ấy có đôi mắt to quyến rũ."},{"type":"compound","zh":"这个海岛既有迷人的沙滩，又有新鲜的海鲜。","pinyin":"Zhè gè hǎidǎo jìyǒu mírén de shātān, yòu yǒu xīnxiān de hǎixiān.","vi":"Hòn đảo này vừa có bãi cát quyến rũ, vừa có hải sản tươi ngon."}],"related":[{"hanzi":"吸引人","pinyin":"xīyǐnrén","vi":"hấp dẫn"},{"hanzi":"魅力","pinyin":"mèilì","vi":"sức quyến rũ"},{"hanzi":"动人","pinyin":"dòngrén","vi":"cảm động lòng người"},{"hanzi":"迷恋","pinyin":"míliàn","vi":"say mê"}]},{"id":"明察秋毫","hanzi":"明察秋毫","pinyin":"míngchá-qiūháo","meaning_vi":"sáng suốt nhìn thấu mọi chi tiết nhỏ nhất","explanation":"Nhìn rõ cả sợi lông tơ của chim thú mọc vào mùa thu (Mạnh Tử) → sáng suốt, nhìn thấu mọi chi tiết nhỏ. Hay dùng khen người xét xử.","hsk_level":6,"tags":["thanh-ngu"],"image":"🦅","examples":[{"type":"basic","zh":"法官明察秋毫。","pinyin":"Fǎguān míngcháqiūháo.","vi":"Thẩm phán sáng suốt thấu suốt mọi chi tiết."},{"type":"simple","zh":"这位侦探以明察秋毫而闻名。","pinyin":"Zhè wèi zhēntàn yǐ míngcháqiūháo ér wénmíng.","vi":"Vị thám tử này nổi tiếng nhờ khả năng nhìn thấu từng chi tiết nhỏ."},{"type":"compound","zh":"即使你骗得了别人，也骗不过明察秋毫的老师。","pinyin":"Jíshǐ nǐ piàn deliǎo biérén, yě piàn búguò míngcháqiūháo de lǎoshī.","vi":"Dù bạn lừa được người khác thì cũng không lừa được người thầy tinh tường."}],"related":[{"hanzi":"洞察","pinyin":"dòngchá","vi":"nhìn thấu"},{"hanzi":"明辨是非","pinyin":"míngbiànshìfēi","vi":"phân biệt phải trái"},{"hanzi":"细致入微","pinyin":"xìzhìrùwēi","vi":"tỉ mỉ từng li"},{"hanzi":"糊涂","pinyin":"hútu","vi":"hồ đồ"}]},{"id":"铭记在心","hanzi":"铭记在心","pinyin":"míngjì-zàixīn","meaning_vi":"ghi nhớ sâu sắc trong lòng","explanation":"铭记 (minh ký – khắc ghi) + 在心 (trong lòng) → ghi khắc trong lòng, không bao giờ quên. Thường dùng với ơn nghĩa, lời dạy.","hsk_level":6,"tags":["thanh-ngu"],"image":"❤️","examples":[{"type":"basic","zh":"您的话我铭记在心。","pinyin":"Nín dehuà wǒ míngjìzàixīn.","vi":"Lời của ngài tôi ghi nhớ trong lòng."},{"type":"simple","zh":"我会把老师的教诲永远铭记在心。","pinyin":"Wǒ huì bǎ lǎoshī de jiàohuì yǒngyuǎn míngjìzàixīn.","vi":"Tôi sẽ mãi ghi nhớ lời dạy bảo của thầy trong lòng."},{"type":"compound","zh":"因为陌生人曾在雨夜帮过我，所以我把这份善意铭记在心。","pinyin":"Yīnwèi mòshēngrén céng zài yǔyè bāngguò wǒ, suǒyǐ wǒ bǎ zhè fèn shànyì míngjìzàixīn.","vi":"Vì một người lạ từng giúp tôi trong đêm mưa nên tôi luôn ghi nhớ lòng tốt ấy."}],"related":[{"hanzi":"牢记","pinyin":"láojì","vi":"ghi nhớ kỹ"},{"hanzi":"刻骨铭心","pinyin":"kègǔmíngxīn","vi":"khắc cốt ghi tâm"},{"hanzi":"念念不忘","pinyin":"niànniànbúwàng","vi":"nhớ mãi không quên"},{"hanzi":"铭记","pinyin":"míngjì","vi":"ghi nhớ"}],"traditional":"銘記在心"},{"id":"名列前茅","hanzi":"名列前茅","pinyin":"míngliè-qiánmáo","meaning_vi":"đứng đầu bảng xếp hạng thành tích","explanation":"Tên đứng ở hàng 前茅 (cờ cỏ mao của đội quân đi đầu nước Sở) → xếp hạng hàng đầu, thành tích dẫn đầu. Thường: 考试名列前茅.","hsk_level":6,"tags":["thanh-ngu","hoc-tap"],"image":"🏆","examples":[{"type":"basic","zh":"他成绩名列前茅。","pinyin":"Tā chéngjì mínglièqiánmáo.","vi":"Thành tích của cậu ấy đứng đầu."},{"type":"simple","zh":"这所大学在全国排名中一直名列前茅。","pinyin":"Zhè suǒ dàxué zài quánguó páimíng zhōng yìzhí mínglièqiánmáo.","vi":"Trường đại học này luôn đứng đầu trong bảng xếp hạng toàn quốc."},{"type":"compound","zh":"她不但学习名列前茅，而且还是校篮球队的主力。","pinyin":"Tā búdàn xuéxí mínglièqiánmáo, érqiě háishì xiào lánqiúduì de zhǔlì.","vi":"Cô ấy không những học hành đứng đầu mà còn là trụ cột của đội bóng rổ trường."}],"related":[{"hanzi":"名落孙山","pinyin":"míngluòsūnshān","vi":"thi trượt"},{"hanzi":"名次","pinyin":"míngcì","vi":"thứ hạng"},{"hanzi":"第一名","pinyin":"dìyīmíng","vi":"hạng nhất"},{"hanzi":"遥遥领先","pinyin":"yáoyáolǐngxiān","vi":"dẫn đầu xa"}]},{"id":"名落孙山","hanzi":"名落孙山","pinyin":"míngluò-sūnshān","meaning_vi":"thi trượt (xếp sau Tôn Sơn)","explanation":"Điển tích thi cử. Thành ngữ.","hsk_level":6,"tags":["thanh-ngu","hoc-tap"],"image":"📉","examples":[{"type":"basic","zh":"他这次名落孙山。","pinyin":"Tā zhè cì míngluòsūnshān.","vi":"Lần này anh ấy thi trượt."},{"type":"simple","zh":"名落孙山的哥哥决定明年再考一次。","pinyin":"Míngluòsūnshān de gēge juédìng míngnián zài kǎo yí cì.","vi":"Người anh thi trượt quyết định năm sau thi lại một lần nữa."},{"type":"compound","zh":"如果考前不好好复习，就很可能名落孙山。","pinyin":"Rúguǒ kǎo qián bù hǎohǎo fùxí, jiù hěn kěnéng míngluòsūnshān.","vi":"Nếu trước kỳ thi không ôn tập chăm chỉ thì rất có thể thi trượt."}],"related":[{"hanzi":"落榜","pinyin":"luòbǎng","vi":"thi trượt"},{"hanzi":"名列前茅","pinyin":"mínglièqiánmáo","vi":"đứng đầu bảng"},{"hanzi":"金榜题名","pinyin":"jīnbǎngtímíng","vi":"đỗ đạt"},{"hanzi":"考试","pinyin":"kǎoshì","vi":"thi cử"}],"traditional":"名落孫山"},{"id":"明智","hanzi":"明智","pinyin":"míngzhì","meaning_vi":"sáng suốt, khôn ngoan","explanation":"明 (minh – sáng) + 智 (trí – trí tuệ) → sáng suốt, khôn ngoan khi quyết định. Cụm: 明智的选择.","hsk_level":6,"tags":["tinh-tu"],"image":"🧠","examples":[{"type":"basic","zh":"这是明智的选择。","pinyin":"Zhè shì míngzhì de xuǎnzé.","vi":"Đây là lựa chọn sáng suốt."},{"type":"simple","zh":"他明智地拒绝了陌生人的投资邀请。","pinyin":"Tā míngzhì de jùjuéle mòshēngrén de tóuzī yāoqǐng.","vi":"Anh ấy sáng suốt từ chối lời mời đầu tư của người lạ."},{"type":"compound","zh":"既然天气这么差，取消登山计划是明智的。","pinyin":"Jìrán tiānqì zhème chà, qǔxiāo dēngshān jìhuà shì míngzhì de.","vi":"Thời tiết đã xấu như vậy thì hủy kế hoạch leo núi là sáng suốt."}],"related":[{"hanzi":"聪明","pinyin":"cōngmíng","vi":"thông minh"},{"hanzi":"理智","pinyin":"lǐzhì","vi":"lý trí"},{"hanzi":"明智之举","pinyin":"míngzhìzhījǔ","vi":"việc làm sáng suốt"},{"hanzi":"愚蠢","pinyin":"yúchǔn","vi":"ngu ngốc"}]},{"id":"明知故犯","hanzi":"明知故犯","pinyin":"míngzhī-gùfàn","meaning_vi":"biết sai mà vẫn cố tình phạm phải","explanation":"明知 (biết rõ) + 故犯 (cố ý phạm) → biết rõ là sai mà vẫn cố tình làm.","hsk_level":6,"tags":["thanh-ngu"],"image":"🚫","examples":[{"type":"basic","zh":"你这是明知故犯。","pinyin":"Nǐ zhè shì míngzhīgùfàn.","vi":"Bạn đây là biết sai mà vẫn cố phạm."},{"type":"simple","zh":"对明知故犯的司机要加重处罚。","pinyin":"Duì míngzhīgùfàn de sījī yào jiāzhòng chǔfá.","vi":"Đối với tài xế biết sai mà vẫn cố tình vi phạm phải xử phạt nặng hơn."},{"type":"compound","zh":"虽然他知道这里禁止钓鱼，但是他还是明知故犯。","pinyin":"Suīrán tā zhīdào zhèlǐ jìnzhǐ diàoyú, dànshì tā háishì míngzhīgùfàn.","vi":"Tuy biết nơi đây cấm câu cá nhưng anh ta vẫn cố tình vi phạm."}],"related":[{"hanzi":"知法犯法","pinyin":"zhīfǎfànfǎ","vi":"biết luật mà phạm luật"},{"hanzi":"故意","pinyin":"gùyì","vi":"cố ý"},{"hanzi":"执迷不悟","pinyin":"zhímíbúwù","vi":"u mê không tỉnh"},{"hanzi":"无心之过","pinyin":"wúxīnzhīguò","vi":"lỗi vô ý"}]},{"id":"名额","hanzi":"名额","pinyin":"míng'é","meaning_vi":"chỉ tiêu, suất","explanation":"名 (danh – tên, người) + 额 (ngạch – mức quy định) → số người được quy định; suất, chỉ tiêu. Cụm: 招生名额.","hsk_level":6,"tags":["danh-tu","cong-viec"],"image":"🎫","examples":[{"type":"basic","zh":"名额已经满了。","pinyin":"Míng'é yǐjīng mǎn le.","vi":"Suất đã hết rồi."},{"type":"simple","zh":"今年公司只有三个出国培训的名额。","pinyin":"Jīnnián gōngsī zhǐyǒu sān gè chūguó péixùn de míng'é.","vi":"Năm nay công ty chỉ có ba suất đi đào tạo ở nước ngoài."},{"type":"compound","zh":"因为报名的人太多，所以学校决定增加招生名额。","pinyin":"Yīnwèi bàomíng de rén tài duō, suǒyǐ xuéxiào juédìng zēngjiā zhāoshēng míng'é.","vi":"Vì số người đăng ký quá đông nên trường quyết định tăng chỉ tiêu tuyển sinh."}],"related":[{"hanzi":"指标","pinyin":"zhǐbiāo","vi":"chỉ tiêu"},{"hanzi":"招生","pinyin":"zhāoshēng","vi":"tuyển sinh"},{"hanzi":"限额","pinyin":"xiàn'é","vi":"hạn mức"},{"hanzi":"名单","pinyin":"míngdān","vi":"danh sách"}],"traditional":"名額"},{"id":"默不作声","hanzi":"默不作声","pinyin":"mòbú-zuòshēng","meaning_vi":"im lặng không nói một lời","explanation":"默 (mặc – im lặng) + 不作声 (không lên tiếng) → im lặng, không nói một lời.","hsk_level":6,"tags":["thanh-ngu"],"image":"🤐","examples":[{"type":"basic","zh":"他默不作声。","pinyin":"Tā mòbúzuòshēng.","vi":"Anh ấy im lặng không nói."},{"type":"simple","zh":"小张默不作声地坐在教室的角落里。","pinyin":"Xiǎo Zhāng mòbúzuòshēng de zuò zài jiàoshì de jiǎoluò lǐ.","vi":"Tiểu Trương lặng lẽ ngồi ở góc lớp học không nói một lời."},{"type":"compound","zh":"虽然心里很委屈，但是她始终默不作声。","pinyin":"Suīrán xīnlǐ hěn wěiqu, dànshì tā shǐzhōng mòbúzuòshēng.","vi":"Tuy trong lòng rất tủi thân nhưng cô ấy trước sau vẫn im lặng không nói một lời."}],"related":[{"hanzi":"沉默不语","pinyin":"chénmòbùyǔ","vi":"im lặng không nói"},{"hanzi":"一声不吭","pinyin":"yìshēngbùkēng","vi":"không nói một tiếng"},{"hanzi":"沉默","pinyin":"chénmò","vi":"im lặng"},{"hanzi":"滔滔不绝","pinyin":"tāotāobùjué","vi":"nói thao thao bất tuyệt"}],"traditional":"默不作聲"},{"id":"默默无闻","hanzi":"默默无闻","pinyin":"mòmò-wúwén","meaning_vi":"âm thầm lặng lẽ không ai biết tiếng","explanation":"默默 (lặng lẽ) + 无闻 (không ai nghe biết) → âm thầm, không tên tuổi; hay khen người cống hiến thầm lặng: 默默无闻地工作.","hsk_level":6,"tags":["thanh-ngu"],"image":"🌱","examples":[{"type":"basic","zh":"他一直默默无闻。","pinyin":"Tā yìzhí mòmòwúwén.","vi":"Anh ấy vẫn luôn âm thầm không ai biết đến."},{"type":"simple","zh":"这位乡村医生默默无闻地工作了四十年。","pinyin":"Zhè wèi xiāngcūn yīshēng mòmòwúwén de gōngzuòle sìshí nián.","vi":"Vị bác sĩ nông thôn này âm thầm làm việc suốt bốn mươi năm."},{"type":"compound","zh":"虽然她在幕后默默无闻，但是没有她就没有这部电影。","pinyin":"Suīrán tā zài mùhòu mòmòwúwén, dànshì méiyǒu tā jiù méiyǒu zhè bù diànyǐng.","vi":"Tuy cô ấy âm thầm ở phía sau không ai biết tên nhưng không có cô thì không có bộ phim này."}],"related":[{"hanzi":"无名","pinyin":"wúmíng","vi":"vô danh"},{"hanzi":"默默","pinyin":"mòmò","vi":"lặng lẽ"},{"hanzi":"举世闻名","pinyin":"jǔshìwénmíng","vi":"nổi tiếng thế giới"},{"hanzi":"默默奉献","pinyin":"mòmòfèngxiàn","vi":"âm thầm cống hiến"}],"traditional":"默默無聞"},{"id":"墨水儿","hanzi":"墨水儿","pinyin":"mòshuǐr","meaning_vi":"mực viết","explanation":"墨 (mặc – mực) + 水 (thủy – nước) + 儿 → mực nước để viết; khẩu ngữ còn chỉ học vấn: 肚子里有墨水儿.","hsk_level":6,"tags":["danh-tu","hoc-tap","do-vat"],"image":"🖋️","examples":[{"type":"basic","zh":"我去买瓶墨水儿。","pinyin":"Wǒqù mǎi píng mòshuǐr.","vi":"Tôi đi mua một lọ mực."},{"type":"simple","zh":"他不小心把墨水儿洒在了白衬衫上。","pinyin":"Tā bù xiǎoxīn bǎ mòshuǐr sǎ zài le bái chènshān shàng.","vi":"Anh ấy vô ý làm đổ mực lên chiếc áo sơ mi trắng."},{"type":"compound","zh":"如果钢笔里的墨水儿干了，就用温水泡一泡。","pinyin":"Rúguǒ gāngbǐ lǐ de mòshuǐr gān le, jiù yòng wēn shuǐpào yi pào.","vi":"Nếu mực trong bút máy bị khô thì ngâm vào nước ấm một chút."}],"related":[{"hanzi":"墨水","pinyin":"mòshuǐ","vi":"mực"},{"hanzi":"钢笔","pinyin":"gāngbǐ","vi":"bút máy"},{"hanzi":"墨汁","pinyin":"mòzhī","vi":"mực tàu"},{"hanzi":"喝过墨水","pinyin":"hēguomòshuǐ","vi":"có học thức"}],"traditional":"墨水兒"},{"id":"膜","hanzi":"膜","pinyin":"mó","meaning_vi":"màng, lớp màng","explanation":"Bộ nguyệt ⺼+ 莫.","hsk_level":6,"tags":["danh-tu","cong-nghe"],"image":"📱","examples":[{"type":"basic","zh":"牛奶上有一层膜。","pinyin":"Niúnǎi shàng yǒu yīcéng mó.","vi":"Trên mặt sữa có một lớp màng."},{"type":"simple","zh":"新手机的屏幕上贴着一层保护膜。","pinyin":"Xīnshǒu jī de píngmù shàng tiēzhe yīcéng bǎohù mó.","vi":"Trên màn hình điện thoại mới có dán một lớp màng bảo vệ."},{"type":"compound","zh":"因为耳朵里的鼓膜受了伤，所以他暂时听不清声音。","pinyin":"Yīnwèi ěrduo lǐ de gǔmó shòule shāng, suǒyǐ tā zànshí tīng bùqīng shēngyīn.","vi":"Vì màng nhĩ bị tổn thương nên tạm thời anh ấy nghe không rõ âm thanh."}],"related":[{"hanzi":"薄膜","pinyin":"bómó","vi":"màng mỏng"},{"hanzi":"保鲜膜","pinyin":"bǎoxiānmó","vi":"màng bọc thực phẩm"},{"hanzi":"面膜","pinyin":"miànmó","vi":"mặt nạ dưỡng da"},{"hanzi":"耳膜","pinyin":"ěrmó","vi":"màng nhĩ"}]},{"id":"模范","hanzi":"模范","pinyin":"mófàn","meaning_vi":"gương mẫu, mẫu mực","explanation":"模 (mô – khuôn) + 范 (phạm – khuôn mẫu) → khuôn mẫu; người hoặc việc đáng làm gương. Cụm: 劳动模范, 模范作用.","hsk_level":6,"tags":["danh-tu","tinh-tu"],"image":"🌟","examples":[{"type":"basic","zh":"他是劳动模范。","pinyin":"Tā shì láodòng mófàn.","vi":"Ông ấy là chiến sĩ thi đua lao động gương mẫu."},{"type":"simple","zh":"王老师被评为全市的模范教师。","pinyin":"Wáng lǎoshī bèi píngwéi quánshì de mófàn jiàoshī.","vi":"Cô Vương được bình chọn là giáo viên gương mẫu của toàn thành phố."},{"type":"compound","zh":"父母只有自己起模范作用，孩子才会跟着学。","pinyin":"Fùmǔ zhǐyǒu zìjǐ qǐ mófàn zuòyòng, háizi cái huì gēnzhe xué.","vi":"Cha mẹ chỉ có tự mình làm gương thì con cái mới học theo."}],"related":[{"hanzi":"榜样","pinyin":"bǎngyàng","vi":"tấm gương"},{"hanzi":"典范","pinyin":"diǎnfàn","vi":"điển hình"},{"hanzi":"劳动模范","pinyin":"láodòngmófàn","vi":"chiến sĩ thi đua"},{"hanzi":"楷模","pinyin":"kǎimó","vi":"mẫu mực"}],"traditional":"模範"},{"id":"魔术","hanzi":"魔术","pinyin":"móshù","meaning_vi":"ảo thuật","explanation":"魔 (ma – ma quái) + 术 (thuật – kỹ thuật) → thuật biến hóa kỳ lạ, ảo thuật. Cụm: 变魔术 (làm ảo thuật).","hsk_level":6,"tags":["danh-tu","giai-tri"],"image":"🎩","examples":[{"type":"basic","zh":"他会变魔术。","pinyin":"Tā huì biànmóshù.","vi":"Anh ấy biết làm ảo thuật."},{"type":"simple","zh":"魔术师从帽子里变出了一只白兔子。","pinyin":"Móshù shīcóng màozi lǐ biàn chūle yì zhī bái tùzi.","vi":"Nhà ảo thuật biến ra một con thỏ trắng từ trong chiếc mũ."},{"type":"compound","zh":"虽然我知道魔术都是假的，但是还是看得很入迷。","pinyin":"Suīrán wǒ zhīdào móshù dōu shì jiǎ de, dànshì háishì kàn de hěn rùmí.","vi":"Tuy biết ảo thuật đều là giả nhưng tôi vẫn xem say mê."}],"related":[{"hanzi":"魔术师","pinyin":"móshùshī","vi":"ảo thuật gia"},{"hanzi":"变魔术","pinyin":"biànmóshù","vi":"làm ảo thuật"},{"hanzi":"杂技","pinyin":"zájì","vi":"xiếc"},{"hanzi":"戏法","pinyin":"xìfǎ","vi":"trò ảo thuật"}],"traditional":"魔術"},{"id":"目不转睛","hanzi":"目不转睛","pinyin":"mùbù-zhuǎnjīng","meaning_vi":"nhìn chằm chằm không chớp mắt","explanation":"Mắt (目) không đảo tròng (睛) → nhìn chăm chú, không rời mắt. Thường: 目不转睛地看着.","hsk_level":6,"tags":["thanh-ngu"],"image":"👀","examples":[{"type":"basic","zh":"他看得目不转睛。","pinyin":"Tā kàn de mùbùzhuǎnjīng.","vi":"Anh ấy xem không rời mắt."},{"type":"simple","zh":"孩子们目不转睛地盯着鱼缸里的金鱼。","pinyin":"Háizimen mùbùzhuǎnjīng de dīngzhe yúgāng lǐ de jīnyú.","vi":"Bọn trẻ nhìn chằm chằm không chớp mắt vào đàn cá vàng trong bể."},{"type":"compound","zh":"电影一开场，观众们就目不转睛地看着银幕。","pinyin":"Diànyǐng yì kāichǎng, guānzhòngmen jiù mùbùzhuǎnjīng de kànzhe yínmù.","vi":"Bộ phim vừa bắt đầu, khán giả đã dán mắt vào màn ảnh không chớp."}],"related":[{"hanzi":"聚精会神","pinyin":"jùjīnghuìshén","vi":"tập trung tinh thần"},{"hanzi":"全神贯注","pinyin":"quánshénguànzhù","vi":"chăm chú"},{"hanzi":"凝视","pinyin":"níngshì","vi":"nhìn chăm chăm"},{"hanzi":"东张西望","pinyin":"dōngzhāngxīwàng","vi":"nhìn ngang ngó dọc"}],"traditional":"目不轉睛"},{"id":"暮气沉沉","hanzi":"暮气沉沉","pinyin":"mùqì-chénchén","meaning_vi":"thiếu sức sống, trì trệ uể oải","explanation":"暮气 (khí chiều tà, uể oải) + 沉沉 (nặng nề) → thiếu sức sống, trì trệ, ủ rũ. Trái nghĩa: 朝气蓬勃.","hsk_level":6,"tags":["thanh-ngu"],"image":"😴","examples":[{"type":"basic","zh":"这个部门暮气沉沉。","pinyin":"Zhè gè bùmén mùqìchénchén.","vi":"Bộ phận này uể oải thiếu sức sống."},{"type":"simple","zh":"年轻人不应该整天暮气沉沉的。","pinyin":"Niánqīngrén bù yīnggāi zhěngtiān mùqìchénchén de.","vi":"Người trẻ không nên cả ngày ủ rũ thiếu sức sống như vậy."},{"type":"compound","zh":"自从新校长上任，学校就不再暮气沉沉了。","pinyin":"Zìcóng xīn xiàozhǎng shàngrèn, xuéxiào jiù bú zài mùqìchénchén le.","vi":"Từ khi hiệu trưởng mới nhậm chức, trường học không còn trì trệ uể oải nữa."}],"related":[{"hanzi":"死气沉沉","pinyin":"sǐqìchénchén","vi":"tẻ nhạt thiếu sức sống"},{"hanzi":"朝气蓬勃","pinyin":"zhāoqìpéngbó","vi":"tràn đầy sức sống"},{"hanzi":"萎靡不振","pinyin":"wěimǐbúzhèn","vi":"uể oải bạc nhược"},{"hanzi":"消沉","pinyin":"xiāochén","vi":"suy sụp"}],"traditional":"暮氣沉沉"},{"id":"沐浴","hanzi":"沐浴","pinyin":"mùyù","meaning_vi":"tắm gội, đắm mình","explanation":"沐 (mộc – gội đầu) + 浴 (dục – tắm) → tắm gội; nghĩa bóng đắm mình trong ánh nắng, ân huệ. Cụm: 沐浴在阳光下.","hsk_level":6,"tags":["dong-tu"],"image":"🛁","examples":[{"type":"basic","zh":"他习惯睡前沐浴。","pinyin":"Tā xíguàn shuì qián mùyù.","vi":"Anh ấy có thói quen tắm gội trước khi ngủ."},{"type":"simple","zh":"古人在重要祭祀前要先沐浴更衣。","pinyin":"Gǔrén zài zhòngyào jìsì qián yào xiān mùyù gēng yī.","vi":"Người xưa trước những lễ tế quan trọng phải tắm gội thay y phục."},{"type":"compound","zh":"一到春天，整个村庄就沐浴在温暖的阳光里。","pinyin":"Yí dào chūntiān, zhěnggè cūnzhuāng jiù mùyù zài wēnnuǎn de yángguāng lǐ.","vi":"Cứ đến mùa xuân, cả ngôi làng lại tắm mình trong ánh nắng ấm áp."}],"related":[{"hanzi":"洗澡","pinyin":"xǐzǎo","vi":"tắm"},{"hanzi":"沐浴露","pinyin":"mùyùlù","vi":"sữa tắm"},{"hanzi":"淋浴","pinyin":"línyù","vi":"tắm vòi sen"},{"hanzi":"沐浴阳光","pinyin":"mùyùyángguāng","vi":"tắm nắng"}]},{"id":"目中无人","hanzi":"目中无人","pinyin":"mùzhōng-wúrén","meaning_vi":"coi trời bằng vung, ngạo mạn không coi ai ra gì","explanation":"Trong mắt không có ai → kiêu ngạo, coi thường người khác, không coi ai ra gì.","hsk_level":6,"tags":["thanh-ngu"],"image":"😤","examples":[{"type":"basic","zh":"他目中无人。","pinyin":"Tā mùzhōngwúrén.","vi":"Hắn coi trời bằng vung."},{"type":"simple","zh":"那个目中无人的球星连球迷都不理。","pinyin":"Nà gè mùzhōngwúrén de qiúxīng lián qiúmí dōu bùlǐ.","vi":"Ngôi sao bóng đá ngạo mạn đó ngay cả người hâm mộ cũng chẳng thèm để ý."},{"type":"compound","zh":"如果你总是目中无人，就不会有人愿意帮你。","pinyin":"Rúguǒ nǐ zǒngshì mùzhōngwúrén, jiù bú huì yǒurén yuànyì bāng nǐ.","vi":"Nếu bạn lúc nào cũng ngạo mạn coi thường người khác thì sẽ không ai muốn giúp bạn."}],"related":[{"hanzi":"目空一切","pinyin":"mùkōngyíqiè","vi":"coi thường tất cả"},{"hanzi":"狂妄自大","pinyin":"kuángwàngzìdà","vi":"ngông cuồng tự đại"},{"hanzi":"傲慢","pinyin":"àomàn","vi":"ngạo mạn"},{"hanzi":"谦虚","pinyin":"qiānxū","vi":"khiêm tốn"}],"traditional":"目中無人"},{"id":"模样","hanzi":"模样","pinyin":"múyàng","meaning_vi":"dáng vẻ, bộ dạng","explanation":"模 (đọc mú) + 样.","hsk_level":6,"tags":["danh-tu"],"image":"👤","examples":[{"type":"basic","zh":"他的模样很帅。","pinyin":"Tā de múyàng hěn shuài.","vi":"Dáng vẻ anh ấy rất đẹp trai."},{"type":"simple","zh":"女儿长得跟她妈妈年轻时一个模样。","pinyin":"Nǚ'ér zhǎngde gēn tā māma niánqīng shí yí gè múyàng.","vi":"Con gái trông giống hệt mẹ hồi trẻ."},{"type":"compound","zh":"十年没见了，他的模样虽然变了，但是笑容一点没变。","pinyin":"Shí nián méi jiàn le, tā de múyàng suīrán biàn le, dànshì xiàoróng yìdiǎn méi biàn.","vi":"Mười năm không gặp, dáng vẻ anh ấy tuy đã thay đổi nhưng nụ cười thì chẳng đổi chút nào."}],"related":[{"hanzi":"样子","pinyin":"yàngzi","vi":"dáng vẻ"},{"hanzi":"长相","pinyin":"zhǎngxiàng","vi":"tướng mạo"},{"hanzi":"外表","pinyin":"wàibiǎo","vi":"bề ngoài"},{"hanzi":"模样可爱","pinyin":"múyàngkě'ài","vi":"dáng vẻ đáng yêu"}],"traditional":"模樣"},{"id":"蒙","hanzi":"蒙","pinyin":"mēng","meaning_vi":"đoán bừa, lừa gạt","explanation":"Động từ đa âm.","hsk_level":6,"tags":["dong-tu"],"image":"🤔","examples":[{"type":"basic","zh":"这道题我蒙对了。","pinyin":"Zhè dào tí wǒ mēng duìle.","vi":"Câu này tôi đoán bừa mà trúng."},{"type":"simple","zh":"别想用这种小把戏蒙我。","pinyin":"Biéxiǎng yòng zhè zhǒng xiǎo bǎxì mēng wǒ.","vi":"Đừng hòng dùng trò vặt này để lừa tôi."},{"type":"compound","zh":"如果不会做选择题，就只能凭运气蒙一个答案了。","pinyin":"Rúguǒ bú huì zuò xuǎnzétí, jiù zhǐnéng píng yùnqi mēng yí gè dá'àn le.","vi":"Nếu không biết làm câu trắc nghiệm thì chỉ còn cách dựa vào vận may đoán bừa một đáp án."}],"related":[{"hanzi":"瞎猜","pinyin":"xiācāi","vi":"đoán mò"},{"hanzi":"欺骗","pinyin":"qīpiàn","vi":"lừa dối"},{"hanzi":"蒙混过关","pinyin":"ménghùnguòguān","vi":"lừa lọc cho qua"},{"hanzi":"蒙在鼓里","pinyin":"méngzàigǔlǐ","vi":"bị che mắt"}]},{"id":"美德","hanzi":"美德","pinyin":"měidé","meaning_vi":"mỹ đức, đức tính tốt đẹp","explanation":"美 (đẹp) + 德 (đức hạnh).","hsk_level":6,"tags":["danh-tu","van-hoa"],"image":"🌟","examples":[{"type":"basic","zh":"诚实是一种美德。","pinyin":"Chéngshí shì yì zhǒng měidé.","vi":"Trung thực là một đức tính tốt."},{"type":"simple","zh":"尊老爱幼是中华民族的传统美德。","pinyin":"Zūnlǎo ài yòu shì Zhōnghuámínzú de chuántǒng měidé.","vi":"Kính già yêu trẻ là truyền thống tốt đẹp của dân tộc Trung Hoa."},{"type":"compound","zh":"节俭虽然是美德，但是过分节俭就成了吝啬。","pinyin":"Jiéjiǎn suīrán shì měidé, dànshì guòfèn jiéjiǎn jiù chéngle lìnsè.","vi":"Tiết kiệm tuy là đức tính tốt nhưng tiết kiệm quá mức thì thành keo kiệt."}],"related":[{"hanzi":"品德","pinyin":"pǐndé","vi":"phẩm đức"},{"hanzi":"传统美德","pinyin":"chuántǒngměidé","vi":"đức tính truyền thống"},{"hanzi":"道德","pinyin":"dàodé","vi":"đạo đức"},{"hanzi":"恶习","pinyin":"èxí","vi":"thói xấu"}]},{"id":"美观","hanzi":"美观","pinyin":"měiguān","meaning_vi":"đẹp mắt, mỹ quan","explanation":"美 (mỹ – đẹp) + 观 (quan – nhìn) → nhìn đẹp mắt, thường tả đồ vật, kiến trúc. Cụm: 美观大方.","hsk_level":6,"tags":["tinh-tu"],"image":"✨","examples":[{"type":"basic","zh":"这个设计很美观。","pinyin":"Zhè gè shèjì hěn měiguān.","vi":"Thiết kế này rất đẹp mắt."},{"type":"simple","zh":"包装美观的月饼卖得特别快。","pinyin":"Bāozhuāng měiguān de yuèbing mài de tèbié kuài.","vi":"Bánh trung thu có bao bì đẹp mắt bán đặc biệt chạy."},{"type":"compound","zh":"这款实木书架不但外形美观，而且非常结实。","pinyin":"Zhè kuǎn shímù shūjià búdàn wàixíng měiguān, érqiě fēicháng jiēshi.","vi":"Kệ sách gỗ nguyên khối này không những có kiểu dáng đẹp mắt mà còn rất chắc chắn."}],"related":[{"hanzi":"好看","pinyin":"hǎokàn","vi":"đẹp"},{"hanzi":"漂亮","pinyin":"piàoliang","vi":"xinh đẹp"},{"hanzi":"美观大方","pinyin":"měiguāndàfang","vi":"đẹp đẽ trang nhã"},{"hanzi":"实用","pinyin":"shíyòng","vi":"thực dụng"}],"traditional":"美觀"},{"id":"每况愈下","hanzi":"每况愈下","pinyin":"měikuàng-yùxià","meaning_vi":"ngày càng sa sút tồi tệ hơn","explanation":"每况 (mỗi lần xét) + 愈下 (càng xuống thấp) → tình hình ngày càng tệ đi. Gốc từ câu 每下愈况 trong Trang Tử.","hsk_level":6,"tags":["thanh-ngu"],"image":"📉","examples":[{"type":"basic","zh":"他的健康每况愈下。","pinyin":"Tā de jiànkāng měikuàngyùxià.","vi":"Sức khỏe của ông ấy ngày càng sa sút."},{"type":"simple","zh":"这家老字号饭店的生意每况愈下。","pinyin":"Zhè jiālǎo zìhao fàndiàn de shēngyi měikuàngyùxià.","vi":"Việc kinh doanh của nhà hàng lâu năm này ngày càng sa sút."},{"type":"compound","zh":"因为他沉迷游戏，所以学习成绩每况愈下。","pinyin":"Yīnwèi tā chénmí yóuxì, suǒyǐ xuéxí chéngjì měikuàngyùxià.","vi":"Vì cậu ấy mê trò chơi điện tử nên thành tích học tập ngày càng tệ."}],"related":[{"hanzi":"江河日下","pinyin":"jiānghérìxià","vi":"ngày càng sa sút"},{"hanzi":"一落千丈","pinyin":"yíluòqiānzhàng","vi":"tụt dốc thê thảm"},{"hanzi":"蒸蒸日上","pinyin":"zhēngzhēngrìshàng","vi":"ngày càng phát đạt"},{"hanzi":"恶化","pinyin":"èhuà","vi":"xấu đi"}],"traditional":"每況愈下"},{"id":"美中不足","hanzi":"美中不足","pinyin":"měizhōng-bùzú","meaning_vi":"vết gợn nhỏ trong cái đẹp hoàn hảo","explanation":"美中 + 不足 (chưa đủ). Thành ngữ.","hsk_level":6,"tags":["thanh-ngu"],"image":"🌸","examples":[{"type":"basic","zh":"这真是美中不足。","pinyin":"Zhè zhēn shì měizhōngbùzú.","vi":"Đây đúng là một điểm trừ nhỏ."},{"type":"simple","zh":"酒店唯一美中不足的是离地铁站太远。","pinyin":"Jiǔdiàn wéiyī měizhōngbùzú de shì lí dìtiězhàn tài yuǎn.","vi":"Điều duy nhất chưa hoàn hảo của khách sạn là cách ga tàu điện ngầm quá xa."},{"type":"compound","zh":"虽然婚礼很完美，但是美中不足的是下了一场雨。","pinyin":"Suīrán hūnlǐ hěn wánměi, dànshì měizhōngbùzú de shì xiàle yì cháng yǔ.","vi":"Tuy đám cưới rất hoàn hảo nhưng điểm trừ nhỏ là có một trận mưa."}],"related":[{"hanzi":"白璧微瑕","pinyin":"báibìwēixiá","vi":"ngọc trắng có vết"},{"hanzi":"遗憾","pinyin":"yíhàn","vi":"đáng tiếc"},{"hanzi":"十全十美","pinyin":"shíquánshíměi","vi":"thập toàn thập mỹ"},{"hanzi":"缺点","pinyin":"quēdiǎn","vi":"khuyết điểm"}]},{"id":"摸着石头过河","hanzi":"摸着石头过河","pinyin":"mōzhe shítou guòhé","meaning_vi":"dò đá qua sông (vừa làm vừa rút kinh nghiệm)","explanation":"Câu nói nổi tiếng thời cải cách.","hsk_level":6,"tags":["thanh-ngu"],"image":"🌊","examples":[{"type":"basic","zh":"我们只能摸着石头过河。","pinyin":"Wǒmen zhǐnéng mōzheshítouguòhé.","vi":"Chúng ta chỉ có thể dò đá qua sông."},{"type":"simple","zh":"他们摸着石头过河建立了第一家网店。","pinyin":"Tāmen mōzheshítouguòhé jiànlìle dì yījiā wǎngdiàn.","vi":"Họ vừa làm vừa rút kinh nghiệm để mở cửa hàng trực tuyến đầu tiên."},{"type":"compound","zh":"既然没有经验可以借鉴，我们就只好摸着石头过河。","pinyin":"Jìrán méiyǒu jīngyàn kěyǐ jièjiàn, wǒmen jiù zhǐhǎo mōzheshítouguòhé.","vi":"Đã không có kinh nghiệm nào để tham khảo thì chúng ta đành dò đá qua sông."}],"related":[{"hanzi":"摸索","pinyin":"mōsuǒ","vi":"mò mẫm tìm tòi"},{"hanzi":"试验","pinyin":"shìyàn","vi":"thử nghiệm"},{"hanzi":"积累经验","pinyin":"jīlěijīngyàn","vi":"tích lũy kinh nghiệm"},{"hanzi":"循序渐进","pinyin":"xúnxùjiànjìn","vi":"tuần tự tiến lên"}],"traditional":"摸著石頭過河"},{"id":"码头","hanzi":"码头","pinyin":"mǎtou","meaning_vi":"bến tàu, cầu cảng","explanation":"码 (mã) + 头 (đầu) → bến tàu, cầu cảng nơi tàu thuyền neo đậu, bốc dỡ hàng và đón khách.","hsk_level":6,"tags":["danh-tu","dia-diem","giao-thong"],"image":"⚓","examples":[{"type":"basic","zh":"船到码头了。","pinyin":"Chuán dào mǎtou le.","vi":"Thuyền đã đến bến."},{"type":"simple","zh":"工人们正在码头上搬运集装箱。","pinyin":"Gōngrénmen zhèngzài mǎtou shàng bānyùn jízhuāngxiāng.","vi":"Công nhân đang bốc dỡ container trên cầu cảng."},{"type":"compound","zh":"我们刚一跑到码头，去对岸的渡船就开走了。","pinyin":"Wǒmen gāngyì pǎo dào mǎtou, qù duì'àn de dùchuán jiù kāizǒu le.","vi":"Chúng tôi vừa chạy đến bến thì chiếc phà sang bờ bên kia đã rời đi."}],"related":[{"hanzi":"港口","pinyin":"gǎngkǒu","vi":"cảng"},{"hanzi":"渡口","pinyin":"dùkǒu","vi":"bến đò"},{"hanzi":"轮船","pinyin":"lúnchuán","vi":"tàu thủy"},{"hanzi":"装卸","pinyin":"zhuāngxiè","vi":"bốc dỡ hàng"}],"traditional":"碼頭"},{"id":"满怀","hanzi":"满怀","pinyin":"mǎnhuái","meaning_vi":"tràn đầy (niềm tin/hy vọng)","explanation":"满 (đầy) + 怀 (lòng). Cụm: 满怀信心.","hsk_level":6,"tags":["dong-tu","cam-xuc"],"image":"💖","examples":[{"type":"basic","zh":"她满怀希望。","pinyin":"Tā mǎnhuái xīwàng.","vi":"Cô ấy tràn đầy hy vọng."},{"type":"simple","zh":"新生们满怀信心地走进了大学校园。","pinyin":"Xīnshēngmen mǎnhuái xìnxīn de zǒujìnle dàxué xiàoyuán.","vi":"Tân sinh viên tràn đầy tự tin bước vào khuôn viên đại học."},{"type":"compound","zh":"虽然他满怀热情地创业，但是最后还是失败了。","pinyin":"Suīrán tā mǎnhuái rèqíng de chuàngyè, dànshì zuìhòu háishì shībài le.","vi":"Tuy anh ấy khởi nghiệp với đầy nhiệt huyết nhưng cuối cùng vẫn thất bại."}],"related":[{"hanzi":"充满","pinyin":"chōngmǎn","vi":"tràn đầy"},{"hanzi":"满怀信心","pinyin":"mǎnhuáixìnxīn","vi":"tràn đầy tự tin"},{"hanzi":"满怀希望","pinyin":"mǎnhuáixīwàng","vi":"tràn đầy hy vọng"},{"hanzi":"满腔","pinyin":"mǎnqiāng","vi":"đầy lòng"}],"traditional":"滿懷"},{"id":"满载而归","hanzi":"满载而归","pinyin":"mǎnzài-érguī","meaning_vi":"thu hoạch đầy ắp trở về","explanation":"满载 (chở đầy) + 而归 (mà về) → trở về với đầy ắp thu hoạch, thành quả. Thường dùng sau chuyến đi, cuộc thi.","hsk_level":6,"tags":["thanh-ngu"],"image":"🌾","examples":[{"type":"basic","zh":"渔船满载而归。","pinyin":"Yúchuán mǎnzài'érguī.","vi":"Thuyền đánh cá trở về đầy ắp."},{"type":"simple","zh":"参观团从书展上满载而归。","pinyin":"Cānguān tuán cóng shūzhǎn shàng mǎnzài'érguī.","vi":"Đoàn tham quan trở về từ hội sách với đầy ắp thu hoạch."},{"type":"compound","zh":"虽然这次考察时间很短，但是大家都满载而归。","pinyin":"Suīrán zhè cì kǎochá shíjiān hěn duǎn, dànshì dàjiā dōu mǎnzài'érguī.","vi":"Tuy chuyến khảo sát lần này rất ngắn nhưng ai cũng trở về với nhiều thu hoạch."}],"related":[{"hanzi":"收获","pinyin":"shōuhuò","vi":"thu hoạch"},{"hanzi":"硕果累累","pinyin":"shuòguǒlěilěi","vi":"thành quả dồi dào"},{"hanzi":"空手而归","pinyin":"kōngshǒu'érguī","vi":"về tay không"},{"hanzi":"丰收","pinyin":"fēngshōu","vi":"được mùa"}],"traditional":"滿載而歸"},{"id":"敏捷","hanzi":"敏捷","pinyin":"mǐnjié","meaning_vi":"nhanh nhẹn, lanh lẹ","explanation":"敏 (mẫn – nhanh nhạy) + 捷 (tiệp – nhanh) → động tác hoặc tư duy nhanh nhẹn. Cụm: 思维敏捷, 动作敏捷.","hsk_level":6,"tags":["tinh-tu"],"image":"⚡","examples":[{"type":"basic","zh":"猴子动作敏捷。","pinyin":"Hóuzi dòngzuò mǐnjié.","vi":"Khỉ có động tác nhanh nhẹn."},{"type":"simple","zh":"守门员敏捷地扑住了那个点球。","pinyin":"Shǒuményuán mǐnjié de pū zhùle nà gè diǎnqiú.","vi":"Thủ môn nhanh nhẹn bắt gọn quả phạt đền đó."},{"type":"compound","zh":"这位老人虽然八十岁了，但是思维仍然很敏捷。","pinyin":"Zhè wèi lǎorén suīrán bāshí suì le, dànshì sīwéi réngrán hěn mǐnjié.","vi":"Cụ già này tuy đã tám mươi tuổi nhưng tư duy vẫn rất nhanh nhạy."}],"related":[{"hanzi":"灵敏","pinyin":"língmǐn","vi":"nhạy bén"},{"hanzi":"灵活","pinyin":"línghuó","vi":"linh hoạt"},{"hanzi":"迟钝","pinyin":"chídùn","vi":"chậm chạp"},{"hanzi":"身手敏捷","pinyin":"shēnshǒumǐnjié","vi":"thân thủ nhanh nhẹn"}]},{"id":"念念不忘","hanzi":"念念不忘","pinyin":"niànniàn-búwàng","meaning_vi":"nhớ mãi không quên","explanation":"念念 (niệm niệm – lúc nào cũng nghĩ tới) + 不忘 (bất vong – không quên) → luôn ghi nhớ trong lòng, nhớ mãi không quên.","hsk_level":6,"tags":["thanh-ngu","cam-xuc"],"image":"💭","examples":[{"type":"basic","zh":"他对她念念不忘。","pinyin":"Tā duì tā niànniànbúwàng.","vi":"Anh ấy nhớ mãi cô ấy không quên."},{"type":"simple","zh":"我至今念念不忘外婆做的红烧肉。","pinyin":"Wǒ zhìjīn niànniànbúwàng wàipó zuò de hóngshāoròu.","vi":"Đến nay tôi vẫn nhớ mãi món thịt kho của bà ngoại."},{"type":"compound","zh":"他之所以念念不忘那座小城，是因为初恋就发生在那里。","pinyin":"Tā zhīsuǒyǐ niànniànbúwàng nà zuò xiǎochéng, shì yīnwèi chūliàn jiù fāshēng zài nàlǐ.","vi":"Sở dĩ anh ấy nhớ mãi không quên thị trấn nhỏ ấy là vì mối tình đầu đã diễn ra ở đó."}],"related":[{"hanzi":"耿耿于怀","pinyin":"gěnggěngyúhuái","vi":"canh cánh trong lòng"},{"hanzi":"铭记在心","pinyin":"míngjìzàixīn","vi":"ghi nhớ trong lòng"},{"hanzi":"难忘","pinyin":"nánwàng","vi":"khó quên"},{"hanzi":"抛在脑后","pinyin":"pāozàinǎohòu","vi":"quên sạch"}]},{"id":"娘家","hanzi":"娘家","pinyin":"niángjia","meaning_vi":"nhà ngoại, nhà mẹ đẻ (của phụ nữ đã lấy chồng)","explanation":"娘 (mẹ) + 家 (nhà).","hsk_level":6,"tags":["danh-tu","gia-dinh"],"image":"🏡","examples":[{"type":"basic","zh":"她娘家在农村。","pinyin":"Tā niángjia zài nóngcūn.","vi":"Nhà mẹ đẻ cô ấy ở nông thôn."},{"type":"simple","zh":"姐姐大年初二带着孩子回了娘家。","pinyin":"Jiějie dà nián chū'èr dàizhe háizi huíle niángjia.","vi":"Chị gái dẫn con về nhà ngoại vào mùng hai Tết."},{"type":"compound","zh":"因为娘家离得很近，所以她周末常常回去看父母。","pinyin":"Yīnwèi niángjia lí de hěn jìn, suǒyǐ tā zhōumò chángcháng huíqù kàn fùmǔ.","vi":"Vì nhà mẹ đẻ ở gần nên cuối tuần cô ấy thường về thăm bố mẹ."}],"related":[{"hanzi":"婆家","pinyin":"pójia","vi":"nhà chồng"},{"hanzi":"回娘家","pinyin":"huíniángjia","vi":"về nhà ngoại"},{"hanzi":"嫁","pinyin":"jià","vi":"lấy chồng"},{"hanzi":"父母","pinyin":"fùmǔ","vi":"bố mẹ"}],"traditional":"孃家"},{"id":"捏","hanzi":"捏","pinyin":"niē","meaning_vi":"nặn, bóp, véo","explanation":"Bộ tài gảy 扌+ 圼.","hsk_level":6,"tags":["dong-tu"],"image":"🤏","examples":[{"type":"basic","zh":"他捏了捏我的脸。","pinyin":"Tā niēle niē wǒ de liǎn.","vi":"Anh ấy véo véo má tôi."},{"type":"simple","zh":"孩子们用彩色橡皮泥捏了一只小猫。","pinyin":"Háizimen yòng cǎisè xiàngpíní niēle yì zhī xiǎomāo.","vi":"Bọn trẻ dùng đất nặn màu nặn một chú mèo con."},{"type":"compound","zh":"你一捏这个小鸭子玩具，它就会发出嘎嘎的叫声。","pinyin":"Nǐ yì niē zhè gè xiǎo yāzi wánjù, tā jiù huì fāchū gāgā de jiàoshēng.","vi":"Bạn vừa bóp món đồ chơi chú vịt con này là nó sẽ kêu cạc cạc."}],"related":[{"hanzi":"捏造","pinyin":"niēzào","vi":"bịa đặt"},{"hanzi":"捏一把汗","pinyin":"niēyìbǎhàn","vi":"toát mồ hôi lo sợ"},{"hanzi":"揉","pinyin":"róu","vi":"nhào, xoa"},{"hanzi":"掐","pinyin":"qiā","vi":"véo, ngắt"}]},{"id":"捏造","hanzi":"捏造","pinyin":"niēzào","meaning_vi":"bịa đặt, vu khống","explanation":"捏 (nặn) + 造 (tạo ra).","hsk_level":6,"tags":["dong-tu","phap-luat"],"image":"🤥","examples":[{"type":"basic","zh":"这是捏造的谣言。","pinyin":"Zhè shì niēzào de yáoyán.","vi":"Đây là tin đồn bịa đặt."},{"type":"simple","zh":"那名记者因为捏造新闻被报社开除了。","pinyin":"Nà míngjì zhě yīnwèi niēzào xīnwén bèi bàoshè kāichú le.","vi":"Phóng viên đó bị tòa soạn sa thải vì bịa đặt tin tức."},{"type":"compound","zh":"如果有人捏造事实诽谤你，你就可以起诉他。","pinyin":"Rúguǒ yǒurén niēzào shìshí fěibàng nǐ, nǐ jiù kěyǐ qǐsù tā.","vi":"Nếu có người bịa đặt sự thật để vu khống bạn thì bạn có thể kiện người đó."}],"related":[{"hanzi":"编造","pinyin":"biānzào","vi":"bịa ra"},{"hanzi":"虚构","pinyin":"xūgòu","vi":"hư cấu"},{"hanzi":"诬陷","pinyin":"wūxiàn","vi":"vu cáo"},{"hanzi":"捏造事实","pinyin":"niēzàoshìshí","vi":"bịa đặt sự thật"}]},{"id":"扭转","hanzi":"扭转","pinyin":"niǔzhuǎn","meaning_vi":"xoay chuyển, vãn hồi (cục diện)","explanation":"扭 (vặn) + 转 (chuyển).","hsk_level":6,"tags":["dong-tu"],"image":"🔄","examples":[{"type":"basic","zh":"比分很难扭转。","pinyin":"Bǐfēn hěn nán niǔzhuǎn.","vi":"Tỷ số rất khó lật ngược."},{"type":"simple","zh":"新产品帮助公司扭转了亏损的局面。","pinyin":"Xīnchǎnpǐn bāngzhù gōngsī niǔzhuǎnle kuīsǔn de júmiàn.","vi":"Sản phẩm mới đã giúp công ty xoay chuyển tình trạng thua lỗ."},{"type":"compound","zh":"只要大家改变观念，就能扭转浪费粮食的风气。","pinyin":"Zhǐyào dàjiā gǎibiàn guānniàn, jiù néng niǔzhuǎn làngfèi liángshi de fēngqì.","vi":"Chỉ cần mọi người thay đổi quan niệm thì có thể xoay chuyển thói lãng phí lương thực."}],"related":[{"hanzi":"转变","pinyin":"zhuǎnbiàn","vi":"chuyển biến"},{"hanzi":"扭转局面","pinyin":"niǔzhuǎnjúmiàn","vi":"xoay chuyển cục diện"},{"hanzi":"逆转","pinyin":"nìzhuǎn","vi":"đảo ngược"},{"hanzi":"挽回","pinyin":"wǎnhuí","vi":"vãn hồi"}],"traditional":"扭轉"},{"id":"懦弱","hanzi":"懦弱","pinyin":"nuòruò","meaning_vi":"nhu nhược, yếu đuối","explanation":"懦 (nọa – hèn nhát) + 弱 (nhược – yếu) → nhu nhược, yếu đuối, thiếu dũng khí. Cụm: 性格懦弱.","hsk_level":6,"tags":["tinh-tu","con-nguoi"],"image":"😨","examples":[{"type":"basic","zh":"他性格懦弱。","pinyin":"Tā xìnggé nuòruò.","vi":"Tính cách anh ta nhu nhược."},{"type":"simple","zh":"懦弱的他从来不敢拒绝别人的要求。","pinyin":"Nuòruò de tā cóngláibù gǎn jùjué biérén de yāoqiú.","vi":"Anh ta nhu nhược, chưa bao giờ dám từ chối yêu cầu của người khác."},{"type":"compound","zh":"如果你一直这么懦弱，就会永远被人欺负。","pinyin":"Rúguǒ nǐ yìzhí zhème nuòruò, jiù huì yǒngyuǎn bèi rén qīfu.","vi":"Nếu bạn cứ nhu nhược như vậy thì sẽ mãi bị người khác bắt nạt."}],"related":[{"hanzi":"软弱","pinyin":"ruǎnruò","vi":"yếu đuối"},{"hanzi":"胆小","pinyin":"dǎnxiǎo","vi":"nhát gan"},{"hanzi":"坚强","pinyin":"jiānqiáng","vi":"kiên cường"},{"hanzi":"怯懦","pinyin":"qiènuò","vi":"nhút nhát"}]},{"id":"挪用","hanzi":"挪用","pinyin":"nuóyòng","meaning_vi":"biển thủ, dùng sai mục đích (công quỹ)","explanation":"挪 (dời) + 用 (dùng).","hsk_level":6,"tags":["dong-tu","phap-luat"],"image":"💸","examples":[{"type":"basic","zh":"他挪用了公款。","pinyin":"Tā nuóyòngle gōngkuǎn.","vi":"Hắn đã biển thủ công quỹ."},{"type":"simple","zh":"会计因挪用公司资金被警方逮捕了。","pinyin":"Kuàijì yīn nuóyòng gōngsī zījīn bèi jǐngfāng dàibǔ le.","vi":"Kế toán bị cảnh sát bắt vì biển thủ tiền của công ty."},{"type":"compound","zh":"即使家里急需用钱，他也不肯挪用一分救灾款。","pinyin":"Jíshǐ jiālǐ jíxū yòngqián, tā yě bùkěn nuóyòng yì fēn jiùzāikuǎn.","vi":"Dù nhà đang cần tiền gấp, anh ấy cũng không chịu dùng sai một xu tiền cứu trợ."}],"related":[{"hanzi":"挪用公款","pinyin":"nuóyònggōngkuǎn","vi":"biển thủ công quỹ"},{"hanzi":"贪污","pinyin":"tānwū","vi":"tham ô"},{"hanzi":"侵占","pinyin":"qīnzhàn","vi":"chiếm đoạt"},{"hanzi":"专款专用","pinyin":"zhuānkuǎnzhuānyòng","vi":"dùng đúng mục đích"}]},{"id":"耐人寻味","hanzi":"耐人寻味","pinyin":"nàirén-xúnwèi","meaning_vi":"sâu sắc đáng suy ngẫm","explanation":"耐 (nại – chịu được) 人 (người) 寻味 (tầm vị – tìm vị) → khiến người ta nghiền ngẫm mãi; ý vị sâu xa, đáng suy ngẫm.","hsk_level":6,"tags":["thanh-ngu"],"image":"🤔","examples":[{"type":"basic","zh":"他的话耐人寻味。","pinyin":"Tā dehuà nàirénxúnwèi.","vi":"Lời anh ấy nói đáng để suy ngẫm."},{"type":"simple","zh":"这部电影的结局留下了一个耐人寻味的悬念。","pinyin":"Zhè bù diànyǐng de jiéjú liúxiàle yí gè nàirénxúnwèi de xuánniàn.","vi":"Kết thúc bộ phim để lại một nút thắt đáng suy ngẫm."},{"type":"compound","zh":"这首诗虽然很短，但是每一句都耐人寻味。","pinyin":"Zhè shǒu shī suīrán hěn duǎn, dànshì měi yíjù dōu nàirénxúnwèi.","vi":"Bài thơ này tuy rất ngắn nhưng câu nào cũng đáng để ngẫm nghĩ."}],"related":[{"hanzi":"意味深长","pinyin":"yìwèishēncháng","vi":"ý vị sâu xa"},{"hanzi":"回味无穷","pinyin":"huíwèiwúqióng","vi":"dư vị vô tận"},{"hanzi":"发人深省","pinyin":"fārénshēnxǐng","vi":"khiến người suy ngẫm"},{"hanzi":"索然无味","pinyin":"suǒránwúwèi","vi":"nhạt nhẽo"}],"traditional":"耐人尋味"},{"id":"耐用","hanzi":"耐用","pinyin":"nàiyòng","meaning_vi":"bền, dùng bền","explanation":"耐 (nại – chịu được) + 用 (dụng – dùng) → chịu được dùng lâu, bền. Cụm: 经久耐用.","hsk_level":6,"tags":["tinh-tu","mua-sam"],"image":"💪","examples":[{"type":"basic","zh":"这双鞋很耐用。","pinyin":"Zhè shuāng xié hěn nàiyòng.","vi":"Đôi giày này rất bền."},{"type":"simple","zh":"爷爷用了二十年的收音机特别耐用。","pinyin":"Yéye yòngle èrshí nián de shōuyīnjī tèbié nàiyòng.","vi":"Chiếc radio ông nội dùng hai mươi năm cực kỳ bền."},{"type":"compound","zh":"这种锅虽然贵一点，但是比普通的锅耐用得多。","pinyin":"Zhè zhǒng guō suīrán guì yìdiǎn, dànshì bǐ pǔtōng de guō nàiyòng de duō.","vi":"Loại nồi này tuy hơi đắt nhưng bền hơn nồi thường nhiều."}],"related":[{"hanzi":"结实","pinyin":"jiēshi","vi":"chắc chắn"},{"hanzi":"经久耐用","pinyin":"jīngjiǔnàiyòng","vi":"bền lâu"},{"hanzi":"耐穿","pinyin":"nàichuān","vi":"mặc bền"},{"hanzi":"不耐用","pinyin":"búnàiyòng","vi":"không bền"}]},{"id":"拿手好戏","hanzi":"拿手好戏","pinyin":"náshǒu-hǎoxì","meaning_vi":"tiết mục sở trường, tài nghệ giỏi nhất","explanation":"拿手 (sở trường, giỏi) + 好戏 (vở diễn hay) → vở diễn tủ của diễn viên → nghĩa bóng: việc mình giỏi nhất, nghề tủ.","hsk_level":6,"tags":["thanh-ngu"],"image":"🌟","examples":[{"type":"basic","zh":"做饺子是她的拿手好戏。","pinyin":"Zuò jiǎozi shì tā de náshǒuhǎoxì.","vi":"Gói bánh sủi cảo là sở trường của cô ấy."},{"type":"simple","zh":"模仿明星唱歌是小刚的拿手好戏。","pinyin":"Mófǎng míngxīng chànggē shì xiǎo gāng de náshǒuhǎoxì.","vi":"Bắt chước ngôi sao hát là tiết mục sở trường của Tiểu Cương."},{"type":"compound","zh":"既然讲故事是你的拿手好戏，今晚就由你来讲吧。","pinyin":"Jìrán jiǎng gùshi shì nǐ de náshǒuhǎoxì, jīnwǎn jiù yóu nǐ láijiǎng ba.","vi":"Kể chuyện đã là sở trường của bạn thì tối nay để bạn kể nhé."}],"related":[{"hanzi":"拿手","pinyin":"náshǒu","vi":"sở trường"},{"hanzi":"看家本领","pinyin":"kānjiāběnlǐng","vi":"tài nghệ sở trường"},{"hanzi":"擅长","pinyin":"shàncháng","vi":"giỏi về"},{"hanzi":"绝活","pinyin":"juéhuó","vi":"tuyệt kỹ"}],"traditional":"拿手好戲"},{"id":"难堪","hanzi":"难堪","pinyin":"nánkān","meaning_vi":"khó xử, bẽ mặt, khó chịu","explanation":"难 (khó) + 堪 (chịu đựng).","hsk_level":6,"tags":["tinh-tu","cam-xuc"],"image":"😳","examples":[{"type":"basic","zh":"场面十分难堪。","pinyin":"Chǎngmiàn shífēn nánkān.","vi":"Tình cảnh vô cùng khó xử."},{"type":"simple","zh":"老师的批评让他在全班面前很难堪。","pinyin":"Lǎoshī de pīpíng ràng tā zài quánbān miànqián hěn nánkān.","vi":"Lời phê bình của thầy khiến cậu ấy bẽ mặt trước cả lớp."},{"type":"compound","zh":"如果你当众指出他的错误，他就会很难堪。","pinyin":"Rúguǒ nǐ dāngzhòng zhǐchū tā de cuòwù, tā jiù huì hěn nánkān.","vi":"Nếu bạn chỉ ra lỗi của anh ấy trước mặt mọi người thì anh ấy sẽ rất khó xử."}],"related":[{"hanzi":"尴尬","pinyin":"gāngà","vi":"lúng túng"},{"hanzi":"难为情","pinyin":"nánwéiqíng","vi":"ngượng ngùng"},{"hanzi":"丢脸","pinyin":"diūliǎn","vi":"mất mặt"},{"hanzi":"狼狈","pinyin":"lángbèi","vi":"chật vật"}],"traditional":"難堪"},{"id":"难能可贵","hanzi":"难能可贵","pinyin":"nánnéng-kěguì","meaning_vi":"hiếm có đáng quý","explanation":"难能 (nan năng – khó làm được) + 可贵 (khả quý – đáng quý) → làm được việc khó nên rất đáng trân trọng.","hsk_level":6,"tags":["thanh-ngu"],"image":"💎","examples":[{"type":"basic","zh":"这种精神难能可贵。","pinyin":"Zhè zhǒng jīngshén nánnéngkěguì.","vi":"Tinh thần này hiếm có đáng quý."},{"type":"simple","zh":"年轻人坚持五年做义工是难能可贵的。","pinyin":"Niánqīngrén jiānchí wǔ nián zuò yìgōng shì nánnéngkěguì de.","vi":"Người trẻ kiên trì làm tình nguyện suốt năm năm là điều hiếm có đáng quý."},{"type":"compound","zh":"虽然他自己并不富裕，但是每月资助贫困学生，真是难能可贵。","pinyin":"Suīrán tā zìjǐ bìngbú fùyù, dànshì měiyuè zīzhù pínkùn xuésheng, zhēn shì nánnéngkěguì.","vi":"Tuy bản thân không hề khá giả nhưng tháng nào anh ấy cũng hỗ trợ học sinh nghèo, thật hiếm có đáng quý."}],"related":[{"hanzi":"可贵","pinyin":"kěguì","vi":"đáng quý"},{"hanzi":"珍贵","pinyin":"zhēnguì","vi":"quý giá"},{"hanzi":"难得","pinyin":"nándé","vi":"hiếm có"},{"hanzi":"来之不易","pinyin":"láizhībúyì","vi":"có được không dễ"}],"traditional":"難能可貴"},{"id":"南辕北辙","hanzi":"南辕北辙","pinyin":"nányuán-běizhé","meaning_vi":"việc làm trái ngược với mục đích (muốn về nam lại đánh xe lên bắc)","explanation":"Muốn đi về nam mà cho xe chạy về bắc (辕 – càng xe, 辙 – vết bánh xe; truyện trong Chiến Quốc sách) → hành động đi ngược mục đích, càng làm càng xa.","hsk_level":6,"tags":["thanh-ngu"],"image":"🧭","examples":[{"type":"basic","zh":"这样做南辕北辙。","pinyin":"Zhèyàng zuò nányuánběizhé.","vi":"Làm như vậy là đi ngược với mục tiêu."},{"type":"simple","zh":"靠节食减肥常常会南辕北辙。","pinyin":"Kào jiéshí jiǎnféi chángcháng huì nányuánběizhé.","vi":"Giảm cân bằng cách nhịn ăn thường lại phản tác dụng."},{"type":"compound","zh":"如果方向错了，就是再努力也只是南辕北辙。","pinyin":"Rúguǒ fāngxiàng cuò le, jiùshì zài nǔlì yě zhǐshì nányuánběizhé.","vi":"Nếu sai hướng thì dù có cố gắng đến đâu cũng chỉ càng đi càng xa mục tiêu."}],"related":[{"hanzi":"背道而驰","pinyin":"bèidào'érchí","vi":"đi ngược đường"},{"hanzi":"事与愿违","pinyin":"shìyǔyuànwéi","vi":"việc trái ý muốn"},{"hanzi":"适得其反","pinyin":"shìdéqífǎn","vi":"phản tác dụng"},{"hanzi":"殊途同归","pinyin":"shūtútóngguī","vi":"khác đường cùng đích"}],"traditional":"南轅北轍"},{"id":"内分泌","hanzi":"内分泌","pinyin":"nèifēnmì","meaning_vi":"nội tiết","explanation":"内 + 分泌 (bài tiết).","hsk_level":6,"tags":["danh-tu","suc-khoe","khoa-hoc"],"image":"🩺","examples":[{"type":"basic","zh":"她内分泌失调。","pinyin":"Tā nèifēnmì shītiáo.","vi":"Cô ấy bị rối loạn nội tiết."},{"type":"simple","zh":"长期压力过大会影响人体的内分泌系统。","pinyin":"Chángqī yālìguò dàhuì yǐngxiǎng réntǐ de nèifēnmì xìtǒng.","vi":"Áp lực quá lớn trong thời gian dài sẽ ảnh hưởng đến hệ nội tiết của cơ thể."},{"type":"compound","zh":"因为内分泌出了问题，所以她脸上长了很多痘痘。","pinyin":"Yīnwèi nèifēnmì chūle wèntí, suǒyǐ tā liǎn shàng zhǎngle hěn duō dòudou.","vi":"Vì nội tiết có vấn đề nên mặt cô ấy nổi rất nhiều mụn."}],"related":[{"hanzi":"激素","pinyin":"jīsù","vi":"hormone"},{"hanzi":"内分泌失调","pinyin":"nèifēnmì shītiáo","vi":"rối loạn nội tiết"},{"hanzi":"腺体","pinyin":"xiàntǐ","vi":"tuyến"},{"hanzi":"甲状腺","pinyin":"jiǎzhuàngxiàn","vi":"tuyến giáp"}],"traditional":"內分泌"},{"id":"内疚","hanzi":"内疚","pinyin":"nèijiù","meaning_vi":"áy náy, cắn rứt lương tâm","explanation":"内 (bên trong) + 疚 (day dứt).","hsk_level":6,"tags":["tinh-tu","cam-xuc"],"image":"😔","examples":[{"type":"basic","zh":"我感到很内疚。","pinyin":"Wǒ gǎndào hěn nèijiù.","vi":"Tôi cảm thấy rất áy náy."},{"type":"simple","zh":"他为错过女儿的毕业典礼而深感内疚。","pinyin":"Tā wèi cuòguò nǚ'ér de bìyè diǎnlǐ ér shēngǎn nèijiù.","vi":"Anh ấy vô cùng áy náy vì đã lỡ lễ tốt nghiệp của con gái."},{"type":"compound","zh":"只要一想起那次对妈妈发脾气，我就十分内疚。","pinyin":"Zhǐyào yì xiǎngqǐ nà cì duì māma fāpíqi, wǒ jiù shífēn nèijiù.","vi":"Chỉ cần nghĩ lại lần nổi nóng với mẹ hôm ấy là tôi lại vô cùng áy náy."}],"related":[{"hanzi":"愧疚","pinyin":"kuìjiù","vi":"áy náy"},{"hanzi":"惭愧","pinyin":"cánkuì","vi":"hổ thẹn"},{"hanzi":"自责","pinyin":"zìzé","vi":"tự trách"},{"hanzi":"问心无愧","pinyin":"wènxīnwúkuì","vi":"không hổ thẹn với lòng"}],"traditional":"內疚"},{"id":"内在美","hanzi":"内在美","pinyin":"nèizàiměi","meaning_vi":"vẻ đẹp tâm hồn, vẻ đẹp bên trong","explanation":"内在 (nội tại – bên trong) + 美 (mỹ – đẹp) → vẻ đẹp bên trong, phẩm chất tâm hồn; đối lập 外在美 (vẻ đẹp bề ngoài).","hsk_level":6,"tags":["danh-tu","con-nguoi"],"image":"💖","examples":[{"type":"basic","zh":"内在美更重要。","pinyin":"Nèizàiměi gèng zhòngyào.","vi":"Vẻ đẹp bên trong quan trọng hơn."},{"type":"simple","zh":"善良和宽容都是一种内在美。","pinyin":"Shànliáng hé kuānróng dōu shì yì zhǒng nèizàiměi.","vi":"Lương thiện và bao dung đều là một vẻ đẹp tâm hồn."},{"type":"compound","zh":"外表的美会随着时间消失，而内在美却能保持一生。","pinyin":"Wàibiǎo de měi huì suízhe shíjiān xiāoshī, ér nèizàiměi què néng bǎochí yìshēng.","vi":"Vẻ đẹp bề ngoài sẽ phai nhạt theo thời gian, còn vẻ đẹp tâm hồn thì có thể giữ được cả đời."}],"related":[{"hanzi":"外在美","pinyin":"wàizàiměi","vi":"vẻ đẹp bề ngoài"},{"hanzi":"心灵美","pinyin":"xīnlíngměi","vi":"tâm hồn đẹp"},{"hanzi":"气质","pinyin":"qìzhì","vi":"khí chất"},{"hanzi":"外表","pinyin":"wàibiǎo","vi":"bề ngoài"}],"traditional":"內在美"},{"id":"能量","hanzi":"能量","pinyin":"néngliàng","meaning_vi":"năng lượng","explanation":"能 (năng – khả năng) + 量 (lượng) → năng lượng trong vật lý; nghĩa bóng sức mạnh tinh thần. Cụm: 正能量 (năng lượng tích cực).","hsk_level":6,"tags":["danh-tu","khoa-hoc"],"image":"⚡","examples":[{"type":"basic","zh":"香蕉能补充能量。","pinyin":"Xiāngjiāo néng bǔchōng néngliàng.","vi":"Chuối có thể bổ sung năng lượng."},{"type":"simple","zh":"运动员每天需要摄入大量能量。","pinyin":"Yùndòngyuán měitiān xūyào shèrù dàliàng néngliàng.","vi":"Vận động viên mỗi ngày cần nạp vào lượng lớn năng lượng."},{"type":"compound","zh":"只要和乐观的人在一起，你就会感受到正能量。","pinyin":"Zhǐyào hé lèguān de rén zài yìqǐ, nǐ jiù huì gǎn shòudào zhèngnéngliàng.","vi":"Chỉ cần ở bên những người lạc quan, bạn sẽ cảm nhận được năng lượng tích cực."}],"related":[{"hanzi":"能源","pinyin":"néngyuán","vi":"năng lượng, nguồn năng lượng"},{"hanzi":"热量","pinyin":"rèliàng","vi":"nhiệt lượng"},{"hanzi":"正能量","pinyin":"zhèngnéngliàng","vi":"năng lượng tích cực"},{"hanzi":"能量守恒","pinyin":"néngliàngshǒuhéng","vi":"bảo toàn năng lượng"}]},{"id":"能耐","hanzi":"能耐","pinyin":"néngnai","meaning_vi":"tài cán, bản lĩnh (khẩu ngữ)","explanation":"能 (năng – có khả năng) + 耐 (nại – chịu đựng) → khẩu ngữ: tài cán, bản lĩnh. Cụm: 有能耐, 你有多大能耐?","hsk_level":6,"tags":["danh-tu","con-nguoi"],"image":"💪","examples":[{"type":"basic","zh":"他真有能耐！","pinyin":"Tā zhēn yǒunéngnai!","vi":"Anh ấy thật có bản lĩnh!"},{"type":"simple","zh":"光靠嘴说可显示不出真正的能耐。","pinyin":"Guāng kào zuǐ shuō kě xiǎnshì bù chū zhēnzhèng de néngnai.","vi":"Chỉ nói suông thì không thể hiện được bản lĩnh thật sự."},{"type":"compound","zh":"这个孩子虽然年纪不大，但是能耐可不小。","pinyin":"Zhè gè háizi suīrán niánjì búdà, dànshì néngnai kěbù xiǎo.","vi":"Đứa trẻ này tuy tuổi còn nhỏ nhưng tài cán không hề nhỏ."}],"related":[{"hanzi":"本事","pinyin":"běnshi","vi":"bản lĩnh"},{"hanzi":"本领","pinyin":"běnlǐng","vi":"năng lực"},{"hanzi":"能力","pinyin":"nénglì","vi":"năng lực"},{"hanzi":"有能耐","pinyin":"yǒunéngnai","vi":"có tài"}]},{"id":"逆境","hanzi":"逆境","pinyin":"nìjìng","meaning_vi":"nghịch cảnh, hoàn cảnh khó khăn","explanation":"逆 (ngược) + 境 (hoàn cảnh). Đối nghĩa với 顺境.","hsk_level":6,"tags":["danh-tu"],"image":"⛰️","examples":[{"type":"basic","zh":"他身处逆境。","pinyin":"Tā shēnchǔ nìjìng.","vi":"Anh ấy đang ở trong nghịch cảnh."},{"type":"simple","zh":"她在逆境中自学完成了大学课程。","pinyin":"Tā zài nìjìng zhōng zìxué wánchéngle dàxué kèchéng.","vi":"Cô ấy tự học hoàn thành chương trình đại học trong nghịch cảnh."},{"type":"compound","zh":"即使遇到逆境，我们也不要轻易放弃希望。","pinyin":"Jíshǐ yùdào nìjìng, wǒmen yě bú yào qīngyì fàngqì xīwàng.","vi":"Dù gặp phải nghịch cảnh, chúng ta cũng đừng dễ dàng từ bỏ hy vọng."}],"related":[{"hanzi":"顺境","pinyin":"shùnjìng","vi":"thuận cảnh"},{"hanzi":"困境","pinyin":"kùnjìng","vi":"khốn cảnh"},{"hanzi":"挫折","pinyin":"cuòzhé","vi":"thất bại, trắc trở"},{"hanzi":"处境","pinyin":"chǔjìng","vi":"hoàn cảnh"}]},{"id":"逆转","hanzi":"逆转","pinyin":"nìzhuǎn","meaning_vi":"đảo ngược tình thế","explanation":"逆 + 转 (xoay chuyển).","hsk_level":6,"tags":["dong-tu","the-thao"],"image":"🔄","examples":[{"type":"basic","zh":"比赛被逆转了。","pinyin":"Bǐsài bèi nìzhuǎn le.","vi":"Trận đấu đã bị lội ngược dòng."},{"type":"simple","zh":"主队在最后五分钟完成了惊人的逆转。","pinyin":"Zhǔduì zài zuìhòu wǔ fēnzhōng wánchéngle jīngrén de nìzhuǎn.","vi":"Đội chủ nhà đã hoàn thành màn lội ngược dòng ngoạn mục trong năm phút cuối."},{"type":"compound","zh":"虽然上半场落后三分，但是他们最终逆转取胜。","pinyin":"Suīrán shàngbànchǎng luòhòu sānfēn, dànshì tāmen zuìzhōng nìzhuǎn qǔshèng.","vi":"Tuy hiệp một bị dẫn ba điểm nhưng cuối cùng họ đã lội ngược dòng giành chiến thắng."}],"related":[{"hanzi":"扭转","pinyin":"niǔzhuǎn","vi":"xoay chuyển"},{"hanzi":"反转","pinyin":"fǎnzhuǎn","vi":"đảo ngược"},{"hanzi":"不可逆转","pinyin":"bùkěnìzhuǎn","vi":"không thể đảo ngược"},{"hanzi":"转机","pinyin":"zhuǎnjī","vi":"bước ngoặt tốt"}],"traditional":"逆轉"},{"id":"宁肯","hanzi":"宁肯","pinyin":"nìngkěn","meaning_vi":"thà rằng","explanation":"宁 + 肯 (bằng lòng). Đồng nghĩa với 宁愿.","hsk_level":6,"tags":["pho-tu"],"image":"⚖️","examples":[{"type":"basic","zh":"我宁肯走路去。","pinyin":"Wǒ nìngkěn zǒulù qù.","vi":"Tôi thà đi bộ còn hơn."},{"type":"simple","zh":"她宁肯多花点钱买正版书。","pinyin":"Tā nìngkěn duō huā diǎn qián mǎi zhèngbǎn shū.","vi":"Cô ấy thà tốn thêm chút tiền để mua sách bản quyền."},{"type":"compound","zh":"宁肯少赚一点，也不能卖假冒伪劣的商品。","pinyin":"Nìngkěn shǎo zhuàn yìdiǎn, yě bù néng mài jiǎmàowěiliè de shāngpǐn.","vi":"Thà kiếm ít đi một chút cũng không được bán hàng giả hàng kém chất lượng."}],"related":[{"hanzi":"宁可","pinyin":"nìngkě","vi":"thà rằng"},{"hanzi":"宁愿","pinyin":"nìngyuàn","vi":"thà"},{"hanzi":"与其","pinyin":"yǔqí","vi":"thà... còn hơn"},{"hanzi":"宁死不屈","pinyin":"nìngsǐbùqū","vi":"thà chết không khuất phục"}],"traditional":"寧肯"},{"id":"宁死不屈","hanzi":"宁死不屈","pinyin":"nìngsǐ-bùqū","meaning_vi":"thà chết không khuất phục","explanation":"宁 (ninh – thà) 死 (tử – chết) 不屈 (bất khuất – không chịu khuất phục) → thà chết chứ không chịu đầu hàng; tả khí tiết anh hùng.","hsk_level":6,"tags":["thanh-ngu"],"image":"✊","examples":[{"type":"basic","zh":"战士们宁死不屈。","pinyin":"Zhànshìmen nìngsǐbùqū.","vi":"Các chiến sĩ thà chết không khuất phục."},{"type":"simple","zh":"这部电影讲述了一位宁死不屈的女英雄。","pinyin":"Zhè bù diànyǐng jiǎngshùle yí wèi nìngsǐbùqū de nǚ yīngxióng.","vi":"Bộ phim này kể về một nữ anh hùng thà chết không chịu khuất phục."},{"type":"compound","zh":"虽然敌人严刑拷打，但是他宁死不屈，什么也没说。","pinyin":"Suīrán dírén yánxíng kǎodǎ, dànshì tā nìngsǐbùqū, shénme yě méi shuō.","vi":"Tuy kẻ địch tra tấn dã man nhưng anh ấy thà chết không khuất phục, không nói nửa lời."}],"related":[{"hanzi":"坚贞不屈","pinyin":"jiānzhēnbùqū","vi":"kiên trinh bất khuất"},{"hanzi":"威武不屈","pinyin":"wēiwǔbùqū","vi":"không khuất phục uy vũ"},{"hanzi":"卑躬屈膝","pinyin":"bēigōngqūxī","vi":"khúm núm quỳ lụy"},{"hanzi":"视死如归","pinyin":"shìsǐrúguī","vi":"coi cái chết nhẹ tựa lông hồng"}],"traditional":"寧死不屈"},{"id":"泥泞","hanzi":"泥泞","pinyin":"nínìng","meaning_vi":"lầy lội, bùn lầy","explanation":"Cả hai chữ đều có bộ thủy 氵.","hsk_level":6,"tags":["tinh-tu","giao-thong"],"image":"🥾","examples":[{"type":"basic","zh":"山路很泥泞。","pinyin":"Shānlù hěn nínìng.","vi":"Đường núi rất lầy lội."},{"type":"simple","zh":"卡车陷在泥泞的乡间小路上动不了了。","pinyin":"Kǎchē xiàn zài nínìng de xiāngjiān xiǎolù shàng dòngbùliǎo le.","vi":"Chiếc xe tải sa lầy trên con đường quê lầy lội không nhúc nhích được."},{"type":"compound","zh":"一下雨，村口的土路就变得十分泥泞。","pinyin":"Yí xiàyǔ, cūn kǒu de tǔlù jiù biànde shífēn nínìng.","vi":"Hễ trời mưa là con đường đất đầu làng lại trở nên rất lầy lội."}],"related":[{"hanzi":"泥土","pinyin":"nítǔ","vi":"bùn đất"},{"hanzi":"泥巴","pinyin":"níba","vi":"bùn"},{"hanzi":"坎坷","pinyin":"kǎnkě","vi":"gập ghềnh"},{"hanzi":"平坦","pinyin":"píngtǎn","vi":"bằng phẳng"}],"traditional":"泥濘"},{"id":"凝聚","hanzi":"凝聚","pinyin":"níngjù","meaning_vi":"ngưng tụ, gắn kết","explanation":"凝 (ngưng – đông lại) + 聚 (tụ – tụ họp) → ngưng tụ (hơi nước); nghĩa bóng quy tụ, gắn kết. Cụm: 凝聚力 (sức gắn kết).","hsk_level":6,"tags":["dong-tu"],"image":"🤝","examples":[{"type":"basic","zh":"团队凝聚力很强。","pinyin":"Tuánduì níngjùlì hěn qiáng.","vi":"Sức gắn kết của đội rất mạnh."},{"type":"simple","zh":"这座大桥凝聚了几千名工人的心血。","pinyin":"Zhè zuò Dàqiáo níngjùle jǐqiān míng gōngrén de xīnxuè.","vi":"Cây cầu này kết tinh tâm huyết của mấy nghìn công nhân."},{"type":"compound","zh":"只要全国人民凝聚在一起，就没有克服不了的困难。","pinyin":"Zhǐyào quánguó rénmín níngjù zài yìqǐ, jiù méiyǒu kèfú bùliǎo de kùnnan.","vi":"Chỉ cần nhân dân cả nước đoàn kết gắn bó với nhau thì không có khó khăn nào không vượt qua được."}],"related":[{"hanzi":"凝聚力","pinyin":"níngjùlì","vi":"sức gắn kết"},{"hanzi":"团结","pinyin":"tuánjié","vi":"đoàn kết"},{"hanzi":"聚集","pinyin":"jùjí","vi":"tụ tập"},{"hanzi":"涣散","pinyin":"huànsàn","vi":"rời rạc"}]},{"id":"弄虚作假","hanzi":"弄虚作假","pinyin":"nòngxū-zuòjiǎ","meaning_vi":"gian dối làm giả","explanation":"弄 (lộng – bày ra) 虚 (hư – dối) 作 (tác – làm) 假 (giả) → bày trò gian dối, làm giả để lừa người.","hsk_level":6,"tags":["thanh-ngu"],"image":"🚫","examples":[{"type":"basic","zh":"不许弄虚作假！","pinyin":"Bùxǔ nòngxūzuòjiǎ!","vi":"Không được gian dối làm giả!"},{"type":"simple","zh":"这家工厂因弄虚作假被罚款五十万。","pinyin":"Zhè jiā gōngchǎng yīn nòngxūzuòjiǎ bèi fákuǎn wǔ shíwàn.","vi":"Nhà máy này bị phạt năm trăm nghìn tệ vì gian dối làm giả."},{"type":"compound","zh":"如果考试时弄虚作假，就会被取消成绩。","pinyin":"Rúguǒ kǎoshì shí nòngxūzuòjiǎ, jiù huì bèi qǔxiāo chéngjì.","vi":"Nếu gian lận trong khi thi thì sẽ bị hủy kết quả."}],"related":[{"hanzi":"作假","pinyin":"zuòjiǎ","vi":"làm giả"},{"hanzi":"欺骗","pinyin":"qīpiàn","vi":"lừa dối"},{"hanzi":"实事求是","pinyin":"shíshìqiúshì","vi":"thực sự cầu thị"},{"hanzi":"造假","pinyin":"zàojiǎ","vi":"làm giả"}],"traditional":"弄虛作假"},{"id":"浓厚","hanzi":"浓厚","pinyin":"nónghòu","meaning_vi":"nồng hậu, đậm đặc","explanation":"浓 (nùng – đậm) + 厚 (hậu – dày) → đậm đặc (mây, khói); nghĩa bóng sâu đậm (không khí, hứng thú). Cụm: 浓厚的兴趣.","hsk_level":6,"tags":["tinh-tu"],"image":"☕","examples":[{"type":"basic","zh":"他对历史兴趣浓厚。","pinyin":"Tā duì lìshǐ xìngqù nónghòu.","vi":"Anh ấy rất hứng thú với lịch sử."},{"type":"simple","zh":"春节前街上的节日气氛越来越浓厚。","pinyin":"Chūnjié qián jiēshàng de jiérì qìfēn yuèláiyuè nónghòu.","vi":"Trước Tết, không khí lễ hội trên phố ngày càng đậm đà."},{"type":"compound","zh":"这座古城不但历史悠久，而且文化氛围浓厚。","pinyin":"Zhè zuò gǔchéng búdàn lìshǐ yōujiǔ, érqiě wénhuà fēnwéi nónghòu.","vi":"Cổ thành này không những có lịch sử lâu đời mà còn đậm bầu không khí văn hóa."}],"related":[{"hanzi":"浓郁","pinyin":"nóngyù","vi":"nồng nàn"},{"hanzi":"深厚","pinyin":"shēnhòu","vi":"sâu đậm"},{"hanzi":"兴趣浓厚","pinyin":"xìngqùnónghòu","vi":"rất hứng thú"},{"hanzi":"淡薄","pinyin":"dànbó","vi":"nhạt nhòa"}],"traditional":"濃厚"},{"id":"浓重","hanzi":"浓重","pinyin":"nóngzhòng","meaning_vi":"đậm đặc, nồng nặc","explanation":"浓 (nùng – đậm) + 重 (trọng – nặng) → đậm và nặng (mùi, màu, khói, giọng địa phương). Cụm: 浓重的口音.","hsk_level":6,"tags":["tinh-tu"],"image":"🌫️","examples":[{"type":"basic","zh":"他口音很浓重。","pinyin":"Tā kǒuyīn hěn nóngzhòng.","vi":"Giọng địa phương của anh ấy rất nặng."},{"type":"simple","zh":"厨房里飘出一股浓重的辣椒味。","pinyin":"Chúfáng lǐ piāo chū yì gǔ nóngzhòng de làjiāo wèi.","vi":"Trong bếp bốc ra mùi ớt nồng nặc."},{"type":"compound","zh":"因为雾气浓重，所以高速公路暂时封闭了。","pinyin":"Yīnwèi wùqì nóngzhòng, suǒyǐ gāosùgōnglù zànshí fēngbì le.","vi":"Vì sương mù dày đặc nên đường cao tốc tạm thời bị đóng."}],"related":[{"hanzi":"浓厚","pinyin":"nónghòu","vi":"đậm đặc"},{"hanzi":"浓烈","pinyin":"nóngliè","vi":"nồng nặc"},{"hanzi":"沉重","pinyin":"chénzhòng","vi":"nặng nề"},{"hanzi":"淡","pinyin":"dàn","vi":"nhạt"}],"traditional":"濃重"},{"id":"奴役","hanzi":"奴役","pinyin":"núyì","meaning_vi":"nô dịch, bắt làm nô lệ","explanation":"奴 (nô lệ) + 役 (sai khiến).","hsk_level":6,"tags":["dong-tu","xa-hoi"],"image":"⛓️","examples":[{"type":"basic","zh":"他们曾被奴役。","pinyin":"Tāmen céng bèi núyì.","vi":"Họ từng bị bắt làm nô lệ."},{"type":"simple","zh":"殖民者奴役了当地人民几百年。","pinyin":"Zhímínzhě núyìle dāngdì rénmín jǐ bǎinián.","vi":"Thực dân đã nô dịch người dân địa phương hàng trăm năm."},{"type":"compound","zh":"如果人被手机奴役，就会失去很多生活乐趣。","pinyin":"Rúguǒ rén bèi shǒujī núyì, jiù huì shīqù hěn duō shēnghuó lèqù.","vi":"Nếu con người bị điện thoại nô dịch thì sẽ mất đi nhiều niềm vui cuộc sống."}],"related":[{"hanzi":"奴隶","pinyin":"núlì","vi":"nô lệ"},{"hanzi":"压迫","pinyin":"yāpò","vi":"áp bức"},{"hanzi":"剥削","pinyin":"bōxuē","vi":"bóc lột"},{"hanzi":"解放","pinyin":"jiěfàng","vi":"giải phóng"}]},{"id":"虐待","hanzi":"虐待","pinyin":"nüèdài","meaning_vi":"ngược đãi, hành hạ","explanation":"虐 (ngược – tàn ác) + 待 (đãi – đối xử) → đối xử tàn ác, hành hạ. Cụm: 虐待动物, 虐待儿童.","hsk_level":6,"tags":["dong-tu","phap-luat"],"image":"⚠️","examples":[{"type":"basic","zh":"虐待动物是违法的。","pinyin":"Nüèdài dòngwù shì wéifǎ de.","vi":"Ngược đãi động vật là vi phạm pháp luật."},{"type":"simple","zh":"那对夫妇因虐待养子被判了刑。","pinyin":"Nà duì fūfù yīn nüèdài yǎngzǐ bèi pànle xíng.","vi":"Cặp vợ chồng đó bị kết án vì ngược đãi con nuôi."},{"type":"compound","zh":"一旦发现有人虐待老人，就应该马上报警。","pinyin":"Yídàn fāxiàn yǒurén nüèdài lǎorén, jiù yīnggāi mǎshàng bàojǐng.","vi":"Một khi phát hiện có người ngược đãi người già thì nên báo cảnh sát ngay."}],"related":[{"hanzi":"折磨","pinyin":"zhémó","vi":"hành hạ"},{"hanzi":"欺负","pinyin":"qīfu","vi":"bắt nạt"},{"hanzi":"善待","pinyin":"shàndài","vi":"đối xử tốt"},{"hanzi":"家暴","pinyin":"jiābào","vi":"bạo lực gia đình"}]},{"id":"恼火","hanzi":"恼火","pinyin":"nǎohuǒ","meaning_vi":"bực mình, nổi cáu","explanation":"恼 (não – bực tức) + 火 (hỏa – lửa) → tức như lửa đốt; bực mình, nổi cáu. Cụm: 让人恼火.","hsk_level":6,"tags":["tinh-tu","cam-xuc"],"image":"😠","examples":[{"type":"basic","zh":"这事真让人恼火。","pinyin":"Zhè shì zhēn ràng rén nǎohuǒ.","vi":"Chuyện này thật khiến người ta bực mình."},{"type":"simple","zh":"楼上每天半夜的装修声让他很恼火。","pinyin":"Lóushàng měitiān bànyè de zhuāngxiū shēng ràng tā hěn nǎohuǒ.","vi":"Tiếng sửa nhà lúc nửa đêm ngày nào cũng có ở tầng trên khiến anh ấy rất bực."},{"type":"compound","zh":"因为快递又送错了地址，所以她非常恼火。","pinyin":"Yīnwèi kuàidì yòu sòng cuòle dìzhǐ, suǒyǐ tā fēicháng nǎohuǒ.","vi":"Vì hàng chuyển phát lại giao nhầm địa chỉ nên cô ấy vô cùng bực mình."}],"related":[{"hanzi":"生气","pinyin":"shēngqì","vi":"tức giận"},{"hanzi":"恼怒","pinyin":"nǎonù","vi":"nổi giận"},{"hanzi":"烦躁","pinyin":"fánzào","vi":"bực bội"},{"hanzi":"心平气和","pinyin":"xīnpíngqìhé","vi":"bình tâm"}],"traditional":"惱火"},{"id":"恼怒","hanzi":"恼怒","pinyin":"nǎonù","meaning_vi":"tức giận, nổi giận","explanation":"恼 (bực) + 怒 (giận).","hsk_level":6,"tags":["tinh-tu","cam-xuc"],"image":"😡","examples":[{"type":"basic","zh":"他显得很恼怒。","pinyin":"Tā xiǎnde hěn nǎonù.","vi":"Anh ấy trông rất tức giận."},{"type":"simple","zh":"经理恼怒地把报告扔在了桌子上。","pinyin":"Jīnglǐ nǎonù de bǎ bàogào rēng zài le zhuōzi shàng.","vi":"Giám đốc tức giận ném bản báo cáo lên bàn."},{"type":"compound","zh":"虽然对方的话让他很恼怒，但是他还是忍住了。","pinyin":"Suīrán duìfāng dehuà ràng tā hěn nǎonù, dànshì tā háishì rěn zhù le.","vi":"Tuy lời của đối phương khiến anh ấy rất tức giận nhưng anh vẫn nhịn được."}],"related":[{"hanzi":"愤怒","pinyin":"fènnù","vi":"phẫn nộ"},{"hanzi":"恼火","pinyin":"nǎohuǒ","vi":"bực mình"},{"hanzi":"恼羞成怒","pinyin":"nǎoxiūchéngnù","vi":"xấu hổ hóa giận"},{"hanzi":"息怒","pinyin":"xīnù","vi":"nguôi giận"}],"traditional":"惱怒"},{"id":"片段","hanzi":"片段","pinyin":"piànduàn","meaning_vi":"đoạn, trích đoạn","explanation":"片 (phiến – mảnh) + 段 (đoạn) → một đoạn, một phần rời của tổng thể (bài văn, phim, cuộc đời). Cụm: 电影片段.","hsk_level":6,"tags":["danh-tu","giai-tri"],"image":"🎞️","examples":[{"type":"basic","zh":"这个片段很感人。","pinyin":"Zhè gè piànduàn hěn gǎnrén.","vi":"Đoạn phim này rất cảm động."},{"type":"simple","zh":"老师给我们播放了电影中的一个片段。","pinyin":"Lǎoshī gěi wǒmen bōfàngle diànyǐng zhōng de yí gè piànduàn.","vi":"Thầy giáo chiếu cho chúng tôi xem một trích đoạn trong phim."},{"type":"compound","zh":"虽然那晚喝醉了，但是他还记得一些零碎的片段。","pinyin":"Suīrán nà wǎn hēzuì le, dànshì tā hái jìde yìxiē língsuì de piànduàn.","vi":"Tuy tối hôm đó say rượu nhưng anh ấy vẫn nhớ được vài đoạn rời rạc."}],"related":[{"hanzi":"片断","pinyin":"piànduàn","vi":"đoạn"},{"hanzi":"段落","pinyin":"duànluò","vi":"đoạn văn"},{"hanzi":"片刻","pinyin":"piànkè","vi":"chốc lát"},{"hanzi":"完整","pinyin":"wánzhěng","vi":"hoàn chỉnh"}]},{"id":"偏见","hanzi":"偏见","pinyin":"piānjiàn","meaning_vi":"thành kiến, định kiến","explanation":"偏 (thiên – lệch) + 见 (kiến – cách nhìn) → cách nhìn thiên lệch; thành kiến. Cụm: 对…有偏见.","hsk_level":6,"tags":["danh-tu","cam-xuc"],"image":"😒","examples":[{"type":"basic","zh":"他对我有偏见。","pinyin":"Tā duì wǒ yǒu piānjiàn.","vi":"Anh ta có định kiến với tôi."},{"type":"simple","zh":"我们应该消除对农村人的偏见。","pinyin":"Wǒmen yīnggāi xiāochú duì nóngcūn rén de piānjiàn.","vi":"Chúng ta nên xóa bỏ định kiến đối với người nông thôn."},{"type":"compound","zh":"如果带着偏见看人，就很难发现别人的优点。","pinyin":"Rúguǒ dàizhe piānjiàn kàn rén, jiù hěn nán fāxiàn biérén de yōudiǎn.","vi":"Nếu nhìn người bằng định kiến thì rất khó phát hiện ưu điểm của họ."}],"related":[{"hanzi":"成见","pinyin":"chéngjiàn","vi":"thành kiến"},{"hanzi":"歧视","pinyin":"qíshì","vi":"kỳ thị"},{"hanzi":"客观","pinyin":"kèguān","vi":"khách quan"},{"hanzi":"固执己见","pinyin":"gùzhíjǐjiàn","vi":"cố chấp ý mình"}],"traditional":"偏見"},{"id":"偏激","hanzi":"偏激","pinyin":"piānjī","meaning_vi":"cực đoan, quá khích (tư tưởng)","explanation":"偏 (lệch) + 激 (mãnh liệt).","hsk_level":6,"tags":["tinh-tu"],"image":"⚠️","examples":[{"type":"basic","zh":"他的想法很偏激。","pinyin":"Tā de xiǎngfǎ hěn piānjī.","vi":"Suy nghĩ của anh ta rất cực đoan."},{"type":"simple","zh":"网上有些评论的言辞过于偏激。","pinyin":"Wǎngshàng yǒuxiē pínglùn de yáncí guòyú piānjī.","vi":"Lời lẽ của một số bình luận trên mạng quá khích."},{"type":"compound","zh":"与其说些偏激的话，不如冷静下来好好沟通。","pinyin":"Yǔqíshuō xiē piānjī dehuà, bùrú lěngjìng xiàlái hǎohǎo gōutōng.","vi":"Thay vì nói những lời cực đoan, chẳng thà bình tĩnh lại để trao đổi tử tế."}],"related":[{"hanzi":"极端","pinyin":"jíduān","vi":"cực đoan"},{"hanzi":"偏见","pinyin":"piānjiàn","vi":"định kiến"},{"hanzi":"片面","pinyin":"piànmiàn","vi":"phiến diện"},{"hanzi":"理智","pinyin":"lǐzhì","vi":"lý trí"}]},{"id":"飘扬","hanzi":"飘扬","pinyin":"piāoyáng","meaning_vi":"tung bay phấp phới","explanation":"飘 (phiêu – bay phất phơ) + 扬 (dương – tung lên) → bay phấp phới trong gió, thường nói về cờ. Cụm: 红旗飘扬.","hsk_level":6,"tags":["dong-tu"],"image":"🚩","examples":[{"type":"basic","zh":"红旗迎风飘扬。","pinyin":"Hóngqí yíngfēng piāoyáng.","vi":"Lá cờ đỏ tung bay trong gió."},{"type":"simple","zh":"操场上空飘扬着五颜六色的彩旗。","pinyin":"Cāochǎng shàngkōng piāoyángzhe wǔyánliùsè de cǎiqí.","vi":"Trên không sân trường tung bay những lá cờ đủ màu sắc."},{"type":"compound","zh":"风一吹，她长长的头发就在空中飘扬起来。","pinyin":"Fēng yì chuī, tā cháng cháng de tóufa jiù zài kōngzhōng piāoyáng qǐlái.","vi":"Gió vừa thổi, mái tóc dài của cô ấy liền tung bay trong không trung."}],"related":[{"hanzi":"飘荡","pinyin":"piāodàng","vi":"lơ lửng phấp phới"},{"hanzi":"飘动","pinyin":"piāodòng","vi":"bay phấp phới"},{"hanzi":"迎风飘扬","pinyin":"yíngfēngpiāoyáng","vi":"tung bay trước gió"},{"hanzi":"旗帜","pinyin":"qízhì","vi":"lá cờ"}],"traditional":"飄揚"},{"id":"飘逸","hanzi":"飘逸","pinyin":"piāoyì","meaning_vi":"thanh thoát, bay bổng","explanation":"飘 (bay) + 逸 (nhàn nhã).","hsk_level":6,"tags":["tinh-tu"],"image":"🍃","examples":[{"type":"basic","zh":"她的长裙很飘逸。","pinyin":"Tā de chángqún hěn piāoyì.","vi":"Chiếc váy dài của cô ấy rất thướt tha."},{"type":"simple","zh":"这位书法家的字体潇洒飘逸。","pinyin":"Zhè wèi shūfǎjiā de zìtǐ xiāosǎ piāoyì.","vi":"Nét chữ của nhà thư pháp này phóng khoáng bay bổng."},{"type":"compound","zh":"这位年轻舞者的动作既飘逸，又充满力量。","pinyin":"Zhè wèi niánqīng wǔzhě de dòngzuò jì piāoyì, yòu chōngmǎn lìliàng.","vi":"Động tác của vũ công trẻ này vừa thanh thoát vừa tràn đầy sức mạnh."}],"related":[{"hanzi":"潇洒","pinyin":"xiāosǎ","vi":"phóng khoáng"},{"hanzi":"洒脱","pinyin":"sǎtuō","vi":"tự nhiên thoải mái"},{"hanzi":"轻盈","pinyin":"qīngyíng","vi":"nhẹ nhàng uyển chuyển"},{"hanzi":"呆板","pinyin":"dāibǎn","vi":"cứng nhắc"}],"traditional":"飄逸"},{"id":"派别","hanzi":"派别","pinyin":"pàibié","meaning_vi":"phe phái, trường phái","explanation":"派 (phái – nhánh) + 别 (biệt – tách riêng) → các nhóm tách biệt theo quan điểm; phe phái, trường phái (học thuật, tôn giáo, chính trị).","hsk_level":6,"tags":["danh-tu"],"image":"📑","examples":[{"type":"basic","zh":"武术有很多派别。","pinyin":"Wǔshù yǒu hěn duō pàibié.","vi":"Võ thuật có nhiều môn phái."},{"type":"simple","zh":"这两个学术派别争论了几十年。","pinyin":"Zhè liǎng gè xuéshù pàibié zhēnglùnle jǐ shí nián.","vi":"Hai trường phái học thuật này tranh luận suốt mấy chục năm."},{"type":"compound","zh":"虽然他们属于不同的派别，但是彼此非常尊重。","pinyin":"Suīrán tāmen shǔyú bùtóng de pàibié, dànshì bǐcǐ fēicháng zūnzhòng.","vi":"Tuy họ thuộc các phe phái khác nhau nhưng rất tôn trọng lẫn nhau."}],"related":[{"hanzi":"派系","pinyin":"pàixì","vi":"phe phái"},{"hanzi":"流派","pinyin":"liúpài","vi":"trường phái"},{"hanzi":"宗派","pinyin":"zōngpài","vi":"bè phái"},{"hanzi":"党派","pinyin":"dǎngpài","vi":"đảng phái"}],"traditional":"派別"},{"id":"畔","hanzi":"畔","pinyin":"pàn","meaning_vi":"bờ sông/hồ","explanation":"Bộ điền 田 + 半.","hsk_level":6,"tags":["danh-tu","thien-nhien","dia-diem"],"image":"🏞️","examples":[{"type":"basic","zh":"我们住在湖畔。","pinyin":"Wǒmen zhùzài húpàn.","vi":"Chúng tôi sống bên bờ hồ."},{"type":"simple","zh":"傍晚很多老人在河畔散步聊天。","pinyin":"Bàngwǎn hěn duō lǎorén zài hépàn sànbù liáotiān.","vi":"Chiều tối, nhiều người già đi dạo trò chuyện bên bờ sông."},{"type":"compound","zh":"每当站在长江畔，我就会想起小时候的家乡。","pinyin":"Měidāng zhàn zài Chángjiāng pàn, wǒ jiù huì xiǎngqǐ xiǎoshíhou de jiāxiāng.","vi":"Mỗi khi đứng bên bờ sông Trường Giang, tôi lại nhớ đến quê hương thời thơ ấu."}],"related":[{"hanzi":"湖畔","pinyin":"húpàn","vi":"bờ hồ"},{"hanzi":"河畔","pinyin":"hépàn","vi":"bờ sông"},{"hanzi":"岸边","pinyin":"ànbiān","vi":"bờ"},{"hanzi":"耳畔","pinyin":"ěrpàn","vi":"bên tai"}]},{"id":"判处","hanzi":"判处","pinyin":"pànchǔ","meaning_vi":"kết án, tuyên phạt","explanation":"判 (xét xử) + 处 (xử phạt).","hsk_level":6,"tags":["dong-tu","phap-luat"],"image":"⚖️","examples":[{"type":"basic","zh":"他被判处三年有期徒刑。","pinyin":"Tā bèi pànchǔ sān nián yǒuqītúxíng.","vi":"Anh ta bị kết án ba năm tù có thời hạn."},{"type":"simple","zh":"法院依法判处那名酒驾司机拘役两个月。","pinyin":"Fǎyuàn yīfǎ pànchǔ nà míng jiǔjià sījī jūyì liǎng gèyuè.","vi":"Tòa án theo pháp luật tuyên phạt tài xế lái xe say rượu đó hai tháng giam giữ."},{"type":"compound","zh":"虽然他主动自首了，但法院还是判处他五年徒刑。","pinyin":"Suīrán tā zhǔdòng zìshǒu le, dàn fǎyuàn háishì pànchǔ tā wǔ nián túxíng.","vi":"Tuy anh ta đã chủ động ra đầu thú, nhưng tòa án vẫn kết án anh ta năm năm tù."}],"related":[{"hanzi":"判决","pinyin":"pànjué","vi":"phán quyết"},{"hanzi":"判刑","pinyin":"pànxíng","vi":"kết án"},{"hanzi":"法院","pinyin":"fǎyuàn","vi":"tòa án"},{"hanzi":"宣判","pinyin":"xuānpàn","vi":"tuyên án"}],"traditional":"判處"},{"id":"炮制","hanzi":"炮制","pinyin":"páozhì","meaning_vi":"bào chế (thuốc), bịa đặt (tin giả)","explanation":"炮 (đọc páo) + 制 (chế tạo).","hsk_level":6,"tags":["dong-tu","suc-khoe"],"image":"💊","examples":[{"type":"basic","zh":"这些谣言是他炮制的。","pinyin":"Zhèxiē yáoyán shì tā páozhì de.","vi":"Những tin đồn này là do hắn bịa ra."},{"type":"simple","zh":"老中医按古方炮制了一批药材。","pinyin":"Lǎo zhōngyī àn gǔfāng páozhìle yìpī yàocái.","vi":"Vị lương y già bào chế một lô dược liệu theo phương thuốc cổ."},{"type":"compound","zh":"因为有人故意炮制假新闻，所以网上一下子乱成一团。","pinyin":"Yīnwèi yǒurén gùyì páozhì jiǎ xīnwén, suǒyǐ wǎngshàng yíxiàzi luàn chéng yì tuán.","vi":"Vì có người cố tình bịa đặt tin giả nên trên mạng bỗng chốc trở nên hỗn loạn."}],"related":[{"hanzi":"捏造","pinyin":"niēzào","vi":"bịa đặt"},{"hanzi":"如法炮制","pinyin":"rúfǎpáozhì","vi":"làm y như cũ"},{"hanzi":"编造","pinyin":"biānzào","vi":"bịa ra"},{"hanzi":"制作","pinyin":"zhìzuò","vi":"chế tác"}],"traditional":"炮製"},{"id":"排除","hanzi":"排除","pinyin":"páichú","meaning_vi":"loại trừ, khắc phục","explanation":"排 (bài – đẩy ra) + 除 (trừ – bỏ đi) → gạt bỏ, loại trừ. Cụm: 排除困难, 排除可能性.","hsk_level":6,"tags":["dong-tu"],"image":"✅","examples":[{"type":"basic","zh":"这种可能不能排除。","pinyin":"Zhè zhǒng kěnéng bu néng páichú.","vi":"Không thể loại trừ khả năng này."},{"type":"simple","zh":"维修工花了一下午才排除了电路故障。","pinyin":"Wéixiūgōng huāle yí xiàwǔ cái pái chúle diànlù gùzhàng.","vi":"Thợ sửa chữa mất cả buổi chiều mới khắc phục được sự cố mạch điện."},{"type":"compound","zh":"只要排除了干扰因素，实验结果就会更准确。","pinyin":"Zhǐyào páichúle gānrǎo yīnsù, shíyàn jiéguǒ jiù huì gèng zhǔnquè.","vi":"Chỉ cần loại trừ các yếu tố gây nhiễu, kết quả thí nghiệm sẽ chính xác hơn."}],"related":[{"hanzi":"消除","pinyin":"xiāochú","vi":"loại bỏ"},{"hanzi":"排除万难","pinyin":"páichúwànnán","vi":"vượt qua mọi khó khăn"},{"hanzi":"除去","pinyin":"chúqù","vi":"trừ đi"},{"hanzi":"包括","pinyin":"bāokuò","vi":"bao gồm"}]},{"id":"排挤","hanzi":"排挤","pinyin":"páijǐ","meaning_vi":"chèn ép, bài xích","explanation":"排 (đẩy) + 挤 (chen lấn).","hsk_level":6,"tags":["dong-tu","cong-viec"],"image":"😒","examples":[{"type":"basic","zh":"他在公司受到排挤。","pinyin":"Tā zài gōngsī shòudào páijǐ.","vi":"Anh ấy bị chèn ép ở công ty."},{"type":"simple","zh":"几个老员工联合起来排挤新来的主管。","pinyin":"Jǐ gè lǎo yuángōng liánhé qǐlái páijǐ xīn lái de zhǔguǎn.","vi":"Mấy nhân viên cũ liên kết lại chèn ép người quản lý mới đến."},{"type":"compound","zh":"大公司不但压低价格，而且把小商家排挤出了市场。","pinyin":"Dàgōngsī búdàn yādī jiàgé, érqiě bǎ xiǎo shāngjiā páijǐ chūle shìchǎng.","vi":"Công ty lớn không những ép giá xuống thấp mà còn đẩy các nhà buôn nhỏ ra khỏi thị trường."}],"related":[{"hanzi":"排斥","pinyin":"páichì","vi":"bài xích"},{"hanzi":"打压","pinyin":"dǎyā","vi":"chèn ép"},{"hanzi":"孤立","pinyin":"gūlì","vi":"cô lập"},{"hanzi":"拉拢","pinyin":"lālǒng","vi":"lôi kéo"}],"traditional":"排擠"},{"id":"牌子","hanzi":"牌子","pinyin":"páizi","meaning_vi":"nhãn hiệu, biển hiệu","explanation":"牌 (bài – tấm biển) + 子 (hậu tố) → tấm biển, bảng hiệu; nhãn hiệu, thương hiệu. Thường: 老牌子, 这是什么牌子?","hsk_level":6,"tags":["danh-tu","mua-sam"],"image":"🏷️","examples":[{"type":"basic","zh":"你的鞋是什么牌子？","pinyin":"Nǐ de xié shì shénme páizi?","vi":"Giày của bạn là hiệu gì?"},{"type":"simple","zh":"店门口挂着一块写着暂停营业的牌子。","pinyin":"Diàn ménkǒu guàzhe yíkuài xiězhe zàntíng yíngyè de páizi.","vi":"Trước cửa tiệm treo một tấm biển ghi \"tạm ngừng kinh doanh\"."},{"type":"compound","zh":"这个牌子的手机虽然贵一点，但是质量很可靠。","pinyin":"Zhè ge páizi de shǒujī suīrán guì yìdiǎn, dànshì zhìliàng hěn kěkào.","vi":"Điện thoại của hãng này tuy hơi đắt, nhưng chất lượng rất đáng tin cậy."}],"related":[{"hanzi":"品牌","pinyin":"pǐnpái","vi":"thương hiệu"},{"hanzi":"名牌","pinyin":"míngpái","vi":"hàng hiệu"},{"hanzi":"招牌","pinyin":"zhāopai","vi":"biển hiệu"},{"hanzi":"商标","pinyin":"shāngbiāo","vi":"nhãn hiệu"}]},{"id":"盘算","hanzi":"盘算","pinyin":"pánsuan","meaning_vi":"tính toán, cân nhắc trong lòng","explanation":"盘 (bàn – xoay vòng) + 算 (toán – tính) → tính đi tính lại trong lòng, toan tính. Cụm: 心里盘算着.","hsk_level":6,"tags":["dong-tu","nhan-thuc"],"image":"🤔","examples":[{"type":"basic","zh":"他心里在盘算什么？","pinyin":"Tā xīnlǐ zài pánsuan shénme?","vi":"Trong lòng anh ta đang tính toán điều gì?"},{"type":"simple","zh":"妈妈一路上都在盘算着这个月的开销。","pinyin":"Māma yílù Shangdōu zài pánsuanzhe zhè geyuè de kāixiāo.","vi":"Suốt dọc đường mẹ cứ tính toán các khoản chi tiêu tháng này."},{"type":"compound","zh":"因为他早就盘算好了退路，所以辞职时一点也不慌。","pinyin":"Yīnwèi tā zǎojiù pánsuan hǎole tuìlù, suǒyǐ cízhí shí yìdiǎn yě bù huāng.","vi":"Vì anh ấy đã tính sẵn đường lui từ lâu nên khi nghỉ việc chẳng hề hoảng."}],"related":[{"hanzi":"打算","pinyin":"dǎsuàn","vi":"dự định"},{"hanzi":"算计","pinyin":"suànji","vi":"tính toán"},{"hanzi":"筹划","pinyin":"chóuhuà","vi":"trù tính"},{"hanzi":"考虑","pinyin":"kǎolǜ","vi":"cân nhắc"}],"traditional":"盤算"},{"id":"磅礴","hanzi":"磅礴","pinyin":"pángbó","meaning_vi":"hùng vĩ, bao la, khí thế mạnh mẽ","explanation":"Cả hai chữ đều có bộ thạch 石.","hsk_level":6,"tags":["tinh-tu"],"image":"🏔️","examples":[{"type":"basic","zh":"黄河气势磅礴。","pinyin":"Huánghé qìshìpángbó.","vi":"Sông Hoàng Hà khí thế hùng vĩ."},{"type":"simple","zh":"站在山顶能看到云海磅礴的壮观景象。","pinyin":"Zhàn zài shāndǐng néng kàndào yúnhǎi pángbó de zhuàngguān jǐngxiàng.","vi":"Đứng trên đỉnh núi có thể thấy cảnh biển mây cuồn cuộn hùng vĩ."},{"type":"compound","zh":"虽然这幅画尺寸不大，但是画面气势磅礴。","pinyin":"Suīrán zhè fú huà chǐcùn búdà, dànshì huàmiàn qìshìpángbó.","vi":"Tuy bức tranh này kích thước không lớn, nhưng bố cục khí thế hùng tráng."}],"related":[{"hanzi":"气势磅礴","pinyin":"qìshìpángbó","vi":"khí thế hùng vĩ"},{"hanzi":"宏伟","pinyin":"hóngwěi","vi":"hùng vĩ"},{"hanzi":"浩瀚","pinyin":"hàohàn","vi":"mênh mông"},{"hanzi":"壮观","pinyin":"zhuàngguān","vi":"tráng lệ"}]},{"id":"旁观","hanzi":"旁观","pinyin":"pángguān","meaning_vi":"đứng ngoài quan sát, bàng quan","explanation":"旁 (bên cạnh) + 观 (xem).","hsk_level":6,"tags":["dong-tu"],"image":"👀","examples":[{"type":"basic","zh":"我们不能袖手旁观。","pinyin":"Wǒmen bù néng xiùshǒupángguān.","vi":"Chúng ta không thể khoanh tay đứng nhìn."},{"type":"simple","zh":"很多路人停下来旁观这场街头表演。","pinyin":"Hěn duō lùrén tíngxiàlái pángguān zhè chǎng jiētóu biǎoyǎn.","vi":"Nhiều người qua đường dừng lại đứng xem buổi biểu diễn đường phố này."},{"type":"compound","zh":"如果你只是旁观，就永远学不会游泳。","pinyin":"Rúguǒ nǐ zhǐshì pángguān, jiù yǒngyuǎn xué bú huì yóuyǒng.","vi":"Nếu bạn chỉ đứng ngoài nhìn thì sẽ mãi không học được bơi."}],"related":[{"hanzi":"旁观者","pinyin":"pángguānzhě","vi":"người đứng ngoài"},{"hanzi":"袖手旁观","pinyin":"xiùshǒupángguān","vi":"khoanh tay đứng nhìn"},{"hanzi":"观望","pinyin":"guānwàng","vi":"đứng xem"},{"hanzi":"参与","pinyin":"cānyù","vi":"tham gia"}],"traditional":"旁觀"},{"id":"配备","hanzi":"配备","pinyin":"pèibèi","meaning_vi":"trang bị, bố trí đầy đủ","explanation":"配 (phối – phân phối) + 备 (bị – chuẩn bị) → phân bổ đủ người hoặc thiết bị cần thiết; trang bị. Cụm: 配备人员, 配备设施.","hsk_level":6,"tags":["dong-tu","cong-viec"],"image":"🛠️","examples":[{"type":"basic","zh":"每间教室都配备了空调。","pinyin":"Měi jiān jiàoshì dōu pèibèile kōngtiáo.","vi":"Mỗi phòng học đều được trang bị máy lạnh."},{"type":"simple","zh":"这辆救护车配备了最先进的急救设备。","pinyin":"Zhè liàng jiùhùchē pèibèile zuì xiānjìn de jíjiù shèbèi.","vi":"Chiếc xe cứu thương này được trang bị thiết bị cấp cứu tiên tiến nhất."},{"type":"compound","zh":"公司不但给新项目配备了专人，而且增加了预算。","pinyin":"Gōngsī búdàn gěi xīn xiàngmù pèibèile zhuānrén, érqiě zēngjiāle yùsuàn.","vi":"Công ty không những bố trí người chuyên trách cho dự án mới mà còn tăng ngân sách."}],"related":[{"hanzi":"装备","pinyin":"zhuāngbèi","vi":"trang bị"},{"hanzi":"配置","pinyin":"pèizhì","vi":"cấu hình"},{"hanzi":"设备","pinyin":"shèbèi","vi":"thiết bị"},{"hanzi":"配套","pinyin":"pèitào","vi":"đồng bộ"}],"traditional":"配備"},{"id":"配制","hanzi":"配制","pinyin":"pèizhì","meaning_vi":"pha chế, phối chế","explanation":"配 + 制 (chế tạo).","hsk_level":6,"tags":["dong-tu","khoa-hoc"],"image":"🧪","examples":[{"type":"basic","zh":"医生在配制药水。","pinyin":"Yīshēng zài pèizhì yàoshuǐ.","vi":"Bác sĩ đang pha chế thuốc nước."},{"type":"simple","zh":"调酒师用三种果汁配制了一杯鸡尾酒。","pinyin":"Tiáojiǔshī yòng sān zhǒng guǒzhī pèizhìle yì bēi jīwěijiǔ.","vi":"Người pha chế dùng ba loại nước ép pha một ly cocktail."},{"type":"compound","zh":"只要按比例配制营养液，蔬菜就能长得很好。","pinyin":"Zhǐyào àn bǐlì pèizhì yíngyǎngyè, shūcài jiù néng zhǎngde hěn hǎo.","vi":"Chỉ cần pha dung dịch dinh dưỡng theo đúng tỉ lệ, rau sẽ phát triển rất tốt."}],"related":[{"hanzi":"调配","pinyin":"tiáopèi","vi":"pha chế"},{"hanzi":"配方","pinyin":"pèifāng","vi":"công thức pha chế"},{"hanzi":"调制","pinyin":"tiáozhì","vi":"điều chế"},{"hanzi":"配药","pinyin":"pèiyào","vi":"pha thuốc"}],"traditional":"配製"},{"id":"赔礼","hanzi":"赔礼","pinyin":"péilǐ","meaning_vi":"xin lỗi, tạ lỗi","explanation":"赔 (đền bù) + 礼 (lễ phép). Động từ ly hợp.","hsk_level":6,"tags":["dong-tu","giao-tiep"],"image":"🙇","examples":[{"type":"basic","zh":"他登门赔礼道歉。","pinyin":"Tā dēngmén péilǐ dàoqiàn.","vi":"Anh ấy đến tận nhà xin lỗi."},{"type":"simple","zh":"店长亲自向投诉的顾客赔礼道歉。","pinyin":"Diànzhǎng qīnzì xiàng tóusù de gùkè péilǐ dàoqiàn.","vi":"Cửa hàng trưởng đích thân xin lỗi vị khách đã khiếu nại."},{"type":"compound","zh":"既然是你撞坏了人家的车，就应该去赔礼道歉。","pinyin":"Jìrán shì nǐ zhuàng huàile rénjia de chē, jiù yīnggāi qù péilǐ dàoqiàn.","vi":"Đã là bạn tông hỏng xe của người ta thì nên đi xin lỗi."}],"related":[{"hanzi":"赔礼道歉","pinyin":"péilǐdàoqiàn","vi":"tạ lỗi xin lỗi"},{"hanzi":"道歉","pinyin":"dàoqiàn","vi":"xin lỗi"},{"hanzi":"赔罪","pinyin":"péizuì","vi":"tạ tội"},{"hanzi":"认错","pinyin":"rèncuò","vi":"nhận lỗi"}],"traditional":"賠禮"},{"id":"培植","hanzi":"培植","pinyin":"péizhí","meaning_vi":"bồi dưỡng, trồng trọt","explanation":"培 + 植 (trồng cây).","hsk_level":6,"tags":["dong-tu"],"image":"🌱","examples":[{"type":"basic","zh":"他在院子里培植兰花。","pinyin":"Tā zài yuànzi lǐ péizhí lánhuā.","vi":"Anh ấy trồng hoa lan trong sân."},{"type":"simple","zh":"研究所成功培植出一种耐旱的新稻种。","pinyin":"Yánjiūsuǒ chénggōng péizhí chū yì zhǒng nàihàn de xīn dào zhǒng.","vi":"Viện nghiên cứu đã trồng thành công một giống lúa mới chịu hạn."},{"type":"compound","zh":"他不但培植自己的亲信，而且排斥有能力的人。","pinyin":"Tā búdàn péizhí zìjǐ de qīnxìn, érqiě páichì yǒunénglì de rén.","vi":"Hắn không chỉ nâng đỡ tay chân thân tín của mình mà còn gạt bỏ những người có năng lực."}],"related":[{"hanzi":"培养","pinyin":"péiyǎng","vi":"bồi dưỡng"},{"hanzi":"栽培","pinyin":"zāipéi","vi":"trồng trọt, vun trồng"},{"hanzi":"种植","pinyin":"zhòngzhí","vi":"trồng"},{"hanzi":"扶植","pinyin":"fúzhí","vi":"nâng đỡ"}]},{"id":"膨胀","hanzi":"膨胀","pinyin":"péngzhàng","meaning_vi":"phình to, giãn nở, lạm phát","explanation":"Cả hai chữ đều có bộ nguyệt ⺼.","hsk_level":6,"tags":["dong-tu","khoa-hoc"],"image":"🎈","examples":[{"type":"basic","zh":"气球受热膨胀了。","pinyin":"Qìqiú shòurè péngzhàng le.","vi":"Quả bóng bay bị nóng nên phình to ra."},{"type":"simple","zh":"去年这个国家的通货膨胀非常严重。","pinyin":"Qùnián zhè ge guójiā de tōnghuòpéngzhàng fēicháng yánzhòng.","vi":"Năm ngoái lạm phát ở nước này rất nghiêm trọng."},{"type":"compound","zh":"因为金属遇热会膨胀，所以铁轨之间要留缝隙。","pinyin":"Yīnwèi jīnshǔ yù rè huì péngzhàng, suǒyǐ tiěguǐ zhījiān yào liú fèngxì.","vi":"Vì kim loại gặp nóng sẽ giãn nở nên giữa các thanh ray phải chừa khe hở."}],"related":[{"hanzi":"通货膨胀","pinyin":"tōnghuòpéngzhàng","vi":"lạm phát"},{"hanzi":"扩张","pinyin":"kuòzhāng","vi":"bành trướng"},{"hanzi":"收缩","pinyin":"shōusuō","vi":"co lại"},{"hanzi":"热胀冷缩","pinyin":"rèzhànglěngsuō","vi":"nóng nở lạnh co"}],"traditional":"膨脹"},{"id":"媲美","hanzi":"媲美","pinyin":"pìměi","meaning_vi":"sánh ngang, đẹp ngang ngửa","explanation":"媲 (sánh đôi) + 美 (đẹp).","hsk_level":6,"tags":["dong-tu"],"image":"🌟","examples":[{"type":"basic","zh":"他的厨艺可与大厨媲美。","pinyin":"Tā de chúyì kě yǔ dàchú pìměi.","vi":"Tay nghề nấu ăn của anh ấy có thể sánh ngang đầu bếp lớn."},{"type":"simple","zh":"这款国产相机的画质足以媲美进口品牌。","pinyin":"Zhè kuǎn guóchǎn xiàngjī de huàzhì zúyǐ pìměi jìnkǒu pǐnpái.","vi":"Chất lượng hình ảnh của chiếc máy ảnh nội địa này đủ sức sánh ngang các thương hiệu nhập khẩu."},{"type":"compound","zh":"虽然这里只是个小镇，但是风景可以和桂林媲美。","pinyin":"Suīrán zhèlǐ zhǐshì gè xiǎozhèn, dànshì fēngjǐng kěyǐ hé Guìlín pìměi.","vi":"Tuy nơi đây chỉ là một thị trấn nhỏ, nhưng phong cảnh có thể sánh ngang Quế Lâm."}],"related":[{"hanzi":"比美","pinyin":"bǐměi","vi":"sánh đẹp"},{"hanzi":"不相上下","pinyin":"bùxiāngshàngxià","vi":"ngang ngửa"},{"hanzi":"相提并论","pinyin":"xiāngtíbìnglùn","vi":"đánh đồng với nhau"},{"hanzi":"逊色","pinyin":"xùnsè","vi":"kém hơn"}]},{"id":"皮革","hanzi":"皮革","pinyin":"pígé","meaning_vi":"da thuộc (làm giày/túi)","explanation":"皮 (da) + 革 (da đã xử lý).","hsk_level":6,"tags":["danh-tu","trang-phuc"],"image":"👜","examples":[{"type":"basic","zh":"这个包是皮革做的。","pinyin":"Zhè ge bāo shì pígé zuò de.","vi":"Chiếc túi này làm bằng da thuộc."},{"type":"simple","zh":"他在一家皮革加工厂当了十年工人。","pinyin":"Tā zài yìjiā pígé jiāgōngchǎng dāngle shí nián gōngrén.","vi":"Anh ấy làm công nhân mười năm ở một xưởng gia công da thuộc."},{"type":"compound","zh":"真皮革的沙发既耐用又舒服，就是价格太高。","pinyin":"Zhēn pígé de shāfā jì nàiyòng yòu shūfu, jiùshì jiàgé tài gāo.","vi":"Ghế sofa da thật vừa bền vừa êm, chỉ có điều giá quá cao."}],"related":[{"hanzi":"真皮","pinyin":"zhēnpí","vi":"da thật"},{"hanzi":"皮鞋","pinyin":"píxié","vi":"giày da"},{"hanzi":"人造革","pinyin":"rénzàogé","vi":"da nhân tạo"},{"hanzi":"皮包","pinyin":"píbāo","vi":"túi da"}]},{"id":"疲倦","hanzi":"疲倦","pinyin":"píjuàn","meaning_vi":"mệt mỏi, buồn ngủ","explanation":"疲 (bì – mệt) + 倦 (quyện – mỏi, chán) → mệt mỏi, uể oải, muốn nghỉ ngơi. Cụm: 感到疲倦.","hsk_level":6,"tags":["tinh-tu"],"image":"😴","examples":[{"type":"basic","zh":"他脸上满是疲倦。","pinyin":"Tā liǎn shang mǎnshì píjuàn.","vi":"Gương mặt anh ấy đầy vẻ mệt mỏi."},{"type":"simple","zh":"她拖着疲倦的身体回到了宿舍。","pinyin":"Tā tuōzhe píjuàn de shēntǐ huídàole sùshè.","vi":"Cô ấy lê tấm thân mệt mỏi trở về ký túc xá."},{"type":"compound","zh":"即使再疲倦，他也坚持每天读半小时书。","pinyin":"Jíshǐ zài píjuàn, tā yě jiānchí měitiān dú bànxiǎoshí shū.","vi":"Dù mệt mỏi đến đâu, anh ấy vẫn kiên trì mỗi ngày đọc sách nửa tiếng."}],"related":[{"hanzi":"疲劳","pinyin":"píláo","vi":"mệt mỏi"},{"hanzi":"困倦","pinyin":"kùnjuàn","vi":"buồn ngủ mệt mỏi"},{"hanzi":"疲惫","pinyin":"píbèi","vi":"mệt nhoài"},{"hanzi":"精神","pinyin":"jīngshen","vi":"tỉnh táo, có tinh thần"}]},{"id":"贫瘠","hanzi":"贫瘠","pinyin":"pínjí","meaning_vi":"cằn cỗi (đất đai)","explanation":"贫 (nghèo) + 瘠 (gầy còm).","hsk_level":6,"tags":["tinh-tu","thien-nhien"],"image":"🏜️","examples":[{"type":"basic","zh":"这里的土地很贫瘠。","pinyin":"Zhèlǐ de tǔdì hěn pínjí.","vi":"Đất đai ở đây rất cằn cỗi."},{"type":"simple","zh":"农民们在贫瘠的山坡上种满了果树。","pinyin":"Nóngmínmen zài pínjí de shānpō shang zhòng mǎnle guǒshù.","vi":"Nông dân trồng kín cây ăn quả trên sườn đồi cằn cỗi."},{"type":"compound","zh":"虽然这片土地十分贫瘠，但是土豆长得很好。","pinyin":"Suīrán zhè piàn tǔdì shífēn pínjí, dànshì tǔdòu zhǎngde hěn hǎo.","vi":"Tuy mảnh đất này rất cằn cỗi, nhưng khoai tây lại mọc rất tốt."}],"related":[{"hanzi":"肥沃","pinyin":"féiwò","vi":"màu mỡ"},{"hanzi":"荒凉","pinyin":"huāngliáng","vi":"hoang vắng"},{"hanzi":"土地","pinyin":"tǔdì","vi":"đất đai"},{"hanzi":"不毛之地","pinyin":"bùmáozhīdì","vi":"vùng đất cằn cỗi"}],"traditional":"貧瘠"},{"id":"贫困","hanzi":"贫困","pinyin":"pínkùn","meaning_vi":"nghèo khổ, nghèo đói","explanation":"贫 (bần – nghèo) + 困 (khốn – khó khăn) → nghèo khó, thiếu thốn. Cụm: 贫困地区, 贫困家庭.","hsk_level":6,"tags":["tinh-tu"],"image":"💸","examples":[{"type":"basic","zh":"他出生在贫困山区。","pinyin":"Tā chūshēng zài pínkùn shānqū.","vi":"Anh ấy sinh ra ở vùng núi nghèo khó."},{"type":"simple","zh":"政府每年都给贫困家庭发放生活补助。","pinyin":"Zhèngfǔ měinián dōu gěi pínkùn jiātíng fāfàng shēnghuó bǔzhù.","vi":"Chính phủ hằng năm đều cấp trợ cấp sinh hoạt cho các gia đình nghèo."},{"type":"compound","zh":"尽管家里很贫困，父母还是坚持送她上大学。","pinyin":"Jǐnguǎn jiālǐ hěn pínkùn, fùmǔ háishì jiānchí sòng tā shàng dàxué.","vi":"Mặc dù nhà rất nghèo, bố mẹ vẫn kiên quyết cho cô ấy học đại học."}],"related":[{"hanzi":"贫穷","pinyin":"pínqióng","vi":"nghèo nàn"},{"hanzi":"富裕","pinyin":"fùyù","vi":"giàu có"},{"hanzi":"扶贫","pinyin":"fúpín","vi":"xóa đói giảm nghèo"},{"hanzi":"贫困地区","pinyin":"pínkùndìqū","vi":"vùng nghèo"}],"traditional":"貧困"},{"id":"评比","hanzi":"评比","pinyin":"píngbǐ","meaning_vi":"bình chọn, thi đua đánh giá","explanation":"评 (đánh giá) + 比 (so sánh).","hsk_level":6,"tags":["dong-tu","cong-viec"],"image":"🏆","examples":[{"type":"basic","zh":"年底要评比优秀员工。","pinyin":"Niándǐ yào píngbǐ yōuxiù yuángōng.","vi":"Cuối năm sẽ bình chọn nhân viên xuất sắc."},{"type":"simple","zh":"我们班在全校卫生评比中得了第一名。","pinyin":"Wǒmen bān zài quán xiào wèishēng píngbǐ zhōng déle dìyīmíng.","vi":"Lớp chúng tôi đứng nhất trong đợt thi đua vệ sinh toàn trường."},{"type":"compound","zh":"因为评比结果和奖金挂钩，所以大家都很重视。","pinyin":"Yīnwèi píngbǐ jiéguǒ hé jiǎngjīn guàgōu, suǒyǐ dàjiā dōu hěn zhòngshì.","vi":"Vì kết quả bình xét gắn với tiền thưởng nên mọi người đều rất coi trọng."}],"related":[{"hanzi":"评选","pinyin":"píngxuǎn","vi":"bình chọn"},{"hanzi":"比赛","pinyin":"bǐsài","vi":"thi đấu"},{"hanzi":"评定","pinyin":"píngdìng","vi":"đánh giá xếp loại"},{"hanzi":"评委","pinyin":"píngwěi","vi":"giám khảo"}],"traditional":"評比"},{"id":"平淡","hanzi":"平淡","pinyin":"píngdàn","meaning_vi":"bình đạm, nhạt nhẽo, giản dị","explanation":"平 (bình – phẳng) + 淡 (đạm – nhạt) → bình thường, nhạt nhẽo, không có gì nổi bật. Cụm: 平淡的生活.","hsk_level":6,"tags":["tinh-tu"],"image":"💧","examples":[{"type":"basic","zh":"日子过得很平淡。","pinyin":"Rìzi guòde hěn píngdàn.","vi":"Cuộc sống trôi qua rất bình lặng."},{"type":"simple","zh":"这部电影的情节平淡得让人想睡觉。","pinyin":"Zhè bù diànyǐng de qíngjié píngdàn de ràng rén xiǎng shuìjiào.","vi":"Tình tiết bộ phim này nhạt nhẽo đến mức khiến người ta buồn ngủ."},{"type":"compound","zh":"虽然他们的婚姻生活很平淡，但是两人一直相互扶持。","pinyin":"Suīrán tāmen de hūnyīn shēnghuó hěn píngdàn, dànshì liǎng rén yìzhí xiānghù fúchí.","vi":"Tuy cuộc sống hôn nhân của họ rất giản dị, nhưng hai người luôn nương tựa nhau."}],"related":[{"hanzi":"平凡","pinyin":"píngfán","vi":"bình thường"},{"hanzi":"平淡无奇","pinyin":"píngdànwúqí","vi":"tầm thường không có gì lạ"},{"hanzi":"精彩","pinyin":"jīngcǎi","vi":"đặc sắc"},{"hanzi":"平静","pinyin":"píngjìng","vi":"bình lặng"}]},{"id":"评估","hanzi":"评估","pinyin":"pínggū","meaning_vi":"đánh giá, ước tính","explanation":"评 (bình – bình xét) + 估 (cổ – ước tính) → xem xét và ước định giá trị, mức độ. Cụm: 风险评估.","hsk_level":6,"tags":["dong-tu","cong-viec"],"image":"📊","examples":[{"type":"basic","zh":"专家正在评估损失。","pinyin":"Zhuānjiā zhèngzài pínggū sǔnshī.","vi":"Chuyên gia đang đánh giá thiệt hại."},{"type":"simple","zh":"银行会先评估这套房子的市场价值。","pinyin":"Yín hánghuì xiān pínggū zhè tào fángzi de shìchǎng jiàzhí.","vi":"Ngân hàng sẽ định giá giá trị thị trường của căn nhà này trước."},{"type":"compound","zh":"只有经过全面评估，我们才能决定是否投资。","pinyin":"Zhǐyǒu jīngguò quánmiàn pínggū, wǒmen cáinéng juédìng shìfǒu tóuzī.","vi":"Chỉ khi đã đánh giá toàn diện, chúng ta mới có thể quyết định có đầu tư hay không."}],"related":[{"hanzi":"评价","pinyin":"píngjià","vi":"đánh giá"},{"hanzi":"估计","pinyin":"gūjì","vi":"ước tính"},{"hanzi":"鉴定","pinyin":"jiàndìng","vi":"giám định"},{"hanzi":"风险评估","pinyin":"fēngxiǎnpínggū","vi":"đánh giá rủi ro"}],"traditional":"評估"},{"id":"评选","hanzi":"评选","pinyin":"píngxuǎn","meaning_vi":"bình chọn, tuyển chọn","explanation":"评 (bình – bình xét) + 选 (tuyển – chọn) → bình xét rồi chọn ra người hoặc vật xuất sắc. Cụm: 评选优秀员工.","hsk_level":6,"tags":["dong-tu","giai-tri"],"image":"🗳️","examples":[{"type":"basic","zh":"他被评选为劳动模范。","pinyin":"Tā bèi píngxuǎn wéi láodòng mófàn.","vi":"Anh ấy được bình chọn là chiến sĩ thi đua."},{"type":"simple","zh":"观众可以在网上评选最受欢迎的歌手。","pinyin":"Guānzhòng kěyǐ zài wǎngshàng píngxuǎn zuì shòuhuānyíng de gēshǒu.","vi":"Khán giả có thể bình chọn ca sĩ được yêu thích nhất trên mạng."},{"type":"compound","zh":"如果这次评选不公开透明，就很难让大家信服。","pinyin":"Rúguǒ zhè cì píngxuǎn bù gōngkāi tòumíng, jiù hěn nán ràng dàjiā xìnfú.","vi":"Nếu lần bình chọn này không công khai minh bạch thì rất khó khiến mọi người tin phục."}],"related":[{"hanzi":"评比","pinyin":"píngbǐ","vi":"bình chọn"},{"hanzi":"选拔","pinyin":"xuǎnbá","vi":"tuyển chọn"},{"hanzi":"投票","pinyin":"tóupiào","vi":"bỏ phiếu"},{"hanzi":"评委","pinyin":"píngwěi","vi":"giám khảo"}],"traditional":"評選"},{"id":"平行","hanzi":"平行","pinyin":"píngxíng","meaning_vi":"song song","explanation":"平 (bình – ngang) + 行 (hành – đi) → song song (đường thẳng, mặt phẳng); cũng nghĩa ngang cấp, tiến hành đồng thời. Cụm: 平行线.","hsk_level":6,"tags":["tinh-tu","khoa-hoc"],"image":"🟰","examples":[{"type":"basic","zh":"两条线互相平行。","pinyin":"Liǎng tiáo xiàn hùxiāng píngxíng.","vi":"Hai đường thẳng song song với nhau."},{"type":"simple","zh":"这条小路和河岸平行延伸了好几公里。","pinyin":"Zhè tiáo xiǎolù hé hé'àn píngxíng yánshēnle hǎojǐ gōnglǐ.","vi":"Con đường nhỏ này chạy song song với bờ sông kéo dài mấy cây số."},{"type":"compound","zh":"既然两条直线是平行的，那么它们就永远不会相交。","pinyin":"Jìrán liǎng tiáo zhíxiàn shì píngxíng de, nàme tāmen jiù yǒngyuǎn bú huì xiāngjiāo.","vi":"Đã là hai đường thẳng song song thì chúng sẽ không bao giờ cắt nhau."}],"related":[{"hanzi":"平行线","pinyin":"píngxíngxiàn","vi":"đường song song"},{"hanzi":"垂直","pinyin":"chuízhí","vi":"vuông góc"},{"hanzi":"并行","pinyin":"bìngxíng","vi":"song hành"},{"hanzi":"交叉","pinyin":"jiāochā","vi":"giao nhau"}]},{"id":"平息","hanzi":"平息","pinyin":"píngxī","meaning_vi":"lắng xuống, dập tắt (cơn giận/bạo loạn)","explanation":"平 (yên) + 息 (ngừng).","hsk_level":6,"tags":["dong-tu"],"image":"🕊️","examples":[{"type":"basic","zh":"风波终于平息了。","pinyin":"Fēngbō zhōngyú píngxī le.","vi":"Sóng gió cuối cùng cũng lắng xuống."},{"type":"simple","zh":"经理的一番解释平息了顾客的怒气。","pinyin":"Jīnglǐ de yìfān jiěshì píngxīle gùkè de nùqì.","vi":"Lời giải thích của giám đốc đã làm dịu cơn giận của khách hàng."},{"type":"compound","zh":"警察一赶到现场，街上的骚乱就很快平息了。","pinyin":"Jǐngchá yì gǎndào xiànchǎng, jiēshang de sāoluàn jiù hěn kuài píngxī le.","vi":"Cảnh sát vừa đến hiện trường, cuộc bạo loạn trên phố liền nhanh chóng được dập tắt."}],"related":[{"hanzi":"平定","pinyin":"píngdìng","vi":"dẹp yên"},{"hanzi":"平静","pinyin":"píngjìng","vi":"bình lặng"},{"hanzi":"风波","pinyin":"fēngbō","vi":"sóng gió"},{"hanzi":"激化","pinyin":"jīhuà","vi":"trở nên gay gắt"}]},{"id":"平易近人","hanzi":"平易近人","pinyin":"píngyì-jìnrén","meaning_vi":"hiền hòa dễ gần (lãnh đạo/người nổi tiếng)","explanation":"平易 (hiền hòa, dễ chịu) + 近人 (gần gũi người) → thái độ hòa nhã, dễ gần; hay khen lãnh đạo, người có địa vị.","hsk_level":6,"tags":["thanh-ngu","con-nguoi"],"image":"🤗","examples":[{"type":"basic","zh":"王教授平易近人。","pinyin":"Wáng jiàoshòu píngyìjìnrén.","vi":"Giáo sư Vương rất hiền hòa dễ gần."},{"type":"simple","zh":"这位平易近人的老市长常去菜市场跟居民聊天。","pinyin":"Zhè wèi píngyìjìnrén de lǎo shìzhǎng cháng qù càishìchǎng gēn jūmín liáotiān.","vi":"Vị thị trưởng già dễ gần này thường ra chợ trò chuyện với cư dân."},{"type":"compound","zh":"虽然他是著名作家，但是对读者十分平易近人。","pinyin":"Suīrán tā shì zhùmíng zuòjiā, dànshì duì dúzhě shífēn píngyìjìnrén.","vi":"Tuy là nhà văn nổi tiếng, nhưng ông ấy rất hòa nhã gần gũi với độc giả."}],"related":[{"hanzi":"和蔼可亲","pinyin":"hé'ǎikěqīn","vi":"hòa nhã dễ gần"},{"hanzi":"亲切","pinyin":"qīnqiè","vi":"thân thiết"},{"hanzi":"盛气凌人","pinyin":"shèngqìlíngrén","vi":"hống hách"},{"hanzi":"高高在上","pinyin":"gāogāozàishàng","vi":"cao cao tại thượng"}]},{"id":"屏障","hanzi":"屏障","pinyin":"píngzhàng","meaning_vi":"bình phong, rào chắn","explanation":"屏 (bình – tấm chắn) + 障 (chướng – ngăn trở) → vật che chắn bảo vệ, như núi sông làm hàng rào tự nhiên. Cụm: 天然屏障.","hsk_level":6,"tags":["danh-tu"],"image":"🛡️","examples":[{"type":"basic","zh":"群山是天然屏障。","pinyin":"Qúnshān shì tiānrán píngzhàng.","vi":"Dãy núi là rào chắn tự nhiên."},{"type":"simple","zh":"这片防护林成了村子抵挡风沙的屏障。","pinyin":"Zhè piàn fánghù lín chéngle cūnzi dǐdǎng fēngshā de píngzhàng.","vi":"Rừng phòng hộ này trở thành bức bình phong chắn gió cát cho ngôi làng."},{"type":"compound","zh":"因为皮肤是人体的第一道屏障，所以一定要保护好。","pinyin":"Yīnwèi pífū shì réntǐ de dì yīdào píngzhàng, suǒyǐ yídìngyào bǎohù hǎo.","vi":"Vì da là hàng rào bảo vệ đầu tiên của cơ thể nên nhất định phải bảo vệ cẩn thận."}],"related":[{"hanzi":"障碍","pinyin":"zhàng'ài","vi":"chướng ngại"},{"hanzi":"天然屏障","pinyin":"tiānránpíngzhàng","vi":"lá chắn tự nhiên"},{"hanzi":"屏风","pinyin":"píngfēng","vi":"bình phong"},{"hanzi":"防线","pinyin":"fángxiàn","vi":"phòng tuyến"}]},{"id":"迫不及待","hanzi":"迫不及待","pinyin":"pòbù-jídài","meaning_vi":"nóng lòng không thể chờ đợi","explanation":"迫 (bách – gấp gáp) + 不及待 (không kịp đợi) → nóng lòng, sốt ruột không chờ nổi. Thường: 迫不及待地打开.","hsk_level":6,"tags":["thanh-ngu"],"image":"🏃","examples":[{"type":"basic","zh":"孩子迫不及待地拆开礼物。","pinyin":"Háizi pòbùjídài de chāikāi lǐwù.","vi":"Đứa trẻ nóng lòng mở quà ngay."},{"type":"simple","zh":"他迫不及待地想把好消息告诉父母。","pinyin":"Tā pòbùjídài de xiǎng bǎ hǎo xiāoxi gàosu fùmǔ.","vi":"Anh ấy nóng lòng muốn báo tin vui cho bố mẹ."},{"type":"compound","zh":"飞机一落地，她就迫不及待地打开了手机。","pinyin":"Fēijī yí luòdì, tā jiù pòbùjídài de dǎkāile shǒujī.","vi":"Máy bay vừa hạ cánh, cô ấy liền nóng lòng bật điện thoại lên."}],"related":[{"hanzi":"急不可待","pinyin":"jíbùkědài","vi":"nóng lòng không đợi được"},{"hanzi":"刻不容缓","pinyin":"kèbùrónghuǎn","vi":"cấp bách"},{"hanzi":"焦急","pinyin":"jiāojí","vi":"sốt ruột"},{"hanzi":"慢条斯理","pinyin":"màntiáosīlǐ","vi":"thong thả từ tốn"}]},{"id":"破釜沉舟","hanzi":"破釜沉舟","pinyin":"pòfǔ-chénzhōu","meaning_vi":"đập nồi dìm thuyền (quyết tâm cao độ không đường lùi)","explanation":"Điển tích Hạng Vũ. Thành ngữ.","hsk_level":6,"tags":["thanh-ngu"],"image":"⛵","examples":[{"type":"basic","zh":"他决定破釜沉舟。","pinyin":"Tā juédìng pòfǔchénzhōu.","vi":"Anh ấy quyết định đập nồi dìm thuyền, không chừa đường lui."},{"type":"simple","zh":"他卖掉房子破釜沉舟地投入了创业。","pinyin":"Tā màidiào fángzi pòfǔchénzhōu de tóurùle chuàngyè.","vi":"Anh ấy bán nhà, dốc hết tất cả để khởi nghiệp mà không chừa đường lui."},{"type":"compound","zh":"既然已经没有退路了，我们不如破釜沉舟拼一把。","pinyin":"Jìrán yǐjīng méiyǒu tuìlù le, wǒmen bùrú pòfǔchénzhōu pīn yì bǎ.","vi":"Đã không còn đường lui, chi bằng chúng ta đập nồi dìm thuyền liều một phen."}],"related":[{"hanzi":"背水一战","pinyin":"bèishuǐyízhàn","vi":"đánh trận quyết tử"},{"hanzi":"孤注一掷","pinyin":"gūzhùyízhì","vi":"được ăn cả ngã về không"},{"hanzi":"义无反顾","pinyin":"yìwúfǎngù","vi":"không chút do dự"},{"hanzi":"犹豫不决","pinyin":"yóuyùbùjué","vi":"do dự không quyết"}]},{"id":"魄力","hanzi":"魄力","pinyin":"pòlì","meaning_vi":"khí phách, bản lĩnh quyết đoán","explanation":"魄 (phách – khí phách) + 力 (lực – sức) → sức quyết đoán, dám nghĩ dám làm. Cụm: 有魄力.","hsk_level":6,"tags":["danh-tu","con-nguoi"],"image":"🦁","examples":[{"type":"basic","zh":"新校长很有魄力。","pinyin":"Xīn xiàozhǎng hěn yǒu pòlì.","vi":"Hiệu trưởng mới rất có bản lĩnh."},{"type":"simple","zh":"她以过人的魄力推动了公司的改革。","pinyin":"Tā yǐ guòrén de pòlì tuīdòngle gōngsī de gǎigé.","vi":"Cô ấy với bản lĩnh hơn người đã thúc đẩy cải cách công ty."},{"type":"compound","zh":"他虽然经验丰富，可是做决定时缺乏魄力。","pinyin":"Tā suīrán jīngyàn fēngfù, kěshì zuò juédìng shí quēfá pòlì.","vi":"Anh ấy tuy giàu kinh nghiệm, nhưng lại thiếu quyết đoán khi đưa ra quyết định."}],"related":[{"hanzi":"气魄","pinyin":"qìpò","vi":"khí phách"},{"hanzi":"胆识","pinyin":"dǎnshí","vi":"gan dạ và hiểu biết"},{"hanzi":"果断","pinyin":"guǒduàn","vi":"quả quyết"},{"hanzi":"优柔寡断","pinyin":"yōuróuguǎduàn","vi":"thiếu quyết đoán"}]},{"id":"破绽","hanzi":"破绽","pinyin":"pòzhàn","meaning_vi":"sơ hở, kẽ hở (trong lời nói dối)","explanation":"破 (rách) + 绽 (bung chỉ).","hsk_level":6,"tags":["danh-tu"],"image":"🔍","examples":[{"type":"basic","zh":"他的话有破绽。","pinyin":"Tā dehuà yǒu pòzhàn.","vi":"Lời anh ta có sơ hở."},{"type":"simple","zh":"侦探很快就从证词里发现了破绽。","pinyin":"Zhēntàn hěn kuài jiù cóng zhèngcí lǐ fāxiànle pòzhàn.","vi":"Thám tử nhanh chóng phát hiện sơ hở trong lời khai."},{"type":"compound","zh":"他的谎言编得再好，也难免会露出破绽。","pinyin":"Tā de huǎngyán biān de zài hǎo, yě nánmiǎn huì lòuchū pòzhàn.","vi":"Lời nói dối của hắn dù bịa khéo đến đâu cũng khó tránh để lộ sơ hở."}],"related":[{"hanzi":"漏洞","pinyin":"lòudòng","vi":"lỗ hổng"},{"hanzi":"破绽百出","pinyin":"pòzhànbǎichū","vi":"đầy sơ hở"},{"hanzi":"天衣无缝","pinyin":"tiānyīwúfèng","vi":"hoàn hảo không sơ hở"},{"hanzi":"马脚","pinyin":"mǎjiǎo","vi":"sơ hở, cái đuôi"}],"traditional":"破綻"},{"id":"拍案叫绝","hanzi":"拍案叫绝","pinyin":"pāi'àn-jiàojué","meaning_vi":"vỗ bàn khen hay (tán thưởng hết lời)","explanation":"拍案 (đập bàn) + 叫绝 (kêu tuyệt) → hết lời tán thưởng, thán phục điều gì rất hay.","hsk_level":6,"tags":["thanh-ngu"],"image":"👏","examples":[{"type":"basic","zh":"观众拍案叫绝。","pinyin":"Guānzhòng pāi'ànjiàojué.","vi":"Khán giả vỗ bàn khen hay."},{"type":"simple","zh":"这个巧妙的结局让读者拍案叫绝。","pinyin":"Zhè ge qiǎomiào de jiéjú ràng dúzhě pāi'ànjiàojué.","vi":"Cái kết khéo léo này khiến độc giả vỗ bàn tán thưởng."},{"type":"compound","zh":"他一说出那个绝妙的点子，大家就拍案叫绝。","pinyin":"Tā yì shuōchū nà ge juémiào de diǎnzi, dàjiā jiù pāi'ànjiàojué.","vi":"Anh ấy vừa nói ra ý tưởng tuyệt diệu đó, mọi người liền vỗ bàn khen hay."}],"related":[{"hanzi":"赞不绝口","pinyin":"zànbùjuékǒu","vi":"khen không ngớt lời"},{"hanzi":"叹为观止","pinyin":"tànwéiguānzhǐ","vi":"thán phục tột cùng"},{"hanzi":"拍手称快","pinyin":"pāishǒuchēngkuài","vi":"vỗ tay hả hê"},{"hanzi":"喝彩","pinyin":"hècǎi","vi":"tán thưởng"}],"traditional":"拍案叫絕"},{"id":"攀比","hanzi":"攀比","pinyin":"pānbǐ","meaning_vi":"so bì, đua đòi","explanation":"攀 (leo/bám) + 比 (so sánh).","hsk_level":6,"tags":["dong-tu","xa-hoi"],"image":"😒","examples":[{"type":"basic","zh":"孩子之间不要攀比。","pinyin":"Háizi zhījiān bú yào pānbǐ.","vi":"Giữa trẻ con với nhau đừng so bì."},{"type":"simple","zh":"有些家长喜欢拿孩子的成绩互相攀比。","pinyin":"Yǒuxiē jiāzhǎng xǐhuan ná háizi de chéngjì hùxiāng pānbǐ.","vi":"Một số phụ huynh thích đem thành tích của con ra so bì với nhau."},{"type":"compound","zh":"与其和别人攀比，不如踏踏实实过好自己的日子。","pinyin":"Yǔqí hé biérén pānbǐ, bùrú tā tāshí shíguò hǎo zìjǐ de rìzi.","vi":"Thay vì so bì với người khác, chẳng bằng sống thật vững vàng cuộc đời của mình."}],"related":[{"hanzi":"比较","pinyin":"bǐjiào","vi":"so sánh"},{"hanzi":"虚荣","pinyin":"xūróng","vi":"hư vinh"},{"hanzi":"炫耀","pinyin":"xuànyào","vi":"khoe khoang"},{"hanzi":"盲目攀比","pinyin":"mángmùpānbǐ","vi":"đua đòi mù quáng"}]},{"id":"抛弃","hanzi":"抛弃","pinyin":"pāoqì","meaning_vi":"vứt bỏ, ruồng bỏ","explanation":"抛 (phao – ném) + 弃 (khí – bỏ) → ném bỏ, ruồng bỏ người hoặc vật. Cụm: 抛弃家庭, 被抛弃.","hsk_level":6,"tags":["dong-tu"],"image":"💔","examples":[{"type":"basic","zh":"他被女朋友抛弃了。","pinyin":"Tā bèi nǚpéngyou pāoqì le.","vi":"Anh ấy bị bạn gái bỏ rơi."},{"type":"simple","zh":"这只小狗是被主人抛弃在路边的。","pinyin":"Zhè zhī xiǎogǒu shì bèi zhǔrén pāoqì zài lùbiān de.","vi":"Chú chó nhỏ này bị chủ bỏ rơi bên đường."},{"type":"compound","zh":"只要我们不抛弃希望，就一定能找到出路。","pinyin":"Zhǐyào wǒmen bù pāoqì xīwàng, jiù yídìng néng zhǎodào chūlù.","vi":"Chỉ cần chúng ta không từ bỏ hy vọng thì nhất định sẽ tìm được lối ra."}],"related":[{"hanzi":"丢弃","pinyin":"diūqì","vi":"vứt bỏ"},{"hanzi":"放弃","pinyin":"fàngqì","vi":"từ bỏ"},{"hanzi":"遗弃","pinyin":"yíqì","vi":"bỏ rơi"},{"hanzi":"珍惜","pinyin":"zhēnxī","vi":"trân trọng"}],"traditional":"拋棄"},{"id":"抛砖引玉","hanzi":"抛砖引玉","pinyin":"pāozhuān-yǐnyù","meaning_vi":"ném gạch dẫn ngọc (đưa ra ý kiến sơ bộ để mời người khác góp ý hay hơn)","explanation":"Ném viên gạch ra để dẫn ngọc về → nêu ý kiến thô thiển của mình để gợi ra ý kiến hay của người khác; lời khiêm tốn khi phát biểu trước.","hsk_level":6,"tags":["thanh-ngu","giao-tiep"],"image":"🧱","examples":[{"type":"basic","zh":"我先抛砖引玉吧。","pinyin":"Wǒ xiān pāozhuānyǐnyù ba.","vi":"Tôi xin mạo muội nói trước để mọi người góp ý nhé."},{"type":"simple","zh":"我这篇粗浅的文章只是想抛砖引玉。","pinyin":"Wǒ zhè piān cūqiǎn de wénzhāng zhǐshì xiǎng pāozhuānyǐnyù.","vi":"Bài viết sơ sài này của tôi chỉ mong gợi mở để nhận được ý kiến hay hơn."},{"type":"compound","zh":"我先抛砖引玉谈几点想法，然后请各位补充。","pinyin":"Wǒ xiān pāozhuānyǐnyù tán jǐ diǎn xiǎngfǎ, ránhòu qǐng gèwèi bǔchōng.","vi":"Tôi xin mạo muội nêu vài suy nghĩ trước, sau đó mời các vị bổ sung."}],"related":[{"hanzi":"集思广益","pinyin":"jísīguǎngyì","vi":"tập hợp trí tuệ"},{"hanzi":"谦虚","pinyin":"qiānxū","vi":"khiêm tốn"},{"hanzi":"献丑","pinyin":"xiànchǒu","vi":"xin bêu xấu"},{"hanzi":"启发","pinyin":"qǐfā","vi":"gợi mở"}],"traditional":"拋磚引玉"},{"id":"喷泉","hanzi":"喷泉","pinyin":"pēnquán","meaning_vi":"đài phun nước","explanation":"喷 (phun) + 泉 (suối).","hsk_level":6,"tags":["danh-tu","dia-diem"],"image":"⛲","examples":[{"type":"basic","zh":"广场上有个喷泉。","pinyin":"Guǎngchǎng shang yǒu gè pēnquán.","vi":"Trên quảng trường có một đài phun nước."},{"type":"simple","zh":"孩子们光着脚在音乐喷泉旁边玩水。","pinyin":"Háizimen guāngzhe jiǎo zài yīnyuè pēnquán pángbiān wán shuǐ.","vi":"Bọn trẻ đi chân trần nghịch nước bên đài phun nước nhạc."},{"type":"compound","zh":"每到晚上八点，喷泉就会随着音乐跳起舞来。","pinyin":"Měi dào wǎnshang bā diǎn, pēnquán jiù huì suízhe yīnyuè tiào qǐ wǔ lái.","vi":"Cứ đến tám giờ tối, đài phun nước lại nhảy múa theo điệu nhạc."}],"related":[{"hanzi":"泉水","pinyin":"quánshuǐ","vi":"nước suối"},{"hanzi":"音乐喷泉","pinyin":"yīnyuèpēnquán","vi":"nhạc nước"},{"hanzi":"喷","pinyin":"pēn","vi":"phun"},{"hanzi":"广场","pinyin":"guǎngchǎng","vi":"quảng trường"}],"traditional":"噴泉"},{"id":"抨击","hanzi":"抨击","pinyin":"pēngjī","meaning_vi":"công kích, phê phán gay gắt","explanation":"抨 (phanh – công kích) + 击 (kích – đánh) → dùng lời lẽ, bài viết công kích gay gắt. Cụm: 抨击时弊.","hsk_level":6,"tags":["dong-tu","giao-tiep"],"image":"🗣️","examples":[{"type":"basic","zh":"媒体纷纷抨击此事。","pinyin":"Méitǐ fēnfēn pēngjī cǐshì.","vi":"Truyền thông đồng loạt chỉ trích gay gắt việc này."},{"type":"simple","zh":"这篇社论猛烈抨击了食品行业的乱象。","pinyin":"Zhè piān shèlùn měngliè pēngjīle shípǐn hángyè de luànxiàng.","vi":"Bài xã luận này công kích dữ dội tình trạng hỗn loạn của ngành thực phẩm."},{"type":"compound","zh":"虽然新政策受到不少抨击，但是政府仍然坚持推行。","pinyin":"Suīrán xīn zhèngcè shòudào bùshǎo pēngjī, dànshì zhèngfǔ réngrán jiānchí tuīxíng.","vi":"Tuy chính sách mới hứng chịu không ít chỉ trích, nhưng chính phủ vẫn kiên quyết thực hiện."}],"related":[{"hanzi":"批评","pinyin":"pīpíng","vi":"phê bình"},{"hanzi":"指责","pinyin":"zhǐzé","vi":"chỉ trích"},{"hanzi":"攻击","pinyin":"gōngjī","vi":"công kích"},{"hanzi":"赞扬","pinyin":"zànyáng","vi":"khen ngợi"}],"traditional":"抨擊"},{"id":"烹饪","hanzi":"烹饪","pinyin":"pēngrèn","meaning_vi":"nấu nướng, ẩm thực","explanation":"烹 (phanh – nấu) + 饪 (nhẫm – nấu chín) → việc nấu nướng, nghệ thuật nấu ăn. Cụm: 烹饪技术.","hsk_level":6,"tags":["dong-tu","an-uong"],"image":"👨‍🍳","examples":[{"type":"basic","zh":"她很擅长烹饪。","pinyin":"Tā hěn shàncháng pēngrèn.","vi":"Cô ấy rất giỏi nấu nướng."},{"type":"simple","zh":"他周末去参加了一个意大利菜烹饪班。","pinyin":"Tā zhōumò qù cānjiāle yí gè Yìdàlì cài pēngrèn bān.","vi":"Cuối tuần anh ấy đi học một lớp nấu món Ý."},{"type":"compound","zh":"如果烹饪时间太长，蔬菜的营养就会流失。","pinyin":"Rúguǒ pēngrèn shíjiān tài cháng, shūcài de yíngyǎng jiù huì liúshī.","vi":"Nếu nấu quá lâu, chất dinh dưỡng trong rau sẽ bị mất đi."}],"related":[{"hanzi":"烹调","pinyin":"pēngtiáo","vi":"nấu nướng"},{"hanzi":"厨艺","pinyin":"chúyì","vi":"tài nấu ăn"},{"hanzi":"厨师","pinyin":"chúshī","vi":"đầu bếp"},{"hanzi":"菜谱","pinyin":"càipǔ","vi":"thực đơn, sách nấu ăn"}],"traditional":"烹飪"},{"id":"捧场","hanzi":"捧场","pinyin":"pěngchǎng","meaning_vi":"cổ vũ, ủng hộ (buổi diễn/cửa hàng)","explanation":"捧 + 场 (sân khấu). Động từ ly hợp.","hsk_level":6,"tags":["dong-tu","giai-tri"],"image":"👏","examples":[{"type":"basic","zh":"谢谢大家来捧场！","pinyin":"Xièxie dàjiā lái pěngchǎng!","vi":"Cảm ơn mọi người đã đến ủng hộ!"},{"type":"simple","zh":"朋友们都来为他的新餐馆捧场。","pinyin":"Péngyoumen dōu lái wèi tā de xīn cānguǎn pěngchǎng.","vi":"Bạn bè đều đến ủng hộ nhà hàng mới của anh ấy."},{"type":"compound","zh":"虽然她唱得一般，但是同学们还是热情地捧场。","pinyin":"Suīrán tā chàng de yìbān, dànshì tóngxuémen háishì rèqíng de pěngchǎng.","vi":"Tuy cô ấy hát bình thường, nhưng các bạn cùng lớp vẫn nhiệt tình cổ vũ."}],"related":[{"hanzi":"支持","pinyin":"zhīchí","vi":"ủng hộ"},{"hanzi":"喝彩","pinyin":"hècǎi","vi":"reo hò cổ vũ"},{"hanzi":"拆台","pinyin":"chāitái","vi":"phá đám"},{"hanzi":"观众","pinyin":"guānzhòng","vi":"khán giả"}],"traditional":"捧場"},{"id":"批发","hanzi":"批发","pinyin":"pīfā","meaning_vi":"bán buôn, bán sỉ","explanation":"批 (phê – lô, số lượng lớn) + 发 (phát – xuất ra) → bán theo lô số lượng lớn; trái nghĩa 零售 (bán lẻ).","hsk_level":6,"tags":["dong-tu","cong-viec"],"image":"📦","examples":[{"type":"basic","zh":"这些衣服是批发的。","pinyin":"Zhèxiē yīfu shì pīfā de.","vi":"Những bộ quần áo này là hàng lấy sỉ."},{"type":"simple","zh":"他每天凌晨去市场批发新鲜蔬菜。","pinyin":"Tā měitiān língchén qù shìchǎng pīfā xīnxiān shūcài.","vi":"Mỗi ngày từ rạng sáng anh ấy ra chợ lấy sỉ rau tươi."},{"type":"compound","zh":"如果你一次买五十件，我们就按批发价卖给你。","pinyin":"Rúguǒ nǐ yí cì mǎi wǔshí jiàn, wǒmen jiù àn pīfājià mài gěi nǐ.","vi":"Nếu bạn mua một lần năm mươi cái, chúng tôi sẽ bán cho bạn theo giá sỉ."}],"related":[{"hanzi":"零售","pinyin":"língshòu","vi":"bán lẻ"},{"hanzi":"批发市场","pinyin":"pīfāshìchǎng","vi":"chợ đầu mối"},{"hanzi":"批发价","pinyin":"pīfājià","vi":"giá sỉ"},{"hanzi":"进货","pinyin":"jìnhuò","vi":"nhập hàng"}],"traditional":"批發"},{"id":"批改","hanzi":"批改","pinyin":"pīgǎi","meaning_vi":"chấm và sửa (bài tập)","explanation":"批 (phê) + 改 (sửa).","hsk_level":6,"tags":["dong-tu","hoc-tap"],"image":"✍️","examples":[{"type":"basic","zh":"老师在批改作业。","pinyin":"Lǎoshī zài pīgǎi zuòyè.","vi":"Cô giáo đang chấm bài tập."},{"type":"simple","zh":"王老师熬夜批改了全班的期末试卷。","pinyin":"Wáng lǎoshī áoyè pīgǎile quánbān de qīmò shìjuàn.","vi":"Thầy Vương thức khuya chấm hết bài thi cuối kỳ của cả lớp."},{"type":"compound","zh":"作文一批改完，老师就把它发还给了学生。","pinyin":"Zuòwén yì pīgǎi wán, lǎoshī jiù bǎ tā fā huán gěile xuésheng.","vi":"Bài văn vừa chấm xong, giáo viên liền trả lại cho học sinh."}],"related":[{"hanzi":"修改","pinyin":"xiūgǎi","vi":"sửa chữa"},{"hanzi":"改作业","pinyin":"gǎizuòyè","vi":"chấm bài tập"},{"hanzi":"作文","pinyin":"zuòwén","vi":"bài văn"},{"hanzi":"打分","pinyin":"dǎfēn","vi":"cho điểm"}]},{"id":"披露","hanzi":"披露","pinyin":"pīlù","meaning_vi":"công bố, tiết lộ (thông tin)","explanation":"披 (mở ra) + 露 (lộ).","hsk_level":6,"tags":["dong-tu","cong-viec"],"image":"📢","examples":[{"type":"basic","zh":"公司披露了年报。","pinyin":"Gōngsī pīlùle niánbào.","vi":"Công ty đã công bố báo cáo thường niên."},{"type":"simple","zh":"记者向公众披露了这起事故的真相。","pinyin":"Jìzhě xiàng gōngzhòng pīlùle zhè qǐ shìgù de zhēnxiàng.","vi":"Phóng viên đã tiết lộ với công chúng sự thật về vụ tai nạn này."},{"type":"compound","zh":"因为消息被提前披露，所以股价当天大幅下跌。","pinyin":"Yīnwèi xiāoxi bèi tíqián pīlù, suǒyǐ gǔjià dàngtiān dàfú xiàdiē.","vi":"Vì tin tức bị tiết lộ sớm nên giá cổ phiếu ngày hôm đó giảm mạnh."}],"related":[{"hanzi":"透露","pinyin":"tòulù","vi":"tiết lộ"},{"hanzi":"公开","pinyin":"gōngkāi","vi":"công khai"},{"hanzi":"揭露","pinyin":"jiēlù","vi":"vạch trần"},{"hanzi":"隐瞒","pinyin":"yǐnmán","vi":"che giấu"}]},{"id":"披星戴月","hanzi":"披星戴月","pinyin":"pīxīng-dàiyuè","meaning_vi":"đi sớm về khuya vất vả (khoác sao đội trăng)","explanation":"Khoác sao, đội trăng → đi sớm về khuya, làm lụng vất vả hoặc đi đường gấp gáp ngày đêm.","hsk_level":6,"tags":["thanh-ngu"],"image":"🌙","examples":[{"type":"basic","zh":"父亲每天披星戴月。","pinyin":"Fùqīn měitiān pīxīngdàiyuè.","vi":"Cha ngày nào cũng đi sớm về khuya."},{"type":"simple","zh":"筑路工人披星戴月地赶修这条公路。","pinyin":"Zhù lù gōngrén pīxīngdàiyuè de gǎn xiū zhè tiáo gōnglù.","vi":"Công nhân làm đường đi sớm về khuya gấp rút sửa con đường này."},{"type":"compound","zh":"为了供孩子上学，她披星戴月地干了好几年。","pinyin":"Wèile gōng háizi shàngxué, tā pīxīngdàiyuè de gànle hǎojǐnián.","vi":"Để nuôi con ăn học, bà ấy đã đi sớm về khuya làm lụng suốt mấy năm."}],"related":[{"hanzi":"早出晚归","pinyin":"zǎochūwǎnguī","vi":"đi sớm về muộn"},{"hanzi":"起早贪黑","pinyin":"qǐzǎotānhēi","vi":"thức khuya dậy sớm"},{"hanzi":"夜以继日","pinyin":"yèyǐjìrì","vi":"ngày đêm liên tục"},{"hanzi":"辛苦","pinyin":"xīnkǔ","vi":"vất vả"}]},{"id":"泼冷水","hanzi":"泼冷水","pinyin":"pōlěngshuǐ","meaning_vi":"dội gáo nước lạnh (làm nhụt chí)","explanation":"泼 + 冷水 (nước lạnh). Thành ngữ khẩu ngữ.","hsk_level":6,"tags":["dong-tu"],"image":"💦","examples":[{"type":"basic","zh":"别总给我泼冷水。","pinyin":"Bié zǒng gěi wǒ pōlěngshuǐ.","vi":"Đừng lúc nào cũng dội nước lạnh vào tôi."},{"type":"simple","zh":"朋友们从不给我的创业梦想泼冷水。","pinyin":"Péngyoumen cóng bù gěi wǒ de chuàngyè mèngxiǎng pōlěngshuǐ.","vi":"Bạn bè chưa bao giờ dội nước lạnh vào giấc mơ khởi nghiệp của tôi."},{"type":"compound","zh":"如果大人总是泼冷水，孩子就会失去尝试的勇气。","pinyin":"Rúguǒ dàrén zǒngshì pōlěngshuǐ, háizi jiù huì shīqù chángshì de yǒngqì.","vi":"Nếu người lớn cứ dội nước lạnh, trẻ con sẽ mất đi dũng khí thử sức."}],"related":[{"hanzi":"打击","pinyin":"dǎjī","vi":"đả kích"},{"hanzi":"扫兴","pinyin":"sǎoxìng","vi":"cụt hứng"},{"hanzi":"鼓励","pinyin":"gǔlì","vi":"khích lệ"},{"hanzi":"打退堂鼓","pinyin":"dǎtuìtánggǔ","vi":"chùn bước"}],"traditional":"潑冷水"},{"id":"扑灭","hanzi":"扑灭","pinyin":"pūmiè","meaning_vi":"dập tắt (lửa/dịch bệnh)","explanation":"扑 (phác – vồ, đập) + 灭 (diệt – tắt) → dập tắt lửa; nghĩa bóng tiêu diệt dịch bệnh, sâu hại. Cụm: 扑灭大火.","hsk_level":6,"tags":["dong-tu"],"image":"🚒","examples":[{"type":"basic","zh":"大火被扑灭了。","pinyin":"Dàhuǒ bèi pūmiè le.","vi":"Đám cháy lớn đã được dập tắt."},{"type":"simple","zh":"消防员用了三个小时才扑灭山火。","pinyin":"Xiāofángyuán yòngle sān gè xiǎoshí cái pūmiè shānhuǒ.","vi":"Lính cứu hỏa mất ba tiếng mới dập tắt được đám cháy rừng."},{"type":"compound","zh":"因为发现得及时，所以疫情很快就被扑灭了。","pinyin":"Yīnwèi fāxiàn de jíshí, suǒyǐ yìqíng hěn kuài jiù bèi pūmiè le.","vi":"Vì phát hiện kịp thời nên dịch bệnh nhanh chóng được dập tắt."}],"related":[{"hanzi":"消灭","pinyin":"xiāomiè","vi":"tiêu diệt"},{"hanzi":"灭火","pinyin":"mièhuǒ","vi":"dập lửa"},{"hanzi":"扑救","pinyin":"pūjiù","vi":"cứu hỏa"},{"hanzi":"火灾","pinyin":"huǒzāi","vi":"hỏa hoạn"}],"traditional":"撲滅"},{"id":"铺张","hanzi":"铺张","pinyin":"pūzhāng","meaning_vi":"phô trương, xa hoa lãng phí","explanation":"铺 + 张 (mở rộng). Cụm: 铺张浪费.","hsk_level":6,"tags":["tinh-tu","dong-tu"],"image":"💸","examples":[{"type":"basic","zh":"婚礼不必太铺张。","pinyin":"Hūnlǐ búbì tài pūzhāng.","vi":"Đám cưới không cần quá phô trương."},{"type":"simple","zh":"公司明令禁止铺张浪费的公款宴请。","pinyin":"Gōngsī mínglìng jìnzhǐ pūzhāng làngfèi de gōngkuǎn yànqǐng.","vi":"Công ty ra lệnh cấm rõ các buổi chiêu đãi phô trương lãng phí bằng tiền công."},{"type":"compound","zh":"与其把钱花在铺张的排场上，不如捐给需要的人。","pinyin":"Yǔqí bǎ qián huā zài pūzhāng de páichǎng shang, bùrú juāngěi xūyào de rén.","vi":"Thay vì tiêu tiền vào sự phô trương xa hoa, chẳng bằng quyên góp cho người cần."}],"related":[{"hanzi":"铺张浪费","pinyin":"pūzhānglàngfèi","vi":"phô trương lãng phí"},{"hanzi":"奢侈","pinyin":"shēchǐ","vi":"xa xỉ"},{"hanzi":"节俭","pinyin":"jiéjiǎn","vi":"tiết kiệm"},{"hanzi":"排场","pinyin":"páichǎng","vi":"phô trương thanh thế"}],"traditional":"鋪張"},{"id":"品尝","hanzi":"品尝","pinyin":"pǐncháng","meaning_vi":"thưởng thức, nếm thử","explanation":"品 (phẩm – thưởng thức) + 尝 (thường – nếm) → nếm kỹ để thưởng thức hương vị. Cụm: 品尝美食.","hsk_level":6,"tags":["dong-tu","an-uong"],"image":"🍽️","examples":[{"type":"basic","zh":"请品尝我们的新茶。","pinyin":"Qǐng pǐncháng wǒmen de xīn chá.","vi":"Mời nếm thử trà mới của chúng tôi."},{"type":"simple","zh":"游客们在夜市品尝了各种地方小吃。","pinyin":"Yóukèmen zài yèshì pǐnchángle gèzhǒng dìfāng xiǎochī.","vi":"Du khách đã thưởng thức đủ loại món ăn vặt địa phương ở chợ đêm."},{"type":"compound","zh":"只有亲自品尝过，你才知道这道菜有多地道。","pinyin":"Zhǐyǒu qīnzì pǐncháng guo, nǐ cái zhīdào zhè dào cài yǒu duō dìdao.","vi":"Chỉ khi tự mình nếm thử, bạn mới biết món này chuẩn vị đến mức nào."}],"related":[{"hanzi":"品味","pinyin":"pǐnwèi","vi":"thưởng thức"},{"hanzi":"尝试","pinyin":"chángshì","vi":"thử"},{"hanzi":"美食","pinyin":"měishí","vi":"món ngon"},{"hanzi":"品茶","pinyin":"pǐnchá","vi":"thưởng trà"}],"traditional":"品嘗"},{"id":"品行","hanzi":"品行","pinyin":"pǐnxíng","meaning_vi":"phẩm hạnh, tư cách đạo đức","explanation":"品 (phẩm chất) + 行 (hành vi).","hsk_level":6,"tags":["danh-tu","con-nguoi"],"image":"🌟","examples":[{"type":"basic","zh":"他品行端正。","pinyin":"Tā pǐnxíng duānzhèng.","vi":"Anh ấy phẩm hạnh đoan chính."},{"type":"simple","zh":"学校评奖学金时也会考查学生的品行。","pinyin":"Xuéxiào píng jiǎngxuéjīn shí yě huì kǎochá xuésheng de pǐnxíng.","vi":"Khi xét học bổng, nhà trường cũng xem xét phẩm hạnh của học sinh."},{"type":"compound","zh":"一个人即使能力再强，品行不好也难以被重用。","pinyin":"Yígèrén jíshǐ nénglì zài qiáng, pǐnxíng bù hǎo yě nányǐ bèi zhòngyòng.","vi":"Một người dù năng lực giỏi đến đâu, nếu phẩm hạnh không tốt cũng khó được trọng dụng."}],"related":[{"hanzi":"品德","pinyin":"pǐndé","vi":"phẩm đức"},{"hanzi":"品质","pinyin":"pǐnzhì","vi":"phẩm chất"},{"hanzi":"操行","pinyin":"cāoxíng","vi":"hạnh kiểm"},{"hanzi":"品行端正","pinyin":"pǐnxíngduānzhèng","vi":"phẩm hạnh đoan chính"}]},{"id":"品种","hanzi":"品种","pinyin":"pǐnzhǒng","meaning_vi":"chủng loại, giống","explanation":"品 (phẩm – loại) + 种 (chủng – giống) → giống cây trồng, vật nuôi; chủng loại sản phẩm. Cụm: 新品种.","hsk_level":6,"tags":["danh-tu","thien-nhien"],"image":"🌾","examples":[{"type":"basic","zh":"这是新品种的苹果。","pinyin":"Zhè shì xīnpǐnzhǒng de píngguǒ.","vi":"Đây là giống táo mới."},{"type":"simple","zh":"这家花店有三十多个品种的玫瑰。","pinyin":"Zhè jiā huādiàn yǒu sānshí duōgè pǐnzhǒng de méigui.","vi":"Cửa hàng hoa này có hơn ba mươi giống hoa hồng."},{"type":"compound","zh":"超市里的商品品种既齐全又便宜，所以顾客很多。","pinyin":"Chāoshì lǐ de shāngpǐn pǐnzhǒng jì qíquán yòu piányi, suǒyǐ gùkè hěn duō.","vi":"Hàng hóa trong siêu thị vừa đủ chủng loại vừa rẻ nên khách rất đông."}],"related":[{"hanzi":"种类","pinyin":"zhǒnglèi","vi":"chủng loại"},{"hanzi":"品类","pinyin":"pǐnlèi","vi":"loại hàng"},{"hanzi":"新品种","pinyin":"xīnpǐnzhǒng","vi":"giống mới"},{"hanzi":"良种","pinyin":"liángzhǒng","vi":"giống tốt"}],"traditional":"品種"},{"id":"普查","hanzi":"普查","pinyin":"pǔchá","meaning_vi":"tổng điều tra (dân số/kinh tế)","explanation":"普 (khắp) + 查 (kiểm tra).","hsk_level":6,"tags":["dong-tu","xa-hoi"],"image":"📊","examples":[{"type":"basic","zh":"全国人口普查开始了。","pinyin":"Quánguó rénkǒupǔchá kāishǐ le.","vi":"Cuộc tổng điều tra dân số toàn quốc đã bắt đầu."},{"type":"simple","zh":"工作人员挨家挨户地进行人口普查登记。","pinyin":"Gōngzuò rényuán āijiā'āihù de jìnxíng rénkǒupǔchá dēngjì.","vi":"Nhân viên đến từng nhà để đăng ký tổng điều tra dân số."},{"type":"compound","zh":"因为每十年才普查一次，所以这些数据非常珍贵。","pinyin":"Yīnwèi měi shí nián cái pǔchá yí cì, suǒyǐ zhèxiē shùjù fēicháng zhēnguì.","vi":"Vì mười năm mới tổng điều tra một lần nên những số liệu này rất quý giá."}],"related":[{"hanzi":"人口普查","pinyin":"rénkǒupǔchá","vi":"điều tra dân số"},{"hanzi":"调查","pinyin":"diàochá","vi":"điều tra"},{"hanzi":"统计","pinyin":"tǒngjì","vi":"thống kê"},{"hanzi":"抽查","pinyin":"chōuchá","vi":"kiểm tra ngẫu nhiên"}]},{"id":"朴实","hanzi":"朴实","pinyin":"pǔshí","meaning_vi":"chất phác, mộc mạc","explanation":"朴 (phác – mộc mạc) + 实 (thực – thật thà) → chất phác thật thà; giản dị không cầu kỳ. Cụm: 朴实的农民.","hsk_level":6,"tags":["tinh-tu","con-nguoi"],"image":"😊","examples":[{"type":"basic","zh":"他为人很朴实。","pinyin":"Tā wéirén hěn pǔshí.","vi":"Anh ấy sống rất chất phác."},{"type":"simple","zh":"这位农民用朴实的语言讲述了家乡的变化。","pinyin":"Zhè wèi nóng mínyòng pǔshí de yǔyán jiǎngshùle jiāxiāng de biànhuà.","vi":"Người nông dân này dùng lời lẽ mộc mạc kể về sự đổi thay của quê hương."},{"type":"compound","zh":"她的穿着虽然朴实，可是看起来非常大方。","pinyin":"Tā de chuānzhuó suīrán pǔshí, kěshì kànqǐlái fēicháng dàfang.","vi":"Cách ăn mặc của cô ấy tuy mộc mạc, nhưng trông rất trang nhã."}],"related":[{"hanzi":"朴素","pinyin":"pǔsù","vi":"giản dị"},{"hanzi":"质朴","pinyin":"zhìpǔ","vi":"chất phác"},{"hanzi":"淳朴","pinyin":"chúnpǔ","vi":"thuần phác"},{"hanzi":"浮华","pinyin":"fúhuá","vi":"phù hoa"}],"traditional":"樸實"},{"id":"普天同庆","hanzi":"普天同庆","pinyin":"pǔtiān-tóngqìng","meaning_vi":"cả nước cùng vui mừng chúc tụng","explanation":"普天 (khắp gầm trời) + 同庆 (cùng mừng) → khắp nơi cùng vui mừng ăn mừng, thường dịp lễ lớn.","hsk_level":6,"tags":["thanh-ngu","van-hoa"],"image":"🎊","examples":[{"type":"basic","zh":"那是普天同庆的日子。","pinyin":"Nàshì pǔtiāntóngqìng de rìzi.","vi":"Đó là ngày cả nước cùng hân hoan."},{"type":"simple","zh":"国庆节这天全国各地普天同庆。","pinyin":"Guóqìngjié zhè tiān quánguó gèdì pǔtiāntóngqìng.","vi":"Vào ngày Quốc khánh, khắp nơi trên cả nước cùng vui mừng chào đón."},{"type":"compound","zh":"战争结束的消息一传来，全国上下就普天同庆。","pinyin":"Zhànzhēng jiéshù de xiāoxi yì chuánlái, quánguó shàngxià jiù pǔtiāntóngqìng.","vi":"Tin chiến tranh kết thúc vừa truyền đến, cả nước liền hân hoan mừng vui."}],"related":[{"hanzi":"举国欢腾","pinyin":"jǔguóhuānténg","vi":"cả nước hân hoan"},{"hanzi":"欢天喜地","pinyin":"huāntiānxǐdì","vi":"vui mừng khôn xiết"},{"hanzi":"庆祝","pinyin":"qìngzhù","vi":"chúc mừng"},{"hanzi":"普天之下","pinyin":"pǔtiānzhīxià","vi":"khắp thiên hạ"}],"traditional":"普天同慶"},{"id":"恰巧","hanzi":"恰巧","pinyin":"qiàqiǎo","meaning_vi":"vừa khéo, tình cờ","explanation":"恰 + 巧 (khéo/trùng hợp).","hsk_level":6,"tags":["pho-tu"],"image":"🍀","examples":[{"type":"basic","zh":"我恰巧也在场。","pinyin":"Wǒ qiàqiǎo yě zài chǎng.","vi":"Tình cờ tôi cũng có mặt ở đó."},{"type":"simple","zh":"我去找他时他恰巧刚出门。","pinyin":"Wǒqù zhǎo tā shí tā qiàqiǎo gāng chūmén.","vi":"Lúc tôi đi tìm, anh ấy vừa khéo mới ra ngoài."},{"type":"compound","zh":"因为恰巧遇到了老同学，所以我在路上耽搁了半个小时。","pinyin":"Yīnwèi qiàqiǎo yùdàole lǎo tóngxué, suǒyǐ wǒ zài lùshang dāngele bàn gè xiǎoshí.","vi":"Vì tình cờ gặp bạn học cũ nên tôi bị chậm trễ nửa tiếng trên đường."}],"related":[{"hanzi":"恰好","pinyin":"qiàhǎo","vi":"vừa hay"},{"hanzi":"碰巧","pinyin":"pèngqiǎo","vi":"tình cờ"},{"hanzi":"正好","pinyin":"zhènghǎo","vi":"vừa đúng"},{"hanzi":"偶然","pinyin":"ǒurán","vi":"ngẫu nhiên"}]},{"id":"恰如其分","hanzi":"恰如其分","pinyin":"qiàrú-qífèn","meaning_vi":"vừa vặn đúng mực","explanation":"恰 (kháp – vừa đúng) 如 (như) 其分 (phần, mức của nó) → vừa đúng mức; nói năng, đánh giá đúng mực, không quá không kém.","hsk_level":6,"tags":["thanh-ngu"],"image":"🎯","examples":[{"type":"basic","zh":"他的评价恰如其分。","pinyin":"Tā de píngjià qiàrúqífèn.","vi":"Lời đánh giá của anh ấy rất đúng mực."},{"type":"simple","zh":"主持人恰如其分地调节了现场的气氛。","pinyin":"Zhǔchírén qiàrúqífèn detiáo jiéle xiànchǎng de qìfēn.","vi":"Người dẫn chương trình điều tiết bầu không khí hiện trường một cách vừa phải."},{"type":"compound","zh":"批评下属要恰如其分，否则会伤了他的自尊心。","pinyin":"Pīpíng xiàshǔ yào qiàrúqífèn, fǒuzé huì shāngle tā de zìzūnxīn.","vi":"Phê bình cấp dưới phải đúng mực, nếu không sẽ làm tổn thương lòng tự trọng của họ."}],"related":[{"hanzi":"恰到好处","pinyin":"qiàdàohǎochù","vi":"vừa đúng chỗ"},{"hanzi":"适度","pinyin":"shìdù","vi":"vừa phải"},{"hanzi":"分寸","pinyin":"fēncun","vi":"chừng mực"},{"hanzi":"过分","pinyin":"guòfèn","vi":"quá đáng"}]},{"id":"欠缺","hanzi":"欠缺","pinyin":"qiànquē","meaning_vi":"thiếu sót, khiếm khuyết","explanation":"欠 (thiếu) + 缺 (hụt).","hsk_level":6,"tags":["dong-tu","danh-tu"],"image":"📉","examples":[{"type":"basic","zh":"他还欠缺一些经验。","pinyin":"Tā hái qiànquē yìxiē jīngyàn.","vi":"Anh ấy vẫn còn thiếu chút kinh nghiệm."},{"type":"simple","zh":"这份方案在细节上还有不少欠缺。","pinyin":"Zhè fèn fāng'àn zài xìjié shang háiyǒu bùshǎo qiànquē.","vi":"Phương án này về chi tiết vẫn còn nhiều thiếu sót."},{"type":"compound","zh":"她的专业知识很扎实，只是欠缺与人沟通的技巧。","pinyin":"Tā de zhuānyè zhīshi hěn zhāshi, zhǐshì qiànquē yǔ rén gōutōng de jìqiǎo.","vi":"Kiến thức chuyên môn của cô ấy rất vững, chỉ là thiếu kỹ năng giao tiếp với người khác."}],"related":[{"hanzi":"缺乏","pinyin":"quēfá","vi":"thiếu"},{"hanzi":"缺陷","pinyin":"quēxiàn","vi":"khiếm khuyết"},{"hanzi":"不足","pinyin":"bùzú","vi":"không đủ"},{"hanzi":"完善","pinyin":"wánshàn","vi":"hoàn thiện"}]},{"id":"翘","hanzi":"翘","pinyin":"qiào","meaning_vi":"vểnh lên, nhón lên","explanation":"Ví dụ: 翘起二郎腿 (vắt chéo chân).","hsk_level":6,"tags":["dong-tu"],"image":"🦵","examples":[{"type":"basic","zh":"小狗翘起了尾巴。","pinyin":"Xiǎogǒu qiàoqǐle wěiba.","vi":"Chú chó con vểnh đuôi lên."},{"type":"simple","zh":"他得意地翘着二郎腿坐在沙发上。","pinyin":"Tā déyì de qiàozhe èrlángtuǐ zuò zài shāfā shang.","vi":"Anh ta đắc ý ngồi vắt chân chữ ngũ trên sofa."},{"type":"compound","zh":"新买的木地板一受潮，边缘就会翘起来。","pinyin":"Xīn mǎi de mù dìbǎn yí shòucháo, biānyuán jiù huì qiào qǐlái.","vi":"Sàn gỗ mới mua hễ bị ẩm là mép sẽ cong vểnh lên."}],"related":[{"hanzi":"翘尾巴","pinyin":"qiàowěiba","vi":"vểnh đuôi, kiêu ngạo"},{"hanzi":"翘首以待","pinyin":"qiáoshǒuyǐdài","vi":"ngóng chờ"},{"hanzi":"翘起","pinyin":"qiàoqǐ","vi":"vểnh lên"},{"hanzi":"踮脚","pinyin":"diǎnjiǎo","vi":"kiễng chân"}],"traditional":"翹"},{"id":"前赴后继","hanzi":"前赴后继","pinyin":"qiánfù-hòujì","meaning_vi":"lớp trước ngã lớp sau tiến lên","explanation":"Người trước xông lên, người sau tiếp bước → lớp này ngã xuống lớp khác tiến lên, đấu tranh kiên cường không ngừng.","hsk_level":6,"tags":["thanh-ngu"],"image":"🚩","examples":[{"type":"basic","zh":"英雄们前赴后继。","pinyin":"Yīngxióngmen qiánfùhòujì.","vi":"Các anh hùng lớp trước ngã, lớp sau tiến lên."},{"type":"simple","zh":"一代代科学家前赴后继地探索宇宙的奥秘。","pinyin":"Yí dàidài kēxuéjiā qiánfùhòujì de tànsuǒ yǔzhòu de àomì.","vi":"Hết thế hệ nhà khoa học này đến thế hệ khác nối tiếp nhau khám phá bí ẩn vũ trụ."},{"type":"compound","zh":"虽然困难重重，但是志愿者们前赴后继地赶往灾区。","pinyin":"Suīrán kùnnan chóngchóng, dànshì zhìyuànzhěmen qiánfùhòujì de gǎnwǎng zāiqū.","vi":"Tuy khó khăn chồng chất, nhưng các tình nguyện viên vẫn nối tiếp nhau đến vùng thiên tai."}],"related":[{"hanzi":"前仆后继","pinyin":"qiánpūhòujì","vi":"người trước ngã người sau tiến"},{"hanzi":"奋不顾身","pinyin":"fènbúgùshēn","vi":"quên mình"},{"hanzi":"英勇","pinyin":"yīngyǒng","vi":"anh dũng"},{"hanzi":"视死如归","pinyin":"shìsǐrúguī","vi":"coi chết như về"}],"traditional":"前赴後繼"},{"id":"潜伏","hanzi":"潜伏","pinyin":"qiánfú","meaning_vi":"tiềm phục, ẩn náu, ủ bệnh","explanation":"潜 (ẩn) + 伏 (nằm phục). Cụm: 潜伏期 (thời kỳ ủ bệnh).","hsk_level":6,"tags":["dong-tu","suc-khoe"],"image":"🕵️","examples":[{"type":"basic","zh":"敌人潜伏在山里。","pinyin":"Dírén qiánfú zài shān lǐ.","vi":"Kẻ địch ẩn nấp trong núi."},{"type":"simple","zh":"这种病毒在体内的潜伏期大约是两周。","pinyin":"Zhè zhǒng bìngdú zài tǐnèi de qiánfúqī dàyuē shì liǎng zhōu.","vi":"Thời gian ủ bệnh của loại virus này trong cơ thể khoảng hai tuần."},{"type":"compound","zh":"猎物一靠近，潜伏在草丛里的狮子就扑了上去。","pinyin":"Lièwù yí kàojìn, qiánfú zài cǎocóng lǐ de shīzi jiù pūle shàngqù.","vi":"Con mồi vừa đến gần, con sư tử nấp trong bụi cỏ liền lao tới."}],"related":[{"hanzi":"埋伏","pinyin":"máifú","vi":"mai phục"},{"hanzi":"隐藏","pinyin":"yǐncáng","vi":"ẩn giấu"},{"hanzi":"潜伏期","pinyin":"qiánfúqī","vi":"thời kỳ ủ bệnh"},{"hanzi":"卧底","pinyin":"wòdǐ","vi":"nằm vùng"}],"traditional":"潛伏"},{"id":"前景","hanzi":"前景","pinyin":"qiánjǐng","meaning_vi":"triển vọng, viễn cảnh","explanation":"前 (phía trước) + 景 (cảnh tượng).","hsk_level":6,"tags":["danh-tu","cong-viec"],"image":"🌅","examples":[{"type":"basic","zh":"这个行业前景很好。","pinyin":"Zhè ge hángyè qiánjǐng hěn hǎo.","vi":"Ngành này có triển vọng rất tốt."},{"type":"simple","zh":"专家对新能源汽车的市场前景十分乐观。","pinyin":"Zhuānjiā duì xīnnéngyuánqìchē de shìchǎng qiánjǐng shífēn lèguān.","vi":"Các chuyên gia rất lạc quan về triển vọng thị trường xe năng lượng mới."},{"type":"compound","zh":"如果不进行技术创新，公司的前景就会越来越暗淡。","pinyin":"Rúguǒ bú jìnxíng jìshù chuàngxīn, gōngsī de qiánjǐng jiù huì yuèláiyuè àndàn.","vi":"Nếu không đổi mới công nghệ, triển vọng của công ty sẽ ngày càng ảm đạm."}],"related":[{"hanzi":"前途","pinyin":"qiántú","vi":"tiền đồ"},{"hanzi":"远景","pinyin":"yuǎnjǐng","vi":"viễn cảnh"},{"hanzi":"前景光明","pinyin":"qiánjǐngguāngmíng","vi":"triển vọng sáng sủa"},{"hanzi":"展望","pinyin":"zhǎnwàng","vi":"nhìn về tương lai"}]},{"id":"潜移默化","hanzi":"潜移默化","pinyin":"qiányí-mòhuà","meaning_vi":"thấm dần một cách tự nhiên (ảnh hưởng)","explanation":"潜 (tiềm – ngầm) 移 (di – dời) 默 (mặc – lặng lẽ) 化 (hóa – biến đổi) → âm thầm thay đổi; chỉ ảnh hưởng thấm dần vào tư tưởng, tính cách.","hsk_level":6,"tags":["thanh-ngu"],"image":"🌱","examples":[{"type":"basic","zh":"父母的影响是潜移默化的。","pinyin":"Fùmǔ de yǐngxiǎng shì qiányímòhuà de.","vi":"Ảnh hưởng của cha mẹ thấm dần một cách tự nhiên."},{"type":"simple","zh":"经典名著潜移默化地塑造着孩子的品格。","pinyin":"Jīngdiǎn míngzhù qiányímòhuà de sùzàozhe háizi de pǐngé.","vi":"Các tác phẩm kinh điển âm thầm hun đúc nhân cách của trẻ."},{"type":"compound","zh":"只要老师以身作则，学生就会在潜移默化中受到影响。","pinyin":"Zhǐyào lǎoshī yǐshēnzuòzé, xuésheng jiù huì zài qiányímòhuà zhōng shòudào yǐngxiǎng.","vi":"Chỉ cần giáo viên làm gương, học sinh sẽ dần dần chịu ảnh hưởng một cách tự nhiên."}],"related":[{"hanzi":"耳濡目染","pinyin":"ěrrúmùrǎn","vi":"mưa dầm thấm lâu"},{"hanzi":"熏陶","pinyin":"xūntáo","vi":"hun đúc"},{"hanzi":"影响","pinyin":"yǐngxiǎng","vi":"ảnh hưởng"},{"hanzi":"言传身教","pinyin":"yánchuánshēnjiào","vi":"dạy bằng lời và gương"}],"traditional":"潛移默化"},{"id":"前仰后合","hanzi":"前仰后合","pinyin":"qiányǎng-hòuhé","meaning_vi":"cười nghiêng ngả (ngả trước nghiêng sau)","explanation":"Người ngửa ra sau (仰) rồi gập về trước (合) → cười nghiêng ngả, không đứng vững. Thường: 笑得前仰后合.","hsk_level":6,"tags":["thanh-ngu"],"image":"😂","examples":[{"type":"basic","zh":"大家笑得前仰后合。","pinyin":"Dàjiā xiào de qiányǎnghòuhé.","vi":"Mọi người cười nghiêng ngả."},{"type":"simple","zh":"他的模仿秀把全场观众逗得前仰后合。","pinyin":"Tā de mófǎng xiù bǎ quánchǎng guānzhòng dòu de qiányǎnghòuhé.","vi":"Màn bắt chước của anh ấy chọc cả khán phòng cười nghiêng ngả."},{"type":"compound","zh":"爷爷一讲起年轻时的糗事，我们就笑得前仰后合。","pinyin":"Yéye yì jiǎng qǐ niánqīng shí de qiǔshì, wǒmen jiù xiào de qiányǎnghòuhé.","vi":"Ông nội hễ kể chuyện ngớ ngẩn hồi trẻ, chúng tôi lại cười nghiêng ngả."}],"related":[{"hanzi":"捧腹大笑","pinyin":"pěngfùdàxiào","vi":"cười ôm bụng"},{"hanzi":"哄堂大笑","pinyin":"hōngtángdàxiào","vi":"cả phòng cười ồ"},{"hanzi":"笑弯了腰","pinyin":"xiàowānleyāo","vi":"cười gập người"},{"hanzi":"哈哈大笑","pinyin":"hāhādàxiào","vi":"cười ha hả"}],"traditional":"前仰後合"},{"id":"穷凶极恶","hanzi":"穷凶极恶","pinyin":"qióngxiōng-jí'è","meaning_vi":"hung ác tàn bạo cùng cực","explanation":"穷 (cùng – tột cùng) + 凶 (hung) + 极恶 (cực ác) → hung ác tàn bạo đến cực điểm.","hsk_level":6,"tags":["thanh-ngu"],"image":"👹","examples":[{"type":"basic","zh":"歹徒穷凶极恶。","pinyin":"Dǎitú qióngxiōngjí'è.","vi":"Bọn côn đồ hung ác tột cùng."},{"type":"simple","zh":"警方终于抓获了那个穷凶极恶的抢劫犯。","pinyin":"Jǐngfāng zhōngyú zhuāhuòle nà ge qióngxiōngjí'è de qiǎngjié fàn.","vi":"Cảnh sát cuối cùng đã bắt được tên cướp hung ác tàn bạo đó."},{"type":"compound","zh":"即使罪犯再穷凶极恶，警察也绝不会退缩。","pinyin":"Jíshǐ zuìfàn zài qióngxiōngjí'è, jǐngchá yě juébú huì tuìsuō.","vi":"Dù tội phạm có hung ác đến đâu, cảnh sát cũng tuyệt đối không lùi bước."}],"related":[{"hanzi":"凶神恶煞","pinyin":"xiōngshén'èshà","vi":"hung thần ác sát"},{"hanzi":"丧心病狂","pinyin":"sàngxīnbìngkuáng","vi":"táng tận lương tâm"},{"hanzi":"罪大恶极","pinyin":"zuìdà'èjí","vi":"tội ác tày trời"},{"hanzi":"凶恶","pinyin":"xiōng'è","vi":"hung ác"}],"traditional":"窮凶極惡"},{"id":"穷追不舍","hanzi":"穷追不舍","pinyin":"qióngzhuī-bùshě","meaning_vi":"đuổi theo quyết liệt không buông tha","explanation":"穷追 (truy đuổi đến cùng) + 不舍 (không buông) → bám đuổi riết không tha; cũng dùng cho truy hỏi vấn đề đến cùng.","hsk_level":6,"tags":["thanh-ngu"],"image":"🏃","examples":[{"type":"basic","zh":"记者穷追不舍。","pinyin":"Jìzhě qióngzhuībùshě.","vi":"Phóng viên bám riết không buông."},{"type":"simple","zh":"交警骑着摩托车对肇事车辆穷追不舍。","pinyin":"Jiāojǐng qízhe mótuōchē duì zhàoshì chēliàng qióngzhuībùshě.","vi":"Cảnh sát giao thông lái mô tô đuổi theo xe gây tai nạn không buông."},{"type":"compound","zh":"小偷虽然跑得很快，但是保安一路穷追不舍。","pinyin":"Xiǎotōu suīrán pǎo de hěn kuài, dànshì bǎo'ān yílù qióngzhuībùshě.","vi":"Tên trộm tuy chạy rất nhanh, nhưng bảo vệ vẫn đuổi theo suốt dọc đường không buông."}],"related":[{"hanzi":"紧追不舍","pinyin":"jǐnzhuībùshě","vi":"bám riết không buông"},{"hanzi":"追赶","pinyin":"zhuīgǎn","vi":"đuổi theo"},{"hanzi":"追击","pinyin":"zhuījī","vi":"truy kích"},{"hanzi":"穷追猛打","pinyin":"qióngzhuīměngdǎ","vi":"truy đuổi đánh tới cùng"}],"traditional":"窮追不捨"},{"id":"求同存异","hanzi":"求同存异","pinyin":"qiútóng-cúnyì","meaning_vi":"tìm điểm chung gác lại bất đồng","explanation":"求同 (tìm điểm chung) + 存异 (gác lại điểm khác) → tìm điểm chung, tạm gác bất đồng; nguyên tắc ngoại giao nổi tiếng của Chu Ân Lai (Hội nghị Bandung 1955).","hsk_level":6,"tags":["thanh-ngu","giao-tiep"],"image":"🤝","examples":[{"type":"basic","zh":"双方应求同存异。","pinyin":"Shuāngfāng yīng qiútóngcúnyì.","vi":"Hai bên nên tìm điểm chung, gác lại bất đồng."},{"type":"simple","zh":"两国代表本着求同存异的原则签署了协议。","pinyin":"Liǎngguó dàibiǎo běnzhe qiútóngcúnyì de yuánzé qiānshǔle xiéyì.","vi":"Đại diện hai nước đã ký hiệp định theo nguyên tắc tìm điểm chung, gác lại bất đồng."},{"type":"compound","zh":"只要大家都能求同存异，合作就能顺利进行下去。","pinyin":"Zhǐyào dàjiā dōu néng qiútóngcúnyì, hézuò jiù néng shùnlì jìnxíng xiàqù.","vi":"Chỉ cần mọi người đều tìm điểm chung và gác lại bất đồng, sự hợp tác sẽ tiến triển thuận lợi."}],"related":[{"hanzi":"和而不同","pinyin":"hé'érbùtóng","vi":"hòa mà không đồng"},{"hanzi":"妥协","pinyin":"tuǒxié","vi":"thỏa hiệp"},{"hanzi":"共识","pinyin":"gòngshí","vi":"đồng thuận"},{"hanzi":"分歧","pinyin":"fēnqí","vi":"bất đồng"}],"traditional":"求同存異"},{"id":"掐","hanzi":"掐","pinyin":"qiā","meaning_vi":"ngắt (hoa), bóp, bấm (giờ)","explanation":"Bộ tài gảy 扌+ 臽.","hsk_level":6,"tags":["dong-tu"],"image":"🤏","examples":[{"type":"basic","zh":"别掐公园的花。","pinyin":"Bié qiā gōngyuán de huā.","vi":"Đừng ngắt hoa trong công viên."},{"type":"simple","zh":"她偷偷掐了一下弟弟的胳膊。","pinyin":"Tā tōutōu qiāle yíxià dìdi de gēbo.","vi":"Cô ấy lén véo cánh tay em trai một cái."},{"type":"compound","zh":"教练一边掐着秒表，一边大声给队员加油。","pinyin":"Jiàoliàn yìbiān qiāzhe miǎobiǎo, yìbiān dàshēng gěi duìyuán jiāyóu.","vi":"Huấn luyện viên vừa bấm đồng hồ bấm giờ vừa lớn tiếng cổ vũ các cầu thủ."}],"related":[{"hanzi":"掐断","pinyin":"qiāduàn","vi":"ngắt đứt"},{"hanzi":"掐指一算","pinyin":"qiāzhǐyísuàn","vi":"bấm đốt ngón tay tính"},{"hanzi":"捏","pinyin":"niē","vi":"véo, bóp"},{"hanzi":"掐时间","pinyin":"qiāshíjiān","vi":"bấm giờ"}]},{"id":"千变万化","hanzi":"千变万化","pinyin":"qiānbiàn-wànhuà","meaning_vi":"biến hóa khôn lường","explanation":"Nghìn biến vạn hóa → thay đổi muôn hình vạn trạng, khôn lường. Hay tả thời tiết, tình hình.","hsk_level":6,"tags":["thanh-ngu"],"image":"🔄","examples":[{"type":"basic","zh":"山里的天气千变万化。","pinyin":"Shān lǐ de tiānqì qiānbiànwànhuà.","vi":"Thời tiết trên núi biến hóa khôn lường."},{"type":"simple","zh":"孩子们被千变万化的魔术表演迷住了。","pinyin":"Háizimen bèi qiānbiànwànhuà de móshù biǎoyǎn mízhù le.","vi":"Bọn trẻ bị cuốn hút bởi màn ảo thuật biến hóa khôn lường."},{"type":"compound","zh":"虽然市场千变万化，但是诚信经营永远不会过时。","pinyin":"Suīrán shìchǎng qiānbiànwànhuà, dànshì chéngxìn jīngyíng yǒngyuǎn bú huì guòshí.","vi":"Tuy thị trường biến đổi khôn lường, nhưng kinh doanh trung thực thì không bao giờ lỗi thời."}],"related":[{"hanzi":"变幻莫测","pinyin":"biànhuànmòcè","vi":"biến ảo khôn lường"},{"hanzi":"瞬息万变","pinyin":"shùnxīwànbiàn","vi":"biến đổi trong chớp mắt"},{"hanzi":"一成不变","pinyin":"yìchéngbúbiàn","vi":"không thay đổi"},{"hanzi":"变化","pinyin":"biànhuà","vi":"biến hóa"}],"traditional":"千變萬化"},{"id":"千军万马","hanzi":"千军万马","pinyin":"qiānjūn-wànmǎ","meaning_vi":"thiên quân vạn mã (lực lượng hùng hậu)","explanation":"Nghìn quân vạn ngựa → đội quân, lực lượng đông đảo hùng mạnh; cũng tả khí thế ào ạt.","hsk_level":6,"tags":["thanh-ngu"],"image":"🐎","examples":[{"type":"basic","zh":"高考像千军万马过独木桥。","pinyin":"Gāokǎo xiàng qiānjūnwànmǎguò dúmùqiáo.","vi":"Thi đại học giống như thiên quân vạn mã qua cầu độc mộc."},{"type":"simple","zh":"瀑布像千军万马一样从山顶奔腾而下。","pinyin":"Pùbù xiàng qiānjūnwànmǎ yíyàng cóng shāndǐng bēnténg ér xià.","vi":"Thác nước như thiên quân vạn mã từ đỉnh núi cuồn cuộn đổ xuống."},{"type":"compound","zh":"即使对方有千军万马，我们也毫不畏惧。","pinyin":"Jíshǐ duìfāng yǒu qiānjūnwànmǎ, wǒmen yě háobú wèijù.","vi":"Dù đối phương có thiên quân vạn mã, chúng ta cũng chẳng hề sợ hãi."}],"related":[{"hanzi":"兵强马壮","pinyin":"bīngqiángmǎzhuàng","vi":"binh hùng tướng mạnh"},{"hanzi":"浩浩荡荡","pinyin":"hàohàodàngdàng","vi":"rầm rộ"},{"hanzi":"单枪匹马","pinyin":"dānqiāngpǐmǎ","vi":"đơn thương độc mã"},{"hanzi":"军队","pinyin":"jūnduì","vi":"quân đội"}],"traditional":"千軍萬馬"},{"id":"千篇一律","hanzi":"千篇一律","pinyin":"qiānpiān-yílǜ","meaning_vi":"rập khuôn, nghìn bài như một","explanation":"Nghìn bài văn cùng một kiểu (律) → rập khuôn, đơn điệu thiếu sáng tạo.","hsk_level":6,"tags":["thanh-ngu"],"image":"📄","examples":[{"type":"basic","zh":"这些楼千篇一律。","pinyin":"Zhèxiē lóu qiānpiānyílǜ.","vi":"Những tòa nhà này rập khuôn như nhau."},{"type":"simple","zh":"很多旅游景点卖的纪念品都千篇一律。","pinyin":"Hěn duō lǚyóu jǐngdiǎn mài de jìniànpǐn dōu qiānpiānyílǜ.","vi":"Đồ lưu niệm bán ở nhiều điểm du lịch đều na ná như nhau."},{"type":"compound","zh":"如果作文总是千篇一律，就很难打动阅卷老师。","pinyin":"Rúguǒ zuòwén zǒngshì qiānpiānyílǜ, jiù hěn nán dǎdòng yuèjuàn lǎoshī.","vi":"Nếu bài văn lúc nào cũng rập khuôn thì rất khó gây ấn tượng với giáo viên chấm."}],"related":[{"hanzi":"千人一面","pinyin":"qiānrényímiàn","vi":"nghìn người một mặt"},{"hanzi":"一成不变","pinyin":"yìchéngbúbiàn","vi":"không thay đổi"},{"hanzi":"千差万别","pinyin":"qiānchāwànbié","vi":"muôn vàn khác biệt"},{"hanzi":"单调","pinyin":"dāndiào","vi":"đơn điệu"}]},{"id":"千辛万苦","hanzi":"千辛万苦","pinyin":"qiānxīn-wànkǔ","meaning_vi":"ngàn cay vạn đắng, muôn vàn gian khổ","explanation":"Nghìn cay vạn đắng → trải qua muôn vàn gian khổ. Thường: 经历千辛万苦.","hsk_level":6,"tags":["thanh-ngu"],"image":"😓","examples":[{"type":"basic","zh":"他吃尽了千辛万苦。","pinyin":"Tā chī jìnle qiānxīnwànkǔ.","vi":"Anh ấy đã nếm trải muôn vàn cay đắng."},{"type":"simple","zh":"救援队千辛万苦才把被困者救了出来。","pinyin":"Jiùyuánduì qiānxīnwànkǔ cái bǎ bèi kùn zhě jiùle chūlái.","vi":"Đội cứu hộ trải qua muôn vàn gian khổ mới cứu được người bị mắc kẹt ra."},{"type":"compound","zh":"虽然经历了千辛万苦，但是他终于找到了失散的妹妹。","pinyin":"Suīrán jīnglìle qiānxīnwànkǔ, dànshì tā zhōngyú zhǎodàole shīsàn de mèimei.","vi":"Tuy đã trải qua muôn vàn gian khổ, nhưng cuối cùng anh ấy cũng tìm được em gái thất lạc."}],"related":[{"hanzi":"历尽艰辛","pinyin":"lìjìnjiānxīn","vi":"trải qua gian khổ"},{"hanzi":"含辛茹苦","pinyin":"hánxīnrúkǔ","vi":"ngậm đắng nuốt cay"},{"hanzi":"艰苦","pinyin":"jiānkǔ","vi":"gian khổ"},{"hanzi":"轻而易举","pinyin":"qīng'éryìjǔ","vi":"dễ như trở bàn tay"}],"traditional":"千辛萬苦"},{"id":"迁移","hanzi":"迁移","pinyin":"qiānyí","meaning_vi":"di cư, di dời","explanation":"迁 (thiên – dời) + 移 (di – chuyển) → dời đi nơi khác. Cụm: 候鸟迁移, 人口迁移.","hsk_level":6,"tags":["dong-tu"],"image":"🚚","examples":[{"type":"basic","zh":"候鸟开始迁移了。","pinyin":"Hòuniǎo kāishǐ qiānyí le.","vi":"Chim di trú đã bắt đầu di cư."},{"type":"simple","zh":"工厂计划明年迁移到郊区的工业园。","pinyin":"Gōngchǎng jìhuà míngnián qiānyí dào jiāoqū de gōngyèyuán.","vi":"Nhà máy dự định năm sau dời ra khu công nghiệp ngoại thành."},{"type":"compound","zh":"因为家乡连年干旱，所以很多村民向城市迁移。","pinyin":"Yīnwèi jiāxiāng liánnián gānhàn, suǒyǐ hěn duō cūnmín xiàng chéngshì qiānyí.","vi":"Vì quê nhà hạn hán liên tiếp nhiều năm nên nhiều dân làng di cư lên thành phố."}],"related":[{"hanzi":"搬迁","pinyin":"bānqiān","vi":"di dời"},{"hanzi":"移民","pinyin":"yímín","vi":"di dân"},{"hanzi":"迁徙","pinyin":"qiānxǐ","vi":"di trú"},{"hanzi":"定居","pinyin":"dìngjū","vi":"định cư"}],"traditional":"遷移"},{"id":"牵制","hanzi":"牵制","pinyin":"qiānzhì","meaning_vi":"kiềm chế, kìm hãm","explanation":"牵 + 制 (chế ngự).","hsk_level":6,"tags":["dong-tu"],"image":"🛑","examples":[{"type":"basic","zh":"他用佯攻牵制敌军。","pinyin":"Tāyòng yáng gōng qiānzhì díjūn.","vi":"Anh ta dùng đòn nghi binh để kìm chân quân địch."},{"type":"simple","zh":"这位后卫整场比赛都在牵制对方的前锋。","pinyin":"Zhè wèi hòuwèi zhěng chǎng bǐsài dōu zài qiānzhì duìfāng de qiánfēng.","vi":"Hậu vệ này kèm chặt tiền đạo đối phương suốt cả trận."},{"type":"compound","zh":"因为资金受到牵制，所以这个项目一直无法推进。","pinyin":"Yīnwèi zījīn shòudào qiānzhì, suǒyǐ zhè ge xiàngmù yìzhí wúfǎ tuījìn.","vi":"Vì nguồn vốn bị kìm hãm nên dự án này mãi không thể triển khai."}],"related":[{"hanzi":"制约","pinyin":"zhìyuē","vi":"ràng buộc"},{"hanzi":"牵扯","pinyin":"qiānchě","vi":"dính líu"},{"hanzi":"限制","pinyin":"xiànzhì","vi":"hạn chế"},{"hanzi":"钳制","pinyin":"qiánzhì","vi":"kìm kẹp"}],"traditional":"牽制"},{"id":"千载难逢","hanzi":"千载难逢","pinyin":"qiānzǎi-nánféng","meaning_vi":"nghìn năm có một (cơ hội hiếm có)","explanation":"千载 (nghìn năm) + 难逢 (khó gặp). Thành ngữ.","hsk_level":6,"tags":["thanh-ngu"],"image":"🌟","examples":[{"type":"basic","zh":"这是千载难逢的机会。","pinyin":"Zhè shì qiānzǎinánféng de jīhuì.","vi":"Đây là cơ hội nghìn năm có một."},{"type":"simple","zh":"天文爱好者都在等待这场千载难逢的流星雨。","pinyin":"Tiānwén àihàozhě dōu zài děngdài zhè chǎng qiānzǎinánféng de liúxīngyǔ.","vi":"Những người yêu thiên văn đều đang chờ trận mưa sao băng nghìn năm có một này."},{"type":"compound","zh":"既然遇到了千载难逢的好机会，你就千万别错过。","pinyin":"Jìrán yùdàole qiānzǎinánféng de hǎo jīhuì, nǐ jiù qiānwàn bié cuòguò.","vi":"Đã gặp được cơ hội tốt nghìn năm có một thì bạn đừng bỏ lỡ."}],"related":[{"hanzi":"千载一时","pinyin":"qiānzǎiyìshí","vi":"nghìn năm một thuở"},{"hanzi":"机不可失","pinyin":"jībùkěshī","vi":"cơ hội không thể mất"},{"hanzi":"难得","pinyin":"nándé","vi":"hiếm có"},{"hanzi":"司空见惯","pinyin":"sīkōngjiànguàn","vi":"chuyện thường"}],"traditional":"千載難逢"},{"id":"枪毙","hanzi":"枪毙","pinyin":"qiāngbì","meaning_vi":"xử bắn","explanation":"枪 (súng) + 毙 (chết).","hsk_level":6,"tags":["dong-tu","phap-luat"],"image":"⚖️","examples":[{"type":"basic","zh":"那个毒贩被枪毙了。","pinyin":"Nà ge dúfàn bèi qiāngbì le.","vi":"Tên buôn ma túy đó đã bị xử bắn."},{"type":"simple","zh":"战争期间这名间谍被敌军枪毙了。","pinyin":"Zhànzhēng qījiān zhè míng jiàndié bèi díjūn qiāngbì le.","vi":"Trong thời chiến, gián điệp này đã bị quân địch xử bắn."},{"type":"compound","zh":"那名杀人犯一审被判死刑，不久后就被枪毙了。","pinyin":"Nà míng shārénfàn yìshěn bèi pàn sǐxíng, bùjiǔ hòu jiù bèi qiāngbì le.","vi":"Tên sát nhân đó bị tuyên án tử hình ở phiên sơ thẩm, không lâu sau đã bị xử bắn."}],"related":[{"hanzi":"枪决","pinyin":"qiāngjué","vi":"xử bắn"},{"hanzi":"死刑","pinyin":"sǐxíng","vi":"tử hình"},{"hanzi":"处决","pinyin":"chǔjué","vi":"hành quyết"},{"hanzi":"判处","pinyin":"pànchǔ","vi":"kết án"}],"traditional":"槍斃"},{"id":"跷跷板","hanzi":"跷跷板","pinyin":"qiāoqiāobǎn","meaning_vi":"bập bênh (trò chơi trẻ em)","explanation":"跷跷 + 板 (tấm ván).","hsk_level":6,"tags":["danh-tu","do-vat","giai-tri"],"image":"🛝","examples":[{"type":"basic","zh":"孩子们在玩跷跷板。","pinyin":"Háizimen zài wán qiāoqiāobǎn.","vi":"Bọn trẻ đang chơi bập bênh."},{"type":"simple","zh":"小区的游乐场新装了一个彩色跷跷板。","pinyin":"Xiǎoqū de yóulèchǎng xīn zhuāngle yí gè cǎisè qiāoqiāobǎn.","vi":"Sân chơi trong khu dân cư mới lắp một chiếc bập bênh nhiều màu."},{"type":"compound","zh":"因为哥哥比妹妹重得多，所以跷跷板总是一头高一头低。","pinyin":"Yīnwèi gēge bǐ mèimei zhòng de duō, suǒyǐ qiāoqiāobǎn zǒngshì yìtóu gāo yìtóu dī.","vi":"Vì anh trai nặng hơn em gái nhiều nên chiếc bập bênh lúc nào cũng một đầu cao một đầu thấp."}],"related":[{"hanzi":"秋千","pinyin":"qiūqiān","vi":"xích đu"},{"hanzi":"滑梯","pinyin":"huátī","vi":"cầu trượt"},{"hanzi":"游乐场","pinyin":"yóulèchǎng","vi":"khu vui chơi"},{"hanzi":"木马","pinyin":"mùmǎ","vi":"ngựa gỗ"}],"traditional":"蹺蹺板"},{"id":"切磋","hanzi":"切磋","pinyin":"qiēcuō","meaning_vi":"trao đổi học hỏi lẫn nhau (kỹ năng/học thuật)","explanation":"切 (thiết – cắt) + 磋 (tha – mài) → vốn chỉ cắt mài xương ngà (Kinh Thi) → cùng nhau trao đổi, học hỏi lẫn nhau. Cụm: 切磋技艺.","hsk_level":6,"tags":["dong-tu","hoc-tap"],"image":"🤝","examples":[{"type":"basic","zh":"我们互相切磋棋艺。","pinyin":"Wǒmen hùxiāng qiēcuō qíyì.","vi":"Chúng tôi cùng nhau trao đổi học hỏi kỹ năng chơi cờ."},{"type":"simple","zh":"两位学者在研讨会上切磋了学术问题。","pinyin":"Liǎng wèi xuézhě zài yántǎohuì shang qiēcuōle xuéshù wèntí.","vi":"Hai học giả đã trao đổi về các vấn đề học thuật tại hội thảo."},{"type":"compound","zh":"只要经常和高手切磋，你的球技就会进步得很快。","pinyin":"Zhǐyào jīngcháng hé gāoshǒu qiēcuō, nǐ de qiú jì jiù huì jìnbù de hěn kuài.","vi":"Chỉ cần thường xuyên giao lưu học hỏi với cao thủ, kỹ thuật chơi bóng của bạn sẽ tiến bộ rất nhanh."}],"related":[{"hanzi":"切磋琢磨","pinyin":"qiēcuōzhuómó","vi":"mài giũa trao đổi"},{"hanzi":"交流","pinyin":"jiāoliú","vi":"giao lưu"},{"hanzi":"探讨","pinyin":"tàntǎo","vi":"thảo luận"},{"hanzi":"互相学习","pinyin":"hùxiāngxuéxí","vi":"học hỏi lẫn nhau"}]},{"id":"丘陵","hanzi":"丘陵","pinyin":"qiūlíng","meaning_vi":"đồi núi trập trùng, vùng đồi","explanation":"丘 (gò đồi) + 陵 (đồi lớn).","hsk_level":6,"tags":["danh-tu","thien-nhien","dia-diem"],"image":"⛰️","examples":[{"type":"basic","zh":"这里多是丘陵。","pinyin":"Zhèlǐ duō shì qiūlíng.","vi":"Nơi này chủ yếu là đồi núi."},{"type":"simple","zh":"茶园沿着起伏的丘陵一直延伸到远方。","pinyin":"Chá yuán yánzhe qǐfú de qiūlíng yìzhí yánshēn dào yuǎnfāng.","vi":"Đồi chè trải dài theo những ngọn đồi nhấp nhô đến tận phương xa."},{"type":"compound","zh":"因为这一带都是丘陵，所以不适合种水稻。","pinyin":"Yīnwèi zhè yídài dōu shì qiūlíng, suǒyǐ bú shìhé zhòng shuǐdào.","vi":"Vì vùng này toàn là đồi nên không thích hợp trồng lúa nước."}],"related":[{"hanzi":"山丘","pinyin":"shānqiū","vi":"đồi"},{"hanzi":"平原","pinyin":"píngyuán","vi":"đồng bằng"},{"hanzi":"山地","pinyin":"shāndì","vi":"vùng núi"},{"hanzi":"高原","pinyin":"gāoyuán","vi":"cao nguyên"}]},{"id":"强词夺理","hanzi":"强词夺理","pinyin":"qiǎngcí-duólǐ","meaning_vi":"cãi chày cãi cối, lý sự cùn","explanation":"强词 (cố gượng lời) + 夺理 (giành lẽ phải) → không có lý mà vẫn cố cãi cho bằng được, lý sự cùn.","hsk_level":6,"tags":["thanh-ngu"],"image":"😤","examples":[{"type":"basic","zh":"你别强词夺理了。","pinyin":"Nǐ bié qiǎngcíduólǐ le.","vi":"Cậu đừng cãi chày cãi cối nữa."},{"type":"simple","zh":"他明明迟到了还强词夺理地怪公交车。","pinyin":"Tā míngmíng chídàole hái qiǎngcíduólǐ de guài gōngjiāochē.","vi":"Rõ ràng anh ta đến muộn mà còn lý sự cùn đổ lỗi cho xe buýt."},{"type":"compound","zh":"与其强词夺理地狡辩，不如痛痛快快地认个错。","pinyin":"Yǔqí qiǎngcíduólǐ de jiǎobiàn, bùrú tòng tòngkuài kuài de rèn gè cuò.","vi":"Thay vì cãi chày cãi cối, chẳng bằng thẳng thắn nhận lỗi."}],"related":[{"hanzi":"胡搅蛮缠","pinyin":"hújiǎománchán","vi":"cãi cùn quấy rối"},{"hanzi":"狡辩","pinyin":"jiǎobiàn","vi":"ngụy biện"},{"hanzi":"理直气壮","pinyin":"lǐzhíqìzhuàng","vi":"lý lẽ hùng hồn"},{"hanzi":"无理取闹","pinyin":"wúlǐqǔnào","vi":"vô cớ gây sự"}],"traditional":"強詞奪理"},{"id":"抢救","hanzi":"抢救","pinyin":"qiǎngjiù","meaning_vi":"cấp cứu, cứu hộ khẩn cấp","explanation":"抢 (thương – giành, gấp rút) + 救 (cứu) → giành giật từng giây để cứu chữa. Cụm: 抢救病人, 抢救无效.","hsk_level":6,"tags":["dong-tu","suc-khoe"],"image":"🚑","examples":[{"type":"basic","zh":"病人正在抢救中。","pinyin":"Bìngrén zhèngzài qiǎngjiù zhōng.","vi":"Bệnh nhân đang được cấp cứu."},{"type":"simple","zh":"医生们连续抢救了六个小时。","pinyin":"Yīshēngmen liánxù qiǎngjiùle liù gè xiǎoshí.","vi":"Các bác sĩ đã cấp cứu liên tục sáu tiếng đồng hồ."},{"type":"compound","zh":"如果抢救不及时，这位老人就可能有生命危险。","pinyin":"Rúguǒ qiǎngjiù bù jíshí, zhè wèi lǎorén jiù kěnéng yǒu shēngmìng wēixiǎn.","vi":"Nếu cấp cứu không kịp thời, cụ già này có thể nguy hiểm đến tính mạng."}],"related":[{"hanzi":"急救","pinyin":"jíjiù","vi":"sơ cứu"},{"hanzi":"救护车","pinyin":"jiùhùchē","vi":"xe cứu thương"},{"hanzi":"救死扶伤","pinyin":"jiùsǐfúshāng","vi":"cứu người bị thương"},{"hanzi":"抢险","pinyin":"qiǎngxiǎn","vi":"cứu hộ khẩn cấp"}],"traditional":"搶救"},{"id":"巧夺天工","hanzi":"巧夺天工","pinyin":"qiǎoduó-tiāngōng","meaning_vi":"khéo léo tinh xảo vượt cả tạo hóa","explanation":"巧 (khéo) + 夺天工 (vượt cả công trời) → tinh xảo hơn cả tạo hóa; khen tác phẩm nghệ thuật, đồ thủ công.","hsk_level":6,"tags":["thanh-ngu","van-hoa"],"image":"🏛️","examples":[{"type":"basic","zh":"这件玉雕巧夺天工。","pinyin":"Zhè jiàn yù diāo qiǎoduótiāngōng.","vi":"Tác phẩm điêu khắc ngọc này tinh xảo vượt cả tạo hóa."},{"type":"simple","zh":"游客们纷纷赞叹这座古桥巧夺天工。","pinyin":"Yóukèmen fēnfēn zàntàn zhè zuò gǔ qiáo qiǎoduótiāngōng.","vi":"Du khách đều trầm trồ khen cây cầu cổ này khéo léo tuyệt vời."},{"type":"compound","zh":"这些刺绣不但巧夺天工，而且全是手工完成的。","pinyin":"Zhèxiē cìxiù búdàn qiǎoduótiāngōng, érqiě quán shì shǒugōng wánchéng de.","vi":"Những bức thêu này không những tinh xảo tuyệt mỹ mà còn hoàn toàn làm bằng tay."}],"related":[{"hanzi":"鬼斧神工","pinyin":"guǐfǔshéngōng","vi":"tuyệt tác thần kỳ"},{"hanzi":"精巧","pinyin":"jīngqiǎo","vi":"tinh xảo"},{"hanzi":"精湛","pinyin":"jīngzhàn","vi":"điêu luyện"},{"hanzi":"粗制滥造","pinyin":"cūzhìlànzào","vi":"làm ẩu"}],"traditional":"巧奪天工"},{"id":"全力以赴","hanzi":"全力以赴","pinyin":"quánlì-yǐfù","meaning_vi":"dốc toàn lực làm việc","explanation":"全力 (hết sức) + 以赴 (dồn vào). Thành ngữ.","hsk_level":6,"tags":["thanh-ngu"],"image":"💪","examples":[{"type":"basic","zh":"我们会全力以赴的。","pinyin":"Wǒmen huì quánlìyǐfù de.","vi":"Chúng tôi sẽ dốc toàn lực."},{"type":"simple","zh":"全体队员全力以赴备战下个月的决赛。","pinyin":"Quántǐ duìyuán quánlìyǐfù bèizhàn xiàgèyuè de juésài.","vi":"Toàn đội dốc hết sức chuẩn bị cho trận chung kết tháng sau."},{"type":"compound","zh":"只要我们全力以赴，就一定能按时完成任务。","pinyin":"Zhǐyào wǒmen quánlìyǐfù, jiù yídìng néng ànshí wánchéng rènwu.","vi":"Chỉ cần chúng ta dốc toàn lực, nhất định sẽ hoàn thành nhiệm vụ đúng hạn."}],"related":[{"hanzi":"竭尽全力","pinyin":"jiéjìnquánlì","vi":"dốc hết toàn lực"},{"hanzi":"尽力而为","pinyin":"jìnlì'érwéi","vi":"cố gắng hết sức"},{"hanzi":"不遗余力","pinyin":"bùyíyúlì","vi":"không tiếc sức"},{"hanzi":"敷衍了事","pinyin":"fūyǎnliǎoshì","vi":"làm qua loa"}]},{"id":"全神贯注","hanzi":"全神贯注","pinyin":"quánshén-guànzhù","meaning_vi":"tập trung tinh thần cao độ","explanation":"全神 (toàn bộ tinh thần) + 贯注 (dồn vào) → dồn hết tâm trí, tập trung cao độ. Thường: 全神贯注地听讲.","hsk_level":6,"tags":["thanh-ngu","hoc-tap"],"image":"🧘","examples":[{"type":"basic","zh":"他全神贯注地听课。","pinyin":"Tā quánshénguànzhù de tīngkè.","vi":"Cậu ấy chăm chú nghe giảng."},{"type":"simple","zh":"外科医生全神贯注地进行着手术。","pinyin":"Wàikē yīshēng quánshénguànzhù de jìnxíngzhe shǒushù.","vi":"Bác sĩ phẫu thuật tập trung cao độ tiến hành ca mổ."},{"type":"compound","zh":"他一全神贯注地看书，就听不见别人叫他。","pinyin":"Tā yì quánshénguànzhù de kànshū, jiù tīngbújiàn biérén jiào tā.","vi":"Hễ anh ấy tập trung đọc sách là không nghe thấy người khác gọi."}],"related":[{"hanzi":"聚精会神","pinyin":"jùjīnghuìshén","vi":"tập trung tinh thần"},{"hanzi":"专心致志","pinyin":"zhuānxīnzhìzhì","vi":"chuyên tâm"},{"hanzi":"心不在焉","pinyin":"xīnbúzàiyān","vi":"lơ đãng"},{"hanzi":"目不转睛","pinyin":"mùbùzhuǎnjīng","vi":"nhìn không chớp mắt"}],"traditional":"全神貫注"},{"id":"权宜之计","hanzi":"权宜之计","pinyin":"quányí-zhījì","meaning_vi":"kế sách tạm thời, giải pháp tình thế","explanation":"权宜 (quyền nghi – tạm thời, linh hoạt) + 之计 (kế sách) → biện pháp tạm thời để ứng phó tình thế.","hsk_level":6,"tags":["thanh-ngu"],"image":"⏳","examples":[{"type":"basic","zh":"这只是权宜之计。","pinyin":"Zhè zhǐshì quányízhījì.","vi":"Đây chỉ là kế sách tạm thời."},{"type":"simple","zh":"用胶带粘住水管只是暂时的权宜之计。","pinyin":"Yòng jiāodài zhān zhù shuǐguǎn zhǐshì zànshí de quányízhījì.","vi":"Dùng băng dính quấn ống nước chỉ là giải pháp tình thế tạm thời."},{"type":"compound","zh":"降价促销虽然是权宜之计，但是能暂时缓解库存压力。","pinyin":"Jiàngjià cùxiāo suīrán shì quányízhījì, dànshì néng zànshí huǎnjiě kùcún yālì.","vi":"Giảm giá khuyến mãi tuy chỉ là kế tạm thời, nhưng có thể tạm giảm áp lực hàng tồn kho."}],"related":[{"hanzi":"缓兵之计","pinyin":"huǎnbīngzhījì","vi":"kế hoãn binh"},{"hanzi":"应急","pinyin":"yìngjí","vi":"ứng phó khẩn cấp"},{"hanzi":"长久之计","pinyin":"chángjiǔzhījì","vi":"kế lâu dài"},{"hanzi":"临时","pinyin":"línshí","vi":"tạm thời"}],"traditional":"權宜之計"},{"id":"确信","hanzi":"确信","pinyin":"quèxìn","meaning_vi":"tin chắc","explanation":"确 (xác – chắc chắn) + 信 (tín – tin) → tin chắc chắn. Ví dụ: 我确信他会来.","hsk_level":6,"tags":["dong-tu"],"image":"💯","examples":[{"type":"basic","zh":"我确信他是无辜的。","pinyin":"Wǒ quèxìn tā shì wúgū de.","vi":"Tôi tin chắc anh ấy vô tội."},{"type":"simple","zh":"律师确信手里的证据足以赢得官司。","pinyin":"Lǜshī quèxìn shǒulǐ de zhèngjù zúyǐ yíngdé guānsi.","vi":"Luật sư tin chắc chứng cứ trong tay đủ để thắng kiện."},{"type":"compound","zh":"因为确信自己没有记错，所以她坚持重新核对账目。","pinyin":"Yīnwèi quèxìn zìjǐ méiyǒu jìcuò, suǒyǐ tā jiānchí chóngxīn héduì zhàngmù.","vi":"Vì tin chắc mình không nhớ nhầm nên cô ấy khăng khăng đối chiếu lại sổ sách."}],"related":[{"hanzi":"相信","pinyin":"xiāngxìn","vi":"tin tưởng"},{"hanzi":"坚信","pinyin":"jiānxìn","vi":"tin chắc"},{"hanzi":"深信不疑","pinyin":"shēnxìnbùyí","vi":"tin không nghi ngờ"},{"hanzi":"怀疑","pinyin":"huáiyí","vi":"nghi ngờ"}],"traditional":"確信"},{"id":"雀跃","hanzi":"雀跃","pinyin":"quèyuè","meaning_vi":"nhảy cẫng lên vì vui sướng","explanation":"雀 (chim sẻ) + 跃 (nhảy).","hsk_level":6,"tags":["dong-tu","cam-xuc"],"image":"🥳","examples":[{"type":"basic","zh":"孩子们欢呼雀跃。","pinyin":"Háizimen huānhū quèyuè.","vi":"Bọn trẻ reo hò nhảy cẫng lên."},{"type":"simple","zh":"球迷们为主队的胜利欢呼雀跃。","pinyin":"Qiúmímen wèi zhǔduì de shènglì huānhū quèyuè.","vi":"Người hâm mộ reo hò nhảy cẫng vì chiến thắng của đội nhà."},{"type":"compound","zh":"一听说明天去动物园，孩子们就雀跃不已。","pinyin":"Yì tīngshuō míngtiān qù dòngwùyuán, háizimen jiù quèyuè bùyǐ.","vi":"Vừa nghe nói ngày mai đi sở thú, bọn trẻ liền nhảy cẫng lên vui sướng."}],"related":[{"hanzi":"欢呼雀跃","pinyin":"huānhūquèyuè","vi":"reo hò nhảy cẫng"},{"hanzi":"欢欣鼓舞","pinyin":"huānxīngǔwǔ","vi":"hân hoan phấn khởi"},{"hanzi":"手舞足蹈","pinyin":"shǒuwǔzúdǎo","vi":"khoa chân múa tay"},{"hanzi":"兴高采烈","pinyin":"xìnggāocǎiliè","vi":"hớn hở"}],"traditional":"雀躍"},{"id":"瘸","hanzi":"瘸","pinyin":"qué","meaning_vi":"què, khập khiễng","explanation":"Bộ nạch 疒+ 欠 + 肉.","hsk_level":6,"tags":["tinh-tu","suc-khoe"],"image":"🦯","examples":[{"type":"basic","zh":"他的腿有点瘸。","pinyin":"Tā de tuǐ yǒudiǎn qué.","vi":"Chân anh ấy hơi khập khiễng."},{"type":"simple","zh":"那只受伤的小狗一瘸一拐地走过来。","pinyin":"Nà zhī shòushāng de xiǎogǒu yì qué yì guǎi de zǒu guòlái.","vi":"Chú chó bị thương khập khiễng đi tới."},{"type":"compound","zh":"他虽然摔瘸了腿，但是仍然坚持来上班。","pinyin":"Tā suīrán shuāi quéle tuǐ, dànshì réngrán jiānchí lái shàngbān.","vi":"Anh ấy tuy bị ngã què chân, nhưng vẫn kiên trì đi làm."}],"related":[{"hanzi":"瘸子","pinyin":"quézi","vi":"người què"},{"hanzi":"跛","pinyin":"bǒ","vi":"khập khiễng"},{"hanzi":"一瘸一拐","pinyin":"yìquéyìguǎi","vi":"đi cà nhắc"},{"hanzi":"残疾","pinyin":"cánjí","vi":"tàn tật"}]},{"id":"圈套","hanzi":"圈套","pinyin":"quāntào","meaning_vi":"cái bẫy, cạm bẫy","explanation":"圈 (vòng tròn) + 套 (thòng lọng).","hsk_level":6,"tags":["danh-tu"],"image":"🪤","examples":[{"type":"basic","zh":"小心别中了圈套。","pinyin":"Xiǎoxīn bié zhòngle quāntào.","vi":"Cẩn thận đừng mắc bẫy."},{"type":"simple","zh":"骗子设下圈套骗走了老人的积蓄。","pinyin":"Piànzi shè xià quāntào piànzǒule lǎorén de jīxù.","vi":"Kẻ lừa đảo giăng bẫy lừa lấy hết tiền tiết kiệm của cụ già."},{"type":"compound","zh":"他一时贪心，结果一步步走进了对方的圈套。","pinyin":"Tā yìshí tānxīn, jiéguǒ yí bùbù zǒujìnle duìfāng de quāntào.","vi":"Anh ta nhất thời tham lam, kết quả từng bước sa vào cạm bẫy của đối phương."}],"related":[{"hanzi":"陷阱","pinyin":"xiànjǐng","vi":"cạm bẫy"},{"hanzi":"骗局","pinyin":"piànjú","vi":"trò lừa đảo"},{"hanzi":"上当","pinyin":"shàngdàng","vi":"mắc lừa"},{"hanzi":"中计","pinyin":"zhòngjì","vi":"trúng kế"}]},{"id":"缺口","hanzi":"缺口","pinyin":"quēkǒu","meaning_vi":"lỗ hổng, chỗ thiếu hụt","explanation":"缺 (thiếu) + 口 (miệng).","hsk_level":6,"tags":["danh-tu"],"image":"🕳️","examples":[{"type":"basic","zh":"围墙上有个缺口。","pinyin":"Wéiqiáng shang yǒu gè quēkǒu.","vi":"Trên tường rào có một lỗ hổng."},{"type":"simple","zh":"今年这座城市的电力缺口达到了百分之十。","pinyin":"Jīnnián zhè zuò chéngshì de diànlì quēkǒu dádàole bǎifēnzhī shí.","vi":"Năm nay mức thiếu hụt điện của thành phố này lên đến mười phần trăm."},{"type":"compound","zh":"如果不及时堵住堤坝的缺口，洪水就会冲进村子。","pinyin":"Rúguǒ bù jíshí dǔzhù dībà de quēkǒu, hóngshuǐ jiù huì chōngjìn cūnzi.","vi":"Nếu không kịp thời bịt chỗ vỡ đê, lũ sẽ tràn vào làng."}],"related":[{"hanzi":"漏洞","pinyin":"lòudòng","vi":"lỗ hổng"},{"hanzi":"缺陷","pinyin":"quēxiàn","vi":"khiếm khuyết"},{"hanzi":"资金缺口","pinyin":"zījīnquēkǒu","vi":"thiếu hụt vốn"},{"hanzi":"突破口","pinyin":"tūpòkǒu","vi":"điểm đột phá"}]},{"id":"犬牙交错","hanzi":"犬牙交错","pinyin":"quǎnyá-jiāocuò","meaning_vi":"xen kẽ chằng chịt như răng chó","explanation":"Răng chó so le đan xen nhau → ranh giới gồ ghề cài răng lược; nghĩa bóng: tình hình phức tạp, đan xen.","hsk_level":6,"tags":["thanh-ngu"],"image":"🦷","examples":[{"type":"basic","zh":"两县边界犬牙交错。","pinyin":"Liǎng xiàn biānjiè quǎnyájiāocuò.","vi":"Ranh giới hai huyện xen kẽ chằng chịt."},{"type":"simple","zh":"海岸线上犬牙交错的礁石十分危险。","pinyin":"Hǎi'àn xiànshang quǎnyájiāocuò de jiāoshí shífēn wēixiǎn.","vi":"Những tảng đá ngầm lởm chởm dọc bờ biển rất nguy hiểm."},{"type":"compound","zh":"因为双方阵地犬牙交错，所以战斗打得异常艰难。","pinyin":"Yīnwèi shuāngfāng zhèndì quǎnyájiāocuò, suǒyǐ zhàndòu dǎ de yìcháng jiānnán.","vi":"Vì trận địa hai bên đan xen chằng chịt nên trận chiến diễn ra vô cùng gian nan."}],"related":[{"hanzi":"错综复杂","pinyin":"cuòzōngfùzá","vi":"chằng chịt phức tạp"},{"hanzi":"参差不齐","pinyin":"cēncībùqí","vi":"so le không đều"},{"hanzi":"交错","pinyin":"jiāocuò","vi":"đan xen"},{"hanzi":"纵横交错","pinyin":"zònghéngjiāocuò","vi":"ngang dọc chằng chịt"}],"traditional":"犬牙交錯"},{"id":"气喘","hanzi":"气喘","pinyin":"qìchuǎn","meaning_vi":"hen suyễn, thở dốc","explanation":"气 (hơi thở) + 喘 (thở gấp).","hsk_level":6,"tags":["danh-tu","suc-khoe"],"image":"😮‍💨","examples":[{"type":"basic","zh":"爷爷有气喘病。","pinyin":"Yéye yǒu qìchuǎnbìng.","vi":"Ông nội bị bệnh hen suyễn."},{"type":"simple","zh":"季节交替时她的气喘常常会发作。","pinyin":"Jìjié jiāotì shí tā de qìchuǎn chángcháng huì fāzuò.","vi":"Lúc giao mùa, bệnh hen suyễn của cô ấy thường tái phát."},{"type":"compound","zh":"因为有气喘，所以他出门总是随身带着喷雾剂。","pinyin":"Yīnwèi yǒu qìchuǎn, suǒyǐ tā chūmén zǒngshì suíshēn dàizhe pēnwù jì.","vi":"Vì bị hen suyễn nên anh ấy ra ngoài luôn mang theo bình xịt."}],"related":[{"hanzi":"哮喘","pinyin":"xiàochuǎn","vi":"bệnh hen"},{"hanzi":"喘气","pinyin":"chuǎnqì","vi":"thở dốc"},{"hanzi":"呼吸","pinyin":"hūxī","vi":"hô hấp"},{"hanzi":"气喘吁吁","pinyin":"qìchuǎnxūxū","vi":"thở hổn hển"}],"traditional":"氣喘"},{"id":"气喘吁吁","hanzi":"气喘吁吁","pinyin":"qìchuǎn-xūxū","meaning_vi":"thở hổn hển","explanation":"气喘 (thở gấp) + 吁吁 (tiếng thở phì phò) → thở hổn hển. Thường: 跑得气喘吁吁.","hsk_level":6,"tags":["thanh-ngu","suc-khoe"],"image":"😮‍💨","examples":[{"type":"basic","zh":"他跑得气喘吁吁。","pinyin":"Tā pǎo deqì chuǎnxūxū.","vi":"Anh ấy chạy đến thở hổn hển."},{"type":"simple","zh":"快递员气喘吁吁地把冰箱搬上了六楼。","pinyin":"Kuàidìyuán qìchuǎnxūxū de bǎ bīngxiāng bān shàngle liù lóu.","vi":"Người giao hàng thở hổn hển khiêng tủ lạnh lên tầng sáu."},{"type":"compound","zh":"我们刚爬到半山腰，大家就已经气喘吁吁了。","pinyin":"Wǒmen gāng pá dào bànshānyāo, dàjiā jiù yǐjīng qìchuǎnxūxū le.","vi":"Chúng tôi mới leo được lưng chừng núi mà mọi người đã thở hổn hển."}],"related":[{"hanzi":"上气不接下气","pinyin":"shàng qì bù jiēxià qì","vi":"thở không ra hơi"},{"hanzi":"气喘","pinyin":"qìchuǎn","vi":"thở gấp"},{"hanzi":"精疲力竭","pinyin":"jīngpílìjié","vi":"kiệt sức"},{"hanzi":"喘气","pinyin":"chuǎnqì","vi":"thở dốc"}],"traditional":"氣喘吁吁"},{"id":"器材","hanzi":"器材","pinyin":"qìcái","meaning_vi":"thiết bị, dụng cụ","explanation":"器 + 材 (vật liệu). Cụm: 体育器材 (dụng cụ thể thao).","hsk_level":6,"tags":["danh-tu","do-vat","the-thao"],"image":"🏋️","examples":[{"type":"basic","zh":"体育器材放在仓库里。","pinyin":"Tǐyù qìcái fàng zài cāngkù lǐ.","vi":"Dụng cụ thể thao để trong kho."},{"type":"simple","zh":"摄影师带着全套器材去草原拍日出。","pinyin":"Shèyǐngshī dàizhe quántào qìcái qù cǎoyuán pāi rìchū.","vi":"Nhiếp ảnh gia mang theo trọn bộ thiết bị lên thảo nguyên chụp bình minh."},{"type":"compound","zh":"如果不会使用健身器材，就最好先请教练示范。","pinyin":"Rúguǒ bú huì shǐyòng jiànshēnqìcái, jiù zuìhǎo xiān qǐng jiàoliàn shìfàn.","vi":"Nếu không biết dùng dụng cụ tập gym thì tốt nhất nên nhờ huấn luyện viên hướng dẫn trước."}],"related":[{"hanzi":"设备","pinyin":"shèbèi","vi":"thiết bị"},{"hanzi":"器械","pinyin":"qìxiè","vi":"khí cụ"},{"hanzi":"体育器材","pinyin":"tǐyùqìcái","vi":"dụng cụ thể thao"},{"hanzi":"工具","pinyin":"gōngjù","vi":"công cụ"}]},{"id":"气功","hanzi":"气功","pinyin":"qìgōng","meaning_vi":"khí công","explanation":"气 + 功 (công phu).","hsk_level":6,"tags":["danh-tu","van-hoa","suc-khoe"],"image":"🧘","examples":[{"type":"basic","zh":"爷爷每天练气功。","pinyin":"Yéye měitiān liàn qìgōng.","vi":"Ông nội ngày nào cũng tập khí công."},{"type":"simple","zh":"公园里有一群老人在跟着音乐练气功。","pinyin":"Gōngyuán lǐ yǒu yìqún lǎorén zài gēnzhe yīnyuè liàn qìgōng.","vi":"Trong công viên có một nhóm cụ già đang tập khí công theo nhạc."},{"type":"compound","zh":"自从练了气功，他的睡眠质量就好了很多。","pinyin":"Zìcóng liànle qìgōng, tā de shuìmián zhìliàng jiù hǎole hěn duō.","vi":"Từ khi tập khí công, chất lượng giấc ngủ của ông ấy tốt hơn nhiều."}],"related":[{"hanzi":"太极拳","pinyin":"tàijíquán","vi":"thái cực quyền"},{"hanzi":"武术","pinyin":"wǔshù","vi":"võ thuật"},{"hanzi":"养生","pinyin":"yǎngshēng","vi":"dưỡng sinh"},{"hanzi":"练功","pinyin":"liàngōng","vi":"luyện công"}],"traditional":"氣功"},{"id":"迄今","hanzi":"迄今","pinyin":"qìjīn","meaning_vi":"cho đến nay","explanation":"迄 (tới) + 今 (nay).","hsk_level":6,"tags":["pho-tu","thoi-gian"],"image":"⏳","examples":[{"type":"basic","zh":"迄今已有十年了。","pinyin":"Qìjīn yǐ yǒu shí nián le.","vi":"Đến nay đã được mười năm."},{"type":"simple","zh":"这是迄今为止发现的最大的恐龙化石。","pinyin":"Zhè shì qìjīnwéizhǐ fāxiàn de zuì dà de kǒnglóng huàshí.","vi":"Đây là hóa thạch khủng long lớn nhất được phát hiện cho đến nay."},{"type":"compound","zh":"虽然研究了很多年，但是迄今仍没有找到病因。","pinyin":"Suīrán yánjiūle hěn duōnián, dànshì qìjīn réng méiyǒu zhǎodào bìngyīn.","vi":"Tuy đã nghiên cứu nhiều năm, nhưng đến nay vẫn chưa tìm ra nguyên nhân gây bệnh."}],"related":[{"hanzi":"至今","pinyin":"zhìjīn","vi":"đến nay"},{"hanzi":"迄今为止","pinyin":"qìjīnwéizhǐ","vi":"cho đến nay"},{"hanzi":"到目前为止","pinyin":"dào mùqián wéizhǐ","vi":"tính đến hiện tại"},{"hanzi":"从来","pinyin":"cónglái","vi":"xưa nay"}]},{"id":"气味","hanzi":"气味","pinyin":"qìwèi","meaning_vi":"mùi, mùi vị","explanation":"气 (khí – hơi) + 味 (vị) → mùi; nghĩa bóng tính khí, sở thích (thường ý xấu). Cụm: 气味相投 (hợp gu nhau).","hsk_level":6,"tags":["danh-tu"],"image":"👃","examples":[{"type":"basic","zh":"厨房有股怪气味。","pinyin":"Chúfáng yǒu gǔ guài qìwèi.","vi":"Trong bếp có mùi lạ."},{"type":"simple","zh":"雨后的森林里弥漫着泥土的气味。","pinyin":"Yǔ hòu de sēnlín lǐ mímànzhe nítǔ de qìwèi.","vi":"Khu rừng sau mưa thoang thoảng mùi đất."},{"type":"compound","zh":"一闻到消毒水的气味，我就想起了住院的日子。","pinyin":"Yì wéndào xiāodú shuǐ de qìwèi, wǒ jiù xiǎngqǐle zhùyuàn de rìzi.","vi":"Hễ ngửi thấy mùi nước sát trùng, tôi lại nhớ về những ngày nằm viện."}],"related":[{"hanzi":"味道","pinyin":"wèidao","vi":"mùi vị"},{"hanzi":"香味","pinyin":"xiāngwèi","vi":"mùi thơm"},{"hanzi":"臭味","pinyin":"chòuwèi","vi":"mùi hôi"},{"hanzi":"气味相投","pinyin":"qìwèixiāngtóu","vi":"hợp tính nhau"}],"traditional":"氣味"},{"id":"气象万千","hanzi":"气象万千","pinyin":"qìxiàng-wànqiān","meaning_vi":"cảnh tượng biến hóa muôn hình vạn trạng hùng vĩ","explanation":"气象 (cảnh tượng) + 万千 (muôn nghìn) → cảnh sắc tráng lệ, biến hóa muôn vẻ. Gốc từ \"Nhạc Dương lâu ký\" của Phạm Trọng Yêm.","hsk_level":6,"tags":["thanh-ngu","thien-nhien"],"image":"🌄","examples":[{"type":"basic","zh":"黄山云海气象万千。","pinyin":"Huángshān yúnhǎi qìxiàngwànqiān.","vi":"Biển mây Hoàng Sơn muôn hình vạn trạng."},{"type":"simple","zh":"登上泰山之巅能看到气象万千的日出。","pinyin":"Dēngshàng Tàishān zhī diān néng kàndào qìxiàngwànqiān de rìchū.","vi":"Lên đến đỉnh Thái Sơn có thể ngắm cảnh bình minh muôn hình vạn trạng."},{"type":"compound","zh":"虽然只是一个小湖，但是一年四季气象万千。","pinyin":"Suīrán zhǐshì yí gè xiǎo hú, dànshì yì nián sìjì qìxiàngwànqiān.","vi":"Tuy chỉ là một hồ nhỏ, nhưng bốn mùa quanh năm cảnh sắc biến hóa muôn vẻ."}],"related":[{"hanzi":"千变万化","pinyin":"qiānbiànwànhuà","vi":"biến hóa khôn lường"},{"hanzi":"壮观","pinyin":"zhuàngguān","vi":"tráng lệ"},{"hanzi":"景象","pinyin":"jǐngxiàng","vi":"cảnh tượng"},{"hanzi":"蔚为壮观","pinyin":"wèiwéizhuàngguān","vi":"vô cùng tráng lệ"}],"traditional":"氣象萬千"},{"id":"庆幸","hanzi":"庆幸","pinyin":"qìngxìng","meaning_vi":"mừng thầm, lấy làm may mắn","explanation":"庆 (mừng) + 幸 (may).","hsk_level":6,"tags":["dong-tu","cam-xuc"],"image":"🍀","examples":[{"type":"basic","zh":"我很庆幸遇见了你。","pinyin":"Wǒ hěn qìngxìng yùjiànle nǐ.","vi":"Tôi rất may mắn vì đã gặp được bạn."},{"type":"simple","zh":"她暗自庆幸自己没有坐那班飞机。","pinyin":"Tā ànzì qìngxìng zìjǐ méiyǒu zuò nà bān fēijī.","vi":"Cô ấy thầm mừng vì mình đã không đi chuyến bay đó."},{"type":"compound","zh":"虽然车被撞坏了，但是他庆幸家人都平安无事。","pinyin":"Suīrán chē bèi zhuàng huàile, dànshì tā qìngxìng jiārén dōu píng'ān wú shì.","vi":"Tuy xe bị đâm hỏng, nhưng anh ấy mừng vì cả nhà đều bình an vô sự."}],"related":[{"hanzi":"幸运","pinyin":"xìngyùn","vi":"may mắn"},{"hanzi":"侥幸","pinyin":"jiǎoxìng","vi":"may mắn thoát"},{"hanzi":"幸亏","pinyin":"xìngkuī","vi":"may mà"},{"hanzi":"遗憾","pinyin":"yíhàn","vi":"tiếc nuối"}],"traditional":"慶幸"},{"id":"奇耻大辱","hanzi":"奇耻大辱","pinyin":"qíchǐ-dàrǔ","meaning_vi":"nỗi nhục nhã lớn lao","explanation":"奇耻 (nỗi nhục lạ thường) + 大辱 (nỗi nhục lớn) → mối nhục nhã cực lớn, khó rửa sạch.","hsk_level":6,"tags":["thanh-ngu"],"image":"😠","examples":[{"type":"basic","zh":"这是奇耻大辱！","pinyin":"Zhè shì qíchǐdàrǔ!","vi":"Đây là nỗi nhục lớn!"},{"type":"simple","zh":"球队主场惨败被球迷视为奇耻大辱。","pinyin":"Qiúduì zhǔchǎng cǎnbài bèi qiúmí shìwéi qíchǐdàrǔ.","vi":"Đội bóng thảm bại trên sân nhà bị người hâm mộ coi là nỗi nhục lớn."},{"type":"compound","zh":"因为当众被徒弟打败，所以他觉得这是奇耻大辱。","pinyin":"Yīnwèi dāngzhòng bèi túdì dǎbài, suǒyǐ tā juéde zhè shì qíchǐdàrǔ.","vi":"Vì bị chính đồ đệ đánh bại trước mặt mọi người nên ông ta thấy đây là nỗi nhục lớn."}],"related":[{"hanzi":"耻辱","pinyin":"chǐrǔ","vi":"nhục nhã"},{"hanzi":"侮辱","pinyin":"wǔrǔ","vi":"làm nhục"},{"hanzi":"屈辱","pinyin":"qūrǔ","vi":"khuất nhục"},{"hanzi":"荣耀","pinyin":"róngyào","vi":"vinh quang"}],"traditional":"奇恥大辱"},{"id":"旗鼓相当","hanzi":"旗鼓相当","pinyin":"qígǔ-xiāngdāng","meaning_vi":"kẻ tám lạng người nửa cân, ngang tài ngang sức","explanation":"Cờ và trống trận của hai quân ngang nhau → hai bên ngang tài ngang sức. Thường: 两队旗鼓相当.","hsk_level":6,"tags":["thanh-ngu"],"image":"⚖️","examples":[{"type":"basic","zh":"两队旗鼓相当。","pinyin":"Liǎng duì qígǔxiāngdāng.","vi":"Hai đội ngang tài ngang sức."},{"type":"simple","zh":"这场辩论赛的正反双方实力旗鼓相当。","pinyin":"Zhè chǎng biànlùnsài de zhèngfǎn shuāngfāng shílì qígǔxiāngdāng.","vi":"Hai phe tán thành và phản đối trong cuộc tranh biện này thực lực ngang ngửa."},{"type":"compound","zh":"因为两位棋手旗鼓相当，所以比赛一直下到深夜。","pinyin":"Yīnwèi liǎng wèi qíshǒu qígǔxiāngdāng, suǒyǐ bǐsài yìzhí xià dào shēnyè.","vi":"Vì hai kỳ thủ kẻ tám lạng người nửa cân nên ván đấu kéo dài đến tận đêm khuya."}],"related":[{"hanzi":"势均力敌","pinyin":"shìjūnlìdí","vi":"lực lượng ngang nhau"},{"hanzi":"不相上下","pinyin":"bùxiāngshàngxià","vi":"ngang ngửa"},{"hanzi":"悬殊","pinyin":"xuánshū","vi":"chênh lệch lớn"},{"hanzi":"难分高下","pinyin":"nánfēngāoxià","vi":"khó phân cao thấp"}],"traditional":"旗鼓相當"},{"id":"歧视","hanzi":"歧视","pinyin":"qíshì","meaning_vi":"kỳ thị, phân biệt đối xử","explanation":"歧 (rẽ nhánh/khác) + 视 (nhìn nhận).","hsk_level":6,"tags":["dong-tu","xa-hoi"],"image":"🚫","examples":[{"type":"basic","zh":"不要歧视残疾人。","pinyin":"Bú yào qíshì cánjírén.","vi":"Đừng phân biệt đối xử với người khuyết tật."},{"type":"simple","zh":"这家公司因为性别歧视被员工起诉了。","pinyin":"Zhè jiā gōngsī yīnwèi xìngbié qíshì bèi yuángōng qǐsù le.","vi":"Công ty này bị nhân viên kiện vì phân biệt giới tính."},{"type":"compound","zh":"即使他来自农村，你也不应该歧视他。","pinyin":"Jíshǐ tā láizì nóngcūn, nǐ yě bù yīnggāi qíshì tā.","vi":"Dù anh ấy đến từ nông thôn, bạn cũng không nên kỳ thị anh ấy."}],"related":[{"hanzi":"偏见","pinyin":"piānjiàn","vi":"định kiến"},{"hanzi":"种族歧视","pinyin":"zhǒngzúqíshì","vi":"phân biệt chủng tộc"},{"hanzi":"平等","pinyin":"píngděng","vi":"bình đẳng"},{"hanzi":"看不起","pinyin":"kànbuqǐ","vi":"coi thường"}],"traditional":"歧視"},{"id":"齐头并进","hanzi":"齐头并进","pinyin":"qítóu-bìngjìn","meaning_vi":"cùng nhau tiến bước song song","explanation":"Đầu ngang hàng cùng tiến → cùng tiến lên song song; nhiều việc được tiến hành đồng thời.","hsk_level":6,"tags":["thanh-ngu"],"image":"🤝","examples":[{"type":"basic","zh":"两个项目齐头并进。","pinyin":"Liǎng gè xiàngmù qítóubìngjìn.","vi":"Hai dự án tiến hành song song."},{"type":"simple","zh":"这座城市的经济和文化正在齐头并进。","pinyin":"Zhè zuò chéngshì de jīngjì hé wénhuà zhèngzài qítóubìngjìn.","vi":"Kinh tế và văn hóa của thành phố này đang cùng phát triển song song."},{"type":"compound","zh":"只有学习和锻炼齐头并进，身心才能健康成长。","pinyin":"Zhǐyǒu xuéxí hé duànliàn qítóubìngjìn, shēnxīn cáinéng jiànkāng chéngzhǎng.","vi":"Chỉ khi học tập và rèn luyện cùng song hành, thể chất và tinh thần mới phát triển khỏe mạnh."}],"related":[{"hanzi":"并驾齐驱","pinyin":"bìngjiàqíqū","vi":"sánh vai ngang hàng"},{"hanzi":"同步","pinyin":"tóngbù","vi":"đồng bộ"},{"hanzi":"齐心协力","pinyin":"qíxīnxiélì","vi":"đồng tâm hiệp lực"},{"hanzi":"并进","pinyin":"bìngjìn","vi":"cùng tiến"}],"traditional":"齊頭並進"},{"id":"齐心协力","hanzi":"齐心协力","pinyin":"qíxīn-xiélì","meaning_vi":"đồng tâm hiệp lực","explanation":"齐心 (cùng lòng) + 协力 (góp sức). Thành ngữ.","hsk_level":6,"tags":["thanh-ngu"],"image":"🤝","examples":[{"type":"basic","zh":"大家齐心协力吧！","pinyin":"Dàjiā qíxīnxiélì ba!","vi":"Mọi người hãy đồng tâm hiệp lực nhé!"},{"type":"simple","zh":"村民们齐心协力修好了被洪水冲毁的桥。","pinyin":"Cūnmínmen qíxīnxiélì xiūhǎole bèi hóngshuǐ chōng huǐ de qiáo.","vi":"Dân làng đồng tâm hiệp lực sửa xong cây cầu bị lũ cuốn hỏng."},{"type":"compound","zh":"只要全家人齐心协力，就没有过不去的难关。","pinyin":"Zhǐyào quán jiārén qíxīnxiélì, jiù méiyǒu guòbúqù de nánguān.","vi":"Chỉ cần cả nhà đồng lòng hợp sức thì không có cửa ải nào không vượt qua được."}],"related":[{"hanzi":"同心协力","pinyin":"tóngxīnxiélì","vi":"đồng lòng hợp sức"},{"hanzi":"团结一致","pinyin":"tuánjiéyízhì","vi":"đoàn kết nhất trí"},{"hanzi":"众志成城","pinyin":"zhòngzhìchéngchéng","vi":"đồng lòng như thành đồng"},{"hanzi":"各自为政","pinyin":"gèzìwéizhèng","vi":"ai làm việc nấy"}],"traditional":"齊心協力"},{"id":"旗帜","hanzi":"旗帜","pinyin":"qízhì","meaning_vi":"lá cờ, ngọn cờ","explanation":"Cả hai chữ đều có bộ phương 方.","hsk_level":6,"tags":["danh-tu","xa-hoi"],"image":"🚩","examples":[{"type":"basic","zh":"旗帜在风中飘扬。","pinyin":"Qízhì zài fēng zhōng piāoyáng.","vi":"Lá cờ tung bay trong gió."},{"type":"simple","zh":"运动员们举着各国的旗帜走进了体育场。","pinyin":"Yùndòngyuánmen jǔzhe gèguó de qízhì zǒujìnle tǐyùchǎng.","vi":"Các vận động viên cầm cờ các nước tiến vào sân vận động."},{"type":"compound","zh":"他不但是公司的创始人，而且是行业改革的一面旗帜。","pinyin":"Tā bú dànshì gōngsī de chuàngshǐrén, érqiě shì hángyè gǎigé de yímiàn qízhì.","vi":"Ông ấy không chỉ là người sáng lập công ty mà còn là ngọn cờ đầu của cải cách ngành."}],"related":[{"hanzi":"旗子","pinyin":"qízi","vi":"lá cờ"},{"hanzi":"国旗","pinyin":"guóqí","vi":"quốc kỳ"},{"hanzi":"旗帜鲜明","pinyin":"qízhìxiānmíng","vi":"lập trường rõ ràng"},{"hanzi":"飘扬","pinyin":"piāoyáng","vi":"tung bay"}],"traditional":"旗幟"},{"id":"勤恳","hanzi":"勤恳","pinyin":"qínkěn","meaning_vi":"cần cù tận tụy","explanation":"勤 + 恳 (chân thành).","hsk_level":6,"tags":["tinh-tu","cong-viec"],"image":"🐝","examples":[{"type":"basic","zh":"她做事勤恳踏实。","pinyin":"Tā zuòshì qínkěn tāshi.","vi":"Cô ấy làm việc cần cù chắc chắn."},{"type":"simple","zh":"这位勤恳的老会计在公司干了三十年。","pinyin":"Zhè wèi qínkěn de lǎo kuàijì zài gōngsī gànle sānshí nián.","vi":"Vị kế toán già cần mẫn này đã làm ở công ty ba mươi năm."},{"type":"compound","zh":"因为他工作勤恳，所以很快就被提拔为组长。","pinyin":"Yīnwèi tā gōngzuò qínkěn, suǒyǐ hěn kuài jiù bèi tíbá wéi zǔzhǎng.","vi":"Vì làm việc cần cù tận tụy nên anh ấy nhanh chóng được đề bạt làm tổ trưởng."}],"related":[{"hanzi":"勤劳","pinyin":"qínláo","vi":"cần cù"},{"hanzi":"勤奋","pinyin":"qínfèn","vi":"chăm chỉ"},{"hanzi":"兢兢业业","pinyin":"jīngjīngyèyè","vi":"tận tụy cẩn trọng"},{"hanzi":"懒惰","pinyin":"lǎnduò","vi":"lười biếng"}],"traditional":"勤懇"},{"id":"琴棋书画","hanzi":"琴棋书画","pinyin":"qínqí-shūhuà","meaning_vi":"cầm kỳ thi họa (bốn thú vui tao nhã xưa)","explanation":"琴 (cầm – đàn) + 棋 (kỳ – cờ) + 书 (thư – thư pháp) + 画 (họa – tranh) → bốn thú nghệ thuật tao nhã của văn nhân xưa; khen người đa tài.","hsk_level":6,"tags":["thanh-ngu","van-hoa"],"image":"🎨","examples":[{"type":"basic","zh":"她精通琴棋书画。","pinyin":"Tā jīngtōng qínqíshūhuà.","vi":"Cô ấy tinh thông cầm kỳ thi họa."},{"type":"simple","zh":"古代的大家闺秀从小就要学习琴棋书画。","pinyin":"Gǔdài de dàjiā guīxiù cóngxiǎo jiùyào xuéxí qínqíshūhuà.","vi":"Các tiểu thư khuê các thời xưa từ nhỏ đã phải học cầm kỳ thi họa."},{"type":"compound","zh":"他虽然是个商人，但是对琴棋书画样样都很在行。","pinyin":"Tā suīrán shì gè shāngrén, dànshì duì qínqíshūhuà yàngyàng dōu hěn zài háng.","vi":"Ông ấy tuy là thương nhân, nhưng món nào trong cầm kỳ thi họa cũng rất thạo."}],"related":[{"hanzi":"书法","pinyin":"shūfǎ","vi":"thư pháp"},{"hanzi":"绘画","pinyin":"huìhuà","vi":"hội họa"},{"hanzi":"围棋","pinyin":"wéiqí","vi":"cờ vây"},{"hanzi":"多才多艺","pinyin":"duōcáiduōyì","vi":"đa tài đa nghệ"}],"traditional":"琴棋書畫"},{"id":"情不自禁","hanzi":"情不自禁","pinyin":"qíngbú-zìjīn","meaning_vi":"không kìm lòng được, bất giác","explanation":"情 (tình cảm) 不 (không) 自禁 (tự cấm – tự kìm) → tình cảm dâng trào không tự kìm được, bất giác. Ví dụ: 情不自禁地笑了.","hsk_level":6,"tags":["thanh-ngu","cam-xuc"],"image":"🥹","examples":[{"type":"basic","zh":"她情不自禁地哭了。","pinyin":"Tā qíngbúzìjīn de kū le.","vi":"Cô ấy không kìm được mà bật khóc."},{"type":"simple","zh":"听到熟悉的旋律他情不自禁地跟着哼唱。","pinyin":"Tīngdào shúxī de xuánlǜ tā qíngbúzìjīn de gēnzhe hēngchàng.","vi":"Nghe thấy giai điệu quen thuộc, anh ấy bất giác ngân nga hát theo."},{"type":"compound","zh":"一看到海边的日落，她就情不自禁地拿出了相机。","pinyin":"Yí kàndào hǎibiān de rìluò, tā jiù qíngbúzìjīn de náchūle xiàngjī.","vi":"Vừa nhìn thấy hoàng hôn bên biển, cô ấy liền không kìm được mà lấy máy ảnh ra."}],"related":[{"hanzi":"不由自主","pinyin":"bùyóuzìzhǔ","vi":"bất giác"},{"hanzi":"忍不住","pinyin":"rěnbuzhù","vi":"không nhịn được"},{"hanzi":"身不由己","pinyin":"shēnbùyóujǐ","vi":"thân bất do kỷ"},{"hanzi":"克制","pinyin":"kèzhì","vi":"kiềm chế"}]},{"id":"晴天霹雳","hanzi":"晴天霹雳","pinyin":"qíngtiān-pīlì","meaning_vi":"sét đánh ngang tai (tin dữ bất ngờ)","explanation":"Sét đánh giữa trời quang → tin dữ hay biến cố ập đến bất ngờ. Thường: 这个消息如晴天霹雳.","hsk_level":6,"tags":["thanh-ngu"],"image":"⚡","examples":[{"type":"basic","zh":"这消息如晴天霹雳。","pinyin":"Zhè xiāoxi rú qíngtiānpīlì.","vi":"Tin này như sét đánh ngang tai."},{"type":"simple","zh":"父亲病重的消息对她来说犹如晴天霹雳。","pinyin":"Fùqīn bìngzhòng de xiāoxi duì tā lái shuō yóurú qíngtiānpīlì.","vi":"Tin bố bệnh nặng đối với cô ấy như sét đánh ngang tai."},{"type":"compound","zh":"他刚升职不久，公司倒闭的消息就像晴天霹雳一样传来。","pinyin":"Tā gāng shēngzhí bùjiǔ, gōngsī dǎobì de xiāoxi jiù xiàng qíngtiānpīlì yíyàng chuánlái.","vi":"Anh ấy vừa được thăng chức chưa lâu thì tin công ty phá sản ập đến như sét đánh ngang tai."}],"related":[{"hanzi":"噩耗","pinyin":"èhào","vi":"tin dữ"},{"hanzi":"出乎意料","pinyin":"chūhūyìliào","vi":"ngoài dự đoán"},{"hanzi":"震惊","pinyin":"zhènjīng","vi":"chấn động"},{"hanzi":"突如其来","pinyin":"tūrúqílái","vi":"đột ngột ập đến"}],"traditional":"晴天霹靂"},{"id":"情形","hanzi":"情形","pinyin":"qíngxing","meaning_vi":"tình hình, tình cảnh","explanation":"情 + 形 (hình thái).","hsk_level":6,"tags":["danh-tu"],"image":"📊","examples":[{"type":"basic","zh":"当时的情形很危急。","pinyin":"Dāngshí de qíngxing hěn wēijí.","vi":"Tình hình lúc đó rất nguy cấp."},{"type":"simple","zh":"他向警察详细描述了事故发生时的情形。","pinyin":"Tā xiàng jǐngchá xiángxì miáoshùle shìgù fāshēng shí de qíngxing.","vi":"Anh ấy mô tả chi tiết với cảnh sát tình cảnh lúc xảy ra tai nạn."},{"type":"compound","zh":"如果遇到这种情形，你就马上打电话给我。","pinyin":"Rúguǒ yùdào zhè zhǒng qíngxing, nǐ jiù mǎshàng dǎdiànhuà gěi wǒ.","vi":"Nếu gặp tình huống như thế này, bạn hãy gọi điện cho tôi ngay."}],"related":[{"hanzi":"情况","pinyin":"qíngkuàng","vi":"tình huống"},{"hanzi":"情景","pinyin":"qíngjǐng","vi":"tình cảnh"},{"hanzi":"状况","pinyin":"zhuàngkuàng","vi":"trạng thái"},{"hanzi":"局面","pinyin":"júmiàn","vi":"cục diện"}]},{"id":"群策群力","hanzi":"群策群力","pinyin":"qúncè-qúnlì","meaning_vi":"góp trí góp sức tập thể","explanation":"群策 (mọi người góp kế) + 群力 (mọi người góp sức) → tập thể cùng góp trí góp sức làm việc.","hsk_level":6,"tags":["thanh-ngu"],"image":"🤝","examples":[{"type":"basic","zh":"我们要群策群力。","pinyin":"Wǒmen yào qúncèqúnlì.","vi":"Chúng ta phải góp trí góp sức."},{"type":"simple","zh":"全村群策群力想出了治理污水的办法。","pinyin":"Quán cūn qúncèqúnlì xiǎngchūle zhìlǐ wūshuǐ de bànfǎ.","vi":"Cả làng cùng góp trí góp sức nghĩ ra cách xử lý nước thải."},{"type":"compound","zh":"只要大家群策群力，这个难题就一定能解决。","pinyin":"Zhǐyào dàjiā qúncèqúnlì, zhè ge nántí jiù yídìng néng jiějué.","vi":"Chỉ cần mọi người cùng góp trí góp sức, vấn đề khó này nhất định sẽ được giải quyết."}],"related":[{"hanzi":"集思广益","pinyin":"jísīguǎngyì","vi":"tập hợp trí tuệ tập thể"},{"hanzi":"齐心协力","pinyin":"qíxīnxiélì","vi":"đồng tâm hiệp lực"},{"hanzi":"众人拾柴火焰高","pinyin":"zhòngrén shí chái huǒyàn gāo","vi":"đông tay vỗ nên kêu"},{"hanzi":"独断专行","pinyin":"dúduànzhuānxíng","vi":"độc đoán"}]},{"id":"欺负","hanzi":"欺负","pinyin":"qīfu","meaning_vi":"bắt nạt","explanation":"欺 (lừa/hiếp) + 负.","hsk_level":6,"tags":["dong-tu","giao-tiep"],"image":"😠","examples":[{"type":"basic","zh":"别欺负小同学。","pinyin":"Bié qīfu xiǎo tóngxué.","vi":"Đừng bắt nạt bạn nhỏ."},{"type":"simple","zh":"那个高个子男生总在放学路上欺负弟弟。","pinyin":"Nà ge gāogèzi nánshēng zǒng zài fàngxué lùshang qīfu dìdi.","vi":"Cậu con trai cao kều đó lúc nào cũng bắt nạt em trai tôi trên đường tan học."},{"type":"compound","zh":"如果有人欺负你，你就要马上告诉老师。","pinyin":"Rúguǒ yǒurén qīfu nǐ, nǐ jiùyào mǎshàng gàosu lǎoshī.","vi":"Nếu có ai bắt nạt con, con phải báo ngay cho cô giáo."}],"related":[{"hanzi":"欺侮","pinyin":"qīwǔ","vi":"ức hiếp"},{"hanzi":"欺凌","pinyin":"qīlíng","vi":"bắt nạt"},{"hanzi":"恃强凌弱","pinyin":"shìqiánglíngruò","vi":"cậy mạnh hiếp yếu"},{"hanzi":"保护","pinyin":"bǎohù","vi":"bảo vệ"}],"traditional":"欺負"},{"id":"欺瞒","hanzi":"欺瞒","pinyin":"qīmán","meaning_vi":"lừa dối, giấu giếm","explanation":"欺 (lừa) + 瞒 (che giấu).","hsk_level":6,"tags":["dong-tu"],"image":"🤥","examples":[{"type":"basic","zh":"他欺瞒了所有人。","pinyin":"Tā qīmánle suǒyǒurén.","vi":"Anh ta đã lừa dối tất cả mọi người."},{"type":"simple","zh":"这家企业长期欺瞒消费者使用过期原料。","pinyin":"Zhè jiā qǐyè chángqī qīmán xiāofèizhě shǐyòng guòqī yuánliào.","vi":"Doanh nghiệp này trong thời gian dài giấu giếm người tiêu dùng việc sử dụng nguyên liệu hết hạn."},{"type":"compound","zh":"即使真相很残酷，你也不应该欺瞒病人的家属。","pinyin":"Jíshǐ zhēnxiàng hěn cánkù, nǐ yě bù yīnggāi qīmán bìngrén de jiāshǔ.","vi":"Dù sự thật có tàn nhẫn đến đâu, bạn cũng không nên giấu giếm người nhà bệnh nhân."}],"related":[{"hanzi":"欺骗","pinyin":"qīpiàn","vi":"lừa gạt"},{"hanzi":"隐瞒","pinyin":"yǐnmán","vi":"giấu giếm"},{"hanzi":"蒙骗","pinyin":"méngpiàn","vi":"lừa bịp"},{"hanzi":"坦诚","pinyin":"tǎnchéng","vi":"thẳng thắn"}],"traditional":"欺瞞"},{"id":"七嘴八舌","hanzi":"七嘴八舌","pinyin":"qīzuǐ-bāshé","meaning_vi":"bảy mồm tám lưỡi (mọi người bàn tán xôn xao)","explanation":"Bảy miệng tám lưỡi → nhiều người tranh nhau nói, bàn tán xôn xao. Thường: 大家七嘴八舌地议论.","hsk_level":6,"tags":["thanh-ngu"],"image":"🗣️","examples":[{"type":"basic","zh":"大家七嘴八舌地议论。","pinyin":"Dàjiā qīzuǐbāshé de yìlùn.","vi":"Mọi người xôn xao bàn tán."},{"type":"simple","zh":"记者们七嘴八舌地向球星提问。","pinyin":"Jìzhěmen qīzuǐbāshé de xiàng qiúxīng tíwèn.","vi":"Các phóng viên nhao nhao đặt câu hỏi cho ngôi sao bóng đá."},{"type":"compound","zh":"老师刚宣布要去春游，同学们就七嘴八舌地讨论起来。","pinyin":"Lǎoshī gāng xuānbù yào qù chūnyóu, tóngxuémen jiù qīzuǐbāshé de tǎolùn qǐlái.","vi":"Cô giáo vừa thông báo đi dã ngoại mùa xuân, học sinh liền nhao nhao bàn tán."}],"related":[{"hanzi":"众说纷纭","pinyin":"zhòngshuōfēnyún","vi":"mỗi người một ý"},{"hanzi":"议论纷纷","pinyin":"yìlùnfēnfēn","vi":"bàn tán xôn xao"},{"hanzi":"各抒己见","pinyin":"gèshūjǐjiàn","vi":"mỗi người bày tỏ ý kiến"},{"hanzi":"鸦雀无声","pinyin":"yāquèwúshēng","vi":"im phăng phắc"}]},{"id":"侵犯","hanzi":"侵犯","pinyin":"qīnfàn","meaning_vi":"xâm phạm (quyền lợi/lãnh thổ)","explanation":"侵 (xâm lấn) + 犯 (phạm).","hsk_level":6,"tags":["dong-tu","phap-luat"],"image":"🚫","examples":[{"type":"basic","zh":"这侵犯了我的隐私。","pinyin":"Zhè qīnfànle wǒ de yǐnsī.","vi":"Việc này xâm phạm quyền riêng tư của tôi."},{"type":"simple","zh":"那家网站未经授权使用照片侵犯了版权。","pinyin":"Nà jiā wǎngzhàn wèijīng shòuquán shǐyòng zhàopiàn qīnfànle bǎnquán.","vi":"Trang web đó sử dụng ảnh khi chưa được cho phép đã xâm phạm bản quyền."},{"type":"compound","zh":"只要有人侵犯我们的领土，我们就坚决反击。","pinyin":"Zhǐyào yǒurén qīnfàn wǒmen de lǐngtǔ, wǒmen jiù jiānjué fǎnjī.","vi":"Hễ có kẻ xâm phạm lãnh thổ của chúng ta, chúng ta sẽ kiên quyết đánh trả."}],"related":[{"hanzi":"侵害","pinyin":"qīnhài","vi":"xâm hại"},{"hanzi":"侵略","pinyin":"qīnlüè","vi":"xâm lược"},{"hanzi":"侵权","pinyin":"qīnquán","vi":"xâm phạm quyền"},{"hanzi":"保护","pinyin":"bǎohù","vi":"bảo vệ"}]},{"id":"亲密","hanzi":"亲密","pinyin":"qīnmì","meaning_vi":"thân mật, gắn bó khăng khít","explanation":"亲 (thân) + 密 (gần gũi).","hsk_level":6,"tags":["tinh-tu","giao-tiep"],"image":"🤗","examples":[{"type":"basic","zh":"她俩关系很亲密。","pinyin":"Tā liǎ guānxì hěn qīnmì.","vi":"Hai cô ấy rất thân thiết."},{"type":"simple","zh":"照片上的两个小姑娘亲密地搂在一起。","pinyin":"Zhàopiàn shang de liǎng gè xiǎo gūniang qīnmì de lǒu zài yìqǐ.","vi":"Hai cô bé trong ảnh ôm nhau thân thiết."},{"type":"compound","zh":"我们虽然是同事，但是私下里像亲密的家人一样。","pinyin":"Wǒmen suīrán shì tóngshì, dànshì sīxià lǐ xiàng qīnmì de jiārén yíyàng.","vi":"Chúng tôi tuy là đồng nghiệp, nhưng ngoài giờ làm thân thiết như người một nhà."}],"related":[{"hanzi":"密切","pinyin":"mìqiè","vi":"mật thiết"},{"hanzi":"亲近","pinyin":"qīnjìn","vi":"gần gũi"},{"hanzi":"疏远","pinyin":"shūyuǎn","vi":"xa cách"},{"hanzi":"亲密无间","pinyin":"qīnmìwújiàn","vi":"thân thiết khăng khít"}],"traditional":"親密"},{"id":"亲身","hanzi":"亲身","pinyin":"qīnshēn","meaning_vi":"tự thân, đích thân trải nghiệm","explanation":"亲 + 身 (bản thân).","hsk_level":6,"tags":["pho-tu"],"image":"🙋","examples":[{"type":"basic","zh":"这是我亲身经历的事。","pinyin":"Zhè shì wǒ qīnshēn jīnglì de shì.","vi":"Đây là chuyện tôi đích thân trải qua."},{"type":"simple","zh":"志愿者们亲身体验了山区孩子的上学路。","pinyin":"Zhìyuànzhěmen qīnshēn tǐyànle shānqū háizi de shàngxué lù.","vi":"Các tình nguyện viên tự mình trải nghiệm con đường đến trường của trẻ em vùng núi."},{"type":"compound","zh":"只有亲身去过那里，你才能体会到当地人的热情。","pinyin":"Zhǐyǒu qīnshēn qùguo nàlǐ, nǐ cáinéng tǐhuì dào dāngdìrén de rèqíng.","vi":"Chỉ khi tự mình đến đó, bạn mới cảm nhận được sự nhiệt tình của người dân địa phương."}],"related":[{"hanzi":"亲自","pinyin":"qīnzì","vi":"đích thân"},{"hanzi":"亲身经历","pinyin":"qīnshēnjīnglì","vi":"trải nghiệm bản thân"},{"hanzi":"亲眼","pinyin":"qīnyǎn","vi":"tận mắt"},{"hanzi":"体验","pinyin":"tǐyàn","vi":"trải nghiệm"}],"traditional":"親身"},{"id":"清晨","hanzi":"清晨","pinyin":"qīngchén","meaning_vi":"sáng sớm, tinh mơ","explanation":"清 + 晨 (buổi sáng).","hsk_level":6,"tags":["danh-tu","thoi-gian"],"image":"🌅","examples":[{"type":"basic","zh":"清晨的空气很新鲜。","pinyin":"Qīngchén de kōngqì hěn xīnxiān.","vi":"Không khí buổi sớm rất trong lành."},{"type":"simple","zh":"每天清晨他都会沿着湖边跑五公里。","pinyin":"Měitiān qīngchén tā dōuhuì yánzhe húbiān pǎo wǔ gōnglǐ.","vi":"Mỗi sáng sớm anh ấy đều chạy năm cây số dọc bờ hồ."},{"type":"compound","zh":"清晨一到，市场里就挤满了买菜的老人。","pinyin":"Qīngchén yí dào, shìchǎng lǐ jiù jǐmǎnle mǎicài de lǎorén.","vi":"Trời vừa sáng, chợ đã chật kín những cụ già đi mua thức ăn."}],"related":[{"hanzi":"早晨","pinyin":"zǎochen","vi":"buổi sáng"},{"hanzi":"黎明","pinyin":"límíng","vi":"bình minh"},{"hanzi":"傍晚","pinyin":"bàngwǎn","vi":"chiều tối"},{"hanzi":"拂晓","pinyin":"fúxiǎo","vi":"rạng sáng"}]},{"id":"青出于蓝","hanzi":"青出于蓝","pinyin":"qīngchū-yúlán","meaning_vi":"trò giỏi hơn thầy (xanh lam từ cây chàm mà ra nhưng xanh hơn)","explanation":"Màu xanh lấy từ cây chàm mà xanh hơn chàm (Tuân Tử \"Khuyến học\") → trò giỏi hơn thầy, lớp sau hơn lớp trước. Đầy đủ: 青出于蓝而胜于蓝.","hsk_level":6,"tags":["thanh-ngu","hoc-tap"],"image":"🎓","examples":[{"type":"basic","zh":"他真是青出于蓝啊！","pinyin":"Tā zhēn shì qīngchūyúlán a!","vi":"Cậu ấy đúng là trò giỏi hơn thầy!"},{"type":"simple","zh":"这位年轻棋手的表现可谓青出于蓝而胜于蓝。","pinyin":"Zhè wèi niánqīng qíshǒu de biǎoxiàn kěwèi qīngchūyúlán ér shèng yú lán.","vi":"Phần thể hiện của kỳ thủ trẻ này có thể nói là trò giỏi hơn thầy."},{"type":"compound","zh":"老师不但不嫉妒，反而为学生的青出于蓝感到骄傲。","pinyin":"Lǎoshī búdàn bù jídù, fǎn'ér wèi xuésheng de qīngchūyúlán gǎndào jiāo'ào.","vi":"Thầy giáo không những không ghen tị mà còn tự hào vì trò giỏi hơn thầy."}],"related":[{"hanzi":"后来居上","pinyin":"hòuláijūshàng","vi":"người đến sau vượt lên"},{"hanzi":"后起之秀","pinyin":"hòuqǐzhīxiù","vi":"tài năng trẻ"},{"hanzi":"长江后浪推前浪","pinyin":"Chángjiāng Hòu Làng Tuī Qián Làng","vi":"sóng sau xô sóng trước"},{"hanzi":"学生","pinyin":"xuésheng","vi":"học trò"}],"traditional":"青出於藍"},{"id":"青睐","hanzi":"青睐","pinyin":"qīnglài","meaning_vi":"ưu ái, để mắt tới, yêu thích","explanation":"青 + 睐 (liếc nhìn).","hsk_level":6,"tags":["dong-tu","danh-tu"],"image":"🌟","examples":[{"type":"basic","zh":"这款车很受青睐。","pinyin":"Zhè kuǎn chē hěn shòu qīnglài.","vi":"Mẫu xe này rất được ưa chuộng."},{"type":"simple","zh":"她的设计作品赢得了评委们的青睐。","pinyin":"Tā de shèjì zuòpǐn yíng déle píngwěimen de qīnglài.","vi":"Tác phẩm thiết kế của cô ấy đã nhận được sự ưu ái của ban giám khảo."},{"type":"compound","zh":"因为价格实惠，所以这家民宿备受年轻游客青睐。","pinyin":"Yīnwèi jiàgé shíhuì, suǒyǐ zhè jiā mínsù bèishòu niánqīng yóukè qīnglài.","vi":"Vì giá cả phải chăng nên homestay này rất được du khách trẻ ưa chuộng."}],"related":[{"hanzi":"喜爱","pinyin":"xǐ'ài","vi":"yêu thích"},{"hanzi":"欢迎","pinyin":"huānyíng","vi":"hoan nghênh"},{"hanzi":"垂青","pinyin":"chuíqīng","vi":"ưu ái"},{"hanzi":"冷落","pinyin":"lěngluò","vi":"lạnh nhạt"}],"traditional":"青睞"},{"id":"清理","hanzi":"清理","pinyin":"qīnglǐ","meaning_vi":"dọn dẹp, thanh lý","explanation":"清 + 理 (sắp xếp).","hsk_level":6,"tags":["dong-tu"],"image":"🧹","examples":[{"type":"basic","zh":"我要清理一下房间。","pinyin":"Wǒ yào qīnglǐ yíxià fángjiān.","vi":"Tôi cần dọn dẹp phòng một chút."},{"type":"simple","zh":"环卫工人一大早就清理了街上的积雪。","pinyin":"Huánwèigōng rén yídàzǎo jiù qīnglǐle jiēshang de jīxuě.","vi":"Công nhân vệ sinh từ sáng sớm đã dọn sạch tuyết đọng trên phố."},{"type":"compound","zh":"如果不定期清理手机缓存，手机就会越来越卡。","pinyin":"Rúguǒ bú dìngqī qīnglǐ shǒujī huǎncún, shǒujī jiù huì yuèláiyuè kǎ.","vi":"Nếu không dọn bộ nhớ đệm định kỳ, điện thoại sẽ ngày càng giật lag."}],"related":[{"hanzi":"整理","pinyin":"zhěnglǐ","vi":"sắp xếp"},{"hanzi":"打扫","pinyin":"dǎsǎo","vi":"quét dọn"},{"hanzi":"清除","pinyin":"qīngchú","vi":"dọn sạch"},{"hanzi":"清洁","pinyin":"qīngjié","vi":"vệ sinh"}]},{"id":"轻描淡写","hanzi":"轻描淡写","pinyin":"qīngmiáo-dànxiě","meaning_vi":"nhắc qua loa nhẹ nhàng (không đi sâu)","explanation":"Vẽ nét nhẹ, tô màu nhạt → nói hoặc viết qua loa, nhẹ nhàng lướt qua điều quan trọng.","hsk_level":6,"tags":["thanh-ngu"],"image":"🖌️","examples":[{"type":"basic","zh":"他轻描淡写地带过了。","pinyin":"Tā qīngmiáodànxiě de dàiguò le.","vi":"Anh ấy nhắc qua loa cho xong."},{"type":"simple","zh":"她轻描淡写地讲起了当年创业的艰辛。","pinyin":"Tā qīngmiáodànxiě de jiǎng qǐle dāngnián chuàngyè de jiānxīn.","vi":"Cô ấy kể nhẹ nhàng về những gian khổ khi khởi nghiệp năm xưa."},{"type":"compound","zh":"事故明明很严重，可是报告里只是轻描淡写地提了一句。","pinyin":"Shìgù míngmíng hěn yánzhòng, kěshì bàogào lǐ zhǐshì qīngmiáodànxiě de tíle yíjù.","vi":"Sự cố rõ ràng rất nghiêm trọng, nhưng trong báo cáo chỉ nhắc qua loa một câu."}],"related":[{"hanzi":"避重就轻","pinyin":"bìzhòngjiùqīng","vi":"tránh nặng tìm nhẹ"},{"hanzi":"一笔带过","pinyin":"yìbǐdàiguò","vi":"lướt qua"},{"hanzi":"浓墨重彩","pinyin":"nóngmòzhòngcǎi","vi":"tô đậm nhấn mạnh"},{"hanzi":"轻松","pinyin":"qīngsōng","vi":"nhẹ nhàng"}],"traditional":"輕描淡寫"},{"id":"倾盆大雨","hanzi":"倾盆大雨","pinyin":"qīngpén-dàyǔ","meaning_vi":"mưa như trút nước","explanation":"倾盆 (dốc ngược chậu) + 大雨 (mưa to) → mưa như trút nước. Thường: 下起了倾盆大雨.","hsk_level":6,"tags":["thanh-ngu","thoi-tiet"],"image":"🌧️","examples":[{"type":"basic","zh":"外面下着倾盆大雨。","pinyin":"Wàimiàn xiàzhe qīngpéndàyǔ.","vi":"Bên ngoài đang mưa như trút nước."},{"type":"simple","zh":"一场倾盆大雨把整条街都淹了。","pinyin":"Yì cháng qīngpéndàyǔ bǎ zhěngtiáo jiē dōu yān le.","vi":"Trận mưa như trút nước làm ngập cả con phố."},{"type":"compound","zh":"我们刚走到山脚下，天空就下起了倾盆大雨。","pinyin":"Wǒmen gāng zǒu dào shān jiǎoxià, tiānkōng jiù xià qǐle qīngpéndàyǔ.","vi":"Chúng tôi vừa đi đến chân núi thì trời đổ mưa như trút nước."}],"related":[{"hanzi":"大雨","pinyin":"dàyǔ","vi":"mưa to"},{"hanzi":"暴雨","pinyin":"bàoyǔ","vi":"mưa rào lớn"},{"hanzi":"毛毛雨","pinyin":"máomaoyǔ","vi":"mưa phùn"},{"hanzi":"狂风暴雨","pinyin":"kuángfēngbàoyǔ","vi":"mưa to gió lớn"}],"traditional":"傾盆大雨"},{"id":"轻率","hanzi":"轻率","pinyin":"qīngshuài","meaning_vi":"khinh suất, vội vàng thiếu suy nghĩ","explanation":"轻 (nhẹ) + 率 (vội).","hsk_level":6,"tags":["tinh-tu"],"image":"🙈","examples":[{"type":"basic","zh":"别轻率地下结论。","pinyin":"Bié qīngshuài dexià jiélùn.","vi":"Đừng vội vàng kết luận."},{"type":"simple","zh":"他为自己轻率的决定付出了沉重的代价。","pinyin":"Tā wèi zìjǐ qīngshuài de juédìng fùchūle chénzhòng de dàijià.","vi":"Anh ấy đã phải trả giá đắt cho quyết định khinh suất của mình."},{"type":"compound","zh":"因为辞职太轻率，所以他现在连房租都付不起了。","pinyin":"Yīnwèi cízhí tài qīngshuài, suǒyǐ tā xiànzài lián fángzū dōu fùbùqǐ le.","vi":"Vì nghỉ việc quá khinh suất nên giờ anh ấy ngay cả tiền thuê nhà cũng không trả nổi."}],"related":[{"hanzi":"草率","pinyin":"cǎoshuài","vi":"qua loa"},{"hanzi":"鲁莽","pinyin":"lǔmǎng","vi":"lỗ mãng"},{"hanzi":"慎重","pinyin":"shènzhòng","vi":"thận trọng"},{"hanzi":"轻举妄动","pinyin":"qīngjǔwàngdòng","vi":"hành động thiếu suy nghĩ"}],"traditional":"輕率"},{"id":"倾听","hanzi":"倾听","pinyin":"qīngtīng","meaning_vi":"lắng nghe","explanation":"倾 (nghiêng tai) + 听 (nghe).","hsk_level":6,"tags":["dong-tu","giao-tiep"],"image":"👂","examples":[{"type":"basic","zh":"她在认真倾听。","pinyin":"Tā zài rènzhēn qīngtīng.","vi":"Cô ấy đang chăm chú lắng nghe."},{"type":"simple","zh":"好的医生会耐心倾听每一位病人的诉说。","pinyin":"Hǎo de yīshēng huì nàixīn qīngtīng měi yí wèi bìngrén de sùshuō.","vi":"Bác sĩ giỏi sẽ kiên nhẫn lắng nghe lời kể của từng bệnh nhân."},{"type":"compound","zh":"如果父母愿意倾听，孩子就会更愿意说出心里话。","pinyin":"Rúguǒ fùmǔ yuànyì qīngtīng, háizi jiù huì gèng yuànyì shuōchū xīnlǐhuà.","vi":"Nếu cha mẹ chịu lắng nghe, con cái sẽ sẵn lòng nói ra tâm sự hơn."}],"related":[{"hanzi":"聆听","pinyin":"língtīng","vi":"lắng nghe"},{"hanzi":"听取","pinyin":"tīngqǔ","vi":"nghe lấy"},{"hanzi":"洗耳恭听","pinyin":"xǐ'ěrgōngtīng","vi":"rửa tai lắng nghe"},{"hanzi":"倾诉","pinyin":"qīngsù","vi":"giãi bày"}],"traditional":"傾聽"},{"id":"清真","hanzi":"清真","pinyin":"qīngzhēn","meaning_vi":"Halal, (thuộc) Hồi giáo","explanation":"Ví dụ: 清真餐厅 (nhà hàng Hồi giáo).","hsk_level":6,"tags":["tinh-tu","van-hoa","an-uong"],"image":"🕌","examples":[{"type":"basic","zh":"这是一家清真餐厅。","pinyin":"Zhè shì yìjiā qīngzhēn cāntīng.","vi":"Đây là một nhà hàng Halal."},{"type":"simple","zh":"学校食堂专门为回族学生开设了清真窗口。","pinyin":"Xuéxiào shítáng zhuānmén wèi Huízú xuésheng kāishèle qīngzhēn chuāngkǒu.","vi":"Nhà ăn trường học mở riêng một quầy Halal cho học sinh dân tộc Hồi."},{"type":"compound","zh":"因为他是穆斯林，所以只吃清真食品。","pinyin":"Yīnwèi tā shì Mùsīlín, suǒyǐ zhǐ chī qīngzhēn shípǐn.","vi":"Vì anh ấy là người Hồi giáo nên chỉ ăn thực phẩm Halal."}],"related":[{"hanzi":"清真寺","pinyin":"qīngzhēnsì","vi":"nhà thờ Hồi giáo"},{"hanzi":"伊斯兰教","pinyin":"Yīsīlánjiào","vi":"đạo Hồi"},{"hanzi":"穆斯林","pinyin":"Mùsīlín","vi":"người Hồi giáo"},{"hanzi":"清真餐厅","pinyin":"qīngzhēncāntīng","vi":"nhà hàng Halal"}]},{"id":"轻而易举","hanzi":"轻而易举","pinyin":"qīng'ér-yìjǔ","meaning_vi":"dễ như trở bàn tay","explanation":"轻 (nhẹ) + 易举 (dễ nhấc lên) → nhẹ nhàng, dễ dàng làm được, dễ như trở bàn tay.","hsk_level":6,"tags":["thanh-ngu"],"image":"👌","examples":[{"type":"basic","zh":"这事轻而易举。","pinyin":"Zhè shì qīng'éryìjǔ.","vi":"Việc này dễ như trở bàn tay."},{"type":"simple","zh":"他轻而易举地举起了那袋五十斤的大米。","pinyin":"Tā qīng'éryìjǔ de jǔqǐle nà dài wǔshí jīn de dàmǐ.","vi":"Anh ấy dễ dàng nhấc bổng bao gạo 25 ký đó."},{"type":"compound","zh":"对专家来说轻而易举的事，对新手来说却很难。","pinyin":"Duì zhuānjiā lái shuō qīng'éryìjǔ de shì, duì xīnshǒu lái shuō què hěn nán.","vi":"Việc dễ như trở bàn tay đối với chuyên gia lại rất khó đối với người mới."}],"related":[{"hanzi":"易如反掌","pinyin":"yìrúfǎnzhǎng","vi":"dễ như trở bàn tay"},{"hanzi":"不费吹灰之力","pinyin":"bú fèi chuīhuīzhīlì","vi":"chẳng tốn chút sức"},{"hanzi":"举步维艰","pinyin":"jǔbùwéijiān","vi":"khó khăn từng bước"},{"hanzi":"容易","pinyin":"róngyì","vi":"dễ dàng"}],"traditional":"輕而易舉"},{"id":"驱逐","hanzi":"驱逐","pinyin":"qūzhú","meaning_vi":"trục xuất, xua đuổi","explanation":"驱 (đuổi) + 逐 (đuổi theo).","hsk_level":6,"tags":["dong-tu"],"image":"🚫","examples":[{"type":"basic","zh":"牧民用火把驱逐狼群。","pinyin":"Mù mínyòng huǒbǎ qūzhú láng qún.","vi":"Người chăn nuôi dùng đuốc xua đuổi bầy sói."},{"type":"simple","zh":"保安把闹事的球迷驱逐出了体育场。","pinyin":"Bǎo'ān bǎ nàoshì de qiúmí qūzhú chūle tǐyùchǎng.","vi":"Bảo vệ đuổi những cổ động viên gây rối ra khỏi sân vận động."},{"type":"compound","zh":"因为签证过期，所以这名游客被驱逐出境。","pinyin":"Yīnwèi qiānzhèng guòqī, suǒyǐ zhè míng yóukè bèi qūzhú chūjìng.","vi":"Vì visa hết hạn nên du khách này bị trục xuất khỏi đất nước."}],"related":[{"hanzi":"驱赶","pinyin":"qūgǎn","vi":"xua đuổi"},{"hanzi":"赶走","pinyin":"gǎnzǒu","vi":"đuổi đi"},{"hanzi":"驱逐出境","pinyin":"qūzhúchūjìng","vi":"trục xuất khỏi nước"},{"hanzi":"收留","pinyin":"shōuliú","vi":"thu nhận"}],"traditional":"驅逐"},{"id":"屈指可数","hanzi":"屈指可数","pinyin":"qūzhǐ-kěshǔ","meaning_vi":"đếm trên đầu ngón tay (rất ít)","explanation":"屈指 (gập ngón tay) + 可数 (đếm được). Thành ngữ.","hsk_level":6,"tags":["thanh-ngu","so-luong"],"image":"🖐️","examples":[{"type":"basic","zh":"这样的人屈指可数。","pinyin":"Zhèyàng de rén qūzhǐkěshǔ.","vi":"Người như thế chỉ đếm trên đầu ngón tay."},{"type":"simple","zh":"能获得这个奖项的华人作家屈指可数。","pinyin":"Néng huòdé zhè ge jiǎngxiàng de Huárén zuòjiā qūzhǐkěshǔ.","vi":"Nhà văn gốc Hoa giành được giải thưởng này chỉ đếm trên đầu ngón tay."},{"type":"compound","zh":"因为这种兰花非常稀有，所以野外的数量屈指可数。","pinyin":"Yīnwèi zhè zhǒng lánhuā fēicháng xīyǒu, suǒyǐ yěwài de shùliàng qūzhǐkěshǔ.","vi":"Vì loài lan này cực kỳ hiếm nên số lượng ngoài tự nhiên chỉ đếm trên đầu ngón tay."}],"related":[{"hanzi":"寥寥无几","pinyin":"liáoliáowújǐ","vi":"rất ít ỏi"},{"hanzi":"凤毛麟角","pinyin":"fèngmáolínjiǎo","vi":"hiếm như lông phượng"},{"hanzi":"不计其数","pinyin":"bújìqíshù","vi":"vô số"},{"hanzi":"数不胜数","pinyin":"shǔbúshèngshǔ","vi":"đếm không xuể"}],"traditional":"屈指可數"},{"id":"启程","hanzi":"启程","pinyin":"qǐchéng","meaning_vi":"khởi hành, lên đường","explanation":"启 (mở đầu) + 程 (hành trình).","hsk_level":6,"tags":["dong-tu","du-lich"],"image":"🛫","examples":[{"type":"basic","zh":"我们明天启程。","pinyin":"Wǒmen míngtiān qǐchéng.","vi":"Ngày mai chúng ta lên đường."},{"type":"simple","zh":"考察队凌晨五点从营地启程前往雪山。","pinyin":"Kǎocháduì língchén wǔ diǎn cóng yíngdì qǐchéng qiánwǎng xuěshān.","vi":"Đoàn khảo sát khởi hành từ doanh trại lúc năm giờ sáng tiến về núi tuyết."},{"type":"compound","zh":"如果明天天气好转，我们就按原计划启程。","pinyin":"Rúguǒ míngtiān tiānqì hǎozhuǎn, wǒmen jiù àn yuán jìhuà qǐchéng.","vi":"Nếu ngày mai thời tiết chuyển tốt, chúng ta sẽ khởi hành theo kế hoạch ban đầu."}],"related":[{"hanzi":"出发","pinyin":"chūfā","vi":"xuất phát"},{"hanzi":"动身","pinyin":"dòngshēn","vi":"lên đường"},{"hanzi":"起程","pinyin":"qǐchéng","vi":"khởi hành"},{"hanzi":"返程","pinyin":"fǎnchéng","vi":"chuyến về"}],"traditional":"啟程"},{"id":"起草","hanzi":"起草","pinyin":"qǐcǎo","meaning_vi":"khởi thảo, soạn thảo (văn bản)","explanation":"起 (bắt đầu) + 草 (bản nháp).","hsk_level":6,"tags":["dong-tu","cong-viec"],"image":"✍️","examples":[{"type":"basic","zh":"她在起草合同。","pinyin":"Tā zài qǐcǎo hétong.","vi":"Cô ấy đang soạn thảo hợp đồng."},{"type":"simple","zh":"秘书连夜为经理起草了一份演讲稿。","pinyin":"Mìshū liányè wèi jīnglǐ qǐcǎole yí fèn yǎnjiǎng gǎo.","vi":"Thư ký thức trắng đêm soạn cho giám đốc một bài diễn văn."},{"type":"compound","zh":"等你起草好合作方案，我们就马上开会讨论。","pinyin":"Děng nǐ qǐcǎo hǎo hézuò fāng'àn, wǒmen jiù mǎshàng kāihuì tǎolùn.","vi":"Đợi anh soạn thảo xong phương án hợp tác, chúng ta sẽ họp thảo luận ngay."}],"related":[{"hanzi":"草稿","pinyin":"cǎogǎo","vi":"bản nháp"},{"hanzi":"拟定","pinyin":"nǐdìng","vi":"soạn thảo"},{"hanzi":"撰写","pinyin":"zhuànxiě","vi":"viết"},{"hanzi":"定稿","pinyin":"dìnggǎo","vi":"bản cuối"}]},{"id":"启迪","hanzi":"启迪","pinyin":"qǐdí","meaning_vi":"khai sáng, gợi mở trí tuệ","explanation":"启 (mở) + 迪 (dẫn dắt).","hsk_level":6,"tags":["dong-tu","hoc-tap"],"image":"💡","examples":[{"type":"basic","zh":"这本书启迪了我。","pinyin":"Zhè běn shū qǐdíle wǒ.","vi":"Cuốn sách này đã khai sáng cho tôi."},{"type":"simple","zh":"老教授的一席话给了年轻人很大的启迪。","pinyin":"Lǎo jiàoshòu de yìxíhuà gěile niánqīngrén hěn dà de qǐdí.","vi":"Lời nói của vị giáo sư già đã gợi mở rất nhiều cho người trẻ."},{"type":"compound","zh":"好的童话不但有趣，而且能启迪孩子的智慧。","pinyin":"Hǎo de tónghuà búdàn yǒuqù, érqiě néng qǐdí háizi de zhìhuì.","vi":"Truyện cổ tích hay không những thú vị mà còn khai mở trí tuệ trẻ em."}],"related":[{"hanzi":"启发","pinyin":"qǐfā","vi":"gợi mở"},{"hanzi":"启蒙","pinyin":"qǐméng","vi":"khai sáng"},{"hanzi":"开导","pinyin":"kāidǎo","vi":"khuyên giải"},{"hanzi":"教诲","pinyin":"jiàohuì","vi":"dạy bảo"}],"traditional":"啟迪"},{"id":"起哄","hanzi":"起哄","pinyin":"qǐhòng","meaning_vi":"hò reo ầm ĩ, chế nhạo hùa theo","explanation":"起 + 哄 (ồn ào).","hsk_level":6,"tags":["dong-tu"],"image":"📢","examples":[{"type":"basic","zh":"大家别起哄了。","pinyin":"Dàjiā bié qǐhòng le.","vi":"Mọi người đừng hò reo ầm ĩ nữa."},{"type":"simple","zh":"同学们在婚礼上起哄让新郎唱歌。","pinyin":"Tóngxuémen zài hūnlǐ shang qǐhòng ràng xīnláng chànggē.","vi":"Bạn học ồn ào trêu chọc bắt chú rể hát trong đám cưới."},{"type":"compound","zh":"他一上台讲话，台下就有人开始起哄。","pinyin":"Tā yí shàngtái jiǎnghuà, táixià jiù yǒurén kāishǐ qǐhòng.","vi":"Anh ấy vừa lên sân khấu phát biểu, bên dưới đã có người bắt đầu la ó."}],"related":[{"hanzi":"哄笑","pinyin":"hōngxiào","vi":"cười ồ"},{"hanzi":"喝倒彩","pinyin":"hèdàocǎi","vi":"la ó chê bai"},{"hanzi":"闹事","pinyin":"nàoshì","vi":"gây chuyện"},{"hanzi":"捣乱","pinyin":"dǎoluàn","vi":"quấy rối"}],"traditional":"起鬨"},{"id":"启示","hanzi":"启示","pinyin":"qǐshì","meaning_vi":"điều gợi mở, bài học (rút ra); gợi mở, khai sáng","explanation":"启 + 示 (cho thấy).","hsk_level":6,"tags":["danh-tu","dong-tu"],"image":"💡","examples":[{"type":"basic","zh":"这件事给我很大启示。","pinyin":"Zhè jiàn shì gěi wǒ hěn dà qǐshì.","vi":"Việc này cho tôi bài học sâu sắc."},{"type":"simple","zh":"这次失败给创业者们带来了深刻的启示。","pinyin":"Zhè cì shībài gěi chuàngyèzhěmen dàiláile shēnkè de qǐshì.","vi":"Thất bại lần này mang lại bài học sâu sắc cho những người khởi nghiệp."},{"type":"compound","zh":"虽然故事很短，但是它给了读者不少人生启示。","pinyin":"Suīrán gùshi hěn duǎn, dànshì tā gěile dúzhě bùshǎo rénshēng qǐshì.","vi":"Tuy câu chuyện rất ngắn, nhưng nó mang lại cho người đọc không ít bài học cuộc sống."}],"related":[{"hanzi":"启发","pinyin":"qǐfā","vi":"gợi mở"},{"hanzi":"启迪","pinyin":"qǐdí","vi":"khai sáng"},{"hanzi":"教训","pinyin":"jiàoxùn","vi":"bài học"},{"hanzi":"感悟","pinyin":"gǎnwù","vi":"cảm ngộ"}],"traditional":"啟示"},{"id":"请教","hanzi":"请教","pinyin":"qǐngjiào","meaning_vi":"thỉnh giáo, xin chỉ bảo","explanation":"请 + 教 (dạy bảo).","hsk_level":6,"tags":["dong-tu","giao-tiep"],"image":"🙇","examples":[{"type":"basic","zh":"我想请教您一个问题。","pinyin":"Wǒ xiǎng qǐngjiào nín yí gè wèntí.","vi":"Tôi muốn thỉnh giáo ngài một câu hỏi."},{"type":"simple","zh":"他经常向退休的老工程师请教技术难题。","pinyin":"Tā jīngcháng xiàng tuìxiū de lǎo gōngchéngshī qǐngjiào jìshù nántí.","vi":"Anh ấy thường xin chỉ giáo kỹ sư già đã nghỉ hưu về các vấn đề kỹ thuật khó."},{"type":"compound","zh":"如果遇到不懂的地方，就要虚心向别人请教。","pinyin":"Rúguǒ yùdào bù dǒng de dìfang, jiùyào xūxīn xiàng biérén qǐngjiào.","vi":"Nếu gặp chỗ không hiểu thì phải khiêm tốn hỏi người khác."}],"related":[{"hanzi":"请问","pinyin":"qǐngwèn","vi":"xin hỏi"},{"hanzi":"指教","pinyin":"zhǐjiào","vi":"chỉ giáo"},{"hanzi":"求教","pinyin":"qiújiào","vi":"xin chỉ bảo"},{"hanzi":"不耻下问","pinyin":"bùchǐxiàwèn","vi":"không ngại hỏi người dưới"}],"traditional":"請教"},{"id":"取长补短","hanzi":"取长补短","pinyin":"qǔcháng-bǔduǎn","meaning_vi":"lấy điểm mạnh bù điểm yếu","explanation":"Lấy chỗ dài bù chỗ ngắn → học điểm mạnh của người để bù điểm yếu của mình. Thường: 互相取长补短.","hsk_level":6,"tags":["thanh-ngu"],"image":"⚖️","examples":[{"type":"basic","zh":"我们要取长补短。","pinyin":"Wǒmen yào qǔchángbǔduǎn.","vi":"Chúng ta phải lấy điểm mạnh bù điểm yếu."},{"type":"simple","zh":"两家医院通过交流学习实现了取长补短。","pinyin":"Liǎng jiā yīyuàn tōngguò jiāoliú xuéxí shíxiànle qǔchángbǔduǎn.","vi":"Hai bệnh viện qua giao lưu học hỏi đã bổ sung điểm mạnh yếu cho nhau."},{"type":"compound","zh":"只要队员之间取长补短，球队的整体实力就会提高。","pinyin":"Zhǐyào duìyuán zhījiān qǔchángbǔduǎn, qiúduì de zhěngtǐ shílì jiù huì tígāo.","vi":"Chỉ cần các cầu thủ bù trừ cho nhau, sức mạnh tổng thể của đội sẽ được nâng cao."}],"related":[{"hanzi":"扬长避短","pinyin":"yángchángbìduǎn","vi":"phát huy ưu điểm tránh nhược điểm"},{"hanzi":"互相学习","pinyin":"hùxiāngxuéxí","vi":"học hỏi lẫn nhau"},{"hanzi":"优点","pinyin":"yōudiǎn","vi":"ưu điểm"},{"hanzi":"缺点","pinyin":"quēdiǎn","vi":"khuyết điểm"}],"traditional":"取長補短"},{"id":"取缔","hanzi":"取缔","pinyin":"qǔdì","meaning_vi":"cấm đoán, đình chỉ hoạt động","explanation":"取 (thủ) + 缔 (đế – ràng buộc, ước thúc) → cơ quan nhà nước ra lệnh cấm, giải tán. Cụm: 取缔非法经营.","hsk_level":6,"tags":["dong-tu","phap-luat"],"image":"🚫","examples":[{"type":"basic","zh":"黑网吧被取缔了。","pinyin":"Hēi wǎngbā bèi qǔdì le.","vi":"Quán net lậu đã bị đóng cửa."},{"type":"simple","zh":"城管部门依法取缔了占道经营的摊位。","pinyin":"Chéngguǎn bùmén yīfǎ qǔdìle zhàn dào jīngyíng de tānwèi.","vi":"Cơ quan quản lý đô thị đã theo luật dẹp bỏ các sạp hàng lấn chiếm lòng đường."},{"type":"compound","zh":"因为这家工厂多次违法排污，所以被政府取缔了。","pinyin":"Yīnwèi zhè jiā gōngchǎng duōcì wéifǎ páiwū, suǒyǐ bèi zhèngfǔ qǔdì le.","vi":"Vì nhà máy này nhiều lần xả thải trái phép nên đã bị chính phủ đình chỉ hoạt động."}],"related":[{"hanzi":"禁止","pinyin":"jìnzhǐ","vi":"cấm"},{"hanzi":"查封","pinyin":"cháfēng","vi":"niêm phong"},{"hanzi":"打击","pinyin":"dǎjī","vi":"trấn áp"},{"hanzi":"非法","pinyin":"fēifǎ","vi":"phi pháp"}],"traditional":"取締"},{"id":"取之不尽","hanzi":"取之不尽","pinyin":"qǔzhī-bújìn","meaning_vi":"dùng mãi không hết","explanation":"Lấy mãi không hết → nguồn vô tận; thường đi cùng 用之不竭 (dùng mãi không cạn).","hsk_level":6,"tags":["thanh-ngu"],"image":"♾️","examples":[{"type":"basic","zh":"知识是取之不尽的。","pinyin":"Zhīshi shì qǔzhībújìn de.","vi":"Tri thức là thứ dùng mãi không hết."},{"type":"simple","zh":"太阳能是一种取之不尽的清洁能源。","pinyin":"Tàiyángnéng shì yì zhǒng qǔzhībújìn de qīngjié néngyuán.","vi":"Năng lượng mặt trời là một nguồn năng lượng sạch dùng mãi không hết."},{"type":"compound","zh":"民间故事是取之不尽的宝库，所以很多作家从中寻找灵感。","pinyin":"Mínjiān gùshi shì qǔzhībújìn de bǎokù, suǒyǐ hěn duō zuòjiā cóng zhōng xúnzhǎo línggǎn.","vi":"Truyện dân gian là kho báu vô tận nên nhiều nhà văn tìm cảm hứng từ đó."}],"related":[{"hanzi":"用之不竭","pinyin":"yòngzhībùjié","vi":"dùng mãi không cạn"},{"hanzi":"源源不断","pinyin":"yuányuánbúduàn","vi":"liên tục không ngừng"},{"hanzi":"无穷无尽","pinyin":"wúqióngwújìn","vi":"vô cùng vô tận"},{"hanzi":"枯竭","pinyin":"kūjié","vi":"cạn kiệt"}],"traditional":"取之不盡"},{"id":"锐利","hanzi":"锐利","pinyin":"ruìlì","meaning_vi":"sắc bén (ánh mắt/tư duy/vũ khí)","explanation":"锐 (nhọn) + 利 (bén).","hsk_level":6,"tags":["tinh-tu"],"image":"🦅","examples":[{"type":"basic","zh":"老鹰的目光很锐利。","pinyin":"Lǎoyīng de mùguāng hěn ruìlì.","vi":"Ánh mắt của chim ưng rất sắc bén."},{"type":"simple","zh":"这把刀的刀刃锐利得能轻松切开纸张。","pinyin":"Zhè bǎ dāo de dāorèn ruìlì de néng qīngsōng qiēkāi zhǐzhāng.","vi":"Lưỡi con dao này sắc đến mức có thể dễ dàng cắt giấy."},{"type":"compound","zh":"他的文笔不但锐利，而且总能一针见血地指出问题。","pinyin":"Tā de wénbǐ búdàn ruìlì, érqiě zǒngnéng yìzhēnjiànxiě de zhǐchū wèntí.","vi":"Ngòi bút của ông ấy không những sắc sảo mà còn luôn chỉ ra vấn đề trúng tim đen."}],"related":[{"hanzi":"锋利","pinyin":"fēnglì","vi":"sắc bén"},{"hanzi":"尖锐","pinyin":"jiānruì","vi":"sắc nhọn"},{"hanzi":"敏锐","pinyin":"mǐnruì","vi":"nhạy bén"},{"hanzi":"迟钝","pinyin":"chídùn","vi":"cùn, chậm chạp"}],"traditional":"銳利"},{"id":"瑞雪","hanzi":"瑞雪","pinyin":"ruìxuě","meaning_vi":"tuyết lành (báo hiệu mùa màng bội thu)","explanation":"瑞 (điềm lành) + 雪 (tuyết).","hsk_level":6,"tags":["danh-tu","thoi-tiet","van-hoa"],"image":"❄️","examples":[{"type":"basic","zh":"昨夜下了一场瑞雪。","pinyin":"Zuóyè xiàle yì cháng ruìxuě.","vi":"Đêm qua có một trận tuyết lành."},{"type":"simple","zh":"一场瑞雪给干旱的麦田带来了充足的水分。","pinyin":"Yì cháng ruìxuě gěi gānhàn de mài tián dàiláile chōngzú de shuǐfèn.","vi":"Trận tuyết lành mang lại độ ẩm dồi dào cho cánh đồng lúa mì khô hạn."},{"type":"compound","zh":"因为下了几场瑞雪，所以农民们对明年的收成充满信心。","pinyin":"Yīnwèi xiàle jǐ cháng ruìxuě, suǒyǐ nóngmínmen duì míngnián de shōucheng chōngmǎn xìnxīn.","vi":"Vì có mấy trận tuyết lành nên nông dân rất tin tưởng vào vụ mùa năm sau."}],"related":[{"hanzi":"大雪","pinyin":"Dàxuě","vi":"tuyết lớn"},{"hanzi":"瑞雪兆丰年","pinyin":"ruìxuě zhào fēngnián","vi":"tuyết lành báo năm được mùa"},{"hanzi":"雪花","pinyin":"xuěhuā","vi":"bông tuyết"},{"hanzi":"吉祥","pinyin":"jíxiáng","vi":"cát tường"}]},{"id":"瑞雪兆丰年","hanzi":"瑞雪兆丰年","pinyin":"ruìxuě zhào fēngnián","meaning_vi":"tuyết lành báo hiệu năm được mùa","explanation":"Ngạn ngữ nông nghiệp.","hsk_level":6,"tags":["thanh-ngu","thoi-tiet"],"image":"❄️","examples":[{"type":"basic","zh":"俗话说瑞雪兆丰年。","pinyin":"Súhuàshuō ruìxuězhàofēngnián.","vi":"Tục ngữ có câu tuyết lành báo hiệu năm được mùa."},{"type":"simple","zh":"爷爷看着满地白雪念叨着瑞雪兆丰年。","pinyin":"Yéye kànzhe mǎndì báixuě niàndaozhe ruìxuězhàofēngnián.","vi":"Ông nội nhìn tuyết trắng phủ đầy đất, lẩm bẩm câu tuyết lành báo năm được mùa."},{"type":"compound","zh":"既然瑞雪兆丰年，那么明年的庄稼一定长得好。","pinyin":"Jìrán ruìxuězhàofēngnián, nàme míngnián de zhuāngjia yídìng zhǎngde hǎo.","vi":"Đã là tuyết lành báo hiệu năm được mùa thì hoa màu năm sau chắc chắn sẽ tốt."}],"related":[{"hanzi":"瑞雪","pinyin":"ruìxuě","vi":"tuyết lành"},{"hanzi":"丰年","pinyin":"fēngnián","vi":"năm được mùa"},{"hanzi":"丰收","pinyin":"fēngshōu","vi":"bội thu"},{"hanzi":"五谷丰登","pinyin":"wǔgǔfēngdēng","vi":"ngũ cốc được mùa"}],"traditional":"瑞雪兆豐年"},{"id":"若干","hanzi":"若干","pinyin":"ruògān","meaning_vi":"một số, bao nhiêu (văn viết)","explanation":"Đứng trước danh từ chỉ số lượng không xác định.","hsk_level":6,"tags":["dai-tu"],"image":"🔢","examples":[{"type":"basic","zh":"我有若干问题要问。","pinyin":"Wǒ yǒu ruògān wèntí yào wèn.","vi":"Tôi có một số câu hỏi cần hỏi."},{"type":"simple","zh":"会议就环保问题提出了若干建议。","pinyin":"Huìyì jiù huánbǎo wèntí tíchūle ruògān jiànyì.","vi":"Hội nghị đã đưa ra một số kiến nghị về vấn đề bảo vệ môi trường."},{"type":"compound","zh":"虽然方案还有若干细节要修改，但是大方向已经定了。","pinyin":"Suīrán fāng'àn háiyǒu ruògān xìjié yào xiūgǎi, dànshì dà fāngxiàng yǐjīng dìng le.","vi":"Tuy phương án vẫn còn một số chi tiết cần sửa, nhưng hướng chính đã được định rồi."}],"related":[{"hanzi":"一些","pinyin":"yìxiē","vi":"một số"},{"hanzi":"几个","pinyin":"jǐgè","vi":"vài cái"},{"hanzi":"若干年","pinyin":"ruògānnián","vi":"một số năm"},{"hanzi":"少许","pinyin":"shǎoxǔ","vi":"một ít"}]},{"id":"若无其事","hanzi":"若无其事","pinyin":"ruòwú-qíshì","meaning_vi":"thản nhiên như không có chuyện gì xảy ra","explanation":"若 (như) + 无其事 (không có việc ấy) → thản nhiên như không có chuyện gì xảy ra.","hsk_level":6,"tags":["thanh-ngu"],"image":"😐","examples":[{"type":"basic","zh":"他若无其事地走了。","pinyin":"Tā ruòwúqíshì de zǒu le.","vi":"Anh ta thản nhiên bỏ đi như không có chuyện gì."},{"type":"simple","zh":"打碎了花瓶的小猫若无其事地舔着爪子。","pinyin":"Dǎsuìle huāpíng de xiǎomāo ruòwúqíshì de tiǎnzhe zhuǎzi.","vi":"Con mèo con làm vỡ bình hoa thản nhiên liếm móng như không có chuyện gì."},{"type":"compound","zh":"虽然心里很难过，但是她在同事面前装得若无其事。","pinyin":"Suīrán xīnlǐ hěn nánguò, dànshì tā zài tóngshì miànqián zhuāng de ruòwúqíshì.","vi":"Tuy trong lòng rất buồn, nhưng trước mặt đồng nghiệp cô ấy tỏ ra như không có chuyện gì."}],"related":[{"hanzi":"泰然自若","pinyin":"tàiránzìruò","vi":"bình thản"},{"hanzi":"满不在乎","pinyin":"mǎnbúzàihu","vi":"không thèm để ý"},{"hanzi":"镇定","pinyin":"zhèndìng","vi":"bình tĩnh"},{"hanzi":"惊慌失措","pinyin":"jīnghuāngshīcuò","vi":"hoảng loạn"}],"traditional":"若無其事"},{"id":"软弱","hanzi":"软弱","pinyin":"ruǎnruò","meaning_vi":"yếu đuối, nhu nhược","explanation":"软 (mềm) + 弱 (yếu).","hsk_level":6,"tags":["tinh-tu","con-nguoi"],"image":"🥀","examples":[{"type":"basic","zh":"你不能这么软弱。","pinyin":"Nǐ bù néng zhème ruǎnruò.","vi":"Bạn không thể nhu nhược như thế."},{"type":"simple","zh":"大病初愈的她身体还很软弱。","pinyin":"Dàbìng chū yù de tā shēntǐ hái hěn ruǎnruò.","vi":"Cô ấy mới khỏi bệnh nặng nên cơ thể vẫn còn rất yếu."},{"type":"compound","zh":"如果你一直这么软弱，别人就会得寸进尺。","pinyin":"Rúguǒ nǐ yìzhí zhème ruǎnruò, biérén jiù huì décùnjìnchǐ.","vi":"Nếu bạn cứ nhu nhược mãi như thế, người khác sẽ được đằng chân lân đằng đầu."}],"related":[{"hanzi":"懦弱","pinyin":"nuòruò","vi":"nhu nhược"},{"hanzi":"无力","pinyin":"wúlì","vi":"không có sức"},{"hanzi":"坚强","pinyin":"jiānqiáng","vi":"kiên cường"},{"hanzi":"软弱无能","pinyin":"ruǎnruòwúnéng","vi":"yếu đuối bất tài"}],"traditional":"軟弱"},{"id":"让步","hanzi":"让步","pinyin":"ràngbù","meaning_vi":"nhượng bộ","explanation":"让 (nhường) + 步 (bước). Động từ ly hợp.","hsk_level":6,"tags":["dong-tu","giao-tiep"],"image":"🤝","examples":[{"type":"basic","zh":"双方都做了让步。","pinyin":"Shuāngfāng dōu zuòle ràngbù.","vi":"Cả hai bên đều đã nhượng bộ."},{"type":"simple","zh":"在价格问题上卖家始终不肯让步。","pinyin":"Zài jiàgé wèntí shang màijiā shǐzhōng bùkěn ràngbù.","vi":"Về vấn đề giá cả, người bán trước sau vẫn không chịu nhượng bộ."},{"type":"compound","zh":"与其一直僵持下去，不如各自让步达成协议。","pinyin":"Yǔqí yìzhí jiāngchí xiàqù, bùrú gèzì ràngbù dáchéng xiéyì.","vi":"Thay vì cứ giằng co mãi, chẳng bằng mỗi bên nhượng bộ để đạt thỏa thuận."}],"related":[{"hanzi":"妥协","pinyin":"tuǒxié","vi":"thỏa hiệp"},{"hanzi":"退让","pinyin":"tuìràng","vi":"nhún nhường"},{"hanzi":"寸步不让","pinyin":"cùnbùbúràng","vi":"không nhường một bước"},{"hanzi":"谦让","pinyin":"qiānràng","vi":"khiêm nhường"}],"traditional":"讓步"},{"id":"热泪盈眶","hanzi":"热泪盈眶","pinyin":"rèlèi-yíngkuàng","meaning_vi":"nước mắt lưng tròng (vì xúc động)","explanation":"热泪 (nước mắt nóng) + 盈眶 (đầy hốc mắt). Thành ngữ.","hsk_level":6,"tags":["thanh-ngu","cam-xuc"],"image":"🥹","examples":[{"type":"basic","zh":"妈妈热泪盈眶。","pinyin":"Māma rèlèiyíngkuàng.","vi":"Mẹ rưng rưng nước mắt."},{"type":"simple","zh":"看到儿子平安归来的老人热泪盈眶。","pinyin":"Kàndào érzi píng'ān guīlái de lǎorén rèlèiyíngkuàng.","vi":"Cụ già nhìn thấy con trai bình an trở về thì nước mắt lưng tròng."},{"type":"compound","zh":"当国歌响起的时候，站在领奖台上的她热泪盈眶。","pinyin":"Dāng guógē xiǎngqǐ de shíhou, zhàn zài lǐngjiǎngtái shang de tā rèlèiyíngkuàng.","vi":"Khi quốc ca vang lên, cô ấy đứng trên bục nhận giải mà nước mắt lưng tròng."}],"related":[{"hanzi":"感动","pinyin":"gǎndòng","vi":"cảm động"},{"hanzi":"泪流满面","pinyin":"lèiliúmǎnmiàn","vi":"nước mắt đầm đìa"},{"hanzi":"激动","pinyin":"jīdòng","vi":"xúc động"},{"hanzi":"眼泪","pinyin":"yǎnlèi","vi":"nước mắt"}],"traditional":"熱淚盈眶"},{"id":"任劳任怨","hanzi":"任劳任怨","pinyin":"rènláo-rènyuàn","meaning_vi":"chịu thương chịu khó không một lời than vãn","explanation":"任劳 (chịu vất vả) + 任怨 (chịu oán trách) → làm lụng chăm chỉ, không ngại khó, không than vãn.","hsk_level":6,"tags":["thanh-ngu","cong-viec"],"image":"🐝","examples":[{"type":"basic","zh":"他任劳任怨地工作。","pinyin":"Tā rènláorènyuàn de gōngzuò.","vi":"Anh ấy làm việc chịu thương chịu khó không than vãn."},{"type":"simple","zh":"这位保洁阿姨在医院任劳任怨地干了二十年。","pinyin":"Zhè wèi bǎojié āyí zài yīyuàn rènláorènyuàn de gànle èrshí nián.","vi":"Cô lao công này đã làm việc ở bệnh viện hai mươi năm, chịu thương chịu khó không một lời than."},{"type":"compound","zh":"她虽然工资不高，但是一直任劳任怨地照顾着孤儿们。","pinyin":"Tā suīrán gōngzī bù gāo, dànshì yìzhí rènláorènyuàn de zhàogùzhe gū'érmen.","vi":"Tuy lương không cao, nhưng cô ấy vẫn luôn tận tụy chăm sóc các em mồ côi không một lời than."}],"related":[{"hanzi":"勤勤恳恳","pinyin":"qínqínkěnkěn","vi":"cần cù chăm chỉ"},{"hanzi":"吃苦耐劳","pinyin":"chīkǔnàiláo","vi":"chịu thương chịu khó"},{"hanzi":"怨天尤人","pinyin":"yuàntiānyóurén","vi":"oán trời trách người"},{"hanzi":"兢兢业业","pinyin":"jīngjīngyèyè","vi":"tận tụy"}],"traditional":"任勞任怨"},{"id":"任命","hanzi":"任命","pinyin":"rènmìng","meaning_vi":"bổ nhiệm (chức vụ)","explanation":"任 (giao việc) + 命 (lệnh).","hsk_level":6,"tags":["dong-tu","cong-viec"],"image":"👔","examples":[{"type":"basic","zh":"他被任命为校长。","pinyin":"Tā bèi rènmìng wéi xiàozhǎng.","vi":"Ông ấy được bổ nhiệm làm hiệu trưởng."},{"type":"simple","zh":"董事会昨天正式任命了新的财务总监。","pinyin":"Dǒngshìhuì zuótiān zhèngshì rènmìngle xīn de cáiwù zǒngjiān.","vi":"Hội đồng quản trị hôm qua đã chính thức bổ nhiệm giám đốc tài chính mới."},{"type":"compound","zh":"因为她业绩突出，所以公司任命她负责海外市场。","pinyin":"Yīnwèi tā yèjì tūchū, suǒyǐ gōngsī rènmìng tā fùzé hǎiwài shìchǎng.","vi":"Vì thành tích nổi bật nên công ty bổ nhiệm cô ấy phụ trách thị trường nước ngoài."}],"related":[{"hanzi":"委任","pinyin":"wěirèn","vi":"ủy nhiệm"},{"hanzi":"任免","pinyin":"rènmiǎn","vi":"bổ nhiệm và miễn nhiệm"},{"hanzi":"免职","pinyin":"miǎnzhí","vi":"cách chức"},{"hanzi":"提拔","pinyin":"tíbá","vi":"đề bạt"}]},{"id":"人才济济","hanzi":"人才济济","pinyin":"réncái-jǐjǐ","meaning_vi":"nhân tài đông đúc","explanation":"人才 (nhân tài) + 济济 (tế tế – đông đúc) → nhân tài đông đảo, tụ hội nhiều người giỏi.","hsk_level":6,"tags":["thanh-ngu"],"image":"🌟","examples":[{"type":"basic","zh":"我们公司人才济济。","pinyin":"Wǒmen gōngsī réncáijǐjǐ.","vi":"Công ty chúng tôi có rất nhiều nhân tài."},{"type":"simple","zh":"这所名牌大学的物理系可谓人才济济。","pinyin":"Zhè suǒ míngpái dàxué de wùlǐ xì kěwèi réncáijǐjǐ.","vi":"Khoa Vật lý của trường đại học danh tiếng này có thể nói là nhân tài đông đúc."},{"type":"compound","zh":"虽然这个团队人才济济，但是缺少一位好的领导者。","pinyin":"Suīrán zhè ge tuánduì réncáijǐjǐ, dànshì quēshǎo yí wèi hǎo de lǐngdǎozhě.","vi":"Tuy đội ngũ này đầy nhân tài, nhưng lại thiếu một người lãnh đạo giỏi."}],"related":[{"hanzi":"济济一堂","pinyin":"jǐjǐyìtáng","vi":"nhân tài tề tựu"},{"hanzi":"人才","pinyin":"réncái","vi":"nhân tài"},{"hanzi":"藏龙卧虎","pinyin":"cánglóngwòhǔ","vi":"ngọa hổ tàng long"},{"hanzi":"人才辈出","pinyin":"réncáibèichū","vi":"nhân tài lớp lớp"}],"traditional":"人才濟濟"},{"id":"人道","hanzi":"人道","pinyin":"réndào","meaning_vi":"nhân đạo","explanation":"人 (người) + 道 (đạo lý).","hsk_level":6,"tags":["tinh-tu","xa-hoi"],"image":"💖","examples":[{"type":"basic","zh":"这样做很不人道。","pinyin":"Zhèyàng zuò hěn bù réndào.","vi":"Làm như vậy rất vô nhân đạo."},{"type":"simple","zh":"国际组织向难民营运送了大批人道主义援助物资。","pinyin":"Guójì zǔzhī xiàng nànmínyíng yùnsòngle dàpī réndào zhǔyì yuánzhù wùzī.","vi":"Các tổ chức quốc tế đã vận chuyển một lượng lớn hàng viện trợ nhân đạo đến trại tị nạn."},{"type":"compound","zh":"即使是对待战俘，我们也必须坚持人道原则。","pinyin":"Jíshǐ shì duìdài zhànfú, wǒmen yě bìxū jiānchí réndào yuánzé.","vi":"Ngay cả khi đối xử với tù binh, chúng ta cũng phải giữ vững nguyên tắc nhân đạo."}],"related":[{"hanzi":"人道主义","pinyin":"réndàozhǔyì","vi":"chủ nghĩa nhân đạo"},{"hanzi":"人权","pinyin":"rénquán","vi":"nhân quyền"},{"hanzi":"不人道","pinyin":"bùréndào","vi":"vô nhân đạo"},{"hanzi":"仁慈","pinyin":"réncí","vi":"nhân từ"}]},{"id":"人家","hanzi":"人家","pinyin":"rénjia","meaning_vi":"người ta; hộ gia đình, nhà","explanation":"人 (nhân – người) + 家 (gia – nhà) → đọc rénjia: người ta, người khác, hoặc tự chỉ mình (giọng nũng nịu); đọc rénjiā: hộ gia đình.","hsk_level":6,"tags":["dai-tu","danh-tu"],"image":"👤","examples":[{"type":"basic","zh":"人家不想去嘛。","pinyin":"Rénjia bù xiǎng qù ma.","vi":"Người ta không muốn đi mà."},{"type":"simple","zh":"山脚下住着十几户人家。","pinyin":"Shān jiǎoxià zhùzhe shíjǐ hù rénjiā.","vi":"Dưới chân núi có hơn mười hộ gia đình sinh sống."},{"type":"compound","zh":"既然人家帮了你大忙，你就应该好好谢谢人家。","pinyin":"Jìrán rénjia bāngle nǐ dà máng, nǐ jiù yīnggāi hǎohǎo xièxie rénjia.","vi":"Người ta đã giúp bạn một việc lớn như vậy thì bạn nên cảm ơn người ta tử tế."}],"related":[{"hanzi":"别人","pinyin":"biérén","vi":"người khác"},{"hanzi":"他人","pinyin":"tārén","vi":"người khác"},{"hanzi":"住户","pinyin":"zhùhù","vi":"hộ dân"},{"hanzi":"自己","pinyin":"zìjǐ","vi":"bản thân"}]},{"id":"人尽皆知","hanzi":"人尽皆知","pinyin":"rénjìn-jiēzhī","meaning_vi":"ai ai cũng biết","explanation":"人尽 (mọi người) + 皆知 (đều biết) → ai ai cũng biết. Gần nghĩa: 家喻户晓.","hsk_level":6,"tags":["thanh-ngu"],"image":"📢","examples":[{"type":"basic","zh":"这件事人尽皆知。","pinyin":"Zhè jiàn shì rénjìnjiēzhī.","vi":"Chuyện này ai ai cũng biết."},{"type":"simple","zh":"他们俩的恋情在公司里早已人尽皆知。","pinyin":"Tāmen liǎ de liànqíng zài gōngsī lǐ zǎoyǐ rénjìnjiēzhī.","vi":"Chuyện tình của hai người họ trong công ty sớm đã ai ai cũng biết."},{"type":"compound","zh":"虽然这个道理人尽皆知，但是真正做到的人很少。","pinyin":"Suīrán zhè ge dàoli rénjìnjiēzhī, dànshì zhēnzhèng zuòdào de rén hěn shǎo.","vi":"Tuy đạo lý này ai cũng biết, nhưng người thực sự làm được thì rất ít."}],"related":[{"hanzi":"众所周知","pinyin":"zhòngsuǒzhōuzhī","vi":"ai cũng biết"},{"hanzi":"家喻户晓","pinyin":"jiāyùhùxiǎo","vi":"nhà nhà đều biết"},{"hanzi":"尽人皆知","pinyin":"jìnrénjiēzhī","vi":"ai cũng biết"},{"hanzi":"鲜为人知","pinyin":"xiǎnwéirénzhī","vi":"ít người biết"}],"traditional":"人盡皆知"},{"id":"人山人海","hanzi":"人山人海","pinyin":"rénshān-rénhǎi","meaning_vi":"đông nghịt người (người như núi như biển)","explanation":"Người như núi, người như biển → đông nghịt người. Hay tả nơi lễ hội, danh lam dịp nghỉ lễ.","hsk_level":6,"tags":["thanh-ngu"],"image":"👥","examples":[{"type":"basic","zh":"广场上人山人海。","pinyin":"Guǎngchǎng shang rénshānrénhǎi.","vi":"Quảng trường đông nghịt người."},{"type":"simple","zh":"国庆假期的长城景区到处人山人海。","pinyin":"Guóqìng jiàqī de Chángchéng jǐngqū dàochù rénshānrénhǎi.","vi":"Vào kỳ nghỉ Quốc khánh, khu thắng cảnh Vạn Lý Trường Thành chỗ nào cũng đông nghịt người."},{"type":"compound","zh":"早知道商场里人山人海，我就不来凑热闹了。","pinyin":"Zǎo zhīdào shāngchǎng lǐ rénshānrénhǎi, wǒ jiù bù lái còurènao le.","vi":"Biết trước trung tâm thương mại đông nghịt người như vậy thì tôi đã không đến góp vui rồi."}],"related":[{"hanzi":"人来人往","pinyin":"rénláirénwǎng","vi":"người qua kẻ lại"},{"hanzi":"熙熙攘攘","pinyin":"xīxīrǎngrǎng","vi":"đông đúc nhộn nhịp"},{"hanzi":"水泄不通","pinyin":"shuǐxièbùtōng","vi":"chật như nêm"},{"hanzi":"冷冷清清","pinyin":"lěnglěngqīngqīng","vi":"vắng vẻ"}]},{"id":"人性","hanzi":"人性","pinyin":"rénxìng","meaning_vi":"nhân tính, bản tính con người","explanation":"人 + 性 (tính chất).","hsk_level":6,"tags":["danh-tu"],"image":"🧠","examples":[{"type":"basic","zh":"他很懂人性。","pinyin":"Tā hěn dǒng rénxìng.","vi":"Anh ấy rất hiểu bản tính con người."},{"type":"simple","zh":"这部小说深刻地揭示了战争中的人性。","pinyin":"Zhè bù xiǎoshuō shēnkè de jiēshìle zhànzhēng zhōng de rénxìng.","vi":"Cuốn tiểu thuyết này đã phơi bày sâu sắc nhân tính trong chiến tranh."},{"type":"compound","zh":"只要多关心别人，就能看到人性中美好的一面。","pinyin":"Zhǐyào duō guānxīn biérén, jiù néng kàndào rénxìng zhōng měihǎo de yímiàn.","vi":"Chỉ cần quan tâm người khác nhiều hơn, bạn sẽ thấy được mặt tốt đẹp trong bản tính con người."}],"related":[{"hanzi":"人性化","pinyin":"rénxìnghuà","vi":"nhân văn hóa"},{"hanzi":"本性","pinyin":"běnxìng","vi":"bản tính"},{"hanzi":"人情","pinyin":"rénqíng","vi":"nhân tình"},{"hanzi":"天性","pinyin":"tiānxìng","vi":"thiên tính"}]},{"id":"人云亦云","hanzi":"人云亦云","pinyin":"rényún-yìyún","meaning_vi":"người ta nói sao mình nói vậy, hùa theo thiếu chính kiến","explanation":"Người ta nói (云) sao cũng nói (亦云) vậy → a dua theo người khác, không có chính kiến.","hsk_level":6,"tags":["thanh-ngu"],"image":"🦜","examples":[{"type":"basic","zh":"他总是人云亦云。","pinyin":"Tā zǒngshì rényúnyìyún.","vi":"Anh ta lúc nào cũng nói theo người khác."},{"type":"simple","zh":"网民不应该对未经证实的消息人云亦云。","pinyin":"Wǎngmín bù yīnggāi duì wèijīng zhèngshí de xiāoxi rényúnyìyún.","vi":"Cư dân mạng không nên hùa theo những tin chưa được xác thực."},{"type":"compound","zh":"与其人云亦云，不如自己去调查一下真相。","pinyin":"Yǔqí rényúnyìyún, bùrú zìjǐ qù diàochá yíxià zhēnxiàng.","vi":"Thay vì nói theo người khác, chẳng bằng tự mình đi tìm hiểu sự thật."}],"related":[{"hanzi":"随声附和","pinyin":"suíshēngfùhè","vi":"hùa theo"},{"hanzi":"随波逐流","pinyin":"suíbōzhúliú","vi":"ba phải"},{"hanzi":"鹦鹉学舌","pinyin":"yīngwǔxuéshé","vi":"nói như vẹt"},{"hanzi":"独立思考","pinyin":"dúlìsīkǎo","vi":"tư duy độc lập"}],"traditional":"人雲亦雲"},{"id":"仁至义尽","hanzi":"仁至义尽","pinyin":"rénzhì-yìjìn","meaning_vi":"tận tình tận nghĩa hết mức có thể","explanation":"仁 (nhân) đến tột cùng, 义 (nghĩa) làm hết mức → đã đối xử hết lòng hết nghĩa. Thường: 我对他已经仁至义尽了.","hsk_level":6,"tags":["thanh-ngu"],"image":"💖","examples":[{"type":"basic","zh":"我已经仁至义尽了。","pinyin":"Wǒ yǐjīng rénzhìyìjìn le.","vi":"Tôi đã tận tình tận nghĩa lắm rồi."},{"type":"simple","zh":"公司对这名违纪员工的处理算是仁至义尽。","pinyin":"Gōngsī duì zhè míng wéijì yuángōng de chǔlǐ suànshì rénzhìyìjìn.","vi":"Cách công ty xử lý nhân viên vi phạm kỷ luật này có thể coi là hết tình hết nghĩa."},{"type":"compound","zh":"我们对他已经仁至义尽，如果他还不悔改，就只好报警了。","pinyin":"Wǒmen duì tā yǐjīng rénzhìyìjìn, rúguǒ tā hái bù huǐgǎi, jiù zhǐhǎo bàojǐng le.","vi":"Chúng tôi đã hết tình hết nghĩa với hắn, nếu hắn vẫn không hối cải thì đành báo cảnh sát."}],"related":[{"hanzi":"尽心尽力","pinyin":"jìnxīnjìnlì","vi":"tận tâm tận lực"},{"hanzi":"仁义","pinyin":"rényì","vi":"nhân nghĩa"},{"hanzi":"情至意尽","pinyin":"qíngzhìyìjìn","vi":"tận tình tận ý"},{"hanzi":"无情无义","pinyin":"wúqíngwúyì","vi":"vô tình vô nghĩa"}],"traditional":"仁至義盡"},{"id":"仍旧","hanzi":"仍旧","pinyin":"réngjiù","meaning_vi":"vẫn như cũ, vẫn cứ","explanation":"仍 + 旧 (cũ). Đồng nghĩa với 仍然.","hsk_level":6,"tags":["pho-tu"],"image":"🔄","examples":[{"type":"basic","zh":"他仍旧住在老房子里。","pinyin":"Tā réngjiù zhùzài lǎo fángzi lǐ.","vi":"Ông ấy vẫn sống trong căn nhà cũ."},{"type":"simple","zh":"退休后的王老师仍旧每天早起读报。","pinyin":"Tuìxiū hòu de Wáng lǎoshī réngjiù měitiān zǎoqǐ dúbào.","vi":"Thầy Vương sau khi nghỉ hưu vẫn mỗi ngày dậy sớm đọc báo."},{"type":"compound","zh":"虽然医生劝了很多次，但是他仍旧戒不掉烟。","pinyin":"Suīrán yīshēng quànle hěn duōcì, dànshì tā réngjiù jiè bú diào yān.","vi":"Tuy bác sĩ đã khuyên rất nhiều lần, nhưng ông ấy vẫn không bỏ được thuốc lá."}],"related":[{"hanzi":"仍然","pinyin":"réngrán","vi":"vẫn"},{"hanzi":"依旧","pinyin":"yījiù","vi":"vẫn như cũ"},{"hanzi":"照旧","pinyin":"zhàojiù","vi":"như cũ"},{"hanzi":"依然","pinyin":"yīrán","vi":"vẫn"}],"traditional":"仍舊"},{"id":"日积月累","hanzi":"日积月累","pinyin":"rìjī-yuèlěi","meaning_vi":"tích lũy từng ngày từng tháng","explanation":"Ngày tích tháng góp → tích lũy dần dần theo thời gian; hay nói về kiến thức, kinh nghiệm.","hsk_level":6,"tags":["thanh-ngu","hoc-tap"],"image":"📚","examples":[{"type":"basic","zh":"知识要日积月累。","pinyin":"Zhīshi yào rìjīyuèlěi.","vi":"Kiến thức phải tích lũy từng ngày."},{"type":"simple","zh":"她把日积月累的读书笔记整理成了一本书。","pinyin":"Tā bǎ rìjīyuèlěi de dúshū bǐjì zhěnglǐ chéngle yì běn shū.","vi":"Cô ấy đã sắp xếp những ghi chép đọc sách tích lũy bao ngày thành một cuốn sách."},{"type":"compound","zh":"只要每天背十个单词，日积月累就能掌握大量词汇。","pinyin":"Zhǐyào měitiān bèi shí gè dāncí, rìjīyuèlěi jiù néng zhǎngwò dàliàng cíhuì.","vi":"Chỉ cần mỗi ngày học thuộc mười từ, tích lũy dần dần sẽ nắm được lượng từ vựng lớn."}],"related":[{"hanzi":"积少成多","pinyin":"jīshǎochéngduō","vi":"tích tiểu thành đại"},{"hanzi":"长年累月","pinyin":"chángniánlěiyuè","vi":"năm này qua năm khác"},{"hanzi":"积累","pinyin":"jīlěi","vi":"tích lũy"},{"hanzi":"一朝一夕","pinyin":"yìzhāoyìxī","vi":"một sớm một chiều"}],"traditional":"日積月累"},{"id":"荣华富贵","hanzi":"荣华富贵","pinyin":"rónghuá-fùguì","meaning_vi":"vinh hoa phú quý","explanation":"荣华 (vinh hoa – vẻ vang) + 富贵 (phú quý – giàu sang) → giàu sang, địa vị cao, cuộc sống sung túc.","hsk_level":6,"tags":["thanh-ngu","van-hoa"],"image":"👑","examples":[{"type":"basic","zh":"他不贪图荣华富贵。","pinyin":"Tā bù tāntú rónghuáfùguì.","vi":"Ông ấy không ham vinh hoa phú quý."},{"type":"simple","zh":"老财主一辈子都在追求荣华富贵。","pinyin":"Lǎo cáizhǔ yíbèizi dōu zài zhuīqiú rónghuáfùguì.","vi":"Lão phú hộ cả đời đều theo đuổi vinh hoa phú quý."},{"type":"compound","zh":"即使给他荣华富贵，他也不肯背叛自己的朋友。","pinyin":"Jíshǐ gěi tā rónghuáfùguì, tā yě bùkěn bèipàn zìjǐ de péngyou.","vi":"Dù có cho anh ta vinh hoa phú quý, anh ta cũng không chịu phản bội bạn mình."}],"related":[{"hanzi":"富贵","pinyin":"fùguì","vi":"phú quý"},{"hanzi":"功名利禄","pinyin":"gōngmínglìlù","vi":"công danh lợi lộc"},{"hanzi":"锦衣玉食","pinyin":"jǐnyīyùshí","vi":"ăn sung mặc sướng"},{"hanzi":"贫贱","pinyin":"pínjiàn","vi":"nghèo hèn"}],"traditional":"榮華富貴"},{"id":"融会贯通","hanzi":"融会贯通","pinyin":"rónghuì-guàntōng","meaning_vi":"dung hội quán thông, hiểu thấu đáo và vận dụng linh hoạt","explanation":"融会 (dung hội – hòa quyện) + 贯通 (quán thông – thông suốt) → tổng hợp kiến thức, hiểu thấu đáo và vận dụng linh hoạt.","hsk_level":6,"tags":["thanh-ngu","hoc-tap"],"image":"🧠","examples":[{"type":"basic","zh":"学习要融会贯通。","pinyin":"Xuéxí yào rónghuìguàntōng.","vi":"Học tập phải hiểu thấu và vận dụng linh hoạt."},{"type":"simple","zh":"他把中西医的理论融会贯通地用于临床。","pinyin":"Tā bǎ zhōngxīyī de lǐlùn rónghuìguàntōng de yòngyú línchuáng.","vi":"Ông ấy dung hòa thông suốt lý thuyết Đông Tây y để áp dụng vào lâm sàng."},{"type":"compound","zh":"只有把这些公式融会贯通，你才能解出难题。","pinyin":"Zhǐyǒu bǎ zhèxiē gōngshì rónghuìguàntōng, nǐ cáinéng jiěchū nántí.","vi":"Chỉ khi hiểu thấu và vận dụng linh hoạt các công thức này, bạn mới giải được bài khó."}],"related":[{"hanzi":"举一反三","pinyin":"jǔyìfǎnsān","vi":"học một biết ba"},{"hanzi":"触类旁通","pinyin":"chùlèipángtōng","vi":"hiểu một suy ra nhiều"},{"hanzi":"死记硬背","pinyin":"sǐjìyìngbèi","vi":"học vẹt"},{"hanzi":"贯通","pinyin":"guàntōng","vi":"thông suốt"}],"traditional":"融會貫通"},{"id":"容器","hanzi":"容器","pinyin":"róngqì","meaning_vi":"đồ đựng, vật chứa","explanation":"容 + 器 (dụng cụ).","hsk_level":6,"tags":["danh-tu","do-vat"],"image":"🏺","examples":[{"type":"basic","zh":"请把水倒进容器里。","pinyin":"Qǐng bǎ shuǐ dào jìn róngqì lǐ.","vi":"Hãy đổ nước vào vật chứa."},{"type":"simple","zh":"化学实验室里摆满了各种玻璃容器。","pinyin":"Huàxué shíyànshì lǐ bǎimǎnle gèzhǒng bōli róngqì.","vi":"Phòng thí nghiệm hóa học bày đầy các loại vật chứa bằng thủy tinh."},{"type":"compound","zh":"如果用塑料容器加热食物，就可能产生有害物质。","pinyin":"Rúguǒ yòng sùliào róngqì jiārè shíwù, jiù kěnéng chǎnshēng yǒuhài wùzhì.","vi":"Nếu dùng hộp nhựa để hâm nóng thức ăn, có thể sinh ra chất độc hại."}],"related":[{"hanzi":"器皿","pinyin":"qìmǐn","vi":"đồ đựng"},{"hanzi":"瓶子","pinyin":"píngzi","vi":"cái chai"},{"hanzi":"罐子","pinyin":"guànzi","vi":"cái hũ"},{"hanzi":"容量","pinyin":"róngliàng","vi":"dung tích"}]},{"id":"荣辱与共","hanzi":"荣辱与共","pinyin":"róngrǔ-yǔgòng","meaning_vi":"vinh nhục có nhau","explanation":"荣 (vinh) + 辱 (nhục) + 与共 (cùng chung) → vinh nhục có nhau, cùng chia sẻ thành bại.","hsk_level":6,"tags":["thanh-ngu"],"image":"🤝","examples":[{"type":"basic","zh":"我们荣辱与共。","pinyin":"Wǒmen róngrǔyǔgòng.","vi":"Chúng ta vinh nhục có nhau."},{"type":"simple","zh":"全体员工和企业是荣辱与共的命运共同体。","pinyin":"Quántǐ yuángōng hé qǐyè shì róngrǔyǔgòng de mìngyùn gòngtóngtǐ.","vi":"Toàn thể nhân viên và doanh nghiệp là một cộng đồng chung vận mệnh, vinh nhục có nhau."},{"type":"compound","zh":"既然我们是一个团队，就应该荣辱与共。","pinyin":"Jìrán wǒmen shì yí gè tuánduì, jiù yīnggāi róngrǔyǔgòng.","vi":"Đã là một đội thì chúng ta nên vinh nhục có nhau."}],"related":[{"hanzi":"同甘共苦","pinyin":"tónggāngòngkǔ","vi":"đồng cam cộng khổ"},{"hanzi":"休戚与共","pinyin":"xiūqīyǔgòng","vi":"chia sẻ vui buồn"},{"hanzi":"患难与共","pinyin":"huànnànyǔgòng","vi":"hoạn nạn có nhau"},{"hanzi":"荣辱","pinyin":"róngrǔ","vi":"vinh nhục"}],"traditional":"榮辱與共"},{"id":"柔和","hanzi":"柔和","pinyin":"róuhé","meaning_vi":"dịu dàng, êm dịu (ánh sáng/âm thanh)","explanation":"柔 (mềm) + 和 (ôn hòa).","hsk_level":6,"tags":["tinh-tu"],"image":"🌸","examples":[{"type":"basic","zh":"灯光很柔和。","pinyin":"Dēngguāng hěn róuhé.","vi":"Ánh đèn rất dịu."},{"type":"simple","zh":"她用柔和的声音给孩子讲睡前故事。","pinyin":"Tā yòng róuhé de shēngyīn gěi háizi jiǎng shuì qián gùshi.","vi":"Cô ấy dùng giọng nói dịu dàng kể chuyện trước giờ ngủ cho con."},{"type":"compound","zh":"这件毛衣的颜色既柔和又大方，很适合送给妈妈。","pinyin":"Zhè jiàn máoyī de yánsè jì róuhé yòu dàfang, hěn shìhé sònggěi māma.","vi":"Màu chiếc áo len này vừa dịu nhẹ vừa trang nhã, rất hợp để tặng mẹ."}],"related":[{"hanzi":"温和","pinyin":"wēnhé","vi":"ôn hòa"},{"hanzi":"柔软","pinyin":"róuruǎn","vi":"mềm mại"},{"hanzi":"刺眼","pinyin":"cìyǎn","vi":"chói mắt"},{"hanzi":"温柔","pinyin":"wēnróu","vi":"dịu dàng"}]},{"id":"入乡随俗","hanzi":"入乡随俗","pinyin":"rùxiāng-suísú","meaning_vi":"nhập gia tùy tục","explanation":"入乡 (vào làng) + 随俗 (theo phong tục). Thành ngữ.","hsk_level":6,"tags":["thanh-ngu","van-hoa"],"image":"🏮","examples":[{"type":"basic","zh":"我们要入乡随俗。","pinyin":"Wǒmen yào rùxiāngsuísú.","vi":"Chúng ta phải nhập gia tùy tục."},{"type":"simple","zh":"到了日本他也入乡随俗地脱鞋进屋。","pinyin":"Dàole Rìběn tā yě rùxiāngsuísú de tuōxié jìn wū.","vi":"Đến Nhật Bản, anh ấy cũng nhập gia tùy tục cởi giày vào nhà."},{"type":"compound","zh":"虽然吃不惯辣，但是来到四川他也只好入乡随俗。","pinyin":"Suīrán chī bú guàn là, dànshì láidào Sìchuān tā yě zhǐhǎo rùxiāngsuísú.","vi":"Tuy không quen ăn cay, nhưng đến Tứ Xuyên anh ấy cũng đành nhập gia tùy tục."}],"related":[{"hanzi":"入境问俗","pinyin":"rùjìngwènsú","vi":"đến nơi hỏi tục"},{"hanzi":"风俗","pinyin":"fēngsú","vi":"phong tục"},{"hanzi":"习俗","pinyin":"xísú","vi":"tập tục"},{"hanzi":"适应","pinyin":"shìyìng","vi":"thích nghi"}],"traditional":"入鄉隨俗"},{"id":"闰年","hanzi":"闰年","pinyin":"rùnnián","meaning_vi":"năm nhuận","explanation":"闰 (nhuận – thừa ra) + 年 (niên – năm) → năm có thêm ngày (dương lịch có 29/2) hoặc thêm tháng (âm lịch).","hsk_level":6,"tags":["danh-tu","thoi-gian"],"image":"📅","examples":[{"type":"basic","zh":"今年是闰年吗？","pinyin":"Jīnnián shì rùnnián ma?","vi":"Năm nay có phải năm nhuận không?"},{"type":"simple","zh":"闰年的二月比平年多出一天。","pinyin":"Rùnnián de Èryuè bǐ píngnián duō chū yì tiān.","vi":"Tháng hai của năm nhuận nhiều hơn năm thường một ngày."},{"type":"compound","zh":"因为她是二月二十九日出生的，所以只有闰年才能过生日。","pinyin":"Yīnwèi tā shì Èryuè èr shíjiǔ rì chūshēng de, suǒyǐ zhǐyǒu rùnnián cáinéng guòshēngrì.","vi":"Vì cô ấy sinh ngày 29 tháng 2 nên chỉ năm nhuận mới được đón sinh nhật."}],"related":[{"hanzi":"平年","pinyin":"píngnián","vi":"năm thường"},{"hanzi":"闰月","pinyin":"rùnyuè","vi":"tháng nhuận"},{"hanzi":"公历","pinyin":"gōnglì","vi":"dương lịch"},{"hanzi":"农历","pinyin":"nónglì","vi":"âm lịch"}],"traditional":"閏年"},{"id":"如出一辙","hanzi":"如出一辙","pinyin":"rúchū-yìzhé","meaning_vi":"giống hệt nhau như đúc","explanation":"Như ra từ cùng một vết bánh xe (辙) → giống hệt nhau; thường mang ý chê: 手法如出一辙.","hsk_level":6,"tags":["thanh-ngu"],"image":"👯","examples":[{"type":"basic","zh":"两人的说法如出一辙。","pinyin":"Liǎng rén de shuōfǎ rúchūyìzhé.","vi":"Lời của hai người giống hệt nhau."},{"type":"simple","zh":"这两起诈骗案的作案手法如出一辙。","pinyin":"Zhè liǎng qǐ zhàpiàn àn de zuò'àn shǒufǎ rúchūyìzhé.","vi":"Thủ đoạn gây án của hai vụ lừa đảo này giống hệt nhau."},{"type":"compound","zh":"因为两份作业的错误如出一辙，所以老师怀疑有人抄袭。","pinyin":"Yīnwèi liǎng fèn zuòyè de cuòwù rúchūyìzhé, suǒyǐ lǎoshī huáiyí yǒurén chāoxí.","vi":"Vì lỗi sai trong hai bài tập giống hệt nhau nên giáo viên nghi có người chép bài."}],"related":[{"hanzi":"一模一样","pinyin":"yìmúyíyàng","vi":"giống hệt"},{"hanzi":"大同小异","pinyin":"dàtóngxiǎoyì","vi":"na ná nhau"},{"hanzi":"截然不同","pinyin":"jiéránbùtóng","vi":"hoàn toàn khác"},{"hanzi":"如出一口","pinyin":"rúchūyìkǒu","vi":"nói như một"}],"traditional":"如出一轍"},{"id":"如火如荼","hanzi":"如火如荼","pinyin":"rúhuǒ-rútú","meaning_vi":"khí thế sôi nổi rầm rộ (đỏ như lửa, trắng như hoa cỏ tranh)","explanation":"如火如荼: như lửa (đỏ) như hoa cỏ tranh 荼 (trắng) – từ đội quân áo đỏ áo trắng của Ngô vương Phù Sai → khí thế sôi nổi, rầm rộ.","hsk_level":6,"tags":["thanh-ngu"],"image":"🔥","examples":[{"type":"basic","zh":"选举如火如荼。","pinyin":"Xuǎnjǔ rúhuǒrútú.","vi":"Cuộc bầu cử đang diễn ra sôi nổi."},{"type":"simple","zh":"全市的植树活动正在如火如荼地进行。","pinyin":"Quánshì de zhíshù huódòng zhèngzài rúhuǒrútú de jìnxíng.","vi":"Phong trào trồng cây toàn thành phố đang diễn ra rầm rộ."},{"type":"compound","zh":"虽然外面下着大雨，但是体育馆里的比赛进行得如火如荼。","pinyin":"Suīrán wàimiàn xiàzhe dàyǔ, dànshì tǐyùguǎn lǐ de bǐsài jìnxíng de rúhuǒrútú.","vi":"Tuy bên ngoài trời mưa to, nhưng trận đấu trong nhà thi đấu vẫn diễn ra vô cùng sôi nổi."}],"related":[{"hanzi":"轰轰烈烈","pinyin":"hōnghōnglièliè","vi":"rầm rộ"},{"hanzi":"热火朝天","pinyin":"rèhuǒcháotiān","vi":"sôi nổi khí thế"},{"hanzi":"声势浩大","pinyin":"shēngshìhàodà","vi":"thanh thế lớn"},{"hanzi":"冷冷清清","pinyin":"lěnglěngqīngqīng","vi":"vắng vẻ"}]},{"id":"如释重负","hanzi":"如释重负","pinyin":"rúshì-zhòngfù","meaning_vi":"nhẹ nhõm như trút được gánh nặng","explanation":"如 (như) 释 (thích – trút bỏ) 重负 (trọng phụ – gánh nặng) → như vừa trút được gánh nặng; nhẹ nhõm hẳn.","hsk_level":6,"tags":["thanh-ngu","cam-xuc"],"image":"😌","examples":[{"type":"basic","zh":"他如释重负地笑了。","pinyin":"Tā rúshìzhòngfù de xiào le.","vi":"Anh ấy cười nhẹ nhõm như trút được gánh nặng."},{"type":"simple","zh":"交完毕业论文后她感到如释重负。","pinyin":"Jiāo wán bìyèlùnwén hòu tā gǎndào rúshìzhòngfù.","vi":"Nộp xong luận văn tốt nghiệp, cô ấy cảm thấy nhẹ nhõm như trút được gánh nặng."},{"type":"compound","zh":"医生一宣布手术成功，家属们就如释重负地松了口气。","pinyin":"Yīshēng yì xuānbù shǒushù chénggōng, jiāshǔmen jiù rúshìzhòngfù de sōngle kǒuqì.","vi":"Bác sĩ vừa thông báo ca mổ thành công, người nhà liền thở phào nhẹ nhõm như trút được gánh nặng."}],"related":[{"hanzi":"松了一口气","pinyin":"sōngle yìkǒuqì","vi":"thở phào nhẹ nhõm"},{"hanzi":"轻松","pinyin":"qīngsōng","vi":"nhẹ nhõm"},{"hanzi":"忧心忡忡","pinyin":"yōuxīnchōngchōng","vi":"lo âu canh cánh"},{"hanzi":"心事重重","pinyin":"xīnshìchóngchóng","vi":"nặng trĩu tâm sự"}],"traditional":"如釋重負"},{"id":"如愿以偿","hanzi":"如愿以偿","pinyin":"rúyuàn-yǐcháng","meaning_vi":"đạt được ước nguyện","explanation":"如愿 (như nguyện – đúng ý muốn) + 以偿 (dĩ thường – được đền đáp) → nguyện vọng được thỏa mãn, đạt điều mong ước.","hsk_level":6,"tags":["thanh-ngu"],"image":"🌟","examples":[{"type":"basic","zh":"他终于如愿以偿。","pinyin":"Tā zhōngyú rúyuànyǐcháng.","vi":"Cuối cùng anh ấy đã toại nguyện."},{"type":"simple","zh":"经过三年的努力她如愿以偿考上了北大。","pinyin":"Jīngguò sān nián de nǔlì tā rúyuànyǐcháng kǎoshàngle Běidà.","vi":"Sau ba năm nỗ lực, cô ấy đã toại nguyện đỗ vào Đại học Bắc Kinh."},{"type":"compound","zh":"只要你坚持不懈地努力，就一定能如愿以偿。","pinyin":"Zhǐyào nǐ jiānchíbúxiè de nǔlì, jiù yídìng néng rúyuànyǐcháng.","vi":"Chỉ cần bạn kiên trì nỗ lực không ngừng, nhất định sẽ đạt được ước nguyện."}],"related":[{"hanzi":"心想事成","pinyin":"xīnxiǎngshìchéng","vi":"muốn gì được nấy"},{"hanzi":"称心如意","pinyin":"chènxīnrúyì","vi":"vừa lòng như ý"},{"hanzi":"事与愿违","pinyin":"shìyǔyuànwéi","vi":"việc trái ý muốn"},{"hanzi":"梦想成真","pinyin":"mèngxiǎngchéngzhēn","vi":"giấc mơ thành hiện thực"}],"traditional":"如願以償"},{"id":"如意","hanzi":"如意","pinyin":"rúyì","meaning_vi":"như ý, vừa ý","explanation":"如 (theo) + 意 (ý muốn). Cụm: 万事如意 (Vạn sự như ý).","hsk_level":6,"tags":["tinh-tu","van-hoa"],"image":"🧧","examples":[{"type":"basic","zh":"祝你万事如意！","pinyin":"Zhù nǐ wànshì rúyì!","vi":"Chúc bạn vạn sự như ý!"},{"type":"simple","zh":"他在新公司里过得不太如意。","pinyin":"Tā zài xīn gōngsī lǐ guòde bú tài rúyì.","vi":"Anh ấy ở công ty mới sống không được như ý lắm."},{"type":"compound","zh":"如果找不到称心如意的房子，我们就先租着住。","pinyin":"Rúguǒ zhǎobúdào chènxīnrúyì de fángzi, wǒmen jiù xiān zūzhe zhù.","vi":"Nếu không tìm được căn nhà vừa ý, chúng ta sẽ thuê ở trước."}],"related":[{"hanzi":"称心","pinyin":"chènxīn","vi":"vừa ý"},{"hanzi":"万事如意","pinyin":"wànshìrúyì","vi":"vạn sự như ý"},{"hanzi":"满意","pinyin":"mǎnyì","vi":"hài lòng"},{"hanzi":"如意算盘","pinyin":"rúyìsuànpán","vi":"tính toán hão"}]},{"id":"如鱼得水","hanzi":"如鱼得水","pinyin":"rúyú-déshuǐ","meaning_vi":"như cá gặp nước (gặp môi trường thuận lợi phát huy tài năng)","explanation":"Như cá gặp nước (lời Lưu Bị khi có được Gia Cát Lượng) → gặp người hợp ý hoặc môi trường thuận lợi để phát huy.","hsk_level":6,"tags":["thanh-ngu"],"image":"🐟","examples":[{"type":"basic","zh":"他在这里如鱼得水。","pinyin":"Tā zài zhèlǐ rúyúdéshuǐ.","vi":"Ở đây anh ấy như cá gặp nước."},{"type":"simple","zh":"喜欢交际的她在销售部门干得如鱼得水。","pinyin":"Xǐhuan jiāojì de tā zài xiāoshòu bùmén gàn de rúyúdéshuǐ.","vi":"Cô ấy thích giao tiếp nên làm ở bộ phận kinh doanh như cá gặp nước."},{"type":"compound","zh":"他一转到设计专业，就如鱼得水般地发挥出了才华。","pinyin":"Tā yì zhuǎn dào shèjì zhuānyè, jiù rúyúdéshuǐ bān de fāhuī chūle cáihuá.","vi":"Anh ấy vừa chuyển sang chuyên ngành thiết kế đã như cá gặp nước, phát huy hết tài năng."}],"related":[{"hanzi":"得心应手","pinyin":"déxīnyìngshǒu","vi":"thuận buồm xuôi gió"},{"hanzi":"游刃有余","pinyin":"yóurènyǒuyú","vi":"xử lý dễ dàng"},{"hanzi":"格格不入","pinyin":"gégébúrù","vi":"lạc lõng"},{"hanzi":"自在","pinyin":"zìzai","vi":"thoải mái"}],"traditional":"如魚得水"},{"id":"儒雅","hanzi":"儒雅","pinyin":"rúyǎ","meaning_vi":"nho nhã, lịch thiệp","explanation":"儒 (nhà nho) + 雅 (tao nhã).","hsk_level":6,"tags":["tinh-tu","con-nguoi"],"image":"🤓","examples":[{"type":"basic","zh":"他举止很儒雅。","pinyin":"Tā jǔzhǐ hěn rúyǎ.","vi":"Cử chỉ của ông ấy rất nho nhã."},{"type":"simple","zh":"那位戴眼镜的儒雅男士是我们的新教授。","pinyin":"Nà wèi dài yǎnjìng de rúyǎ nánshì shì wǒmen de xīn jiàoshòu.","vi":"Người đàn ông nho nhã đeo kính kia là giáo sư mới của chúng tôi."},{"type":"compound","zh":"他不但学识渊博，而且谈吐也十分儒雅。","pinyin":"Tā búdàn xuéshí yuānbó, érqiě tántǔ yě shífēn rúyǎ.","vi":"Ông ấy không những học thức uyên bác mà lời ăn tiếng nói cũng rất nho nhã."}],"related":[{"hanzi":"文雅","pinyin":"wényǎ","vi":"tao nhã"},{"hanzi":"斯文","pinyin":"sīwen","vi":"nho nhã"},{"hanzi":"风度翩翩","pinyin":"fēngdùpiānpiān","vi":"phong độ lịch lãm"},{"hanzi":"粗俗","pinyin":"cūsú","vi":"thô tục"}]},{"id":"忍俊不禁","hanzi":"忍俊不禁","pinyin":"rěnjùn-bùjīn","meaning_vi":"không nhịn được cười, phì cười","explanation":"忍俊 (nín cười) + 不禁 (không kìm được) → không nhịn được cười, bật cười. Thường: 令人忍俊不禁.","hsk_level":6,"tags":["thanh-ngu","cam-xuc"],"image":"😆","examples":[{"type":"basic","zh":"大家都忍俊不禁。","pinyin":"Dàjiā dōu rěnjùnbùjīn.","vi":"Mọi người đều không nhịn được cười."},{"type":"simple","zh":"小猫笨拙的样子让人忍俊不禁。","pinyin":"Xiǎomāo bènzhuō de yàngzi ràng rén rěnjùnbùjīn.","vi":"Dáng vẻ vụng về của chú mèo con khiến người ta phì cười."},{"type":"compound","zh":"他一本正经地讲笑话，结果全场观众都忍俊不禁。","pinyin":"Tā yì běn zhèngjīng de jiǎng xiàohua, jiéguǒ quánchǎng guānzhòng dōu rěnjùnbùjīn.","vi":"Anh ấy nghiêm túc kể chuyện cười, kết quả cả khán phòng đều không nhịn được cười."}],"related":[{"hanzi":"忍不住笑","pinyin":"rěnbuzhùxiào","vi":"không nhịn được cười"},{"hanzi":"哑然失笑","pinyin":"yǎránshīxiào","vi":"bật cười"},{"hanzi":"啼笑皆非","pinyin":"tíxiàojiēfēi","vi":"dở khóc dở cười"},{"hanzi":"捧腹大笑","pinyin":"pěngfùdàxiào","vi":"cười ôm bụng"}]},{"id":"忍气吞声","hanzi":"忍气吞声","pinyin":"rěnqì-tūnshēng","meaning_vi":"ngậm bồ hòn làm ngọt, nhẫn nhục chịu đựng","explanation":"忍气 (nén giận) + 吞声 (nuốt tiếng) → nhẫn nhục chịu đựng, không dám lên tiếng.","hsk_level":6,"tags":["thanh-ngu"],"image":"🤐","examples":[{"type":"basic","zh":"他只能忍气吞声。","pinyin":"Tā zhǐnéng rěnqìtūnshēng.","vi":"Anh ấy chỉ có thể nhẫn nhục chịu đựng."},{"type":"simple","zh":"她在婆家忍气吞声地过了好多年。","pinyin":"Tā zài pójia rěnqìtūnshēng de guò le hǎo duōnián.","vi":"Cô ấy đã ngậm đắng nuốt cay sống ở nhà chồng nhiều năm."},{"type":"compound","zh":"他因为害怕丢掉工作，所以对老板的辱骂忍气吞声。","pinyin":"Tā yīnwèi hàipà diūdiào gōngzuò, suǒyǐ duì lǎobǎn de rǔmà rěnqìtūnshēng.","vi":"Vì sợ mất việc nên anh ấy đành nhẫn nhịn trước những lời chửi mắng của sếp."}],"related":[{"hanzi":"逆来顺受","pinyin":"nìláishùnshòu","vi":"cam chịu"},{"hanzi":"委曲求全","pinyin":"wěiqūqiúquán","vi":"nhẫn nhịn cầu toàn"},{"hanzi":"忍辱负重","pinyin":"rěnrǔfùzhòng","vi":"nhẫn nhục gánh vác"},{"hanzi":"忍耐","pinyin":"rěnnài","vi":"nhẫn nại"}],"traditional":"忍氣吞聲"},{"id":"忍受","hanzi":"忍受","pinyin":"rěnshòu","meaning_vi":"chịu đựng","explanation":"忍 (nhẫn – nhịn) + 受 (thụ – chịu) → nhẫn nhịn chịu đựng đau đớn, bất công. Cụm: 无法忍受.","hsk_level":6,"tags":["dong-tu"],"image":"😓","examples":[{"type":"basic","zh":"我无法忍受噪音。","pinyin":"Wǒ wúfǎ rěnshòu zàoyīn.","vi":"Tôi không chịu nổi tiếng ồn."},{"type":"simple","zh":"病人咬着牙忍受着伤口的剧痛。","pinyin":"Bìngrén yǎozhe yá rěnshòuzhe shāngkǒu de jùtòng.","vi":"Bệnh nhân nghiến răng chịu đựng cơn đau dữ dội ở vết thương."},{"type":"compound","zh":"因为实在忍受不了邻居的吵闹，所以他决定搬家。","pinyin":"Yīnwèi shízài rěnshòu bùliǎo línjū de chǎonào, suǒyǐ tā juédìng bānjiā.","vi":"Vì thực sự không chịu nổi sự ồn ào của hàng xóm nên anh ấy quyết định chuyển nhà."}],"related":[{"hanzi":"承受","pinyin":"chéngshòu","vi":"chịu đựng"},{"hanzi":"忍耐","pinyin":"rěnnài","vi":"nhẫn nại"},{"hanzi":"忍无可忍","pinyin":"rěnwúkěrěn","vi":"không thể nhịn được nữa"},{"hanzi":"难以忍受","pinyin":"nányǐrěnshòu","vi":"khó chịu đựng"}]},{"id":"乳制品","hanzi":"乳制品","pinyin":"rǔzhìpǐn","meaning_vi":"sản phẩm từ sữa","explanation":"乳 (sữa) + 制品 (sản phẩm chế biến).","hsk_level":6,"tags":["danh-tu","an-uong"],"image":"🧀","examples":[{"type":"basic","zh":"他对乳制品过敏。","pinyin":"Tā duì rǔzhìpǐn guòmǐn.","vi":"Anh ấy bị dị ứng với các sản phẩm từ sữa."},{"type":"simple","zh":"这家超市的乳制品大多来自内蒙古。","pinyin":"Zhè jiā chāoshì de rǔzhìpǐn dàduō láizì Nèiménggǔ.","vi":"Sản phẩm từ sữa của siêu thị này phần lớn đến từ Nội Mông."},{"type":"compound","zh":"酸奶等乳制品不但营养丰富，而且有助于消化。","pinyin":"Suānnǎi děng rǔzhìpǐn búdàn yíngyǎng fēngfù, érqiě yǒuzhùyú xiāohuà.","vi":"Các sản phẩm từ sữa như sữa chua không những giàu dinh dưỡng mà còn giúp tiêu hóa."}],"related":[{"hanzi":"牛奶","pinyin":"niúnǎi","vi":"sữa bò"},{"hanzi":"酸奶","pinyin":"suānnǎi","vi":"sữa chua"},{"hanzi":"奶酪","pinyin":"nǎilào","vi":"phô mai"},{"hanzi":"黄油","pinyin":"huángyóu","vi":"bơ"}],"traditional":"乳製品"},{"id":"涮火锅","hanzi":"涮火锅","pinyin":"shuànhuǒguō","meaning_vi":"ăn lẩu, nhúng lẩu","explanation":"涮 (nhúng) + 火锅 (lẩu).","hsk_level":6,"tags":["dong-tu","an-uong"],"image":"🍲","examples":[{"type":"basic","zh":"今晚去涮火锅吧！","pinyin":"Jīnwǎn qù shuànhuǒguō ba!","vi":"Tối nay đi ăn lẩu nhé!"},{"type":"simple","zh":"冬天全家人围坐在一起涮火锅最暖和。","pinyin":"Dōng Tiānquán jiārén wéizuò zài yìqǐ shuànhuǒguō zuì nuǎnhuo.","vi":"Mùa đông cả nhà quây quần nhúng lẩu là ấm áp nhất."},{"type":"compound","zh":"一到下雪天，这家店涮火锅的客人就特别多。","pinyin":"Yí dào xiàxuě tiān, zhè jiā diàn shuànhuǒguō de kèrén jiù tèbié duō.","vi":"Cứ đến ngày tuyết rơi, khách đến quán này ăn lẩu lại đặc biệt đông."}],"related":[{"hanzi":"火锅","pinyin":"huǒguō","vi":"lẩu"},{"hanzi":"涮羊肉","pinyin":"shuànyángròu","vi":"lẩu thịt dê nhúng"},{"hanzi":"麻辣烫","pinyin":"málàtàng","vi":"món nhúng cay"},{"hanzi":"蘸料","pinyin":"zhànliào","vi":"nước chấm"}],"traditional":"涮火鍋"},{"id":"硕果累累","hanzi":"硕果累累","pinyin":"shuòguǒ-lěilěi","meaning_vi":"trĩu quả, thành quả to lớn dồi dào","explanation":"硕果 (quả lớn) + 累累 (đọc léi léi - trĩu trịt). Thành ngữ.","hsk_level":6,"tags":["thanh-ngu"],"image":"🍎","examples":[{"type":"basic","zh":"枝头硕果累累。","pinyin":"Zhī tóu shuòguǒlěilěi.","vi":"Đầu cành trĩu quả."},{"type":"simple","zh":"这位科学家在基因研究领域硕果累累。","pinyin":"Zhè wèi kēxuéjiā zài jīyīn yánjiū lǐngyù shuòguǒlěilěi.","vi":"Nhà khoa học này đạt được thành quả dồi dào trong lĩnh vực nghiên cứu gen."},{"type":"compound","zh":"虽然春天经历了干旱，但是秋天苹果园里依然硕果累累。","pinyin":"Suīrán chūntiān jīnglìle gānhàn, dànshì qiūtiān píng guǒyuán lǐ yīrán shuòguǒlěilěi.","vi":"Tuy mùa xuân trải qua hạn hán, nhưng đến mùa thu vườn táo vẫn trĩu quả."}],"related":[{"hanzi":"成果","pinyin":"chéngguǒ","vi":"thành quả"},{"hanzi":"丰收","pinyin":"fēngshōu","vi":"bội thu"},{"hanzi":"满载而归","pinyin":"mǎnzài'érguī","vi":"thu hoạch đầy ắp"},{"hanzi":"一无所获","pinyin":"yìwúsuǒhuò","vi":"không thu được gì"}],"traditional":"碩果纍纍"},{"id":"衰老","hanzi":"衰老","pinyin":"shuāilǎo","meaning_vi":"già yếu, lão hóa","explanation":"衰 (suy yếu) + 老 (già).","hsk_level":6,"tags":["tinh-tu","suc-khoe"],"image":"👴","examples":[{"type":"basic","zh":"爷爷明显衰老了。","pinyin":"Yéye míngxiǎn shuāilǎo le.","vi":"Ông nội rõ ràng đã già yếu đi."},{"type":"simple","zh":"长期熬夜会加速皮肤的衰老。","pinyin":"Chángqī áoyè huì jiāsù pífū de shuāilǎo.","vi":"Thức khuya thường xuyên sẽ đẩy nhanh quá trình lão hóa da."},{"type":"compound","zh":"即使身体会慢慢衰老，心态也可以永远年轻。","pinyin":"Jíshǐ shēn tǐhuì mànmàn shuāilǎo, xīntài yě kěyǐ yǒngyuǎn niánqīng.","vi":"Dù cơ thể có dần già đi, tâm hồn vẫn có thể mãi trẻ trung."}],"related":[{"hanzi":"老化","pinyin":"lǎohuà","vi":"lão hóa"},{"hanzi":"年老","pinyin":"niánlǎo","vi":"tuổi già"},{"hanzi":"抗衰老","pinyin":"kàngshuāilǎo","vi":"chống lão hóa"},{"hanzi":"年轻","pinyin":"niánqīng","vi":"trẻ trung"}]},{"id":"双管齐下","hanzi":"双管齐下","pinyin":"shuāngguǎn-qíxià","meaning_vi":"tiến hành song song hai biện pháp cùng lúc","explanation":"Hai cây bút cùng vẽ một lúc (họa sĩ Trương Tảo đời Đường) → dùng hai biện pháp tiến hành đồng thời.","hsk_level":6,"tags":["thanh-ngu"],"image":"✌️","examples":[{"type":"basic","zh":"我们要双管齐下。","pinyin":"Wǒmen yào shuāngguǎnqíxià.","vi":"Chúng ta phải làm song song cả hai cách."},{"type":"simple","zh":"医生采用药物和饮食双管齐下的方法治疗。","pinyin":"Yīshēng cǎiyòng yàowù hé yǐnshí shuāngguǎnqíxià de fāngfǎ zhìliáo.","vi":"Bác sĩ áp dụng phương pháp kết hợp đồng thời thuốc và chế độ ăn uống để điều trị."},{"type":"compound","zh":"只有运动和节食双管齐下，减肥才能有明显效果。","pinyin":"Zhǐyǒu yùndòng hé jiéshí shuāngguǎnqíxià, jiǎnféi cáinéng yǒu míngxiǎn xiàoguǒ.","vi":"Chỉ khi kết hợp đồng thời tập thể dục và ăn kiêng, việc giảm cân mới có hiệu quả rõ rệt."}],"related":[{"hanzi":"齐头并进","pinyin":"qítóubìngjìn","vi":"cùng tiến song song"},{"hanzi":"双重","pinyin":"shuāngchóng","vi":"song trùng"},{"hanzi":"两手准备","pinyin":"liǎngshǒuzhǔnbèi","vi":"chuẩn bị hai phương án"},{"hanzi":"多管齐下","pinyin":"duōguǎnqíxià","vi":"nhiều biện pháp cùng lúc"}],"traditional":"雙管齊下"},{"id":"说一不二","hanzi":"说一不二","pinyin":"shuōyì-bú'èr","meaning_vi":"nói một là một, dứt khoát giữ lời","explanation":"Nói một không nói hai → nói là làm, giữ lời; cũng chỉ người có uy quyền, nói gì người khác phải theo.","hsk_level":6,"tags":["thanh-ngu"],"image":"✊","examples":[{"type":"basic","zh":"我爸说一不二。","pinyin":"Wǒ bà shuōyìbú'èr.","vi":"Bố tôi nói một là một."},{"type":"simple","zh":"这位说一不二的老板从来不轻易改变决定。","pinyin":"Zhè wèi shuōyìbú'èr de lǎobǎn cóngláibù qīngyì gǎibiàn juédìng.","vi":"Ông chủ nói một là một này chưa bao giờ dễ dàng thay đổi quyết định."},{"type":"compound","zh":"因为奶奶在家里说一不二，所以谁也不敢反对她。","pinyin":"Yīnwèi nǎinai zài jiālǐ shuōyìbú'èr, suǒyǐ shéi yě bù gǎn fǎnduì tā.","vi":"Vì bà nội trong nhà nói một là một nên không ai dám phản đối bà."}],"related":[{"hanzi":"言出必行","pinyin":"yánchūbìxíng","vi":"nói là làm"},{"hanzi":"一言为定","pinyin":"yìyánwéidìng","vi":"nói là chắc"},{"hanzi":"出尔反尔","pinyin":"chū'ěrfǎn'ěr","vi":"tráo trở"},{"hanzi":"说话算数","pinyin":"shuōhuàsuànshù","vi":"nói lời giữ lời"}],"traditional":"說一不二"},{"id":"水滴石穿","hanzi":"水滴石穿","pinyin":"shuǐdī-shíchuān","meaning_vi":"nước chảy đá mòn","explanation":"Giọt nước nhỏ mãi làm thủng đá → kiên trì bền bỉ thì việc khó cũng thành, như \"nước chảy đá mòn\".","hsk_level":6,"tags":["thanh-ngu"],"image":"💧","examples":[{"type":"basic","zh":"学习要有水滴石穿的精神。","pinyin":"Xuéxí yàoyǒu shuǐdīshíchuān de jīngshén.","vi":"Học tập phải có tinh thần nước chảy đá mòn."},{"type":"simple","zh":"老人用水滴石穿的毅力在荒山上种出了一片树林。","pinyin":"Lǎorén yòng shuǐdīshíchuān de yìlì zài huāngshān shang zhòng chūle yípiàn shùlín.","vi":"Cụ già dùng nghị lực nước chảy đá mòn trồng nên cả một cánh rừng trên núi hoang."},{"type":"compound","zh":"水滴石穿的道理人人都懂，可是能坚持下去的人不多。","pinyin":"Shuǐdīshíchuān de dàoli rénrén dōu dǒng, kěshì néng jiānchí xiàqù de rén bù duō.","vi":"Đạo lý nước chảy đá mòn ai cũng hiểu, nhưng người kiên trì được thì không nhiều."}],"related":[{"hanzi":"滴水穿石","pinyin":"dīshuǐchuānshí","vi":"nước chảy đá mòn"},{"hanzi":"铁杵磨成针","pinyin":"tiě chǔ mó chéng zhēn","vi":"có công mài sắt có ngày nên kim"},{"hanzi":"锲而不舍","pinyin":"qiè'érbùshě","vi":"bền chí không bỏ"},{"hanzi":"持之以恒","pinyin":"chízhīyǐhéng","vi":"kiên trì bền bỉ"}]},{"id":"水落石出","hanzi":"水落石出","pinyin":"shuǐluò-shíchū","meaning_vi":"nước rút đá lộ (sự thật được phơi bày rõ ràng)","explanation":"水落石出: nước rút thì đá lộ ra (Tô Thức, Hậu Xích Bích phú) → sự việc sáng tỏ, chân tướng lộ rõ. Cụm: 查个水落石出.","hsk_level":6,"tags":["thanh-ngu"],"image":"🔍","examples":[{"type":"basic","zh":"真相终将水落石出。","pinyin":"Zhēnxiàng zhōng jiāng shuǐluòshíchū.","vi":"Sự thật cuối cùng sẽ được phơi bày."},{"type":"simple","zh":"警方一定会把这起失踪案查个水落石出。","pinyin":"Jǐngfāng yídìng huì bǎ zhè qǐ shīzōng àn chá gè shuǐluòshíchū.","vi":"Cảnh sát nhất định sẽ điều tra vụ mất tích này đến nơi đến chốn."},{"type":"compound","zh":"等调查结果出来以后，事情自然就会水落石出。","pinyin":"Děng diàochá jiéguǒ chūlái yǐhòu, shìqing zìrán jiù huì shuǐluòshíchū.","vi":"Đợi khi có kết quả điều tra, sự việc tự nhiên sẽ sáng tỏ."}],"related":[{"hanzi":"真相大白","pinyin":"zhēnxiàngdàbái","vi":"sự thật sáng tỏ"},{"hanzi":"一清二楚","pinyin":"yìqīng'èrchǔ","vi":"rõ ràng rành mạch"},{"hanzi":"真相","pinyin":"zhēnxiàng","vi":"chân tướng"},{"hanzi":"扑朔迷离","pinyin":"pūshuòmílí","vi":"mù mịt khó đoán"}]},{"id":"水龙头","hanzi":"水龙头","pinyin":"shuǐlóngtóu","meaning_vi":"vòi nước","explanation":"水 + 龙头 (đầu rồng).","hsk_level":6,"tags":["danh-tu","do-vat","nha-cua"],"image":"🚰","examples":[{"type":"basic","zh":"请关好水龙头。","pinyin":"Qǐng guān hǎo shuǐlóngtóu.","vi":"Vui lòng khóa vòi nước cẩn thận."},{"type":"simple","zh":"厨房的水龙头漏了一整夜的水。","pinyin":"Chúfáng de shuǐlóngtóu lòule yì zhěngyè de shuǐ.","vi":"Vòi nước trong bếp rò rỉ cả đêm."},{"type":"compound","zh":"如果水龙头一直滴水，就要赶紧找人来修理。","pinyin":"Rúguǒ shuǐlóngtóu yìzhí dīshuǐ, jiùyào gǎnjǐn zhǎo rén lái xiūlǐ.","vi":"Nếu vòi nước cứ nhỏ giọt mãi thì phải nhanh chóng gọi người đến sửa."}],"related":[{"hanzi":"自来水","pinyin":"zìláishuǐ","vi":"nước máy"},{"hanzi":"水管","pinyin":"shuǐguǎn","vi":"ống nước"},{"hanzi":"开关","pinyin":"kāiguān","vi":"công tắc, van"},{"hanzi":"漏水","pinyin":"lòushuǐ","vi":"rò nước"}],"traditional":"水龍頭"},{"id":"水乳交融","hanzi":"水乳交融","pinyin":"shuǐrǔ-jiāoróng","meaning_vi":"hòa quyện gắn bó khăng khít như nước với sữa","explanation":"Nước và sữa hòa lẫn vào nhau → quan hệ hòa hợp, gắn bó khăng khít.","hsk_level":6,"tags":["thanh-ngu"],"image":"🥛","examples":[{"type":"basic","zh":"两种文化水乳交融。","pinyin":"Liǎng zhǒng wénhuà shuǐrǔjiāoróng.","vi":"Hai nền văn hóa hòa quyện khăng khít với nhau."},{"type":"simple","zh":"这家店的中西菜式搭配得水乳交融。","pinyin":"Zhè jiā diàn de Zhōngxī càishì dāpèi de shuǐrǔjiāoróng.","vi":"Món Âu và món Hoa ở quán này được kết hợp hòa quyện với nhau."},{"type":"compound","zh":"因为他们合作了十年，所以配合得水乳交融。","pinyin":"Yīnwèi tāmen hézuòle shí nián, suǒyǐ pèihé de shuǐrǔjiāoróng.","vi":"Vì họ đã hợp tác mười năm nên phối hợp với nhau vô cùng ăn ý."}],"related":[{"hanzi":"融洽","pinyin":"róngqià","vi":"hòa hợp"},{"hanzi":"亲密无间","pinyin":"qīnmìwújiàn","vi":"thân thiết khăng khít"},{"hanzi":"格格不入","pinyin":"gégébúrù","vi":"lạc lõng không hợp"},{"hanzi":"融为一体","pinyin":"róngwéiyìtǐ","vi":"hòa làm một"}]},{"id":"水土不服","hanzi":"水土不服","pinyin":"shuǐtǔ-bùfú","meaning_vi":"không hợp thủy thổ (lạ nước lạ cái)","explanation":"水土 (thủy thổ – khí hậu, đất nước) + 不服 (không quen) → cơ thể chưa thích nghi khí hậu, ăn uống nơi ở mới.","hsk_level":6,"tags":["thanh-ngu","du-lich"],"image":"🤒","examples":[{"type":"basic","zh":"他到北京后水土不服。","pinyin":"Tā dào Běijīng hòu shuǐtǔbùfú.","vi":"Anh ấy đến Bắc Kinh thì bị không hợp thủy thổ."},{"type":"simple","zh":"刚到广州那几天，我有点水土不服。","pinyin":"Gāng dào Guǎngzhōu nà jǐtiān, wǒ yǒudiǎn shuǐtǔbùfú.","vi":"Mấy ngày mới đến Quảng Châu, tôi hơi bị lạ nước lạ cái."},{"type":"compound","zh":"一到新地方，孩子就水土不服，还拉肚子。","pinyin":"Yí dào xīn dìfang, háizi jiù shuǐtǔbùfú, hái lādùzi.","vi":"Cứ đến nơi mới là đứa bé lại không hợp thủy thổ, còn bị tiêu chảy."}],"related":[{"hanzi":"不适应","pinyin":"búshìyìng","vi":"không thích nghi"},{"hanzi":"适应","pinyin":"shìyìng","vi":"thích nghi"},{"hanzi":"入乡随俗","pinyin":"rùxiāngsuísú","vi":"nhập gia tùy tục"},{"hanzi":"气候","pinyin":"qìhòu","vi":"khí hậu"}]},{"id":"善罢甘休","hanzi":"善罢甘休","pinyin":"shànbà-gānxiū","meaning_vi":"dễ dàng bỏ qua (thường dùng phủ định: 不肯善罢甘休)","explanation":"善罢 (êm thấm dừng lại) + 甘休 (cam lòng thôi) → chịu bỏ qua cho êm; thường dùng phủ định: 决不善罢甘休 (quyết không để yên).","hsk_level":6,"tags":["thanh-ngu"],"image":"😠","examples":[{"type":"basic","zh":"他绝不会善罢甘休。","pinyin":"Tā juébú huì shànbàgānxiū.","vi":"Anh ta tuyệt đối sẽ không dễ dàng bỏ qua."},{"type":"simple","zh":"邻居半夜被吵醒后不肯善罢甘休。","pinyin":"Línjū bànyè bèi chǎoxǐng hòu bùkěn shànbàgānxiū.","vi":"Người hàng xóm bị đánh thức lúc nửa đêm nên không chịu bỏ qua dễ dàng."},{"type":"compound","zh":"如果你今天不当面道歉，她就不会善罢甘休。","pinyin":"Rúguǒ nǐ jīntiān bù dāngmiàn dàoqiàn, tā jiù bú huì shànbàgānxiū.","vi":"Nếu hôm nay bạn không xin lỗi trực tiếp thì cô ấy sẽ không dễ dàng bỏ qua đâu."}],"related":[{"hanzi":"罢休","pinyin":"bàxiū","vi":"thôi, chịu dừng"},{"hanzi":"罢手","pinyin":"bàshǒu","vi":"dừng tay"},{"hanzi":"不依不饶","pinyin":"bùyībùráo","vi":"không buông tha"},{"hanzi":"善了","pinyin":"shànliǎo","vi":"giải quyết êm"}],"traditional":"善罷甘休"},{"id":"擅长","hanzi":"擅长","pinyin":"shàncháng","meaning_vi":"giỏi về, sở trường về","explanation":"善 (giỏi) + 长 (điểm mạnh).","hsk_level":6,"tags":["dong-tu"],"image":"🌟","examples":[{"type":"basic","zh":"她擅长画油画。","pinyin":"Tā shàncháng huà yóuhuà.","vi":"Cô ấy giỏi vẽ tranh sơn dầu."},{"type":"simple","zh":"我的同事特别擅长跟客户谈价格。","pinyin":"Wǒ de tóngshì tèbié shàncháng gēn kèhù tán jiàgé.","vi":"Đồng nghiệp của tôi đặc biệt giỏi đàm phán giá với khách hàng."},{"type":"compound","zh":"他虽然擅长数学，但是作文写得很一般。","pinyin":"Tā suīrán shàncháng shùxué, dànshì zuòwén xiě de hěn yìbān.","vi":"Cậu ấy tuy giỏi toán nhưng viết văn chỉ ở mức bình thường."}],"related":[{"hanzi":"善于","pinyin":"shànyú","vi":"giỏi về"},{"hanzi":"拿手","pinyin":"náshǒu","vi":"sở trường"},{"hanzi":"精通","pinyin":"jīngtōng","vi":"tinh thông"},{"hanzi":"不擅长","pinyin":"búshàncháng","vi":"không giỏi"}],"traditional":"擅長"},{"id":"善始善终","hanzi":"善始善终","pinyin":"shànshǐ-shànzhōng","meaning_vi":"có đầu có cuối, làm việc trọn vẹn","explanation":"善 (thiện – tốt) 始 (thủy – đầu) 善 终 (chung – cuối) → bắt đầu tốt, kết thúc tốt; làm việc trọn vẹn đến cùng.","hsk_level":6,"tags":["thanh-ngu"],"image":"🏁","examples":[{"type":"basic","zh":"做事要善始善终。","pinyin":"Zuòshì yào shànshǐshànzhōng.","vi":"Làm việc phải có đầu có cuối."},{"type":"simple","zh":"老员工离职前把交接工作做得善始善终。","pinyin":"Lǎo yuángōng lízhí qián bǎ jiāojiē gōngzuò zuò de shànshǐshànzhōng.","vi":"Nhân viên lâu năm trước khi nghỉ việc đã bàn giao công việc rất trọn vẹn."},{"type":"compound","zh":"既然答应了负责这个项目，就要善始善终。","pinyin":"Jìrán dāyingle fùzé zhè ge xiàngmù, jiùyào shànshǐshànzhōng.","vi":"Đã nhận phụ trách dự án này thì phải làm đến nơi đến chốn."}],"related":[{"hanzi":"有始有终","pinyin":"yǒushǐyǒuzhōng","vi":"có đầu có cuối"},{"hanzi":"虎头蛇尾","pinyin":"hǔtóushéwěi","vi":"đầu voi đuôi chuột"},{"hanzi":"半途而废","pinyin":"bàntú'érfèi","vi":"bỏ dở giữa chừng"},{"hanzi":"始终如一","pinyin":"shǐzhōngrúyī","vi":"trước sau như một"}],"traditional":"善始善終"},{"id":"善意","hanzi":"善意","pinyin":"shànyì","meaning_vi":"thiện ý, ý tốt","explanation":"善 (tốt) + 意 (ý nghĩ). Đối nghĩa với 恶意 (ác ý).","hsk_level":6,"tags":["danh-tu","tinh-tu"],"image":"💖","examples":[{"type":"basic","zh":"谢谢你的善意。","pinyin":"Xièxie nǐ de shànyì.","vi":"Cảm ơn ý tốt của bạn."},{"type":"simple","zh":"老人善意地提醒我钱包没拉好。","pinyin":"Lǎorén shànyì de tíxǐng wǒ qiánbāo méi lā hǎo.","vi":"Cụ già có ý tốt nhắc tôi rằng ví chưa kéo khóa."},{"type":"compound","zh":"班长的批评虽然不好听，但是完全出于善意。","pinyin":"Bānzhǎng de pīpíng suīrán bù hǎotīng, dànshì wánquán chūyú shànyì.","vi":"Lời phê bình của lớp trưởng tuy khó nghe nhưng hoàn toàn xuất phát từ thiện ý."}],"related":[{"hanzi":"好意","pinyin":"hǎoyì","vi":"ý tốt"},{"hanzi":"恶意","pinyin":"èyì","vi":"ác ý"},{"hanzi":"善良","pinyin":"shànliáng","vi":"lương thiện"},{"hanzi":"诚意","pinyin":"chéngyì","vi":"thành ý"}]},{"id":"上进心","hanzi":"上进心","pinyin":"shàngjìnxīn","meaning_vi":"tinh thần cầu tiến","explanation":"上进 (thượng tiến – vươn lên) + 心 (tâm – lòng) → lòng muốn vươn lên, cầu tiến. Cụm: 有上进心.","hsk_level":6,"tags":["danh-tu","con-nguoi"],"image":"📈","examples":[{"type":"basic","zh":"这孩子很有上进心。","pinyin":"Zhè háizi hěn yǒu shàngjìnxīn.","vi":"Đứa trẻ này rất có tinh thần cầu tiến."},{"type":"simple","zh":"小王的上进心让领导很欣赏。","pinyin":"Xiǎo Wáng de shàngjìnxīn ràng lǐngdǎo hěn xīnshǎng.","vi":"Tinh thần cầu tiến của Tiểu Vương khiến lãnh đạo rất tán thưởng."},{"type":"compound","zh":"只要年轻人有上进心，就不怕学历和起点低。","pinyin":"Zhǐyào niánqīngrén yǒu shàngjìnxīn, jiù bú pà xuélì hé qǐdiǎn dī.","vi":"Chỉ cần người trẻ có tinh thần cầu tiến thì không sợ bằng cấp và xuất phát điểm thấp."}],"related":[{"hanzi":"进取心","pinyin":"jìnqǔxīn","vi":"tinh thần tiến thủ"},{"hanzi":"上进","pinyin":"shàngjìn","vi":"cầu tiến"},{"hanzi":"积极","pinyin":"jījí","vi":"tích cực"},{"hanzi":"不思进取","pinyin":"bùsījìnqǔ","vi":"không chịu tiến thủ"}],"traditional":"上進心"},{"id":"上级","hanzi":"上级","pinyin":"shàngjí","meaning_vi":"cấp trên","explanation":"上 (trên) + 级 (cấp bậc). Đối nghĩa với 下级 (cấp dưới).","hsk_level":6,"tags":["danh-tu","cong-viec","con-nguoi"],"image":"👔","examples":[{"type":"basic","zh":"我得先问问上级。","pinyin":"Wǒ děi xiān wèn wen shàngjí.","vi":"Tôi phải hỏi cấp trên trước đã."},{"type":"simple","zh":"上级要求我们周五前交报告。","pinyin":"Shàngjí yāoqiú wǒmen Zhōuwǔ qián jiāo bàogào.","vi":"Cấp trên yêu cầu chúng tôi nộp báo cáo trước thứ Sáu."},{"type":"compound","zh":"因为上级没批准，所以这次出差取消了。","pinyin":"Yīnwèi shàngjí méi pīzhǔn, suǒyǐ zhè cì chūchāi qǔxiāo le.","vi":"Vì cấp trên không phê duyệt nên chuyến công tác lần này bị hủy."}],"related":[{"hanzi":"下级","pinyin":"xiàjí","vi":"cấp dưới"},{"hanzi":"领导","pinyin":"lǐngdǎo","vi":"lãnh đạo"},{"hanzi":"上司","pinyin":"shàngsi","vi":"cấp trên"},{"hanzi":"同级","pinyin":"tóngjí","vi":"cùng cấp"}],"traditional":"上級"},{"id":"尚且","hanzi":"尚且","pinyin":"shàngqiě","meaning_vi":"huống chi, còn (dùng trong câu nhấn mạnh)","explanation":"尚 + 且. Thường đi với 何况.","hsk_level":6,"tags":["lien-tu"],"image":"➕","examples":[{"type":"basic","zh":"大人尚且搬不动。","pinyin":"Dàrén shàngqiě bān budòng.","vi":"Người lớn còn không khiêng nổi."},{"type":"simple","zh":"这道题连老师尚且要想半天。","pinyin":"Zhè dào tí lián lǎoshī shàngqiě yào xiǎng bàn tiān.","vi":"Bài này đến thầy giáo còn phải nghĩ mãi."},{"type":"compound","zh":"专家尚且看不懂，何况我们这些外行呢？","pinyin":"Zhuānjiā shàngqiě kànbudǒng, hékuàng wǒmen zhèxiē wàiháng ne?","vi":"Chuyên gia còn không hiểu, huống chi những người ngoài nghề như chúng ta?"}],"related":[{"hanzi":"何况","pinyin":"hékuàng","vi":"huống hồ"},{"hanzi":"况且","pinyin":"kuàngqiě","vi":"huống chi"},{"hanzi":"连","pinyin":"lián","vi":"ngay cả"},{"hanzi":"甚至","pinyin":"shènzhì","vi":"thậm chí"}]},{"id":"上上下下","hanzi":"上上下下","pinyin":"shàngshàngxiàxià","meaning_vi":"trên dưới, khắp nơi, toàn thể","explanation":"Từ láy AABB.","hsk_level":6,"tags":["danh-tu","pho-tu"],"image":"🏢","examples":[{"type":"basic","zh":"全家上上下下都很开心。","pinyin":"Quánjiā shàngshàngxiàxià dōu hěn kāixīn.","vi":"Cả nhà trên dưới ai cũng rất vui."},{"type":"simple","zh":"公司上上下下都在忙着准备年会。","pinyin":"Gōngsī shàngshàngxiàxià dōu zài mángzhe zhǔnbèi niánhuì.","vi":"Toàn công ty trên dưới đều đang bận chuẩn bị tiệc tất niên."},{"type":"compound","zh":"虽然他把房子上上下下找了一遍，但还是没找到钥匙。","pinyin":"Suīrán tā bǎ fángzi shàngshàngxiàxià zhǎole yíbiàn, dàn háishì méi zhǎodào yàoshi.","vi":"Tuy anh ấy đã lục khắp nhà trên dưới một lượt nhưng vẫn không tìm thấy chìa khóa."}],"related":[{"hanzi":"全体","pinyin":"quántǐ","vi":"toàn thể"},{"hanzi":"里里外外","pinyin":"lǐlǐwàiwài","vi":"trong ngoài"},{"hanzi":"前前后后","pinyin":"qiánqiánhòuhòu","vi":"trước sau"},{"hanzi":"上下","pinyin":"shàngxià","vi":"trên dưới"}]},{"id":"上瘾","hanzi":"上瘾","pinyin":"shàngyǐn","meaning_vi":"nghiện (game/cà phê/mua sắm)","explanation":"上 + 瘾 (cơn nghiện).","hsk_level":6,"tags":["dong-tu"],"image":"🎮","examples":[{"type":"basic","zh":"玩手机容易上瘾。","pinyin":"Wán shǒujī róngyì shàngyǐn.","vi":"Chơi điện thoại dễ bị nghiện."},{"type":"simple","zh":"我喝了一个月咖啡，现在有点上瘾了。","pinyin":"Wǒ hēle yí gèyuè kāfēi, xiànzài yǒudiǎn shàngyǐn le.","vi":"Tôi uống cà phê một tháng, giờ hơi nghiện rồi."},{"type":"compound","zh":"这款游戏一玩就上瘾，所以我把它删了。","pinyin":"Zhè kuǎn yóuxì yì wán jiù shàngyǐn, suǒyǐ wǒ bǎ tā shān le.","vi":"Trò chơi này cứ chơi là nghiện nên tôi đã xóa nó đi."}],"related":[{"hanzi":"成瘾","pinyin":"chéngyǐn","vi":"nghiện"},{"hanzi":"网瘾","pinyin":"wǎngyǐn","vi":"nghiện mạng"},{"hanzi":"戒瘾","pinyin":"jièyǐn","vi":"cai nghiện"},{"hanzi":"沉迷","pinyin":"chénmí","vi":"đắm chìm"}],"traditional":"上癮"},{"id":"设法","hanzi":"设法","pinyin":"shèfǎ","meaning_vi":"tìm cách, nghĩ cách","explanation":"设 (lập) + 法 (phương pháp).","hsk_level":6,"tags":["dong-tu"],"image":"💡","examples":[{"type":"basic","zh":"我们设法联系他。","pinyin":"Wǒmen shèfǎ liánxì tā.","vi":"Chúng tôi tìm cách liên lạc với anh ấy."},{"type":"simple","zh":"消防员设法把小猫从树上救了下来。","pinyin":"Xiāofángyuán shèfǎ bǎ xiǎomāo cóng shù shang jiùle xiàlái.","vi":"Lính cứu hỏa tìm cách cứu chú mèo con từ trên cây xuống."},{"type":"compound","zh":"如果买房的钱不够，我就设法再向朋友借一点。","pinyin":"Rúguǒ mǎifáng de qián búgòu, wǒ jiù shèfǎ zài xiàng péngyou jiè yìdiǎn.","vi":"Nếu tiền mua nhà không đủ, tôi sẽ tìm cách vay thêm bạn bè một ít."}],"related":[{"hanzi":"想办法","pinyin":"xiǎngbànfǎ","vi":"nghĩ cách"},{"hanzi":"千方百计","pinyin":"qiānfāngbǎijì","vi":"tìm mọi cách"},{"hanzi":"尽力","pinyin":"jìnlì","vi":"cố hết sức"},{"hanzi":"无计可施","pinyin":"wújìkěshī","vi":"hết cách"}],"traditional":"設法"},{"id":"社区","hanzi":"社区","pinyin":"shèqū","meaning_vi":"khu dân cư, cộng đồng","explanation":"社 (xã hội) + 区 (khu vực).","hsk_level":6,"tags":["danh-tu","dia-diem","xa-hoi"],"image":"🏘️","examples":[{"type":"basic","zh":"我们社区很安静。","pinyin":"Wǒmen shèqū hěn ānjìng.","vi":"Khu dân cư của chúng tôi rất yên tĩnh."},{"type":"simple","zh":"社区周末组织老人免费体检。","pinyin":"Shèqū zhōumò zǔzhī lǎorén miǎnfèi tǐjiǎn.","vi":"Cuối tuần khu dân cư tổ chức khám sức khỏe miễn phí cho người già."},{"type":"compound","zh":"社区建了公园后，居民不但散步多了，而且关系更好了。","pinyin":"Shèqū jiànle gōngyuán hòu, jūmín búdàn sànbù duō le, érqiě guānxì gèng hǎo le.","vi":"Từ khi khu dân cư xây công viên, cư dân không chỉ đi dạo nhiều hơn mà quan hệ cũng tốt hơn."}],"related":[{"hanzi":"小区","pinyin":"xiǎoqū","vi":"khu dân cư"},{"hanzi":"居民","pinyin":"jūmín","vi":"cư dân"},{"hanzi":"邻居","pinyin":"línjū","vi":"hàng xóm"},{"hanzi":"社区服务","pinyin":"shèqūfúwù","vi":"dịch vụ cộng đồng"}],"traditional":"社區"},{"id":"摄氏度","hanzi":"摄氏度","pinyin":"Shèshìdù","meaning_vi":"độ C (°C)","explanation":"摄氏 (Celsius) + 度 (độ).","hsk_level":6,"tags":["luong-tu","khoa-hoc","thoi-tiet"],"image":"🌡️","examples":[{"type":"basic","zh":"今天三十五摄氏度。","pinyin":"Jīntiān sān shíwǔ Shèshìdù.","vi":"Hôm nay trời 35 độ C."},{"type":"simple","zh":"水在一百摄氏度时开始沸腾。","pinyin":"Shuǐ zài yī bǎi Shèshìdù shí kāishǐ fèiténg.","vi":"Nước bắt đầu sôi ở 100 độ C."},{"type":"compound","zh":"只要气温低于零摄氏度，湖面就会结冰。","pinyin":"Zhǐyào qìwēn dīyú líng Shèshìdù, húmiàn jiù huì jiébīng.","vi":"Chỉ cần nhiệt độ xuống dưới 0 độ C là mặt hồ sẽ đóng băng."}],"related":[{"hanzi":"温度","pinyin":"wēndù","vi":"nhiệt độ"},{"hanzi":"华氏度","pinyin":"Huáshìdù","vi":"độ F"},{"hanzi":"零下","pinyin":"língxià","vi":"âm độ"},{"hanzi":"气温","pinyin":"qìwēn","vi":"nhiệt độ không khí"}],"traditional":"攝氏度"},{"id":"设身处地","hanzi":"设身处地","pinyin":"shèshēn-chǔdì","meaning_vi":"đặt mình vào hoàn cảnh của người khác","explanation":"设身 (đặt mình) + 处地 (xử địa – ở vào chỗ) → đặt mình vào vị trí người khác mà suy nghĩ. Cụm: 设身处地为别人着想.","hsk_level":6,"tags":["thanh-ngu","giao-tiep"],"image":"🤗","examples":[{"type":"basic","zh":"请你设身处地想一想。","pinyin":"Qǐng nǐ shèshēnchǔdì xiǎng yi xiǎng.","vi":"Bạn hãy đặt mình vào hoàn cảnh đó mà nghĩ thử xem."},{"type":"simple","zh":"好医生会设身处地为病人着想。","pinyin":"Hǎo yīshēng huì shèshēnchǔdì wèi bìngrén zhuóxiǎng.","vi":"Bác sĩ giỏi sẽ đặt mình vào vị trí bệnh nhân để nghĩ cho họ."},{"type":"compound","zh":"如果你能设身处地替她考虑，就不会说这种话了。","pinyin":"Rúguǒ nǐ néng shèshēnchǔdì tì tā kǎolǜ, jiù bú huì shuō zhè zhǒng huà le.","vi":"Nếu bạn biết đặt mình vào vị trí của cô ấy thì đã không nói những lời như vậy."}],"related":[{"hanzi":"将心比心","pinyin":"jiāngxīnbǐxīn","vi":"suy bụng ta ra bụng người"},{"hanzi":"换位思考","pinyin":"huànwèisīkǎo","vi":"đặt mình vào vị trí người khác"},{"hanzi":"感同身受","pinyin":"gǎntóngshēnshòu","vi":"đồng cảm sâu sắc"},{"hanzi":"体谅","pinyin":"tǐliàng","vi":"thông cảm"}],"traditional":"設身處地"},{"id":"肾","hanzi":"肾","pinyin":"shèn","meaning_vi":"quả thận","explanation":"Cơ quan nội tạng.","hsk_level":6,"tags":["danh-tu","co-the","suc-khoe"],"image":"🩺","examples":[{"type":"basic","zh":"他的肾不太好。","pinyin":"Tā de shèn bú tài hǎo.","vi":"Thận của anh ấy không tốt lắm."},{"type":"simple","zh":"医生说多喝水对肾有好处。","pinyin":"Yīshēng shuō duō hēshuǐ duì shèn yǒu hǎochù.","vi":"Bác sĩ nói uống nhiều nước có lợi cho thận."},{"type":"compound","zh":"因为长期吃得太咸，所以他的肾出了问题。","pinyin":"Yīnwèi chángqī chī de tài xián, suǒyǐ tā de shèn chūle wèntí.","vi":"Vì lâu ngày ăn quá mặn nên thận của anh ấy có vấn đề."}],"related":[{"hanzi":"肾脏","pinyin":"shènzàng","vi":"thận"},{"hanzi":"肝","pinyin":"gān","vi":"gan"},{"hanzi":"肾结石","pinyin":"shènjiéshí","vi":"sỏi thận"},{"hanzi":"器官","pinyin":"qìguān","vi":"cơ quan nội tạng"}],"traditional":"腎"},{"id":"胜负","hanzi":"胜负","pinyin":"shèngfù","meaning_vi":"thắng thua","explanation":"胜 (thắng) + 负 (thua).","hsk_level":6,"tags":["danh-tu","the-thao"],"image":"🏆","examples":[{"type":"basic","zh":"胜负还很难说。","pinyin":"Shèngfù hái hěn nánshuō.","vi":"Thắng thua vẫn còn khó nói."},{"type":"simple","zh":"这场比赛的胜负取决于最后一球。","pinyin":"Zhè chǎng bǐsài de shèngfù qǔjuéyú zuìhòu yì qiú.","vi":"Thắng thua của trận đấu này phụ thuộc vào quả bóng cuối cùng."},{"type":"compound","zh":"与其太在乎胜负，不如好好享受比赛。","pinyin":"Yǔqí tài zàihu shèngfù, bùrú hǎohǎo xiǎngshòu bǐsài.","vi":"Thay vì quá để tâm thắng thua, chi bằng hãy tận hưởng trận đấu."}],"related":[{"hanzi":"输赢","pinyin":"shūyíng","vi":"thắng thua"},{"hanzi":"成败","pinyin":"chéngbài","vi":"thành bại"},{"hanzi":"胜利","pinyin":"shènglì","vi":"thắng lợi"},{"hanzi":"胜负难分","pinyin":"shèngfùnánfēn","vi":"khó phân thắng bại"}],"traditional":"勝負"},{"id":"盛名","hanzi":"盛名","pinyin":"shèngmíng","meaning_vi":"danh tiếng lẫy lừng","explanation":"盛 (lớn/thịnh) + 名 (tiếng tăm).","hsk_level":6,"tags":["danh-tu"],"image":"🌟","examples":[{"type":"basic","zh":"这家老店久负盛名。","pinyin":"Zhè jiālǎo diàn jiǔ fù shèngmíng.","vi":"Cửa hàng lâu đời này nổi tiếng từ lâu."},{"type":"simple","zh":"这位钢琴家在欧洲享有盛名。","pinyin":"Zhè wèi gāngqínjiā zài Ōuzhōu xiǎngyǒu shèngmíng.","vi":"Nghệ sĩ dương cầm này có danh tiếng lẫy lừng ở châu Âu."},{"type":"compound","zh":"这家餐厅虽然享有盛名，但是服务并不好。","pinyin":"Zhè jiā cāntīng suīrán xiǎngyǒu shèngmíng, dànshì fúwù bìngbù hǎo.","vi":"Nhà hàng này tuy danh tiếng lẫy lừng nhưng phục vụ lại chẳng tốt."}],"related":[{"hanzi":"名声","pinyin":"míngshēng","vi":"danh tiếng"},{"hanzi":"声誉","pinyin":"shēngyù","vi":"thanh danh"},{"hanzi":"久负盛名","pinyin":"jiǔfùshèngmíng","vi":"nổi tiếng lâu đời"},{"hanzi":"名气","pinyin":"míngqi","vi":"tiếng tăm"}]},{"id":"胜券在握","hanzi":"胜券在握","pinyin":"shèngquàn-zàiwò","meaning_vi":"nắm chắc phần thắng trong tay","explanation":"胜券 (vé thắng) + 在握 (nắm trong tay). Thành ngữ.","hsk_level":6,"tags":["thanh-ngu"],"image":"🏆","examples":[{"type":"basic","zh":"我们队胜券在握。","pinyin":"Wǒmen duì shèngquànzàiwò.","vi":"Đội chúng ta đã nắm chắc phần thắng."},{"type":"simple","zh":"领先二十分后，主队觉得胜券在握了。","pinyin":"Lǐngxiān èr shífēn hòu, zhǔduì juéde shèngquànzàiwò le.","vi":"Sau khi dẫn trước 20 điểm, đội chủ nhà cảm thấy đã nắm chắc phần thắng."},{"type":"compound","zh":"即使觉得胜券在握，我们也不能放松。","pinyin":"Jíshǐ juéde shèngquànzàiwò, wǒmen yě bù néng fàngsōng.","vi":"Dù cảm thấy đã nắm chắc phần thắng, chúng ta cũng không được lơ là."}],"related":[{"hanzi":"稳操胜券","pinyin":"wěncāoshèngquàn","vi":"nắm chắc phần thắng"},{"hanzi":"十拿九稳","pinyin":"shínájiǔwěn","vi":"chắc chín phần mười"},{"hanzi":"必胜","pinyin":"bìshèng","vi":"tất thắng"},{"hanzi":"胜算","pinyin":"shèngsuàn","vi":"khả năng thắng"}],"traditional":"勝券在握"},{"id":"盛气凌人","hanzi":"盛气凌人","pinyin":"shèngqì-língrén","meaning_vi":"kiêu ngạo hống hách lấn át người khác","explanation":"盛气 (khí thế hung hăng) + 凌人 (lấn át người) → kiêu căng hống hách, chèn ép người khác.","hsk_level":6,"tags":["thanh-ngu"],"image":"😤","examples":[{"type":"basic","zh":"他说话盛气凌人。","pinyin":"Tā shuōhuà shèngqìlíngrén.","vi":"Anh ta nói chuyện hống hách kiêu ngạo."},{"type":"simple","zh":"那位经理总是盛气凌人地训斥员工。","pinyin":"Nà wèi jīnglǐ zǒngshì shèngqìlíngrén de xùnchì yuángōng.","vi":"Vị giám đốc đó lúc nào cũng hống hách quát mắng nhân viên."},{"type":"compound","zh":"虽然她能力很强，但是盛气凌人的态度让人反感。","pinyin":"Suīrán tā nénglì hěn qiáng, dànshì shèngqìlíngrén de tàidù ràng rén fǎngǎn.","vi":"Tuy cô ấy rất có năng lực nhưng thái độ hống hách khiến người khác khó chịu."}],"related":[{"hanzi":"目中无人","pinyin":"mùzhōngwúrén","vi":"coi thường người khác"},{"hanzi":"咄咄逼人","pinyin":"duōduōbīrén","vi":"hống hách lấn người"},{"hanzi":"平易近人","pinyin":"píngyìjìnrén","vi":"dễ gần"},{"hanzi":"傲慢","pinyin":"àomàn","vi":"ngạo mạn"}],"traditional":"盛氣凌人"},{"id":"盛情","hanzi":"盛情","pinyin":"shèngqíng","meaning_vi":"thịnh tình, lòng nhiệt tình nồng hậu","explanation":"盛 + 情 (tình cảm).","hsk_level":6,"tags":["danh-tu","giao-tiep"],"image":"🤗","examples":[{"type":"basic","zh":"我们收到了他的盛情邀请。","pinyin":"Wǒmen shōudàole tā de shèngqíng yāoqǐng.","vi":"Chúng tôi đã nhận được lời mời nồng hậu của anh ấy."},{"type":"simple","zh":"感谢各位对代表团的盛情款待。","pinyin":"Gǎnxiè gèwèi duì dàibiǎotuán de shèngqíng kuǎndài.","vi":"Cảm ơn mọi người đã tiếp đón đoàn đại biểu một cách nồng hậu."},{"type":"compound","zh":"因为主人盛情难却，所以我又喝了一杯酒。","pinyin":"Yīnwèi zhǔrén shèngqíngnánquè, suǒyǐ wǒ yòu hēle yì bēi jiǔ.","vi":"Vì khó từ chối lòng nhiệt tình của chủ nhà nên tôi lại uống thêm một ly."}],"related":[{"hanzi":"热情","pinyin":"rèqíng","vi":"nhiệt tình"},{"hanzi":"盛情款待","pinyin":"shèngqíngkuǎndài","vi":"tiếp đãi nồng hậu"},{"hanzi":"好客","pinyin":"hàokè","vi":"hiếu khách"},{"hanzi":"盛情难却","pinyin":"shèngqíngnánquè","vi":"khó từ chối thịnh tình"}]},{"id":"舌战","hanzi":"舌战","pinyin":"shézhàn","meaning_vi":"khẩu chiến, tranh luận nảy lửa","explanation":"舌 (lưỡi) + 战 (chiến đấu).","hsk_level":6,"tags":["dong-tu","giao-tiep"],"image":"🗣️","examples":[{"type":"basic","zh":"双方舌战了一个小时。","pinyin":"Shuāngfāng shézhànle yí gè xiǎoshí.","vi":"Hai bên khẩu chiến suốt một tiếng đồng hồ."},{"type":"simple","zh":"辩论赛上两队选手展开了激烈的舌战。","pinyin":"Biànlùnsài shang liǎng duì xuǎnshǒu zhǎnkāile jīliè de shézhàn.","vi":"Tại cuộc thi tranh biện, tuyển thủ hai đội đã có một trận khẩu chiến nảy lửa."},{"type":"compound","zh":"会议一开始，两位部门经理就舌战起来。","pinyin":"Huìyì yì kāishǐ, liǎng wèi bùmén jīnglǐ jiù shézhàn qǐlái.","vi":"Cuộc họp vừa bắt đầu, hai trưởng phòng đã khẩu chiến với nhau."}],"related":[{"hanzi":"辩论","pinyin":"biànlùn","vi":"tranh luận"},{"hanzi":"争论","pinyin":"zhēnglùn","vi":"tranh cãi"},{"hanzi":"口才","pinyin":"kǒucái","vi":"tài ăn nói"},{"hanzi":"唇枪舌剑","pinyin":"chúnqiāngshéjiàn","vi":"đấu khẩu gay gắt"}],"traditional":"舌戰"},{"id":"神采飞扬","hanzi":"神采飞扬","pinyin":"shéncǎi-fēiyáng","meaning_vi":"tinh thần phấn chấn rạng ngời","explanation":"神采 (thần thái) + 飞扬 (bay bổng) → thần thái rạng rỡ, hăng hái phấn chấn.","hsk_level":6,"tags":["thanh-ngu"],"image":"🌟","examples":[{"type":"basic","zh":"他讲得神采飞扬。","pinyin":"Tā jiǎng de shéncǎifēiyáng.","vi":"Anh ấy nói say sưa, rạng ngời phấn chấn."},{"type":"simple","zh":"拿到冠军的她神采飞扬地走上领奖台。","pinyin":"Nádào guànjūn de tā shéncǎifēiyáng de zǒushàng lǐngjiǎngtái.","vi":"Giành chức vô địch, cô ấy phấn chấn rạng ngời bước lên bục nhận giải."},{"type":"compound","zh":"一谈到自己拍的摄影作品，他就神采飞扬。","pinyin":"Yì tándào zìjǐ pāi de shèyǐng zuòpǐn, tā jiù shéncǎifēiyáng.","vi":"Hễ nói đến những tác phẩm nhiếp ảnh mình chụp là anh ấy lại hào hứng rạng ngời."}],"related":[{"hanzi":"神采奕奕","pinyin":"shéncǎiyìyì","vi":"thần sắc rạng rỡ"},{"hanzi":"意气风发","pinyin":"yìqìfēngfā","vi":"hăng hái phấn chấn"},{"hanzi":"精神焕发","pinyin":"jīngshénhuànfā","vi":"tinh thần phấn chấn"},{"hanzi":"无精打采","pinyin":"wújīngdǎcǎi","vi":"uể oải"}],"traditional":"神采飛揚"},{"id":"神采奕奕","hanzi":"神采奕奕","pinyin":"shéncǎi-yìyì","meaning_vi":"thần sắc rạng rỡ, tràn đầy sức sống","explanation":"神采 (thần thái) + 奕奕 (dịch dịch – sáng rực) → thần sắc rạng rỡ, tinh thần phấn chấn tràn đầy sức sống.","hsk_level":6,"tags":["thanh-ngu"],"image":"🌟","examples":[{"type":"basic","zh":"爷爷神采奕奕。","pinyin":"Yéye shéncǎiyìyì.","vi":"Ông nội trông rạng rỡ đầy sức sống."},{"type":"simple","zh":"睡了个好觉，她早上看起来神采奕奕。","pinyin":"Shuìle ge hǎo jiào, tā zǎoshang kànqǐlái shéncǎiyìyì.","vi":"Ngủ một giấc ngon, buổi sáng cô ấy trông rạng rỡ tràn đầy sức sống."},{"type":"compound","zh":"虽然已经八十岁了，但是奶奶依然神采奕奕。","pinyin":"Suīrán yǐjīng bāshí suì le, dànshì nǎinai yīrán shéncǎiyìyì.","vi":"Tuy đã tám mươi tuổi nhưng bà vẫn rạng rỡ đầy sức sống."}],"related":[{"hanzi":"精神抖擞","pinyin":"jīngshendǒusǒu","vi":"tinh thần hăng hái"},{"hanzi":"容光焕发","pinyin":"róngguānghuànfā","vi":"mặt mày rạng rỡ"},{"hanzi":"神采飞扬","pinyin":"shéncǎifēiyáng","vi":"phấn chấn rạng ngời"},{"hanzi":"萎靡不振","pinyin":"wěimǐbúzhèn","vi":"uể oải bạc nhược"}]},{"id":"神机妙算","hanzi":"神机妙算","pinyin":"shénjī-miàosuàn","meaning_vi":"thần cơ diệu toán, tính toán tài tình","explanation":"神机 (thần cơ – mưu kế như thần) + 妙算 (diệu toán – tính toán khéo) → mưu tính tài tình, dự liệu chính xác; hay dùng nói về Gia Cát Lượng.","hsk_level":6,"tags":["thanh-ngu"],"image":"🧠","examples":[{"type":"basic","zh":"诸葛亮神机妙算。","pinyin":"Zhūgěliàng shénjīmiàosuàn.","vi":"Gia Cát Lượng tính toán như thần."},{"type":"simple","zh":"球迷都佩服教练的神机妙算。","pinyin":"Qiúmí dōu pèifú jiàoliàn de shénjīmiàosuàn.","vi":"Người hâm mộ đều khâm phục tài tính toán như thần của huấn luyện viên."},{"type":"compound","zh":"即使你神机妙算，也算不到天气会突然变化。","pinyin":"Jíshǐ nǐ shénjīmiàosuàn, yě suàn budào tiānqì huì tūrán biànhuà.","vi":"Dù bạn có tính toán như thần cũng không lường được thời tiết đột ngột thay đổi."}],"related":[{"hanzi":"足智多谋","pinyin":"zúzhìduōmóu","vi":"đa mưu túc trí"},{"hanzi":"料事如神","pinyin":"liàoshìrúshén","vi":"đoán việc như thần"},{"hanzi":"运筹帷幄","pinyin":"yùnchóuwéiwò","vi":"bày mưu tính kế"},{"hanzi":"智谋","pinyin":"zhìmóu","vi":"mưu trí"}],"traditional":"神機妙算"},{"id":"神情","hanzi":"神情","pinyin":"shénqíng","meaning_vi":"vẻ mặt, thần thái","explanation":"神 + 情 (tình cảm).","hsk_level":6,"tags":["danh-tu"],"image":"😊","examples":[{"type":"basic","zh":"她神情很紧张。","pinyin":"Tā shénqíng hěn jǐnzhāng.","vi":"Vẻ mặt cô ấy rất căng thẳng."},{"type":"simple","zh":"听到这个消息，父亲的神情变得严肃起来。","pinyin":"Tīngdào zhè ge xiāoxi, fùqīn de shénqíng biànde yánsù qǐlái.","vi":"Nghe tin này, vẻ mặt của bố trở nên nghiêm nghị."},{"type":"compound","zh":"他虽然嘴上说没事，但是神情显得很疲惫。","pinyin":"Tā suīrán zuǐ shang shuō méishì, dànshì shénqíng xiǎnde hěn píbèi.","vi":"Anh ấy tuy miệng nói không sao nhưng vẻ mặt trông rất mệt mỏi."}],"related":[{"hanzi":"表情","pinyin":"biǎoqíng","vi":"biểu cảm"},{"hanzi":"神色","pinyin":"shénsè","vi":"thần sắc"},{"hanzi":"神态","pinyin":"shéntài","vi":"thần thái"},{"hanzi":"面部表情","pinyin":"miànbùbiǎoqíng","vi":"nét mặt"}]},{"id":"神态","hanzi":"神态","pinyin":"shéntài","meaning_vi":"thần thái, dáng vẻ","explanation":"神 + 态 (thái độ).","hsk_level":6,"tags":["danh-tu"],"image":"🌟","examples":[{"type":"basic","zh":"这只猫神态悠闲。","pinyin":"Zhè zhī māo shéntài yōuxián.","vi":"Con mèo này có dáng vẻ thong thả."},{"type":"simple","zh":"画家把老人的神态画得栩栩如生。","pinyin":"Huàjiā bǎ lǎorén de shéntài huà de xǔxǔrúshēng.","vi":"Họa sĩ vẽ thần thái của ông lão sống động như thật."},{"type":"compound","zh":"他一上台就神态自若，好像一点也不紧张。","pinyin":"Tā yí shàngtái jiù shéntài zìruò, hǎoxiàng yìdiǎn yě bù jǐnzhāng.","vi":"Anh ấy vừa lên sân khấu đã điềm tĩnh tự nhiên, như thể không hề căng thẳng."}],"related":[{"hanzi":"神情","pinyin":"shénqíng","vi":"vẻ mặt"},{"hanzi":"姿态","pinyin":"zītài","vi":"tư thế"},{"hanzi":"举止","pinyin":"jǔzhǐ","vi":"cử chỉ"},{"hanzi":"神态自若","pinyin":"shéntàizìruò","vi":"thần thái tự nhiên"}],"traditional":"神態"},{"id":"神仙","hanzi":"神仙","pinyin":"shénxiān","meaning_vi":"thần tiên","explanation":"神 (thần) + 仙 (tiên) → thần tiên; nghĩa bóng người siêu phàm hoặc cuộc sống ung dung tự tại. Cụm: 神仙般的日子.","hsk_level":6,"tags":["danh-tu","van-hoa"],"image":"🧚","examples":[{"type":"basic","zh":"这里美得像神仙住的地方。","pinyin":"Zhèlǐ měi de xiàng shénxiān zhù de dìfang.","vi":"Nơi này đẹp như chốn thần tiên ở."},{"type":"simple","zh":"奶奶常给我讲神仙下凡的故事。","pinyin":"Nǎinai cháng gěi wǒ jiǎng shénxiān xiàfán de gùshi.","vi":"Bà thường kể cho tôi nghe chuyện thần tiên giáng trần."},{"type":"compound","zh":"退休后他既能钓鱼又能喝茶，过得比神仙还自在。","pinyin":"Tuìxiū hòu tā jì néng diàoyú yòu néng hēchá, guòde bǐ shénxiān hái zìzai.","vi":"Nghỉ hưu rồi, ông vừa được câu cá vừa được uống trà, sống còn thảnh thơi hơn cả thần tiên."}],"related":[{"hanzi":"仙女","pinyin":"xiānnǚ","vi":"tiên nữ"},{"hanzi":"神话","pinyin":"shénhuà","vi":"thần thoại"},{"hanzi":"天堂","pinyin":"tiāntáng","vi":"thiên đường"},{"hanzi":"妖怪","pinyin":"yāoguài","vi":"yêu quái"}]},{"id":"事半功倍","hanzi":"事半功倍","pinyin":"shìbàn-gōngbèi","meaning_vi":"làm một được hai, hiệu quả gấp bội","explanation":"事半功倍: việc chỉ một nửa, công gấp đôi (Mạnh Tử) → tốn ít sức mà hiệu quả lớn. Trái nghĩa 事倍功半.","hsk_level":6,"tags":["thanh-ngu","hoc-tap"],"image":"🚀","examples":[{"type":"basic","zh":"方法对了，事半功倍。","pinyin":"Fāngfǎ duìle, shìbàngōngbèi.","vi":"Đúng phương pháp thì hiệu quả gấp bội."},{"type":"simple","zh":"用思维导图复习能让学习事半功倍。","pinyin":"Yòng sīwéi dǎo tú fùxí néng ràng xuéxí shìbàngōngbèi.","vi":"Ôn tập bằng sơ đồ tư duy giúp việc học đạt hiệu quả gấp bội."},{"type":"compound","zh":"只要提前做好计划，工作就能事半功倍。","pinyin":"Zhǐyào tíqián zuò hǎo jìhuà, gōngzuò jiù néng shìbàngōngbèi.","vi":"Chỉ cần lên kế hoạch trước là công việc sẽ đạt hiệu quả gấp bội."}],"related":[{"hanzi":"事倍功半","pinyin":"shìbèigōngbàn","vi":"làm nhiều được ít"},{"hanzi":"高效","pinyin":"gāoxiào","vi":"hiệu quả cao"},{"hanzi":"一举两得","pinyin":"yìjǔliǎngdé","vi":"một công đôi việc"},{"hanzi":"效率","pinyin":"xiàolǜ","vi":"hiệu suất"}]},{"id":"事倍功半","hanzi":"事倍功半","pinyin":"shìbèi-gōngbàn","meaning_vi":"làm nhiều được ít, kém hiệu quả","explanation":"事倍功半: việc gấp đôi, công chỉ một nửa → bỏ nhiều sức mà hiệu quả ít. Trái nghĩa 事半功倍.","hsk_level":6,"tags":["thanh-ngu"],"image":"📉","examples":[{"type":"basic","zh":"这样做事倍功半。","pinyin":"Zhèyàng zuò shìbèigōngbàn.","vi":"Làm thế này tốn công mà ít hiệu quả."},{"type":"simple","zh":"死记硬背单词往往事倍功半。","pinyin":"Sǐjì yìng bèi dāncí wǎngwǎng shìbèigōngbàn.","vi":"Học vẹt từ vựng thường tốn nhiều công mà hiệu quả thấp."},{"type":"compound","zh":"如果不先弄清楚问题，就会事倍功半。","pinyin":"Rúguǒ bù xiān nòng qīngchu wèntí, jiù huì shìbèigōngbàn.","vi":"Nếu không làm rõ vấn đề trước thì sẽ làm nhiều mà được ít."}],"related":[{"hanzi":"事半功倍","pinyin":"shìbàngōngbèi","vi":"làm ít được nhiều"},{"hanzi":"徒劳无功","pinyin":"túláowúgōng","vi":"công cốc"},{"hanzi":"低效","pinyin":"dīxiào","vi":"hiệu quả thấp"},{"hanzi":"白费力气","pinyin":"báifèilìqi","vi":"phí công vô ích"}]},{"id":"势必","hanzi":"势必","pinyin":"shìbì","meaning_vi":"tất yếu sẽ, chắc chắn sẽ","explanation":"势 (thế trận) + 必 (ắt hẳn).","hsk_level":6,"tags":["pho-tu"],"image":"❗","examples":[{"type":"basic","zh":"这样势必失败。","pinyin":"Zhèyàng shìbì shībài.","vi":"Làm như vậy ắt sẽ thất bại."},{"type":"simple","zh":"连续下暴雨势必会影响今年的收成。","pinyin":"Liánxù xià bàoyǔ shìbì huì yǐngxiǎng jīnnián de shōucheng.","vi":"Mưa lớn liên tục ắt sẽ ảnh hưởng đến mùa màng năm nay."},{"type":"compound","zh":"如果油价继续上涨，物价就势必跟着涨。","pinyin":"Rúguǒ yóujià jìxù shàngzhǎng, wùjià jiù shìbì gēnzhe zhǎng.","vi":"Nếu giá xăng tiếp tục tăng thì vật giá chắc chắn sẽ tăng theo."}],"related":[{"hanzi":"必然","pinyin":"bìrán","vi":"tất nhiên"},{"hanzi":"必定","pinyin":"bìdìng","vi":"nhất định"},{"hanzi":"一定","pinyin":"yídìng","vi":"chắc chắn"},{"hanzi":"不可避免","pinyin":"bùkěbìmiǎn","vi":"không thể tránh khỏi"}],"traditional":"勢必"},{"id":"事不宜迟","hanzi":"事不宜迟","pinyin":"shìbù-yíchí","meaning_vi":"việc không nên chậm trễ","explanation":"事 (sự – việc) 不宜 (bất nghi – không nên) 迟 (trì – chậm) → việc gấp, phải làm ngay. Ví dụ: 事不宜迟，马上出发.","hsk_level":6,"tags":["thanh-ngu"],"image":"⚡","examples":[{"type":"basic","zh":"事不宜迟，马上出发！","pinyin":"Shìbùyíchí, mǎshàng chūfā!","vi":"Việc không nên chậm trễ, xuất phát ngay!"},{"type":"simple","zh":"外婆病危的消息让全家觉得事不宜迟。","pinyin":"Wàipó bìngwēi de xiāoxi ràng quánjiā juéde shìbùyíchí.","vi":"Tin bà ngoại nguy kịch khiến cả nhà thấy không thể chậm trễ."},{"type":"compound","zh":"既然机票已经订好了，事不宜迟，我们现在就收拾行李。","pinyin":"Jìrán jīpiào yǐjīng dìng hǎo le, shìbùyíchí, wǒmen xiànzài jiù shōushi xíngli.","vi":"Vé máy bay đã đặt rồi, việc không nên chậm trễ, chúng ta thu dọn hành lý ngay bây giờ."}],"related":[{"hanzi":"刻不容缓","pinyin":"kèbùrónghuǎn","vi":"không thể chậm trễ"},{"hanzi":"迫在眉睫","pinyin":"pòzàiméijié","vi":"cấp bách trước mắt"},{"hanzi":"赶紧","pinyin":"gǎnjǐn","vi":"nhanh lên"},{"hanzi":"从长计议","pinyin":"cóngchángjìyì","vi":"bàn bạc lâu dài"}],"traditional":"事不宜遲"},{"id":"适得其反","hanzi":"适得其反","pinyin":"shìdé-qífǎn","meaning_vi":"phản tác dụng, ngược lại mong muốn","explanation":"适 (thích – vừa vặn) 得 (đắc – được) 其反 (cái ngược lại) → kết quả lại đúng ngược với mong muốn; phản tác dụng.","hsk_level":6,"tags":["thanh-ngu"],"image":"↩️","examples":[{"type":"basic","zh":"催得太急适得其反。","pinyin":"Cuī de tài jí shìdéqífǎn.","vi":"Giục quá gấp lại phản tác dụng."},{"type":"simple","zh":"过度节食减肥往往适得其反。","pinyin":"Guòdù jiéshí jiǎnféi wǎngwǎng shìdéqífǎn.","vi":"Nhịn ăn quá mức để giảm cân thường phản tác dụng."},{"type":"compound","zh":"虽然他想安慰她，但是说出的话适得其反。","pinyin":"Suīrán tā xiǎng ānwèi tā, dànshì shuōchū dehuà shìdéqífǎn.","vi":"Tuy anh ấy muốn an ủi cô nhưng những lời nói ra lại phản tác dụng."}],"related":[{"hanzi":"事与愿违","pinyin":"shìyǔyuànwéi","vi":"trái với mong muốn"},{"hanzi":"南辕北辙","pinyin":"nányuánběizhé","vi":"đi ngược mục tiêu"},{"hanzi":"弄巧成拙","pinyin":"nòngqiǎochéngzhuō","vi":"khéo quá hóa vụng"},{"hanzi":"事半功倍","pinyin":"shìbàngōngbèi","vi":"làm ít được nhiều"}],"traditional":"適得其反"},{"id":"是非","hanzi":"是非","pinyin":"shìfēi","meaning_vi":"đúng sai, phải trái; thị phi, điều tiếng","explanation":"是 (đúng) + 非 (sai).","hsk_level":6,"tags":["danh-tu"],"image":"⚖️","examples":[{"type":"basic","zh":"他不分是非。","pinyin":"Tā bùfēn shìfēi.","vi":"Anh ta không phân biệt phải trái."},{"type":"simple","zh":"孩子从小就要懂得明辨是非。","pinyin":"Háizi cóngxiǎo jiùyào dǒngde míngbiàn shìfēi.","vi":"Trẻ con từ nhỏ phải biết phân biệt đúng sai."},{"type":"compound","zh":"她不但爱打听别人的事，而且喜欢搬弄是非。","pinyin":"Tā búdàn ài dǎting biérén de shì, érqiě xǐhuan bānnòngshìfēi.","vi":"Cô ta không chỉ thích dò hỏi chuyện người khác mà còn thích đơm đặt thị phi."}],"related":[{"hanzi":"对错","pinyin":"duìcuò","vi":"đúng sai"},{"hanzi":"是非分明","pinyin":"shìfēifēnmíng","vi":"phân rõ phải trái"},{"hanzi":"搬弄是非","pinyin":"bānnòngshìfēi","vi":"đặt điều thị phi"},{"hanzi":"颠倒是非","pinyin":"diāndǎoshìfēi","vi":"đảo lộn phải trái"}]},{"id":"事件","hanzi":"事件","pinyin":"shìjiàn","meaning_vi":"sự kiện, vụ việc","explanation":"事 (sự – việc) + 件 (kiện – vụ, cái) → sự việc, vụ việc có ảnh hưởng nhất định. Cụm: 突发事件, 历史事件.","hsk_level":6,"tags":["danh-tu"],"image":"📰","examples":[{"type":"basic","zh":"这起事件很严重。","pinyin":"Zhè qǐ shìjiàn hěn yánzhòng.","vi":"Vụ việc này rất nghiêm trọng."},{"type":"simple","zh":"警方正在调查昨晚的枪击事件。","pinyin":"Jǐngfāng zhèngzài diàochá zuówǎn de qiāngjī shìjiàn.","vi":"Cảnh sát đang điều tra vụ nổ súng tối qua."},{"type":"compound","zh":"这个事件一上网，就引起了大量讨论。","pinyin":"Zhè ge shìjiàn yí shàngwǎng, jiù yǐnqǐle dàliàng tǎolùn.","vi":"Vụ việc này vừa lên mạng đã gây ra rất nhiều tranh luận."}],"related":[{"hanzi":"事故","pinyin":"shìgù","vi":"sự cố"},{"hanzi":"事情","pinyin":"shìqing","vi":"sự việc"},{"hanzi":"突发事件","pinyin":"tūfāshìjiàn","vi":"sự kiện đột xuất"},{"hanzi":"案件","pinyin":"ànjiàn","vi":"vụ án"}]},{"id":"势均力敌","hanzi":"势均力敌","pinyin":"shìjūn-lìdí","meaning_vi":"ngang tài ngang sức, cân tài cân sức","explanation":"势 (thế) 均 (quân – đều) 力 (lực) 敌 (địch – ngang nhau) → thế lực đều nhau, sức mạnh ngang nhau, khó phân thắng bại.","hsk_level":6,"tags":["thanh-ngu","the-thao"],"image":"⚖️","examples":[{"type":"basic","zh":"两支球队势均力敌。","pinyin":"Liǎng zhī qiúduì shìjūnlìdí.","vi":"Hai đội bóng ngang tài ngang sức."},{"type":"simple","zh":"决赛中两位棋手下得势均力敌。","pinyin":"Juésài zhōng liǎng wèi qí shǒuxià de shìjūnlìdí.","vi":"Trong trận chung kết, hai kỳ thủ đánh cờ ngang tài ngang sức."},{"type":"compound","zh":"因为双方势均力敌，所以比赛一直打到了加时赛。","pinyin":"Yīnwèi shuāngfāng shìjūnlìdí, suǒyǐ bǐsài yìzhí dǎ dàole jiāshísài.","vi":"Vì hai bên ngang tài ngang sức nên trận đấu kéo dài đến tận hiệp phụ."}],"related":[{"hanzi":"旗鼓相当","pinyin":"qígǔxiāngdāng","vi":"ngang tài ngang sức"},{"hanzi":"不相上下","pinyin":"bùxiāngshàngxià","vi":"ngang ngửa"},{"hanzi":"寡不敌众","pinyin":"guǎbùdízhòng","vi":"ít không địch nổi nhiều"},{"hanzi":"悬殊","pinyin":"xuánshū","vi":"chênh lệch lớn"}],"traditional":"勢均力敵"},{"id":"适量","hanzi":"适量","pinyin":"shìliàng","meaning_vi":"vừa phải, liều lượng thích hợp","explanation":"适 (vừa) + 量 (lượng).","hsk_level":6,"tags":["tinh-tu","suc-khoe"],"image":"💊","examples":[{"type":"basic","zh":"请适量饮酒。","pinyin":"Qǐng shìliàng yǐnjiǔ.","vi":"Xin hãy uống rượu vừa phải."},{"type":"simple","zh":"炒菜时放适量的盐就够了。","pinyin":"Chǎocài shí fàng shìliàng de yán jiù gòu le.","vi":"Khi xào rau chỉ cần cho lượng muối vừa phải là đủ."},{"type":"compound","zh":"适量运动不但能减肥，而且能改善睡眠。","pinyin":"Shìliàng yùndòng búdàn néng jiǎnféi, érqiě néng gǎishàn shuìmián.","vi":"Vận động vừa phải không chỉ giúp giảm cân mà còn cải thiện giấc ngủ."}],"related":[{"hanzi":"适度","pinyin":"shìdù","vi":"vừa phải"},{"hanzi":"过量","pinyin":"guòliàng","vi":"quá liều"},{"hanzi":"少量","pinyin":"shǎoliàng","vi":"lượng nhỏ"},{"hanzi":"适当","pinyin":"shìdàng","vi":"thích đáng"}],"traditional":"適量"},{"id":"逝世","hanzi":"逝世","pinyin":"shìshì","meaning_vi":"qua đời, tạ thế (kính ngữ)","explanation":"逝 (trôi qua) + 世 (thế gian).","hsk_level":6,"tags":["dong-tu"],"image":"🕯️","examples":[{"type":"basic","zh":"老教授昨天逝世了。","pinyin":"Lǎo jiàoshòu zuótiān shìshì le.","vi":"Vị giáo sư già đã qua đời hôm qua."},{"type":"simple","zh":"这位著名作家于去年冬天在北京逝世。","pinyin":"Zhè wèi zhùmíng zuòjiā yú qùnián dōngtiān zài Běijīng shìshì.","vi":"Nhà văn nổi tiếng này đã tạ thế tại Bắc Kinh vào mùa đông năm ngoái."},{"type":"compound","zh":"虽然科学家已经逝世多年，但是他的理论仍然影响着我们。","pinyin":"Suīrán kēxuéjiā yǐjīng shìshì duōnián, dànshì tā de lǐlùn réngrán yǐngxiǎngzhe wǒmen.","vi":"Tuy nhà khoa học đã qua đời nhiều năm nhưng lý thuyết của ông vẫn ảnh hưởng đến chúng ta."}],"related":[{"hanzi":"去世","pinyin":"qùshì","vi":"qua đời"},{"hanzi":"死亡","pinyin":"sǐwáng","vi":"chết"},{"hanzi":"病逝","pinyin":"bìngshì","vi":"qua đời vì bệnh"},{"hanzi":"诞辰","pinyin":"dànchén","vi":"ngày sinh"}]},{"id":"世世代代","hanzi":"世世代代","pinyin":"shìshìdàidài","meaning_vi":"đời đời kiếp kiếp, qua nhiều thế hệ","explanation":"Từ láy AABB.","hsk_level":6,"tags":["pho-tu","thoi-gian","gia-dinh"],"image":"👨‍👩‍👧‍👦","examples":[{"type":"basic","zh":"他们世世代代住在这里。","pinyin":"Tāmen shìshìdàidài zhùzài zhèlǐ.","vi":"Họ đã sống ở đây qua bao đời nay."},{"type":"simple","zh":"这个村子世世代代以种茶为生。","pinyin":"Zhè ge cūnzi shìshìdàidài yǐ zhòng chá wéishēng.","vi":"Ngôi làng này đời đời sống bằng nghề trồng chè."},{"type":"compound","zh":"只要保护好这片森林，子孙就能世世代代受益。","pinyin":"Zhǐyào bǎohù hǎo zhè piàn sēnlín, zǐsūn jiù néng shìshìdàidài shòuyì.","vi":"Chỉ cần bảo vệ tốt khu rừng này thì con cháu sẽ được hưởng lợi đời đời."}],"related":[{"hanzi":"子子孙孙","pinyin":"zǐzǐsūnsūn","vi":"con cháu đời đời"},{"hanzi":"祖祖辈辈","pinyin":"zǔzǔbèibèi","vi":"bao đời tổ tiên"},{"hanzi":"代代相传","pinyin":"dàidàixiāngchuán","vi":"đời đời truyền lại"},{"hanzi":"历代","pinyin":"lìdài","vi":"các đời"}]},{"id":"世俗","hanzi":"世俗","pinyin":"shìsú","meaning_vi":"thế tục, thói đời","explanation":"世 (đời) + 俗 (tục lệ).","hsk_level":6,"tags":["danh-tu","xa-hoi"],"image":"🌍","examples":[{"type":"basic","zh":"他不在乎世俗的眼光。","pinyin":"Tā bú zàihu shìsú de yǎnguāng.","vi":"Anh ấy không bận tâm đến cái nhìn của thế tục."},{"type":"simple","zh":"很多人被世俗的成功标准束缚住了。","pinyin":"Hěn duō rén bèi shìsú de chénggōng biāozhǔn shùfù zhù le.","vi":"Rất nhiều người bị trói buộc bởi chuẩn mực thành công của thói đời."},{"type":"compound","zh":"她虽然出身富贵，但是一点也不世俗。","pinyin":"Tā suīrán chūshēn fùguì, dànshì yìdiǎn yě bú shìsú.","vi":"Cô ấy tuy xuất thân giàu sang nhưng không hề tầm thường thế tục."}],"related":[{"hanzi":"庸俗","pinyin":"yōngsú","vi":"tầm thường dung tục"},{"hanzi":"世俗眼光","pinyin":"shìsúyǎnguāng","vi":"con mắt thế tục"},{"hanzi":"超凡脱俗","pinyin":"chāofántuōsú","vi":"thoát tục"},{"hanzi":"习俗","pinyin":"xísú","vi":"tập tục"}]},{"id":"试探","hanzi":"试探","pinyin":"shìtàn","meaning_vi":"thăm dò (ý kiến/phản ứng)","explanation":"试 (thử) + 探 (dò xét).","hsk_level":6,"tags":["dong-tu"],"image":"🔍","examples":[{"type":"basic","zh":"他在试探我的态度。","pinyin":"Tā zài shìtàn wǒ de tàidù.","vi":"Anh ta đang thăm dò thái độ của tôi."},{"type":"simple","zh":"小李试探着问老板能不能涨工资。","pinyin":"Xiǎo Lǐ shìtànzhe wèn lǎobǎn néng bu néng zhǎng gōngzī.","vi":"Tiểu Lý dò hỏi ông chủ xem có thể tăng lương không."},{"type":"compound","zh":"我先试探一下她的口风，如果她同意，我们就去办。","pinyin":"Wǒ xiān shìtàn yíxià tā de kǒufēng, rúguǒ tā tóngyì, wǒmen jiù qù bàn.","vi":"Tôi sẽ thăm dò ý cô ấy trước, nếu cô ấy đồng ý thì chúng ta sẽ đi làm."}],"related":[{"hanzi":"探索","pinyin":"tànsuǒ","vi":"thăm dò, khám phá"},{"hanzi":"打探","pinyin":"dǎtàn","vi":"dò hỏi"},{"hanzi":"试探性","pinyin":"shìtànxìng","vi":"mang tính thăm dò"},{"hanzi":"摸底","pinyin":"mōdǐ","vi":"thăm dò tình hình"}],"traditional":"試探"},{"id":"世外桃源","hanzi":"世外桃源","pinyin":"shìwài-táoyuán","meaning_vi":"chốn bồng lai tiên cảnh (nơi yên bình tách biệt)","explanation":"Điển tích Đào Hoa Nguyên. Thành ngữ.","hsk_level":6,"tags":["thanh-ngu","thien-nhien"],"image":"🌸","examples":[{"type":"basic","zh":"这个小山村像世外桃源。","pinyin":"Zhè ge xiǎo shāncūn xiàng shìwàitáoyuán.","vi":"Ngôi làng nhỏ trên núi này như chốn bồng lai tiên cảnh."},{"type":"simple","zh":"退休后他想找个世外桃源安度晚年。","pinyin":"Tuìxiū hòu tā xiǎng zhǎo ge shìwàitáoyuán ān dù wǎnnián.","vi":"Nghỉ hưu rồi ông ấy muốn tìm một chốn yên bình tách biệt để an hưởng tuổi già."},{"type":"compound","zh":"这里虽然交通不便，但是安静得像世外桃源。","pinyin":"Zhèlǐ suīrán jiāotōng búbiàn, dànshì ānjìng de xiàng shìwàitáoyuán.","vi":"Nơi này tuy đi lại bất tiện nhưng yên tĩnh như chốn bồng lai."}],"related":[{"hanzi":"桃花源","pinyin":"táohuāyuán","vi":"đào nguyên"},{"hanzi":"人间天堂","pinyin":"rénjiāntiāntáng","vi":"thiên đường trần gian"},{"hanzi":"仙境","pinyin":"xiānjìng","vi":"tiên cảnh"},{"hanzi":"与世隔绝","pinyin":"yǔshìgéjué","vi":"cách biệt với thế giới"}]},{"id":"示威","hanzi":"示威","pinyin":"shìwēi","meaning_vi":"biểu tình, thị uy","explanation":"示 (bày tỏ) + 威 (uy lực).","hsk_level":6,"tags":["dong-tu","xa-hoi"],"image":"✊","examples":[{"type":"basic","zh":"工人们上街示威。","pinyin":"Gōngrénmen shàngjiē shìwēi.","vi":"Công nhân xuống đường biểu tình."},{"type":"simple","zh":"数千名市民在市政府门前示威。","pinyin":"Shù qiān míng shìmín zài shìzhèngfǔ ménqián shìwēi.","vi":"Hàng nghìn người dân biểu tình trước cửa trụ sở chính quyền thành phố."},{"type":"compound","zh":"那只狗一看见陌生人，就叫着向他示威。","pinyin":"Nà zhī gǒu yí kànjiàn mòshēngrén, jiù jiàozhe xiàng tā shìwēi.","vi":"Con chó đó vừa thấy người lạ là sủa lên thị uy."}],"related":[{"hanzi":"抗议","pinyin":"kàngyì","vi":"phản đối"},{"hanzi":"游行","pinyin":"yóuxíng","vi":"diễu hành"},{"hanzi":"示威游行","pinyin":"shìwēiyóuxíng","vi":"biểu tình tuần hành"},{"hanzi":"罢工","pinyin":"bàgōng","vi":"đình công"}]},{"id":"视线","hanzi":"视线","pinyin":"shìxiàn","meaning_vi":"tầm nhìn, ánh mắt","explanation":"视 (nhìn) + 线 (đường thẳng).","hsk_level":6,"tags":["danh-tu"],"image":"👁️","examples":[{"type":"basic","zh":"大树挡住了视线。","pinyin":"Dà shù dǎngzhùle shìxiàn.","vi":"Cái cây to che mất tầm nhìn."},{"type":"simple","zh":"她的视线一直没离开过舞台。","pinyin":"Tā de shìxiàn yìzhí méi líkāiguo wǔtái.","vi":"Ánh mắt cô ấy chưa từng rời khỏi sân khấu."},{"type":"compound","zh":"因为雾太大，所以司机的视线很模糊。","pinyin":"Yīnwèi wù tài dà, suǒyǐ sījī de shìxiàn hěn móhu.","vi":"Vì sương mù quá dày nên tầm nhìn của tài xế rất mờ."}],"related":[{"hanzi":"视野","pinyin":"shìyě","vi":"tầm nhìn"},{"hanzi":"目光","pinyin":"mùguāng","vi":"ánh mắt"},{"hanzi":"视力","pinyin":"shìlì","vi":"thị lực"},{"hanzi":"转移视线","pinyin":"zhuǎnyíshìxiàn","vi":"đánh lạc hướng"}],"traditional":"視線"},{"id":"事项","hanzi":"事项","pinyin":"shìxiàng","meaning_vi":"hạng mục, điều khoản cần lưu ý","explanation":"事 (sự – việc) + 项 (hạng – khoản, mục) → các khoản việc, mục việc cụ thể. Cụm: 注意事项 (những điều cần lưu ý).","hsk_level":6,"tags":["danh-tu"],"image":"📌","examples":[{"type":"basic","zh":"请注意以下事项。","pinyin":"Qǐng zhùyì yǐxià shìxiàng.","vi":"Xin lưu ý những điều sau đây."},{"type":"simple","zh":"考试的注意事项都写在准考证背面。","pinyin":"Kǎoshì de zhùyì shìxiàng dōu xiě zài zhǔnkǎozhèng bèimiàn.","vi":"Những điều cần lưu ý khi thi đều được ghi ở mặt sau thẻ dự thi."},{"type":"compound","zh":"会议讨论了三个事项，可是一个也没有决定。","pinyin":"Huìyì tǎolùnle sān gè shìxiàng, kěshì yí gè yě méiyǒu juédìng.","vi":"Cuộc họp đã thảo luận ba hạng mục nhưng không quyết được mục nào."}],"related":[{"hanzi":"注意事项","pinyin":"zhùyìshìxiàng","vi":"điều cần chú ý"},{"hanzi":"项目","pinyin":"xiàngmù","vi":"hạng mục"},{"hanzi":"条款","pinyin":"tiáokuǎn","vi":"điều khoản"},{"hanzi":"事宜","pinyin":"shìyí","vi":"công việc liên quan"}],"traditional":"事項"},{"id":"视野","hanzi":"视野","pinyin":"shìyě","meaning_vi":"tầm nhìn, tầm mắt","explanation":"视 + 野 (khoảng rộng). Cụm: 开阔视野.","hsk_level":6,"tags":["danh-tu","hoc-tap"],"image":"🔭","examples":[{"type":"basic","zh":"旅行能开阔视野。","pinyin":"Lǚxíng néng kāikuò shìyě.","vi":"Du lịch có thể mở rộng tầm nhìn."},{"type":"simple","zh":"站在山顶上，整座城市都进入了视野。","pinyin":"Zhàn zài shāndǐng shang, zhěng zuò chéngshì dōu jìnrùle shìyě.","vi":"Đứng trên đỉnh núi, cả thành phố đều thu vào tầm mắt."},{"type":"compound","zh":"多读书不但能增长知识，而且能拓宽视野。","pinyin":"Duō dúshū búdàn néng zēngzhǎng zhīshi, érqiě néng tuòkuān shìyě.","vi":"Đọc nhiều sách không chỉ tăng thêm kiến thức mà còn mở rộng tầm nhìn."}],"related":[{"hanzi":"眼界","pinyin":"yǎnjiè","vi":"tầm mắt"},{"hanzi":"开阔视野","pinyin":"kāikuòshìyě","vi":"mở rộng tầm nhìn"},{"hanzi":"视线","pinyin":"shìxiàn","vi":"tầm nhìn"},{"hanzi":"见识","pinyin":"jiànshi","vi":"kiến thức"}],"traditional":"視野"},{"id":"事与愿违","hanzi":"事与愿违","pinyin":"shìyǔ-yuànwéi","meaning_vi":"sự việc trái với ý muốn","explanation":"事 (sự việc) 与 (dữ – với) 愿 (nguyện – mong muốn) 违 (vi – trái) → sự việc diễn ra trái với mong muốn.","hsk_level":6,"tags":["thanh-ngu"],"image":"😔","examples":[{"type":"basic","zh":"可惜事与愿违。","pinyin":"Kěxī shìyǔyuànwéi.","vi":"Đáng tiếc là sự việc lại trái với mong muốn."},{"type":"simple","zh":"他想早点回家，结果事与愿违碰上了大堵车。","pinyin":"Tā xiǎng zǎodiǎn huíjiā, jiéguǒ shìyǔyuànwéi pèngshàngle dà dǔchē.","vi":"Anh ấy muốn về nhà sớm, nào ngờ trái ý lại gặp phải kẹt xe nặng."},{"type":"compound","zh":"虽然我们做了充分准备，但是事与愿违，比赛还是输了。","pinyin":"Suīrán wǒmen zuòle chōngfèn zhǔnbèi, dànshì shìyǔyuànwéi, bǐsài háishì shū le.","vi":"Tuy chúng tôi đã chuẩn bị kỹ nhưng mọi chuyện trái với mong muốn, vẫn thua trận."}],"related":[{"hanzi":"适得其反","pinyin":"shìdéqífǎn","vi":"phản tác dụng"},{"hanzi":"如愿以偿","pinyin":"rúyuànyǐcháng","vi":"đạt được ước nguyện"},{"hanzi":"天不遂人愿","pinyin":"tiān búsuì rén yuàn","vi":"trời không chiều lòng người"},{"hanzi":"心想事成","pinyin":"xīnxiǎngshìchéng","vi":"muốn gì được nấy"}],"traditional":"事與願違"},{"id":"视而不见","hanzi":"视而不见","pinyin":"shì'ér-bújiàn","meaning_vi":"nhìn mà như không thấy, làm ngơ","explanation":"视 (thị – nhìn) 而 不见 (không thấy) → nhìn mà như không thấy; cố tình làm ngơ hoặc không để ý.","hsk_level":6,"tags":["thanh-ngu"],"image":"🙈","examples":[{"type":"basic","zh":"他对错误视而不见。","pinyin":"Tā duì cuòwù shì'érbújiàn.","vi":"Anh ta làm ngơ trước sai lầm."},{"type":"simple","zh":"很多人对路边的垃圾视而不见。","pinyin":"Hěn duō rén duì lùbiān de lājī shì'érbújiàn.","vi":"Nhiều người nhìn rác bên đường mà như không thấy."},{"type":"compound","zh":"如果管理者对问题视而不见，公司就会出大事。","pinyin":"Rúguǒ guǎnlǐ zhě duì wèntí shì'érbújiàn, gōngsī jiù huì chū dàshì.","vi":"Nếu người quản lý làm ngơ trước vấn đề thì công ty sẽ gặp chuyện lớn."}],"related":[{"hanzi":"熟视无睹","pinyin":"shúshìwúdǔ","vi":"nhìn quen mà như không thấy"},{"hanzi":"置之不理","pinyin":"zhìzhībùlǐ","vi":"bỏ mặc"},{"hanzi":"充耳不闻","pinyin":"chōng'ěrbùwén","vi":"bịt tai làm ngơ"},{"hanzi":"视若无睹","pinyin":"shìruòwúdǔ","vi":"nhìn như không thấy"}],"traditional":"視而不見"},{"id":"时不时","hanzi":"时不时","pinyin":"shíbushí","meaning_vi":"thỉnh thoảng, thi thoảng","explanation":"时 (thời) 不 时 → khẩu ngữ: chốc chốc, thỉnh thoảng lại. Ví dụ: 他时不时看一下手机.","hsk_level":6,"tags":["pho-tu"],"image":"🕰️","examples":[{"type":"basic","zh":"他时不时看看手表。","pinyin":"Tā shíbushí kànkan shǒubiǎo.","vi":"Anh ấy thỉnh thoảng lại nhìn đồng hồ."},{"type":"simple","zh":"窗外时不时传来几声鸟叫。","pinyin":"Chuāng wài shíbushí chuánlái jǐ shēng niǎo jiào.","vi":"Ngoài cửa sổ thỉnh thoảng lại vọng vào vài tiếng chim hót."},{"type":"compound","zh":"虽然我们住得很远，但是时不时还会打个电话。","pinyin":"Suīrán wǒmen zhù de hěn yuǎn, dànshì shíbushí hái huì dǎ ge diànhuà.","vi":"Tuy chúng tôi sống xa nhau nhưng thi thoảng vẫn gọi điện cho nhau."}],"related":[{"hanzi":"时常","pinyin":"shícháng","vi":"thường xuyên"},{"hanzi":"偶尔","pinyin":"ǒu'ěr","vi":"thỉnh thoảng"},{"hanzi":"不时","pinyin":"bùshí","vi":"thỉnh thoảng"},{"hanzi":"有时候","pinyin":"yǒushíhou","vi":"có lúc"}],"traditional":"時不時"},{"id":"时常","hanzi":"时常","pinyin":"shícháng","meaning_vi":"thường xuyên","explanation":"时 + 常. Đồng nghĩa với 经常.","hsk_level":6,"tags":["pho-tu"],"image":"🔁","examples":[{"type":"basic","zh":"我时常想起老家。","pinyin":"Wǒ shícháng xiǎngqǐ lǎojiā.","vi":"Tôi thường nhớ về quê nhà."},{"type":"simple","zh":"这条路上时常发生交通事故。","pinyin":"Zhè tiáo lùshang shícháng fāshēng jiāotōng shìgù.","vi":"Trên con đường này thường xuyên xảy ra tai nạn giao thông."},{"type":"compound","zh":"因为工作太忙，所以他时常忘记吃午饭。","pinyin":"Yīnwèi gōngzuò tài máng, suǒyǐ tā shícháng wàngjì chī wǔfàn.","vi":"Vì công việc quá bận nên anh ấy thường quên ăn trưa."}],"related":[{"hanzi":"经常","pinyin":"jīngcháng","vi":"thường xuyên"},{"hanzi":"常常","pinyin":"chángcháng","vi":"thường"},{"hanzi":"往往","pinyin":"wǎngwǎng","vi":"thường hay"},{"hanzi":"偶尔","pinyin":"ǒu'ěr","vi":"thỉnh thoảng"}],"traditional":"時常"},{"id":"时过境迁","hanzi":"时过境迁","pinyin":"shíguò-jìngqiān","meaning_vi":"thời thế đổi thay, vật đổi sao dời","explanation":"时 (thời) 过 (quá – qua) 境 (cảnh – hoàn cảnh) 迁 (thiên – đổi) → thời gian trôi qua, hoàn cảnh đã đổi khác.","hsk_level":6,"tags":["thanh-ngu"],"image":"⏳","examples":[{"type":"basic","zh":"如今早已时过境迁。","pinyin":"Rújīn zǎoyǐ shíguòjìngqiān.","vi":"Bây giờ mọi thứ đã đổi thay từ lâu."},{"type":"simple","zh":"二十年后回到母校，他感到时过境迁。","pinyin":"Èrshí nián hòu huídào mǔxiào, tā gǎndào shíguòjìngqiān.","vi":"Hai mươi năm sau trở về trường cũ, anh ấy cảm thấy vật đổi sao dời."},{"type":"compound","zh":"虽然时过境迁，但是那段友谊她一直记在心里。","pinyin":"Suīrán shíguòjìngqiān, dànshì nà duàn yǒuyì tā yìzhí jì zài xīnlǐ.","vi":"Dù thời thế đã đổi thay nhưng tình bạn ấy cô vẫn luôn ghi nhớ trong lòng."}],"related":[{"hanzi":"物是人非","pinyin":"wùshìrénfēi","vi":"cảnh cũ người xưa đâu"},{"hanzi":"沧海桑田","pinyin":"cānghǎisāngtián","vi":"thương hải tang điền"},{"hanzi":"今非昔比","pinyin":"jīnfēixībǐ","vi":"nay đã khác xưa"},{"hanzi":"一成不变","pinyin":"yìchéngbúbiàn","vi":"không thay đổi"}],"traditional":"時過境遷"},{"id":"时光","hanzi":"时光","pinyin":"shíguāng","meaning_vi":"thời gian, năm tháng","explanation":"时 + 光 (ánh sáng).","hsk_level":6,"tags":["danh-tu","thoi-gian"],"image":"⏳","examples":[{"type":"basic","zh":"时光过得真快。","pinyin":"Shíguāng guòde zhēn kuài.","vi":"Thời gian trôi thật nhanh."},{"type":"simple","zh":"大学四年是我最快乐的时光。","pinyin":"Dàxué sì nián shì wǒ zuì kuàilè de shíguāng.","vi":"Bốn năm đại học là quãng thời gian vui vẻ nhất của tôi."},{"type":"compound","zh":"既然时光不能倒流，我们就要珍惜现在。","pinyin":"Jìrán shíguāng bù néng dàoliú, wǒmen jiùyào zhēnxī xiànzài.","vi":"Thời gian đã không thể quay ngược thì chúng ta phải trân trọng hiện tại."}],"related":[{"hanzi":"时间","pinyin":"shíjiān","vi":"thời gian"},{"hanzi":"岁月","pinyin":"suìyuè","vi":"năm tháng"},{"hanzi":"光阴","pinyin":"guāngyīn","vi":"thời gian"},{"hanzi":"时光飞逝","pinyin":"shíguāngfēishì","vi":"thời gian trôi nhanh"}],"traditional":"時光"},{"id":"实话实说","hanzi":"实话实说","pinyin":"shíhuà-shíshuō","meaning_vi":"nói thẳng nói thật","explanation":"实话 (thực thoại – lời thật) + 实说 (nói thật) → có sao nói vậy, nói thẳng nói thật. Thường đứng đầu câu: 实话实说，….","hsk_level":6,"tags":["thanh-ngu","giao-tiep"],"image":"🗣️","examples":[{"type":"basic","zh":"我就实话实说吧。","pinyin":"Wǒ jiù shíhuàshíshuō ba.","vi":"Vậy tôi nói thật luôn nhé."},{"type":"simple","zh":"面对记者，他决定实话实说。","pinyin":"Miànduì jìzhě, tā juédìng shíhuàshíshuō.","vi":"Trước các phóng viên, anh ấy quyết định nói thẳng nói thật."},{"type":"compound","zh":"与其编各种借口骗老师，不如干脆实话实说。","pinyin":"Yǔqí biān gèzhǒng jièkǒu piàn lǎoshī, bùrú gāncuì shíhuàshíshuō.","vi":"Thay vì bịa đủ thứ cớ để lừa thầy giáo, chi bằng cứ nói thẳng nói thật."}],"related":[{"hanzi":"实话","pinyin":"shíhuà","vi":"lời thật"},{"hanzi":"直言不讳","pinyin":"zhíyánbúhuì","vi":"nói thẳng không kiêng"},{"hanzi":"说谎","pinyin":"shuōhuǎng","vi":"nói dối"},{"hanzi":"坦白","pinyin":"tǎnbái","vi":"thẳng thắn"}],"traditional":"實話實說"},{"id":"实惠","hanzi":"实惠","pinyin":"shíhuì","meaning_vi":"thiết thực, có lợi, giá cả phải chăng","explanation":"实 (thực tế) + 惠 (lợi ích).","hsk_level":6,"tags":["tinh-tu","mua-sam"],"image":"💰","examples":[{"type":"basic","zh":"这家饭馆很实惠。","pinyin":"Zhè jiā fànguǎn hěn shíhuì.","vi":"Quán ăn này giá cả rất phải chăng."},{"type":"simple","zh":"超市周末的打折活动对顾客很实惠。","pinyin":"Chāoshì zhōumò de dǎzhé huódòng duì gùkè hěn shíhuì.","vi":"Chương trình giảm giá cuối tuần của siêu thị rất có lợi cho khách hàng."},{"type":"compound","zh":"这款手机既便宜又耐用，买起来很实惠。","pinyin":"Zhè kuǎn shǒujī jì piányi yòu nàiyòng, mǎi qǐlái hěn shíhuì.","vi":"Chiếc điện thoại này vừa rẻ vừa bền, mua rất đáng tiền."}],"related":[{"hanzi":"划算","pinyin":"huásuàn","vi":"đáng giá"},{"hanzi":"便宜","pinyin":"piányi","vi":"rẻ"},{"hanzi":"经济实惠","pinyin":"jīngjìshíhuì","vi":"kinh tế hợp lý"},{"hanzi":"物美价廉","pinyin":"wùměijiàlián","vi":"hàng tốt giá rẻ"}],"traditional":"實惠"},{"id":"识货","hanzi":"识货","pinyin":"shíhuò","meaning_vi":"sành hàng, biết nhìn hàng thật giả/tốt xấu","explanation":"识 (nhận biết) + 货 (hàng hóa). Động từ ly hợp.","hsk_level":6,"tags":["dong-tu","mua-sam"],"image":"🛍️","examples":[{"type":"basic","zh":"您可真识货啊！","pinyin":"Nín kě zhēn shíhuò a!","vi":"Ông đúng là sành hàng thật!"},{"type":"simple","zh":"老板夸我识货，一眼就挑中了好茶。","pinyin":"Lǎobǎn kuā wǒ shíhuò, yìyǎn jiù tiāo zhòngle hǎo chá.","vi":"Ông chủ khen tôi sành hàng, chỉ nhìn một cái là chọn trúng trà ngon."},{"type":"compound","zh":"如果你不识货，在古玩市场就很容易买到假玉。","pinyin":"Rúguǒ nǐ bù shíhuò, zài gǔwán shìchǎng jiù hěn róngyì mǎi dào jiǎ yù.","vi":"Nếu bạn không biết nhìn hàng thì ở chợ đồ cổ rất dễ mua phải ngọc giả."}],"related":[{"hanzi":"内行","pinyin":"nèiháng","vi":"người trong nghề"},{"hanzi":"眼光","pinyin":"yǎnguāng","vi":"con mắt nhìn"},{"hanzi":"行家","pinyin":"hángjia","vi":"người sành"},{"hanzi":"货真价实","pinyin":"huòzhēnjiàshí","vi":"hàng thật giá thật"}],"traditional":"識貨"},{"id":"拾金不昧","hanzi":"拾金不昧","pinyin":"shíjīn-búmèi","meaning_vi":"nhặt được của rơi trả người đánh mất","explanation":"拾金 (nhặt vàng) + 不昧 (không giấu). Thành ngữ.","hsk_level":6,"tags":["thanh-ngu"],"image":"🏅","examples":[{"type":"basic","zh":"司机拾金不昧。","pinyin":"Sījī shíjīnbúmèi.","vi":"Người tài xế nhặt được của rơi đem trả lại."},{"type":"simple","zh":"学校表扬了拾金不昧的小明。","pinyin":"Xuéxiào biǎoyángle shíjīnbúmèi de xiǎo míng.","vi":"Nhà trường khen ngợi bạn Tiểu Minh nhặt được của rơi trả người đánh mất."},{"type":"compound","zh":"保洁员捡到一个钱包，因为拾金不昧，所以受到了表扬。","pinyin":"Bǎojié yuán jiǎn dào yí gè qiánbāo, yīnwèi shíjīnbúmèi, suǒyǐ shòudàole biǎoyáng.","vi":"Nhân viên vệ sinh nhặt được một chiếc ví, vì trả lại cho người mất nên đã được khen ngợi."}],"related":[{"hanzi":"路不拾遗","pinyin":"lùbùshíyí","vi":"của rơi không ai nhặt"},{"hanzi":"诚实","pinyin":"chéngshí","vi":"thành thật"},{"hanzi":"见利忘义","pinyin":"jiànlìwàngyì","vi":"thấy lợi quên nghĩa"},{"hanzi":"失物招领","pinyin":"shīwùzhāolǐng","vi":"nhận lại đồ thất lạc"}]},{"id":"石榴","hanzi":"石榴","pinyin":"shíliu","meaning_vi":"quả lựu","explanation":"石 (thạch) + 榴 (lựu) → quả lựu; vốn gọi 安石榴, du nhập từ nước An Tức (Ba Tư) theo đường Tơ lụa.","hsk_level":6,"tags":["danh-tu","an-uong"],"image":"🍎","examples":[{"type":"basic","zh":"这个石榴很甜。","pinyin":"Zhè ge shíliu hěn tián.","vi":"Quả lựu này rất ngọt."},{"type":"simple","zh":"院子里的石榴树结满了红红的果子。","pinyin":"Yuànzi lǐ de shíliu shù jié mǎnle hóng hóng de guǒzi.","vi":"Cây lựu trong sân sai trĩu những quả đỏ au."},{"type":"compound","zh":"石榴虽然又甜又好吃，但是剥起来很麻烦。","pinyin":"Shíliu suīrán yòu tián yòu hǎochī, dànshì bāo qǐlái hěn máfan.","vi":"Lựu tuy vừa ngọt vừa ngon nhưng bóc rất phiền."}],"related":[{"hanzi":"水果","pinyin":"shuǐguǒ","vi":"trái cây"},{"hanzi":"葡萄","pinyin":"pútao","vi":"nho"},{"hanzi":"苹果","pinyin":"píngguǒ","vi":"táo"},{"hanzi":"柿子","pinyin":"shìzi","vi":"quả hồng"}]},{"id":"十全十美","hanzi":"十全十美","pinyin":"shíquán-shíměi","meaning_vi":"thập toàn thập mỹ, hoàn hảo không tì vết","explanation":"Mười phần đủ, mười phần đẹp → hoàn hảo không chê vào đâu được. Thường: 世上没有十全十美的事.","hsk_level":6,"tags":["thanh-ngu"],"image":"💎","examples":[{"type":"basic","zh":"世上没有十全十美的人。","pinyin":"Shìshang méiyǒu shíquánshíměi de rén.","vi":"Trên đời không có ai hoàn hảo cả."},{"type":"simple","zh":"这次婚礼办得十全十美。","pinyin":"Zhè cì hūnlǐ bàn de shíquánshíměi.","vi":"Lễ cưới lần này được tổ chức hoàn hảo không tì vết."},{"type":"compound","zh":"即使方案不是十全十美，我们也应该先试一试。","pinyin":"Jíshǐ fāng'àn bú shì shíquánshíměi, wǒmen yě yīnggāi xiān shìyishì.","vi":"Dù phương án chưa hoàn hảo, chúng ta cũng nên thử trước đã."}],"related":[{"hanzi":"完美无缺","pinyin":"wánměiwúquē","vi":"hoàn mỹ không khuyết"},{"hanzi":"尽善尽美","pinyin":"jìnshànjìnměi","vi":"tận thiện tận mỹ"},{"hanzi":"美中不足","pinyin":"měizhōngbùzú","vi":"vết gợn trong cái đẹp"},{"hanzi":"完美","pinyin":"wánměi","vi":"hoàn hảo"}]},{"id":"实事求是","hanzi":"实事求是","pinyin":"shíshì-qiúshì","meaning_vi":"thực sự cầu thị, tôn trọng sự thật khách quan","explanation":"Dựa vào sự thật mà tìm ra lẽ đúng (Hán thư) → tôn trọng thực tế, khách quan; phương châm quen thuộc trong chính trị Trung Quốc.","hsk_level":6,"tags":["thanh-ngu"],"image":"⚖️","examples":[{"type":"basic","zh":"做研究要实事求是。","pinyin":"Zuò yánjiū yào shíshìqiúshì.","vi":"Làm nghiên cứu phải tôn trọng sự thật."},{"type":"simple","zh":"这份报告实事求是地分析了销售下降的原因。","pinyin":"Zhè fèn bàogào shíshìqiúshì de fēnxīle xiāoshòu xiàjiàng de yuányīn.","vi":"Bản báo cáo này đã phân tích một cách khách quan nguyên nhân doanh số giảm."},{"type":"compound","zh":"只要实事求是地反映情况，领导就不会怪你。","pinyin":"Zhǐyào shíshìqiúshì de fǎnyìng qíngkuàng, lǐngdǎo jiù bú huì guài nǐ.","vi":"Chỉ cần phản ánh tình hình đúng sự thật thì lãnh đạo sẽ không trách bạn."}],"related":[{"hanzi":"脚踏实地","pinyin":"jiǎotàshídì","vi":"chân đạp đất thật"},{"hanzi":"客观","pinyin":"kèguān","vi":"khách quan"},{"hanzi":"弄虚作假","pinyin":"nòngxūzuòjiǎ","vi":"gian dối làm giả"},{"hanzi":"夸大其词","pinyin":"kuādàqící","vi":"nói quá sự thật"}],"traditional":"實事求是"},{"id":"实实在在","hanzi":"实实在在","pinyin":"shíshízàizài","meaning_vi":"chân thật, thực tế, thiết thực","explanation":"Từ láy AABB.","hsk_level":6,"tags":["tinh-tu"],"image":"✅","examples":[{"type":"basic","zh":"他是个实实在在的人。","pinyin":"Tā shì ge shíshízàizài de rén.","vi":"Anh ấy là người chân thật."},{"type":"simple","zh":"政府为村民办了几件实实在在的好事。","pinyin":"Zhèngfǔ wèi cūn mínbànle jǐ jiàn shíshízàizài de hǎoshì.","vi":"Chính quyền đã làm được mấy việc tốt thiết thực cho dân làng."},{"type":"compound","zh":"口号喊得再响也没用，不如做点实实在在的事。","pinyin":"Kǒuhào hǎn de zài xiǎng yě méiyòng, bùrú zuò diǎn shíshízàizài de shì.","vi":"Hô khẩu hiệu to đến mấy cũng vô ích, chi bằng làm chút việc thiết thực."}],"related":[{"hanzi":"实在","pinyin":"shízài","vi":"thật sự"},{"hanzi":"踏踏实实","pinyin":"tātāshíshí","vi":"chắc chắn vững vàng"},{"hanzi":"真真切切","pinyin":"zhēnzhēnqièqiè","vi":"chân thực rõ ràng"},{"hanzi":"虚情假意","pinyin":"xūqíngjiǎyì","vi":"giả dối"}],"traditional":"實實在在"},{"id":"实质","hanzi":"实质","pinyin":"shízhì","meaning_vi":"thực chất, bản chất","explanation":"实 (thực) + 质 (chất) → bản chất thực sự bên trong. Cụm: 问题的实质, 实质性进展.","hsk_level":6,"tags":["danh-tu"],"image":"🔍","examples":[{"type":"basic","zh":"这才是问题的实质。","pinyin":"Zhè cái shì wèntí de shízhì.","vi":"Đây mới là thực chất của vấn đề."},{"type":"simple","zh":"双方的谈判至今没有实质进展。","pinyin":"Shuāngfāng de tánpàn zhìjīn méiyǒu shízhì jìnzhǎn.","vi":"Cuộc đàm phán giữa hai bên đến nay chưa có tiến triển thực chất."},{"type":"compound","zh":"表面上是降价促销，实质上却是清理库存。","pinyin":"Biǎomiànshang shì jiàngjià cùxiāo, shízhìshang quèshì qīnglǐ kùcún.","vi":"Bề ngoài là giảm giá khuyến mãi, nhưng thực chất lại là thanh lý hàng tồn kho."}],"related":[{"hanzi":"本质","pinyin":"běnzhì","vi":"bản chất"},{"hanzi":"实质性","pinyin":"shízhìxìng","vi":"tính thực chất"},{"hanzi":"表面","pinyin":"biǎomiàn","vi":"bề mặt"},{"hanzi":"本质上","pinyin":"běnzhìshang","vi":"về bản chất"}],"traditional":"實質"},{"id":"十足","hanzi":"十足","pinyin":"shízú","meaning_vi":"đầy đủ, hoàn toàn, mười phần","explanation":"十 (mười) + 足 (đủ).","hsk_level":6,"tags":["tinh-tu"],"image":"💯","examples":[{"type":"basic","zh":"他信心十足。","pinyin":"Tā xìnxīn shízú.","vi":"Anh ấy tràn đầy tự tin."},{"type":"simple","zh":"这位演员的表演喜剧味十足。","pinyin":"Zhè wèi yǎnyuán de biǎoyǎn xǐjù wèi shízú.","vi":"Màn trình diễn của diễn viên này đậm chất hài."},{"type":"compound","zh":"他虽然年纪不大，但是干起活来劲头十足。","pinyin":"Tā suīrán niánjì búdà, dànshì gàn qǐ huó lái jìntóu shízú.","vi":"Cậu ấy tuy còn trẻ nhưng làm việc rất hăng hái."}],"related":[{"hanzi":"充足","pinyin":"chōngzú","vi":"đầy đủ"},{"hanzi":"信心十足","pinyin":"xìnxīnshízú","vi":"đầy tự tin"},{"hanzi":"完全","pinyin":"wánquán","vi":"hoàn toàn"},{"hanzi":"十分","pinyin":"shífēn","vi":"rất, vô cùng"}]},{"id":"受骗","hanzi":"受骗","pinyin":"shòupiàn","meaning_vi":"bị lừa","explanation":"受 (chịu) + 骗 (lừa gạt). Động từ ly hợp.","hsk_level":6,"tags":["dong-tu"],"image":"🤥","examples":[{"type":"basic","zh":"我差点受骗了。","pinyin":"Wǒ chàdiǎn shòupiàn le.","vi":"Tôi suýt nữa thì bị lừa."},{"type":"simple","zh":"很多老人在网上购物时受骗上当。","pinyin":"Hěn duō lǎorén zài wǎngshang gòuwù shí shòupiàn shàngdàng.","vi":"Nhiều người già bị lừa khi mua sắm trên mạng."},{"type":"compound","zh":"只要不随便点陌生链接，就不容易受骗。","pinyin":"Zhǐ yàobù suíbiàn diǎn mòshēng liànjiē, jiù bù róngyì shòupiàn.","vi":"Chỉ cần không tùy tiện nhấp vào đường link lạ thì sẽ khó bị lừa."}],"related":[{"hanzi":"上当","pinyin":"shàngdàng","vi":"mắc lừa"},{"hanzi":"被骗","pinyin":"bèipiàn","vi":"bị lừa"},{"hanzi":"骗子","pinyin":"piànzi","vi":"kẻ lừa đảo"},{"hanzi":"上当受骗","pinyin":"shàngdàngshòupiàn","vi":"bị mắc lừa"}],"traditional":"受騙"},{"id":"寿星","hanzi":"寿星","pinyin":"shòuxīng","meaning_vi":"cụ thọ, người sống lâu; người có sinh nhật (nhân vật chính bữa tiệc)","explanation":"寿 (tuổi thọ) + 星 (ngôi sao).","hsk_level":6,"tags":["danh-tu","van-hoa","con-nguoi"],"image":"🎂","examples":[{"type":"basic","zh":"今天你是寿星。","pinyin":"Jīntiān nǐ shì shòuxīng.","vi":"Hôm nay bạn là nhân vật chính của sinh nhật."},{"type":"simple","zh":"大家围着寿星唱起了生日歌。","pinyin":"Dàjiā wéizhe shòuxīng chàng qǐle shēngrì gē.","vi":"Mọi người quây quanh người mừng sinh nhật cùng hát bài chúc mừng sinh nhật."},{"type":"compound","zh":"村里的这位寿星已经一百零二岁，而且还能自己做饭。","pinyin":"Cūnlǐ de zhè wèi shòuxīng yǐjīng yī bǎi líng èr suì, érqiě hái néng zìjǐ zuòfàn.","vi":"Cụ thọ trong làng đã 102 tuổi mà vẫn còn tự nấu cơm được."}],"related":[{"hanzi":"生日","pinyin":"shēngrì","vi":"sinh nhật"},{"hanzi":"长寿","pinyin":"chángshòu","vi":"trường thọ"},{"hanzi":"寿命","pinyin":"shòumìng","vi":"tuổi thọ"},{"hanzi":"祝寿","pinyin":"zhùshòu","vi":"chúc thọ"}],"traditional":"壽星"},{"id":"竖","hanzi":"竖","pinyin":"shù","meaning_vi":"dựng đứng, dựng lên; thẳng đứng, dọc; nét sổ (chữ Hán)","explanation":"Đối nghĩa với 横 (ngang).","hsk_level":6,"tags":["dong-tu","tinh-tu","danh-tu"],"image":"⬇️","examples":[{"type":"basic","zh":"把箱子竖起来。","pinyin":"Bǎ xiāngzi shù qǐlái.","vi":"Dựng cái thùng đứng lên."},{"type":"simple","zh":"写“十”字时要先写横再写竖。","pinyin":"Xiě shí zì shí yào xiān xiě héng zài xiě shù.","vi":"Khi viết chữ \"thập\" phải viết nét ngang trước rồi mới viết nét sổ."},{"type":"compound","zh":"小狗一听到门外有动静，就竖起耳朵仔细听。","pinyin":"Xiǎogǒu yì tīngdào ménwài yǒu dòngjing, jiù shùqǐ ěrduo zǐxì tīng.","vi":"Chú chó con vừa nghe thấy động tĩnh ngoài cửa liền dựng tai lên nghe kỹ."}],"related":[{"hanzi":"横","pinyin":"héng","vi":"ngang, nét ngang"},{"hanzi":"竖立","pinyin":"shùlì","vi":"dựng đứng"},{"hanzi":"竖起","pinyin":"shùqǐ","vi":"giơ thẳng lên"},{"hanzi":"垂直","pinyin":"chuízhí","vi":"thẳng đứng"}],"traditional":"豎"},{"id":"树碑立传","hanzi":"树碑立传","pinyin":"shùbēi-lìzhuàn","meaning_vi":"dựng bia lập truyện, tâng bốc công lao","explanation":"Dựng bia đá, viết truyện ký → ca tụng công đức một người; nay thường mang nghĩa xấu: tâng bốc, đánh bóng tên tuổi.","hsk_level":6,"tags":["thanh-ngu"],"image":"🗿","examples":[{"type":"basic","zh":"他不想为自己树碑立传。","pinyin":"Tā bù xiǎng wèi zìjǐ shùbēilìzhuàn.","vi":"Ông ấy không muốn dựng bia lập truyện cho bản thân."},{"type":"simple","zh":"有些官员喜欢花公款给自己树碑立传。","pinyin":"Yǒuxiē guānyuán xǐhuan huā gōngkuǎn gěi zìjǐ shùbēilìzhuàn.","vi":"Có những quan chức thích tiêu tiền công để tâng bốc công lao của mình."},{"type":"compound","zh":"与其花钱树碑立传，不如多为百姓办实事。","pinyin":"Yǔqí huāqián shùbēilìzhuàn, bùrú duō wèi bǎixìng bàn shíshì.","vi":"Thay vì tốn tiền dựng bia lập truyện, chi bằng làm nhiều việc thiết thực cho dân."}],"related":[{"hanzi":"歌功颂德","pinyin":"gēgōngsòngdé","vi":"ca công tụng đức"},{"hanzi":"立传","pinyin":"lìzhuàn","vi":"lập truyện"},{"hanzi":"纪念碑","pinyin":"jìniànbēi","vi":"bia kỷ niệm"},{"hanzi":"吹捧","pinyin":"chuīpěng","vi":"tâng bốc"}],"traditional":"樹碑立傳"},{"id":"束手无策","hanzi":"束手无策","pinyin":"shùshǒu-wúcè","meaning_vi":"bó tay hết cách","explanation":"束手 (trói tay) + 无策 (không kế sách). Thành ngữ.","hsk_level":6,"tags":["thanh-ngu"],"image":"🤷‍♂️","examples":[{"type":"basic","zh":"医生也束手无策。","pinyin":"Yīshēng yě shùshǒuwúcè.","vi":"Bác sĩ cũng bó tay hết cách."},{"type":"simple","zh":"面对突然停电，工厂的技术员束手无策。","pinyin":"Miànduì tūrán tíngdiàn, gōngchǎng de jìshùyuán shùshǒuwúcè.","vi":"Trước sự cố mất điện đột ngột, kỹ thuật viên nhà máy đành bó tay."},{"type":"compound","zh":"如果电脑又中病毒，我就真的束手无策了。","pinyin":"Rúguǒ diànnǎo yòu zhòng bìngdú, wǒ jiù zhēn de shùshǒuwúcè le.","vi":"Nếu máy tính lại nhiễm virus thì tôi thật sự hết cách."}],"related":[{"hanzi":"无计可施","pinyin":"wújìkěshī","vi":"hết cách"},{"hanzi":"无可奈何","pinyin":"wúkěnàihé","vi":"không biết làm sao"},{"hanzi":"一筹莫展","pinyin":"yìchóumòzhǎn","vi":"không có cách nào"},{"hanzi":"胸有成竹","pinyin":"xiōngyǒuchéngzhú","vi":"đã có tính toán"}],"traditional":"束手無策"},{"id":"顺理成章","hanzi":"顺理成章","pinyin":"shùnlǐ-chéngzhāng","meaning_vi":"hợp tình hợp lý, lẽ đương nhiên","explanation":"顺理 (thuận lý – theo lẽ) + 成章 (thành chương – thành bài văn) → theo mạch lý mà viết thì thành văn → việc hợp lẽ, tất nhiên như vậy.","hsk_level":6,"tags":["thanh-ngu"],"image":"✅","examples":[{"type":"basic","zh":"这是顺理成章的事。","pinyin":"Zhè shì shùnlǐchéngzhāng de shì.","vi":"Đây là chuyện hợp tình hợp lý."},{"type":"simple","zh":"他工作出色，顺理成章地当上了主管。","pinyin":"Tā gōngzuò chūsè, shùnlǐchéngzhāng de dāngshàngle zhǔguǎn.","vi":"Anh ấy làm việc xuất sắc nên đương nhiên được lên làm trưởng nhóm."},{"type":"compound","zh":"既然两人感情这么好，结婚就顺理成章了。","pinyin":"Jìrán liǎng rén gǎnqíng zhème hǎo, jiéhūn jiù shùnlǐchéngzhāng le.","vi":"Hai người đã yêu nhau như vậy thì kết hôn là lẽ đương nhiên."}],"related":[{"hanzi":"理所当然","pinyin":"lǐsuǒdāngrán","vi":"lẽ đương nhiên"},{"hanzi":"水到渠成","pinyin":"shuǐdàoqúchéng","vi":"nước chảy thành sông"},{"hanzi":"自然而然","pinyin":"zìrán'érrán","vi":"tự nhiên mà thế"},{"hanzi":"合情合理","pinyin":"héqínghélǐ","vi":"hợp tình hợp lý"}],"traditional":"順理成章"},{"id":"顺其自然","hanzi":"顺其自然","pinyin":"shùnqí-zìrán","meaning_vi":"thuận theo tự nhiên","explanation":"顺 (thuận – theo) 其 (kỳ – nó) 自然 (tự nhiên) → để mọi việc diễn ra tự nhiên, không cưỡng cầu.","hsk_level":6,"tags":["thanh-ngu"],"image":"🍃","examples":[{"type":"basic","zh":"一切顺其自然吧。","pinyin":"Yíqiè shùnqízìrán ba.","vi":"Mọi thứ cứ thuận theo tự nhiên đi."},{"type":"simple","zh":"对于孩子的兴趣，父母应该顺其自然。","pinyin":"Duìyú háizi de xìngqù, fùmǔ yīnggāi shùnqízìrán.","vi":"Đối với sở thích của con cái, cha mẹ nên thuận theo tự nhiên."},{"type":"compound","zh":"与其整天担心考试结果，不如顺其自然。","pinyin":"Yǔqí zhěngtiān dānxīn kǎoshì jiéguǒ, bùrú shùnqízìrán.","vi":"Thay vì cả ngày lo lắng về kết quả thi, chi bằng cứ thuận theo tự nhiên."}],"related":[{"hanzi":"听天由命","pinyin":"tīngtiānyóumìng","vi":"phó mặc cho trời"},{"hanzi":"随遇而安","pinyin":"suíyù'ér'ān","vi":"tùy hoàn cảnh mà an"},{"hanzi":"强求","pinyin":"qiǎngqiú","vi":"cưỡng cầu"},{"hanzi":"自然","pinyin":"zìrán","vi":"tự nhiên"}],"traditional":"順其自然"},{"id":"顺水推舟","hanzi":"顺水推舟","pinyin":"shùnshuǐ-tuīzhōu","meaning_vi":"thuận nước đẩy thuyền (nương theo tình thế mà làm)","explanation":"Thuận dòng nước mà đẩy thuyền → nương theo tình thế có sẵn mà làm, tiện thể hành động.","hsk_level":6,"tags":["thanh-ngu"],"image":"🚣","examples":[{"type":"basic","zh":"他顺水推舟答应了。","pinyin":"Tā shùnshuǐtuīzhōu dāying le.","vi":"Anh ấy nương theo tình thế mà đồng ý luôn."},{"type":"simple","zh":"经理顺水推舟地把这个项目交给了小陈。","pinyin":"Jīnglǐ shùnshuǐtuīzhōu de bǎ zhè ge xiàngmù jiāogěile xiǎo Chén.","vi":"Giám đốc thuận nước đẩy thuyền giao luôn dự án này cho Tiểu Trần."},{"type":"compound","zh":"既然大家都提议去海边，我就顺水推舟定了酒店。","pinyin":"Jìrán dàjiā dōu tíyì qù hǎibiān, wǒ jiù shùnshuǐtuīzhōu dìngle jiǔdiàn.","vi":"Mọi người đều đề nghị đi biển nên tôi thuận nước đẩy thuyền đặt luôn khách sạn."}],"related":[{"hanzi":"顺势而为","pinyin":"shùnshì'érwéi","vi":"thuận thế mà làm"},{"hanzi":"因势利导","pinyin":"yīnshìlìdǎo","vi":"dẫn dắt theo tình thế"},{"hanzi":"逆水行舟","pinyin":"nìshuǐxíngzhōu","vi":"đi thuyền ngược nước"},{"hanzi":"借机","pinyin":"jièjī","vi":"nhân cơ hội"}],"traditional":"順水推舟"},{"id":"顺顺利利","hanzi":"顺顺利利","pinyin":"shùnshùnlìlì","meaning_vi":"thuận buồm xuôi gió, suôn sẻ","explanation":"Từ láy AABB.","hsk_level":6,"tags":["tinh-tu"],"image":"🍀","examples":[{"type":"basic","zh":"祝你一路顺顺利利！","pinyin":"Zhù nǐ yílù shùnshùnlìlì!","vi":"Chúc bạn thượng lộ bình an, mọi việc suôn sẻ!"},{"type":"simple","zh":"这次搬家顺顺利利地完成了。","pinyin":"Zhè cì bānjiā shùnshùnlìlì de wánchéng le.","vi":"Lần chuyển nhà này đã hoàn tất suôn sẻ."},{"type":"compound","zh":"只要准备充分，面试就会顺顺利利的。","pinyin":"Zhǐyào zhǔnbèi chōngfèn, miànshì jiù huì shùnshùnlìlì de.","vi":"Chỉ cần chuẩn bị đầy đủ thì buổi phỏng vấn sẽ suôn sẻ."}],"related":[{"hanzi":"顺利","pinyin":"shùnlì","vi":"thuận lợi"},{"hanzi":"一帆风顺","pinyin":"yìfānfēngshùn","vi":"thuận buồm xuôi gió"},{"hanzi":"平平安安","pinyin":"píngpíng'ān'ān","vi":"bình bình an an"},{"hanzi":"坎坷","pinyin":"kǎnkě","vi":"lận đận"}],"traditional":"順順利利"},{"id":"熟能生巧","hanzi":"熟能生巧","pinyin":"shúnéng-shēngqiǎo","meaning_vi":"trăm hay không bằng tay quen","explanation":"熟能 (quen thuộc) + 生巧 (sinh khéo léo). Thành ngữ.","hsk_level":6,"tags":["thanh-ngu","hoc-tap"],"image":"✨","examples":[{"type":"basic","zh":"熟能生巧嘛。","pinyin":"Shúnéngshēngqiǎo ma.","vi":"Trăm hay không bằng tay quen mà."},{"type":"simple","zh":"包饺子的手艺全靠熟能生巧。","pinyin":"Bāojiǎozi de shǒuyì quán kào shúnéngshēngqiǎo.","vi":"Tay nghề gói sủi cảo hoàn toàn nhờ làm nhiều thành quen."},{"type":"compound","zh":"刚开始打字很慢，但是熟能生巧，现在快多了。","pinyin":"Gāng kāishǐ dǎzì hěn màn, dànshì shúnéngshēngqiǎo, xiànzài kuài duō le.","vi":"Lúc đầu gõ chữ rất chậm, nhưng quen tay hay việc, giờ đã nhanh hơn nhiều."}],"related":[{"hanzi":"熟练","pinyin":"shúliàn","vi":"thành thạo"},{"hanzi":"勤学苦练","pinyin":"qínxuékǔliàn","vi":"chăm học khổ luyện"},{"hanzi":"炉火纯青","pinyin":"lúhuǒchúnqīng","vi":"điêu luyện"},{"hanzi":"生疏","pinyin":"shēngshū","vi":"lạ tay"}]},{"id":"杀鸡取卵","hanzi":"杀鸡取卵","pinyin":"shājī-qǔluǎn","meaning_vi":"giết gà lấy trứng (tham lợi trước mắt hại lợi lâu dài)","explanation":"Giết gà để lấy trứng → tham lợi trước mắt mà làm hỏng lợi ích lâu dài.","hsk_level":6,"tags":["thanh-ngu"],"image":"🐔","examples":[{"type":"basic","zh":"这是杀鸡取卵。","pinyin":"Zhè shì shājīqǔluǎn.","vi":"Đây là giết gà lấy trứng."},{"type":"simple","zh":"过度砍伐森林无异于杀鸡取卵。","pinyin":"Guòdù kǎnfá sēnlín wúyì yú shājīqǔluǎn.","vi":"Chặt phá rừng quá mức chẳng khác gì giết gà lấy trứng."},{"type":"compound","zh":"如果为了眼前利益乱涨价，就是杀鸡取卵。","pinyin":"Rúguǒ wèile yǎnqián lìyì luàn zhǎngjià, jiùshì shājīqǔluǎn.","vi":"Nếu vì lợi ích trước mắt mà tăng giá bừa bãi thì đó là giết gà lấy trứng."}],"related":[{"hanzi":"竭泽而渔","pinyin":"jiézé'éryú","vi":"tát cạn ao bắt cá"},{"hanzi":"急功近利","pinyin":"jígōngjìnlì","vi":"nóng vội cầu lợi"},{"hanzi":"目光短浅","pinyin":"mùguāngduǎnqiǎn","vi":"tầm nhìn hạn hẹp"},{"hanzi":"得不偿失","pinyin":"débùchángshī","vi":"được không bù mất"}],"traditional":"殺雞取卵"},{"id":"杀戮","hanzi":"杀戮","pinyin":"shālù","meaning_vi":"giết chóc, tàn sát","explanation":"杀 (sát – giết) + 戮 (lục – giết) → giết chóc hàng loạt, tàn sát; văn viết.","hsk_level":6,"tags":["dong-tu"],"image":"⚔️","examples":[{"type":"basic","zh":"战争带来了杀戮。","pinyin":"Zhànzhēng dàiláile shālù.","vi":"Chiến tranh mang đến sự giết chóc."},{"type":"simple","zh":"这部电影里有太多血腥的杀戮场面。","pinyin":"Zhè bù diànyǐng lǐ yǒu tài duō xuèxīng de shālù chǎngmiàn.","vi":"Bộ phim này có quá nhiều cảnh giết chóc đẫm máu."},{"type":"compound","zh":"因为偷猎者疯狂杀戮，所以大象数量急剧减少。","pinyin":"Yīnwèi tōulièzhě fēngkuáng shālù, suǒyǐ dàxiàng shùliàng jíjù jiǎnshǎo.","vi":"Vì những kẻ săn trộm tàn sát điên cuồng nên số lượng voi giảm mạnh."}],"related":[{"hanzi":"屠杀","pinyin":"túshā","vi":"tàn sát"},{"hanzi":"杀害","pinyin":"shāhài","vi":"sát hại"},{"hanzi":"残杀","pinyin":"cánshā","vi":"giết hại tàn nhẫn"},{"hanzi":"战争","pinyin":"zhànzhēng","vi":"chiến tranh"}],"traditional":"殺戮"},{"id":"筛选","hanzi":"筛选","pinyin":"shāixuǎn","meaning_vi":"sàng lọc, chọn lọc","explanation":"筛 (cái sàng) + 选 (chọn).","hsk_level":6,"tags":["dong-tu"],"image":"🔍","examples":[{"type":"basic","zh":"我们正在筛选简历。","pinyin":"Wǒmen zhèngzài shāixuǎn jiǎnlì.","vi":"Chúng tôi đang sàng lọc hồ sơ."},{"type":"simple","zh":"系统会自动筛选出不合格的产品。","pinyin":"Xìtǒng huì zìdòng shāi xuǎnchū bù hégé de chǎnpǐn.","vi":"Hệ thống sẽ tự động lọc ra những sản phẩm không đạt chuẩn."},{"type":"compound","zh":"经过三轮筛选，只有五个人进入了决赛。","pinyin":"Jīngguò sānlún shāixuǎn, zhǐyǒu wǔ gè rén jìnrùle juésài.","vi":"Qua ba vòng sàng lọc, chỉ có năm người vào chung kết."}],"related":[{"hanzi":"选拔","pinyin":"xuǎnbá","vi":"tuyển chọn"},{"hanzi":"挑选","pinyin":"tiāoxuǎn","vi":"lựa chọn"},{"hanzi":"过滤","pinyin":"guòlǜ","vi":"lọc"},{"hanzi":"淘汰","pinyin":"táotài","vi":"loại bỏ"}],"traditional":"篩選"},{"id":"煽动","hanzi":"煽动","pinyin":"shāndòng","meaning_vi":"kích động, xúi giục","explanation":"煽 (quạt lửa) + 动 (hành động).","hsk_level":6,"tags":["dong-tu"],"image":"🔥","examples":[{"type":"basic","zh":"他在网上煽动网民。","pinyin":"Tā zài wǎngshang shāndòng wǎngmín.","vi":"Hắn kích động cư dân mạng trên internet."},{"type":"simple","zh":"那个人因为煽动闹事被警察带走了。","pinyin":"Nàgerén yīnwèi shāndòng nàoshì bèi jǐngchá dàizǒu le.","vi":"Người đó bị cảnh sát đưa đi vì xúi giục gây rối."},{"type":"compound","zh":"有人故意煽动情绪，所以大家要冷静判断。","pinyin":"Yǒurén gùyì shāndòng qíngxù, suǒyǐ dàjiā yào lěngjìng pànduàn.","vi":"Có người cố ý kích động cảm xúc nên mọi người cần bình tĩnh phán đoán."}],"related":[{"hanzi":"鼓动","pinyin":"gǔdòng","vi":"cổ động"},{"hanzi":"挑拨","pinyin":"tiǎobō","vi":"khiêu khích"},{"hanzi":"蛊惑","pinyin":"gǔhuò","vi":"mê hoặc"},{"hanzi":"煽风点火","pinyin":"shānfēngdiǎnhuǒ","vi":"đổ thêm dầu vào lửa"}],"traditional":"煽動"},{"id":"山穷水尽","hanzi":"山穷水尽","pinyin":"shānqióng-shuǐjìn","meaning_vi":"sơn cùng thủy tận (bước đường cùng)","explanation":"Núi cùng nước tận → đi đến bước đường cùng, không còn lối thoát. Hay đối lập với 柳暗花明.","hsk_level":6,"tags":["thanh-ngu"],"image":"⛰️","examples":[{"type":"basic","zh":"公司已经山穷水尽。","pinyin":"Gōngsī yǐjīng shānqióngshuǐjìn.","vi":"Công ty đã đến bước đường cùng."},{"type":"simple","zh":"连续亏损让这家小店走到了山穷水尽的地步。","pinyin":"Liánxù kuīsǔn ràng zhè jiā xiǎodiàn zǒu dàole shānqióngshuǐjìn de dìbù.","vi":"Thua lỗ liên tục khiến cửa hàng nhỏ này lâm vào bước đường cùng."},{"type":"compound","zh":"即使到了山穷水尽的时候，他也没有放弃希望。","pinyin":"Jíshǐ dàole shānqióngshuǐjìn de shíhou, tā yě méiyǒu fàngqì xīwàng.","vi":"Ngay cả khi đến bước đường cùng, anh ấy cũng không từ bỏ hy vọng."}],"related":[{"hanzi":"走投无路","pinyin":"zǒutóuwúlù","vi":"cùng đường"},{"hanzi":"穷途末路","pinyin":"qióngtúmòlù","vi":"bước đường cùng"},{"hanzi":"绝境","pinyin":"juéjìng","vi":"tuyệt cảnh"},{"hanzi":"柳暗花明","pinyin":"liǔ'ànhuāmíng","vi":"tìm ra lối thoát"}],"traditional":"山窮水盡"},{"id":"山清水秀","hanzi":"山清水秀","pinyin":"shānqīng-shuǐxiù","meaning_vi":"non xanh nước biếc","explanation":"山清 (sơn thanh – núi xanh trong) + 水秀 (thủy tú – nước đẹp) → cảnh núi sông tươi đẹp, non xanh nước biếc.","hsk_level":6,"tags":["thanh-ngu","thien-nhien"],"image":"🏞️","examples":[{"type":"basic","zh":"桂林山清水秀。","pinyin":"Guìlín shānqīngshuǐxiù.","vi":"Quế Lâm non xanh nước biếc."},{"type":"simple","zh":"我的老家是个山清水秀的小镇。","pinyin":"Wǒ de lǎojiā shì ge shānqīngshuǐxiù de xiǎozhèn.","vi":"Quê tôi là một thị trấn nhỏ non xanh nước biếc."},{"type":"compound","zh":"这里不但山清水秀，而且空气特别新鲜。","pinyin":"Zhèlǐ búdàn shānqīngshuǐxiù, érqiě kōngqì tèbié xīnxiān.","vi":"Nơi đây không chỉ non xanh nước biếc mà không khí còn đặc biệt trong lành."}],"related":[{"hanzi":"青山绿水","pinyin":"qīngshānlǜshuǐ","vi":"non xanh nước biếc"},{"hanzi":"风景如画","pinyin":"fēngjǐngrúhuà","vi":"cảnh đẹp như tranh"},{"hanzi":"山明水秀","pinyin":"shānmíngshuǐxiù","vi":"non xanh nước biếc"},{"hanzi":"穷山恶水","pinyin":"qióngshān'èshuǐ","vi":"núi trọc sông dữ"}]},{"id":"伤痕","hanzi":"伤痕","pinyin":"shānghén","meaning_vi":"vết thương, sẹo","explanation":"伤 (bị thương) + 痕 (vết).","hsk_level":6,"tags":["danh-tu","suc-khoe"],"image":"🩹","examples":[{"type":"basic","zh":"他手上有道伤痕。","pinyin":"Tā shǒushang yǒudào shānghén.","vi":"Trên tay anh ấy có một vết sẹo."},{"type":"simple","zh":"那次车祸在她腿上留下了一道伤痕。","pinyin":"Nà cì chēhuò zài tā tuǐ shang liúxiàle yídào shānghén.","vi":"Vụ tai nạn xe đó đã để lại một vết sẹo trên chân cô ấy."},{"type":"compound","zh":"身体的伤痕好了，可是心里的伤痕还在。","pinyin":"Shēntǐ de shānghén hǎo le, kěshì xīnlǐ de shānghén hái zài.","vi":"Vết thương trên cơ thể đã lành nhưng vết thương trong lòng vẫn còn."}],"related":[{"hanzi":"伤疤","pinyin":"shāngbā","vi":"vết sẹo"},{"hanzi":"疤痕","pinyin":"bāhén","vi":"sẹo"},{"hanzi":"伤口","pinyin":"shāngkǒu","vi":"vết thương"},{"hanzi":"痕迹","pinyin":"hénjì","vi":"dấu vết"}],"traditional":"傷痕"},{"id":"捎","hanzi":"捎","pinyin":"shāo","meaning_vi":"nhắn gửi, mang hộ đồ","explanation":"Bộ tài gảy 扌+ 肖. Cụm: 捎信 (nhắn tin hộ).","hsk_level":6,"tags":["dong-tu"],"image":"📦","examples":[{"type":"basic","zh":"帮我捎个话。","pinyin":"Bāng wǒ shāo ge huà.","vi":"Nhắn giúp tôi một câu."},{"type":"simple","zh":"妈妈让我给奶奶捎一袋苹果。","pinyin":"Māma ràng wǒ gěi nǎinai shāo yí dài píngguǒ.","vi":"Mẹ bảo tôi mang hộ một túi táo cho bà."},{"type":"compound","zh":"你要是顺路，就帮我把这封信捎过去。","pinyin":"Nǐ yàoshi shùnlù, jiù bāng wǒ bǎ zhè fēng xìn shāo guòqù.","vi":"Nếu bạn tiện đường thì mang giúp tôi lá thư này qua nhé."}],"related":[{"hanzi":"带","pinyin":"dài","vi":"mang"},{"hanzi":"捎带","pinyin":"shāodài","vi":"tiện thể mang"},{"hanzi":"转交","pinyin":"zhuǎnjiāo","vi":"chuyển giao"},{"hanzi":"捎话","pinyin":"shāohuà","vi":"nhắn lời"}]},{"id":"烧烤","hanzi":"烧烤","pinyin":"shāokǎo","meaning_vi":"đồ nướng, tiệc nướng BBQ","explanation":"烧 (đốt) + 烤 (nướng).","hsk_level":6,"tags":["danh-tu","an-uong"],"image":"🍢","examples":[{"type":"basic","zh":"我们晚上吃烧烤。","pinyin":"Wǒmen wǎnshang chī shāokǎo.","vi":"Tối nay chúng ta ăn đồ nướng."},{"type":"simple","zh":"周末我们在河边办了一场烧烤聚会。","pinyin":"Zhōumò wǒmen zài hébiān bànle yì chǎng shāokǎo jùhuì.","vi":"Cuối tuần chúng tôi tổ chức một bữa tiệc nướng bên bờ sông."},{"type":"compound","zh":"烧烤虽然好吃，但是吃多了对身体不好。","pinyin":"Shāokǎo suīrán hǎochī, dànshì chī duōle duì shēntǐ bù hǎo.","vi":"Đồ nướng tuy ngon nhưng ăn nhiều không tốt cho sức khỏe."}],"related":[{"hanzi":"烤肉","pinyin":"kǎoròu","vi":"thịt nướng"},{"hanzi":"串","pinyin":"chuàn","vi":"xiên"},{"hanzi":"烤串","pinyin":"kǎochuàn","vi":"xiên nướng"},{"hanzi":"野餐","pinyin":"yěcān","vi":"dã ngoại"}],"traditional":"燒烤"},{"id":"稍纵即逝","hanzi":"稍纵即逝","pinyin":"shāozòng-jíshì","meaning_vi":"thoáng qua rất nhanh (thời cơ/thời gian)","explanation":"稍纵 (hơi buông lỏng) + 即逝 (liền trôi mất). Thành ngữ.","hsk_level":6,"tags":["thanh-ngu","thoi-gian"],"image":"⚡","examples":[{"type":"basic","zh":"机会稍纵即逝。","pinyin":"Jīhuì shāozòngjíshì.","vi":"Cơ hội thoáng qua rất nhanh."},{"type":"simple","zh":"摄影师抓住了那稍纵即逝的美丽瞬间。","pinyin":"Shèyǐngshī zhuāzhùle nà shāozòngjíshì de měilì shùnjiān.","vi":"Nhiếp ảnh gia đã bắt được khoảnh khắc đẹp thoáng qua ấy."},{"type":"compound","zh":"因为好机会稍纵即逝，所以你得马上决定。","pinyin":"Yīnwèi hǎo jīhuì shāozòngjíshì, suǒyǐ nǐ děi mǎshàng juédìng.","vi":"Vì cơ hội tốt thoáng qua rất nhanh nên bạn phải quyết định ngay."}],"related":[{"hanzi":"转瞬即逝","pinyin":"zhuǎnshùnjíshì","vi":"thoáng chốc qua đi"},{"hanzi":"机不可失","pinyin":"jībùkěshī","vi":"cơ hội không thể mất"},{"hanzi":"昙花一现","pinyin":"tánhuāyíxiàn","vi":"sớm nở tối tàn"},{"hanzi":"一去不复返","pinyin":"yí qù bú fùfǎn","vi":"một đi không trở lại"}],"traditional":"稍縱即逝"},{"id":"奢华","hanzi":"奢华","pinyin":"shēhuá","meaning_vi":"xa hoa, lộng lẫy","explanation":"奢 (xa xỉ) + 华 (hoa lệ).","hsk_level":6,"tags":["tinh-tu"],"image":"💎","examples":[{"type":"basic","zh":"酒店装修很奢华。","pinyin":"Jiǔdiàn zhuāngxiū hěn shēhuá.","vi":"Khách sạn được trang trí rất xa hoa."},{"type":"simple","zh":"那位明星在海边办了一场奢华的婚礼。","pinyin":"Nà wèi míngxīng zài hǎibiān bànle yì chǎng shēhuá de hūnlǐ.","vi":"Ngôi sao đó đã tổ chức một đám cưới xa hoa bên bờ biển."},{"type":"compound","zh":"他虽然很有钱，但是从不追求奢华的生活。","pinyin":"Tā suīrán hěn yǒuqián, dànshì cóng bù zhuīqiú shēhuá de shēnghuó.","vi":"Anh ấy tuy rất giàu nhưng chưa bao giờ theo đuổi cuộc sống xa hoa."}],"related":[{"hanzi":"豪华","pinyin":"háohuá","vi":"xa hoa"},{"hanzi":"奢侈","pinyin":"shēchǐ","vi":"xa xỉ"},{"hanzi":"简朴","pinyin":"jiǎnpǔ","vi":"giản dị"},{"hanzi":"奢侈品","pinyin":"shēchǐpǐn","vi":"hàng xa xỉ"}],"traditional":"奢華"},{"id":"深不可测","hanzi":"深不可测","pinyin":"shēnbù-kěcè","meaning_vi":"sâu không lường được, bí ẩn khó đoán","explanation":"深 (sâu) + 不可测 (không thể đo) → sâu không lường được; nghĩa bóng: con người bí hiểm, khó đoán.","hsk_level":6,"tags":["thanh-ngu"],"image":"🌊","examples":[{"type":"basic","zh":"这个湖深不可测。","pinyin":"Zhè ge hú shēnbùkěcè.","vi":"Cái hồ này sâu không lường được."},{"type":"simple","zh":"那位老人的武功深不可测。","pinyin":"Nà wèi lǎorén de wǔgōng shēnbùkěcè.","vi":"Võ công của ông lão đó thâm sâu khó lường."},{"type":"compound","zh":"他平时话很少，所以大家都觉得他深不可测。","pinyin":"Tā píngshí huà hěn shǎo, suǒyǐ dàjiā dōu juéde tā shēnbùkěcè.","vi":"Anh ấy bình thường ít nói nên mọi người đều thấy anh ấy bí ẩn khó đoán."}],"related":[{"hanzi":"高深莫测","pinyin":"gāoshēnmòcè","vi":"cao thâm khó lường"},{"hanzi":"神秘","pinyin":"shénmì","vi":"thần bí"},{"hanzi":"莫测高深","pinyin":"mòcègāoshēn","vi":"khó lường"},{"hanzi":"一目了然","pinyin":"yímùliǎorán","vi":"nhìn qua là hiểu"}],"traditional":"深不可測"},{"id":"身临其境","hanzi":"身临其境","pinyin":"shēnlín-qíjìng","meaning_vi":"như tự mình đang ở ngay tại hiện trường","explanation":"身临 (thân đến) + 其境 (nơi ấy) → như chính mình có mặt tại chỗ. Thường: 让人有身临其境的感觉.","hsk_level":6,"tags":["thanh-ngu"],"image":"🥽","examples":[{"type":"basic","zh":"看这部电影仿佛身临其境。","pinyin":"Kàn zhè bù diànyǐng fǎngfú shēnlínqíjìng.","vi":"Xem bộ phim này cứ như đang ở ngay tại đó."},{"type":"simple","zh":"这部纪录片让观众有身临其境的感觉。","pinyin":"Zhè bù jìlùpiàn ràng guānzhòng yǒu shēnlínqíjìng de gǎnjué.","vi":"Bộ phim tài liệu này khiến khán giả có cảm giác như đang có mặt tại hiện trường."},{"type":"compound","zh":"他描写得十分生动，读者一读就像身临其境。","pinyin":"Tā miáoxiě de shífēn shēngdòng, dúzhě yì dú jiù xiàng shēnlínqíjìng.","vi":"Anh ấy miêu tả rất sinh động, người đọc vừa đọc đã như đang ở ngay tại đó."}],"related":[{"hanzi":"亲临现场","pinyin":"qīnlínxiànchǎng","vi":"có mặt tại hiện trường"},{"hanzi":"身历其境","pinyin":"shēnlìqíjìng","vi":"tự mình trải qua"},{"hanzi":"逼真","pinyin":"bīzhēn","vi":"y như thật"},{"hanzi":"设身处地","pinyin":"shèshēnchǔdì","vi":"đặt mình vào hoàn cảnh"}],"traditional":"身臨其境"},{"id":"深情","hanzi":"深情","pinyin":"shēnqíng","meaning_vi":"tình cảm sâu đậm","explanation":"深 (sâu) + 情 (tình).","hsk_level":6,"tags":["danh-tu","tinh-tu"],"image":"❤️","examples":[{"type":"basic","zh":"她深情地望着他。","pinyin":"Tā shēnqíng de wàngzhe tā.","vi":"Cô ấy nhìn anh ấy đầy tình cảm."},{"type":"simple","zh":"老歌手深情地演唱了一首思乡的歌。","pinyin":"Lǎo gēshǒu shēnqíng de yǎnchàngle yì shǒu sīxiāng de gē.","vi":"Ca sĩ lão làng say đắm hát một bài hát nhớ quê."},{"type":"compound","zh":"虽然分别多年，但是他对故乡的深情从未改变。","pinyin":"Suīrán fēnbié duōnián, dànshì tā duì gùxiāng de shēnqíng cóngwèi gǎibiàn.","vi":"Tuy xa cách nhiều năm nhưng tình cảm sâu đậm của ông với quê hương chưa từng thay đổi."}],"related":[{"hanzi":"感情","pinyin":"gǎnqíng","vi":"tình cảm"},{"hanzi":"深情厚谊","pinyin":"shēnqínghòuyì","vi":"tình nghĩa sâu nặng"},{"hanzi":"无情","pinyin":"wúqíng","vi":"vô tình"},{"hanzi":"柔情","pinyin":"róuqíng","vi":"tình cảm dịu dàng"}]},{"id":"深入浅出","hanzi":"深入浅出","pinyin":"shēnrù-qiǎnchū","meaning_vi":"diễn đạt vấn đề sâu sắc bằng ngôn ngữ dễ hiểu","explanation":"Nội dung đi sâu, cách nói dễ hiểu → giảng giải vấn đề khó một cách đơn giản, dễ tiếp thu.","hsk_level":6,"tags":["thanh-ngu","hoc-tap"],"image":"🧑‍🏫","examples":[{"type":"basic","zh":"王老师讲课深入浅出。","pinyin":"Wáng lǎoshī jiǎngkè shēnrùqiǎnchū.","vi":"Thầy Vương giảng bài sâu sắc mà dễ hiểu."},{"type":"simple","zh":"这本科普书深入浅出地介绍了黑洞。","pinyin":"Zhè běn kēpǔ shū shēnrùqiǎnchū de jièshàole hēidòng.","vi":"Cuốn sách phổ biến khoa học này giới thiệu về hố đen một cách sâu sắc mà dễ hiểu."},{"type":"compound","zh":"如果讲解能深入浅出，学生就更容易记住。","pinyin":"Rúguǒ jiǎngjiě néng shēnrùqiǎnchū, xuésheng jiù gèng róngyì jìzhù.","vi":"Nếu giảng giải được sâu sắc mà dễ hiểu thì học sinh sẽ dễ nhớ hơn."}],"related":[{"hanzi":"通俗易懂","pinyin":"tōngsúyìdǒng","vi":"dễ hiểu"},{"hanzi":"浅显","pinyin":"qiǎnxiǎn","vi":"dễ hiểu"},{"hanzi":"深奥","pinyin":"shēn'ào","vi":"sâu xa khó hiểu"},{"hanzi":"晦涩","pinyin":"huìsè","vi":"tối nghĩa"}],"traditional":"深入淺出"},{"id":"深思熟虑","hanzi":"深思熟虑","pinyin":"shēnsī-shúlǜ","meaning_vi":"suy nghĩ chín chắn kỹ lưỡng","explanation":"深思 (thâm tư – nghĩ sâu) + 熟虑 (thục lự – cân nhắc kỹ) → suy nghĩ thấu đáo, chín chắn trước khi quyết định.","hsk_level":6,"tags":["thanh-ngu","nhan-thuc"],"image":"🧠","examples":[{"type":"basic","zh":"这是我深思熟虑的决定。","pinyin":"Zhè shì wǒ shēnsīshúlǜ de juédìng.","vi":"Đây là quyết định tôi đã suy nghĩ chín chắn."},{"type":"simple","zh":"经过深思熟虑，她决定辞职去读研究生。","pinyin":"Jīngguò shēnsīshúlǜ, tā juédìng cízhí qù dú yánjiūshēng.","vi":"Sau khi suy nghĩ kỹ lưỡng, cô ấy quyết định nghỉ việc để học cao học."},{"type":"compound","zh":"买房是大事，所以一定要深思熟虑以后再签合同。","pinyin":"Mǎifáng shì dàshì, suǒyǐ yídìngyào shēnsīshúlǜ yǐhòu zài qiānhétong.","vi":"Mua nhà là việc lớn nên nhất định phải suy nghĩ chín chắn rồi mới ký hợp đồng."}],"related":[{"hanzi":"三思而后行","pinyin":"sānsī érhòu xíng","vi":"suy nghĩ kỹ rồi hãy làm"},{"hanzi":"深谋远虑","pinyin":"shēnmóuyuǎnlǜ","vi":"tính sâu lo xa"},{"hanzi":"轻率","pinyin":"qīngshuài","vi":"khinh suất"},{"hanzi":"考虑","pinyin":"kǎolǜ","vi":"cân nhắc"}],"traditional":"深思熟慮"},{"id":"深渊","hanzi":"深渊","pinyin":"shēnyuān","meaning_vi":"vực thẳm","explanation":"深 + 渊 (vực sâu).","hsk_level":6,"tags":["danh-tu","thien-nhien"],"image":"🕳️","examples":[{"type":"basic","zh":"他掉进了绝望的深渊。","pinyin":"Tā diào jìnle juéwàng de shēnyuān.","vi":"Anh ấy rơi vào vực thẳm tuyệt vọng."},{"type":"simple","zh":"悬崖下面是一片看不见底的深渊。","pinyin":"Xuányá xiàmiàn shì yípiàn kànbujiàn dǐ de shēnyuān.","vi":"Bên dưới vách núi là một vực thẳm không thấy đáy."},{"type":"compound","zh":"一旦染上赌博，就可能滑向犯罪的深渊。","pinyin":"Yídàn rǎnshàng dǔbó, jiù kěnéng huá xiàng fànzuì de shēnyuān.","vi":"Một khi đã dính vào cờ bạc thì có thể trượt xuống vực thẳm tội phạm."}],"related":[{"hanzi":"悬崖","pinyin":"xuányá","vi":"vách đá"},{"hanzi":"深谷","pinyin":"shēngǔ","vi":"thung lũng sâu"},{"hanzi":"万丈深渊","pinyin":"wànzhàngshēnyuān","vi":"vực sâu muôn trượng"},{"hanzi":"陷入","pinyin":"xiànrù","vi":"rơi vào"}],"traditional":"深淵"},{"id":"深奥","hanzi":"深奥","pinyin":"shēn'ào","meaning_vi":"sâu xa, uyên thâm, khó hiểu","explanation":"深 (sâu) + 奥 (bí ẩn).","hsk_level":6,"tags":["tinh-tu"],"image":"🧠","examples":[{"type":"basic","zh":"这本书太深奥了。","pinyin":"Zhè běn shū tài shēn'ào le.","vi":"Cuốn sách này quá cao siêu khó hiểu."},{"type":"simple","zh":"爷爷用简单的话讲清了深奥的道理。","pinyin":"Yéye yòng jiǎndān dehuà jiǎng qīngle shēn'ào de dàoli.","vi":"Ông nội dùng lời lẽ đơn giản giải thích rõ một đạo lý sâu xa."},{"type":"compound","zh":"哲学虽然深奥，但是和日常生活密切相关。","pinyin":"Zhéxué suīrán shēn'ào, dànshì hé rìcháng shēnghuó mìqiè xiāngguān.","vi":"Triết học tuy uyên thâm nhưng lại liên quan mật thiết đến cuộc sống hằng ngày."}],"related":[{"hanzi":"高深","pinyin":"gāoshēn","vi":"cao thâm"},{"hanzi":"难懂","pinyin":"nándǒng","vi":"khó hiểu"},{"hanzi":"浅显","pinyin":"qiǎnxiǎn","vi":"dễ hiểu"},{"hanzi":"深入浅出","pinyin":"shēnrùqiǎnchū","vi":"sâu sắc mà dễ hiểu"}],"traditional":"深奧"},{"id":"生搬硬套","hanzi":"生搬硬套","pinyin":"shēngbān-yìngtào","meaning_vi":"áp dụng máy móc rập khuôn","explanation":"生搬 (bê nguyên) + 硬套 (ép áp vào) → áp dụng máy móc kinh nghiệm, lý thuyết mà không xét thực tế.","hsk_level":6,"tags":["thanh-ngu"],"image":"🤖","examples":[{"type":"basic","zh":"学习不能生搬硬套。","pinyin":"Xuéxí bù néng shēngbānyìngtào.","vi":"Học tập không được rập khuôn máy móc."},{"type":"simple","zh":"他把国外的管理模式生搬硬套到小公司里。","pinyin":"Tā bǎ guówài de guǎnlǐ móshì shēngbānyìngtào dào xiǎo gōngsī lǐ.","vi":"Anh ta rập khuôn máy móc mô hình quản lý nước ngoài vào công ty nhỏ."},{"type":"compound","zh":"如果生搬硬套别人的经验，就很难成功。","pinyin":"Rúguǒ shēngbānyìngtào biérén de jīngyàn, jiù hěn nán chénggōng.","vi":"Nếu áp dụng máy móc kinh nghiệm của người khác thì rất khó thành công."}],"related":[{"hanzi":"照搬","pinyin":"zhàobān","vi":"rập khuôn"},{"hanzi":"死板","pinyin":"sǐbǎn","vi":"cứng nhắc"},{"hanzi":"机械","pinyin":"jīxiè","vi":"máy móc"},{"hanzi":"灵活运用","pinyin":"línghuóyùnyòng","vi":"vận dụng linh hoạt"}]},{"id":"生存","hanzi":"生存","pinyin":"shēngcún","meaning_vi":"sinh tồn, tồn tại","explanation":"生 (sống) + 存 (tồn tại).","hsk_level":6,"tags":["dong-tu"],"image":"🌍","examples":[{"type":"basic","zh":"动物需要水才能生存。","pinyin":"Dòngwù xūyào shuǐ cáinéng shēngcún.","vi":"Động vật cần nước mới có thể sinh tồn."},{"type":"simple","zh":"骆驼能在干旱的沙漠里生存很久。","pinyin":"Luòtuo néng zài gānhàn de shāmò lǐ shēngcún hěn jiǔ.","vi":"Lạc đà có thể sinh tồn rất lâu trong sa mạc khô hạn."},{"type":"compound","zh":"小企业如果不创新，就很难在竞争中生存下去。","pinyin":"Xiǎoqǐyè rúguǒ bú chuàngxīn, jiù hěn nán zài jìngzhēng zhōng shēngcún xiàqù.","vi":"Doanh nghiệp nhỏ nếu không đổi mới thì rất khó tồn tại trong cạnh tranh."}],"related":[{"hanzi":"生活","pinyin":"shēnghuó","vi":"cuộc sống"},{"hanzi":"存活","pinyin":"cúnhuó","vi":"sống sót"},{"hanzi":"生存竞争","pinyin":"shēngcúnjìngzhēng","vi":"đấu tranh sinh tồn"},{"hanzi":"灭亡","pinyin":"mièwáng","vi":"diệt vong"}]},{"id":"声东击西","hanzi":"声东击西","pinyin":"shēngdōng-jīxī","meaning_vi":"dương đông kích tây","explanation":"Binh pháp / Thành ngữ.","hsk_level":6,"tags":["thanh-ngu"],"image":"🧭","examples":[{"type":"basic","zh":"敌人在声东击西。","pinyin":"Dírén zài shēngdōngjīxī.","vi":"Quân địch đang dương đông kích tây."},{"type":"simple","zh":"这名球员用声东击西的假动作骗过了守门员。","pinyin":"Zhè míng qiúyuán yòng shēngdōngjīxī de jiǎdòngzuò piànguò le shǒuményuán.","vi":"Cầu thủ này dùng động tác giả dương đông kích tây lừa được thủ môn."},{"type":"compound","zh":"他们先佯攻北门，接着声东击西，从南门攻了进去。","pinyin":"Tāmen xiān yáng gōng běi mén, jiēzhe shēngdōngjīxī, cóng nán mén gōngle jìnqù.","vi":"Họ giả vờ tấn công cổng bắc trước, rồi dương đông kích tây, đánh vào từ cổng nam."}],"related":[{"hanzi":"调虎离山","pinyin":"diàohǔlíshān","vi":"điệu hổ ly sơn"},{"hanzi":"出其不意","pinyin":"chūqíbúyì","vi":"bất ngờ"},{"hanzi":"兵法","pinyin":"bīngfǎ","vi":"binh pháp"},{"hanzi":"迷惑","pinyin":"míhuò","vi":"đánh lừa"}],"traditional":"聲東擊西"},{"id":"生机勃勃","hanzi":"生机勃勃","pinyin":"shēngjī-bóbó","meaning_vi":"tràn đầy sức sống mãnh liệt","explanation":"生机 (sinh cơ – sức sống) + 勃勃 (bột bột – trỗi dậy mạnh mẽ) → tràn trề sức sống, phát triển mạnh mẽ.","hsk_level":6,"tags":["thanh-ngu"],"image":"🌿","examples":[{"type":"basic","zh":"春天的公园生机勃勃。","pinyin":"Chūntiān de gōngyuán shēngjībóbó.","vi":"Công viên mùa xuân tràn đầy sức sống."},{"type":"simple","zh":"雨后的田野显得生机勃勃。","pinyin":"Yǔ hòu de tiányě xiǎnde shēngjībóbó.","vi":"Cánh đồng sau mưa trông tràn trề sức sống."},{"type":"compound","zh":"自从年轻人回乡创业，小村子就变得生机勃勃了。","pinyin":"Zìcóng niánqīngrén huíxiāng chuàngyè, xiǎo cūnzi jiù biànde shēngjībóbó le.","vi":"Từ khi người trẻ về quê khởi nghiệp, ngôi làng nhỏ trở nên tràn đầy sức sống."}],"related":[{"hanzi":"生气勃勃","pinyin":"shēngqìbóbó","vi":"tràn đầy sức sống"},{"hanzi":"欣欣向荣","pinyin":"xīnxīnxiàngróng","vi":"phát triển thịnh vượng"},{"hanzi":"死气沉沉","pinyin":"sǐqìchénchén","vi":"tẻ nhạt thiếu sức sống"},{"hanzi":"生机","pinyin":"shēngjī","vi":"sức sống"}],"traditional":"生機勃勃"},{"id":"生灵涂炭","hanzi":"生灵涂炭","pinyin":"shēnglíng-tútàn","meaning_vi":"chúng sinh lầm than (cảnh chiến tranh/thiên tai)","explanation":"生灵 (dân chúng) + 涂炭 (bùn lầy và than lửa) → dân chúng lầm than khổ cực, thường do chiến tranh, bạo chính.","hsk_level":6,"tags":["thanh-ngu"],"image":"😢","examples":[{"type":"basic","zh":"战争使生灵涂炭。","pinyin":"Zhànzhēng shǐ shēnglíngtútàn.","vi":"Chiến tranh khiến chúng sinh lầm than."},{"type":"simple","zh":"那场大地震造成了生灵涂炭的惨状。","pinyin":"Nà chǎng dà dìzhèn zào chéngle shēnglíngtútàn de cǎnzhuàng.","vi":"Trận động đất lớn đó đã gây ra cảnh muôn dân lầm than thê thảm."},{"type":"compound","zh":"如果两国真的开战，边境地区势必生灵涂炭。","pinyin":"Rúguǒ liǎngguó zhēn de kāizhàn, biānjìng dìqū shìbì shēnglíngtútàn.","vi":"Nếu hai nước thật sự khai chiến thì vùng biên giới ắt sẽ chìm trong cảnh lầm than."}],"related":[{"hanzi":"民不聊生","pinyin":"mínbùliáoshēng","vi":"dân chúng lầm than"},{"hanzi":"水深火热","pinyin":"shuǐshēnhuǒrè","vi":"nước sôi lửa bỏng"},{"hanzi":"国泰民安","pinyin":"guótàimín'ān","vi":"quốc thái dân an"},{"hanzi":"战乱","pinyin":"zhànluàn","vi":"loạn lạc"}],"traditional":"生靈塗炭"},{"id":"声名狼藉","hanzi":"声名狼藉","pinyin":"shēngmíng-lángjí","meaning_vi":"tiếng xấu đồn xa, danh tiếng bê bối","explanation":"声名 (thanh danh) + 狼藉 (lang tạ – bừa bộn như ổ cỏ sói nằm) → thanh danh bại hoại, tiếng xấu đồn xa.","hsk_level":6,"tags":["thanh-ngu"],"image":"👎","examples":[{"type":"basic","zh":"这家公司声名狼藉。","pinyin":"Zhè jiā gōngsī shēngmínglángjí.","vi":"Công ty này tai tiếng khắp nơi."},{"type":"simple","zh":"那位明星因为偷税而声名狼藉。","pinyin":"Nà wèi míngxīng yīnwèi tōushuì ér shēngmínglángjí.","vi":"Ngôi sao đó vì trốn thuế mà mang tiếng xấu."},{"type":"compound","zh":"一旦卖假货被曝光，商家就会声名狼藉。","pinyin":"Yídàn mài jiǎhuò bèi bàoguāng, shāngjiā jiù huì shēngmínglángjí.","vi":"Một khi bị phanh phui bán hàng giả, cửa hàng sẽ mang tiếng xấu."}],"related":[{"hanzi":"臭名昭著","pinyin":"chòumíngzhāozhù","vi":"tiếng xấu đồn xa"},{"hanzi":"身败名裂","pinyin":"shēnbàimíngliè","vi":"thân bại danh liệt"},{"hanzi":"名誉扫地","pinyin":"míngyùsǎodì","vi":"mất hết danh dự"},{"hanzi":"德高望重","pinyin":"dégāowàngzhòng","vi":"đức cao vọng trọng"}],"traditional":"聲名狼藉"},{"id":"生气勃勃","hanzi":"生气勃勃","pinyin":"shēngqì-bóbó","meaning_vi":"tràn đầy sức sống","explanation":"生气 (sức sống) + 勃勃. Thành ngữ.","hsk_level":6,"tags":["thanh-ngu"],"image":"🌱","examples":[{"type":"basic","zh":"孩子们生气勃勃。","pinyin":"Háizimen shēngqìbóbó.","vi":"Bọn trẻ tràn đầy sức sống."},{"type":"simple","zh":"操场上到处是生气勃勃的年轻人。","pinyin":"Cāochǎng shang dàochù shì shēngqìbóbó de niánqīngrén.","vi":"Trên sân tập khắp nơi là những người trẻ tràn đầy sức sống."},{"type":"compound","zh":"新校长来了以后，学校不但面貌一新，而且生气勃勃。","pinyin":"Xīn xiàozhǎng láile yǐhòu, xuéxiào búdàn miànmàoyìxīn, érqiě shēngqìbóbó.","vi":"Từ khi hiệu trưởng mới đến, trường không chỉ thay đổi diện mạo mà còn tràn đầy sức sống."}],"related":[{"hanzi":"朝气蓬勃","pinyin":"zhāoqìpéngbó","vi":"tràn đầy sức sống"},{"hanzi":"生机勃勃","pinyin":"shēngjībóbó","vi":"tràn đầy sức sống"},{"hanzi":"活力","pinyin":"huólì","vi":"sức sống"},{"hanzi":"暮气沉沉","pinyin":"mùqìchénchén","vi":"uể oải trì trệ"}],"traditional":"生氣勃勃"},{"id":"声势","hanzi":"声势","pinyin":"shēngshì","meaning_vi":"thanh thế, khí thế","explanation":"声 + 势 (thế lực).","hsk_level":6,"tags":["danh-tu"],"image":"🔥","examples":[{"type":"basic","zh":"活动声势很大。","pinyin":"Huódòng shēngshì hěn dà.","vi":"Hoạt động có thanh thế rất lớn."},{"type":"simple","zh":"新产品上市前公司做了声势浩大的宣传。","pinyin":"Xīnchǎnpǐn shàngshì qián gōngsī zuòle shēngshì hàodà de xuānchuán.","vi":"Trước khi sản phẩm mới ra mắt, công ty đã quảng bá rầm rộ."},{"type":"compound","zh":"这场比赛虽然声势不小，但是观众并不多。","pinyin":"Zhè chǎng bǐsài suīrán shēngshì bù xiǎo, dànshì guānzhòng bìngbù duō.","vi":"Trận đấu này tuy được làm rầm rộ nhưng khán giả lại không nhiều."}],"related":[{"hanzi":"气势","pinyin":"qìshì","vi":"khí thế"},{"hanzi":"声势浩大","pinyin":"shēngshìhàodà","vi":"thanh thế lớn"},{"hanzi":"虚张声势","pinyin":"xūzhāngshēngshì","vi":"làm ra vẻ hùng mạnh"},{"hanzi":"威势","pinyin":"wēishì","vi":"uy thế"}],"traditional":"聲勢"},{"id":"生态","hanzi":"生态","pinyin":"shēngtài","meaning_vi":"sinh thái","explanation":"生 + 态 (trạng thái). Cụm: 生态环境 (môi trường sinh thái).","hsk_level":6,"tags":["danh-tu","thien-nhien"],"image":"🌿","examples":[{"type":"basic","zh":"要保护海洋生态。","pinyin":"Yào bǎohù hǎiyáng shēngtài.","vi":"Phải bảo vệ sinh thái biển."},{"type":"simple","zh":"这片湿地的生态环境越来越好了。","pinyin":"Zhè piàn shīdì de shēngtài huánjìng yuèláiyuè hǎo le.","vi":"Môi trường sinh thái của vùng đất ngập nước này ngày càng tốt hơn."},{"type":"compound","zh":"如果乱扔塑料垃圾，就会破坏河流的生态。","pinyin":"Rúguǒ luànrēng sùliào lājī, jiù huì pòhuài héliú de shēngtài.","vi":"Nếu vứt rác nhựa bừa bãi thì sẽ phá hoại sinh thái của sông ngòi."}],"related":[{"hanzi":"生态环境","pinyin":"shēngtàihuánjìng","vi":"môi trường sinh thái"},{"hanzi":"生态平衡","pinyin":"shēngtàipínghéng","vi":"cân bằng sinh thái"},{"hanzi":"环保","pinyin":"huánbǎo","vi":"bảo vệ môi trường"},{"hanzi":"自然","pinyin":"zìrán","vi":"tự nhiên"}],"traditional":"生態"},{"id":"生锈","hanzi":"生锈","pinyin":"shēngxiù","meaning_vi":"bị gỉ sét","explanation":"生 + 锈 (gỉ). Động từ ly hợp.","hsk_level":6,"tags":["dong-tu"],"image":"🔩","examples":[{"type":"basic","zh":"铁门生锈了。","pinyin":"Tiě mén shēngxiù le.","vi":"Cổng sắt bị gỉ rồi."},{"type":"simple","zh":"放在阳台上的自行车很快就生锈了。","pinyin":"Fàng zài yángtái shang de zìxíngchē hěn kuài jiù shēngxiù le.","vi":"Chiếc xe đạp để ngoài ban công rất nhanh bị gỉ sét."},{"type":"compound","zh":"刀用完以后要擦干，否则很容易生锈。","pinyin":"Dāo yòngwán yǐhòu yào cāgān, fǒuzé hěn róngyì shēngxiù.","vi":"Dao dùng xong phải lau khô, nếu không sẽ rất dễ bị gỉ."}],"related":[{"hanzi":"铁锈","pinyin":"tiěxiù","vi":"gỉ sắt"},{"hanzi":"腐蚀","pinyin":"fǔshí","vi":"ăn mòn"},{"hanzi":"防锈","pinyin":"fángxiù","vi":"chống gỉ"},{"hanzi":"氧化","pinyin":"yǎnghuà","vi":"oxy hóa"}],"traditional":"生鏽"},{"id":"舍己为人","hanzi":"舍己为人","pinyin":"shějǐ-wèirén","meaning_vi":"quên mình vì người khác","explanation":"舍己 (bỏ mình) + 为人 (vì người). Thành ngữ.","hsk_level":6,"tags":["thanh-ngu"],"image":"🦸","examples":[{"type":"basic","zh":"他一生舍己为人。","pinyin":"Tā yìshēng shějǐwèirén.","vi":"Cả đời ông ấy quên mình vì người khác."},{"type":"simple","zh":"这位舍己为人的消防员感动了全国人民。","pinyin":"Zhè wèi shějǐwèirén de xiāofángyuán gǎndòngle quánguó rénmín.","vi":"Người lính cứu hỏa quên mình vì người khác này đã làm cảm động nhân dân cả nước."},{"type":"compound","zh":"虽然他自己也很困难，但是总是舍己为人帮助邻居。","pinyin":"Suīrán tā zìjǐ yě hěn kùnnan, dànshì zǒngshì shějǐwèirén bāngzhù línjū.","vi":"Tuy bản thân cũng khó khăn nhưng anh ấy luôn quên mình giúp đỡ hàng xóm."}],"related":[{"hanzi":"舍己救人","pinyin":"shějǐjiùrén","vi":"xả thân cứu người"},{"hanzi":"大公无私","pinyin":"dàgōngwúsī","vi":"chí công vô tư"},{"hanzi":"自私自利","pinyin":"zìsīzìlì","vi":"ích kỷ tư lợi"},{"hanzi":"无私奉献","pinyin":"wúsīfèngxiàn","vi":"cống hiến vô tư"}],"traditional":"捨己為人"},{"id":"审判","hanzi":"审判","pinyin":"shěnpàn","meaning_vi":"xét xử, phán xét","explanation":"审 + 判 (phân định).","hsk_level":6,"tags":["dong-tu","phap-luat"],"image":"⚖️","examples":[{"type":"basic","zh":"法院明天审判此案。","pinyin":"Fǎyuàn míngtiān shěnpàn cǐ àn.","vi":"Tòa án sẽ xét xử vụ án này vào ngày mai."},{"type":"simple","zh":"这名贪官最终受到了法律的审判。","pinyin":"Zhè míng tānguān zuìzhōng shòudàole fǎlǜ de shěnpàn.","vi":"Tên quan tham này cuối cùng đã bị pháp luật xét xử."},{"type":"compound","zh":"在审判结果出来以前，谁也不能说他有罪。","pinyin":"Zài shěnpàn jiéguǒ chūlái yǐqián, shéi yě bù néng shuō tā yǒuzuì.","vi":"Trước khi có kết quả xét xử, không ai được nói anh ta có tội."}],"related":[{"hanzi":"审理","pinyin":"shěnlǐ","vi":"xét xử"},{"hanzi":"判决","pinyin":"pànjué","vi":"phán quyết"},{"hanzi":"法庭","pinyin":"fǎtíng","vi":"tòa án"},{"hanzi":"审判长","pinyin":"shěnpànzhǎng","vi":"chánh án"}],"traditional":"審判"},{"id":"审时度势","hanzi":"审时度势","pinyin":"shěnshí-duóshì","meaning_vi":"xem xét thời thế, đánh giá cục diện","explanation":"审时 + 度势 (đọc duó). Thành ngữ.","hsk_level":6,"tags":["thanh-ngu"],"image":"♟️","examples":[{"type":"basic","zh":"领导要善于审时度势。","pinyin":"Lǐngdǎo yào shànyú shěnshíduóshì.","vi":"Người lãnh đạo phải giỏi nhận định thời thế."},{"type":"simple","zh":"董事会审时度势地调整了投资计划。","pinyin":"Dǒngshìhuì shěnshíduóshì de tiáozhěngle tóuzī jìhuà.","vi":"Hội đồng quản trị đã xem xét tình hình và điều chỉnh kế hoạch đầu tư."},{"type":"compound","zh":"只要能审时度势，就能在危机中找到机会。","pinyin":"Zhǐyào néng shěnshíduóshì, jiù néng zài wēijī zhōng zhǎodào jīhuì.","vi":"Chỉ cần biết đánh giá thời thế thì có thể tìm thấy cơ hội trong khủng hoảng."}],"related":[{"hanzi":"因势利导","pinyin":"yīnshìlìdǎo","vi":"dẫn dắt theo tình thế"},{"hanzi":"随机应变","pinyin":"suíjīyìngbiàn","vi":"tùy cơ ứng biến"},{"hanzi":"高瞻远瞩","pinyin":"gāozhānyuǎnzhǔ","vi":"nhìn xa trông rộng"},{"hanzi":"形势","pinyin":"xíngshì","vi":"tình hình"}],"traditional":"審時度勢"},{"id":"省吃俭用","hanzi":"省吃俭用","pinyin":"shěngchī-jiǎnyòng","meaning_vi":"ăn tiêu tiết kiệm, thắt lưng buộc bụng","explanation":"省 (tỉnh – bớt) 吃 (ăn) 俭 (kiệm) 用 (dụng – dùng) → bớt ăn bớt tiêu, sống tằn tiện tiết kiệm.","hsk_level":6,"tags":["thanh-ngu","tien-te"],"image":"💰","examples":[{"type":"basic","zh":"父母一直省吃俭用。","pinyin":"Fùmǔ yìzhí shěngchījiǎnyòng.","vi":"Bố mẹ luôn ăn tiêu dè sẻn."},{"type":"simple","zh":"她省吃俭用攒了三年才买了一台钢琴。","pinyin":"Tā shěngchījiǎnyòng zǎnle sān nián cái mǎile yì tái gāngqín.","vi":"Cô ấy thắt lưng buộc bụng tích góp ba năm mới mua được một cây đàn piano."},{"type":"compound","zh":"爸妈虽然省吃俭用，但是给我交学费从来不犹豫。","pinyin":"Bàmā suīrán shěngchījiǎnyòng, dànshì gěi wǒ jiāo xuéfèi cóngláibù yóuyù.","vi":"Bố mẹ tuy ăn tiêu tiết kiệm nhưng đóng học phí cho tôi thì chưa bao giờ do dự."}],"related":[{"hanzi":"节衣缩食","pinyin":"jiéyīsuōshí","vi":"thắt lưng buộc bụng"},{"hanzi":"勤俭节约","pinyin":"qínjiǎnjiéyuē","vi":"cần kiệm tiết kiệm"},{"hanzi":"挥霍无度","pinyin":"huīhuòwúdù","vi":"tiêu xài hoang phí"},{"hanzi":"节俭","pinyin":"jiéjiǎn","vi":"tiết kiệm"}],"traditional":"省吃儉用"},{"id":"失魂落魄","hanzi":"失魂落魄","pinyin":"shīhún-luòpò","meaning_vi":"mất hồn mất vía, hoảng hốt bàng hoàng","explanation":"失 (thất – mất) 魂 (hồn) 落 (lạc – rơi) 魄 (phách) → mất hồn lạc phách; hoảng loạn, thất thần.","hsk_level":6,"tags":["thanh-ngu","cam-xuc"],"image":"😱","examples":[{"type":"basic","zh":"他失魂落魄地走了。","pinyin":"Tā shīhúnluòpò de zǒu le.","vi":"Anh ấy bỏ đi như người mất hồn."},{"type":"simple","zh":"丢了钱包后，她一整天都失魂落魄的。","pinyin":"Diūle qiánbāo hòu, tā yìzhěngtiān dōu shīhúnluòpò de.","vi":"Sau khi mất ví, cô ấy cả ngày cứ như người mất hồn."},{"type":"compound","zh":"一听说儿子出了车祸，他就吓得失魂落魄。","pinyin":"Yì tīngshuō érzi chūle chēhuò, tā jiù xià de shīhúnluòpò.","vi":"Vừa nghe tin con trai gặp tai nạn, ông ấy sợ đến hồn bay phách lạc."}],"related":[{"hanzi":"魂不守舍","pinyin":"húnbùshǒushè","vi":"hồn vía lên mây"},{"hanzi":"惊慌失措","pinyin":"jīnghuāngshīcuò","vi":"hoảng loạn"},{"hanzi":"心神不定","pinyin":"xīnshénbúdìng","vi":"tâm thần bất định"},{"hanzi":"镇定自若","pinyin":"zhèndìngzìruò","vi":"bình tĩnh như thường"}]},{"id":"失礼","hanzi":"失礼","pinyin":"shīlǐ","meaning_vi":"thất lễ, thiếu lễ phép","explanation":"失 + 礼 (lễ nghi).","hsk_level":6,"tags":["dong-tu","giao-tiep"],"image":"🙇","examples":[{"type":"basic","zh":"刚才真是失礼了。","pinyin":"Gāngcái zhēn shì shīlǐ le.","vi":"Vừa rồi thật là thất lễ quá."},{"type":"simple","zh":"客人进门不打招呼是很失礼的。","pinyin":"Kèrén jìnmén bù dǎzhāohu shì hěn shīlǐ de.","vi":"Khách vào nhà mà không chào hỏi là rất thất lễ."},{"type":"compound","zh":"我来晚了，如果有失礼的地方，请大家原谅。","pinyin":"Wǒ lái wǎn le, rúguǒ yǒu shīlǐ de dìfang, qǐng dàjiā yuánliàng.","vi":"Tôi đến muộn, nếu có chỗ nào thất lễ, mong mọi người thứ lỗi."}],"related":[{"hanzi":"无礼","pinyin":"wúlǐ","vi":"vô lễ"},{"hanzi":"冒犯","pinyin":"màofàn","vi":"mạo phạm"},{"hanzi":"礼貌","pinyin":"lǐmào","vi":"lễ phép"},{"hanzi":"失敬","pinyin":"shījìng","vi":"thất kính"}],"traditional":"失禮"},{"id":"失眠症","hanzi":"失眠症","pinyin":"shīmiánzhèng","meaning_vi":"chứng mất ngủ","explanation":"失眠 (thất miên – mất ngủ) + 症 (chứng – bệnh) → chứng bệnh mất ngủ. Cụm: 患失眠症.","hsk_level":6,"tags":["danh-tu","suc-khoe"],"image":"🦉","examples":[{"type":"basic","zh":"他患有失眠症。","pinyin":"Tā huànyǒu shīmiánzhèng.","vi":"Anh ấy mắc chứng mất ngủ."},{"type":"simple","zh":"长期加班让她得了严重的失眠症。","pinyin":"Chángqī jiābān ràng tā déle yánzhòng de shīmiánzhèng.","vi":"Tăng ca lâu ngày khiến cô ấy mắc chứng mất ngủ nghiêm trọng."},{"type":"compound","zh":"自从开始练瑜伽，他的失眠症就好多了。","pinyin":"Zìcóng kāishǐ liàn yújiā, tā de shīmiánzhèng jiù hǎoduō le.","vi":"Từ khi bắt đầu tập yoga, chứng mất ngủ của anh ấy đã đỡ hơn nhiều."}],"related":[{"hanzi":"失眠","pinyin":"shīmián","vi":"mất ngủ"},{"hanzi":"睡眠","pinyin":"shuìmián","vi":"giấc ngủ"},{"hanzi":"安眠药","pinyin":"ānmiányào","vi":"thuốc ngủ"},{"hanzi":"熬夜","pinyin":"áoyè","vi":"thức khuya"}]},{"id":"诗情画意","hanzi":"诗情画意","pinyin":"shīqíng-huàyì","meaning_vi":"đầy chất thơ và ý họa (cảnh đẹp lãng mạn)","explanation":"诗情 (thi tình – tình thơ) + 画意 (họa ý – ý tranh) → cảnh vật đẹp như thơ như tranh, đầy chất lãng mạn.","hsk_level":6,"tags":["thanh-ngu","van-hoa"],"image":"🎨","examples":[{"type":"basic","zh":"西湖充满诗情画意。","pinyin":"Xīhú chōngmǎn shīqínghuàyì.","vi":"Tây Hồ tràn đầy chất thơ và ý họa."},{"type":"simple","zh":"烟雨中的江南小镇显得诗情画意。","pinyin":"Yānyǔ zhōng de Jiāngnán xiǎozhèn xiǎnde shīqínghuàyì.","vi":"Thị trấn Giang Nam trong mưa bụi trông đầy chất thơ."},{"type":"compound","zh":"这家咖啡馆不但环境安静，而且布置得诗情画意。","pinyin":"Zhè jiā kāfēiguǎn búdàn huánjìng ānjìng, érqiě bùzhì de shīqínghuàyì.","vi":"Quán cà phê này không chỉ yên tĩnh mà còn được bài trí đầy chất thơ."}],"related":[{"hanzi":"诗意","pinyin":"shīyì","vi":"chất thơ"},{"hanzi":"如诗如画","pinyin":"rúshīrúhuà","vi":"đẹp như thơ như họa"},{"hanzi":"风景如画","pinyin":"fēngjǐngrúhuà","vi":"cảnh đẹp như tranh"},{"hanzi":"浪漫","pinyin":"làngmàn","vi":"lãng mạn"}],"traditional":"詩情畫意"},{"id":"施舍","hanzi":"施舍","pinyin":"shīshě","meaning_vi":"bố thí","explanation":"施 + 舍 (cho đi).","hsk_level":6,"tags":["dong-tu"],"image":"🤲","examples":[{"type":"basic","zh":"他施舍给乞丐一些钱。","pinyin":"Tā shīshě gěi qǐgài yìxiē qián.","vi":"Anh ấy bố thí cho người ăn xin một ít tiền."},{"type":"simple","zh":"老和尚每天在寺门口施舍粥饭。","pinyin":"Lǎo héshang měitiān zài sì ménkǒu shīshě zhōu fàn.","vi":"Vị sư già ngày nào cũng bố thí cơm cháo trước cổng chùa."},{"type":"compound","zh":"我宁可自己努力赚钱，也不要别人的施舍。","pinyin":"Wǒ nìngkě zìjǐ nǔlì zhuànqián, yě bú yào biérén de shīshě.","vi":"Tôi thà tự mình cố gắng kiếm tiền chứ không cần người khác bố thí."}],"related":[{"hanzi":"布施","pinyin":"bùshī","vi":"bố thí"},{"hanzi":"救济","pinyin":"jiùjì","vi":"cứu tế"},{"hanzi":"乞丐","pinyin":"qǐgài","vi":"người ăn xin"},{"hanzi":"慈善","pinyin":"císhàn","vi":"từ thiện"}],"traditional":"施捨"},{"id":"失误","hanzi":"失误","pinyin":"shīwù","meaning_vi":"sai sót, sơ suất","explanation":"失 (mất) + 误 (sai).","hsk_level":6,"tags":["danh-tu","dong-tu"],"image":"⚠️","examples":[{"type":"basic","zh":"这是我的失误。","pinyin":"Zhè shì wǒ de shīwù.","vi":"Đây là sơ suất của tôi."},{"type":"simple","zh":"守门员的一次失误让球队输掉了比赛。","pinyin":"Shǒuményuán de yí cì shīwù ràng qiúduì shūdiàole bǐsài.","vi":"Một sai sót của thủ môn đã khiến đội bóng thua trận."},{"type":"compound","zh":"因为操作失误，所以整批产品都得返工。","pinyin":"Yīnwèi cāozuò shīwù, suǒyǐ zhěng pī chǎnpǐn dōu děi fǎngōng.","vi":"Vì thao tác sai sót nên cả lô sản phẩm đều phải làm lại."}],"related":[{"hanzi":"错误","pinyin":"cuòwù","vi":"sai lầm"},{"hanzi":"失手","pinyin":"shīshǒu","vi":"lỡ tay"},{"hanzi":"疏忽","pinyin":"shūhu","vi":"sơ suất"},{"hanzi":"过失","pinyin":"guòshī","vi":"lỗi lầm"}],"traditional":"失誤"},{"id":"失信","hanzi":"失信","pinyin":"shīxìn","meaning_vi":"thất hứa, mất chữ tín","explanation":"失 + 信 (niềm tin).","hsk_level":6,"tags":["dong-tu","giao-tiep"],"image":"🤥","examples":[{"type":"basic","zh":"做人不能失信。","pinyin":"Zuòrén bù néng shīxìn.","vi":"Làm người không được thất hứa."},{"type":"simple","zh":"他多次失信于朋友，现在没人相信他了。","pinyin":"Tā duōcì shīxìn yú péngyou, xiànzài méi rén xiāngxìn tā le.","vi":"Anh ta nhiều lần thất hứa với bạn bè, giờ không ai tin anh ta nữa."},{"type":"compound","zh":"既然答应了帮你搬家，我就不会失信。","pinyin":"Jìrán dāyingle bāng nǐ bānjiā, wǒ jiù bú huì shīxìn.","vi":"Đã hứa giúp bạn chuyển nhà thì tôi sẽ không thất hứa."}],"related":[{"hanzi":"失约","pinyin":"shīyuē","vi":"lỡ hẹn"},{"hanzi":"守信","pinyin":"shǒuxìn","vi":"giữ chữ tín"},{"hanzi":"背信弃义","pinyin":"bèixìnqìyì","vi":"bội tín bạc nghĩa"},{"hanzi":"信用","pinyin":"xìnyòng","vi":"uy tín"}]},{"id":"收成","hanzi":"收成","pinyin":"shōucheng","meaning_vi":"mùa màng, thu hoạch","explanation":"收 (thu) + 成 (thành quả).","hsk_level":6,"tags":["danh-tu","thien-nhien"],"image":"🌾","examples":[{"type":"basic","zh":"今年收成很好。","pinyin":"Jīnnián shōucheng hěn hǎo.","vi":"Năm nay mùa màng bội thu."},{"type":"simple","zh":"由于干旱，村里的玉米收成减少了一半。","pinyin":"Yóuyú gānhàn, cūnlǐ de yùmǐ shōucheng jiǎnshǎole yíbàn.","vi":"Do hạn hán, sản lượng ngô trong làng giảm mất một nửa."},{"type":"compound","zh":"只要风调雨顺，今年秋天就会有好收成。","pinyin":"Zhǐyào fēngtiáoyǔshùn, jīnnián qiūtiān jiù huì yǒu hǎo shōucheng.","vi":"Chỉ cần mưa thuận gió hòa thì mùa thu năm nay sẽ được mùa."}],"related":[{"hanzi":"收获","pinyin":"shōuhuò","vi":"thu hoạch"},{"hanzi":"丰收","pinyin":"fēngshōu","vi":"được mùa"},{"hanzi":"产量","pinyin":"chǎnliàng","vi":"sản lượng"},{"hanzi":"歉收","pinyin":"qiànshōu","vi":"mất mùa"}]},{"id":"收留","hanzi":"收留","pinyin":"shōuliú","meaning_vi":"cưu mang, cho ở nhờ","explanation":"收 + 留 (giữ lại).","hsk_level":6,"tags":["dong-tu","xa-hoi"],"image":"🏡","examples":[{"type":"basic","zh":"好心人收留了流浪猫。","pinyin":"Hǎoxīnrén shōuliúle liúlàngmāo.","vi":"Người tốt bụng đã cưu mang chú mèo hoang."},{"type":"simple","zh":"大雪那天，一户农家收留了迷路的游客。","pinyin":"Dàxuě nà tiān, yí hù nóngjiā shōuliúle mílù de yóukè.","vi":"Hôm tuyết rơi dày, một gia đình nông dân đã cho du khách lạc đường ở nhờ."},{"type":"compound","zh":"如果没有阿姨收留他，他就只能睡在街上了。","pinyin":"Rúguǒ méiyǒu āyí shōuliú tā, tā jiù zhǐnéng shuì zài jiēshang le.","vi":"Nếu không có cô ấy cưu mang thì cậu ta chỉ có thể ngủ ngoài đường."}],"related":[{"hanzi":"收养","pinyin":"shōuyǎng","vi":"nhận nuôi"},{"hanzi":"收容","pinyin":"shōuróng","vi":"thu nhận"},{"hanzi":"救济","pinyin":"jiùjì","vi":"cứu tế"},{"hanzi":"驱逐","pinyin":"qūzhú","vi":"xua đuổi"}]},{"id":"收益","hanzi":"收益","pinyin":"shōuyì","meaning_vi":"lợi nhuận, thu nhập","explanation":"收 + 益 (lợi ích).","hsk_level":6,"tags":["danh-tu","tien-te","cong-viec"],"image":"💰","examples":[{"type":"basic","zh":"这项投资收益不错。","pinyin":"Zhè xiàng tóuzī shōuyì búcuò.","vi":"Khoản đầu tư này lợi nhuận khá tốt."},{"type":"simple","zh":"今年公司的收益比去年增加了百分之二十。","pinyin":"Jīnnián gōngsī de shōuyì bǐ qùnián zēngjiāle bǎifēnzhī èrshí.","vi":"Lợi nhuận năm nay của công ty tăng 20% so với năm ngoái."},{"type":"compound","zh":"虽然投资股票的收益比较高，但是风险也很大。","pinyin":"Suīrán tóuzī gǔpiào de shōuyì bǐjiào gāo, dànshì fēngxiǎn yě hěn dà.","vi":"Tuy đầu tư cổ phiếu có lợi nhuận khá cao nhưng rủi ro cũng rất lớn."}],"related":[{"hanzi":"收入","pinyin":"shōurù","vi":"thu nhập"},{"hanzi":"利润","pinyin":"lìrùn","vi":"lợi nhuận"},{"hanzi":"盈利","pinyin":"yínglì","vi":"có lãi"},{"hanzi":"亏损","pinyin":"kuīsǔn","vi":"thua lỗ"}]},{"id":"书呆子","hanzi":"书呆子","pinyin":"shūdāizi","meaning_vi":"mọt sách (người chỉ biết đọc sách thiếu thực tế)","explanation":"书 (sách) + 呆子 (kẻ ngốc).","hsk_level":6,"tags":["danh-tu","con-nguoi","hoc-tap"],"image":"🤓","examples":[{"type":"basic","zh":"他是个书呆子。","pinyin":"Tā shì ge shūdāizi.","vi":"Cậu ấy là một con mọt sách."},{"type":"simple","zh":"同学们都笑他是只会考试的书呆子。","pinyin":"Tóngxuémen dōu xiào tā shì zhǐ huì kǎoshì de shūdāizi.","vi":"Các bạn đều cười cậu ấy là mọt sách chỉ biết thi cử."},{"type":"compound","zh":"与其做个书呆子，不如多出去看看世界。","pinyin":"Yǔqí zuò ge shūdāizi, bùrú duō chūqù kànkan shìjiè.","vi":"Thay vì làm mọt sách, chi bằng ra ngoài ngắm nhìn thế giới nhiều hơn."}],"related":[{"hanzi":"读死书","pinyin":"dúsǐshū","vi":"học vẹt"},{"hanzi":"书生","pinyin":"shūshēng","vi":"thư sinh"},{"hanzi":"学霸","pinyin":"xuébà","vi":"học bá"},{"hanzi":"死读书","pinyin":"sǐdúshū","vi":"chỉ biết đọc sách"}],"traditional":"書呆子"},{"id":"抒发","hanzi":"抒发","pinyin":"shūfā","meaning_vi":"bộc lộ, giãi bày (tình cảm)","explanation":"抒 (trút ra) + 发 (phát ra).","hsk_level":6,"tags":["dong-tu","cam-xuc"],"image":"💌","examples":[{"type":"basic","zh":"他用诗抒发感情。","pinyin":"Tāyòng shī shūfā gǎnqíng.","vi":"Anh ấy dùng thơ để bày tỏ tình cảm."},{"type":"simple","zh":"这首歌抒发了游子对家乡的思念。","pinyin":"Zhè shǒu gē shūfāle yóuzǐ duì jiāxiāng de sīniàn.","vi":"Bài hát này bộc lộ nỗi nhớ quê hương của người con xa xứ."},{"type":"compound","zh":"心里不痛快的时候，写日记能帮我抒发情绪。","pinyin":"Xīnlǐ bú tòngkuai de shíhou, xiě rìjì néng bāng wǒ shūfā qíngxù.","vi":"Khi trong lòng không vui, viết nhật ký giúp tôi giãi bày cảm xúc."}],"related":[{"hanzi":"表达","pinyin":"biǎodá","vi":"biểu đạt"},{"hanzi":"抒情","pinyin":"shūqíng","vi":"trữ tình"},{"hanzi":"倾诉","pinyin":"qīngsù","vi":"giãi bày"},{"hanzi":"发泄","pinyin":"fāxiè","vi":"trút ra"}],"traditional":"抒發"},{"id":"书法","hanzi":"书法","pinyin":"shūfǎ","meaning_vi":"thư pháp","explanation":"书 (viết chữ) + 法 (phép tắc).","hsk_level":6,"tags":["danh-tu","van-hoa","giai-tri"],"image":"🖌️","examples":[{"type":"basic","zh":"爷爷每天练书法。","pinyin":"Yéye měitiān liàn shūfǎ.","vi":"Ông nội ngày nào cũng luyện thư pháp."},{"type":"simple","zh":"客厅墙上挂着一幅漂亮的书法作品。","pinyin":"Kètīng qiáng shang guàzhe yì fú piàoliang de shūfǎ zuòpǐn.","vi":"Trên tường phòng khách treo một bức thư pháp rất đẹp."},{"type":"compound","zh":"学书法不但能练字，而且能让人静下心来。","pinyin":"Xué shūfǎ búdàn néng liànzì, érqiě néng ràng rén jìng xià xīn lái.","vi":"Học thư pháp không chỉ luyện chữ mà còn giúp con người tĩnh tâm."}],"related":[{"hanzi":"毛笔","pinyin":"máobǐ","vi":"bút lông"},{"hanzi":"书法家","pinyin":"shūfǎjiā","vi":"nhà thư pháp"},{"hanzi":"字帖","pinyin":"zìtiè","vi":"vở tập viết"},{"hanzi":"绘画","pinyin":"huìhuà","vi":"hội họa"}],"traditional":"書法"},{"id":"书面","hanzi":"书面","pinyin":"shūmiàn","meaning_vi":"bằng văn bản, chữ viết","explanation":"书 + 面 (mặt giấy). Đối nghĩa với 口头 (bằng miệng).","hsk_level":6,"tags":["tinh-tu","ngon-ngu"],"image":"📄","examples":[{"type":"basic","zh":"请提交书面申请。","pinyin":"Qǐng tíjiāo shūmiàn shēnqǐng.","vi":"Xin hãy nộp đơn bằng văn bản."},{"type":"simple","zh":"公司要求请假必须提前写书面报告。","pinyin":"Gōngsī yāoqiú qǐngjià bìxū tíqián xiě shūmiàn bàogào.","vi":"Công ty yêu cầu xin nghỉ phải viết báo cáo bằng văn bản trước."},{"type":"compound","zh":"口头答应不算数，所以最好有书面合同。","pinyin":"Kǒutóu dāying bú suànshù, suǒyǐ zuìhǎo yǒu shūmiàn hétong.","vi":"Hứa miệng thì không tính nên tốt nhất là có hợp đồng bằng văn bản."}],"related":[{"hanzi":"口头","pinyin":"kǒutóu","vi":"bằng miệng"},{"hanzi":"书面语","pinyin":"shūmiànyǔ","vi":"ngôn ngữ viết"},{"hanzi":"书面通知","pinyin":"shūmiàntōngzhī","vi":"thông báo bằng văn bản"},{"hanzi":"文字","pinyin":"wénzì","vi":"chữ viết"}],"traditional":"書面"},{"id":"枢纽","hanzi":"枢纽","pinyin":"shūniǔ","meaning_vi":"đầu mối (giao thông/kinh tế), then chốt","explanation":"枢 (xu – trục cửa) + 纽 (nữu – núm, nút buộc) → bộ phận then chốt; đầu mối quan trọng. Cụm: 交通枢纽.","hsk_level":6,"tags":["danh-tu","giao-thong"],"image":"🚉","examples":[{"type":"basic","zh":"郑州是交通枢纽。","pinyin":"Zhèngzhōu shì jiāotōng shūniǔ.","vi":"Trịnh Châu là đầu mối giao thông."},{"type":"simple","zh":"这个新建的高铁站将成为区域交通枢纽。","pinyin":"Zhè ge xīnjiàn de gāotiě zhàn jiāng chéngwéi qūyù jiāotōng shūniǔ.","vi":"Ga tàu cao tốc mới xây này sẽ trở thành đầu mối giao thông của khu vực."},{"type":"compound","zh":"因为这里是物流枢纽，所以很多快递公司都在这儿建了仓库。","pinyin":"Yīnwèi zhèlǐ shì wùliú shūniǔ, suǒyǐ hěn duō kuàidì gōngsī dōu zài zhèr jiànle cāngkù.","vi":"Vì đây là đầu mối logistics nên nhiều công ty chuyển phát đã xây kho ở đây."}],"related":[{"hanzi":"交通枢纽","pinyin":"jiāotōngshūniǔ","vi":"đầu mối giao thông"},{"hanzi":"中心","pinyin":"zhōngxīn","vi":"trung tâm"},{"hanzi":"关键","pinyin":"guānjiàn","vi":"then chốt"},{"hanzi":"要道","pinyin":"yàodào","vi":"con đường trọng yếu"}],"traditional":"樞紐"},{"id":"殊途同归","hanzi":"殊途同归","pinyin":"shūtú-tóngguī","meaning_vi":"khác đường nhưng cùng đích đến","explanation":"殊途 (đường khác) + 同归 (cùng về). Thành ngữ.","hsk_level":6,"tags":["thanh-ngu"],"image":"🛤️","examples":[{"type":"basic","zh":"两种方法殊途同归。","pinyin":"Liǎng zhǒng fāngfǎ shūtútóngguī.","vi":"Hai phương pháp khác đường nhưng cùng đích đến."},{"type":"simple","zh":"东西方医学在治病救人上殊途同归。","pinyin":"Dōngxīfāng yīxué zài zhìbìng jiùrén shang shūtútóngguī.","vi":"Y học phương Đông và phương Tây khác đường nhưng cùng mục đích chữa bệnh cứu người."},{"type":"compound","zh":"虽然我们的思路不一样，但是结论殊途同归。","pinyin":"Suīrán wǒmen de sīlù bù yíyàng, dànshì jiélùn shūtútóngguī.","vi":"Tuy cách nghĩ của chúng ta khác nhau nhưng kết luận lại cùng một đích."}],"related":[{"hanzi":"异曲同工","pinyin":"yìqǔtónggōng","vi":"khác cách cùng hiệu quả"},{"hanzi":"南辕北辙","pinyin":"nányuánběizhé","vi":"đi ngược mục tiêu"},{"hanzi":"不谋而合","pinyin":"bùmóu'érhé","vi":"không hẹn mà gặp"},{"hanzi":"条条大路通罗马","pinyin":"tiáo tiáo dàlù tōng Luómǎ","vi":"đường nào cũng tới La Mã"}],"traditional":"殊途同歸"},{"id":"疏远","hanzi":"疏远","pinyin":"shūyuǎn","meaning_vi":"xa cách, lạnh nhạt (quan hệ)","explanation":"疏 (thưa) + 远 (xa).","hsk_level":6,"tags":["dong-tu","tinh-tu"],"image":"🚶","examples":[{"type":"basic","zh":"他们渐渐疏远了。","pinyin":"Tāmen jiànjiàn shūyuǎn le.","vi":"Họ dần dần xa cách nhau."},{"type":"simple","zh":"搬家以后，她和老同学的关系疏远了不少。","pinyin":"Bānjiā yǐhòu, tā hé lǎo tóngxué de guānxì shūyuǎnle bùshǎo.","vi":"Sau khi chuyển nhà, quan hệ của cô ấy với bạn học cũ xa cách đi nhiều."},{"type":"compound","zh":"如果总是拒绝朋友的邀请，就会慢慢疏远他们。","pinyin":"Rúguǒ zǒngshì jùjué péngyou de yāoqǐng, jiù huì mànmàn shūyuǎn tāmen.","vi":"Nếu cứ từ chối lời mời của bạn bè thì sẽ dần dần xa cách họ."}],"related":[{"hanzi":"冷淡","pinyin":"lěngdàn","vi":"lạnh nhạt"},{"hanzi":"隔阂","pinyin":"géhé","vi":"ngăn cách"},{"hanzi":"亲近","pinyin":"qīnjìn","vi":"gần gũi"},{"hanzi":"亲密","pinyin":"qīnmì","vi":"thân mật"}],"traditional":"疏遠"},{"id":"傻瓜","hanzi":"傻瓜","pinyin":"shǎguā","meaning_vi":"kẻ ngốc, đồ ngốc (thân mật)","explanation":"傻 (ngốc) + 瓜 (quả dưa).","hsk_level":6,"tags":["danh-tu","con-nguoi"],"image":"🤪","examples":[{"type":"basic","zh":"你这个小傻瓜！","pinyin":"Nǐ zhè ge xiǎo shǎguā!","vi":"Đồ ngốc nhỏ này!"},{"type":"simple","zh":"只有傻瓜才会相信这种中奖短信。","pinyin":"Zhǐyǒu shǎguā cái huì xiāngxìn zhè zhǒng zhòngjiǎng duǎnxìn.","vi":"Chỉ có kẻ ngốc mới tin loại tin nhắn trúng thưởng này."},{"type":"compound","zh":"他虽然常说我是傻瓜，但是其实很关心我。","pinyin":"Tā suīrán cháng shuō wǒ shì shǎguā, dànshì qíshí hěn guānxīn wǒ.","vi":"Anh ấy tuy hay bảo tôi là đồ ngốc nhưng thực ra rất quan tâm tôi."}],"related":[{"hanzi":"笨蛋","pinyin":"bèndàn","vi":"đồ ngốc"},{"hanzi":"傻子","pinyin":"shǎzi","vi":"kẻ khờ"},{"hanzi":"聪明人","pinyin":"cōngmíngrén","vi":"người thông minh"},{"hanzi":"傻乎乎","pinyin":"shǎhūhū","vi":"ngơ ngơ ngẩn ngẩn"}]},{"id":"闪耀","hanzi":"闪耀","pinyin":"shǎnyào","meaning_vi":"tỏa sáng rực rỡ, lấp lánh","explanation":"闪 (lóe) + 耀 (chiếu sáng).","hsk_level":6,"tags":["dong-tu"],"image":"✨","examples":[{"type":"basic","zh":"星星在夜空闪耀。","pinyin":"Xīngxing zài yèkōng shǎnyào.","vi":"Những vì sao lấp lánh trên bầu trời đêm."},{"type":"simple","zh":"她手上的钻石戒指在灯光下闪耀着。","pinyin":"Tā shǒushang de zuànshí jièzhi zài dēngguāng xià shǎnyào zhe.","vi":"Chiếc nhẫn kim cương trên tay cô ấy lấp lánh dưới ánh đèn."},{"type":"compound","zh":"只要坚持梦想，每个人都能在自己的舞台上闪耀。","pinyin":"Zhǐyào jiānchí mèngxiǎng, měigèrén dōu néng zài zìjǐ de wǔtái shang shǎnyào.","vi":"Chỉ cần kiên trì với ước mơ, ai cũng có thể tỏa sáng trên sân khấu của mình."}],"related":[{"hanzi":"闪烁","pinyin":"shǎnshuò","vi":"lấp lánh"},{"hanzi":"闪亮","pinyin":"shǎnliàng","vi":"sáng lóa"},{"hanzi":"耀眼","pinyin":"yàoyǎn","vi":"chói lọi"},{"hanzi":"光芒","pinyin":"guāngmáng","vi":"tia sáng"}],"traditional":"閃耀"},{"id":"赏赐","hanzi":"赏赐","pinyin":"shǎngcì","meaning_vi":"ban thưởng","explanation":"赏 + 赐 (ban cho).","hsk_level":6,"tags":["dong-tu","van-hoa"],"image":"🎁","examples":[{"type":"basic","zh":"皇帝赏赐了他黄金。","pinyin":"Huángdì shǎngcìle tā huángjīn.","vi":"Hoàng đế ban thưởng vàng cho ông ấy."},{"type":"simple","zh":"打了胜仗的将军得到了丰厚的赏赐。","pinyin":"Dǎle shèngzhàng de jiāngjūn dédàole fēnghòu de shǎngcì.","vi":"Vị tướng thắng trận đã nhận được phần ban thưởng hậu hĩnh."},{"type":"compound","zh":"因为他救了公主，所以国王赏赐他一座城堡。","pinyin":"Yīnwèi tā jiùle gōngzhǔ, suǒyǐ guówáng shǎngcì tā yí zuò chéngbǎo.","vi":"Vì chàng đã cứu công chúa nên nhà vua ban thưởng cho chàng một tòa lâu đài."}],"related":[{"hanzi":"奖赏","pinyin":"jiǎngshǎng","vi":"ban thưởng"},{"hanzi":"恩赐","pinyin":"ēncì","vi":"ân huệ"},{"hanzi":"赏罚","pinyin":"shǎngfá","vi":"thưởng phạt"},{"hanzi":"封赏","pinyin":"fēngshǎng","vi":"phong thưởng"}],"traditional":"賞賜"},{"id":"赏识","hanzi":"赏识","pinyin":"shǎngshí","meaning_vi":"đánh giá cao, trọng dụng (nhân tài)","explanation":"赏 + 识 (nhận biết).","hsk_level":6,"tags":["dong-tu","cong-viec"],"image":"🌟","examples":[{"type":"basic","zh":"老板很赏识他。","pinyin":"Lǎobǎn hěn shǎngshí tā.","vi":"Ông chủ rất đánh giá cao anh ấy."},{"type":"simple","zh":"她的设计才华得到了总监的赏识。","pinyin":"Tā de shèjì cáihuá dédàole zǒngjiān de shǎngshí.","vi":"Tài năng thiết kế của cô ấy được giám đốc đánh giá cao."},{"type":"compound","zh":"因为得到了导演的赏识，所以这个新人有了第一个主角。","pinyin":"Yīnwèi dédàole dǎoyǎn de shǎngshí, suǒyǐ zhè ge xīnrén yǒule dìyī gè zhǔjué.","vi":"Nhờ được đạo diễn trọng dụng nên diễn viên mới này đã có vai chính đầu tiên."}],"related":[{"hanzi":"器重","pinyin":"qìzhòng","vi":"coi trọng"},{"hanzi":"欣赏","pinyin":"xīnshǎng","vi":"thưởng thức, đánh giá cao"},{"hanzi":"重用","pinyin":"zhòngyòng","vi":"trọng dụng"},{"hanzi":"伯乐","pinyin":"Bólè","vi":"người biết nhìn nhân tài"}],"traditional":"賞識"},{"id":"赏心悦目","hanzi":"赏心悦目","pinyin":"shǎngxīn-yuèmù","meaning_vi":"đẹp mắt vui lòng (cảnh đẹp/tác phẩm hay)","explanation":"赏心 (lòng vui thích) + 悦目 (đẹp mắt) → cảnh vật, tác phẩm đẹp khiến vui mắt vui lòng.","hsk_level":6,"tags":["thanh-ngu"],"image":"🌸","examples":[{"type":"basic","zh":"这些花真赏心悦目。","pinyin":"Zhèxiē huā zhēn shǎngxīnyuèmù.","vi":"Những bông hoa này thật đẹp mắt vui lòng."},{"type":"simple","zh":"秋天的枫叶林让人感到赏心悦目。","pinyin":"Qiūtiān de fēngyè lín ràng rén gǎndào shǎngxīnyuèmù.","vi":"Rừng phong mùa thu khiến người ta thấy vui mắt sảng khoái."},{"type":"compound","zh":"这本画册不但印刷精美，而且图片赏心悦目。","pinyin":"Zhè běn huàcè búdàn yìnshuā jīngměi, érqiě túpiàn shǎngxīnyuèmù.","vi":"Cuốn sách ảnh này không chỉ in ấn tinh xảo mà hình ảnh còn rất đẹp mắt."}],"related":[{"hanzi":"心旷神怡","pinyin":"xīnkuàngshényí","vi":"khoan khoái thư thái"},{"hanzi":"美不胜收","pinyin":"měibúshèngshōu","vi":"đẹp không tả xiết"},{"hanzi":"悦目","pinyin":"yuèmù","vi":"đẹp mắt"},{"hanzi":"不堪入目","pinyin":"bùkānrùmù","vi":"không thể nhìn nổi"}],"traditional":"賞心悅目"},{"id":"史无前例","hanzi":"史无前例","pinyin":"shǐwú-qiánlì","meaning_vi":"chưa từng có trong lịch sử","explanation":"史 (lịch sử) + 无前例 (không có tiền lệ). Thành ngữ.","hsk_level":6,"tags":["thanh-ngu"],"image":"📜","examples":[{"type":"basic","zh":"这是史无前例的。","pinyin":"Zhè shì shǐwúqiánlì de.","vi":"Điều này chưa từng có trong lịch sử."},{"type":"simple","zh":"今年夏天出现了史无前例的高温。","pinyin":"Jīnnián xiàtiān chūxiànle shǐwúqiánlì de gāowēn.","vi":"Mùa hè năm nay xuất hiện nắng nóng kỷ lục chưa từng có."},{"type":"compound","zh":"这次展览史无前例地吸引了一百万名观众。","pinyin":"Zhè cì zhǎnlǎn shǐwúqiánlì de xīyǐnle yī bǎi wànmíng guānzhòng.","vi":"Triển lãm lần này đã thu hút một triệu khách tham quan, điều chưa từng có."}],"related":[{"hanzi":"前所未有","pinyin":"qiánsuǒwèiyǒu","vi":"chưa từng có"},{"hanzi":"空前绝后","pinyin":"kōngqiánjuéhòu","vi":"vô tiền khoáng hậu"},{"hanzi":"破天荒","pinyin":"pòtiānhuāng","vi":"lần đầu tiên"},{"hanzi":"屡见不鲜","pinyin":"lǚjiànbùxiān","vi":"thường thấy"}],"traditional":"史無前例"},{"id":"矢志不渝","hanzi":"矢志不渝","pinyin":"shǐzhì-bùyú","meaning_vi":"một lòng kiên định không đổi thay","explanation":"矢志 (thề giữ chí) + 不渝 (không đổi). Thành ngữ.","hsk_level":6,"tags":["thanh-ngu"],"image":"✊","examples":[{"type":"basic","zh":"他矢志不渝地追求真理。","pinyin":"Tā shǐzhìbùyú de zhuīqiú zhēnlǐ.","vi":"Ông ấy kiên định theo đuổi chân lý không đổi thay."},{"type":"simple","zh":"这位科学家矢志不渝地研究了三十年。","pinyin":"Zhè wèi kēxuéjiā shǐzhìbùyú de yánjiūle sānshí nián.","vi":"Nhà khoa học này đã một lòng kiên định nghiên cứu suốt ba mươi năm."},{"type":"compound","zh":"虽然遇到过很多挫折，但是她对音乐的热爱矢志不渝。","pinyin":"Suīrán yùdàoguo hěn duō cuòzhé, dànshì tā duì yīnyuè de rè'ài shǐzhìbùyú.","vi":"Tuy gặp nhiều trắc trở nhưng tình yêu âm nhạc của cô ấy vẫn kiên định không đổi."}],"related":[{"hanzi":"坚定不移","pinyin":"jiāndìngbùyí","vi":"kiên định không đổi"},{"hanzi":"始终如一","pinyin":"shǐzhōngrúyī","vi":"trước sau như một"},{"hanzi":"忠贞不渝","pinyin":"zhōngzhēnbùyú","vi":"trung trinh không đổi"},{"hanzi":"见异思迁","pinyin":"jiànyìsīqiān","vi":"thấy lạ đổi lòng"}]},{"id":"首当其冲","hanzi":"首当其冲","pinyin":"shǒudāng-qíchōng","meaning_vi":"đứng mũi chịu sào, chịu ảnh hưởng đầu tiên","explanation":"首 (đầu tiên) + 当其冲 (đứng ngay chỗ xung yếu) → chịu tác động, tai họa đầu tiên.","hsk_level":6,"tags":["thanh-ngu"],"image":"🛡️","examples":[{"type":"basic","zh":"沿海城市首当其冲。","pinyin":"Yánhǎi chéngshì shǒudāngqíchōng.","vi":"Các thành phố ven biển hứng chịu đầu tiên."},{"type":"simple","zh":"台风来袭，海边的渔村首当其冲。","pinyin":"Táifēng láixí, hǎibiān de yú cūn shǒudāngqíchōng.","vi":"Bão ập tới, làng chài ven biển là nơi hứng chịu đầu tiên."},{"type":"compound","zh":"如果经济不景气，小企业就会首当其冲。","pinyin":"Rúguǒ jīngjì bùjǐngqì, xiǎoqǐyè jiù huì shǒudāngqíchōng.","vi":"Nếu kinh tế suy thoái thì doanh nghiệp nhỏ sẽ là bên chịu ảnh hưởng đầu tiên."}],"related":[{"hanzi":"首先","pinyin":"shǒuxiān","vi":"trước tiên"},{"hanzi":"首要","pinyin":"shǒuyào","vi":"hàng đầu"},{"hanzi":"冲击","pinyin":"chōngjī","vi":"tác động mạnh"},{"hanzi":"首当其冲的受害者","pinyin":"shǒudāngqíchōng de shòuhàizhě","vi":"nạn nhân đầu tiên"}],"traditional":"首當其衝"},{"id":"手忙脚乱","hanzi":"手忙脚乱","pinyin":"shǒumáng-jiǎoluàn","meaning_vi":"cuống cuồng tay chân, luống cuống","explanation":"手忙 (tay bận) + 脚乱 (chân rối) → cuống quýt luống cuống, làm việc rối loạn thiếu trật tự.","hsk_level":6,"tags":["thanh-ngu"],"image":"慌","examples":[{"type":"basic","zh":"他忙得手忙脚乱。","pinyin":"Tā máng de shǒumángjiǎoluàn.","vi":"Anh ấy bận đến mức luống cuống tay chân."},{"type":"simple","zh":"客人突然来了，妈妈手忙脚乱地准备饭菜。","pinyin":"Kèrén tūrán lái le, māma shǒumángjiǎoluàn de zhǔnbèi fàncài.","vi":"Khách đến bất ngờ, mẹ cuống cuồng chuẩn bị cơm nước."},{"type":"compound","zh":"如果平时不整理东西，出门时就会手忙脚乱。","pinyin":"Rúguǒ píngshí bù zhěnglǐ dōngxi, chūmén shí jiù huì shǒumángjiǎoluàn.","vi":"Nếu bình thường không sắp xếp đồ đạc thì lúc ra ngoài sẽ luống cuống."}],"related":[{"hanzi":"慌手慌脚","pinyin":"huāngshǒuhuāngjiǎo","vi":"luống cuống"},{"hanzi":"惊慌失措","pinyin":"jīnghuāngshīcuò","vi":"hoảng loạn"},{"hanzi":"有条不紊","pinyin":"yǒutiáobùwěn","vi":"ngăn nắp đâu ra đấy"},{"hanzi":"从容不迫","pinyin":"cóngróngbúpò","vi":"ung dung bình tĩnh"}],"traditional":"手忙腳亂"},{"id":"首屈一指","hanzi":"首屈一指","pinyin":"shǒuqū-yìzhǐ","meaning_vi":"đứng đầu, số một không ai bằng","explanation":"Khi đếm thì gập ngón tay cái đầu tiên → đứng hàng đầu, số một. Thường: 在国内首屈一指.","hsk_level":6,"tags":["thanh-ngu"],"image":"☝️","examples":[{"type":"basic","zh":"他的厨艺首屈一指。","pinyin":"Tā de chúyì shǒuqūyìzhǐ.","vi":"Tay nghề nấu ăn của anh ấy đứng hàng đầu."},{"type":"simple","zh":"这所大学的医学专业在全国首屈一指。","pinyin":"Zhè suǒ dàxué de yīxué zhuānyè zài quánguó shǒuqūyìzhǐ.","vi":"Ngành y của trường đại học này đứng số một cả nước."},{"type":"compound","zh":"这家工厂不但规模首屈一指，而且技术也最先进。","pinyin":"Zhè jiā gōngchǎng búdàn guīmó shǒuqūyìzhǐ, érqiě jìshù yě zuì xiānjìn.","vi":"Nhà máy này không chỉ có quy mô đứng đầu mà công nghệ cũng tiên tiến nhất."}],"related":[{"hanzi":"数一数二","pinyin":"shǔyishǔ'èr","vi":"nhất nhì"},{"hanzi":"名列前茅","pinyin":"mínglièqiánmáo","vi":"đứng đầu bảng"},{"hanzi":"独占鳌头","pinyin":"dúzhàn'áotóu","vi":"đứng đầu"},{"hanzi":"首位","pinyin":"shǒuwèi","vi":"vị trí đầu"}]},{"id":"手势","hanzi":"手势","pinyin":"shǒushì","meaning_vi":"cử chỉ tay, điệu bộ","explanation":"手 + 势 (tư thế).","hsk_level":6,"tags":["danh-tu","giao-tiep"],"image":"🤟","examples":[{"type":"basic","zh":"他做了个让我安静的手势。","pinyin":"Tā zuòle ge ràng wǒ ānjìng de shǒushì.","vi":"Anh ấy ra hiệu bằng tay bảo tôi im lặng."},{"type":"simple","zh":"交警用手势指挥车辆通过路口。","pinyin":"Jiāojǐng yòng shǒushì zhǐhuī chēliàng tōngguò lùkǒu.","vi":"Cảnh sát giao thông dùng cử chỉ tay điều khiển xe qua ngã tư."},{"type":"compound","zh":"虽然语言不通，但是我们靠手势也能交流。","pinyin":"Suīrán yǔyán bùtōng, dànshì wǒmen kào shǒushì yě néng jiāoliú.","vi":"Tuy bất đồng ngôn ngữ nhưng chúng tôi vẫn giao tiếp được bằng cử chỉ tay."}],"related":[{"hanzi":"姿势","pinyin":"zīshì","vi":"tư thế"},{"hanzi":"手语","pinyin":"shǒuyǔ","vi":"ngôn ngữ ký hiệu"},{"hanzi":"动作","pinyin":"dòngzuò","vi":"động tác"},{"hanzi":"打手势","pinyin":"dǎshǒushì","vi":"ra hiệu bằng tay"}],"traditional":"手勢"},{"id":"首饰","hanzi":"首饰","pinyin":"shǒushì","meaning_vi":"trang sức","explanation":"首 (đầu) + 饰 (trang điểm).","hsk_level":6,"tags":["danh-tu","trang-phuc","do-vat"],"image":"💍","examples":[{"type":"basic","zh":"她很喜欢戴首饰。","pinyin":"Tā hěn xǐhuan dài shǒushì.","vi":"Cô ấy rất thích đeo trang sức."},{"type":"simple","zh":"奶奶把一盒金首饰留给了孙女。","pinyin":"Nǎinai bǎ yì hé jīn shǒushì liúgěile sūnnǚ.","vi":"Bà đã để lại một hộp trang sức vàng cho cháu gái."},{"type":"compound","zh":"出国旅行时，最好别戴贵重的首饰，否则容易被偷。","pinyin":"Chūguó lǚxíng shí, zuìhǎo bié dài guìzhòng de shǒushì, fǒuzé róngyì bèi tōu.","vi":"Khi đi du lịch nước ngoài, tốt nhất đừng đeo trang sức đắt tiền, nếu không dễ bị trộm."}],"related":[{"hanzi":"项链","pinyin":"xiàngliàn","vi":"vòng cổ"},{"hanzi":"戒指","pinyin":"jièzhi","vi":"nhẫn"},{"hanzi":"耳环","pinyin":"ěrhuán","vi":"bông tai"},{"hanzi":"手镯","pinyin":"shǒuzhuó","vi":"vòng tay"}],"traditional":"首飾"},{"id":"手舞足蹈","hanzi":"手舞足蹈","pinyin":"shǒuwǔ-zúdǎo","meaning_vi":"múa tay múa chân vì vui mừng","explanation":"Tay múa chân nhảy → vui sướng đến mức khoa chân múa tay.","hsk_level":6,"tags":["thanh-ngu","cam-xuc"],"image":"🥳","examples":[{"type":"basic","zh":"孩子高兴得手舞足蹈。","pinyin":"Háizi gāoxìng de shǒuwǔzúdǎo.","vi":"Đứa bé vui đến mức múa tay múa chân."},{"type":"simple","zh":"球迷们看到进球，在看台上手舞足蹈。","pinyin":"Qiúmímen kàndào jìnqiú, zài kàntái shang shǒuwǔzúdǎo.","vi":"Thấy bàn thắng, người hâm mộ trên khán đài nhảy múa tưng bừng."},{"type":"compound","zh":"他一收到录取通知书，就高兴得手舞足蹈起来。","pinyin":"Tā yì shōudào lùqǔ tōngzhīshū, jiù gāoxìng de shǒuwǔzúdǎo qǐlái.","vi":"Vừa nhận được giấy báo trúng tuyển, cậu ấy đã vui sướng múa tay múa chân."}],"related":[{"hanzi":"欢呼雀跃","pinyin":"huānhūquèyuè","vi":"reo hò nhảy cẫng"},{"hanzi":"兴高采烈","pinyin":"xìnggāocǎiliè","vi":"hớn hở"},{"hanzi":"欢天喜地","pinyin":"huāntiānxǐdì","vi":"vui mừng khôn xiết"},{"hanzi":"垂头丧气","pinyin":"chuítóusàngqì","vi":"ủ rũ"}]},{"id":"守信用","hanzi":"守信用","pinyin":"shǒuxìnyòng","meaning_vi":"giữ chữ tín","explanation":"守 (giữ) + 信用 (uy tín).","hsk_level":6,"tags":["dong-tu","giao-tiep"],"image":"🤝","examples":[{"type":"basic","zh":"他一向守信用。","pinyin":"Tā yíxiàng shǒuxìnyòng.","vi":"Anh ấy luôn giữ chữ tín."},{"type":"simple","zh":"这家供应商很守信用，从来不拖延交货。","pinyin":"Zhè jiā gōngyìngshāng hěn shǒuxìnyòng, cóngláibù tuōyán jiāohuò.","vi":"Nhà cung cấp này rất giữ chữ tín, chưa bao giờ giao hàng chậm."},{"type":"compound","zh":"只要你守信用，大家就愿意跟你合作。","pinyin":"Zhǐyào nǐ shǒuxìnyòng, dàjiā jiù yuànyì gēn nǐ hézuò.","vi":"Chỉ cần bạn giữ chữ tín thì mọi người sẽ sẵn lòng hợp tác với bạn."}],"related":[{"hanzi":"守信","pinyin":"shǒuxìn","vi":"giữ chữ tín"},{"hanzi":"信用","pinyin":"xìnyòng","vi":"uy tín"},{"hanzi":"言而有信","pinyin":"yán'éryǒuxìn","vi":"nói lời giữ lời"},{"hanzi":"失信","pinyin":"shīxìn","vi":"thất hứa"}]},{"id":"数一数二","hanzi":"数一数二","pinyin":"shǔyi-shǔ'èr","meaning_vi":"thuộc hàng nhất nhì, xuất sắc hàng đầu","explanation":"数 (đọc shǔ - đếm). Thành ngữ.","hsk_level":6,"tags":["thanh-ngu"],"image":"🥇","examples":[{"type":"basic","zh":"她的成绩数一数二。","pinyin":"Tā de chéngjì shǔyishǔ'èr.","vi":"Thành tích của cô ấy thuộc hàng nhất nhì."},{"type":"simple","zh":"这家火锅店在成都是数一数二的。","pinyin":"Zhè jiā huǒguōdiàn zài Chéngdū shì shǔyishǔ'èr de.","vi":"Quán lẩu này thuộc hàng nhất nhì ở Thành Đô."},{"type":"compound","zh":"他虽然年轻，但是技术在厂里数一数二。","pinyin":"Tā suīrán niánqīng, dànshì jìshù zài chǎng lǐ shǔyishǔ'èr.","vi":"Anh ấy tuy còn trẻ nhưng tay nghề thuộc hàng nhất nhì trong xưởng."}],"related":[{"hanzi":"首屈一指","pinyin":"shǒuqūyìzhǐ","vi":"đứng đầu"},{"hanzi":"名列前茅","pinyin":"mínglièqiánmáo","vi":"đứng đầu bảng"},{"hanzi":"出类拔萃","pinyin":"chūlèibácuì","vi":"xuất chúng"},{"hanzi":"屈指可数","pinyin":"qūzhǐkěshǔ","vi":"đếm trên đầu ngón tay"}],"traditional":"數一數二"},{"id":"算了","hanzi":"算了","pinyin":"suànle","meaning_vi":"thôi bỏ đi, thôi vậy","explanation":"Biểu thị sự nhượng bộ hoặc không muốn tính toán nữa.","hsk_level":6,"tags":["dong-tu","giao-tiep"],"image":"🤷","examples":[{"type":"basic","zh":"算了，别生气了。","pinyin":"Suànle, bié shēngqì le.","vi":"Thôi bỏ đi, đừng giận nữa."},{"type":"simple","zh":"这件衣服太贵，我看还是算了吧。","pinyin":"Zhè jiàn yīfu tài guì, wǒ kàn háishì suànle ba.","vi":"Bộ quần áo này đắt quá, tôi thấy thôi bỏ đi."},{"type":"compound","zh":"既然他不想去，那就算了，我们自己去。","pinyin":"Jìrán tā bù xiǎng qù, nà jiù suànle, wǒmen zìjǐ qù.","vi":"Anh ấy đã không muốn đi thì thôi vậy, chúng ta tự đi."}],"related":[{"hanzi":"罢了","pinyin":"bàle","vi":"thôi vậy"},{"hanzi":"拉倒","pinyin":"lādǎo","vi":"thôi bỏ đi"},{"hanzi":"无所谓","pinyin":"wúsuǒwèi","vi":"không sao cả"},{"hanzi":"放弃","pinyin":"fàngqì","vi":"từ bỏ"}]},{"id":"岁月","hanzi":"岁月","pinyin":"suìyuè","meaning_vi":"năm tháng, thời gian","explanation":"岁 (năm) + 月 (tháng).","hsk_level":6,"tags":["danh-tu","thoi-gian"],"image":"⏳","examples":[{"type":"basic","zh":"岁月不饶人。","pinyin":"Suìyuè bù ráo rén.","vi":"Năm tháng chẳng tha một ai."},{"type":"simple","zh":"岁月在爷爷的脸上留下了很多皱纹。","pinyin":"Suìyuè zài yéye de liǎn shang liúxiàle hěn duō zhòuwén.","vi":"Năm tháng đã để lại nhiều nếp nhăn trên gương mặt ông."},{"type":"compound","zh":"虽然岁月流逝，但是我们的友谊一直没变。","pinyin":"Suīrán suìyuè liúshì, dànshì wǒmen de yǒuyì yìzhí méi biàn.","vi":"Tuy năm tháng trôi qua nhưng tình bạn của chúng tôi vẫn không đổi."}],"related":[{"hanzi":"时光","pinyin":"shíguāng","vi":"thời gian"},{"hanzi":"年华","pinyin":"niánhuá","vi":"tuổi xuân"},{"hanzi":"光阴","pinyin":"guāngyīn","vi":"thời gian"},{"hanzi":"岁月如梭","pinyin":"suìyuèrúsuō","vi":"thời gian thấm thoắt"}],"traditional":"歲月"},{"id":"随波逐流","hanzi":"随波逐流","pinyin":"suíbō-zhúliú","meaning_vi":"ba phải, chạy theo số đông không có chính kiến","explanation":"随 (tùy – theo) 波 (ba – sóng) 逐 (trục – đuổi theo) 流 (lưu – dòng) → trôi theo sóng nước → không có chính kiến, theo số đông.","hsk_level":6,"tags":["thanh-ngu"],"image":"🌊","examples":[{"type":"basic","zh":"他不愿随波逐流。","pinyin":"Tā búyuàn suíbōzhúliú.","vi":"Anh ấy không muốn chạy theo số đông."},{"type":"simple","zh":"很多年轻人选专业时只是随波逐流。","pinyin":"Hěn duō niánqīng rénxuǎn zhuānyè shí zhǐshì suíbōzhúliú.","vi":"Nhiều bạn trẻ khi chọn ngành chỉ chạy theo số đông."},{"type":"compound","zh":"与其随波逐流，不如找到自己真正喜欢的事。","pinyin":"Yǔqí suíbōzhúliú, bùrú zhǎodào zìjǐ zhēnzhèng xǐhuan de shì.","vi":"Thay vì chạy theo số đông, chi bằng tìm ra việc mình thật sự yêu thích."}],"related":[{"hanzi":"人云亦云","pinyin":"rényúnyìyún","vi":"hùa theo người khác"},{"hanzi":"随大流","pinyin":"suídàliú","vi":"chạy theo số đông"},{"hanzi":"随声附和","pinyin":"suíshēngfùhè","vi":"phụ họa"},{"hanzi":"特立独行","pinyin":"tèlìdúxíng","vi":"độc lập khác người"}],"traditional":"隨波逐流"},{"id":"随机应变","hanzi":"随机应变","pinyin":"suíjī-yìngbiàn","meaning_vi":"tùy cơ ứng biến","explanation":"随 (tùy – theo) 机 (cơ – thời cơ) 应 (ứng – đối phó) 变 (biến – thay đổi) → tùy tình huống mà ứng phó linh hoạt.","hsk_level":6,"tags":["thanh-ngu"],"image":"⚡","examples":[{"type":"basic","zh":"遇事要随机应变。","pinyin":"Yù shì yào suíjīyìngbiàn.","vi":"Gặp chuyện phải biết tùy cơ ứng biến."},{"type":"simple","zh":"导游随机应变地改了参观路线。","pinyin":"Dǎoyóu suíjīyìngbiàn de gǎile cānguān lùxiàn.","vi":"Hướng dẫn viên tùy cơ ứng biến đổi lộ trình tham quan."},{"type":"compound","zh":"如果面试官问到意外的问题，你就要随机应变。","pinyin":"Rúguǒ miànshìguān wèn dào yìwài de wèntí, nǐ jiùyào suíjīyìngbiàn.","vi":"Nếu người phỏng vấn hỏi câu bất ngờ thì bạn phải tùy cơ ứng biến."}],"related":[{"hanzi":"见机行事","pinyin":"jiànjīxíngshì","vi":"tùy cơ hành sự"},{"hanzi":"灵活","pinyin":"línghuó","vi":"linh hoạt"},{"hanzi":"急中生智","pinyin":"jízhōngshēngzhì","vi":"nguy cấp sinh trí khôn"},{"hanzi":"墨守成规","pinyin":"mòshǒuchéngguī","vi":"khư khư nếp cũ"}],"traditional":"隨機應變"},{"id":"随心所欲","hanzi":"随心所欲","pinyin":"suíxīn-suǒyù","meaning_vi":"tùy tâm sở dục, muốn làm gì thì làm","explanation":"随 (tùy – theo) 心 (tâm) 所欲 (sở dục – điều mong muốn) → làm theo ý muốn; có khi mang nghĩa xấu là tùy tiện.","hsk_level":6,"tags":["thanh-ngu"],"image":"😎","examples":[{"type":"basic","zh":"假期里我想随心所欲。","pinyin":"Jiàqī lǐ wǒ xiǎng suíxīnsuǒyù.","vi":"Kỳ nghỉ này tôi muốn tự do làm điều mình thích."},{"type":"simple","zh":"他在自己的画室里随心所欲地涂鸦。","pinyin":"Tā zài zìjǐ de huàshì lǐ suíxīnsuǒyù de túyā.","vi":"Anh ấy vẽ nguệch ngoạc tùy thích trong phòng vẽ của mình."},{"type":"compound","zh":"即使你是老板，也不能随心所欲地改规定。","pinyin":"Jíshǐ nǐ shì lǎobǎn, yě bù néng suíxīnsuǒyù de gǎi guīdìng.","vi":"Dù bạn là ông chủ cũng không thể muốn sửa quy định thế nào thì sửa."}],"related":[{"hanzi":"为所欲为","pinyin":"wéisuǒyùwéi","vi":"muốn làm gì thì làm"},{"hanzi":"自由自在","pinyin":"zìyóuzìzài","vi":"tự do tự tại"},{"hanzi":"随意","pinyin":"suíyì","vi":"tùy ý"},{"hanzi":"任性","pinyin":"rènxìng","vi":"tùy hứng"}],"traditional":"隨心所欲"},{"id":"随遇而安","hanzi":"随遇而安","pinyin":"suíyù-ér'ān","meaning_vi":"tùy ngộ nhi an (dễ thích nghi với mọi hoàn cảnh)","explanation":"随遇 (theo cảnh ngộ) + 而安 (mà yên) → tùy ngộ nhi an, gặp hoàn cảnh nào cũng an lòng thích nghi.","hsk_level":6,"tags":["thanh-ngu"],"image":"😌","examples":[{"type":"basic","zh":"她性格随遇而安。","pinyin":"Tā xìnggé suíyù'ér'ān.","vi":"Cô ấy có tính cách dễ thích nghi với mọi hoàn cảnh."},{"type":"simple","zh":"外公一辈子随遇而安，从不抱怨生活。","pinyin":"Wàigōng yíbèizi suíyù'ér'ān, cóng bú bàoyuàn shēnghuó.","vi":"Ông ngoại cả đời tùy ngộ nhi an, chưa bao giờ than phiền cuộc sống."},{"type":"compound","zh":"他不管被派到哪里工作，都能随遇而安。","pinyin":"Tā bùguǎn bèi pài dào nǎlǐ gōngzuò, dōu néng suíyù'ér'ān.","vi":"Dù được cử đi làm ở đâu, anh ấy cũng đều thích nghi được."}],"related":[{"hanzi":"适应","pinyin":"shìyìng","vi":"thích nghi"},{"hanzi":"知足常乐","pinyin":"zhīzúchánglè","vi":"biết đủ thì vui"},{"hanzi":"随和","pinyin":"suíhé","vi":"dễ tính"},{"hanzi":"随缘","pinyin":"suíyuán","vi":"tùy duyên"}],"traditional":"隨遇而安"},{"id":"缩影","hanzi":"缩影","pinyin":"suōyǐng","meaning_vi":"hình ảnh thu nhỏ","explanation":"缩 (thu nhỏ) + 影 (hình bóng).","hsk_level":6,"tags":["danh-tu"],"image":"🔍","examples":[{"type":"basic","zh":"这条老街是城市的缩影。","pinyin":"Zhè tiáo lǎojiē shì chéngshì de suōyǐng.","vi":"Con phố cổ này là hình ảnh thu nhỏ của thành phố."},{"type":"simple","zh":"小小的菜市场就是普通人生活的缩影。","pinyin":"Xiǎoxiǎo de càishìchǎng jiùshì pǔtōngrén shēnghuó de suōyǐng.","vi":"Khu chợ nhỏ bé chính là hình ảnh thu nhỏ cuộc sống của người bình thường."},{"type":"compound","zh":"这个家庭的变化不但是个人的故事，而且是时代的缩影。","pinyin":"Zhè ge jiātíng de biànhuà bú dànshì gèrén de gùshi, érqiě shì shídài de suōyǐng.","vi":"Sự thay đổi của gia đình này không chỉ là câu chuyện cá nhân mà còn là hình ảnh thu nhỏ của thời đại."}],"related":[{"hanzi":"缩小","pinyin":"suōxiǎo","vi":"thu nhỏ"},{"hanzi":"象征","pinyin":"xiàngzhēng","vi":"tượng trưng"},{"hanzi":"代表","pinyin":"dàibiǎo","vi":"đại diện"},{"hanzi":"写照","pinyin":"xiězhào","vi":"bức chân dung"}],"traditional":"縮影"},{"id":"所向披靡","hanzi":"所向披靡","pinyin":"suǒxiàng-pīmǐ","meaning_vi":"đánh đâu thắng đó, sức mạnh vô địch","explanation":"所向 (hướng tới đâu) + 披靡 (cỏ cây rạp xuống) → tiến đến đâu đối thủ tan tác đến đó, đánh đâu thắng đó.","hsk_level":6,"tags":["thanh-ngu"],"image":"🏆","examples":[{"type":"basic","zh":"这支球队所向披靡。","pinyin":"Zhè zhī qiúduì suǒxiàngpīmǐ.","vi":"Đội bóng này đánh đâu thắng đó."},{"type":"simple","zh":"那位拳王在赛场上所向披靡。","pinyin":"Nà wèi quánwáng zài sàichǎng shang suǒxiàngpīmǐ.","vi":"Nhà vô địch quyền anh đó bất khả chiến bại trên võ đài."},{"type":"compound","zh":"虽然他们去年所向披靡，但是今年连输了三场。","pinyin":"Suīrán tāmen qùnián suǒxiàngpīmǐ, dànshì jīnnián lián shūle sān chǎng.","vi":"Tuy năm ngoái họ đánh đâu thắng đó nhưng năm nay đã thua liền ba trận."}],"related":[{"hanzi":"所向无敌","pinyin":"suǒxiàngwúdí","vi":"vô địch thiên hạ"},{"hanzi":"势不可当","pinyin":"shìbùkědāng","vi":"không gì cản nổi"},{"hanzi":"战无不胜","pinyin":"zhànwúbúshèng","vi":"đánh đâu thắng đó"},{"hanzi":"无敌","pinyin":"wúdí","vi":"vô địch"}]},{"id":"索性","hanzi":"索性","pinyin":"suǒxìng","meaning_vi":"dứt khoát, thôi thì, chi bằng","explanation":"索 (tác) + 性 (tính) → phó từ: dứt khoát, thôi thì làm luôn. Ví dụ: 雨太大，索性不去了.","hsk_level":6,"tags":["pho-tu"],"image":"⚡","examples":[{"type":"basic","zh":"我索性不睡了。","pinyin":"Wǒ suǒxìng bú shuì le.","vi":"Tôi dứt khoát không ngủ nữa."},{"type":"simple","zh":"雨太大了，我们索性在咖啡馆多坐一会儿。","pinyin":"Yǔ tài dà le, wǒmen suǒxìng zài kāfēiguǎn duō zuò yíhuìr.","vi":"Mưa to quá, chúng tôi thôi thì ngồi thêm một lúc ở quán cà phê."},{"type":"compound","zh":"既然已经迟到了，他就索性请了一天假。","pinyin":"Jìrán yǐjīng chídào le, tā jiù suǒxìng qǐngle yì tiān jià.","vi":"Đã muộn rồi nên anh ấy dứt khoát xin nghỉ luôn một ngày."}],"related":[{"hanzi":"干脆","pinyin":"gāncuì","vi":"dứt khoát"},{"hanzi":"不如","pinyin":"bùrú","vi":"chi bằng"},{"hanzi":"干脆利落","pinyin":"gāncuìlìluo","vi":"nhanh gọn dứt khoát"}]},{"id":"所作所为","hanzi":"所作所为","pinyin":"suǒzuò-suǒwéi","meaning_vi":"những việc đã làm, hành vi","explanation":"所作 (sở tác) + 所为 (sở vi) → tất cả những việc đã làm, hành vi; thường hàm ý phê phán.","hsk_level":6,"tags":["thanh-ngu"],"image":"👤","examples":[{"type":"basic","zh":"他为自己的所作所为后悔。","pinyin":"Tā wèi zìjǐ de suǒzuòsuǒwéi hòuhuǐ.","vi":"Anh ấy hối hận về những việc mình đã làm."},{"type":"simple","zh":"老百姓都看清了那个贪官的所作所为。","pinyin":"Lǎobǎixìng dōu kànqīngle nà ge tānguān de suǒzuòsuǒwéi.","vi":"Dân chúng đều đã thấy rõ hành vi của tên quan tham đó."},{"type":"compound","zh":"如果你的所作所为对得起良心，就不用怕别人议论。","pinyin":"Rúguǒ nǐ de suǒzuòsuǒwéi duìdeqǐ liángxīn, jiù bú yòng pà biérén yìlùn.","vi":"Nếu những việc bạn làm không thẹn với lương tâm thì không cần sợ người khác bàn tán."}],"related":[{"hanzi":"行为","pinyin":"xíngwéi","vi":"hành vi"},{"hanzi":"言行","pinyin":"yánxíng","vi":"lời nói và việc làm"},{"hanzi":"举动","pinyin":"jǔdòng","vi":"cử chỉ hành động"},{"hanzi":"作为","pinyin":"zuòwéi","vi":"việc làm"}],"traditional":"所作所為"},{"id":"四海为家","hanzi":"四海为家","pinyin":"sìhǎi-wéijiā","meaning_vi":"bốn bể là nhà","explanation":"Lấy bốn biển làm nhà → sống phiêu bạt khắp nơi, đâu cũng là nhà; cũng chỉ chí lớn bôn ba.","hsk_level":6,"tags":["thanh-ngu"],"image":"🌍","examples":[{"type":"basic","zh":"他年轻时四海为家。","pinyin":"Tā niánqīng shí sìhǎiwéijiā.","vi":"Lúc trẻ anh ấy coi bốn bể là nhà."},{"type":"simple","zh":"这位摄影师背着相机四海为家。","pinyin":"Zhè wèi shèyǐngshī bēizhe xiàngjī sìhǎiwéijiā.","vi":"Nhà nhiếp ảnh này đeo máy ảnh rong ruổi bốn phương."},{"type":"compound","zh":"因为工作需要经常出差，所以他早已习惯了四海为家。","pinyin":"Yīnwèi gōngzuò xūyào jīngcháng chūchāi, suǒyǐ tā zǎoyǐ xíguànle sìhǎiwéijiā.","vi":"Vì công việc phải đi công tác thường xuyên nên anh ấy đã quen sống bốn bể là nhà."}],"related":[{"hanzi":"四面八方","pinyin":"sìmiànbāfāng","vi":"bốn phương tám hướng"},{"hanzi":"漂泊","pinyin":"piāobó","vi":"phiêu bạt"},{"hanzi":"流浪","pinyin":"liúlàng","vi":"lang thang"},{"hanzi":"走南闯北","pinyin":"zǒunánchuǎngběi","vi":"đi khắp nơi"}],"traditional":"四海為家"},{"id":"四面八方","hanzi":"四面八方","pinyin":"sìmiàn-bāfāng","meaning_vi":"bốn phương tám hướng, khắp mọi nơi","explanation":"四面 (bốn mặt) + 八方 (tám phương) → khắp mọi nơi, mọi hướng. Cụm: 从四面八方赶来.","hsk_level":6,"tags":["thanh-ngu","phuong-huong"],"image":"🧭","examples":[{"type":"basic","zh":"人们从四面八方赶来。","pinyin":"Rénmen cóng sìmiànbāfāng gǎnlái.","vi":"Mọi người từ bốn phương tám hướng kéo đến."},{"type":"simple","zh":"音乐节吸引了来自四面八方的游客。","pinyin":"Yīnyuèjié xīyǐnle láizì sìmiànbāfāng de yóukè.","vi":"Lễ hội âm nhạc thu hút du khách từ khắp mọi nơi."},{"type":"compound","zh":"他一发出求助信息，四面八方的朋友就都打来了电话。","pinyin":"Tā yì fāchū qiúzhù xìnxī, sìmiànbāfāng de péngyou jiù dōu dǎ láile diànhuà.","vi":"Anh ấy vừa đăng tin cần giúp đỡ, bạn bè khắp nơi đều gọi điện đến."}],"related":[{"hanzi":"四海为家","pinyin":"sìhǎiwéijiā","vi":"bốn bể là nhà"},{"hanzi":"到处","pinyin":"dàochù","vi":"khắp nơi"},{"hanzi":"各地","pinyin":"gèdì","vi":"các nơi"},{"hanzi":"五湖四海","pinyin":"wǔhúsìhǎi","vi":"năm châu bốn bể"}]},{"id":"肆虐","hanzi":"肆虐","pinyin":"sìnüè","meaning_vi":"hoành hành tàn phá (bão lũ/dịch bệnh)","explanation":"肆 + 虐 (tàn bạo).","hsk_level":6,"tags":["dong-tu","thien-nhien"],"image":"🌪️","examples":[{"type":"basic","zh":"洪水在南方肆虐。","pinyin":"Hóngshuǐ zài nánfāng sìnüè.","vi":"Lũ lụt đang hoành hành ở miền Nam."},{"type":"simple","zh":"流感今年冬天在多个城市肆虐。","pinyin":"Liúgǎn jīnnián dōngtiān zài duōgè chéngshì sìnüè.","vi":"Mùa đông năm nay dịch cúm hoành hành ở nhiều thành phố."},{"type":"compound","zh":"台风肆虐了整整一夜，所以第二天到处都是倒下的树。","pinyin":"Táifēng sìnüèle zhěngzhěng yī yè, suǒyǐ dì'èrtiān dàochù dōu shì dǎoxià de shù.","vi":"Bão tàn phá suốt cả đêm nên hôm sau khắp nơi toàn cây đổ."}],"related":[{"hanzi":"蔓延","pinyin":"mànyán","vi":"lan tràn"},{"hanzi":"横行","pinyin":"héngxíng","vi":"hoành hành"},{"hanzi":"破坏","pinyin":"pòhuài","vi":"phá hoại"},{"hanzi":"灾害","pinyin":"zāihài","vi":"thiên tai"}]},{"id":"似是而非","hanzi":"似是而非","pinyin":"sìshì-érfēi","meaning_vi":"tưởng đúng mà sai, mập mờ","explanation":"似是 (giống như đúng) + 而非 (mà sai). Thành ngữ.","hsk_level":6,"tags":["thanh-ngu"],"image":"🤔","examples":[{"type":"basic","zh":"这个说法似是而非。","pinyin":"Zhè ge shuōfǎ sìshì'érfēi.","vi":"Cách nói này tưởng đúng mà sai."},{"type":"simple","zh":"网上有很多似是而非的健康知识。","pinyin":"Wǎngshang yǒu hěn duō sìshì'érfēi de jiànkāng zhīshi.","vi":"Trên mạng có rất nhiều kiến thức sức khỏe nghe thì đúng mà thực ra sai."},{"type":"compound","zh":"这些观点虽然听起来有道理，但是其实似是而非。","pinyin":"Zhèxiē guāndiǎn suīrán tīngqǐlái yǒudàoli, dànshì qíshí sìshì'érfēi.","vi":"Những quan điểm này tuy nghe có lý nhưng thực ra tưởng đúng mà sai."}],"related":[{"hanzi":"模棱两可","pinyin":"móléngliǎngkě","vi":"nước đôi mập mờ"},{"hanzi":"含糊","pinyin":"hánhu","vi":"mơ hồ"},{"hanzi":"自相矛盾","pinyin":"zìxiāngmáodùn","vi":"tự mâu thuẫn"},{"hanzi":"混淆","pinyin":"hùnxiáo","vi":"lẫn lộn"}]},{"id":"饲养","hanzi":"饲养","pinyin":"sìyǎng","meaning_vi":"chăn nuôi, nuôi dưỡng (động vật)","explanation":"饲 (cho ăn) + 养 (nuôi).","hsk_level":6,"tags":["dong-tu","dong-vat"],"image":"🐄","examples":[{"type":"basic","zh":"他在农场饲养奶牛。","pinyin":"Tā zài nóngchǎng sìyǎng nǎiniú.","vi":"Anh ấy nuôi bò sữa ở trang trại."},{"type":"simple","zh":"动物园的工作人员负责饲养大熊猫。","pinyin":"Dòngwùyuán de gōngzuò rényuán fùzé sìyǎng dàxióngmāo.","vi":"Nhân viên vườn thú phụ trách chăm nuôi gấu trúc."},{"type":"compound","zh":"如果饲养方法不科学，鸡就容易生病。","pinyin":"Rúguǒ sìyǎng fāngfǎ bù kēxué, jī jiù róngyì shēngbìng.","vi":"Nếu phương pháp chăn nuôi không khoa học thì gà dễ bị bệnh."}],"related":[{"hanzi":"养","pinyin":"yǎng","vi":"nuôi"},{"hanzi":"喂养","pinyin":"wèiyǎng","vi":"cho ăn nuôi dưỡng"},{"hanzi":"饲料","pinyin":"sìliào","vi":"thức ăn gia súc"},{"hanzi":"养殖","pinyin":"yǎngzhí","vi":"nuôi trồng"}],"traditional":"飼養"},{"id":"素不相识","hanzi":"素不相识","pinyin":"sùbù-xiāngshí","meaning_vi":"chưa từng quen biết nhau","explanation":"素 (vốn dĩ) + 不相识. Thành ngữ.","hsk_level":6,"tags":["thanh-ngu"],"image":"👤","examples":[{"type":"basic","zh":"我们素不相识。","pinyin":"Wǒmen sùbùxiāngshí.","vi":"Chúng tôi chưa từng quen biết nhau."},{"type":"simple","zh":"一位素不相识的路人帮我推了车。","pinyin":"Yí wèi sùbùxiāngshí de lùrén bāng wǒ tuīle chē.","vi":"Một người qua đường không quen biết đã giúp tôi đẩy xe."},{"type":"compound","zh":"虽然我们素不相识，但是他还是热情地给我指了路。","pinyin":"Suīrán wǒmen sùbùxiāngshí, dànshì tā háishì rèqíng de gěi wǒ zhǐle lù.","vi":"Tuy chúng tôi không hề quen biết nhưng anh ấy vẫn nhiệt tình chỉ đường cho tôi."}],"related":[{"hanzi":"陌生","pinyin":"mòshēng","vi":"xa lạ"},{"hanzi":"陌生人","pinyin":"mòshēngrén","vi":"người lạ"},{"hanzi":"相识","pinyin":"xiāngshí","vi":"quen biết"},{"hanzi":"萍水相逢","pinyin":"píngshuǐxiāngféng","vi":"bèo nước gặp nhau"}],"traditional":"素不相識"},{"id":"素食","hanzi":"素食","pinyin":"sùshí","meaning_vi":"đồ ăn chay, ăn chay","explanation":"素 (thanh đạm/chay) + 食 (thức ăn).","hsk_level":6,"tags":["danh-tu","an-uong"],"image":"🥗","examples":[{"type":"basic","zh":"她只吃素食。","pinyin":"Tā zhǐ chī sùshí.","vi":"Cô ấy chỉ ăn đồ chay."},{"type":"simple","zh":"这家素食餐厅的豆腐做得特别好吃。","pinyin":"Zhè jiā sùshí cāntīng de dòufu zuò de tèbié hǎochī.","vi":"Món đậu phụ của nhà hàng chay này làm rất ngon."},{"type":"compound","zh":"自从改吃素食，他不但瘦了，而且精神更好了。","pinyin":"Zìcóng gǎi chī sùshí, tā búdàn shòu le, érqiě jīngshen gèng hǎo le.","vi":"Từ khi chuyển sang ăn chay, anh ấy không chỉ gầy đi mà tinh thần còn tốt hơn."}],"related":[{"hanzi":"吃素","pinyin":"chīsù","vi":"ăn chay"},{"hanzi":"素食者","pinyin":"sùshízhě","vi":"người ăn chay"},{"hanzi":"荤菜","pinyin":"hūncài","vi":"món mặn"},{"hanzi":"蔬菜","pinyin":"shūcài","vi":"rau"}]},{"id":"俗不可耐","hanzi":"俗不可耐","pinyin":"súbù-kěnài","meaning_vi":"tầm thường dung tục không chịu nổi","explanation":"俗 (tục – tầm thường) + 不可耐 (không thể chịu) → dung tục, thô thiển đến khó chịu.","hsk_level":6,"tags":["thanh-ngu"],"image":"😒","examples":[{"type":"basic","zh":"这种装修俗不可耐。","pinyin":"Zhè zhǒng zhuāngxiū súbùkěnài.","vi":"Kiểu trang trí này dung tục không chịu nổi."},{"type":"simple","zh":"那部电视剧的台词写得俗不可耐。","pinyin":"Nà bù diànshìjù de táicí xiě de súbùkěnài.","vi":"Lời thoại của bộ phim truyền hình đó được viết tầm thường không chịu nổi."},{"type":"compound","zh":"他总是炫耀自己的名牌，所以大家觉得他俗不可耐。","pinyin":"Tā zǒngshì xuànyào zìjǐ de míngpái, suǒyǐ dàjiā juéde tā súbùkěnài.","vi":"Anh ta lúc nào cũng khoe đồ hiệu nên mọi người thấy anh ta dung tục không chịu nổi."}],"related":[{"hanzi":"庸俗","pinyin":"yōngsú","vi":"dung tục"},{"hanzi":"俗气","pinyin":"súqi","vi":"quê mùa thô tục"},{"hanzi":"低俗","pinyin":"dīsú","vi":"thấp kém tầm thường"},{"hanzi":"高雅","pinyin":"gāoyǎ","vi":"thanh nhã"}]},{"id":"塞","hanzi":"塞","pinyin":"sāi","meaning_vi":"nhét vào, nút lại","explanation":"Bộ thổ 土 + 寒. Ví dụ: 塞车 (tắc xe), 瓶塞 (nút chai).","hsk_level":6,"tags":["dong-tu"],"image":"🍾","examples":[{"type":"basic","zh":"抽屉塞满了。","pinyin":"Chōuti sāimǎn le.","vi":"Ngăn kéo đã nhét đầy rồi."},{"type":"simple","zh":"妈妈往我的包里塞了两个苹果。","pinyin":"Māma wǎng wǒ de bāo lǐ sāile liǎng gè píngguǒ.","vi":"Mẹ nhét vào túi tôi hai quả táo."},{"type":"compound","zh":"行李箱已经塞得满满的，再也放不下了。","pinyin":"Xínglixiāng yǐjīng sāi de mǎnmǎn de, zài yě fàngbuxià le.","vi":"Vali đã nhét chật cứng, không thể để thêm gì nữa."}],"related":[{"hanzi":"塞车","pinyin":"sāichē","vi":"tắc đường"},{"hanzi":"堵塞","pinyin":"dǔsè","vi":"tắc nghẽn"},{"hanzi":"塞子","pinyin":"sāizi","vi":"cái nút"},{"hanzi":"填","pinyin":"tián","vi":"lấp đầy"}]},{"id":"三思而后行","hanzi":"三思而后行","pinyin":"sānsī érhòu xíng","meaning_vi":"suy nghĩ kỹ càng rồi mới hành động","explanation":"Suy nghĩ ba lần rồi mới làm (Luận Ngữ, nói về Quý Văn Tử) → cân nhắc kỹ càng trước khi hành động.","hsk_level":6,"tags":["thanh-ngu"],"image":"🤔","examples":[{"type":"basic","zh":"凡事要三思而后行。","pinyin":"Fánshì yào sānsī'érhòuxíng.","vi":"Việc gì cũng phải suy nghĩ kỹ rồi mới làm."},{"type":"simple","zh":"爸爸提醒我辞职前要三思而后行。","pinyin":"Bàba tíxǐng wǒ cízhí qián yào sānsī'érhòuxíng.","vi":"Bố nhắc tôi trước khi nghỉ việc phải suy nghĩ kỹ rồi mới hành động."},{"type":"compound","zh":"投资风险很大，所以你最好三思而后行。","pinyin":"Tóuzī fēngxiǎn hěn dà, suǒyǐ nǐ zuìhǎo sānsī'érhòuxíng.","vi":"Đầu tư rủi ro rất lớn nên tốt nhất bạn hãy suy nghĩ kỹ rồi mới làm."}],"related":[{"hanzi":"深思熟虑","pinyin":"shēnsīshúlǜ","vi":"suy nghĩ thấu đáo"},{"hanzi":"慎重","pinyin":"shènzhòng","vi":"thận trọng"},{"hanzi":"谨慎","pinyin":"jǐnshèn","vi":"cẩn thận"},{"hanzi":"轻举妄动","pinyin":"qīngjǔwàngdòng","vi":"hành động khinh suất"}],"traditional":"三思而後行"},{"id":"三心二意","hanzi":"三心二意","pinyin":"sānxīn-èryì","meaning_vi":"đứng núi này trông núi nọ, thiếu tập trung","explanation":"三心 (ba lòng) + 二意 (hai ý) → không chuyên tâm, do dự, hay thay đổi. Ví dụ: 做事不能三心二意.","hsk_level":6,"tags":["thanh-ngu"],"image":"🔀","examples":[{"type":"basic","zh":"学习别三心二意。","pinyin":"Xuéxí bié sānxīn'èryì.","vi":"Học hành đừng có thiếu tập trung."},{"type":"simple","zh":"他一边写作业一边看电视，三心二意的。","pinyin":"Tā yìbiān xiě zuòyè yìbiān kàn diànshì, sānxīn'èryì de.","vi":"Cậu ấy vừa làm bài tập vừa xem tivi, chẳng tập trung gì cả."},{"type":"compound","zh":"如果你做事总是三心二意，就什么也做不好。","pinyin":"Rúguǒ nǐ zuòshì zǒngshì sānxīn'èryì, jiù shénme yě zuò bu hǎo.","vi":"Nếu bạn làm việc lúc nào cũng thiếu tập trung thì chẳng làm tốt được việc gì."}],"related":[{"hanzi":"一心一意","pinyin":"yìxīnyíyì","vi":"một lòng một dạ"},{"hanzi":"心不在焉","pinyin":"xīnbúzàiyān","vi":"lơ đãng"},{"hanzi":"专心","pinyin":"zhuānxīn","vi":"chuyên tâm"},{"hanzi":"犹豫不决","pinyin":"yóuyùbùjué","vi":"do dự không quyết"}]},{"id":"骚扰","hanzi":"骚扰","pinyin":"sāorǎo","meaning_vi":"quấy rối, làm phiền","explanation":"骚 + 扰 (quấy rầy).","hsk_level":6,"tags":["dong-tu"],"image":"📵","examples":[{"type":"basic","zh":"请不要骚扰我。","pinyin":"Qǐng bú yào sāorǎo wǒ.","vi":"Xin đừng làm phiền tôi."},{"type":"simple","zh":"最近我天天接到推销保险的骚扰电话。","pinyin":"Zuìjìn wǒ tiāntiān jiēdào tuīxiāo bǎoxiǎn de sāorǎo diànhuà.","vi":"Dạo này ngày nào tôi cũng nhận được cuộc gọi quấy rối chào bán bảo hiểm."},{"type":"compound","zh":"如果那个人再打电话骚扰你，你就马上报警。","pinyin":"Rúguǒ nàgerén zài dǎdiànhuà sāorǎo nǐ, nǐ jiù mǎshàng bàojǐng.","vi":"Nếu người đó còn gọi điện quấy rối bạn thì bạn hãy báo cảnh sát ngay."}],"related":[{"hanzi":"打扰","pinyin":"dǎrǎo","vi":"làm phiền"},{"hanzi":"干扰","pinyin":"gānrǎo","vi":"quấy nhiễu"},{"hanzi":"性骚扰","pinyin":"xìngsāorǎo","vi":"quấy rối tình dục"},{"hanzi":"骚扰电话","pinyin":"sāorǎodiànhuà","vi":"cuộc gọi quấy rối"}],"traditional":"騷擾"},{"id":"森严","hanzi":"森严","pinyin":"sēnyán","meaning_vi":"nghiêm ngặt, trang nghiêm (canh gác/kỷ luật)","explanation":"森 (sâm – dày đặc) + 严 (nghiêm) → nghiêm ngặt, chặt chẽ. Cụm: 戒备森严, 等级森严.","hsk_level":6,"tags":["tinh-tu"],"image":"🛡️","examples":[{"type":"basic","zh":"这里戒备森严。","pinyin":"Zhèlǐ jièbèi sēnyán.","vi":"Nơi đây canh gác nghiêm ngặt."},{"type":"simple","zh":"古代皇宫里的等级制度十分森严。","pinyin":"Gǔdài huánggōng lǐ de děngjí zhìdù shífēn sēnyán.","vi":"Chế độ đẳng cấp trong hoàng cung thời xưa vô cùng nghiêm ngặt."},{"type":"compound","zh":"因为峰会在这里召开，所以酒店周围戒备森严。","pinyin":"Yīnwèi fēnghuì zài zhèlǐ zhàokāi, suǒyǐ jiǔdiàn zhōuwéi jièbèi sēnyán.","vi":"Vì hội nghị thượng đỉnh được tổ chức ở đây nên xung quanh khách sạn canh gác nghiêm ngặt."}],"related":[{"hanzi":"戒备森严","pinyin":"jièbèisēnyán","vi":"canh phòng nghiêm ngặt"},{"hanzi":"严密","pinyin":"yánmì","vi":"chặt chẽ"},{"hanzi":"严格","pinyin":"yángé","vi":"nghiêm khắc"},{"hanzi":"庄严","pinyin":"zhuāngyán","vi":"trang nghiêm"}],"traditional":"森嚴"},{"id":"司法","hanzi":"司法","pinyin":"sīfǎ","meaning_vi":"tư pháp","explanation":"司 (quản lý) + 法 (pháp luật).","hsk_level":6,"tags":["danh-tu","phap-luat"],"image":"⚖️","examples":[{"type":"basic","zh":"司法必须公正。","pinyin":"Sīfǎ bìxū gōngzhèng.","vi":"Tư pháp phải công bằng."},{"type":"simple","zh":"这起案件已经进入司法程序。","pinyin":"Zhè qǐ ànjiàn yǐjīng jìnrù sīfǎ chéngxù.","vi":"Vụ án này đã bước vào trình tự tư pháp."},{"type":"compound","zh":"只有司法独立，百姓才能真正信任法院。","pinyin":"Zhǐyǒu sīfǎ dúlì, bǎixìng cáinéng zhēnzhèng xìnrèn fǎyuàn.","vi":"Chỉ khi tư pháp độc lập thì người dân mới thật sự tin tưởng tòa án."}],"related":[{"hanzi":"法律","pinyin":"fǎlǜ","vi":"pháp luật"},{"hanzi":"法院","pinyin":"fǎyuàn","vi":"tòa án"},{"hanzi":"立法","pinyin":"lìfǎ","vi":"lập pháp"},{"hanzi":"执法","pinyin":"zhífǎ","vi":"thực thi pháp luật"}]},{"id":"司空见惯","hanzi":"司空见惯","pinyin":"sīkōng-jiànguàn","meaning_vi":"chuyện thường tình ở huyện, thấy mãi thành quen","explanation":"Quan Tư Không (Lý Thân) xem ca múa mãi đã quen (thơ Lưu Vũ Tích) → chuyện thường gặp, chẳng có gì lạ.","hsk_level":6,"tags":["thanh-ngu"],"image":"🤷","examples":[{"type":"basic","zh":"这种事司空见惯。","pinyin":"Zhè zhǒng shì sīkōngjiànguàn.","vi":"Chuyện này đã quá quen thuộc."},{"type":"simple","zh":"在大城市，早高峰堵车已经司空见惯了。","pinyin":"Zài dàchéngshì, zǎogāofēng dǔchē yǐjīng sīkōngjiànguàn le.","vi":"Ở thành phố lớn, kẹt xe giờ cao điểm buổi sáng đã quá quen thuộc."},{"type":"compound","zh":"虽然网购退货早已司空见惯，但是老人还是不太会操作。","pinyin":"Suīrán wǎnggòu tuìhuò zǎoyǐ sīkōngjiànguàn, dànshì lǎorén háishì bú tài huì cāozuò.","vi":"Tuy trả hàng khi mua online đã là chuyện thường nhưng người già vẫn chưa biết thao tác lắm."}],"related":[{"hanzi":"习以为常","pinyin":"xíyǐwéicháng","vi":"quen thành thói"},{"hanzi":"屡见不鲜","pinyin":"lǚjiànbùxiān","vi":"thường thấy chẳng lạ"},{"hanzi":"平常","pinyin":"píngcháng","vi":"bình thường"},{"hanzi":"少见多怪","pinyin":"shǎojiànduōguài","vi":"ít thấy nên lạ"}],"traditional":"司空見慣"},{"id":"思索","hanzi":"思索","pinyin":"sīsuǒ","meaning_vi":"suy tư, tìm tòi suy nghĩ","explanation":"思 (tư – nghĩ) + 索 (tác – tìm) → suy nghĩ tìm tòi. Cụm: 不假思索 (không cần suy nghĩ).","hsk_level":6,"tags":["dong-tu","nhan-thuc"],"image":"🤔","examples":[{"type":"basic","zh":"他低头思索着。","pinyin":"Tā dītóu sīsuǒ zhe.","vi":"Anh ấy cúi đầu suy tư."},{"type":"simple","zh":"老师的问题让全班同学陷入了思索。","pinyin":"Lǎoshī de wèntí ràng quánbān tóngxué xiànrùle sīsuǒ.","vi":"Câu hỏi của thầy giáo khiến cả lớp chìm vào suy nghĩ."},{"type":"compound","zh":"她不假思索地回答了问题，可是答案却错了。","pinyin":"Tā bù jiǎ sīsuǒ de huídále wèntí, kěshì dá'àn què cuò le.","vi":"Cô ấy trả lời câu hỏi chẳng cần suy nghĩ, nhưng đáp án lại sai."}],"related":[{"hanzi":"思考","pinyin":"sīkǎo","vi":"suy nghĩ"},{"hanzi":"考虑","pinyin":"kǎolǜ","vi":"cân nhắc"},{"hanzi":"琢磨","pinyin":"zuómo","vi":"nghiền ngẫm"},{"hanzi":"不假思索","pinyin":"bùjiǎsīsuǒ","vi":"không cần nghĩ ngợi"}]},{"id":"苏醒","hanzi":"苏醒","pinyin":"sūxǐng","meaning_vi":"tỉnh lại, hồi tỉnh","explanation":"苏 (tô – sống lại) + 醒 (tỉnh – tỉnh) → tỉnh lại sau hôn mê; nghĩa bóng vạn vật hồi sinh. Cụm: 大地苏醒.","hsk_level":6,"tags":["dong-tu","suc-khoe"],"image":"👀","examples":[{"type":"basic","zh":"病人终于苏醒了。","pinyin":"Bìngrén zhōngyú sūxǐng le.","vi":"Bệnh nhân cuối cùng đã tỉnh lại."},{"type":"simple","zh":"春风吹过，沉睡的大地渐渐苏醒。","pinyin":"Chūnfēng chuī guò, chénshuì de dàdì jiànjiàn sūxǐng.","vi":"Gió xuân thổi qua, mặt đất say ngủ dần dần thức giấc."},{"type":"compound","zh":"他昏迷了三天，一苏醒就问家人在哪儿。","pinyin":"Tā hūnmíle sān tiān, yì sūxǐng jiù wèn jiārén zài nǎr.","vi":"Anh ấy hôn mê ba ngày, vừa tỉnh lại đã hỏi người nhà đâu."}],"related":[{"hanzi":"醒","pinyin":"xǐng","vi":"tỉnh"},{"hanzi":"清醒","pinyin":"qīngxǐng","vi":"tỉnh táo"},{"hanzi":"昏迷","pinyin":"hūnmí","vi":"hôn mê"},{"hanzi":"复苏","pinyin":"fùsū","vi":"hồi phục"}],"traditional":"蘇醒"},{"id":"散文","hanzi":"散文","pinyin":"sǎnwén","meaning_vi":"tản văn","explanation":"散 (đọc sǎn) + 文 (văn chương).","hsk_level":6,"tags":["danh-tu","van-hoa","hoc-tap"],"image":"📖","examples":[{"type":"basic","zh":"我喜欢读散文。","pinyin":"Wǒ xǐhuan dú sǎnwén.","vi":"Tôi thích đọc tản văn."},{"type":"simple","zh":"朱自清的散文语言优美而朴素。","pinyin":"Zhūzìqīng de sǎnwén yǔyán yōuměi ér pǔsù.","vi":"Tản văn của Chu Tự Thanh có ngôn từ đẹp mà mộc mạc."},{"type":"compound","zh":"这篇散文虽然不长，但是写出了浓浓的乡愁。","pinyin":"Zhè piān sǎnwén suīrán bù cháng, dànshì xiě chūle nóng nóng de xiāngchóu.","vi":"Bài tản văn này tuy không dài nhưng đã viết nên nỗi nhớ quê da diết."}],"related":[{"hanzi":"诗歌","pinyin":"shīgē","vi":"thơ ca"},{"hanzi":"小说","pinyin":"xiǎoshuō","vi":"tiểu thuyết"},{"hanzi":"文学","pinyin":"wénxué","vi":"văn học"},{"hanzi":"随笔","pinyin":"suíbǐ","vi":"tùy bút"}]},{"id":"死气沉沉","hanzi":"死气沉沉","pinyin":"sǐqì-chénchén","meaning_vi":"ảm đạm thiếu sức sống","explanation":"死气 (khí chết) + 沉沉 (nặng nề) → không khí ảm đạm, thiếu sinh khí. Trái nghĩa: 生气勃勃.","hsk_level":6,"tags":["thanh-ngu"],"image":"😴","examples":[{"type":"basic","zh":"会场死气沉沉的。","pinyin":"Huìchǎng sǐqìchénchén de.","vi":"Hội trường ảm đạm thiếu sức sống."},{"type":"simple","zh":"下雨天的商业街显得死气沉沉。","pinyin":"Xià yǔtiān de shāngyè jiē xiǎnde sǐqìchénchén.","vi":"Phố thương mại ngày mưa trông ảm đạm vắng vẻ."},{"type":"compound","zh":"自从老师来了以后，原来死气沉沉的班级变得活跃了。","pinyin":"Zìcóng lǎoshī láile yǐhòu, yuánlái sǐqìchénchén de bānjí biànde huóyuè le.","vi":"Từ khi cô giáo đến, lớp học vốn ảm đạm đã trở nên sôi nổi."}],"related":[{"hanzi":"无精打采","pinyin":"wújīngdǎcǎi","vi":"ủ rũ"},{"hanzi":"生机勃勃","pinyin":"shēngjībóbó","vi":"tràn đầy sức sống"},{"hanzi":"沉闷","pinyin":"chénmèn","vi":"nặng nề buồn tẻ"},{"hanzi":"朝气蓬勃","pinyin":"zhāoqìpéngbó","vi":"hăng hái tràn đầy"}],"traditional":"死氣沉沉"},{"id":"死亡","hanzi":"死亡","pinyin":"sǐwáng","meaning_vi":"tử vong, cái chết","explanation":"死 (chết) + 亡 (mất).","hsk_level":6,"tags":["dong-tu","suc-khoe"],"image":"🕯️","examples":[{"type":"basic","zh":"车祸造成两人死亡。","pinyin":"Chēhuò zàochéng liǎng rén sǐwáng.","vi":"Vụ tai nạn xe khiến hai người tử vong."},{"type":"simple","zh":"吸烟是导致肺癌死亡的主要原因之一。","pinyin":"Xīyān shì dǎozhì fèi'ái sǐwáng de zhǔyào yuányīn zhīyī.","vi":"Hút thuốc là một trong những nguyên nhân chính gây tử vong do ung thư phổi."},{"type":"compound","zh":"如果救护车晚到十分钟，病人就可能死亡。","pinyin":"Rúguǒ jiùhùchē wǎn dào shí fēnzhōng, bìngrén jiù kěnéng sǐwáng.","vi":"Nếu xe cứu thương đến muộn mười phút thì bệnh nhân có thể đã tử vong."}],"related":[{"hanzi":"死","pinyin":"sǐ","vi":"chết"},{"hanzi":"去世","pinyin":"qùshì","vi":"qua đời"},{"hanzi":"生命","pinyin":"shēngmìng","vi":"sinh mệnh"},{"hanzi":"出生","pinyin":"chūshēng","vi":"ra đời"}]},{"id":"死心塌地","hanzi":"死心塌地","pinyin":"sǐxīn-tādì","meaning_vi":"một lòng một dạ, ngoan cố không đổi","explanation":"死心 (lòng đã quyết) + 塌地 (yên vị) → một lòng một dạ không đổi; thường mang ý chê (cam tâm theo kẻ xấu).","hsk_level":6,"tags":["thanh-ngu"],"image":"✊","examples":[{"type":"basic","zh":"她死心塌地爱着他。","pinyin":"Tā sǐxīntādì àizhe tā.","vi":"Cô ấy một lòng một dạ yêu anh ấy."},{"type":"simple","zh":"这位老员工死心塌地地跟着老板干了二十年。","pinyin":"Zhè wèi lǎo yuángōng sǐxīntādì de gēnzhe lǎobǎn gànle èrshí nián.","vi":"Nhân viên lâu năm này một lòng một dạ theo ông chủ suốt hai mươi năm."},{"type":"compound","zh":"虽然大家都劝他回头，但是他死心塌地要跟那伙人走。","pinyin":"Suīrán dàjiā dōu quàn tā huítóu, dànshì tā sǐxīntādì yào gēn nà huǒ rén zǒu.","vi":"Tuy mọi người đều khuyên anh ta quay đầu nhưng anh ta vẫn khăng khăng theo bọn người kia."}],"related":[{"hanzi":"一心一意","pinyin":"yìxīnyíyì","vi":"một lòng một dạ"},{"hanzi":"忠心耿耿","pinyin":"zhōngxīngěnggěng","vi":"trung thành tận tụy"},{"hanzi":"执迷不悟","pinyin":"zhímíbúwù","vi":"u mê không tỉnh"},{"hanzi":"死心","pinyin":"sǐxīn","vi":"hết hy vọng"}]},{"id":"耸人听闻","hanzi":"耸人听闻","pinyin":"sǒngrén-tīngwén","meaning_vi":"giật gân, gây sốc dư luận","explanation":"耸 (tủng – làm kinh động) 人 听闻 (thính văn – nghe) → cố ý nói quá làm người nghe sửng sốt; giật gân.","hsk_level":6,"tags":["thanh-ngu"],"image":"😱","examples":[{"type":"basic","zh":"这条新闻耸人听闻。","pinyin":"Zhè tiáo xīnwén sǒngréntīngwén.","vi":"Tin tức này thật giật gân."},{"type":"simple","zh":"有些媒体喜欢用耸人听闻的标题吸引读者。","pinyin":"Yǒuxiē méitǐ xǐhuan yòng sǒngréntīngwén de biāotí xīyǐn dúzhě.","vi":"Một số báo thích dùng tiêu đề giật gân để thu hút độc giả."},{"type":"compound","zh":"这个消息虽然耸人听闻，但是没有任何证据。","pinyin":"Zhè ge xiāoxi suīrán sǒngréntīngwén, dànshì méiyǒu rènhé zhèngjù.","vi":"Tin này tuy gây sốc nhưng không có bất kỳ bằng chứng nào."}],"related":[{"hanzi":"危言耸听","pinyin":"wēiyánsǒngtīng","vi":"nói lời giật gân"},{"hanzi":"骇人听闻","pinyin":"hàiréntīngwén","vi":"nghe mà kinh hãi"},{"hanzi":"夸张","pinyin":"kuāzhāng","vi":"phóng đại"},{"hanzi":"轰动","pinyin":"hōngdòng","vi":"gây chấn động"}],"traditional":"聳人聽聞"},{"id":"损人利己","hanzi":"损人利己","pinyin":"sǔnrén-lìjǐ","meaning_vi":"hại người lợi mình","explanation":"损 (tổn – hại) 人 (người) 利 (lợi) 己 (kỷ – mình) → làm hại người khác để lợi cho bản thân.","hsk_level":6,"tags":["thanh-ngu"],"image":"😒","examples":[{"type":"basic","zh":"不要做损人利己的事。","pinyin":"Bú yào zuò sǔnrénlìjǐ de shì.","vi":"Đừng làm chuyện hại người lợi mình."},{"type":"simple","zh":"他在背后抢同事的客户，真是损人利己。","pinyin":"Tā zài bèihòu qiǎng tóngshì de kèhù, zhēn shì sǔnrénlìjǐ.","vi":"Hắn lén giành khách hàng của đồng nghiệp, đúng là hại người lợi mình."},{"type":"compound","zh":"损人利己的人即使一时得到好处，最后也会失去朋友。","pinyin":"Sǔnrénlìjǐ de rén jíshǐ yìshí dédào hǎochù, zuìhòu yě huì shīqù péngyou.","vi":"Kẻ hại người lợi mình dù được lợi nhất thời thì cuối cùng cũng sẽ mất bạn bè."}],"related":[{"hanzi":"自私","pinyin":"zìsī","vi":"ích kỷ"},{"hanzi":"自私自利","pinyin":"zìsīzìlì","vi":"ích kỷ tư lợi"},{"hanzi":"舍己为人","pinyin":"shějǐwèirén","vi":"quên mình vì người"},{"hanzi":"损失","pinyin":"sǔnshī","vi":"tổn thất"}],"traditional":"損人利己"},{"id":"田径","hanzi":"田径","pinyin":"tiánjìng","meaning_vi":"điền kinh","explanation":"田 (sân) + 径 (đường chạy).","hsk_level":6,"tags":["danh-tu","the-thao"],"image":"🏃","examples":[{"type":"basic","zh":"我喜欢看田径比赛。","pinyin":"Wǒ xǐhuan kàn tiánjìng bǐsài.","vi":"Tôi thích xem thi đấu điền kinh."},{"type":"simple","zh":"她在全国田径锦标赛上拿了跳远金牌。","pinyin":"Tā zài quánguó tiánjìng jǐnbiāosài shang nále tiàoyuǎn jīnpái.","vi":"Cô ấy giành huy chương vàng nhảy xa tại giải vô địch điền kinh toàn quốc."},{"type":"compound","zh":"因为从小练田径，所以他跑得比同学们都快。","pinyin":"Yīnwèi cóngxiǎo liàn tiánjìng, suǒyǐ tā pǎo de bǐ tóngxuémen dōu kuài.","vi":"Vì tập điền kinh từ nhỏ nên cậu ấy chạy nhanh hơn tất cả bạn cùng lớp."}],"related":[{"hanzi":"跑步","pinyin":"pǎobù","vi":"chạy bộ"},{"hanzi":"跳远","pinyin":"tiàoyuǎn","vi":"nhảy xa"},{"hanzi":"体育","pinyin":"tǐyù","vi":"thể dục thể thao"},{"hanzi":"运动员","pinyin":"yùndòngyuán","vi":"vận động viên"}],"traditional":"田徑"},{"id":"田园","hanzi":"田园","pinyin":"tiányuán","meaning_vi":"điền viên, đồng quê","explanation":"田 (ruộng) + 园 (vườn).","hsk_level":6,"tags":["danh-tu","thien-nhien","dia-diem"],"image":"🌾","examples":[{"type":"basic","zh":"他向往田园生活。","pinyin":"Tā xiàngwǎng tiányuán shēnghuó.","vi":"Anh ấy khao khát cuộc sống điền viên."},{"type":"simple","zh":"这幅画描绘了一片宁静的田园风光。","pinyin":"Zhè fú huà miáohuìle yípiàn níngjìng de tiányuán fēngguāng.","vi":"Bức tranh này miêu tả một khung cảnh đồng quê yên bình."},{"type":"compound","zh":"退休以后，爸爸既种菜又养鸡，过上了田园生活。","pinyin":"Tuìxiū yǐhòu, bàba jì zhòngcài yòu yǎng jī, guò shàngle tiányuán shēnghuó.","vi":"Sau khi nghỉ hưu, bố vừa trồng rau vừa nuôi gà, sống cuộc sống điền viên."}],"related":[{"hanzi":"农村","pinyin":"nóngcūn","vi":"nông thôn"},{"hanzi":"乡村","pinyin":"xiāngcūn","vi":"làng quê"},{"hanzi":"田野","pinyin":"tiányě","vi":"đồng ruộng"},{"hanzi":"田园风光","pinyin":"tiányuánfēngguāng","vi":"cảnh đồng quê"}],"traditional":"田園"},{"id":"调剂","hanzi":"调剂","pinyin":"tiáojì","meaning_vi":"điều phối, điều tiết; thay đổi cho đỡ đơn điệu","explanation":"调 (đọc tiáo) + 剂.","hsk_level":6,"tags":["dong-tu"],"image":"🔄","examples":[{"type":"basic","zh":"听音乐能调剂心情。","pinyin":"Tīng yīnyuè néng tiáojì xīnqíng.","vi":"Nghe nhạc có thể điều hòa tâm trạng."},{"type":"simple","zh":"周末去爬山可以调剂一下紧张的生活。","pinyin":"Zhōumò qù páshān kěyǐ tiáojì yíxià jǐnzhāng de shēnghuó.","vi":"Cuối tuần đi leo núi có thể thay đổi không khí cho cuộc sống căng thẳng."},{"type":"compound","zh":"如果天天吃米饭太单调，就偶尔吃面条调剂一下。","pinyin":"Rúguǒ tiāntiān chī mǐfàn tài dāndiào, jiù ǒu'ěr chī miàntiáo tiáojì yíxià.","vi":"Nếu ngày nào cũng ăn cơm thấy đơn điệu thì thỉnh thoảng ăn mì cho đổi món."}],"related":[{"hanzi":"调节","pinyin":"tiáojié","vi":"điều tiết"},{"hanzi":"调整","pinyin":"tiáozhěng","vi":"điều chỉnh"},{"hanzi":"调和","pinyin":"tiáohé","vi":"điều hòa"},{"hanzi":"放松","pinyin":"fàngsōng","vi":"thư giãn"}],"traditional":"調劑"},{"id":"调料","hanzi":"调料","pinyin":"tiáoliào","meaning_vi":"gia vị","explanation":"调 (pha trộn) + 料 (nguyên liệu).","hsk_level":6,"tags":["danh-tu","an-uong"],"image":"🧂","examples":[{"type":"basic","zh":"这道菜缺点调料。","pinyin":"Zhè dào cài quēdiǎn tiáoliào.","vi":"Món này thiếu chút gia vị."},{"type":"simple","zh":"厨房的架子上摆满了各种各样的调料。","pinyin":"Chúfáng de jiàzi shang bǎimǎnle gèzhǒng gèyàng de tiáoliào.","vi":"Trên kệ bếp bày đầy đủ các loại gia vị."},{"type":"compound","zh":"做火锅时，调料不但要新鲜，而且比例要合适。","pinyin":"Zuò huǒguō shí, tiáoliào búdàn yào xīnxiān, érqiě bǐlì yào héshì.","vi":"Khi nấu lẩu, gia vị không chỉ phải tươi mà tỷ lệ còn phải phù hợp."}],"related":[{"hanzi":"味精","pinyin":"wèijīng","vi":"mì chính"},{"hanzi":"酱油","pinyin":"jiàngyóu","vi":"xì dầu"},{"hanzi":"盐","pinyin":"yán","vi":"muối"},{"hanzi":"佐料","pinyin":"zuǒliào","vi":"gia vị"}],"traditional":"調料"},{"id":"条理","hanzi":"条理","pinyin":"tiáolǐ","meaning_vi":"mạch lạc, có trình tự","explanation":"条 (điều mục) + 理 (lý lẽ). Cụm: 条理清晰.","hsk_level":6,"tags":["danh-tu","hoc-tap"],"image":"📋","examples":[{"type":"basic","zh":"他说话很有条理。","pinyin":"Tā shuōhuà hěn yǒu tiáolǐ.","vi":"Anh ấy nói chuyện rất mạch lạc."},{"type":"simple","zh":"这份计划书写得清楚又有条理。","pinyin":"Zhè fèn jìhuà shūxiě de qīngchu yòu yǒu tiáolǐ.","vi":"Bản kế hoạch này được viết rõ ràng và mạch lạc."},{"type":"compound","zh":"只要做事有条理，再多的任务也不会乱。","pinyin":"Zhǐyào zuòshì yǒu tiáolǐ, zài duō de rènwu yě bú huì luàn.","vi":"Chỉ cần làm việc có trình tự thì nhiều nhiệm vụ đến đâu cũng không bị rối."}],"related":[{"hanzi":"条理清楚","pinyin":"tiáolǐqīngchu","vi":"rõ ràng mạch lạc"},{"hanzi":"有条不紊","pinyin":"yǒutiáobùwěn","vi":"ngăn nắp trật tự"},{"hanzi":"秩序","pinyin":"zhìxù","vi":"trật tự"},{"hanzi":"混乱","pinyin":"hùnluàn","vi":"hỗn loạn"}],"traditional":"條理"},{"id":"调皮捣蛋","hanzi":"调皮捣蛋","pinyin":"tiáopí-dǎodàn","meaning_vi":"tinh nghịch quậy phá","explanation":"调皮 (điều bì – nghịch ngợm) + 捣蛋 (đảo đản – quấy phá) → nghịch ngợm phá phách, thường nói trẻ con.","hsk_level":6,"tags":["thanh-ngu"],"image":"😜","examples":[{"type":"basic","zh":"这孩子调皮捣蛋。","pinyin":"Zhè háizi tiáopídǎodàn.","vi":"Đứa trẻ này tinh nghịch quậy phá."},{"type":"simple","zh":"上课时那几个男生总是调皮捣蛋。","pinyin":"Shàngkè shí nà jǐ gè nánshēng zǒngshì tiáopídǎodàn.","vi":"Trong giờ học, mấy cậu học sinh đó lúc nào cũng nghịch ngợm quậy phá."},{"type":"compound","zh":"他小时候虽然调皮捣蛋，但是长大后非常懂事。","pinyin":"Tā xiǎoshíhou suīrán tiáopídǎodàn, dànshì zhǎngdà hòu fēicháng dǒngshì.","vi":"Hồi nhỏ cậu ấy tuy nghịch ngợm quậy phá nhưng lớn lên lại rất hiểu chuyện."}],"related":[{"hanzi":"调皮","pinyin":"tiáopí","vi":"nghịch ngợm"},{"hanzi":"淘气","pinyin":"táoqì","vi":"tinh nghịch"},{"hanzi":"顽皮","pinyin":"wánpí","vi":"nghịch ngợm"},{"hanzi":"捣乱","pinyin":"dǎoluàn","vi":"quấy rối"}],"traditional":"調皮搗蛋"},{"id":"条条大路通罗马","hanzi":"条条大路通罗马","pinyin":"tiáo tiáo dàlù tōng Luómǎ","meaning_vi":"mọi con đường đều dẫn tới thành Rome","explanation":"Mọi con đường lớn đều dẫn tới La Mã (ngạn ngữ phương Tây) → có nhiều cách khác nhau để đạt cùng một mục tiêu.","hsk_level":6,"tags":["thanh-ngu"],"image":"🛤️","examples":[{"type":"basic","zh":"条条大路通罗马嘛。","pinyin":"Tiáotiáodàlùtōngluómǎ ma.","vi":"Mọi con đường đều dẫn tới thành Rome mà."},{"type":"simple","zh":"没考上大学也别灰心，条条大路通罗马。","pinyin":"Méi kǎoshàng dàxué yě bié huīxīn, tiáotiáodàlùtōngluómǎ.","vi":"Không đỗ đại học cũng đừng nản, đường nào cũng dẫn đến thành công."},{"type":"compound","zh":"既然条条大路通罗马，你就不必只盯着这一份工作。","pinyin":"Jìrán tiáotiáodàlùtōngluómǎ, nǐ jiù búbì zhǐ dīngzhe zhè yí fèn gōngzuò.","vi":"Đã là đường nào cũng dẫn tới Rome thì bạn không cần chỉ chăm chăm vào công việc này."}],"related":[{"hanzi":"殊途同归","pinyin":"shūtútóngguī","vi":"khác đường cùng đích"},{"hanzi":"办法","pinyin":"bànfǎ","vi":"cách làm"},{"hanzi":"途径","pinyin":"tújìng","vi":"con đường cách thức"}],"traditional":"條條大路通羅馬"},{"id":"天长地久","hanzi":"天长地久","pinyin":"tiāncháng-dìjiǔ","meaning_vi":"thiên trường địa cửu (vĩnh cửu)","explanation":"Trời dài đất lâu (Đạo Đức Kinh) → bền lâu vĩnh cửu; hay nói về tình yêu, tình bạn bền chặt.","hsk_level":6,"tags":["thanh-ngu"],"image":"♾️","examples":[{"type":"basic","zh":"祝你们天长地久！","pinyin":"Zhù nǐmen tiānchángdìjiǔ!","vi":"Chúc hai bạn mãi mãi bên nhau!"},{"type":"simple","zh":"他们在婚礼上许下天长地久的誓言。","pinyin":"Tāmen zài hūnlǐ shang xǔxià tiānchángdìjiǔ de shìyán.","vi":"Họ đã thề nguyện bên nhau trọn đời trong lễ cưới."},{"type":"compound","zh":"真正的友谊即使相隔万里，也能天长地久。","pinyin":"Zhēnzhèng de yǒuyì jíshǐ xiānggé wànlǐ, yě néng tiānchángdìjiǔ.","vi":"Tình bạn thật sự dù cách xa vạn dặm cũng có thể trường tồn mãi mãi."}],"related":[{"hanzi":"永恒","pinyin":"yǒnghéng","vi":"vĩnh hằng"},{"hanzi":"永远","pinyin":"yǒngyuǎn","vi":"mãi mãi"},{"hanzi":"地久天长","pinyin":"dìjiǔtiāncháng","vi":"trường tồn mãi mãi"},{"hanzi":"海枯石烂","pinyin":"hǎikūshílàn","vi":"sông cạn đá mòn"}],"traditional":"天長地久"},{"id":"天才","hanzi":"天才","pinyin":"tiāncái","meaning_vi":"thiên tài","explanation":"天 (trời) + 才 (tài năng).","hsk_level":6,"tags":["danh-tu","con-nguoi"],"image":"🧠","examples":[{"type":"basic","zh":"他是数学天才。","pinyin":"Tā shì shùxué tiāncái.","vi":"Cậu ấy là thiên tài toán học."},{"type":"simple","zh":"这个八岁的孩子是个音乐天才。","pinyin":"Zhè ge bā suì de háizi shì ge yīnyuè tiāncái.","vi":"Đứa trẻ tám tuổi này là một thiên tài âm nhạc."},{"type":"compound","zh":"即使是天才，如果不努力，也很难取得成就。","pinyin":"Jíshǐ shì tiāncái, rúguǒ bù nǔlì, yě hěn nán qǔdé chéngjiù.","vi":"Dù là thiên tài, nếu không nỗ lực cũng khó đạt được thành tựu."}],"related":[{"hanzi":"天赋","pinyin":"tiānfù","vi":"thiên phú"},{"hanzi":"天生","pinyin":"tiānshēng","vi":"bẩm sinh"},{"hanzi":"才能","pinyin":"cáinéng","vi":"tài năng"},{"hanzi":"神童","pinyin":"shéntóng","vi":"thần đồng"}]},{"id":"天翻地覆","hanzi":"天翻地覆","pinyin":"tiānfān-dìfù","meaning_vi":"trời long đất lở (thay đổi cực lớn)","explanation":"天翻地覆: trời lật đất úp → biến đổi cực lớn; hoặc náo loạn ầm ĩ. Cụm: 闹得天翻地覆.","hsk_level":6,"tags":["thanh-ngu"],"image":"🌍","examples":[{"type":"basic","zh":"家里吵得天翻地覆。","pinyin":"Jiālǐ chǎo de tiānfāndìfù.","vi":"Trong nhà cãi nhau ầm ĩ long trời lở đất."},{"type":"simple","zh":"这几十年来，家乡发生了天翻地覆的变化。","pinyin":"Zhè jǐ shí niánlái, jiāxiāng fāshēngle tiānfāndìfù de biànhuà.","vi":"Mấy chục năm qua, quê hương đã có những thay đổi to lớn."},{"type":"compound","zh":"自从有了智能手机，人们的生活方式就发生了天翻地覆的变化。","pinyin":"Zìcóng yǒule zhìnéng shǒujī, rénmen de shēnghuó fāngshì jiù fāshēngle tiānfāndìfù de biànhuà.","vi":"Từ khi có điện thoại thông minh, lối sống của con người đã thay đổi hoàn toàn."}],"related":[{"hanzi":"翻天覆地","pinyin":"fāntiānfùdì","vi":"long trời lở đất"},{"hanzi":"巨变","pinyin":"jùbiàn","vi":"biến đổi lớn"},{"hanzi":"变化","pinyin":"biànhuà","vi":"thay đổi"},{"hanzi":"一成不变","pinyin":"yìchéngbúbiàn","vi":"không hề thay đổi"}]},{"id":"天经地义","hanzi":"天经地义","pinyin":"tiānjīng-dìyì","meaning_vi":"chân lý hiển nhiên, lẽ đương nhiên","explanation":"天经 (lẽ thường của trời) + 地义 (nghĩa của đất) → chân lý hiển nhiên, lẽ đương nhiên không cần bàn cãi.","hsk_level":6,"tags":["thanh-ngu"],"image":"⚖️","examples":[{"type":"basic","zh":"欠债还钱，天经地义。","pinyin":"Qiànzhài huán qián, tiānjīngdìyì.","vi":"Nợ thì phải trả, đó là lẽ đương nhiên."},{"type":"simple","zh":"孝敬父母是天经地义的事。","pinyin":"Xiàojìng fùmǔ shì tiānjīngdìyì de shì.","vi":"Hiếu kính cha mẹ là chuyện hiển nhiên."},{"type":"compound","zh":"既然你弄坏了别人的东西，赔偿就是天经地义的。","pinyin":"Jìrán nǐ nòng huàile biérén de dōngxi, péicháng jiùshì tiānjīngdìyì de.","vi":"Bạn đã làm hỏng đồ của người khác thì bồi thường là lẽ đương nhiên."}],"related":[{"hanzi":"理所当然","pinyin":"lǐsuǒdāngrán","vi":"lẽ đương nhiên"},{"hanzi":"理直气壮","pinyin":"lǐzhíqìzhuàng","vi":"lý lẽ hùng hồn"},{"hanzi":"应该","pinyin":"yīnggāi","vi":"nên"},{"hanzi":"毋庸置疑","pinyin":"wúyōngzhìyí","vi":"không thể nghi ngờ"}],"traditional":"天經地義"},{"id":"天生","hanzi":"天生","pinyin":"tiānshēng","meaning_vi":"trời sinh, bẩm sinh","explanation":"天 + 生 (sinh ra).","hsk_level":6,"tags":["tinh-tu","pho-tu"],"image":"🌟","examples":[{"type":"basic","zh":"她天生一副好嗓子。","pinyin":"Tā tiānshēng yí fù hǎo sǎngzi.","vi":"Cô ấy bẩm sinh có một giọng hát hay."},{"type":"simple","zh":"这孩子天生对数字特别敏感。","pinyin":"Zhè háizi tiānshēng duì shùzì tèbié mǐngǎn.","vi":"Đứa trẻ này bẩm sinh đã rất nhạy cảm với con số."},{"type":"compound","zh":"虽然他天生胆小，但是遇到危险时一点也不退缩。","pinyin":"Suīrán tā tiānshēng dǎnxiǎo, dànshì yùdào wēixiǎn shí yìdiǎn yě bú tuìsuō.","vi":"Tuy anh ấy bẩm sinh nhút nhát, nhưng khi gặp nguy hiểm lại không hề lùi bước."}],"related":[{"hanzi":"天赋","pinyin":"tiānfù","vi":"thiên phú"},{"hanzi":"天才","pinyin":"tiāncái","vi":"thiên tài"},{"hanzi":"生来","pinyin":"shēnglái","vi":"sinh ra đã"},{"hanzi":"后天","pinyin":"hòutiān","vi":"hậu thiên"}]},{"id":"天涯海角","hanzi":"天涯海角","pinyin":"tiānyá-hǎijiǎo","meaning_vi":"chân trời góc bể","explanation":"天涯 (thiên nhai – ven trời) + 海角 (hải giác – góc biển) → nơi xa xôi tận cùng trời đất.","hsk_level":6,"tags":["thanh-ngu","du-lich"],"image":"🌊","examples":[{"type":"basic","zh":"我愿陪你走到天涯海角。","pinyin":"Wǒ yuàn péi nǐ zǒu dào tiānyáhǎijiǎo.","vi":"Anh nguyện cùng em đi đến chân trời góc bể."},{"type":"simple","zh":"毕业后，老同学们散落在天涯海角。","pinyin":"Bìyè hòu, lǎo tóngxuémen sànluò zài tiānyáhǎijiǎo.","vi":"Sau khi tốt nghiệp, các bạn học cũ tản mát khắp chân trời góc bể."},{"type":"compound","zh":"即使你逃到天涯海角，警察也会把你找出来。","pinyin":"Jíshǐ nǐ táo dào tiānyáhǎijiǎo, jǐngchá yě huì bǎ nǐ zhǎo chūlái.","vi":"Dù anh có trốn đến chân trời góc bể, cảnh sát cũng sẽ tìm ra anh."}],"related":[{"hanzi":"天南地北","pinyin":"tiānnándìběi","vi":"trời nam đất bắc"},{"hanzi":"遥远","pinyin":"yáoyuǎn","vi":"xa xôi"},{"hanzi":"四面八方","pinyin":"sìmiànbāfāng","vi":"bốn phương tám hướng"},{"hanzi":"远方","pinyin":"yuǎnfāng","vi":"phương xa"}]},{"id":"天衣无缝","hanzi":"天衣无缝","pinyin":"tiānyī-wúfèng","meaning_vi":"hoàn hảo không một kẽ hở (áo trời không đường may)","explanation":"Áo của tiên nữ trên trời không có đường may → hoàn hảo, không chút sơ hở. Thường: 计划天衣无缝.","hsk_level":6,"tags":["thanh-ngu"],"image":"✨","examples":[{"type":"basic","zh":"他们的配合天衣无缝。","pinyin":"Tāmen de pèihé tiānyīwúfèng.","vi":"Sự phối hợp của họ hoàn hảo không một kẽ hở."},{"type":"simple","zh":"小偷以为自己的计划天衣无缝。","pinyin":"Xiǎotōu yǐwéi zìjǐ de jìhuà tiānyīwúfèng.","vi":"Tên trộm tưởng kế hoạch của mình hoàn hảo không chút sơ hở."},{"type":"compound","zh":"这个谎言看似天衣无缝，可是一个细节就让它露了馅。","pinyin":"Zhè ge huǎngyán kànsì tiānyīwúfèng, kěshì yí gè xìjié jiù ràng tā lòule xiàn.","vi":"Lời nói dối này tưởng như hoàn hảo, nhưng chỉ một chi tiết đã làm nó lộ tẩy."}],"related":[{"hanzi":"完美","pinyin":"wánměi","vi":"hoàn mỹ"},{"hanzi":"完美无缺","pinyin":"wánměiwúquē","vi":"hoàn hảo không tì vết"},{"hanzi":"无懈可击","pinyin":"wúxièkějī","vi":"không chê vào đâu"},{"hanzi":"破绽","pinyin":"pòzhàn","vi":"sơ hở"}],"traditional":"天衣無縫"},{"id":"天灾人祸","hanzi":"天灾人祸","pinyin":"tiānzāi-rénhuò","meaning_vi":"thiên tai nhân họa","explanation":"天灾 (thiên tai) + 人祸 (nhân họa – họa do người) → tai họa do thiên nhiên và con người gây ra.","hsk_level":6,"tags":["thanh-ngu"],"image":"🌪️","examples":[{"type":"basic","zh":"天灾人祸难以预料。","pinyin":"Tiānzāirénhuò nányǐ yùliào.","vi":"Thiên tai nhân họa thật khó lường trước."},{"type":"simple","zh":"那年村里接连遭遇天灾人祸。","pinyin":"Nà nián cūnlǐ jiēlián zāoyù tiānzāirénhuò.","vi":"Năm đó làng liên tiếp gặp phải thiên tai nhân họa."},{"type":"compound","zh":"因为经历过太多天灾人祸，所以老人格外珍惜平静的日子。","pinyin":"Yīnwèi jīnglìguò tài duō tiānzāirénhuò, suǒyǐ lǎorén géwài zhēnxī píngjìng de rìzi.","vi":"Vì đã trải qua quá nhiều thiên tai nhân họa nên ông cụ đặc biệt trân trọng những ngày bình yên."}],"related":[{"hanzi":"灾难","pinyin":"zāinàn","vi":"tai họa"},{"hanzi":"自然灾害","pinyin":"zìránzāihài","vi":"thiên tai"},{"hanzi":"灾害","pinyin":"zāihài","vi":"tai hại"},{"hanzi":"祸害","pinyin":"huòhai","vi":"tai ương"}],"traditional":"天災人禍"},{"id":"挑肥拣瘦","hanzi":"挑肥拣瘦","pinyin":"tiāoféi-jiǎnshòu","meaning_vi":"kén cá chọn canh","explanation":"挑肥 (chọn mỡ) + 拣瘦 (nhặt nạc). Thành ngữ.","hsk_level":6,"tags":["thanh-ngu"],"image":"😒","examples":[{"type":"basic","zh":"找工作别挑肥拣瘦。","pinyin":"Zhǎogōngzuò bié tiāoféijiǎnshòu.","vi":"Tìm việc thì đừng kén cá chọn canh."},{"type":"simple","zh":"她买菜时总爱挑肥拣瘦。","pinyin":"Tā mǎicài shí zǒng ài tiāoféijiǎnshòu.","vi":"Khi đi chợ, bà ấy luôn thích kén cá chọn canh."},{"type":"compound","zh":"如果你一直挑肥拣瘦，就永远找不到合适的房子。","pinyin":"Rúguǒ nǐ yìzhí tiāoféijiǎnshòu, jiù yǒngyuǎn zhǎobúdào héshì de fángzi.","vi":"Nếu bạn cứ kén cá chọn canh mãi thì sẽ không bao giờ tìm được căn nhà phù hợp."}],"related":[{"hanzi":"挑剔","pinyin":"tiāoti","vi":"kén chọn"},{"hanzi":"挑三拣四","pinyin":"tiāosānjiǎnsì","vi":"kén cá chọn canh"},{"hanzi":"挑选","pinyin":"tiāoxuǎn","vi":"lựa chọn"},{"hanzi":"讲究","pinyin":"jiǎngjiu","vi":"cầu kỳ"}],"traditional":"挑肥揀瘦"},{"id":"挑拨离间","hanzi":"挑拨离间","pinyin":"tiǎobō-líjiàn","meaning_vi":"châm ngòi ly gián, chia rẽ","explanation":"挑拨 (khiêu bát – khích bác, xúi giục) + 离间 (ly gián) → xúi giục gây mâu thuẫn, chia rẽ quan hệ người khác.","hsk_level":6,"tags":["thanh-ngu"],"image":"🐍","examples":[{"type":"basic","zh":"别听他挑拨离间。","pinyin":"Bié tīng tā tiǎobōlíjiàn.","vi":"Đừng nghe hắn châm ngòi ly gián."},{"type":"simple","zh":"有人在背后挑拨离间我们的关系。","pinyin":"Yǒurén zài bèihòu tiǎobōlíjiàn wǒmen de guānxì.","vi":"Có người đứng sau ly gián mối quan hệ của chúng ta."},{"type":"compound","zh":"虽然有人挑拨离间，但是两兄弟的感情一点也没受影响。","pinyin":"Suīrán yǒurén tiǎobōlíjiàn, dànshì liǎng xiōngdì de gǎnqíng yìdiǎn yě méi shòu yǐngxiǎng.","vi":"Tuy có người châm ngòi chia rẽ, nhưng tình cảm hai anh em không hề bị ảnh hưởng."}],"related":[{"hanzi":"挑拨","pinyin":"tiǎobō","vi":"xúi giục"},{"hanzi":"挑衅","pinyin":"tiǎoxìn","vi":"khiêu khích"},{"hanzi":"离间","pinyin":"líjiàn","vi":"ly gián"},{"hanzi":"搬弄是非","pinyin":"bānnòngshìfēi","vi":"đâm bị thóc chọc bị gạo"}],"traditional":"挑撥離間"},{"id":"挑衅","hanzi":"挑衅","pinyin":"tiǎoxìn","meaning_vi":"khiêu khích","explanation":"挑 + 衅 (gây sự).","hsk_level":6,"tags":["dong-tu"],"image":"⚔️","examples":[{"type":"basic","zh":"他故意向我挑衅。","pinyin":"Tā gù yìxiàng wǒ tiǎoxìn.","vi":"Hắn cố tình khiêu khích tôi."},{"type":"simple","zh":"对方球员不停地用言语挑衅。","pinyin":"Duìfāng qiúyuán bùtíng de yòng yányǔ tiǎoxìn.","vi":"Cầu thủ đối phương liên tục dùng lời lẽ khiêu khích."},{"type":"compound","zh":"面对别人的挑衅，与其动手打架，不如冷静走开。","pinyin":"Miànduì biérén de tiǎoxìn, yǔqí dòngshǒu dǎjià, bùrú lěngjìng zǒukāi.","vi":"Đối mặt với sự khiêu khích của người khác, thay vì đánh nhau chi bằng bình tĩnh bỏ đi."}],"related":[{"hanzi":"挑战","pinyin":"tiǎozhàn","vi":"thách thức"},{"hanzi":"挑拨","pinyin":"tiǎobō","vi":"xúi giục"},{"hanzi":"激怒","pinyin":"jīnù","vi":"chọc giận"},{"hanzi":"冲突","pinyin":"chōngtū","vi":"xung đột"}],"traditional":"挑釁"},{"id":"团聚","hanzi":"团聚","pinyin":"tuánjù","meaning_vi":"đoàn tụ, sum họp","explanation":"团 (tụ) + 聚 (họp).","hsk_level":6,"tags":["dong-tu","gia-dinh"],"image":"👨‍👩‍👧‍👦","examples":[{"type":"basic","zh":"春节全家人团聚。","pinyin":"Chūnjié quán jiārén tuánjù.","vi":"Tết Nguyên đán cả nhà đoàn tụ."},{"type":"simple","zh":"分别十年后，母女终于团聚了。","pinyin":"Fēnbié shí nián hòu, mǔnǚ zhōngyú tuánjù le.","vi":"Sau mười năm xa cách, hai mẹ con cuối cùng cũng đoàn tụ."},{"type":"compound","zh":"只要一家人能团聚在一起，吃什么都觉得香。","pinyin":"Zhǐyào yìjiārén néng tuánjù zài yìqǐ, chī shénme dōu juéde xiāng.","vi":"Chỉ cần cả nhà được sum họp bên nhau, ăn gì cũng thấy ngon."}],"related":[{"hanzi":"团圆","pinyin":"tuányuán","vi":"đoàn viên"},{"hanzi":"相聚","pinyin":"xiāngjù","vi":"sum họp"},{"hanzi":"聚会","pinyin":"jùhuì","vi":"tụ họp"},{"hanzi":"分离","pinyin":"fēnlí","vi":"chia ly"}],"traditional":"團聚"},{"id":"蜕变","hanzi":"蜕变","pinyin":"tuìbiàn","meaning_vi":"lột xác, biến đổi về chất","explanation":"蜕 (lột vỏ) + 变 (thay đổi).","hsk_level":6,"tags":["dong-tu"],"image":"🦋","examples":[{"type":"basic","zh":"毛毛虫蜕变成了蝴蝶。","pinyin":"Máomaochóng tuìbiàn chéngle húdié.","vi":"Con sâu đã lột xác thành con bướm."},{"type":"simple","zh":"经过三年磨炼，他完成了华丽的蜕变。","pinyin":"Jīngguò sān nián móliàn, tā wánchéngle huálì de tuìbiàn.","vi":"Sau ba năm rèn luyện, anh ấy đã lột xác ngoạn mục."},{"type":"compound","zh":"这家小作坊不但蜕变成了大企业，而且产品远销海外。","pinyin":"Zhè jiā xiǎo zuōfang búdàn tuìbiàn chéngle dà qǐyè, érqiě chǎnpǐn yuǎnxiāo hǎiwài.","vi":"Xưởng nhỏ này không những lột xác thành doanh nghiệp lớn mà sản phẩm còn bán ra nước ngoài."}],"related":[{"hanzi":"转变","pinyin":"zhuǎnbiàn","vi":"chuyển biến"},{"hanzi":"变化","pinyin":"biànhuà","vi":"thay đổi"},{"hanzi":"演变","pinyin":"yǎnbiàn","vi":"diễn biến"},{"hanzi":"进化","pinyin":"jìnhuà","vi":"tiến hóa"}],"traditional":"蛻變"},{"id":"退化","hanzi":"退化","pinyin":"tuìhuà","meaning_vi":"thoái hóa","explanation":"退 (lùi) + 化 (biến đổi). Đối nghĩa với 进化 (tiến hóa).","hsk_level":6,"tags":["dong-tu","khoa-hoc"],"image":"📉","examples":[{"type":"basic","zh":"他的视力退化了。","pinyin":"Tā de shìlì tuìhuà le.","vi":"Thị lực của ông ấy đã thoái hóa."},{"type":"simple","zh":"长期不运动会让肌肉逐渐退化。","pinyin":"Chángqī bú yùndònghuì ràng jīròu zhújiàn tuìhuà.","vi":"Lâu ngày không vận động sẽ khiến cơ bắp dần thoái hóa."},{"type":"compound","zh":"如果器官长期不用，它就可能慢慢退化。","pinyin":"Rúguǒ qìguān chángqī bú yòng, tā jiù kěnéng mànmàn tuìhuà.","vi":"Nếu một cơ quan lâu ngày không dùng đến thì nó có thể dần dần thoái hóa."}],"related":[{"hanzi":"进化","pinyin":"jìnhuà","vi":"tiến hóa"},{"hanzi":"衰退","pinyin":"shuāituì","vi":"suy thoái"},{"hanzi":"退步","pinyin":"tuìbù","vi":"thụt lùi"},{"hanzi":"老化","pinyin":"lǎohuà","vi":"lão hóa"}]},{"id":"颓废","hanzi":"颓废","pinyin":"tuífèi","meaning_vi":"suy sụp, chán chường, buông xuôi","explanation":"颓 + 废 (bỏ đi).","hsk_level":6,"tags":["tinh-tu","cam-xuc"],"image":"😔","examples":[{"type":"basic","zh":"他最近非常颓废。","pinyin":"Tā zuìjìn fēicháng tuífèi.","vi":"Dạo này anh ấy rất suy sụp chán chường."},{"type":"simple","zh":"失业后，他整天在家过着颓废的生活。","pinyin":"Shīyè hòu, tā zhěngtiān zài jiāguò zhe tuífèi de shēnghuó.","vi":"Sau khi mất việc, anh ta suốt ngày ở nhà sống buông xuôi."},{"type":"compound","zh":"虽然考试失败了，但是你不能一直这么颓废下去。","pinyin":"Suīrán kǎoshì shībài le, dànshì nǐ bù néng yìzhí zhème tuífèi xiàqù.","vi":"Tuy thi trượt rồi, nhưng con không thể cứ chán chường mãi như thế này được."}],"related":[{"hanzi":"消沉","pinyin":"xiāochén","vi":"sa sút tinh thần"},{"hanzi":"堕落","pinyin":"duòluò","vi":"sa đọa"},{"hanzi":"沮丧","pinyin":"jǔsàng","vi":"chán nản"},{"hanzi":"振作","pinyin":"zhènzuò","vi":"phấn chấn"}],"traditional":"頹廢"},{"id":"唾沫","hanzi":"唾沫","pinyin":"tuòmo","meaning_vi":"nước bọt","explanation":"Cả hai chữ đều có bộ thủy 氵.","hsk_level":6,"tags":["danh-tu","co-the"],"image":"💧","examples":[{"type":"basic","zh":"他咽了一口唾沫。","pinyin":"Tā yànle yìkǒu tuòmo.","vi":"Anh ấy nuốt một ngụm nước bọt."},{"type":"simple","zh":"说话时唾沫星子溅到了别人脸上。","pinyin":"Shuōhuà shí tuòmo xīng zi jiàn dàole biérén liǎn shang.","vi":"Lúc nói chuyện, nước bọt bắn lên mặt người khác."},{"type":"compound","zh":"他一紧张就咽唾沫，所以大家很快看出他在撒谎。","pinyin":"Tā yì jǐnzhāng jiù yàn tuòmo, suǒyǐ dàjiā hěn kuài kànchū tā zài sāhuǎng.","vi":"Hễ căng thẳng là anh ta lại nuốt nước bọt, nên mọi người nhanh chóng nhận ra anh ta đang nói dối."}],"related":[{"hanzi":"口水","pinyin":"kǒushuǐ","vi":"nước miếng"},{"hanzi":"吐痰","pinyin":"tǔtán","vi":"khạc nhổ"},{"hanzi":"唾液","pinyin":"tuòyè","vi":"nước bọt"}]},{"id":"唾弃","hanzi":"唾弃","pinyin":"tuòqì","meaning_vi":"khinh bỉ, ruồng bỏ","explanation":"唾 (nhổ) + 弃 (vứt bỏ).","hsk_level":6,"tags":["dong-tu"],"image":"👎","examples":[{"type":"basic","zh":"叛徒被人们唾弃。","pinyin":"Pàntú bèi rénmen tuòqì.","vi":"Kẻ phản bội bị mọi người khinh bỉ."},{"type":"simple","zh":"这种卖国行为遭到全社会的唾弃。","pinyin":"Zhè zhǒng màiguó xíngwéi zāodào quán shèhuì de tuòqì.","vi":"Hành vi bán nước này bị toàn xã hội ruồng bỏ."},{"type":"compound","zh":"他虽然一时得到了钱，但是从此被乡亲们唾弃。","pinyin":"Tā suīrán yìshí dédàole qián, dànshì cóngcǐ bèi xiāngqīnmen tuòqì.","vi":"Tuy hắn nhất thời có được tiền, nhưng từ đó bị bà con làng xóm khinh bỉ."}],"related":[{"hanzi":"鄙视","pinyin":"bǐshì","vi":"khinh bỉ"},{"hanzi":"抛弃","pinyin":"pāoqì","vi":"vứt bỏ"},{"hanzi":"厌恶","pinyin":"yànwù","vi":"ghê tởm"},{"hanzi":"嫌弃","pinyin":"xiánqì","vi":"ghét bỏ"}],"traditional":"唾棄"},{"id":"推陈出新","hanzi":"推陈出新","pinyin":"tuīchén-chūxīn","meaning_vi":"loại bỏ cái cũ tạo ra cái mới, đổi mới sáng tạo","explanation":"推 (thôi – đẩy bỏ) 陈 (trần – cũ) 出 (xuất) 新 (tân – mới) → gạt bỏ cái cũ lỗi thời, tạo ra cái mới; đổi mới sáng tạo.","hsk_level":6,"tags":["thanh-ngu"],"image":"💡","examples":[{"type":"basic","zh":"传统戏曲需要推陈出新。","pinyin":"Chuántǒng xìqǔ xūyào tuīchénchūxīn.","vi":"Hí khúc truyền thống cần loại bỏ cái cũ, sáng tạo cái mới."},{"type":"simple","zh":"这家餐厅的菜单每个季度都推陈出新。","pinyin":"Zhè jiā cāntīng de càidān měi gè jìdù dōu tuīchénchūxīn.","vi":"Thực đơn của nhà hàng này mỗi quý đều được đổi mới."},{"type":"compound","zh":"一个品牌只有不断推陈出新，才能留住年轻顾客。","pinyin":"Yí gè pǐnpái zhǐyǒu búduàn tuīchénchūxīn, cáinéng liúzhù niánqīng gùkè.","vi":"Một thương hiệu chỉ có không ngừng đổi mới sáng tạo mới giữ chân được khách hàng trẻ."}],"related":[{"hanzi":"创新","pinyin":"chuàngxīn","vi":"sáng tạo đổi mới"},{"hanzi":"革新","pinyin":"géxīn","vi":"cách tân"},{"hanzi":"更新","pinyin":"gēngxīn","vi":"cập nhật đổi mới"},{"hanzi":"守旧","pinyin":"shǒujiù","vi":"bảo thủ"}],"traditional":"推陳出新"},{"id":"推测","hanzi":"推测","pinyin":"tuīcè","meaning_vi":"suy đoán","explanation":"推 (suy diễn) + 测 (đo lường).","hsk_level":6,"tags":["dong-tu","nhan-thuc"],"image":"🤔","examples":[{"type":"basic","zh":"这只是我的推测。","pinyin":"Zhè zhǐshì wǒ de tuīcè.","vi":"Đây chỉ là suy đoán của tôi."},{"type":"simple","zh":"专家推测这座古墓有两千年历史。","pinyin":"Zhuānjiā tuīcè zhè zuò gǔmù yǒu liǎngqiānnián lìshǐ.","vi":"Các chuyên gia suy đoán ngôi mộ cổ này có lịch sử hai nghìn năm."},{"type":"compound","zh":"根据脚印推测，小偷是从后窗进来的，所以后窗必须修好。","pinyin":"Gēnjù jiǎoyìn tuīcè, xiǎotōu shì cóng hòu chuāng jìnlái de, suǒ yǐhòu chuāng bìxū xiūhǎo.","vi":"Suy đoán từ dấu chân thì tên trộm vào từ cửa sổ sau, vì vậy phải sửa cửa sổ sau ngay."}],"related":[{"hanzi":"猜测","pinyin":"cāicè","vi":"phỏng đoán"},{"hanzi":"估计","pinyin":"gūjì","vi":"ước tính"},{"hanzi":"推断","pinyin":"tuīduàn","vi":"suy đoán"},{"hanzi":"推理","pinyin":"tuīlǐ","vi":"suy luận"}],"traditional":"推測"},{"id":"推论","hanzi":"推论","pinyin":"tuīlùn","meaning_vi":"suy luận, kết luận suy ra","explanation":"推 + 论 (bàn luận).","hsk_level":6,"tags":["dong-tu","danh-tu"],"image":"💡","examples":[{"type":"basic","zh":"这个推论不成立。","pinyin":"Zhè ge tuīlùn bù chénglì.","vi":"Suy luận này không đứng vững."},{"type":"simple","zh":"侦探从一根头发推论出凶手的身份。","pinyin":"Zhēntàn cóng yìgēn tóufa tuīlùn chū xiōngshǒu de shēnfèn.","vi":"Thám tử từ một sợi tóc đã suy luận ra danh tính hung thủ."},{"type":"compound","zh":"既然前提是错的，那么你的推论也就站不住脚。","pinyin":"Jìrán qiántí shì cuò de, nàme nǐ de tuīlùn yě jiù zhàn bú zhùjiǎo.","vi":"Đã là tiền đề sai thì suy luận của anh cũng không đứng vững được."}],"related":[{"hanzi":"推理","pinyin":"tuīlǐ","vi":"suy luận"},{"hanzi":"结论","pinyin":"jiélùn","vi":"kết luận"},{"hanzi":"推断","pinyin":"tuīduàn","vi":"suy đoán"},{"hanzi":"论证","pinyin":"lùnzhèng","vi":"lập luận"}],"traditional":"推論"},{"id":"推卸","hanzi":"推卸","pinyin":"tuīxiè","meaning_vi":"thoái thác, đùn đẩy (trách nhiệm)","explanation":"推 (đẩy) + 卸 (trút bỏ). Cụm: 推卸责任.","hsk_level":6,"tags":["dong-tu"],"image":"🙈","examples":[{"type":"basic","zh":"他总想推卸责任。","pinyin":"Tā zǒng xiǎng tuīxiè zérèn.","vi":"Anh ta luôn muốn đùn đẩy trách nhiệm."},{"type":"simple","zh":"出了事故，几个部门互相推卸责任。","pinyin":"Chūleshì gù, jǐ gè bùmén hùxiāng tuīxiè zérèn.","vi":"Xảy ra sự cố, mấy phòng ban đùn đẩy trách nhiệm cho nhau."},{"type":"compound","zh":"既然是你签的字，就不要再推卸责任了。","pinyin":"Jìrán shì nǐ qiān de zì, jiù bú yào zài tuīxiè zérèn le.","vi":"Đã là anh ký tên thì đừng thoái thác trách nhiệm nữa."}],"related":[{"hanzi":"推卸责任","pinyin":"tuīxièzérèn","vi":"đùn đẩy trách nhiệm"},{"hanzi":"推辞","pinyin":"tuīcí","vi":"từ chối"},{"hanzi":"逃避","pinyin":"táobì","vi":"trốn tránh"},{"hanzi":"承担","pinyin":"chéngdān","vi":"gánh vác"}]},{"id":"推心置腹","hanzi":"推心置腹","pinyin":"tuīxīn-zhìfù","meaning_vi":"chân thành cởi mở tâm sự hết lòng","explanation":"Đem lòng mình đặt vào bụng người (Lưu Tú đối đãi chân thành với hàng tướng) → đối xử chân thành, tâm sự thật lòng. Thường: 推心置腹地谈.","hsk_level":6,"tags":["thanh-ngu","giao-tiep"],"image":"❤️","examples":[{"type":"basic","zh":"我们推心置腹地谈了谈。","pinyin":"Wǒmen tuīxīnzhìfù de tánle tán.","vi":"Chúng tôi đã tâm sự hết lòng với nhau."},{"type":"simple","zh":"父子俩终于进行了一次推心置腹的长谈。","pinyin":"Fùzǐ liǎ zhōngyú jìnxíngle yí cì tuīxīnzhìfù de chángtán.","vi":"Hai cha con cuối cùng đã có một cuộc trò chuyện dài chân thành cởi mở."},{"type":"compound","zh":"只要双方推心置腹地沟通，误会就能很快解开。","pinyin":"Zhǐyào shuāngfāng tuīxīnzhìfù de gōutōng, wùhuì jiù néng hěn kuài jiěkāi.","vi":"Chỉ cần hai bên trao đổi chân thành cởi mở thì hiểu lầm sẽ nhanh chóng được hóa giải."}],"related":[{"hanzi":"坦诚","pinyin":"tǎnchéng","vi":"thẳng thắn chân thành"},{"hanzi":"真诚","pinyin":"zhēnchéng","vi":"chân thành"},{"hanzi":"开诚布公","pinyin":"kāichéngbùgōng","vi":"thẳng thắn công khai"},{"hanzi":"肝胆相照","pinyin":"gāndǎnxiāngzhào","vi":"thật lòng với nhau"}]},{"id":"脱口而出","hanzi":"脱口而出","pinyin":"tuōkǒu-érchū","meaning_vi":"buột miệng nói ra","explanation":"脱口 (thoát khẩu – ra khỏi miệng) + 而出 → chưa kịp suy nghĩ đã buột miệng nói ra.","hsk_level":6,"tags":["thanh-ngu","giao-tiep"],"image":"😮","examples":[{"type":"basic","zh":"答案脱口而出。","pinyin":"Dá'àn tuōkǒu'érchū.","vi":"Câu trả lời buột miệng nói ra."},{"type":"simple","zh":"他一生气就把秘密脱口而出了。","pinyin":"Tā yì shēngqì jiù bǎ mìmì tuōkǒu'érchū le.","vi":"Vừa nổi giận là anh ta buột miệng nói ra bí mật."},{"type":"compound","zh":"那句话脱口而出以后，她后悔得不得了，可是已经来不及了。","pinyin":"Nà jù huà tuōkǒu'érchū yǐhòu, tā hòuhuǐ de budéliǎo, kěshì yǐjīng láibují le.","vi":"Sau khi buột miệng nói ra câu đó, cô ấy hối hận vô cùng, nhưng đã không kịp nữa."}],"related":[{"hanzi":"随口","pinyin":"suíkǒu","vi":"buột miệng"},{"hanzi":"不假思索","pinyin":"bùjiǎsīsuǒ","vi":"không cần nghĩ ngợi"},{"hanzi":"口无遮拦","pinyin":"kǒuwúzhēlán","vi":"ăn nói bừa bãi"},{"hanzi":"冲口而出","pinyin":"chōngkǒu'érchū","vi":"buột miệng nói ra"}],"traditional":"脫口而出"},{"id":"脱离","hanzi":"脱离","pinyin":"tuōlí","meaning_vi":"thoát ly, tách rời","explanation":"脱 (cởi) + 离 (rời xa).","hsk_level":6,"tags":["dong-tu"],"image":"🕊️","examples":[{"type":"basic","zh":"病人已脱离危险。","pinyin":"Bìngrén yǐ tuōlí wēixiǎn.","vi":"Bệnh nhân đã thoát khỏi nguy hiểm."},{"type":"simple","zh":"这个方案完全脱离了实际情况。","pinyin":"Zhè ge fāng'àn wánquán tuōlíle shíjì qíngkuàng.","vi":"Phương án này hoàn toàn tách rời thực tế."},{"type":"compound","zh":"他二十岁就脱离了家庭，而且从此再没回过老家。","pinyin":"Tā èrshí suì jiù tuōlíle jiātíng, érqiě cóngcǐ zài méi huíguo lǎojiā.","vi":"Anh ấy thoát ly gia đình từ năm hai mươi tuổi, và từ đó không về quê nữa."}],"related":[{"hanzi":"摆脱","pinyin":"bǎituō","vi":"thoát khỏi"},{"hanzi":"离开","pinyin":"líkāi","vi":"rời khỏi"},{"hanzi":"分离","pinyin":"fēnlí","vi":"tách rời"},{"hanzi":"脱离危险","pinyin":"tuōlíwēixiǎn","vi":"thoát khỏi nguy hiểm"}],"traditional":"脫離"},{"id":"脱颖而出","hanzi":"脱颖而出","pinyin":"tuōyǐng-érchū","meaning_vi":"tỏa sáng nổi bật giữa đám đông (tài năng)","explanation":"Mũi dùi (颖) lọt ra khỏi túi (truyện Mao Toại tự tiến cử) → tài năng bộc lộ, nổi bật hẳn lên giữa đám đông.","hsk_level":6,"tags":["thanh-ngu"],"image":"🌟","examples":[{"type":"basic","zh":"她在比赛中脱颖而出。","pinyin":"Tā zài bǐsài zhōng tuōyǐng'érchū.","vi":"Cô ấy nổi bật hẳn lên trong cuộc thi."},{"type":"simple","zh":"他从五百名应聘者中脱颖而出。","pinyin":"Tā cóng wǔ bǎi míng yìngpìnzhě zhōng tuōyǐng'érchū.","vi":"Anh ấy tỏa sáng nổi bật giữa năm trăm ứng viên."},{"type":"compound","zh":"只要你有真本事，就一定能在人才市场上脱颖而出。","pinyin":"Zhǐyào nǐ yǒu zhēn běnshi, jiù yídìng néng zài réncái shìchǎng shang tuōyǐng'érchū.","vi":"Chỉ cần bạn có thực tài thì nhất định sẽ nổi bật trên thị trường nhân lực."}],"related":[{"hanzi":"出类拔萃","pinyin":"chūlèibácuì","vi":"xuất chúng"},{"hanzi":"崭露头角","pinyin":"zhǎnlùtóujiǎo","vi":"bộc lộ tài năng"},{"hanzi":"突出","pinyin":"tūchū","vi":"nổi bật"},{"hanzi":"出众","pinyin":"chūzhòng","vi":"xuất chúng"}],"traditional":"脫穎而出"},{"id":"妥善","hanzi":"妥善","pinyin":"tuǒshàn","meaning_vi":"thỏa đáng, chu toàn","explanation":"妥 + 善 (tốt đẹp).","hsk_level":6,"tags":["tinh-tu"],"image":"👍","examples":[{"type":"basic","zh":"请妥善保管证件。","pinyin":"Qǐng tuǒshàn bǎoguǎn zhèngjiàn.","vi":"Xin hãy giữ gìn giấy tờ cẩn thận chu đáo."},{"type":"simple","zh":"政府妥善安置了受灾群众。","pinyin":"Zhèngfǔ tuǒshàn ānzhìle shòuzāi qúnzhòng.","vi":"Chính quyền đã sắp xếp chỗ ở thỏa đáng cho người dân bị thiên tai."},{"type":"compound","zh":"如果这件纠纷不能妥善处理，就会影响公司的声誉。","pinyin":"Rúguǒ zhè jiàn jiūfēn bù néng tuǒshàn chǔlǐ, jiù huì yǐngxiǎng gōngsī de shēngyù.","vi":"Nếu vụ tranh chấp này không được xử lý thỏa đáng thì sẽ ảnh hưởng đến danh tiếng công ty."}],"related":[{"hanzi":"妥当","pinyin":"tuǒdang","vi":"thỏa đáng"},{"hanzi":"稳妥","pinyin":"wěntuǒ","vi":"ổn thỏa"},{"hanzi":"恰当","pinyin":"qiàdàng","vi":"thích đáng"},{"hanzi":"妥善处理","pinyin":"tuǒshànchǔlǐ","vi":"xử lý thỏa đáng"}]},{"id":"泰然自若","hanzi":"泰然自若","pinyin":"tàirán-zìruò","meaning_vi":"điềm nhiên tự tại, bình tĩnh trước sóng gió","explanation":"泰然 (thái nhiên – bình thản) + 自若 (tự nhược – vẫn như thường) → gặp chuyện vẫn điềm tĩnh như không.","hsk_level":6,"tags":["thanh-ngu"],"image":"🧘","examples":[{"type":"basic","zh":"他神情泰然自若。","pinyin":"Tā shénqíng tàiránzìruò.","vi":"Nét mặt anh ấy điềm nhiên tự tại."},{"type":"simple","zh":"飞机剧烈颠簸，机长却泰然自若。","pinyin":"Fēijī jùliè diānbǒ, jīzhǎng què tàiránzìruò.","vi":"Máy bay rung lắc dữ dội, nhưng cơ trưởng vẫn điềm nhiên tự tại."},{"type":"compound","zh":"虽然记者的问题很尖锐，但是发言人始终泰然自若。","pinyin":"Suīrán jìzhě de wèntí hěn jiānruì, dànshì fāyánrén shǐzhōng tàiránzìruò.","vi":"Tuy câu hỏi của phóng viên rất gay gắt, nhưng người phát ngôn trước sau vẫn điềm tĩnh."}],"related":[{"hanzi":"镇定","pinyin":"zhèndìng","vi":"bình tĩnh"},{"hanzi":"从容不迫","pinyin":"cóngróngbúpò","vi":"ung dung thong thả"},{"hanzi":"若无其事","pinyin":"ruòwúqíshì","vi":"như không có chuyện gì"},{"hanzi":"惊慌失措","pinyin":"jīnghuāngshīcuò","vi":"hoảng hốt luống cuống"}]},{"id":"探求","hanzi":"探求","pinyin":"tànqiú","meaning_vi":"tìm tòi, khám phá (chân lý/tri thức)","explanation":"探 (tìm) + 求 (cầu).","hsk_level":6,"tags":["dong-tu","hoc-tap"],"image":"🔭","examples":[{"type":"basic","zh":"他一生探求真理。","pinyin":"Tā yìshēng tànqiú zhēnlǐ.","vi":"Cả đời ông ấy tìm tòi chân lý."},{"type":"simple","zh":"科学家们不断探求宇宙的奥秘。","pinyin":"Kēxuéjiāmen búduàn tànqiú yǔzhòu de àomì.","vi":"Các nhà khoa học không ngừng khám phá bí ẩn của vũ trụ."},{"type":"compound","zh":"因为他喜欢探求问题的根源，所以常常一个人研究到深夜。","pinyin":"Yīnwèi tā xǐhuan tànqiú wèntí de gēnyuán, suǒyǐ chángcháng yígèrén yánjiū dào shēnyè.","vi":"Vì thích tìm tòi tận gốc vấn đề nên anh ấy thường một mình nghiên cứu đến khuya."}],"related":[{"hanzi":"探索","pinyin":"tànsuǒ","vi":"khám phá"},{"hanzi":"追求","pinyin":"zhuīqiú","vi":"theo đuổi"},{"hanzi":"研究","pinyin":"yánjiū","vi":"nghiên cứu"},{"hanzi":"寻求","pinyin":"xúnqiú","vi":"tìm kiếm"}]},{"id":"叹气","hanzi":"叹气","pinyin":"tànqì","meaning_vi":"thở dài","explanation":"叹 + 气 (hơi thở). Động từ ly hợp.","hsk_level":6,"tags":["dong-tu","cam-xuc"],"image":"😮‍💨","examples":[{"type":"basic","zh":"妈妈轻轻叹气。","pinyin":"Māma qīngqīng tànqì.","vi":"Mẹ khẽ thở dài."},{"type":"simple","zh":"他看着成绩单，忍不住直叹气。","pinyin":"Tā kànzhe chéngjìdān, rěnbuzhù zhí tànqì.","vi":"Nhìn bảng điểm, cậu ấy không kìm được cứ thở dài mãi."},{"type":"compound","zh":"与其坐在那里唉声叹气，不如想想怎么解决问题。","pinyin":"Yǔqí zuò zài nàlǐ āi shēng tànqì, bùrú xiǎng xiang zěnme jiějué wèntí.","vi":"Thay vì ngồi đó than ngắn thở dài, chi bằng nghĩ xem giải quyết vấn đề thế nào."}],"related":[{"hanzi":"唉声叹气","pinyin":"āishēngtànqì","vi":"than ngắn thở dài"},{"hanzi":"叹息","pinyin":"tànxī","vi":"than thở"},{"hanzi":"感叹","pinyin":"gǎntàn","vi":"cảm thán"},{"hanzi":"呼吸","pinyin":"hūxī","vi":"hô hấp"}],"traditional":"嘆氣"},{"id":"探望","hanzi":"探望","pinyin":"tànwàng","meaning_vi":"thăm hỏi, thăm nom","explanation":"探 + 望 (ngóng). Đồng nghĩa với 看望.","hsk_level":6,"tags":["dong-tu","giao-tiep"],"image":"💐","examples":[{"type":"basic","zh":"周末我去探望奶奶。","pinyin":"Zhōumò wǒqù tànwàng nǎinai.","vi":"Cuối tuần tôi đi thăm bà nội."},{"type":"simple","zh":"同事们带着水果去医院探望他。","pinyin":"Tóngshìmen dàizhe shuǐguǒ qù yīyuàn tànwàng tā.","vi":"Đồng nghiệp mang hoa quả đến bệnh viện thăm anh ấy."},{"type":"compound","zh":"虽然工作很忙，但是她每个月都回老家探望父母。","pinyin":"Suīrán gōngzuò hěn máng, dànshì tā měi gèyuè dōu huílǎojiā tànwàng fùmǔ.","vi":"Tuy công việc rất bận, nhưng tháng nào cô ấy cũng về quê thăm bố mẹ."}],"related":[{"hanzi":"看望","pinyin":"kànwàng","vi":"thăm hỏi"},{"hanzi":"拜访","pinyin":"bàifǎng","vi":"đến thăm"},{"hanzi":"探病","pinyin":"tànbìng","vi":"thăm người ốm"},{"hanzi":"问候","pinyin":"wènhòu","vi":"hỏi thăm"}]},{"id":"叹为观止","hanzi":"叹为观止","pinyin":"tànwéi-guānzhǐ","meaning_vi":"trầm trồ khen ngợi hết lời","explanation":"Khen rằng xem đến đây là hết mức (Quý Trát xem nhạc nước Lỗ) → tán thưởng hết lời, cho là hay đẹp đến tột đỉnh.","hsk_level":6,"tags":["thanh-ngu"],"image":"🤩","examples":[{"type":"basic","zh":"这座宫殿令人叹为观止。","pinyin":"Zhè zuò gōngdiàn lìngrén tànwéiguānzhǐ.","vi":"Cung điện này khiến người ta trầm trồ thán phục."},{"type":"simple","zh":"杂技演员的表演让观众叹为观止。","pinyin":"Zájì yǎnyuán de biǎoyǎn ràng guānzhòng tànwéiguānzhǐ.","vi":"Màn biểu diễn của diễn viên xiếc khiến khán giả trầm trồ khen ngợi."},{"type":"compound","zh":"一走进溶洞，游客们就被眼前的景色惊得叹为观止。","pinyin":"Yì zǒujìn róngdòng, yóukèmen jiù bèi yǎnqián de jǐngsè jīng de tànwéiguānzhǐ.","vi":"Vừa bước vào hang động, du khách đã sững sờ trầm trồ trước cảnh sắc trước mắt."}],"related":[{"hanzi":"赞叹","pinyin":"zàntàn","vi":"tán thán"},{"hanzi":"惊叹","pinyin":"jīngtàn","vi":"kinh ngạc thán phục"},{"hanzi":"赞不绝口","pinyin":"zànbùjuékǒu","vi":"khen không ngớt lời"},{"hanzi":"精彩","pinyin":"jīngcǎi","vi":"đặc sắc"}],"traditional":"嘆為觀止"},{"id":"谈何容易","hanzi":"谈何容易","pinyin":"tánhé-róngyì","meaning_vi":"nói thì dễ làm mới khó, đâu phải chuyện dễ","explanation":"谈 (đàm – nói) 何 (hà – sao) 容易 (dung dị – dễ) → nói ra thì dễ, làm thật mới khó; đâu phải chuyện dễ.","hsk_level":6,"tags":["thanh-ngu"],"image":"🤷","examples":[{"type":"basic","zh":"戒烟谈何容易！","pinyin":"Jièyān tánhéróngyì!","vi":"Cai thuốc lá đâu phải chuyện dễ!"},{"type":"simple","zh":"一个人创业养活全家，谈何容易？","pinyin":"Yígèrén chuàngyè yǎnghuo quánjiā, tánhéróngyì?","vi":"Một mình khởi nghiệp nuôi cả nhà, đâu phải chuyện dễ?"},{"type":"compound","zh":"说起来很简单，可是真要做到，谈何容易。","pinyin":"Shuōqǐlái hěn jiǎndān, kěshì zhēn yào zuòdào, tánhéróngyì.","vi":"Nói thì đơn giản, nhưng thật sự làm được thì đâu có dễ."}],"related":[{"hanzi":"说起来容易","pinyin":"shuōqǐlái róngyì","vi":"nói thì dễ"},{"hanzi":"不容易","pinyin":"bùróngyì","vi":"không dễ"},{"hanzi":"困难","pinyin":"kùnnan","vi":"khó khăn"},{"hanzi":"轻而易举","pinyin":"qīng'éryìjǔ","vi":"dễ như trở bàn tay"}],"traditional":"談何容易"},{"id":"谈吐","hanzi":"谈吐","pinyin":"tántǔ","meaning_vi":"cách ăn nói, khẩu khí","explanation":"谈 (nói) + 吐 (thốt ra).","hsk_level":6,"tags":["danh-tu","giao-tiep"],"image":"🗣️","examples":[{"type":"basic","zh":"他谈吐很优雅。","pinyin":"Tā tántǔ hěn yōuyǎ.","vi":"Cách ăn nói của anh ấy rất tao nhã."},{"type":"simple","zh":"面试官很欣赏她得体的谈吐。","pinyin":"Miànshìguān hěn xīnshǎng tā détǐ de tántǔ.","vi":"Người phỏng vấn rất đánh giá cao cách ăn nói đúng mực của cô ấy."},{"type":"compound","zh":"他不但学识渊博，而且谈吐幽默，大家都爱听他讲课。","pinyin":"Tā búdàn xuéshí yuānbó, érqiě tántǔ yōumò, dàjiā dōu ài tīng tā jiǎngkè.","vi":"Ông ấy không những học rộng mà cách ăn nói còn hài hước, ai cũng thích nghe ông giảng bài."}],"related":[{"hanzi":"言谈","pinyin":"yántán","vi":"lời ăn tiếng nói"},{"hanzi":"举止","pinyin":"jǔzhǐ","vi":"cử chỉ"},{"hanzi":"谈吐不凡","pinyin":"tántǔbùfán","vi":"ăn nói phi phàm"},{"hanzi":"口才","pinyin":"kǒucái","vi":"tài ăn nói"}],"traditional":"談吐"},{"id":"谈笑风生","hanzi":"谈笑风生","pinyin":"tánxiào-fēngshēng","meaning_vi":"trò chuyện vui vẻ duyên dáng","explanation":"谈笑 (nói cười) + 风生 (như gió nổi) → trò chuyện vui vẻ, hóm hỉnh, sôi nổi.","hsk_level":6,"tags":["thanh-ngu","giao-tiep"],"image":"😄","examples":[{"type":"basic","zh":"宴会上他谈笑风生。","pinyin":"Yànhuì shang tā tánxiàofēngshēng.","vi":"Trong bữa tiệc anh ấy trò chuyện vui vẻ duyên dáng."},{"type":"simple","zh":"几位老朋友围坐在炉边谈笑风生。","pinyin":"Jǐ wèi lǎopéngyou wéizuò zài lúbiān tánxiàofēngshēng.","vi":"Mấy người bạn cũ ngồi quanh lò sưởi chuyện trò rôm rả."},{"type":"compound","zh":"他刚才还谈笑风生，一听到那个消息就沉默了。","pinyin":"Tā gāngcái hái tánxiàofēngshēng, yì tīngdào nà ge xiāoxi jiù chénmò le.","vi":"Vừa nãy anh ấy còn nói cười vui vẻ, vừa nghe tin đó liền im lặng."}],"related":[{"hanzi":"有说有笑","pinyin":"yǒushuōyǒuxiào","vi":"vừa nói vừa cười"},{"hanzi":"谈天说地","pinyin":"tántiānshuōdì","vi":"trò chuyện đủ thứ"},{"hanzi":"风趣","pinyin":"fēngqù","vi":"dí dỏm"},{"hanzi":"谈话","pinyin":"tánhuà","vi":"nói chuyện"}],"traditional":"談笑風生"},{"id":"堂堂正正","hanzi":"堂堂正正","pinyin":"tángtáng-zhèngzhèng","meaning_vi":"đường đường chính chính","explanation":"Từ láy AABB.","hsk_level":6,"tags":["thanh-ngu"],"image":"🦁","examples":[{"type":"basic","zh":"做人要堂堂正正。","pinyin":"Zuòrén yào tángtángzhèngzhèng.","vi":"Làm người phải đường đường chính chính."},{"type":"simple","zh":"我们要堂堂正正地赢下这场比赛。","pinyin":"Wǒmen yào tángtángzhèngzhèng de yíng xià zhè chǎng bǐsài.","vi":"Chúng ta phải thắng trận đấu này một cách đường đường chính chính."},{"type":"compound","zh":"即使输了比赛，我们也要输得堂堂正正。","pinyin":"Jíshǐ shūle bǐsài, wǒmen yě yào shū de tángtángzhèngzhèng.","vi":"Dù có thua trận, chúng ta cũng phải thua một cách đường đường chính chính."}],"related":[{"hanzi":"光明正大","pinyin":"guāngmíngzhèngdà","vi":"quang minh chính đại"},{"hanzi":"正直","pinyin":"zhèngzhí","vi":"chính trực"},{"hanzi":"坦荡","pinyin":"tǎndàng","vi":"ngay thẳng"},{"hanzi":"鬼鬼祟祟","pinyin":"guǐguǐsuìsuì","vi":"lén lén lút lút"}]},{"id":"堂而皇之","hanzi":"堂而皇之","pinyin":"táng'ér-huángzhī","meaning_vi":"công khai đường hoàng (thường hàm ý châm biếm)","explanation":"Từ 堂皇 (đường hoàng) → công khai, đàng hoàng không che giấu; thường châm biếm việc làm sai mà ngang nhiên.","hsk_level":6,"tags":["thanh-ngu"],"image":"🏛️","examples":[{"type":"basic","zh":"他堂而皇之地插队。","pinyin":"Tā táng'érhuángzhī de chāduì.","vi":"Hắn ta công khai chen hàng một cách trơ trẽn."},{"type":"simple","zh":"有人堂而皇之地把公物搬回了家。","pinyin":"Yǒurén táng'érhuángzhī de bǎ gōngwù bān huíle jiā.","vi":"Có người đường hoàng khuân đồ của công về nhà."},{"type":"compound","zh":"他抄袭了别人的论文，却堂而皇之地拿去评奖。","pinyin":"Tā chāoxíle biérén de lùnwén, què táng'érhuángzhī de ná qù píngjiǎng.","vi":"Hắn đạo văn luận văn của người khác, vậy mà còn công khai đem đi dự xét giải."}],"related":[{"hanzi":"冠冕堂皇","pinyin":"guānmiǎntánghuáng","vi":"đường hoàng bề ngoài"},{"hanzi":"公然","pinyin":"gōngrán","vi":"công khai trắng trợn"},{"hanzi":"明目张胆","pinyin":"míngmùzhāngdǎn","vi":"trắng trợn"},{"hanzi":"光明正大","pinyin":"guāngmíngzhèngdà","vi":"quang minh chính đại"}]},{"id":"淘汰","hanzi":"淘汰","pinyin":"táotài","meaning_vi":"đào thải, loại bỏ","explanation":"Cả hai chữ đều có bộ thủy 氵.","hsk_level":6,"tags":["dong-tu","the-thao"],"image":"❌","examples":[{"type":"basic","zh":"我们队被淘汰了。","pinyin":"Wǒmen duì bèi táotài le.","vi":"Đội chúng tôi bị loại rồi."},{"type":"simple","zh":"这种旧手机早就被市场淘汰了。","pinyin":"Zhè zhǒng jiù shǒujī zǎojiù bèi shìchǎng táotài le.","vi":"Loại điện thoại cũ này đã bị thị trường đào thải từ lâu."},{"type":"compound","zh":"如果企业不肯创新，就会被激烈的竞争淘汰。","pinyin":"Rúguǒ qǐyè bùkěn chuàngxīn, jiù huì bèi jīliè de jìngzhēng táotài.","vi":"Nếu doanh nghiệp không chịu đổi mới thì sẽ bị cạnh tranh khốc liệt đào thải."}],"related":[{"hanzi":"淘汰赛","pinyin":"táotàisài","vi":"vòng đấu loại"},{"hanzi":"优胜劣汰","pinyin":"yōushèngliètài","vi":"mạnh được yếu thua"},{"hanzi":"排除","pinyin":"páichú","vi":"loại trừ"},{"hanzi":"被淘汰","pinyin":"bèitáotài","vi":"bị loại"}]},{"id":"淘汰赛","hanzi":"淘汰赛","pinyin":"táotàisài","meaning_vi":"vòng đấu loại trực tiếp","explanation":"淘汰 + 赛 (thi đấu).","hsk_level":6,"tags":["danh-tu","the-thao"],"image":"🏆","examples":[{"type":"basic","zh":"明天进入淘汰赛。","pinyin":"Míngtiān jìnrù táotàisài.","vi":"Ngày mai bước vào vòng đấu loại trực tiếp."},{"type":"simple","zh":"淘汰赛第一轮就遇上了卫冕冠军。","pinyin":"Táotàisài dìyīlún jiù yùshàngle wèimiǎn guànjūn.","vi":"Ngay vòng một đấu loại trực tiếp đã gặp nhà đương kim vô địch."},{"type":"compound","zh":"淘汰赛只有一次机会，所以每个球员都格外拼命。","pinyin":"Táotàisài zhǐ yǒuyícì jīhuì, suǒyǐ měi gè qiúyuán dōu géwài pīnmìng.","vi":"Đấu loại trực tiếp chỉ có một cơ hội, nên cầu thủ nào cũng dốc hết sức."}],"related":[{"hanzi":"比赛","pinyin":"bǐsài","vi":"thi đấu"},{"hanzi":"决赛","pinyin":"juésài","vi":"chung kết"},{"hanzi":"半决赛","pinyin":"bànjuésài","vi":"bán kết"},{"hanzi":"小组赛","pinyin":"xiǎozǔsài","vi":"vòng bảng"}],"traditional":"淘汰賽"},{"id":"陶冶","hanzi":"陶冶","pinyin":"táoyě","meaning_vi":"hun đúc, bồi dưỡng (tình cảm/tâm hồn)","explanation":"陶 + 冶 (luyện kim). Cụm: 陶冶情操.","hsk_level":6,"tags":["dong-tu","van-hoa"],"image":"🎨","examples":[{"type":"basic","zh":"音乐能陶冶性情。","pinyin":"Yīnyuè néng táoyě xìngqíng.","vi":"Âm nhạc có thể hun đúc tính cách."},{"type":"simple","zh":"周末去博物馆可以陶冶孩子的情操。","pinyin":"Zhōumò qù bówùguǎn kěyǐ táoyě háizi de qíngcāo.","vi":"Cuối tuần đi bảo tàng có thể bồi dưỡng tâm hồn cho trẻ."},{"type":"compound","zh":"练书法既能陶冶情操，又能让人静下心来。","pinyin":"Liàn shūfǎ jì néng táoyě qíngcāo, yòu néng ràng rén jìng xià xīn lái.","vi":"Luyện thư pháp vừa có thể bồi dưỡng tâm hồn, vừa giúp con người tĩnh tâm."}],"related":[{"hanzi":"熏陶","pinyin":"xūntáo","vi":"hun đúc"},{"hanzi":"培养","pinyin":"péiyǎng","vi":"bồi dưỡng"},{"hanzi":"陶冶情操","pinyin":"táoyěqíngcāo","vi":"bồi dưỡng tâm hồn"},{"hanzi":"修养","pinyin":"xiūyǎng","vi":"tu dưỡng"}]},{"id":"特此","hanzi":"特此","pinyin":"tècǐ","meaning_vi":"nay trân trọng (dùng cuối công văn/thông báo)","explanation":"特 (đặc biệt) + 此 (điều này).","hsk_level":6,"tags":["pho-tu","cong-viec"],"image":"📜","examples":[{"type":"basic","zh":"特此通知。","pinyin":"Tècǐ tōngzhī.","vi":"Nay trân trọng thông báo."},{"type":"simple","zh":"因停电维修，明日停业一天，特此公告。","pinyin":"Yīn tíngdiàn wéixiū, míngrì tíngyè yì tiān, tècǐ gōnggào.","vi":"Do cúp điện sửa chữa, ngày mai tạm nghỉ một ngày, nay trân trọng thông báo."},{"type":"compound","zh":"由于王经理表现突出，公司决定给予奖励，特此表彰。","pinyin":"Yóuyú Wáng jīnglǐ biǎoxiàn tūchū, gōngsī juédìng jǐyǔ jiǎnglì, tècǐ biǎozhāng.","vi":"Do giám đốc Vương có thành tích nổi bật, công ty quyết định khen thưởng, nay trân trọng biểu dương."}],"related":[{"hanzi":"特此通知","pinyin":"tècǐtōngzhī","vi":"nay xin thông báo"},{"hanzi":"通知","pinyin":"tōngzhī","vi":"thông báo"},{"hanzi":"证明","pinyin":"zhèngmíng","vi":"chứng nhận"},{"hanzi":"公告","pinyin":"gōnggào","vi":"công bố"}]},{"id":"特权","hanzi":"特权","pinyin":"tèquán","meaning_vi":"đặc quyền","explanation":"特 + 权 (quyền lực).","hsk_level":6,"tags":["danh-tu","xa-hoi"],"image":"👑","examples":[{"type":"basic","zh":"谁都没有特权。","pinyin":"Shéi dōu méiyǒu tèquán.","vi":"Không ai có đặc quyền cả."},{"type":"simple","zh":"他利用特权为亲戚安排了工作。","pinyin":"Tā lìyòng tèquán wèi qīnqi ānpáile gōngzuò.","vi":"Ông ta lợi dụng đặc quyền để sắp xếp việc làm cho họ hàng."},{"type":"compound","zh":"会员不但享有打折特权，而且可以免费停车。","pinyin":"Huìyuán búdàn xiǎngyǒu dǎzhé tèquán, érqiě kěyǐ miǎnfèi tíngchē.","vi":"Hội viên không những được hưởng đặc quyền giảm giá mà còn được gửi xe miễn phí."}],"related":[{"hanzi":"权利","pinyin":"quánlì","vi":"quyền lợi"},{"hanzi":"权力","pinyin":"quánlì","vi":"quyền lực"},{"hanzi":"特殊","pinyin":"tèshū","vi":"đặc biệt"},{"hanzi":"特权阶层","pinyin":"tèquánjiēcéng","vi":"tầng lớp đặc quyền"}],"traditional":"特權"},{"id":"提拔","hanzi":"提拔","pinyin":"tíbá","meaning_vi":"đề bạt, thăng chức","explanation":"提 (nâng lên) + 拔 (kéo lên).","hsk_level":6,"tags":["dong-tu","cong-viec"],"image":"👔","examples":[{"type":"basic","zh":"他被提拔为主任。","pinyin":"Tā bèi tíbá wéi zhǔrèn.","vi":"Anh ấy được đề bạt làm chủ nhiệm."},{"type":"simple","zh":"老板决定提拔这位年轻的工程师。","pinyin":"Lǎobǎn juédìng tíbá zhè wèi niánqīng de gōngchéngshī.","vi":"Ông chủ quyết định đề bạt kỹ sư trẻ này."},{"type":"compound","zh":"因为她业绩一直排第一，所以很快就被提拔了。","pinyin":"Yīnwèi tā yèjì yì zhípái dìyī, suǒyǐ hěn kuài jiù bèi tíbá le.","vi":"Vì doanh số luôn đứng đầu nên cô ấy nhanh chóng được thăng chức."}],"related":[{"hanzi":"提升","pinyin":"tíshēng","vi":"thăng chức"},{"hanzi":"晋升","pinyin":"jìnshēng","vi":"thăng tiến"},{"hanzi":"升职","pinyin":"shēngzhí","vi":"lên chức"},{"hanzi":"降职","pinyin":"jiàngzhí","vi":"giáng chức"}]},{"id":"提议","hanzi":"提议","pinyin":"tíyì","meaning_vi":"đề nghị, kiến nghị","explanation":"提 + 议 (bàn bạc).","hsk_level":6,"tags":["dong-tu","cong-viec"],"image":"🙋","examples":[{"type":"basic","zh":"我提议休息一下。","pinyin":"Wǒ tíyì xiūxi yíxià.","vi":"Tôi đề nghị nghỉ một chút."},{"type":"simple","zh":"小李提议周末去郊外烧烤。","pinyin":"Xiǎo Lǐ tíyì zhōumò qù jiāowài shāokǎo.","vi":"Tiểu Lý đề nghị cuối tuần ra ngoại ô nướng thịt."},{"type":"compound","zh":"他的提议一提出来，就得到了全体员工的支持。","pinyin":"Tā de tíyì yì tí chūlái, jiù dédàole quántǐ yuángōng de zhīchí.","vi":"Đề nghị của anh ấy vừa đưa ra đã được toàn thể nhân viên ủng hộ."}],"related":[{"hanzi":"建议","pinyin":"jiànyì","vi":"kiến nghị"},{"hanzi":"提案","pinyin":"tí'àn","vi":"đề án"},{"hanzi":"倡议","pinyin":"chàngyì","vi":"đề xướng"},{"hanzi":"主张","pinyin":"zhǔzhāng","vi":"chủ trương"}],"traditional":"提議"},{"id":"亭亭玉立","hanzi":"亭亭玉立","pinyin":"tíngtíng-yùlì","meaning_vi":"dáng người thon thả thanh tú","explanation":"亭亭 (dáng cao thẳng) + 玉立 (đứng như ngọc) → dáng thon thả, duyên dáng; tả thiếu nữ hoặc cây hoa.","hsk_level":6,"tags":["thanh-ngu"],"image":"💃","examples":[{"type":"basic","zh":"她长得亭亭玉立。","pinyin":"Tā zhǎngde tíngtíngyùlì.","vi":"Cô ấy có dáng người thon thả thanh tú."},{"type":"simple","zh":"池塘里的荷花亭亭玉立。","pinyin":"Chítáng lǐ de héhuā tíngtíngyùlì.","vi":"Hoa sen trong ao vươn lên thanh tú yêu kiều."},{"type":"compound","zh":"几年不见，那个小丫头已经长成了亭亭玉立的大姑娘。","pinyin":"Jǐ nián bújiàn, nà ge xiǎo yātou yǐjīng zhǎng chéngle tíngtíngyùlì de dà gūniang.","vi":"Mấy năm không gặp, cô bé ngày nào đã thành thiếu nữ thon thả duyên dáng."}],"related":[{"hanzi":"苗条","pinyin":"miáotiao","vi":"thon thả"},{"hanzi":"婀娜多姿","pinyin":"ēnuóduōzī","vi":"thướt tha yểu điệu"},{"hanzi":"美丽","pinyin":"měilì","vi":"xinh đẹp"},{"hanzi":"身材","pinyin":"shēncái","vi":"vóc dáng"}]},{"id":"停滞","hanzi":"停滞","pinyin":"tíngzhì","meaning_vi":"đình trệ, trì trệ","explanation":"停 + 滞 (ngưng đọng).","hsk_level":6,"tags":["dong-tu"],"image":"🛑","examples":[{"type":"basic","zh":"经济陷入停滞。","pinyin":"Jīngjì xiànrù tíngzhì.","vi":"Kinh tế rơi vào đình trệ."},{"type":"simple","zh":"由于缺少资金，工程停滞了半年。","pinyin":"Yóuyú quēshǎo zījīn, gōngchéng tíngzhìle bàn nián.","vi":"Do thiếu vốn, công trình bị đình trệ nửa năm."},{"type":"compound","zh":"如果你满足于现状，你的技术水平就会停滞不前。","pinyin":"Rúguǒ nǐ mǎnzú yú xiànzhuàng, nǐ de jìshù shuǐpíng jiù huì tíngzhì bù qián.","vi":"Nếu bạn thỏa mãn với hiện tại thì trình độ kỹ thuật của bạn sẽ dậm chân tại chỗ."}],"related":[{"hanzi":"停顿","pinyin":"tíngdùn","vi":"ngừng trệ"},{"hanzi":"停滞不前","pinyin":"tíngzhìbùqián","vi":"đình trệ không tiến"},{"hanzi":"发展","pinyin":"fāzhǎn","vi":"phát triển"},{"hanzi":"萧条","pinyin":"xiāotiáo","vi":"tiêu điều"}],"traditional":"停滯"},{"id":"痛改前非","hanzi":"痛改前非","pinyin":"tònggǎi-qiánfēi","meaning_vi":"quyết tâm sửa chữa triệt để lỗi lầm trước đây","explanation":"痛 (triệt để) + 改 (sửa) + 前非 (lỗi trước) → quyết tâm sửa hẳn sai lầm cũ.","hsk_level":6,"tags":["thanh-ngu"],"image":"🌱","examples":[{"type":"basic","zh":"他决心痛改前非。","pinyin":"Tā juéxīn tònggǎiqiánfēi.","vi":"Anh ta quyết tâm sửa chữa triệt để lỗi lầm trước đây."},{"type":"simple","zh":"出狱后，他痛改前非，开了一家小店。","pinyin":"Chūyù hòu, tā tònggǎiqiánfēi, kāile yìjiā xiǎodiàn.","vi":"Sau khi ra tù, anh ta hối cải làm lại, mở một cửa hàng nhỏ."},{"type":"compound","zh":"只要你真心痛改前非，大家就会给你重新开始的机会。","pinyin":"Zhǐyào nǐ zhēnxīn tònggǎiqiánfēi, dàjiā jiù huì gěi nǐ chóngxīn kāishǐ de jīhuì.","vi":"Chỉ cần anh thật lòng sửa đổi lỗi lầm, mọi người sẽ cho anh cơ hội làm lại từ đầu."}],"related":[{"hanzi":"改过自新","pinyin":"gǎiguòzìxīn","vi":"sửa lỗi làm lại"},{"hanzi":"改正","pinyin":"gǎizhèng","vi":"sửa chữa"},{"hanzi":"悔改","pinyin":"huǐgǎi","vi":"hối cải"},{"hanzi":"执迷不悟","pinyin":"zhímíbúwù","vi":"u mê không tỉnh"}]},{"id":"透彻","hanzi":"透彻","pinyin":"tòuchè","meaning_vi":"thấu đáo, sâu sắc","explanation":"透 (xuyên qua) + 彻 (thông suốt).","hsk_level":6,"tags":["tinh-tu"],"image":"💡","examples":[{"type":"basic","zh":"他分析得很透彻。","pinyin":"Tā fēnxī de hěn tòuchè.","vi":"Anh ấy phân tích rất thấu đáo."},{"type":"simple","zh":"老师把这个难题讲得非常透彻。","pinyin":"Lǎoshī bǎ zhè ge nántí jiǎng de fēicháng tòuchè.","vi":"Thầy giáo giảng bài toán khó này vô cùng thấu đáo."},{"type":"compound","zh":"只有把原理理解透彻，做题时才能举一反三。","pinyin":"Zhǐyǒu bǎ yuánlǐ lǐjiě tòuchè, zuò tí shí cáinéng jǔyìfǎnsān.","vi":"Chỉ khi hiểu thấu đáo nguyên lý thì làm bài mới có thể suy một ra ba."}],"related":[{"hanzi":"深刻","pinyin":"shēnkè","vi":"sâu sắc"},{"hanzi":"彻底","pinyin":"chèdǐ","vi":"triệt để"},{"hanzi":"透彻理解","pinyin":"tòuchèlǐjiě","vi":"hiểu thấu đáo"},{"hanzi":"深入","pinyin":"shēnrù","vi":"đi sâu"}],"traditional":"透徹"},{"id":"同归于尽","hanzi":"同归于尽","pinyin":"tóngguī-yújìn","meaning_vi":"cùng nhau tiêu vong","explanation":"同 (đồng – cùng) 归 (quy – về) 于 尽 (tận – hết) → cùng đi đến chỗ diệt vong, cùng chết với nhau.","hsk_level":6,"tags":["thanh-ngu"],"image":"💥","examples":[{"type":"basic","zh":"歹徒想同归于尽。","pinyin":"Dǎitú xiǎng tóngguīyújìn.","vi":"Tên côn đồ muốn cùng chết với mọi người."},{"type":"simple","zh":"两只狼在搏斗中同归于尽了。","pinyin":"Liǎng zhī láng zài bódòu zhōng tóngguīyújìn le.","vi":"Hai con sói đã cùng chết trong cuộc vật lộn."},{"type":"compound","zh":"如果双方继续恶性竞争，最后只会同归于尽。","pinyin":"Rúguǒ shuāngfāng jìxù èxìngjìngzhēng, zuìhòu zhǐ huì tóngguīyújìn.","vi":"Nếu hai bên tiếp tục cạnh tranh khốc liệt thì cuối cùng chỉ có cùng nhau tiêu vong."}],"related":[{"hanzi":"两败俱伤","pinyin":"liǎngbàijùshāng","vi":"cả hai cùng thiệt"},{"hanzi":"毁灭","pinyin":"huǐmiè","vi":"hủy diệt"},{"hanzi":"鱼死网破","pinyin":"yúsǐwǎngpò","vi":"cá chết lưới rách"},{"hanzi":"灭亡","pinyin":"mièwáng","vi":"diệt vong"}],"traditional":"同歸於盡"},{"id":"同甘共苦","hanzi":"同甘共苦","pinyin":"tónggān-gòngkǔ","meaning_vi":"đồng cam cộng khổ","explanation":"同甘 (cùng ngọt) + 共苦 (cùng khổ). Thành ngữ.","hsk_level":6,"tags":["thanh-ngu"],"image":"❤️","examples":[{"type":"basic","zh":"夫妻应该同甘共苦。","pinyin":"Fūqī yīnggāi tónggāngòngkǔ.","vi":"Vợ chồng nên đồng cam cộng khổ."},{"type":"simple","zh":"创业那几年，我们几个同甘共苦。","pinyin":"Chuàngyè nà jǐ nián, wǒmen jǐ gè tónggāngòngkǔ.","vi":"Mấy năm khởi nghiệp, mấy anh em chúng tôi đồng cam cộng khổ."},{"type":"compound","zh":"既然我们决定同甘共苦，就不能一遇到困难就分开。","pinyin":"Jìrán wǒmen juédìng tónggāngòngkǔ, jiù bù néng yí yùdào kùnnan jiù fēnkāi.","vi":"Đã quyết định đồng cam cộng khổ thì không thể hễ gặp khó khăn là chia tay."}],"related":[{"hanzi":"同舟共济","pinyin":"tóngzhōugòngjì","vi":"chung lưng đấu cật"},{"hanzi":"患难与共","pinyin":"huànnànyǔgòng","vi":"hoạn nạn có nhau"},{"hanzi":"共同","pinyin":"gòngtóng","vi":"cùng nhau"},{"hanzi":"同心协力","pinyin":"tóngxīnxiélì","vi":"đồng tâm hiệp lực"}]},{"id":"童话","hanzi":"童话","pinyin":"tónghuà","meaning_vi":"truyện cổ tích","explanation":"童 (trẻ em) + 话 (câu chuyện).","hsk_level":6,"tags":["danh-tu","van-hoa","giai-tri"],"image":"🧚","examples":[{"type":"basic","zh":"我爱看童话。","pinyin":"Wǒ ài kàn tónghuà.","vi":"Tôi thích đọc truyện cổ tích."},{"type":"simple","zh":"奶奶每晚给孙女讲一个童话。","pinyin":"Nǎinai měi wǎn gěi sūnnǚ jiǎng yí gè tónghuà.","vi":"Tối nào bà cũng kể cho cháu gái nghe một câu chuyện cổ tích."},{"type":"compound","zh":"虽然童话里的故事不是真的，但是能让孩子学会善良。","pinyin":"Suīrán tónghuà lǐ de gùshi bú shì zhēn de, dànshì néng ràng háizi xuéhuì shànliáng.","vi":"Tuy chuyện trong cổ tích không có thật, nhưng có thể dạy trẻ biết lương thiện."}],"related":[{"hanzi":"故事","pinyin":"gùshi","vi":"câu chuyện"},{"hanzi":"童话故事","pinyin":"tónghuàgùshi","vi":"truyện cổ tích"},{"hanzi":"神话","pinyin":"shénhuà","vi":"thần thoại"},{"hanzi":"寓言","pinyin":"yùyán","vi":"ngụ ngôn"}],"traditional":"童話"},{"id":"同流合污","hanzi":"同流合污","pinyin":"tóngliú-héwū","meaning_vi":"cấu kết làm việc xấu, hùa theo cái xấu","explanation":"同流 (cùng dòng) + 合污 (hợp ô – hòa vào chỗ dơ) → hùa theo, cấu kết với kẻ xấu làm việc xấu.","hsk_level":6,"tags":["thanh-ngu"],"image":"👎","examples":[{"type":"basic","zh":"他不肯同流合污。","pinyin":"Tā bùkěn tóngliúhéwū.","vi":"Anh ấy không chịu hùa theo cái xấu."},{"type":"simple","zh":"他拒绝与贪官同流合污，结果被调走了。","pinyin":"Tā jùjué yǔ tānguān tóngliúhéwū, jiéguǒ bèi diào zǒu le.","vi":"Anh ấy từ chối cấu kết với quan tham, kết quả bị điều đi nơi khác."},{"type":"compound","zh":"即使周围的人都收了红包，他也绝不同流合污。","pinyin":"Jíshǐ zhōuwéi de rén dōu shōule hóngbāo, tā yě juébù tóngliúhéwū.","vi":"Dù những người xung quanh đều nhận phong bì, anh ấy cũng tuyệt đối không hùa theo."}],"related":[{"hanzi":"狼狈为奸","pinyin":"lángbèiwéijiān","vi":"cấu kết làm bậy"},{"hanzi":"勾结","pinyin":"gōujié","vi":"cấu kết"},{"hanzi":"随波逐流","pinyin":"suíbōzhúliú","vi":"trôi theo dòng"},{"hanzi":"洁身自好","pinyin":"jiéshēnzìhào","vi":"giữ mình trong sạch"}],"traditional":"同流合汙"},{"id":"铜墙铁壁","hanzi":"铜墙铁壁","pinyin":"tóngqiáng-tiěbì","meaning_vi":"tường đồng vách sắt (phòng tuyến kiên cố)","explanation":"铜墙 (tường đồng) + 铁壁 (vách sắt) → phòng tuyến kiên cố, không gì phá nổi.","hsk_level":6,"tags":["thanh-ngu"],"image":"🏰","examples":[{"type":"basic","zh":"防线如铜墙铁壁。","pinyin":"Fángxiàn rú tóngqiángtiěbì.","vi":"Phòng tuyến vững như tường đồng vách sắt."},{"type":"simple","zh":"这支球队的后防线就像铜墙铁壁。","pinyin":"Zhè zhī qiúduì de hòu fángxiàn jiù xiàng tóngqiángtiěbì.","vi":"Hàng phòng ngự của đội bóng này giống như tường đồng vách sắt."},{"type":"compound","zh":"即使敌人的城墙是铜墙铁壁，我们也要想办法攻破它。","pinyin":"Jíshǐ dírén de chéngqiáng shì tóngqiángtiěbì, wǒmen yě yào xiǎngbànfǎ gōngpò tā.","vi":"Dù tường thành của địch là tường đồng vách sắt, chúng ta cũng phải tìm cách phá vỡ nó."}],"related":[{"hanzi":"坚不可摧","pinyin":"jiānbùkěcuī","vi":"không thể phá vỡ"},{"hanzi":"牢固","pinyin":"láogù","vi":"vững chắc"},{"hanzi":"坚固","pinyin":"jiāngù","vi":"kiên cố"},{"hanzi":"防线","pinyin":"fángxiàn","vi":"phòng tuyến"}],"traditional":"銅牆鐵壁"},{"id":"同心协力","hanzi":"同心协力","pinyin":"tóngxīn-xiélì","meaning_vi":"đồng tâm hiệp lực","explanation":"同心 (cùng lòng) + 协力 (hợp sức) → đồng tâm hiệp lực. Gần nghĩa: 齐心协力.","hsk_level":6,"tags":["thanh-ngu"],"image":"🤝","examples":[{"type":"basic","zh":"大家同心协力干活。","pinyin":"Dàjiā tóngxīnxiélì gànhuó.","vi":"Mọi người đồng tâm hiệp lực làm việc."},{"type":"simple","zh":"村民们同心协力修好了被冲毁的桥。","pinyin":"Cūnmínmen tóngxīnxiélì xiūhǎole bèi chōng huǐ de qiáo.","vi":"Dân làng đồng tâm hiệp lực sửa xong cây cầu bị lũ cuốn trôi."},{"type":"compound","zh":"只要全队同心协力，就没有完不成的任务。","pinyin":"Zhǐyào quán duì tóngxīnxiélì, jiù méiyǒu wán buchéng de rènwu.","vi":"Chỉ cần cả đội đồng tâm hiệp lực thì không có nhiệm vụ nào không hoàn thành được."}],"related":[{"hanzi":"齐心协力","pinyin":"qíxīnxiélì","vi":"đồng lòng hợp sức"},{"hanzi":"团结","pinyin":"tuánjié","vi":"đoàn kết"},{"hanzi":"万众一心","pinyin":"wànzhòngyìxīn","vi":"vạn người như một"},{"hanzi":"合作","pinyin":"hézuò","vi":"hợp tác"}],"traditional":"同心協力"},{"id":"同舟共济","hanzi":"同舟共济","pinyin":"tóngzhōu-gòngjì","meaning_vi":"chung lưng đấu cật, cùng nhau vượt qua khó khăn","explanation":"同舟 (cùng thuyền) + 共济 (cùng qua sông). Thành ngữ.","hsk_level":6,"tags":["thanh-ngu"],"image":"🚣","examples":[{"type":"basic","zh":"危难时要同舟共济。","pinyin":"Wēinàn shí yào tóngzhōugòngjì.","vi":"Lúc hoạn nạn phải chung lưng đấu cật."},{"type":"simple","zh":"疫情期间，邻居们同舟共济，互相送菜。","pinyin":"Yìqíng qījiān, línjūmen tóngzhōugòngjì, hùxiāng sòng cài.","vi":"Trong thời gian dịch bệnh, hàng xóm cùng nhau vượt khó, gửi rau cho nhau."},{"type":"compound","zh":"公司虽然遇到了危机，但是员工们愿意同舟共济。","pinyin":"Gōngsī suīrán yùdàole wēijī, dànshì yuángōngmen yuànyì tóngzhōugòngjì.","vi":"Tuy công ty gặp khủng hoảng, nhưng nhân viên sẵn lòng cùng nhau vượt qua khó khăn."}],"related":[{"hanzi":"同甘共苦","pinyin":"tónggāngòngkǔ","vi":"đồng cam cộng khổ"},{"hanzi":"同心协力","pinyin":"tóngxīnxiélì","vi":"đồng tâm hiệp lực"},{"hanzi":"互相帮助","pinyin":"hùxiāngbāngzhù","vi":"giúp đỡ lẫn nhau"},{"hanzi":"团结","pinyin":"tuánjié","vi":"đoàn kết"}],"traditional":"同舟共濟"},{"id":"投机取巧","hanzi":"投机取巧","pinyin":"tóujī-qǔqiǎo","meaning_vi":"khôn lỏi, dùng mánh khóe để đi đường tắt","explanation":"投机 (đầu cơ – chớp thời cơ) + 取巧 (thủ xảo – dùng mánh khóe) → dùng mánh lới kiếm lợi mà không bỏ công sức thật.","hsk_level":6,"tags":["thanh-ngu"],"image":"🦊","examples":[{"type":"basic","zh":"学习不能投机取巧。","pinyin":"Xuéxí bù néng tóujīqǔqiǎo.","vi":"Học tập không thể khôn lỏi đi đường tắt."},{"type":"simple","zh":"他做生意总想投机取巧赚快钱。","pinyin":"Tā zuòshēngyi zǒng xiǎng tóujīqǔqiǎo zhuàn kuàiqián.","vi":"Anh ta làm ăn lúc nào cũng muốn khôn lỏi kiếm tiền nhanh."},{"type":"compound","zh":"如果总是投机取巧，那么迟早会吃大亏。","pinyin":"Rúguǒ zǒngshì tóujīqǔqiǎo, nàme chízǎo huì chīdàkuī.","vi":"Nếu lúc nào cũng khôn lỏi thì sớm muộn gì cũng chịu thiệt lớn."}],"related":[{"hanzi":"投机","pinyin":"tóujī","vi":"đầu cơ"},{"hanzi":"取巧","pinyin":"qǔqiǎo","vi":"khôn lỏi"},{"hanzi":"偷工减料","pinyin":"tōugōngjiǎnliào","vi":"ăn bớt vật liệu"},{"hanzi":"脚踏实地","pinyin":"jiǎotàshídì","vi":"chân chạm đất vững vàng"}],"traditional":"投機取巧"},{"id":"投诉","hanzi":"投诉","pinyin":"tóusù","meaning_vi":"khiếu nại, phàn nàn","explanation":"投 + 诉 (kể tội).","hsk_level":6,"tags":["dong-tu","mua-sam"],"image":"📞","examples":[{"type":"basic","zh":"我要投诉这家店。","pinyin":"Wǒ yào tóusù zhè jiā diàn.","vi":"Tôi muốn khiếu nại cửa hàng này."},{"type":"simple","zh":"她打电话投诉快递员态度太差。","pinyin":"Tā dǎdiànhuà tóusù kuàidìyuán tàidù tài chà.","vi":"Cô ấy gọi điện khiếu nại nhân viên giao hàng thái độ quá tệ."},{"type":"compound","zh":"如果客人投诉三次以上，这个服务员就会被扣奖金。","pinyin":"Rúguǒ kèrén tóusù sāncì yǐshàng, zhè ge fúwùyuán jiù huì bèi kòu jiǎngjīn.","vi":"Nếu khách khiếu nại từ ba lần trở lên, người phục vụ này sẽ bị trừ thưởng."}],"related":[{"hanzi":"抱怨","pinyin":"bàoyuàn","vi":"phàn nàn"},{"hanzi":"申诉","pinyin":"shēnsù","vi":"khiếu nại"},{"hanzi":"举报","pinyin":"jǔbào","vi":"tố giác"},{"hanzi":"投诉电话","pinyin":"tóusùdiànhuà","vi":"đường dây khiếu nại"}],"traditional":"投訴"},{"id":"头头是道","hanzi":"头头是道","pinyin":"tóutóu-shìdào","meaning_vi":"nói năng mạch lạc có lý có tình","explanation":"头头 (mọi đầu mối, mọi mặt) + 是道 (đều hợp đạo lý) → nói năng, làm việc đâu ra đấy, mạch lạc có lý.","hsk_level":6,"tags":["thanh-ngu","giao-tiep"],"image":"🗣️","examples":[{"type":"basic","zh":"他说得头头是道。","pinyin":"Tā shuō de tóutóushìdào.","vi":"Anh ấy nói năng đâu ra đấy."},{"type":"simple","zh":"这个小学生讲起恐龙来头头是道。","pinyin":"Zhè ge xiǎoxuéshēng jiǎng qǐ kǒnglóng lái tóutóushìdào.","vi":"Cậu học sinh tiểu học này nói về khủng long rất mạch lạc rành rọt."},{"type":"compound","zh":"他理论讲得头头是道，可是一动手就出错。","pinyin":"Tā lǐlùn jiǎng de tóutóushìdào, kěshì yí dòngshǒu jiù chūcuò.","vi":"Lý thuyết thì anh ta nói đâu ra đấy, nhưng hễ bắt tay làm là sai."}],"related":[{"hanzi":"有条有理","pinyin":"yǒutiáoyǒulǐ","vi":"có đầu có đuôi"},{"hanzi":"条理","pinyin":"tiáolǐ","vi":"mạch lạc"},{"hanzi":"振振有词","pinyin":"zhènzhènyǒucí","vi":"lý lẽ hùng hồn"},{"hanzi":"语无伦次","pinyin":"yǔwúlúncì","vi":"nói năng lộn xộn"}],"traditional":"頭頭是道"},{"id":"头晕目眩","hanzi":"头晕目眩","pinyin":"tóuyūn-mùxuàn","meaning_vi":"hoa mắt chóng mặt","explanation":"头晕 (đầu choáng) + 目眩 (mục huyễn – mắt hoa) → đầu choáng váng, mắt hoa lên.","hsk_level":6,"tags":["thanh-ngu","suc-khoe"],"image":"😵","examples":[{"type":"basic","zh":"我突然头晕目眩。","pinyin":"Wǒ tūrán tóuyūnmùxuàn.","vi":"Tôi đột nhiên hoa mắt chóng mặt."},{"type":"simple","zh":"站在高楼顶上往下看，让人头晕目眩。","pinyin":"Zhàn zài gāolóu dǐngshang wǎng xià kàn, ràng rén tóuyūnmùxuàn.","vi":"Đứng trên nóc tòa nhà cao nhìn xuống khiến người ta hoa mắt chóng mặt."},{"type":"compound","zh":"他一整天没吃饭，所以一站起来就头晕目眩。","pinyin":"Tā yìzhěngtiān méi chīfàn, suǒyǐ yí zhànqǐlái jiù tóuyūnmùxuàn.","vi":"Anh ấy cả ngày không ăn gì nên vừa đứng dậy là hoa mắt chóng mặt."}],"related":[{"hanzi":"头晕","pinyin":"tóuyūn","vi":"chóng mặt"},{"hanzi":"眼花","pinyin":"yǎnhuā","vi":"hoa mắt"},{"hanzi":"头昏脑涨","pinyin":"tóuhūnnǎozhàng","vi":"đầu óc choáng váng"},{"hanzi":"晕倒","pinyin":"yūndǎo","vi":"ngất xỉu"}],"traditional":"頭暈目眩"},{"id":"徒弟","hanzi":"徒弟","pinyin":"túdì","meaning_vi":"đồ đệ, học trò (học nghề)","explanation":"徒 + 弟 (em). Đối ứng với 师父 (sư phụ).","hsk_level":6,"tags":["danh-tu","con-nguoi","hoc-tap"],"image":"🙇","examples":[{"type":"basic","zh":"师傅收了个徒弟。","pinyin":"Shīfu shōule gè túdì.","vi":"Sư phụ đã nhận một đồ đệ."},{"type":"simple","zh":"老木匠把手艺都传给了徒弟。","pinyin":"Lǎo mùjiang bǎ shǒuyì dōu chuángěile túdì.","vi":"Người thợ mộc già truyền hết tay nghề cho học trò."},{"type":"compound","zh":"徒弟不但学会了师傅的本领，而且有了自己的创新。","pinyin":"Túdì búdàn xuéhuìle shīfu de běnlǐng, érqiě yǒule zìjǐ de chuàngxīn.","vi":"Đồ đệ không những học được bản lĩnh của sư phụ mà còn có sáng tạo riêng."}],"related":[{"hanzi":"师傅","pinyin":"shīfu","vi":"thầy sư phụ"},{"hanzi":"学徒","pinyin":"xuétú","vi":"người học việc"},{"hanzi":"弟子","pinyin":"dìzǐ","vi":"đệ tử"},{"hanzi":"徒弟出师","pinyin":"túdìchūshī","vi":"học trò ra nghề"}]},{"id":"途经","hanzi":"途经","pinyin":"tújīng","meaning_vi":"đi qua, quá cảnh (tuyến đường)","explanation":"途 (đường) + 经 (qua).","hsk_level":6,"tags":["dong-tu","giao-thong"],"image":"🚆","examples":[{"type":"basic","zh":"这趟火车途经南京。","pinyin":"Zhè tàng huǒchē tújīng Nánjīng.","vi":"Chuyến tàu này đi qua Nam Kinh."},{"type":"simple","zh":"我们去西藏时途经了好几个古镇。","pinyin":"Wǒmen qù Xīzàng shí tújīngle hǎojǐ gè gǔzhèn.","vi":"Khi đi Tây Tạng, chúng tôi đi qua mấy thị trấn cổ."},{"type":"compound","zh":"因为航班途经香港，所以我们顺便在那儿逛了一天。","pinyin":"Yīnwèi hángbān tújīng Xiānggǎng, suǒyǐ wǒmen shùnbiàn zài nàr guàngle yì tiān.","vi":"Vì chuyến bay quá cảnh Hồng Kông nên chúng tôi tiện thể dạo chơi ở đó một ngày."}],"related":[{"hanzi":"经过","pinyin":"jīngguò","vi":"đi qua"},{"hanzi":"路过","pinyin":"lùguò","vi":"ngang qua"},{"hanzi":"途中","pinyin":"túzhōng","vi":"trên đường"},{"hanzi":"路线","pinyin":"lùxiàn","vi":"tuyến đường"}],"traditional":"途經"},{"id":"徒劳","hanzi":"徒劳","pinyin":"túláo","meaning_vi":"uổng công vô ích","explanation":"徒 (suông) + 劳 (vất vả). Cụm: 徒劳无功.","hsk_level":6,"tags":["tinh-tu","dong-tu"],"image":"😓","examples":[{"type":"basic","zh":"一切努力都是徒劳。","pinyin":"Yíqiè nǔlì dōu shì túláo.","vi":"Mọi nỗ lực đều uổng công vô ích."},{"type":"simple","zh":"他想说服固执的父亲，结果是徒劳。","pinyin":"Tā xiǎng shuōfú gùzhí de fùqīn, jiéguǒ shì túláo.","vi":"Anh ấy muốn thuyết phục người cha cố chấp, kết quả là uổng công."},{"type":"compound","zh":"如果方向错了，那么再怎么用力也是徒劳。","pinyin":"Rúguǒ fāngxiàng cuò le, nàme zài zěnme yònglì yě shì túláo.","vi":"Nếu đi sai hướng thì dù cố gắng thế nào cũng là uổng công."}],"related":[{"hanzi":"白费","pinyin":"báifèi","vi":"uổng phí"},{"hanzi":"徒劳无功","pinyin":"túláowúgōng","vi":"uổng công vô ích"},{"hanzi":"白费力气","pinyin":"báifèilìqi","vi":"phí sức"},{"hanzi":"无济于事","pinyin":"wújìyúshì","vi":"chẳng ích gì"}],"traditional":"徒勞"},{"id":"涂鸦","hanzi":"涂鸦","pinyin":"túyā","meaning_vi":"vẽ bậy, viết nguệch ngoạc, tranh graffiti","explanation":"涂 (bôi) + 鸦 (con quạ).","hsk_level":6,"tags":["dong-tu","giai-tri"],"image":"🎨","examples":[{"type":"basic","zh":"墙上满是涂鸦。","pinyin":"Qiáng shang mǎnshì túyā.","vi":"Trên tường đầy những hình vẽ graffiti."},{"type":"simple","zh":"孩子在作业本上随手涂鸦。","pinyin":"Háizi zài zuòyè běn shang suíshǒu túyā.","vi":"Đứa trẻ vẽ nguệch ngoạc lung tung lên vở bài tập."},{"type":"compound","zh":"这条街的涂鸦既有创意，又成了网红打卡点。","pinyin":"Zhè tiáo jiē de túyā jìyǒu chuàngyì, yòu chéngle wǎnghóng dǎkǎ diǎn.","vi":"Tranh graffiti trên con phố này vừa sáng tạo, vừa trở thành điểm check-in nổi tiếng."}],"related":[{"hanzi":"涂抹","pinyin":"túmǒ","vi":"bôi quệt"},{"hanzi":"乱画","pinyin":"luànhuà","vi":"vẽ bậy"},{"hanzi":"绘画","pinyin":"huìhuà","vi":"hội họa"},{"hanzi":"墙壁","pinyin":"qiángbì","vi":"bức tường"}],"traditional":"塗鴉"},{"id":"贪得无厌","hanzi":"贪得无厌","pinyin":"tāndé-wúyàn","meaning_vi":"tham lam vô độ","explanation":"贪得 + 无厌 (không chán). Thành ngữ.","hsk_level":6,"tags":["thanh-ngu"],"image":"🤑","examples":[{"type":"basic","zh":"他真是贪得无厌。","pinyin":"Tā zhēn shì tāndéwúyàn.","vi":"Hắn đúng là tham lam vô độ."},{"type":"simple","zh":"贪得无厌的商人最终破产了。","pinyin":"Tāndéwúyàn de shāngrén zuìzhōng pòchǎn le.","vi":"Gã thương nhân tham lam vô độ cuối cùng đã phá sản."},{"type":"compound","zh":"渔夫的妻子贪得无厌，所以最后什么都没得到。","pinyin":"Yúfū de qīzi tāndéwúyàn, suǒyǐ zuìhòu shénme dōu méi dédào.","vi":"Vợ ông lão đánh cá tham lam vô độ nên cuối cùng chẳng được gì."}],"related":[{"hanzi":"贪婪","pinyin":"tānlán","vi":"tham lam"},{"hanzi":"得寸进尺","pinyin":"décùnjìnchǐ","vi":"được đằng chân lân đằng đầu"},{"hanzi":"贪心","pinyin":"tānxīn","vi":"lòng tham"},{"hanzi":"知足常乐","pinyin":"zhīzúchánglè","vi":"biết đủ thì vui"}],"traditional":"貪得無厭"},{"id":"瘫痪","hanzi":"瘫痪","pinyin":"tānhuàn","meaning_vi":"tê liệt, bại liệt","explanation":"Cả hai chữ đều có bộ nạch 疒(bệnh).","hsk_level":6,"tags":["dong-tu","suc-khoe"],"image":"♿","examples":[{"type":"basic","zh":"爷爷瘫痪在床。","pinyin":"Yéye tānhuàn zài chuáng.","vi":"Ông nội bị liệt nằm trên giường."},{"type":"simple","zh":"暴雪使全市交通几乎瘫痪。","pinyin":"Bàoxuě shǐ quánshì jiāotōng jīhū tānhuàn.","vi":"Bão tuyết khiến giao thông toàn thành phố gần như tê liệt."},{"type":"compound","zh":"服务器一出故障，整个订票系统就瘫痪了。","pinyin":"Fúwùqì yì chūgùzhàng, zhěnggè dìngpiào xìtǒng jiù tānhuàn le.","vi":"Máy chủ vừa gặp sự cố, toàn bộ hệ thống đặt vé liền tê liệt."}],"related":[{"hanzi":"偏瘫","pinyin":"piāntān","vi":"liệt nửa người"},{"hanzi":"瘫倒","pinyin":"tāndǎo","vi":"ngã gục"},{"hanzi":"交通瘫痪","pinyin":"jiāotōngtānhuàn","vi":"giao thông tê liệt"},{"hanzi":"麻木","pinyin":"mámù","vi":"tê dại"}],"traditional":"癱瘓"},{"id":"贪婪","hanzi":"贪婪","pinyin":"tānlán","meaning_vi":"tham lam","explanation":"贪 (tham) + 婪 (lam – tham) → tham lam không biết đủ. Cụm: 贪婪的目光.","hsk_level":6,"tags":["tinh-tu","con-nguoi"],"image":"🤑","examples":[{"type":"basic","zh":"他眼里满是贪婪。","pinyin":"Tā yǎn lǐ mǎnshì tānlán.","vi":"Trong mắt hắn đầy vẻ tham lam."},{"type":"simple","zh":"那只猫贪婪地盯着桌上的鱼。","pinyin":"Nà zhī māo tānlán de dīngzhe zhuō shang de yú.","vi":"Con mèo thèm thuồng nhìn chằm chằm con cá trên bàn."},{"type":"compound","zh":"人一旦变得贪婪，就很容易掉进别人的陷阱。","pinyin":"Rén yídàn biànde tānlán, jiù hěn róngyì diào jìn biérén de xiànjǐng.","vi":"Con người một khi trở nên tham lam thì rất dễ rơi vào bẫy của kẻ khác."}],"related":[{"hanzi":"贪心","pinyin":"tānxīn","vi":"lòng tham"},{"hanzi":"贪得无厌","pinyin":"tāndéwúyàn","vi":"tham lam vô độ"},{"hanzi":"贪图","pinyin":"tāntú","vi":"ham muốn"},{"hanzi":"吝啬","pinyin":"lìnsè","vi":"keo kiệt"}],"traditional":"貪婪"},{"id":"贪小失大","hanzi":"贪小失大","pinyin":"tānxiǎo-shīdà","meaning_vi":"tham bát bỏ mâm, tham nhỏ mất lớn","explanation":"贪 (tham) 小 (tiểu – nhỏ) 失 (thất – mất) 大 (đại – lớn) → tham lợi nhỏ mà mất lợi lớn.","hsk_level":6,"tags":["thanh-ngu"],"image":"⚖️","examples":[{"type":"basic","zh":"千万别贪小失大。","pinyin":"Qiānwàn bié tānxiǎoshīdà.","vi":"Nhất định đừng tham bát bỏ mâm."},{"type":"simple","zh":"为了省运费不买保险，真是贪小失大。","pinyin":"Wèile shěng yùnfèi bù mǎi bǎoxiǎn, zhēn shì tānxiǎoshīdà.","vi":"Vì tiết kiệm phí vận chuyển mà không mua bảo hiểm, đúng là tham nhỏ mất lớn."},{"type":"compound","zh":"他为了一点回扣丢了工作，可以说是贪小失大。","pinyin":"Tā wèile yìdiǎn huíkòu diūle gōngzuò, kěyǐ shuō shì tānxiǎoshīdà.","vi":"Anh ta vì chút tiền hoa hồng mà mất việc, có thể nói là tham bát bỏ mâm."}],"related":[{"hanzi":"因小失大","pinyin":"yīnxiǎoshīdà","vi":"vì nhỏ mất lớn"},{"hanzi":"贪小便宜","pinyin":"tānxiǎopiányi","vi":"ham lợi nhỏ"},{"hanzi":"得不偿失","pinyin":"débùchángshī","vi":"được không bù mất"},{"hanzi":"贪心","pinyin":"tānxīn","vi":"lòng tham"}],"traditional":"貪小失大"},{"id":"滔滔不绝","hanzi":"滔滔不绝","pinyin":"tāotāo-bùjué","meaning_vi":"nói thao thao bất tuyệt","explanation":"滔滔 (nước cuồn cuộn) + 不绝 (không dứt). Thành ngữ.","hsk_level":6,"tags":["thanh-ngu","giao-tiep"],"image":"🗣️","examples":[{"type":"basic","zh":"她说起话来滔滔不绝。","pinyin":"Tā shuōqǐ huà lái tāotāobùjué.","vi":"Cô ấy hễ nói là thao thao bất tuyệt."},{"type":"simple","zh":"导游一路上滔滔不绝地介绍历史。","pinyin":"Dǎoyóu yílùshang tāotāobùjué de jièshào lìshǐ.","vi":"Hướng dẫn viên suốt dọc đường thao thao giới thiệu lịch sử."},{"type":"compound","zh":"他一谈起足球就滔滔不绝，别人根本插不上嘴。","pinyin":"Tā yì tánqǐ zúqiú jiù tāotāobùjué, biérén gēnběn chā bu shàng zuǐ.","vi":"Anh ấy hễ nói về bóng đá là thao thao bất tuyệt, người khác chẳng chen vào được câu nào."}],"related":[{"hanzi":"口若悬河","pinyin":"kǒuruòxuánhé","vi":"nói như nước chảy"},{"hanzi":"喋喋不休","pinyin":"diédiébùxiū","vi":"nói luyên thuyên"},{"hanzi":"侃侃而谈","pinyin":"kǎnkǎn'értán","vi":"nói chuyện hùng hồn"},{"hanzi":"沉默寡言","pinyin":"chénmòguǎyán","vi":"trầm lặng ít nói"}],"traditional":"滔滔不絕"},{"id":"掏腰包","hanzi":"掏腰包","pinyin":"tāoyāobāo","meaning_vi":"móc hầu bao, bỏ tiền túi ra trả","explanation":"掏 + 腰包 (túi tiền). Thành ngữ khẩu ngữ.","hsk_level":6,"tags":["dong-tu","tien-te"],"image":"👛","examples":[{"type":"basic","zh":"这顿饭我掏腰包。","pinyin":"Zhè dùn fàn wǒ tāoyāobāo.","vi":"Bữa này tôi móc hầu bao trả."},{"type":"simple","zh":"维修费得由房东自己掏腰包。","pinyin":"Wéixiū fèi děi yóu fángdōng zìjǐ tāoyāobāo.","vi":"Phí sửa chữa phải do chủ nhà tự bỏ tiền túi ra trả."},{"type":"compound","zh":"公司虽然不报销，但是他还是自掏腰包买了新电脑。","pinyin":"Gōngsī suīrán bú bàoxiāo, dànshì tā háishi zì tāoyāobāo mǎile xīn diànnǎo.","vi":"Tuy công ty không thanh toán, nhưng anh ấy vẫn tự bỏ tiền túi mua máy tính mới."}],"related":[{"hanzi":"腰包","pinyin":"yāobāo","vi":"hầu bao"},{"hanzi":"付钱","pinyin":"fùqián","vi":"trả tiền"},{"hanzi":"请客","pinyin":"qǐngkè","vi":"mời khách"},{"hanzi":"自掏腰包","pinyin":"zìtāoyāobāo","vi":"tự bỏ tiền túi"}]},{"id":"通情达理","hanzi":"通情达理","pinyin":"tōngqíng-dálǐ","meaning_vi":"thấu tình đạt lý","explanation":"通情 (thông tình – hiểu tình) + 达理 (đạt lý – thấu lý) → hiểu chuyện, biết lẽ phải, biết thông cảm.","hsk_level":6,"tags":["thanh-ngu","con-nguoi"],"image":"🤝","examples":[{"type":"basic","zh":"她很通情达理。","pinyin":"Tā hěn tōngqíngdálǐ.","vi":"Cô ấy rất thấu tình đạt lý."},{"type":"simple","zh":"房东是个通情达理的老太太。","pinyin":"Fángdōng shì gè tōngqíngdálǐ de lǎotàitai.","vi":"Chủ nhà là một bà cụ rất thấu tình đạt lý."},{"type":"compound","zh":"他父母很通情达理，所以没有反对他转专业。","pinyin":"Tā fùmǔ hěn tōngqíngdálǐ, suǒyǐ méiyǒu fǎnduì tā zhuǎn zhuānyè.","vi":"Bố mẹ cậu ấy rất thấu tình đạt lý nên không phản đối cậu chuyển ngành."}],"related":[{"hanzi":"通情","pinyin":"tōngqíng","vi":"hiểu lòng người"},{"hanzi":"明白事理","pinyin":"míngbaishìlǐ","vi":"hiểu lẽ phải"},{"hanzi":"讲道理","pinyin":"jiǎngdàoli","vi":"biết điều"},{"hanzi":"蛮不讲理","pinyin":"mánbùjiǎnglǐ","vi":"ngang ngược vô lý"}],"traditional":"通情達理"},{"id":"通俗","hanzi":"通俗","pinyin":"tōngsú","meaning_vi":"thông tục, dễ hiểu, bình dân","explanation":"通 + 俗 (phổ thông).","hsk_level":6,"tags":["tinh-tu"],"image":"📖","examples":[{"type":"basic","zh":"这本书很通俗。","pinyin":"Zhè běn shū hěn tōngsú.","vi":"Cuốn sách này rất dễ hiểu."},{"type":"simple","zh":"教授用通俗的语言解释了量子力学。","pinyin":"Jiàoshòu yòng tōngsú de yǔyán jiěshìle liàngzǐlìxué.","vi":"Giáo sư dùng ngôn ngữ bình dân để giải thích cơ học lượng tử."},{"type":"compound","zh":"这首歌的歌词既通俗又有深意，所以很快就流行起来了。","pinyin":"Zhè shǒu gē de gēcí jì tōngsú yòu yǒu shēn yì, suǒyǐ hěn kuài jiù liúxíng qǐlái le.","vi":"Lời bài hát này vừa dễ hiểu vừa sâu sắc, nên nhanh chóng trở nên thịnh hành."}],"related":[{"hanzi":"通俗易懂","pinyin":"tōngsúyìdǒng","vi":"dễ hiểu"},{"hanzi":"大众化","pinyin":"dàzhònghuà","vi":"đại chúng hóa"},{"hanzi":"浅显","pinyin":"qiǎnxiǎn","vi":"dễ hiểu đơn giản"},{"hanzi":"深奥","pinyin":"shēn'ào","vi":"sâu xa khó hiểu"}]},{"id":"偷工减料","hanzi":"偷工减料","pinyin":"tōugōng-jiǎnliào","meaning_vi":"ăn bớt nguyên vật liệu, làm ẩu","explanation":"偷工 (bớt công) + 减料 (giảm vật liệu) → làm gian dối, bớt xén công sức và nguyên liệu (công trình, sản phẩm).","hsk_level":6,"tags":["thanh-ngu","cong-viec"],"image":"⚠️","examples":[{"type":"basic","zh":"这栋楼偷工减料。","pinyin":"Zhè dòng lóu tōugōngjiǎnliào.","vi":"Tòa nhà này bị ăn bớt nguyên vật liệu."},{"type":"simple","zh":"施工队偷工减料，导致桥梁开裂。","pinyin":"Shīgōng duì tōugōngjiǎnliào, dǎozhì qiáoliáng kāiliè.","vi":"Đội thi công ăn bớt vật liệu dẫn đến cầu bị nứt."},{"type":"compound","zh":"如果厂家偷工减料，那么产品质量肯定没有保证。","pinyin":"Rúguǒ chǎngjiā tōugōngjiǎnliào, nàme chǎnpǐn zhìliàng kěndìng méiyǒu bǎozhèng.","vi":"Nếu nhà sản xuất làm ẩu ăn bớt vật liệu thì chất lượng sản phẩm chắc chắn không được đảm bảo."}],"related":[{"hanzi":"粗制滥造","pinyin":"cūzhìlànzào","vi":"làm ẩu làm bừa"},{"hanzi":"敷衍了事","pinyin":"fūyǎnliǎoshì","vi":"làm qua loa"},{"hanzi":"精益求精","pinyin":"jīngyìqiújīng","vi":"tinh càng thêm tinh"},{"hanzi":"质量","pinyin":"zhìliàng","vi":"chất lượng"}],"traditional":"偷工減料"},{"id":"偷梁换柱","hanzi":"偷梁换柱","pinyin":"tōuliáng-huànzhù","meaning_vi":"đánh tráo khái niệm, trộm xà đổi cột","explanation":"Lén thay xà nhà và cột nhà → ngấm ngầm đánh tráo nội dung, bản chất để lừa người; một kế trong Tam thập lục kế.","hsk_level":6,"tags":["thanh-ngu"],"image":"🏛️","examples":[{"type":"basic","zh":"商家偷梁换柱。","pinyin":"Shāngjiā tōuliánghuànzhù.","vi":"Người bán đánh tráo hàng."},{"type":"simple","zh":"他偷梁换柱，把真画换成了假画。","pinyin":"Tā tōuliánghuànzhù, bǎ zhēn huà huànchéngle jiǎ huà.","vi":"Hắn trộm xà đổi cột, đánh tráo bức tranh thật thành tranh giả."},{"type":"compound","zh":"这篇文章表面上在讲道理，其实是在偷梁换柱地误导读者。","pinyin":"Zhè piān wénzhāng biǎomiànshang zài jiǎngdàolǐ, qíshí shì zài tōuliánghuànzhù de wùdǎo dúzhě.","vi":"Bài viết này bề ngoài thì nói lý lẽ, thực chất là đánh tráo khái niệm để đánh lừa người đọc."}],"related":[{"hanzi":"偷换概念","pinyin":"tōuhuàngàiniàn","vi":"đánh tráo khái niệm"},{"hanzi":"掉包","pinyin":"diàobāo","vi":"đánh tráo"},{"hanzi":"弄虚作假","pinyin":"nòngxūzuòjiǎ","vi":"làm giả gian dối"},{"hanzi":"欺骗","pinyin":"qīpiàn","vi":"lừa gạt"}],"traditional":"偷梁換柱"},{"id":"秃","hanzi":"秃","pinyin":"tū","meaning_vi":"hói (đầu), trọc (núi)","explanation":"Ví dụ: 秃头 (đầu hói).","hsk_level":6,"tags":["tinh-tu","co-the"],"image":"👨‍🦲","examples":[{"type":"basic","zh":"他的头顶秃了。","pinyin":"Tā de tóudǐng tū le.","vi":"Đỉnh đầu anh ấy đã hói rồi."},{"type":"simple","zh":"冬天到了，山上的树都秃了。","pinyin":"Dōngtiān dào le, shān shang de shù dōu tū le.","vi":"Mùa đông đến, cây cối trên núi đều trụi lá."},{"type":"compound","zh":"他才三十岁，头发就快秃了，因为工作压力实在太大。","pinyin":"Tā cái sānshí suì, tóufa jiù kuài tū le, yīnwèi gōngzuò yālì shízài tài dà.","vi":"Anh ấy mới ba mươi tuổi mà tóc đã sắp hói, vì áp lực công việc thực sự quá lớn."}],"related":[{"hanzi":"秃头","pinyin":"tūtóu","vi":"đầu hói"},{"hanzi":"光秃秃","pinyin":"guāngtūtū","vi":"trơ trụi"},{"hanzi":"秃顶","pinyin":"tūdǐng","vi":"hói đỉnh đầu"},{"hanzi":"头发","pinyin":"tóufa","vi":"tóc"}],"traditional":"禿"},{"id":"凸","hanzi":"凸","pinyin":"tū","meaning_vi":"lồi lên, nhô ra","explanation":"Đối nghĩa với 凹 (lõm).","hsk_level":6,"tags":["tinh-tu","dong-tu"],"image":"⛰️","examples":[{"type":"basic","zh":"镜面中间有点凸。","pinyin":"Jìng miàn zhōngjiān yǒudiǎn tū.","vi":"Giữa mặt gương hơi lồi lên."},{"type":"simple","zh":"他瘦得连锁骨都凸出来了。","pinyin":"Tā shòu de liánsuǒ gǔ dōu tūchū lái le.","vi":"Anh ấy gầy đến mức xương quai xanh cũng lồi ra."},{"type":"compound","zh":"这块木板中间凸了起来，所以桌面一直放不平。","pinyin":"Zhè kuài mùbǎn zhōngjiān tūle qǐlái, suǒyǐ zhuōmiàn yìzhí fàng bùpíng.","vi":"Tấm ván này ở giữa bị nhô lên, nên mặt bàn mãi không đặt phẳng được."}],"related":[{"hanzi":"凹","pinyin":"āo","vi":"lõm"},{"hanzi":"凹凸","pinyin":"āotū","vi":"lồi lõm"},{"hanzi":"突出","pinyin":"tūchū","vi":"nhô ra"},{"hanzi":"凸起","pinyin":"tūqǐ","vi":"nhô lên"}]},{"id":"突飞猛进","hanzi":"突飞猛进","pinyin":"tūfēi-měngjìn","meaning_vi":"tiến bộ vượt bậc, phát triển thần tốc","explanation":"突飞 (đột phi – bay vọt) + 猛进 (mãnh tiến – tiến mạnh) → tiến bộ, phát triển cực kỳ nhanh.","hsk_level":6,"tags":["thanh-ngu"],"image":"🚀","examples":[{"type":"basic","zh":"他的汉语突飞猛进。","pinyin":"Tā de Hànyǔ tūfēiměngjìn.","vi":"Tiếng Trung của anh ấy tiến bộ vượt bậc."},{"type":"simple","zh":"近年来人工智能技术突飞猛进。","pinyin":"Jìnniánlái réngōngzhìnéng jìshù tūfēiměngjìn.","vi":"Những năm gần đây công nghệ trí tuệ nhân tạo phát triển thần tốc."},{"type":"compound","zh":"自从请了家教，她的数学成绩就突飞猛进。","pinyin":"Zìcóng qǐngle jiājiào, tā de shùxué chéngjì jiù tūfēiměngjìn.","vi":"Từ khi thuê gia sư, điểm toán của cô bé tiến bộ vượt bậc."}],"related":[{"hanzi":"日新月异","pinyin":"rìxīnyuèyì","vi":"thay đổi từng ngày"},{"hanzi":"飞速","pinyin":"fēisù","vi":"thần tốc"},{"hanzi":"进步","pinyin":"jìnbù","vi":"tiến bộ"},{"hanzi":"停滞不前","pinyin":"tíngzhìbùqián","vi":"đình trệ không tiến"}],"traditional":"突飛猛進"},{"id":"吞吞吐吐","hanzi":"吞吞吐吐","pinyin":"tūntūntǔtǔ","meaning_vi":"ấp a ấp úng, nói năng ngập ngừng","explanation":"Từ láy AABB.","hsk_level":6,"tags":["tinh-tu","giao-tiep"],"image":"🤐","examples":[{"type":"basic","zh":"他说话吞吞吐吐。","pinyin":"Tā shuōhuà tūntūntǔtǔ.","vi":"Anh ta nói năng ấp a ấp úng."},{"type":"simple","zh":"问到钱的去向，他就吞吞吐吐的。","pinyin":"Wèn dào qián de qùxiàng, tā jiù tūntūntǔtǔ de.","vi":"Hỏi tiền đi đâu là anh ta ấp a ấp úng."},{"type":"compound","zh":"有话就直说，别这么吞吞吐吐的，我又不会怪你。","pinyin":"Yǒu huà jiù zhíshuō, bié zhème tūntūntǔtǔ de, wǒ yòu bú huì guài nǐ.","vi":"Có gì thì cứ nói thẳng, đừng ấp úng thế, tôi có trách cậu đâu."}],"related":[{"hanzi":"支支吾吾","pinyin":"zhīzhīwúwú","vi":"ấp úng"},{"hanzi":"含糊其辞","pinyin":"hánhúqící","vi":"nói mập mờ"},{"hanzi":"犹豫","pinyin":"yóuyù","vi":"do dự"},{"hanzi":"直截了当","pinyin":"zhíjiéliǎodàng","vi":"thẳng thắn dứt khoát"}]},{"id":"塔","hanzi":"塔","pinyin":"tǎ","meaning_vi":"ngôi tháp","explanation":"Bộ thổ 土 + 荅.","hsk_level":6,"tags":["danh-tu","van-hoa","dia-diem"],"image":"🗼","examples":[{"type":"basic","zh":"山顶有座古塔。","pinyin":"Shāndǐng yǒu zuò Gǔtǎ.","vi":"Trên đỉnh núi có một ngôi tháp cổ."},{"type":"simple","zh":"我们爬上塔顶俯瞰整座城市。","pinyin":"Wǒmen páshàng tǎ dǐng fǔkàn zhěng zuò chéngshì.","vi":"Chúng tôi leo lên đỉnh tháp nhìn xuống toàn thành phố."},{"type":"compound","zh":"这座塔虽然建于唐朝，但是至今保存得非常完整。","pinyin":"Zhè zuò tǎ suīrán jiàn yú Tángcháo, dànshì zhìjīn bǎocún de fēicháng wánzhěng.","vi":"Ngôi tháp này tuy được xây từ thời Đường, nhưng đến nay vẫn được bảo tồn rất nguyên vẹn."}],"related":[{"hanzi":"宝塔","pinyin":"bǎotǎ","vi":"bảo tháp"},{"hanzi":"灯塔","pinyin":"dēngtǎ","vi":"hải đăng"},{"hanzi":"铁塔","pinyin":"tiětǎ","vi":"tháp sắt"},{"hanzi":"金字塔","pinyin":"Jīnzìtǎ","vi":"kim tự tháp"}]},{"id":"坦荡","hanzi":"坦荡","pinyin":"tǎndàng","meaning_vi":"ngay thẳng, quang minh lỗi lạc","explanation":"坦 (bằng phẳng) + 荡 (rộng lớn).","hsk_level":6,"tags":["tinh-tu","con-nguoi"],"image":"☀️","examples":[{"type":"basic","zh":"他心胸坦荡。","pinyin":"Tā xīnxiōng tǎndàng.","vi":"Anh ấy có tấm lòng quang minh lỗi lạc."},{"type":"simple","zh":"做人要光明磊落，心地坦荡。","pinyin":"Zuòrén yào guāngmínglěiluò, xīndì tǎndàng.","vi":"Làm người phải quang minh chính đại, lòng dạ ngay thẳng."},{"type":"compound","zh":"因为他一生坦荡，所以面对流言毫不在意。","pinyin":"Yīnwèi tā yìshēng tǎndàng, suǒyǐ miànduì liúyán háobú zàiyì.","vi":"Vì cả đời ông sống ngay thẳng nên trước lời đồn đại chẳng hề bận tâm."}],"related":[{"hanzi":"坦率","pinyin":"tǎnshuài","vi":"thẳng thắn"},{"hanzi":"光明磊落","pinyin":"guāngmínglěiluò","vi":"quang minh lỗi lạc"},{"hanzi":"胸怀","pinyin":"xiōnghuái","vi":"tấm lòng"},{"hanzi":"心胸开阔","pinyin":"xīnxiōngkāikuò","vi":"lòng dạ rộng mở"}],"traditional":"坦蕩"},{"id":"倘使","hanzi":"倘使","pinyin":"tǎngshǐ","meaning_vi":"giả sử, nếu như","explanation":"倘 + 使. Đồng nghĩa với 倘若 / 如果.","hsk_level":6,"tags":["lien-tu"],"image":"❓","examples":[{"type":"basic","zh":"倘使下雨就改期。","pinyin":"Tǎngshǐ xiàyǔ jiù gǎiqī.","vi":"Giả sử trời mưa thì đổi ngày."},{"type":"simple","zh":"倘使你早来一步，就能见到他了。","pinyin":"Tǎngshǐ nǐ zǎolái yí bù, jiù néng jiàndào tā le.","vi":"Nếu như anh đến sớm một bước thì đã gặp được anh ấy rồi."},{"type":"compound","zh":"倘使当初听了老师的劝告，他也不至于落到今天这个地步。","pinyin":"Tǎngshǐ dāngchū tīngle lǎoshī de quàngào, tā yě bú zhìyú luò dào jīntiān zhè ge dìbù.","vi":"Giả sử lúc đầu nghe lời khuyên của thầy, cậu ta cũng không đến nỗi rơi vào tình cảnh hôm nay."}],"related":[{"hanzi":"倘若","pinyin":"tǎngruò","vi":"nếu như"},{"hanzi":"假如","pinyin":"jiǎrú","vi":"giả như"},{"hanzi":"如果","pinyin":"rúguǒ","vi":"nếu"},{"hanzi":"假使","pinyin":"jiǎshǐ","vi":"giả sử"}]},{"id":"讨好","hanzi":"讨好","pinyin":"tǎohǎo","meaning_vi":"lấy lòng, nịnh nọt","explanation":"讨 (thảo – xin, cầu) + 好 (hảo – cảm tình) → cầu cảm tình người khác, lấy lòng. Cụm: 吃力不讨好 (vất vả mà chẳng được gì).","hsk_level":6,"tags":["dong-tu","giao-tiep"],"image":"😊","examples":[{"type":"basic","zh":"他总爱讨好领导。","pinyin":"Tā zǒng ài tǎohǎo lǐngdǎo.","vi":"Anh ta luôn thích nịnh nọt lãnh đạo."},{"type":"simple","zh":"小狗摇着尾巴讨好主人。","pinyin":"Xiǎogǒu yáozhe wěiba tǎohǎo zhǔrén.","vi":"Chú chó vẫy đuôi lấy lòng chủ."},{"type":"compound","zh":"你想讨好所有人，结果往往谁也没讨好。","pinyin":"Nǐ xiǎng tǎohǎo suǒyǒurén, jiéguǒ wǎngwǎng shéi yě méi tǎohǎo.","vi":"Bạn muốn lấy lòng tất cả mọi người, kết quả thường là chẳng làm vừa lòng ai."}],"related":[{"hanzi":"巴结","pinyin":"bājie","vi":"nịnh bợ"},{"hanzi":"拍马屁","pinyin":"pāimǎpì","vi":"nịnh hót"},{"hanzi":"奉承","pinyin":"fèngcheng","vi":"tâng bốc"},{"hanzi":"吃力不讨好","pinyin":"chīlì bù tǎohǎo","vi":"mất công mà chẳng được lòng"}],"traditional":"討好"},{"id":"体积","hanzi":"体积","pinyin":"tǐjī","meaning_vi":"thể tích","explanation":"体 + 积 (tích lũy).","hsk_level":6,"tags":["danh-tu","khoa-hoc","so-luong"],"image":"🧊","examples":[{"type":"basic","zh":"这个箱子体积很大。","pinyin":"Zhè ge xiāngzi tǐjī hěn dà.","vi":"Cái thùng này thể tích rất lớn."},{"type":"simple","zh":"冰融化成水后，体积会变小。","pinyin":"Bīng rónghuà chéng shuǐ hòu, tǐjī huì biàn xiǎo.","vi":"Băng tan thành nước thì thể tích sẽ nhỏ lại."},{"type":"compound","zh":"这台冰箱虽然体积小，但是容量一点也不小。","pinyin":"Zhè tái bīngxiāng suīrán tǐjī xiǎo, dànshì róngliàng yìdiǎn yě bù xiǎo.","vi":"Chiếc tủ lạnh này tuy kích thước nhỏ, nhưng dung tích không hề nhỏ."}],"related":[{"hanzi":"面积","pinyin":"miànjī","vi":"diện tích"},{"hanzi":"容积","pinyin":"róngjī","vi":"dung tích"},{"hanzi":"重量","pinyin":"zhòngliàng","vi":"trọng lượng"},{"hanzi":"立方米","pinyin":"lìfāngmǐ","vi":"mét khối"}],"traditional":"體積"},{"id":"体贴","hanzi":"体贴","pinyin":"tǐtiē","meaning_vi":"chu đáo, ân cần, biết quan tâm","explanation":"体 + 贴 (sát gần).","hsk_level":6,"tags":["tinh-tu","con-nguoi"],"image":"🤗","examples":[{"type":"basic","zh":"她对丈夫很体贴。","pinyin":"Tā duì zhàngfu hěn tǐtiē.","vi":"Cô ấy rất chu đáo với chồng."},{"type":"simple","zh":"护士体贴地给老人盖好了被子。","pinyin":"Hùshi tǐtiē de gěi lǎorén gài hǎole bèizi.","vi":"Y tá ân cần đắp chăn cho cụ già."},{"type":"compound","zh":"他不但工作能干，而且对家人特别体贴。","pinyin":"Tā búdàn gōngzuò nénggàn, érqiě duì jiārén tèbié tǐtiē.","vi":"Anh ấy không những giỏi việc mà còn đặc biệt biết quan tâm người nhà."}],"related":[{"hanzi":"关心","pinyin":"guānxīn","vi":"quan tâm"},{"hanzi":"体贴入微","pinyin":"tǐtiērùwēi","vi":"quan tâm chu đáo từng li"},{"hanzi":"照顾","pinyin":"zhàogù","vi":"chăm sóc"},{"hanzi":"温柔","pinyin":"wēnróu","vi":"dịu dàng"}],"traditional":"體貼"},{"id":"体统","hanzi":"体统","pinyin":"tǐtǒng","meaning_vi":"thể thống, quy củ","explanation":"体 + 统 (hệ thống). Cụm: 成何体统 (còn ra thể thống gì nữa).","hsk_level":6,"tags":["danh-tu"],"image":"⚖️","examples":[{"type":"basic","zh":"这样太不成体统了。","pinyin":"Zhèyàng tài bùchéng tǐtǒng le.","vi":"Thế này thật chẳng ra thể thống gì."},{"type":"simple","zh":"大庭广众之下吵架，成何体统？","pinyin":"Dà tíng guǎng zhòng zhīxià chǎojià, chéng hé tǐtǒng?","vi":"Cãi nhau giữa chốn đông người thì còn ra thể thống gì?"},{"type":"compound","zh":"他穿着拖鞋就去参加婚礼，大家都觉得不成体统。","pinyin":"Tā chuānzhe tuōxié jiù qù cānjiā hūnlǐ, dàjiā dōu juéde bùchéng tǐtǒng.","vi":"Anh ta đi dép lê đến dự đám cưới, ai cũng thấy chẳng ra thể thống gì."}],"related":[{"hanzi":"规矩","pinyin":"guīju","vi":"quy củ"},{"hanzi":"不成体统","pinyin":"bùchéngtǐtǒng","vi":"chẳng ra thể thống gì"},{"hanzi":"礼节","pinyin":"lǐjié","vi":"lễ tiết"},{"hanzi":"体面","pinyin":"tǐmiàn","vi":"thể diện"}],"traditional":"體統"},{"id":"体质","hanzi":"体质","pinyin":"tǐzhì","meaning_vi":"thể chất, cơ địa","explanation":"体 + 质 (bản chất).","hsk_level":6,"tags":["danh-tu","suc-khoe"],"image":"💪","examples":[{"type":"basic","zh":"他体质比较弱。","pinyin":"Tā tǐzhì bǐjiào ruò.","vi":"Thể chất của anh ấy khá yếu."},{"type":"simple","zh":"每天跑步能有效增强体质。","pinyin":"Měitiān pǎobù néng yǒuxiào zēngqiáng tǐzhì.","vi":"Chạy bộ mỗi ngày có thể tăng cường thể chất hiệu quả."},{"type":"compound","zh":"因为她是过敏体质，所以不敢随便吃海鲜。","pinyin":"Yīnwèi tā shì guòmǐn tǐzhì, suǒyǐ bù gǎn suíbiàn chī hǎixiān.","vi":"Vì cô ấy có cơ địa dị ứng nên không dám tùy tiện ăn hải sản."}],"related":[{"hanzi":"体格","pinyin":"tǐgé","vi":"thể chất vóc dáng"},{"hanzi":"体力","pinyin":"tǐlì","vi":"thể lực"},{"hanzi":"健康","pinyin":"jiànkāng","vi":"sức khỏe"},{"hanzi":"增强体质","pinyin":"zēngqiángtǐzhì","vi":"tăng cường thể chất"}],"traditional":"體質"},{"id":"挺身而出","hanzi":"挺身而出","pinyin":"tǐngshēn-érchū","meaning_vi":"đứng ra gánh vác, dũng cảm xung phong","explanation":"挺身 (đĩnh thân – ưỡn thẳng người) + 而出 (bước ra) → dũng cảm đứng ra đối mặt khó khăn, nguy hiểm.","hsk_level":6,"tags":["thanh-ngu"],"image":"🦸","examples":[{"type":"basic","zh":"他挺身而出救人。","pinyin":"Tā tǐng shēn ér chū jiùrén.","vi":"Anh ấy dũng cảm đứng ra cứu người."},{"type":"simple","zh":"看到小偷行窃，一位大学生挺身而出。","pinyin":"Kàndào xiǎotōu xíngqiè, yí wèi dàxuéshēng tǐng shēn ér chū.","vi":"Thấy kẻ trộm đang ra tay, một sinh viên đã dũng cảm xông ra."},{"type":"compound","zh":"每当团队遇到难题，她总会第一个挺身而出。","pinyin":"Měidāng tuánduì yùdào nántí, tā zǒng huì dìyī gè tǐng shēn ér chū.","vi":"Mỗi khi nhóm gặp khó khăn, cô ấy luôn là người đầu tiên đứng ra gánh vác."}],"related":[{"hanzi":"见义勇为","pinyin":"jiànyìyǒngwéi","vi":"thấy việc nghĩa dũng cảm làm"},{"hanzi":"奋不顾身","pinyin":"fènbúgùshēn","vi":"quên mình xông lên"},{"hanzi":"勇敢","pinyin":"yǒnggǎn","vi":"dũng cảm"},{"hanzi":"袖手旁观","pinyin":"xiùshǒupángguān","vi":"khoanh tay đứng nhìn"}]},{"id":"统筹","hanzi":"统筹","pinyin":"tǒngchóu","meaning_vi":"trù tính tổng thể","explanation":"统 + 筹 (tính toán).","hsk_level":6,"tags":["dong-tu","cong-viec"],"image":"📊","examples":[{"type":"basic","zh":"这件事由他统筹。","pinyin":"Zhè jiàn shìyóu tā tǒngchóu.","vi":"Việc này do anh ấy trù tính tổng thể."},{"type":"simple","zh":"市政府统筹安排了全市的防汛工作。","pinyin":"Shìzhèngfǔ tǒngchóu ānpáile quánshì de fángxùn gōngzuò.","vi":"Chính quyền thành phố đã trù tính sắp xếp tổng thể công tác phòng lũ toàn thành phố."},{"type":"compound","zh":"只有把时间统筹好，才能同时兼顾学习和工作。","pinyin":"Zhǐyǒu bǎ shíjiān tǒngchóu hǎo, cáinéng tóngshí jiāngù xuéxí hé gōngzuò.","vi":"Chỉ khi sắp xếp thời gian tổng thể hợp lý mới có thể cùng lúc lo cả việc học và việc làm."}],"related":[{"hanzi":"统筹兼顾","pinyin":"tǒngchóujiāngù","vi":"tính toán tổng thể"},{"hanzi":"规划","pinyin":"guīhuà","vi":"quy hoạch"},{"hanzi":"安排","pinyin":"ānpái","vi":"sắp xếp"},{"hanzi":"协调","pinyin":"xiétiáo","vi":"điều phối"}],"traditional":"統籌"},{"id":"统统","hanzi":"统统","pinyin":"tǒngtǒng","meaning_vi":"tất cả, hết thảy (khẩu ngữ)","explanation":"Lặp lại chữ 统.","hsk_level":6,"tags":["pho-tu"],"image":"💯","examples":[{"type":"basic","zh":"统统拿走吧。","pinyin":"Tǒngtǒng názǒu ba.","vi":"Cầm đi hết đi."},{"type":"simple","zh":"他把旧衣服统统捐给了灾区。","pinyin":"Tā bǎ jiù yīfu tǒngtǒng juāngěile zāiqū.","vi":"Anh ấy quyên tặng hết thảy quần áo cũ cho vùng bị thiên tai."},{"type":"compound","zh":"只要是过期的食品，就统统扔掉，一样也别留。","pinyin":"Zhǐ yàoshì guòqī de shípǐn, jiù tǒngtǒng rēngdiào, yíyàng yě bié liú.","vi":"Chỉ cần là thực phẩm hết hạn thì vứt hết, đừng giữ lại món nào."}],"related":[{"hanzi":"全部","pinyin":"quánbù","vi":"toàn bộ"},{"hanzi":"都","pinyin":"dōu","vi":"đều"},{"hanzi":"一律","pinyin":"yílǜ","vi":"nhất loạt"},{"hanzi":"所有","pinyin":"suǒyǒu","vi":"tất cả"}],"traditional":"統統"},{"id":"土壤","hanzi":"土壤","pinyin":"tǔrǎng","meaning_vi":"đất đai, thổ nhưỡng","explanation":"土 (đất) + 壤 (đất xốp).","hsk_level":6,"tags":["danh-tu","thien-nhien","khoa-hoc"],"image":"🌱","examples":[{"type":"basic","zh":"这里的土壤很肥沃。","pinyin":"Zhèlǐ de tǔrǎng hěn féiwò.","vi":"Đất đai ở đây rất màu mỡ."},{"type":"simple","zh":"化肥用得太多会让土壤变硬。","pinyin":"Huàféi yòng de tài duō huì ràng tǔrǎng biànyìng.","vi":"Dùng quá nhiều phân hóa học sẽ khiến đất bị chai cứng."},{"type":"compound","zh":"因为这片土壤偏酸，所以特别适合种茶树。","pinyin":"Yīnwèi zhè piàn tǔrǎng piān suān, suǒyǐ tèbié shìhé zhòng cháshù.","vi":"Vì vùng đất này hơi chua nên đặc biệt thích hợp trồng chè."}],"related":[{"hanzi":"泥土","pinyin":"nítǔ","vi":"bùn đất"},{"hanzi":"土地","pinyin":"tǔdì","vi":"đất đai"},{"hanzi":"肥沃","pinyin":"féiwò","vi":"màu mỡ"},{"hanzi":"土壤污染","pinyin":"tǔrǎngwūrǎn","vi":"ô nhiễm đất"}]},{"id":"土生土长","hanzi":"土生土长","pinyin":"tǔshēng-tǔzhǎng","meaning_vi":"sinh ra và lớn lên tại bản địa","explanation":"土 (thổ – đất) 生 (sinh) 土 长 (trưởng – lớn lên) → sinh ra và lớn lên tại địa phương. Cụm: 土生土长的北京人.","hsk_level":6,"tags":["thanh-ngu"],"image":"🏡","examples":[{"type":"basic","zh":"我是土生土长的北京人。","pinyin":"Wǒ shì tǔshēngtǔzhǎng de Běijīngrén.","vi":"Tôi là người Bắc Kinh chính gốc."},{"type":"simple","zh":"这种水果是本地土生土长的品种。","pinyin":"Zhè zhǒng shuǐguǒ shì běndì tǔshēngtǔzhǎng de pǐnzhǒng.","vi":"Loại trái cây này là giống bản địa sinh trưởng tại chỗ."},{"type":"compound","zh":"他在这个小镇土生土长，所以每条小巷都熟悉得很。","pinyin":"Tā zài zhè ge xiǎozhèn tǔshēngtǔzhǎng, suǒyǐ měi tiáo xiǎoxiàng dōu shúxī de hěn.","vi":"Anh ấy sinh ra và lớn lên ở thị trấn nhỏ này nên con hẻm nào cũng rất thông thuộc."}],"related":[{"hanzi":"本地","pinyin":"běndì","vi":"bản địa"},{"hanzi":"本地人","pinyin":"běndìrén","vi":"người bản xứ"},{"hanzi":"家乡","pinyin":"jiāxiāng","vi":"quê hương"},{"hanzi":"外地人","pinyin":"wàidìrén","vi":"người nơi khác"}],"traditional":"土生土長"},{"id":"外宾","hanzi":"外宾","pinyin":"wàibīn","meaning_vi":"khách nước ngoài (ngoại giao)","explanation":"外 (nước ngoài) + 宾 (khách quý).","hsk_level":6,"tags":["danh-tu","con-nguoi","du-lich"],"image":"🌍","examples":[{"type":"basic","zh":"今天要接待外宾。","pinyin":"Jīntiān yào jiēdài wàibīn.","vi":"Hôm nay phải tiếp đón khách nước ngoài."},{"type":"simple","zh":"校长陪同外宾参观了实验室。","pinyin":"Xiàozhǎng péitóng wàibīn cānguānle shíyànshì.","vi":"Hiệu trưởng cùng khách nước ngoài tham quan phòng thí nghiệm."},{"type":"compound","zh":"因为下午有外宾来访，所以大家都穿上了正装。","pinyin":"Yīnwèi xiàwǔ yǒu wàibīn láifǎng, suǒyǐ dàjiā dōu chuānshàngle zhèngzhuāng.","vi":"Vì buổi chiều có khách nước ngoài đến thăm nên mọi người đều mặc trang phục lịch sự."}],"related":[{"hanzi":"外国人","pinyin":"wàiguórén","vi":"người nước ngoài"},{"hanzi":"贵宾","pinyin":"guìbīn","vi":"khách quý"},{"hanzi":"来宾","pinyin":"láibīn","vi":"khách mời"},{"hanzi":"接待","pinyin":"jiēdài","vi":"tiếp đón"}],"traditional":"外賓"},{"id":"外行","hanzi":"外行","pinyin":"wàiháng","meaning_vi":"người ngoại đạo, không chuyên","explanation":"外 + 行 (đọc háng - ngành nghề). Đối nghĩa với 内行.","hsk_level":6,"tags":["danh-tu","con-nguoi"],"image":"🤷","examples":[{"type":"basic","zh":"我对股票是外行。","pinyin":"Wǒ duì gǔpiào shì wàiháng.","vi":"Tôi là người ngoại đạo về cổ phiếu."},{"type":"simple","zh":"他一开口就说外行话，被同行笑了。","pinyin":"Tā yì kāikǒu jiù shuō wàihánghuà, bèi tóngháng xiào le.","vi":"Anh ta vừa mở miệng đã nói lời không chuyên, bị người trong nghề cười cho."},{"type":"compound","zh":"虽然我是外行，但是也能看出这幅画画得不错。","pinyin":"Suīrán wǒ shì wàiháng, dànshì yě néng kànchū zhè fú huàhuà de búcuò.","vi":"Tuy tôi là người ngoại đạo, nhưng cũng nhìn ra bức tranh này vẽ khá đẹp."}],"related":[{"hanzi":"内行","pinyin":"nèiháng","vi":"người trong nghề"},{"hanzi":"行家","pinyin":"hángjia","vi":"chuyên gia"},{"hanzi":"门外汉","pinyin":"ménwàihàn","vi":"người ngoại đạo"},{"hanzi":"业余","pinyin":"yèyú","vi":"nghiệp dư"}]},{"id":"外快","hanzi":"外快","pinyin":"wàikuài","meaning_vi":"thu nhập thêm, tiền kiếm thêm ngoài lương","explanation":"外 (ngoại – bên ngoài) + 快 (khoái) → khẩu ngữ: khoản thu nhập ngoài lương chính. Cụm: 赚外快, 挣外快.","hsk_level":6,"tags":["danh-tu","tien-te","cong-viec"],"image":"💵","examples":[{"type":"basic","zh":"他周末赚点外快。","pinyin":"Tā zhōumò zhuàn diǎn wàikuài.","vi":"Cuối tuần anh ấy kiếm thêm chút tiền ngoài lương."},{"type":"simple","zh":"不少大学生靠做家教挣外快。","pinyin":"Bùshǎo dàxuéshēng kào zuò jiājiào zhèng wàikuài.","vi":"Không ít sinh viên kiếm thêm thu nhập nhờ làm gia sư."},{"type":"compound","zh":"他白天上班，晚上开网约车，所以外快比工资还多。","pinyin":"Tā báitiān shàngbān, wǎnshang kāi wǎngyuēchē, suǒyǐ wàikuài bǐ gōngzī hái duō.","vi":"Ban ngày anh ấy đi làm, buổi tối chạy xe công nghệ, nên tiền làm thêm còn nhiều hơn lương."}],"related":[{"hanzi":"兼职","pinyin":"jiānzhí","vi":"làm thêm"},{"hanzi":"收入","pinyin":"shōurù","vi":"thu nhập"},{"hanzi":"工资","pinyin":"gōngzī","vi":"tiền lương"},{"hanzi":"赚钱","pinyin":"zhuànqián","vi":"kiếm tiền"}]},{"id":"外援","hanzi":"外援","pinyin":"wàiyuán","meaning_vi":"viện trợ nước ngoài; ngoại binh (thể thao)","explanation":"外 + 援 (giúp đỡ).","hsk_level":6,"tags":["danh-tu","the-thao","xa-hoi"],"image":"⚽","examples":[{"type":"basic","zh":"球队请了两名外援。","pinyin":"Qiúduì qǐngle liǎng míng wàiyuán.","vi":"Đội bóng đã mời hai ngoại binh."},{"type":"simple","zh":"这个国家的重建离不开外援。","pinyin":"Zhè ge guójiā de chóngjiàn líbukāi wàiyuán.","vi":"Công cuộc tái thiết đất nước này không thể thiếu viện trợ nước ngoài."},{"type":"compound","zh":"虽然那名外援技术出色，但是他还没融入球队。","pinyin":"Suīrán nà míng wàiyuán jìshù chūsè, dànshì tā hái méi róngrù qiúduì.","vi":"Tuy cầu thủ ngoại binh đó kỹ thuật xuất sắc, nhưng anh ta vẫn chưa hòa nhập với đội."}],"related":[{"hanzi":"援助","pinyin":"yuánzhù","vi":"viện trợ"},{"hanzi":"支援","pinyin":"zhīyuán","vi":"chi viện"},{"hanzi":"外资","pinyin":"wàizī","vi":"vốn nước ngoài"},{"hanzi":"外籍球员","pinyin":"wàijíqiúyuán","vi":"cầu thủ ngoại"}]},{"id":"万分","hanzi":"万分","pinyin":"wànfēn","meaning_vi":"vô cùng, hết sức","explanation":"万 (mười nghìn) + 分 (phần). Cụm: 万分感谢.","hsk_level":6,"tags":["pho-tu"],"image":"🙏","examples":[{"type":"basic","zh":"我感激万分。","pinyin":"Wǒ gǎnjī wànfēn.","vi":"Tôi vô cùng cảm kích."},{"type":"simple","zh":"听到儿子获救的消息，她激动万分。","pinyin":"Tīngdào érzi huòjiù de xiāoxi, tā jīdòng wànfēn.","vi":"Nghe tin con trai được cứu, bà ấy xúc động vô cùng."},{"type":"compound","zh":"他虽然万分不舍，但是还是把小狗送给了别人。","pinyin":"Tā suīrán wànfēn bùshě, dànshì háishi bǎ xiǎogǒu sònggěile biérén.","vi":"Tuy vô cùng lưu luyến, nhưng cậu ấy vẫn đem chú chó cho người khác."}],"related":[{"hanzi":"十分","pinyin":"shífēn","vi":"vô cùng"},{"hanzi":"非常","pinyin":"fēicháng","vi":"rất"},{"hanzi":"万分感谢","pinyin":"wànfēngǎnxiè","vi":"vô cùng cảm ơn"},{"hanzi":"极其","pinyin":"jíqí","vi":"cực kỳ"}],"traditional":"萬分"},{"id":"万古长青","hanzi":"万古长青","pinyin":"wàngǔ-chángqīng","meaning_vi":"xanh tươi mãi mãi, trường tồn vĩnh cửu","explanation":"万古 (vạn cổ – muôn đời) + 长青 (trường thanh – xanh mãi) → xanh tươi muôn đời; ví tình hữu nghị, tinh thần trường tồn.","hsk_level":6,"tags":["thanh-ngu"],"image":"🌲","examples":[{"type":"basic","zh":"友谊万古长青。","pinyin":"Yǒuyì wàngǔchángqīng.","vi":"Tình hữu nghị xanh tươi mãi mãi."},{"type":"simple","zh":"祝两国人民的友谊万古长青！","pinyin":"Zhù liǎngguó rénmín de yǒuyì wàngǔchángqīng!","vi":"Chúc tình hữu nghị giữa nhân dân hai nước trường tồn mãi mãi!"},{"type":"compound","zh":"英雄虽然已经离去，但是他们的精神万古长青。","pinyin":"Yīngxióng suīrán yǐjīng líqù, dànshì tāmen de jīngshén wàngǔchángqīng.","vi":"Các anh hùng tuy đã ra đi, nhưng tinh thần của họ trường tồn vĩnh cửu."}],"related":[{"hanzi":"永垂不朽","pinyin":"yǒngchuíbùxiǔ","vi":"đời đời bất diệt"},{"hanzi":"永恒","pinyin":"yǒnghéng","vi":"vĩnh hằng"},{"hanzi":"长青","pinyin":"chángqīng","vi":"xanh mãi"},{"hanzi":"天长地久","pinyin":"tiānchángdìjiǔ","vi":"thiên trường địa cửu"}],"traditional":"萬古長青"},{"id":"万无一失","hanzi":"万无一失","pinyin":"wànwú-yìshī","meaning_vi":"vạn lần không sai một, chắc chắn an toàn tuyệt đối","explanation":"Vạn lần không sai một → chắc chắn tuyệt đối, không chút sơ suất.","hsk_level":6,"tags":["thanh-ngu"],"image":"💯","examples":[{"type":"basic","zh":"这样做万无一失。","pinyin":"Zhèyàng zuò wànwúyìshī.","vi":"Làm như vậy là chắc chắn tuyệt đối."},{"type":"simple","zh":"出发前他把行李检查了三遍，确保万无一失。","pinyin":"Chūfā qián tā bǎ xíngli jiǎnchále sān biàn, quèbǎo wànwúyìshī.","vi":"Trước khi xuất phát anh ấy kiểm tra hành lý ba lần, để đảm bảo không sai sót gì."},{"type":"compound","zh":"即使计划看起来万无一失，我们也要准备一个备用方案。","pinyin":"Jíshǐ jìhuà kànqǐlái wànwúyìshī, wǒmen yě yào zhǔnbèi yí gè bèiyòng fāng'àn.","vi":"Dù kế hoạch trông có vẻ an toàn tuyệt đối, chúng ta vẫn phải chuẩn bị một phương án dự phòng."}],"related":[{"hanzi":"十拿九稳","pinyin":"shínájiǔwěn","vi":"chắc chín phần mười"},{"hanzi":"稳妥","pinyin":"wěntuǒ","vi":"ổn thỏa"},{"hanzi":"保险","pinyin":"bǎoxiǎn","vi":"chắc chắn an toàn"},{"hanzi":"万一","pinyin":"wànyī","vi":"lỡ như"}],"traditional":"萬無一失"},{"id":"万众一心","hanzi":"万众一心","pinyin":"wànzhòng-yìxīn","meaning_vi":"vạn người như một, đồng lòng nhất trí","explanation":"万众 (vạn chúng – muôn người) + 一心 (nhất tâm – một lòng) → muôn người một lòng, đồng tâm hiệp lực.","hsk_level":6,"tags":["thanh-ngu"],"image":"🤝","examples":[{"type":"basic","zh":"全国人民万众一心。","pinyin":"Quánguó rénmín wànzhòngyìxīn.","vi":"Nhân dân cả nước vạn người như một."},{"type":"simple","zh":"洪水面前，全城百姓万众一心抗灾。","pinyin":"Hóngshuǐ miànqián, quánchéng bǎixìng wànzhòngyìxīn kàngzāi.","vi":"Trước cơn lũ, người dân cả thành phố đồng lòng chống thiên tai."},{"type":"compound","zh":"只要我们万众一心，就一定能战胜这场疫情。","pinyin":"Zhǐyào wǒmen wànzhòngyìxīn, jiù yídìng néng zhànshèng zhè chǎng yìqíng.","vi":"Chỉ cần chúng ta vạn người như một thì nhất định sẽ chiến thắng dịch bệnh này."}],"related":[{"hanzi":"同心协力","pinyin":"tóngxīnxiélì","vi":"đồng tâm hiệp lực"},{"hanzi":"齐心协力","pinyin":"qíxīnxiélì","vi":"đồng lòng hợp sức"},{"hanzi":"团结一致","pinyin":"tuánjiéyízhì","vi":"đoàn kết nhất trí"},{"hanzi":"众志成城","pinyin":"zhòngzhìchéngchéng","vi":"đồng lòng thành sức mạnh"}],"traditional":"萬眾一心"},{"id":"望尘莫及","hanzi":"望尘莫及","pinyin":"wàngchén-mòjí","meaning_vi":"theo không kịp, kém xa một trời một vực","explanation":"Nhìn bụi xe ngựa người trước mà không đuổi kịp → kém xa, không theo kịp; hay dùng khiêm tốn: 我望尘莫及.","hsk_level":6,"tags":["thanh-ngu"],"image":"🏃","examples":[{"type":"basic","zh":"他的速度我望尘莫及。","pinyin":"Tā de sùdù wǒ wàngchénmòjí.","vi":"Tốc độ của anh ấy tôi theo không kịp."},{"type":"simple","zh":"她的书法水平让同学们望尘莫及。","pinyin":"Tā de shūfǎ shuǐpíng ràng tóngxuémen wàngchénmòjí.","vi":"Trình độ thư pháp của cô ấy khiến các bạn cùng lớp kém xa."},{"type":"compound","zh":"他不但精通五门外语，而且记忆力惊人，我实在望尘莫及。","pinyin":"Tā búdàn jīngtōng wǔ mén wàiyǔ, érqiě jìyìlì jīngrén, wǒ shízài wàngchénmòjí.","vi":"Anh ấy không những thông thạo năm ngoại ngữ mà trí nhớ còn kinh người, tôi thật sự kém xa."}],"related":[{"hanzi":"望其项背","pinyin":"wàngqíxiàngbèi","vi":"sánh kịp được"},{"hanzi":"自愧不如","pinyin":"zìkuìbùrú","vi":"tự thấy không bằng"},{"hanzi":"遥遥领先","pinyin":"yáoyáolǐngxiān","vi":"dẫn trước xa"},{"hanzi":"赶不上","pinyin":"gǎnbushàng","vi":"đuổi không kịp"}],"traditional":"望塵莫及"},{"id":"忘乎所以","hanzi":"忘乎所以","pinyin":"wànghū-suǒyǐ","meaning_vi":"quên hết trời đất (quá đắc ý hoặc quá vui)","explanation":"Quên mất cả bản thân → quá đắc ý hoặc phấn khích mà quên hết chừng mực.","hsk_level":6,"tags":["thanh-ngu"],"image":"🥳","examples":[{"type":"basic","zh":"别高兴得忘乎所以。","pinyin":"Bié gāoxìng de wànghūsuǒyǐ.","vi":"Đừng vui quá mà quên hết trời đất."},{"type":"simple","zh":"中了大奖后，他有点忘乎所以了。","pinyin":"Zhòngle dàjiǎng hòu, tā yǒudiǎn wànghūsuǒyǐ le.","vi":"Sau khi trúng giải lớn, anh ta có phần quên hết trời đất."},{"type":"compound","zh":"他一喝酒就忘乎所以，所以常常说错话得罪人。","pinyin":"Tā yì hējiǔ jiù wànghūsuǒyǐ, suǒyǐ chángcháng shuō cuò huà dézuì rén.","vi":"Hễ uống rượu là anh ta quên hết trời đất, nên thường nói lỡ lời làm mất lòng người khác."}],"related":[{"hanzi":"得意忘形","pinyin":"déyìwàngxíng","vi":"đắc ý quên mình"},{"hanzi":"飘飘然","pinyin":"piāopiāorán","vi":"lâng lâng tự mãn"},{"hanzi":"骄傲","pinyin":"jiāo'ào","vi":"kiêu ngạo"},{"hanzi":"冷静","pinyin":"lěngjìng","vi":"bình tĩnh"}]},{"id":"妄想","hanzi":"妄想","pinyin":"wàngxiǎng","meaning_vi":"mơ tưởng hão huyền, vọng tưởng","explanation":"妄 (bừa bãi) + 想 (nghĩ).","hsk_level":6,"tags":["dong-tu","danh-tu"],"image":"💭","examples":[{"type":"basic","zh":"这完全是妄想。","pinyin":"Zhè wánquán shì wàngxiǎng.","vi":"Đây hoàn toàn là mơ tưởng hão huyền."},{"type":"simple","zh":"他妄想不劳而获，一夜暴富。","pinyin":"Tā wàngxiǎng bù láo ér huò, yí yè bàofù.","vi":"Hắn mơ tưởng không làm mà hưởng, giàu lên sau một đêm."},{"type":"compound","zh":"敌人妄想阻止我们前进，可是他们注定要失败。","pinyin":"Dírén wàngxiǎng zǔzhǐ wǒmen qiánjìn, kěshì tāmen zhùdìng yào shībài.","vi":"Kẻ địch vọng tưởng ngăn cản bước tiến của chúng ta, nhưng chúng nhất định sẽ thất bại."}],"related":[{"hanzi":"幻想","pinyin":"huànxiǎng","vi":"ảo tưởng"},{"hanzi":"痴心妄想","pinyin":"chīxīnwàngxiǎng","vi":"mơ tưởng hão huyền"},{"hanzi":"梦想","pinyin":"mèngxiǎng","vi":"ước mơ"},{"hanzi":"空想","pinyin":"kōngxiǎng","vi":"không tưởng"}]},{"id":"丸","hanzi":"丸","pinyin":"wán","meaning_vi":"viên (thuốc/thịt viên)","explanation":"Ví dụ: 药丸 (viên thuốc), 肉丸 (thịt viên).","hsk_level":6,"tags":["danh-tu","an-uong"],"image":"💊","examples":[{"type":"basic","zh":"吃两丸药就好了。","pinyin":"Chī liǎng wán yào jiù hǎo le.","vi":"Uống hai viên thuốc là khỏi."},{"type":"simple","zh":"妈妈做了一锅香喷喷的肉丸汤。","pinyin":"Māma zuòle yì guō xiāngpēnpēn de ròuwán tāng.","vi":"Mẹ nấu một nồi canh thịt viên thơm phức."},{"type":"compound","zh":"奶奶每天睡前吃一丸中药，所以睡眠好了很多。","pinyin":"Nǎinai měitiān shuì qián chī yì wán zhōngyào, suǒyǐ shuìmián hǎole hěn duō.","vi":"Bà mỗi tối trước khi ngủ uống một viên thuốc bắc, nên giấc ngủ tốt hơn nhiều."}],"related":[{"hanzi":"药丸","pinyin":"yàowán","vi":"viên thuốc"},{"hanzi":"肉丸","pinyin":"ròuwán","vi":"thịt viên"},{"hanzi":"鱼丸","pinyin":"yúwán","vi":"chả cá viên"},{"hanzi":"颗","pinyin":"kē","vi":"viên hạt"}]},{"id":"完好无损","hanzi":"完好无损","pinyin":"wánhǎo-wúsǔn","meaning_vi":"nguyên vẹn không hư hại gì","explanation":"完好 (hoàn hảo – nguyên vẹn) + 无损 (vô tổn – không hư hại) → còn nguyên vẹn, không suy suyển chút nào.","hsk_level":6,"tags":["thanh-ngu"],"image":"✅","examples":[{"type":"basic","zh":"包裹完好无损。","pinyin":"Bāoguǒ wánhǎowúsǔn.","vi":"Bưu kiện nguyên vẹn không hư hại gì."},{"type":"simple","zh":"地震过后，这座古桥竟然完好无损。","pinyin":"Dìzhèn guòhòu, zhè zuò gǔ qiáo jìngrán wánhǎowúsǔn.","vi":"Sau trận động đất, cây cầu cổ này vẫn nguyên vẹn không hư hại."},{"type":"compound","zh":"手机从三楼掉下去，却完好无损，真是个奇迹。","pinyin":"Shǒujī cóng sān lóu diào xiàqù, què wánhǎowúsǔn, zhēn shì gè qíjì.","vi":"Điện thoại rơi từ tầng ba xuống mà vẫn nguyên vẹn, đúng là kỳ tích."}],"related":[{"hanzi":"完整","pinyin":"wánzhěng","vi":"hoàn chỉnh"},{"hanzi":"完好","pinyin":"wánhǎo","vi":"nguyên vẹn"},{"hanzi":"无损","pinyin":"wúsǔn","vi":"không tổn hại"},{"hanzi":"损坏","pinyin":"sǔnhuài","vi":"hư hỏng"}],"traditional":"完好無損"},{"id":"玩弄","hanzi":"玩弄","pinyin":"wánnòng","meaning_vi":"đùa giỡn, lợi dụng (tình cảm/thủ đoạn)","explanation":"玩 (chơi) + 弄 (làm).","hsk_level":6,"tags":["dong-tu"],"image":"🎭","examples":[{"type":"basic","zh":"他玩弄了她的感情。","pinyin":"Tā wánnòngle tā de gǎnqíng.","vi":"Hắn đã đùa giỡn tình cảm của cô ấy."},{"type":"simple","zh":"这个骗子很会玩弄花招。","pinyin":"Zhè ge piànzi hěn huì wánnòng huāzhāo.","vi":"Tên lừa đảo này rất giỏi giở trò mánh khóe."},{"type":"compound","zh":"他表面上很诚恳，其实一直在玩弄手段骗取信任。","pinyin":"Tā biǎomiànshang hěn chéngkěn, qíshí yìzhí zài wánnòng shǒuduàn piànqǔ xìnrèn.","vi":"Bề ngoài hắn rất thành khẩn, thực chất luôn giở thủ đoạn để lừa lấy lòng tin."}],"related":[{"hanzi":"玩弄感情","pinyin":"wánnònggǎnqíng","vi":"đùa giỡn tình cảm"},{"hanzi":"戏弄","pinyin":"xìnòng","vi":"trêu đùa"},{"hanzi":"操纵","pinyin":"cāozòng","vi":"thao túng"},{"hanzi":"欺骗","pinyin":"qīpiàn","vi":"lừa gạt"}]},{"id":"顽皮","hanzi":"顽皮","pinyin":"wánpí","meaning_vi":"tinh nghịch, nghịch ngợm","explanation":"顽 + 皮. Đồng nghĩa với 调皮.","hsk_level":6,"tags":["tinh-tu","con-nguoi"],"image":"😜","examples":[{"type":"basic","zh":"这孩子太顽皮了。","pinyin":"Zhè háizi tài wánpí le.","vi":"Đứa bé này nghịch quá."},{"type":"simple","zh":"顽皮的小猴子抢走了游客的帽子。","pinyin":"Wánpí de xiǎo hóuzi qiǎngzǒule yóukè de màozi.","vi":"Chú khỉ con tinh nghịch giật mất mũ của du khách."},{"type":"compound","zh":"他小时候虽然很顽皮，但是长大后变得非常稳重。","pinyin":"Tā xiǎoshíhou suīrán hěn wánpí, dànshì zhǎngdà hòu biànde fēicháng wěnzhòng.","vi":"Hồi nhỏ cậu ấy tuy rất nghịch ngợm, nhưng lớn lên lại trở nên rất chín chắn."}],"related":[{"hanzi":"调皮","pinyin":"tiáopí","vi":"nghịch ngợm"},{"hanzi":"淘气","pinyin":"táoqì","vi":"tinh nghịch"},{"hanzi":"顽皮捣蛋","pinyin":"wánpídǎodàn","vi":"quậy phá"},{"hanzi":"乖","pinyin":"guāi","vi":"ngoan"}],"traditional":"頑皮"},{"id":"慰藉","hanzi":"慰藉","pinyin":"wèijiè","meaning_vi":"an ủi, vỗ về tinh thần","explanation":"慰 (an ủi) + 藉.","hsk_level":6,"tags":["dong-tu","cam-xuc"],"image":"🤗","examples":[{"type":"basic","zh":"音乐给了我慰藉。","pinyin":"Yīnyuè gěile wǒ wèijiè.","vi":"Âm nhạc đã an ủi tôi."},{"type":"simple","zh":"孩子的来信是老人最大的慰藉。","pinyin":"Háizi de láixìn shì lǎorén zuì dà de wèijiè.","vi":"Thư con cái gửi về là niềm an ủi lớn nhất của người già."},{"type":"compound","zh":"虽然比赛输了，但是观众的掌声让他得到了一些慰藉。","pinyin":"Suīrán bǐsài shū le, dànshì guānzhòng de zhǎngshēng ràng tā dédàole yìxiē wèijiè.","vi":"Tuy thua trận, nhưng tràng vỗ tay của khán giả đã an ủi anh ấy phần nào."}],"related":[{"hanzi":"安慰","pinyin":"ānwèi","vi":"an ủi"},{"hanzi":"抚慰","pinyin":"fǔwèi","vi":"vỗ về"},{"hanzi":"心灵慰藉","pinyin":"xīnlíngwèijiè","vi":"an ủi tâm hồn"},{"hanzi":"鼓励","pinyin":"gǔlì","vi":"khích lệ"}]},{"id":"味精","hanzi":"味精","pinyin":"wèijīng","meaning_vi":"mì chính, bột ngọt","explanation":"味 (vị) + 精 (tinh chất).","hsk_level":6,"tags":["danh-tu","an-uong"],"image":"🧂","examples":[{"type":"basic","zh":"少放点味精。","pinyin":"Shǎofàng diǎn wèijīng.","vi":"Cho ít mì chính thôi."},{"type":"simple","zh":"这家面馆的汤里完全不加味精。","pinyin":"Zhè jiā miànguǎn de tāng lǐ wánquán bùjiā wèijīng.","vi":"Nước dùng của quán mì này hoàn toàn không cho bột ngọt."},{"type":"compound","zh":"如果食材够新鲜，就根本不需要放味精。","pinyin":"Rúguǒ shícái gòu xīnxiān, jiù gēnběnbù xūyào fàng wèijīng.","vi":"Nếu nguyên liệu đủ tươi thì hoàn toàn không cần cho mì chính."}],"related":[{"hanzi":"调料","pinyin":"tiáoliào","vi":"gia vị"},{"hanzi":"盐","pinyin":"yán","vi":"muối"},{"hanzi":"鸡精","pinyin":"jījīng","vi":"hạt nêm gà"},{"hanzi":"酱油","pinyin":"jiàngyóu","vi":"xì dầu"}]},{"id":"畏缩","hanzi":"畏缩","pinyin":"wèisuō","meaning_vi":"rụt rè, chùn bước (vì sợ hãi)","explanation":"畏 (sợ) + 缩 (co lại).","hsk_level":6,"tags":["dong-tu"],"image":"😨","examples":[{"type":"basic","zh":"他从不畏缩。","pinyin":"Tā cóng bú wèisuō.","vi":"Anh ấy chưa bao giờ chùn bước."},{"type":"simple","zh":"面对凶猛的大狗，孩子畏缩地躲到妈妈身后。","pinyin":"Miànduì xiōngměng de dà gǒu, háizi wèisuō de duǒ dào māma shēnhòu.","vi":"Trước con chó to dữ tợn, đứa bé rụt rè nấp sau lưng mẹ."},{"type":"compound","zh":"即使困难再大，我们也不能畏缩不前。","pinyin":"Jíshǐ kùnnan zài dà, wǒmen yě bù néng wèisuō bù qián.","vi":"Dù khó khăn lớn đến đâu, chúng ta cũng không được chùn bước."}],"related":[{"hanzi":"退缩","pinyin":"tuìsuō","vi":"co rút lùi bước"},{"hanzi":"畏惧","pinyin":"wèijù","vi":"sợ hãi"},{"hanzi":"胆怯","pinyin":"dǎnqiè","vi":"nhút nhát"},{"hanzi":"勇往直前","pinyin":"yǒngwǎngzhíqián","vi":"dũng cảm tiến lên"}],"traditional":"畏縮"},{"id":"违背","hanzi":"违背","pinyin":"wéibèi","meaning_vi":"làm trái, vi phạm (nguyên tắc/lời hứa)","explanation":"违 (trái) + 背 (quay lưng).","hsk_level":6,"tags":["dong-tu"],"image":"🚫","examples":[{"type":"basic","zh":"你违背了诺言。","pinyin":"Nǐ wéibèile nuòyán.","vi":"Anh đã làm trái lời hứa."},{"type":"simple","zh":"这种做法违背了公司的基本原则。","pinyin":"Zhè zhǒng zuòfǎ wéibèile gōngsī de jīběn yuánzé.","vi":"Cách làm này vi phạm nguyên tắc cơ bản của công ty."},{"type":"compound","zh":"既然大家都签了合同，就谁也不能违背约定。","pinyin":"Jìrán dàjiā dōu qiānle hétong, jiù shéi yě bù néng wéibèi yuēdìng.","vi":"Đã cùng ký hợp đồng thì không ai được làm trái thỏa thuận."}],"related":[{"hanzi":"违反","pinyin":"wéifǎn","vi":"vi phạm"},{"hanzi":"背叛","pinyin":"bèipàn","vi":"phản bội"},{"hanzi":"遵守","pinyin":"zūnshǒu","vi":"tuân thủ"},{"hanzi":"违背诺言","pinyin":"wéibèinuòyán","vi":"thất hứa"}],"traditional":"違背"},{"id":"唯独","hanzi":"唯独","pinyin":"wéidú","meaning_vi":"duy chỉ có, chỉ riêng","explanation":"唯 (chỉ) + 独 (một mình).","hsk_level":6,"tags":["pho-tu"],"image":"1️⃣","examples":[{"type":"basic","zh":"大家都来了，唯独他没来。","pinyin":"Dàjiā dōu lái le, wéidú tā méi lái.","vi":"Mọi người đều đến cả, duy chỉ có anh ấy không đến."},{"type":"simple","zh":"她什么菜都吃，唯独不吃香菜。","pinyin":"Tā shénme cài dōu chī, wéidú bù chī xiāngcài.","vi":"Món gì cô ấy cũng ăn, chỉ riêng rau mùi là không ăn."},{"type":"compound","zh":"这次考试他各科都及格了，唯独数学差了两分，所以只好补考。","pinyin":"Zhè cì kǎoshì tā gè kē dōu jígé le, wéidú shùxué chàle liǎng fēn, suǒyǐ zhǐhǎo bǔkǎo.","vi":"Kỳ thi này môn nào cậu ấy cũng đỗ, chỉ riêng toán thiếu hai điểm nên đành thi lại."}],"related":[{"hanzi":"只有","pinyin":"zhǐyǒu","vi":"chỉ có"},{"hanzi":"唯一","pinyin":"wéiyī","vi":"duy nhất"},{"hanzi":"惟独","pinyin":"wéidú","vi":"chỉ riêng"},{"hanzi":"除了","pinyin":"chúle","vi":"ngoại trừ"}],"traditional":"唯獨"},{"id":"为难","hanzi":"为难","pinyin":"wéinán","meaning_vi":"làm khó, gây khó dễ, khó xử","explanation":"为 (vi – làm) + 难 (nan – khó) → cảm thấy khó xử (感到为难), hoặc cố ý làm khó người khác (为难他).","hsk_level":6,"tags":["dong-tu","tinh-tu"],"image":"😅","examples":[{"type":"basic","zh":"你别为难他了。","pinyin":"Nǐ bié wéinán tā le.","vi":"Anh đừng làm khó cậu ấy nữa."},{"type":"simple","zh":"两个好朋友同时请我吃饭，我很为难。","pinyin":"Liǎng gè hǎopéngyou tóngshí qǐng wǒ chīfàn, wǒ hěn wéinán.","vi":"Hai người bạn thân cùng lúc mời tôi đi ăn, tôi rất khó xử."},{"type":"compound","zh":"如果这件事让你为难，你就直接拒绝我吧。","pinyin":"Rúguǒ zhè jiàn shì ràng nǐ wéinán, nǐ jiù zhíjiē jùjué wǒ ba.","vi":"Nếu chuyện này khiến bạn khó xử thì cứ từ chối thẳng tôi đi."}],"related":[{"hanzi":"刁难","pinyin":"diāonàn","vi":"làm khó dễ"},{"hanzi":"难为","pinyin":"nánwei","vi":"làm khó"},{"hanzi":"尴尬","pinyin":"gāngà","vi":"khó xử"},{"hanzi":"左右为难","pinyin":"zuǒyòuwéinán","vi":"tiến thoái lưỡng nan"}],"traditional":"為難"},{"id":"为期","hanzi":"为期","pinyin":"wéiqī","meaning_vi":"trong thời hạn (bao lâu)","explanation":"为 + 期 (kỳ hạn). Ví dụ: 为期三天 (kéo dài 3 ngày).","hsk_level":6,"tags":["dong-tu","thoi-gian"],"image":"📅","examples":[{"type":"basic","zh":"培训为期三天。","pinyin":"Péixùn wéiqī sān tiān.","vi":"Khóa đào tạo kéo dài ba ngày."},{"type":"simple","zh":"他们开始了为期一个月的海外考察。","pinyin":"Tāmen kāishǐle wéiqī yí gèyuè de hǎiwài kǎochá.","vi":"Họ bắt đầu chuyến khảo sát nước ngoài kéo dài một tháng."},{"type":"compound","zh":"这次展览为期两周，所以想看的人要抓紧时间。","pinyin":"Zhè cì zhǎnlǎn wéiqī liǎng zhōu, suǒyǐ xiǎng kàn de rén yào zhuājǐn shíjiān.","vi":"Triển lãm lần này kéo dài hai tuần, nên ai muốn xem phải tranh thủ."}],"related":[{"hanzi":"期限","pinyin":"qīxiàn","vi":"thời hạn"},{"hanzi":"为期一周","pinyin":"wéiqīyìzhōu","vi":"trong thời hạn một tuần"},{"hanzi":"期间","pinyin":"qījiān","vi":"trong thời gian"},{"hanzi":"日期","pinyin":"rìqī","vi":"ngày tháng"}],"traditional":"為期"},{"id":"为人处世","hanzi":"为人处世","pinyin":"wéirén-chǔshì","meaning_vi":"đối nhân xử thế","explanation":"为人 (vi nhân – làm người) + 处世 (xử thế – cư xử ở đời) → cách đối nhân xử thế.","hsk_level":6,"tags":["thanh-ngu","giao-tiep"],"image":"🤝","examples":[{"type":"basic","zh":"他很懂为人处世。","pinyin":"Tā hěn dǒng wéirénchǔshì.","vi":"Anh ấy rất hiểu cách đối nhân xử thế."},{"type":"simple","zh":"父亲教会了我为人处世的道理。","pinyin":"Fùqīn jiāohuìle wǒ wéirénchǔshì de dàolǐ.","vi":"Cha đã dạy tôi đạo lý đối nhân xử thế."},{"type":"compound","zh":"一个人不但要有能力，而且要懂得为人处世。","pinyin":"Yígèrén búdàn yàoyǒu nénglì, érqiě yào dǒngde wéirénchǔshì.","vi":"Một người không những phải có năng lực mà còn phải biết đối nhân xử thế."}],"related":[{"hanzi":"为人","pinyin":"wéirén","vi":"cách làm người"},{"hanzi":"待人接物","pinyin":"dàirénjiēwù","vi":"đối nhân xử thế"},{"hanzi":"处世","pinyin":"chǔshì","vi":"xử thế"},{"hanzi":"人际关系","pinyin":"rénjìguānxì","vi":"quan hệ giữa người"}],"traditional":"為人處世"},{"id":"维生素","hanzi":"维生素","pinyin":"wéishēngsù","meaning_vi":"vitamin","explanation":"维 + 生素 (phiên âm 'vitamin').","hsk_level":6,"tags":["danh-tu","suc-khoe","an-uong"],"image":"🍊","examples":[{"type":"basic","zh":"橙子富含维生素。","pinyin":"Chéngzi fùhán wéishēngsù.","vi":"Cam chứa nhiều vitamin."},{"type":"simple","zh":"医生建议他每天吃一片维生素。","pinyin":"Yīshēng jiànyì tā měitiān chī yípiàn wéishēngsù.","vi":"Bác sĩ khuyên anh ấy mỗi ngày uống một viên vitamin."},{"type":"compound","zh":"因为长期缺乏维生素，所以他的牙龈经常出血。","pinyin":"Yīnwèi chángqī quēfá wéishēngsù, suǒyǐ tā de yáyín jīngcháng chūxiě.","vi":"Vì lâu ngày thiếu vitamin nên lợi của anh ấy thường xuyên chảy máu."}],"related":[{"hanzi":"营养","pinyin":"yíngyǎng","vi":"dinh dưỡng"},{"hanzi":"蛋白质","pinyin":"dànbáizhì","vi":"protein"},{"hanzi":"矿物质","pinyin":"kuàngwùzhì","vi":"khoáng chất"},{"hanzi":"补充","pinyin":"bǔchōng","vi":"bổ sung"}],"traditional":"維生素"},{"id":"维系","hanzi":"维系","pinyin":"wéixì","meaning_vi":"duy trì, gắn kết (tình cảm/mối quan hệ)","explanation":"维 (giữ) + 系 (nối).","hsk_level":6,"tags":["dong-tu"],"image":"🔗","examples":[{"type":"basic","zh":"感情需要维系。","pinyin":"Gǎnqíng xūyào wéixì.","vi":"Tình cảm cần được vun đắp duy trì."},{"type":"simple","zh":"共同的爱好维系着他们的友谊。","pinyin":"Gòngtóng de àihào wéixìzhe tāmen de yǒuyì.","vi":"Sở thích chung gắn kết tình bạn của họ."},{"type":"compound","zh":"虽然两人分隔两地，但是每天的视频电话维系着他们的感情。","pinyin":"Suīrán liǎng rén fēngé liǎng dì, dànshì měitiān de shìpín diànhuà wéixìzhe tāmen de gǎnqíng.","vi":"Tuy hai người ở hai nơi, nhưng cuộc gọi video mỗi ngày đã gắn kết tình cảm của họ."}],"related":[{"hanzi":"维持","pinyin":"wéichí","vi":"duy trì"},{"hanzi":"保持","pinyin":"bǎochí","vi":"giữ gìn"},{"hanzi":"联系","pinyin":"liánxì","vi":"liên hệ"},{"hanzi":"纽带","pinyin":"niǔdài","vi":"sợi dây gắn kết"}],"traditional":"維繫"},{"id":"文盲","hanzi":"文盲","pinyin":"wénmáng","meaning_vi":"người mù chữ, nạn mù chữ","explanation":"文 (chữ viết) + 盲 (mù).","hsk_level":6,"tags":["danh-tu","hoc-tap","xa-hoi"],"image":"📖","examples":[{"type":"basic","zh":"他奶奶是文盲。","pinyin":"Tā nǎinai shì wénmáng.","vi":"Bà nội anh ấy là người mù chữ."},{"type":"simple","zh":"那个年代，村里的文盲非常多。","pinyin":"Nà ge niándài, cūnlǐ de wénmáng fēichángduō.","vi":"Thời đó, trong làng có rất nhiều người mù chữ."},{"type":"compound","zh":"如果不会用电脑和手机，那么在今天也算是一种新文盲。","pinyin":"Rúguǒ bú huì yòng diànnǎo hé shǒujī, nàme zài jīntiān yě suànshì yì zhǒng xīn wénmáng.","vi":"Nếu không biết dùng máy tính và điện thoại thì ngày nay cũng coi như một kiểu mù chữ mới."}],"related":[{"hanzi":"识字","pinyin":"shízì","vi":"biết chữ"},{"hanzi":"扫盲","pinyin":"sǎománg","vi":"xóa mù chữ"},{"hanzi":"文化","pinyin":"wénhuà","vi":"văn hóa"},{"hanzi":"法盲","pinyin":"fǎmáng","vi":"người mù luật"}]},{"id":"文物","hanzi":"文物","pinyin":"wénwù","meaning_vi":"cổ vật, di vật văn hóa","explanation":"文 + 物 (vật phẩm).","hsk_level":6,"tags":["danh-tu","van-hoa"],"image":"🏺","examples":[{"type":"basic","zh":"这件文物很珍贵。","pinyin":"Zhè jiàn wénwù hěn zhēnguì.","vi":"Cổ vật này rất quý giá."},{"type":"simple","zh":"考古队在工地下挖出了一批文物。","pinyin":"Kǎogǔ duì zài gōngdì xià wā chūle yìpī wénwù.","vi":"Đội khảo cổ đào được một loạt cổ vật dưới công trường."},{"type":"compound","zh":"因为这些文物非常脆弱，所以参观时禁止用闪光灯拍照。","pinyin":"Yīnwèi zhèxiē wénwù fēicháng cuìruò, suǒyǐ cānguān shí jìnzhǐ yòng shǎnguāngdēng pāizhào.","vi":"Vì những cổ vật này rất dễ hỏng nên khi tham quan cấm chụp ảnh có đèn flash."}],"related":[{"hanzi":"古董","pinyin":"gǔdǒng","vi":"đồ cổ"},{"hanzi":"文化遗产","pinyin":"wénhuàyíchǎn","vi":"di sản văn hóa"},{"hanzi":"博物馆","pinyin":"bówùguǎn","vi":"bảo tàng"},{"hanzi":"古迹","pinyin":"gǔjì","vi":"di tích cổ"}]},{"id":"文艺","hanzi":"文艺","pinyin":"wényì","meaning_vi":"văn nghệ, văn học nghệ thuật","explanation":"文 (văn học) + 艺 (nghệ thuật).","hsk_level":6,"tags":["danh-tu","van-hoa","giai-tri"],"image":"🎭","examples":[{"type":"basic","zh":"她很喜欢文艺片。","pinyin":"Tā hěn xǐhuan wényì piàn.","vi":"Cô ấy rất thích phim nghệ thuật."},{"type":"simple","zh":"学校每年元旦都举办文艺晚会。","pinyin":"Xuéxiào měinián Yuándàn dōu jǔbàn wényì wǎnhuì.","vi":"Trường năm nào cũng tổ chức đêm văn nghệ vào Tết Dương lịch."},{"type":"compound","zh":"他既爱好文艺，又擅长运动，在班里很受欢迎。","pinyin":"Tā jì àihào wényì, yòu shàncháng yùndòng, zài bān lǐ hěn shòuhuānyíng.","vi":"Cậu ấy vừa yêu văn nghệ vừa giỏi thể thao, rất được yêu mến trong lớp."}],"related":[{"hanzi":"文学","pinyin":"wénxué","vi":"văn học"},{"hanzi":"艺术","pinyin":"yìshù","vi":"nghệ thuật"},{"hanzi":"文艺演出","pinyin":"wényìyǎnchū","vi":"biểu diễn văn nghệ"},{"hanzi":"文娱","pinyin":"wényú","vi":"văn hóa giải trí"}],"traditional":"文藝"},{"id":"误解","hanzi":"误解","pinyin":"wùjiě","meaning_vi":"hiểu lầm","explanation":"误 + 解 (hiểu). Đồng nghĩa với 误会.","hsk_level":6,"tags":["dong-tu","danh-tu"],"image":"😵‍💫","examples":[{"type":"basic","zh":"你误解我的意思了。","pinyin":"Nǐ wùjiě wǒ de yìsi le.","vi":"Bạn hiểu lầm ý tôi rồi."},{"type":"simple","zh":"一条没回的短信引起了很大的误解。","pinyin":"Yì tiáo méi huí de duǎnxìn yǐnqǐle hěn dà de wùjiě.","vi":"Một tin nhắn không trả lời đã gây ra hiểu lầm lớn."},{"type":"compound","zh":"只要双方把话说清楚，这个误解就能消除。","pinyin":"Zhǐyào shuāngfāng bǎ huàshuō qīngchu, zhè ge wùjiě jiù néng xiāochú.","vi":"Chỉ cần hai bên nói rõ ràng thì hiểu lầm này sẽ được xóa bỏ."}],"related":[{"hanzi":"误会","pinyin":"wùhuì","vi":"hiểu lầm"},{"hanzi":"曲解","pinyin":"qūjiě","vi":"xuyên tạc"},{"hanzi":"理解","pinyin":"lǐjiě","vi":"thấu hiểu"},{"hanzi":"误区","pinyin":"wùqū","vi":"quan niệm sai lầm"}],"traditional":"誤解"},{"id":"误区","hanzi":"误区","pinyin":"wùqū","meaning_vi":"hiểu lầm phổ biến, vùng nhận thức sai lầm","explanation":"误 (sai) + 区 (vùng).","hsk_level":6,"tags":["danh-tu","nhan-thuc"],"image":"⚠️","examples":[{"type":"basic","zh":"这是减肥的误区。","pinyin":"Zhè shì jiǎnféi de wùqū.","vi":"Đây là quan niệm sai lầm khi giảm cân."},{"type":"simple","zh":"很多家长在教育孩子上走进了误区。","pinyin":"Hěn duō jiāzhǎng zài jiàoyù háizi shang zǒujìnle wùqū.","vi":"Nhiều phụ huynh đã đi vào lối mòn sai lầm trong việc giáo dục con cái."},{"type":"compound","zh":"有人以为不吃早饭能减肥，其实这是一个常见的误区。","pinyin":"Yǒurén yǐwéi bù chī zǎofàn néng jiǎnféi, qíshí zhè shì yí gè chángjiàn de wùqū.","vi":"Có người tưởng nhịn ăn sáng sẽ giảm cân, thực ra đây là một quan niệm sai lầm phổ biến."}],"related":[{"hanzi":"误解","pinyin":"wùjiě","vi":"hiểu lầm"},{"hanzi":"错误","pinyin":"cuòwù","vi":"sai lầm"},{"hanzi":"走出误区","pinyin":"zǒuchūwùqū","vi":"thoát khỏi nhận thức sai"},{"hanzi":"偏见","pinyin":"piānjiàn","vi":"định kiến"}],"traditional":"誤區"},{"id":"务实","hanzi":"务实","pinyin":"wùshí","meaning_vi":"thực tế, thiết thực","explanation":"务 (chú trọng) + 实 (thực tế).","hsk_level":6,"tags":["tinh-tu","cong-viec"],"image":"✅","examples":[{"type":"basic","zh":"他做事很务实。","pinyin":"Tā zuòshì hěn wùshí.","vi":"Anh ấy làm việc rất thực tế."},{"type":"simple","zh":"新领导提出了一套务实的改革方案。","pinyin":"Xīn lǐngdǎo tíchūle yítào wùshí de gǎigé fāng'àn.","vi":"Lãnh đạo mới đưa ra một phương án cải cách thiết thực."},{"type":"compound","zh":"与其整天空谈理想，不如务实地做好眼前的事。","pinyin":"Yǔqí zhěngtiān kōngtán lǐxiǎng, bùrú wù shíde zuò hǎo yǎnqián de shì.","vi":"Thay vì suốt ngày nói suông về lý tưởng, chi bằng thực tế làm tốt việc trước mắt."}],"related":[{"hanzi":"实际","pinyin":"shíjì","vi":"thực tế"},{"hanzi":"踏实","pinyin":"tāshi","vi":"vững vàng chắc chắn"},{"hanzi":"实事求是","pinyin":"shíshìqiúshì","vi":"thực sự cầu thị"},{"hanzi":"务虚","pinyin":"wùxū","vi":"bàn lý luận suông"}],"traditional":"務實"},{"id":"物资","hanzi":"物资","pinyin":"wùzī","meaning_vi":"vật tư, hàng hóa thiết yếu","explanation":"物 + 资 (tài nguyên).","hsk_level":6,"tags":["danh-tu","cong-viec"],"image":"📦","examples":[{"type":"basic","zh":"救灾物资已送到。","pinyin":"Jiùzāi wùzī yǐ sòng dào.","vi":"Vật tư cứu trợ đã được đưa đến."},{"type":"simple","zh":"志愿者们连夜搬运防疫物资。","pinyin":"Zhìyuànzhěmen liányè bānyùn fángyì wùzī.","vi":"Các tình nguyện viên suốt đêm vận chuyển vật tư phòng dịch."},{"type":"compound","zh":"因为道路被冲断了，所以物资只能用直升机送进山区。","pinyin":"Yīnwèi dàolù bèi chōng duàn le, suǒyǐ wùzī zhǐnéng yòng zhíshēngjī sòng jìn shānqū.","vi":"Vì đường bị lũ cắt đứt nên hàng hóa thiết yếu chỉ có thể đưa vào vùng núi bằng trực thăng."}],"related":[{"hanzi":"物品","pinyin":"wùpǐn","vi":"đồ vật"},{"hanzi":"资源","pinyin":"zīyuán","vi":"tài nguyên"},{"hanzi":"救灾物资","pinyin":"jiùzāiwùzī","vi":"hàng cứu trợ"},{"hanzi":"供应","pinyin":"gōngyìng","vi":"cung ứng"}],"traditional":"物資"},{"id":"无偿","hanzi":"无偿","pinyin":"wúcháng","meaning_vi":"miễn phí, không lấy thù lao","explanation":"无 + 偿 (đền bù/trả tiền). Cụm: 无偿献血 (hiến máu nhân đạo).","hsk_level":6,"tags":["tinh-tu","pho-tu"],"image":"💖","examples":[{"type":"basic","zh":"他无偿献血十年。","pinyin":"Tā wúchángxiànxiě shí nián.","vi":"Anh ấy hiến máu không lấy thù lao suốt mười năm."},{"type":"simple","zh":"这位律师无偿为老人提供法律帮助。","pinyin":"Zhè wèi lǜshī wúcháng wèi lǎorén tígōng fǎlǜ bāngzhù.","vi":"Vị luật sư này giúp đỡ pháp lý miễn phí cho người già."},{"type":"compound","zh":"虽然这份工作是无偿的，但是她做得比谁都认真。","pinyin":"Suīrán zhè fèn gōngzuò shì wúcháng de, dànshì tā zuò de bǐ shéi dōu rènzhēn.","vi":"Tuy công việc này không có thù lao, nhưng cô ấy làm còn chăm chỉ hơn bất kỳ ai."}],"related":[{"hanzi":"免费","pinyin":"miǎnfèi","vi":"miễn phí"},{"hanzi":"有偿","pinyin":"yǒucháng","vi":"có thù lao"},{"hanzi":"无偿献血","pinyin":"wúchángxiànxuè","vi":"hiến máu tình nguyện"},{"hanzi":"义务","pinyin":"yìwù","vi":"nghĩa vụ tự nguyện"}],"traditional":"無償"},{"id":"无精打采","hanzi":"无精打采","pinyin":"wújīng-dǎcǎi","meaning_vi":"ủ rũ, thiếu sức sống","explanation":"无精 (không có tinh thần) + 打采 (không phấn chấn) → uể oải, ủ rũ, thiếu sinh khí. Còn viết 没精打采.","hsk_level":6,"tags":["thanh-ngu","cam-xuc"],"image":"😴","examples":[{"type":"basic","zh":"他今天无精打采的。","pinyin":"Tā jīntiān wújīngdǎcǎi de.","vi":"Hôm nay anh ấy ủ rũ thiếu sức sống."},{"type":"simple","zh":"熬了一夜，他无精打采地走进教室。","pinyin":"Áole yí yè, tā wújīngdǎcǎi de zǒujìn jiàoshì.","vi":"Thức trắng một đêm, cậu ấy uể oải bước vào lớp."},{"type":"compound","zh":"他一听说春游取消了，就无精打采地趴在桌子上。","pinyin":"Tā yì tīngshuō chūnyóu qǔxiāo le, jiù wújīngdǎcǎi de pā zài zhuōzi shang.","vi":"Vừa nghe nói chuyến dã ngoại mùa xuân bị hủy, cậu bé liền ủ rũ gục xuống bàn."}],"related":[{"hanzi":"没精打采","pinyin":"méijīngdǎcǎi","vi":"uể oải"},{"hanzi":"垂头丧气","pinyin":"chuítóusàngqì","vi":"ủ rũ cụp đuôi"},{"hanzi":"死气沉沉","pinyin":"sǐqìchénchén","vi":"ảm đạm"},{"hanzi":"精神抖擞","pinyin":"jīngshéndǒusǒu","vi":"tinh thần phấn chấn"}],"traditional":"無精打采"},{"id":"无可奉告","hanzi":"无可奉告","pinyin":"wúkě-fènggào","meaning_vi":"miễn bình luận, không có gì để nói","explanation":"无可 (không có gì) + 奉告 (kính báo) → không có gì để nói, miễn bình luận; câu quen thuộc của người phát ngôn.","hsk_level":6,"tags":["thanh-ngu","giao-tiep"],"image":"🤐","examples":[{"type":"basic","zh":"对此我无可奉告。","pinyin":"Duì cǐ wǒ wúkěfènggào.","vi":"Về việc này tôi miễn bình luận."},{"type":"simple","zh":"面对记者的追问，经纪人只说无可奉告。","pinyin":"Miànduì jìzhě de zhuīwèn, jīngjìrén zhǐ shuō wúkěfènggào.","vi":"Trước sự truy hỏi của phóng viên, người quản lý chỉ nói miễn bình luận."},{"type":"compound","zh":"因为调查还没结束，所以警方暂时无可奉告。","pinyin":"Yīnwèi diàochá hái méi jiéshù, suǒyǐ jǐngfāng zànshí wúkěfènggào.","vi":"Vì cuộc điều tra chưa kết thúc nên cảnh sát tạm thời không có gì để nói."}],"related":[{"hanzi":"不予置评","pinyin":"bùyǔzhìpíng","vi":"miễn bình luận"},{"hanzi":"保密","pinyin":"bǎomì","vi":"giữ bí mật"},{"hanzi":"奉告","pinyin":"fènggào","vi":"xin báo cho biết"},{"hanzi":"回答","pinyin":"huídá","vi":"trả lời"}],"traditional":"無可奉告"},{"id":"无可奈何","hanzi":"无可奈何","pinyin":"wúkě-nàihé","meaning_vi":"bất lực đành chịu, không còn cách nào khác","explanation":"无可 (không có cách) + 奈何 (làm sao được) → đành bó tay, chẳng biết làm thế nào. Thường: 无可奈何地叹气.","hsk_level":6,"tags":["thanh-ngu"],"image":"🤷","examples":[{"type":"basic","zh":"他无可奈何地笑了。","pinyin":"Tā wúkěnàihé de xiào le.","vi":"Anh ấy cười một cách bất lực."},{"type":"simple","zh":"看着末班车开走，我们无可奈何。","pinyin":"Kànzhe mòbānchē kāizǒu, wǒmen wúkěnàihé.","vi":"Nhìn chuyến xe cuối rời đi, chúng tôi đành bất lực."},{"type":"compound","zh":"虽然大家都想留住他，但是他执意要走，我们也无可奈何。","pinyin":"Suīrán dàjiā dōu xiǎng liúzhù tā, dànshì tā zhíyì yào zǒu, wǒmen yě wúkěnàihé.","vi":"Tuy mọi người đều muốn giữ anh ấy lại, nhưng anh ấy nhất quyết ra đi, chúng tôi cũng đành chịu."}],"related":[{"hanzi":"无奈","pinyin":"wúnài","vi":"đành chịu"},{"hanzi":"束手无策","pinyin":"shùshǒuwúcè","vi":"bó tay hết cách"},{"hanzi":"迫不得已","pinyin":"pòbùdéyǐ","vi":"bất đắc dĩ"},{"hanzi":"没办法","pinyin":"méibànfǎ","vi":"không có cách"}],"traditional":"無可奈何"},{"id":"无穷无尽","hanzi":"无穷无尽","pinyin":"wúqióng-wújìn","meaning_vi":"vô cùng vô tận","explanation":"无穷 (vô cùng) + 无尽 (vô tận) → không có giới hạn, không bao giờ hết.","hsk_level":6,"tags":["thanh-ngu"],"image":"♾️","examples":[{"type":"basic","zh":"宇宙无穷无尽。","pinyin":"Yǔzhòu wúqióngwújìn.","vi":"Vũ trụ vô cùng vô tận."},{"type":"simple","zh":"孩子的问题总是无穷无尽的。","pinyin":"Háizi de wèntí zǒngshì wúqióngwújìn de.","vi":"Câu hỏi của trẻ con lúc nào cũng vô cùng vô tận."},{"type":"compound","zh":"人的欲望如果无穷无尽，就永远不会感到满足。","pinyin":"Rén de yùwàng rúguǒ wúqióngwújìn, jiù yǒngyuǎn bú huì gǎndào mǎnzú.","vi":"Nếu dục vọng của con người vô cùng vô tận thì sẽ không bao giờ cảm thấy thỏa mãn."}],"related":[{"hanzi":"无穷","pinyin":"wúqióng","vi":"vô cùng"},{"hanzi":"无边无际","pinyin":"wúbiānwújì","vi":"mênh mông vô tận"},{"hanzi":"无限","pinyin":"wúxiàn","vi":"vô hạn"},{"hanzi":"有限","pinyin":"yǒuxiàn","vi":"có hạn"}],"traditional":"無窮無盡"},{"id":"无缘无故","hanzi":"无缘无故","pinyin":"wúyuán-wúgù","meaning_vi":"vô duyên vô cớ, không lý do","explanation":"无缘 (không duyên cớ) + 无故 (vô cố – không lý do) → hoàn toàn không có lý do gì. Lưu ý: khác nghĩa vô duyên của tiếng Việt.","hsk_level":6,"tags":["thanh-ngu"],"image":"❓","examples":[{"type":"basic","zh":"他无缘无故发火。","pinyin":"Tā wúyuánwúgù fāhuǒ.","vi":"Anh ta nổi giận vô duyên vô cớ."},{"type":"simple","zh":"电脑昨天无缘无故地死机了好几次。","pinyin":"Diànnǎo zuótiān wúyuánwúgù de sǐjīle hǎojǐ cì.","vi":"Hôm qua máy tính bị treo mấy lần chẳng vì lý do gì."},{"type":"compound","zh":"世上没有无缘无故的爱，也没有无缘无故的恨。","pinyin":"Shìshàng méiyǒu wúyuánwúgù de ài, yě méiyǒu wúyuánwúgù de hèn.","vi":"Trên đời không có tình yêu vô duyên vô cớ, cũng không có hận thù vô duyên vô cớ."}],"related":[{"hanzi":"莫名其妙","pinyin":"mòmíngqímiào","vi":"khó hiểu vô cớ"},{"hanzi":"平白无故","pinyin":"píngbáiwúgù","vi":"vô cớ"},{"hanzi":"原因","pinyin":"yuányīn","vi":"nguyên nhân"},{"hanzi":"理由","pinyin":"lǐyóu","vi":"lý do"}],"traditional":"無緣無故"},{"id":"无影无踪","hanzi":"无影无踪","pinyin":"wúyǐng-wúzōng","meaning_vi":"biến mất không dấu vết, biệt tăm biệt tích","explanation":"无影 (không bóng) + 无踪 (vô tung – không dấu vết) → biến mất không còn dấu vết. Cụm: 消失得无影无踪.","hsk_level":6,"tags":["thanh-ngu"],"image":"🌫️","examples":[{"type":"basic","zh":"小偷跑得无影无踪。","pinyin":"Xiǎo tōupǎo de wúyǐngwúzōng.","vi":"Tên trộm chạy mất không dấu vết."},{"type":"simple","zh":"太阳一出来，晨雾就消失得无影无踪。","pinyin":"Tàiyáng yì chūlái, chén wù jiù xiāoshī de wúyǐngwúzōng.","vi":"Mặt trời vừa ló lên, sương sớm liền tan biến không dấu vết."},{"type":"compound","zh":"他借了钱以后就无影无踪了，连电话也打不通。","pinyin":"Tā jièle qián yǐhòu jiù wúyǐngwúzōng le, lián diànhuà yě dǎbutōng.","vi":"Sau khi vay tiền hắn liền biệt tăm biệt tích, ngay cả điện thoại cũng không gọi được."}],"related":[{"hanzi":"销声匿迹","pinyin":"xiāoshēngnìjì","vi":"bặt tăm"},{"hanzi":"消失","pinyin":"xiāoshī","vi":"biến mất"},{"hanzi":"踪影","pinyin":"zōngyǐng","vi":"tung tích"},{"hanzi":"无踪","pinyin":"wúzōng","vi":"không dấu vết"}],"traditional":"無影無蹤"},{"id":"无知","hanzi":"无知","pinyin":"wúzhī","meaning_vi":"vô tri, thiếu hiểu biết","explanation":"无 + 知 (hiểu biết).","hsk_level":6,"tags":["tinh-tu"],"image":"🙈","examples":[{"type":"basic","zh":"别笑话他无知。","pinyin":"Bié xiàohua tā wúzhī.","vi":"Đừng chê cười anh ấy thiếu hiểu biết."},{"type":"simple","zh":"当年的我太无知，才上了骗子的当。","pinyin":"Dāngnián de wǒ tài wúzhī, cái shàngle piànzi de dàng.","vi":"Năm đó tôi quá thiếu hiểu biết nên mới mắc lừa kẻ lừa đảo."},{"type":"compound","zh":"无知并不可怕，可怕的是不懂装懂。","pinyin":"Wúzhī bìngbù kěpà, kěpà de shì bù dǒng zhuāng dǒng.","vi":"Thiếu hiểu biết không đáng sợ, đáng sợ là không biết mà giả vờ biết."}],"related":[{"hanzi":"愚昧","pinyin":"yúmèi","vi":"ngu muội"},{"hanzi":"无知无畏","pinyin":"wúzhīwúwèi","vi":"không biết nên không sợ"},{"hanzi":"博学","pinyin":"bóxué","vi":"uyên bác"},{"hanzi":"知识","pinyin":"zhīshi","vi":"tri thức"}],"traditional":"無知"},{"id":"挖苦","hanzi":"挖苦","pinyin":"wāku","meaning_vi":"mỉa mai, châm chọc","explanation":"挖 (đào bới) + 苦 (đắng).","hsk_level":6,"tags":["dong-tu","giao-tiep"],"image":"😏","examples":[{"type":"basic","zh":"别挖苦人家。","pinyin":"Bié wāku rénjia.","vi":"Đừng mỉa mai người ta."},{"type":"simple","zh":"他总爱挖苦同事的穿着打扮。","pinyin":"Tā zǒng ài wāku tóngshì de chuānzhuó dǎbàn.","vi":"Anh ta luôn thích châm chọc cách ăn mặc của đồng nghiệp."},{"type":"compound","zh":"她本来想安慰朋友，结果说出的话却像是在挖苦人。","pinyin":"Tā běnlái xiǎng ānwèi péngyou, jiéguǒ shuōchū dehuà què xiàng shì zài wāku rén.","vi":"Cô ấy vốn định an ủi bạn, kết quả lời nói ra lại giống như đang mỉa mai người ta."}],"related":[{"hanzi":"讽刺","pinyin":"fěngcì","vi":"châm biếm"},{"hanzi":"嘲笑","pinyin":"cháoxiào","vi":"chế giễu"},{"hanzi":"冷嘲热讽","pinyin":"lěngcháorèfěng","vi":"mỉa mai châm chọc"},{"hanzi":"讥讽","pinyin":"jīfěng","vi":"giễu cợt"}]},{"id":"哇塞","hanzi":"哇塞","pinyin":"wāsāi","meaning_vi":"trời ơi, đỉnh quá (thán từ cảm thán)","explanation":"Thán từ khẩu ngữ.","hsk_level":6,"tags":["tro-tu","cam-xuc"],"image":"😲","examples":[{"type":"basic","zh":"哇塞，太漂亮了！","pinyin":"Wāsāi, tài piàoliang le!","vi":"Trời ơi, đẹp quá!"},{"type":"simple","zh":"哇塞，这家店的蛋糕也太好吃了吧！","pinyin":"Wāsāi, zhè jiā diàn de dàngāo yě tài hǎochīle ba!","vi":"Trời ơi, bánh kem của tiệm này ngon quá đi mất!"},{"type":"compound","zh":"哇塞，你不但考上了北大，而且还拿了奖学金！","pinyin":"Wāsāi, nǐ búdàn kǎoshàngle Běidà, érqiě hái nále jiǎngxuéjīn!","vi":"Trời ơi, cậu không những đỗ Đại học Bắc Kinh mà còn giành được học bổng!"}],"related":[{"hanzi":"哇","pinyin":"wā","vi":"oa"},{"hanzi":"天哪","pinyin":"tiānna","vi":"trời ơi"},{"hanzi":"厉害","pinyin":"lìhai","vi":"giỏi quá"},{"hanzi":"太棒了","pinyin":"tàibàngle","vi":"tuyệt quá"}]},{"id":"歪风邪气","hanzi":"歪风邪气","pinyin":"wāifēng-xiéqì","meaning_vi":"thói hư tật xấu, tệ nạn xã hội","explanation":"歪风 (gió lệch) + 邪气 (tà khí) → thói hư tật xấu, tác phong bất chính lan trong xã hội.","hsk_level":6,"tags":["thanh-ngu","xa-hoi"],"image":"🌪️","examples":[{"type":"basic","zh":"要刹住歪风邪气。","pinyin":"Yào shāzhù wāifēngxiéqì.","vi":"Phải chặn đứng thói hư tật xấu."},{"type":"simple","zh":"公司严厉打击送礼拉关系的歪风邪气。","pinyin":"Gōngsī yánlì dǎjī sònglǐ lāguānxì de wāifēngxiéqì.","vi":"Công ty nghiêm khắc trấn áp thói xấu biếu quà chạy quan hệ."},{"type":"compound","zh":"如果对歪风邪气视而不见，那么好风气就会被慢慢破坏。","pinyin":"Rúguǒ duì wāifēngxiéqì shì'érbújiàn, nàme hǎo fēngqì jiù huì bèi mànmàn pòhuài.","vi":"Nếu làm ngơ trước tệ nạn xấu thì nề nếp tốt sẽ dần dần bị phá hoại."}],"related":[{"hanzi":"不正之风","pinyin":"búzhèngzhīfēng","vi":"thói tiêu cực"},{"hanzi":"风气","pinyin":"fēngqì","vi":"phong khí"},{"hanzi":"邪恶","pinyin":"xié'è","vi":"tà ác"},{"hanzi":"正气","pinyin":"zhèngqì","vi":"chính khí"}],"traditional":"歪風邪氣"},{"id":"弯弯曲曲","hanzi":"弯弯曲曲","pinyin":"wānwānqūqū","meaning_vi":"quanh co uốn lượn","explanation":"Từ láy AABB.","hsk_level":6,"tags":["tinh-tu","giao-thong"],"image":"〰️","examples":[{"type":"basic","zh":"山路弯弯曲曲。","pinyin":"Shānlù wānwānqūqū.","vi":"Đường núi quanh co uốn lượn."},{"type":"simple","zh":"一条弯弯曲曲的小河穿过村庄。","pinyin":"Yì tiáo wānwānqūqū de xiǎohé chuānguò cūnzhuāng.","vi":"Một con sông nhỏ uốn lượn chảy qua làng."},{"type":"compound","zh":"这条小路弯弯曲曲的，所以第一次来的人很容易迷路。","pinyin":"Zhè tiáo xiǎolù wānwānqūqū de, suǒyǐ dìyīcì lái de rén hěn róngyì mílù.","vi":"Con đường nhỏ này quanh co khúc khuỷu nên người lần đầu đến rất dễ lạc đường."}],"related":[{"hanzi":"弯曲","pinyin":"wānqū","vi":"cong queo"},{"hanzi":"曲折","pinyin":"qūzhé","vi":"quanh co"},{"hanzi":"蜿蜒","pinyin":"wānyán","vi":"uốn lượn"},{"hanzi":"笔直","pinyin":"bǐzhí","vi":"thẳng tắp"}],"traditional":"彎彎曲曲"},{"id":"威风","hanzi":"威风","pinyin":"wēifēng","meaning_vi":"uy phong, oai vệ","explanation":"威 (uy quyền) + 风 (phong thái).","hsk_level":6,"tags":["tinh-tu","danh-tu"],"image":"🦁","examples":[{"type":"basic","zh":"警犬真威风。","pinyin":"Jǐngquǎn zhēn wēifēng.","vi":"Chó nghiệp vụ trông thật oai vệ."},{"type":"simple","zh":"他穿上军装，显得特别威风。","pinyin":"Tā chuānshàng jūnzhuāng, xiǎnde tèbié wēifēng.","vi":"Anh ấy mặc quân phục vào trông đặc biệt oai phong."},{"type":"compound","zh":"他在外面很威风，可是一回到家就怕老婆。","pinyin":"Tā zài wàimiàn hěn wēifēng, kěshì yì huí dàojiā jiù pàlǎopo.","vi":"Ở ngoài anh ta rất oai phong, nhưng hễ về nhà là sợ vợ."}],"related":[{"hanzi":"威严","pinyin":"wēiyán","vi":"uy nghiêm"},{"hanzi":"神气","pinyin":"shénqì","vi":"oai vệ"},{"hanzi":"威风凛凛","pinyin":"wēifēnglǐnlǐn","vi":"oai phong lẫm liệt"},{"hanzi":"霸气","pinyin":"bàqì","vi":"bá khí"}],"traditional":"威風"},{"id":"微乎其微","hanzi":"微乎其微","pinyin":"wēihū-qíwēi","meaning_vi":"vô cùng nhỏ bé, ít ỏi không đáng kể","explanation":"微 (vi – nhỏ) + 乎其微 (nhỏ đến cực điểm) → cực kỳ nhỏ, ít ỏi không đáng kể. Thường: 可能性微乎其微.","hsk_level":6,"tags":["thanh-ngu","so-luong"],"image":"🤏","examples":[{"type":"basic","zh":"成功率微乎其微。","pinyin":"Chéng gōnglǜ wēihūqíwēi.","vi":"Tỷ lệ thành công vô cùng nhỏ."},{"type":"simple","zh":"这种药的副作用微乎其微。","pinyin":"Zhè zhǒng yào de fùzuòyòng wēihūqíwēi.","vi":"Tác dụng phụ của loại thuốc này ít ỏi không đáng kể."},{"type":"compound","zh":"虽然中奖的可能微乎其微，但是他每周还是买一张彩票。","pinyin":"Suīrán zhòngjiǎng de kěnéng wēihūqíwēi, dànshì tā měizhōu háishi mǎi yì zhāng cǎipiào.","vi":"Tuy khả năng trúng thưởng vô cùng nhỏ, nhưng tuần nào anh ấy vẫn mua một tờ vé số."}],"related":[{"hanzi":"微不足道","pinyin":"wēibùzúdào","vi":"không đáng kể"},{"hanzi":"极少","pinyin":"jíshǎo","vi":"cực ít"},{"hanzi":"微小","pinyin":"wēixiǎo","vi":"nhỏ bé"},{"hanzi":"寥寥无几","pinyin":"liáoliáowújǐ","vi":"lèo tèo vài cái"}]},{"id":"威望","hanzi":"威望","pinyin":"wēiwàng","meaning_vi":"uy tín và danh vọng","explanation":"威 + 望 (danh vọng).","hsk_level":6,"tags":["danh-tu"],"image":"👑","examples":[{"type":"basic","zh":"他在村里很有威望。","pinyin":"Tā zài cūnlǐ hěn yǒu wēiwàng.","vi":"Ông ấy rất có uy tín trong làng."},{"type":"simple","zh":"这位老教授在学术界享有很高的威望。","pinyin":"Zhè wèi lǎo jiàoshòu zài xuéshùjiè xiǎngyǒu hěn gāo de wēiwàng.","vi":"Vị giáo sư già này có uy tín rất cao trong giới học thuật."},{"type":"compound","zh":"因为他办事公正，所以在员工中树立了很高的威望。","pinyin":"Yīnwèi tā bànshì gōngzhèng, suǒyǐ zài yuángōng zhōng shùlìle hěn gāo de wēiwàng.","vi":"Vì làm việc công bằng nên ông ấy đã tạo được uy tín cao trong nhân viên."}],"related":[{"hanzi":"威信","pinyin":"wēixìn","vi":"uy tín"},{"hanzi":"声望","pinyin":"shēngwàng","vi":"danh vọng"},{"hanzi":"名望","pinyin":"míngwàng","vi":"danh tiếng"},{"hanzi":"权威","pinyin":"quánwēi","vi":"quyền uy"}]},{"id":"危言耸听","hanzi":"危言耸听","pinyin":"wēiyán-sǒngtīng","meaning_vi":"nói lời giật gân gây hoang mang","explanation":"危言 (nguy ngôn – lời đáng sợ) + 耸听 (tủng thính – làm người nghe kinh động) → cố ý nói quá để dọa, gây hoang mang.","hsk_level":6,"tags":["thanh-ngu"],"image":"😱","examples":[{"type":"basic","zh":"你别危言耸听。","pinyin":"Nǐ bié wēiyánsǒngtīng.","vi":"Anh đừng nói lời giật gân gây hoang mang."},{"type":"simple","zh":"网上有些文章故意危言耸听吸引点击。","pinyin":"Wǎngshang yǒuxiē wénzhāng gùyì wēiyánsǒngtīng xīyǐn diǎnjī.","vi":"Một số bài viết trên mạng cố ý giật gân để thu hút lượt nhấp."},{"type":"compound","zh":"这并不是危言耸听，如果再不治理，河水就会彻底污染。","pinyin":"Zhè bìngbú shì wēiyánsǒngtīng, rúguǒ zài bú zhìlǐ, héshuǐ jiù huì chèdǐ wūrǎn.","vi":"Đây không phải nói giật gân, nếu không xử lý thì nước sông sẽ bị ô nhiễm hoàn toàn."}],"related":[{"hanzi":"耸人听闻","pinyin":"sǒngréntīngwén","vi":"giật gân"},{"hanzi":"夸大其词","pinyin":"kuādàqící","vi":"phóng đại sự việc"},{"hanzi":"制造恐慌","pinyin":"zhìzàokǒnghuāng","vi":"gây hoang mang"},{"hanzi":"谣言","pinyin":"yáoyán","vi":"tin đồn"}],"traditional":"危言聳聽"},{"id":"温带","hanzi":"温带","pinyin":"wēndài","meaning_vi":"ôn đới","explanation":"温 (ấm) + 带 (vùng/đới).","hsk_level":6,"tags":["danh-tu","thien-nhien","khoa-hoc"],"image":"🌍","examples":[{"type":"basic","zh":"这里属于温带。","pinyin":"Zhèlǐ shǔyú wēndài.","vi":"Nơi này thuộc vùng ôn đới."},{"type":"simple","zh":"温带地区一年四季分明。","pinyin":"Wēndài dìqū yì nián sìjì fēnmíng.","vi":"Vùng ôn đới một năm bốn mùa rõ rệt."},{"type":"compound","zh":"因为这种苹果只适合温带气候，所以在热带很难种活。","pinyin":"Yīnwèi zhè zhǒng píngguǒ zhǐ shìhé wēndài qìhòu, suǒyǐ zài rèdài hěn nán zhòng huó.","vi":"Vì loại táo này chỉ hợp khí hậu ôn đới nên ở vùng nhiệt đới rất khó trồng."}],"related":[{"hanzi":"热带","pinyin":"rèdài","vi":"nhiệt đới"},{"hanzi":"寒带","pinyin":"hándài","vi":"hàn đới"},{"hanzi":"亚热带","pinyin":"yàrèdài","vi":"cận nhiệt đới"},{"hanzi":"气候","pinyin":"qìhòu","vi":"khí hậu"}],"traditional":"溫帶"},{"id":"温顺","hanzi":"温顺","pinyin":"wēnshùn","meaning_vi":"hiền lành, ngoan ngoãn (thú nuôi/tính cách)","explanation":"温 (ôn hòa) + 顺 (thuận theo).","hsk_level":6,"tags":["tinh-tu","dong-vat"],"image":"🐑","examples":[{"type":"basic","zh":"这只羊很温顺。","pinyin":"Zhè zhī yáng hěn wēnshùn.","vi":"Con cừu này rất hiền lành."},{"type":"simple","zh":"她性格温顺，从来不跟人吵架。","pinyin":"Tā xìnggé wēnshùn, cóngláibù gēn rén chǎojià.","vi":"Cô ấy tính tình hiền lành, chưa bao giờ cãi nhau với ai."},{"type":"compound","zh":"这匹马看起来很温顺，可是一受惊就会乱跑。","pinyin":"Zhè pǐ mǎ kànqǐlái hěn wēnshùn, kěshì yí shòujīng jiù huì luànpǎo.","vi":"Con ngựa này trông rất ngoan ngoãn, nhưng hễ bị hoảng là chạy loạn."}],"related":[{"hanzi":"温和","pinyin":"wēnhé","vi":"ôn hòa"},{"hanzi":"顺从","pinyin":"shùncóng","vi":"phục tùng"},{"hanzi":"乖巧","pinyin":"guāiqiǎo","vi":"ngoan ngoãn"},{"hanzi":"凶猛","pinyin":"xiōngměng","vi":"hung dữ"}],"traditional":"溫順"},{"id":"尾声","hanzi":"尾声","pinyin":"wěishēng","meaning_vi":"hồi kết, phần cuối","explanation":"尾 (đuôi) + 声 (âm thanh).","hsk_level":6,"tags":["danh-tu","giai-tri"],"image":"🎬","examples":[{"type":"basic","zh":"晚会接近尾声。","pinyin":"Wǎnhuì jiējìn wěishēng.","vi":"Buổi dạ hội sắp đến hồi kết."},{"type":"simple","zh":"到了故事的尾声，主人公终于回到了家乡。","pinyin":"Dàole gùshi de wěishēng, zhǔréngōng zhōngyú huídàole jiāxiāng.","vi":"Đến phần kết của câu chuyện, nhân vật chính cuối cùng cũng trở về quê hương."},{"type":"compound","zh":"虽然工程已经进入尾声，但是安全检查一点也不能放松。","pinyin":"Suīrán gōngchéng yǐjīng jìnrù wěishēng, dànshì ānquán jiǎnchá yìdiǎn yě bù néng fàngsōng.","vi":"Tuy công trình đã bước vào giai đoạn cuối, nhưng kiểm tra an toàn không được lơi lỏng chút nào."}],"related":[{"hanzi":"结尾","pinyin":"jiéwěi","vi":"phần kết"},{"hanzi":"接近尾声","pinyin":"jiējìnwěishēng","vi":"sắp kết thúc"},{"hanzi":"序幕","pinyin":"xùmù","vi":"màn mở đầu"},{"hanzi":"高潮","pinyin":"gāocháo","vi":"cao trào"}],"traditional":"尾聲"},{"id":"纬线","hanzi":"纬线","pinyin":"Wěixiàn","meaning_vi":"vĩ tuyến","explanation":"纬 + 线 (đường). Đối ứng với 经线 (kinh tuyến).","hsk_level":6,"tags":["danh-tu","khoa-hoc","dia-danh"],"image":"🌐","examples":[{"type":"basic","zh":"赤道是最长的纬线。","pinyin":"Chìdào shì zuì cháng de Wěixiàn.","vi":"Xích đạo là vĩ tuyến dài nhất."},{"type":"simple","zh":"地图上横着画的线叫纬线。","pinyin":"Dìtú shang héngzhe huà de xiàn jiào Wěixiàn.","vi":"Những đường kẻ ngang trên bản đồ gọi là vĩ tuyến."},{"type":"compound","zh":"只要知道经线和纬线，就能确定地球上任何一个地点。","pinyin":"Zhǐyào zhīdào jīngxiàn hé Wěixiàn, jiù néng quèdìng dìqiú shang rènhé yí gè dìdiǎn.","vi":"Chỉ cần biết kinh tuyến và vĩ tuyến là có thể xác định bất kỳ địa điểm nào trên Trái Đất."}],"related":[{"hanzi":"经线","pinyin":"jīngxiàn","vi":"kinh tuyến"},{"hanzi":"纬度","pinyin":"Wěidù","vi":"vĩ độ"},{"hanzi":"赤道","pinyin":"Chìdào","vi":"xích đạo"},{"hanzi":"地球仪","pinyin":"dìqiúyí","vi":"quả địa cầu"}],"traditional":"緯線"},{"id":"伪装","hanzi":"伪装","pinyin":"wěizhuāng","meaning_vi":"ngụy trang, giả trang","explanation":"伪 (giả) + 装 (trang điểm/mặc).","hsk_level":6,"tags":["dong-tu"],"image":"🎭","examples":[{"type":"basic","zh":"变色龙善于伪装。","pinyin":"Biànsèlóng shànyú wěizhuāng.","vi":"Tắc kè hoa giỏi ngụy trang."},{"type":"simple","zh":"士兵们用树枝伪装了坦克。","pinyin":"Shìbīngmen yòng shùzhī wěizhuāngle tǎnkè.","vi":"Những người lính dùng cành cây ngụy trang xe tăng."},{"type":"compound","zh":"他伪装得再好，也骗不过经验丰富的老警察。","pinyin":"Tā wěizhuāng de zài hǎo, yě piàn buguò jīngyàn fēngfù de lǎo jǐngchá.","vi":"Hắn có ngụy trang khéo đến đâu cũng không qua mắt được viên cảnh sát lão luyện."}],"related":[{"hanzi":"假装","pinyin":"jiǎzhuāng","vi":"giả vờ"},{"hanzi":"掩饰","pinyin":"yǎnshì","vi":"che đậy"},{"hanzi":"冒充","pinyin":"màochōng","vi":"mạo danh"},{"hanzi":"虚伪","pinyin":"xūwěi","vi":"giả dối"}],"traditional":"偽裝"},{"id":"稳步","hanzi":"稳步","pinyin":"wěnbù","meaning_vi":"vững bước, từng bước ổn định","explanation":"稳 (vững) + 步 (bước).","hsk_level":6,"tags":["pho-tu"],"image":"👣","examples":[{"type":"basic","zh":"销量稳步上升。","pinyin":"Xiāoliàng wěnbù shàngshēng.","vi":"Doanh số tăng lên ổn định."},{"type":"simple","zh":"这座城市的经济正在稳步发展。","pinyin":"Zhè zuò chéngshì de jīngjì zhèngzài wěnbù fāzhǎn.","vi":"Kinh tế thành phố này đang phát triển vững bước."},{"type":"compound","zh":"只要按计划稳步推进，项目年底前就能完成。","pinyin":"Zhǐyào àn jìhuà wěnbù tuījìn, xiàngmù niándǐ qián jiù néng wánchéng.","vi":"Chỉ cần từng bước triển khai ổn định theo kế hoạch, dự án sẽ hoàn thành trước cuối năm."}],"related":[{"hanzi":"稳定","pinyin":"wěndìng","vi":"ổn định"},{"hanzi":"逐步","pinyin":"zhúbù","vi":"từng bước"},{"hanzi":"稳步发展","pinyin":"wěnbùfāzhǎn","vi":"phát triển ổn định"},{"hanzi":"循序渐进","pinyin":"xúnxùjiànjìn","vi":"tuần tự tiến lên"}],"traditional":"穩步"},{"id":"稳固","hanzi":"稳固","pinyin":"wěngù","meaning_vi":"vững chắc, kiên cố","explanation":"稳 (ổn – vững) + 固 (cố – chắc) → vững chắc, ổn định. Cụm: 地位稳固, 稳固基础.","hsk_level":6,"tags":["tinh-tu"],"image":"🏰","examples":[{"type":"basic","zh":"地基非常稳固。","pinyin":"Dìjī fēicháng wěngù.","vi":"Nền móng vô cùng vững chắc."},{"type":"simple","zh":"两国建立了稳固的合作关系。","pinyin":"Liǎngguó jiànlìle wěngù de hézuò guānxì.","vi":"Hai nước đã xây dựng quan hệ hợp tác vững chắc."},{"type":"compound","zh":"这张桌子虽然很旧，但是放在地上依然很稳固。","pinyin":"Zhè zhāng zhuōzi suīrán hěn jiù, dànshì fàng zài dìshang yīrán hěn wěngù.","vi":"Cái bàn này tuy đã cũ, nhưng đặt dưới đất vẫn rất vững chãi."}],"related":[{"hanzi":"牢固","pinyin":"láogù","vi":"chắc chắn"},{"hanzi":"坚固","pinyin":"jiāngù","vi":"kiên cố"},{"hanzi":"巩固","pinyin":"gǒnggù","vi":"củng cố"},{"hanzi":"动摇","pinyin":"dòngyáo","vi":"lung lay"}],"traditional":"穩固"},{"id":"稳妥","hanzi":"稳妥","pinyin":"wěntuǒ","meaning_vi":"ổn thỏa, chắc chắn an toàn","explanation":"稳 + 妥 (thỏa đáng).","hsk_level":6,"tags":["tinh-tu"],"image":"✅","examples":[{"type":"basic","zh":"这个办法很稳妥。","pinyin":"Zhè ge bànfǎ hěn wěntuǒ.","vi":"Cách này rất ổn thỏa."},{"type":"simple","zh":"为了稳妥起见，我们还是提前出发吧。","pinyin":"Wèile wěntuǒ qǐjiàn, wǒmen háishi tíqián chūfā ba.","vi":"Để cho chắc chắn, chúng ta nên xuất phát sớm hơn."},{"type":"compound","zh":"把钱存银行虽然收益低，但是比炒股稳妥得多。","pinyin":"Bǎ qián cún yínháng suīrán shōuyì dī, dànshì bǐ chǎogǔ wěntuǒ de duō.","vi":"Gửi tiền ngân hàng tuy lãi thấp, nhưng an toàn hơn chơi chứng khoán nhiều."}],"related":[{"hanzi":"妥当","pinyin":"tuǒdang","vi":"thỏa đáng"},{"hanzi":"可靠","pinyin":"kěkào","vi":"đáng tin cậy"},{"hanzi":"稳当","pinyin":"wěndang","vi":"vững vàng"},{"hanzi":"冒险","pinyin":"màoxiǎn","vi":"mạo hiểm"}],"traditional":"穩妥"},{"id":"窝囊","hanzi":"窝囊","pinyin":"wōnang","meaning_vi":"bực bội, ấm ức; nhu nhược, hèn kém","explanation":"窝 (oa – ổ) + 囊 (nang – túi) → khẩu ngữ: ấm ức phải nhịn (受窝囊气); hoặc nhu nhược vô dụng (窝囊废).","hsk_level":6,"tags":["tinh-tu","cam-xuc"],"image":"😣","examples":[{"type":"basic","zh":"他活得真窝囊。","pinyin":"Tā huó de zhēn wōnang.","vi":"Anh ta sống thật nhu nhược."},{"type":"simple","zh":"被人冤枉了也不敢说，真窝囊！","pinyin":"Bèi rén yuānwangle yě bù gǎn shuō, zhēn wōnang!","vi":"Bị người ta đổ oan mà cũng không dám nói, thật ấm ức!"},{"type":"compound","zh":"他明明没做错，却挨了一顿骂，心里窝囊极了。","pinyin":"Tā míngmíng méi zuòcuò, què áile yí dùn mà, xīnlǐ wōnang jíle.","vi":"Rõ ràng anh ấy không làm sai mà vẫn bị mắng một trận, trong lòng ấm ức vô cùng."}],"related":[{"hanzi":"窝囊废","pinyin":"wōnangfèi","vi":"đồ vô dụng"},{"hanzi":"懦弱","pinyin":"nuòruò","vi":"nhu nhược"},{"hanzi":"憋屈","pinyin":"biēqu","vi":"ấm ức"},{"hanzi":"委屈","pinyin":"wěiqu","vi":"tủi thân"}],"traditional":"窩囊"},{"id":"污蔑","hanzi":"污蔑","pinyin":"wūmiè","meaning_vi":"vu khống, bôi nhọ","explanation":"污 (bẩn) + 蔑 (khinh miệt).","hsk_level":6,"tags":["dong-tu","phap-luat"],"image":"🗣️","examples":[{"type":"basic","zh":"你这是污蔑！","pinyin":"Nǐ zhè shì wūmiè!","vi":"Anh đang vu khống!"},{"type":"simple","zh":"有人在网上污蔑这位医生收红包。","pinyin":"Yǒurén zài wǎngshang wūmiè zhè wèi yīshēng shōu hóngbāo.","vi":"Có người lên mạng vu khống vị bác sĩ này nhận phong bì."},{"type":"compound","zh":"如果你继续污蔑我，我就去法院起诉你。","pinyin":"Rúguǒ nǐ jìxù wūmiè wǒ, wǒ jiù qù fǎyuàn qǐsù nǐ.","vi":"Nếu anh còn tiếp tục bôi nhọ tôi, tôi sẽ kiện anh ra tòa."}],"related":[{"hanzi":"诬蔑","pinyin":"wūmiè","vi":"vu khống"},{"hanzi":"诽谤","pinyin":"fěibàng","vi":"phỉ báng"},{"hanzi":"诬陷","pinyin":"wūxiàn","vi":"vu oan"},{"hanzi":"造谣","pinyin":"zàoyáo","vi":"tung tin đồn"}],"traditional":"污衊"},{"id":"乌鸦","hanzi":"乌鸦","pinyin":"wūyā","meaning_vi":"con quạ","explanation":"乌 (đen) + 鸦 (quạ).","hsk_level":6,"tags":["danh-tu","dong-vat"],"image":"🐦‍⬛","examples":[{"type":"basic","zh":"树上有只乌鸦。","pinyin":"Shù shang yǒu zhī wūyā.","vi":"Trên cây có một con quạ."},{"type":"simple","zh":"乌鸦把小石子一颗颗丢进瓶子里。","pinyin":"Wūyā bǎ xiǎo shízǐ yì kē kē diū jìn píngzi lǐ.","vi":"Con quạ thả từng viên sỏi nhỏ vào trong bình."},{"type":"compound","zh":"乌鸦一叫，奶奶就说不吉利，所以赶紧把它赶走了。","pinyin":"Wūyā yí jiào, nǎinai jiù shuō bù jílì, suǒyǐ gǎnjǐn bǎ tā gǎnzǒu le.","vi":"Quạ vừa kêu là bà nói không may mắn, nên vội vàng đuổi nó đi."}],"related":[{"hanzi":"喜鹊","pinyin":"xǐquè","vi":"chim khách"},{"hanzi":"鸟","pinyin":"niǎo","vi":"chim"},{"hanzi":"乌鸦嘴","pinyin":"wūyāzuǐ","vi":"miệng quạ nói gở"},{"hanzi":"黑色","pinyin":"hēisè","vi":"màu đen"}],"traditional":"烏鴉"},{"id":"瓦解","hanzi":"瓦解","pinyin":"wǎjiě","meaning_vi":"tan rã, sụp đổ","explanation":"瓦 (ngói) + 解 (tách rời).","hsk_level":6,"tags":["dong-tu"],"image":"💥","examples":[{"type":"basic","zh":"敌军迅速瓦解。","pinyin":"Díjūn xùnsù wǎjiě.","vi":"Quân địch nhanh chóng tan rã."},{"type":"simple","zh":"警方成功瓦解了一个诈骗团伙。","pinyin":"Jǐngfāng chénggōng wǎjiěle yí gè zhàpiàn tuánhuǒ.","vi":"Cảnh sát đã triệt phá thành công một băng nhóm lừa đảo."},{"type":"compound","zh":"因为内部矛盾越来越多，所以这个联盟很快就瓦解了。","pinyin":"Yīnwèi nèibù máodùn yuèláiyuè duō, suǒyǐ zhè ge liánméng hěn kuài jiù wǎjiě le.","vi":"Vì mâu thuẫn nội bộ ngày càng nhiều nên liên minh này nhanh chóng tan rã."}],"related":[{"hanzi":"崩溃","pinyin":"bēngkuì","vi":"sụp đổ"},{"hanzi":"解体","pinyin":"jiětǐ","vi":"tan rã"},{"hanzi":"土崩瓦解","pinyin":"tǔbēngwǎjiě","vi":"tan đàn xẻ nghé"},{"hanzi":"分裂","pinyin":"fēnliè","vi":"chia rẽ"}]},{"id":"挽回","hanzi":"挽回","pinyin":"wǎnhuí","meaning_vi":"vãn hồi, cứu vãn (tình thế/tổn thất)","explanation":"挽 (kéo) + 回 (quay lại).","hsk_level":6,"tags":["dong-tu"],"image":"🔄","examples":[{"type":"basic","zh":"损失无法挽回。","pinyin":"Sǔnshī wúfǎ wǎnhuí.","vi":"Tổn thất không thể cứu vãn."},{"type":"simple","zh":"他送了一束花，想挽回女朋友的心。","pinyin":"Tā sòngle yíshùhuā, xiǎng wǎnhuí nǚpéngyou de xīn.","vi":"Anh ấy tặng một bó hoa, muốn níu kéo lại trái tim bạn gái."},{"type":"compound","zh":"如果公司及时道歉，就还能挽回一部分声誉。","pinyin":"Rúguǒ gōngsī jíshí dàoqiàn, jiù hái néng wǎnhuí yíbùfen shēngyù.","vi":"Nếu công ty kịp thời xin lỗi thì vẫn có thể vãn hồi một phần danh tiếng."}],"related":[{"hanzi":"挽救","pinyin":"wǎnjiù","vi":"cứu vãn"},{"hanzi":"弥补","pinyin":"míbǔ","vi":"bù đắp"},{"hanzi":"挽回损失","pinyin":"wǎnhuísǔnshī","vi":"gỡ lại tổn thất"},{"hanzi":"无可挽回","pinyin":"wúkěwǎnhuí","vi":"không thể cứu vãn"}]},{"id":"网罗","hanzi":"网罗","pinyin":"wǎngluó","meaning_vi":"thu hút, tập hợp (nhân tài/thông tin)","explanation":"网 (lưới) + 罗 (thu gom).","hsk_level":6,"tags":["dong-tu"],"image":"🕸️","examples":[{"type":"basic","zh":"公司网罗了不少人才。","pinyin":"Gōngsī wǎngluóle bùshǎo réncái.","vi":"Công ty đã thu hút được không ít nhân tài."},{"type":"simple","zh":"这本词典网罗了几万条常用成语。","pinyin":"Zhè běn cídiǎn wǎngluóle jǐ wàn tiáo chángyòng chéngyǔ.","vi":"Cuốn từ điển này tập hợp mấy vạn thành ngữ thường dùng."},{"type":"compound","zh":"为了网罗顶尖科学家，这所大学不但提供高薪，而且分配住房。","pinyin":"Wèile wǎngluó dǐngjiān kēxuéjiā, zhè suǒ dàxué búdàn tígōng gāoxīn, érqiě fēnpèi zhùfáng.","vi":"Để thu hút các nhà khoa học hàng đầu, trường đại học này không những trả lương cao mà còn cấp nhà ở."}],"related":[{"hanzi":"招揽","pinyin":"zhāolǎn","vi":"chiêu mộ"},{"hanzi":"搜罗","pinyin":"sōuluó","vi":"thu thập"},{"hanzi":"招聘","pinyin":"zhāopìn","vi":"tuyển dụng"},{"hanzi":"人才","pinyin":"réncái","vi":"nhân tài"}],"traditional":"網羅"},{"id":"往日","hanzi":"往日","pinyin":"wǎngrì","meaning_vi":"ngày xưa, trước đây","explanation":"往 (quá khứ) + 日 (ngày).","hsk_level":6,"tags":["danh-tu","thoi-gian"],"image":"⏪","examples":[{"type":"basic","zh":"往日的朋友都散了。","pinyin":"Wǎngrì de péngyou dōu sàn le.","vi":"Bạn bè ngày xưa đều tản mát cả rồi."},{"type":"simple","zh":"老街早已没有了往日的热闹。","pinyin":"Lǎojiē zǎoyǐ méiyǒule wǎngrì de rènao.","vi":"Phố cổ từ lâu đã không còn náo nhiệt như ngày trước."},{"type":"compound","zh":"他往日总是第一个到办公室，今天却迟到了一个小时。","pinyin":"Tā wǎngrì zǒngshì dìyī gè dào bàngōngshì, jīntiān què chídàole yí gè xiǎoshí.","vi":"Ngày trước anh ấy luôn là người đến văn phòng đầu tiên, hôm nay lại đến muộn một tiếng."}],"related":[{"hanzi":"昔日","pinyin":"xīrì","vi":"ngày xưa"},{"hanzi":"过去","pinyin":"guòqù","vi":"quá khứ"},{"hanzi":"以往","pinyin":"yǐwǎng","vi":"trước đây"},{"hanzi":"今日","pinyin":"jīnrì","vi":"hôm nay"}]},{"id":"捂","hanzi":"捂","pinyin":"wǔ","meaning_vi":"bịt, che (miệng/mắt/tai)","explanation":"Bộ tài gảy 扌+ 吾. Cụm: 捂住嘴巴 (bịt miệng lại).","hsk_level":6,"tags":["dong-tu"],"image":"🤭","examples":[{"type":"basic","zh":"她捂着嘴笑了。","pinyin":"Tā wǔzhe zuǐ xiào le.","vi":"Cô ấy che miệng cười."},{"type":"simple","zh":"放鞭炮时，孩子们赶紧捂住耳朵。","pinyin":"Fàngbiānpào shí, háizimen gǎnjǐn wǔzhù ěrduo.","vi":"Khi đốt pháo, bọn trẻ vội vàng bịt tai lại."},{"type":"compound","zh":"看恐怖片时她一害怕就捂住眼睛，可是又忍不住从指缝里偷看。","pinyin":"Kàn kǒngbù piànshí tā yí hàipà jiù wǔzhù yǎnjing, kěshì yòu rěnbuzhù cóng zhǐ fèng lǐ tōukàn.","vi":"Xem phim kinh dị, hễ sợ là cô ấy lấy tay che mắt, nhưng lại không nhịn được nhìn trộm qua kẽ tay."}],"related":[{"hanzi":"捂住","pinyin":"wǔzhù","vi":"bịt chặt"},{"hanzi":"遮","pinyin":"zhē","vi":"che"},{"hanzi":"盖","pinyin":"gài","vi":"đậy"},{"hanzi":"捂嘴","pinyin":"wǔzuǐ","vi":"bịt miệng"}]},{"id":"五颜六色","hanzi":"五颜六色","pinyin":"wǔyán-liùsè","meaning_vi":"đủ màu sắc sặc sỡ","explanation":"五颜 (năm sắc) + 六色 (sáu màu) → nhiều màu sắc, sặc sỡ đủ màu.","hsk_level":6,"tags":["thanh-ngu","mau-sac"],"image":"🌈","examples":[{"type":"basic","zh":"花园里五颜六色。","pinyin":"Huāyuán lǐ wǔyánliùsè.","vi":"Trong vườn hoa đủ màu sặc sỡ."},{"type":"simple","zh":"天空中飘着五颜六色的气球。","pinyin":"Tiānkōng zhōng piāozhe wǔyánliùsè de qìqiú.","vi":"Trên bầu trời bay lơ lửng những quả bóng bay đủ màu sắc."},{"type":"compound","zh":"一到秋天，山上的树叶就变得五颜六色，美极了。","pinyin":"Yí dào qiūtiān, shān shang de shùyè jiù biànde wǔyánliùsè, měi jíle.","vi":"Cứ đến mùa thu, lá cây trên núi lại chuyển sang đủ màu sặc sỡ, đẹp vô cùng."}],"related":[{"hanzi":"色彩","pinyin":"sècǎi","vi":"màu sắc"},{"hanzi":"五彩缤纷","pinyin":"wǔcǎibīnfēn","vi":"rực rỡ sắc màu"},{"hanzi":"多彩","pinyin":"duōcǎi","vi":"nhiều màu"},{"hanzi":"色彩斑斓","pinyin":"sècǎibānlán","vi":"sặc sỡ"}],"traditional":"五顏六色"},{"id":"武装","hanzi":"武装","pinyin":"wǔzhuāng","meaning_vi":"vũ trang, trang bị","explanation":"武 + 装 (trang bị).","hsk_level":6,"tags":["dong-tu","xa-hoi"],"image":"🪖","examples":[{"type":"basic","zh":"敌人全副武装。","pinyin":"Dírén quánfù wǔzhuāng.","vi":"Quân địch vũ trang đầy đủ."},{"type":"simple","zh":"我们要用知识武装自己的头脑。","pinyin":"Wǒmen yào yòng zhīshi wǔzhuāng zìjǐ de tóunǎo.","vi":"Chúng ta phải dùng tri thức để trang bị cho đầu óc mình."},{"type":"compound","zh":"虽然村民没有武装，但是他们靠智慧打败了强盗。","pinyin":"Suīrán cūnmín méiyǒu wǔzhuāng, dànshì tāmen kào zhìhuì dǎbàile qiángdào.","vi":"Tuy dân làng không có vũ trang, nhưng họ đã dùng trí khôn đánh bại bọn cướp."}],"related":[{"hanzi":"武器","pinyin":"wǔqì","vi":"vũ khí"},{"hanzi":"军队","pinyin":"jūnduì","vi":"quân đội"},{"hanzi":"武装力量","pinyin":"wǔzhuānglìliàng","vi":"lực lượng vũ trang"},{"hanzi":"装备","pinyin":"zhuāngbèi","vi":"trang bị"}],"traditional":"武裝"},{"id":"现成","hanzi":"现成","pinyin":"xiànchéng","meaning_vi":"có sẵn","explanation":"现 (hiện – sẵn có) + 成 (thành – xong) → có sẵn, làm sẵn. Thường: 现成的饭, 现成的答案.","hsk_level":6,"tags":["tinh-tu"],"image":"🍱","examples":[{"type":"basic","zh":"冰箱里有现成的饭。","pinyin":"Bīngxiāng lǐ yǒu xiànchéng de fàn.","vi":"Trong tủ lạnh có sẵn cơm."},{"type":"simple","zh":"他总想捡现成的便宜，不肯自己动手。","pinyin":"Tā zǒng xiǎng jiǎn xiànchéng de piányi, bùkěn zìjǐ dòngshǒu.","vi":"Anh ta luôn muốn hưởng lợi có sẵn, không chịu tự mình làm."},{"type":"compound","zh":"既然有现成的模板，你就不用从头开始做了。","pinyin":"Jìrán yǒu xiànchéng de múbǎn, nǐ jiù bú yòng cóngtóu kāishǐ zuò le.","vi":"Đã có mẫu có sẵn thì bạn không cần làm lại từ đầu."}],"related":[{"hanzi":"现成的","pinyin":"xiànchéngde","vi":"đồ có sẵn"},{"hanzi":"现有","pinyin":"xiànyǒu","vi":"hiện có"},{"hanzi":"准备好","pinyin":"zhǔnbèihǎo","vi":"chuẩn bị xong"},{"hanzi":"现成饭","pinyin":"xiànchéngfàn","vi":"cơm có sẵn"}],"traditional":"現成"},{"id":"宪法","hanzi":"宪法","pinyin":"xiànfǎ","meaning_vi":"hiến pháp","explanation":"宪 (hiến) + 法 (pháp – luật) → hiến pháp, đạo luật cơ bản của nhà nước. Thường: 遵守宪法.","hsk_level":6,"tags":["danh-tu","phap-luat"],"image":"📜","examples":[{"type":"basic","zh":"宪法是根本大法。","pinyin":"Xiànfǎ shì gēnběn dà fǎ.","vi":"Hiến pháp là luật cơ bản."},{"type":"simple","zh":"每个公民都应该遵守宪法。","pinyin":"Měi gè gōngmín dōu yīnggāi zūnshǒu xiànfǎ.","vi":"Mỗi công dân đều phải tuân thủ hiến pháp."},{"type":"compound","zh":"宪法不但规定了公民的权利，而且规定了公民的义务。","pinyin":"Xiànfǎ búdàn guīdìngle gōngmín de quánlì, érqiě guīdìngle gōngmín de yìwù.","vi":"Hiến pháp không những quy định quyền lợi mà còn quy định nghĩa vụ của công dân."}],"related":[{"hanzi":"法律","pinyin":"fǎlǜ","vi":"pháp luật"},{"hanzi":"法规","pinyin":"fǎguī","vi":"pháp quy"},{"hanzi":"违宪","pinyin":"wéixiàn","vi":"vi hiến"},{"hanzi":"国家","pinyin":"guójiā","vi":"quốc gia"}],"traditional":"憲法"},{"id":"向来","hanzi":"向来","pinyin":"xiànglái","meaning_vi":"xưa nay","explanation":"向 (hướng – từ trước) + 来 (lai – đến nay) → từ trước đến nay, xưa nay vẫn vậy. Thường: 他向来很守时.","hsk_level":6,"tags":["pho-tu"],"image":"♾️","examples":[{"type":"basic","zh":"他向来很守时。","pinyin":"Tā xiànglái hěn shǒushí.","vi":"Xưa nay anh ấy rất đúng giờ."},{"type":"simple","zh":"我们家向来是爸爸做饭，妈妈洗碗。","pinyin":"Wǒmen jiā xiànglái shì bàba zuòfàn, māma xǐwǎn.","vi":"Nhà tôi xưa nay bố nấu cơm, mẹ rửa bát."},{"type":"compound","zh":"她向来不爱说话，所以今天的发言让大家很意外。","pinyin":"Tā xiànglái bú ài shuōhuà, suǒyǐ jīntiān de fāyán ràng dàjiā hěn yìwài.","vi":"Xưa nay cô ấy ít nói, nên bài phát biểu hôm nay khiến mọi người rất bất ngờ."}],"related":[{"hanzi":"一向","pinyin":"yíxiàng","vi":"xưa nay"},{"hanzi":"从来","pinyin":"cónglái","vi":"từ trước đến nay"},{"hanzi":"一直","pinyin":"yìzhí","vi":"luôn luôn"},{"hanzi":"历来","pinyin":"lìlái","vi":"từ xưa"}],"traditional":"向來"},{"id":"效益","hanzi":"效益","pinyin":"xiàoyì","meaning_vi":"hiệu quả kinh tế","explanation":"效 (hiệu – hiệu quả) + 益 (ích – lợi ích) → hiệu quả và lợi ích thu được. Thường: 经济效益, 社会效益.","hsk_level":6,"tags":["danh-tu","cong-viec"],"image":"📈","examples":[{"type":"basic","zh":"今年效益不错。","pinyin":"Jīnnián xiàoyì búcuò.","vi":"Năm nay hiệu quả kinh tế khá tốt."},{"type":"simple","zh":"这家工厂的经济效益逐年下降。","pinyin":"Zhè jiā gōngchǎng de jīngjì xiàoyì zhúnián xiàjiàng.","vi":"Hiệu quả kinh tế của nhà máy này giảm dần qua từng năm."},{"type":"compound","zh":"如果公司效益好，年底员工就能多拿奖金。","pinyin":"Rúguǒ gōngsī xiàoyì hǎo, niándǐ yuángōng jiù néng duō ná jiǎngjīn.","vi":"Nếu công ty làm ăn hiệu quả, cuối năm nhân viên sẽ được thưởng nhiều hơn."}],"related":[{"hanzi":"经济效益","pinyin":"jīngjìxiàoyì","vi":"hiệu quả kinh tế"},{"hanzi":"效率","pinyin":"xiàolǜ","vi":"hiệu suất"},{"hanzi":"利润","pinyin":"lìrùn","vi":"lợi nhuận"},{"hanzi":"收益","pinyin":"shōuyì","vi":"lợi ích thu được"}]},{"id":"狭窄","hanzi":"狭窄","pinyin":"xiázhǎi","meaning_vi":"chật hẹp","explanation":"狭 (hiệp – hẹp) + 窄 (trách – chật) → chật hẹp; nghĩa bóng: hẹp hòi. Thường: 道路狭窄, 心胸狭窄.","hsk_level":6,"tags":["tinh-tu"],"image":"↔️","examples":[{"type":"basic","zh":"这条胡同很狭窄。","pinyin":"Zhè tiáo hútòng hěn xiázhǎi.","vi":"Con ngõ này rất chật hẹp."},{"type":"simple","zh":"狭窄的楼梯只能容一个人通过。","pinyin":"Xiázhǎi de lóutī zhǐnéng róng yígèrén tōngguò.","vi":"Cầu thang chật hẹp chỉ đủ cho một người đi qua."},{"type":"compound","zh":"他不但房间狭窄，而且心胸也很狭窄，一点小事就生气。","pinyin":"Tā búdàn fángjiān xiázhǎi, érqiě xīnxiōng yě hěn xiázhǎi, yìdiǎn xiǎoshì jiù shēngqì.","vi":"Anh ta không những phòng ở chật hẹp mà lòng dạ cũng hẹp hòi, chuyện nhỏ cũng nổi giận."}],"related":[{"hanzi":"宽敞","pinyin":"kuānchang","vi":"rộng rãi"},{"hanzi":"窄","pinyin":"zhǎi","vi":"hẹp"},{"hanzi":"狭小","pinyin":"xiáxiǎo","vi":"chật hẹp"},{"hanzi":"拥挤","pinyin":"yōngjǐ","vi":"chen chúc"}],"traditional":"狹窄"},{"id":"闲话","hanzi":"闲话","pinyin":"xiánhuà","meaning_vi":"chuyện phiếm; lời đàm tiếu, lời ra tiếng vào","explanation":"闲 (nhàn – rảnh) + 话 (lời) → chuyện phiếm; cũng là lời đàm tiếu sau lưng. Thường: 说闲话.","hsk_level":6,"tags":["danh-tu","giao-tiep"],"image":"💬","examples":[{"type":"basic","zh":"别说别人闲话。","pinyin":"Biéshuō biérén xiánhuà.","vi":"Đừng đàm tiếu về người khác."},{"type":"simple","zh":"几个邻居坐在树下说闲话。","pinyin":"Jǐ gè línjū zuò zài shù xià shuōxiánhuà.","vi":"Mấy người hàng xóm ngồi dưới gốc cây tán chuyện phiếm."},{"type":"compound","zh":"她怕别人说闲话，所以一直不敢告诉家人自己离婚了。","pinyin":"Tā pà biérén shuōxiánhuà, suǒyǐ yìzhí bù gǎn gàosu jiārén zìjǐ líhūn le.","vi":"Cô ấy sợ người ta đàm tiếu nên mãi không dám nói với gia đình mình đã ly hôn."}],"related":[{"hanzi":"闲聊","pinyin":"xiánliáo","vi":"tán gẫu"},{"hanzi":"聊天","pinyin":"liáotiān","vi":"nói chuyện"},{"hanzi":"八卦","pinyin":"bāguà","vi":"chuyện phiếm"},{"hanzi":"说闲话","pinyin":"shuōxiánhuà","vi":"nói ra nói vào"}],"traditional":"閒話"},{"id":"嫌疑","hanzi":"嫌疑","pinyin":"xiányí","meaning_vi":"tình nghi","explanation":"嫌 (hiềm – nghi ngờ) + 疑 (nghi) → sự tình nghi. Thường: 嫌疑人 (nghi phạm), 有嫌疑.","hsk_level":6,"tags":["danh-tu","phap-luat"],"image":"🕵️","examples":[{"type":"basic","zh":"他有作案嫌疑。","pinyin":"Tā yǒu zuò'àn xiányí.","vi":"Anh ta bị tình nghi gây án."},{"type":"simple","zh":"警方排除了司机的嫌疑。","pinyin":"Jǐngfāng páichúle sījī de xiányí.","vi":"Cảnh sát đã loại trừ nghi vấn đối với tài xế."},{"type":"compound","zh":"因为他案发时不在现场，所以很快就洗清了嫌疑。","pinyin":"Yīnwèi tā ànfā shí bú zài xiànchǎng, suǒyǐ hěn kuài jiù xǐ qīngle xiányí.","vi":"Vì lúc xảy ra vụ án anh ta không có mặt tại hiện trường nên nhanh chóng được rửa sạch nghi ngờ."}],"related":[{"hanzi":"嫌疑人","pinyin":"xiányírén","vi":"nghi phạm"},{"hanzi":"怀疑","pinyin":"huáiyí","vi":"nghi ngờ"},{"hanzi":"犯罪嫌疑","pinyin":"fànzuìxiányí","vi":"tình nghi phạm tội"},{"hanzi":"疑点","pinyin":"yídiǎn","vi":"điểm đáng ngờ"}]},{"id":"谢绝","hanzi":"谢绝","pinyin":"xièjué","meaning_vi":"từ chối khéo","explanation":"谢 (tạ – từ tạ) + 绝 (tuyệt – dứt) → khéo léo từ chối. Thường: 谢绝参观, 谢绝好意.","hsk_level":6,"tags":["dong-tu"],"image":"🙇","examples":[{"type":"basic","zh":"本店谢绝还价。","pinyin":"Běn diàn xièjué huán jià.","vi":"Cửa hàng xin miễn trả giá."},{"type":"simple","zh":"她礼貌地谢绝了对方的邀请。","pinyin":"Tā lǐmào de xièjuéle duìfāng de yāoqǐng.","vi":"Cô ấy lịch sự từ chối lời mời của đối phương."},{"type":"compound","zh":"展厅里的文物很珍贵，所以谢绝游客拍照。","pinyin":"Zhǎntīng lǐ de wénwù hěn zhēnguì, suǒyǐ xièjué yóukè pāizhào.","vi":"Cổ vật trong phòng trưng bày rất quý nên du khách vui lòng không chụp ảnh."}],"related":[{"hanzi":"拒绝","pinyin":"jùjué","vi":"từ chối"},{"hanzi":"婉拒","pinyin":"wǎnjù","vi":"từ chối khéo"},{"hanzi":"谢绝参观","pinyin":"xièjuécānguān","vi":"miễn tham quan"},{"hanzi":"推辞","pinyin":"tuīcí","vi":"thoái thác"}],"traditional":"謝絕"},{"id":"泄露","hanzi":"泄露","pinyin":"xièlòu","meaning_vi":"tiết lộ, rò rỉ","explanation":"泄 (tiết – rò ra) + 露 (lộ – lộ ra) → để lộ ra ngoài điều cần giữ kín. Thường: 泄露秘密, 泄露信息.","hsk_level":6,"tags":["dong-tu"],"image":"🔓","examples":[{"type":"basic","zh":"消息泄露了。","pinyin":"Xiāoxi xièlòu le.","vi":"Tin tức đã bị rò rỉ."},{"type":"simple","zh":"有员工把公司机密泄露给了对手。","pinyin":"Yǒu yuángōng bǎ gōngsī jīmì xièlòu gěile duìshǒu.","vi":"Có nhân viên đã tiết lộ bí mật công ty cho đối thủ."},{"type":"compound","zh":"如果用户信息被泄露，那么网站要承担法律责任。","pinyin":"Rúguǒ yònghù xìnxī bèi xièlòu, nàme wǎngzhàn yào chéngdān fǎlǜ zérèn.","vi":"Nếu thông tin người dùng bị rò rỉ thì trang web phải chịu trách nhiệm pháp lý."}],"related":[{"hanzi":"泄密","pinyin":"xièmì","vi":"lộ bí mật"},{"hanzi":"透露","pinyin":"tòulù","vi":"tiết lộ"},{"hanzi":"保密","pinyin":"bǎomì","vi":"giữ bí mật"},{"hanzi":"暴露","pinyin":"bàolù","vi":"lộ ra"}],"traditional":"洩露"},{"id":"协调","hanzi":"协调","pinyin":"xiétiáo","meaning_vi":"điều phối, phối hợp; hài hòa, cân đối","explanation":"协 (hiệp – phối hợp) + 调 (điều – điều chỉnh) → điều phối cho nhịp nhàng; tính từ: hài hòa. Thường: 协调工作, 颜色很协调.","hsk_level":6,"tags":["dong-tu"],"image":"🎶","examples":[{"type":"basic","zh":"他负责协调工作。","pinyin":"Tā fùzé xiétiáo gōngzuò.","vi":"Anh ấy phụ trách điều phối công việc."},{"type":"simple","zh":"经理正在协调两个部门之间的矛盾。","pinyin":"Jīnglǐ zhèngzài xiétiáo liǎng gè bùmén zhījiān de máodùn.","vi":"Giám đốc đang điều phối mâu thuẫn giữa hai phòng ban."},{"type":"compound","zh":"只要各方协调好时间，会议就能按时召开。","pinyin":"Zhǐyào gèfāng xiétiáo hǎo shíjiān, huìyì jiù néng ànshí zhàokāi.","vi":"Chỉ cần các bên sắp xếp phối hợp thời gian tốt thì cuộc họp sẽ được tổ chức đúng giờ."}],"related":[{"hanzi":"协商","pinyin":"xiéshāng","vi":"hiệp thương"},{"hanzi":"配合","pinyin":"pèihé","vi":"phối hợp"},{"hanzi":"调和","pinyin":"tiáohé","vi":"điều hòa"},{"hanzi":"不协调","pinyin":"bùxiétiáo","vi":"không hài hòa"}],"traditional":"協調"},{"id":"先例","hanzi":"先例","pinyin":"xiānlì","meaning_vi":"tiền lệ","explanation":"先 (trước) + 例 (ví dụ/quy tắc).","hsk_level":6,"tags":["danh-tu","phap-luat"],"image":"📜","examples":[{"type":"basic","zh":"这件事没有先例。","pinyin":"Zhè jiàn shì méiyǒu xiānlì.","vi":"Việc này chưa có tiền lệ."},{"type":"simple","zh":"学校从没有过提前毕业的先例。","pinyin":"Xuéxiào cóng méiyǒuguo tíqián bìyè de xiānlì.","vi":"Trường chưa từng có tiền lệ tốt nghiệp sớm."},{"type":"compound","zh":"如果这次给你开了先例，那么以后别人也会提同样的要求。","pinyin":"Rúguǒ zhè cì gěi nǐ kāile xiānlì, nàme yǐhòu biérén yě huì tí tóngyàng de yāoqiú.","vi":"Nếu lần này mở tiền lệ cho anh thì sau này người khác cũng sẽ đưa ra yêu cầu tương tự."}],"related":[{"hanzi":"前例","pinyin":"qiánlì","vi":"tiền lệ"},{"hanzi":"史无前例","pinyin":"shǐwúqiánlì","vi":"chưa từng có"},{"hanzi":"惯例","pinyin":"guànlì","vi":"thông lệ"},{"hanzi":"例子","pinyin":"lìzi","vi":"ví dụ"}]},{"id":"相辅相成","hanzi":"相辅相成","pinyin":"xiāngfǔ-xiāngchéng","meaning_vi":"bổ sung hỗ trợ nhau","explanation":"相辅 (giúp đỡ nhau) + 相成 (hoàn thiện nhau) → hai bên bổ trợ cho nhau, thiếu một không được.","hsk_level":6,"tags":["thanh-ngu"],"image":"🤝","examples":[{"type":"basic","zh":"二者相辅相成。","pinyin":"Èrzhě xiāngfǔxiāngchéng.","vi":"Hai thứ bổ trợ cho nhau."},{"type":"simple","zh":"理论和实践是相辅相成的。","pinyin":"Lǐlùn hé shíjiàn shì xiāngfǔxiāngchéng de.","vi":"Lý thuyết và thực tiễn bổ sung hỗ trợ lẫn nhau."},{"type":"compound","zh":"读书和旅行相辅相成，一个开阔思路，一个丰富见闻。","pinyin":"Dúshū hé lǚxíng xiāngfǔxiāngchéng, yí gè kāikuò sīlù, yí gè fēngfù jiànwén.","vi":"Đọc sách và du lịch bổ trợ cho nhau, một cái mở mang tư duy, một cái làm phong phú hiểu biết."}],"related":[{"hanzi":"相得益彰","pinyin":"xiāngdéyìzhāng","vi":"bổ trợ cho nhau"},{"hanzi":"互补","pinyin":"hùbǔ","vi":"bổ sung lẫn nhau"},{"hanzi":"相互促进","pinyin":"xiānghùcùjìn","vi":"thúc đẩy lẫn nhau"},{"hanzi":"相反相成","pinyin":"xiāngfǎnxiāngchéng","vi":"đối lập mà bổ sung"}],"traditional":"相輔相成"},{"id":"相提并论","hanzi":"相提并论","pinyin":"xiāngtí-bìnglùn","meaning_vi":"đánh đồng, đặt ngang hàng để so sánh","explanation":"相提 (cùng nêu ra) + 并论 (tịnh luận – cùng bàn) → đặt ngang hàng mà so sánh; thường dùng phủ định: 不能相提并论.","hsk_level":6,"tags":["thanh-ngu"],"image":"⚖️","examples":[{"type":"basic","zh":"二者不能相提并论。","pinyin":"Èrzhě bù néng xiāngtíbìnglùn.","vi":"Hai thứ không thể đánh đồng với nhau."},{"type":"simple","zh":"他的作品怎么能和大师相提并论？","pinyin":"Tā de zuòpǐn zěnme néng hé dàshī xiāngtíbìnglùn?","vi":"Tác phẩm của anh ta sao có thể đặt ngang hàng với bậc thầy?"},{"type":"compound","zh":"虽然两家公司都卖手机，但是规模根本无法相提并论。","pinyin":"Suīrán liǎng jiā gōngsī dōu mài shǒujī, dànshì guīmó gēnběn wúfǎ xiāngtíbìnglùn.","vi":"Tuy hai công ty đều bán điện thoại, nhưng quy mô hoàn toàn không thể so sánh ngang hàng."}],"related":[{"hanzi":"混为一谈","pinyin":"hùnwéiyìtán","vi":"đánh đồng"},{"hanzi":"同日而语","pinyin":"tóngrì'éryǔ","vi":"đặt ngang hàng"},{"hanzi":"比较","pinyin":"bǐjiào","vi":"so sánh"},{"hanzi":"并列","pinyin":"bìngliè","vi":"song song"}],"traditional":"相提並論"},{"id":"乡镇","hanzi":"乡镇","pinyin":"xiāngzhèn","meaning_vi":"làng xã","explanation":"乡 (hương – làng) + 镇 (trấn – thị trấn) → đơn vị hành chính cấp xã, thị trấn ở nông thôn. Thường: 乡镇企业.","hsk_level":6,"tags":["danh-tu","dia-diem"],"image":"🏘️","examples":[{"type":"basic","zh":"他在乡镇工作。","pinyin":"Tā zài xiāngzhèn gōngzuò.","vi":"Anh ấy làm việc ở xã."},{"type":"simple","zh":"这几年乡镇企业发展得很快。","pinyin":"Zhè jǐ nián xiāngzhèn qǐyè fāzhǎn de hěn kuài.","vi":"Mấy năm nay doanh nghiệp làng xã phát triển rất nhanh."},{"type":"compound","zh":"因为修通了公路，所以这些偏远乡镇也能网购了。","pinyin":"Yīnwèi xiū tōngle gōnglù, suǒyǐ zhèxiē piānyuǎn xiāngzhèn yě néng wǎnggòu le.","vi":"Vì đã làm xong đường quốc lộ nên những làng xã xa xôi này cũng có thể mua sắm trực tuyến."}],"related":[{"hanzi":"乡村","pinyin":"xiāngcūn","vi":"nông thôn"},{"hanzi":"城镇","pinyin":"chéngzhèn","vi":"thị trấn"},{"hanzi":"农村","pinyin":"nóngcūn","vi":"nông thôn"},{"hanzi":"乡镇企业","pinyin":"xiāngzhènqǐyè","vi":"doanh nghiệp hương trấn"}],"traditional":"鄉鎮"},{"id":"削","hanzi":"削","pinyin":"xiāo","meaning_vi":"gọt, vót","explanation":"Tước – gọt, vót (đọc xiāo khi dùng riêng, xuē trong từ ghép). Thường: 削苹果 (gọt táo), 削铅笔; 削弱 (làm suy yếu), 剥削 (bóc lột).","hsk_level":6,"tags":["dong-tu"],"image":"🍎","examples":[{"type":"basic","zh":"我来削苹果。","pinyin":"Wǒ lái xiāopíngguǒ.","vi":"Để tôi gọt táo."},{"type":"simple","zh":"奶奶用小刀给我削了一个梨。","pinyin":"Nǎinai yòng xiǎodāo gěi wǒ xiāole yí gè lí.","vi":"Bà dùng dao nhỏ gọt cho tôi một quả lê."},{"type":"compound","zh":"他削土豆皮时不小心削到了手指，所以只好去贴创可贴。","pinyin":"Tā xiāo tǔdòu pí shí bù xiǎoxīn xiāo dàole shǒuzhǐ, suǒyǐ zhǐhǎo qù tiē chuāngkětiē.","vi":"Khi gọt vỏ khoai tây, anh ấy không cẩn thận gọt vào ngón tay nên đành đi dán băng cá nhân."}],"related":[{"hanzi":"削皮","pinyin":"xiāopí","vi":"gọt vỏ"},{"hanzi":"削苹果","pinyin":"xiāopíngguǒ","vi":"gọt táo"},{"hanzi":"削弱","pinyin":"xuēruò","vi":"làm suy yếu"},{"hanzi":"刀","pinyin":"dāo","vi":"con dao"}]},{"id":"消防","hanzi":"消防","pinyin":"xiāofáng","meaning_vi":"phòng cháy chữa cháy","explanation":"消 (tiêu – dập tắt) + 防 (phòng – phòng ngừa) → phòng cháy chữa cháy. Thường: 消防车, 消防员.","hsk_level":6,"tags":["danh-tu","xa-hoi"],"image":"🚒","examples":[{"type":"basic","zh":"消防车来了。","pinyin":"Xiāofángchē lái le.","vi":"Xe cứu hỏa đến rồi."},{"type":"simple","zh":"大楼每年都要进行消防演习。","pinyin":"Dàlóu měinián dōu yào jìnxíng xiāofáng yǎnxí.","vi":"Tòa nhà mỗi năm đều phải tổ chức diễn tập phòng cháy chữa cháy."},{"type":"compound","zh":"如果消防通道被堵住，一旦着火就会非常危险。","pinyin":"Rúguǒ xiāofáng tōngdào bèi dǔzhù, yídàn zháohuǒ jiù huì fēicháng wēixiǎn.","vi":"Nếu lối thoát hiểm phòng cháy bị chặn, một khi xảy ra cháy sẽ vô cùng nguy hiểm."}],"related":[{"hanzi":"消防员","pinyin":"xiāofángyuán","vi":"lính cứu hỏa"},{"hanzi":"消防车","pinyin":"xiāofángchē","vi":"xe cứu hỏa"},{"hanzi":"火灾","pinyin":"huǒzāi","vi":"hỏa hoạn"},{"hanzi":"灭火","pinyin":"mièhuǒ","vi":"dập lửa"}]},{"id":"凶手","hanzi":"凶手","pinyin":"xiōngshǒu","meaning_vi":"hung thủ","explanation":"凶 (hung – hung ác) + 手 (thủ – người làm) → kẻ gây án mạng, hung thủ. Thường: 抓获凶手.","hsk_level":6,"tags":["danh-tu","phap-luat"],"image":"🚨","examples":[{"type":"basic","zh":"凶手被抓住了。","pinyin":"Xiōngshǒu bèi zhuāzhù le.","vi":"Hung thủ đã bị bắt."},{"type":"simple","zh":"警察根据监控录像找到了凶手。","pinyin":"Jǐngchá gēnjù jiānkòng lùxiàng zhǎodàole xiōngshǒu.","vi":"Cảnh sát dựa vào video giám sát đã tìm ra hung thủ."},{"type":"compound","zh":"虽然凶手逃到了外地，但是警方还是在三天内抓获了他。","pinyin":"Suīrán xiōngshǒu táo dàole wàidì, dànshì jǐngfāng háishi zài sān tiān nèi zhuāhuòle tā.","vi":"Tuy hung thủ đã trốn sang tỉnh khác, nhưng cảnh sát vẫn bắt được hắn trong vòng ba ngày."}],"related":[{"hanzi":"杀手","pinyin":"shāshǒu","vi":"sát thủ"},{"hanzi":"罪犯","pinyin":"zuìfàn","vi":"tội phạm"},{"hanzi":"嫌疑人","pinyin":"xiányírén","vi":"nghi phạm"},{"hanzi":"谋杀","pinyin":"móushā","vi":"mưu sát"}],"traditional":"兇手"},{"id":"羞耻","hanzi":"羞耻","pinyin":"xiūchǐ","meaning_vi":"xấu hổ","explanation":"羞 (tu – thẹn) + 耻 (sỉ – nhục) → cảm giác xấu hổ, nhục nhã. Thường: 羞耻心, 不知羞耻 (không biết xấu hổ).","hsk_level":6,"tags":["tinh-tu"],"image":"😳","examples":[{"type":"basic","zh":"他毫无羞耻之心。","pinyin":"Tā háowú xiūchǐ zhī xīn.","vi":"Hắn không hề biết xấu hổ."},{"type":"simple","zh":"撒谎被拆穿，她感到非常羞耻。","pinyin":"Sāhuǎng bèi chāichuān, tā gǎndào fēicháng xiūchǐ.","vi":"Lời nói dối bị vạch trần, cô ấy cảm thấy vô cùng xấu hổ."},{"type":"compound","zh":"一个人如果失去了羞耻感，就什么坏事都做得出来。","pinyin":"Yígèrén rúguǒ shīqùle xiūchǐ gǎn, jiù shénme huàishì dōu zuò de chūlái.","vi":"Một người nếu mất đi lòng biết xấu hổ thì việc xấu gì cũng có thể làm."}],"related":[{"hanzi":"羞愧","pinyin":"xiūkuì","vi":"hổ thẹn"},{"hanzi":"耻辱","pinyin":"chǐrǔ","vi":"sỉ nhục"},{"hanzi":"害羞","pinyin":"hàixiū","vi":"xấu hổ"},{"hanzi":"无耻","pinyin":"wúchǐ","vi":"vô liêm sỉ"}],"traditional":"羞恥"},{"id":"修复","hanzi":"修复","pinyin":"xiūfù","meaning_vi":"tu sửa, khôi phục","explanation":"修 (tu – sửa) + 复 (phục – khôi phục) → sửa chữa, khôi phục lại như cũ. Thường: 修复文物, 修复关系.","hsk_level":6,"tags":["dong-tu"],"image":"🏛️","examples":[{"type":"basic","zh":"古画修复好了。","pinyin":"Gǔ huà xiūfù hǎo le.","vi":"Bức tranh cổ đã được phục chế xong."},{"type":"simple","zh":"工程师连夜修复了网络故障。","pinyin":"Gōngchéngshī liányè xiūfùle wǎngluò gùzhàng.","vi":"Kỹ sư đã suốt đêm khắc phục sự cố mạng."},{"type":"compound","zh":"两人的关系虽然修复了，但是再也回不到从前了。","pinyin":"Liǎng rén de guānxì suīrán xiūfù le, dànshì zài yě huí budào cóngqián le.","vi":"Quan hệ của hai người tuy đã được hàn gắn, nhưng không thể trở lại như xưa nữa."}],"related":[{"hanzi":"修理","pinyin":"xiūlǐ","vi":"sửa chữa"},{"hanzi":"恢复","pinyin":"huīfù","vi":"khôi phục"},{"hanzi":"修补","pinyin":"xiūbǔ","vi":"tu bổ"},{"hanzi":"损坏","pinyin":"sǔnhuài","vi":"hư hại"}],"traditional":"修復"},{"id":"鲜为人知","hanzi":"鲜为人知","pinyin":"xiǎnwéi-rénzhī","meaning_vi":"ít người biết đến","explanation":"鲜 (đọc xiǎn - hiếm/ít) + 为人知. Thành ngữ.","hsk_level":6,"tags":["thanh-ngu"],"image":"🤫","examples":[{"type":"basic","zh":"这是鲜为人知的秘密。","pinyin":"Zhè shì xiǎnwéirénzhī de mìmì.","vi":"Đây là bí mật ít người biết đến."},{"type":"simple","zh":"这本书讲述了名人鲜为人知的童年。","pinyin":"Zhè běn shū jiǎngshùle míngrén xiǎnwéirénzhī de tóngnián.","vi":"Cuốn sách này kể về tuổi thơ ít người biết của người nổi tiếng."},{"type":"compound","zh":"这个小岛虽然鲜为人知，但是风景比很多热门景点都美。","pinyin":"Zhè ge xiǎodǎo suīrán xiǎnwéirénzhī, dànshì fēngjǐng bǐ hěn duō rèmén jǐngdiǎn dōu měi.","vi":"Hòn đảo nhỏ này tuy ít người biết đến, nhưng phong cảnh còn đẹp hơn nhiều điểm du lịch nổi tiếng."}],"related":[{"hanzi":"不为人知","pinyin":"bùwéirénzhī","vi":"không ai biết"},{"hanzi":"默默无闻","pinyin":"mòmòwúwén","vi":"vô danh"},{"hanzi":"家喻户晓","pinyin":"jiāyùhùxiǎo","vi":"nhà nhà đều biết"},{"hanzi":"众所周知","pinyin":"zhòngsuǒzhōuzhī","vi":"ai cũng biết"}],"traditional":"鮮為人知"},{"id":"显微镜","hanzi":"显微镜","pinyin":"xiǎnwēijìng","meaning_vi":"kính hiển vi","explanation":"显 (làm lộ rõ) + 微 (nhỏ) + 镜 (kính).","hsk_level":6,"tags":["danh-tu","khoa-hoc","do-vat"],"image":"🔬","examples":[{"type":"basic","zh":"请把显微镜调好。","pinyin":"Qǐng bǎ xiǎnwēijìng tiáo hǎo.","vi":"Hãy chỉnh kính hiển vi cho chuẩn."},{"type":"simple","zh":"学生们用显微镜观察洋葱细胞。","pinyin":"Xuéshengmen yòng xiǎnwēijìng guānchá yángcōng xìbāo.","vi":"Học sinh dùng kính hiển vi quan sát tế bào hành tây."},{"type":"compound","zh":"细菌太小了，所以只有在显微镜下才能看清楚。","pinyin":"Xìjūn tài xiǎo le, suǒyǐ zhǐyǒu zài xiǎnwēijìng xià cáinéng kàn qīngchu.","vi":"Vi khuẩn quá nhỏ nên chỉ có dưới kính hiển vi mới nhìn rõ được."}],"related":[{"hanzi":"望远镜","pinyin":"wàngyuǎnjìng","vi":"kính viễn vọng"},{"hanzi":"放大镜","pinyin":"fàngdàjìng","vi":"kính lúp"},{"hanzi":"细胞","pinyin":"xìbāo","vi":"tế bào"},{"hanzi":"实验室","pinyin":"shíyànshì","vi":"phòng thí nghiệm"}],"traditional":"顯微鏡"},{"id":"显而易见","hanzi":"显而易见","pinyin":"xiǎn'ér-yìjiàn","meaning_vi":"rõ ràng dễ thấy, hiển nhiên","explanation":"显 (rõ) + 而易见 (dễ thấy). Thành ngữ.","hsk_level":6,"tags":["thanh-ngu"],"image":"💡","examples":[{"type":"basic","zh":"结果显而易见。","pinyin":"Jiéguǒ xiǎn'éryìjiàn.","vi":"Kết quả rõ ràng dễ thấy."},{"type":"simple","zh":"这份报告里有几个显而易见的错误。","pinyin":"Zhè fèn bàogào lǐ yǒu jǐ gè xiǎn'éryìjiàn de cuòwù.","vi":"Bản báo cáo này có mấy lỗi sai hiển nhiên."},{"type":"compound","zh":"他的话前后矛盾，显而易见，他在说谎。","pinyin":"Tā dehuà qiánhòu máodùn, xiǎn'éryìjiàn, tā zài shuōhuǎng.","vi":"Lời anh ta trước sau mâu thuẫn, rõ ràng là anh ta đang nói dối."}],"related":[{"hanzi":"一目了然","pinyin":"yímùliǎorán","vi":"nhìn là hiểu"},{"hanzi":"明显","pinyin":"míngxiǎn","vi":"rõ ràng"},{"hanzi":"众所周知","pinyin":"zhòngsuǒzhōuzhī","vi":"ai cũng biết"},{"hanzi":"不言而喻","pinyin":"bùyán'éryù","vi":"không nói cũng hiểu"}],"traditional":"顯而易見"},{"id":"响亮","hanzi":"响亮","pinyin":"xiǎngliàng","meaning_vi":"vang dội","explanation":"响 (hưởng – tiếng vang) + 亮 (lượng – sáng, to rõ) → âm thanh to, vang và rõ. Cũng dùng nghĩa bóng: 响亮的名字, 响亮的口号.","hsk_level":6,"tags":["tinh-tu"],"image":"📢","examples":[{"type":"basic","zh":"他的声音很响亮。","pinyin":"Tā de shēngyīn hěn xiǎngliàng.","vi":"Giọng anh ấy rất vang."},{"type":"simple","zh":"孩子们响亮地回答了老师的问题。","pinyin":"Háizimen xiǎngliàng de huídále lǎoshī de wèntí.","vi":"Bọn trẻ trả lời câu hỏi của cô giáo thật to rõ."},{"type":"compound","zh":"这个品牌的名字不但响亮，而且很容易记住。","pinyin":"Zhè ge pǐnpái de míngzi búdàn xiǎngliàng, érqiě hěn róngyì jìzhù.","vi":"Tên của thương hiệu này không những vang dội mà còn rất dễ nhớ."}],"related":[{"hanzi":"洪亮","pinyin":"hóngliàng","vi":"vang to"},{"hanzi":"嘹亮","pinyin":"liáoliàng","vi":"lanh lảnh"},{"hanzi":"清脆","pinyin":"qīngcuì","vi":"trong trẻo"},{"hanzi":"低沉","pinyin":"dīchén","vi":"trầm thấp"}],"traditional":"響亮"},{"id":"宣扬","hanzi":"宣扬","pinyin":"xuānyáng","meaning_vi":"tuyên truyền, truyền bá; rêu rao khắp nơi","explanation":"宣 (tuyên – công bố) + 扬 (dương – giương cao, lan ra) → truyền bá rộng rãi cho nhiều người biết. Thường đi với 宣扬思想, 宣扬精神; đôi khi mang sắc thái tiêu cực (宣扬迷信).","hsk_level":6,"tags":["dong-tu"],"image":"📢","examples":[{"type":"basic","zh":"他到处宣扬自己。","pinyin":"Tā dàochù xuānyáng zìjǐ.","vi":"Anh ta đi khắp nơi khoe khoang về bản thân."},{"type":"simple","zh":"这部电影宣扬了勇敢和善良。","pinyin":"Zhè bù diànyǐng xuānyángle yǒnggǎn hé shànliáng.","vi":"Bộ phim này ca ngợi tinh thần dũng cảm và lòng lương thiện."},{"type":"compound","zh":"这件事你知道就好，千万别到处宣扬，否则会伤害她。","pinyin":"Zhè jiàn shì nǐ zhīdào jiù hǎo, qiānwàn bié dàochù xuānyáng, fǒuzé huì shānghài tā.","vi":"Chuyện này bạn biết là được rồi, đừng đi rêu rao khắp nơi, nếu không sẽ làm tổn thương cô ấy."}],"related":[{"hanzi":"宣传","pinyin":"xuānchuán","vi":"tuyên truyền"},{"hanzi":"传播","pinyin":"chuánbō","vi":"truyền bá"},{"hanzi":"弘扬","pinyin":"hóngyáng","vi":"phát huy"},{"hanzi":"张扬","pinyin":"zhāngyáng","vi":"phô trương"}],"traditional":"宣揚"},{"id":"薛","hanzi":"薛","pinyin":"xuē","meaning_vi":"họ Tiết","explanation":"薛 (Tiết): một họ phổ biến của người Hoa, ví dụ 薛宝钗 trong Hồng Lâu Mộng; nghĩa gốc là một loại cỏ, nay hầu như chỉ dùng làm họ.","hsk_level":6,"tags":["danh-tu","con-nguoi"],"image":"👤","examples":[{"type":"basic","zh":"我们老师姓薛。","pinyin":"Wǒmen lǎoshī xìng xuē.","vi":"Thầy giáo chúng tôi họ Tiết."},{"type":"simple","zh":"薛阿姨每天早上在公园打太极拳。","pinyin":"Xuē āyí měitiān zǎoshang zài gōngyuán dǎ tàijíquán.","vi":"Dì Tiết sáng nào cũng tập thái cực quyền trong công viên."},{"type":"compound","zh":"薛经理虽然很严格，但是对新员工特别有耐心。","pinyin":"Xuē jīnglǐ suīrán hěn yángé, dànshì duì xīn yuángōng tèbié yǒu nàixīn.","vi":"Giám đốc Tiết tuy rất nghiêm khắc, nhưng lại đặc biệt kiên nhẫn với nhân viên mới."}],"related":[{"hanzi":"姓","pinyin":"xìng","vi":"họ"},{"hanzi":"姓氏","pinyin":"xìngshì","vi":"họ tộc"},{"hanzi":"百家姓","pinyin":"Bǎijiāxìng","vi":"bách gia tính"}]},{"id":"雪上加霜","hanzi":"雪上加霜","pinyin":"xuěshàng-jiāshuāng","meaning_vi":"họa vô đơn chí","explanation":"雪上加霜: trên tuyết lại thêm sương giá → tai họa này chưa qua lại thêm tai họa khác, tình hình càng thêm tồi tệ; tương đương \"họa vô đơn chí\".","hsk_level":6,"tags":["thanh-ngu"],"image":"❄️","examples":[{"type":"basic","zh":"这真是雪上加霜。","pinyin":"Zhè zhēn shì xuěshàngjiāshuāng.","vi":"Đây đúng là họa vô đơn chí."},{"type":"simple","zh":"刚丢了工作，又生了病，真是雪上加霜。","pinyin":"Gāng diūle gōngzuò, yòu shēngle bìng, zhēn shì xuěshàngjiāshuāng.","vi":"Vừa mất việc lại đổ bệnh, đúng là họa vô đơn chí."},{"type":"compound","zh":"公司本来就缺钱，大客户又突然退单，这无疑是雪上加霜。","pinyin":"Gōngsī běnlái jiù quēqián, dà kèhù yòu tūrán tuì dān, zhè wúyí shì xuěshàngjiāshuāng.","vi":"Công ty vốn đã thiếu tiền, khách hàng lớn lại đột ngột hủy đơn, đây chắc chắn là họa vô đơn chí."}],"related":[{"hanzi":"祸不单行","pinyin":"huòbùdānxíng","vi":"họa vô đơn chí"},{"hanzi":"屋漏偏逢连夜雨","pinyin":"wū lòu piān féng liányè yǔ","vi":"nhà dột lại gặp mưa dầm"},{"hanzi":"雪中送炭","pinyin":"xuězhōngsòngtàn","vi":"giúp đỡ lúc khó khăn"},{"hanzi":"火上浇油","pinyin":"huǒshàngjiāoyóu","vi":"đổ thêm dầu vào lửa"}]},{"id":"雪中送炭","hanzi":"雪中送炭","pinyin":"xuězhōng-sòngtàn","meaning_vi":"tặng than sưởi ấm giữa trời tuyết (giúp đỡ đúng lúc khó khăn nhất)","explanation":"雪中送炭: giữa trời tuyết đem than đến sưởi → giúp đỡ đúng lúc người khác khó khăn nhất. Thường đối lập với 锦上添花 (thêu hoa trên gấm).","hsk_level":6,"tags":["thanh-ngu"],"image":"🔥","examples":[{"type":"basic","zh":"谢谢你雪中送炭。","pinyin":"Xièxie nǐ xuězhōngsòngtàn.","vi":"Cảm ơn anh đã giúp đỡ đúng lúc khó khăn."},{"type":"simple","zh":"朋友借我的这笔钱真是雪中送炭。","pinyin":"Péngyou jiè wǒ de zhè bǐ qián zhēn shì xuězhōngsòngtàn.","vi":"Khoản tiền bạn cho tôi vay đúng là giúp đỡ lúc ngặt nghèo nhất."},{"type":"compound","zh":"锦上添花的人很多，可是雪中送炭的人却很少。","pinyin":"Jǐnshàngtiānhuā de rén hěn duō, kěshì xuězhōngsòngtàn de rén què hěn shǎo.","vi":"Người thêu hoa trên gấm thì nhiều, nhưng người đưa than sưởi giữa trời tuyết lại rất ít."}],"related":[{"hanzi":"锦上添花","pinyin":"jǐnshàngtiānhuā","vi":"thêu hoa trên gấm"},{"hanzi":"雪上加霜","pinyin":"xuěshàngjiāshuāng","vi":"họa vô đơn chí"},{"hanzi":"帮助","pinyin":"bāngzhù","vi":"giúp đỡ"},{"hanzi":"及时雨","pinyin":"jíshíyǔ","vi":"cơn mưa đúng lúc"}]},{"id":"选拔","hanzi":"选拔","pinyin":"xuǎnbá","meaning_vi":"tuyển chọn","explanation":"选 (tuyển – chọn) + 拔 (bạt – nhổ lên, cất nhắc) → chọn lọc người giỏi từ nhiều người để đề bạt hoặc giao nhiệm vụ. Thường dùng: 选拔人才, 选拔赛 (vòng tuyển chọn).","hsk_level":6,"tags":["dong-tu"],"image":"🏅","examples":[{"type":"basic","zh":"学校在选拔运动员。","pinyin":"Xuéxiào zài xuǎnbá yùndòngyuán.","vi":"Trường đang tuyển chọn vận động viên."},{"type":"simple","zh":"国家队从全国选拔了二十名队员。","pinyin":"Guójiāduì cóng quánguó xuǎnbále èrshí míng duìyuán.","vi":"Đội tuyển quốc gia đã tuyển chọn hai mươi thành viên từ khắp cả nước."},{"type":"compound","zh":"这次选拔既看成绩，又看综合素质，所以竞争非常激烈。","pinyin":"Zhè cì xuǎnbá jì kàn chéngjì, yòu kàn zōnghésùzhì, suǒyǐ jìngzhēng fēicháng jīliè.","vi":"Đợt tuyển chọn này vừa xét thành tích vừa xét tố chất tổng hợp, nên cạnh tranh rất gay gắt."}],"related":[{"hanzi":"挑选","pinyin":"tiāoxuǎn","vi":"chọn lựa"},{"hanzi":"选择","pinyin":"xuǎnzé","vi":"lựa chọn"},{"hanzi":"选拔赛","pinyin":"xuǎnbásài","vi":"vòng tuyển chọn"},{"hanzi":"提拔","pinyin":"tíbá","vi":"đề bạt"}],"traditional":"選拔"},{"id":"细胞","hanzi":"细胞","pinyin":"xìbāo","meaning_vi":"tế bào","explanation":"细 (tế – nhỏ) + 胞 (bào – bọc, màng) → đơn vị nhỏ nhất cấu tạo nên cơ thể sinh vật. Hay gặp: 细胞分裂, 癌细胞, 脑细胞.","hsk_level":6,"tags":["danh-tu","khoa-hoc"],"image":"🧬","examples":[{"type":"basic","zh":"人体由细胞组成。","pinyin":"Réntǐ yóu xìbāo zǔchéng.","vi":"Cơ thể người được cấu tạo từ tế bào."},{"type":"simple","zh":"癌细胞会在体内不断分裂扩散。","pinyin":"Áixìbāo huì zài tǐnèi búduàn fēnliè kuòsàn.","vi":"Tế bào ung thư sẽ không ngừng phân chia và lan rộng trong cơ thể."},{"type":"compound","zh":"如果长期熬夜，身体的细胞就会加速老化。","pinyin":"Rúguǒ chángqī áoyè, shēntǐ de xìbāo jiù huì jiāsù lǎohuà.","vi":"Nếu thức khuya thường xuyên thì tế bào cơ thể sẽ lão hóa nhanh hơn."}],"related":[{"hanzi":"细菌","pinyin":"xìjūn","vi":"vi khuẩn"},{"hanzi":"基因","pinyin":"jīyīn","vi":"gen"},{"hanzi":"细胞核","pinyin":"xìbāohé","vi":"nhân tế bào"},{"hanzi":"显微镜","pinyin":"xiǎnwēijìng","vi":"kính hiển vi"}],"traditional":"細胞"},{"id":"信仰","hanzi":"信仰","pinyin":"xìnyǎng","meaning_vi":"tín ngưỡng","explanation":"信 (tín – tin) + 仰 (ngưỡng – ngẩng lên, kính ngưỡng) → niềm tin và sự tôn sùng vào một tôn giáo, chủ nghĩa hay lý tưởng. Thường nói: 宗教信仰, 信仰自由.","hsk_level":6,"tags":["danh-tu","van-hoa"],"image":"🙏","examples":[{"type":"basic","zh":"他有自己的信仰。","pinyin":"Tā yǒu zìjǐ de xìnyǎng.","vi":"Anh ấy có tín ngưỡng của riêng mình."},{"type":"simple","zh":"我的奶奶一直保持着佛教信仰。","pinyin":"Wǒ de nǎinai yìzhí bǎochízhe Fójiào xìnyǎng.","vi":"Bà tôi luôn giữ tín ngưỡng Phật giáo."},{"type":"compound","zh":"虽然我们的信仰不同，但是我们依然是好朋友。","pinyin":"Suīrán wǒmen de xìnyǎng bùtóng, dànshì wǒmen yīrán shì hǎopéngyou.","vi":"Tuy tín ngưỡng của chúng tôi khác nhau, nhưng chúng tôi vẫn là bạn tốt."}],"related":[{"hanzi":"宗教","pinyin":"zōngjiào","vi":"tôn giáo"},{"hanzi":"信念","pinyin":"xìnniàn","vi":"niềm tin"},{"hanzi":"信奉","pinyin":"xìnfèng","vi":"tin theo"},{"hanzi":"崇拜","pinyin":"chóngbài","vi":"sùng bái"}]},{"id":"兴高采烈","hanzi":"兴高采烈","pinyin":"xìnggāo-cǎiliè","meaning_vi":"phấn khởi vui mừng","explanation":"兴高采烈: hứng (兴) dâng cao, thần sắc (采) rạng rỡ mãnh liệt → vui mừng phấn khởi tột độ, hớn hở ra mặt. Dùng tả người đang rất hào hứng.","hsk_level":6,"tags":["thanh-ngu"],"image":"🥳","examples":[{"type":"basic","zh":"孩子们兴高采烈。","pinyin":"Háizimen xìnggāocǎiliè.","vi":"Bọn trẻ vui mừng phấn khởi."},{"type":"simple","zh":"球迷们兴高采烈地走出了体育场。","pinyin":"Qiúmímen xìnggāocǎiliè de zǒuchūle tǐyùchǎng.","vi":"Các cổ động viên phấn khởi bước ra khỏi sân vận động."},{"type":"compound","zh":"一听说明天去海边，弟弟就兴高采烈地收拾起行李来。","pinyin":"Yì tīngshuō míngtiān qù hǎibiān, dìdi jiù xìnggāocǎiliè de shōushi qǐ xíngli lái.","vi":"Vừa nghe nói ngày mai đi biển, em trai liền hớn hở thu dọn hành lý."}],"related":[{"hanzi":"欢天喜地","pinyin":"huāntiānxǐdì","vi":"vui mừng hớn hở"},{"hanzi":"兴致勃勃","pinyin":"xìngzhìbóbó","vi":"hứng thú bừng bừng"},{"hanzi":"高兴","pinyin":"gāoxìng","vi":"vui vẻ"},{"hanzi":"垂头丧气","pinyin":"chuítóusàngqì","vi":"ủ rũ chán nản"}],"traditional":"興高采烈"},{"id":"性命","hanzi":"性命","pinyin":"xìngmìng","meaning_vi":"tính mạng","explanation":"性 (tính – bản tính, sự sống) + 命 (mệnh – mạng) → mạng sống của con người. Thường dùng: 保住性命, 性命攸关 (liên quan đến tính mạng), 拿性命开玩笑.","hsk_level":6,"tags":["danh-tu"],"image":"❤️","examples":[{"type":"basic","zh":"医生救了他的性命。","pinyin":"Yīshēng jiùle tā de xìngmìng.","vi":"Bác sĩ đã cứu mạng anh ấy."},{"type":"simple","zh":"为了救落水的孩子，他连自己的性命都不顾了。","pinyin":"Wèile jiù luòshuǐ de háizi, tā lián zìjǐ de xìngmìng dōu búgù le.","vi":"Để cứu đứa trẻ rơi xuống nước, anh ấy bất chấp cả tính mạng của mình."},{"type":"compound","zh":"如果不系安全带，你就是拿自己的性命开玩笑。","pinyin":"Rúguǒ bú jì ānquándài, nǐ jiùshì ná zìjǐ de xìngmìng kāiwánxiào.","vi":"Nếu không thắt dây an toàn, bạn đang đùa với tính mạng của mình."}],"related":[{"hanzi":"生命","pinyin":"shēngmìng","vi":"sinh mệnh"},{"hanzi":"性命攸关","pinyin":"xìngmìngyōuguān","vi":"liên quan tính mạng"},{"hanzi":"命","pinyin":"mìng","vi":"mạng"},{"hanzi":"人命","pinyin":"rénmìng","vi":"mạng người"}]},{"id":"习以为常","hanzi":"习以为常","pinyin":"xíyǐ-wéicháng","meaning_vi":"quen rồi thành bình thường","explanation":"习 (quen) + 以为常 (coi là thường). Thành ngữ.","hsk_level":6,"tags":["thanh-ngu"],"image":"🔄","examples":[{"type":"basic","zh":"大家早已习以为常。","pinyin":"Dàjiā zǎoyǐ xíyǐwéicháng.","vi":"Mọi người đã sớm quen rồi."},{"type":"simple","zh":"住在城市里的人对堵车习以为常。","pinyin":"Zhùzài chéngshì li de rén duì dǔchē xíyǐwéicháng.","vi":"Người sống ở thành phố đã quen với chuyện tắc đường."},{"type":"compound","zh":"刚开始他很不适应加班，但是半年后就习以为常了。","pinyin":"Gāng kāishǐ tā hěn bú shìyìng jiābān, dànshì bàn nián hòu jiù xíyǐwéicháng le.","vi":"Lúc đầu anh ấy rất không quen tăng ca, nhưng nửa năm sau đã thành chuyện bình thường."}],"related":[{"hanzi":"司空见惯","pinyin":"sīkōngjiànguàn","vi":"thấy mãi thành quen"},{"hanzi":"习惯","pinyin":"xíguàn","vi":"thói quen"},{"hanzi":"屡见不鲜","pinyin":"lǚjiànbùxiān","vi":"thường thấy chẳng lạ"},{"hanzi":"平常","pinyin":"píngcháng","vi":"bình thường"}],"traditional":"習以為常"},{"id":"畜牧","hanzi":"畜牧","pinyin":"xùmù","meaning_vi":"chăn nuôi","explanation":"畜 (súc – gia súc) + 牧 (mục – chăn thả) → chăn nuôi gia súc như trâu, bò, cừu, ngựa. Thường gặp: 畜牧业 (ngành chăn nuôi), 畜牧区.","hsk_level":6,"tags":["danh-tu","dong-vat"],"image":"🐄","examples":[{"type":"basic","zh":"这里以畜牧为主。","pinyin":"Zhèlǐ yǐ xùmù wéizhǔ.","vi":"Nơi này chủ yếu làm chăn nuôi."},{"type":"simple","zh":"内蒙古草原的畜牧业非常发达。","pinyin":"Nèiměnggǔ cǎoyuán de xùmùyè fēicháng fādá.","vi":"Ngành chăn nuôi trên thảo nguyên Nội Mông rất phát triển."},{"type":"compound","zh":"因为这里草场广阔，所以牧民们世代从事畜牧。","pinyin":"Yīnwèi zhèlǐ cǎochǎng guǎngkuò, suǒyǐ mùmínmen shìdài cóngshì xùmù.","vi":"Vì đồng cỏ ở đây rộng lớn nên người dân du mục đời đời làm nghề chăn nuôi."}],"related":[{"hanzi":"畜牧业","pinyin":"xùmùyè","vi":"ngành chăn nuôi"},{"hanzi":"牧场","pinyin":"mùchǎng","vi":"đồng cỏ chăn nuôi"},{"hanzi":"饲养","pinyin":"sìyǎng","vi":"chăn nuôi"},{"hanzi":"牲畜","pinyin":"shēngchù","vi":"gia súc"}]},{"id":"循序渐进","hanzi":"循序渐进","pinyin":"xúnxù-jiànjìn","meaning_vi":"tuần tự tiến lên","explanation":"循序渐进: theo (循) thứ tự (序), dần dần (渐) tiến lên (进) → học tập hay làm việc từng bước một, từ dễ đến khó, không nóng vội.","hsk_level":6,"tags":["thanh-ngu"],"image":"📈","examples":[{"type":"basic","zh":"学习要循序渐进。","pinyin":"Xuéxí yào xúnxùjiànjìn.","vi":"Học tập phải đi từng bước."},{"type":"simple","zh":"教练让我们循序渐进地增加跑步距离。","pinyin":"Jiàoliàn ràng wǒmen xúnxùjiànjìn de zēngjiā pǎobù jùlí.","vi":"Huấn luyện viên bảo chúng tôi tăng dần quãng đường chạy theo từng bước."},{"type":"compound","zh":"只要循序渐进地练习，你的中文就会越来越流利。","pinyin":"Zhǐyào xúnxùjiànjìn de liànxí, nǐ de Zhōngwén jiù huì yuèláiyuè liúlì.","vi":"Chỉ cần luyện tập từng bước, tiếng Trung của bạn sẽ ngày càng trôi chảy."}],"related":[{"hanzi":"按部就班","pinyin":"ànbùjiùbān","vi":"theo trình tự"},{"hanzi":"稳步","pinyin":"wěnbù","vi":"vững bước"},{"hanzi":"逐步","pinyin":"zhúbù","vi":"từng bước"},{"hanzi":"急于求成","pinyin":"jíyúqiúchéng","vi":"nóng vội cầu thành"}],"traditional":"循序漸進"},{"id":"昔日","hanzi":"昔日","pinyin":"xīrì","meaning_vi":"ngày xưa, thuở trước","explanation":"昔 (xưa) + 日 (ngày).","hsk_level":6,"tags":["danh-tu","thoi-gian"],"image":"⏪","examples":[{"type":"basic","zh":"昔日的小村庄变了。","pinyin":"Xīrì de xiǎo cūnzhuāng biàn le.","vi":"Ngôi làng nhỏ ngày xưa đã thay đổi."},{"type":"simple","zh":"这座古城依稀还能看出昔日的繁华。","pinyin":"Zhè zuò gǔchéng yīxī hái néng kànchū xīrì de fánhuá.","vi":"Tòa cổ thành này vẫn còn thấp thoáng vẻ phồn hoa ngày trước."},{"type":"compound","zh":"昔日的同学虽然各奔东西，但是感情一点也没变。","pinyin":"Xīrì de tóngxué suīrán gèbèndōngxī, dànshì gǎnqíng yìdiǎn yě méi biàn.","vi":"Bạn học ngày xưa tuy mỗi người một ngả nhưng tình cảm chẳng hề thay đổi."}],"related":[{"hanzi":"往日","pinyin":"wǎngrì","vi":"ngày xưa"},{"hanzi":"从前","pinyin":"cóngqián","vi":"trước kia"},{"hanzi":"今日","pinyin":"jīnrì","vi":"hôm nay"},{"hanzi":"过去","pinyin":"guòqù","vi":"quá khứ"}]},{"id":"牺牲","hanzi":"牺牲","pinyin":"xīshēng","meaning_vi":"hy sinh","explanation":"Cả hai chữ đều có bộ ngưu 牜(trâu bò tế lễ xưa).","hsk_level":6,"tags":["dong-tu","xa-hoi"],"image":"🕯️","examples":[{"type":"basic","zh":"他为国家牺牲了。","pinyin":"Tā wèi guójiā xīshēng le.","vi":"Anh ấy đã hy sinh vì đất nước."},{"type":"simple","zh":"妈妈牺牲了很多休息时间来照顾我。","pinyin":"Māma xīshēngle hěn duō xiūxi shíjiān lái zhàogù wǒ.","vi":"Mẹ đã hy sinh rất nhiều thời gian nghỉ ngơi để chăm sóc tôi."},{"type":"compound","zh":"与其牺牲健康去赚钱，不如好好休息几天。","pinyin":"Yǔqí xīshēng jiànkāng qù zhuànqián, bùrú hǎohǎo xiūxi jǐtiān.","vi":"Thay vì hy sinh sức khỏe để kiếm tiền, chi bằng nghỉ ngơi tử tế vài ngày."}],"related":[{"hanzi":"献身","pinyin":"xiànshēn","vi":"hiến thân"},{"hanzi":"牺牲品","pinyin":"xīshēngpǐn","vi":"vật hy sinh"},{"hanzi":"奉献","pinyin":"fèngxiàn","vi":"cống hiến"},{"hanzi":"舍己为人","pinyin":"shějǐwèirén","vi":"quên mình vì người"}],"traditional":"犧牲"},{"id":"息息相关","hanzi":"息息相关","pinyin":"xīxī-xiāngguān","meaning_vi":"gắn bó mật thiết với nhau (như hơi thở)","explanation":"息息 (hơi thở) + 相关 (liên quan). Thành ngữ.","hsk_level":6,"tags":["thanh-ngu"],"image":"🔗","examples":[{"type":"basic","zh":"环境与健康息息相关。","pinyin":"Huánjìng yǔ jiànkāng xīxīxiāngguān.","vi":"Môi trường và sức khỏe gắn bó mật thiết với nhau."},{"type":"simple","zh":"物价的变化和每个家庭的生活息息相关。","pinyin":"Wùjià de biànhuà hé měi gè jiātíng de shēnghuó xīxīxiāngguān.","vi":"Sự thay đổi giá cả gắn liền mật thiết với cuộc sống của mỗi gia đình."},{"type":"compound","zh":"因为这项政策和农民息息相关，所以大家都很关注。","pinyin":"Yīnwèi zhè xiàng zhèngcè hé nóngmín xīxīxiāngguān, suǒyǐ dàjiā dōu hěn guānzhù.","vi":"Vì chính sách này liên quan mật thiết đến nông dân nên mọi người đều rất quan tâm."}],"related":[{"hanzi":"密切相关","pinyin":"mìqièxiāngguān","vi":"liên quan mật thiết"},{"hanzi":"相关","pinyin":"xiāngguān","vi":"liên quan"},{"hanzi":"休戚相关","pinyin":"xiūqīxiāngguān","vi":"vui buồn có nhau"},{"hanzi":"毫不相干","pinyin":"háobùxiānggān","vi":"chẳng liên quan gì"}],"traditional":"息息相關"},{"id":"新陈代谢","hanzi":"新陈代谢","pinyin":"xīnchén-dàixiè","meaning_vi":"trao đổi chất","explanation":"新陈代谢: cái mới (新) thay thế (代谢) cái cũ (陈) → trong sinh học là quá trình trao đổi chất; nghĩa bóng chỉ quy luật cái mới thay thế cái cũ.","hsk_level":6,"tags":["thanh-ngu"],"image":"🧬","examples":[{"type":"basic","zh":"运动能促进新陈代谢。","pinyin":"Yùndòng néng cùjìn xīnchéndàixiè.","vi":"Vận động có thể thúc đẩy quá trình trao đổi chất."},{"type":"simple","zh":"人上了年纪以后新陈代谢会变慢。","pinyin":"Rén shàngle niánjì yǐhòu xīnchéndàixiè huì biàn màn.","vi":"Con người khi có tuổi thì quá trình trao đổi chất sẽ chậm lại."},{"type":"compound","zh":"如果每天多喝水，新陈代谢就会更加顺畅。","pinyin":"Rúguǒ měitiān duō hēshuǐ, xīnchéndàixiè jiù huì gèngjiā shùnchàng.","vi":"Nếu mỗi ngày uống nhiều nước, quá trình trao đổi chất sẽ trơn tru hơn."}],"related":[{"hanzi":"代谢","pinyin":"dàixiè","vi":"chuyển hóa"},{"hanzi":"消化","pinyin":"xiāohuà","vi":"tiêu hóa"},{"hanzi":"细胞","pinyin":"xìbāo","vi":"tế bào"},{"hanzi":"吐故纳新","pinyin":"tǔgùnàxīn","vi":"bỏ cũ nạp mới"}],"traditional":"新陳代謝"},{"id":"心甘情愿","hanzi":"心甘情愿","pinyin":"xīngān-qíngyuàn","meaning_vi":"cam tâm tình nguyện","explanation":"心甘 (cam lòng) + 情愿 (tình nguyện) → hoàn toàn cam tâm tự nguyện, không chút miễn cưỡng.","hsk_level":6,"tags":["thanh-ngu","cam-xuc"],"image":"💖","examples":[{"type":"basic","zh":"我心甘情愿等你。","pinyin":"Wǒ xīngānqíngyuàn děng nǐ.","vi":"Tôi cam tâm tình nguyện chờ bạn."},{"type":"simple","zh":"他心甘情愿地把奖金捐给了山区学校。","pinyin":"Tā xīngānqíngyuàn de bǎ jiǎngjīn juāngěile shānqū xuéxiào.","vi":"Anh ấy tự nguyện quyên góp tiền thưởng cho trường học vùng núi."},{"type":"compound","zh":"只要孩子过得幸福，父母就心甘情愿地付出一切。","pinyin":"Zhǐyào háizi guòde xìngfú, fùmǔ jiù xīngānqíngyuàn de fùchū yíqiè.","vi":"Chỉ cần con cái sống hạnh phúc, cha mẹ cam lòng hy sinh tất cả."}],"related":[{"hanzi":"甘心","pinyin":"gānxīn","vi":"cam lòng"},{"hanzi":"情愿","pinyin":"qíngyuàn","vi":"tình nguyện"},{"hanzi":"自愿","pinyin":"zìyuàn","vi":"tự nguyện"},{"hanzi":"被迫","pinyin":"bèipò","vi":"bị ép buộc"}],"traditional":"心甘情願"},{"id":"心花怒放","hanzi":"心花怒放","pinyin":"xīnhuā-nùfàng","meaning_vi":"vui mừng khôn xiết (lòng nở hoa)","explanation":"心花 (hoa trong lòng) + 怒放 (nộ phóng – nở rộ) → lòng như hoa nở rộ; vui sướng tột độ.","hsk_level":6,"tags":["thanh-ngu","cam-xuc"],"image":"🌸","examples":[{"type":"basic","zh":"她听了心花怒放。","pinyin":"Tā tīngle xīnhuānùfàng.","vi":"Cô ấy nghe xong vui như mở cờ trong bụng."},{"type":"simple","zh":"收到录取通知书那天，我心花怒放。","pinyin":"Shōudào lùqǔ tōngzhīshū nà tiān, wǒ xīnhuānùfàng.","vi":"Hôm nhận giấy báo trúng tuyển, tôi vui mừng khôn xiết."},{"type":"compound","zh":"老板一宣布发年终奖，员工们就心花怒放。","pinyin":"Lǎobǎn yì xuānbù fā niánzhōngjiǎng, yuángōngmen jiù xīnhuānùfàng.","vi":"Sếp vừa thông báo phát thưởng cuối năm, nhân viên liền mừng rỡ khôn xiết."}],"related":[{"hanzi":"兴高采烈","pinyin":"xìnggāocǎiliè","vi":"phấn khởi vui mừng"},{"hanzi":"喜出望外","pinyin":"xǐchūwàngwài","vi":"mừng ngoài mong đợi"},{"hanzi":"欣喜若狂","pinyin":"xīnxǐruòkuáng","vi":"vui mừng như điên"},{"hanzi":"开心","pinyin":"kāixīn","vi":"vui vẻ"}]},{"id":"辛勤","hanzi":"辛勤","pinyin":"xīnqín","meaning_vi":"cần cù","explanation":"辛 (tân – cay đắng, vất vả) + 勤 (cần – chăm chỉ) → chăm chỉ, cần cù chịu khó. Thường đi với 辛勤劳动, 辛勤工作, 辛勤的园丁 (chỉ thầy cô).","hsk_level":6,"tags":["tinh-tu"],"image":"🐝","examples":[{"type":"basic","zh":"农民辛勤劳动。","pinyin":"Nóngmín xīnqín láodòng.","vi":"Nông dân lao động cần cù."},{"type":"simple","zh":"感谢老师们一年来的辛勤付出。","pinyin":"Gǎnxiè lǎoshīmen yì niánlái de xīnqín fùchū.","vi":"Cảm ơn sự cống hiến cần mẫn của các thầy cô suốt một năm qua."},{"type":"compound","zh":"虽然蜜蜂很小，但是它们每天都在辛勤地工作。","pinyin":"Suīrán mìfēng hěn xiǎo, dànshì tāmen měitiān dōu zài xīnqín de gōngzuò.","vi":"Tuy loài ong rất nhỏ nhưng ngày nào chúng cũng làm việc chăm chỉ."}],"related":[{"hanzi":"勤劳","pinyin":"qínláo","vi":"cần cù"},{"hanzi":"辛苦","pinyin":"xīnkǔ","vi":"vất vả"},{"hanzi":"勤奋","pinyin":"qínfèn","vi":"chăm chỉ"},{"hanzi":"懒惰","pinyin":"lǎnduò","vi":"lười biếng"}]},{"id":"薪水","hanzi":"薪水","pinyin":"xīnshuǐ","meaning_vi":"tiền lương","explanation":"薪 (tân – củi) + 水 (thủy – nước) → vốn là tiền củi tiền nước, nay chỉ tiền lương hằng tháng. Thường nói: 领薪水, 薪水很高; đồng nghĩa 工资.","hsk_level":6,"tags":["danh-tu","tien-te"],"image":"💰","examples":[{"type":"basic","zh":"这份工作薪水很高。","pinyin":"Zhè fèn gōngzuò xīnshuǐ hěn gāo.","vi":"Công việc này lương rất cao."},{"type":"simple","zh":"他每个月都把一半薪水存进银行。","pinyin":"Tā měi gèyuè dōu bǎ yíbàn xīnshuǐ cún jìn yínháng.","vi":"Mỗi tháng anh ấy đều gửi một nửa tiền lương vào ngân hàng."},{"type":"compound","zh":"即使薪水不太高，她也很喜欢这份教书的工作。","pinyin":"Jíshǐ xīnshuǐ bú tài gāo, tā yě hěn xǐhuan zhè fèn jiāoshū de gōngzuò.","vi":"Dù lương không cao lắm, cô ấy vẫn rất thích công việc dạy học này."}],"related":[{"hanzi":"工资","pinyin":"gōngzī","vi":"tiền lương"},{"hanzi":"收入","pinyin":"shōurù","vi":"thu nhập"},{"hanzi":"加薪","pinyin":"jiāxīn","vi":"tăng lương"},{"hanzi":"奖金","pinyin":"jiǎngjīn","vi":"tiền thưởng"}]},{"id":"心疼","hanzi":"心疼","pinyin":"xīnténg","meaning_vi":"thương, xót; tiếc (của)","explanation":"心 (tâm – lòng) + 疼 (đông – đau) → đau lòng, xót xa; cũng có nghĩa thương yêu, xót của. Ví dụ: 妈妈心疼孩子, 花这么多钱真心疼.","hsk_level":6,"tags":["dong-tu"],"image":"🥺","examples":[{"type":"basic","zh":"妈妈心疼儿子。","pinyin":"Māma xīnténg érzi.","vi":"Mẹ xót con trai."},{"type":"simple","zh":"看到孩子摔破了膝盖，奶奶心疼得直掉眼泪。","pinyin":"Kàndào háizi shuāipòle xīgài, nǎinai xīnténg dezhí diào yǎnlèi.","vi":"Thấy cháu ngã trầy đầu gối, bà xót đến rơi nước mắt."},{"type":"compound","zh":"新买的手机摔坏了，他不但心疼，而且很后悔。","pinyin":"Xīn mǎi de shǒujī shuāi huàile, tā búdàn xīnténg, érqiě hěn hòuhuǐ.","vi":"Chiếc điện thoại mới mua bị rơi hỏng, anh ấy không chỉ xót mà còn rất hối hận."}],"related":[{"hanzi":"疼爱","pinyin":"téng'ài","vi":"yêu thương"},{"hanzi":"可惜","pinyin":"kěxī","vi":"tiếc"},{"hanzi":"怜惜","pinyin":"liánxī","vi":"thương xót"},{"hanzi":"舍不得","pinyin":"shěbude","vi":"không nỡ"}]},{"id":"兴旺","hanzi":"兴旺","pinyin":"xīngwàng","meaning_vi":"hưng thịnh","explanation":"兴 (hưng – thịnh, dấy lên) + 旺 (vượng – thịnh vượng) → phát đạt, thịnh vượng, đông đúc. Thường đi với 生意兴旺, 家业兴旺, 人丁兴旺.","hsk_level":6,"tags":["tinh-tu"],"image":"📈","examples":[{"type":"basic","zh":"生意越来越兴旺。","pinyin":"Shēngyi yuèláiyuè xīngwàng.","vi":"Việc làm ăn ngày càng phát đạt."},{"type":"simple","zh":"这个小镇的旅游业近几年十分兴旺。","pinyin":"Zhè ge xiǎozhèn de lǚyóuyè jìnjǐnián shífēn xīngwàng.","vi":"Ngành du lịch của thị trấn nhỏ này mấy năm gần đây rất hưng thịnh."},{"type":"compound","zh":"只要家人团结一心，家业就会越来越兴旺。","pinyin":"Zhǐyào jiārén tuánjié yìxīn, jiāyè jiù huì yuèláiyuè xīngwàng.","vi":"Chỉ cần người nhà đồng lòng, gia nghiệp sẽ ngày càng thịnh vượng."}],"related":[{"hanzi":"兴盛","pinyin":"xīngshèng","vi":"hưng thịnh"},{"hanzi":"繁荣","pinyin":"fánróng","vi":"phồn vinh"},{"hanzi":"昌盛","pinyin":"chāngshèng","vi":"thịnh vượng"},{"hanzi":"衰落","pinyin":"shuāiluò","vi":"suy tàn"}],"traditional":"興旺"},{"id":"虚假","hanzi":"虚假","pinyin":"xūjiǎ","meaning_vi":"giả dối","explanation":"虚 (hư – trống rỗng, không thật) + 假 (giả – giả) → giả dối, không đúng sự thật. Thường dùng: 虚假广告, 虚假信息, 虚假的笑容.","hsk_level":6,"tags":["tinh-tu"],"image":"🤥","examples":[{"type":"basic","zh":"这条广告很虚假。","pinyin":"Zhè tiáo guǎnggào hěn xūjiǎ.","vi":"Quảng cáo này rất giả dối."},{"type":"simple","zh":"警方查处了一批发布虚假信息的网站。","pinyin":"Jǐngfāng cháchǔle yìpī fābù xūjiǎ xìnxī de wǎngzhàn.","vi":"Cảnh sát đã xử lý một loạt trang web đăng thông tin sai sự thật."},{"type":"compound","zh":"他的笑容虽然很热情，但是让人觉得有些虚假。","pinyin":"Tā de xiàoróng suīrán hěn rèqíng, dànshì ràng rén juéde yǒuxiē xūjiǎ.","vi":"Nụ cười của anh ta tuy rất nhiệt tình nhưng khiến người ta thấy hơi giả tạo."}],"related":[{"hanzi":"虚伪","pinyin":"xūwěi","vi":"giả dối"},{"hanzi":"假","pinyin":"jiǎ","vi":"giả"},{"hanzi":"真实","pinyin":"zhēnshí","vi":"chân thật"},{"hanzi":"虚假广告","pinyin":"xūjiǎguǎnggào","vi":"quảng cáo sai sự thật"}],"traditional":"虛假"},{"id":"须知","hanzi":"须知","pinyin":"xūzhī","meaning_vi":"điều cần biết","explanation":"须 (tu – cần phải) + 知 (tri – biết) → những điều cần phải biết, thường là bản hướng dẫn, quy định. Ví dụ: 入学须知, 乘客须知, 考生须知.","hsk_level":6,"tags":["danh-tu"],"image":"📋","examples":[{"type":"basic","zh":"请阅读考试须知。","pinyin":"Qǐng yuèdú kǎoshì xūzhī.","vi":"Vui lòng đọc những điều cần biết khi thi."},{"type":"simple","zh":"入住前，酒店前台给了我们一份住宿须知。","pinyin":"Rùzhù qián, jiǔdiàn qiántái gěile wǒmen yí fèn zhùsù xūzhī.","vi":"Trước khi nhận phòng, lễ tân khách sạn đưa chúng tôi bản lưu ý lưu trú."},{"type":"compound","zh":"如果你没看游客须知，就可能错过重要的安全提示。","pinyin":"Rúguǒ nǐ méi kàn yóukè xūzhī, jiù kěnéng cuòguò zhòngyào de ānquán tíshì.","vi":"Nếu bạn không đọc phần lưu ý dành cho du khách, bạn có thể bỏ lỡ những nhắc nhở an toàn quan trọng."}],"related":[{"hanzi":"注意事项","pinyin":"zhùyìshìxiàng","vi":"những điều cần chú ý"},{"hanzi":"必须","pinyin":"bìxū","vi":"bắt buộc"},{"hanzi":"规定","pinyin":"guīdìng","vi":"quy định"},{"hanzi":"入学须知","pinyin":"rùxuéxūzhī","vi":"điều cần biết khi nhập học"}],"traditional":"須知"},{"id":"喜怒哀乐","hanzi":"喜怒哀乐","pinyin":"xǐnù-āilè","meaning_vi":"hỉ nộ ái ố (mọi cung bậc cảm xúc)","explanation":"喜 (vui) + 怒 (giận) + 哀 (buồn) + 乐 (vui sướng). Thành ngữ.","hsk_level":6,"tags":["thanh-ngu","cam-xuc"],"image":"🎭","examples":[{"type":"basic","zh":"他喜怒哀乐都写在脸上。","pinyin":"Tā xǐnù'āilè dōu xiě zài liǎn shang.","vi":"Vui buồn giận hờn của anh ấy đều hiện trên mặt."},{"type":"simple","zh":"这本日记记录了她青春时期的喜怒哀乐。","pinyin":"Zhè běn rìjì jìlùle tā qīngchūn shíqī de xǐnù'āilè.","vi":"Cuốn nhật ký này ghi lại mọi cung bậc cảm xúc thời thanh xuân của cô ấy."},{"type":"compound","zh":"好朋友不但分享你的喜怒哀乐，而且在困难时帮助你。","pinyin":"Hǎopéngyou búdàn fēnxiǎng nǐ de xǐnù'āilè, érqiě zài kùnnan shí bāngzhù nǐ.","vi":"Bạn tốt không chỉ chia sẻ mọi vui buồn với bạn mà còn giúp bạn lúc khó khăn."}],"related":[{"hanzi":"情绪","pinyin":"qíngxù","vi":"cảm xúc"},{"hanzi":"感情","pinyin":"gǎnqíng","vi":"tình cảm"},{"hanzi":"悲欢离合","pinyin":"bēihuānlíhé","vi":"vui buồn ly hợp"},{"hanzi":"七情六欲","pinyin":"qīqíngliùyù","vi":"thất tình lục dục"}],"traditional":"喜怒哀樂"},{"id":"喜闻乐见","hanzi":"喜闻乐见","pinyin":"xǐwén-lèjiàn","meaning_vi":"ưa thích đón nhận","explanation":"喜闻乐见: thích (喜) nghe, vui (乐) xem → được đông đảo mọi người yêu thích, sẵn lòng đón nhận. Thường nói về hình thức nghệ thuật, văn hóa đại chúng.","hsk_level":6,"tags":["thanh-ngu"],"image":"😄","examples":[{"type":"basic","zh":"这是群众喜闻乐见的节目。","pinyin":"Zhè shì qúnzhòng xǐwénlèjiàn de jiémù.","vi":"Đây là chương trình được quần chúng ưa thích."},{"type":"simple","zh":"相声是北方老百姓喜闻乐见的艺术形式。","pinyin":"Xiàngsheng shì běifāng lǎobǎixìng xǐwénlèjiàn de yìshù xíngshì.","vi":"Tấu nói là loại hình nghệ thuật được người dân miền Bắc yêu thích."},{"type":"compound","zh":"只有作品贴近生活，才能成为观众喜闻乐见的好作品。","pinyin":"Zhǐyǒu zuòpǐn tiējìn shēnghuó, cáinéng chéngwéi guānzhòng xǐwénlèjiàn de hǎo zuòpǐn.","vi":"Chỉ khi gần gũi đời sống, tác phẩm mới trở thành tác phẩm hay được khán giả đón nhận."}],"related":[{"hanzi":"受欢迎","pinyin":"shòuhuānyíng","vi":"được yêu thích"},{"hanzi":"脍炙人口","pinyin":"kuàizhìrénkǒu","vi":"được mọi người ưa chuộng"},{"hanzi":"喜爱","pinyin":"xǐ'ài","vi":"yêu thích"},{"hanzi":"通俗","pinyin":"tōngsú","vi":"bình dân dễ hiểu"}],"traditional":"喜聞樂見"},{"id":"原始","hanzi":"原始","pinyin":"yuánshǐ","meaning_vi":"nguyên thủy; gốc, ban đầu","explanation":"原 (nguyên – gốc, ban đầu) + 始 (thủy – bắt đầu) → nguyên thủy, ở trạng thái ban đầu, chưa phát triển. Thường gặp: 原始社会, 原始森林, 原始资料 (tư liệu gốc).","hsk_level":6,"tags":["tinh-tu"],"image":"🦴","examples":[{"type":"basic","zh":"这是原始森林。","pinyin":"Zhè shì yuánshǐ sēnlín.","vi":"Đây là rừng nguyên sinh."},{"type":"simple","zh":"博物馆里展出了原始人使用的石器。","pinyin":"Bówùguǎn li zhǎnchūle yuánshǐrén shǐyòng de shíqì.","vi":"Bảo tàng trưng bày đồ đá mà người nguyên thủy sử dụng."},{"type":"compound","zh":"因为原始数据丢失了，所以我们只好重新调查。","pinyin":"Yīnwèi yuánshǐ shùjù diūshī le, suǒyǐ wǒmen zhǐhǎo chóngxīn diàochá.","vi":"Vì dữ liệu gốc bị mất nên chúng tôi đành phải điều tra lại."}],"related":[{"hanzi":"原始社会","pinyin":"yuánshǐshèhuì","vi":"xã hội nguyên thủy"},{"hanzi":"原来","pinyin":"yuánlái","vi":"ban đầu"},{"hanzi":"最初","pinyin":"zuìchū","vi":"lúc đầu"},{"hanzi":"现代","pinyin":"xiàndài","vi":"hiện đại"}]},{"id":"冤枉","hanzi":"冤枉","pinyin":"yuānwang","meaning_vi":"đổ oan, làm oan; oan uổng, oan ức; uổng công","explanation":"冤 (oan – oan ức) + 枉 (uổng – cong, sai trái) → bị buộc tội sai, oan ức; làm động từ là đổ oan cho ai. Ví dụ: 冤枉好人, 你冤枉我了; còn có nghĩa uổng công: 冤枉钱.","hsk_level":6,"tags":["tinh-tu"],"image":"😭","examples":[{"type":"basic","zh":"你冤枉他了。","pinyin":"Nǐ yuānwang tā le.","vi":"Bạn đã đổ oan cho anh ấy rồi."},{"type":"simple","zh":"小明被老师冤枉偷了同学的钢笔。","pinyin":"Xiǎo míng bèi lǎoshī yuānwang tōule tóngxué de gāngbǐ.","vi":"Tiểu Minh bị cô giáo đổ oan là lấy trộm bút máy của bạn."},{"type":"compound","zh":"因为走错了路，所以我们白白多走了很多冤枉路。","pinyin":"Yīnwèi zǒucuòle lù, suǒyǐ wǒmen báibái duō zǒule hěn duō yuānwanglù.","vi":"Vì đi nhầm đường nên chúng tôi đã đi thêm rất nhiều đoạn đường uổng công."}],"related":[{"hanzi":"委屈","pinyin":"wěiqu","vi":"tủi thân"},{"hanzi":"冤屈","pinyin":"yuānqū","vi":"oan khuất"},{"hanzi":"冤枉钱","pinyin":"yuānwangqián","vi":"tiền tiêu phí uổng"},{"hanzi":"诬陷","pinyin":"wūxiàn","vi":"vu oan"}]},{"id":"约束","hanzi":"约束","pinyin":"yuēshù","meaning_vi":"ràng buộc","explanation":"约 (ước – ràng, hẹn) + 束 (thúc – bó buộc) → ràng buộc, hạn chế hành vi trong một phạm vi. Thường dùng: 约束自己, 受到约束, 法律约束.","hsk_level":6,"tags":["dong-tu"],"image":"⛓️","examples":[{"type":"basic","zh":"法律约束每个人。","pinyin":"Fǎlǜ yuēshù měigèrén.","vi":"Pháp luật ràng buộc mỗi người."},{"type":"simple","zh":"公司用严格的制度约束员工的行为。","pinyin":"Gōngsī yòng yángé de zhìdù yuēshù yuángōng de xíngwéi.","vi":"Công ty dùng chế độ nghiêm ngặt để ràng buộc hành vi của nhân viên."},{"type":"compound","zh":"孩子既需要自由，又需要适当的约束。","pinyin":"Háizi jì xūyào zìyóu, yòu xūyào shìdàng de yuēshù.","vi":"Trẻ em vừa cần tự do, vừa cần sự ràng buộc thích đáng."}],"related":[{"hanzi":"束缚","pinyin":"shùfù","vi":"trói buộc"},{"hanzi":"限制","pinyin":"xiànzhì","vi":"hạn chế"},{"hanzi":"管束","pinyin":"guǎnshù","vi":"quản thúc"},{"hanzi":"自由","pinyin":"zìyóu","vi":"tự do"}],"traditional":"約束"},{"id":"验证","hanzi":"验证","pinyin":"yànzhèng","meaning_vi":"kiểm chứng","explanation":"验 (nghiệm – kiểm tra) + 证 (chứng – chứng minh) → kiểm tra để chứng thực là đúng. Thường dùng: 验证理论, 验证码 (mã xác minh), 身份验证.","hsk_level":6,"tags":["dong-tu"],"image":"🔐","examples":[{"type":"basic","zh":"请输入验证码。","pinyin":"Qǐng shūrù yànzhèngmǎ.","vi":"Vui lòng nhập mã xác minh."},{"type":"simple","zh":"科学家用实验验证了这个假设。","pinyin":"Kēxué jiāyòng shíyàn yànzhèngle zhè ge jiǎshè.","vi":"Các nhà khoa học đã dùng thí nghiệm để kiểm chứng giả thuyết này."},{"type":"compound","zh":"理论虽然很完美，但是还需要在实践中验证。","pinyin":"Lǐlùn suīrán hěn wánměi, dànshì hái xūyào zài shíjiàn zhōng yànzhèng.","vi":"Lý thuyết tuy rất hoàn hảo nhưng vẫn cần được kiểm chứng trong thực tiễn."}],"related":[{"hanzi":"证实","pinyin":"zhèngshí","vi":"chứng thực"},{"hanzi":"检验","pinyin":"jiǎnyàn","vi":"kiểm nghiệm"},{"hanzi":"核实","pinyin":"héshí","vi":"xác minh"},{"hanzi":"验证码","pinyin":"yànzhèngmǎ","vi":"mã xác minh"}],"traditional":"驗證"},{"id":"要点","hanzi":"要点","pinyin":"yàodiǎn","meaning_vi":"điểm chính","explanation":"要 (yếu – quan trọng) + 点 (điểm – điểm) → những điểm chính, ý quan trọng nhất của một bài nói, bài viết. Ví dụ: 抓住要点, 讲话要点.","hsk_level":6,"tags":["danh-tu"],"image":"📌","examples":[{"type":"basic","zh":"请记下会议要点。","pinyin":"Qǐng jìxià huìyì yàodiǎn.","vi":"Hãy ghi lại các điểm chính của cuộc họp."},{"type":"simple","zh":"老师把这篇课文的要点写在了黑板上。","pinyin":"Lǎoshī bǎ zhè piān kèwén de yàodiǎn xiě zài le hēibǎn shang.","vi":"Thầy giáo viết các ý chính của bài khóa lên bảng."},{"type":"compound","zh":"只要抓住文章的要点，回答问题就不难了。","pinyin":"Zhǐyào zhuāzhù wénzhāng de yàodiǎn, huídá wèntí jiù bùnán le.","vi":"Chỉ cần nắm được ý chính của bài, trả lời câu hỏi sẽ không khó."}],"related":[{"hanzi":"重点","pinyin":"zhòngdiǎn","vi":"trọng điểm"},{"hanzi":"要领","pinyin":"yàolǐng","vi":"yếu lĩnh"},{"hanzi":"关键","pinyin":"guānjiàn","vi":"then chốt"},{"hanzi":"摘要","pinyin":"zhāiyào","vi":"tóm tắt"}],"traditional":"要點"},{"id":"耀眼","hanzi":"耀眼","pinyin":"yàoyǎn","meaning_vi":"chói mắt","explanation":"耀 (diệu – chiếu sáng) + 眼 (nhãn – mắt) → ánh sáng chói chang làm lóa mắt; nghĩa bóng là rực rỡ, nổi bật. Ví dụ: 耀眼的阳光, 耀眼的成绩.","hsk_level":6,"tags":["tinh-tu"],"image":"☀️","examples":[{"type":"basic","zh":"阳光很耀眼。","pinyin":"Yángguāng hěn yàoyǎn.","vi":"Ánh nắng rất chói mắt."},{"type":"simple","zh":"舞台上的她穿着一条耀眼的红裙子。","pinyin":"Wǔtái shang de tā chuānzhe yì tiáo yàoyǎn de hóng qúnzi.","vi":"Trên sân khấu, cô ấy mặc một chiếc váy đỏ rực rỡ chói lọi."},{"type":"compound","zh":"雪地反射的光太耀眼了，所以登山者都戴着墨镜。","pinyin":"Xuědì fǎnshè de guāng tài yàoyǎn le, suǒyǐ dēngshān zhě dōu dàizhe mòjìng.","vi":"Ánh sáng phản chiếu từ tuyết quá chói nên người leo núi đều đeo kính râm."}],"related":[{"hanzi":"刺眼","pinyin":"cìyǎn","vi":"chói mắt"},{"hanzi":"灿烂","pinyin":"cànlàn","vi":"rực rỡ"},{"hanzi":"夺目","pinyin":"duómù","vi":"lóa mắt"},{"hanzi":"光芒","pinyin":"guāngmáng","vi":"ánh sáng chói"}]},{"id":"严寒","hanzi":"严寒","pinyin":"yánhán","meaning_vi":"giá rét","explanation":"严 (nghiêm – gay gắt) + 寒 (hàn – lạnh) → lạnh buốt, rét đậm. Thường dùng: 严寒的冬天, 冒着严寒; đối lập với 酷暑 (nóng gay gắt).","hsk_level":6,"tags":["tinh-tu","thoi-tiet"],"image":"🥶","examples":[{"type":"basic","zh":"他们冒着严寒出发了。","pinyin":"Tāmen màozhe yánhán chūfā le.","vi":"Họ đội giá rét lên đường."},{"type":"simple","zh":"这些战士在严寒中坚守了整整一夜。","pinyin":"Zhèxiē zhànshì zài yánhán zhōng jiānshǒule zhěngzhěng yī yè.","vi":"Những chiến sĩ này đã kiên trì trấn giữ suốt một đêm trong giá rét."},{"type":"compound","zh":"虽然外面严寒刺骨，但是屋里的暖气很足。","pinyin":"Suīrán wàimiàn yánhán cìgǔ, dànshì wū li de nuǎnqì hěn zú.","vi":"Tuy bên ngoài lạnh buốt thấu xương nhưng trong nhà lò sưởi rất ấm."}],"related":[{"hanzi":"寒冷","pinyin":"hánlěng","vi":"rét lạnh"},{"hanzi":"酷暑","pinyin":"kùshǔ","vi":"nóng gắt"},{"hanzi":"冰冷","pinyin":"bīnglěng","vi":"lạnh buốt"},{"hanzi":"冬天","pinyin":"dōngtiān","vi":"mùa đông"}],"traditional":"嚴寒"},{"id":"严密","hanzi":"严密","pinyin":"yánmì","meaning_vi":"chặt chẽ","explanation":"严 (nghiêm – chặt) + 密 (mật – kín, dày) → chặt chẽ, kín kẽ, không có sơ hở. Thường đi với 组织严密, 严密监视, 逻辑严密.","hsk_level":6,"tags":["tinh-tu"],"image":"🔒","examples":[{"type":"basic","zh":"他的计划很严密。","pinyin":"Tā de jìhuà hěn yánmì.","vi":"Kế hoạch của anh ấy rất chặt chẽ."},{"type":"simple","zh":"警察对大楼周围进行了严密的监视。","pinyin":"Jǐngchá duì dàlóu zhōuwéi jìnxíngle yánmì de jiānshì.","vi":"Cảnh sát đã giám sát chặt chẽ khu vực xung quanh tòa nhà."},{"type":"compound","zh":"这篇论文不但逻辑严密，而且数据也很充分。","pinyin":"Zhè piān lùnwén búdàn luójí yánmì, érqiě shùjù yě hěn chōngfèn.","vi":"Bài luận văn này không chỉ lập luận chặt chẽ mà số liệu cũng rất đầy đủ."}],"related":[{"hanzi":"周密","pinyin":"zhōumì","vi":"chu đáo kín kẽ"},{"hanzi":"紧密","pinyin":"jǐnmì","vi":"chặt chẽ"},{"hanzi":"严谨","pinyin":"yánjǐn","vi":"nghiêm cẩn"},{"hanzi":"松散","pinyin":"sōngsǎn","vi":"lỏng lẻo"}],"traditional":"嚴密"},{"id":"言行一致","hanzi":"言行一致","pinyin":"yánxíng-yízhì","meaning_vi":"lời nói đi đôi với việc làm","explanation":"言行一致: lời nói (言) và hành động (行) thống nhất (一致) → nói sao làm vậy, đáng tin cậy. Trái nghĩa với 言行不一.","hsk_level":6,"tags":["thanh-ngu"],"image":"🤝","examples":[{"type":"basic","zh":"做人要言行一致。","pinyin":"Zuòrén yào yánxíngyízhì.","vi":"Làm người phải nói đi đôi với làm."},{"type":"simple","zh":"王老师是一位言行一致的好榜样。","pinyin":"Wáng lǎoshī shì yí wèi yánxíngyízhì de hǎo bǎngyàng.","vi":"Thầy Vương là tấm gương tốt luôn nói đi đôi với làm."},{"type":"compound","zh":"如果父母言行一致，孩子就会更信任他们。","pinyin":"Rúguǒ fùmǔ yánxíngyízhì, háizi jiù huì gèng xìnrèn tāmen.","vi":"Nếu cha mẹ nói đi đôi với làm, con cái sẽ tin tưởng họ hơn."}],"related":[{"hanzi":"表里如一","pinyin":"biǎolǐrúyī","vi":"trong ngoài như một"},{"hanzi":"说到做到","pinyin":"shuōdàozuòdào","vi":"nói được làm được"},{"hanzi":"言而有信","pinyin":"yán'éryǒuxìn","vi":"giữ lời"},{"hanzi":"言行不一","pinyin":"yánxíngbùyī","vi":"nói một đằng làm một nẻo"}]},{"id":"谣言","hanzi":"谣言","pinyin":"yáoyán","meaning_vi":"tin đồn nhảm","explanation":"谣 (dao – tin đồn, câu hát dân gian) + 言 (ngôn – lời) → tin đồn không có căn cứ, tin bịa đặt. Thường dùng: 造谣言, 散布谣言, 谣言不攻自破.","hsk_level":6,"tags":["danh-tu"],"image":"🗣️","examples":[{"type":"basic","zh":"不要相信谣言。","pinyin":"Bú yào xiāngxìn yáoyán.","vi":"Đừng tin tin đồn nhảm."},{"type":"simple","zh":"有人在网上散布关于这家餐厅的谣言。","pinyin":"Yǒurén zài wǎngshang sànbù guānyú zhè jiā cāntīng de yáoyán.","vi":"Có người tung tin đồn nhảm trên mạng về nhà hàng này."},{"type":"compound","zh":"谣言一传开，公司的股价就大幅下跌了。","pinyin":"Yáoyán yì chuánkāi, gōngsī de gǔjià jiù dàfú xiàdiē le.","vi":"Tin đồn vừa lan ra, giá cổ phiếu của công ty liền giảm mạnh."}],"related":[{"hanzi":"传言","pinyin":"chuányán","vi":"lời đồn"},{"hanzi":"造谣","pinyin":"zàoyáo","vi":"tung tin đồn"},{"hanzi":"谣传","pinyin":"yáochuán","vi":"tin đồn nhảm"},{"hanzi":"辟谣","pinyin":"pìyáo","vi":"bác bỏ tin đồn"}],"traditional":"謠言"},{"id":"液体","hanzi":"液体","pinyin":"yètǐ","meaning_vi":"chất lỏng","explanation":"液 (dịch – chất lỏng) + 体 (thể – thể, dạng) → chất ở thể lỏng, như nước, dầu. Đi cùng 固体 (thể rắn), 气体 (thể khí).","hsk_level":6,"tags":["danh-tu","khoa-hoc"],"image":"💧","examples":[{"type":"basic","zh":"水是一种液体。","pinyin":"Shuǐ shì yì zhǒng yètǐ.","vi":"Nước là một loại chất lỏng."},{"type":"simple","zh":"乘客不能携带超过一百毫升的液体登机。","pinyin":"Chéngkè bù néng xiédài chāoguò yī bǎi háoshēng de yètǐ dēngjī.","vi":"Hành khách không được mang chất lỏng quá một trăm mililít lên máy bay."},{"type":"compound","zh":"如果把冰加热，它就会从固体变成液体。","pinyin":"Rúguǒ bǎ bīng jiārè, tā jiù huì cóng gùtǐ biànchéng yètǐ.","vi":"Nếu đun nóng băng, nó sẽ chuyển từ thể rắn sang thể lỏng."}],"related":[{"hanzi":"固体","pinyin":"gùtǐ","vi":"chất rắn"},{"hanzi":"气体","pinyin":"qìtǐ","vi":"chất khí"},{"hanzi":"液态","pinyin":"yètài","vi":"thể lỏng"},{"hanzi":"流体","pinyin":"liútǐ","vi":"chất lưu"}],"traditional":"液體"},{"id":"一举一动","hanzi":"一举一动","pinyin":"yìjǔ-yídòng","meaning_vi":"từng cử chỉ hành động","explanation":"一举一动: mỗi lần giơ tay (举), mỗi lần cử động (动) → mọi cử chỉ, hành động dù nhỏ nhất. Ví dụ: 他的一举一动都受到关注.","hsk_level":6,"tags":["thanh-ngu"],"image":"👤","examples":[{"type":"basic","zh":"他的一举一动很优雅。","pinyin":"Tā de yìjǔyídòng hěn yōuyǎ.","vi":"Từng cử chỉ của anh ấy rất tao nhã."},{"type":"simple","zh":"明星的一举一动都受到记者的关注。","pinyin":"Míngxīng de yìjǔyídòng dōu shòudào jìzhě de guānzhù.","vi":"Mỗi cử chỉ hành động của ngôi sao đều bị phóng viên chú ý."},{"type":"compound","zh":"因为孩子会模仿大人，所以父母要注意自己的一举一动。","pinyin":"Yīnwèi háizi huì mófǎng dàrén, suǒyǐ fùmǔ yào zhùyì zìjǐ de yìjǔyídòng.","vi":"Vì trẻ con hay bắt chước người lớn nên cha mẹ phải chú ý từng cử chỉ của mình."}],"related":[{"hanzi":"举动","pinyin":"jǔdòng","vi":"cử chỉ"},{"hanzi":"一言一行","pinyin":"yìyányìxíng","vi":"mỗi lời nói việc làm"},{"hanzi":"举止","pinyin":"jǔzhǐ","vi":"cử chỉ"},{"hanzi":"行为","pinyin":"xíngwéi","vi":"hành vi"}],"traditional":"一舉一動"},{"id":"意料","hanzi":"意料","pinyin":"yìliào","meaning_vi":"dự liệu","explanation":"意 (ý – ý nghĩ) + 料 (liệu – liệu tính) → dự đoán, đoán trước. Thường gặp trong 出乎意料 (ngoài dự liệu), 意料之中, 意料之外.","hsk_level":6,"tags":["dong-tu"],"image":"😲","examples":[{"type":"basic","zh":"这在意料之中。","pinyin":"Zhè zài yìliào zhīzhōng.","vi":"Điều này nằm trong dự liệu."},{"type":"simple","zh":"谁也没有意料到他会突然辞职。","pinyin":"Shuí yě méi yǒuyì liàodào tā huì tūrán cízhí.","vi":"Không ai ngờ được anh ấy lại đột ngột nghỉ việc."},{"type":"compound","zh":"虽然大家都看好主队，但是比赛结果完全出乎意料。","pinyin":"Suīrán dàjiā dōu kànhǎo zhǔduì, dànshì bǐsài jiéguǒ wánquán chūhūyìliào.","vi":"Tuy mọi người đều đặt kỳ vọng vào đội chủ nhà nhưng kết quả trận đấu hoàn toàn ngoài dự liệu."}],"related":[{"hanzi":"预料","pinyin":"yùliào","vi":"dự đoán"},{"hanzi":"出乎意料","pinyin":"chūhūyìliào","vi":"ngoài dự liệu"},{"hanzi":"意外","pinyin":"yìwài","vi":"bất ngờ"},{"hanzi":"意料之中","pinyin":"yìliàozhīzhōng","vi":"trong dự liệu"}]},{"id":"毅力","hanzi":"毅力","pinyin":"yìlì","meaning_vi":"nghị lực","explanation":"毅 (nghị – cương quyết) + 力 (lực – sức) → sức mạnh ý chí bền bỉ, kiên trì đến cùng. Thường nói: 有毅力, 惊人的毅力, 靠毅力坚持下来.","hsk_level":6,"tags":["danh-tu"],"image":"🦁","examples":[{"type":"basic","zh":"他很有毅力。","pinyin":"Tā hěn yǒuyìlì.","vi":"Anh ấy rất có nghị lực."},{"type":"simple","zh":"她凭着惊人的毅力跑完了全程马拉松。","pinyin":"Tā píngzhe jīngrén de yìlì pǎo wánle quánchéng mǎlāsōng.","vi":"Cô ấy dựa vào nghị lực đáng kinh ngạc mà chạy hết cự ly marathon."},{"type":"compound","zh":"学外语没有捷径，只要有毅力，就一定能学好。","pinyin":"Xué wàiyǔ méiyǒu jiéjìng, zhǐyào yǒuyìlì, jiù yídìng néng xuéhǎo.","vi":"Học ngoại ngữ không có đường tắt, chỉ cần có nghị lực thì nhất định sẽ học tốt."}],"related":[{"hanzi":"意志","pinyin":"yìzhì","vi":"ý chí"},{"hanzi":"恒心","pinyin":"héngxīn","vi":"lòng kiên trì"},{"hanzi":"坚持","pinyin":"jiānchí","vi":"kiên trì"},{"hanzi":"耐力","pinyin":"nàilì","vi":"sức bền"}]},{"id":"一模一样","hanzi":"一模一样","pinyin":"yìmú-yíyàng","meaning_vi":"giống hệt như đúc","explanation":"一模一样: cùng một khuôn (模), cùng một dạng (样) → giống hệt nhau như đúc từ một khuôn ra. Ví dụ: 双胞胎长得一模一样.","hsk_level":6,"tags":["thanh-ngu"],"image":"👯","examples":[{"type":"basic","zh":"这对双胞胎长得一模一样。","pinyin":"Zhè duì shuāngbāotāi zhǎngde yìmúyíyàng.","vi":"Cặp song sinh này giống nhau như đúc."},{"type":"simple","zh":"我在商场看到一件和你一模一样的大衣。","pinyin":"Wǒ zài shāngchǎng kàndào yí jiàn hé nǐ yìmúyíyàng de dàyī.","vi":"Tôi thấy ở trung tâm thương mại một chiếc áo khoác giống hệt cái của bạn."},{"type":"compound","zh":"两份作业的答案一模一样，所以老师怀疑有人抄袭。","pinyin":"Liǎng fèn zuòyè de dá'àn yìmúyíyàng, suǒyǐ lǎoshī huáiyí yǒurén chāoxí.","vi":"Đáp án hai bài tập giống hệt nhau nên thầy giáo nghi có người chép bài."}],"related":[{"hanzi":"相同","pinyin":"xiāngtóng","vi":"giống nhau"},{"hanzi":"一样","pinyin":"yíyàng","vi":"như nhau"},{"hanzi":"如出一辙","pinyin":"rúchūyìzhé","vi":"giống như đúc"},{"hanzi":"截然不同","pinyin":"jiéránbùtóng","vi":"hoàn toàn khác"}],"traditional":"一模一樣"},{"id":"一如既往","hanzi":"一如既往","pinyin":"yìrú-jìwǎng","meaning_vi":"trước sau như một","explanation":"一如既往: hoàn toàn (一) như (如) đã qua (既往) → trước sau như một, giữ nguyên như trước đây. Thường đi với 一如既往地支持, 一如既往地关心.","hsk_level":6,"tags":["thanh-ngu"],"image":"🔄","examples":[{"type":"basic","zh":"他一如既往地努力。","pinyin":"Tā yìrújìwǎng de nǔlì.","vi":"Anh ấy vẫn chăm chỉ như trước."},{"type":"simple","zh":"这家老店的饺子一如既往地好吃。","pinyin":"Zhè jiālǎo diàn de jiǎozi yìrújìwǎng de hǎochī.","vi":"Sủi cảo của tiệm lâu năm này vẫn ngon như xưa."},{"type":"compound","zh":"即使公司遇到困难，我们也会一如既往地支持你。","pinyin":"Jíshǐ gōngsī yùdào kùnnan, wǒmen yě huì yìrújìwǎng de zhīchí nǐ.","vi":"Dù công ty gặp khó khăn, chúng tôi vẫn sẽ ủng hộ bạn trước sau như một."}],"related":[{"hanzi":"始终如一","pinyin":"shǐzhōngrúyī","vi":"trước sau như một"},{"hanzi":"一贯","pinyin":"yíguàn","vi":"nhất quán"},{"hanzi":"依旧","pinyin":"yījiù","vi":"vẫn như cũ"},{"hanzi":"照常","pinyin":"zhàocháng","vi":"như thường lệ"}]},{"id":"意味着","hanzi":"意味着","pinyin":"yìwèizhe","meaning_vi":"có nghĩa là","explanation":"意 (ý – ý nghĩa) + 味 (vị – mùi vị, hàm ý) + 着 (trợ từ) → hàm ý là, đồng nghĩa với việc. Ví dụ: 放弃意味着失败.","hsk_level":6,"tags":["dong-tu"],"image":"💡","examples":[{"type":"basic","zh":"沉默意味着同意。","pinyin":"Chénmò yìwèizhe tóngyì.","vi":"Im lặng có nghĩa là đồng ý."},{"type":"simple","zh":"红灯亮起意味着所有车辆必须停下。","pinyin":"Hóngdēng liàng qǐ yìwèizhe suǒyǒu chēliàng bìxū tíngxià.","vi":"Đèn đỏ bật lên có nghĩa là mọi xe phải dừng lại."},{"type":"compound","zh":"毕业不但意味着结束，而且意味着新的开始。","pinyin":"Bìyè búdàn yìwèizhe jiéshù, érqiě yìwèizhe xīn de kāishǐ.","vi":"Tốt nghiệp không chỉ có nghĩa là kết thúc mà còn là một khởi đầu mới."}],"related":[{"hanzi":"表示","pinyin":"biǎoshì","vi":"biểu thị"},{"hanzi":"意思","pinyin":"yìsi","vi":"ý nghĩa"},{"hanzi":"象征","pinyin":"xiàngzhēng","vi":"tượng trưng"},{"hanzi":"代表","pinyin":"dàibiǎo","vi":"đại diện cho"}],"traditional":"意味著"},{"id":"一心一意","hanzi":"一心一意","pinyin":"yìxīn-yíyì","meaning_vi":"toàn tâm toàn ý","explanation":"一心一意: một lòng một ý → chuyên tâm làm một việc, không có ý nghĩ khác. Ví dụ: 一心一意为人民服务, 一心一意地学习.","hsk_level":6,"tags":["thanh-ngu"],"image":"❤️","examples":[{"type":"basic","zh":"他一心一意工作。","pinyin":"Tā yìxīnyíyì gōngzuò.","vi":"Anh ấy toàn tâm toàn ý làm việc."},{"type":"simple","zh":"退休后，爷爷一心一意地照顾花园。","pinyin":"Tuìxiū hòu, yéye yìxīnyíyì de zhàogù huāyuán.","vi":"Sau khi nghỉ hưu, ông nội dồn hết tâm sức chăm sóc khu vườn."},{"type":"compound","zh":"只要你一心一意地对待她，她就会感受到你的真心。","pinyin":"Zhǐyào nǐ yìxīnyíyì de duìdài tā, tā jiù huì gǎn shòudào nǐ de zhēnxīn.","vi":"Chỉ cần bạn đối xử với cô ấy toàn tâm toàn ý, cô ấy sẽ cảm nhận được chân tình của bạn."}],"related":[{"hanzi":"全心全意","pinyin":"quánxīnquányì","vi":"toàn tâm toàn ý"},{"hanzi":"专心致志","pinyin":"zhuānxīnzhìzhì","vi":"chuyên tâm dốc chí"},{"hanzi":"三心二意","pinyin":"sānxīn'èryì","vi":"không chuyên tâm"},{"hanzi":"专心","pinyin":"zhuānxīn","vi":"chuyên tâm"}]},{"id":"一针见血","hanzi":"一针见血","pinyin":"yìzhēn-jiànxiě","meaning_vi":"nói trúng tim đen, nhận xét sắc bén đi thẳng vào trọng tâm","explanation":"一针见血: một mũi kim châm là thấy máu (như châm cứu trúng huyệt) → lời nói ngắn gọn mà đánh trúng thực chất vấn đề.","hsk_level":6,"tags":["thanh-ngu"],"image":"💉","examples":[{"type":"basic","zh":"他的评论一针见血。","pinyin":"Tā de pínglùn yìzhēnjiànxiě.","vi":"Lời bình của anh ấy đi thẳng vào trọng tâm."},{"type":"simple","zh":"教授一针见血地指出了方案的漏洞。","pinyin":"Jiàoshòu yìzhēnjiànxiě de zhǐchūle fāng'àn de lòudòng.","vi":"Giáo sư sắc bén chỉ ra ngay lỗ hổng của phương án."},{"type":"compound","zh":"他的话虽然不多，但是每句都一针见血。","pinyin":"Tā dehuà suīrán bù duō, dànshì měi jù dōu yìzhēnjiànxiě.","vi":"Anh ấy tuy nói không nhiều nhưng câu nào cũng trúng tim đen."}],"related":[{"hanzi":"一语道破","pinyin":"yìyǔdàopò","vi":"một câu nói trúng"},{"hanzi":"切中要害","pinyin":"qièzhòngyàohài","vi":"trúng chỗ hiểm"},{"hanzi":"尖锐","pinyin":"jiānruì","vi":"sắc bén"},{"hanzi":"不着边际","pinyin":"bùzhuóbiānjì","vi":"chẳng ăn nhập gì"}],"traditional":"一針見血"},{"id":"遗留","hanzi":"遗留","pinyin":"yíliú","meaning_vi":"để lại, sót lại","explanation":"遗 (di – để lại) + 留 (lưu – giữ lại) → để lại từ trước, còn sót lại đến nay. Thường đi với 历史遗留问题, 遗留下来的习俗.","hsk_level":6,"tags":["dong-tu"],"image":"📜","examples":[{"type":"basic","zh":"这是历史遗留问题。","pinyin":"Zhè shì lìshǐ yíliú wèntí.","vi":"Đây là vấn đề do lịch sử để lại."},{"type":"simple","zh":"前任经理遗留下了一大堆没处理的文件。","pinyin":"Qiánrèn jīnglǐ yíliú xiàle yí dà duī méi chǔlǐ de wénjiàn.","vi":"Giám đốc tiền nhiệm để lại một đống hồ sơ chưa xử lý."},{"type":"compound","zh":"因为上次装修遗留了不少问题，所以这次要格外小心。","pinyin":"Yīnwèi shàngcì zhuāngxiū yíliúle bùshǎo wèntí, suǒyǐ zhè cìyào géwài xiǎoxīn.","vi":"Vì lần sửa nhà trước để lại không ít vấn đề nên lần này phải đặc biệt cẩn thận."}],"related":[{"hanzi":"遗产","pinyin":"yíchǎn","vi":"di sản"},{"hanzi":"留下","pinyin":"liúxià","vi":"để lại"},{"hanzi":"遗留问题","pinyin":"yíliúwèntí","vi":"vấn đề tồn đọng"},{"hanzi":"残留","pinyin":"cánliú","vi":"sót lại"}],"traditional":"遺留"},{"id":"一诺千金","hanzi":"一诺千金","pinyin":"yínuò-qiānjīn","meaning_vi":"một lời hứa đáng giá nghìn vàng","explanation":"一诺千金: một lời hứa (诺) đáng nghìn vàng (truyện Quý Bố đời Hán rất giữ chữ tín) → giữ lời hứa tuyệt đối, rất đáng tin cậy.","hsk_level":6,"tags":["thanh-ngu"],"image":"💰","examples":[{"type":"basic","zh":"他向来一诺千金。","pinyin":"Tā xiànglái yínuòqiānjīn.","vi":"Anh ấy xưa nay luôn giữ lời hứa."},{"type":"simple","zh":"张老板是生意圈里出了名的一诺千金的人。","pinyin":"Zhāng lǎobǎn shì shēngyi quān li chūle míng de yínuòqiānjīn de rén.","vi":"Ông chủ Trương là người nổi tiếng giữ chữ tín trong giới kinh doanh."},{"type":"compound","zh":"既然你答应了别人，就应该一诺千金，说到做到。","pinyin":"Jìrán nǐ dāyingle biérén, jiù yīnggāi yínuòqiānjīn, shuōdào zuòdào.","vi":"Đã hứa với người ta thì phải giữ lời, nói được làm được."}],"related":[{"hanzi":"言而有信","pinyin":"yán'éryǒuxìn","vi":"giữ lời hứa"},{"hanzi":"信守诺言","pinyin":"xìnshǒunuòyán","vi":"giữ đúng lời hứa"},{"hanzi":"承诺","pinyin":"chéngnuò","vi":"cam kết"},{"hanzi":"言而无信","pinyin":"yán'érwúxìn","vi":"nói không giữ lời"}],"traditional":"一諾千金"},{"id":"一视同仁","hanzi":"一视同仁","pinyin":"yíshì-tóngrén","meaning_vi":"đối xử bình đẳng như nhau không thiên vị","explanation":"一视同仁: nhìn (视) như nhau, cùng (同) một lòng nhân (仁) → đối xử công bằng với mọi người, không phân biệt thân sơ, sang hèn.","hsk_level":6,"tags":["thanh-ngu"],"image":"⚖️","examples":[{"type":"basic","zh":"老师对学生一视同仁。","pinyin":"Lǎoshī duì xuésheng yíshìtóngrén.","vi":"Thầy giáo đối xử với học sinh như nhau."},{"type":"simple","zh":"这家医院对所有病人都一视同仁。","pinyin":"Zhè jiā yīyuàn duì suǒyǒu bìngrén dōu yíshìtóngrén.","vi":"Bệnh viện này đối xử bình đẳng với mọi bệnh nhân."},{"type":"compound","zh":"不管顾客穿得怎么样，店员都应该一视同仁。","pinyin":"Bùguǎn gùkè chuān de zěnmeyàng, diànyuán dōu yīnggāi yíshìtóngrén.","vi":"Bất kể khách hàng ăn mặc thế nào, nhân viên cửa hàng đều nên đối xử như nhau."}],"related":[{"hanzi":"公平","pinyin":"gōngpíng","vi":"công bằng"},{"hanzi":"平等","pinyin":"píngděng","vi":"bình đẳng"},{"hanzi":"不偏不倚","pinyin":"bùpiānbùyǐ","vi":"không thiên vị"},{"hanzi":"偏心","pinyin":"piānxīn","vi":"thiên vị"}],"traditional":"一視同仁"},{"id":"迎面","hanzi":"迎面","pinyin":"yíngmiàn","meaning_vi":"trước mặt, thẳng vào mặt, ngược chiều tới","explanation":"迎 (nghênh – đón) + 面 (diện – mặt) → ngay trước mặt, đối diện hướng tới. Thường làm trạng ngữ: 迎面走来, 迎面吹来一阵风, 迎面相撞.","hsk_level":6,"tags":["pho-tu"],"image":"👀","examples":[{"type":"basic","zh":"冷风迎面吹来。","pinyin":"Lěng fēng yíngmiàn chuī lái.","vi":"Gió lạnh thổi thốc vào mặt."},{"type":"simple","zh":"一辆自行车迎面向我骑了过来。","pinyin":"Yí liàng zìxíngchē yíng miànxiàng wǒ qíle guòlái.","vi":"Một chiếc xe đạp lao thẳng về phía tôi từ phía trước."},{"type":"compound","zh":"一打开车门，一股热浪就迎面扑了过来。","pinyin":"Yì dǎkāi chēmén, yì gǔ rèlàng jiù yíngmiàn pūle guòlái.","vi":"Vừa mở cửa xe, một luồng hơi nóng liền ập thẳng vào mặt."}],"related":[{"hanzi":"迎面而来","pinyin":"yíngmiàn'érlái","vi":"đi ngược chiều tới"},{"hanzi":"对面","pinyin":"duìmiàn","vi":"đối diện"},{"hanzi":"迎接","pinyin":"yíngjiē","vi":"nghênh đón"},{"hanzi":"当面","pinyin":"dāngmiàn","vi":"trước mặt"}]},{"id":"用户","hanzi":"用户","pinyin":"yònghù","meaning_vi":"người dùng","explanation":"用 (dụng – dùng) + 户 (hộ – hộ, nhà) → người dùng, khách hàng sử dụng một sản phẩm hay dịch vụ. Thường gặp: 用户名, 用户体验, 手机用户.","hsk_level":6,"tags":["danh-tu","cong-nghe"],"image":"👤","examples":[{"type":"basic","zh":"用户越来越多了。","pinyin":"Yònghù yuèláiyuè duō le.","vi":"Người dùng ngày càng nhiều."},{"type":"simple","zh":"这款聊天应用在全球拥有上亿用户。","pinyin":"Zhè kuǎn liáotiān yìngyòng zài quánqiú yōngyǒu shàng yì yònghù.","vi":"Ứng dụng nhắn tin này có hơn trăm triệu người dùng trên toàn cầu."},{"type":"compound","zh":"如果用户反映的问题不及时解决，产品就会失去口碑。","pinyin":"Rúguǒ yònghù fǎnyìng de wèntí bù jíshí jiějué, chǎnpǐn jiù huì shīqù kǒubēi.","vi":"Nếu vấn đề người dùng phản ánh không được giải quyết kịp thời, sản phẩm sẽ mất uy tín."}],"related":[{"hanzi":"顾客","pinyin":"gùkè","vi":"khách hàng"},{"hanzi":"客户","pinyin":"kèhù","vi":"khách hàng"},{"hanzi":"使用者","pinyin":"shǐyòngzhě","vi":"người sử dụng"},{"hanzi":"用户名","pinyin":"yònghùmíng","vi":"tên người dùng"}],"traditional":"用戶"},{"id":"油漆","hanzi":"油漆","pinyin":"yóuqī","meaning_vi":"sơn (dầu); quét sơn","explanation":"油 (du – dầu) + 漆 (tất – sơn) → sơn phủ lên gỗ, kim loại, tường; cũng dùng làm động từ \"sơn\". Ví dụ: 刷油漆, 油漆未干 (sơn chưa khô).","hsk_level":6,"tags":["danh-tu","do-vat"],"image":"🎨","examples":[{"type":"basic","zh":"小心，油漆未干！","pinyin":"Xiǎoxīn, yóuqī wèi gān!","vi":"Cẩn thận, sơn chưa khô!"},{"type":"simple","zh":"爸爸周末把旧门刷了一层白油漆。","pinyin":"Bàba zhōumò bǎ jiù mén shuāle yīcéng bái yóuqī.","vi":"Cuối tuần bố sơn lại cánh cửa cũ một lớp sơn trắng."},{"type":"compound","zh":"新油漆的味道很大，所以我们打算过一个月再搬进去。","pinyin":"Xīn yóuqī de wèidao hěn dà, suǒyǐ wǒmen dǎsuànguò yí gèyuè zài bān jìnqu.","vi":"Mùi sơn mới rất nồng nên chúng tôi định một tháng nữa mới chuyển vào."}],"related":[{"hanzi":"涂料","pinyin":"túliào","vi":"sơn phủ"},{"hanzi":"刷漆","pinyin":"shuāqī","vi":"quét sơn"},{"hanzi":"油漆未干","pinyin":"yóuqīwèigān","vi":"sơn chưa khô"},{"hanzi":"颜料","pinyin":"yánliào","vi":"chất màu"}]},{"id":"愈","hanzi":"愈","pinyin":"yù","meaning_vi":"càng; khỏi (bệnh)","explanation":"愈 (dũ): càng; cũng có nghĩa khỏi bệnh. Thường dùng trong cấu trúc 愈…愈… (càng…càng…) và từ 痊愈 (khỏi hẳn), 愈加, 愈来愈.","hsk_level":6,"tags":["pho-tu"],"image":"📈","examples":[{"type":"basic","zh":"雨愈下愈大。","pinyin":"Yǔ yù xià yù dà.","vi":"Mưa càng lúc càng to."},{"type":"simple","zh":"这首老歌愈听愈有味道。","pinyin":"Zhè shǒu lǎogē yù tīng yù yǒu wèidao.","vi":"Bài hát cũ này càng nghe càng thấm."},{"type":"compound","zh":"问题拖得愈久，以后解决起来就愈困难。","pinyin":"Wèntí tuō de yù jiǔ, yǐhòu jiějué qǐlái jiù yù kùnnan.","vi":"Vấn đề càng kéo dài lâu thì giải quyết càng khó khăn."}],"related":[{"hanzi":"越","pinyin":"yuè","vi":"càng"},{"hanzi":"愈来愈","pinyin":"yùláiyù","vi":"càng ngày càng"},{"hanzi":"愈加","pinyin":"yùjiā","vi":"càng thêm"},{"hanzi":"痊愈","pinyin":"quányù","vi":"khỏi bệnh"}]},{"id":"预先","hanzi":"预先","pinyin":"yùxiān","meaning_vi":"trước, từ trước","explanation":"预 (dự – trước) + 先 (tiên – trước) → trước, từ trước khi sự việc xảy ra. Ví dụ: 预先通知, 预先准备; đồng nghĩa 事先.","hsk_level":6,"tags":["pho-tu"],"image":"⏪","examples":[{"type":"basic","zh":"请预先订座。","pinyin":"Qǐng yùxiān dìng zuò.","vi":"Vui lòng đặt chỗ trước."},{"type":"simple","zh":"导游预先为我们准备好了门票。","pinyin":"Dǎoyóu yùxiān wèi wǒmen zhǔnbèihǎole ménpiào.","vi":"Hướng dẫn viên đã chuẩn bị sẵn vé vào cửa cho chúng tôi từ trước."},{"type":"compound","zh":"如果你能预先通知我，我就去车站接你。","pinyin":"Rúguǒ nǐ néng yùxiān tōngzhī wǒ, wǒ jiù qù chēzhàn jiē nǐ.","vi":"Nếu bạn báo trước cho tôi, tôi sẽ ra ga đón bạn."}],"related":[{"hanzi":"事先","pinyin":"shìxiān","vi":"trước đó"},{"hanzi":"提前","pinyin":"tíqián","vi":"trước thời hạn"},{"hanzi":"预定","pinyin":"yùdìng","vi":"đặt trước"},{"hanzi":"事后","pinyin":"shìhòu","vi":"sau đó"}],"traditional":"預先"},{"id":"酝酿","hanzi":"酝酿","pinyin":"yùnniàng","meaning_vi":"ấp ủ","explanation":"酝 (uấn – ủ rượu) + 酿 (nhưỡng – cất rượu) → nghĩa gốc là ủ rượu, nghĩa bóng là ấp ủ, chuẩn bị dần một kế hoạch. Ví dụ: 酝酿计划, 酝酿已久.","hsk_level":6,"tags":["dong-tu"],"image":"🍷","examples":[{"type":"basic","zh":"他们在酝酿新计划。","pinyin":"Tāmen zài yùnniàng xīn jìhuà.","vi":"Họ đang ấp ủ kế hoạch mới."},{"type":"simple","zh":"这位作家酝酿了五年才写出这部小说。","pinyin":"Zhè wèi zuòjiā yùnniàngle wǔ nián cái xiě chū zhè bù xiǎoshuō.","vi":"Nhà văn này ấp ủ năm năm mới viết ra cuốn tiểu thuyết."},{"type":"compound","zh":"既然大家都同意改革，那就先酝酿一个具体方案。","pinyin":"Jìrán dàjiā dōu tóngyì gǎigé, nà jiù xiān yùnniàng yí gè jùtǐ fāng'àn.","vi":"Mọi người đã đồng ý cải cách thì trước hết hãy bàn bạc chuẩn bị một phương án cụ thể."}],"related":[{"hanzi":"筹备","pinyin":"chóubèi","vi":"trù bị"},{"hanzi":"策划","pinyin":"cèhuà","vi":"lên kế hoạch"},{"hanzi":"孕育","pinyin":"yùnyù","vi":"thai nghén"},{"hanzi":"准备","pinyin":"zhǔnbèi","vi":"chuẩn bị"}],"traditional":"醞釀"},{"id":"孕育","hanzi":"孕育","pinyin":"yùnyù","meaning_vi":"thai nghén","explanation":"孕 (dựng – mang thai) + 育 (dục – nuôi dưỡng) → mang thai và sinh nở; nghĩa bóng là ấp ủ, nuôi dưỡng cái mới. Ví dụ: 孕育新生命, 孕育着希望.","hsk_level":6,"tags":["dong-tu"],"image":"🌱","examples":[{"type":"basic","zh":"大地孕育了生命。","pinyin":"Dàdì yùnyùle shēngmìng.","vi":"Đất mẹ đã thai nghén sự sống."},{"type":"simple","zh":"黄河孕育了灿烂的中华文明。","pinyin":"Huánghé yùnyùle cànlàn de zhōnghuáwénmíng.","vi":"Sông Hoàng Hà đã sinh ra nền văn minh Trung Hoa rực rỡ."},{"type":"compound","zh":"每一次危机不但带来挑战，而且孕育着新的机会。","pinyin":"Měi yí cì wēijī búdàn dàilái tiǎozhàn, érqiě yùnyùzhe xīn de jīhuì.","vi":"Mỗi cuộc khủng hoảng không chỉ mang đến thách thức mà còn ấp ủ những cơ hội mới."}],"related":[{"hanzi":"孕妇","pinyin":"yùnfù","vi":"phụ nữ mang thai"},{"hanzi":"酝酿","pinyin":"yùnniàng","vi":"ấp ủ"},{"hanzi":"培育","pinyin":"péiyù","vi":"ươm trồng"},{"hanzi":"诞生","pinyin":"dànshēng","vi":"ra đời"}]},{"id":"愚蠢","hanzi":"愚蠢","pinyin":"yúchǔn","meaning_vi":"ngu xuẩn","explanation":"愚 (ngu – ngu dốt) + 蠢 (xuẩn – đần độn) → ngu ngốc, đần độn. Mức độ nặng, mang sắc thái chê bai. Ví dụ: 愚蠢的行为, 愚蠢的想法.","hsk_level":6,"tags":["tinh-tu"],"image":"🤪","examples":[{"type":"basic","zh":"这个想法很愚蠢。","pinyin":"Zhè ge xiǎngfǎ hěn yúchǔn.","vi":"Ý nghĩ này rất ngu xuẩn."},{"type":"simple","zh":"我为自己昨天的愚蠢行为感到后悔。","pinyin":"Wǒ wèi zìjǐ zuótiān de yúchǔn xíngwéi gǎndào hòuhuǐ.","vi":"Tôi hối hận về hành động ngu ngốc của mình hôm qua."},{"type":"compound","zh":"如果明知是骗局还投钱，那就太愚蠢了。","pinyin":"Rúguǒ míngzhī shì piànjú hái tóu qián, nà jiù tài yúchǔn le.","vi":"Nếu biết rõ là lừa đảo mà vẫn bỏ tiền vào thì quá ngu ngốc."}],"related":[{"hanzi":"笨","pinyin":"bèn","vi":"ngốc"},{"hanzi":"愚昧","pinyin":"yúmèi","vi":"ngu muội"},{"hanzi":"聪明","pinyin":"cōngmíng","vi":"thông minh"},{"hanzi":"傻","pinyin":"shǎ","vi":"khờ"}]},{"id":"压岁钱","hanzi":"压岁钱","pinyin":"yāsuìqián","meaning_vi":"tiền lì xì","explanation":"压 (áp – đè, trấn) + 岁 (tuế – năm, tuổi) + 钱 (tiền) → tiền \"trấn tuổi\" người lớn mừng trẻ em dịp Tết để cầu bình an, tức tiền lì xì. Thường nói: 给压岁钱.","hsk_level":6,"tags":["danh-tu","van-hoa"],"image":"🧧","examples":[{"type":"basic","zh":"奶奶给我压岁钱。","pinyin":"Nǎinai gěi wǒ yāsuìqián.","vi":"Bà cho tôi tiền lì xì."},{"type":"simple","zh":"春节时孩子们最盼望的就是收压岁钱。","pinyin":"Chūnjié shí háizimen zuì pànwàng de jiùshì shōu yāsuìqián.","vi":"Dịp Tết, điều bọn trẻ mong nhất là được nhận tiền lì xì."},{"type":"compound","zh":"弟弟没有乱花压岁钱，而是把它存起来买书。","pinyin":"Dìdi méiyǒu luànhuā yāsuìqián, érshì bǎ tā cún qǐlái mǎi shū.","vi":"Em trai không tiêu xài lung tung tiền lì xì mà để dành mua sách."}],"related":[{"hanzi":"红包","pinyin":"hóngbāo","vi":"bao lì xì"},{"hanzi":"春节","pinyin":"Chūnjié","vi":"Tết"},{"hanzi":"拜年","pinyin":"bàinián","vi":"chúc Tết"},{"hanzi":"除夕","pinyin":"Chúxī","vi":"đêm giao thừa"}],"traditional":"壓歲錢"},{"id":"淹没","hanzi":"淹没","pinyin":"yānmò","meaning_vi":"nhấn chìm","explanation":"淹 (yêm – ngập) + 没 (một – chìm) → nước tràn lên làm ngập, chìm; nghĩa bóng là bị lấn át, lẫn mất. Ví dụ: 洪水淹没村庄, 声音被淹没在人群中.","hsk_level":6,"tags":["dong-tu"],"image":"🌊","examples":[{"type":"basic","zh":"洪水淹没了村庄。","pinyin":"Hóngshuǐ yānmòle cūnzhuāng.","vi":"Lũ lụt đã nhấn chìm ngôi làng."},{"type":"simple","zh":"他的声音很快被观众的欢呼声淹没了。","pinyin":"Tā de shēngyīn hěn kuài bèi guānzhòng de huānhū shēng yānmò le.","vi":"Giọng anh ấy nhanh chóng bị tiếng hò reo của khán giả nhấn chìm."},{"type":"compound","zh":"一到雨季，村口这条路就会被河水淹没。","pinyin":"Yí dào yǔjì, cūn kǒu zhè tiáo lù jiù huì bèi héshuǐ yānmò.","vi":"Cứ đến mùa mưa, con đường đầu làng này lại bị nước sông nhấn chìm."}],"related":[{"hanzi":"淹","pinyin":"yān","vi":"ngập"},{"hanzi":"洪水","pinyin":"hóngshuǐ","vi":"lũ lụt"},{"hanzi":"埋没","pinyin":"máimò","vi":"vùi lấp"},{"hanzi":"沉没","pinyin":"chénmò","vi":"chìm"}],"traditional":"淹沒"},{"id":"依旧","hanzi":"依旧","pinyin":"yījiù","meaning_vi":"vẫn như cũ","explanation":"依 (y – dựa theo) + 旧 (cựu – cũ) → vẫn như cũ, không thay đổi. Thường làm trạng từ: 依旧美丽, 风景依旧; đồng nghĩa 仍旧, 依然.","hsk_level":6,"tags":["pho-tu"],"image":"🔄","examples":[{"type":"basic","zh":"风景依旧美丽。","pinyin":"Fēngjǐng yījiù měilì.","vi":"Phong cảnh vẫn đẹp như xưa."},{"type":"simple","zh":"退休多年的爷爷依旧每天早起锻炼。","pinyin":"Tuìxiū duōnián de yéye yījiù měitiān zǎoqǐ duànliàn.","vi":"Ông nội nghỉ hưu nhiều năm mà sáng nào vẫn dậy sớm tập thể dục."},{"type":"compound","zh":"虽然吃了药，但是他的咳嗽依旧没有好转。","pinyin":"Suīrán chīle yào, dànshì tā de késou yījiù méiyǒu hǎozhuǎn.","vi":"Tuy đã uống thuốc nhưng cơn ho của anh ấy vẫn chưa đỡ."}],"related":[{"hanzi":"依然","pinyin":"yīrán","vi":"vẫn"},{"hanzi":"仍然","pinyin":"réngrán","vi":"vẫn còn"},{"hanzi":"照旧","pinyin":"zhàojiù","vi":"như cũ"},{"hanzi":"一如既往","pinyin":"yìrújìwǎng","vi":"trước sau như một"}],"traditional":"依舊"},{"id":"依赖","hanzi":"依赖","pinyin":"yīlài","meaning_vi":"ỷ lại","explanation":"依 (y – dựa) + 赖 (lại – nhờ cậy) → dựa dẫm, ỷ lại, phụ thuộc. Thường đi với 依赖父母, 依赖性, 对…产生依赖.","hsk_level":6,"tags":["dong-tu"],"image":"🔗","examples":[{"type":"basic","zh":"他太依赖父母了。","pinyin":"Tā tài yīlài fùmǔ le.","vi":"Anh ấy quá ỷ lại vào bố mẹ."},{"type":"simple","zh":"现代人越来越依赖手机导航找路。","pinyin":"Xiàndàirén yuèláiyuè yīlài shǒujī dǎoháng zhǎo lù.","vi":"Người hiện đại ngày càng phụ thuộc vào định vị trên điện thoại để tìm đường."},{"type":"compound","zh":"如果总是依赖别人帮忙，你就永远学不会独立。","pinyin":"Rúguǒ zǒngshì yīlài biérén bāngmáng, nǐ jiù yǒngyuǎn xué bú huì dúlì.","vi":"Nếu lúc nào cũng dựa dẫm vào người khác, bạn sẽ mãi không học được cách tự lập."}],"related":[{"hanzi":"依靠","pinyin":"yīkào","vi":"dựa vào"},{"hanzi":"依赖性","pinyin":"yīlàixìng","vi":"tính phụ thuộc"},{"hanzi":"独立","pinyin":"dúlì","vi":"độc lập"},{"hanzi":"依附","pinyin":"yīfù","vi":"bám dựa"}],"traditional":"依賴"},{"id":"音响","hanzi":"音响","pinyin":"yīnxiǎng","meaning_vi":"dàn âm thanh","explanation":"音 (âm – tiếng) + 响 (hưởng – vang) → thiết bị phát âm thanh như loa, dàn âm thanh; cũng chỉ hiệu ứng âm thanh. Ví dụ: 音响设备, 汽车音响.","hsk_level":6,"tags":["danh-tu","cong-nghe"],"image":"🔊","examples":[{"type":"basic","zh":"这套音响很贵。","pinyin":"Zhè tào yīnxiǎng hěn guì.","vi":"Bộ dàn âm thanh này rất đắt."},{"type":"simple","zh":"邻居把客厅里的音响开得特别大声。","pinyin":"Línjū bǎ kètīng li de yīnxiǎng kāi de tèbié dàshēng.","vi":"Hàng xóm bật dàn loa trong phòng khách cực to."},{"type":"compound","zh":"因为音响效果不好，所以后排观众听不清台词。","pinyin":"Yīnwèi yīnxiǎng xiàoguǒ bù hǎo, suǒyǐ hòupái guānzhòng tīng buqīng táicí.","vi":"Vì hiệu quả âm thanh không tốt nên khán giả hàng sau nghe không rõ lời thoại."}],"related":[{"hanzi":"音箱","pinyin":"yīnxiāng","vi":"loa"},{"hanzi":"音乐","pinyin":"yīnyuè","vi":"âm nhạc"},{"hanzi":"音响效果","pinyin":"yīnxiǎngxiàoguǒ","vi":"hiệu ứng âm thanh"},{"hanzi":"声音","pinyin":"shēngyīn","vi":"âm thanh"}],"traditional":"音響"},{"id":"英明","hanzi":"英明","pinyin":"yīngmíng","meaning_vi":"anh minh","explanation":"英 (anh – tài giỏi) + 明 (minh – sáng suốt) → sáng suốt, tài giỏi, quyết đoán đúng đắn. Thường dùng khen lãnh đạo: 英明的领导, 英明决策.","hsk_level":6,"tags":["tinh-tu"],"image":"👑","examples":[{"type":"basic","zh":"这是英明的决定。","pinyin":"Zhè shì yīngmíng de juédìng.","vi":"Đây là một quyết định sáng suốt."},{"type":"simple","zh":"在英明的领导下，这家小厂发展成了大企业。","pinyin":"Zài yīngmíng de lǐngdǎo xià, zhè jiā xiǎo chǎng fāzhǎn chéngle dà qǐyè.","vi":"Dưới sự lãnh đạo sáng suốt, xưởng nhỏ này đã phát triển thành doanh nghiệp lớn."},{"type":"compound","zh":"因为老板英明地提前转型，所以公司躲过了危机。","pinyin":"Yīnwèi lǎobǎn yīngmíng de tíqián zhuǎnxíng, suǒyǐ gōngsī duǒguò le wēijī.","vi":"Vì ông chủ sáng suốt chuyển đổi sớm nên công ty đã tránh được khủng hoảng."}],"related":[{"hanzi":"英明决策","pinyin":"yīngmíngjuécè","vi":"quyết sách sáng suốt"},{"hanzi":"明智","pinyin":"míngzhì","vi":"sáng suốt"},{"hanzi":"贤明","pinyin":"xiánmíng","vi":"hiền minh"},{"hanzi":"昏庸","pinyin":"hūnyōng","vi":"u mê hèn kém"}]},{"id":"拥护","hanzi":"拥护","pinyin":"yōnghù","meaning_vi":"ủng hộ","explanation":"拥 (ủng – ôm, ủng hộ) + 护 (hộ – che chở) → ủng hộ, bảo vệ một cách nhiệt tình. Thường đi với 拥护政策, 受到群众拥护.","hsk_level":6,"tags":["dong-tu"],"image":"👍","examples":[{"type":"basic","zh":"人民拥护这项政策。","pinyin":"Rénmín yōnghù zhè xiàng zhèngcè.","vi":"Nhân dân ủng hộ chính sách này."},{"type":"simple","zh":"新校长的改革方案得到了全体老师的拥护。","pinyin":"Xīn xiàozhǎng de gǎigé fāng'àn dédàole quántǐ lǎoshī de yōnghù.","vi":"Phương án cải cách của hiệu trưởng mới nhận được sự ủng hộ của toàn thể giáo viên."},{"type":"compound","zh":"只要政策真正为百姓着想，就一定会受到大家的拥护。","pinyin":"Zhǐyào zhèngcè zhēnzhèng wèi bǎixìng zhuóxiǎng, jiù yídìng huì shòudào dàjiā de yōnghù.","vi":"Chỉ cần chính sách thật sự nghĩ cho dân, nhất định sẽ được mọi người ủng hộ."}],"related":[{"hanzi":"支持","pinyin":"zhīchí","vi":"ủng hộ"},{"hanzi":"拥戴","pinyin":"yōngdài","vi":"tôn phò"},{"hanzi":"赞成","pinyin":"zànchéng","vi":"tán thành"},{"hanzi":"反对","pinyin":"fǎnduì","vi":"phản đối"}],"traditional":"擁護"},{"id":"优异","hanzi":"优异","pinyin":"yōuyì","meaning_vi":"ưu tú","explanation":"优 (ưu – tốt) + 异 (dị – khác thường) → xuất sắc, vượt trội hẳn. Thường đi với 成绩优异, 表现优异, 优异的成果.","hsk_level":6,"tags":["tinh-tu"],"image":"🏆","examples":[{"type":"basic","zh":"她成绩优异。","pinyin":"Tā chéngjì yōuyì.","vi":"Cô ấy có thành tích xuất sắc."},{"type":"simple","zh":"哥哥以优异的成绩考上了北京大学。","pinyin":"Gēge yǐ yōuyì de chéngjì kǎoshangle Běijīngdàxué.","vi":"Anh trai thi đỗ Đại học Bắc Kinh với thành tích xuất sắc."},{"type":"compound","zh":"他不但工作表现优异，而且很乐于帮助同事。","pinyin":"Tā búdàn gōngzuò biǎoxiàn yōuyì, érqiě hěn lèyú bāngzhù tóngshì.","vi":"Anh ấy không chỉ làm việc xuất sắc mà còn rất sẵn lòng giúp đỡ đồng nghiệp."}],"related":[{"hanzi":"优秀","pinyin":"yōuxiù","vi":"xuất sắc"},{"hanzi":"优良","pinyin":"yōuliáng","vi":"ưu tú"},{"hanzi":"杰出","pinyin":"jiéchū","vi":"kiệt xuất"},{"hanzi":"成绩优异","pinyin":"chéngjìyōuyì","vi":"thành tích xuất sắc"}],"traditional":"優異"},{"id":"掩盖","hanzi":"掩盖","pinyin":"yǎngài","meaning_vi":"che giấu","explanation":"掩 (yểm – che) + 盖 (cái – đậy) → che đậy, che giấu sự thật hoặc vật. Thường đi với 掩盖真相, 掩盖错误, 掩盖不了.","hsk_level":6,"tags":["dong-tu"],"image":"🙈","examples":[{"type":"basic","zh":"他想掩盖错误。","pinyin":"Tā xiǎng yǎngài cuòwù.","vi":"Anh ta muốn che giấu sai lầm."},{"type":"simple","zh":"厚厚的积雪掩盖了山间的小路。","pinyin":"Hòu hòu de jīxuě yǎngàile shān jiān de xiǎolù.","vi":"Lớp tuyết dày đã che lấp con đường nhỏ giữa núi."},{"type":"compound","zh":"即使你用谎言掩盖真相，事实也迟早会暴露。","pinyin":"Jíshǐ nǐ yòng huǎngyán yǎngài zhēnxiàng, shìshí yě chízǎo huì bàolù.","vi":"Dù bạn dùng lời nói dối để che giấu sự thật, sự thật sớm muộn cũng sẽ bị phơi bày."}],"related":[{"hanzi":"掩饰","pinyin":"yǎnshì","vi":"che đậy"},{"hanzi":"隐瞒","pinyin":"yǐnmán","vi":"giấu giếm"},{"hanzi":"遮盖","pinyin":"zhēgài","vi":"che phủ"},{"hanzi":"揭露","pinyin":"jiēlù","vi":"vạch trần"}],"traditional":"掩蓋"},{"id":"演化","hanzi":"演化","pinyin":"yǎnhuà","meaning_vi":"tiến hóa, biến đổi dần","explanation":"演 (diễn – diễn biến) + 化 (hóa – biến đổi) → biến đổi dần qua thời gian dài, tiến hóa. Thường dùng về tự nhiên, xã hội: 生物演化, 语言演化.","hsk_level":6,"tags":["dong-tu"],"image":"🧬","examples":[{"type":"basic","zh":"生物在不断演化。","pinyin":"Shēngwù zài búduàn yǎnhuà.","vi":"Sinh vật không ngừng tiến hóa."},{"type":"simple","zh":"科学家认为鸟类是从恐龙演化而来的。","pinyin":"Kēxuéjiā rènwéi niǎolèi shì cóng kǒnglóng yǎnhuà ér lái de.","vi":"Các nhà khoa học cho rằng loài chim tiến hóa từ khủng long."},{"type":"compound","zh":"随着时代变化，这个词的意思也慢慢演化了。","pinyin":"Suízhe shídài biànhuà, zhè ge cí de yìsi yě mànmàn yǎnhuà le.","vi":"Theo sự thay đổi của thời đại, nghĩa của từ này cũng dần dần biến đổi."}],"related":[{"hanzi":"演变","pinyin":"yǎnbiàn","vi":"diễn biến"},{"hanzi":"进化","pinyin":"jìnhuà","vi":"tiến hóa"},{"hanzi":"变化","pinyin":"biànhuà","vi":"biến đổi"},{"hanzi":"发展","pinyin":"fāzhǎn","vi":"phát triển"}]},{"id":"眼色","hanzi":"眼色","pinyin":"yǎnsè","meaning_vi":"ánh mắt ra hiệu; sắc mặt (người khác)","explanation":"眼 (nhãn – mắt) + 色 (sắc – sắc thái) → ánh mắt ra hiệu ngầm. Thường đi với 使眼色 (nháy mắt ra hiệu), 看眼色行事 (nhìn sắc mặt mà làm).","hsk_level":6,"tags":["danh-tu"],"image":"😉","examples":[{"type":"basic","zh":"他给我使了个眼色。","pinyin":"Tā gěi wǒ shǐle ge yǎnsè.","vi":"Anh ấy nháy mắt ra hiệu cho tôi."},{"type":"simple","zh":"新来的服务员很会看客人的眼色。","pinyin":"Xīn lái de fúwùyuán hěn huì kàn kèrén de yǎnsè.","vi":"Nhân viên phục vụ mới rất biết nhìn sắc mặt khách."},{"type":"compound","zh":"妈妈一递眼色，我就明白自己该闭嘴了。","pinyin":"Māma yí dìyǎnsè, wǒ jiù míngbai zìjǐ gāi bìzuǐ le.","vi":"Mẹ vừa đưa mắt ra hiệu, tôi liền hiểu là nên im lặng."}],"related":[{"hanzi":"使眼色","pinyin":"shǐyǎnsè","vi":"nháy mắt ra hiệu"},{"hanzi":"眼神","pinyin":"yǎnshén","vi":"ánh mắt"},{"hanzi":"脸色","pinyin":"liǎnsè","vi":"sắc mặt"},{"hanzi":"暗示","pinyin":"ànshì","vi":"ám chỉ"}]},{"id":"以便","hanzi":"以便","pinyin":"yǐbiàn","meaning_vi":"để tiện cho","explanation":"以 (dĩ – để) + 便 (tiện – thuận tiện) → để, nhằm tiện cho việc sau. Đứng đầu vế sau chỉ mục đích: 早点出发，以便准时到达.","hsk_level":6,"tags":["lien-tu"],"image":"👌","examples":[{"type":"basic","zh":"请留下电话，以便联系。","pinyin":"Qǐng liúxià diànhuà, yǐbiàn liánxì.","vi":"Vui lòng để lại số điện thoại để tiện liên lạc."},{"type":"simple","zh":"他把闹钟调早了半小时以便赶上早班车。","pinyin":"Tā bǎ nàozhōng tiáo zǎole bànxiǎoshí yǐbiàn gǎnshàng zǎo bānchē.","vi":"Anh ấy chỉnh đồng hồ báo thức sớm nửa tiếng để kịp chuyến xe sớm."},{"type":"compound","zh":"我们应该提前把资料发给大家，以便大家在会前做好准备。","pinyin":"Wǒmen yīnggāi tíqián bǎ zīliào fāgěi dàjiā, yǐbiàn dàjiā zài huì qián zuò hǎo zhǔnbèi.","vi":"Chúng ta nên gửi tài liệu cho mọi người trước để mọi người tiện chuẩn bị trước cuộc họp."}],"related":[{"hanzi":"为了","pinyin":"wèile","vi":"để"},{"hanzi":"以免","pinyin":"yǐmiǎn","vi":"để tránh"},{"hanzi":"便于","pinyin":"biànyú","vi":"tiện cho"},{"hanzi":"从而","pinyin":"cóng'ér","vi":"từ đó"}]},{"id":"以身作则","hanzi":"以身作则","pinyin":"yǐshēn-zuòzé","meaning_vi":"lấy bản thân làm gương","explanation":"以身作则: lấy (以) bản thân (身) làm (作) khuôn mẫu (则) → tự mình làm gương cho người khác noi theo. Thường dùng cho lãnh đạo, cha mẹ, thầy cô.","hsk_level":6,"tags":["thanh-ngu"],"image":"🌟","examples":[{"type":"basic","zh":"领导要以身作则。","pinyin":"Lǐngdǎo yào yǐshēnzuòzé.","vi":"Lãnh đạo phải lấy mình làm gương."},{"type":"simple","zh":"父母的以身作则对孩子影响很大。","pinyin":"Fùmǔ de yǐshēnzuòzé duì háizi yǐngxiǎng hěn dà.","vi":"Việc cha mẹ làm gương có ảnh hưởng rất lớn đến con cái."},{"type":"compound","zh":"如果老师不以身作则，就很难要求学生守纪律。","pinyin":"Rúguǒ lǎoshī bù yǐshēnzuòzé, jiù hěn nán yāoqiú xuésheng shǒu jìlǜ.","vi":"Nếu giáo viên không làm gương thì rất khó yêu cầu học sinh giữ kỷ luật."}],"related":[{"hanzi":"身体力行","pinyin":"shēntǐlìxíng","vi":"tự mình làm gương"},{"hanzi":"榜样","pinyin":"bǎngyàng","vi":"tấm gương"},{"hanzi":"带头","pinyin":"dàitóu","vi":"đi đầu"},{"hanzi":"言传身教","pinyin":"yánchuánshēnjiào","vi":"dạy bằng lời và gương"}],"traditional":"以身作則"},{"id":"以至","hanzi":"以至","pinyin":"yǐzhì","meaning_vi":"cho đến; đến mức, đến nỗi","explanation":"以 (dĩ) + 至 (chí – đến) → cho đến, đến nỗi; nối vế chỉ mức độ hoặc kết quả. Ví dụ: 他工作太专心，以至忘了吃饭; còn dạng 以至于.","hsk_level":6,"tags":["lien-tu"],"image":"➡️","examples":[{"type":"basic","zh":"他太累了，以至站着都能睡着。","pinyin":"Tā tài lèi le, yǐzhì zhànzhe dōu néng shuìzháo.","vi":"Anh ấy mệt đến mức đứng cũng có thể ngủ được."},{"type":"simple","zh":"从学生以至老人都爱看这部剧。","pinyin":"Cóng xuésheng yǐzhì lǎorén dōu ài kàn zhè bù jù.","vi":"Từ học sinh cho đến người già đều thích xem bộ phim này."},{"type":"compound","zh":"他专心看书，以至连有人敲门都没听见。","pinyin":"Tā zhuānxīn kànshū, yǐzhì lián yǒurén qiāomén dōu méi tīngjiàn.","vi":"Anh ấy chăm chú đọc sách đến mức có người gõ cửa cũng không nghe thấy."}],"related":[{"hanzi":"以至于","pinyin":"yǐzhìyú","vi":"đến nỗi"},{"hanzi":"甚至","pinyin":"shènzhì","vi":"thậm chí"},{"hanzi":"以致","pinyin":"yǐzhì","vi":"dẫn đến"},{"hanzi":"乃至","pinyin":"nǎizhì","vi":"cho đến"}]},{"id":"隐蔽","hanzi":"隐蔽","pinyin":"yǐnbì","meaning_vi":"ẩn nấp, che giấu; kín đáo, khuất","explanation":"隐 (ẩn – giấu) + 蔽 (tế – che lấp) → ẩn nấp, che khuất khỏi tầm nhìn; cũng làm tính từ \"kín đáo\". Ví dụ: 隐蔽在树林里, 隐蔽的地方.","hsk_level":6,"tags":["dong-tu"],"image":"🙈","examples":[{"type":"basic","zh":"士兵隐蔽在树林里。","pinyin":"Shìbīng yǐnbì zài shùlín li.","vi":"Binh lính ẩn nấp trong rừng."},{"type":"simple","zh":"小偷把赃物藏在一个很隐蔽的地方。","pinyin":"Xiǎotōu bǎ zāngwù cáng zài yí gè hěn yǐnbì de dìfang.","vi":"Tên trộm giấu tang vật ở một nơi rất kín đáo."},{"type":"compound","zh":"因为这家小店的位置很隐蔽，所以很少有游客找到。","pinyin":"Yīnwèi zhè jiā xiǎodiàn de wèizhì hěn yǐnbì, suǒyǐ hěn shǎoyǒu yóukè zhǎodào.","vi":"Vì vị trí cửa hàng nhỏ này rất khuất nên ít du khách tìm thấy."}],"related":[{"hanzi":"隐藏","pinyin":"yǐncáng","vi":"ẩn giấu"},{"hanzi":"躲藏","pinyin":"duǒcáng","vi":"trốn nấp"},{"hanzi":"掩护","pinyin":"yǎnhù","vi":"yểm hộ"},{"hanzi":"暴露","pinyin":"bàolù","vi":"lộ ra"}],"traditional":"隱蔽"},{"id":"引人注目","hanzi":"引人注目","pinyin":"yǐnrén-zhùmù","meaning_vi":"thu hút sự chú ý của mọi người","explanation":"引人注目: dẫn (引) người ta chú (注) mắt (目) vào → gây chú ý, thu hút ánh nhìn của mọi người. Ví dụ: 她的打扮十分引人注目.","hsk_level":6,"tags":["thanh-ngu"],"image":"👀","examples":[{"type":"basic","zh":"她的打扮引人注目。","pinyin":"Tā de dǎban yǐnrénzhùmù.","vi":"Cách ăn mặc của cô ấy thu hút sự chú ý."},{"type":"simple","zh":"这座红色的建筑在街上特别引人注目。","pinyin":"Zhè zuò hóngsè de jiànzhù zài jiēshang tèbié yǐnrénzhùmù.","vi":"Tòa nhà màu đỏ này đặc biệt nổi bật trên phố."},{"type":"compound","zh":"他虽然话不多，但是在比赛中的表现非常引人注目。","pinyin":"Tā suīrán huà bù duō, dànshì zài bǐsài zhōng de biǎoxiàn fēicháng yǐnrénzhùmù.","vi":"Anh ấy tuy ít nói nhưng màn thể hiện trong cuộc thi rất thu hút sự chú ý."}],"related":[{"hanzi":"显眼","pinyin":"xiǎnyǎn","vi":"bắt mắt"},{"hanzi":"瞩目","pinyin":"zhǔmù","vi":"được chú ý"},{"hanzi":"醒目","pinyin":"xǐngmù","vi":"nổi bật"},{"hanzi":"默默无闻","pinyin":"mòmòwúwén","vi":"lặng lẽ vô danh"}]},{"id":"饮水思源","hanzi":"饮水思源","pinyin":"yǐnshuǐ-sīyuán","meaning_vi":"uống nước nhớ nguồn","explanation":"饮水思源: uống nước (饮水) nghĩ đến nguồn (思源) → khi hưởng thành quả phải nhớ ơn người tạo ra nó; tương đương \"uống nước nhớ nguồn\".","hsk_level":6,"tags":["thanh-ngu","van-hoa"],"image":"💧","examples":[{"type":"basic","zh":"我们不能忘记饮水思源。","pinyin":"Wǒmen bù néng wàngjì yǐnshuǐsīyuán.","vi":"Chúng ta không được quên đạo lý uống nước nhớ nguồn."},{"type":"simple","zh":"他怀着饮水思源的心情回到了家乡。","pinyin":"Tā huáizhe yǐnshuǐsīyuán de xīnqíng huídàole jiāxiāng.","vi":"Anh ấy mang tấm lòng uống nước nhớ nguồn trở về quê hương."},{"type":"compound","zh":"因为懂得饮水思源，所以他成功后出钱为村里修了路。","pinyin":"Yīnwèi dǒngde yǐnshuǐsīyuán, suǒyǐ tā chénggōng hòu chūqián wèi cūnli xiūle lù.","vi":"Vì hiểu đạo lý uống nước nhớ nguồn nên sau khi thành công anh ấy bỏ tiền làm đường cho làng."}],"related":[{"hanzi":"知恩图报","pinyin":"zhī'ēntúbào","vi":"biết ơn báo đáp"},{"hanzi":"感恩","pinyin":"gǎn'ēn","vi":"biết ơn"},{"hanzi":"忘恩负义","pinyin":"wàng'ēnfùyì","vi":"vong ơn bội nghĩa"},{"hanzi":"吃水不忘挖井人","pinyin":"chīshuǐ bú wàng wā jǐng rén","vi":"uống nước nhớ người đào giếng"}],"traditional":"飲水思源"},{"id":"隐私","hanzi":"隐私","pinyin":"yǐnsī","meaning_vi":"chuyện riêng tư, đời tư","explanation":"隐 (ẩn – giấu kín) + 私 (tư – riêng) → chuyện riêng tư không muốn người khác biết, quyền riêng tư. Thường đi với 个人隐私, 侵犯隐私, 保护隐私.","hsk_level":6,"tags":["danh-tu"],"image":"🔒","examples":[{"type":"basic","zh":"请尊重别人的隐私。","pinyin":"Qǐng zūnzhòng biérén de yǐnsī.","vi":"Hãy tôn trọng quyền riêng tư của người khác."},{"type":"simple","zh":"这款软件偷偷收集用户的个人隐私。","pinyin":"Zhè kuǎn ruǎnjiàn tōutōu shōují yònghù de gèrén yǐnsī.","vi":"Phần mềm này lén thu thập thông tin riêng tư của người dùng."},{"type":"compound","zh":"即使是父母，也不应该随便翻看孩子的日记，侵犯他们的隐私。","pinyin":"Jíshǐ shì fùmǔ, yě bù yīnggāi suíbiàn fānkàn háizi de rìjì, qīnfàn tāmen de yǐnsī.","vi":"Dù là cha mẹ cũng không nên tùy tiện lật xem nhật ký của con, xâm phạm quyền riêng tư của chúng."}],"related":[{"hanzi":"秘密","pinyin":"mìmì","vi":"bí mật"},{"hanzi":"隐私权","pinyin":"yǐnsīquán","vi":"quyền riêng tư"},{"hanzi":"个人信息","pinyin":"gèrénxìnxī","vi":"thông tin cá nhân"},{"hanzi":"泄露","pinyin":"xièlòu","vi":"tiết lộ"}],"traditional":"隱私"},{"id":"涌现","hanzi":"涌现","pinyin":"yǒngxiàn","meaning_vi":"xuất hiện hàng loạt","explanation":"涌 (dũng – trào lên) + 现 (hiện – xuất hiện) → xuất hiện ồ ạt, liên tục như nước trào. Thường đi với 涌现出大批人才, 新事物不断涌现.","hsk_level":6,"tags":["dong-tu"],"image":"🌊","examples":[{"type":"basic","zh":"新人不断涌现。","pinyin":"Xīnrén búduàn yǒngxiàn.","vi":"Người mới không ngừng xuất hiện."},{"type":"simple","zh":"近年来，城市里涌现出大批网红咖啡店。","pinyin":"Jìnniánlái, chéngshì li yǒngxiàn chū dàpī wǎnghóng kāfēidiàn.","vi":"Những năm gần đây, trong thành phố xuất hiện hàng loạt quán cà phê nổi tiếng trên mạng."},{"type":"compound","zh":"地震一发生，各地就涌现出许多志愿者。","pinyin":"Dìzhèn yì fāshēng, gèdì jiù yǒngxiàn chū xǔduō zhìyuànzhě.","vi":"Động đất vừa xảy ra, khắp nơi liền xuất hiện rất nhiều tình nguyện viên."}],"related":[{"hanzi":"出现","pinyin":"chūxiàn","vi":"xuất hiện"},{"hanzi":"层出不穷","pinyin":"céngchūbùqióng","vi":"liên tục xuất hiện"},{"hanzi":"涌入","pinyin":"yǒngrù","vi":"ùa vào"},{"hanzi":"呈现","pinyin":"chéngxiàn","vi":"hiện ra"}],"traditional":"湧現"},{"id":"有条不紊","hanzi":"有条不紊","pinyin":"yǒutiáo-bùwěn","meaning_vi":"ngăn nắp có trật tự đâu ra đấy","explanation":"有条不紊: có thứ lớp (条) mà không (不) rối (紊) → làm việc ngăn nắp, có trình tự, đâu ra đấy. Ví dụ: 工作安排得有条不紊.","hsk_level":6,"tags":["thanh-ngu"],"image":"📋","examples":[{"type":"basic","zh":"她做事有条不紊。","pinyin":"Tā zuòshì yǒutiáobùwěn.","vi":"Cô ấy làm việc ngăn nắp, đâu ra đấy."},{"type":"simple","zh":"护士们有条不紊地给伤员包扎伤口。","pinyin":"Hùshimen yǒutiáobùwěn de gěi shāngyuán bāozā shāngkǒu.","vi":"Các y tá băng bó vết thương cho người bị thương một cách bài bản."},{"type":"compound","zh":"虽然来的客人很多，但是酒店的接待工作有条不紊。","pinyin":"Suīrán lái de kèrén hěn duō, dànshì jiǔdiàn de jiēdài gōngzuò yǒutiáobùwěn.","vi":"Tuy khách đến rất đông nhưng công tác đón tiếp của khách sạn vẫn đâu ra đấy."}],"related":[{"hanzi":"井井有条","pinyin":"jǐngjǐngyǒutiáo","vi":"ngăn nắp gọn gàng"},{"hanzi":"有条有理","pinyin":"yǒutiáoyǒulǐ","vi":"có trật tự"},{"hanzi":"条理","pinyin":"tiáolǐ","vi":"mạch lạc"},{"hanzi":"杂乱无章","pinyin":"záluànwúzhāng","vi":"lộn xộn bừa bãi"}],"traditional":"有條不紊"},{"id":"有效","hanzi":"有效","pinyin":"yǒuxiào","meaning_vi":"có hiệu quả; có hiệu lực","explanation":"有 (hữu – có) + 效 (hiệu – hiệu quả) → có hiệu quả, có tác dụng; cũng nghĩa là còn hiệu lực. Ví dụ: 有效方法, 有效期 (hạn sử dụng), 签证有效.","hsk_level":6,"tags":["tinh-tu"],"image":"✅","examples":[{"type":"basic","zh":"这个方法很有效。","pinyin":"Zhè ge fāngfǎ hěn yǒuxiào.","vi":"Phương pháp này rất hiệu quả."},{"type":"simple","zh":"这张优惠券在月底前一直有效。","pinyin":"Zhè zhāng yōuhuìquàn zài yuèdǐ qián yìzhí yǒuxiào.","vi":"Phiếu giảm giá này có hiệu lực đến cuối tháng."},{"type":"compound","zh":"这种药虽然很有效，但是副作用也不小。","pinyin":"Zhè zhǒng yào suīrán hěn yǒuxiào, dànshì fùzuòyòng yě bù xiǎo.","vi":"Loại thuốc này tuy rất hiệu quả nhưng tác dụng phụ cũng không nhỏ."}],"related":[{"hanzi":"有效期","pinyin":"yǒuxiàoqī","vi":"thời hạn hiệu lực"},{"hanzi":"无效","pinyin":"wúxiào","vi":"vô hiệu"},{"hanzi":"效果","pinyin":"xiàoguǒ","vi":"hiệu quả"},{"hanzi":"生效","pinyin":"shēngxiào","vi":"có hiệu lực"}]},{"id":"与日俱增","hanzi":"与日俱增","pinyin":"yǔrì-jùzēng","meaning_vi":"tăng lên từng ngày","explanation":"与日俱增: cùng (与) với ngày (日) mà tăng (增) lên → tăng lên không ngừng theo thời gian. Ví dụ: 感情与日俱增, 压力与日俱增.","hsk_level":6,"tags":["thanh-ngu"],"image":"📈","examples":[{"type":"basic","zh":"他的压力与日俱增。","pinyin":"Tā de yālì yǔrìjùzēng.","vi":"Áp lực của anh ấy tăng lên từng ngày."},{"type":"simple","zh":"来这座小城旅游的人数与日俱增。","pinyin":"Lái zhè zuò xiǎochéng lǚyóu de rénshù yǔrìjùzēng.","vi":"Số người đến thành phố nhỏ này du lịch tăng lên từng ngày."},{"type":"compound","zh":"随着交往的加深，两人的感情与日俱增。","pinyin":"Suízhe jiāowǎng de jiāshēn, liǎng rén de gǎnqíng yǔrìjùzēng.","vi":"Theo sự qua lại ngày càng sâu đậm, tình cảm hai người tăng lên từng ngày."}],"related":[{"hanzi":"日益","pinyin":"rìyì","vi":"ngày càng"},{"hanzi":"日渐","pinyin":"rìjiàn","vi":"dần dần từng ngày"},{"hanzi":"增长","pinyin":"zēngzhǎng","vi":"tăng trưởng"},{"hanzi":"日新月异","pinyin":"rìxīnyuèyì","vi":"thay đổi từng ngày"}],"traditional":"與日俱增"},{"id":"与众不同","hanzi":"与众不同","pinyin":"yǔzhòng-bùtóng","meaning_vi":"khác biệt với số đông, độc đáo","explanation":"与众不同: so với (与) mọi người (众) không giống (不同) → khác biệt, độc đáo, nổi bật hơn người. Ví dụ: 她的想法与众不同.","hsk_level":6,"tags":["thanh-ngu"],"image":"🌟","examples":[{"type":"basic","zh":"他的想法与众不同。","pinyin":"Tā de xiǎngfǎ yǔzhòngbùtóng.","vi":"Cách nghĩ của anh ấy khác người."},{"type":"simple","zh":"这家餐厅的装修风格与众不同。","pinyin":"Zhè jiā cāntīng de zhuāngxiū fēnggé yǔzhòngbùtóng.","vi":"Phong cách trang trí của nhà hàng này rất độc đáo."},{"type":"compound","zh":"她既不化妆，又不追时尚，显得与众不同。","pinyin":"Tā jì bú huàzhuāng, yòu bù zhuī shíshàng, xiǎnde yǔzhòngbùtóng.","vi":"Cô ấy vừa không trang điểm, vừa không chạy theo mốt, trông thật khác biệt."}],"related":[{"hanzi":"独特","pinyin":"dútè","vi":"độc đáo"},{"hanzi":"别具一格","pinyin":"biéjùyìgé","vi":"có phong cách riêng"},{"hanzi":"独一无二","pinyin":"dúyìwú'èr","vi":"độc nhất vô nhị"},{"hanzi":"普通","pinyin":"pǔtōng","vi":"bình thường"}],"traditional":"與眾不同"},{"id":"拽","hanzi":"拽","pinyin":"zhuài","meaning_vi":"kéo, lôi","explanation":"拽 (duệ): kéo, lôi mạnh. Khẩu ngữ, ví dụ 拽住他的手, 把门拽开; đọc zhuǎi trong khẩu ngữ còn nghĩa \"làm phách, ra vẻ\" (很拽).","hsk_level":6,"tags":["dong-tu"],"image":"🪢","examples":[{"type":"basic","zh":"别拽我的衣服！","pinyin":"Bié zhuài wǒ de yīfu!","vi":"Đừng kéo áo tôi!"},{"type":"simple","zh":"小狗拽着主人往公园跑。","pinyin":"Xiǎogǒu zhuàizhe zhǔrén wǎng gōngyuán pǎo.","vi":"Chú chó nhỏ lôi chủ chạy về phía công viên."},{"type":"compound","zh":"他刚想走，就被朋友一把拽住了胳膊。","pinyin":"Tā gāng xiǎng zǒu, jiù bèi péngyou yì bǎ zhuài zhùle gēbo.","vi":"Anh ấy vừa định đi thì bị bạn túm lấy cánh tay kéo lại."}],"related":[{"hanzi":"拉","pinyin":"lā","vi":"kéo"},{"hanzi":"拖","pinyin":"tuō","vi":"lôi"},{"hanzi":"扯","pinyin":"chě","vi":"giật"},{"hanzi":"推","pinyin":"tuī","vi":"đẩy"}]},{"id":"传记","hanzi":"传记","pinyin":"zhuànjì","meaning_vi":"tiểu sử","explanation":"传 (truyện – ghi chép đời người) + 记 (ký – ghi chép) → tác phẩm ghi lại cuộc đời một người, tiểu sử. Lưu ý 传 đọc zhuàn. Ví dụ: 人物传记, 名人传记.","hsk_level":6,"tags":["danh-tu","van-hoa"],"image":"📖","examples":[{"type":"basic","zh":"我在读他的传记。","pinyin":"Wǒ zài dú tā de zhuànjì.","vi":"Tôi đang đọc tiểu sử của ông ấy."},{"type":"simple","zh":"这本乔布斯传记在书店里卖得很好。","pinyin":"Zhè běn Qiáobùsī zhuànjì zài shūdiàn li mài de hěn hǎo.","vi":"Cuốn tiểu sử Steve Jobs này bán rất chạy ở hiệu sách."},{"type":"compound","zh":"如果你想了解这位科学家，就去读读他的传记吧。","pinyin":"Rúguǒ nǐ xiǎng liǎojiě zhè wèi kēxuéjiā, jiù qù dú du tā de zhuànjì ba.","vi":"Nếu bạn muốn tìm hiểu nhà khoa học này thì hãy đọc tiểu sử của ông ấy."}],"related":[{"hanzi":"自传","pinyin":"zìzhuàn","vi":"tự truyện"},{"hanzi":"人物传记","pinyin":"rénwùzhuànjì","vi":"tiểu sử nhân vật"},{"hanzi":"回忆录","pinyin":"huíyìlù","vi":"hồi ký"},{"hanzi":"传记文学","pinyin":"zhuànjìwénxué","vi":"văn học tiểu sử"}],"traditional":"傳記"},{"id":"壮观","hanzi":"壮观","pinyin":"zhuàngguān","meaning_vi":"hùng vĩ","explanation":"壮 (tráng – to lớn, mạnh mẽ) + 观 (quan – cảnh quan) → cảnh tượng hùng vĩ, tráng lệ. Ví dụ: 壮观的瀑布, 场面十分壮观.","hsk_level":6,"tags":["tinh-tu"],"image":"🏞️","examples":[{"type":"basic","zh":"瀑布非常壮观。","pinyin":"Pùbù fēicháng zhuàngguān.","vi":"Thác nước vô cùng hùng vĩ."},{"type":"simple","zh":"我们在山顶看到了壮观的日出。","pinyin":"Wǒmen zài shāndǐng kàndàole zhuàngguān de rìchū.","vi":"Chúng tôi ngắm cảnh mặt trời mọc hùng vĩ trên đỉnh núi."},{"type":"compound","zh":"钱塘江大潮不但十分壮观，而且非常危险。","pinyin":"Qiántángjiāng dàcháo búdàn shífēn zhuàngguān, érqiě fēicháng wēixiǎn.","vi":"Sóng triều lớn sông Tiền Đường không chỉ hùng vĩ mà còn rất nguy hiểm."}],"related":[{"hanzi":"壮丽","pinyin":"zhuànglì","vi":"hùng tráng"},{"hanzi":"宏伟","pinyin":"hóngwěi","vi":"hùng vĩ"},{"hanzi":"雄伟","pinyin":"xióngwěi","vi":"hùng vĩ"},{"hanzi":"景观","pinyin":"jǐngguān","vi":"cảnh quan"}],"traditional":"壯觀"},{"id":"着手","hanzi":"着手","pinyin":"zhuóshǒu","meaning_vi":"bắt tay làm","explanation":"着 (trước – đặt vào) + 手 (thủ – tay) → bắt tay vào làm, khởi sự. Thường đi với 着手准备, 着手调查, 从…着手.","hsk_level":6,"tags":["dong-tu"],"image":"🛠️","examples":[{"type":"basic","zh":"我们已着手准备。","pinyin":"Wǒmen yǐ zhuóshǒu zhǔnbèi.","vi":"Chúng tôi đã bắt tay chuẩn bị."},{"type":"simple","zh":"政府着手调查这起食品安全事故。","pinyin":"Zhèngfǔ zhuóshǒu diàochá zhè qǐ shípǐn ānquán shìgù.","vi":"Chính phủ bắt tay điều tra vụ sự cố an toàn thực phẩm này."},{"type":"compound","zh":"只要资金一到位，我们就立刻着手装修。","pinyin":"Zhǐyào zījīn yí dàowèi, wǒmen jiù lìkè zhuóshǒu zhuāngxiū.","vi":"Chỉ cần vốn sẵn sàng, chúng tôi sẽ lập tức bắt tay vào sửa sang."}],"related":[{"hanzi":"开始","pinyin":"kāishǐ","vi":"bắt đầu"},{"hanzi":"动手","pinyin":"dòngshǒu","vi":"bắt tay làm"},{"hanzi":"下手","pinyin":"xiàshǒu","vi":"ra tay"},{"hanzi":"入手","pinyin":"rùshǒu","vi":"bắt đầu từ"}],"traditional":"著手"},{"id":"着重","hanzi":"着重","pinyin":"zhuózhòng","meaning_vi":"nhấn mạnh","explanation":"着 (trước – đặt vào) + 重 (trọng – nặng, quan trọng) → đặt trọng tâm vào, nhấn mạnh. Ví dụ: 着重指出, 着重说明; gần nghĩa 注重, 强调.","hsk_level":6,"tags":["dong-tu"],"image":"❗","examples":[{"type":"basic","zh":"老师着重讲了语法。","pinyin":"Lǎoshī zhuózhòng jiǎngle yǔfǎ.","vi":"Thầy giáo giảng nhấn mạnh phần ngữ pháp."},{"type":"simple","zh":"这次会议着重讨论了环境保护问题。","pinyin":"Zhè cì huìyì zhuózhòng tǎolùnle huánjìngbǎohù wèntí.","vi":"Cuộc họp lần này tập trung thảo luận vấn đề bảo vệ môi trường."},{"type":"compound","zh":"面试时不但要着重介绍经验，而且要展示自己的优势。","pinyin":"Miànshì shí búdàn yào zhuózhòng jièshào jīngyàn, érqiě yào zhǎnshì zìjǐ de yōushì.","vi":"Khi phỏng vấn không chỉ phải nhấn mạnh kinh nghiệm mà còn phải thể hiện ưu thế của bản thân."}],"related":[{"hanzi":"重点","pinyin":"zhòngdiǎn","vi":"trọng điểm"},{"hanzi":"强调","pinyin":"qiángdiào","vi":"nhấn mạnh"},{"hanzi":"注重","pinyin":"zhùzhòng","vi":"chú trọng"},{"hanzi":"侧重","pinyin":"cèzhòng","vi":"thiên về"}],"traditional":"著重"},{"id":"专利","hanzi":"专利","pinyin":"zhuānlì","meaning_vi":"bằng sáng chế","explanation":"专 (chuyên – riêng) + 利 (lợi – quyền lợi) → quyền độc quyền về phát minh được pháp luật bảo hộ, bằng sáng chế. Ví dụ: 申请专利, 专利权.","hsk_level":6,"tags":["danh-tu","cong-viec"],"image":"💡","examples":[{"type":"basic","zh":"他申请了专利。","pinyin":"Tā shēnqǐngle zhuānlì.","vi":"Anh ấy đã đăng ký bằng sáng chế."},{"type":"simple","zh":"这家公司拥有两百多项技术专利。","pinyin":"Zhè jiā gōngsī yōngyǒu liǎng bǎi duōxiàng jìshù zhuānlì.","vi":"Công ty này sở hữu hơn hai trăm bằng sáng chế kỹ thuật."},{"type":"compound","zh":"因为这项发明已经有了专利，所以别人不能随便仿制。","pinyin":"Yīnwèi zhè xiàng fāmíng yǐjīng yǒule zhuānlì, suǒyǐ biérén bù néng suíbiàn fǎngzhì.","vi":"Vì phát minh này đã có bằng sáng chế nên người khác không được tùy tiện làm nhái."}],"related":[{"hanzi":"专利权","pinyin":"zhuānlìquán","vi":"quyền sáng chế"},{"hanzi":"发明","pinyin":"fāmíng","vi":"phát minh"},{"hanzi":"知识产权","pinyin":"zhīshichǎnquán","vi":"sở hữu trí tuệ"},{"hanzi":"申请专利","pinyin":"shēnqǐngzhuānlì","vi":"đăng ký sáng chế"}],"traditional":"專利"},{"id":"庄严","hanzi":"庄严","pinyin":"zhuāngyán","meaning_vi":"trang nghiêm","explanation":"庄 (trang – nghiêm trang) + 严 (nghiêm – nghiêm) → trang nghiêm, uy nghi, khiến người ta kính trọng. Ví dụ: 庄严的仪式, 庄严宣誓.","hsk_level":6,"tags":["tinh-tu"],"image":"🏛️","examples":[{"type":"basic","zh":"会场气氛很庄严。","pinyin":"Huìchǎng qìfēn hěn zhuāngyán.","vi":"Bầu không khí hội trường rất trang nghiêm."},{"type":"simple","zh":"升国旗时，同学们庄严地敬礼。","pinyin":"Shēng guóqí shí, tóngxuémen zhuāngyán de jìnglǐ.","vi":"Khi chào cờ, các bạn học sinh nghiêm trang giơ tay chào."},{"type":"compound","zh":"婚礼虽然办得很简单，但是仪式十分庄严。","pinyin":"Hūnlǐ suīrán bàn de hěn jiǎndān, dànshì yíshì shífēn zhuāngyán.","vi":"Đám cưới tuy giản dị nhưng nghi thức rất trang nghiêm."}],"related":[{"hanzi":"庄重","pinyin":"zhuāngzhòng","vi":"trang trọng"},{"hanzi":"严肃","pinyin":"yánsù","vi":"nghiêm túc"},{"hanzi":"隆重","pinyin":"lóngzhòng","vi":"long trọng"},{"hanzi":"森严","pinyin":"sēnyán","vi":"nghiêm ngặt"}],"traditional":"莊嚴"},{"id":"追究","hanzi":"追究","pinyin":"zhuījiū","meaning_vi":"truy cứu","explanation":"追 (truy – đuổi theo) + 究 (cứu – xét đến cùng) → truy cứu nguyên nhân hoặc trách nhiệm. Thường đi với 追究责任, 追究法律责任.","hsk_level":6,"tags":["dong-tu"],"image":"⚖️","examples":[{"type":"basic","zh":"我们会追究责任。","pinyin":"Wǒmen huì zhuījiū zérèn.","vi":"Chúng tôi sẽ truy cứu trách nhiệm."},{"type":"simple","zh":"警方正在追究这起车祸的原因。","pinyin":"Jǐngfāng zhèngzài zhuījiū zhè qǐ chēhuò de yuányīn.","vi":"Cảnh sát đang truy tìm nguyên nhân vụ tai nạn xe này."},{"type":"compound","zh":"既然他已经道歉了，我们就不再追究了。","pinyin":"Jìrán tā yǐjīng dàoqiàn le, wǒmen jiù bú zài zhuījiū le.","vi":"Anh ấy đã xin lỗi rồi thì chúng ta không truy cứu nữa."}],"related":[{"hanzi":"追究责任","pinyin":"zhuījiūzérèn","vi":"truy cứu trách nhiệm"},{"hanzi":"追查","pinyin":"zhuīchá","vi":"truy tra"},{"hanzi":"调查","pinyin":"diàochá","vi":"điều tra"},{"hanzi":"处分","pinyin":"chǔfèn","vi":"kỷ luật"}]},{"id":"转达","hanzi":"转达","pinyin":"zhuǎndá","meaning_vi":"chuyển đạt","explanation":"转 (chuyển – chuyển) + 达 (đạt – đến nơi) → chuyển lời, chuyển đạt ý kiến của người này tới người khác. Ví dụ: 请转达我的问候, 转达意见.","hsk_level":6,"tags":["dong-tu"],"image":"💬","examples":[{"type":"basic","zh":"请代我转达问候。","pinyin":"Qǐng dài wǒ zhuǎndá wènhòu.","vi":"Xin chuyển lời hỏi thăm giúp tôi."},{"type":"simple","zh":"秘书把经理的意见转达给了客户。","pinyin":"Mìshū bǎ jīnglǐ de yìjiàn zhuǎndá gěile kèhù.","vi":"Thư ký đã chuyển ý kiến của giám đốc tới khách hàng."},{"type":"compound","zh":"因为他不在家，所以我会把你的话转达给他。","pinyin":"Yīnwèi tā bú zài jiā, suǒyǐ wǒ huì bǎ nǐ dehuà zhuǎndá gěi tā.","vi":"Vì anh ấy không có nhà nên tôi sẽ chuyển lời của bạn cho anh ấy."}],"related":[{"hanzi":"转告","pinyin":"zhuǎngào","vi":"nhắn lại"},{"hanzi":"传达","pinyin":"chuándá","vi":"truyền đạt"},{"hanzi":"转交","pinyin":"zhuǎnjiāo","vi":"chuyển giao"},{"hanzi":"带话","pinyin":"dàihuà","vi":"nhắn lời"}],"traditional":"轉達"},{"id":"债券","hanzi":"债券","pinyin":"zhàiquàn","meaning_vi":"trái phiếu","explanation":"债 (trái – nợ) + 券 (khoán – giấy tờ có giá) → giấy nợ do nhà nước hay công ty phát hành để vay vốn, trái phiếu. Ví dụ: 发行债券, 国债.","hsk_level":6,"tags":["danh-tu","tien-te"],"image":"📜","examples":[{"type":"basic","zh":"他买了一些债券。","pinyin":"Tā mǎile yìxiē zhàiquàn.","vi":"Anh ấy đã mua một ít trái phiếu."},{"type":"simple","zh":"政府发行了一批十年期的债券。","pinyin":"Zhèngfǔ fāxíngle yìpī shí nián qī de zhàiquàn.","vi":"Chính phủ phát hành một đợt trái phiếu kỳ hạn mười năm."},{"type":"compound","zh":"与其把钱都投进股市，不如买点风险低的债券。","pinyin":"Yǔqí bǎ qián dōu tóu jìn gǔshì, bùrú mǎi diǎn fēngxiǎn dī de zhàiquàn.","vi":"Thay vì đổ hết tiền vào chứng khoán, chi bằng mua ít trái phiếu rủi ro thấp."}],"related":[{"hanzi":"股票","pinyin":"gǔpiào","vi":"cổ phiếu"},{"hanzi":"国债","pinyin":"guózhài","vi":"trái phiếu chính phủ"},{"hanzi":"投资","pinyin":"tóuzī","vi":"đầu tư"},{"hanzi":"债务","pinyin":"zhàiwù","vi":"nợ"}],"traditional":"債券"},{"id":"战术","hanzi":"战术","pinyin":"zhànshù","meaning_vi":"chiến thuật","explanation":"战 (chiến – đánh) + 术 (thuật – phương pháp) → phương pháp tác chiến cụ thể trong một trận; cũng dùng trong thể thao. So với 战略 (chiến lược) mang tầm tổng thể.","hsk_level":6,"tags":["danh-tu","the-thao"],"image":"🎯","examples":[{"type":"basic","zh":"教练调整了战术。","pinyin":"Jiàoliàn tiáozhěngle zhànshù.","vi":"Huấn luyện viên đã điều chỉnh chiến thuật."},{"type":"simple","zh":"主队用防守反击的战术赢下了比赛。","pinyin":"Zhǔduì yòng fángshǒu fǎnjī de zhànshù yíng xiàle bǐsài.","vi":"Đội chủ nhà dùng chiến thuật phòng ngự phản công để thắng trận."},{"type":"compound","zh":"如果上半场的战术不管用，下半场就得马上换。","pinyin":"Rúguǒ shàngbànchǎng de zhànshù bù guǎnyòng, xiàbànchǎng jiù děi mǎshàng huàn.","vi":"Nếu chiến thuật hiệp một không hiệu quả thì sang hiệp hai phải đổi ngay."}],"related":[{"hanzi":"战略","pinyin":"zhànlüè","vi":"chiến lược"},{"hanzi":"策略","pinyin":"cèlüè","vi":"sách lược"},{"hanzi":"战斗","pinyin":"zhàndòu","vi":"chiến đấu"},{"hanzi":"兵法","pinyin":"bīngfǎ","vi":"binh pháp"}],"traditional":"戰術"},{"id":"照应","hanzi":"照应","pinyin":"zhàoying","meaning_vi":"chăm sóc lẫn nhau","explanation":"照 (chiếu – trông nom) + 应 (ứng – đáp ứng) → đọc zhàoying: chăm sóc, trông nom nhau (互相照应); đọc zhàoyìng: phối hợp, hô ứng trước sau trong bài văn.","hsk_level":6,"tags":["dong-tu"],"image":"🤝","examples":[{"type":"basic","zh":"出门在外要互相照应。","pinyin":"Chūmén zài wài yào hùxiāng zhàoying.","vi":"Xa nhà thì phải chăm sóc lẫn nhau."},{"type":"simple","zh":"邻居阿姨经常照应我们这些租房的学生。","pinyin":"Línjū āyí jīngcháng zhàoying wǒmen zhèxiē zūfáng de xuésheng.","vi":"Cô hàng xóm thường trông nom đám sinh viên thuê trọ chúng tôi."},{"type":"compound","zh":"因为两家住得很近，所以平时能互相照应。","pinyin":"Yīnwèi liǎng jiā zhù de hěn jìn, suǒyǐ píngshí néng hùxiāng zhàoying.","vi":"Vì hai nhà ở rất gần nên ngày thường có thể chăm sóc lẫn nhau."}],"related":[{"hanzi":"照顾","pinyin":"zhàogù","vi":"chăm sóc"},{"hanzi":"照料","pinyin":"zhàoliào","vi":"trông nom"},{"hanzi":"互相照应","pinyin":"hùxiāngzhàoying","vi":"chăm sóc lẫn nhau"},{"hanzi":"关照","pinyin":"guānzhào","vi":"quan tâm giúp đỡ"}],"traditional":"照應"},{"id":"阵地","hanzi":"阵地","pinyin":"zhèndì","meaning_vi":"trận địa","explanation":"阵 (trận – thế trận) + 地 (địa – đất) → vị trí đóng quân bố trí để chiến đấu; nghĩa bóng là lĩnh vực hoạt động. Ví dụ: 守住阵地, 宣传阵地.","hsk_level":6,"tags":["danh-tu"],"image":"🚩","examples":[{"type":"basic","zh":"士兵守住了阵地。","pinyin":"Shìbīng shǒuzhùle zhèndì.","vi":"Binh lính đã giữ vững trận địa."},{"type":"simple","zh":"敌人的炮火猛烈地轰击着我们的阵地。","pinyin":"Dírén de pàohuǒ měngliè de hōngjīzhe wǒmen de zhèndì.","vi":"Pháo của địch dội dữ dội vào trận địa của ta."},{"type":"compound","zh":"即使只剩下三个人，他们也没有放弃阵地。","pinyin":"Jíshǐ zhǐ shèngxià sān gè rén, tāmen yě méiyǒu fàngqì zhèndì.","vi":"Dù chỉ còn ba người, họ vẫn không từ bỏ trận địa."}],"related":[{"hanzi":"战场","pinyin":"zhànchǎng","vi":"chiến trường"},{"hanzi":"前线","pinyin":"qiánxiàn","vi":"tiền tuyến"},{"hanzi":"阵营","pinyin":"zhènyíng","vi":"phe phái"},{"hanzi":"坚守阵地","pinyin":"jiānshǒuzhèndì","vi":"giữ vững trận địa"}],"traditional":"陣地"},{"id":"震撼","hanzi":"震撼","pinyin":"zhènhàn","meaning_vi":"làm chấn động, làm rung động (lòng người)","explanation":"震 (chấn – rung động) + 撼 (hám – lay động) → làm rung chuyển mạnh, gây chấn động lòng người. Ví dụ: 震撼人心, 令人震撼的场面.","hsk_level":6,"tags":["dong-tu"],"image":"😲","examples":[{"type":"basic","zh":"这部电影很震撼。","pinyin":"Zhè bù diànyǐng hěn zhènhàn.","vi":"Bộ phim này thật sự gây chấn động lòng người."},{"type":"simple","zh":"那张战争照片深深地震撼了每个观众。","pinyin":"Nà zhāng zhànzhēng zhàopiàn shēnshēn de zhènhànle měi gè guānzhòng.","vi":"Bức ảnh chiến tranh đó đã làm rung động sâu sắc mọi khán giả."},{"type":"compound","zh":"我一站到长城上，就被眼前的景色震撼了。","pinyin":"Wǒ yí zhàn dào Chángchéng shang, jiù bèi yǎnqián de jǐngsè zhènhàn le.","vi":"Vừa đứng trên Vạn Lý Trường Thành, tôi liền choáng ngợp trước cảnh sắc trước mắt."}],"related":[{"hanzi":"震惊","pinyin":"zhènjīng","vi":"kinh ngạc"},{"hanzi":"震动","pinyin":"zhèndòng","vi":"chấn động"},{"hanzi":"感动","pinyin":"gǎndòng","vi":"cảm động"},{"hanzi":"震撼人心","pinyin":"zhènhànrénxīn","vi":"rung động lòng người"}]},{"id":"镇静","hanzi":"镇静","pinyin":"zhènjìng","meaning_vi":"trấn tĩnh","explanation":"镇 (trấn – đè giữ, làm yên) + 静 (tĩnh – yên) → bình tĩnh, điềm tĩnh trước tình huống bất ngờ. Ví dụ: 保持镇静, 镇静剂 (thuốc an thần).","hsk_level":6,"tags":["tinh-tu"],"image":"😌","examples":[{"type":"basic","zh":"请大家保持镇静。","pinyin":"Qǐng dàjiā bǎochí zhènjìng.","vi":"Mọi người hãy giữ bình tĩnh."},{"type":"simple","zh":"面对持刀的歹徒，她表现得非常镇静。","pinyin":"Miànduì chídāo de dǎitú, tā biǎoxiàn de fēicháng zhènjìng.","vi":"Đối mặt với tên côn đồ cầm dao, cô ấy tỏ ra vô cùng bình tĩnh."},{"type":"compound","zh":"虽然心里很紧张，但是他在台上显得很镇静。","pinyin":"Suīrán xīnli hěn jǐnzhāng, dànshì tā zài tái shang xiǎnde hěn zhènjìng.","vi":"Tuy trong lòng rất căng thẳng nhưng trên sân khấu anh ấy trông rất bình tĩnh."}],"related":[{"hanzi":"镇定","pinyin":"zhèndìng","vi":"bình tĩnh"},{"hanzi":"冷静","pinyin":"lěngjìng","vi":"điềm tĩnh"},{"hanzi":"沉着","pinyin":"chénzhuó","vi":"trầm tĩnh"},{"hanzi":"慌张","pinyin":"huāngzhāng","vi":"hoảng hốt"}],"traditional":"鎮靜"},{"id":"正负","hanzi":"正负","pinyin":"zhèngfù","meaning_vi":"dương và âm, cộng và trừ (dấu +/−)","explanation":"正 (chính – dương) + 负 (phụ – âm) → dương và âm, cộng và trừ trong toán học, điện học. Ví dụ: 正负号 (dấu +/−), 正负极; nghĩa rộng là mặt tốt và mặt xấu.","hsk_level":6,"tags":["danh-tu","khoa-hoc"],"image":"➕","examples":[{"type":"basic","zh":"注意数字的正负。","pinyin":"Zhùyì shùzì de zhèngfù.","vi":"Chú ý dấu dương âm của các số."},{"type":"simple","zh":"这台秤的误差在正负一克之内。","pinyin":"Zhè táichèng de wùchā zài zhèngfù yí kè zhīnèi.","vi":"Sai số của chiếc cân này nằm trong phạm vi cộng trừ một gam."},{"type":"compound","zh":"如果算错了正负号，整道题的答案就全错了。","pinyin":"Rúguǒ suàn cuòle zhèngfùhào, zhěng dào tí de dá'àn jiù quán cuò le.","vi":"Nếu tính sai dấu cộng trừ thì đáp án cả bài sẽ sai hết."}],"related":[{"hanzi":"正数","pinyin":"zhèngshù","vi":"số dương"},{"hanzi":"负数","pinyin":"fùshù","vi":"số âm"},{"hanzi":"加减","pinyin":"jiājiǎn","vi":"cộng trừ"},{"hanzi":"正负极","pinyin":"zhèngfùjí","vi":"cực dương âm"}],"traditional":"正負"},{"id":"政权","hanzi":"政权","pinyin":"zhèngquán","meaning_vi":"chính quyền","explanation":"政 (chính – chính trị) + 权 (quyền – quyền lực) → quyền lực chính trị, bộ máy nắm quyền cai trị đất nước. Ví dụ: 国家政权, 夺取政权.","hsk_level":6,"tags":["danh-tu","xa-hoi"],"image":"🏛️","examples":[{"type":"basic","zh":"新政权成立了。","pinyin":"Xīn zhèngquán chénglì le.","vi":"Chính quyền mới đã được thành lập."},{"type":"simple","zh":"这场战争导致了旧政权的垮台。","pinyin":"Zhè chǎng zhànzhēng dǎozhìle jiù zhèngquán de kuǎtái.","vi":"Cuộc chiến này dẫn đến sự sụp đổ của chính quyền cũ."},{"type":"compound","zh":"一个政权如果失去民心，就很难长久维持下去。","pinyin":"Yí gè zhèngquán rúguǒ shīqù mínxīn, jiù hěn nán chángjiǔ wéichí xiàqu.","vi":"Một chính quyền nếu mất lòng dân thì khó duy trì lâu dài."}],"related":[{"hanzi":"政府","pinyin":"zhèngfǔ","vi":"chính phủ"},{"hanzi":"权力","pinyin":"quánlì","vi":"quyền lực"},{"hanzi":"国家","pinyin":"guójiā","vi":"quốc gia"},{"hanzi":"政治","pinyin":"zhèngzhì","vi":"chính trị"}],"traditional":"政權"},{"id":"证书","hanzi":"证书","pinyin":"zhèngshū","meaning_vi":"giấy chứng nhận","explanation":"证 (chứng – chứng nhận) + 书 (thư – giấy tờ) → giấy chứng nhận, văn bằng do cơ quan cấp. Ví dụ: 毕业证书, 结婚证书, 获得证书.","hsk_level":6,"tags":["danh-tu","hoc-tap"],"image":"📜","examples":[{"type":"basic","zh":"他拿到了证书。","pinyin":"Tā nádàole zhèngshū.","vi":"Anh ấy đã nhận được giấy chứng nhận."},{"type":"simple","zh":"她花了半年时间考取了教师资格证书。","pinyin":"Tā huāle bàn nián shíjiān kǎoqǔle jiàoshī zīgé zhèngshū.","vi":"Cô ấy mất nửa năm để thi lấy chứng chỉ hành nghề giáo viên."},{"type":"compound","zh":"只要通过最后的考核，你就能领到结业证书。","pinyin":"Zhǐyào tōngguò zuìhòu de kǎohé, nǐ jiù néng lǐngdào jiéyè zhèngshū.","vi":"Chỉ cần vượt qua đợt kiểm tra cuối, bạn sẽ được nhận giấy chứng nhận hoàn thành khóa học."}],"related":[{"hanzi":"证件","pinyin":"zhèngjiàn","vi":"giấy tờ"},{"hanzi":"毕业证书","pinyin":"bìyèzhèngshū","vi":"bằng tốt nghiệp"},{"hanzi":"证明","pinyin":"zhèngmíng","vi":"giấy chứng nhận"},{"hanzi":"资格证","pinyin":"zīgézhèng","vi":"chứng chỉ"}],"traditional":"證書"},{"id":"正义","hanzi":"正义","pinyin":"zhèngyì","meaning_vi":"chính nghĩa","explanation":"正 (chính – ngay thẳng) + 义 (nghĩa – lẽ phải) → lẽ phải, công lý; làm tính từ là chính nghĩa. Ví dụ: 主持正义, 正义的事业, 正义感.","hsk_level":6,"tags":["danh-tu"],"image":"⚖️","examples":[{"type":"basic","zh":"正义终将胜利。","pinyin":"Zhèngyì zhōng jiāng shènglì.","vi":"Chính nghĩa cuối cùng sẽ chiến thắng."},{"type":"simple","zh":"这位律师一直在为穷人伸张正义。","pinyin":"Zhè wèi lǜshī yìzhí zài wèi qióngrén shēnzhāng zhèngyì.","vi":"Vị luật sư này luôn đòi lại công bằng cho người nghèo."},{"type":"compound","zh":"即使面对威胁，他也坚定地站在正义的一边。","pinyin":"Jíshǐ miànduì wēixié, tā yě jiāndìng de zhàn zài zhèngyì de yìbiān.","vi":"Dù đối mặt với đe dọa, anh ấy vẫn kiên định đứng về phía chính nghĩa."}],"related":[{"hanzi":"公正","pinyin":"gōngzhèng","vi":"công bằng"},{"hanzi":"正义感","pinyin":"zhèngyìgǎn","vi":"tinh thần chính nghĩa"},{"hanzi":"邪恶","pinyin":"xié'è","vi":"tà ác"},{"hanzi":"公平","pinyin":"gōngpíng","vi":"công bằng"}],"traditional":"正義"},{"id":"折","hanzi":"折","pinyin":"zhé","meaning_vi":"bẻ gãy, gãy; gấp (giấy); chiết khấu, giảm giá","explanation":"折 (chiết): bẻ gãy, gấp lại, giảm giá, quy đổi. Ví dụ: 折纸 (gấp giấy), 打八折 (giảm 20%), 骨折 (gãy xương), 折合 (quy đổi).","hsk_level":6,"tags":["dong-tu"],"image":"📄","examples":[{"type":"basic","zh":"这件衣服打八折。","pinyin":"Zhè jiàn yīfu dǎ bā zhé.","vi":"Chiếc áo này được giảm giá còn 80%."},{"type":"simple","zh":"妹妹用彩纸折了一只漂亮的小鸟。","pinyin":"Mèimei yòng cǎi zhǐ zhéle yì zhī piàoliang de xiǎoniǎo.","vi":"Em gái dùng giấy màu gấp một chú chim nhỏ xinh xắn."},{"type":"compound","zh":"因为风太大，所以院子里的小树被折断了。","pinyin":"Yīnwèi fēng tài dà, suǒyǐ yuànzi li de xiǎoshù bèi zhéduàn le.","vi":"Vì gió quá lớn nên cái cây nhỏ trong sân bị gãy."}],"related":[{"hanzi":"打折","pinyin":"dǎzhé","vi":"giảm giá"},{"hanzi":"折叠","pinyin":"zhédié","vi":"gấp lại"},{"hanzi":"折扣","pinyin":"zhékòu","vi":"chiết khấu"},{"hanzi":"折断","pinyin":"zhéduàn","vi":"bẻ gãy"}]},{"id":"制服","hanzi":"制服","pinyin":"zhìfú","meaning_vi":"đồng phục","explanation":"制 (chế – quy định) + 服 (phục – quần áo) → quần áo theo mẫu quy định, đồng phục. Ví dụ: 学生制服, 警察制服; làm động từ còn nghĩa khuất phục (制服敌人).","hsk_level":6,"tags":["danh-tu","trang-phuc"],"image":"👮","examples":[{"type":"basic","zh":"他穿着警察制服。","pinyin":"Tā chuānzhe jǐngchá zhìfú.","vi":"Anh ấy mặc đồng phục cảnh sát."},{"type":"simple","zh":"这家航空公司换上了新设计的制服。","pinyin":"Zhè jiā hángkōng gōngsī huàn shangle xīn shèjì de zhìfú.","vi":"Hãng hàng không này đã thay đồng phục thiết kế mới."},{"type":"compound","zh":"学校规定学生周一必须穿制服，否则不能进校门。","pinyin":"Xuéxiào guīdìng xuésheng Zhōuyí bìxū chuān zhìfú, fǒuzé bù néng jìn xiàomén.","vi":"Nhà trường quy định thứ Hai học sinh phải mặc đồng phục, nếu không sẽ không được vào cổng."}],"related":[{"hanzi":"校服","pinyin":"xiàofú","vi":"đồng phục học sinh"},{"hanzi":"工作服","pinyin":"gōngzuòfú","vi":"quần áo bảo hộ"},{"hanzi":"军装","pinyin":"jūnzhuāng","vi":"quân phục"},{"hanzi":"便服","pinyin":"biànfú","vi":"thường phục"}]},{"id":"志同道合","hanzi":"志同道合","pinyin":"zhìtóng-dàohé","meaning_vi":"chí đồng đạo hợp, cùng chí hướng lý tưởng","explanation":"志同道合: chí (志) hướng giống nhau (同), con đường (道) hợp nhau (合) → cùng chí hướng, lý tưởng. Thường nói: 志同道合的朋友.","hsk_level":6,"tags":["thanh-ngu"],"image":"🤝","examples":[{"type":"basic","zh":"我们志同道合。","pinyin":"Wǒmen zhìtóngdàohé.","vi":"Chúng tôi cùng chí hướng."},{"type":"simple","zh":"他在大学里结识了几个志同道合的朋友。","pinyin":"Tā zài dàxué li jiéshíle jǐ gè zhìtóngdàohé de péngyou.","vi":"Ở đại học anh ấy quen được vài người bạn cùng chí hướng."},{"type":"compound","zh":"因为两人志同道合，所以毕业后一起创办了公司。","pinyin":"Yīnwèi liǎng rén zhìtóngdàohé, suǒyǐ bìyè hòu yìqǐ chuàngbànle gōngsī.","vi":"Vì hai người cùng chí hướng nên sau khi tốt nghiệp đã cùng nhau thành lập công ty."}],"related":[{"hanzi":"情投意合","pinyin":"qíngtóuyìhé","vi":"tâm đầu ý hợp"},{"hanzi":"同心同德","pinyin":"tóngxīntóngdé","vi":"đồng lòng đồng đức"},{"hanzi":"志向","pinyin":"zhìxiàng","vi":"chí hướng"},{"hanzi":"道不同不相为谋","pinyin":"dào bùtóng bù xiāng wéi móu","vi":"khác đường không cùng mưu"}]},{"id":"治安","hanzi":"治安","pinyin":"zhì'ān","meaning_vi":"trị an","explanation":"治 (trị – quản lý) + 安 (an – yên ổn) → trật tự an ninh xã hội. Ví dụ: 社会治安, 治安良好, 维护治安.","hsk_level":6,"tags":["danh-tu","xa-hoi"],"image":"🚔","examples":[{"type":"basic","zh":"这里治安很好。","pinyin":"Zhèlǐ zhì'ān hěn hǎo.","vi":"Trị an ở đây rất tốt."},{"type":"simple","zh":"警察每天晚上在小区巡逻维护治安。","pinyin":"Jǐngchá měitiān wǎnshang zài xiǎoqū xúnluó wéihù zhì'ān.","vi":"Cảnh sát tuần tra khu dân cư mỗi tối để giữ gìn trị an."},{"type":"compound","zh":"自从装了监控以后，这条街的治安就好多了。","pinyin":"Zìcóng zhuāngle jiānkòng yǐhòu, zhè tiáo jiē de zhì'ān jiù hǎoduō le.","vi":"Từ khi lắp camera giám sát, trị an của con phố này đã tốt hơn nhiều."}],"related":[{"hanzi":"安全","pinyin":"ānquán","vi":"an toàn"},{"hanzi":"社会治安","pinyin":"shèhuìzhì'ān","vi":"trật tự xã hội"},{"hanzi":"警察","pinyin":"jǐngchá","vi":"cảnh sát"},{"hanzi":"秩序","pinyin":"zhìxù","vi":"trật tự"}]},{"id":"值班","hanzi":"值班","pinyin":"zhíbān","meaning_vi":"trực ban","explanation":"值 (trị – đến phiên) + 班 (ban – ca, phiên) → trực, làm phiên trực theo ca. Ví dụ: 今晚我值班, 值班医生, 值班室.","hsk_level":6,"tags":["dong-tu"],"image":"🏥","examples":[{"type":"basic","zh":"今晚我值班。","pinyin":"Jīnwǎn wǒ zhíbān.","vi":"Tối nay tôi trực."},{"type":"simple","zh":"春节期间，医院安排了二十名医生值班。","pinyin":"Chūnjié qījiān, yīyuàn ānpáile èrshí míng yīshēng zhíbān.","vi":"Dịp Tết, bệnh viện bố trí hai mươi bác sĩ trực."},{"type":"compound","zh":"如果夜里有急事，就给值班的保安打电话。","pinyin":"Rúguǒ yèli yǒu jíshì, jiù gěi zhíbān de bǎo'ān dǎdiànhuà.","vi":"Nếu ban đêm có việc gấp thì gọi điện cho bảo vệ trực ca."}],"related":[{"hanzi":"值日","pinyin":"zhírì","vi":"trực nhật"},{"hanzi":"上班","pinyin":"shàngbān","vi":"đi làm"},{"hanzi":"夜班","pinyin":"yèbān","vi":"ca đêm"},{"hanzi":"轮班","pinyin":"lúnbān","vi":"luân ca"}]},{"id":"职务","hanzi":"职务","pinyin":"zhíwù","meaning_vi":"chức vụ","explanation":"职 (chức – chức trách) + 务 (vụ – công việc) → chức vụ, vị trí công tác cùng nhiệm vụ của nó. Ví dụ: 担任职务, 撤销职务.","hsk_level":6,"tags":["danh-tu","cong-viec"],"image":"💼","examples":[{"type":"basic","zh":"他被撤销了职务。","pinyin":"Tā bèi chèxiāole zhíwù.","vi":"Anh ta bị cách chức."},{"type":"simple","zh":"她在公司担任财务总监的职务。","pinyin":"Tā zài gōngsī dānrèn cáiwù zǒngjiān de zhíwù.","vi":"Cô ấy giữ chức vụ giám đốc tài chính trong công ty."},{"type":"compound","zh":"虽然职务提高了，但是他对人依旧很谦虚。","pinyin":"Suīrán zhíwù tígāo le, dànshì tā duì rén yījiù hěn qiānxū.","vi":"Tuy chức vụ được nâng lên nhưng anh ấy vẫn khiêm tốn với mọi người."}],"related":[{"hanzi":"职位","pinyin":"zhíwèi","vi":"chức vị"},{"hanzi":"职责","pinyin":"zhízé","vi":"chức trách"},{"hanzi":"岗位","pinyin":"gǎngwèi","vi":"cương vị"},{"hanzi":"职称","pinyin":"zhíchēng","vi":"chức danh"}],"traditional":"職務"},{"id":"执行","hanzi":"执行","pinyin":"zhíxíng","meaning_vi":"thực thi","explanation":"执 (chấp – nắm giữ, thi hành) + 行 (hành – làm) → thi hành, thực hiện kế hoạch, mệnh lệnh. Ví dụ: 执行任务, 执行命令, 执行力.","hsk_level":6,"tags":["dong-tu"],"image":"✅","examples":[{"type":"basic","zh":"命令必须执行。","pinyin":"Mìnglìng bìxū zhíxíng.","vi":"Mệnh lệnh phải được thi hành."},{"type":"simple","zh":"新的交通规定从下个月开始执行。","pinyin":"Xīn de jiāotōng guīdìng cóng xiàgèyuè kāishǐ zhíxíng.","vi":"Quy định giao thông mới bắt đầu được thực thi từ tháng sau."},{"type":"compound","zh":"计划再好，如果不认真执行，也只是一张废纸。","pinyin":"Jìhuà zài hǎo, rúguǒ bú rènzhēn zhíxíng, yě zhǐshì yì zhāng fèizhǐ.","vi":"Kế hoạch dù tốt đến đâu, nếu không thực hiện nghiêm túc thì cũng chỉ là tờ giấy lộn."}],"related":[{"hanzi":"实行","pinyin":"shíxíng","vi":"thực hành"},{"hanzi":"实施","pinyin":"shíshī","vi":"thực thi"},{"hanzi":"执行力","pinyin":"zhíxínglì","vi":"năng lực thực thi"},{"hanzi":"履行","pinyin":"lǚxíng","vi":"thực hiện"}],"traditional":"執行"},{"id":"重心","hanzi":"重心","pinyin":"zhòngxīn","meaning_vi":"trọng tâm","explanation":"重 (trọng – nặng) + 心 (tâm – tâm điểm) → trọng tâm vật lý; nghĩa bóng là phần quan trọng nhất của công việc. Ví dụ: 工作重心, 失去重心.","hsk_level":6,"tags":["danh-tu"],"image":"🎯","examples":[{"type":"basic","zh":"跳舞时要稳住重心。","pinyin":"Tiàowǔ shí yào wěn zhù zhòngxīn.","vi":"Khi nhảy phải giữ vững trọng tâm."},{"type":"simple","zh":"公司把今年的工作重心放在了海外市场。","pinyin":"Gōngsī bǎ jīnnián de gōngzuò zhòngxīn fàng zài le hǎiwài shìchǎng.","vi":"Công ty đặt trọng tâm công việc năm nay vào thị trường nước ngoài."},{"type":"compound","zh":"因为车上的货物太重，所以卡车的重心不稳。","pinyin":"Yīnwèi chē shang de huòwù tài zhòng, suǒyǐ kǎchē de zhòngxīn bùwěn.","vi":"Vì hàng trên xe quá nặng nên trọng tâm xe tải không vững."}],"related":[{"hanzi":"中心","pinyin":"zhōngxīn","vi":"trung tâm"},{"hanzi":"重点","pinyin":"zhòngdiǎn","vi":"trọng điểm"},{"hanzi":"核心","pinyin":"héxīn","vi":"hạt nhân"},{"hanzi":"平衡","pinyin":"pínghéng","vi":"cân bằng"}]},{"id":"皱纹","hanzi":"皱纹","pinyin":"zhòuwén","meaning_vi":"nếp nhăn","explanation":"皱 (trứu – nhăn) + 纹 (văn – vân, đường nét) → nếp nhăn trên da hoặc vải. Ví dụ: 脸上有皱纹, 长皱纹.","hsk_level":6,"tags":["danh-tu","co-the"],"image":"👵","examples":[{"type":"basic","zh":"爷爷满脸皱纹。","pinyin":"Yéye mǎnliǎn zhòuwén.","vi":"Ông nội mặt đầy nếp nhăn."},{"type":"simple","zh":"这几年妈妈的眼角多了不少皱纹。","pinyin":"Zhè jǐ nián māma de yǎnjiǎo duōle bùshǎo zhòuwén.","vi":"Mấy năm nay khóe mắt mẹ có thêm nhiều nếp nhăn."},{"type":"compound","zh":"她虽然脸上有了皱纹，但是笑起来还是那么美。","pinyin":"Tā suīrán liǎn shang yǒule zhòuwén, dànshì xiào qǐlái háishi nàme měi.","vi":"Bà ấy tuy trên mặt đã có nếp nhăn nhưng khi cười vẫn đẹp như vậy."}],"related":[{"hanzi":"皱眉","pinyin":"zhòuméi","vi":"nhíu mày"},{"hanzi":"衰老","pinyin":"shuāilǎo","vi":"già yếu"},{"hanzi":"皮肤","pinyin":"pífū","vi":"làn da"},{"hanzi":"皱","pinyin":"zhòu","vi":"nhăn"}],"traditional":"皺紋"},{"id":"助手","hanzi":"助手","pinyin":"zhùshǒu","meaning_vi":"trợ lý","explanation":"助 (trợ – giúp) + 手 (thủ – tay, người làm) → người giúp việc, trợ lý. Ví dụ: 得力助手 (trợ thủ đắc lực), 当助手.","hsk_level":6,"tags":["danh-tu","cong-viec"],"image":"🧑‍💼","examples":[{"type":"basic","zh":"他是我的助手。","pinyin":"Tā shì wǒ de zhùshǒu.","vi":"Anh ấy là trợ lý của tôi."},{"type":"simple","zh":"王教授的助手负责整理实验数据。","pinyin":"Wáng jiàoshòu de zhùshǒu fùzé zhěnglǐ shíyànshùjù.","vi":"Trợ lý của giáo sư Vương phụ trách sắp xếp dữ liệu thí nghiệm."},{"type":"compound","zh":"有了智能语音助手以后，我做饭时就能随时查菜谱了。","pinyin":"Yǒule zhìnéng yǔyīn zhùshǒu yǐhòu, wǒ zuòfàn shí jiù néng suíshí chá càipǔ le.","vi":"Từ khi có trợ lý giọng nói thông minh, lúc nấu ăn tôi có thể tra công thức bất cứ lúc nào."}],"related":[{"hanzi":"助理","pinyin":"zhùlǐ","vi":"trợ lý"},{"hanzi":"帮手","pinyin":"bāngshǒu","vi":"người giúp việc"},{"hanzi":"秘书","pinyin":"mìshū","vi":"thư ký"},{"hanzi":"得力助手","pinyin":"délìzhùshǒu","vi":"trợ thủ đắc lực"}]},{"id":"注重","hanzi":"注重","pinyin":"zhùzhòng","meaning_vi":"chú trọng","explanation":"注 (chú – dồn vào) + 重 (trọng – coi trọng) → chú trọng, đặc biệt coi trọng. Ví dụ: 注重细节, 注重质量, 注重实际.","hsk_level":6,"tags":["dong-tu"],"image":"❗","examples":[{"type":"basic","zh":"她很注重健康。","pinyin":"Tā hěn zhùzhòng jiànkāng.","vi":"Cô ấy rất chú trọng sức khỏe."},{"type":"simple","zh":"这所学校特别注重培养学生的动手能力。","pinyin":"Zhè suǒ xuéxiào tèbié zhùzhòng péiyǎng xuésheng de dòngshǒunénglì.","vi":"Ngôi trường này đặc biệt chú trọng bồi dưỡng khả năng thực hành của học sinh."},{"type":"compound","zh":"他不但注重外表，而且很注重自己的言谈举止。","pinyin":"Tā búdàn zhùzhòng wàibiǎo, érqiě hěn zhùzhòng zìjǐ de yántán jǔzhǐ.","vi":"Anh ấy không chỉ chú trọng vẻ ngoài mà còn rất chú trọng lời ăn tiếng nói của mình."}],"related":[{"hanzi":"重视","pinyin":"zhòngshì","vi":"coi trọng"},{"hanzi":"着重","pinyin":"zhuózhòng","vi":"nhấn mạnh"},{"hanzi":"讲究","pinyin":"jiǎngjiu","vi":"chú ý cầu kỳ"},{"hanzi":"忽视","pinyin":"hūshì","vi":"xem nhẹ"}]},{"id":"扎","hanzi":"扎","pinyin":"zhā","meaning_vi":"đâm, châm (kim); bám, cắm (rễ)","explanation":"扎 (trát): đâm, châm, cắm vào. Ví dụ: 扎针 (châm kim), 扎根 (bén rễ), 扎手 (đâm tay); đọc zā nghĩa là buộc, bó (扎辫子).","hsk_level":6,"tags":["dong-tu"],"image":"💉","examples":[{"type":"basic","zh":"手被针扎了。","pinyin":"Shǒu bèi zhēnzhā le.","vi":"Tay bị kim đâm."},{"type":"simple","zh":"中医在他的背上扎了十几根银针。","pinyin":"Zhōngyī zài tā de bèi shang zhāle shíjǐ gēn yínzhēn.","vi":"Thầy thuốc Đông y châm hơn chục cây kim bạc lên lưng anh ấy."},{"type":"compound","zh":"虽然他刚来这个城市，但是很快就在这里扎下了根。","pinyin":"Suīrán tā gāng lái zhè ge chéngshì, dànshì hěn kuài jiù zài zhèlǐ zhā xiàle gēn.","vi":"Tuy mới đến thành phố này nhưng anh ấy nhanh chóng bám rễ ở đây."}],"related":[{"hanzi":"扎针","pinyin":"zhāzhēn","vi":"châm kim"},{"hanzi":"扎根","pinyin":"zhāgēn","vi":"bám rễ"},{"hanzi":"刺","pinyin":"cì","vi":"đâm"},{"hanzi":"扎实","pinyin":"zhāshi","vi":"vững chắc"}]},{"id":"朝气","hanzi":"朝气","pinyin":"zhāoqì","meaning_vi":"sức sống thanh xuân, khí thế trẻ trung","explanation":"朝 (đọc zhāo - buổi sáng) + 气.","hsk_level":6,"tags":["danh-tu"],"image":"🌅","examples":[{"type":"basic","zh":"他们个个朝气蓬勃。","pinyin":"Tāmen gègè zhāoqìpéngbó.","vi":"Ai nấy đều tràn trề sức sống."},{"type":"simple","zh":"新来的实习生身上有一股朝气。","pinyin":"Xīn lái de shíxíshēng shēnshang yǒu yì gǔ zhāoqì.","vi":"Các thực tập sinh mới mang một luồng sinh khí trẻ trung."},{"type":"compound","zh":"只要团队里有年轻人，办公室就总是充满朝气。","pinyin":"Zhǐyào tuánduì li yǒu niánqīngrén, bàngōngshì jiù zǒngshì chōngmǎn zhāoqì.","vi":"Chỉ cần trong nhóm có người trẻ, văn phòng luôn tràn đầy sức sống."}],"related":[{"hanzi":"朝气蓬勃","pinyin":"zhāoqìpéngbó","vi":"tràn đầy sức sống"},{"hanzi":"活力","pinyin":"huólì","vi":"sức sống"},{"hanzi":"青春","pinyin":"qīngchūn","vi":"thanh xuân"},{"hanzi":"暮气","pinyin":"mùqì","vi":"khí thế ủ rũ"}],"traditional":"朝氣"},{"id":"招收","hanzi":"招收","pinyin":"zhāoshōu","meaning_vi":"tuyển, tuyển sinh, tuyển dụng","explanation":"招 (chiêu – vẫy gọi) + 收 (thu – thu nhận) → tuyển nhận học sinh, công nhân. Ví dụ: 招收新生, 招收工人; gần nghĩa 招生, 招聘.","hsk_level":6,"tags":["dong-tu"],"image":"🎓","examples":[{"type":"basic","zh":"学校招收新生。","pinyin":"Xuéxiào zhāoshōu xīnshēng.","vi":"Trường tuyển học sinh mới."},{"type":"simple","zh":"这家工厂今年计划招收五十名技术工人。","pinyin":"Zhè jiā gōngchǎng jīnnián jìhuà zhāoshōu wǔshí míng jìshù gōngrén.","vi":"Nhà máy này năm nay dự định tuyển năm mươi công nhân kỹ thuật."},{"type":"compound","zh":"因为报名人数太多，所以研究所只招收了前十名。","pinyin":"Yīnwèi bàomíng rénshù tài duō, suǒyǐ yánjiūsuǒ zhǐ zhāoshōule qián shí míng.","vi":"Vì số người đăng ký quá đông nên viện nghiên cứu chỉ tuyển mười người đứng đầu."}],"related":[{"hanzi":"招生","pinyin":"zhāoshēng","vi":"tuyển sinh"},{"hanzi":"招聘","pinyin":"zhāopìn","vi":"tuyển dụng"},{"hanzi":"录取","pinyin":"lùqǔ","vi":"trúng tuyển"},{"hanzi":"招募","pinyin":"zhāomù","vi":"chiêu mộ"}]},{"id":"朝三暮四","hanzi":"朝三暮四","pinyin":"zhāosān-mùsì","meaning_vi":"sáng nắng chiều mưa, hay thay đổi thất thường","explanation":"朝三暮四: sáng ba chiều bốn (truyện người nuôi khỉ đổi cách chia hạt dẻ, sách Trang Tử) → vốn chỉ lừa bịp, nay ví người hay thay đổi, không chung thủy.","hsk_level":6,"tags":["thanh-ngu"],"image":"🌦️","examples":[{"type":"basic","zh":"他做事朝三暮四。","pinyin":"Tā zuòshì zhāosānmùsì.","vi":"Anh ta làm việc thất thường, hay thay đổi."},{"type":"simple","zh":"她受不了男朋友朝三暮四的态度。","pinyin":"Tā shòubuliǎo nánpéngyou zhāosānmùsì de tàidù.","vi":"Cô ấy không chịu nổi thái độ thay đổi thất thường của bạn trai."},{"type":"compound","zh":"如果你学东西总是朝三暮四，就什么也学不好。","pinyin":"Rúguǒ nǐ xué dōngxi zǒngshì zhāosānmùsì, jiù shénme yě xué bu hǎo.","vi":"Nếu bạn học gì cũng cả thèm chóng chán thì chẳng học tốt được gì."}],"related":[{"hanzi":"反复无常","pinyin":"fǎnfùwúcháng","vi":"thất thường"},{"hanzi":"三心二意","pinyin":"sānxīn'èryì","vi":"không chuyên tâm"},{"hanzi":"见异思迁","pinyin":"jiànyìsīqiān","vi":"thấy mới nới cũ"},{"hanzi":"始终如一","pinyin":"shǐzhōngrúyī","vi":"trước sau như một"}]},{"id":"朝夕相处","hanzi":"朝夕相处","pinyin":"zhāoxī-xiāngchǔ","meaning_vi":"sớm tối bên nhau","explanation":"朝夕 (sáng tối) + 相处 (chung sống). Thành ngữ.","hsk_level":6,"tags":["thanh-ngu"],"image":"👫","examples":[{"type":"basic","zh":"我和她朝夕相处。","pinyin":"Wǒ hé tā zhāoxīxiāngchǔ.","vi":"Tôi và cô ấy sớm tối bên nhau."},{"type":"simple","zh":"他和战友们在边防哨所朝夕相处了五年。","pinyin":"Tā hé zhànyǒumen zài biānfáng shàosuǒ zhāoxīxiāngchǔle wǔ nián.","vi":"Anh ấy và đồng đội sớm tối bên nhau năm năm ở đồn biên phòng."},{"type":"compound","zh":"虽然我们朝夕相处，但是我对他的过去一无所知。","pinyin":"Suīrán wǒmen zhāoxīxiāngchǔ, dànshì wǒ duì tā de guòqù yìwúsuǒzhī.","vi":"Tuy chúng tôi sớm tối bên nhau nhưng tôi chẳng biết gì về quá khứ của anh ấy."}],"related":[{"hanzi":"形影不离","pinyin":"xíngyǐngbùlí","vi":"như hình với bóng"},{"hanzi":"相处","pinyin":"xiāngchǔ","vi":"chung sống"},{"hanzi":"朝夕","pinyin":"zhāoxī","vi":"sớm tối"},{"hanzi":"日夜","pinyin":"rìyè","vi":"ngày đêm"}],"traditional":"朝夕相處"},{"id":"真相","hanzi":"真相","pinyin":"zhēnxiàng","meaning_vi":"chân tướng","explanation":"真 (chân – thật) + 相 (tướng – hình dạng) → bộ mặt thật, sự thật của sự việc. Ví dụ: 真相大白 (sự thật sáng tỏ), 了解真相, 掩盖真相.","hsk_level":6,"tags":["danh-tu"],"image":"🔍","examples":[{"type":"basic","zh":"真相大白了。","pinyin":"Zhēnxiàng dàbái le.","vi":"Sự thật đã sáng tỏ."},{"type":"simple","zh":"记者花了三个月调查事件的真相。","pinyin":"Jìzhě huāle sān gèyuè diàochá shìjiàn de zhēnxiàng.","vi":"Phóng viên mất ba tháng điều tra chân tướng sự việc."},{"type":"compound","zh":"如果你不告诉我真相，我就再也不相信你了。","pinyin":"Rúguǒ nǐ bú gàosu wǒ zhēnxiàng, wǒ jiù zài yě bù xiāngxìn nǐ le.","vi":"Nếu bạn không nói cho tôi sự thật, tôi sẽ không bao giờ tin bạn nữa."}],"related":[{"hanzi":"事实","pinyin":"shìshí","vi":"sự thật"},{"hanzi":"真相大白","pinyin":"zhēnxiàngdàbái","vi":"sự thật phơi bày"},{"hanzi":"假象","pinyin":"jiǎxiàng","vi":"giả tượng"},{"hanzi":"真实","pinyin":"zhēnshí","vi":"chân thật"}]},{"id":"珍珠","hanzi":"珍珠","pinyin":"zhēnzhū","meaning_vi":"ngọc trai","explanation":"珍 (trân – quý) + 珠 (châu – ngọc tròn) → ngọc trai, viên ngọc tròn sinh ra trong con trai. Ví dụ: 珍珠项链; nghĩa bóng chỉ thứ quý giá.","hsk_level":6,"tags":["danh-tu","do-vat"],"image":"🦪","examples":[{"type":"basic","zh":"她戴着珍珠项链。","pinyin":"Tā dàizhe zhēnzhū xiàngliàn.","vi":"Cô ấy đeo vòng cổ ngọc trai."},{"type":"simple","zh":"渔民从海底捞上来一颗很大的珍珠。","pinyin":"Yúmín cóng Hǎidǐlāo shanglái yì kē hěn dà de zhēnzhū.","vi":"Ngư dân vớt được một viên ngọc trai rất lớn từ đáy biển."},{"type":"compound","zh":"这颗珍珠既圆润又有光泽，所以价格非常高。","pinyin":"Zhè kē zhēnzhū jì yuánrùn yòu yǒu guāngzé, suǒyǐ jiàgé fēicháng gāo.","vi":"Viên ngọc trai này vừa tròn đẹp vừa bóng nên giá rất cao."}],"related":[{"hanzi":"宝石","pinyin":"bǎoshí","vi":"đá quý"},{"hanzi":"项链","pinyin":"xiàngliàn","vi":"dây chuyền"},{"hanzi":"珍贵","pinyin":"zhēnguì","vi":"quý giá"},{"hanzi":"钻石","pinyin":"zuànshí","vi":"kim cương"}]},{"id":"蒸发","hanzi":"蒸发","pinyin":"zhēngfā","meaning_vi":"bốc hơi","explanation":"蒸 (chưng – hơi nước bốc lên) + 发 (phát – tỏa ra) → chất lỏng bốc hơi; khẩu ngữ còn chỉ người, tiền biến mất không dấu vết. Ví dụ: 水分蒸发, 人间蒸发.","hsk_level":6,"tags":["dong-tu"],"image":"♨️","examples":[{"type":"basic","zh":"水蒸发得很快。","pinyin":"Shuǐ zhēngfā de hěn kuài.","vi":"Nước bay hơi rất nhanh."},{"type":"simple","zh":"盘子里的酒精不到一分钟就蒸发了。","pinyin":"Pánzi li de jiǔjīng búdào yì fēnzhōng jiù zhēngfā le.","vi":"Cồn trong đĩa chưa đến một phút đã bay hơi hết."},{"type":"compound","zh":"因为天气持续高温，所以湖里的水大量蒸发。","pinyin":"Yīnwèi tiānqì chíxù gāowēn, suǒyǐ Húli de shuǐ dàliàng zhēngfā.","vi":"Vì thời tiết nắng nóng kéo dài nên nước hồ bốc hơi rất nhiều."}],"related":[{"hanzi":"挥发","pinyin":"huīfā","vi":"bay hơi"},{"hanzi":"水蒸气","pinyin":"shuǐzhēngqì","vi":"hơi nước"},{"hanzi":"凝结","pinyin":"níngjié","vi":"ngưng tụ"},{"hanzi":"人间蒸发","pinyin":"rénjiānzhēngfā","vi":"biến mất khỏi nhân gian"}],"traditional":"蒸發"},{"id":"争气","hanzi":"争气","pinyin":"zhēngqì","meaning_vi":"cố gắng vươn lên","explanation":"争 (tranh – giành) + 气 (khí – chí khí) → cố gắng vươn lên, không chịu thua kém, làm người khác tự hào. Ví dụ: 孩子很争气, 不争气.","hsk_level":6,"tags":["dong-tu"],"image":"💪","examples":[{"type":"basic","zh":"儿子真争气！","pinyin":"Érzi zhēn zhēngqì!","vi":"Con trai thật biết phấn đấu, làm rạng mặt!"},{"type":"simple","zh":"这个争气的孩子考上了全县第一名。","pinyin":"Zhè ge zhēngqì de háizi kǎoshangle quán xiàn dìyīmíng.","vi":"Đứa trẻ biết phấn đấu này đã đỗ thủ khoa toàn huyện."},{"type":"compound","zh":"既然父母为你付出了那么多，你就一定要争气。","pinyin":"Jìrán fùmǔ wèi nǐ fùchūle nàme duō, nǐ jiù yídìngyào zhēngqì.","vi":"Bố mẹ đã hy sinh cho con nhiều như vậy thì con nhất định phải cố gắng vươn lên."}],"related":[{"hanzi":"争光","pinyin":"zhēngguāng","vi":"làm rạng danh"},{"hanzi":"不争气","pinyin":"bùzhēngqì","vi":"chẳng ra gì"},{"hanzi":"努力","pinyin":"nǔlì","vi":"nỗ lực"},{"hanzi":"争取","pinyin":"zhēngqǔ","vi":"tranh thủ giành lấy"}],"traditional":"爭氣"},{"id":"征收","hanzi":"征收","pinyin":"zhēngshōu","meaning_vi":"thu (thuế, phí); trưng thu, thu hồi (đất)","explanation":"征 (trưng – thu) + 收 (thu – thu) → nhà nước thu thuế, phí theo luật; cũng nghĩa trưng thu. Ví dụ: 征收税款, 征收土地.","hsk_level":6,"tags":["dong-tu"],"image":"💰","examples":[{"type":"basic","zh":"政府征收新税。","pinyin":"Zhèngfǔ zhēngshōu xīn shuì.","vi":"Chính phủ thu loại thuế mới."},{"type":"simple","zh":"这座城市开始对外地车辆征收拥堵费。","pinyin":"Zhè zuò chéngshì kāishǐ duì wàidì chēliàng zhēngshōu yōngdǔ fèi.","vi":"Thành phố này bắt đầu thu phí ùn tắc đối với xe ngoại tỉnh."},{"type":"compound","zh":"因为这块土地被政府征收了，所以村民们搬进了新楼。","pinyin":"Yīnwèi zhè kuài tǔdì bèi zhèngfǔ zhēngshōu le, suǒyǐ cūnmínmen bān jìnle xīn lóu.","vi":"Vì mảnh đất này bị nhà nước thu hồi nên dân làng đã chuyển vào nhà mới."}],"related":[{"hanzi":"税收","pinyin":"shuìshōu","vi":"thu thuế"},{"hanzi":"征税","pinyin":"zhēngshuì","vi":"đánh thuế"},{"hanzi":"收费","pinyin":"shōufèi","vi":"thu phí"},{"hanzi":"征用","pinyin":"zhēngyòng","vi":"trưng dụng"}],"traditional":"徵收"},{"id":"蒸蒸日上","hanzi":"蒸蒸日上","pinyin":"zhēngzhēng-rìshàng","meaning_vi":"ngày càng phát triển hưng thịnh","explanation":"蒸蒸日上: như hơi nước (蒸蒸) mỗi ngày (日) bốc lên (上) → sự nghiệp, đời sống ngày càng phát triển, thịnh vượng. Ví dụ: 事业蒸蒸日上.","hsk_level":6,"tags":["thanh-ngu"],"image":"📈","examples":[{"type":"basic","zh":"祝贵公司蒸蒸日上！","pinyin":"Zhù guìgōngsī zhēngzhēngrìshàng!","vi":"Chúc quý công ty ngày càng phát triển!"},{"type":"simple","zh":"改革开放以后，这里的经济蒸蒸日上。","pinyin":"Gǎigékāifàng yǐhòu, zhèlǐ de jīngjì zhēngzhēngrìshàng.","vi":"Sau cải cách mở cửa, kinh tế nơi đây ngày càng đi lên."},{"type":"compound","zh":"他们不但产品质量好，而且服务周到，所以事业蒸蒸日上。","pinyin":"Tāmen búdàn chǎnpǐn zhìliàng hǎo, érqiě fúwù zhōudào, suǒyǐ shìyè zhēngzhēngrìshàng.","vi":"Họ không chỉ có sản phẩm chất lượng tốt mà còn phục vụ chu đáo nên sự nghiệp ngày càng thịnh vượng."}],"related":[{"hanzi":"欣欣向荣","pinyin":"xīnxīnxiàngróng","vi":"phát triển tươi tốt"},{"hanzi":"兴旺","pinyin":"xīngwàng","vi":"hưng thịnh"},{"hanzi":"繁荣","pinyin":"fánróng","vi":"phồn vinh"},{"hanzi":"每况愈下","pinyin":"měikuàngyùxià","vi":"ngày càng tệ"}]},{"id":"知觉","hanzi":"知觉","pinyin":"zhījué","meaning_vi":"tri giác, cảm giác; ý thức, sự tỉnh táo","explanation":"知 (tri – biết) + 觉 (giác – cảm giác) → khả năng cảm nhận, nhận biết của giác quan; cũng chỉ sự tỉnh táo. Ví dụ: 失去知觉 (bất tỉnh).","hsk_level":6,"tags":["danh-tu","nhan-thuc"],"image":"🧠","examples":[{"type":"basic","zh":"他失去了知觉。","pinyin":"Tā shīqùle zhījué.","vi":"Anh ấy bất tỉnh."},{"type":"simple","zh":"冻了一夜之后，他的双脚已经没有知觉了。","pinyin":"Dòngle yí yè zhīhòu, tā de shuāngjiǎo yǐjīng méiyǒu zhījué le.","vi":"Sau một đêm bị lạnh cóng, hai bàn chân anh ấy đã mất cảm giác."},{"type":"compound","zh":"病人虽然还没醒，但是手指已经恢复了知觉。","pinyin":"Bìngrén suīrán hái méi xǐng, dànshì shǒuzhǐ yǐjīng huīfùle zhījué.","vi":"Bệnh nhân tuy chưa tỉnh nhưng ngón tay đã có lại cảm giác."}],"related":[{"hanzi":"感觉","pinyin":"gǎnjué","vi":"cảm giác"},{"hanzi":"意识","pinyin":"yìshí","vi":"ý thức"},{"hanzi":"失去知觉","pinyin":"shīqùzhījué","vi":"bất tỉnh"},{"hanzi":"察觉","pinyin":"chájué","vi":"nhận ra"}],"traditional":"知覺"},{"id":"支援","hanzi":"支援","pinyin":"zhīyuán","meaning_vi":"chi viện, hỗ trợ","explanation":"支 (chi – chống đỡ) + 援 (viện – giúp) → chi viện, giúp đỡ bằng nhân lực, vật lực. Ví dụ: 支援灾区, 互相支援, 支援前线.","hsk_level":6,"tags":["dong-tu"],"image":"🤝","examples":[{"type":"basic","zh":"请快来支援！","pinyin":"Qǐng kuài lái zhīyuán!","vi":"Mau đến chi viện!"},{"type":"simple","zh":"全国各地的医生纷纷赶去支援灾区。","pinyin":"Quánguó gèdì de yīshēng fēnfēn gǎn qù zhīyuán zāiqū.","vi":"Bác sĩ khắp cả nước lần lượt tới chi viện vùng thiên tai."},{"type":"compound","zh":"如果人手不够，总部就会派人来支援。","pinyin":"Rúguǒ rénshǒu búgòu, zǒngbù jiù huì pàirén lái zhīyuán.","vi":"Nếu thiếu người, trụ sở chính sẽ cử người tới hỗ trợ."}],"related":[{"hanzi":"援助","pinyin":"yuánzhù","vi":"viện trợ"},{"hanzi":"支持","pinyin":"zhīchí","vi":"ủng hộ"},{"hanzi":"帮助","pinyin":"bāngzhù","vi":"giúp đỡ"},{"hanzi":"增援","pinyin":"zēngyuán","vi":"tăng viện"}]},{"id":"忠实","hanzi":"忠实","pinyin":"zhōngshí","meaning_vi":"trung thành, chân thật; đúng với nguyên bản","explanation":"忠 (trung – trung thành) + 实 (thực – thật) → trung thành, đáng tin; cũng nghĩa đúng với thực tế. Ví dụ: 忠实的朋友, 忠实观众, 忠实于原文.","hsk_level":6,"tags":["tinh-tu"],"image":"🤝","examples":[{"type":"basic","zh":"我是他的忠实读者。","pinyin":"Wǒ shì tā de zhōngshí dúzhě.","vi":"Tôi là độc giả trung thành của anh ấy."},{"type":"simple","zh":"这部纪录片忠实地记录了战争的残酷。","pinyin":"Zhè bù jìlùpiàn zhōng shíde jìlùle zhànzhēng de cánkù.","vi":"Bộ phim tài liệu này ghi lại chân thực sự tàn khốc của chiến tranh."},{"type":"compound","zh":"即使主人去世多年，这只忠实的狗也每天在门口等着。","pinyin":"Jíshǐ zhǔrén qùshì duōnián, zhè zhī zhōngshí de gǒu yě měitiān zài ménkǒu děng zhe.","vi":"Dù chủ đã mất nhiều năm, chú chó trung thành này vẫn ngày ngày chờ ở cửa."}],"related":[{"hanzi":"忠诚","pinyin":"zhōngchéng","vi":"trung thành"},{"hanzi":"诚实","pinyin":"chéngshí","vi":"thành thật"},{"hanzi":"忠实粉丝","pinyin":"zhōngshífěnsī","vi":"người hâm mộ trung thành"},{"hanzi":"可靠","pinyin":"kěkào","vi":"đáng tin"}],"traditional":"忠實"},{"id":"终身","hanzi":"终身","pinyin":"zhōngshēn","meaning_vi":"suốt đời","explanation":"终 (chung – trọn, kết thúc) + 身 (thân – đời người) → suốt đời, cả cuộc đời. Ví dụ: 终身大事 (chuyện hôn nhân), 终身学习, 终身难忘.","hsk_level":6,"tags":["danh-tu","thoi-gian"],"image":"♾️","examples":[{"type":"basic","zh":"这是终身大事。","pinyin":"Zhè shì zhōngshēn dàshì.","vi":"Đây là việc hệ trọng cả đời."},{"type":"simple","zh":"他立志终身从事教育事业。","pinyin":"Tā lìzhì zhōngshēn cóngshì jiàoyù shìyè.","vi":"Anh ấy quyết chí cả đời theo đuổi sự nghiệp giáo dục."},{"type":"compound","zh":"只要买了这张会员卡，你就可以终身免费使用健身房。","pinyin":"Zhǐyào mǎile zhè zhāng huìyuánkǎ, nǐ jiù kěyǐ zhōngshēn miǎnfèi shǐyòng jiànshēnfáng.","vi":"Chỉ cần mua thẻ hội viên này, bạn có thể dùng phòng tập miễn phí trọn đời."}],"related":[{"hanzi":"终生","pinyin":"zhōngshēng","vi":"cả đời"},{"hanzi":"一生","pinyin":"yìshēng","vi":"một đời"},{"hanzi":"终身大事","pinyin":"zhōngshēndàshì","vi":"chuyện trăm năm"},{"hanzi":"终身教育","pinyin":"zhōngshēnjiàoyù","vi":"giáo dục suốt đời"}],"traditional":"終身"},{"id":"周边","hanzi":"周边","pinyin":"zhōubiān","meaning_vi":"vùng lân cận","explanation":"周 (chu – xung quanh) + 边 (biên – bên, mép) → khu vực xung quanh, lân cận. Ví dụ: 周边地区, 周边国家; còn chỉ hàng hóa ăn theo (周边产品).","hsk_level":6,"tags":["danh-tu","dia-diem"],"image":"📍","examples":[{"type":"basic","zh":"学校周边很安静。","pinyin":"Xuéxiào zhōubiān hěn ānjìng.","vi":"Khu vực quanh trường rất yên tĩnh."},{"type":"simple","zh":"周末我们开车去城市周边的农家乐玩。","pinyin":"Zhōumò wǒmen kāichē qù chéngshì zhōubiān de nóngjiālè wán.","vi":"Cuối tuần chúng tôi lái xe đi chơi ở các trang trại du lịch quanh thành phố."},{"type":"compound","zh":"地铁站一开通，周边的房价就涨了不少。","pinyin":"Dìtiězhàn yì kāitōng, zhōubiān de fángjià jiù zhǎngle bùshǎo.","vi":"Ga tàu điện ngầm vừa khai trương, giá nhà khu vực xung quanh liền tăng không ít."}],"related":[{"hanzi":"周围","pinyin":"zhōuwéi","vi":"xung quanh"},{"hanzi":"附近","pinyin":"fùjìn","vi":"lân cận"},{"hanzi":"周边国家","pinyin":"zhōubiānguójiā","vi":"các nước láng giềng"},{"hanzi":"邻近","pinyin":"línjìn","vi":"gần kề"}],"traditional":"周邊"},{"id":"周折","hanzi":"周折","pinyin":"zhōuzhé","meaning_vi":"trắc trở","explanation":"周 (chu – vòng) + 折 (chiết – gấp khúc) → quanh co, trắc trở, phải qua nhiều bước mới xong. Thường nói: 几经周折, 费了一番周折.","hsk_level":6,"tags":["danh-tu"],"image":"〰️","examples":[{"type":"basic","zh":"事情几经周折。","pinyin":"Shìqing jǐjīng zhōuzhé.","vi":"Sự việc trải qua nhiều trắc trở."},{"type":"simple","zh":"他费了好一番周折才找到这家老店。","pinyin":"Tā fèile hǎo yìfān zhōuzhé cái zhǎodào zhè jiālǎo diàn.","vi":"Anh ấy phải mất bao công sức mới tìm được tiệm lâu đời này."},{"type":"compound","zh":"虽然签证办得颇费周折，但是我们最后还是顺利出发了。","pinyin":"Suīrán qiānzhèng bàn de pō fèizhōuzhé, dànshì wǒmen zuìhòu háishi shùnlì chūfā le.","vi":"Tuy làm visa khá trắc trở nhưng cuối cùng chúng tôi vẫn lên đường suôn sẻ."}],"related":[{"hanzi":"曲折","pinyin":"qūzhé","vi":"quanh co"},{"hanzi":"波折","pinyin":"bōzhé","vi":"trắc trở"},{"hanzi":"费周折","pinyin":"fèizhōuzhé","vi":"tốn nhiều công sức"},{"hanzi":"顺利","pinyin":"shùnlì","vi":"thuận lợi"}]},{"id":"诸位","hanzi":"诸位","pinyin":"zhūwèi","meaning_vi":"chư vị, quý vị","explanation":"诸 (chư – các) + 位 (vị – vị) → các vị, quý vị; lời xưng hô lịch sự với nhiều người. Ví dụ: 诸位来宾, 诸位朋友.","hsk_level":6,"tags":["dai-tu"],"image":"🙇","examples":[{"type":"basic","zh":"诸位请安静。","pinyin":"Zhūwèi qǐng ānjìng.","vi":"Thưa quý vị, xin hãy giữ yên lặng."},{"type":"simple","zh":"感谢诸位今天来参加我们的婚礼。","pinyin":"Gǎnxiè zhūwèi jīntiān lái cānjiā wǒmen de hūnlǐ.","vi":"Cảm ơn quý vị hôm nay đã đến dự đám cưới của chúng tôi."},{"type":"compound","zh":"如果诸位还有什么问题，就请会后找我详谈。","pinyin":"Rúguǒ zhūwèi háiyǒu shénme wèntí, jiù qǐng huì hòu zhǎo wǒ xiáng tán.","vi":"Nếu quý vị còn câu hỏi gì, xin hãy gặp tôi sau cuộc họp để trao đổi chi tiết."}],"related":[{"hanzi":"各位","pinyin":"gèwèi","vi":"các vị"},{"hanzi":"大家","pinyin":"dàjiā","vi":"mọi người"},{"hanzi":"女士们先生们","pinyin":"nǚshìmen xiānshengmen","vi":"thưa quý vị"},{"hanzi":"诸如","pinyin":"zhūrú","vi":"chẳng hạn như"}],"traditional":"諸位"},{"id":"眨","hanzi":"眨","pinyin":"zhǎ","meaning_vi":"chớp mắt","explanation":"眨 (trát): chớp mắt. Ví dụ: 眨眼, 一眨眼 (chớp mắt, rất nhanh), 眼睛都不眨一下 (không chớp mắt).","hsk_level":6,"tags":["dong-tu"],"image":"😉","examples":[{"type":"basic","zh":"她眨了眨眼睛。","pinyin":"Tā zhǎle zhǎyǎnjing.","vi":"Cô ấy chớp chớp mắt."},{"type":"simple","zh":"小女孩调皮地朝我眨了一下眼。","pinyin":"Xiǎo nǚhái tiáopí de cháo wǒ zhǎle yíxià yǎn.","vi":"Cô bé tinh nghịch nháy mắt với tôi."},{"type":"compound","zh":"魔术师的手太快了，我一眨眼，硬币就不见了。","pinyin":"Móshùshī de shǒu tài kuài le, wǒ yìzhǎyǎn, yìngbì jiù bújiàn le.","vi":"Tay ảo thuật gia quá nhanh, tôi vừa chớp mắt, đồng xu đã biến mất."}],"related":[{"hanzi":"眨眼","pinyin":"zhǎyǎn","vi":"chớp mắt"},{"hanzi":"一眨眼","pinyin":"yìzhǎyǎn","vi":"trong chớp mắt"},{"hanzi":"闭眼","pinyin":"bìyǎn","vi":"nhắm mắt"},{"hanzi":"睁眼","pinyin":"zhēngyǎn","vi":"mở mắt"}]},{"id":"展示","hanzi":"展示","pinyin":"zhǎnshì","meaning_vi":"trưng bày, giới thiệu; thể hiện, phô diễn","explanation":"展 (triển – mở ra) + 示 (thị – cho thấy) → bày ra cho mọi người thấy, trưng bày, thể hiện. Ví dụ: 展示作品, 展示才华, 展示柜.","hsk_level":6,"tags":["dong-tu"],"image":"🖼️","examples":[{"type":"basic","zh":"他展示了新产品。","pinyin":"Tā zhǎnshìle xīnchǎnpǐn.","vi":"Anh ấy đã giới thiệu sản phẩm mới."},{"type":"simple","zh":"博物馆展示了三百多件唐代文物。","pinyin":"Bówùguǎn zhǎnshìle sān bǎi duō jiàn Tángdài wénwù.","vi":"Bảo tàng trưng bày hơn ba trăm hiện vật thời Đường."},{"type":"compound","zh":"这次比赛不但能展示才华，而且能结交新朋友。","pinyin":"Zhè cì bǐsài búdàn néng zhǎnshì cáihuá, érqiě néng jiéjiāo xīnpéngyou.","vi":"Cuộc thi lần này không chỉ giúp thể hiện tài năng mà còn giúp kết bạn mới."}],"related":[{"hanzi":"展览","pinyin":"zhǎnlǎn","vi":"triển lãm"},{"hanzi":"展现","pinyin":"zhǎnxiàn","vi":"thể hiện"},{"hanzi":"表现","pinyin":"biǎoxiàn","vi":"biểu hiện"},{"hanzi":"展品","pinyin":"zhǎnpǐn","vi":"vật trưng bày"}]},{"id":"崭新","hanzi":"崭新","pinyin":"zhǎnxīn","meaning_vi":"mới tinh","explanation":"崭 (tiệm – cao vút, rất) + 新 (tân – mới) → mới tinh, hoàn toàn mới. Ví dụ: 崭新的衣服, 崭新的面貌.","hsk_level":6,"tags":["tinh-tu"],"image":"🆕","examples":[{"type":"basic","zh":"他穿着崭新的鞋。","pinyin":"Tā chuānzhe zhǎnxīn de xié.","vi":"Anh ấy đi đôi giày mới tinh."},{"type":"simple","zh":"毕业后，她开始了崭新的生活。","pinyin":"Bìyè hòu, tā kāishǐle zhǎnxīn de shēnghuó.","vi":"Sau khi tốt nghiệp, cô ấy bắt đầu một cuộc sống hoàn toàn mới."},{"type":"compound","zh":"这辆车虽然开了五年，但是看起来还是崭新的。","pinyin":"Zhè liàng chē suīrán kāile wǔ nián, dànshì kànqǐlái háishi zhǎnxīn de.","vi":"Chiếc xe này tuy đã chạy năm năm nhưng trông vẫn mới tinh."}],"related":[{"hanzi":"全新","pinyin":"quánxīn","vi":"hoàn toàn mới"},{"hanzi":"新颖","pinyin":"xīnyǐng","vi":"mới lạ"},{"hanzi":"陈旧","pinyin":"chénjiù","vi":"cũ kỹ"},{"hanzi":"簇新","pinyin":"cùxīn","vi":"mới toanh"}],"traditional":"嶄新"},{"id":"沼泽","hanzi":"沼泽","pinyin":"zhǎozé","meaning_vi":"đầm lầy","explanation":"沼 (chiểu – ao) + 泽 (trạch – đầm) → vùng đất lầy ngập nước, đầm lầy. Ví dụ: 沼泽地, 陷入沼泽.","hsk_level":6,"tags":["danh-tu","thien-nhien"],"image":"🌿","examples":[{"type":"basic","zh":"前面是一片沼泽。","pinyin":"Qiánmiàn shì yípiàn zhǎozé.","vi":"Phía trước là một vùng đầm lầy."},{"type":"simple","zh":"许多珍稀的鸟类在这片沼泽里过冬。","pinyin":"Xǔduō zhēnxī de niǎolèi zài zhè piàn zhǎozé li guòdōng.","vi":"Nhiều loài chim quý hiếm trú đông trong vùng đầm lầy này."},{"type":"compound","zh":"如果不小心走进沼泽，人就会越陷越深。","pinyin":"Rúguǒ bù xiǎoxīn zǒujìn zhǎozé, rén jiù huì yuè xiàn yuè shēn.","vi":"Nếu không cẩn thận đi vào đầm lầy, người ta sẽ càng lún càng sâu."}],"related":[{"hanzi":"湿地","pinyin":"shīdì","vi":"đất ngập nước"},{"hanzi":"泥潭","pinyin":"nítán","vi":"vũng bùn"},{"hanzi":"池塘","pinyin":"chítáng","vi":"ao"},{"hanzi":"湖泊","pinyin":"húpō","vi":"hồ"}],"traditional":"沼澤"},{"id":"指定","hanzi":"指定","pinyin":"zhǐdìng","meaning_vi":"chỉ định","explanation":"指 (chỉ – chỉ ra) + 定 (định – định) → chỉ định, quy định rõ người, địa điểm, thời gian. Ví dụ: 指定地点, 指定时间, 指定人选.","hsk_level":6,"tags":["dong-tu"],"image":"👉","examples":[{"type":"basic","zh":"请坐在指定位置。","pinyin":"Qǐngzuò zài zhǐdìng wèizhì.","vi":"Vui lòng ngồi đúng vị trí được chỉ định."},{"type":"simple","zh":"老板指定小李负责这个新项目。","pinyin":"Lǎobǎn zhǐdìng xiǎo Lǐ fùzé zhè ge xīn xiàngmù.","vi":"Sếp chỉ định Tiểu Lý phụ trách dự án mới này."},{"type":"compound","zh":"只要在指定时间内付款，就能享受八折优惠。","pinyin":"Zhǐyào zài zhǐdìng shíjiān nèi fùkuǎn, jiù néng xiǎngshòu bā zhé yōuhuì.","vi":"Chỉ cần thanh toán trong thời gian quy định là được giảm giá 20%."}],"related":[{"hanzi":"指派","pinyin":"zhǐpài","vi":"chỉ định phân công"},{"hanzi":"规定","pinyin":"guīdìng","vi":"quy định"},{"hanzi":"指定地点","pinyin":"zhǐdìngdìdiǎn","vi":"địa điểm chỉ định"},{"hanzi":"委派","pinyin":"wěipài","vi":"ủy phái"}]},{"id":"指示","hanzi":"指示","pinyin":"zhǐshì","meaning_vi":"chỉ thị","explanation":"指 (chỉ – chỉ ra) + 示 (thị – cho thấy) → chỉ thị, chỉ đạo của cấp trên; cũng nghĩa chỉ cho thấy. Ví dụ: 上级指示, 按指示办事, 指示牌.","hsk_level":6,"tags":["dong-tu"],"image":"📢","examples":[{"type":"basic","zh":"请按指示操作。","pinyin":"Qǐng àn zhǐshì cāozuò.","vi":"Vui lòng thao tác theo chỉ dẫn."},{"type":"simple","zh":"上级指示我们尽快完成救援工作。","pinyin":"Shàngjí zhǐshì wǒmen jǐnkuài wánchéng jiùyuán gōngzuò.","vi":"Cấp trên chỉ thị chúng tôi nhanh chóng hoàn thành công tác cứu hộ."},{"type":"compound","zh":"因为没有收到经理的指示，所以他不敢擅自行动。","pinyin":"Yīnwèi méiyǒu shōudào jīnglǐ de zhǐshì, suǒyǐ tā bù gǎn shànzì xíngdòng.","vi":"Vì chưa nhận được chỉ thị của giám đốc nên anh ấy không dám tự ý hành động."}],"related":[{"hanzi":"指令","pinyin":"zhǐlìng","vi":"mệnh lệnh"},{"hanzi":"命令","pinyin":"mìnglìng","vi":"ra lệnh"},{"hanzi":"指导","pinyin":"zhǐdǎo","vi":"chỉ đạo"},{"hanzi":"指示牌","pinyin":"zhǐshìpái","vi":"biển chỉ dẫn"}]},{"id":"肿","hanzi":"肿","pinyin":"zhǒng","meaning_vi":"sưng, phù","explanation":"肿 (thũng): sưng, phù. Ví dụ: 脚肿了, 红肿, 肿瘤 (khối u), 浮肿 (phù nề).","hsk_level":6,"tags":["dong-tu"],"image":"🤕","examples":[{"type":"basic","zh":"他的脚肿了。","pinyin":"Tā de jiǎo zhǒng le.","vi":"Chân anh ấy bị sưng."},{"type":"simple","zh":"被蚊子咬过的地方肿起了一个大包。","pinyin":"Bèi wénzi yǎoguo de dìfang zhǒng qǐle yí gè dà bāo.","vi":"Chỗ bị muỗi đốt sưng lên một cục to."},{"type":"compound","zh":"如果脚踝肿得厉害，就要马上去医院拍片子。","pinyin":"Rúguǒ jiǎohuái zhǒng de lìhai, jiùyào mǎ shàngqù yīyuàn pāi piānzi.","vi":"Nếu mắt cá chân sưng nhiều thì phải đến bệnh viện chụp phim ngay."}],"related":[{"hanzi":"肿胀","pinyin":"zhǒngzhàng","vi":"sưng phù"},{"hanzi":"红肿","pinyin":"hóngzhǒng","vi":"sưng đỏ"},{"hanzi":"浮肿","pinyin":"fúzhǒng","vi":"phù nề"},{"hanzi":"消肿","pinyin":"xiāozhǒng","vi":"tiêu sưng"}],"traditional":"腫"},{"id":"主权","hanzi":"主权","pinyin":"zhǔquán","meaning_vi":"chủ quyền","explanation":"主 (chủ – chủ) + 权 (quyền – quyền) → quyền tự chủ tối cao của một quốc gia. Ví dụ: 国家主权, 维护主权, 领土主权.","hsk_level":6,"tags":["danh-tu","xa-hoi"],"image":"🏛️","examples":[{"type":"basic","zh":"主权不容侵犯。","pinyin":"Zhǔquán bùróng qīnfàn.","vi":"Chủ quyền không cho phép xâm phạm."},{"type":"simple","zh":"每个国家都有权维护自己的领土主权。","pinyin":"Měi gè guójiā dōu yǒuquán wéihù zìjǐ de lǐngtǔ zhǔquán.","vi":"Mỗi quốc gia đều có quyền bảo vệ chủ quyền lãnh thổ của mình."},{"type":"compound","zh":"两国虽然存在分歧，但是都尊重对方的主权。","pinyin":"Liǎngguó suīrán cúnzài fēnqí, dànshì dōu zūnzhòng duìfāng de zhǔquán.","vi":"Hai nước tuy tồn tại bất đồng nhưng đều tôn trọng chủ quyền của nhau."}],"related":[{"hanzi":"领土","pinyin":"lǐngtǔ","vi":"lãnh thổ"},{"hanzi":"主权国家","pinyin":"Zhǔquánguójiā","vi":"quốc gia có chủ quyền"},{"hanzi":"独立","pinyin":"dúlì","vi":"độc lập"},{"hanzi":"领海","pinyin":"lǐnghǎi","vi":"lãnh hải"}],"traditional":"主權"},{"id":"作风","hanzi":"作风","pinyin":"zuòfēng","meaning_vi":"tác phong","explanation":"作 (tác – làm) + 风 (phong – lối, nếp) → tác phong, phong cách làm việc và lối sống. Ví dụ: 工作作风, 作风正派, 官僚作风.","hsk_level":6,"tags":["danh-tu"],"image":"👔","examples":[{"type":"basic","zh":"他作风很正派。","pinyin":"Tā zuòfēng hěn zhèngpài.","vi":"Tác phong của anh ấy rất đứng đắn."},{"type":"simple","zh":"新局长雷厉风行的作风让大家很佩服。","pinyin":"Xīn júzhǎng léilìfēngxíng de zuòfēng ràng dàjiā hěn pèifú.","vi":"Tác phong quyết liệt, mau lẹ của cục trưởng mới khiến mọi người rất khâm phục."},{"type":"compound","zh":"如果干部作风不正，老百姓就不会信任政府。","pinyin":"Rúguǒ gànbù zuòfēng bú zhèng, lǎobǎixìng jiù bú huì xìnrèn zhèngfǔ.","vi":"Nếu cán bộ tác phong không đứng đắn, người dân sẽ không tin tưởng chính quyền."}],"related":[{"hanzi":"风格","pinyin":"fēnggé","vi":"phong cách"},{"hanzi":"工作作风","pinyin":"gōngzuòzuòfēng","vi":"tác phong làm việc"},{"hanzi":"品行","pinyin":"pǐnxíng","vi":"phẩm hạnh"},{"hanzi":"习气","pinyin":"xíqì","vi":"thói quen xấu"}],"traditional":"作風"},{"id":"坐井观天","hanzi":"坐井观天","pinyin":"zuòjǐng-guāntiān","meaning_vi":"ngồi đáy giếng ngắm trời (tầm nhìn hạn hẹp)","explanation":"坐井观天: ngồi trong giếng (坐井) mà nhìn trời (观天) → ví người tầm nhìn hạn hẹp, hiểu biết nông cạn mà tưởng mình biết nhiều.","hsk_level":6,"tags":["thanh-ngu"],"image":"🐸","examples":[{"type":"basic","zh":"别再坐井观天了。","pinyin":"Bié zài zuòjǐngguāntiān le.","vi":"Đừng làm ếch ngồi đáy giếng nữa."},{"type":"simple","zh":"他出国留学后才发现自己以前是坐井观天。","pinyin":"Tā chūguó liúxué hòu cái fāxiàn zìjǐ yǐqián shì zuòjǐngguāntiān.","vi":"Sau khi du học anh ấy mới nhận ra trước đây mình như ếch ngồi đáy giếng."},{"type":"compound","zh":"如果你从来不出去看看，就只能坐井观天。","pinyin":"Rúguǒ nǐ cóngláibù chūqu kànkan, jiù zhǐnéng zuòjǐngguāntiān.","vi":"Nếu bạn không bao giờ ra ngoài nhìn ngắm, bạn chỉ có thể như ếch ngồi đáy giếng."}],"related":[{"hanzi":"井底之蛙","pinyin":"jǐngdǐzhīwā","vi":"ếch ngồi đáy giếng"},{"hanzi":"目光短浅","pinyin":"mùguāngduǎnqiǎn","vi":"tầm nhìn hạn hẹp"},{"hanzi":"孤陋寡闻","pinyin":"gūlòuguǎwén","vi":"kiến thức nông cạn"},{"hanzi":"见多识广","pinyin":"jiànduōshíguǎng","vi":"hiểu rộng biết nhiều"}],"traditional":"坐井觀天"},{"id":"做主","hanzi":"做主","pinyin":"zuòzhǔ","meaning_vi":"làm chủ, quyết định","explanation":"做 (tố – làm) + 主 (chủ – chủ) → làm chủ, tự quyết định. Ví dụ: 自己做主, 当家做主, 我做不了主.","hsk_level":6,"tags":["dong-tu"],"image":"👑","examples":[{"type":"basic","zh":"这事我做主。","pinyin":"Zhè shì wǒ zuòzhǔ.","vi":"Việc này tôi quyết."},{"type":"simple","zh":"婚姻大事应该由自己做主。","pinyin":"Hūnyīn dàshì yīnggāi yóu zìjǐ zuòzhǔ.","vi":"Chuyện hôn nhân nên do bản thân tự quyết định."},{"type":"compound","zh":"既然你是老板，那么这件事就由你来做主吧。","pinyin":"Jìrán nǐ shì lǎobǎn, nàme zhè jiàn shì jiù yóu nǐ lái zuòzhǔ ba.","vi":"Anh là ông chủ thì việc này để anh quyết định nhé."}],"related":[{"hanzi":"作主","pinyin":"zuòzhǔ","vi":"làm chủ"},{"hanzi":"决定","pinyin":"juédìng","vi":"quyết định"},{"hanzi":"当家作主","pinyin":"dāngjiāzuòzhǔ","vi":"làm chủ gia đình"},{"hanzi":"自作主张","pinyin":"zìzuòzhǔzhāng","vi":"tự ý quyết định"}]},{"id":"钻研","hanzi":"钻研","pinyin":"zuānyán","meaning_vi":"nghiên cứu sâu","explanation":"钻 (toản – khoan, dùi) + 研 (nghiên – nghiên cứu) → đi sâu nghiên cứu, tìm tòi kỹ lưỡng. Ví dụ: 钻研技术, 刻苦钻研, 钻研业务.","hsk_level":6,"tags":["dong-tu"],"image":"🔬","examples":[{"type":"basic","zh":"他刻苦钻研技术。","pinyin":"Tā kèkǔ zuānyán jìshù.","vi":"Anh ấy miệt mài nghiên cứu kỹ thuật."},{"type":"simple","zh":"这位老中医钻研了一辈子针灸。","pinyin":"Zhè wèi lǎo zhōngyī zuānyánle yíbèizi zhēnjiǔ.","vi":"Vị lương y già này nghiên cứu châm cứu cả đời."},{"type":"compound","zh":"只要肯下功夫钻研，再难的问题也能解决。","pinyin":"Zhǐyào kěn xiàgōngfu zuānyán, zài nán de wèntí yě néng jiějué.","vi":"Chỉ cần chịu khó nghiên cứu sâu, vấn đề khó đến mấy cũng giải quyết được."}],"related":[{"hanzi":"研究","pinyin":"yánjiū","vi":"nghiên cứu"},{"hanzi":"刻苦钻研","pinyin":"kèkǔzuānyán","vi":"chăm chỉ nghiên cứu"},{"hanzi":"探索","pinyin":"tànsuǒ","vi":"khám phá"},{"hanzi":"琢磨","pinyin":"zuómo","vi":"nghiền ngẫm"}],"traditional":"鑽研"},{"id":"责怪","hanzi":"责怪","pinyin":"zéguài","meaning_vi":"trách móc","explanation":"责 (trách – trách) + 怪 (quái – trách móc) → trách móc, đổ lỗi cho ai. Ví dụ: 别责怪他, 责怪自己.","hsk_level":6,"tags":["dong-tu"],"image":"😠","examples":[{"type":"basic","zh":"别责怪孩子了。","pinyin":"Bié zéguài háizi le.","vi":"Đừng trách đứa trẻ nữa."},{"type":"simple","zh":"经理没有责怪他迟到的事。","pinyin":"Jīnglǐ méiyǒu zéguài tā chídào de shì.","vi":"Giám đốc không trách anh ấy chuyện đến muộn."},{"type":"compound","zh":"与其互相责怪，不如一起想想解决办法。","pinyin":"Yǔqí hùxiāng zéguài, bùrú yìqǐ xiǎng xiang jiějué bànfǎ.","vi":"Thay vì trách móc nhau, chi bằng cùng nghĩ cách giải quyết."}],"related":[{"hanzi":"责备","pinyin":"zébèi","vi":"trách mắng"},{"hanzi":"埋怨","pinyin":"mányuàn","vi":"oán trách"},{"hanzi":"抱怨","pinyin":"bàoyuàn","vi":"phàn nàn"},{"hanzi":"怪罪","pinyin":"guàizuì","vi":"đổ lỗi"}],"traditional":"責怪"},{"id":"自力更生","hanzi":"自力更生","pinyin":"zìlì-gēngshēng","meaning_vi":"tự lực cánh sinh","explanation":"自力更生: dựa vào sức mình (自力) mà sống lại, vươn lên (更生) → không dựa dẫm người khác, tự lực cánh sinh. Thường dùng cho cá nhân, quốc gia.","hsk_level":6,"tags":["thanh-ngu"],"image":"💪","examples":[{"type":"basic","zh":"我们要自力更生。","pinyin":"Wǒmen yào zìlìgēngshēng.","vi":"Chúng ta phải tự lực cánh sinh."},{"type":"simple","zh":"这个山村靠自力更生修通了公路。","pinyin":"Zhè ge shāncūn kào zìlìgēngshēng xiū tōngle gōnglù.","vi":"Ngôi làng miền núi này đã tự lực làm thông con đường."},{"type":"compound","zh":"父母去世后，他不但自力更生，而且供妹妹读完了大学。","pinyin":"Fùmǔ qùshì hòu, tā búdàn zìlìgēngshēng, érqiě gōng mèimei dú wánle dàxué.","vi":"Sau khi bố mẹ qua đời, anh ấy không chỉ tự lực cánh sinh mà còn nuôi em gái học hết đại học."}],"related":[{"hanzi":"自食其力","pinyin":"zìshíqílì","vi":"tự lực nuôi thân"},{"hanzi":"独立自主","pinyin":"dúlìzìzhǔ","vi":"độc lập tự chủ"},{"hanzi":"依赖","pinyin":"yīlài","vi":"ỷ lại"},{"hanzi":"白手起家","pinyin":"báishǒuqǐjiā","vi":"tay trắng làm nên"}]},{"id":"自强不息","hanzi":"自强不息","pinyin":"zìqiáng-bùxī","meaning_vi":"tự cường không ngừng nghỉ","explanation":"自强不息: tự mình (自) mạnh lên (强) không (不) ngừng nghỉ (息) (từ Kinh Dịch) → không ngừng nỗ lực vươn lên.","hsk_level":6,"tags":["thanh-ngu"],"image":"🦁","examples":[{"type":"basic","zh":"人要自强不息。","pinyin":"Rén yào zìqiángbùxī.","vi":"Con người phải không ngừng tự cường."},{"type":"simple","zh":"这位残疾运动员用自强不息的精神感动了大家。","pinyin":"Zhè wèi cánjí yùndòngyuán yòng zìqiángbùxī de jīngshén gǎndòngle dàjiā.","vi":"Vận động viên khuyết tật này đã làm mọi người cảm động bằng tinh thần tự cường không ngừng."},{"type":"compound","zh":"一个民族只有自强不息，才能屹立于世界之林。","pinyin":"Yí gè mínzú zhǐyǒu zìqiángbùxī, cáinéng yìlì yú shìjiè zhī lín.","vi":"Một dân tộc chỉ có không ngừng tự cường mới có thể đứng vững giữa các dân tộc trên thế giới."}],"related":[{"hanzi":"奋发图强","pinyin":"fènfātúqiáng","vi":"phấn đấu vươn lên"},{"hanzi":"坚持不懈","pinyin":"jiānchíbúxiè","vi":"kiên trì bền bỉ"},{"hanzi":"自强","pinyin":"zìqiáng","vi":"tự cường"},{"hanzi":"自暴自弃","pinyin":"zìbàozìqì","vi":"tự buông xuôi"}],"traditional":"自強不息"},{"id":"自相矛盾","hanzi":"自相矛盾","pinyin":"zìxiāng-máodùn","meaning_vi":"tự mâu thuẫn với chính mình","explanation":"自相矛盾: tự mình mâu (矛) thuẫn (盾) với nhau (truyện người nước Sở bán giáo và khiên, sách Hàn Phi Tử) → lời nói, hành động tự mâu thuẫn.","hsk_level":6,"tags":["thanh-ngu"],"image":"⚔️","examples":[{"type":"basic","zh":"你的话自相矛盾。","pinyin":"Nǐ dehuà zìxiāngmáodùn.","vi":"Lời bạn nói tự mâu thuẫn."},{"type":"simple","zh":"证人前后的说法明显自相矛盾。","pinyin":"Zhèngrén qiánhòu de shuōfǎ míngxiǎn zìxiāngmáodùn.","vi":"Lời khai trước sau của nhân chứng rõ ràng tự mâu thuẫn."},{"type":"compound","zh":"他一边说要减肥，一边又吃炸鸡，真是自相矛盾。","pinyin":"Tā yìbiān shuō yào jiǎnféi, yìbiān yòu chī zhájī, zhēn shì zìxiāngmáodùn.","vi":"Anh ấy vừa nói muốn giảm cân vừa ăn gà rán, thật là tự mâu thuẫn."}],"related":[{"hanzi":"矛盾","pinyin":"máodùn","vi":"mâu thuẫn"},{"hanzi":"前后矛盾","pinyin":"qiánhòumáodùn","vi":"trước sau mâu thuẫn"},{"hanzi":"自圆其说","pinyin":"zìyuánqíshuō","vi":"tự lý giải hợp lý"},{"hanzi":"似是而非","pinyin":"sìshì'érfēi","vi":"tưởng đúng mà sai"}]},{"id":"纵横","hanzi":"纵横","pinyin":"zònghéng","meaning_vi":"dọc ngang","explanation":"纵 (tung – dọc) + 横 (hoành – ngang) → dọc ngang chằng chịt; nghĩa bóng là tung hoành, tự do. Ví dụ: 河流纵横, 纵横交错, 老泪纵横.","hsk_level":6,"tags":["tinh-tu"],"image":"✚","examples":[{"type":"basic","zh":"这里河道纵横。","pinyin":"Zhèlǐ hédào zònghéng.","vi":"Ở đây sông ngòi chằng chịt."},{"type":"simple","zh":"老人满是皱纹的脸上泪水纵横。","pinyin":"Lǎorén mǎnshì zhòuwén de liǎn shang lèishuǐ zònghéng.","vi":"Trên khuôn mặt đầy nếp nhăn của ông lão, nước mắt chảy ràn rụa."},{"type":"compound","zh":"因为城市里的道路纵横交错，所以第一次来的人很容易迷路。","pinyin":"Yīnwèi chéngshì li de dàolù zònghéngjiāocuò, suǒyǐ dìyīcì lái de rén hěn róngyì mílù.","vi":"Vì đường sá trong thành phố chằng chịt nên người lần đầu đến rất dễ lạc."}],"related":[{"hanzi":"纵横交错","pinyin":"zònghéngjiāocuò","vi":"chằng chịt ngang dọc"},{"hanzi":"横竖","pinyin":"héngshù","vi":"ngang dọc"},{"hanzi":"纵向","pinyin":"zòngxiàng","vi":"chiều dọc"},{"hanzi":"横向","pinyin":"héngxiàng","vi":"chiều ngang"}],"traditional":"縱橫"},{"id":"族","hanzi":"族","pinyin":"zú","meaning_vi":"dân tộc; dòng họ, gia tộc; nhóm người, giới (cùng đặc điểm)","explanation":"族 (tộc): dòng họ, dân tộc; cũng chỉ nhóm người hay loài có chung đặc điểm. Ví dụ: 民族, 家族, 汉族, 上班族 (dân công sở).","hsk_level":6,"tags":["danh-tu","xa-hoi"],"image":"👥","examples":[{"type":"basic","zh":"他是蒙古族人。","pinyin":"Tā shì Měnggǔ zúrén.","vi":"Anh ấy là người dân tộc Mông Cổ."},{"type":"simple","zh":"汉族是中国人口最多的民族。","pinyin":"Hànzú shì Zhōngguó rénkǒu zuì duō de mínzú.","vi":"Dân tộc Hán là dân tộc đông dân nhất Trung Quốc."},{"type":"compound","zh":"虽然他是上班族，但是每天都坚持下班后学画画。","pinyin":"Suīrán tā shì shàngbānzú, dànshì měitiān dōu jiānchí xiàbān hòuxué huàhuà.","vi":"Tuy là dân văn phòng nhưng ngày nào anh ấy cũng kiên trì học vẽ sau giờ làm."}],"related":[{"hanzi":"民族","pinyin":"mínzú","vi":"dân tộc"},{"hanzi":"家族","pinyin":"jiāzú","vi":"gia tộc"},{"hanzi":"汉族","pinyin":"Hànzú","vi":"dân tộc Hán"},{"hanzi":"上班族","pinyin":"shàngbānzú","vi":"dân công sở"}]},{"id":"遭受","hanzi":"遭受","pinyin":"zāoshòu","meaning_vi":"gặp phải, chịu (bất hạnh, tổn thất)","explanation":"遭 (tao – gặp phải) + 受 (thụ – chịu) → gặp phải, phải chịu điều không may như tổn thất, đả kích. Ví dụ: 遭受损失, 遭受打击, 遭受灾害.","hsk_level":6,"tags":["dong-tu"],"image":"⚠️","examples":[{"type":"basic","zh":"庄稼遭受了水灾。","pinyin":"Zhuāngjia zāoshòule shuǐzāi.","vi":"Mùa màng bị lũ lụt tàn phá."},{"type":"simple","zh":"这家公司在金融危机中遭受了巨大损失。","pinyin":"Zhè jiā gōngsī zài jīnróngwēijī zhōng zāoshòule jùdà sǔnshī.","vi":"Công ty này chịu tổn thất to lớn trong khủng hoảng tài chính."},{"type":"compound","zh":"即使遭受了很多挫折，她也从来没想过放弃。","pinyin":"Jíshǐ zāoshòule hěn duō cuòzhé, tā yě cónglái méi xiǎngguo fàngqì.","vi":"Dù gặp phải nhiều thất bại, cô ấy chưa bao giờ nghĩ đến việc từ bỏ."}],"related":[{"hanzi":"遭到","pinyin":"zāodào","vi":"gặp phải"},{"hanzi":"遭遇","pinyin":"zāoyù","vi":"gặp phải"},{"hanzi":"受到","pinyin":"shòudào","vi":"chịu"},{"hanzi":"蒙受","pinyin":"méngshòu","vi":"chịu đựng"}]},{"id":"糟蹋","hanzi":"糟蹋","pinyin":"zāotà","meaning_vi":"lãng phí, phung phí; làm hỏng, hủy hoại","explanation":"糟 (tao – bã, hỏng) + 蹋 (đạp – giẫm) → làm hỏng, phí phạm; cũng nghĩa chà đạp, làm nhục. Ví dụ: 糟蹋粮食, 糟蹋身体.","hsk_level":6,"tags":["dong-tu"],"image":"🗑️","examples":[{"type":"basic","zh":"别糟蹋粮食。","pinyin":"Bié zāotà liángshi.","vi":"Đừng lãng phí lương thực."},{"type":"simple","zh":"孩子们把刚种的花都糟蹋了。","pinyin":"Háizimen bǎ gāng zhòng de Huādōu zāotà le.","vi":"Bọn trẻ đã phá nát hết chỗ hoa vừa trồng."},{"type":"compound","zh":"如果你天天熬夜，就是在糟蹋自己的身体。","pinyin":"Rúguǒ nǐ tiāntiān áoyè, jiùshì zài zāotà zìjǐ de shēntǐ.","vi":"Nếu ngày nào bạn cũng thức khuya là đang hủy hoại cơ thể mình."}],"related":[{"hanzi":"浪费","pinyin":"làngfèi","vi":"lãng phí"},{"hanzi":"破坏","pinyin":"pòhuài","vi":"phá hoại"},{"hanzi":"糟糕","pinyin":"zāogāo","vi":"tồi tệ"},{"hanzi":"珍惜","pinyin":"zhēnxī","vi":"trân trọng"}]},{"id":"资助","hanzi":"资助","pinyin":"zīzhù","meaning_vi":"tài trợ, giúp đỡ về tiền của","explanation":"资 (tư – tiền của) + 助 (trợ – giúp) → giúp đỡ bằng tiền của, tài trợ. Ví dụ: 资助贫困学生, 资助项目, 得到资助.","hsk_level":6,"tags":["dong-tu"],"image":"🎓","examples":[{"type":"basic","zh":"企业资助了贫困生。","pinyin":"Qǐyè zīzhùle pínkùn shēng.","vi":"Doanh nghiệp đã tài trợ cho học sinh nghèo."},{"type":"simple","zh":"这位老人每年都资助山区的十个孩子上学。","pinyin":"Zhè wèi lǎorén měinián dōu zīzhù shānqū de shí gè háizi shàngxué.","vi":"Ông cụ này mỗi năm đều tài trợ cho mười đứa trẻ vùng núi đi học."},{"type":"compound","zh":"要不是有基金会资助，我根本读不起大学。","pinyin":"Yàobúshì yǒu jījīnhuì zīzhù, wǒ gēnběn dú bu qǐ dàxué.","vi":"Nếu không có quỹ tài trợ, tôi hoàn toàn không đủ tiền học đại học."}],"related":[{"hanzi":"赞助","pinyin":"zànzhù","vi":"tài trợ"},{"hanzi":"捐助","pinyin":"juānzhù","vi":"quyên góp giúp đỡ"},{"hanzi":"资金","pinyin":"zījīn","vi":"tiền vốn"},{"hanzi":"援助","pinyin":"yuánzhù","vi":"viện trợ"}],"traditional":"資助"},{"id":"宗旨","hanzi":"宗旨","pinyin":"zōngzhǐ","meaning_vi":"tôn chỉ","explanation":"宗 (tông – gốc, chủ) + 旨 (chỉ – ý chỉ) → mục đích, ý định chủ yếu của một tổ chức. Ví dụ: 本会宗旨, 以服务为宗旨.","hsk_level":6,"tags":["danh-tu"],"image":"🎯","examples":[{"type":"basic","zh":"顾客至上是我们的宗旨。","pinyin":"Gùkè zhìshàng shì wǒmen de zōngzhǐ.","vi":"Khách hàng là trên hết là tôn chỉ của chúng tôi."},{"type":"simple","zh":"这个协会的宗旨是保护野生动物。","pinyin":"Zhè ge xiéhuì de zōngzhǐ shì bǎohù yěshēng dòngwù.","vi":"Tôn chỉ của hiệp hội này là bảo vệ động vật hoang dã."},{"type":"compound","zh":"既然学校的宗旨是培养人才，就不应该只看分数。","pinyin":"Jìrán xuéxiào de zōngzhǐ shì péiyǎng réncái, jiù bù yīnggāi zhǐ kàn fēnshù.","vi":"Tôn chỉ của nhà trường đã là đào tạo nhân tài thì không nên chỉ nhìn vào điểm số."}],"related":[{"hanzi":"目的","pinyin":"mùdì","vi":"mục đích"},{"hanzi":"原则","pinyin":"yuánzé","vi":"nguyên tắc"},{"hanzi":"理念","pinyin":"lǐniàn","vi":"triết lý"},{"hanzi":"方针","pinyin":"fāngzhēn","vi":"phương châm"}]},{"id":"尊严","hanzi":"尊严","pinyin":"zūnyán","meaning_vi":"phẩm giá, lòng tự tôn; tôn nghiêm","explanation":"尊 (tôn – kính) + 严 (nghiêm – nghiêm) → phẩm giá, danh dự không thể xâm phạm. Ví dụ: 人格尊严, 维护尊严, 失去尊严.","hsk_level":6,"tags":["danh-tu"],"image":"👑","examples":[{"type":"basic","zh":"人人都有尊严。","pinyin":"Rénrén dōu yǒu zūnyán.","vi":"Ai cũng có phẩm giá."},{"type":"simple","zh":"这位老人靠捡废品有尊严地生活着。","pinyin":"Zhè wèi lǎorén kào jiǎn fèipǐn yǒu zūnyán de shēnghuó zhe.","vi":"Ông cụ này sống có phẩm giá nhờ nhặt phế liệu."},{"type":"compound","zh":"他宁可饿肚子，也不愿意为了钱失去尊严。","pinyin":"Tā nìngkě èdùzi, yě bú yuànyì wèile qián shīqù zūnyán.","vi":"Anh ấy thà nhịn đói chứ không muốn vì tiền mà đánh mất phẩm giá."}],"related":[{"hanzi":"尊重","pinyin":"zūnzhòng","vi":"tôn trọng"},{"hanzi":"自尊","pinyin":"zìzūn","vi":"lòng tự trọng"},{"hanzi":"人格","pinyin":"réngé","vi":"nhân cách"},{"hanzi":"面子","pinyin":"miànzi","vi":"thể diện"}],"traditional":"尊嚴"},{"id":"咋","hanzi":"咋","pinyin":"zǎ","meaning_vi":"sao, thế nào","explanation":"咋 (trá): khẩu ngữ phương Bắc, nghĩa là sao, thế nào. Ví dụ: 咋办 (làm sao bây giờ), 咋了 (sao thế), 你咋不去.","hsk_level":6,"tags":["dai-tu"],"image":"❓","examples":[{"type":"basic","zh":"你咋不说话？","pinyin":"Nǐ zǎ bù shuōhuà?","vi":"Sao bạn không nói gì?"},{"type":"simple","zh":"这台旧电视咋又打不开了？","pinyin":"Zhè tái jiù diànshì zǎ yòu dǎ bu kāi le?","vi":"Cái tivi cũ này sao lại không bật được nữa?"},{"type":"compound","zh":"你要是身体不舒服，咋不早点告诉我呢？","pinyin":"Nǐ yàoshi shēntǐ bù shūfu, zǎ bù zǎodiǎn gàosu wǒ ne?","vi":"Nếu bạn không khỏe, sao không nói với tôi sớm hơn?"}],"related":[{"hanzi":"怎么","pinyin":"zěnme","vi":"thế nào"},{"hanzi":"咋办","pinyin":"zǎbàn","vi":"làm sao đây"},{"hanzi":"咋样","pinyin":"zǎyàng","vi":"ra sao"},{"hanzi":"为什么","pinyin":"wèishénme","vi":"tại sao"}]},{"id":"宰","hanzi":"宰","pinyin":"zǎi","meaning_vi":"mổ, giết thịt; chặt chém, hét giá (khách)","explanation":"宰 (tể): giết mổ gia súc; nghĩa gốc là cai quản (宰相 – tể tướng); khẩu ngữ còn nghĩa chặt chém khách. Ví dụ: 宰猪, 被宰了.","hsk_level":6,"tags":["dong-tu"],"image":"🔪","examples":[{"type":"basic","zh":"农民在宰猪。","pinyin":"Nóngmín zài zǎi zhū.","vi":"Người nông dân đang mổ lợn."},{"type":"simple","zh":"过年前，爷爷宰了家里最肥的一只鸡。","pinyin":"Guò niánqián, yéye zǎile jiāli zuì féi de yì zhī jī.","vi":"Trước Tết, ông nội làm thịt con gà béo nhất nhà."},{"type":"compound","zh":"因为景区的饭菜太贵，所以游客都觉得被宰了。","pinyin":"Yīnwèi jǐngqū de fàncài tài guì, suǒyǐ yóukè dōu juéde bèi zǎile.","vi":"Vì đồ ăn trong khu du lịch quá đắt nên du khách đều thấy mình bị chặt chém."}],"related":[{"hanzi":"宰杀","pinyin":"zǎishā","vi":"giết mổ"},{"hanzi":"屠宰","pinyin":"túzǎi","vi":"mổ thịt"},{"hanzi":"杀","pinyin":"shā","vi":"giết"},{"hanzi":"宰客","pinyin":"zǎikè","vi":"chặt chém khách"}]},{"id":"攒","hanzi":"攒","pinyin":"zǎn","meaning_vi":"tích góp","explanation":"攒 (toàn): tích góp, dành dụm dần. Ví dụ: 攒钱 (để dành tiền), 攒经验; đọc cuán nghĩa là tụ lại, ghép lại.","hsk_level":6,"tags":["dong-tu"],"image":"💰","examples":[{"type":"basic","zh":"我在攒钱买车。","pinyin":"Wǒ zài zǎnqián mǎi chē.","vi":"Tôi đang dành dụm tiền mua xe."},{"type":"simple","zh":"她攒了三年的工资才付得起首付。","pinyin":"Tā zǎnle sān nián de gōngzī cái fù deqǐ shǒufù.","vi":"Cô ấy dành dụm lương ba năm mới đủ tiền trả trước khi mua nhà."},{"type":"compound","zh":"只要每个月攒一些，一年后就能去旅行了。","pinyin":"Zhǐyào měi gèyuè zǎn yìxiē, yì nián hòu jiù néng qù lǚxíng le.","vi":"Chỉ cần mỗi tháng dành dụm một ít, một năm sau là có thể đi du lịch."}],"related":[{"hanzi":"积攒","pinyin":"jīzǎn","vi":"tích lũy"},{"hanzi":"攒钱","pinyin":"zǎnqián","vi":"dành dụm tiền"},{"hanzi":"存钱","pinyin":"cúnqián","vi":"tiết kiệm tiền"},{"hanzi":"积累","pinyin":"jīlěi","vi":"tích lũy"}],"traditional":"攢"},{"id":"子弹","hanzi":"子弹","pinyin":"zǐdàn","meaning_vi":"viên đạn","explanation":"子 (tử – vật nhỏ) + 弹 (đạn – viên đạn) → viên đạn bắn ra từ súng. Ví dụ: 一颗子弹, 子弹头; 弹 ở đây đọc dàn.","hsk_level":6,"tags":["danh-tu","do-vat"],"image":"🔫","examples":[{"type":"basic","zh":"枪里没有子弹。","pinyin":"Qiāng li méiyǒu zǐdàn.","vi":"Trong súng không có đạn."},{"type":"simple","zh":"一颗子弹擦着他的耳朵飞了过去。","pinyin":"Yì kē zǐdàn cāzhe tā de ěrduo fēile guòqu.","vi":"Một viên đạn bay sượt qua tai anh ấy."},{"type":"compound","zh":"虽然子弹打中了他的腿，但是他仍然坚持战斗。","pinyin":"Suīrán zǐdàn dǎzhòngle tā de tuǐ, dànshì tā réngrán jiānchí zhàndòu.","vi":"Tuy bị đạn bắn trúng chân nhưng anh ấy vẫn kiên trì chiến đấu."}],"related":[{"hanzi":"枪","pinyin":"qiāng","vi":"súng"},{"hanzi":"炮弹","pinyin":"pàodàn","vi":"đạn pháo"},{"hanzi":"武器","pinyin":"wǔqì","vi":"vũ khí"},{"hanzi":"弹药","pinyin":"dànyào","vi":"đạn dược"}],"traditional":"子彈"},{"id":"走马观花","hanzi":"走马观花","pinyin":"zǒumǎ-guānhuā","meaning_vi":"cưỡi ngựa xem hoa (xem qua loa đại khái)","explanation":"走马观花: cưỡi ngựa (走马) xem hoa (观花) → xem xét qua loa, đại khái, không đi sâu. Ví dụ: 走马观花地参观.","hsk_level":6,"tags":["thanh-ngu"],"image":"🐎","examples":[{"type":"basic","zh":"我们只是走马观花。","pinyin":"Wǒmen zhǐshì zǒumǎguānhuā.","vi":"Chúng tôi chỉ xem qua loa thôi."},{"type":"simple","zh":"跟团游往往只能走马观花地看看景点。","pinyin":"Gēn tuán yóu wǎngwǎng zhǐnéng zǒumǎguānhuā de kànkan jǐngdiǎn.","vi":"Đi du lịch theo đoàn thường chỉ có thể cưỡi ngựa xem hoa các điểm tham quan."},{"type":"compound","zh":"与其走马观花地去十个城市，不如深入了解一个地方。","pinyin":"Yǔqí zǒumǎguānhuā de qù shí gè chéngshì, bùrú shēnrù liǎojiě yí gè dìfang.","vi":"Thay vì cưỡi ngựa xem hoa mười thành phố, chi bằng tìm hiểu sâu một nơi."}],"related":[{"hanzi":"浮光掠影","pinyin":"fúguānglüèyǐng","vi":"qua loa hời hợt"},{"hanzi":"粗略","pinyin":"cūlüè","vi":"sơ lược"},{"hanzi":"走过场","pinyin":"zǒuguòchǎng","vi":"làm cho có"},{"hanzi":"仔细","pinyin":"zǐxì","vi":"tỉ mỉ"}],"traditional":"走馬觀花"},{"id":"走私","hanzi":"走私","pinyin":"zǒusī","meaning_vi":"buôn lậu","explanation":"走 (tẩu – đi) + 私 (tư – riêng, lén) → vận chuyển hàng hóa trốn thuế, trái phép qua biên giới, buôn lậu. Ví dụ: 走私货物, 打击走私.","hsk_level":6,"tags":["dong-tu"],"image":"🚨","examples":[{"type":"basic","zh":"他因走私被捕。","pinyin":"Tā yīn zǒusī bèibǔ.","vi":"Anh ta bị bắt vì buôn lậu."},{"type":"simple","zh":"海关查获了一批走私的象牙。","pinyin":"Hǎiguān cháhuòle yìpī zǒusī de xiàngyá.","vi":"Hải quan thu giữ một lô ngà voi buôn lậu."},{"type":"compound","zh":"一旦被发现走私毒品，就会受到法律的严惩。","pinyin":"Yídàn bèi fāxiàn zǒusī dúpǐn, jiù huì shòudào fǎlǜ de yánchéng.","vi":"Một khi bị phát hiện buôn lậu ma túy sẽ bị pháp luật trừng trị nghiêm khắc."}],"related":[{"hanzi":"走私犯","pinyin":"zǒusīfàn","vi":"kẻ buôn lậu"},{"hanzi":"偷运","pinyin":"tōuyùn","vi":"vận chuyển lén"},{"hanzi":"海关","pinyin":"hǎiguān","vi":"hải quan"},{"hanzi":"违法","pinyin":"wéifǎ","vi":"phạm pháp"}]},{"id":"祖父","hanzi":"祖父","pinyin":"zǔfù","meaning_vi":"ông nội","explanation":"祖 (tổ – ông bà) + 父 (phụ – cha) → ông nội (cha của cha). Văn viết, khẩu ngữ dùng 爷爷; ông ngoại là 外祖父.","hsk_level":6,"tags":["danh-tu","gia-dinh"],"image":"👴","examples":[{"type":"basic","zh":"我的祖父是医生。","pinyin":"Wǒ de zǔfù shì yīshēng.","vi":"Ông nội tôi là bác sĩ."},{"type":"simple","zh":"这块老怀表是祖父留给我的。","pinyin":"Zhè kuài lǎo huáibiǎo shì zǔfù liúgěi wǒ de.","vi":"Chiếc đồng hồ quả quýt cũ này là ông nội để lại cho tôi."},{"type":"compound","zh":"祖父虽然已经九十岁了，但是每天还坚持写毛笔字。","pinyin":"Zǔfù suīrán yǐjīng jiǔshí suì le, dànshì měitiān hái jiānchí xiě máobǐ zì.","vi":"Ông nội tuy đã chín mươi tuổi nhưng hằng ngày vẫn kiên trì viết thư pháp."}],"related":[{"hanzi":"爷爷","pinyin":"yéye","vi":"ông nội"},{"hanzi":"祖母","pinyin":"zǔmǔ","vi":"bà nội"},{"hanzi":"外祖父","pinyin":"wàizǔfù","vi":"ông ngoại"},{"hanzi":"祖先","pinyin":"zǔxiān","vi":"tổ tiên"}]},{"id":"爱理不理","hanzi":"爱理不理","pinyin":"àilǐ-bulǐ","meaning_vi":"lạnh nhạt, hờ hững, chẳng thèm để ý","explanation":"Cấu trúc A不A biểu thị thái độ thờ ơ.","hsk_level":6,"tags":["thanh-ngu","giao-tiep"],"image":"😒","examples":[{"type":"basic","zh":"她对我爱理不理。","pinyin":"Tā duì wǒ àilǐbulǐ.","vi":"Cô ấy đối với tôi lạnh nhạt, hờ hững."},{"type":"simple","zh":"那家店的店员对顾客总是爱理不理的。","pinyin":"Nà jiā diàn de diànyuán duì gùkè zǒngshì àilǐbulǐ de.","vi":"Nhân viên cửa hàng đó lúc nào cũng hờ hững với khách."},{"type":"compound","zh":"如果你对别人爱理不理，别人也不会热情地对你。","pinyin":"Rúguǒ nǐ duì biérén àilǐbulǐ, biérén yě bú huì rèqíng de duì nǐ.","vi":"Nếu bạn hờ hững với người khác, người khác cũng sẽ không nhiệt tình với bạn."}],"related":[{"hanzi":"冷淡","pinyin":"lěngdàn","vi":"lạnh nhạt"},{"hanzi":"冷漠","pinyin":"lěngmò","vi":"thờ ơ"},{"hanzi":"不理不睬","pinyin":"bùlǐbùcǎi","vi":"mặc kệ không đoái hoài"},{"hanzi":"热情","pinyin":"rèqíng","vi":"nhiệt tình"}],"traditional":"愛理不理"},{"id":"暧昧","hanzi":"暧昧","pinyin":"àimèi","meaning_vi":"mập mờ, ám muội","explanation":"暧 (ái – mờ tối) + 昧 (muội – tối) → mập mờ, không rõ ràng; thường chỉ quan hệ nam nữ không rõ ràng. Ví dụ: 态度暧昧, 暧昧关系.","hsk_level":6,"tags":["tinh-tu"],"image":"🤫","examples":[{"type":"basic","zh":"他们关系很暧昧。","pinyin":"Tāmen guānxi hěn àimèi.","vi":"Quan hệ của họ rất mập mờ."},{"type":"simple","zh":"发言人对这个问题的回答十分暧昧。","pinyin":"Fāyánrén duì zhè ge wèntí de huídá shífēn àimèi.","vi":"Câu trả lời của người phát ngôn về vấn đề này rất mập mờ."},{"type":"compound","zh":"既然你不喜欢他，就别再和他保持暧昧了。","pinyin":"Jìrán nǐ bù xǐhuan tā, jiù bié zài hé tā bǎochí àimèi le.","vi":"Bạn đã không thích anh ta thì đừng giữ mối quan hệ mập mờ với anh ta nữa."}],"related":[{"hanzi":"含糊","pinyin":"hánhu","vi":"mơ hồ"},{"hanzi":"不清不楚","pinyin":"bùqīngbùchǔ","vi":"không rõ ràng"},{"hanzi":"模糊","pinyin":"móhu","vi":"mập mờ"},{"hanzi":"明确","pinyin":"míngquè","vi":"rõ ràng"}],"traditional":"曖昧"},{"id":"爱莫能助","hanzi":"爱莫能助","pinyin":"àimò-néngzhù","meaning_vi":"lực bất tòng tâm (muốn giúp nhưng không giúp được)","explanation":"爱 (yêu quý) + 莫能助 (không thể giúp). Thành ngữ.","hsk_level":6,"tags":["thanh-ngu"],"image":"🤷","examples":[{"type":"basic","zh":"对不起，我爱莫能助。","pinyin":"Duìbuqǐ, wǒ àimònéngzhù.","vi":"Xin lỗi, tôi lực bất tòng tâm."},{"type":"simple","zh":"面对朋友的请求，他实在爱莫能助。","pinyin":"Miànduì péngyou de qǐngqiú, tā shízài àimònéngzhù.","vi":"Trước lời nhờ vả của bạn, anh ấy thật sự lực bất tòng tâm."},{"type":"compound","zh":"虽然我很同情你的遭遇，但是这件事我真的爱莫能助。","pinyin":"Suīrán wǒ hěn tóngqíng nǐ de zāoyù, dànshì zhè jiàn shì wǒ zhēn de àimònéngzhù.","vi":"Tuy tôi rất thông cảm với cảnh ngộ của bạn nhưng việc này tôi thật sự lực bất tòng tâm."}],"related":[{"hanzi":"无能为力","pinyin":"wúnéngwéilì","vi":"bất lực"},{"hanzi":"力不从心","pinyin":"lìbùcóngxīn","vi":"lực bất tòng tâm"},{"hanzi":"无可奈何","pinyin":"wúkěnàihé","vi":"đành chịu"},{"hanzi":"帮助","pinyin":"bāngzhù","vi":"giúp đỡ"}],"traditional":"愛莫能助"},{"id":"案例","hanzi":"案例","pinyin":"ànlì","meaning_vi":"trường hợp điển hình, ví dụ thực tế","explanation":"案 + 例 (ví dụ).","hsk_level":6,"tags":["danh-tu","cong-viec"],"image":"📋","examples":[{"type":"basic","zh":"这是一个典型案例。","pinyin":"Zhè shì yí gè diǎnxíng ànlì.","vi":"Đây là một trường hợp điển hình."},{"type":"simple","zh":"老师在课上分析了几个真实的法律案例。","pinyin":"Lǎoshī zài kè shang fēnxīle jǐ gè zhēnshí de fǎlǜ ànlì.","vi":"Thầy giáo phân tích vài vụ việc pháp lý có thật trong giờ học."},{"type":"compound","zh":"因为有成功的案例可以参考，所以这个方案很快就通过了。","pinyin":"Yīnwèi yǒu chénggōng de ànlì kěyǐ cānkǎo, suǒyǐ zhè ge fāng'àn hěn kuài jiù tōngguò le.","vi":"Vì có trường hợp thành công để tham khảo nên phương án này nhanh chóng được thông qua."}],"related":[{"hanzi":"例子","pinyin":"lìzi","vi":"ví dụ"},{"hanzi":"实例","pinyin":"shílì","vi":"thực tế ví dụ"},{"hanzi":"典型","pinyin":"diǎnxíng","vi":"điển hình"},{"hanzi":"案件","pinyin":"ànjiàn","vi":"vụ án"}]},{"id":"暗杀","hanzi":"暗杀","pinyin":"ànshā","meaning_vi":"ám sát","explanation":"暗 (ngầm/bí mật) + 杀 (giết).","hsk_level":6,"tags":["dong-tu","phap-luat"],"image":"🗡️","examples":[{"type":"basic","zh":"总统遭到暗杀。","pinyin":"Zǒngtǒng zāodào ànshā.","vi":"Tổng thống bị ám sát."},{"type":"simple","zh":"警方成功阻止了一起针对市长的暗杀。","pinyin":"Jǐngfāng chénggōng zǔzhǐle yìqǐ zhēnduì shìzhǎng de ànshā.","vi":"Cảnh sát đã ngăn chặn thành công một vụ ám sát nhắm vào thị trưởng."},{"type":"compound","zh":"如果没有保镖保护，这位记者早就被暗杀了。","pinyin":"Rúguǒ méiyǒu bǎobiāo bǎohù, zhè wèi jìzhě zǎojiù bèi ànshā le.","vi":"Nếu không có vệ sĩ bảo vệ, nhà báo này đã bị ám sát từ lâu."}],"related":[{"hanzi":"谋杀","pinyin":"móushā","vi":"mưu sát"},{"hanzi":"刺杀","pinyin":"cìshā","vi":"hành thích"},{"hanzi":"杀害","pinyin":"shāhài","vi":"sát hại"},{"hanzi":"暗中","pinyin":"ànzhōng","vi":"ngấm ngầm"}],"traditional":"暗殺"},{"id":"暗中","hanzi":"暗中","pinyin":"ànzhōng","meaning_vi":"ngấm ngầm, bí mật, trong bóng tối","explanation":"暗 (ám – tối) + 中 (trung – trong) → trong bóng tối; ngấm ngầm, lén lút. Cụm: 暗中帮助, 暗中调查.","hsk_level":6,"tags":["pho-tu"],"image":"🤫","examples":[{"type":"basic","zh":"他暗中帮助我。","pinyin":"Tā ànzhōng bāngzhù wǒ.","vi":"Anh ấy ngấm ngầm giúp tôi."},{"type":"simple","zh":"警察在暗中调查这家公司的账目。","pinyin":"Jǐngchá zài ànzhōng diàochá zhè jiā gōngsī de zhàngmù.","vi":"Cảnh sát đang bí mật điều tra sổ sách của công ty này."},{"type":"compound","zh":"虽然表面上他们不说话，但是暗中一直在较劲。","pinyin":"Suīrán biǎomiànshang tāmen bù shuōhuà, dànshì ànzhōng yìzhí zài jiàojìn.","vi":"Tuy bề ngoài họ không nói chuyện với nhau nhưng ngấm ngầm vẫn luôn ganh đua."}],"related":[{"hanzi":"秘密","pinyin":"mìmì","vi":"bí mật"},{"hanzi":"偷偷","pinyin":"tōutōu","vi":"lén lút"},{"hanzi":"背地里","pinyin":"bèidìli","vi":"sau lưng"},{"hanzi":"公开","pinyin":"gōngkāi","vi":"công khai"}]},{"id":"奥林匹克","hanzi":"奥林匹克","pinyin":"Àolínpǐkè","meaning_vi":"Olympic, Thế vận hội","explanation":"Từ phiên âm tiếng Anh 'Olympic'.","hsk_level":6,"tags":["danh-tu","the-thao","van-hoa"],"image":"🏅","examples":[{"type":"basic","zh":"奥林匹克起源于希腊。","pinyin":"Àolínpǐkè qǐ yuányú Xīlà.","vi":"Olympic khởi nguồn từ Hy Lạp."},{"type":"simple","zh":"奥林匹克精神鼓励人们更快、更高、更强。","pinyin":"Àolínpǐkè jīngshén gǔlì rénmen gèng kuài, gèng gāo, gèng qiáng.","vi":"Tinh thần Olympic khuyến khích con người nhanh hơn, cao hơn, mạnh hơn."},{"type":"compound","zh":"只要坚持训练，你就有机会参加奥林匹克数学竞赛。","pinyin":"Zhǐyào jiānchí xùnliàn, nǐ jiù yǒujī huì cānjiā Àolínpǐkè shùxué jìngsài.","vi":"Chỉ cần kiên trì luyện tập, bạn sẽ có cơ hội tham gia kỳ thi Olympic Toán."}],"related":[{"hanzi":"奥运会","pinyin":"Àoyùnhuì","vi":"Thế vận hội"},{"hanzi":"奥林匹克运动会","pinyin":"Àolínpǐkè Yùndònghuì","vi":"Thế vận hội Olympic"},{"hanzi":"金牌","pinyin":"jīnpái","vi":"huy chương vàng"},{"hanzi":"运动员","pinyin":"yùndòngyuán","vi":"vận động viên"}],"traditional":"奧林匹克"},{"id":"奥林匹克运动会","hanzi":"奥林匹克运动会","pinyin":"Àolínpǐkè Yùndònghuì","meaning_vi":"Thế vận hội Olympic","explanation":"Tên đầy đủ của Thế vận hội.","hsk_level":6,"tags":["danh-tu","the-thao"],"image":"🏅","examples":[{"type":"basic","zh":"他去看奥林匹克运动会。","pinyin":"Tā qù kàn Àolínpǐkèyùndònghuì.","vi":"Anh ấy đi xem Thế vận hội Olympic."},{"type":"simple","zh":"第一届现代奥林匹克运动会在雅典举行。","pinyin":"Dìyījiè xiàndài Àolínpǐkèyùndònghuì zài Yǎdiǎn jǔxíng.","vi":"Thế vận hội Olympic hiện đại đầu tiên được tổ chức tại Athens."},{"type":"compound","zh":"因为奥林匹克运动会每四年才举行一次，所以运动员都非常珍惜机会。","pinyin":"Yīnwèi Àolínpǐkèyùndònghuì měi sì nián cái jǔxíng yí cì, suǒyǐ yùndòngyuán dōu fēicháng zhēnxī jīhuì.","vi":"Vì Thế vận hội Olympic bốn năm mới tổ chức một lần nên các vận động viên đều rất trân trọng cơ hội."}],"related":[{"hanzi":"奥运会","pinyin":"Àoyùnhuì","vi":"Thế vận hội"},{"hanzi":"奥林匹克","pinyin":"Àolínpǐkè","vi":"Olympic"},{"hanzi":"冬奥会","pinyin":"Dōng'àohuì","vi":"Thế vận hội mùa đông"},{"hanzi":"圣火","pinyin":"shènghuǒ","vi":"ngọn đuốc thiêng"}],"traditional":"奧林匹克運動會"},{"id":"奥妙","hanzi":"奥妙","pinyin":"àomiào","meaning_vi":"kỳ diệu, huyền bí, bí quyết sâu xa","explanation":"奥 (sâu xa) + 妙 (tinh diệu).","hsk_level":6,"tags":["tinh-tu","danh-tu"],"image":"🔮","examples":[{"type":"basic","zh":"大自然真奥妙。","pinyin":"Dàzìrán zhēn àomiào.","vi":"Thiên nhiên thật kỳ diệu."},{"type":"simple","zh":"他终于弄明白了这个魔术的奥妙。","pinyin":"Tā zhōngyú nòngmíngbaile zhè ge móshù de àomiào.","vi":"Cuối cùng anh ấy đã hiểu ra bí quyết của trò ảo thuật này."},{"type":"compound","zh":"围棋看起来简单，但是其中的奥妙无穷无尽。","pinyin":"Wéiqí kànqǐlái jiǎndān, dànshì qízhōng de àomiào wúqióngwújìn.","vi":"Cờ vây trông có vẻ đơn giản nhưng ẩn chứa vô vàn điều huyền diệu."}],"related":[{"hanzi":"奥秘","pinyin":"àomì","vi":"bí ẩn"},{"hanzi":"神秘","pinyin":"shénmì","vi":"thần bí"},{"hanzi":"玄妙","pinyin":"xuánmiào","vi":"huyền diệu"},{"hanzi":"秘诀","pinyin":"mìjué","vi":"bí quyết"}],"traditional":"奧妙"},{"id":"傲慢","hanzi":"傲慢","pinyin":"àomàn","meaning_vi":"ngạo mạn, kiêu căng","explanation":"傲 (kiêu ngạo) + 慢 (khinh mạn).","hsk_level":6,"tags":["tinh-tu","con-nguoi"],"image":"😤","examples":[{"type":"basic","zh":"他态度很傲慢。","pinyin":"Tā tàidù hěn àomàn.","vi":"Thái độ của anh ta rất ngạo mạn."},{"type":"simple","zh":"那个经理用傲慢的语气跟员工说话。","pinyin":"Nà ge jīnglǐ yòng àomàn de yǔqì gēn yuángōng shuōhuà.","vi":"Viên giám đốc đó nói chuyện với nhân viên bằng giọng kiêu căng."},{"type":"compound","zh":"即使你能力很强，也不应该对别人这么傲慢。","pinyin":"Jíshǐ nǐ nénglì hěn qiáng, yě bù yīnggāi duì biérén zhème àomàn.","vi":"Dù bạn có năng lực giỏi cũng không nên ngạo mạn với người khác như vậy."}],"related":[{"hanzi":"骄傲","pinyin":"jiāo'ào","vi":"kiêu ngạo"},{"hanzi":"自大","pinyin":"zìdà","vi":"tự cao"},{"hanzi":"傲慢无礼","pinyin":"àomànwúlǐ","vi":"ngạo mạn vô lễ"},{"hanzi":"谦虚","pinyin":"qiānxū","vi":"khiêm tốn"}]},{"id":"癌症","hanzi":"癌症","pinyin":"áizhèng","meaning_vi":"bệnh ung thư","explanation":"癌 (ung thư) + 症 (chứng bệnh).","hsk_level":6,"tags":["danh-tu","suc-khoe"],"image":"🏥","examples":[{"type":"basic","zh":"他得了癌症。","pinyin":"Tā déle áizhèng.","vi":"Ông ấy bị ung thư."},{"type":"simple","zh":"长期吸烟会增加患癌症的风险。","pinyin":"Chángqī xīyān huì zēngjiā huàn áizhèng de fēngxiǎn.","vi":"Hút thuốc lâu dài làm tăng nguy cơ mắc bệnh ung thư."},{"type":"compound","zh":"如果癌症能早期发现，治愈的可能性就大很多。","pinyin":"Rúguǒ áizhèng néng zǎoqī fāxiàn, zhìyù de kěnéngxìng jiù dà hěn duō.","vi":"Nếu ung thư được phát hiện sớm, khả năng chữa khỏi sẽ cao hơn nhiều."}],"related":[{"hanzi":"癌","pinyin":"ái","vi":"ung thư"},{"hanzi":"肿瘤","pinyin":"zhǒngliú","vi":"khối u"},{"hanzi":"化疗","pinyin":"huàliáo","vi":"hóa trị"},{"hanzi":"绝症","pinyin":"juézhèng","vi":"bệnh nan y"}]},{"id":"昂首","hanzi":"昂首","pinyin":"ángshǒu","meaning_vi":"ngẩng cao đầu","explanation":"昂 (ngẩng cao) + 首 (đầu).","hsk_level":6,"tags":["dong-tu"],"image":"🦁","examples":[{"type":"basic","zh":"骏马昂首嘶鸣。","pinyin":"Jùnmǎ ángshǒu sīmíng.","vi":"Con tuấn mã ngẩng đầu hí vang."},{"type":"simple","zh":"公鸡站在墙头上昂首啼叫。","pinyin":"Gōngjī zhàn zài qiáng tóushang ángshǒu tí jiào.","vi":"Con gà trống đứng trên đầu tường ngẩng cao đầu gáy."},{"type":"compound","zh":"他虽然输了比赛，但是依然昂首走下了赛场。","pinyin":"Tā suīrán shūle bǐsài, dànshì yīrán ángshǒu zǒu xiàle sàichǎng.","vi":"Tuy thua trận nhưng anh ấy vẫn ngẩng cao đầu bước ra khỏi sân đấu."}],"related":[{"hanzi":"昂首挺胸","pinyin":"ángshǒutǐngxiōng","vi":"ngẩng đầu ưỡn ngực"},{"hanzi":"抬头","pinyin":"táitóu","vi":"ngẩng đầu"},{"hanzi":"低头","pinyin":"dītóu","vi":"cúi đầu"},{"hanzi":"昂扬","pinyin":"ángyáng","vi":"sôi nổi"}]},{"id":"昂首挺胸","hanzi":"昂首挺胸","pinyin":"ángshǒu-tǐngxiōng","meaning_vi":"ngẩng cao đầu ưỡn ngực (hiên ngang tự tin)","explanation":"昂首 (ngẩng đầu) + 挺胸 (ưỡn ngực). Thành ngữ.","hsk_level":6,"tags":["thanh-ngu"],"image":"🦁","examples":[{"type":"basic","zh":"士兵们昂首挺胸。","pinyin":"Shìbīngmen ángshǒutǐngxiōng.","vi":"Binh lính ngẩng cao đầu, ưỡn ngực."},{"type":"simple","zh":"毕业生们昂首挺胸地走上了领奖台。","pinyin":"Bìyèshēngmen ángshǒutǐngxiōng de zǒushangle lǐngjiǎngtái.","vi":"Các sinh viên tốt nghiệp hiên ngang bước lên bục nhận thưởng."},{"type":"compound","zh":"只要你问心无愧，就可以昂首挺胸地面对别人。","pinyin":"Zhǐyào nǐ wènxīnwúkuì, jiù kěyǐ ángshǒutǐngxiōng de miànduì biérén.","vi":"Chỉ cần không hổ thẹn với lương tâm, bạn có thể ngẩng cao đầu đối mặt với người khác."}],"related":[{"hanzi":"昂首","pinyin":"ángshǒu","vi":"ngẩng cao đầu"},{"hanzi":"抬头挺胸","pinyin":"táitóutǐngxiōng","vi":"ngẩng đầu ưỡn ngực"},{"hanzi":"自信","pinyin":"zìxìn","vi":"tự tin"},{"hanzi":"垂头丧气","pinyin":"chuítóusàngqì","vi":"ủ rũ cúi đầu"}]},{"id":"昂扬","hanzi":"昂扬","pinyin":"ángyáng","meaning_vi":"sôi nổi, hào hứng (tinh thần)","explanation":"昂 (cao) + 扬 (nêu cao).","hsk_level":6,"tags":["tinh-tu"],"image":"🔥","examples":[{"type":"basic","zh":"大家斗志昂扬。","pinyin":"Dàjiā dòuzhì ángyáng.","vi":"Mọi người khí thế hừng hực."},{"type":"simple","zh":"运动员们以昂扬的精神进入了决赛场地。","pinyin":"Yùndòngyuánmen yǐ ángyáng de jīngshén jìnrùle juésài chǎngdì.","vi":"Các vận động viên bước vào sân chung kết với tinh thần hăng hái."},{"type":"compound","zh":"虽然连续输了两场，但是队员们的士气依然昂扬。","pinyin":"Suīrán liánxù shūle liǎng chǎng, dànshì duìyuánmen de shìqì yīrán ángyáng.","vi":"Tuy thua liền hai trận nhưng sĩ khí của các cầu thủ vẫn hăng hái."}],"related":[{"hanzi":"高昂","pinyin":"gāo'áng","vi":"dâng cao"},{"hanzi":"斗志昂扬","pinyin":"dòuzhì'ángyáng","vi":"ý chí chiến đấu sục sôi"},{"hanzi":"激昂","pinyin":"jī'áng","vi":"kích động hăng hái"},{"hanzi":"低沉","pinyin":"dīchén","vi":"trầm buồn"}],"traditional":"昂揚"},{"id":"熬煎","hanzi":"熬煎","pinyin":"áojiān","meaning_vi":"dày vò, chịu đựng khổ sở","explanation":"熬 (ngao – ninh lâu, chịu đựng) + 煎 (tiên – rán) → như bị ninh, bị rán; chịu đày đọa, đau khổ giày vò.","hsk_level":6,"tags":["dong-tu","cam-xuc"],"image":"😣","examples":[{"type":"basic","zh":"他饱受病痛熬煎。","pinyin":"Tā bǎoshòu bìngtòng áojiān.","vi":"Anh ấy chịu đủ sự dày vò của bệnh tật."},{"type":"simple","zh":"等待手术结果的那几个小时对她是一种熬煎。","pinyin":"Děngdài shǒushù jiéguǒ de nà jǐ gè xiǎoshí duì tā shì yì zhǒng áojiān.","vi":"Mấy tiếng chờ kết quả phẫu thuật đối với cô ấy là một sự dày vò."},{"type":"compound","zh":"虽然那段日子充满熬煎，但是全家人一起挺过来了。","pinyin":"Suīrán nà duàn rìzi chōngmǎn áojiān, dànshì quán jiārén yìqǐ tǐng guòlái le.","vi":"Tuy quãng thời gian đó đầy khổ cực nhưng cả nhà đã cùng nhau vượt qua."}],"related":[{"hanzi":"煎熬","pinyin":"jiān'áo","vi":"dày vò"},{"hanzi":"折磨","pinyin":"zhémó","vi":"hành hạ"},{"hanzi":"痛苦","pinyin":"tòngkǔ","vi":"đau khổ"},{"hanzi":"熬夜","pinyin":"áoyè","vi":"thức khuya"}]},{"id":"恶贯满盈","hanzi":"恶贯满盈","pinyin":"èguàn-mǎnyíng","meaning_vi":"tội ác chồng chất đến cùng cực (sắp bị trừng trị)","explanation":"恶贯满盈: tội ác (恶) xâu thành chuỗi (贯) đã đầy (满盈) → tội ác chồng chất đến cùng cực, đã đến lúc phải bị trừng trị.","hsk_level":6,"tags":["thanh-ngu"],"image":"⚖️","examples":[{"type":"basic","zh":"这个罪犯恶贯满盈。","pinyin":"Zhè ge zuìfàn èguànmǎnyíng.","vi":"Tên tội phạm này tội ác chồng chất."},{"type":"simple","zh":"恶贯满盈的毒贩终于被警方抓获了。","pinyin":"Èguànmǎnyíng de dúfàn zhōngyú bèi jǐngfāng zhuāhuò le.","vi":"Tên buôn ma túy tội ác tày trời cuối cùng đã bị cảnh sát bắt giữ."},{"type":"compound","zh":"因为这伙土匪恶贯满盈，所以村民们都盼着他们早日落网。","pinyin":"Yīnwèi zhè huǒ tǔfěi èguànmǎnyíng, suǒyǐ cūnmínmen dōu pànzhe tāmen zǎorì luòwǎng.","vi":"Vì bọn thổ phỉ này tội ác chồng chất nên dân làng đều mong chúng sớm sa lưới."}],"related":[{"hanzi":"罪大恶极","pinyin":"zuìdà'èjí","vi":"tội ác tày trời"},{"hanzi":"罪恶","pinyin":"zuì'è","vi":"tội ác"},{"hanzi":"恶有恶报","pinyin":"èyǒu'èbào","vi":"ác giả ác báo"},{"hanzi":"作恶多端","pinyin":"zuò'èduōduān","vi":"làm nhiều điều ác"}],"traditional":"惡貫滿盈"},{"id":"挨","hanzi":"挨","pinyin":"āi","meaning_vi":"kề sát, sát cạnh; lần lượt, theo thứ tự","explanation":"Đọc āi (kề sát/lần lượt - 挨着); đọc ái (chịu đựng - 挨打/挨饿).","hsk_level":6,"tags":["dong-tu"],"image":"🤜","examples":[{"type":"basic","zh":"我们挨着坐吧。","pinyin":"Wǒmen āizhe zuò ba.","vi":"Chúng ta ngồi sát nhau nhé."},{"type":"simple","zh":"医生挨个给排队的孩子打疫苗。","pinyin":"Yīshēng āigè gěi páiduì de háizi dǎyìmiáo.","vi":"Bác sĩ lần lượt tiêm vắc-xin cho từng đứa trẻ đang xếp hàng."},{"type":"compound","zh":"因为我家挨着菜市场，所以每天早上都很吵。","pinyin":"Yīnwèi wǒ jiā āizhe càishìchǎng, suǒyǐ měitiān zǎo Shangdōu hěn chǎo.","vi":"Vì nhà tôi sát chợ nên sáng nào cũng ồn ào."}],"related":[{"hanzi":"挨个","pinyin":"āigè","vi":"lần lượt từng cái"},{"hanzi":"挨着","pinyin":"āizhe","vi":"kề sát"},{"hanzi":"紧挨","pinyin":"jǐn'āi","vi":"sát cạnh"},{"hanzi":"挨家挨户","pinyin":"āijiā'āihù","vi":"từng nhà một"}]},{"id":"挨家挨户","hanzi":"挨家挨户","pinyin":"āijiā-āihù","meaning_vi":"từng nhà một, nhà nhà","explanation":"挨 (lần lượt) + 家 (nhà) + 户 (hộ). Thành ngữ.","hsk_level":6,"tags":["thanh-ngu"],"image":"🏘️","examples":[{"type":"basic","zh":"他们挨家挨户通知。","pinyin":"Tāmen āijiā'āihù tōngzhī.","vi":"Họ đi thông báo đến từng nhà."},{"type":"simple","zh":"社区工作人员挨家挨户地登记人口信息。","pinyin":"Shèqū gōngzuò rényuán āijiā'āihù de dēngjì rénkǒu xìnxī.","vi":"Nhân viên khu dân cư đến từng nhà đăng ký thông tin nhân khẩu."},{"type":"compound","zh":"只要挨家挨户地问，就一定能找到那只丢失的小狗。","pinyin":"Zhǐyào āijiā'āihù de wèn, jiù yídìng néng zhǎodào nà zhī diūshī de xiǎogǒu.","vi":"Chỉ cần hỏi từng nhà một, nhất định sẽ tìm được chú chó bị lạc đó."}],"related":[{"hanzi":"家家户户","pinyin":"jiājiāhùhù","vi":"nhà nhà"},{"hanzi":"挨个","pinyin":"āigè","vi":"lần lượt từng cái"},{"hanzi":"逐个","pinyin":"zhúgè","vi":"từng cái một"},{"hanzi":"上门","pinyin":"shàngmén","vi":"đến tận nhà"}],"traditional":"挨家挨戶"},{"id":"哎哟","hanzi":"哎哟","pinyin":"āiyō","meaning_vi":"ối, ái chà (thán từ đau/ngạc nhiên)","explanation":"哎 + 哟: hai thán từ (bộ 口) ghép lại → tiếng kêu ối, ái da khi đau, ngạc nhiên hoặc tiếc. Ví dụ: 哎哟，好疼!","hsk_level":6,"tags":["tro-tu","cam-xuc"],"image":"😣","examples":[{"type":"basic","zh":"哎哟，好疼啊！","pinyin":"Āiyō, hǎo téng a!","vi":"Ối, đau quá!"},{"type":"simple","zh":"哎哟，我把家里的钥匙忘在办公室了！","pinyin":"Āiyō, wǒ bǎ jiāli de yàoshi wàng zài bàngōngshì le!","vi":"Ái chà, tôi để quên chìa khóa nhà ở văn phòng rồi!"},{"type":"compound","zh":"哎哟，你一说我才想起来，今天是妈妈的生日！","pinyin":"Āiyō, nǐ yìshuō wǒ cái xiǎngqǐlái, jīntiān shì māma de shēngrì!","vi":"Ối, bạn vừa nói tôi mới nhớ ra, hôm nay là sinh nhật mẹ!"}],"related":[{"hanzi":"哎呀","pinyin":"āiyā","vi":"ôi chao"},{"hanzi":"唉","pinyin":"āi","vi":"haizz"},{"hanzi":"天哪","pinyin":"tiānna","vi":"trời ơi"},{"hanzi":"疼","pinyin":"téng","vi":"đau"}],"traditional":"哎喲"},{"id":"安抚","hanzi":"安抚","pinyin":"ānfǔ","meaning_vi":"an ủi, vỗ về, xoa dịu","explanation":"安 (yên ổn) + 抚 (vỗ về).","hsk_level":6,"tags":["dong-tu","cam-xuc"],"image":"🤗","examples":[{"type":"basic","zh":"妈妈安抚着婴儿。","pinyin":"Māma ānfǔzhe yīng'ér.","vi":"Mẹ đang vỗ về em bé."},{"type":"simple","zh":"空姐耐心地安抚着紧张的乘客。","pinyin":"Kōngjiě nàixīn de ānfǔ zhejǐn zhāng de chéngkè.","vi":"Tiếp viên kiên nhẫn trấn an những hành khách đang căng thẳng."},{"type":"compound","zh":"事故发生后，公司不但赔偿了损失，而且派人安抚了家属。","pinyin":"Shìgù fāshēng hòu, gōngsī búdàn péichángle sǔnshī, érqiě pàirén ānfǔle jiāshǔ.","vi":"Sau sự cố, công ty không chỉ bồi thường thiệt hại mà còn cử người an ủi gia đình nạn nhân."}],"related":[{"hanzi":"安慰","pinyin":"ānwèi","vi":"an ủi"},{"hanzi":"抚慰","pinyin":"fǔwèi","vi":"vỗ về"},{"hanzi":"安顿","pinyin":"āndùn","vi":"sắp xếp ổn thỏa"},{"hanzi":"平息","pinyin":"píngxī","vi":"dẹp yên"}],"traditional":"安撫"},{"id":"安然无恙","hanzi":"安然无恙","pinyin":"ānrán-wúyàng","meaning_vi":"bình an vô sự","explanation":"安然 (yên ổn) + 无恙 (không bệnh tật/hư hại). Thành ngữ.","hsk_level":6,"tags":["thanh-ngu"],"image":"🕊️","examples":[{"type":"basic","zh":"孩子安然无恙。","pinyin":"Háizi ānránwúyàng.","vi":"Đứa trẻ bình an vô sự."},{"type":"simple","zh":"地震中，这座古塔竟然安然无恙。","pinyin":"Dìzhèn zhōng, zhè zuò Gǔtǎ jìngrán ānránwúyàng.","vi":"Trong trận động đất, ngọn tháp cổ này vậy mà vẫn bình an vô sự."},{"type":"compound","zh":"车虽然撞坏了，但是车里的人都安然无恙。","pinyin":"Chē suīrán zhuàng huàile, dànshì chē li de rén dōu ānránwúyàng.","vi":"Xe tuy bị đâm hỏng nhưng người trong xe đều bình an vô sự."}],"related":[{"hanzi":"平安无事","pinyin":"píng'ānwúshì","vi":"bình an vô sự"},{"hanzi":"平安","pinyin":"píng'ān","vi":"bình an"},{"hanzi":"毫发无损","pinyin":"háofàwúsǔn","vi":"không mảy may tổn hại"},{"hanzi":"安全","pinyin":"ānquán","vi":"an toàn"}],"traditional":"安然無恙"},{"id":"安详","hanzi":"安详","pinyin":"ānxiáng","meaning_vi":"điềm tĩnh, thanh thản","explanation":"安 (an – yên) + 详 (tường – điềm đạm) → điềm tĩnh, ung dung, thanh thản. Ví dụ: 神态安详, 安详地睡着了.","hsk_level":6,"tags":["tinh-tu"],"image":"😌","examples":[{"type":"basic","zh":"老人睡得很安详。","pinyin":"Lǎorén shuì de hěn ānxiáng.","vi":"Ông lão ngủ rất thanh thản."},{"type":"simple","zh":"奶奶坐在摇椅上，神情十分安详。","pinyin":"Nǎinai zuò zài yáoyǐ shang, shénqíng shífēn ānxiáng.","vi":"Bà ngồi trên ghế bập bênh, vẻ mặt vô cùng thanh thản."},{"type":"compound","zh":"虽然病得很重，但是他的脸上始终很安详。","pinyin":"Suīrán bìng de hěn zhòng, dànshì tā de liǎn shang shǐzhōng hěn ānxiáng.","vi":"Tuy bệnh rất nặng nhưng gương mặt ông luôn thanh thản."}],"related":[{"hanzi":"安静","pinyin":"ānjìng","vi":"yên tĩnh"},{"hanzi":"慈祥","pinyin":"cíxiáng","vi":"hiền từ"},{"hanzi":"平静","pinyin":"píngjìng","vi":"bình lặng"},{"hanzi":"从容","pinyin":"cóngróng","vi":"ung dung"}],"traditional":"安詳"},{"id":"安葬","hanzi":"安葬","pinyin":"ānzàng","meaning_vi":"an táng, chôn cất","explanation":"安 (yên ổn) + 葬 (chôn cất).","hsk_level":6,"tags":["dong-tu","van-hoa"],"image":"🪦","examples":[{"type":"basic","zh":"他被安葬在故乡。","pinyin":"Tā bèi ānzàng zài gùxiāng.","vi":"Ông ấy được an táng tại quê nhà."},{"type":"simple","zh":"家人按照老人的遗愿把他安葬在山上。","pinyin":"Jiārén ànzhào lǎorén de yíyuàn bǎ tā ānzàng zài shān shang.","vi":"Gia đình an táng ông cụ trên núi theo di nguyện."},{"type":"compound","zh":"因为烈士生前热爱这片土地，所以人们把他安葬在了这里。","pinyin":"Yīnwèi lièshì shēngqián rè'ài zhè piàn tǔdì, suǒyǐ rénmen bǎ tā ānzàng zài le zhèlǐ.","vi":"Vì liệt sĩ khi còn sống yêu mảnh đất này nên mọi người đã an táng ông ở đây."}],"related":[{"hanzi":"埋葬","pinyin":"máizàng","vi":"chôn cất"},{"hanzi":"葬礼","pinyin":"zànglǐ","vi":"tang lễ"},{"hanzi":"下葬","pinyin":"xiàzàng","vi":"hạ táng"},{"hanzi":"坟墓","pinyin":"fénmù","vi":"mộ phần"}]},{"id":"凹凸","hanzi":"凹凸","pinyin":"āotū","meaning_vi":"lồi lõm, gồ ghề","explanation":"Hai chữ tượng hình phần lõm xuống (凹) và phần nhô lên (凸).","hsk_level":6,"tags":["tinh-tu"],"image":"⛰️","examples":[{"type":"basic","zh":"路面凹凸不平。","pinyin":"Lùmiàn āotū bùpíng.","vi":"Mặt đường gồ ghề."},{"type":"simple","zh":"这种凹凸的花纹能防止鞋底打滑。","pinyin":"Zhè zhǒng āotū de huāwén néng fángzhǐ xiédǐ dǎhuá.","vi":"Loại hoa văn lồi lõm này có thể chống trơn trượt cho đế giày."},{"type":"compound","zh":"因为月球表面凹凸不平，所以我们能看到明暗不同的区域。","pinyin":"Yīnwèi yuèqiú biǎomiàn āotū bùpíng, suǒyǐ wǒmen néng kàndào míng àn bùtóng de qūyù.","vi":"Vì bề mặt Mặt Trăng lồi lõm nên chúng ta có thể thấy các vùng sáng tối khác nhau."}],"related":[{"hanzi":"凹","pinyin":"āo","vi":"lõm"},{"hanzi":"凸","pinyin":"tū","vi":"lồi"},{"hanzi":"凹凸不平","pinyin":"āotūbùpíng","vi":"gồ ghề lồi lõm"},{"hanzi":"平坦","pinyin":"píngtǎn","vi":"bằng phẳng"}]},{"id":"恩怨","hanzi":"恩怨","pinyin":"ēnyuàn","meaning_vi":"ân oán","explanation":"恩 (ân – ơn) + 怨 (oán – oán hận) → ơn và oán, những ân oán, mâu thuẫn tình cảm giữa người với người. Ví dụ: 个人恩怨, 恩怨分明.","hsk_level":6,"tags":["danh-tu"],"image":"⚖️","examples":[{"type":"basic","zh":"忘掉过去的恩怨吧。","pinyin":"Wàngdiào guòqù de ēnyuàn ba.","vi":"Hãy quên đi ân oán trong quá khứ."},{"type":"simple","zh":"这部小说讲述了两个家族几十年的恩怨。","pinyin":"Zhè bù xiǎoshuō jiǎngshùle liǎng gè jiāzú jǐ shí nián de ēnyuàn.","vi":"Cuốn tiểu thuyết kể về ân oán mấy chục năm giữa hai gia tộc."},{"type":"compound","zh":"即使两人有过恩怨，在灾难面前也选择了互相帮助。","pinyin":"Jíshǐ liǎng rén yǒuguo ēnyuàn, zài zāinàn miànqián yě xuǎnzéle hùxiāng bāngzhù.","vi":"Dù hai người từng có ân oán, trước thảm họa họ vẫn chọn giúp đỡ nhau."}],"related":[{"hanzi":"恩情","pinyin":"ēnqíng","vi":"ân tình"},{"hanzi":"怨恨","pinyin":"yuànhèn","vi":"oán hận"},{"hanzi":"恩将仇报","pinyin":"ēnjiāngchóubào","vi":"lấy oán báo ơn"},{"hanzi":"恩仇","pinyin":"ēnchóu","vi":"ân oán thù hận"}]},{"id":"恶心","hanzi":"恶心","pinyin":"ěxin","meaning_vi":"buồn nôn, kinh tởm","explanation":"恶 (ố – ghét, ghê) + 心 (tâm – lòng, dạ dày) → buồn nôn; nghĩa bóng là ghê tởm, khó chịu. Ví dụ: 感到恶心, 真恶心.","hsk_level":6,"tags":["tinh-tu"],"image":"🤢","examples":[{"type":"basic","zh":"我有点恶心。","pinyin":"Wǒ yǒudiǎn ěxin.","vi":"Tôi hơi buồn nôn."},{"type":"simple","zh":"垃圾桶里散发出一股让人恶心的臭味。","pinyin":"Lājītǒng li sànfā chū yì gǔ ràng rén ěxin de chòuwèi.","vi":"Thùng rác bốc ra một mùi hôi khiến người ta buồn nôn."},{"type":"compound","zh":"我一坐长途汽车，就会觉得头晕恶心。","pinyin":"Wǒ yí zuò chángtú qìchē, jiù huì juéde tóuyūn ěxin.","vi":"Cứ ngồi xe khách đường dài là tôi lại chóng mặt buồn nôn."}],"related":[{"hanzi":"呕吐","pinyin":"ǒutù","vi":"nôn mửa"},{"hanzi":"想吐","pinyin":"xiǎngtù","vi":"buồn nôn"},{"hanzi":"讨厌","pinyin":"tǎoyàn","vi":"đáng ghét"},{"hanzi":"反感","pinyin":"fǎngǎn","vi":"ác cảm"}],"traditional":"惡心"},{"id":"耳濡目染","hanzi":"耳濡目染","pinyin":"ěrrú-mùrǎn","meaning_vi":"mưa dầm thấm lâu (mắt thấy tai nghe mà nhiễm theo)","explanation":"耳濡目染: tai thấm (濡) mắt nhuộm (染) → thường xuyên nghe thấy, nhìn thấy nên bị ảnh hưởng tự nhiên. Ví dụ: 在父母的耳濡目染下.","hsk_level":6,"tags":["thanh-ngu"],"image":"👂","examples":[{"type":"basic","zh":"这是耳濡目染的结果。","pinyin":"Zhè shì ěrrúmùrǎn de jiéguǒ.","vi":"Đây là kết quả của việc mưa dầm thấm lâu."},{"type":"simple","zh":"在父亲的耳濡目染下，她也爱上了京剧。","pinyin":"Zài fùqīn de ěrrúmùrǎn xià, tā yě àishangle Jīngjù.","vi":"Nhờ mưa dầm thấm lâu bên cạnh cha, cô ấy cũng yêu Kinh kịch."},{"type":"compound","zh":"因为父母都是医生，所以他从小耳濡目染，对医学很感兴趣。","pinyin":"Yīnwèi fùmǔ dōu shì yīshēng, suǒyǐ tā cóngxiǎo ěrrúmùrǎn, duì yīxué hěn gǎnxìngqù.","vi":"Vì bố mẹ đều là bác sĩ nên từ nhỏ anh ấy đã mắt thấy tai nghe, rất hứng thú với y học."}],"related":[{"hanzi":"潜移默化","pinyin":"qiányímòhuà","vi":"thay đổi âm thầm"},{"hanzi":"熏陶","pinyin":"xūntáo","vi":"hun đúc"},{"hanzi":"近朱者赤","pinyin":"jìnzhūzhěchì","vi":"gần mực thì đen"},{"hanzi":"影响","pinyin":"yǐngxiǎng","vi":"ảnh hưởng"}]},{"id":"耳熟能详","hanzi":"耳熟能详","pinyin":"ěrshú-néngxiáng","meaning_vi":"nghe quen đến mức thuộc lòng","explanation":"耳熟能详: nghe (耳) quen (熟) đến mức có thể kể tường tận (详) → nghe nhiều nên thuộc lòng, quen thuộc. Ví dụ: 耳熟能详的故事.","hsk_level":6,"tags":["thanh-ngu"],"image":"🎶","examples":[{"type":"basic","zh":"这首歌大家耳熟能详。","pinyin":"Zhè shǒu gē dàjiā ěrshúnéngxiáng.","vi":"Bài hát này ai cũng thuộc lòng."},{"type":"simple","zh":"孙悟空是中国孩子耳熟能详的人物。","pinyin":"Sūnwùkōng shì Zhōngguó háizi ěrshúnéngxiáng de rénwù.","vi":"Tôn Ngộ Không là nhân vật mà trẻ em Trung Quốc ai cũng thuộc làu."},{"type":"compound","zh":"这些道理虽然大家都耳熟能详，但是真正做到的人很少。","pinyin":"Zhèxiē dàoli suīrán dàjiā dōu ěrshúnéngxiáng, dànshì zhēnzhèng zuòdào de rén hěn shǎo.","vi":"Những đạo lý này tuy ai cũng nghe đến thuộc lòng nhưng người thực sự làm được rất ít."}],"related":[{"hanzi":"家喻户晓","pinyin":"jiāyùhùxiǎo","vi":"nhà nhà đều biết"},{"hanzi":"熟悉","pinyin":"shúxi","vi":"quen thuộc"},{"hanzi":"众所周知","pinyin":"zhòngsuǒzhōuzhī","vi":"ai cũng biết"},{"hanzi":"闻所未闻","pinyin":"wénsuǒwèiwén","vi":"chưa từng nghe"}],"traditional":"耳熟能詳"}];
